        private void Awake()
        {
            EnsureJobCategoryPolicy();
            ConfigureCamera();
            CreateRenderLayers();
            GenerateWorld();
            ResetCycleReports();
            CreateWorkers();
            BuildHud();
            RenderTerrain();
            RenderGas();
            RenderOverlay();
            UpdateColonyStatus(true);
            ShowStartStatePanel();
            UpdateHud();
        }

        private void Update()
        {
            HandleKeyboardShortcuts();
            if (!startStateVisible)
            {
                HandleCameraControls();
                HandlePointerCommands();
            }

            EnsureWorldState();

            if (!paused && !startStateVisible)
            {
                float scaledDeltaTime = Mathf.Clamp(Time.deltaTime * simulationSpeed, 0f, 0.12f);
                SimulateColony(scaledDeltaTime);
                EnsureWorkerRecords();
                EnsureHatchTransforms();
                UpdateWorkers(scaledDeltaTime);
            }

            if (terrainDirty)
            {
                RenderTerrain();
            }

            if (gasDirty)
            {
                RenderGas();
            }

            if (overlayDirty)
            {
                RenderOverlay();
            }

            UpdateHudThrottled();
        }

