        private Sprite CreateGrubgrubSprite()
        {
            const int width = 22;
            const int height = 18;
            Texture2D texture = new Texture2D(width, height, TextureFormat.RGBA32, false)
            {
                name = "Grubgrub Critter Sprite",
                filterMode = FilterMode.Point,
                wrapMode = TextureWrapMode.Clamp
            };

            Color clear = new Color(0f, 0f, 0f, 0f);
            Color body = new Color(0.72f, 0.52f, 0.24f, 1f);
            Color belly = new Color(0.96f, 0.78f, 0.38f, 1f);
            Color shadow = new Color(0.36f, 0.22f, 0.10f, 1f);
            Color tend = new Color(0.64f, 0.92f, 0.34f, 1f);
            Color eye = new Color(0.05f, 0.03f, 0.02f, 1f);

            for (int y = 0; y < height; y++)
            {
                for (int x = 0; x < width; x++)
                {
                    texture.SetPixel(x, y, clear);
                    float nx = (x - width * 0.50f) / (width * 0.40f);
                    float ny = (y - height * 0.36f) / (height * 0.28f);
                    if (nx * nx + ny * ny <= 1f && y < height - 3)
                    {
                        texture.SetPixel(x, y, x < width * 0.36f ? shadow : body);
                    }

                    float bny = (y - height * 0.28f) / (height * 0.15f);
                    if (nx * nx * 1.35f + bny * bny <= 1f && y < height * 0.48f)
                    {
                        texture.SetPixel(x, y, belly);
                    }

                    if ((x == 5 || x == 9 || x == 13 || x == 17) && y >= 4 && y <= 7)
                    {
                        texture.SetPixel(x, y, shadow);
                    }

                    if ((x == 10 || x == 11 || x == 12) && y >= 13 && y <= 16)
                    {
                        texture.SetPixel(x, y, tend);
                    }

                    if ((x == 15 || x == 16) && (y == 8 || y == 9))
                    {
                        texture.SetPixel(x, y, eye);
                    }
                }
            }

            texture.Apply(false, false);
            return Sprite.Create(texture, new Rect(0f, 0f, width, height), new Vector2(0.5f, 0.12f), 18f);
        }

