            for (int x = 27; x <= 53; x++)
            {
                cells[x, 18] = CellKind.Floor;
            }

            for (int y = 18; y <= 34; y++)
            {
                cells[40, y] = CellKind.Ladder;
            }

            cells[30, 19] = CellKind.ManualGenerator;
            cells[32, 19] = CellKind.Battery;
            cells[35, 19] = CellKind.OxygenDiffuser;
