                {
                    if (IsPassable(x, y))
                    {
                        bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
                        oxygen[x, y] = inStartRoom ? 1.18f : Mathf.Lerp(0.1f, 0.78f, Mathf.InverseLerp(5f, 30f, y));
                        carbonDioxide[x, y] = y < 12 ? 0.42f : 0.05f;
                        pollutedOxygen[x, y] = 0f;
                        hydrogen[x, y] = 0f;
                        steam[x, y] = 0f;
                        chlorine[x, y] = 0f;
                        naturalGas[x, y] = 0f;
                        sourGas[x, y] = 0f;
                        germs[x, y] = 0f;
                    }
                    else
                    {
