                        carbonDioxide[x, y] = 0f;
                        pollutedOxygen[x, y] = 0f;
                        hydrogen[x, y] = 0f;
                        steam[x, y] = 0f;
                        chlorine[x, y] = 0f;
                        naturalGas[x, y] = 0f;
                        sourGas[x, y] = 0f;
