                    automationCycleSensorEnd[x, y] = AutomationCycleSensorDefaultEnd;
                    automationTimerGreenSeconds[x, y] = AutomationTimerDefaultGreenSeconds;
                    automationTimerRedSeconds[x, y] = AutomationTimerDefaultRedSeconds;
