        private void SeedWaterPool(int minX, int minY, int maxX, int maxY, float mass)
        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!IsInside(x, y))
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.Water;
                    waterMass[x, y] = mass;
                    equipmentCondition[x, y] = 0f;
                    looseResourceKind[x, y] = LooseResourceKind.None;
                    looseResourceAmount[x, y] = 0f;
                    oxygen[x, y] = 0f;
                    carbonDioxide[x, y] = 0f;
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    powerWire[x, y] = false;
                    powerWireKind[x, y] = PowerWireKind.Normal;
                    poweredWire[x, y] = false;
                }
            }
        }

        private void SeedSurfaceRegolithPatches()
        {
            SeedSurfaceRegolithPatch(12, 19, WorldHeight - 11, WorldHeight - 10);
            SeedSurfaceRegolithPatch(WorldWidth - 25, WorldWidth - 18, WorldHeight - 11, WorldHeight - 10);
        }

        private void EnsureSurfaceRegolithPatches()
        {
            if (CountCells(CellKind.Regolith) > 0)
            {
                return;
            }

            SeedSurfaceRegolithPatches();
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private void SeedSurfaceRegolithPatch(int minX, int maxX, int minY, int maxY)
        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!CanSeedSurfaceRegolithAt(x, y))
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.Regolith;
                    waterMass[x, y] = 0f;
                    oxygen[x, y] = 0f;
                    carbonDioxide[x, y] = 0f;
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    equipmentCondition[x, y] = 0f;
                    buildingDisabled[x, y] = false;
                    looseResourceKind[x, y] = LooseResourceKind.None;
                    looseResourceAmount[x, y] = 0f;
                    hatchEggAge[x, y] = 0f;
                    temperature[x, y] = Mathf.Max(temperature[x, y], InitialTemperature(x, y, CellKind.Regolith));
                    constructionMaterialGrade[x, y] = DefaultConstructionMaterialGrade(CellKind.Regolith);
                }
            }
        }

        private bool CanSeedSurfaceRegolithAt(int x, int y)
        {
            if (!IsInside(x, y) || x < 3 || x >= WorldWidth - 3 || y < WorldHeight - 16 || y >= WorldHeight - 3)
            {
                return false;
            }

            bool inUpperShaft = x >= 39 && x <= 41 && y >= 19 && y <= 34;
            if (inUpperShaft)
            {
                return false;
            }

            return (cells[x, y] == CellKind.Empty || IsNaturalSolid(cells[x, y])) &&
                waterMass[x, y] <= 0.05f &&
                !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                looseResourceKind[x, y] == LooseResourceKind.None;
        }

