        private void EnsureSulfurPatches()
        {
            if (TotalLooseSulfur() + sulfur > 1f)
            {
                return;
            }

            SeedSulfurPatches();
        }

        private void SeedSulfurPatch(Vector2Int center, int radius)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > radius || !CanSeedSulfurAt(x, y))
                    {
                        continue;
                    }

                    float noise = Mathf.PerlinNoise(x * 0.37f + 16.7f, y * 0.31f + 4.2f);
                    if (noise < 0.38f && distance > 2)
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.Empty;
                    waterMass[x, y] = 0f;
                    oxygen[x, y] = Mathf.Max(oxygen[x, y], 0.24f);
                    carbonDioxide[x, y] = Mathf.Max(carbonDioxide[x, y], 0.08f);
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    looseResourceKind[x, y] = LooseResourceKind.Sulfur;
                    looseResourceAmount[x, y] = Mathf.Lerp(4.5f, 12f, noise);
                    temperature[x, y] = Mathf.Clamp(Mathf.Max(temperature[x, y], 24f + noise * 18f), -30f, 120f);
                }
            }
        }

        private bool CanSeedSulfurAt(int x, int y)
        {
            if (!IsInside(x, y) || x < 3 || x >= WorldWidth - 3 || y < 18 || y > 34)
            {
                return false;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            bool inUpperShaft = x >= 39 && x <= 41 && y >= 19 && y <= 34;
            if (inStartRoom || inUpperShaft)
            {
                return false;
            }

            return (cells[x, y] == CellKind.Empty || IsNaturalSolid(cells[x, y])) &&
                waterMass[x, y] <= 0.05f &&
                !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                looseResourceKind[x, y] == LooseResourceKind.None;
        }

