        {
            SeedMoltenSlicksterPocket(new Vector2Int(20, 10));
            SeedMoltenSlicksterPocket(new Vector2Int(WorldWidth - 20, 10));
        }

        private void SeedMoltenSlicksterPocket(Vector2Int center)
        {
            for (int dy = -2; dy <= 2; dy++)
            {
                for (int dx = -3; dx <= 3; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (CanWarmMoltenSlicksterPocketAt(x, y))
                    {
                        temperature[x, y] = Mathf.Clamp(Mathf.Max(temperature[x, y], MoltenSlicksterPreferredTemperatureMin + 14f), -30f, 120f);
                    }
                }
            }

            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -2; dx <= 2; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!CanSeedMoltenSlicksterPocketAt(x, y))
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.Empty;
                    waterMass[x, y] = 0f;
                    oxygen[x, y] = 0f;
                    carbonDioxide[x, y] = Mathf.Max(carbonDioxide[x, y], 0.62f);
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    naturalGas[x, y] = Mathf.Max(naturalGas[x, y], 0.05f);
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    looseResourceKind[x, y] = LooseResourceKind.None;
                    looseResourceAmount[x, y] = 0f;
                    hatchEggAge[x, y] = 0f;
                    equipmentCondition[x, y] = 0f;
                    temperature[x, y] = Mathf.Clamp(Mathf.Max(temperature[x, y], MoltenSlicksterPreferredTemperatureMin + 18f), -30f, 120f);
                }
            }
        }

        private bool CanWarmMoltenSlicksterPocketAt(int x, int y)
        {
            if (!IsInside(x, y) || x < 2 || x >= WorldWidth - 2 || y < 3 || y > 15)
            {
                return false;
            }

            return (IsPassable(x, y) || IsNaturalSolid(cells[x, y]) || IsWorldLiquidCell(cells[x, y])) &&
                !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y];
        }

        private bool CanSeedMoltenSlicksterPocketAt(int x, int y)
        {
            if (!IsInside(x, y) || x < 3 || x >= WorldWidth - 3 || y < 4 || y > 14)
            {
                return false;
            }

            return (cells[x, y] == CellKind.Empty || IsNaturalSolid(cells[x, y]) || IsWorldLiquidCell(cells[x, y])) &&
                !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y];
        }

