        private bool TryFindCritterSpawnCell(CritterKind kind, Vector2Int preferred, int searchRadius, out Vector2Int spawnCell)
        {
            spawnCell = new Vector2Int(-1, -1);
            for (int radius = 0; radius <= searchRadius; radius++)
            {
                for (int y = preferred.y - radius; y <= preferred.y + radius; y++)
                {
                    for (int x = preferred.x - radius; x <= preferred.x + radius; x++)
                    {
                        if (Mathf.Abs(x - preferred.x) != radius && Mathf.Abs(y - preferred.y) != radius)
                        {
                            continue;
                        }

                        if (CanSpawnCritterAt(kind, x, y))
                        {
                            spawnCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanSpawnHatchAt(int x, int y)
        {
            return CanSpawnCritterAt(CritterKind.Hatch, x, y);
        }

        private bool CanSpawnCritterAt(CritterKind kind, int x, int y)
        {
            if (kind == CritterKind.Pacu)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return IsPacuSwimCell(cell) && HatchAt(cell) == null;
            }

            if (!IsInside(x, y) || !IsPassable(x, y) || HatchAt(new Vector2Int(x, y)) != null)
            {
                return false;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            if (inStartRoom || waterMass[x, y] > 0.05f)
            {
                return false;
            }

            if (kind == CritterKind.Slickster)
            {
                return y <= 18 &&
                    temperature[x, y] > SlicksterMoveTemperatureMin &&
                    temperature[x, y] < SlicksterMoveTemperatureMax &&
                    CarbonDioxideAround(new Vector2Int(x, y), SlicksterCarbonSearchRange) > 0.08f;
            }

            if (kind == CritterKind.MoltenSlickster)
            {
                return y <= 16 &&
                    temperature[x, y] > MoltenSlicksterMoveTemperatureMin &&
                    temperature[x, y] < MoltenSlicksterMoveTemperatureMax &&
                    HotCarbonDioxideAround(new Vector2Int(x, y), SlicksterCarbonSearchRange) > 0.08f;
            }

            if (kind == CritterKind.Drecko)
            {
                return y >= 22 &&
                    temperature[x, y] > DreckoMoveTemperatureMin &&
                    temperature[x, y] < DreckoMoveTemperatureMax;
            }

            if (kind == CritterKind.Puft)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 16 &&
                    temperature[x, y] > PuftMoveTemperatureMin &&
                    temperature[x, y] < PuftMoveTemperatureMax &&
                    (PollutedOxygenAround(cell, PuftPollutedOxygenSearchRange) > 0.08f ||
                        SlimeCellsAround(cell, PuftPollutedOxygenSearchRange) > 0);
            }

            if (kind == CritterKind.Morb)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 15 &&
                    temperature[x, y] > MorbMoveTemperatureMin &&
                    temperature[x, y] < MorbMoveTemperatureMax &&
                    (PollutedOxygenAround(cell, MorbPollutionSearchRange) > 0.04f ||
                        PollutionSourceCellsAround(cell, MorbPollutionSearchRange) > 0);
            }

            if (kind == CritterKind.ShineBug)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 20 &&
                    temperature[x, y] > ShineBugMoveTemperatureMin &&
                    temperature[x, y] < ShineBugMoveTemperatureMax &&
                    (oxygen[x, y] > 0.12f || hydrogen[x, y] > 0.04f || AlgaeCellsAround(cell, 4) > 0);
            }

            if (kind == CritterKind.Pip)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 16 &&
                    temperature[x, y] > PipMoveTemperatureMin &&
                    temperature[x, y] < PipMoveTemperatureMax &&
                    (ArborTreesAround(cell, PipArborSearchRange) > 0 || ForestPocketCellsAround(cell, 5) > 0);
            }

            if (kind == CritterKind.PlugSlug)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 12 &&
                    temperature[x, y] > PlugSlugMoveTemperatureMin &&
                    temperature[x, y] < PlugSlugMoveTemperatureMax &&
                    (MetalOreCellsAround(cell, PlugSlugMetalSearchRange) > 0 || HasPlugSlugMetalFeedAvailable());
            }

            if (kind == CritterKind.GassyMoo)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 16 &&
                    temperature[x, y] > GassyMooMoveTemperatureMin &&
                    temperature[x, y] < GassyMooMoveTemperatureMax &&
                    (BristleBlossomsAround(cell, GassyMooBristleSearchRange) > 0 || oxygen[x, y] > 0.16f);
            }

            if (kind == CritterKind.Beeta)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= WorldHeight - 12 &&
                    temperature[x, y] > BeetaMoveTemperatureMin &&
                    temperature[x, y] < BeetaMoveTemperatureMax &&
                    BeetaRadiationSourceScore(cell) >= BeetaRadiationMinimum;
            }

            if (kind == CritterKind.Grubgrub)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 14 &&
                    temperature[x, y] > GrubgrubMoveTemperatureMin &&
                    temperature[x, y] < GrubgrubMoveTemperatureMax &&
                    CropCellsAround(cell, GrubgrubCropSearchRange) > 0;
            }

            if (kind == CritterKind.Sweetle)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 14 &&
                    temperature[x, y] > SweetleMoveTemperatureMin &&
                    temperature[x, y] < SweetleMoveTemperatureMax &&
                    (SulfurAround(cell, SweetleSulfurSearchRange) > 0.05f ||
                        CropCellsAround(cell, GrubgrubCropSearchRange) > 0);
            }

            if (kind == CritterKind.CuddlePip)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= 14 &&
                    temperature[x, y] > CuddlePipMoveTemperatureMin &&
                    temperature[x, y] < CuddlePipMoveTemperatureMax &&
                    (EggTargetsAround(cell, CuddlePipEggSearchRange) > 0 ||
                        ArborTreesAround(cell, PipArborSearchRange) > 0 ||
                        ForestPocketCellsAround(cell, 5) > 0);
            }

            if (kind == CritterKind.ShoveVole)
            {
                Vector2Int cell = new Vector2Int(x, y);
                return y >= WorldHeight - 16 &&
                    temperature[x, y] > ShoveVoleMoveTemperatureMin &&
                    temperature[x, y] < ShoveVoleMoveTemperatureMax &&
                    RegolithCellsAround(cell, ShoveVoleRegolithSearchRange) > 0;
            }

            return temperature[x, y] > -8f && temperature[x, y] < 48f;
        }

        private void SeedHydrogenPocket(int minX, int minY, int maxX, int maxY, float mass)
        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float shape = Mathf.PerlinNoise(x * 0.25f + 91.4f, y * 0.22f + 37.6f);
                    if (shape <= 0.34f)
                    {
                        continue;
                    }

                    hydrogen[x, y] = Mathf.Max(hydrogen[x, y], mass);
                    oxygen[x, y] *= 0.42f;
                    carbonDioxide[x, y] *= 0.18f;
                    pollutedOxygen[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                }
            }
        }

        private void SeedChlorinePocket(int minX, int minY, int maxX, int maxY, float mass)
        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float shape = Mathf.PerlinNoise(x * 0.19f + 24.8f, y * 0.27f + 66.1f);
                    if (shape <= 0.36f)
                    {
                        continue;
                    }

                    chlorine[x, y] = Mathf.Max(chlorine[x, y], mass);
                    oxygen[x, y] *= 0.30f;
                    carbonDioxide[x, y] *= 0.35f;
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    temperature[x, y] = Mathf.Clamp(Mathf.Max(temperature[x, y], 22f), -30f, 120f);
                }
            }
        }

        private void SeedBleachStonePocket(int minX, int minY, int maxX, int maxY)
        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!IsInside(x, y) || IsWorldLiquidCell(cells[x, y]) || !IsNaturalSolid(cells[x, y]) || cells[x, y] == CellKind.Slime)
                    {
                        continue;
                    }

                    float shape = Mathf.PerlinNoise(x * 0.31f + 43.8f, y * 0.21f + 91.5f);
                    if (shape <= 0.44f)
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.BleachStone;
                    oxygen[x, y] = 0f;
                    carbonDioxide[x, y] = 0f;
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = Mathf.Max(chlorine[x, y], 0.08f);
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    waterMass[x, y] = 0f;
                    temperature[x, y] = InitialTemperature(x, y, CellKind.BleachStone);
                }
            }
        }

        private void SeedNaturalGasPocket(int minX, int minY, int maxX, int maxY, float mass)
        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float shape = Mathf.PerlinNoise(x * 0.23f + 58.2f, y * 0.18f + 11.7f);
                    if (shape <= 0.35f)
                    {
                        continue;
                    }

                    naturalGas[x, y] = Mathf.Max(naturalGas[x, y], mass);
                    oxygen[x, y] *= 0.30f;
                    carbonDioxide[x, y] *= 0.24f;
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    temperature[x, y] = Mathf.Clamp(Mathf.Max(temperature[x, y], 30f), -30f, 120f);
                }
            }
        }

