        private void SeedAntiEntropyThermoNullifiers()
        {
            if (CountCells(CellKind.AntiEntropyThermoNullifier) > 0)
            {
                return;
            }

            TrySeedAntiEntropyThermoNullifier(new Vector2Int(18, 38), 10);
        }

        private bool TrySeedAntiEntropyThermoNullifier(Vector2Int preferred, int searchRadius)
        {
            Vector2Int cell;
            if (!TryFindAntiEntropyThermoNullifierCell(preferred, searchRadius, out cell))
            {
                return false;
            }

            CarveAntiEntropyThermoNullifierPocket(cell);
            cells[cell.x, cell.y] = CellKind.AntiEntropyThermoNullifier;
            waterMass[cell.x, cell.y] = 0f;
            oxygen[cell.x, cell.y] = 0f;
            carbonDioxide[cell.x, cell.y] = 0f;
            pollutedOxygen[cell.x, cell.y] = 0f;
            hydrogen[cell.x, cell.y] = 0f;
            steam[cell.x, cell.y] = 0f;
            chlorine[cell.x, cell.y] = 0f;
            naturalGas[cell.x, cell.y] = 0f;
            sourGas[cell.x, cell.y] = 0f;
            germs[cell.x, cell.y] = 0f;
            looseResourceKind[cell.x, cell.y] = LooseResourceKind.None;
            looseResourceAmount[cell.x, cell.y] = 0f;
            powerWire[cell.x, cell.y] = false;
            powerWireKind[cell.x, cell.y] = PowerWireKind.Normal;
            poweredWire[cell.x, cell.y] = false;
            automationWire[cell.x, cell.y] = false;
            liquidPipe[cell.x, cell.y] = false;
            gasPipe[cell.x, cell.y] = false;
            shippingRail[cell.x, cell.y] = false;
            equipmentCondition[cell.x, cell.y] = 0f;
            buildingDisabled[cell.x, cell.y] = false;
            constructionMaterialGrade[cell.x, cell.y] = ConstructionMaterialGrade.Basic;
            temperature[cell.x, cell.y] = InitialTemperature(cell.x, cell.y, CellKind.AntiEntropyThermoNullifier);
            plantGrowth[cell.x, cell.y] = 0f;
            return true;
        }

        private bool TryFindAntiEntropyThermoNullifierCell(Vector2Int preferred, int searchRadius, out Vector2Int nullifierCell)
        {
            nullifierCell = new Vector2Int(-1, -1);
            for (int radius = 0; radius <= searchRadius; radius++)
            {
                for (int y = preferred.y - radius; y <= preferred.y + radius; y++)
                {
                    for (int x = preferred.x - radius; x <= preferred.x + radius; x++)
                    {
                        if (Mathf.Abs(x - preferred.x) != radius && Mathf.Abs(y - preferred.y) != radius)
                        {
                            continue;
                        }

                        if (CanPlaceAntiEntropyThermoNullifierAt(x, y))
                        {
                            nullifierCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanPlaceAntiEntropyThermoNullifierAt(int x, int y)
        {
            if (!IsInside(x, y) || x < 3 || x >= WorldWidth - 3 || y < 30 || y >= WorldHeight - 3 || waterMass[x, y] > 0.05f)
            {
                return false;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            bool inUpperShaft = x >= 39 && x <= 41 && y >= 19 && y <= 34;
            if (inStartRoom || inUpperShaft)
            {
                return false;
            }

            CellKind kind = cells[x, y];
            bool replaceable = kind == CellKind.Empty || IsNaturalSolid(kind) || IsWorldLiquidCell(kind);
            if (!replaceable ||
                powerWire[x, y] ||
                automationWire[x, y] ||
                liquidPipe[x, y] ||
                gasPipe[x, y] ||
                shippingRail[x, y] ||
                looseResourceKind[x, y] != LooseResourceKind.None)
            {
                return false;
            }

            Vector2Int cell = new Vector2Int(x, y);
            return HydrogenAround(cell, 4) >= 0.05f || IceCellsAround(cell, 6) > 0 || y >= 36;
        }

        private void CarveAntiEntropyThermoNullifierPocket(Vector2Int center)
        {
            for (int dy = -2; dy <= 2; dy++)
            {
                for (int dx = -2; dx <= 2; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || (dx == 0 && dy == 0))
                    {
                        continue;
                    }

                    if (powerWire[x, y] ||
                        automationWire[x, y] ||
                        liquidPipe[x, y] ||
                        gasPipe[x, y] ||
                        shippingRail[x, y] ||
                        (cells[x, y] != CellKind.Empty && !IsNaturalSolid(cells[x, y]) && !IsWorldLiquidCell(cells[x, y])))
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.Empty;
                    waterMass[x, y] = 0f;
                    oxygen[x, y] = Mathf.Min(oxygen[x, y], 0.08f);
                    carbonDioxide[x, y] = Mathf.Min(carbonDioxide[x, y], 0.04f);
                    pollutedOxygen[x, y] = 0f;
                    hydrogen[x, y] = Mathf.Max(hydrogen[x, y], 0.32f);
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = 0f;
                    equipmentCondition[x, y] = 0f;
                    looseResourceKind[x, y] = LooseResourceKind.None;
                    looseResourceAmount[x, y] = 0f;
                    temperature[x, y] = Mathf.Min(temperature[x, y], 4f);
                }
            }
        }

