        private bool TrySeedArborTree(Vector2Int preferred, int searchRadius)
        {
            Vector2Int cell;
            if (!TryFindArborTreeCell(preferred, searchRadius, out cell))
            {
                return false;
            }

            cells[cell.x, cell.y] = CellKind.ArborTree;
            waterMass[cell.x, cell.y] = 0f;
            oxygen[cell.x, cell.y] = Mathf.Max(oxygen[cell.x, cell.y], 0.16f);
            carbonDioxide[cell.x, cell.y] = Mathf.Max(carbonDioxide[cell.x, cell.y], 0.10f);
            pollutedOxygen[cell.x, cell.y] = Mathf.Max(pollutedOxygen[cell.x, cell.y], 0.02f);
            hydrogen[cell.x, cell.y] = 0f;
            steam[cell.x, cell.y] = 0f;
            chlorine[cell.x, cell.y] = 0f;
            naturalGas[cell.x, cell.y] = 0f;
            sourGas[cell.x, cell.y] = 0f;
            germs[cell.x, cell.y] = 0f;
            looseResourceKind[cell.x, cell.y] = LooseResourceKind.None;
            looseResourceAmount[cell.x, cell.y] = 0f;
            temperature[cell.x, cell.y] = InitialTemperature(cell.x, cell.y, CellKind.ArborTree);
            plantGrowth[cell.x, cell.y] = 1f;
            cropTendedSeconds[cell.x, cell.y] = 0f;
            cropStress[cell.x, cell.y] = 0f;
            return true;
        }

        private bool TryFindArborTreeCell(Vector2Int preferred, int searchRadius, out Vector2Int plantCell)
        {
            plantCell = new Vector2Int(-1, -1);
            for (int radius = 0; radius <= searchRadius; radius++)
            {
                for (int y = preferred.y - radius; y <= preferred.y + radius; y++)
                {
                    for (int x = preferred.x - radius; x <= preferred.x + radius; x++)
                    {
                        if (Mathf.Abs(x - preferred.x) != radius && Mathf.Abs(y - preferred.y) != radius)
                        {
                            continue;
                        }

                        if (CanPlaceArborTreeAt(x, y))
                        {
                            plantCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanPlaceArborTreeAt(int x, int y)
        {
            if (!IsInside(x, y) || y < 12 || y > 34 || waterMass[x, y] > 0.05f)
            {
                return false;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            bool inUpperShaft = x >= 39 && x <= 41 && y >= 19 && y <= 34;
            if (inStartRoom || inUpperShaft)
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind != CellKind.Empty && !IsNaturalSolid(kind))
            {
                return false;
            }

            return ForestPocketCellsAround(new Vector2Int(x, y), 5) > 0;
        }

