                    for (int x = preferred.x - radius; x <= preferred.x + radius; x++)
                    {
                        if (Mathf.Abs(x - preferred.x) != radius && Mathf.Abs(y - preferred.y) != radius)
                        {
                            continue;
                        }

                        if (CanPlaceThimbleReedAt(x, y))
                        {
                            plantCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanPlaceThimbleReedAt(int x, int y)
        {
            if (!IsInside(x, y) || y < 14 || y > 34 || waterMass[x, y] > 0.05f)
            {
                return false;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            bool inUpperShaft = x >= 39 && x <= 41 && y >= 19 && y <= 34;
            if (inStartRoom || inUpperShaft)
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind != CellKind.Empty && !IsNaturalSolid(kind))
            {
                return false;
            }

            return !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                PollutedWaterCellsAround(new Vector2Int(x, y), ThimbleReedPollutedWaterSearchRange) > 0;
        }

        private int PollutedWaterCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (IsPollutedWorldLiquidAt(x, y) && waterMass[x, y] > 0.05f)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void EnsureThimbleReedPollutedWaterSource(Vector2Int plant)
        {
            if (PollutedWorldWaterAround(plant, ThimbleReedPollutedWaterSearchRange) >= ThimbleReedMinimumNaturalPollutedWater)
            {
                return;
            }

            if (TryFindThimbleReedPollutedWaterSourceCell(plant, out Vector2Int source))
            {
                SetThimbleReedPollutedWaterSource(source);
            }
        }

        private bool TryFindThimbleReedPollutedWaterSourceCell(Vector2Int plant, out Vector2Int source)
        {
            source = new Vector2Int(-1, -1);
            for (int radius = 1; radius <= ThimbleReedPollutedWaterSearchRange; radius++)
            {
                for (int y = plant.y - radius; y <= plant.y + radius; y++)
                {
                    for (int x = plant.x - radius; x <= plant.x + radius; x++)
                    {
                        if (Mathf.Abs(x - plant.x) != radius && Mathf.Abs(y - plant.y) != radius)
                        {
                            continue;
                        }

                        if (!CanPlaceThimbleReedPollutedWaterSourceAt(plant, x, y))
                        {
                            continue;
                        }

                        source = new Vector2Int(x, y);
                        return true;
                    }
                }
            }

            return false;
        }

        private bool CanPlaceThimbleReedPollutedWaterSourceAt(Vector2Int plant, int x, int y)
        {
            if (!IsInside(x, y) || (x == plant.x && y == plant.y) || (x == plant.x && y == plant.y - 1))
            {
                return false;
            }

            if (waterMass[x, y] > 0.05f && !IsPollutedWorldLiquidAt(x, y))
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind != CellKind.Empty && kind != CellKind.PollutedWater && !IsNaturalSolid(kind))
            {
                return false;
            }

            return !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                looseResourceKind[x, y] == LooseResourceKind.None;
        }

        private void SetThimbleReedPollutedWaterSource(Vector2Int source)
        {
            cells[source.x, source.y] = CellKind.PollutedWater;
            waterMass[source.x, source.y] = Mathf.Max(waterMass[source.x, source.y], ThimbleReedNaturalPollutedWaterSourceMass);
            oxygen[source.x, source.y] = 0f;
            carbonDioxide[source.x, source.y] = Mathf.Max(carbonDioxide[source.x, source.y], 0.03f);
            pollutedOxygen[source.x, source.y] = Mathf.Max(pollutedOxygen[source.x, source.y], 0.06f);
            hydrogen[source.x, source.y] = 0f;
            steam[source.x, source.y] = 0f;
            chlorine[source.x, source.y] = 0f;
            naturalGas[source.x, source.y] = 0f;
            sourGas[source.x, source.y] = 0f;
            germs[source.x, source.y] = Mathf.Max(germs[source.x, source.y], 0.14f);
            looseResourceKind[source.x, source.y] = LooseResourceKind.None;
            looseResourceAmount[source.x, source.y] = 0f;
            temperature[source.x, source.y] = 30f;
        }

        private void SeedSleetWheat()
        {
            if (CountCells(CellKind.SleetWheat) > 0)
            {
                return;
            }

            TrySeedSleetWheat(new Vector2Int(9, 34), 9, 0.74f);
            TrySeedSleetWheat(new Vector2Int(67, 33), 9, 0.64f);
            TrySeedSleetWheat(new Vector2Int(24, 34), 8, 0.48f);
        }

        private bool TrySeedSleetWheat(Vector2Int preferred, int searchRadius, float growth)
        {
            Vector2Int cell;
            if (!TryFindSleetWheatCell(preferred, searchRadius, out cell))
            {
                return false;
            }

            cells[cell.x, cell.y] = CellKind.SleetWheat;
            waterMass[cell.x, cell.y] = 0f;
            oxygen[cell.x, cell.y] = Mathf.Max(oxygen[cell.x, cell.y], 0.22f);
            carbonDioxide[cell.x, cell.y] = Mathf.Max(carbonDioxide[cell.x, cell.y], 0.02f);
            pollutedOxygen[cell.x, cell.y] = 0f;
            hydrogen[cell.x, cell.y] = 0f;
            steam[cell.x, cell.y] = 0f;
            chlorine[cell.x, cell.y] = 0f;
            naturalGas[cell.x, cell.y] = 0f;
            sourGas[cell.x, cell.y] = 0f;
            germs[cell.x, cell.y] = 0f;
            looseResourceKind[cell.x, cell.y] = LooseResourceKind.None;
            looseResourceAmount[cell.x, cell.y] = 0f;
            temperature[cell.x, cell.y] = InitialTemperature(cell.x, cell.y, CellKind.SleetWheat);
            plantGrowth[cell.x, cell.y] = Mathf.Clamp01(growth);
            cropTendedSeconds[cell.x, cell.y] = 0f;
            cropStress[cell.x, cell.y] = 0f;
            return true;
        }

        private bool TryFindSleetWheatCell(Vector2Int preferred, int searchRadius, out Vector2Int plantCell)
        {
            plantCell = new Vector2Int(-1, -1);
            for (int radius = 0; radius <= searchRadius; radius++)
            {
                for (int y = preferred.y - radius; y <= preferred.y + radius; y++)
                {
                    for (int x = preferred.x - radius; x <= preferred.x + radius; x++)
                    {
                        if (Mathf.Abs(x - preferred.x) != radius && Mathf.Abs(y - preferred.y) != radius)
                        {
                            continue;
                        }

                        if (CanPlaceSleetWheatAt(x, y))
                        {
                            plantCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanPlaceSleetWheatAt(int x, int y)
        {
            if (!IsInside(x, y) || y < 26 || y > 38 || waterMass[x, y] > 0.05f)
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind != CellKind.Empty && kind != CellKind.Ice && !IsNaturalSolid(kind))
            {
                return false;
            }

            return !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                IceCellsAround(new Vector2Int(x, y), 3) > 0;
        }

        private int ForestPocketCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && (cells[x, y] == CellKind.Slime || cells[x, y] == CellKind.PollutedWater || pollutedOxygen[x, y] > 0.04f))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TrySeedWheezewort(Vector2Int preferred, int searchRadius)
        {
            Vector2Int cell;
            if (!TryFindWheezewortCell(preferred, searchRadius, out cell))
            {
                return false;
            }

            cells[cell.x, cell.y] = CellKind.Wheezewort;
            waterMass[cell.x, cell.y] = 0f;
            oxygen[cell.x, cell.y] = Mathf.Min(oxygen[cell.x, cell.y], 0.12f);
            carbonDioxide[cell.x, cell.y] = Mathf.Min(carbonDioxide[cell.x, cell.y], 0.05f);
            pollutedOxygen[cell.x, cell.y] = 0f;
            hydrogen[cell.x, cell.y] = Mathf.Max(hydrogen[cell.x, cell.y], 0.20f);
            steam[cell.x, cell.y] = 0f;
            chlorine[cell.x, cell.y] = 0f;
            naturalGas[cell.x, cell.y] = 0f;
            sourGas[cell.x, cell.y] = 0f;
            germs[cell.x, cell.y] = 0f;
            looseResourceKind[cell.x, cell.y] = LooseResourceKind.None;
            looseResourceAmount[cell.x, cell.y] = 0f;
            temperature[cell.x, cell.y] = Mathf.Min(temperature[cell.x, cell.y], InitialTemperature(cell.x, cell.y, CellKind.Wheezewort));
            plantGrowth[cell.x, cell.y] = 1f;
            return true;
        }

        private bool TryFindWheezewortCell(Vector2Int preferred, int searchRadius, out Vector2Int plantCell)
        {
            plantCell = new Vector2Int(-1, -1);
            for (int radius = 0; radius <= searchRadius; radius++)
            {
                for (int y = preferred.y - radius; y <= preferred.y + radius; y++)
                {
                    for (int x = preferred.x - radius; x <= preferred.x + radius; x++)
                    {
                        if (Mathf.Abs(x - preferred.x) != radius && Mathf.Abs(y - preferred.y) != radius)
                        {
                            continue;
                        }

                        if (CanPlaceWheezewortAt(x, y))
                        {
                            plantCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanPlaceWheezewortAt(int x, int y)
        {
            if (!IsInside(x, y) || y < 26 || y > 37 || waterMass[x, y] > 0.05f)
            {
                return false;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            bool inUpperShaft = x >= 39 && x <= 41 && y >= 19 && y <= 34;
            if (inStartRoom || inUpperShaft)
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind != CellKind.Empty && !IsNaturalSolid(kind))
            {
                return false;
            }

            return IceCellsAround(new Vector2Int(x, y), 5) > 0 || y >= 31;
        }

        private int IceCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && cells[x, y] == CellKind.Ice)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

