                    float shape = Mathf.PerlinNoise(x * 0.22f + 73.5f, y * 0.31f + 19.6f);
                    if (shape <= 0.46f || (!IsNaturalSolid(cells[x, y]) && cells[x, y] != CellKind.Empty))
                    {
                        continue;
                    }

                    cells[x, y] = CellKind.PollutedWater;
                    waterMass[x, y] = Mathf.Clamp(mass + shape * 18f, 18f, LiquidTileCapacity);
                    oxygen[x, y] = 0f;
                    carbonDioxide[x, y] = 0f;
                    pollutedOxygen[x, y] = 0.18f;
                    hydrogen[x, y] = 0f;
                    steam[x, y] = 0f;
                    chlorine[x, y] = 0f;
                    naturalGas[x, y] = 0f;
                    sourGas[x, y] = 0f;
                    germs[x, y] = Mathf.Max(germs[x, y], 0.72f);
                    temperature[x, y] = InitialTemperature(x, y, CellKind.PollutedWater);
                }
