        {
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    if (!IsInside(x, y) || IsWorldLiquidCell(cells[x, y]) || !IsNaturalSolid(cells[x, y]))
                    {
                        continue;
                    }

                    float shape = Mathf.PerlinNoise(x * 0.28f + 61.2f, y * 0.33f + 14.9f);
                    if (shape > 0.31f)
                    {
                        cells[x, y] = CellKind.Coal;
                        oxygen[x, y] = 0f;
                        carbonDioxide[x, y] = 0f;
                        pollutedOxygen[x, y] = 0f;
                        hydrogen[x, y] = 0f;
                        steam[x, y] = 0f;
                        chlorine[x, y] = 0f;
                        naturalGas[x, y] = 0f;
                        sourGas[x, y] = 0f;
                        germs[x, y] = 0f;
                        waterMass[x, y] = 0f;
                    }
                }
            }
        }

        private float InitialTemperature(int x, int y, CellKind kind)
        {
            if (kind == CellKind.Ice)
            {
                return -6f;
            }

            if (kind == CellKind.Wheezewort)
            {
                return -8f;
            }

            if (kind == CellKind.AntiEntropyThermoNullifier)
            {
                return -12f;
            }

            if (kind == CellKind.ArborTree)
            {
                return 28f;
            }

            if (kind == CellKind.GrubfruitPlant)
            {
                return 31f;
            }

            if (kind == CellKind.ThimbleReed)
            {
                return 30f;
            }

            if (kind == CellKind.SleetWheat)
            {
                return -8f;
            }

            if (kind == CellKind.Water)
            {
                return y < 8 ? 13f : 18f;
            }

            if (kind == CellKind.PollutedWater)
            {
                return y < 18 ? 18f : 24f;
            }

            if (kind == CellKind.SaltWater)
            {
                return y < 18 ? 16f : 21f;
            }

            if (kind == CellKind.CrudeOil)
            {
                return 58f + Mathf.Clamp(8f - y, 0f, 8f) * 1.7f;
            }

            if (kind == CellKind.Petroleum)
            {
                return 84f + Mathf.Clamp(8f - y, 0f, 8f) * 1.2f;
            }

            if (kind == CellKind.LeakyOilFissure)
            {
                return LeakyOilFissureOutputTemperature;
            }

            if (kind == CellKind.Magma)
            {
                return MagmaTemperature;
            }

            if (kind == CellKind.MagmaVolcano)
            {
                return MagmaTemperature;
            }

            if (kind == CellKind.SteamVent)
            {
                return 86f;
            }

            if (kind == CellKind.WaterGeyser)
            {
                return WaterGeyserOutputTemperature;
            }

            if (kind == CellKind.CoolSteamVent)
            {
                return CoolSteamVentOutputTemperature;
            }

            if (kind == CellKind.SaltWaterGeyser)
            {
                return 74f;
            }

            if (kind == CellKind.CoolSlushGeyser)
            {
                return CoolSlushGeyserOutputTemperature;
            }

            if (kind == CellKind.PollutedWaterVent)
            {
                return PollutedWaterVentOutputTemperature;
            }

            if (kind == CellKind.ChlorineGasVent)
            {
                return 52f;
            }

            if (kind == CellKind.CarbonDioxideVent)
            {
                return 36f;
            }

            if (kind == CellKind.PollutedOxygenVent)
            {
                return PollutedOxygenVentOutputTemperature;
            }

            if (kind == CellKind.HydrogenVent)
            {
                return 64f;
            }

            if (kind == CellKind.NaturalGasVent)
            {
                return 70f;
            }

            if (kind == CellKind.MetalVolcano)
            {
                return MetalVolcanoOutputTemperature;
            }

            bool inStartRoom = x >= 27 && x <= 53 && y >= 18 && y <= 27;
            if (inStartRoom)
            {
                return 22f;
            }

            float variation = Mathf.PerlinNoise(x * 0.09f + 4.3f, y * 0.11f + 17.2f) * 5f - 2.5f;
            if (y <= 6)
            {
                return 45f + variation + (6 - y) * 2.2f;
            }

            if (y >= 30)
            {
                return 9f + variation - (y - 30) * 0.9f;
            }

            if (kind == CellKind.Slime)
            {
                return 31f + variation;
            }

            if (kind == CellKind.BleachStone)
            {
                return 24f + variation;
            }

            return 21f + variation;
        }

        private void CreateWorkers()
        {
            if (workers.Count > 0)
            {
                return;
            }

            SpawnWorker("Ari", new Vector2Int(34, 19), WorkerTint(0));
            SpawnWorker("Bomi", new Vector2Int(40, 20), WorkerTint(1));
            SpawnWorker("Chae", new Vector2Int(46, 19), WorkerTint(2));
        }

        private void EnsureWorkerRecords()
        {
            if (workers.Count > 0)
            {
                return;
            }

            for (int i = 0; i < transform.childCount; i++)
            {
                Transform child = transform.GetChild(i);
                if (!child.name.StartsWith("Duplicant ", StringComparison.Ordinal))
                {
                    continue;
                }

                SpriteRenderer spriteRenderer = child.GetComponent<SpriteRenderer>();
                if (spriteRenderer == null)
                {
                    continue;
                }

                Worker worker = new Worker
                {
                    Name = child.name.Substring("Duplicant ".Length),
                    Transform = child,
                    Renderer = spriteRenderer,
                    Cell = WorldToCell(child.position),
                    Calories = 2800f,
                    Health = 100f,
                    Morale = BaseWorkerMorale,
                    Fatigue = 25f,
                    Bladder = 20f,
                    Experience = 0f,
                    WorkSpeed = 1f,
                    MoveSpeed = 5f,
                    Trait = DefaultWorkerTrait(workers.Count),
                    Interest = DefaultWorkerInterest(workers.Count),
                    Role = DefaultWorkerInterest(workers.Count),
                    StressReaction = DefaultWorkerStressReaction(workers.Count),
                    OverjoyedResponse = DefaultWorkerOverjoyedResponse(workers.Count)
                };
                worker.NarcolepticCooldownSeconds = InitialNarcolepticCooldownSeconds(workers.Count, worker.Trait);
                worker.FlatulenceCooldownSeconds = InitialFlatulenceCooldownSeconds(workers.Count, worker.Trait);

                if (!IsCharacterStandableCell(worker.Cell) && TryFindCharacterStandableCellNear(worker.Cell, 8, worker, out Vector2Int safeCell))
                {
                    worker.Cell = safeCell;
                    worker.Transform.position = CellCenter(safeCell);
                }

                workers.Add(worker);
            }

            if (workers.Count == 0)
            {
                CreateWorkers();
            }
        }

        private void EnsureWorldState()
        {
            bool hasNonEmptyCell = false;
            for (int y = 0; y < WorldHeight && !hasNonEmptyCell; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.Empty)
                    {
                        hasNonEmptyCell = true;
                        break;
                    }
                }
            }

            if (!hasNonEmptyCell)
            {
                maxPower = 100f;
                GenerateWorld();
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
                Log("World data restored.");
            }
        }

        private void StartNewRun()
        {
            ClearWorkers();
            jobs.Clear();
            rooms.Clear();
            pollutedWaterOffgasSources.Clear();
            pollutedDirtOffgasSources.Clear();
            slimeOffgasSources.Clear();
            bleachStoneOffgasSources.Clear();
            dragCells.Clear();
            inspectedCell = null;
            isDraggingCommand = false;
            isPanningCamera = false;

            ResetRunState();
            GenerateWorld();
            CreateWorkers();
            HideStartStatePanel(false);
            SetVisible(endStatePanel, false);

            SetMode(CommandMode.Inspect);
            SetOverlayMode(OverlayMode.Gas);
            RenderTerrain();
            RenderGas();
            RenderOverlay();
            UpdateColonyStatus(true);
            Log("New colony started.");
            UpdateHud();
        }

        private void ShowStartStatePanel()
        {
            startStateVisible = true;
            paused = true;
            UpdateStartStatePanel();
        }

        private void HideStartStatePanel(bool resume)
        {
            startStateVisible = false;
            if (resume && !colonyFailed)
            {
                paused = false;
            }

            SetVisible(startStatePanel, false);
        }

        private void StartBriefedNewRun()
        {
            StartNewRun();
            HideStartStatePanel(true);
            Log("Colony charter accepted. Begin survival operations.");
            UpdateHud();
        }

        private void BeginCurrentRun()
        {
            HideStartStatePanel(true);
            Log("Colony charter accepted. Begin survival operations.");
            UpdateHud();
        }

