        private void ClearWorkers()
        {
            for (int i = transform.childCount - 1; i >= 0; i--)
            {
                Transform child = transform.GetChild(i);
                if (child.name.StartsWith("Duplicant ", StringComparison.Ordinal))
                {
                    DestroyRuntimeObject(child.gameObject);
                }
            }

            workers.Clear();
        }

        private void SpawnWorker(string workerName, Vector2Int cell, Color tint)
        {
            WorkerTrait trait = DefaultWorkerTrait(workers.Count);
            JobCategory interest = DefaultWorkerInterest(workers.Count);
            WorkerStressReaction stressReaction = DefaultWorkerStressReaction(workers.Count);
            WorkerOverjoyedResponse overjoyedResponse = DefaultWorkerOverjoyedResponse(workers.Count);
            if (!IsCharacterStandableCell(cell) && TryFindCharacterStandableCellNear(cell, 8, null, out Vector2Int safeCell))
            {
                cell = safeCell;
            }

            GameObject workerObject = new GameObject("Duplicant " + workerName);
            workerObject.transform.SetParent(transform, false);
            workerObject.transform.position = CellCenter(cell);

            SpriteRenderer spriteRenderer = workerObject.AddComponent<SpriteRenderer>();
            spriteRenderer.sprite = workerSprite;
            spriteRenderer.color = tint;
            spriteRenderer.sortingOrder = 5;

            workers.Add(new Worker
            {
                Name = workerName,
                Transform = workerObject.transform,
                Renderer = spriteRenderer,
                Cell = cell,
                Morale = BaseWorkerMorale,
                Bladder = 20f,
                Experience = 0f,
                WorkSpeed = 0.95f + workers.Count * 0.1f,
                MoveSpeed = 4.6f + workers.Count * 0.35f,
                Trait = trait,
                Interest = interest,
                Role = interest,
                StressReaction = stressReaction,
                OverjoyedResponse = overjoyedResponse,
                NarcolepticCooldownSeconds = InitialNarcolepticCooldownSeconds(workers.Count, trait),
                FlatulenceCooldownSeconds = InitialFlatulenceCooldownSeconds(workers.Count, trait)
            });
        }

        private HatchCritter SpawnHatch(string hatchName, Vector2Int cell, float happiness, float groomedSeconds, float moveTimer, float eatTimer, float reproduction, float coalProduced)
        {
            return SpawnCritter(CritterKind.Hatch, hatchName, cell, happiness, groomedSeconds, moveTimer, eatTimer, reproduction, coalProduced, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f);
        }

        private HatchCritter SpawnCritter(CritterKind kind, string critterName, Vector2Int cell, float happiness, float groomedSeconds, float moveTimer, float eatTimer, float reproduction, float coalProduced, float crudeOilProduced, float carbonDioxideConsumed, float plasticProduced, float foodConsumed, float slimeProduced, float pollutedOxygenConsumed, float pollutedOxygenProduced, float germsProduced, float seafoodProduced)
        {
            string kindName = CritterKindName(kind);
            string resolvedName = string.IsNullOrEmpty(critterName) ? kindName + " " + (hatches.Count + 1) : critterName;
            GameObject hatchObject = new GameObject(kindName + " " + resolvedName);
            hatchObject.transform.SetParent(transform, false);
            hatchObject.transform.position = CellCenter(cell);

            SpriteRenderer spriteRenderer = hatchObject.AddComponent<SpriteRenderer>();
            spriteRenderer.sprite = CritterSprite(kind);
            spriteRenderer.color = CritterRestingColor(kind);
            spriteRenderer.sortingOrder = 4;

            HatchCritter hatch = new HatchCritter
            {
                Kind = kind,
                Name = resolvedName,
                Transform = hatchObject.transform,
                Renderer = spriteRenderer,
                Cell = cell,
                TargetCell = cell,
                Happiness = Mathf.Clamp(happiness <= 0f ? 35f : happiness, 0f, 100f),
                GroomedSeconds = Mathf.Max(0f, groomedSeconds),
                MoveTimer = Mathf.Max(0.1f, moveTimer),
                EatTimer = Mathf.Max(0.1f, eatTimer),
                Reproduction = Mathf.Clamp01(reproduction),
                CoalProduced = Mathf.Max(0f, coalProduced),
                CrudeOilProduced = Mathf.Max(0f, crudeOilProduced),
                CarbonDioxideConsumed = Mathf.Max(0f, carbonDioxideConsumed),
                PlasticProduced = Mathf.Max(0f, plasticProduced),
                FoodConsumed = Mathf.Max(0f, foodConsumed),
                SlimeProduced = Mathf.Max(0f, slimeProduced),
                PollutedOxygenConsumed = Mathf.Max(0f, pollutedOxygenConsumed),
                PollutedOxygenProduced = Mathf.Max(0f, pollutedOxygenProduced),
                GermsProduced = Mathf.Max(0f, germsProduced),
                SeafoodProduced = Mathf.Max(0f, seafoodProduced)
            };
            hatches.Add(hatch);
            return hatch;
        }

