        private void ClearHatches()
        {
            for (int i = hatches.Count - 1; i >= 0; i--)
            {
                if (hatches[i].Transform != null)
                {
                    DestroyRuntimeObject(hatches[i].Transform.gameObject);
                }
            }

            hatches.Clear();
        }

        private void EnsureHatchTransforms()
        {
            for (int i = hatches.Count - 1; i >= 0; i--)
            {
                HatchCritter hatch = hatches[i];
                if (hatch.Transform != null)
                {
                    continue;
                }

                SpawnCritter(hatch.Kind, hatch.Name, hatch.Cell, hatch.Happiness, hatch.GroomedSeconds, hatch.MoveTimer, hatch.EatTimer, hatch.Reproduction, hatch.CoalProduced, hatch.CrudeOilProduced, hatch.CarbonDioxideConsumed, hatch.PlasticProduced, hatch.FoodConsumed, hatch.SlimeProduced, hatch.PollutedOxygenConsumed, hatch.PollutedOxygenProduced, hatch.GermsProduced, hatch.SeafoodProduced);
                hatches.RemoveAt(i);
            }
        }

        private Color WorkerTint(int index)
        {
            switch (index % 8)
            {
                case 0:
                    return new Color(0.35f, 0.86f, 1f);
                case 1:
                    return new Color(0.7f, 0.95f, 0.45f);
                case 2:
                    return new Color(1f, 0.78f, 0.34f);
                case 3:
                    return new Color(0.95f, 0.50f, 0.68f);
                case 4:
                    return new Color(0.58f, 0.72f, 1f);
                case 5:
                    return new Color(0.72f, 0.58f, 0.95f);
                case 6:
                    return new Color(0.62f, 0.96f, 0.78f);
                default:
                    return new Color(1f, 0.62f, 0.42f);
            }
        }

        private WorkerTrait DefaultWorkerTrait(int index)
        {
            switch (Mathf.Abs(index) % 16)
            {
                case 0:
                    return WorkerTrait.MoleHands;
                case 1:
                    return WorkerTrait.QuickLearner;
                case 2:
                    return WorkerTrait.DiversLungs;
                case 3:
                    return WorkerTrait.Gearhead;
                case 4:
                    return WorkerTrait.IronGut;
                case 5:
                    return WorkerTrait.Anxious;
                case 6:
                    return WorkerTrait.LoudSleeper;
                case 7:
                    return WorkerTrait.MouthBreather;
                case 8:
                    return WorkerTrait.SmallBladder;
                case 9:
                    return WorkerTrait.Narcoleptic;
                case 10:
                    return WorkerTrait.Flatulent;
                case 11:
                    return WorkerTrait.Gourmet;
                case 12:
                    return WorkerTrait.Allergic;
                case 13:
                    return WorkerTrait.Twinkletoes;
                case 14:
                    return WorkerTrait.BottomlessStomach;
                default:
                    return WorkerTrait.Nyctophobic;
            }
        }

        private float InitialNarcolepticCooldownSeconds(int index, WorkerTrait trait)
        {
            if (trait != WorkerTrait.Narcoleptic)
            {
                return 0f;
            }

            return NarcolepticNapCooldownSeconds * 0.5f + Mathf.Abs(index % 5) * NarcolepticNapStaggerSeconds;
        }

        private float InitialFlatulenceCooldownSeconds(int index, WorkerTrait trait)
        {
            if (trait != WorkerTrait.Flatulent)
            {
                return 0f;
            }

            return FlatulentIntervalSeconds * 0.45f + Mathf.Abs(index % 6) * FlatulentStaggerSeconds;
        }

        private WorkerTrait NormalizeWorkerTrait(int trait)
        {
            int max = Enum.GetValues(typeof(WorkerTrait)).Length - 1;
            return (WorkerTrait)Mathf.Clamp(trait, 0, max);
        }

