            SetVisible(printingPodOfferPanel, false);

            SetMode(CommandMode.Inspect);
            SetOverlayMode(OverlayMode.Gas);
            hudElementsBound = true;
            return true;
        }

        private void SelectPreviousResearchFocus()
        {
            CycleResearchFocus(-1);
        }

        private void SelectNextResearchFocus()
        {
            CycleResearchFocus(1);
        }

        private void CycleResearchFocus(int direction)
        {
            int focusCount = Enum.GetValues(typeof(ResearchFocus)).Length;
            int next = ((int)selectedResearchFocus + direction) % focusCount;
            if (next < 0)
            {
                next += focusCount;
            }

            selectedResearchFocus = (ResearchFocus)next;
            Log("Research focus set to " + ResearchFocusName(selectedResearchFocus) + ".");
            UpdateHud();
        }

        private void SelectPreviousCrew()
        {
            CycleSelectedCrew(-1);
        }

        private void SelectNextCrew()
        {
            CycleSelectedCrew(1);
        }

        private void SelectPreviousCrewRole()
        {
            CycleSelectedCrewRole(-1);
        }

        private void SelectNextCrewRole()
        {
            CycleSelectedCrewRole(1);
        }

        private void CycleSelectedCrew(int direction)
        {
            if (workers.Count == 0)
            {
                selectedCrewIndex = 0;
                UpdateHud();
                return;
            }

            selectedCrewIndex = (selectedCrewIndex + direction) % workers.Count;
            if (selectedCrewIndex < 0)
            {
                selectedCrewIndex += workers.Count;
            }

            RefreshCrewScheduleButtonLabel();
            RefreshCrewFoodPolicyButtonLabel();
            UpdateHud();
        }

        private void CycleSelectedCrewRole(int direction)
        {
            Worker worker = SelectedCrewWorker();
            if (worker == null)
            {
                Log("No duplicant selected.");
                UpdateHud();
                return;
            }

            int categoryCount = Enum.GetValues(typeof(JobCategory)).Length;
            int next = ((int)worker.Role + direction) % categoryCount;
            if (next < 0)
            {
                next += categoryCount;
            }

            worker.Role = NormalizeJobCategory(next);
            Log(worker.Name + " role set to " + JobCategoryName(worker.Role) + ".");
            UpdateHud();
        }

        private void CycleSelectedCrewSchedule()
        {
            Worker worker = SelectedCrewWorker();
            if (worker == null)
            {
                Log("No duplicant selected.");
                UpdateHud();
                return;
            }

            int next = worker.ScheduleOffsetSteps + 1;
            if (next > CrewScheduleOffsetMax)
            {
                next = CrewScheduleOffsetMin;
            }

            worker.ScheduleOffsetSteps = NormalizeCrewScheduleOffset(next);
            Log(worker.Name + " schedule shift set to " + CrewScheduleOffsetLabel(worker.ScheduleOffsetSteps) + ".");
            RefreshCrewScheduleButtonLabel();
            UpdateHud();
        }

        private void CycleSelectedCrewFoodPolicy()
        {
            Worker worker = SelectedCrewWorker();
            if (worker == null)
            {
                Log("No duplicant selected.");
                UpdateHud();
                return;
            }

            int count = Enum.GetValues(typeof(WorkerFoodPolicyMode)).Length;
            int next = ((int)worker.FoodPolicyOverride + 1) % count;
            worker.FoodPolicyOverride = NormalizeWorkerFoodPolicyMode(next);
            Log(worker.Name + " diet policy set to " + WorkerFoodPolicyLabel(worker.FoodPolicyOverride) + ".");
            RefreshCrewFoodPolicyButtonLabel();
            UpdateHud();
        }

        private void RefreshCrewScheduleButtonLabel()
        {
            if (crewScheduleButton == null)
            {
                return;
            }

            Worker worker = SelectedCrewWorker();
            SetLocalizedText(crewScheduleButton, worker == null ? "Sh+0" : "Sh" + CrewScheduleOffsetLabel(worker.ScheduleOffsetSteps));
        }

        private void RefreshCrewFoodPolicyButtonLabel()
        {
            if (crewFoodPolicyButton == null)
            {
                return;
            }

            Worker worker = SelectedCrewWorker();
            SetLocalizedText(crewFoodPolicyButton, worker == null ? "Diet\nCOL" : "Diet\n" + WorkerFoodPolicyShortLabel(worker.FoodPolicyOverride));
        }

        private void FocusSelectedCrew()
        {
            Worker worker = SelectedCrewWorker();
            if (worker == null)
            {
                Log("No duplicant selected.");
                return;
            }

            if (worker.Transform != null)
            {
                worker.Cell = WorldToCell(worker.Transform.position);
            }

            inspectedCell = worker.Cell;
            SetMode(CommandMode.Inspect);
            if (gameCamera != null)
            {
                Vector3 center = CellCenter(worker.Cell);
                gameCamera.transform.position = new Vector3(center.x, center.y, -10f);
                ClampCamera();
            }

            Log("Focused " + worker.Name + ".");
            UpdateHud();
        }

        private Worker SelectedCrewWorker()
        {
            NormalizeSelectedCrewIndex();
            return workers.Count == 0 ? null : workers[selectedCrewIndex];
        }

        private void NormalizeSelectedCrewIndex()
        {
            if (workers.Count == 0)
            {
                selectedCrewIndex = 0;
                return;
            }

            selectedCrewIndex = Mathf.Clamp(selectedCrewIndex, 0, workers.Count - 1);
        }

        private void EnsureEventSystem()
        {
            EventSystem eventSystem = FindFirstObjectByType<EventSystem>();
            if (eventSystem == null)
            {
                GameObject eventObject = new GameObject("EventSystem");
                eventSystem = eventObject.AddComponent<EventSystem>();
            }

            StandaloneInputModule legacyInputModule = eventSystem.GetComponent<StandaloneInputModule>();
            if (legacyInputModule != null)
            {
                Destroy(legacyInputModule);
            }

            if (eventSystem.GetComponent<InputSystemUIInputModule>() == null)
            {
                eventSystem.gameObject.AddComponent<InputSystemUIInputModule>();
            }
        }

