        private void SelectPreviousJobCategory()
        {
            CycleSelectedJobCategory(-1);
        }

        private void SelectNextJobCategory()
        {
            CycleSelectedJobCategory(1);
        }

        private void CycleSelectedJobCategory(int direction)
        {
            EnsureJobCategoryPolicy();
            int count = JobCategoryCount();
            int selected = ((int)selectedJobCategory + direction) % count;
            if (selected < 0)
            {
                selected += count;
            }

            selectedJobCategory = (JobCategory)selected;
            InvalidateJobPolicyUi();
            UpdateHud();
        }

        private void AdjustSelectedJobCategoryPriority(int delta)
        {
            EnsureJobCategoryPolicy();
            int index = (int)selectedJobCategory;
            int current = jobCategoryPriorityAdjustments[index];
            int adjusted = NormalizeJobCategoryPolicyAdjustment(selectedJobCategory, current + delta);
            if (adjusted == current)
            {
                return;
            }

            jobCategoryPriorityAdjustments[index] = adjusted;
            Log("Labor policy " + JobCategoryName(selectedJobCategory) + " adjusted to " + JobCategoryPriorityLabel(adjusted) + ".");
            InvalidateJobPolicyUi();
            UpdateHud();
        }

        private void ResetJobCategoryPolicies()
        {
            ResetJobCategoryPolicies(true);
        }

        private void ResetJobCategoryPolicies(bool announce)
        {
            EnsureJobCategoryPolicy();
            for (int i = 0; i < jobCategoryPriorityAdjustments.Length; i++)
            {
                jobCategoryPriorityAdjustments[i] = 0;
            }

            selectedJobCategory = JobCategory.Construction;
            if (announce)
            {
                Log("Labor policies reset.");
            }

            InvalidateJobPolicyUi();
        }

        private void InvalidateJobPolicyUi()
        {
            nextJobQueueRefreshTime = -1f;
            jobQueueTextCache = string.Empty;
        }

        private void EnsureJobCategoryPolicy()
        {
            int count = JobCategoryCount();
            if (jobCategoryPriorityAdjustments == null || jobCategoryPriorityAdjustments.Length != count)
            {
                int[] previous = jobCategoryPriorityAdjustments;
                jobCategoryPriorityAdjustments = new int[count];
                if (previous != null)
                {
                    Array.Copy(previous, jobCategoryPriorityAdjustments, Mathf.Min(previous.Length, count));
                }
            }

            for (int i = 0; i < jobCategoryPriorityAdjustments.Length; i++)
            {
                jobCategoryPriorityAdjustments[i] = NormalizeJobCategoryPolicyAdjustment((JobCategory)i, jobCategoryPriorityAdjustments[i]);
            }

            selectedJobCategory = (JobCategory)Mathf.Clamp((int)selectedJobCategory, 0, count - 1);
        }

        private int NormalizeJobCategoryPolicyAdjustment(JobCategory category, int adjustment)
        {
            if (category != JobCategory.Survival && adjustment <= JobCategoryPriorityDisabled)
            {
                return JobCategoryPriorityDisabled;
            }

            return Mathf.Clamp(adjustment, JobCategoryPriorityMin, JobCategoryPriorityMax);
        }

        private int JobCategoryCount()
        {
            return Enum.GetValues(typeof(JobCategory)).Length;
        }

        private static void SetAbsolute(VisualElement element)
        {
            element.style.position = Position.Absolute;
        }

        private static void SetVerticalSlot(VisualElement element, float left, float top, float width, float bottom)
        {
            SetAbsolute(element);
            element.style.left = left;
            element.style.top = top;
            element.style.width = width;
            element.style.bottom = bottom;
        }

        private static void SetFixedSlot(VisualElement element, float left, float top, float width, float height)
        {
            SetAbsolute(element);
            element.style.left = left;
            element.style.top = top;
            element.style.width = width;
            element.style.height = height;
        }

        private static void SetVisible(VisualElement element, bool visible)
        {
            if (element != null)
            {
                element.EnableInClassList("hidden", !visible);
            }
        }

        private void HandleKeyboardShortcuts()
        {
            Keyboard keyboard = Keyboard.current;
            if (keyboard == null)
            {
                return;
            }

            if (startStateVisible)
            {
                if (keyboard.f9Key.wasPressedThisFrame)
                {
                    LoadGame(false);
                }
                else if (keyboard.enterKey.wasPressedThisFrame || keyboard.spaceKey.wasPressedThisFrame)
                {
                    BeginCurrentRun();
                }

                return;
            }

            if (keyboard.digit1Key.wasPressedThisFrame) SetMode(CommandMode.Inspect);
            if (keyboard.digit2Key.wasPressedThisFrame) SetMode(CommandMode.Dig);
            if (keyboard.digit3Key.wasPressedThisFrame) SetMode(CommandMode.Ladder);
            if (keyboard.digit4Key.wasPressedThisFrame) SetMode(CommandMode.Floor);
            if (keyboard.digit5Key.wasPressedThisFrame) SetMode(CommandMode.OxygenDiffuser);
            if (keyboard.digit6Key.wasPressedThisFrame) SetMode(CommandMode.ManualGenerator);
            if (keyboard.digit7Key.wasPressedThisFrame) SetMode(CommandMode.Battery);
            if (keyboard.digit8Key.wasPressedThisFrame) SetMode(CommandMode.Bed);
            if (keyboard.digit9Key.wasPressedThisFrame) SetMode(CommandMode.Planter);
            if (keyboard.digit0Key.wasPressedThisFrame) SetMode(CommandMode.Cancel);
            if (keyboard.dKey.wasPressedThisFrame) SetMode(CommandMode.Deconstruct);
            if (keyboard.sKey.wasPressedThisFrame) SetMode(CommandMode.Mop);
            if (keyboard.aKey.wasPressedThisFrame) SetMode(CommandMode.Repair);
            if (keyboard.periodKey.wasPressedThisFrame) SetMode(CommandMode.Sweep);
            if (keyboard.pKey.wasPressedThisFrame) SetMode(CommandMode.WaterPump);
            if (keyboard.rKey.wasPressedThisFrame) SetMode(CommandMode.ResearchStation);
            if (keyboard.mKey.wasPressedThisFrame) SetMode(CommandMode.MicrobeMusher);
            if (keyboard.oKey.wasPressedThisFrame) SetMode(CommandMode.AirDeodorizer);
            if (keyboard.hKey.wasPressedThisFrame) SetMode(CommandMode.MedicalCot);
            if (keyboard.tKey.wasPressedThisFrame) SetMode(CommandMode.SpaceHeater);
