            if (keyboard.f3Key.wasPressedThisFrame) SetOverlayMode(OverlayMode.Power);
            if (keyboard.f4Key.wasPressedThisFrame) SetOverlayMode(OverlayMode.Germs);
            if (keyboard.f11Key.wasPressedThisFrame) SetOverlayMode(OverlayMode.Plumbing);
            if (keyboard.f12Key.wasPressedThisFrame) SetOverlayMode(OverlayMode.Ventilation);
            if (keyboard.f6Key.wasPressedThisFrame) AdjustSleepStart(-ScheduleStep);
            if (keyboard.f7Key.wasPressedThisFrame) AdjustSleepStart(ScheduleStep);
            if (keyboard.f8Key.wasPressedThisFrame) AdjustSleepEnd(-ScheduleStep);
            if (keyboard.f10Key.wasPressedThisFrame) AdjustSleepEnd(ScheduleStep);
            if (keyboard.f5Key.wasPressedThisFrame) SaveGame(false);
            if (keyboard.f9Key.wasPressedThisFrame) LoadGame(false);
            if (keyboard.leftBracketKey.wasPressedThisFrame) AdjustInspectedJobPriority(-1);
            if (keyboard.rightBracketKey.wasPressedThisFrame) AdjustInspectedJobPriority(1);
            if (keyboard.deleteKey.wasPressedThisFrame) CancelInspectedJob();

            if (keyboard.spaceKey.wasPressedThisFrame)
            {
                TogglePause();
            }

            if (keyboard.equalsKey.wasPressedThisFrame || keyboard.numpadPlusKey.wasPressedThisFrame)
            {
                simulationSpeed = Mathf.Min(4f, simulationSpeed + 1f);
                paused = false;
                Log("Simulation speed x" + simulationSpeed.ToString("0"));
            }

            if (keyboard.minusKey.wasPressedThisFrame || keyboard.numpadMinusKey.wasPressedThisFrame)
            {
                simulationSpeed = Mathf.Max(1f, simulationSpeed - 1f);
                Log("Simulation speed x" + simulationSpeed.ToString("0"));
            }
        }

        private void HandleCameraControls()
        {
            if (gameCamera == null)
            {
                return;
            }

            Keyboard keyboard = Keyboard.current;
            Vector3 movement = Vector3.zero;
            if (keyboard != null)
            {
                if (keyboard.aKey.isPressed || keyboard.leftArrowKey.isPressed) movement.x -= 1f;
                if (keyboard.dKey.isPressed || keyboard.rightArrowKey.isPressed) movement.x += 1f;
                if (keyboard.sKey.isPressed || keyboard.downArrowKey.isPressed) movement.y -= 1f;
                if (keyboard.wKey.isPressed || keyboard.upArrowKey.isPressed) movement.y += 1f;
            }

            if (movement.sqrMagnitude > 0f)
            {
                gameCamera.transform.position += movement.normalized * (gameCamera.orthographicSize * 1.25f * Time.deltaTime);
            }

            Mouse mouse = Mouse.current;
            if (mouse == null)
            {
                ClampCamera();
                return;
            }

            float scroll = mouse.scroll.ReadValue().y;
            if (Mathf.Abs(scroll) > 0.1f)
            {
                gameCamera.orthographicSize = Mathf.Clamp(gameCamera.orthographicSize - scroll * 0.015f, 7f, 28f);
            }

            Vector2 screenPosition = mouse.position.ReadValue();
            if (mouse.middleButton.wasPressedThisFrame)
            {
                isPanningCamera = true;
                lastPanScreenPosition = screenPosition;
            }

            if (mouse.middleButton.wasReleasedThisFrame)
            {
                isPanningCamera = false;
            }

            if (isPanningCamera && mouse.middleButton.isPressed)
            {
                Vector2 delta = screenPosition - lastPanScreenPosition;
                float worldUnitsPerPixel = gameCamera.orthographicSize * 2f / Mathf.Max(1f, Screen.height);
                gameCamera.transform.position -= new Vector3(delta.x, delta.y, 0f) * worldUnitsPerPixel;
                lastPanScreenPosition = screenPosition;
            }

            ClampCamera();
        }

        private void ClampCamera()
        {
            Vector3 position = gameCamera.transform.position;
            position.x = Mathf.Clamp(position.x, 2f, WorldWidth - 2f);
            position.y = Mathf.Clamp(position.y, 2f, WorldHeight - 2f);
            position.z = -10f;
            gameCamera.transform.position = position;
        }

        private void HandlePointerCommands()
        {
            Mouse mouse = Mouse.current;
            if (mouse == null || gameCamera == null)
            {
                return;
            }

            Vector2 screenPosition = mouse.position.ReadValue();
            if (mouse.leftButton.wasPressedThisFrame)
            {
                isDraggingCommand = !IsScreenPositionBlocked(screenPosition);
                dragCells.Clear();
            }

            if (mouse.leftButton.wasReleasedThisFrame)
            {
                isDraggingCommand = false;
                dragCells.Clear();
            }

            if (isDraggingCommand && mouse.leftButton.isPressed && TryScreenToCell(screenPosition, out Vector2Int cell))
            {
                ApplyCommand(cell);
            }

            if (mouse.rightButton.wasPressedThisFrame && !IsScreenPositionBlocked(screenPosition) && TryScreenToCell(screenPosition, out Vector2Int cancelCell))
            {
                CancelJobsAt(cancelCell, true);
            }
        }

        private bool IsScreenPositionBlocked(Vector2 screenPosition)
        {
            if (uiRoot == null || uiRoot.panel == null)
            {
                return false;
            }

            Vector2 panelPosition = RuntimePanelUtils.ScreenToPanel(uiRoot.panel, screenPosition);
            VisualElement picked = uiRoot.panel.Pick(panelPosition);
            return picked != null && picked != uiRoot;
        }

        private bool TryScreenToCell(Vector2 screenPosition, out Vector2Int cell)
        {
            Vector3 world = gameCamera.ScreenToWorldPoint(new Vector3(screenPosition.x, screenPosition.y, Mathf.Abs(gameCamera.transform.position.z)));
            cell = new Vector2Int(Mathf.FloorToInt(world.x), Mathf.FloorToInt(world.y));
            return IsInside(cell.x, cell.y);
        }

        private void ApplyCommand(Vector2Int cell)
        {
            int key = Key(cell.x, cell.y);
            if (!dragCells.Add(key))
            {
                return;
            }

            inspectedCell = cell;

            switch (currentMode)
            {
                case CommandMode.Inspect:
                    overlayDirty = true;
                    break;
                case CommandMode.MoveHere:
                    QueueMoveHere(cell);
                    break;
                case CommandMode.Dig:
                    QueueDig(cell);
                    break;
                case CommandMode.Cancel:
                    CancelJobsAt(cell, false);
                    break;
                case CommandMode.Deconstruct:
                    QueueDeconstruct(cell);
                    break;
                case CommandMode.Mop:
                    QueueMop(cell);
                    break;
                case CommandMode.Disinfect:
                    QueueDisinfect(cell);
                    break;
                case CommandMode.Repair:
                    QueueRepair(cell);
                    break;
                case CommandMode.Sweep:
                    QueueSweep(cell);
                    break;
                case CommandMode.Harvest:
                    QueueHarvest(cell);
                    break;
                case CommandMode.ButcherCritter:
                    QueueButcherCritter(cell);
                    break;
                case CommandMode.WrangleCritter:
                    QueueWrangleCritter(cell);
                    break;
                case CommandMode.PriorityUp:
                    AdjustJobPriorityAt(cell, 1, false);
                    break;
                case CommandMode.PriorityDown:
                    AdjustJobPriorityAt(cell, -1, false);
                    break;
                case CommandMode.YellowAlert:
                    ToggleJobYellowAlertAt(cell, false);
                    break;
                case CommandMode.ToggleBuildingEnabled:
                    ToggleBuildingEnabledAt(cell, false);
                    break;
                case CommandMode.CopySettings:
                    CopyOrPasteBuildingSettingsAt(cell, false);
                    break;
                default:
                    QueueBuild(cell, currentMode);
                    break;
            }
        }

        private void QueueMoveHere(Vector2Int cell)
        {
            Worker worker = SelectedCrewWorker();
            if (worker == null)
            {
                Log("Move order blocked: no duplicant selected.");
                UpdateHud();
                return;
            }

            if (worker.Health <= 0f)
            {
                Log("Move order blocked: selected duplicant is incapacitated.");
                UpdateHud();
                return;
            }

            if (!IsCharacterStandableCell(cell))
            {
                Log("Move order blocked: target tile is not standable.");
                UpdateHud();
                return;
            }

            Job moveJob = CreateMoveToJob(worker, cell);
            if (!TryFindPathToJob(worker.Cell, moveJob, out _))
            {
                Log("Move order blocked: no reachable path for " + worker.Name + ".");
                UpdateHud();
                return;
            }

            if (!TryFindSafePathToJob(worker, moveJob, out List<Vector2Int> path))
            {
                Log("Move order blocked: route is unsafe for " + worker.Name + ".");
                UpdateHud();
                return;
            }

            RemoveMoveToJobsFor(worker.Name);
            ClearAssignment(worker);
            if (!AssignJob(worker, moveJob, path))
            {
                Log("Move order blocked: route is unsafe for " + worker.Name + ".");
                UpdateHud();
                return;
            }

            jobs.Add(moveJob);
            inspectedCell = cell;
            InvalidateJobPolicyUi();
            overlayDirty = true;
            Log("Move order issued: " + worker.Name + " moving to " + cell.x + ", " + cell.y + ".");
            UpdateHud();
        }

        private Job CreateMoveToJob(Worker worker, Vector2Int cell)
        {
            return new Job(JobType.MoveTo, cell, 0.1f)
            {
                AutoGenerated = true,
                Priority = 9,
                TargetWorkerName = worker == null ? string.Empty : worker.Name
            };
        }

        private void RemoveMoveToJobsFor(string workerName)
        {
            if (string.IsNullOrEmpty(workerName))
            {
                return;
            }

            for (int i = jobs.Count - 1; i >= 0; i--)
            {
                Job job = jobs[i];
                if (job.Type != JobType.MoveTo || job.TargetWorkerName != workerName)
                {
                    continue;
                }

                if (job.AssignedWorker != null)
                {
                    ClearAssignment(job.AssignedWorker);
                }

                jobs.RemoveAt(i);
            }
        }

        private void SetMode(CommandMode mode)
        {
            currentMode = mode;
            if (mode == CommandMode.CopySettings)
            {
                copiedSettingsAvailable = false;
            }

            foreach (KeyValuePair<CommandMode, Button> pair in modeButtons)
            {
                pair.Value.EnableInClassList("mode-selected", pair.Key == currentMode);
            }

            overlayDirty = true;
        }

        private void SetOverlayMode(OverlayMode mode)
        {
            currentOverlayMode = mode;
            renderedLegendOverlayMode = (OverlayMode)(-1);
            foreach (KeyValuePair<OverlayMode, Button> pair in overlayButtons)
            {
                pair.Value.EnableInClassList("overlay-selected", pair.Key == currentOverlayMode);
            }

            gasDirty = true;
            overlayDirty = true;
        }

        private void InvalidateRooms()
        {
            roomsDirty = true;
            if (currentOverlayMode == OverlayMode.Rooms)
            {
                gasDirty = true;
            }

            overlayDirty = true;
        }

        private void AdjustSleepStart(float delta)
        {
            sleepStartCycleTime = NormalizeCycleTime(sleepStartCycleTime + delta);
            NormalizeSleepWindow();
            Log("Sleep starts at " + CycleClockLabel(sleepStartCycleTime) + ".");
        }

        private void AdjustSleepEnd(float delta)
        {
            sleepEndCycleTime = NormalizeCycleTime(sleepEndCycleTime + delta);
            NormalizeSleepWindow();
            Log("Wake time set to " + CycleClockLabel(sleepEndCycleTime) + ".");
        }

        private float NormalizeCycleTime(float value)
        {
            value %= 1f;
            return value < 0f ? value + 1f : value;
        }

        private float SleepWindowDuration()
        {
            return sleepStartCycleTime <= sleepEndCycleTime
                ? sleepEndCycleTime - sleepStartCycleTime
                : 1f - sleepStartCycleTime + sleepEndCycleTime;
        }

        private void NormalizeSleepWindow()
        {
            float duration = SleepWindowDuration();
            if (duration < 0.12f)
            {
                sleepEndCycleTime = NormalizeCycleTime(sleepStartCycleTime + 0.12f);
            }
            else if (duration > 0.56f)
            {
                sleepEndCycleTime = NormalizeCycleTime(sleepStartCycleTime + 0.56f);
            }
        }

        private void AdjustInspectedJobPriority(int delta)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            AdjustJobPriorityAt(inspectedCell.Value, delta);
        }

        private void AdjustJobPriorityAt(Vector2Int cell, int delta, bool refreshHud = true)
        {
            Job job = FindAnyJobAt(cell);
            if (job == null)
            {
                return;
            }

            int currentPriority = JobPriority(job);
            int nextPriority = Mathf.Clamp(currentPriority + delta, 1, 10);
            if (nextPriority == currentPriority && job.Priority == nextPriority)
            {
                return;
            }

            job.Priority = nextPriority;
            overlayDirty = true;
            InvalidateJobPolicyUi();
            Log(JobLabel(job) + " priority " + job.Priority + ".");
            if (refreshHud)
            {
                UpdateHud();
            }
        }

        private void ToggleInspectedJobYellowAlert()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            ToggleJobYellowAlertAt(inspectedCell.Value);
        }

        private void ToggleJobYellowAlertAt(Vector2Int cell, bool refreshHud = true)
        {
            Job job = FindAnyJobAt(cell);
            if (job == null)
            {
                return;
            }

            job.YellowAlert = !job.YellowAlert;
            if (job.YellowAlert)
            {
                job.Priority = Mathf.Max(JobPriority(job), 10);
                job.AgeSeconds = JobAgingMaxSeconds;
                yellowAlertToggles++;
                milestoneYellowAlert = true;
                foreach (Worker worker in workers)
                {
                    if (ShouldInterruptAssignedJobForYellowAlert(worker))
                    {
                        ClearAssignment(worker);
                    }
                }
            }

            InvalidateJobPolicyUi();
            overlayDirty = true;
            Log(JobLabel(job) + (job.YellowAlert ? " marked Yellow Alert." : " cleared Yellow Alert."));
            if (refreshHud)
            {
                UpdateHud();
            }
        }

        private void ToggleBuildingEnabledAt(Vector2Int cell, bool refreshHud = true)
        {
            if (!IsInside(cell.x, cell.y) || !IsDisablableBuilding(cells[cell.x, cell.y]))
            {
                return;
            }

            buildingDisabled[cell.x, cell.y] = !buildingDisabled[cell.x, cell.y];
            if (buildingDisabled[cell.x, cell.y])
            {
                foreach (Worker worker in workers)
                {
                    if (worker.AssignedJob != null && worker.AssignedJob.Cell == cell && !IsJobValid(worker.AssignedJob))
                    {
                        ClearAssignment(worker);
                    }
                }
            }

            overlayDirty = true;
            if (cells[cell.x, cell.y] == CellKind.MechanizedAirlock || cells[cell.x, cell.y] == CellKind.BunkerDoor)
            {
                terrainDirty = true;
                gasDirty = true;
                InvalidateRooms();
            }

            InvalidateJobPolicyUi();
            Log((buildingDisabled[cell.x, cell.y] ? "Building disabled: " : "Building enabled: ") + CellLabel(cells[cell.x, cell.y]) + ".");
            if (refreshHud)
            {
                UpdateHud();
            }
        }

        private void CopyOrPasteBuildingSettingsAt(Vector2Int cell, bool refreshHud = true)
        {
            if (!HasCopyableBuildingSettings(cell))
            {
                return;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (!copiedSettingsAvailable || copiedSettingsKind != kind)
            {
                CopyBuildingSettingsFrom(cell);
                Log("Settings copied from " + CellLabel(kind) + ".");
                if (refreshHud)
                {
                    UpdateHud();
                }

                return;
            }

            ApplyCopiedBuildingSettingsTo(cell);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            UpdateSmartBatterySignalState(cell.x, cell.y);
            UpdateAutomationWires();
            Log("Settings pasted to " + CellLabel(kind) + ".");
            if (refreshHud)
            {
                UpdateHud();
            }
        }

        private bool HasCopyableBuildingSettings(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && IsCopyableSettingsKind(cells[cell.x, cell.y]);
        }

        private bool IsCopyableSettingsKind(CellKind kind)
        {
            return IsDisablableBuilding(kind) ||
                kind == CellKind.StorageBin ||
                kind == CellKind.ConveyorLoader ||
                kind == CellKind.ConveyorReceptacle ||
                kind == CellKind.ShippingRailSensor ||
                kind == CellKind.ShippingRailMeter ||
                kind == CellKind.SignalSwitch ||
                kind == CellKind.LiquidPipeSensor ||
                kind == CellKind.LiquidFilter ||
                kind == CellKind.LiquidValve ||
                kind == CellKind.GasPipeSensor ||
                kind == CellKind.GasFilter ||
                kind == CellKind.GasValve ||
                kind == CellKind.AutomationBufferGate ||
                kind == CellKind.AutomationFilterGate ||
                kind == CellKind.AutomationCycleSensor ||
                kind == CellKind.AutomationTimerSensor ||
                kind == CellKind.SmartBattery ||
                IsDoorAccessControlledKind(kind) ||
                IsDirectionalBridge(kind) ||
                IsAdjustableThresholdSensor(kind);
        }

        private void CopyBuildingSettingsFrom(Vector2Int cell)
        {
            copiedSettingsAvailable = true;
            copiedSettingsSourceCell = cell;
            copiedSettingsKind = cells[cell.x, cell.y];
            copiedSettingsBuildingDisabled = IsBuildingDisabled(cell);
            copiedSettingsStorageFilter = CopyableStorageFilterAt(cell);
            copiedSettingsStorageSweepOnly = cells[cell.x, cell.y] == CellKind.StorageBin && storageSweepOnly[cell.x, cell.y];
            copiedSettingsDoorAccessMode = DoorAccessModeAt(cell.x, cell.y);
            copiedSettingsBridgeDirection = BridgeDirectionAt(cell.x, cell.y);
            copiedSettingsThresholdCondition = ThresholdSensorConditionAt(cell.x, cell.y);
            copiedSettingsThresholdValue = CopyableThresholdValueAt(cell);
            copiedSettingsLiquidSensorMode = liquidSensorMode[cell.x, cell.y];
            copiedSettingsLiquidFilterMode = liquidFilterMode[cell.x, cell.y];
            copiedSettingsGasSensorMode = gasSensorMode[cell.x, cell.y];
            copiedSettingsGasFilterMode = gasFilterMode[cell.x, cell.y];
            copiedSettingsLiquidValveFlowLimit = LiquidValveFlowLimitAt(cell.x, cell.y);
            copiedSettingsGasValveFlowLimit = GasValveFlowLimitAt(cell.x, cell.y);
            copiedSettingsShippingRailMeterFlowLimit = ShippingRailMeterFlowLimitAt(cell.x, cell.y);
            copiedSettingsSmartBatteryLowThreshold = SmartBatteryLowThresholdAt(cell.x, cell.y);
            copiedSettingsSmartBatteryHighThreshold = SmartBatteryHighThresholdAt(cell.x, cell.y);
            copiedSettingsSignalSwitchState = automationSwitchState[cell.x, cell.y];
            copiedSettingsAutomationBufferHoldSeconds = AutomationBufferHoldSecondsAt(cell.x, cell.y);
            copiedSettingsAutomationFilterDelaySeconds = AutomationFilterDelaySecondsAt(cell.x, cell.y);
            copiedSettingsAutomationCycleSensorStart = CycleSensorStartAt(cell.x, cell.y);
            copiedSettingsAutomationCycleSensorEnd = CycleSensorEndAt(cell.x, cell.y);
            copiedSettingsAutomationTimerGreenSeconds = AutomationTimerGreenSecondsAt(cell.x, cell.y);
            copiedSettingsAutomationTimerRedSeconds = AutomationTimerRedSecondsAt(cell.x, cell.y);
        }

        private void ApplyCopiedBuildingSettingsTo(Vector2Int cell)
        {
            CellKind kind = cells[cell.x, cell.y];
            if (IsDisablableBuilding(kind))
            {
                buildingDisabled[cell.x, cell.y] = copiedSettingsBuildingDisabled;
            }

            ApplyCopyableStorageFilterTo(cell, copiedSettingsStorageFilter);
            if (kind == CellKind.StorageBin)
            {
                storageSweepOnly[cell.x, cell.y] = copiedSettingsStorageSweepOnly;
            }

            if (IsDoorAccessControlledKind(kind))
            {
                doorAccessMode[cell.x, cell.y] = copiedSettingsDoorAccessMode;
            }

            if (IsDirectionalBridge(kind))
            {
                bridgeDirection[cell.x, cell.y] = copiedSettingsBridgeDirection;
            }

            ApplyCopyableThresholdValueTo(cell, copiedSettingsThresholdValue, copiedSettingsThresholdCondition);

            if (kind == CellKind.LiquidPipeSensor)
            {
                liquidSensorMode[cell.x, cell.y] = copiedSettingsLiquidSensorMode;
            }
            else if (kind == CellKind.LiquidFilter)
            {
                liquidFilterMode[cell.x, cell.y] = copiedSettingsLiquidFilterMode;
            }
            else if (kind == CellKind.LiquidValve)
            {
                liquidValveFlowLimit[cell.x, cell.y] = copiedSettingsLiquidValveFlowLimit;
                liquidValveFlowRemaining[cell.x, cell.y] = Mathf.Min(liquidValveFlowRemaining[cell.x, cell.y], copiedSettingsLiquidValveFlowLimit);
            }
            else if (kind == CellKind.GasPipeSensor)
            {
                gasSensorMode[cell.x, cell.y] = copiedSettingsGasSensorMode;
            }
            else if (kind == CellKind.GasFilter)
            {
                gasFilterMode[cell.x, cell.y] = copiedSettingsGasFilterMode;
            }
            else if (kind == CellKind.GasValve)
            {
                gasValveFlowLimit[cell.x, cell.y] = copiedSettingsGasValveFlowLimit;
                gasValveFlowRemaining[cell.x, cell.y] = Mathf.Min(gasValveFlowRemaining[cell.x, cell.y], copiedSettingsGasValveFlowLimit);
            }
            else if (kind == CellKind.ShippingRailMeter)
            {
                shippingRailMeterFlowLimit[cell.x, cell.y] = copiedSettingsShippingRailMeterFlowLimit;
                shippingRailMeterFlowRemaining[cell.x, cell.y] = Mathf.Min(shippingRailMeterFlowRemaining[cell.x, cell.y], copiedSettingsShippingRailMeterFlowLimit);
            }
            else if (kind == CellKind.SignalSwitch)
            {
                automationSwitchState[cell.x, cell.y] = copiedSettingsSignalSwitchState;
            }
            else if (kind == CellKind.AutomationBufferGate)
            {
                automationBufferHoldSeconds[cell.x, cell.y] = copiedSettingsAutomationBufferHoldSeconds;
                automationBufferRemainingSeconds[cell.x, cell.y] = Mathf.Min(automationBufferRemainingSeconds[cell.x, cell.y], copiedSettingsAutomationBufferHoldSeconds);
            }
            else if (kind == CellKind.AutomationFilterGate)
            {
                automationFilterDelaySeconds[cell.x, cell.y] = copiedSettingsAutomationFilterDelaySeconds;
                automationFilterProgressSeconds[cell.x, cell.y] = Mathf.Min(automationFilterProgressSeconds[cell.x, cell.y], copiedSettingsAutomationFilterDelaySeconds);
            }
            else if (kind == CellKind.AutomationCycleSensor)
            {
                automationCycleSensorStart[cell.x, cell.y] = copiedSettingsAutomationCycleSensorStart;
                automationCycleSensorEnd[cell.x, cell.y] = copiedSettingsAutomationCycleSensorEnd;
            }
            else if (kind == CellKind.AutomationTimerSensor)
            {
                automationTimerGreenSeconds[cell.x, cell.y] = copiedSettingsAutomationTimerGreenSeconds;
                automationTimerRedSeconds[cell.x, cell.y] = copiedSettingsAutomationTimerRedSeconds;
                automationTimerElapsedSeconds[cell.x, cell.y] = Mathf.Repeat(automationTimerElapsedSeconds[cell.x, cell.y], AutomationTimerCycleSecondsAt(cell.x, cell.y));
            }
            else if (kind == CellKind.SmartBattery)
            {
                smartBatteryLowThreshold[cell.x, cell.y] = copiedSettingsSmartBatteryLowThreshold;
                smartBatteryHighThreshold[cell.x, cell.y] = copiedSettingsSmartBatteryHighThreshold;
            }
        }

        private StorageFilter CopyableStorageFilterAt(Vector2Int cell)
        {
            switch (cells[cell.x, cell.y])
            {
                case CellKind.StorageBin:
                    return storageBinFilter[cell.x, cell.y];
                case CellKind.ConveyorLoader:
                    return conveyorLoaderFilter[cell.x, cell.y];
                case CellKind.ConveyorReceptacle:
                    return conveyorReceptacleFilter[cell.x, cell.y];
                case CellKind.ShippingRailSensor:
                    return shippingRailSensorFilter[cell.x, cell.y];
                default:
                    return StorageFilter.All;
            }
        }

        private void ApplyCopyableStorageFilterTo(Vector2Int cell, StorageFilter filter)
        {
            switch (cells[cell.x, cell.y])
            {
                case CellKind.StorageBin:
                    storageBinFilter[cell.x, cell.y] = filter;
                    break;
                case CellKind.ConveyorLoader:
                    conveyorLoaderFilter[cell.x, cell.y] = filter;
                    break;
                case CellKind.ConveyorReceptacle:
                    conveyorReceptacleFilter[cell.x, cell.y] = filter;
                    break;
                case CellKind.ShippingRailSensor:
                    shippingRailSensorFilter[cell.x, cell.y] = filter;
                    break;
            }
        }

        private float CopyableThresholdValueAt(Vector2Int cell)
        {
            switch (cells[cell.x, cell.y])
            {
                case CellKind.AtmoSensor:
                    return AtmoSensorThresholdAt(cell.x, cell.y);
                case CellKind.ThermoSensor:
                    return ThermoSensorThresholdAt(cell.x, cell.y);
                case CellKind.HydroSensor:
                    return HydroSensorThresholdAt(cell.x, cell.y);
                case CellKind.GermSensor:
                    return GermSensorThresholdAt(cell.x, cell.y);
                case CellKind.WeightPlate:
                    return WeightPlateThresholdAt(cell.x, cell.y);
                case CellKind.CritterSensor:
                    return CritterSensorThresholdAt(cell.x, cell.y);
                default:
                    return 0f;
            }
        }

        private void ApplyCopyableThresholdValueTo(Vector2Int cell, float threshold, ThresholdSensorCondition condition)
        {
            switch (cells[cell.x, cell.y])
            {
                case CellKind.AtmoSensor:
                    atmoSensorThreshold[cell.x, cell.y] = Mathf.Clamp(threshold, AtmoSensorPressureMin, AtmoSensorPressureMax);
                    atmoSensorCondition[cell.x, cell.y] = condition;
                    break;
                case CellKind.ThermoSensor:
                    thermoSensorThreshold[cell.x, cell.y] = Mathf.Clamp(threshold, ThermoSensorTemperatureMin, ThermoSensorTemperatureMax);
                    thermoSensorCondition[cell.x, cell.y] = condition;
                    break;
                case CellKind.HydroSensor:
                    hydroSensorThreshold[cell.x, cell.y] = Mathf.Clamp(threshold, HydroSensorLiquidMin, HydroSensorLiquidMax);
                    hydroSensorCondition[cell.x, cell.y] = condition;
                    break;
                case CellKind.GermSensor:
                    germSensorThreshold[cell.x, cell.y] = Mathf.Clamp(threshold, GermSensorMin, GermSensorMax);
                    germSensorCondition[cell.x, cell.y] = condition;
                    break;
                case CellKind.WeightPlate:
                    weightPlateThreshold[cell.x, cell.y] = Mathf.Clamp(threshold, WeightPlateMin, WeightPlateMax);
                    weightPlateCondition[cell.x, cell.y] = condition;
                    break;
                case CellKind.CritterSensor:
                    critterSensorThreshold[cell.x, cell.y] = Mathf.Clamp(threshold, CritterSensorMin, CritterSensorMax);
                    critterSensorCondition[cell.x, cell.y] = condition;
                    break;
            }
        }

        private void CancelInspectedJob()
        {
            if (!inspectedCell.HasValue || FindAnyJobAt(inspectedCell.Value) == null)
            {
                return;
            }

            CancelJobsAt(inspectedCell.Value, true);
        }

