        private void UpdateInspectControls()
        {
            Job inspectedJob = null;
            bool jobVisible = inspectedCell.HasValue && (inspectedJob = FindAnyJobAt(inspectedCell.Value)) != null;
            SetInspectControlsVisible(jobVisible);
            if (jobVisible)
            {
                if (yellowAlertButton != null)
                {
                    yellowAlertButton.text = Localize(inspectedJob.YellowAlert ? "Yellow\nON" : "Yellow\nOFF");
                    yellowAlertButton.EnableInClassList("mode-selected", inspectedJob.YellowAlert);
                }

                return;
            }

            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            bool inside = IsInside(cell.x, cell.y);
            bool storageVisible = inside && cells[cell.x, cell.y] == CellKind.StorageBin;
            bool switchVisible = inside && cells[cell.x, cell.y] == CellKind.SignalSwitch;
            bool thresholdSensorVisible = inside && IsAdjustableThresholdSensor(cells[cell.x, cell.y]);
            bool automationCycleSensorVisible = inside && cells[cell.x, cell.y] == CellKind.AutomationCycleSensor;
            bool automationTimerSensorVisible = inside && cells[cell.x, cell.y] == CellKind.AutomationTimerSensor;
            bool smartBatteryVisible = inside && cells[cell.x, cell.y] == CellKind.SmartBattery;
            bool reservoirEmptyVisible = inside && (cells[cell.x, cell.y] == CellKind.LiquidReservoir || cells[cell.x, cell.y] == CellKind.GasReservoir);
            bool pipeEmptyVisible = inside && (liquidPipe[cell.x, cell.y] || gasPipe[cell.x, cell.y]);
            bool railDropVisible = inside && shippingRail[cell.x, cell.y];
            if (signalSwitchButton != null)
            {
                SetVisible(signalSwitchButton, storageVisible || switchVisible || thresholdSensorVisible || automationCycleSensorVisible || automationTimerSensorVisible || smartBatteryVisible || reservoirEmptyVisible || pipeEmptyVisible || railDropVisible);
