        private void CycleInspectedStorageFilter()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return;
            }

            int count = Enum.GetValues(typeof(StorageFilter)).Length;
            storageBinFilter[cell.x, cell.y] = (StorageFilter)(((int)storageBinFilter[cell.x, cell.y] + 1) % count);
            Log("Storage Bin filter set to " + StorageFilterName(storageBinFilter[cell.x, cell.y]) + ".");
            overlayDirty = true;
            UpdateHud();
        }

