        private bool IsAdjustableThresholdSensor(CellKind kind)
        {
            return kind == CellKind.AtmoSensor || kind == CellKind.ThermoSensor || kind == CellKind.HydroSensor || kind == CellKind.GermSensor || kind == CellKind.WeightPlate || kind == CellKind.CritterSensor;
        }

        private string ThresholdSensorLabel(CellKind kind)
        {
            if (kind == CellKind.ThermoSensor)
            {
                return "Thermo Sensor";
            }

            if (kind == CellKind.HydroSensor)
            {
                return "Hydro Sensor";
            }

            if (kind == CellKind.GermSensor)
            {
                return "Germ Sensor";
            }

            if (kind == CellKind.WeightPlate)
            {
                return "Weight Plate";
            }

            if (kind == CellKind.CritterSensor)
            {
                return "Critter Sensor";
            }

            return "Atmo Sensor";
        }

        private string ThresholdSensorConditionName(ThresholdSensorCondition condition)
        {
            return condition == ThresholdSensorCondition.BelowOrEqual ? "below threshold" : "above threshold";
        }

        private string ThresholdSensorConditionShortName(ThresholdSensorCondition condition)
        {
            return condition == ThresholdSensorCondition.BelowOrEqual ? "Below" : "Above";
        }

        private void AdjustInspectedThresholdSensor(int direction)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || !IsAdjustableThresholdSensor(cells[cell.x, cell.y]))
            {
                return;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (kind == CellKind.AtmoSensor)
            {
                atmoSensorThreshold[cell.x, cell.y] = Mathf.Clamp(AtmoSensorThresholdAt(cell.x, cell.y) + AtmoSensorPressureStep * direction, AtmoSensorPressureMin, AtmoSensorPressureMax);
                Log("Atmo Sensor threshold set to " + atmoSensorThreshold[cell.x, cell.y].ToString("0.0") + " kg.");
            }
            else if (kind == CellKind.ThermoSensor)
            {
                thermoSensorThreshold[cell.x, cell.y] = Mathf.Clamp(ThermoSensorThresholdAt(cell.x, cell.y) + ThermoSensorTemperatureStep * direction, ThermoSensorTemperatureMin, ThermoSensorTemperatureMax);
                Log("Thermo Sensor threshold set to " + thermoSensorThreshold[cell.x, cell.y].ToString("0") + " C.");
            }
            else if (kind == CellKind.HydroSensor)
            {
                hydroSensorThreshold[cell.x, cell.y] = Mathf.Clamp(HydroSensorThresholdAt(cell.x, cell.y) + HydroSensorLiquidStep * direction, HydroSensorLiquidMin, HydroSensorLiquidMax);
                Log("Hydro Sensor threshold set to " + hydroSensorThreshold[cell.x, cell.y].ToString("0") + " kg.");
            }
            else if (kind == CellKind.GermSensor)
            {
                germSensorThreshold[cell.x, cell.y] = Mathf.Clamp(GermSensorThresholdAt(cell.x, cell.y) + GermSensorStep * direction, GermSensorMin, GermSensorMax);
                Log("Germ Sensor threshold set to " + Mathf.RoundToInt(germSensorThreshold[cell.x, cell.y] * 100f) + "%.");
            }
            else if (kind == CellKind.WeightPlate)
            {
                weightPlateThreshold[cell.x, cell.y] = Mathf.Clamp(WeightPlateThresholdAt(cell.x, cell.y) + WeightPlateStep * direction, WeightPlateMin, WeightPlateMax);
                Log("Weight Plate threshold set to " + weightPlateThreshold[cell.x, cell.y].ToString("0") + " kg.");
            }
            else if (kind == CellKind.CritterSensor)
            {
                critterSensorThreshold[cell.x, cell.y] = Mathf.Clamp(CritterSensorThresholdAt(cell.x, cell.y) + CritterSensorStep * direction, CritterSensorMin, CritterSensorMax);
                Log("Critter Sensor threshold set to " + critterSensorThreshold[cell.x, cell.y].ToString("0") + ".");
            }

            overlayDirty = true;
            UpdateAutomationWires();
            UpdateHud();
        }

        private void AdjustInspectedSmartBatteryThreshold(int direction)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.SmartBattery)
            {
                return;
            }

            float lowThreshold = SmartBatteryLowThresholdAt(cell.x, cell.y);
            float highThreshold = SmartBatteryHighThresholdAt(cell.x, cell.y);
            if (smartBatteryEditingHigh)
            {
                highThreshold = Mathf.Clamp(
                    highThreshold + SmartBatteryThresholdStep * direction,
                    lowThreshold + SmartBatteryThresholdMinGap,
                    SmartBatteryThresholdMax);
                smartBatteryHighThreshold[cell.x, cell.y] = highThreshold;
                Log("Smart Battery high threshold set to " + Mathf.RoundToInt(highThreshold * 100f) + "%.");
            }
            else
            {
                lowThreshold = Mathf.Clamp(
                    lowThreshold + SmartBatteryThresholdStep * direction,
                    SmartBatteryThresholdMin,
                    highThreshold - SmartBatteryThresholdMinGap);
                smartBatteryLowThreshold[cell.x, cell.y] = lowThreshold;
                Log("Smart Battery low threshold set to " + Mathf.RoundToInt(lowThreshold * 100f) + "%.");
            }

            UpdateSmartBatterySignalState(cell.x, cell.y);
            terrainDirty = true;
            overlayDirty = true;
            UpdateAutomationWires();
            UpdateHud();
        }

        private void AdjustInspectedConduitValveFlow(int direction)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y))
            {
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidValve)
            {
                liquidValveFlowLimit[cell.x, cell.y] = Mathf.Clamp(
                    LiquidValveFlowLimitAt(cell.x, cell.y) + LiquidValveFlowStep * direction,
                    LiquidValveMinFlow,
                    LiquidValveFlowLimitMax);
                Log("Liquid Valve flow set to " + liquidValveFlowLimit[cell.x, cell.y].ToString("0.0") + " kg/s.");
            }
            else if (cells[cell.x, cell.y] == CellKind.GasValve)
            {
                gasValveFlowLimit[cell.x, cell.y] = Mathf.Clamp(
                    GasValveFlowLimitAt(cell.x, cell.y) + GasValveFlowStep * direction,
                    GasValveMinFlow,
                    GasValveFlowLimitMax);
                Log("Gas Valve flow set to " + gasValveFlowLimit[cell.x, cell.y].ToString("0.00") + " kg/s.");
            }
            else
            {
                return;
            }

            gasDirty = true;
            overlayDirty = true;
            UpdateHud();
        }

