        private void AdjustInspectedAutomationBufferHold(int direction)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.AutomationBufferGate)
            {
                return;
            }

            float holdSeconds = Mathf.Clamp(
                AutomationBufferHoldSecondsAt(cell.x, cell.y) + AutomationBufferHoldStepSeconds * direction,
                AutomationBufferHoldMinSeconds,
                AutomationBufferHoldMaxSeconds);
            automationBufferHoldSeconds[cell.x, cell.y] = holdSeconds;
            automationBufferRemainingSeconds[cell.x, cell.y] = Mathf.Min(automationBufferRemainingSeconds[cell.x, cell.y], holdSeconds);
            overlayDirty = true;
            Log("Automation Buffer Gate hold set to " + holdSeconds.ToString("0") + "s.");
            UpdateAutomationWires();
            UpdateHud();
        }

