        private void AdjustInspectedAutomationCycleSensorTime(int direction)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.AutomationCycleSensor)
            {
                return;
            }

            float delta = AutomationCycleSensorStep * direction;
            if (cycleSensorEditingEnd)
            {
                automationCycleSensorEnd[cell.x, cell.y] = NormalizeCycleTime(CycleSensorEndAt(cell.x, cell.y) + delta);
                if (CycleSensorWindowDuration(cell.x, cell.y) < AutomationCycleSensorMinWindow)
                {
                    automationCycleSensorEnd[cell.x, cell.y] = NormalizeCycleTime(CycleSensorStartAt(cell.x, cell.y) + AutomationCycleSensorMinWindow);
                }

                Log("Automation Cycle Sensor end set to " + CycleClockLabel(automationCycleSensorEnd[cell.x, cell.y]) + ".");
            }
            else
            {
                automationCycleSensorStart[cell.x, cell.y] = NormalizeCycleTime(CycleSensorStartAt(cell.x, cell.y) + delta);
                if (CycleSensorWindowDuration(cell.x, cell.y) < AutomationCycleSensorMinWindow)
                {
                    automationCycleSensorStart[cell.x, cell.y] = NormalizeCycleTime(CycleSensorEndAt(cell.x, cell.y) - AutomationCycleSensorMinWindow);
                }

                Log("Automation Cycle Sensor start set to " + CycleClockLabel(automationCycleSensorStart[cell.x, cell.y]) + ".");
            }

            overlayDirty = true;
            UpdateAutomationWires();
            UpdateHud();
        }

        private void AdjustInspectedAutomationTimerSensorTime(int direction)
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.AutomationTimerSensor)
            {
                return;
            }

            if (timerSensorEditingRed)
            {
                float redSeconds = Mathf.Clamp(
                    AutomationTimerRedSecondsAt(cell.x, cell.y) + AutomationTimerStepSeconds * direction,
                    AutomationTimerMinSeconds,
                    AutomationTimerMaxSeconds);
                automationTimerRedSeconds[cell.x, cell.y] = redSeconds;
                Log("Automation Timer Sensor red time set to " + redSeconds.ToString("0") + "s.");
            }
            else
            {
                float greenSeconds = Mathf.Clamp(
                    AutomationTimerGreenSecondsAt(cell.x, cell.y) + AutomationTimerStepSeconds * direction,
                    AutomationTimerMinSeconds,
                    AutomationTimerMaxSeconds);
                automationTimerGreenSeconds[cell.x, cell.y] = greenSeconds;
                Log("Automation Timer Sensor green time set to " + greenSeconds.ToString("0") + "s.");
            }

            automationTimerElapsedSeconds[cell.x, cell.y] = Mathf.Repeat(automationTimerElapsedSeconds[cell.x, cell.y], AutomationTimerCycleSecondsAt(cell.x, cell.y));
            overlayDirty = true;
            UpdateAutomationWires();
            UpdateHud();
        }

