        private void CycleInspectedContextFilter()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y))
            {
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.StorageBin)
            {
                CycleInspectedStorageFilter();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.Apothecary)
            {
                CycleInspectedMedicineStockMode();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.ConveyorLoader)
            {
                CycleInspectedConveyorLoaderFilter();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.ConveyorReceptacle)
            {
                CycleInspectedConveyorReceptacleFilter();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingRailSensor)
            {
                CycleInspectedShippingRailSensorFilter();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingRailMeter)
            {
                AdjustInspectedShippingRailMeterFlow(1);
                return;
            }

            if (IsAdjustableThresholdSensor(cells[cell.x, cell.y]))
            {
                AdjustInspectedThresholdSensor(1);
                return;
            }

            if (IsDirectionalBridge(cells[cell.x, cell.y]))
            {
                AdjustInspectedBridgeDirection(1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.SmartBattery)
            {
                AdjustInspectedSmartBatteryThreshold(1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidPipeSensor)
            {
                CycleInspectedLiquidSensorMode();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidFilter)
            {
                CycleInspectedLiquidFilterMode();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidValve || cells[cell.x, cell.y] == CellKind.GasValve)
            {
                AdjustInspectedConduitValveFlow(1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.GasPipeSensor)
            {
                CycleInspectedGasSensorMode();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.GasFilter)
            {
                CycleInspectedGasFilterMode();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationBufferGate)
            {
                AdjustInspectedAutomationBufferHold(1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationFilterGate)
            {
                AdjustInspectedAutomationFilterDelay(1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationCycleSensor)
            {
                AdjustInspectedAutomationCycleSensorTime(1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationTimerSensor)
            {
                AdjustInspectedAutomationTimerSensorTime(1);
            }
        }

        private void ToggleInspectedContextSecondary()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y))
            {
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.StorageBin)
            {
                ToggleInspectedStorageSweepOnly();
                return;
            }

            if (IsDoorAccessControlledKind(cells[cell.x, cell.y]))
            {
                ToggleInspectedDoorAccess();
                return;
            }

            if (IsPersonalAssignableStation(cells[cell.x, cell.y]))
            {
                ToggleInspectedPersonalStationAssignment();
                return;
            }

            if (IsAdjustableThresholdSensor(cells[cell.x, cell.y]))
            {
                AdjustInspectedThresholdSensor(-1);
                return;
            }

            if (IsDirectionalBridge(cells[cell.x, cell.y]))
            {
                AdjustInspectedBridgeDirection(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.SmartBattery)
            {
                AdjustInspectedSmartBatteryThreshold(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidValve || cells[cell.x, cell.y] == CellKind.GasValve)
            {
                AdjustInspectedConduitValveFlow(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingRailMeter)
            {
                AdjustInspectedShippingRailMeterFlow(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationBufferGate)
            {
                AdjustInspectedAutomationBufferHold(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationFilterGate)
            {
                AdjustInspectedAutomationFilterDelay(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationCycleSensor)
            {
                AdjustInspectedAutomationCycleSensorTime(-1);
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationTimerSensor)
            {
                AdjustInspectedAutomationTimerSensorTime(-1);
            }
        }

        private void ToggleInspectedStorageSweepOnly()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return;
            }

            storageSweepOnly[cell.x, cell.y] = !storageSweepOnly[cell.x, cell.y];
            Log(storageSweepOnly[cell.x, cell.y] ? "Storage Bin accepts only manual Sweep deliveries." : "Storage Bin accepts automatic deliveries.");
            overlayDirty = true;
            UpdateHud();
        }

        private void ToggleInspectedPersonalStationAssignment()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || !IsPersonalAssignableStation(cells[cell.x, cell.y]))
            {
                return;
            }

            string current = PersonalStationAssignedWorkerName(cell);
            string next = string.Empty;
            if (workers.Count > 0)
            {
                int nextIndex = 0;
                if (!string.IsNullOrEmpty(current))
                {
                    int currentIndex = workers.FindIndex(worker => worker != null && worker.Name == current);
                    nextIndex = currentIndex < 0 ? 0 : currentIndex + 1;
                }

                if (nextIndex < workers.Count)
                {
                    next = workers[nextIndex].Name;
                }
            }

            SetPersonalStationAssignedWorkerName(cell, next);
            ClearPersonalStationReservationJobs(cell);
            string label = cells[cell.x, cell.y] == CellKind.MessTable ? "Mess Table" : cells[cell.x, cell.y] == CellKind.MedicalCot ? "Medical Cot" : "Bed";
            Log(string.IsNullOrEmpty(next) ? label + " assignment cleared." : label + " assigned to " + next + ".");
            overlayDirty = true;
            UpdateHud();
        }

        private void ClearPersonalStationReservationJobs(Vector2Int cell)
        {
            for (int i = jobs.Count - 1; i >= 0; i--)
            {
                Job job = jobs[i];
                if (job == null ||
                    job.Cell != cell ||
                    (job.Type != JobType.Sleep && job.Type != JobType.Eat && job.Type != JobType.Treat && job.Type != JobType.MedicalRest))
                {
                    continue;
                }

                if (job.AssignedWorker != null)
                {
                    ClearAssignment(job.AssignedWorker);
                }

                jobs.RemoveAt(i);
            }
        }

        private void EmptyInspectedStorageBin()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return;
            }

            float available = StorageBinEmptyableResourceAmount(cell);
            if (available <= 0.05f)
            {
                Log("Storage Bin empty blocked: no stored resources match filter.");
                UpdateHud();
                return;
            }

            if (!HasStorageBinDropSpace(cell))
            {
                Log("Storage Bin empty blocked: no adjacent drop space.");
                UpdateHud();
                return;
            }

            float target = Mathf.Min(StorageBinCapacityAt(cell.x, cell.y), available);
            float emptied = EmptyStorageBinAt(cell);
            if (emptied <= 0.05f)
            {
                Log("Storage Bin empty blocked: no adjacent drop space.");
                UpdateHud();
                return;
            }

            Log("Storage Bin emptied " +
                emptied.ToString("0.#") +
                (emptied + 0.05f < target ? " kg matching resources. Nearby space filled." : " kg matching resources."));
            terrainDirty = true;
            overlayDirty = true;
            UpdateHud();
        }

        private float EmptyStorageBinAt(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return 0f;
            }

            float remaining = StorageBinCapacityAt(cell.x, cell.y);
            float dropped = 0f;
            foreach (LooseResourceKind kind in StorageBinEmptyResourceOrder())
            {
                if (!StorageBinEmptyFilterAccepts(cell, kind))
                {
                    continue;
                }

                dropped += DropStoredStorageResource(cell, kind, remaining - dropped);
                if (remaining - dropped <= 0.05f)
                {
                    break;
                }
            }

            return dropped;
        }

        private float DropStoredStorageResource(Vector2Int origin, LooseResourceKind kind, float amountLimit)
        {
            float dropped = 0f;
            while (amountLimit - dropped > 0.05f && StoredDryResourceAmount(kind) > 0.05f)
            {
                if (!TryFindLooseResourceDropCell(origin, kind, out Vector2Int dropCell))
                {
                    break;
                }

                float existing = looseResourceKind[dropCell.x, dropCell.y] == kind ? looseResourceAmount[dropCell.x, dropCell.y] : 0f;
                float freeSpace = Mathf.Max(0f, 80f - existing);
                if (freeSpace <= 0.05f)
                {
                    break;
                }

                float chunk = Mathf.Min(amountLimit - dropped, Mathf.Min(freeSpace, StoredDryResourceAmount(kind)));
                float removed = RemoveStoredDryResource(kind, chunk);
                if (removed <= 0.05f)
                {
                    break;
                }

                if (looseResourceKind[dropCell.x, dropCell.y] != kind)
                {
                    looseResourceKind[dropCell.x, dropCell.y] = kind;
                    looseResourceAmount[dropCell.x, dropCell.y] = 0f;
                }

                looseResourceAmount[dropCell.x, dropCell.y] = Mathf.Min(80f, looseResourceAmount[dropCell.x, dropCell.y] + removed);
                if (kind != LooseResourceKind.HatchEgg)
                {
                    hatchEggAge[dropCell.x, dropCell.y] = 0f;
                }

                dropped += removed;
            }

            return dropped;
        }

        private bool HasStorageBinDropSpace(Vector2Int cell)
        {
            foreach (LooseResourceKind kind in StorageBinEmptyResourceOrder())
            {
                if (StorageBinEmptyFilterAccepts(cell, kind) &&
                    StoredDryResourceAmount(kind) > 0.05f &&
                    HasLooseResourceDropSpace(cell, kind))
                {
                    return true;
                }
            }

            return false;
        }

        private bool HasLooseResourceDropSpace(Vector2Int origin, LooseResourceKind kind)
        {
            return TryFindLooseResourceDropCell(origin, kind, out Vector2Int dropCell) &&
                (looseResourceKind[dropCell.x, dropCell.y] == LooseResourceKind.None || looseResourceKind[dropCell.x, dropCell.y] == kind) &&
                looseResourceAmount[dropCell.x, dropCell.y] < 80f;
        }

        private float StorageBinEmptyableResourceAmount(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return 0f;
            }

            float amount = 0f;
            foreach (LooseResourceKind kind in StorageBinEmptyResourceOrder())
            {
                if (StorageBinEmptyFilterAccepts(cell, kind))
                {
                    amount += StoredDryResourceAmount(kind);
                }
            }

            return amount;
        }

        private bool StorageBinEmptyFilterAccepts(Vector2Int cell, LooseResourceKind kind)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.StorageBin &&
                StorageFilterAcceptsResource(storageBinFilter[cell.x, cell.y], kind);
        }

        private LooseResourceKind[] StorageBinEmptyResourceOrder()
        {
            return new[]
            {
                LooseResourceKind.Dirt,
                LooseResourceKind.Metal,
                LooseResourceKind.Algae,
                LooseResourceKind.Coal,
                LooseResourceKind.RefinedMetal,
                LooseResourceKind.PollutedDirt,
                LooseResourceKind.HatchEgg,
                LooseResourceKind.Slime,
                LooseResourceKind.BleachStone,
                LooseResourceKind.Plastic,
                LooseResourceKind.Peppernut,
                LooseResourceKind.Lumber,
                LooseResourceKind.ReedFiber,
                LooseResourceKind.Sulfur,
                LooseResourceKind.Steel,
                LooseResourceKind.Ceramic,
                LooseResourceKind.Glass,
                LooseResourceKind.Niobium,
                LooseResourceKind.Thermium,
                LooseResourceKind.Fullerene,
                LooseResourceKind.SuperCoolant,
                LooseResourceKind.CryogenicPropellant
            };
        }

        private void EmptyInspectedPipeContents()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || (!liquidPipe[cell.x, cell.y] && !gasPipe[cell.x, cell.y]))
            {
                return;
            }

            float liquidBefore = liquidPipe[cell.x, cell.y] ? LiquidPipeTotal(cell.x, cell.y) : 0f;
            float gasBefore = gasPipe[cell.x, cell.y] ? GasPipeTotal(cell.x, cell.y) : 0f;
            if (liquidBefore <= 0.001f && gasBefore <= 0.001f)
            {
                Log("Pipe empty idle: selected pipe has no contents.");
                UpdateHud();
                return;
            }

            float liquidEmptied = EmptyLiquidPipeContentsAt(cell);
            float gasEmptied = EmptyGasPipeContentsAt(cell);
            if (liquidEmptied <= 0.001f && gasEmptied <= 0.001f)
            {
                if (liquidBefore > 0.001f && gasBefore > 0.001f)
                {
                    Log("Pipe empty blocked: no liquid spill or gas release space.");
                }
                else
                {
                    Log(liquidBefore > 0.001f
                        ? "Pipe empty blocked: no liquid spill space."
                        : "Pipe empty blocked: no gas release space.");
                }

                UpdateHud();
                return;
            }

            string summary = PipeEmptyAmountSummary(liquidEmptied, gasEmptied);
            bool partial = liquidEmptied + 0.001f < liquidBefore || gasEmptied + 0.001f < gasBefore;
            Log("Pipe emptied " + summary + (partial ? ". Nearby space filled." : "."));
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            UpdateHud();
        }

        private float EmptyLiquidPipeContentsAt(Vector2Int pipe)
        {
            if (!IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            float total = LiquidPipeTotal(pipe.x, pipe.y);
            if (total <= 0.001f || !TryFindPipeLiquidOutput(pipe, out Vector2Int output))
            {
                return 0f;
            }

            float amount = Mathf.Min(total, LiquidFreeCapacity(output.x, output.y));
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float cleanGermLevel = pipeWaterGerms[pipe.x, pipe.y];
            float pollutedGermLevel = pipePollutedWaterGerms[pipe.x, pipe.y];
            float cleanAmount = Mathf.Min(pipeWater[pipe.x, pipe.y], amount * pipeWater[pipe.x, pipe.y] / Mathf.Max(0.001f, total));
            float pollutedAmount = Mathf.Min(pipePollutedWater[pipe.x, pipe.y], amount * pipePollutedWater[pipe.x, pipe.y] / Mathf.Max(0.001f, total));
            float petroleumAmount = Mathf.Min(pipePetroleum[pipe.x, pipe.y], amount - cleanAmount - pollutedAmount);
            pipeWater[pipe.x, pipe.y] = Mathf.Max(0f, pipeWater[pipe.x, pipe.y] - cleanAmount);
            if (pipeWater[pipe.x, pipe.y] <= 0.001f)
            {
                pipeWaterGerms[pipe.x, pipe.y] = 0f;
            }

            pipePollutedWater[pipe.x, pipe.y] = Mathf.Max(0f, pipePollutedWater[pipe.x, pipe.y] - pollutedAmount);
            if (pipePollutedWater[pipe.x, pipe.y] <= 0.001f)
            {
                pipePollutedWaterGerms[pipe.x, pipe.y] = 0f;
            }

            pipePetroleum[pipe.x, pipe.y] = Mathf.Max(0f, pipePetroleum[pipe.x, pipe.y] - petroleumAmount);
            ReleaseWaterToCell(output, cleanAmount, cleanGermLevel);
            ReleasePollutedWaterToCell(output, pollutedAmount, pollutedGermLevel);
            ReleasePetroleumToCell(output, petroleumAmount);
            return cleanAmount + pollutedAmount + petroleumAmount;
        }

        private float EmptyGasPipeContentsAt(Vector2Int pipe)
        {
            if (!IsInside(pipe.x, pipe.y) || !gasPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            float total = GasPipeTotal(pipe.x, pipe.y);
            if (total <= 0.001f || !TryFindPipeGasOutput(pipe, out Vector2Int output))
            {
                return 0f;
            }

            float amount = Mathf.Min(total, Mathf.Max(0f, GasVentMaxPressure - TileGasTotal(output.x, output.y)));
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasPipeOxygen[pipe.x, pipe.y], amount * gasPipeOxygen[pipe.x, pipe.y] / total);
            float carbonAmount = Mathf.Min(gasPipeCarbonDioxide[pipe.x, pipe.y], amount * gasPipeCarbonDioxide[pipe.x, pipe.y] / total);
            float pollutedAmount = Mathf.Min(gasPipePollutedOxygen[pipe.x, pipe.y], amount * gasPipePollutedOxygen[pipe.x, pipe.y] / total);
            float hydrogenAmount = Mathf.Min(gasPipeHydrogen[pipe.x, pipe.y], amount * gasPipeHydrogen[pipe.x, pipe.y] / total);
            float steamAmount = Mathf.Min(gasPipeSteam[pipe.x, pipe.y], amount * gasPipeSteam[pipe.x, pipe.y] / total);
            float chlorineAmount = Mathf.Min(gasPipeChlorine[pipe.x, pipe.y], amount * gasPipeChlorine[pipe.x, pipe.y] / total);
            float naturalGasAmount = Mathf.Min(gasPipeNaturalGas[pipe.x, pipe.y], amount * gasPipeNaturalGas[pipe.x, pipe.y] / total);
            float sourGasAmount = Mathf.Min(gasPipeSourGas[pipe.x, pipe.y], Mathf.Max(0f, amount - oxygenAmount - carbonAmount - pollutedAmount - hydrogenAmount - steamAmount - chlorineAmount - naturalGasAmount));
            AddGasToTileWithSteam(output.x, output.y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, gasPipeGerms[pipe.x, pipe.y], temperature[pipe.x, pipe.y], sourGasAmount);
            gasPipeOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeOxygen[pipe.x, pipe.y] - oxygenAmount);
            gasPipeCarbonDioxide[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeCarbonDioxide[pipe.x, pipe.y] - carbonAmount);
            gasPipePollutedOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipePollutedOxygen[pipe.x, pipe.y] - pollutedAmount);
            gasPipeHydrogen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeHydrogen[pipe.x, pipe.y] - hydrogenAmount);
            gasPipeSteam[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSteam[pipe.x, pipe.y] - steamAmount);
            gasPipeChlorine[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeChlorine[pipe.x, pipe.y] - chlorineAmount);
            gasPipeNaturalGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeNaturalGas[pipe.x, pipe.y] - naturalGasAmount);
            gasPipeSourGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSourGas[pipe.x, pipe.y] - sourGasAmount);
            ClearGasPipeGermsIfEmpty(pipe.x, pipe.y);
            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private bool TryFindPipeGasOutput(Vector2Int pipe, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                pipe,
                new Vector2Int(pipe.x, pipe.y + 1),
                new Vector2Int(pipe.x + 1, pipe.y),
                new Vector2Int(pipe.x - 1, pipe.y),
                new Vector2Int(pipe.x, pipe.y - 1)
            };

            float bestPressure = float.MaxValue;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !IsPassable(candidate.x, candidate.y))
                {
                    continue;
                }

                float pressure = TileGasTotal(candidate.x, candidate.y);
                if (pressure >= GasVentMaxPressure - 0.02f || pressure >= bestPressure)
                {
                    continue;
                }

                bestPressure = pressure;
                output = candidate;
            }

            return output.x >= 0;
        }

        private string PipeEmptyAmountSummary(float liquidAmount, float gasAmount)
        {
            if (liquidAmount > 0.001f && gasAmount > 0.001f)
            {
                return liquidAmount.ToString("0.0") + " kg liquid and " + gasAmount.ToString("0.00") + " kg gas";
            }

            if (liquidAmount > 0.001f)
            {
                return liquidAmount.ToString("0.0") + " kg liquid";
            }

            return gasAmount.ToString("0.00") + " kg gas";
        }

        private void EmptyInspectedReservoirContents()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || (cells[cell.x, cell.y] != CellKind.LiquidReservoir && cells[cell.x, cell.y] != CellKind.GasReservoir))
            {
                return;
            }

            bool liquidReservoir = cells[cell.x, cell.y] == CellKind.LiquidReservoir;
            float liquidBefore = liquidReservoir ? LiquidReservoirTotal(cell.x, cell.y) : 0f;
            float gasBefore = !liquidReservoir ? GasReservoirTotal(cell.x, cell.y) : 0f;
            if (liquidBefore <= 0.001f && gasBefore <= 0.001f)
            {
                Log("Reservoir empty idle: selected reservoir has no contents.");
                UpdateHud();
                return;
            }

            float liquidEmptied = liquidReservoir ? EmptyLiquidReservoirContentsAt(cell) : 0f;
            float gasEmptied = liquidReservoir ? 0f : EmptyGasReservoirContentsAt(cell);
            if (liquidEmptied <= 0.001f && gasEmptied <= 0.001f)
            {
                Log(liquidReservoir
                    ? "Reservoir empty blocked: no liquid spill space."
                    : "Reservoir empty blocked: no gas release space.");
                UpdateHud();
                return;
            }

            string summary = PipeEmptyAmountSummary(liquidEmptied, gasEmptied);
            bool partial = liquidEmptied + 0.001f < liquidBefore || gasEmptied + 0.001f < gasBefore;
            Log("Reservoir emptied " + summary + (partial ? ". Nearby space filled." : "."));
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            UpdateHud();
        }

        private float EmptyLiquidReservoirContentsAt(Vector2Int reservoir)
        {
            if (!IsInside(reservoir.x, reservoir.y) || cells[reservoir.x, reservoir.y] != CellKind.LiquidReservoir)
            {
                return 0f;
            }

            float total = LiquidReservoirTotal(reservoir.x, reservoir.y);
            if (total <= 0.001f || !TryFindPipeLiquidOutput(reservoir, out Vector2Int output))
            {
                return 0f;
            }

            float amount = Mathf.Min(total, LiquidFreeCapacity(output.x, output.y));
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float cleanGermLevel = liquidReservoirWaterGerms[reservoir.x, reservoir.y];
            float pollutedGermLevel = liquidReservoirPollutedWaterGerms[reservoir.x, reservoir.y];
            float cleanAmount = Mathf.Min(liquidReservoirWater[reservoir.x, reservoir.y], amount * liquidReservoirWater[reservoir.x, reservoir.y] / Mathf.Max(0.001f, total));
            float pollutedAmount = Mathf.Min(liquidReservoirPollutedWater[reservoir.x, reservoir.y], amount * liquidReservoirPollutedWater[reservoir.x, reservoir.y] / Mathf.Max(0.001f, total));
            float petroleumAmount = Mathf.Min(liquidReservoirPetroleum[reservoir.x, reservoir.y], Mathf.Max(0f, amount - cleanAmount - pollutedAmount));
            liquidReservoirWater[reservoir.x, reservoir.y] = Mathf.Max(0f, liquidReservoirWater[reservoir.x, reservoir.y] - cleanAmount);
            if (liquidReservoirWater[reservoir.x, reservoir.y] <= 0.001f)
            {
                liquidReservoirWaterGerms[reservoir.x, reservoir.y] = 0f;
            }

            liquidReservoirPollutedWater[reservoir.x, reservoir.y] = Mathf.Max(0f, liquidReservoirPollutedWater[reservoir.x, reservoir.y] - pollutedAmount);
            if (liquidReservoirPollutedWater[reservoir.x, reservoir.y] <= 0.001f)
            {
                liquidReservoirPollutedWaterGerms[reservoir.x, reservoir.y] = 0f;
            }

            liquidReservoirPetroleum[reservoir.x, reservoir.y] = Mathf.Max(0f, liquidReservoirPetroleum[reservoir.x, reservoir.y] - petroleumAmount);
            ReleaseWaterToCell(output, cleanAmount, cleanGermLevel);
            ReleasePollutedWaterToCell(output, pollutedAmount, pollutedGermLevel);
            ReleasePetroleumToCell(output, petroleumAmount);
            return cleanAmount + pollutedAmount + petroleumAmount;
        }

        private float EmptyGasReservoirContentsAt(Vector2Int reservoir)
        {
            if (!IsInside(reservoir.x, reservoir.y) || cells[reservoir.x, reservoir.y] != CellKind.GasReservoir)
            {
                return 0f;
            }

            float total = GasReservoirTotal(reservoir.x, reservoir.y);
            if (total <= 0.001f || !TryFindPipeGasOutput(reservoir, out Vector2Int output))
            {
                return 0f;
            }

            float amount = Mathf.Min(total, Mathf.Max(0f, GasVentMaxPressure - TileGasTotal(output.x, output.y)));
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasReservoirOxygen[reservoir.x, reservoir.y], amount * gasReservoirOxygen[reservoir.x, reservoir.y] / total);
            float carbonAmount = Mathf.Min(gasReservoirCarbonDioxide[reservoir.x, reservoir.y], amount * gasReservoirCarbonDioxide[reservoir.x, reservoir.y] / total);
            float pollutedAmount = Mathf.Min(gasReservoirPollutedOxygen[reservoir.x, reservoir.y], amount * gasReservoirPollutedOxygen[reservoir.x, reservoir.y] / total);
            float hydrogenAmount = Mathf.Min(gasReservoirHydrogen[reservoir.x, reservoir.y], amount * gasReservoirHydrogen[reservoir.x, reservoir.y] / total);
            float steamAmount = Mathf.Min(gasReservoirSteam[reservoir.x, reservoir.y], amount * gasReservoirSteam[reservoir.x, reservoir.y] / total);
            float chlorineAmount = Mathf.Min(gasReservoirChlorine[reservoir.x, reservoir.y], amount * gasReservoirChlorine[reservoir.x, reservoir.y] / total);
            float naturalGasAmount = Mathf.Min(gasReservoirNaturalGas[reservoir.x, reservoir.y], amount * gasReservoirNaturalGas[reservoir.x, reservoir.y] / total);
            float sourGasAmount = Mathf.Min(gasReservoirSourGas[reservoir.x, reservoir.y], Mathf.Max(0f, amount - oxygenAmount - carbonAmount - pollutedAmount - hydrogenAmount - steamAmount - chlorineAmount - naturalGasAmount));
            AddGasToTileWithSteam(output.x, output.y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, gasReservoirGerms[reservoir.x, reservoir.y], temperature[reservoir.x, reservoir.y], sourGasAmount);
            gasReservoirOxygen[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirOxygen[reservoir.x, reservoir.y] - oxygenAmount);
            gasReservoirCarbonDioxide[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirCarbonDioxide[reservoir.x, reservoir.y] - carbonAmount);
            gasReservoirPollutedOxygen[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirPollutedOxygen[reservoir.x, reservoir.y] - pollutedAmount);
            gasReservoirHydrogen[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirHydrogen[reservoir.x, reservoir.y] - hydrogenAmount);
            gasReservoirSteam[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirSteam[reservoir.x, reservoir.y] - steamAmount);
            gasReservoirChlorine[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirChlorine[reservoir.x, reservoir.y] - chlorineAmount);
            gasReservoirNaturalGas[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirNaturalGas[reservoir.x, reservoir.y] - naturalGasAmount);
            gasReservoirSourGas[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirSourGas[reservoir.x, reservoir.y] - sourGasAmount);
            ClearGasReservoirGermsIfEmpty(reservoir.x, reservoir.y);
            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private void DropInspectedShippingRailPacket()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int rail = inspectedCell.Value;
            if (!IsInside(rail.x, rail.y) || !shippingRail[rail.x, rail.y])
            {
                return;
            }

            if (shippingRailKind[rail.x, rail.y] == LooseResourceKind.None || shippingRailAmount[rail.x, rail.y] <= 0.001f)
            {
                Log("Rail drop idle: selected rail has no packet.");
                UpdateHud();
                return;
            }

            if (!TryFindLooseResourceDropCell(rail, shippingRailKind[rail.x, rail.y], out _))
            {
                Log("Rail drop blocked: no adjacent loose-resource drop space.");
                UpdateHud();
                return;
            }

            LooseResourceKind kind = shippingRailKind[rail.x, rail.y];
            float target = shippingRailAmount[rail.x, rail.y];
            float dropped = DropShippingRailPacketAt(rail);
            if (dropped <= 0.001f)
            {
                Log("Rail drop blocked: no adjacent loose-resource drop space.");
                UpdateHud();
                return;
            }

            Log("Rail dropped " + dropped.ToString("0.#") + " kg " + LooseResourceLabel(kind) + (dropped + 0.001f < target ? ". Nearby space filled." : "."));
            terrainDirty = true;
            overlayDirty = true;
            UpdateHud();
        }

        private float DropShippingRailPacketAt(Vector2Int rail)
        {
            if (!IsInside(rail.x, rail.y) ||
                !shippingRail[rail.x, rail.y] ||
                shippingRailKind[rail.x, rail.y] == LooseResourceKind.None ||
                shippingRailAmount[rail.x, rail.y] <= 0.001f)
            {
                return 0f;
            }

            float dropped = DropLooseResourceNear(rail, shippingRailKind[rail.x, rail.y], shippingRailAmount[rail.x, rail.y]);
            if (dropped <= 0.001f)
            {
                return 0f;
            }

            shippingRailAmount[rail.x, rail.y] = Mathf.Max(0f, shippingRailAmount[rail.x, rail.y] - dropped);
            if (shippingRailAmount[rail.x, rail.y] <= 0.001f)
            {
                shippingRailAmount[rail.x, rail.y] = 0f;
                shippingRailKind[rail.x, rail.y] = LooseResourceKind.None;
            }

            return dropped;
        }

        private void ToggleInspectedDoorAccess()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || !IsDoorAccessControlledKind(cells[cell.x, cell.y]))
            {
                return;
            }

            if (!CanUseDoorAccessControl(cell))
            {
                Log("Door access blocked: repair the Mechanized Airlock before changing permissions.");
                UpdateHud();
                return;
            }

            doorAccessMode[cell.x, cell.y] = NextDoorAccessMode(DoorAccessModeAt(cell.x, cell.y));
            doorAccessChanges++;
            milestoneDoorAccess |= AnyRestrictedDoorAccess();
            foreach (Worker worker in workers)
            {
                if (worker.AssignedJob != null)
                {
                    ClearAssignment(worker);
                }
            }

            overlayDirty = true;
            Log(CellLabel(cells[cell.x, cell.y]) + " access set to " + DoorAccessModeName(doorAccessMode[cell.x, cell.y]) + ".");
            UpdateHud();
        }

        private void ToggleInspectedSignalContext()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y))
            {
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.StorageBin)
            {
                EmptyInspectedStorageBin();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.SignalSwitch)
            {
                ToggleSignalSwitch(cell, true);
                return;
            }

            if (IsAdjustableThresholdSensor(cells[cell.x, cell.y]))
            {
                ToggleInspectedThresholdSensorCondition();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.SmartBattery)
            {
                smartBatteryEditingHigh = !smartBatteryEditingHigh;
                Log(smartBatteryEditingHigh ? "Smart Battery editing high threshold." : "Smart Battery editing low threshold.");
                UpdateHud();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationCycleSensor)
            {
                cycleSensorEditingEnd = !cycleSensorEditingEnd;
                Log(cycleSensorEditingEnd ? "Automation Cycle Sensor editing end time." : "Automation Cycle Sensor editing start time.");
                UpdateHud();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationTimerSensor)
            {
                timerSensorEditingRed = !timerSensorEditingRed;
                Log(timerSensorEditingRed ? "Automation Timer Sensor editing red time." : "Automation Timer Sensor editing green time.");
                UpdateHud();
                return;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidReservoir || cells[cell.x, cell.y] == CellKind.GasReservoir)
            {
                EmptyInspectedReservoirContents();
                return;
            }

            if (liquidPipe[cell.x, cell.y] || gasPipe[cell.x, cell.y])
            {
                EmptyInspectedPipeContents();
                return;
            }

            if (shippingRail[cell.x, cell.y])
            {
                DropInspectedShippingRailPacket();
            }
        }

        private void ToggleInspectedThresholdSensorCondition()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y) || !IsAdjustableThresholdSensor(cells[cell.x, cell.y]))
            {
                return;
            }

            ThresholdSensorCondition condition = ThresholdSensorConditionAt(cell.x, cell.y) == ThresholdSensorCondition.AboveOrEqual
                ? ThresholdSensorCondition.BelowOrEqual
                : ThresholdSensorCondition.AboveOrEqual;
            CellKind kind = cells[cell.x, cell.y];
            if (kind == CellKind.AtmoSensor)
            {
                atmoSensorCondition[cell.x, cell.y] = condition;
            }
            else if (kind == CellKind.ThermoSensor)
            {
                thermoSensorCondition[cell.x, cell.y] = condition;
            }
            else if (kind == CellKind.HydroSensor)
            {
                hydroSensorCondition[cell.x, cell.y] = condition;
            }
            else if (kind == CellKind.GermSensor)
            {
                germSensorCondition[cell.x, cell.y] = condition;
            }
            else if (kind == CellKind.WeightPlate)
            {
                weightPlateCondition[cell.x, cell.y] = condition;
            }
            else if (kind == CellKind.CritterSensor)
            {
                critterSensorCondition[cell.x, cell.y] = condition;
            }

            Log(ThresholdSensorLabel(kind) + " condition set to " + ThresholdSensorConditionName(condition) + ".");
            overlayDirty = true;
            UpdateAutomationWires();
            UpdateHud();
        }

        private void ToggleSignalSwitch(Vector2Int cell, bool countToggle)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.SignalSwitch)
            {
                return;
            }

            automationSwitchState[cell.x, cell.y] = !automationSwitchState[cell.x, cell.y];
            if (countToggle)
            {
                signalSwitchesToggled++;
            }

            UpdateAutomationWires();
            bool signalActive = SignalSwitchSignalActive(cell.x, cell.y);
            milestoneSignalSwitching |= techAutomationLogistics &&
                signalSwitchesToggled > 0 &&
                HasAutomationWireAccess(cell) &&
                signalActive;
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            Log("Signal Switch " + (signalActive
                ? "ON: green automation signal."
                : automationSwitchState[cell.x, cell.y] ? "ON: disabled or unlinked, no green automation signal." : "OFF: red automation signal."));
        }

        private void ToggleInspectedAirlock()
        {
            if (!inspectedCell.HasValue)
            {
                return;
            }

            ToggleAirlock(inspectedCell.Value, true);
        }

        private void ToggleAirlock(Vector2Int cell, bool countToggle)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.ManualAirlock)
            {
                return;
            }

            airlockOpen[cell.x, cell.y] = !airlockOpen[cell.x, cell.y];
            if (countToggle)
            {
                airlockToggles++;
            }

            if (!airlockOpen[cell.x, cell.y])
            {
                oxygen[cell.x, cell.y] = 0f;
                carbonDioxide[cell.x, cell.y] = 0f;
                pollutedOxygen[cell.x, cell.y] = 0f;
                hydrogen[cell.x, cell.y] = 0f;
                steam[cell.x, cell.y] = 0f;
                chlorine[cell.x, cell.y] = 0f;
                naturalGas[cell.x, cell.y] = 0f;
                sourGas[cell.x, cell.y] = 0f;
                germs[cell.x, cell.y] = 0f;
            }

            milestoneAirlockControl |= airlockToggles > 0 && CountPressureControlledClosedAirlocks() > 0;
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            InvalidateRooms();
            Log("Manual Airlock " + (airlockOpen[cell.x, cell.y] ? "opened: duplicants and gas can pass." : "closed: pathing and pressure are sealed."));
        }

        private void TogglePause()
        {
            paused = !paused;
            Log(paused ? "Simulation paused." : "Simulation resumed.");
        }

        private void ToggleRedAlert()
        {
            SetRedAlertActive(!redAlertActive, true);
        }

        private void ToggleFoodPolicy()
        {
            foodPolicyMode = foodPolicyMode == FoodPolicyMode.Safe ? FoodPolicyMode.All : FoodPolicyMode.Safe;
            Log(foodPolicyMode == FoodPolicyMode.Safe
                ? "Food policy set to SAFE: stale or contaminated meals are blocked unless starvation is critical."
                : "Food policy set to ALL: duplicants may eat stale or contaminated meals.");
            InvalidateJobPolicyUi();
            RefreshFoodPolicyButtonLabel();
            UpdateHud();
        }

        private void ToggleMedicalLeavePolicy()
        {
            medicalLeavePolicyActive = !medicalLeavePolicyActive;
            Log(medicalLeavePolicyActive
                ? "Medical leave enabled: sick duplicants avoid routine errands until vitals recover."
                : "Medical leave disabled: sick duplicants may take routine errands.");
            InvalidateJobPolicyUi();
            RefreshMedicalLeaveButtonLabel();
            UpdateHud();
        }

        private void SetRedAlertActive(bool active, bool announce)
        {
            if (redAlertActive == active)
            {
                RefreshRedAlertButtonLabel();
                return;
            }

            redAlertActive = active;
            if (active)
            {
                redAlertToggles++;
                paused = false;
            }

            if (announce)
            {
                Log(active
                    ? "Red Alert active: duplicants ignore routine downtime for urgent errands."
                    : "Red Alert cleared: duplicants return to normal schedules.");
            }

            InvalidateJobPolicyUi();
            RefreshRedAlertButtonLabel();
            UpdateHud();
        }

        private void ContinueFreeplay()
        {
            if (colonyVictory && !colonyFailed)
            {
                colonyVictoryAcknowledged = true;
                paused = false;
                Log("Freeplay continues.");
                SetVisible(endStatePanel, false);
            }
        }

        private void CycleSpeed()
        {
            if (paused)
            {
                paused = false;
                simulationSpeed = 1f;
            }
            else if (simulationSpeed < 2f)
            {
                simulationSpeed = 2f;
            }
            else if (simulationSpeed < 4f)
            {
                simulationSpeed = 4f;
            }
            else
            {
                simulationSpeed = 1f;
            }

            Log("Simulation speed x" + simulationSpeed.ToString("0"));
        }

        private void QueueDig(Vector2Int cell)
        {
            if (!IsNaturalSolid(cells[cell.x, cell.y]))
            {
                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            Job job = new Job(JobType.Dig, cell, DigWorkRequired(cells[cell.x, cell.y]))
            {
                Priority = 5
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Dig queued at " + cell.x + ", " + cell.y + ".");
        }

        private void QueueMop(Vector2Int cell)
        {
            if (!IsMoppableSpill(cell))
            {
                if (IsInside(cell.x, cell.y) && IsWorldLiquidCell(cells[cell.x, cell.y]) && waterMass[cell.x, cell.y] > MoppableSpillMaxMass)
                {
                    Log("Mop only targets shallow spills under " + MoppableSpillMaxMass.ToString("0") + " kg. Use a pump for deeper water.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            Job job = new Job(JobType.Mop, cell, MopWorkRequired(cell))
            {
                Priority = 6
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Mop queued at " + cell.x + ", " + cell.y + ".");
        }

        private bool IsMoppableSpill(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                (IsWorldLiquidCell(cells[cell.x, cell.y]) || IsFloodableCellKind(cells[cell.x, cell.y])) &&
                waterMass[cell.x, cell.y] > 0.5f &&
                waterMass[cell.x, cell.y] <= MoppableSpillMaxMass &&
                HasAdjacentPassableCell(cell);
        }

        private bool HasAdjacentPassableCell(Vector2Int cell)
        {
            return (IsInside(cell.x + 1, cell.y) && IsPassable(cell.x + 1, cell.y)) ||
                (IsInside(cell.x - 1, cell.y) && IsPassable(cell.x - 1, cell.y)) ||
                (IsInside(cell.x, cell.y + 1) && IsPassable(cell.x, cell.y + 1)) ||
                (IsInside(cell.x, cell.y - 1) && IsPassable(cell.x, cell.y - 1));
        }

        private float MopWorkRequired(Vector2Int cell)
        {
            float mass = IsInside(cell.x, cell.y) ? Mathf.Max(0f, waterMass[cell.x, cell.y]) : 0f;
            float work = Mathf.Lerp(0.9f, 3.2f, Mathf.Clamp01(mass / MoppableSpillMaxMass));
            if (IsPollutedMopCell(cell))
            {
                work += 0.55f;
            }

            return work;
        }

        private bool IsPollutedMopCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                (cells[cell.x, cell.y] == CellKind.PollutedWater || germs[cell.x, cell.y] > 0.18f || pollutedOxygen[cell.x, cell.y] > 0.1f);
        }

        private void QueueDisinfect(Vector2Int cell)
        {
            if (!IsDisinfectableCell(cell))
            {
                if (IsInside(cell.x, cell.y) && IsPassable(cell.x, cell.y))
                {
                    Log("Disinfect targets germy passable tiles.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            Job job = new Job(JobType.Disinfect, cell, DisinfectWorkRequired(cell))
            {
                Priority = 6
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Disinfect queued at " + cell.x + ", " + cell.y + ".");
        }

        private bool IsDisinfectableCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsPassable(cell.x, cell.y) &&
                germs[cell.x, cell.y] >= DisinfectGermThreshold &&
                (IsCharacterStandableCell(cell) || HasAdjacentPassableCell(cell));
        }

        private float DisinfectWorkRequired(Vector2Int cell)
        {
            float germLevel = IsInside(cell.x, cell.y) ? germs[cell.x, cell.y] : 0f;
            return Mathf.Lerp(1.2f, 3.1f, Mathf.Clamp01(germLevel));
        }

        private void QueueSweep(Vector2Int cell)
        {
            if (!HasLooseResource(cell))
            {
                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            if (DryResourceFreeSpace() <= 0.01f)
            {
                Log("Dry storage is full. Build Storage Bins before sweeping.");
                return;
            }

            LooseResourceKind kind = looseResourceKind[cell.x, cell.y];
            if (!CanStoreLooseResource(kind, true))
            {
                Log("No Storage Bin accepts " + LooseResourceLabel(kind) + ". Change a storage filter or free matching storage.");
                return;
            }

            Job job = new Job(JobType.Sweep, cell, SweepWorkRequired(cell))
            {
                Priority = 4
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Sweep queued: " + LooseResourceLabel(kind) + ".");
        }

        private bool HasLooseResource(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                looseResourceKind[cell.x, cell.y] != LooseResourceKind.None &&
                looseResourceAmount[cell.x, cell.y] > 0.05f;
        }

        private float SweepWorkRequired(Vector2Int cell)
        {
            float amount = HasLooseResource(cell) ? looseResourceAmount[cell.x, cell.y] : 0f;
            return Mathf.Lerp(0.8f, 2.8f, Mathf.Clamp01(amount / 24f));
        }

        private void QueueHarvest(Vector2Int cell)
        {
            if (!IsCropCell(cell))
            {
                return;
            }

            if (plantGrowth[cell.x, cell.y] < 1f)
            {
                Log("Harvest only targets mature crops.");
                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            if (!CanHarvestCrop(cell))
            {
                Log("Dry storage is full. Free storage before harvesting this crop.");
                return;
            }

            Job job = new Job(JobType.Harvest, cell, 2f)
            {
                Priority = food < workers.Count * 1500f ? 7 : 4
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Harvest queued: " + CropDisplayName(cells[cell.x, cell.y]) + ".");
        }

        private void QueueWrangleCritter(Vector2Int cell)
        {
            HatchCritter critter = HatchAt(cell);
            if (critter == null)
            {
                Log("Wrangle only targets critters.");
                return;
            }

            if (IsCritterSettledInStable(critter))
            {
                Log(CritterKindName(critter.Kind) + " " + critter.Name + " is already in a Stable.");
                return;
            }

            if (FindWrangleJobForCritter(critter) != null)
            {
                return;
            }

            if (FindButcherJobForCritter(critter) != null)
            {
                Log("Wrangle blocked: critter is already marked for butcher.");
                return;
            }

            if (!TryFindWrangleDestination(critter, out _))
            {
                Log("Wrangle blocked: no Stable has a valid destination cell.");
                return;
            }

            Job existingJob = FindAnyJobAt(critter.Cell);
            if (existingJob != null)
            {
                Log("Another errand is already queued on that critter cell.");
                return;
            }

            Job job = new Job(JobType.WrangleCritter, critter.Cell, CritterWrangleWorkRequired)
            {
                TargetCritterName = critter.Name,
                Priority = 6
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Wrangle queued: " + CritterKindName(critter.Kind) + " " + critter.Name + ".");
        }

        private void QueueButcherCritter(Vector2Int cell)
        {
            HatchCritter critter = HatchAt(cell);
            if (critter == null)
            {
                Log("Butcher only targets critters.");
                return;
            }

            if (FindButcherJobForCritter(critter) != null)
            {
                return;
            }

            Job existingJob = FindAnyJobAt(critter.Cell);
            if (existingJob != null)
            {
                Log("Another errand is already queued on that critter cell.");
                return;
            }

            Job job = new Job(JobType.ButcherCritter, critter.Cell, CritterButcherWorkRequired)
            {
                TargetCritterName = critter.Name,
                Priority = food < workers.Count * 1000f ? 8 : 5
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Butcher queued: " + CritterKindName(critter.Kind) + " " + critter.Name + ".");
        }

        private void QueueRepair(Vector2Int cell)
        {
            if (!NeedsRepair(cell))
            {
                if (IsInside(cell.x, cell.y) && IsRepairableEquipment(cells[cell.x, cell.y]))
                {
                    Log(CellLabel(cells[cell.x, cell.y]) + " does not need repair.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            if (metal < RepairMetalCost)
            {
                Log("Not enough metal to repair " + CellLabel(cells[cell.x, cell.y]) + ".");
                return;
            }

            Job job = new Job(JobType.Repair, cell, RepairWorkRequired(cell))
            {
                BuildKind = cells[cell.x, cell.y],
                Priority = IsBrokenEquipment(cell) ? 8 : 5
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Repair queued: " + CellLabel(job.BuildKind) + ".");
        }

        private bool NeedsRepair(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsRepairableEquipment(cells[cell.x, cell.y]) &&
                equipmentCondition[cell.x, cell.y] < 0.995f;
        }

        private bool NeedsAutoRepair(Vector2Int cell)
        {
            return NeedsRepair(cell) &&
                (IsBrokenEquipment(cell) || equipmentCondition[cell.x, cell.y] <= EquipmentAutoRepairThreshold);
        }

        private float RepairWorkRequired(Vector2Int cell)
        {
            float missing = IsInside(cell.x, cell.y) ? 1f - Mathf.Clamp01(equipmentCondition[cell.x, cell.y]) : 1f;
            return Mathf.Lerp(1.2f, 4.6f, missing) + (IsBrokenEquipment(cell) ? 0.8f : 0f);
        }

        private void QueueBuild(Vector2Int cell, CommandMode mode)
        {
            if (mode == CommandMode.PowerWire || mode == CommandMode.ConductiveWire || mode == CommandMode.HeavyWattWire)
            {
                QueuePowerWire(cell, PowerWireKindForMode(mode));
                return;
            }

            if (mode == CommandMode.AutomationWire)
            {
                QueueAutomationWire(cell);
                return;
            }

            if (mode == CommandMode.LiquidPipe ||
                mode == CommandMode.RadiantLiquidPipe ||
                mode == CommandMode.InsulatedLiquidPipe)
            {
                QueueLiquidPipe(cell, LiquidPipeKindForMode(mode));
                return;
            }

            if (mode == CommandMode.GasPipe ||
                mode == CommandMode.RadiantGasPipe ||
                mode == CommandMode.InsulatedGasPipe)
            {
                QueueGasPipe(cell, GasPipeKindForMode(mode));
                return;
            }

            if (mode == CommandMode.ShippingRail)
            {
                QueueShippingRail(cell);
                return;
            }

            BuildSpec spec = BuildSpecForMode(mode);
            if (spec.Kind == CellKind.Empty)
            {
                return;
            }

            if (!IsBuildUnlocked(spec.Kind, true))
            {
                return;
            }

            if (!CanPlaceBuild(cell, spec.Kind))
            {
                if (spec.Kind == CellKind.WaterPump)
                {
                    Log("Water Pump must be built beside a liquid tile.");
                }
                else if (RequiresFloorSupport(spec.Kind))
                {
                    Log(spec.Label + " needs floor support.");
                }
                else if (RequiresCeilingSupport(spec.Kind))
                {
                    Log(spec.Label + " needs ceiling support.");
                }
                else if (spec.Kind == CellKind.PowerShutoff)
                {
                    Log(spec.Label + " must be built on an existing Power Wire.");
                }
                else if (spec.Kind == CellKind.LiquidPipeSensor || spec.Kind == CellKind.LiquidShutoff || spec.Kind == CellKind.LiquidValve)
                {
                    Log(spec.Label + " must be built on an existing Liquid Pipe.");
                }
                else if (spec.Kind == CellKind.GasPipeSensor || spec.Kind == CellKind.GasShutoff || spec.Kind == CellKind.GasValve)
                {
                    Log(spec.Label + " must be built on an existing Gas Pipe.");
                }
                else if (spec.Kind == CellKind.ShippingRailSensor || spec.Kind == CellKind.ShippingRailShutoff || spec.Kind == CellKind.ShippingRailMeter)
                {
                    Log(spec.Label + " must be built on an existing Shipping Rail.");
                }
                else if (spec.Kind == CellKind.LiquidBridge || spec.Kind == CellKind.GasBridge || spec.Kind == CellKind.ShippingBridge || spec.Kind == CellKind.AutomationBridge || spec.Kind == CellKind.AutomationNotGate || spec.Kind == CellKind.AutomationAndGate || spec.Kind == CellKind.AutomationOrGate || spec.Kind == CellKind.AutomationXorGate || spec.Kind == CellKind.AutomationBufferGate || spec.Kind == CellKind.AutomationFilterGate || spec.Kind == CellKind.AutomationMemoryGate || spec.Kind == CellKind.PowerBridge)
                {
                    Log(spec.Label + " needs an empty tile between conduit endpoints.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            if (!SpendCost(spec))
            {
                Log(BuildCostFailureText(spec));
                return;
            }

            Job job = new Job(JobType.Build, cell, spec.Work)
            {
                BuildKind = spec.Kind,
                DirtCost = spec.Dirt,
                MetalCost = spec.Metal,
                AlgaeCost = spec.Algae,
                RefinedMetalCost = spec.RefinedMetal,
                Priority = 5
            };
            jobs.Add(job);
            overlayDirty = true;
            Log(spec.Label + " build queued.");
        }

        private void QueuePowerWire(Vector2Int cell)
        {
            QueuePowerWire(cell, PowerWireKind.Normal);
        }

        private void QueuePowerWire(Vector2Int cell, PowerWireKind kind)
        {
            if (!IsPowerWireKindUnlocked(kind, true))
            {
                return;
            }

            if (!CanPlacePowerWire(cell, kind))
            {
                if (IsInside(cell.x, cell.y) && IsWorldLiquidCell(cells[cell.x, cell.y]))
                {
                    Log(PowerWireKindName(kind) + " cannot be built through water.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            float metalCost = PowerWireMetalCost(kind);
            float refinedMetalCost = PowerWireRefinedMetalCost(kind);
            string label = PowerWireKindName(kind);
            if (metal < metalCost || refinedMetal < refinedMetalCost)
            {
                Log(BuildCostFailureText(label, 0f, metalCost, 0f, refinedMetalCost));
                return;
            }

            metal -= metalCost;
            refinedMetal -= refinedMetalCost;
            Job job = new Job(JobType.BuildWire, cell, PowerWireWorkRequired(kind))
            {
                MetalCost = metalCost,
                RefinedMetalCost = refinedMetalCost,
                Priority = 5,
                BuildWire = true,
                PowerWireKind = kind
            };
            jobs.Add(job);
            gasDirty = true;
            overlayDirty = true;
            Log(label + " build queued.");
        }

        private bool CanPlacePowerWire(Vector2Int cell)
        {
            return CanPlacePowerWire(cell, PowerWireKind.Normal);
        }

        private bool CanPlacePowerWire(Vector2Int cell, PowerWireKind kind)
        {
            return IsInside(cell.x, cell.y) &&
                !IsWorldLiquidCell(cells[cell.x, cell.y]) &&
                cells[cell.x, cell.y] != CellKind.PowerBridge &&
                (!powerWire[cell.x, cell.y] || powerWireKind[cell.x, cell.y] != kind);
        }

        private PowerWireKind PowerWireKindForMode(CommandMode mode)
        {
            if (mode == CommandMode.HeavyWattWire)
            {
                return PowerWireKind.HeavyWatt;
            }

            return mode == CommandMode.ConductiveWire ? PowerWireKind.Conductive : PowerWireKind.Normal;
        }

        private PowerWireKind NormalizePowerWireKind(int kind)
        {
            int max = Enum.GetValues(typeof(PowerWireKind)).Length - 1;
            return (PowerWireKind)Mathf.Clamp(kind, 0, max);
        }

        private bool IsPowerWireKindUnlocked(PowerWireKind kind, bool showLog)
        {
            if ((kind == PowerWireKind.Conductive || kind == PowerWireKind.HeavyWatt) && !techPowerRegulation)
            {
                if (showLog)
                {
                    Log(kind == PowerWireKind.HeavyWatt ? "Research Power Regulation before building Heavy-Watt Wire." : "Research Power Regulation before building Conductive Wire.");
                }

                return false;
            }

            return true;
        }

        private float PowerWireMetalCost(PowerWireKind kind)
        {
            return kind == PowerWireKind.HeavyWatt ? 4f : 1f;
        }

        private float PowerWireRefinedMetalCost(PowerWireKind kind)
        {
            switch (kind)
            {
                case PowerWireKind.HeavyWatt:
                    return 2f;
                case PowerWireKind.Conductive:
                    return 1f;
                default:
                    return 0f;
            }
        }

        private float PowerWireWorkRequired(PowerWireKind kind)
        {
            switch (kind)
            {
                case PowerWireKind.HeavyWatt:
                    return 1.35f;
                case PowerWireKind.Conductive:
                    return 1.0f;
                default:
                    return 0.8f;
            }
        }

        private string PowerWireKindName(PowerWireKind kind)
        {
            switch (kind)
            {
                case PowerWireKind.HeavyWatt:
                    return "Heavy-Watt Wire";
                case PowerWireKind.Conductive:
                    return "Conductive Wire";
                default:
                    return "Power Wire";
            }
        }

        private float PowerWireSafeLoad(PowerWireKind kind)
        {
            switch (kind)
            {
                case PowerWireKind.HeavyWatt:
                    return HeavyWattWireSafeLoad;
                case PowerWireKind.Conductive:
                    return ConductiveWireSafeLoad;
                default:
                    return WireSafeLoad;
            }
        }

        private float RefundPowerWireMaterials(PowerWireKind kind)
        {
            float recovered = StoreDryResource(ref metal, PowerWireMetalCost(kind) * 0.5f);
            recovered += StoreDryResource(ref refinedMetal, PowerWireRefinedMetalCost(kind) * 0.5f);
            return recovered;
        }

        private void QueueAutomationWire(Vector2Int cell)
        {
            if (!techAutomationLogistics)
            {
                Log("Research Automation Logistics before building Automation Wire.");
                return;
            }

            if (!CanPlaceAutomationWire(cell))
            {
                if (IsInside(cell.x, cell.y) && IsWorldLiquidCell(cells[cell.x, cell.y]))
                {
                    Log("Automation Wire cannot be built through water.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            if (metal < 1f)
            {
                Log(BuildCostFailureText("Automation Wire", 0f, 1f, 0f, 0f));
                return;
            }

            metal -= 1f;
            Job job = new Job(JobType.BuildAutomationWire, cell, 0.75f)
            {
                MetalCost = 1f,
                Priority = 5
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Automation Wire build queued.");
        }

        private bool CanPlaceAutomationWire(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                !IsWorldLiquidCell(cells[cell.x, cell.y]) &&
                cells[cell.x, cell.y] != CellKind.AutomationBridge &&
                cells[cell.x, cell.y] != CellKind.AutomationNotGate &&
                cells[cell.x, cell.y] != CellKind.AutomationAndGate &&
                cells[cell.x, cell.y] != CellKind.AutomationOrGate &&
                cells[cell.x, cell.y] != CellKind.AutomationXorGate &&
                cells[cell.x, cell.y] != CellKind.AutomationBufferGate &&
                cells[cell.x, cell.y] != CellKind.AutomationFilterGate &&
                cells[cell.x, cell.y] != CellKind.AutomationMemoryGate &&
                !automationWire[cell.x, cell.y];
        }

        private void QueueLiquidPipe(Vector2Int cell)
        {
            QueueLiquidPipe(cell, LiquidPipeKind.Normal);
        }

        private void QueueLiquidPipe(Vector2Int cell, LiquidPipeKind kind)
        {
            if (kind != LiquidPipeKind.Normal && !techThermalEngineering)
            {
                Log("Research Thermal Engineering before building advanced liquid pipes.");
                return;
            }

            if (!CanPlaceLiquidPipe(cell, kind))
            {
                if (IsInside(cell.x, cell.y) && IsWorldLiquidCell(cells[cell.x, cell.y]))
                {
                    Log(LiquidPipeKindName(kind) + " cannot be built through open water.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            float metalCost = LiquidPipeMetalCost(kind);
            float refinedMetalCost = LiquidPipeRefinedMetalCost(kind);
            if (metal < metalCost || refinedMetal < refinedMetalCost)
            {
                Log(BuildCostFailureText(LiquidPipeKindName(kind), 0f, metalCost, 0f, refinedMetalCost));
                return;
            }

            metal -= metalCost;
            refinedMetal -= refinedMetalCost;
            Job job = new Job(JobType.BuildPipe, cell, LiquidPipeWorkRequired(kind))
            {
                MetalCost = metalCost,
                RefinedMetalCost = refinedMetalCost,
                Priority = 5,
                BuildPipe = true,
                LiquidPipeKind = kind
            };
            jobs.Add(job);
            overlayDirty = true;
            Log(LiquidPipeKindName(kind) + " build queued.");
        }

        private bool CanPlaceLiquidPipe(Vector2Int cell)
        {
            return CanPlaceLiquidPipe(cell, LiquidPipeKind.Normal);
        }

        private bool CanPlaceLiquidPipe(Vector2Int cell, LiquidPipeKind kind)
        {
            if (!IsInside(cell.x, cell.y) || IsWorldLiquidCell(cells[cell.x, cell.y]))
            {
