        private void QueueGasPipe(Vector2Int cell)
        {
            QueueGasPipe(cell, GasPipeKind.Normal);
        }

        private void QueueGasPipe(Vector2Int cell, GasPipeKind kind)
        {
            if (!techAirSystems)
            {
                Log("Research Air Systems before building " + GasPipeKindName(kind) + ".");
                return;
            }

            if (kind != GasPipeKind.Normal && !techThermalEngineering)
            {
                Log("Research Thermal Engineering before building advanced gas pipes.");
                return;
            }

            if (!CanPlaceGasPipe(cell, kind))
            {
                if (IsWorldLiquidCell(cells[cell.x, cell.y]))
                {
                    Log(GasPipeKindName(kind) + " cannot be built through open water.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            float metalCost = GasPipeMetalCost(kind);
            float refinedMetalCost = GasPipeRefinedMetalCost(kind);
            if (metal < metalCost || refinedMetal < refinedMetalCost)
            {
                Log(BuildCostFailureText(GasPipeKindName(kind), 0f, metalCost, 0f, refinedMetalCost));
                return;
            }

            metal -= metalCost;
            refinedMetal -= refinedMetalCost;
            Job job = new Job(JobType.BuildGasPipe, cell, GasPipeWorkRequired(kind))
            {
                MetalCost = metalCost,
                RefinedMetalCost = refinedMetalCost,
                Priority = 5,
                BuildGasPipe = true,
                GasPipeKind = kind
            };
            jobs.Add(job);
            overlayDirty = true;
            Log(GasPipeKindName(kind) + " build queued.");
        }

        private bool CanPlaceGasPipe(Vector2Int cell)
        {
            return CanPlaceGasPipe(cell, GasPipeKind.Normal);
        }

        private bool CanPlaceGasPipe(Vector2Int cell, GasPipeKind kind)
        {
            if (!IsInside(cell.x, cell.y) || IsWorldLiquidCell(cells[cell.x, cell.y]))
            {
                return false;
            }

            return !gasPipe[cell.x, cell.y] || gasPipeKind[cell.x, cell.y] != kind;
        }

        private GasPipeKind GasPipeKindForMode(CommandMode mode)
        {
            if (mode == CommandMode.RadiantGasPipe)
            {
                return GasPipeKind.Radiant;
            }

            if (mode == CommandMode.InsulatedGasPipe)
            {
                return GasPipeKind.Insulated;
            }

            return GasPipeKind.Normal;
        }

        private float GasPipeMetalCost(GasPipeKind kind)
        {
            return kind == GasPipeKind.Radiant ? 2f : 1f;
        }

        private float GasPipeRefinedMetalCost(GasPipeKind kind)
        {
            switch (kind)
            {
                case GasPipeKind.Radiant:
                    return 2f;
                case GasPipeKind.Insulated:
                    return 1f;
                default:
                    return 0f;
            }
        }

        private float GasPipeWorkRequired(GasPipeKind kind)
        {
            switch (kind)
            {
                case GasPipeKind.Radiant:
                    return 1.1f;
                case GasPipeKind.Insulated:
                    return 1.0f;
                default:
                    return 0.75f;
            }
        }

        private string GasPipeKindName(GasPipeKind kind)
        {
            switch (kind)
            {
                case GasPipeKind.Radiant:
                    return "Radiant Gas Pipe";
                case GasPipeKind.Insulated:
                    return "Insulated Gas Pipe";
                default:
                    return "Gas Pipe";
            }
        }

        private float GasPipeHeatTransferCoefficient(GasPipeKind kind)
        {
            switch (kind)
            {
                case GasPipeKind.Radiant:
                    return RadiantGasPipeHeatTransfer;
                case GasPipeKind.Insulated:
                    return InsulatedGasPipeHeatTransfer;
                default:
                    return NormalGasPipeHeatTransfer;
            }
        }

        private float RefundGasPipeMaterials(GasPipeKind kind)
        {
            float recovered = StoreDryResource(ref metal, GasPipeMetalCost(kind) * 0.5f);
            recovered += StoreDryResource(ref refinedMetal, GasPipeRefinedMetalCost(kind) * 0.5f);
            return recovered;
        }

        private void QueueShippingRail(Vector2Int cell)
        {
            if (!techAutomationLogistics)
            {
                Log("Research Automation Logistics before building Shipping Rail.");
                return;
            }

            if (!CanPlaceShippingRail(cell))
            {
                if (IsWorldLiquidCell(cells[cell.x, cell.y]))
                {
                    Log("Shipping Rail cannot be built through open water.");
                }

                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            if (metal < 1f)
            {
                Log(BuildCostFailureText("Shipping Rail", 0f, 1f, 0f, 0f));
                return;
            }

            metal -= 1f;
            Job job = new Job(JobType.BuildShippingRail, cell, 0.75f)
            {
                MetalCost = 1f,
                Priority = 5,
                BuildShippingRail = true
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Shipping Rail build queued.");
        }

        private bool CanPlaceShippingRail(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                !IsWorldLiquidCell(cells[cell.x, cell.y]) &&
                cells[cell.x, cell.y] != CellKind.ShippingBridge &&
                !shippingRail[cell.x, cell.y];
        }

        private void QueueDeconstruct(Vector2Int cell)
        {
            if (!TryGetDeconstructTarget(cell, out CellKind targetKind, out bool removePowerWire, out bool removeAutomationWire, out bool removeLiquidPipe, out bool removeGasPipe, out bool removeShippingRail))
            {
                Log("Nothing deconstructable at " + cell.x + ", " + cell.y + ".");
                return;
            }

            if (FindAnyJobAt(cell) != null)
            {
                return;
            }

            Job job = new Job(JobType.Deconstruct, cell, DeconstructWorkRequired(targetKind, removePowerWire, removeAutomationWire, removeLiquidPipe, removeGasPipe, removeShippingRail))
            {
                BuildKind = targetKind,
                RemovePowerWire = removePowerWire,
                RemoveAutomationWire = removeAutomationWire,
                RemoveLiquidPipe = removeLiquidPipe,
                RemoveGasPipe = removeGasPipe,
                RemoveShippingRail = removeShippingRail,
                Priority = 5
            };
            jobs.Add(job);
            overlayDirty = true;
            Log("Deconstruct queued: " + DeconstructTargetLabel(job) + ".");
        }

        private bool TryGetDeconstructTarget(Vector2Int cell, out CellKind targetKind, out bool removePowerWire, out bool removeAutomationWire, out bool removeLiquidPipe, out bool removeGasPipe, out bool removeShippingRail)
        {
            targetKind = CellKind.Empty;
            removePowerWire = false;
            removeAutomationWire = false;
            removeLiquidPipe = false;
            removeGasPipe = false;
            removeShippingRail = false;

            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (IsDeconstructableBuilding(cells[cell.x, cell.y]))
            {
                targetKind = cells[cell.x, cell.y];
                return true;
            }

            if (powerWire[cell.x, cell.y])
            {
                removePowerWire = true;
                return true;
            }

            if (automationWire[cell.x, cell.y])
            {
                removeAutomationWire = true;
                return true;
            }

            if (liquidPipe[cell.x, cell.y])
            {
                removeLiquidPipe = true;
                return true;
            }

            if (gasPipe[cell.x, cell.y])
            {
                removeGasPipe = true;
                return true;
            }

            if (shippingRail[cell.x, cell.y])
            {
                removeShippingRail = true;
                return true;
            }

            return false;
        }

        private float DeconstructWorkRequired(CellKind targetKind, bool removePowerWire, bool removeAutomationWire, bool removeLiquidPipe, bool removeGasPipe, bool removeShippingRail)
        {
            if (targetKind != CellKind.Empty)
            {
                BuildSpec spec = BuildSpecForKind(targetKind);
                return Mathf.Max(0.8f, spec.Work * 0.65f);
            }

            return (removePowerWire || removeAutomationWire || removeLiquidPipe || removeGasPipe || removeShippingRail) ? 0.65f : 1f;
        }

        private bool IsDeconstructableBuilding(CellKind kind)
        {
            return BuildSpecForKind(kind).Kind != CellKind.Empty;
        }

        private bool CanPlaceBuild(Vector2Int cell, CellKind buildKind)
        {
            CellKind current = cells[cell.x, cell.y];
            if (IsSolidTile(current))
            {
                return false;
            }

            if (current != CellKind.Empty)
            {
                if (buildKind != CellKind.LiquidTepidizer || !IsLiquidTepidizerBuildLiquid(current))
                {
                    return false;
                }
            }

            if (HasLooseResource(cell))
            {
                return false;
            }

            if (RequiresFloorSupport(buildKind) && !HasFloorSupport(cell))
            {
                return false;
            }

            if (RequiresCeilingSupport(buildKind) && !HasCeilingSupport(cell))
            {
                return false;
            }

            if (buildKind == CellKind.WaterPump && !HasAdjacentWater(cell))
            {
                return false;
            }

            if (buildKind == CellKind.PowerShutoff && !powerWire[cell.x, cell.y])
            {
                return false;
            }

            if ((buildKind == CellKind.LiquidPipeSensor || buildKind == CellKind.LiquidShutoff || buildKind == CellKind.LiquidValve) && !liquidPipe[cell.x, cell.y])
            {
                return false;
            }

            if ((buildKind == CellKind.GasPipeSensor || buildKind == CellKind.GasShutoff || buildKind == CellKind.GasValve) && !gasPipe[cell.x, cell.y])
            {
                return false;
            }

            if ((buildKind == CellKind.ShippingRailSensor || buildKind == CellKind.ShippingRailShutoff || buildKind == CellKind.ShippingRailMeter) && !shippingRail[cell.x, cell.y])
            {
                return false;
            }

            if ((buildKind == CellKind.LiquidBridge || buildKind == CellKind.GasBridge) && (liquidPipe[cell.x, cell.y] || gasPipe[cell.x, cell.y]))
            {
                return false;
            }

            if (buildKind == CellKind.ShippingBridge && shippingRail[cell.x, cell.y])
            {
                return false;
            }

            if (buildKind == CellKind.PowerBridge && powerWire[cell.x, cell.y])
            {
                return false;
            }

            if ((buildKind == CellKind.AutomationBridge || buildKind == CellKind.AutomationNotGate || buildKind == CellKind.AutomationAndGate || buildKind == CellKind.AutomationOrGate || buildKind == CellKind.AutomationXorGate || buildKind == CellKind.AutomationBufferGate || buildKind == CellKind.AutomationFilterGate || buildKind == CellKind.AutomationMemoryGate) && automationWire[cell.x, cell.y])
            {
                return false;
            }

            return true;
        }

        private bool RequiresFloorSupport(CellKind buildKind)
        {
            return buildKind == CellKind.Planter ||
                buildKind == CellKind.FungalFarm ||
                buildKind == CellKind.PepperPlant ||
                buildKind == CellKind.GrubfruitPlant ||
                buildKind == CellKind.ThimbleReed ||
                buildKind == CellKind.SleetWheat ||
                buildKind == CellKind.DecorPlant ||
                buildKind == CellKind.SculptingBlock ||
                buildKind == CellKind.RationBox ||
                buildKind == CellKind.Incubator ||
                buildKind == CellKind.CritterFeeder ||
                buildKind == CellKind.EggCracker ||
                buildKind == CellKind.ElectricGrill ||
                buildKind == CellKind.TextileLoom ||
                buildKind == CellKind.PowerControlStation ||
                buildKind == CellKind.ComfyBed ||
                buildKind == CellKind.Lavatory ||
                buildKind == CellKind.Shower ||
                buildKind == CellKind.HandSanitizer ||
                buildKind == CellKind.Apothecary ||
                buildKind == CellKind.WaterCooler ||
                buildKind == CellKind.ArcadeCabinet ||
                buildKind == CellKind.OrbitalDataBank ||
                buildKind == CellKind.VentAnalyzer ||
                buildKind == CellKind.OilWell ||
                buildKind == CellKind.Desalinator ||
                buildKind == CellKind.FertilizerSynthesizer ||
                buildKind == CellKind.MetalRefinery ||
                buildKind == CellKind.OxygenMaskDock ||
                buildKind == CellKind.OxygenMaskCheckpoint ||
                buildKind == CellKind.LeadSuitLocker ||
                buildKind == CellKind.LeadSuitCheckpoint ||
                buildKind == CellKind.SkillScrubber ||
                buildKind == CellKind.AlgaeTerrarium;
        }

        private bool RequiresCeilingSupport(CellKind buildKind)
        {
            return buildKind == CellKind.CeilingLight;
        }

        private bool HasFloorSupport(Vector2Int cell)
        {
            if (cell.y <= 0)
            {
                return true;
            }

            CellKind below = cells[cell.x, cell.y - 1];
            return IsSolidTile(below) ||
                below == CellKind.Floor ||
                below == CellKind.HydroponicFarm ||
                below == CellKind.MeshTile ||
                below == CellKind.ManualAirlock ||
                below == CellKind.MechanizedAirlock ||
                below == CellKind.BunkerDoor;
        }

        private bool HasCeilingSupport(Vector2Int cell)
        {
            if (cell.y >= WorldHeight - 1)
            {
                return true;
            }

            CellKind above = cells[cell.x, cell.y + 1];
            return IsSolidTile(above) ||
                above == CellKind.Floor ||
                above == CellKind.Tile ||
                above == CellKind.AirflowTile ||
                above == CellKind.MeshTile ||
                above == CellKind.InsulatedTile ||
                above == CellKind.ManualAirlock ||
                above == CellKind.MechanizedAirlock ||
                above == CellKind.BunkerDoor;
        }

        private void CancelJobsAt(Vector2Int cell, bool forceLog)
        {
            bool cancelled = false;
            for (int i = jobs.Count - 1; i >= 0; i--)
            {
                Job job = jobs[i];
                if (job.Cell != cell)
                {
                    continue;
                }

                RefundJobCost(job);
                if (job.AssignedWorker != null)
                {
                    ClearAssignment(job.AssignedWorker);
                }

                jobs.RemoveAt(i);
                cancelled = true;
            }

            if (cancelled)
            {
                overlayDirty = true;
                Log("Job cancelled at " + cell.x + ", " + cell.y + ".");
            }
            else if (powerWire[cell.x, cell.y])
            {
                PowerWireKind removedKind = powerWireKind[cell.x, cell.y];
                powerWire[cell.x, cell.y] = false;
                powerWireKind[cell.x, cell.y] = PowerWireKind.Normal;
                poweredWire[cell.x, cell.y] = false;
                wireLoad[cell.x, cell.y] = 0f;
                overloadedWire[cell.x, cell.y] = false;
                wireOverloadStress[cell.x, cell.y] = 0f;
                float recovered = RefundPowerWireMaterials(removedKind);
                gasDirty = true;
                overlayDirty = true;
                string label = PowerWireKindName(removedKind);
                Log(recovered > 0f ? label + " removed at " + cell.x + ", " + cell.y + "." : label + " removed, but dry storage is full.");
            }
            else if (automationWire[cell.x, cell.y])
            {
                automationWire[cell.x, cell.y] = false;
                automationControlledWire[cell.x, cell.y] = false;
                automationSignalWire[cell.x, cell.y] = false;
                float recovered = StoreDryResource(ref metal, 0.5f);
                overlayDirty = true;
                Log(recovered > 0f ? "Automation Wire removed at " + cell.x + ", " + cell.y + "." : "Automation Wire removed, but dry storage is full.");
            }
            else if (liquidPipe[cell.x, cell.y])
            {
                float drained = pipeWater[cell.x, cell.y];
                float drainedGerms = pipeWaterGerms[cell.x, cell.y];
                float pollutedDrained = pipePollutedWater[cell.x, cell.y];
                float pollutedDrainedGerms = pipePollutedWaterGerms[cell.x, cell.y];
                float petroleumDrained = pipePetroleum[cell.x, cell.y];
                LiquidPipeKind removedKind = liquidPipeKind[cell.x, cell.y];
                liquidPipe[cell.x, cell.y] = false;
                liquidPipeKind[cell.x, cell.y] = LiquidPipeKind.Normal;
                pipeWater[cell.x, cell.y] = 0f;
                pipeWaterGerms[cell.x, cell.y] = 0f;
                pipePollutedWater[cell.x, cell.y] = 0f;
                pipePollutedWaterGerms[cell.x, cell.y] = 0f;
                pipePetroleum[cell.x, cell.y] = 0f;
                StoreCleanWaterInStorage(drained, drainedGerms);
                StorePollutedWaterInStorage(pollutedDrained, pollutedDrainedGerms);
                StorePetroleumInStorage(petroleumDrained);
                float recovered = RefundLiquidPipeMaterials(removedKind);
                overlayDirty = true;
                string label = LiquidPipeKindName(removedKind);
                Log(recovered > 0f ? label + " removed at " + cell.x + ", " + cell.y + "." : label + " removed, but dry storage is full.");
            }
            else if (gasPipe[cell.x, cell.y])
            {
                GasPipeKind removedKind = gasPipeKind[cell.x, cell.y];
                ReleaseGasPipeContents(cell);
                gasPipe[cell.x, cell.y] = false;
                gasPipeKind[cell.x, cell.y] = GasPipeKind.Normal;
                gasPipeOxygen[cell.x, cell.y] = 0f;
                gasPipeCarbonDioxide[cell.x, cell.y] = 0f;
                gasPipePollutedOxygen[cell.x, cell.y] = 0f;
                gasPipeHydrogen[cell.x, cell.y] = 0f;
                gasPipeSteam[cell.x, cell.y] = 0f;
                gasPipeChlorine[cell.x, cell.y] = 0f;
                gasPipeNaturalGas[cell.x, cell.y] = 0f;
                gasPipeSourGas[cell.x, cell.y] = 0f;
                gasPipeGerms[cell.x, cell.y] = 0f;
                float recovered = RefundGasPipeMaterials(removedKind);
                gasDirty = true;
                overlayDirty = true;
                string label = GasPipeKindName(removedKind);
                Log(recovered > 0f ? label + " removed at " + cell.x + ", " + cell.y + "." : label + " removed, but dry storage is full.");
            }
            else if (shippingRail[cell.x, cell.y])
            {
                ReleaseShippingRailContents(cell);
                shippingRail[cell.x, cell.y] = false;
                shippingRailKind[cell.x, cell.y] = LooseResourceKind.None;
                shippingRailAmount[cell.x, cell.y] = 0f;
                shippingRailMeterFlowRemaining[cell.x, cell.y] = 0f;
                float recovered = StoreDryResource(ref metal, 0.5f);
                overlayDirty = true;
                Log(recovered > 0f ? "Shipping Rail removed at " + cell.x + ", " + cell.y + "." : "Shipping Rail removed, but dry storage is full.");
            }
            else if (forceLog)
            {
                Log("No job at " + cell.x + ", " + cell.y + ".");
            }
        }

        private void CancelQueuedJobsAt(Vector2Int cell)
        {
            bool cancelled = false;
            for (int i = jobs.Count - 1; i >= 0; i--)
            {
                Job job = jobs[i];
                if (job.Cell != cell)
                {
                    continue;
                }

                RefundJobCost(job);
                if (job.AssignedWorker != null)
                {
                    ClearAssignment(job.AssignedWorker);
                }

                jobs.RemoveAt(i);
                cancelled = true;
            }

            if (cancelled)
            {
                overlayDirty = true;
                Log("Job cancelled at " + cell.x + ", " + cell.y + ".");
            }
        }

        private void SimulateColony(float deltaTime)
        {
            if (colonyFailed)
            {
                return;
            }

            elapsedTime += deltaTime;
            cycleTimer += deltaTime;
            gasTimer += deltaTime;
            thermalTimer += deltaTime;
            sandTimer += deltaTime;
            maintenanceTimer += deltaTime;
            autosaveTimer += deltaTime;
            objectiveTimer += deltaTime;
            if (redAlertActive)
            {
                redAlertSeconds += deltaTime;
            }

            UpdateJobAges(deltaTime);

            if (cycleTimer >= CycleLengthSeconds)
            {
                cycleTimer -= CycleLengthSeconds;
                CompleteCycleReport();
                ResetWorkerCommutes();
                cycle++;
                Log("Cycle " + cycle + " started.");
            }

            if (objectiveTimer >= ObjectiveRefreshSeconds)
            {
                objectiveTimer = 0f;
                UpdateColonyStatus(false);
            }

            if (autosaveTimer >= AutosaveIntervalSeconds)
            {
                autosaveTimer = 0f;
                SaveGame(true);
            }

            if (maintenanceTimer >= 0.75f)
            {
                maintenanceTimer = 0f;
                EnsureMaintenanceJobs();
            }

            AdvanceAutomationTimerSensors(deltaTime);
            UpdateAutomationWires();
            AdvanceAutomationBufferGates(deltaTime);
            UpdateAutomationWires();
            AdvanceAutomationFilterGates(deltaTime);
            UpdateAutomationWires();
            UpdateAutomationMemoryGates();
            UpdateAutomationWires();
            ResetConduitValveFlowBudgets(deltaTime);
            UpdatePoweredWires();
            UpdatePowerLoad(deltaTime, true);
            if (currentOverlayMode == OverlayMode.Power ||
                currentOverlayMode == OverlayMode.Automation ||
                currentOverlayMode == OverlayMode.Vitals ||
                currentOverlayMode == OverlayMode.Medical ||
                currentOverlayMode == OverlayMode.Morale ||
                currentOverlayMode == OverlayMode.Suit ||
                currentOverlayMode == OverlayMode.Materials ||
                currentOverlayMode == OverlayMode.Food ||
                currentOverlayMode == OverlayMode.Errands ||
                currentOverlayMode == OverlayMode.Farming ||
                currentOverlayMode == OverlayMode.Light)
            {
                gasDirty = true;
            }

            SimulateBuildings(deltaTime);
            SimulatePrintingPods(deltaTime);
            SimulateNaturalVents(deltaTime);
            SimulateMeteorShowers(deltaTime);
            SimulateHatches(deltaTime);
            SimulateHatchEggs(deltaTime);
            SimulateShipping(deltaTime);
            SimulatePlumbing(deltaTime);
            SimulateFlooding(deltaTime);
            SimulateVentilation(deltaTime);
            SimulateFoodSpoilage(deltaTime);
            SimulatePollutedDirtOffgas(deltaTime);
            SimulateSlimeOffgas(deltaTime);
            SimulateBleachStoneOffgas(deltaTime);
            SimulatePollutedWaterOffgas(deltaTime);
            SimulateChlorineLiquidSterilization(deltaTime);
            SimulateChlorineGasConduitSterilization(deltaTime);

            if (sandTimer >= SandFallInterval)
            {
                sandTimer = 0f;
                SimulateFallingSand();
            }

            if (gasTimer >= 0.18f)
            {
                float gasStep = gasTimer;
                gasTimer = 0f;
                StepGas(gasStep);
                gasDirty = true;
            }

            if (thermalTimer >= 0.5f)
            {
                float thermalStep = thermalTimer;
                thermalTimer = 0f;
                StepTemperature(thermalStep);
                SimulateMagmaHeat(thermalStep);
                SimulateCrudeOilThermalCracking(thermalStep);
                SimulateWheezeworts(thermalStep);
                SimulateAntiEntropyThermoNullifiers(thermalStep);
                SimulateLiquidPipeHeatExchange(thermalStep);
                SimulateGasPipeHeatExchange(thermalStep);
                SimulateLiquidPipePhaseRuptures(thermalStep);
                SimulateLiquidReservoirPhaseRuptures(thermalStep);
                SimulateGasConduitSteamCondensation(thermalStep);
                SimulateEquipmentOverheating(thermalStep);
                gasDirty = true;
            }
        }

        private void ResetCycleReports()
        {
            currentCycleReport = CreateCycleReport(Mathf.Max(1, cycle));
            lastCycleReport = default;
            hasLastCycleReport = false;
        }

        private void CompleteCycleReport()
        {
            UpdateCycleReportBalances();
            currentCycleReport.Cycle = Mathf.Max(1, cycle);
            lastCycleReport = currentCycleReport;
            hasLastCycleReport = true;
            UpdateSustainableCycleStreak(lastCycleReport);
            currentCycleReport = CreateCycleReport(cycle + 1);
        }

        private CycleReport CreateCycleReport(int reportCycle)
        {
            float cleanWaterStock = TotalCleanWaterStock();
            float oxygenStock = TotalBreathableOxygenStock();
            float foodStock = Mathf.Max(0f, food);
            float powerStock = Mathf.Max(0f, power);
            return new CycleReport
            {
                Cycle = Mathf.Max(1, reportCycle),
                FoodStart = foodStock,
                FoodEnd = foodStock,
                WaterStart = cleanWaterStock,
                WaterEnd = cleanWaterStock,
                PowerStart = powerStock,
                PowerEnd = powerStock,
                OxygenStart = oxygenStock,
                OxygenEnd = oxygenStock
            };
        }

        private void UpdateCycleReportBalances()
        {
            if (currentCycleReport.Cycle <= 0)
            {
                currentCycleReport = CreateCycleReport(Mathf.Max(1, cycle));
                return;
            }

            currentCycleReport.Cycle = Mathf.Max(1, currentCycleReport.Cycle);
            currentCycleReport.FoodEnd = Mathf.Max(0f, food);
            currentCycleReport.WaterEnd = TotalCleanWaterStock();
            currentCycleReport.PowerEnd = Mathf.Max(0f, power);
            currentCycleReport.OxygenEnd = TotalBreathableOxygenStock();
        }

        private void UpdateSustainableCycleStreak(CycleReport report)
        {
            sustainableCycleStreak = IsSustainableCycle(report)
                ? Mathf.Min(SustainableCycleTarget, sustainableCycleStreak + 1)
                : 0;
        }

        private bool IsSustainableCycle(CycleReport report)
        {
            int activeWorkers = CountActiveWorkers();
            int livingWorkers = Mathf.Max(1, activeWorkers > 0 ? activeWorkers : workers.Count);
            return activeWorkers > 0 &&
                !colonyFailed &&
                milestoneSafetyOperations &&
                milestoneRoomSpecialization &&
                !AnyWorkerNeedsRescue() &&
                !AnyWorkerNeedsTreatment() &&
                CountLowMoraleWorkers() == 0 &&
                CountBrokenEquipment() == 0 &&
                CountOverheatingEquipment() == 0 &&
                CountSubmergedEquipment() == 0 &&
                CountFloodedPowerWires() == 0 &&
                CountDangerousPressureTiles() == 0 &&
                CountOverloadedPowerWires() == 0 &&
                foodGerms < FoodGermExposureThreshold &&
                (food <= 1f || foodFreshness >= 0.45f) &&
                AverageGas(oxygen) >= 0.22f &&
                !HasCycleDeficit(report.FoodEnd - report.FoodStart, 350f) &&
                !HasCycleDeficit(report.WaterEnd - report.WaterStart, 6f) &&
                !HasCycleDeficit(report.PowerEnd - report.PowerStart, 8f) &&
                !HasCycleDeficit(report.OxygenEnd - report.OxygenStart, 0.35f) &&
                report.FoodEnd >= livingWorkers * 1400f &&
                report.WaterEnd >= livingWorkers * 16f &&
                (maxPower <= 0.001f || report.PowerEnd >= maxPower * 0.20f);
        }

        private void ResetWorkerCommutes()
        {
            foreach (Worker worker in workers)
            {
                worker.CommuteSeconds = 0f;
            }
        }

        private float AddGeneratedPower(float amount)
        {
            float generated = Mathf.Min(Mathf.Max(0f, amount), Mathf.Max(0f, maxPower - power));
            if (generated <= 0f)
            {
                return 0f;
            }

            power += generated;
            currentCycleReport.PowerGenerated += generated;
            return generated;
        }

        private float ConsumeCyclePower(float requested)
        {
            float consumed = Mathf.Min(Mathf.Max(0f, requested), power);
            if (consumed <= 0f)
            {
                return 0f;
            }

            power -= consumed;
            currentCycleReport.PowerConsumed += consumed;
            return consumed;
        }

        private float ConsumeBatteryLeak(float requested)
        {
            float leaked = ConsumeCyclePower(requested);
            if (leaked <= 0f)
            {
                return 0f;
            }

            currentCycleReport.PowerLeaked += leaked;
            batteryPowerLeaked += leaked;
            return leaked;
        }

        private float ConsumeCycleWater(float requested)
        {
            return ConsumeCycleWater(requested, out _);
        }

        private float ConsumeCycleWater(float requested, out float consumedGerms)
        {
            float consumed = Mathf.Min(Mathf.Max(0f, requested), water);
            consumedGerms = consumed > 0.001f ? waterGerms : 0f;
            if (consumed <= 0f)
            {
                return 0f;
            }

            water -= consumed;
            if (water <= 0.001f)
            {
                waterGerms = 0f;
            }

            currentCycleReport.WaterConsumed += consumed;
            return consumed;
        }

        private void SimulateBuildings(float deltaTime)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    CellKind kind = cells[x, y];
                    Vector2Int cell = new Vector2Int(x, y);
                    UpdateGeneratorTuneUp(cell, deltaTime);
                    if (IsBrokenEquipment(cell))
                    {
                        continue;
                    }

                    if (kind == CellKind.OxygenDiffuser && algae > 0.02f && CanPoweredMachineRun(cell))
                    {
                        float spendPower = Mathf.Min(power, 0.95f * deltaTime);
                        float spendAlgae = Mathf.Min(algae, 0.075f * deltaTime);
                        float efficiency = Mathf.Min(spendPower / Mathf.Max(0.001f, 0.95f * deltaTime), spendAlgae / Mathf.Max(0.001f, 0.075f * deltaTime));
                        float airSystemsBonus = techAirSystems ? 1.35f : 1f;
                        ConsumeCyclePower(spendPower * efficiency);
                        algae -= spendAlgae * efficiency;
                        AddOxygen(cell, 0.82f * deltaTime * efficiency * airSystemsBonus);
                        AddHeat(cell, 0.08f * deltaTime * efficiency, 1);
                        WearEquipment(cell, 0.00034f * deltaTime * efficiency);
                    }
                    else if (kind == CellKind.AlgaeTerrarium)
                    {
                        RunAlgaeTerrarium(cell, deltaTime);
                    }
                    else if (IsCropKind(kind))
                    {
                        float localOxygen = oxygen[x, y];
                        float localTemperature = temperature[x, y];
                        float localPressure = TileGasTotal(x, y);
                        bool irrigated = HasCropIrrigation(cell);
                        bool lit = IsCellLit(x, y);
                        bool flooded = waterMass[x, y] >= CropFloodWaterMass;
                        bool overpressured = localPressure > OverpressureDamageThreshold;
                        bool comfortableTemperature = CropComfortableTemperature(kind, localTemperature);
                        bool lethalTemperature = CropLethalTemperature(kind, localTemperature);
                        bool healthyCrop = CropAtmosphereSatisfied(kind, x, y) &&
                            irrigated &&
                            comfortableTemperature &&
                            !flooded &&
                            !overpressured &&
                            CropLightSatisfied(kind, lit);
                        float previousStress = cropStress[x, y];
                        if (healthyCrop)
                        {
                            cropStress[x, y] = Mathf.Max(0f, cropStress[x, y] - CropStressRecoveryRate * deltaTime);
                        }
                        else
                        {
                            cropStress[x, y] = Mathf.Min(CropWiltThresholdSeconds + 12f, cropStress[x, y] + deltaTime);
                            cropStifledSeconds += deltaTime;
                        }

                        float stressPenalty = Mathf.InverseLerp(CropStressThresholdSeconds, CropWiltThresholdSeconds, cropStress[x, y]);
                        float growthRate = healthyCrop ? CropBaseGrowthRate(kind) * Mathf.Lerp(1f, 0.22f, stressPenalty) : cropStress[x, y] < CropStressThresholdSeconds ? 0.003f : 0f;
                        bool tended = cropTendedSeconds[x, y] > 0f;
                        if (tended && growthRate > 0f)
                        {
                            growthRate *= cropTendedSeconds[x, y] > CropTendedSeconds ? FertilizedCropGrowthMultiplier : CropTendedGrowthMultiplier;
                        }

                        if (healthyCrop && growthRate > 0f && lit)
                        {
                            growthRate *= LitCropGrowthMultiplier;
                        }

                        if (lethalTemperature || flooded || overpressured)
                        {
                            growthRate = -0.012f * Mathf.Lerp(1f, 1.8f, stressPenalty);
                        }

                        if (irrigated)
                        {
                            ConsumeCropIrrigationWater(cell, CropConsumableRateFor(kind) * deltaTime);
                        }

                        plantGrowth[x, y] = Mathf.Clamp01(plantGrowth[x, y] + growthRate * deltaTime);
                        cropTendedSeconds[x, y] = Mathf.Max(0f, cropTendedSeconds[x, y] - deltaTime);
                        if ((previousStress < CropStressThresholdSeconds && cropStress[x, y] >= CropStressThresholdSeconds) ||
                            (previousStress >= CropStressThresholdSeconds && cropStress[x, y] < CropStressThresholdSeconds) ||
                            (previousStress < CropWiltThresholdSeconds && cropStress[x, y] >= CropWiltThresholdSeconds) ||
                            (previousStress >= CropWiltThresholdSeconds && cropStress[x, y] < CropWiltThresholdSeconds))
                        {
                            terrainDirty = true;
                            overlayDirty = true;
                        }

                        if (previousStress < CropWiltThresholdSeconds && cropStress[x, y] >= CropWiltThresholdSeconds)
                        {
                            plantGrowth[x, y] = Mathf.Max(0f, plantGrowth[x, y] - 0.22f);
                            cropsWilted++;
                            terrainDirty = true;
                            overlayDirty = true;
                            Log("A crop is wilting from " + CropStressReason(new Vector2Int(x, y)) + ".");
                        }
                    }
                    else if (kind == CellKind.Slime)
                    {
                        VentPollutedOxygen(new Vector2Int(x, y), 0.035f * deltaTime, 0.16f * deltaTime);
                    }
                    else if (kind == CellKind.AirDeodorizer && CanPoweredMachineRun(cell))
                    {
                        RunAirDeodorizer(cell, deltaTime);
                    }
                    else if (kind == CellKind.Electrolyzer && CanPoweredMachineRun(cell))
                    {
                        RunElectrolyzer(cell, deltaTime);
                    }
                    else if (kind == CellKind.CarbonSkimmer && CanPoweredMachineRun(cell))
                    {
                        RunCarbonSkimmer(cell, deltaTime);
                    }
                    else if (kind == CellKind.WaterSieve && CanPoweredMachineRun(cell))
                    {
                        RunWaterSieve(cell, deltaTime);
                    }
                    else if (kind == CellKind.Desalinator && CanPoweredMachineRun(cell))
                    {
                        RunDesalinator(cell, deltaTime);
                    }
                    else if (kind == CellKind.FertilizerSynthesizer && CanPoweredMachineRun(cell))
                    {
                        RunFertilizerSynthesizer(cell, deltaTime);
                    }
                    else if (kind == CellKind.MetalRefinery && CanPoweredMachineRun(cell))
                    {
                        RunMetalRefinery(cell, deltaTime);
                    }
                    else if (kind == CellKind.OilWell && CanPoweredMachineRun(cell))
                    {
                        RunOilWell(cell, deltaTime);
                    }
                    else if (kind == CellKind.OilRefinery && CanPoweredMachineRun(cell))
                    {
                        RunOilRefinery(cell, deltaTime);
                    }
                    else if (kind == CellKind.EthanolDistiller && CanPoweredMachineRun(cell))
                    {
                        RunEthanolDistiller(cell, deltaTime);
                    }
                    else if (kind == CellKind.TextileLoom && CanPoweredMachineRun(cell))
                    {
                        RunTextileLoom(cell, deltaTime);
                    }
                    else if (kind == CellKind.PolymerPress && CanPoweredMachineRun(cell))
                    {
                        RunPolymerPress(cell, deltaTime);
                    }
                    else if (kind == CellKind.Compost && pollutedDirt > 0.1f)
                    {
                        VentPollutedOxygen(cell, 0.004f * deltaTime, 0.018f * deltaTime);
                        WearEquipment(cell, 0.00012f * deltaTime);
                    }
                    else if (kind == CellKind.SpaceHeater && CanPoweredMachineRun(cell))
                    {
                        RunSpaceHeater(cell, deltaTime);
                    }
                    else if (kind == CellKind.LiquidTepidizer && CanPoweredMachineRun(cell))
                    {
                        RunLiquidTepidizer(cell, deltaTime);
                    }
                    else if (kind == CellKind.ThermoRegulator && CanPoweredMachineRun(cell))
                    {
                        RunThermoRegulator(cell, deltaTime);
                    }
                    else if (kind == CellKind.ThermoAquatuner && CanPoweredMachineRun(cell))
                    {
                        RunThermoAquatuner(cell, deltaTime);
                    }
                    else if (kind == CellKind.Refrigerator && CanPoweredMachineRun(cell))
                    {
                        RunRefrigerator(cell, deltaTime);
                    }
                    else if (kind == CellKind.AutoSweeper && CanPoweredMachineRun(cell))
                    {
                        RunAutoSweeper(cell, deltaTime);
                    }
                    else if (kind == CellKind.CoalGenerator)
                    {
                        RunCoalGenerator(cell, deltaTime);
                    }
                    else if (kind == CellKind.HydrogenGenerator)
                    {
                        RunHydrogenGenerator(cell, deltaTime);
                    }
                    else if (kind == CellKind.NaturalGasGenerator)
                    {
                        RunNaturalGasGenerator(cell, deltaTime);
                    }
                    else if (kind == CellKind.PetroleumGenerator)
                    {
                        RunPetroleumGenerator(cell, deltaTime);
                    }
                    else if (kind == CellKind.SteamTurbine)
                    {
                        RunSteamTurbine(cell, deltaTime);
                    }
                    else if (kind == CellKind.ResearchReactor)
                    {
                        RunResearchReactor(cell, deltaTime);
                    }
                    else if (kind == CellKind.RadboltCollector && CanPoweredMachineRun(cell))
                    {
                        RunRadboltCollector(cell, deltaTime);
                    }
                    else if (kind == CellKind.SolarPanel)
                    {
                        RunSolarPanel(cell, deltaTime);
                    }
                    else if (kind == CellKind.SpaceScanner)
                    {
                        RunSpaceScanner(cell, deltaTime);
                    }
                    else if (kind == CellKind.VentAnalyzer)
                    {
                        RunVentAnalyzer(cell, deltaTime);
                    }
                    else if (kind == CellKind.RocketPlatform)
                    {
                        RunRocketPlatform(cell, deltaTime);
                    }
                    else if (kind == CellKind.OrbitalDataBank)
                    {
                        RunOrbitalDataBank(cell, deltaTime);
                    }
                    else if (kind == CellKind.HydrogenFilter && CanPoweredMachineRun(cell))
                    {
                        RunHydrogenFilter(cell, deltaTime);
                    }
                    else if (kind == CellKind.GasFilter && CanPoweredMachineRun(cell))
                    {
                        RunGasFilter(cell, deltaTime);
                    }
                    else if (kind == CellKind.SourGasCondenser && CanPoweredMachineRun(cell))
                    {
                        RunSourGasCondenser(cell, deltaTime);
                    }
                    else if (kind == CellKind.LiquidFilter && CanPoweredMachineRun(cell))
                    {
                        RunLiquidFilter(cell, deltaTime);
                    }
                    else if (kind == CellKind.AtmoSuitDock)
                    {
                        RunAtmoSuitDock(cell, deltaTime);
                    }
                    else if (kind == CellKind.OxygenMaskDock)
                    {
                        RunOxygenMaskDock(cell, deltaTime);
                    }
                    else if (kind == CellKind.Incubator)
                    {
                        RunIncubator(cell, deltaTime);
                    }
                    else if (kind == CellKind.CeilingLight && CanPoweredMachineRun(cell))
                    {
                        RunCeilingLight(cell, deltaTime);
                    }
                    else if (kind == CellKind.Battery)
                    {
                        RunBattery(cell, deltaTime);
                    }
                    else if (kind == CellKind.JumboBattery)
                    {
                        RunJumboBattery(cell, deltaTime);
                    }
                    else if (kind == CellKind.SmartBattery)
                    {
                        RunSmartBattery(cell, deltaTime);
                    }
                }
            }
        }

        private void RunBattery(Vector2Int cell, float deltaTime)
        {
            RunBatteryStorage(cell, deltaTime, BatteryLeakRate, BatteryHeatRate, BatteryWearRate);
        }

        private void RunJumboBattery(Vector2Int cell, float deltaTime)
        {
            RunBatteryStorage(cell, deltaTime, JumboBatteryLeakRate, JumboBatteryHeatRate, JumboBatteryWearRate);
        }

        private void RunSmartBattery(Vector2Int cell, float deltaTime)
        {
            RunBatteryStorage(cell, deltaTime, SmartBatteryLeakRate, SmartBatteryHeatRate, SmartBatteryWearRate);
        }

        private void RunBatteryStorage(Vector2Int cell, float deltaTime, float leakRate, float heatRate, float wearRate)
        {
            ConsumeBatteryLeak(leakRate * deltaTime);
            AddHeat(cell, heatRate * deltaTime, 1);
            WearEquipment(cell, wearRate * deltaTime);
        }

        private float BatteryLeakRateAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            switch (cells[x, y])
            {
                case CellKind.Battery:
                    return BatteryLeakRate;
                case CellKind.JumboBattery:
                    return JumboBatteryLeakRate;
                case CellKind.SmartBattery:
                    return SmartBatteryLeakRate;
                default:
                    return 0f;
            }
        }

        private float BatteryHeatRateAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            switch (cells[x, y])
            {
                case CellKind.Battery:
                    return BatteryHeatRate;
                case CellKind.JumboBattery:
                    return JumboBatteryHeatRate;
                case CellKind.SmartBattery:
                    return SmartBatteryHeatRate;
                default:
                    return 0f;
            }
        }

        private float ActiveBatteryLeakRate()
        {
            float leakRate = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (BatteryLeakRateAt(x, y) <= 0f || IsBrokenEquipment(new Vector2Int(x, y)))
                    {
                        continue;
                    }

                    leakRate += BatteryLeakRateAt(x, y);
                }
            }

            return leakRate;
        }

        private void RunCeilingLight(Vector2Int cell, float deltaTime)
        {
            float requestedPower = CeilingLightPowerRate * deltaTime;
            float consumed = ConsumeCyclePower(requestedPower);
            float efficiency = consumed / Mathf.Max(0.001f, requestedPower);
            if (efficiency <= 0f)
            {
                return;
            }

            AddHeat(cell, 0.012f * deltaTime * efficiency, 1);
            WearEquipment(cell, 0.00008f * deltaTime * efficiency);
            if (currentOverlayMode == OverlayMode.Decor || currentOverlayMode == OverlayMode.Power || currentOverlayMode == OverlayMode.Light)
            {
                overlayDirty = true;
            }
        }

        private void SimulatePrintingPods(float deltaTime)
        {
            if (CountCells(CellKind.PrintingPod) == 0)
            {
                printingPodProgress = 0f;
                ClearPrintingPodOffers();
                return;
            }

            if (printingPodOfferReady)
            {
                printingPodProgress = 1f;
                return;
            }

            if (CountActiveWorkers() == 0)
            {
                return;
            }

            printingPodProgress = Mathf.Clamp01(printingPodProgress + deltaTime / PrintingPodChargeSeconds);
            if (printingPodProgress >= 1f)
            {
                GeneratePrintingPodOffers(true);
            }
        }

        private bool TryPrintDuplicant()
        {
            int workerIndex = workers.Count + duplicantsPrinted;
            return TryPrintDuplicant(NextDuplicantName(), DefaultWorkerTrait(workerIndex), DefaultWorkerInterest(workerIndex));
        }

        private bool TryPrintDuplicant(string workerName, WorkerTrait trait, JobCategory interest)
        {
            if (workers.Count >= MaxWorkers)
            {
                return false;
            }

            if (!TryFindPrintingPodSpawn(out Vector2Int spawnCell))
            {
                Log("Printing Pod is ready, but nearby space is blocked.");
                return false;
            }

            SpawnWorker(workerName, spawnCell, WorkerTint(workers.Count));
            Worker worker = workers[workers.Count - 1];
            worker.Trait = trait;
            worker.NarcolepticNapSeconds = 0f;
            worker.NarcolepticCooldownSeconds = InitialNarcolepticCooldownSeconds(workers.Count - 1, trait);
            worker.FlatulenceCooldownSeconds = InitialFlatulenceCooldownSeconds(workers.Count - 1, trait);
            worker.FlatulenceGasProduced = 0f;
            worker.Interest = interest;
            worker.Role = interest;
            worker.Stress = 6f;
            worker.Fatigue = 12f;
            worker.Bladder = 12f;
            AddFreshFood(700f, 0.92f, PackagedFoodQuality);
            StoreCleanWaterInStorage(8f, 0f);
            currentCycleReport.WaterProduced += 8f;
            duplicantsPrinted++;
            milestoneColonyExpansion = true;
            terrainDirty = true;
            overlayDirty = true;
            Log("Printing Pod welcomed " + workerName + ". Colony population is now " + workers.Count + ".");
            return true;
        }

        private void GeneratePrintingPodOffers(bool announce)
        {
            EnsurePrintingPodOfferArray();
            printingPodProgress = 1f;
            printingPodOfferReady = true;

            string workerName = NextDuplicantName();
            int workerIndex = workers.Count + duplicantsPrinted;
            WorkerTrait trait = DefaultWorkerTrait(workerIndex);
            JobCategory interest = DefaultWorkerInterest(workerIndex);
            printingPodOffers[0] = workers.Count < MaxWorkers
                ? new PrintingPodOffer(PrintingPodOfferKind.Duplicant, 1f, workerName, trait, interest)
                : new PrintingPodOffer(PrintingPodOfferKind.ResearchPoints, 10f);
            printingPodOffers[1] = PreferredSurvivalPrintingPodOffer();
            printingPodOffers[2] = PreferredIndustryPrintingPodOffer();

            if (announce)
            {
                Log("Printing Pod is ready. Choose a printable offer.");
            }

            UpdateHud();
        }

        private PrintingPodOffer PreferredSurvivalPrintingPodOffer()
        {
            int livingWorkers = Mathf.Max(1, CountActiveWorkers() > 0 ? CountActiveWorkers() : workers.Count);
            if (food < livingWorkers * 1400f)
            {
                return new PrintingPodOffer(PrintingPodOfferKind.Food, 1400f);
            }

            if (water < 35f)
            {
                return new PrintingPodOffer(PrintingPodOfferKind.Water, 45f);
            }

            if (algae < 18f && CountCells(CellKind.Electrolyzer) == 0)
            {
                return new PrintingPodOffer(PrintingPodOfferKind.Algae, 24f);
            }

            return new PrintingPodOffer(PrintingPodOfferKind.Food, 900f);
        }

        private PrintingPodOffer PreferredIndustryPrintingPodOffer()
        {
            if (techPowerRegulation && refinedMetal < 24f)
            {
                return new PrintingPodOffer(PrintingPodOfferKind.RefinedMetal, 18f);
            }

            if (CountCells(CellKind.CoalGenerator) > 0 && coal < 24f)
            {
                return new PrintingPodOffer(PrintingPodOfferKind.Coal, 32f);
            }

            if (HasLockedResearch() && CountCells(CellKind.ResearchStation) > 0)
            {
                return new PrintingPodOffer(PrintingPodOfferKind.ResearchPoints, 6f);
            }

            return new PrintingPodOffer(PrintingPodOfferKind.Metal, 38f);
        }

        private void ClaimPrintingPodOffer(int optionIndex)
        {
            EnsurePrintingPodOfferArray();
            if (!printingPodOfferReady || optionIndex < 0 || optionIndex >= printingPodOffers.Length)
            {
                Log("Printing Pod is still charging.");
                return;
            }

            PrintingPodOffer offer = printingPodOffers[optionIndex];
            if (!ApplyPrintingPodOffer(offer))
            {
                return;
            }

            printingPodOfferReady = false;
            printingPodProgress = 0f;
            ClearPrintingPodOffers();
            milestoneColonyExpansion |= workers.Count >= 4 || duplicantsPrinted > 0;
            terrainDirty = true;
            overlayDirty = true;
            UpdateColonyStatus(false);
            UpdateHud();
        }

        private bool ApplyPrintingPodOffer(PrintingPodOffer offer)
        {
            switch (offer.Kind)
            {
                case PrintingPodOfferKind.Duplicant:
                    return TryPrintDuplicant(string.IsNullOrEmpty(offer.WorkerName) ? NextDuplicantName() : offer.WorkerName, offer.Trait, offer.Interest);
                case PrintingPodOfferKind.Food:
                    AddFreshFood(offer.Amount, 0.90f, PackagedFoodQuality);
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " kcal food.");
                    return true;
                case PrintingPodOfferKind.Water:
                    StoreCleanWaterInStorage(offer.Amount, 0f);
                    currentCycleReport.WaterProduced += offer.Amount;
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " kg clean water.");
                    return true;
                case PrintingPodOfferKind.Algae:
                    algae += offer.Amount;
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " kg algae.");
                    return true;
                case PrintingPodOfferKind.Metal:
                    metal += offer.Amount;
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " kg metal ore.");
                    return true;
                case PrintingPodOfferKind.Coal:
                    coal += offer.Amount;
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " kg coal.");
                    return true;
                case PrintingPodOfferKind.RefinedMetal:
                    refinedMetal += offer.Amount;
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " kg refined metal.");
                    return true;
                case PrintingPodOfferKind.ResearchPoints:
                    researchPoints += offer.Amount;
                    currentCycleReport.ResearchPoints += offer.Amount;
                    ApplyResearchUnlocks(true);
                    Log("Printing Pod supplied " + offer.Amount.ToString("0") + " research points.");
                    return true;
                default:
                    Log("Printing Pod offer is invalid.");
                    return false;
            }
        }

        private void EnsurePrintingPodOfferArray()
        {
            if (printingPodOffers == null || printingPodOffers.Length != PrintingPodOfferCount)
            {
                printingPodOffers = new PrintingPodOffer[PrintingPodOfferCount];
            }
        }

        private void ClearPrintingPodOffers()
        {
            printingPodOfferReady = false;
            EnsurePrintingPodOfferArray();
            for (int i = 0; i < printingPodOffers.Length; i++)
            {
                printingPodOffers[i] = default;
            }
        }

        private bool CanClaimPrintingPodOffer(int optionIndex)
        {
            EnsurePrintingPodOfferArray();
            if (!printingPodOfferReady || optionIndex < 0 || optionIndex >= printingPodOffers.Length)
            {
                return false;
            }

            PrintingPodOffer offer = printingPodOffers[optionIndex];
            if (offer.Kind == PrintingPodOfferKind.Duplicant)
            {
                return workers.Count < MaxWorkers && TryFindPrintingPodSpawn(out _);
            }

            return offer.Kind != PrintingPodOfferKind.None;
        }

        private string PrintingPodReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.PrintingPod)
            {
                return "Printing Pod blocked: pod missing.";
            }

            if (printingPodOfferReady)
            {
                if (workers.Count >= MaxWorkers)
                {
                    return "Printing Pod ready: choose a care package; crew limit is reached.";
                }

                return TryFindPrintingPodSpawn(out _)
                    ? "Printing Pod ready: choose a printable offer."
                    : "Printing Pod ready: care packages available, but duplicant printing needs open pod space.";
            }

            if (CountActiveWorkers() == 0)
            {
                return "Printing Pod blocked: no active duplicants to stabilize the colony.";
            }

            return "Printing Pod charging: next offers arrive at full charge.";
        }

        private string BuildPrintingPodOfferText()
        {
            return "Printing Pod Ready\nChoose one printable care package. Unpicked offers are recycled when one is claimed.";
        }

        private string BuildPrintingPodOfferButtonText(int optionIndex)
        {
            EnsurePrintingPodOfferArray();
            if (optionIndex < 0 || optionIndex >= printingPodOffers.Length)
            {
                return "Offer";
            }

            PrintingPodOffer offer = printingPodOffers[optionIndex];
            switch (offer.Kind)
            {
                case PrintingPodOfferKind.Duplicant:
                    return "Print " + (string.IsNullOrEmpty(offer.WorkerName) ? "Duplicant" : offer.WorkerName) + "\n" + WorkerTraitShortName(offer.Trait) + " / " + JobCategoryShortName(offer.Interest);
                case PrintingPodOfferKind.Food:
                    return "Food\n+" + offer.Amount.ToString("0") + " kcal";
                case PrintingPodOfferKind.Water:
                    return "Water\n+" + offer.Amount.ToString("0") + " kg";
                case PrintingPodOfferKind.Algae:
                    return "Algae\n+" + offer.Amount.ToString("0") + " kg";
                case PrintingPodOfferKind.Metal:
                    return "Metal Ore\n+" + offer.Amount.ToString("0") + " kg";
                case PrintingPodOfferKind.Coal:
                    return "Coal\n+" + offer.Amount.ToString("0") + " kg";
                case PrintingPodOfferKind.RefinedMetal:
                    return "Refined Metal\n+" + offer.Amount.ToString("0") + " kg";
                case PrintingPodOfferKind.ResearchPoints:
                    return "Research\n+" + offer.Amount.ToString("0") + " RP";
                default:
                    return "Empty";
            }
        }

        private string CompactPrintingPodOfferList()
        {
            EnsurePrintingPodOfferArray();
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < printingPodOffers.Length; i++)
            {
                if (i > 0)
                {
                    builder.Append(" | ");
                }

                builder.Append(BuildPrintingPodOfferButtonText(i).Replace("\n", " "));
            }

            return builder.ToString();
        }

        private bool TryFindPrintingPodSpawn(out Vector2Int spawnCell)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.PrintingPod)
                    {
                        continue;
                    }

                    if (TryFindOpenSpawnNear(new Vector2Int(x, y), out spawnCell))
                    {
                        return true;
                    }
                }
            }

            spawnCell = Vector2Int.zero;
            return false;
        }

        private bool TryFindOpenSpawnNear(Vector2Int center, out Vector2Int spawnCell)
        {
            Vector2Int[] offsets =
            {
                new Vector2Int(0, 1),
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, -1),
                new Vector2Int(1, 1),
                new Vector2Int(-1, 1),
                new Vector2Int(1, -1),
                new Vector2Int(-1, -1),
                new Vector2Int(2, 0),
                new Vector2Int(-2, 0)
            };

            for (int i = 0; i < offsets.Length; i++)
            {
                Vector2Int candidate = center + offsets[i];
                if (IsCharacterStandableCell(candidate) && WorkerAt(candidate) == null)
                {
                    spawnCell = candidate;
                    return true;
                }
            }

            spawnCell = Vector2Int.zero;
            return false;
        }

        private bool TryFindCharacterStandableCellNear(Vector2Int center, int radius, Worker ignoreWorker, out Vector2Int standableCell)
        {
            for (int distance = 0; distance <= radius; distance++)
            {
                for (int dy = -distance; dy <= distance; dy++)
                {
                    int dxLimit = distance - Mathf.Abs(dy);
                    for (int dx = -dxLimit; dx <= dxLimit; dx++)
                    {
                        if (Mathf.Abs(dx) + Mathf.Abs(dy) != distance)
                        {
                            continue;
                        }

                        Vector2Int candidate = center + new Vector2Int(dx, dy);
                        Worker occupant = WorkerAt(candidate);
                        if (IsCharacterStandableCell(candidate) && (occupant == null || occupant == ignoreWorker))
                        {
                            standableCell = candidate;
                            return true;
                        }
                    }
                }
            }

            standableCell = Vector2Int.zero;
            return false;
        }

        private string NextDuplicantName()
        {
            string[] names =
            {
                "Duri",
                "Eun",
                "Haru",
                "Jin",
                "Kira",
                "Miro",
                "Nari",
                "Oren",
                "Pia",
                "Rin",
                "Sol",
                "Tae"
            };

            for (int i = 0; i < names.Length; i++)
            {
                if (FindWorkerByName(names[i]) == null)
                {
                    return names[i];
                }
            }

            return "Dup " + (workers.Count + duplicantsPrinted + 1);
        }

        private void SimulateNaturalVents(float deltaTime)
        {
            bool terrainChanged = false;
            bool gasChanged = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    CellKind kind = cells[x, y];
                    if (!IsNaturalVentKind(kind))
                    {
                        continue;
                    }

                    Vector2Int vent = new Vector2Int(x, y);
                    if (!NaturalVentActive(vent))
                    {
                        continue;
                    }

                    if (kind == CellKind.SteamVent)
                    {
                        terrainChanged |= RunSteamVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.WaterGeyser)
                    {
                        terrainChanged |= RunWaterGeyser(vent, deltaTime);
                    }
                    else if (kind == CellKind.CoolSteamVent)
                    {
                        gasChanged |= RunCoolSteamVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.LeakyOilFissure)
                    {
                        terrainChanged |= RunLeakyOilFissure(vent, deltaTime);
                    }
                    else if (kind == CellKind.SaltWaterGeyser)
                    {
                        terrainChanged |= RunSaltWaterGeyser(vent, deltaTime);
                    }
                    else if (kind == CellKind.CoolSlushGeyser)
                    {
                        terrainChanged |= RunCoolSlushGeyser(vent, deltaTime);
                    }
                    else if (kind == CellKind.PollutedWaterVent)
                    {
                        terrainChanged |= RunPollutedWaterVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.ChlorineGasVent)
                    {
                        gasChanged |= RunChlorineVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.CarbonDioxideVent)
                    {
                        gasChanged |= RunCarbonDioxideVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.PollutedOxygenVent)
                    {
                        gasChanged |= RunPollutedOxygenVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.HydrogenVent)
                    {
                        gasChanged |= RunHydrogenVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.NaturalGasVent)
                    {
                        gasChanged |= RunNaturalGasVent(vent, deltaTime);
                    }
                    else if (kind == CellKind.MetalVolcano)
                    {
                        terrainChanged |= RunMetalVolcano(vent, deltaTime);
                    }
                    else if (kind == CellKind.MagmaVolcano)
                    {
                        terrainChanged |= RunMagmaVolcano(vent, deltaTime);
                    }
                }
            }

            if (terrainChanged)
            {
                terrainDirty = true;
                overlayDirty = true;
            }

            if (gasChanged)
            {
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private bool RunSteamVent(Vector2Int vent, float deltaTime)
        {
            Vector2Int output;
            if (!TryFindNaturalVentLiquidOutput(vent, out output))
            {
                AddHeat(vent, 0.12f * deltaTime, 2);
                return false;
            }

            float amount = Mathf.Min(SteamVentWaterRate * NaturalVentOutputMultiplier(vent) * deltaTime, 140f - waterMass[output.x, output.y]);
            if (amount <= 0.001f)
            {
                AddHeat(vent, 0.12f * deltaTime, 2);
                return false;
            }

            ReleaseWaterToCell(output, amount);
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], 72f), -30f, 120f);
            AddHeat(vent, 0.36f * deltaTime, 2);
            renewableWaterGenerated += amount;
            steamVentWaterGenerated += amount;
            return true;
        }

