        private bool RunMetalVolcano(Vector2Int vent, float deltaTime)
        {
            Vector2Int output;
            if (!TryFindLooseResourceDropCell(vent, LooseResourceKind.RefinedMetal, out output))
            {
                AddHeat(vent, MetalVolcanoHeatRate * 0.35f * deltaTime, 2);
                return false;
            }

            float outputCapacity = looseResourceKind[output.x, output.y] == LooseResourceKind.None
                ? 80f
                : 80f - looseResourceAmount[output.x, output.y];
            float amount = Mathf.Min(
                MetalVolcanoRefinedMetalRate * NaturalVentOutputMultiplier(vent) * deltaTime,
                Mathf.Max(0f, outputCapacity));
            if (amount <= 0.001f)
            {
                AddHeat(vent, MetalVolcanoHeatRate * 0.35f * deltaTime, 2);
                return false;
            }

            looseResourceKind[output.x, output.y] = LooseResourceKind.RefinedMetal;
            looseResourceAmount[output.x, output.y] = Mathf.Min(80f, looseResourceAmount[output.x, output.y] + amount);
            hatchEggAge[output.x, output.y] = 0f;
            temperature[output.x, output.y] = Mathf.Clamp(
                Mathf.Max(temperature[output.x, output.y], MetalVolcanoOutputTemperature),
                -30f,
                120f);
            AddHeat(vent, MetalVolcanoHeatRate * deltaTime, 2);
            volcanicRefinedMetalGenerated += amount;
            return true;
        }

        private bool RunMagmaVolcano(Vector2Int vent, float deltaTime)
        {
            Vector2Int output;
            if (!TryFindMagmaVolcanoOutput(vent, out output))
            {
                AddHeat(vent, MagmaHeatRate * 0.45f * deltaTime, 2);
                return false;
            }

            float amount = MagmaVolcanoMagmaRate * NaturalVentOutputMultiplier(vent) * deltaTime;
            if (amount <= 0.001f)
            {
                AddHeat(vent, MagmaHeatRate * 0.45f * deltaTime, 2);
                return false;
            }

            if (cells[output.x, output.y] != CellKind.Magma)
            {
                cells[output.x, output.y] = CellKind.Magma;
                waterMass[output.x, output.y] = 0f;
                oxygen[output.x, output.y] = 0f;
                carbonDioxide[output.x, output.y] = 0f;
                pollutedOxygen[output.x, output.y] = 0f;
                hydrogen[output.x, output.y] = 0f;
                steam[output.x, output.y] = 0f;
                chlorine[output.x, output.y] = 0f;
                naturalGas[output.x, output.y] = 0f;
                sourGas[output.x, output.y] = 0f;
                germs[output.x, output.y] = 0f;
                looseResourceKind[output.x, output.y] = LooseResourceKind.None;
                looseResourceAmount[output.x, output.y] = 0f;
                equipmentCondition[output.x, output.y] = 0f;
                constructionMaterialGrade[output.x, output.y] = ConstructionMaterialGrade.Basic;
            }

            temperature[output.x, output.y] = MagmaTemperature;
            AddHeat(vent, MagmaHeatRate * deltaTime, 2);
            magmaVolcanoMagmaGenerated += amount;
            return true;
        }

        private bool NaturalVentActive(Vector2Int vent)
        {
            return NaturalVentPhase(vent) < NaturalVentActiveDuration(vent);
        }

        private float NaturalVentOutputMultiplier(Vector2Int vent)
        {
            return IsNaturalVentAnalyzed(vent) ? VentAnalysisOutputBonus : 1f;
        }

        private bool HasCompletedVentAnalysis()
        {
            return CountAnalyzedNaturalVents() > 0;
        }

        private void RunVentAnalyzer(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f ||
                !techAutomationLogistics ||
                !CanPoweredMachineRun(center) ||
                !TryFindNaturalVentForAnalysis(center, VentAnalyzerRange, out Vector2Int targetVent))
            {
                return;
            }

            float requestedPower = VentAnalyzerPowerRate * deltaTime;
            float powerUsed = Mathf.Min(power, requestedPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, requestedPower);
            if (efficiency <= 0.001f)
            {
                return;
            }

            ConsumeCyclePower(powerUsed);
            float before = NaturalVentAnalysisProgress(targetVent);
            naturalVentAnalysisProgress[targetVent.x, targetVent.y] = Mathf.Min(VentAnalysisRequiredSeconds, before + deltaTime * efficiency);
            RefreshNaturalVentAnalysisSummary();
            AddHeat(center, VentAnalyzerHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00018f * deltaTime * efficiency);
            overlayDirty = true;
            if (before < VentAnalysisRequiredSeconds && IsNaturalVentAnalyzed(targetVent))
            {
                Log("Natural vent analysis complete. Output forecast and tuning bonus active.");
            }
        }

        private bool CanVentAnalyzerRun(Vector2Int center)
        {
            return techAutomationLogistics &&
                CanPoweredMachineRun(center) &&
                TryFindNaturalVentForAnalysis(center, VentAnalyzerRange, out _);
        }

        private bool HasVentAnalyzerAnalysisTarget(Vector2Int center)
        {
            return IsInside(center.x, center.y) &&
                cells[center.x, center.y] == CellKind.VentAnalyzer &&
                TryFindNaturalVentForAnalysis(center, VentAnalyzerRange, out _);
        }

        private int CountVentAnalyzersWithAnalysisTargets()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (HasVentAnalyzerAnalysisTarget(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string VentAnalyzerReadinessText(Vector2Int cell)
        {
            if (!techAutomationLogistics)
            {
                return "Analysis blocked: research Automation Logistics.";
            }

            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.VentAnalyzer)
            {
                return "Analysis blocked: Vent Analyzer missing.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Analysis blocked: Vent Analyzer needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Analysis blocked: Vent Analyzer is submerged.";
            }

            if (!HasVentAnalyzerAnalysisTarget(cell))
            {
                return AllNaturalVentsAnalyzed()
                    ? "Analysis complete: all discovered natural vents are analyzed."
                    : "Analysis blocked: move within range of an unanalyzed natural vent.";
            }

            if (!HasWireAccess(cell))
            {
                return "Analysis blocked: needs adjacent or under-floor power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Analysis blocked: power circuit has no stored power.";
            }

            UpdateAutomationWires();
            if (!MachineAutomationAllows(cell))
            {
                return "Analysis blocked: automation signal is red.";
            }

            return "Analysis ready: studying nearby natural vent cycles.";
        }

        private bool TryFindNaturalVentForAnalysis(Vector2Int center, int range, out Vector2Int vent)
        {
            vent = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;
            for (int y = Mathf.Max(0, center.y - range); y <= Mathf.Min(WorldHeight - 1, center.y + range); y++)
            {
                for (int x = Mathf.Max(0, center.x - range); x <= Mathf.Min(WorldWidth - 1, center.x + range); x++)
                {
                    int distance = Mathf.Abs(x - center.x) + Mathf.Abs(y - center.y);
                    if (distance > range ||
                        distance >= bestDistance ||
                        !IsNaturalVentKind(cells[x, y]) ||
                        IsNaturalVentAnalyzed(new Vector2Int(x, y)))
                    {
                        continue;
                    }

                    bestDistance = distance;
                    vent = new Vector2Int(x, y);
                }
            }

            return vent.x >= 0;
        }

        private bool TryFindNaturalVentInRange(Vector2Int center, int range, out Vector2Int vent)
        {
            vent = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;
            for (int y = Mathf.Max(0, center.y - range); y <= Mathf.Min(WorldHeight - 1, center.y + range); y++)
            {
                for (int x = Mathf.Max(0, center.x - range); x <= Mathf.Min(WorldWidth - 1, center.x + range); x++)
                {
                    int distance = Mathf.Abs(x - center.x) + Mathf.Abs(y - center.y);
                    if (distance > range || distance >= bestDistance || !IsNaturalVentKind(cells[x, y]))
                    {
                        continue;
                    }

                    bestDistance = distance;
                    vent = new Vector2Int(x, y);
                }
            }

            return vent.x >= 0;
        }

        private bool IsNaturalVentKind(CellKind kind)
        {
            return kind == CellKind.SteamVent ||
                kind == CellKind.WaterGeyser ||
                kind == CellKind.CoolSteamVent ||
                kind == CellKind.LeakyOilFissure ||
                kind == CellKind.SaltWaterGeyser ||
                kind == CellKind.CoolSlushGeyser ||
                kind == CellKind.PollutedWaterVent ||
                kind == CellKind.ChlorineGasVent ||
                kind == CellKind.CarbonDioxideVent ||
                kind == CellKind.PollutedOxygenVent ||
                kind == CellKind.HydrogenVent ||
                kind == CellKind.NaturalGasVent ||
                kind == CellKind.MetalVolcano ||
                kind == CellKind.MagmaVolcano;
        }

        private string NaturalVentStateText(Vector2Int vent)
        {
            float phase = NaturalVentPhase(vent);
            float activeSeconds = NaturalVentActiveDuration(vent);
            float cycleSeconds = NaturalVentCycleLength(vent);
            if (phase < activeSeconds)
            {
                return "Active for " + (activeSeconds - phase).ToString("0") + "s.";
            }

            return "Dormant for " + (cycleSeconds - phase).ToString("0") + "s.";
        }

        private string NaturalVentAnalysisText(Vector2Int vent)
        {
            float progress = NaturalVentAnalysisProgress(vent);
            return IsNaturalVentAnalyzed(vent)
                ? "Analysis complete: output forecast and +" + Mathf.RoundToInt((VentAnalysisOutputBonus - 1f) * 100f) + "% tuning bonus active."
                : "Analysis " + progress.ToString("0") + "/" + VentAnalysisRequiredSeconds.ToString("0") + "s. Build a powered Vent Analyzer nearby.";
        }

        private string NaturalVentForecastText(Vector2Int vent)
        {
            if (!IsNaturalVentAnalyzed(vent))
            {
                return "Cycle forecast locked until this natural vent is analyzed.";
            }

            float activeSeconds = NaturalVentActiveDuration(vent);
            float dormantSeconds = NaturalVentCycleLength(vent) - activeSeconds;
            float averageRate = NaturalVentAverageOutputRate(vent);
            return "Forecast: active " + activeSeconds.ToString("0") + "s, dormant " + dormantSeconds.ToString("0") + "s, average " + averageRate.ToString("0.000") + " kg/s.";
        }

        private float NaturalVentPhase(Vector2Int vent)
        {
            float offset = Mathf.Abs(vent.x * 13.37f + vent.y * 3.19f);
            return Mathf.Repeat(elapsedTime + offset, NaturalVentCycleLength(vent));
        }

        private float NaturalVentCycleLength(Vector2Int vent)
        {
            float variance = Mathf.Repeat(Mathf.Abs(vent.x * 5.1f + vent.y * 2.7f), 42f);
            return NaturalVentCycleSeconds + variance;
        }

        private float NaturalVentActiveDuration(Vector2Int vent)
        {
            CellKind kind = IsInside(vent.x, vent.y) ? cells[vent.x, vent.y] : CellKind.Empty;
            float fraction = kind == CellKind.HydrogenVent ? 0.58f : kind == CellKind.NaturalGasVent ? 0.50f : kind == CellKind.MetalVolcano ? 0.42f : kind == CellKind.MagmaVolcano ? 0.38f : kind == CellKind.SaltWaterGeyser ? 0.56f : kind == CellKind.WaterGeyser ? 0.55f : kind == CellKind.CoolSlushGeyser ? 0.52f : kind == CellKind.PollutedWaterVent ? 0.53f : kind == CellKind.ChlorineGasVent ? 0.48f : kind == CellKind.CarbonDioxideVent ? 0.53f : kind == CellKind.PollutedOxygenVent ? 0.55f : kind == CellKind.CoolSteamVent ? 0.50f : kind == CellKind.LeakyOilFissure ? 0.47f : 0.54f;
            fraction += Mathf.Repeat(Mathf.Abs(vent.x * 0.017f + vent.y * 0.029f), 0.16f) - 0.08f;
            float cycleSeconds = NaturalVentCycleLength(vent);
            return Mathf.Clamp(cycleSeconds * fraction, 24f, cycleSeconds - 18f);
        }

        private float NaturalVentBaseOutputRate(CellKind kind)
        {
            if (kind == CellKind.SteamVent)
            {
                return SteamVentWaterRate;
            }

            if (kind == CellKind.WaterGeyser)
            {
                return WaterGeyserWaterRate;
            }

            if (kind == CellKind.CoolSteamVent)
            {
                return CoolSteamVentSteamRate;
            }

            if (kind == CellKind.LeakyOilFissure)
            {
                return LeakyOilFissureCrudeRate;
            }

            if (kind == CellKind.SaltWaterGeyser)
            {
                return SaltWaterGeyserSaltWaterRate;
            }

            if (kind == CellKind.CoolSlushGeyser)
            {
                return CoolSlushGeyserPollutedWaterRate;
            }

            if (kind == CellKind.PollutedWaterVent)
            {
                return PollutedWaterVentPollutedWaterRate;
            }

            if (kind == CellKind.ChlorineGasVent)
            {
                return ChlorineVentRate;
            }

            if (kind == CellKind.CarbonDioxideVent)
            {
                return CarbonDioxideVentRate;
            }

            if (kind == CellKind.PollutedOxygenVent)
            {
                return PollutedOxygenVentRate;
            }

            if (kind == CellKind.HydrogenVent)
            {
                return HydrogenVentRate;
            }

            if (kind == CellKind.NaturalGasVent)
            {
                return NaturalGasVentRate;
            }

            if (kind == CellKind.MetalVolcano)
            {
                return MetalVolcanoRefinedMetalRate;
            }

            return kind == CellKind.MagmaVolcano ? MagmaVolcanoMagmaRate : 0f;
        }

        private float NaturalVentAverageOutputRate(Vector2Int vent)
        {
            if (!IsInside(vent.x, vent.y) || !IsNaturalVentKind(cells[vent.x, vent.y]))
            {
                return 0f;
            }

            return NaturalVentBaseOutputRate(cells[vent.x, vent.y]) *
                NaturalVentOutputMultiplier(vent) *
                NaturalVentActiveDuration(vent) /
                Mathf.Max(0.001f, NaturalVentCycleLength(vent));
        }

        private float NaturalVentAnalysisProgress(Vector2Int vent)
        {
            return IsInside(vent.x, vent.y) && IsNaturalVentKind(cells[vent.x, vent.y])
                ? Mathf.Clamp(naturalVentAnalysisProgress[vent.x, vent.y], 0f, VentAnalysisRequiredSeconds)
                : 0f;
        }

        private bool IsNaturalVentAnalyzed(Vector2Int vent)
        {
            return NaturalVentAnalysisProgress(vent) >= VentAnalysisRequiredSeconds;
        }

        private int CountAnalyzedNaturalVents()
        {
