        private void RefreshNaturalVentAnalysisSummary()
        {
            float maxProgress = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsNaturalVentKind(cells[x, y]))
                    {
                        maxProgress = Mathf.Max(maxProgress, NaturalVentAnalysisProgress(new Vector2Int(x, y)));
                    }
                }
            }

            naturalVentAnalysisSeconds = maxProgress;
        }

        private void MigrateNaturalVentAnalysisProgress(int version)
        {
            if (version < 266 && naturalVentAnalysisSeconds > 0f)
            {
                float legacyProgress = Mathf.Clamp(naturalVentAnalysisSeconds, 0f, VentAnalysisRequiredSeconds);
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        if (IsNaturalVentKind(cells[x, y]))
                        {
                            naturalVentAnalysisProgress[x, y] = legacyProgress;
                        }
                    }
                }
            }

            RefreshNaturalVentAnalysisSummary();
        }

        private void SimulateHatches(float deltaTime)
        {
            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                if (hatch.Transform == null)
                {
                    continue;
                }

                RoomInfo stableRoom = RoomAt(hatch.Cell.x, hatch.Cell.y);
                bool inStable = stableRoom != null && stableRoom.Kind == RoomKind.Stable;
                bool overcrowded = IsStableOvercrowded(stableRoom);
                hatch.GroomedSeconds = Mathf.Max(0f, hatch.GroomedSeconds - deltaTime * (overcrowded ? StableOvercrowdedGroomingDrainMultiplier : 1f));
                float targetHappiness = CritterTargetHappiness(hatch, inStable, overcrowded);
                hatch.Happiness = Mathf.MoveTowards(hatch.Happiness, targetHappiness, (hatch.GroomedSeconds > 0f ? 4.2f : 1.8f) * deltaTime);

                Vector3 targetPosition = CellCenter(hatch.TargetCell);
                hatch.Transform.position = Vector3.MoveTowards(hatch.Transform.position, targetPosition, HatchMoveSpeed * deltaTime);
                if ((hatch.Transform.position - targetPosition).sqrMagnitude <= 0.0025f)
                {
                    hatch.Transform.position = targetPosition;
                    hatch.Cell = hatch.TargetCell;
                    hatch.MoveTimer -= deltaTime;
                    if (hatch.MoveTimer <= 0f)
                    {
                        hatch.TargetCell = ChooseHatchMoveTarget(hatch);
                        hatch.MoveTimer = HatchMoveIntervalSeconds + Mathf.Repeat(hatch.Cell.x * 0.37f + hatch.Cell.y * 0.19f + elapsedTime, 1.1f);
                    }
                }

                hatch.EatTimer -= deltaTime;
                if (hatch.EatTimer <= 0f)
                {
                    hatch.EatTimer = HatchEatIntervalSeconds;
                    TryFeedHatch(hatch);
                }

                UpdateHatchReproduction(hatch, deltaTime);

                if (IsShineBugGlowing(hatch))
                {
                    shineBugGlowSeconds += deltaTime;
                    if (currentOverlayMode == OverlayMode.Decor || currentOverlayMode == OverlayMode.Power)
                    {
                        overlayDirty = true;
                    }
                }

                if (hatch.Renderer != null)
                {
                    float groomed = Mathf.Clamp01(hatch.GroomedSeconds / HatchGroomedSeconds);
                    hatch.Renderer.color = Color.Lerp(CritterRestingColor(hatch.Kind), CritterGroomedColor(hatch.Kind), groomed);
                }
            }
        }

        private float CritterTargetHappiness(HatchCritter hatch, bool inStable, bool overcrowded)
        {
            float target = hatch.GroomedSeconds > 0f
                ? (inStable ? 92f : 86f)
                : (inStable ? 44f : 34f);

            float habitatComfort = CritterHabitatComfort(hatch);
            target = Mathf.Lerp(CritterPoorHabitatHappiness, target, habitatComfort);
            return StableOvercrowdedHappinessTarget(target, overcrowded);
        }

        private float CritterHabitatComfort(HatchCritter hatch)
        {
            if (hatch == null || !IsInside(hatch.Cell.x, hatch.Cell.y))
            {
                return 0f;
            }

            switch (hatch.Kind)
            {
                case CritterKind.Hatch:
                    return HatchHabitatComfort(hatch);
                case CritterKind.Slickster:
                    return SlicksterHabitatComfort(hatch.Cell);
                case CritterKind.MoltenSlickster:
                    return MoltenSlicksterHabitatComfort(hatch.Cell);
                case CritterKind.Drecko:
                    return DreckoHabitatComfort(hatch);
                case CritterKind.Puft:
                    return Mathf.Clamp01(PollutedOxygenAround(hatch.Cell, PuftPollutedOxygenSearchRange) / Mathf.Max(0.001f, PuftPollutedOxygenMeal * 2f));
                case CritterKind.Morb:
                    return MorbHabitatComfort(hatch.Cell);
                case CritterKind.Pacu:
                    return PacuHabitatComfort(hatch.Cell);
                case CritterKind.ShineBug:
                    return ShineBugHabitatComfort(hatch.Cell);
                case CritterKind.Pip:
                    return PipHabitatComfort(hatch.Cell);
                case CritterKind.PlugSlug:
                    return PlugSlugHabitatComfort(hatch.Cell);
                case CritterKind.GassyMoo:
                    return GassyMooHabitatComfort(hatch.Cell);
                case CritterKind.Beeta:
                    return BeetaHabitatComfort(hatch.Cell);
                case CritterKind.Grubgrub:
                    return GrubgrubHabitatComfort(hatch.Cell);
                case CritterKind.Sweetle:
                    return SweetleHabitatComfort(hatch.Cell);
                case CritterKind.CuddlePip:
                    return CuddlePipHabitatComfort(hatch.Cell);
                case CritterKind.ShoveVole:
                    return ShoveVoleHabitatComfort(hatch.Cell);
                default:
                    return 1f;
            }
        }

        private float HatchHabitatComfort(HatchCritter hatch)
        {
            if (TryFindHatchFoodCell(hatch, out _))
            {
                return 1f;
            }

            return TryFindHatchFeeder(hatch, out _) ? 0.92f : 0.28f;
        }

        private float SlicksterHabitatComfort(Vector2Int cell)
        {
            float temperatureComfort = SlicksterTemperatureComfort(cell);
            float carbonComfort = Mathf.Clamp01(CarbonDioxideAround(cell, SlicksterCarbonSearchRange) / Mathf.Max(0.001f, SlicksterCarbonDioxideMeal * 2f));
            return Mathf.Clamp01(temperatureComfort * 0.65f + carbonComfort * 0.35f);
        }

        private float MoltenSlicksterHabitatComfort(Vector2Int cell)
        {
            float temperatureComfort = MoltenSlicksterTemperatureComfort(cell);
            float carbonComfort = Mathf.Clamp01(HotCarbonDioxideAround(cell, SlicksterCarbonSearchRange) / Mathf.Max(0.001f, SlicksterCarbonDioxideMeal * 2f));
            return Mathf.Clamp01(temperatureComfort * 0.68f + carbonComfort * 0.32f);
        }

        private float DreckoHabitatComfort(HatchCritter drecko)
        {
            float feedComfort = TryFindDreckoGrazingTarget(drecko, out _) ? 1f : 0.20f;
            if (algae > 0.05f && TryFindHatchFeeder(drecko, out _))
            {
                feedComfort = Mathf.Max(feedComfort, 0.86f);
            }

            float hydrogenComfort = Mathf.Clamp01(HydrogenAround(drecko.Cell, 3) / Mathf.Max(0.001f, DreckoHydrogenThreshold));
            return Mathf.Clamp01(feedComfort * 0.72f + hydrogenComfort * 0.28f);
        }

        private float MorbHabitatComfort(Vector2Int cell)
        {
            float pressureComfort = Mathf.Clamp01((GasVentMaxPressure - TileGasTotal(cell.x, cell.y)) / Mathf.Max(0.001f, GasVentMaxPressure));
            float sourceComfort = Mathf.Clamp01(PollutionSourceCellsAround(cell, MorbPollutionSearchRange) / 3f);
            return Mathf.Clamp01(0.25f + pressureComfort * 0.30f + sourceComfort * 0.45f);
        }

        private float PacuHabitatComfort(Vector2Int cell)
        {
            if (!IsPacuSwimCell(cell))
            {
                return 0f;
            }

            float waterComfort = Mathf.Clamp01(waterMass[cell.x, cell.y] / Mathf.Max(0.001f, PacuMinimumWaterMass * 2f));
            float temperatureComfort = temperature[cell.x, cell.y] < PacuMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(PacuMoveTemperatureMin - 8f, PacuMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > PacuMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(PacuMoveTemperatureMax, PacuMoveTemperatureMax + 16f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(waterComfort * 0.70f + temperatureComfort * 0.30f);
        }

        private float ShineBugHabitatComfort(Vector2Int cell)
        {
            float airComfort = Mathf.Clamp01((oxygen[cell.x, cell.y] + hydrogen[cell.x, cell.y]) / 0.30f);
            float usefulLightTarget = Mathf.Clamp01(ShineBugGlowTargetScore(cell) / 1.8f);
            return Mathf.Clamp01(airComfort * 0.70f + usefulLightTarget * 0.30f);
        }

        private float PipHabitatComfort(Vector2Int cell)
        {
            float arborComfort = Mathf.Clamp01(ArborTreesAround(cell, PipArborSearchRange) / 2f);
            float forestComfort = Mathf.Clamp01(ForestPocketCellsAround(cell, 5) / 8f);
            float temperatureComfort = temperature[cell.x, cell.y] < PipMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(PipMoveTemperatureMin - 8f, PipMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > PipMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(PipMoveTemperatureMax, PipMoveTemperatureMax + 14f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(arborComfort * 0.55f + forestComfort * 0.20f + temperatureComfort * 0.25f);
        }

        private float PlugSlugHabitatComfort(Vector2Int cell)
        {
            float metalComfort = Mathf.Clamp01((metal + refinedMetal) / 8f);
            float oreComfort = Mathf.Clamp01(MetalOreCellsAround(cell, PlugSlugMetalSearchRange) / 3f);
            float batteryComfort = Mathf.Clamp01((maxPower <= 0.001f ? 0f : power / maxPower) * 0.50f + CountPowerStorageCellsAround(cell, 5) / 2f);
            float temperatureComfort = temperature[cell.x, cell.y] < PlugSlugMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(PlugSlugMoveTemperatureMin - 8f, PlugSlugMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > PlugSlugMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(PlugSlugMoveTemperatureMax, PlugSlugMoveTemperatureMax + 16f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(Mathf.Max(metalComfort, oreComfort) * 0.52f + batteryComfort * 0.20f + temperatureComfort * 0.28f);
        }

        private float GassyMooHabitatComfort(Vector2Int cell)
        {
            float bristleComfort = Mathf.Clamp01(BristleBlossomsAround(cell, GassyMooBristleSearchRange) / 2f);
            float gasSpaceComfort = Mathf.Clamp01((GasVentMaxPressure - TileGasTotal(cell.x, cell.y)) / Mathf.Max(0.001f, GasVentMaxPressure));
            float temperatureComfort = temperature[cell.x, cell.y] < GassyMooMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(GassyMooMoveTemperatureMin - 8f, GassyMooMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > GassyMooMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(GassyMooMoveTemperatureMax, GassyMooMoveTemperatureMax + 16f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(bristleComfort * 0.58f + gasSpaceComfort * 0.17f + temperatureComfort * 0.25f);
        }

        private float BeetaHabitatComfort(Vector2Int cell)
        {
            float radiationComfort = Mathf.Clamp01(BeetaRadiationSourceScore(cell) / Mathf.Max(0.001f, BeetaRadiationMinimum * 3f));
            float temperatureComfort = temperature[cell.x, cell.y] < BeetaMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(BeetaMoveTemperatureMin - 8f, BeetaMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > BeetaMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(BeetaMoveTemperatureMax, BeetaMoveTemperatureMax + 18f, temperature[cell.x, cell.y]))
                    : 1f;
            float gasComfort = Mathf.Clamp01(TileGasTotal(cell.x, cell.y) / 0.18f);
            return Mathf.Clamp01(radiationComfort * 0.62f + temperatureComfort * 0.24f + gasComfort * 0.14f);
        }

        private float GrubgrubHabitatComfort(Vector2Int cell)
        {
            float cropComfort = Mathf.Clamp01(CropCellsAround(cell, GrubgrubCropSearchRange) / 3f);
            float tendComfort = Mathf.Clamp01(TendableCropCellsAround(cell, GrubgrubCropSearchRange) / 2f);
            float temperatureComfort = temperature[cell.x, cell.y] < GrubgrubMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(GrubgrubMoveTemperatureMin - 8f, GrubgrubMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > GrubgrubMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(GrubgrubMoveTemperatureMax, GrubgrubMoveTemperatureMax + 16f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(cropComfort * 0.46f + tendComfort * 0.29f + temperatureComfort * 0.25f);
        }

        private float SweetleHabitatComfort(Vector2Int cell)
        {
            float sulfurComfort = Mathf.Clamp01(SulfurAround(cell, SweetleSulfurSearchRange) / Mathf.Max(0.001f, SweetleSulfurMeal * 3f));
            float cropComfort = Mathf.Clamp01(CropCellsAround(cell, GrubgrubCropSearchRange) / 3f);
            float temperatureComfort = temperature[cell.x, cell.y] < SweetleMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(SweetleMoveTemperatureMin - 8f, SweetleMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > SweetleMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(SweetleMoveTemperatureMax, SweetleMoveTemperatureMax + 16f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(sulfurComfort * 0.48f + cropComfort * 0.27f + temperatureComfort * 0.25f);
        }

        private float CuddlePipHabitatComfort(Vector2Int cell)
        {
            float eggComfort = Mathf.Clamp01(EggTargetsAround(cell, CuddlePipEggSearchRange) / 2f);
            float forestComfort = Mathf.Clamp01((ArborTreesAround(cell, PipArborSearchRange) + ForestPocketCellsAround(cell, 5) * 0.20f) / 2f);
            float temperatureComfort = temperature[cell.x, cell.y] < CuddlePipMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(CuddlePipMoveTemperatureMin - 8f, CuddlePipMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > CuddlePipMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(CuddlePipMoveTemperatureMax, CuddlePipMoveTemperatureMax + 14f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(eggComfort * 0.50f + forestComfort * 0.25f + temperatureComfort * 0.25f);
        }

        private float ShoveVoleHabitatComfort(Vector2Int cell)
        {
            float regolithComfort = Mathf.Clamp01(RegolithCellsAround(cell, ShoveVoleRegolithSearchRange) / 4f);
            float surfaceComfort = Mathf.Clamp01(Mathf.InverseLerp(WorldHeight - 18, WorldHeight - 4, cell.y));
            float temperatureComfort = temperature[cell.x, cell.y] < ShoveVoleMoveTemperatureMin
                ? Mathf.Clamp01(Mathf.InverseLerp(ShoveVoleMoveTemperatureMin - 20f, ShoveVoleMoveTemperatureMin, temperature[cell.x, cell.y]))
                : temperature[cell.x, cell.y] > ShoveVoleMoveTemperatureMax
                    ? Mathf.Clamp01(1f - Mathf.InverseLerp(ShoveVoleMoveTemperatureMax, ShoveVoleMoveTemperatureMax + 22f, temperature[cell.x, cell.y]))
                    : 1f;
            return Mathf.Clamp01(regolithComfort * 0.62f + surfaceComfort * 0.14f + temperatureComfort * 0.24f);
        }

        private float StableOvercrowdedHappinessTarget(float target, bool overcrowded)
        {
            return overcrowded ? Mathf.Max(8f, target - StableOvercrowdedHappinessPenalty) : target;
        }

        private float SlicksterTemperatureComfort(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            float temp = temperature[cell.x, cell.y];
            if (temp < SlicksterPreferredTemperatureMin)
            {
                return Mathf.Clamp01(Mathf.InverseLerp(SlicksterMoveTemperatureMin, SlicksterPreferredTemperatureMin, temp));
            }

            if (temp > SlicksterPreferredTemperatureMax)
            {
                return Mathf.Clamp01(1f - Mathf.InverseLerp(SlicksterPreferredTemperatureMax, SlicksterMoveTemperatureMax, temp) * 0.75f);
            }

            return 1f;
        }

        private float MoltenSlicksterTemperatureComfort(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            float temp = temperature[cell.x, cell.y];
            if (temp < MoltenSlicksterPreferredTemperatureMin)
            {
                return Mathf.Clamp01(Mathf.InverseLerp(MoltenSlicksterMoveTemperatureMin, MoltenSlicksterPreferredTemperatureMin, temp));
            }

            if (temp > MoltenSlicksterPreferredTemperatureMax)
            {
                return Mathf.Clamp01(1f - Mathf.InverseLerp(MoltenSlicksterPreferredTemperatureMax, MoltenSlicksterMoveTemperatureMax, temp) * 0.80f);
            }

            return 1f;
        }

        private void UpdateHatchReproduction(HatchCritter hatch, float deltaTime)
        {
            if (hatch.Kind == CritterKind.Hatch)
            {
                UpdateHatchEggReproduction(hatch, deltaTime);
                return;
            }

            UpdateCritterBirthReproduction(hatch, deltaTime);
        }

        private void UpdateHatchEggReproduction(HatchCritter hatch, float deltaTime)
        {
            if (hatch.Happiness < HatchEggMinimumHappiness)
            {
                hatch.Reproduction = Mathf.Max(0f, hatch.Reproduction - 0.018f * deltaTime);
                return;
            }

            if (IsStableOvercrowded(hatch.Cell))
            {
                hatch.Reproduction = Mathf.Max(0f, hatch.Reproduction - 0.012f * deltaTime);
                return;
            }

            float happinessScale = Mathf.InverseLerp(HatchEggMinimumHappiness, 100f, hatch.Happiness);
            float stableScale = RoomKindAt(hatch.Cell.x, hatch.Cell.y) == RoomKind.Stable ? 1.35f : 1f;
            float groomScale = hatch.GroomedSeconds > 0f ? 1.25f : 0.75f;
            hatch.Reproduction += deltaTime * happinessScale * stableScale * groomScale / HatchEggLaySeconds;
            if (hatch.Reproduction < 1f)
            {
                return;
            }

            if (TryLayHatchEgg(hatch.Cell))
            {
                hatch.Reproduction = Mathf.Repeat(hatch.Reproduction, 1f);
                hatchEggsLaid++;
                Log("A happy hatch laid an egg.");
            }
            else
            {
                hatch.Reproduction = 0.98f;
            }
        }

        private void UpdateCritterBirthReproduction(HatchCritter hatch, float deltaTime)
        {
            if (hatch.Happiness < CritterBirthMinimumHappiness)
            {
                hatch.Reproduction = Mathf.Max(0f, hatch.Reproduction - 0.014f * deltaTime);
                return;
            }

            if (IsStableOvercrowded(hatch.Cell))
            {
                hatch.Reproduction = Mathf.Max(0f, hatch.Reproduction - 0.010f * deltaTime);
                return;
            }

            if (hatches.Count >= MaxWildHatches)
            {
                hatch.Reproduction = Mathf.Min(hatch.Reproduction, 0.98f);
                return;
            }

            float happinessScale = Mathf.InverseLerp(CritterBirthMinimumHappiness, 100f, hatch.Happiness);
            float stableScale = RoomKindAt(hatch.Cell.x, hatch.Cell.y) == RoomKind.Stable ? 1.35f : 0.65f;
            float groomScale = hatch.GroomedSeconds > 0f ? 1.25f : 0.75f;
            float habitatScale = Mathf.Lerp(0.55f, 1.20f, CritterHabitatComfort(hatch));
            hatch.Reproduction += deltaTime * happinessScale * stableScale * groomScale * habitatScale * CritterBirthSpeedMultiplier(hatch.Kind) / CritterBirthSeconds;
            if (hatch.Reproduction < 1f)
            {
                return;
            }

            if (TrySpawnCritterOffspring(hatch))
            {
                hatch.Reproduction = Mathf.Repeat(hatch.Reproduction, 1f);
                Log("A happy " + CritterKindName(hatch.Kind) + " had offspring.");
            }
            else
            {
                hatch.Reproduction = 0.98f;
            }
        }

        private float CritterBirthSpeedMultiplier(CritterKind kind)
        {
            switch (kind)
            {
                case CritterKind.Morb:
                    return 0.75f;
                case CritterKind.Pacu:
                    return 0.90f;
                case CritterKind.ShineBug:
                    return 1.15f;
                case CritterKind.ShoveVole:
                    return 0.82f;
                case CritterKind.MoltenSlickster:
                    return 0.82f;
                case CritterKind.Sweetle:
                    return 1.08f;
                default:
                    return 1f;
            }
        }

        private bool TrySpawnCritterOffspring(HatchCritter parent)
        {
            if (parent == null || hatches.Count >= MaxWildHatches || !TryFindCritterBirthCell(parent, out Vector2Int spawnCell))
            {
                return false;
            }

            float childHappiness = Mathf.Clamp(parent.Happiness * 0.55f, 36f, 58f);
            float childGroomedSeconds = Mathf.Max(0f, parent.GroomedSeconds * 0.25f);
            string childName = "Baby " + CritterKindName(parent.Kind) + " " + (CountCritters(parent.Kind) + 1);
            SpawnCritter(parent.Kind, childName, spawnCell, childHappiness, childGroomedSeconds, HatchMoveIntervalSeconds, HatchEatIntervalSeconds, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f);
            terrainDirty = true;
            overlayDirty = true;
            return true;
        }

        private bool TryFindCritterBirthCell(HatchCritter parent, out Vector2Int birthCell)
        {
            birthCell = new Vector2Int(-1, -1);
            RoomInfo parentRoom = RoomAt(parent.Cell.x, parent.Cell.y);
            bool keepInsideRoom = parentRoom != null && parentRoom.Enclosed;

            for (int radius = 0; radius <= 2; radius++)
            {
                for (int y = parent.Cell.y - radius; y <= parent.Cell.y + radius; y++)
                {
                    for (int x = parent.Cell.x - radius; x <= parent.Cell.x + radius; x++)
                    {
                        if (Mathf.Abs(x - parent.Cell.x) != radius && Mathf.Abs(y - parent.Cell.y) != radius)
                        {
                            continue;
                        }

                        Vector2Int candidate = new Vector2Int(x, y);
                        if (!CanCritterBirthAt(parent.Kind, candidate))
                        {
                            continue;
                        }

                        if (keepInsideRoom)
                        {
                            RoomInfo candidateRoom = RoomAt(candidate.x, candidate.y);
                            if (candidateRoom == null || candidateRoom.Id != parentRoom.Id)
                            {
                                continue;
                            }
                        }

                        birthCell = candidate;
                        return true;
                    }
                }
            }

            return false;
        }

        private bool CanCritterBirthAt(CritterKind kind, Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) ||
                HatchAt(cell) != null ||
                !CanCritterMoveTo(kind, cell))
            {
                return false;
            }

            return kind == CritterKind.Pacu || looseResourceKind[cell.x, cell.y] == LooseResourceKind.None;
        }

        private bool TryLayHatchEgg(Vector2Int origin)
        {
            Vector2Int[] offsets =
            {
                Vector2Int.zero,
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1),
                new Vector2Int(1, 1),
                new Vector2Int(-1, 1),
                new Vector2Int(1, -1),
                new Vector2Int(-1, -1)
            };

            for (int i = 0; i < offsets.Length; i++)
            {
                Vector2Int cell = origin + offsets[i];
                if (!CanPlaceHatchEgg(cell))
                {
                    continue;
                }

                looseResourceKind[cell.x, cell.y] = LooseResourceKind.HatchEgg;
                looseResourceAmount[cell.x, cell.y] = 1f;
                hatchEggAge[cell.x, cell.y] = 0f;
                terrainDirty = true;
                overlayDirty = true;
                return true;
            }

            return false;
        }

        private bool CanPlaceHatchEgg(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsPassable(cell.x, cell.y) &&
                waterMass[cell.x, cell.y] <= 0.05f &&
                looseResourceKind[cell.x, cell.y] == LooseResourceKind.None &&
                HatchAt(cell) == null;
        }

        private void SimulateHatchEggs(float deltaTime)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (looseResourceKind[x, y] != LooseResourceKind.HatchEgg || looseResourceAmount[x, y] <= 0.001f)
                    {
                        hatchEggAge[x, y] = 0f;
                        continue;
                    }

                    hatchEggAge[x, y] += deltaTime;
                    if (hatchEggAge[x, y] < HatchEggIncubationSeconds || hatches.Count >= MaxWildHatches)
                    {
                        continue;
                    }

                    Vector2Int cell = new Vector2Int(x, y);
                    if (!CanHatchEggAt(cell))
                    {
                        continue;
                    }

                    looseResourceKind[x, y] = LooseResourceKind.None;
                    looseResourceAmount[x, y] = 0f;
                    hatchEggAge[x, y] = 0f;
                    SpawnHatch("Hatchling " + (hatchEggsHatched + 1), cell, 42f, 0f, HatchMoveIntervalSeconds, HatchEatIntervalSeconds, 0f, 0f);
                    hatchEggsHatched++;
                    terrainDirty = true;
                    overlayDirty = true;
                    Log("A hatch egg hatched.");
                }
            }
        }

        private bool CanHatchEggAt(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsPassable(cell.x, cell.y) &&
                waterMass[cell.x, cell.y] <= 0.05f &&
                HatchAt(cell) == null;
        }

        private void RunIncubator(Vector2Int center, float deltaTime)
        {
            if (!CanUseEquipment(center))
            {
                return;
            }

            if (!incubatorEggLoaded[center.x, center.y])
            {
                if (!CanPoweredMachineRun(center) || hatchEggs < 1f || hatches.Count >= MaxWildHatches)
                {
                    return;
                }

                float consumed = ConsumeDryResource(LooseResourceKind.HatchEgg, 1f);
                if (consumed < 0.999f)
                {
                    StoreLooseResource(LooseResourceKind.HatchEgg, consumed);
                    return;
                }

                incubatorEggLoaded[center.x, center.y] = true;
                incubatorEggProgress[center.x, center.y] = 0f;
                terrainDirty = true;
                overlayDirty = true;
                Log("An Incubator loaded a hatch egg.");
            }

            if (TryCompleteIncubatorHatch(center))
            {
                return;
            }

            if (incubatorEggProgress[center.x, center.y] >= 1f)
            {
                return;
            }

            if (!CanPoweredMachineRun(center))
            {
                return;
            }

            float requestedPower = IncubatorPowerRate * deltaTime;
            float powerUsed = Mathf.Min(power, requestedPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, requestedPower);
            if (efficiency <= 0.001f)
            {
                return;
            }

            ConsumeCyclePower(powerUsed);
            incubatorEggProgress[center.x, center.y] = Mathf.Clamp01(incubatorEggProgress[center.x, center.y] + deltaTime * efficiency * IncubatorIncubationMultiplier / HatchEggIncubationSeconds);
            AddHeat(center, 0.04f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00028f * deltaTime * efficiency);
            terrainDirty = true;
            overlayDirty = true;

            TryCompleteIncubatorHatch(center);
        }

        private bool TryCompleteIncubatorHatch(Vector2Int center)
        {
            if (!incubatorEggLoaded[center.x, center.y] ||
                incubatorEggProgress[center.x, center.y] < 1f ||
                hatches.Count >= MaxWildHatches ||
                !TryFindIncubatorHatchSpawn(center, out Vector2Int spawnCell))
            {
                return false;
            }

            incubatorEggLoaded[center.x, center.y] = false;
            incubatorEggProgress[center.x, center.y] = 0f;
            SpawnHatch("Incubated Hatch " + (hatchEggsHatched + 1), spawnCell, 52f, HatchGroomedSeconds * 0.45f, HatchMoveIntervalSeconds, HatchEatIntervalSeconds, 0f, 0f);
            hatchEggsHatched++;
            incubatorHatchings++;
            milestoneRanching |= techFoodPreparation;
            terrainDirty = true;
            overlayDirty = true;
            Log("An Incubator hatched a hatchling.");
            return true;
        }

        private bool TryFindIncubatorHatchSpawn(Vector2Int center, out Vector2Int spawnCell)
        {
            Vector2Int[] offsets =
            {
                new Vector2Int(0, -1),
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(1, -1),
                new Vector2Int(-1, -1),
                new Vector2Int(1, 1),
                new Vector2Int(-1, 1)
            };

            for (int i = 0; i < offsets.Length; i++)
            {
                Vector2Int candidate = center + offsets[i];
                if (CanHatchEggAt(candidate))
                {
                    spawnCell = candidate;
                    return true;
                }
            }

            return TryFindHatchSpawnCell(center, 4, out spawnCell);
        }

        private int CountLoadedIncubatorEggs()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.Incubator && incubatorEggLoaded[x, y])
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CuddlePipsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                if (hatch.Kind == CritterKind.CuddlePip &&
                    Mathf.Abs(hatch.Cell.x - center.x) + Mathf.Abs(hatch.Cell.y - center.y) <= radius)
                {
                    count++;
                }
            }

            return count;
        }

        private string IncubatorReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.Incubator)
            {
                return "Incubator blocked: incubator missing.";
            }

            if (!techFoodPreparation)
            {
                return "Incubator blocked: research Food Preparation.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Incubator blocked: needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Incubator blocked: incubator is submerged.";
            }

            if (!HasWireAccess(cell))
            {
                return "Incubator blocked: needs power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Incubator blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Incubator blocked: automation signal is red.";
            }

            if (incubatorEggLoaded[cell.x, cell.y])
            {
                if (hatches.Count >= MaxWildHatches)
                {
                    return "Incubator blocked: critter capacity reached.";
                }

                if (incubatorEggProgress[cell.x, cell.y] >= 1f && !TryFindIncubatorHatchSpawn(cell, out _))
                {
                    return "Incubator blocked: loaded egg has no open hatch space.";
                }

                return "Incubator ready: incubating loaded egg.";
            }

            if (hatchEggs < 1f)
            {
                return "Incubator idle: no stored hatch eggs.";
            }

            if (hatches.Count >= MaxWildHatches)
            {
                return "Incubator blocked: critter capacity reached.";
            }

            return "Incubator ready: can load stored hatch egg.";
        }

        private Vector2Int ChooseHatchMoveTarget(HatchCritter hatch)
        {
            if (hatch.Kind == CritterKind.ShineBug && TryFindShineBugGlowMoveCell(hatch, out Vector2Int shineCell))
            {
                return shineCell;
            }

            if (hatch.Kind == CritterKind.Pacu && TryFindPacuWaterMoveCell(hatch, out Vector2Int pacuCell))
            {
                return pacuCell;
            }

            if (hatch.Kind == CritterKind.Morb && TryFindMorbPollutionMoveCell(hatch, out Vector2Int morbCell))
            {
                return morbCell;
            }

            if (hatch.Kind == CritterKind.Puft && TryFindPuftPollutedOxygenMoveCell(hatch, out Vector2Int pollutedOxygenCell))
            {
                return pollutedOxygenCell;
            }

            if (hatch.Kind == CritterKind.Slickster && TryFindSlicksterCarbonMoveCell(hatch, out Vector2Int carbonCell))
            {
                return carbonCell;
            }

            if (hatch.Kind == CritterKind.MoltenSlickster && TryFindMoltenSlicksterCarbonMoveCell(hatch, out Vector2Int moltenCarbonCell))
            {
                return moltenCarbonCell;
            }

            if (hatch.Kind == CritterKind.Drecko && TryFindDreckoGrazingTarget(hatch, out Vector2Int grazeCell))
            {
                return grazeCell;
            }

            if (hatch.Kind == CritterKind.Pip && TryFindPipArborMoveCell(hatch, out Vector2Int pipCell))
            {
                return pipCell;
            }

            if (hatch.Kind == CritterKind.PlugSlug && TryFindPlugSlugMetalMoveCell(hatch, out Vector2Int plugSlugCell))
            {
                return plugSlugCell;
            }

            if (hatch.Kind == CritterKind.GassyMoo && TryFindGassyMooBristleMoveCell(hatch, out Vector2Int gassyMooCell))
            {
                return gassyMooCell;
            }

            if (hatch.Kind == CritterKind.Beeta && TryFindBeetaRadiationMoveCell(hatch, out Vector2Int beetaCell))
            {
                return beetaCell;
            }

            if (hatch.Kind == CritterKind.Grubgrub && TryFindGrubgrubCropMoveCell(hatch, out Vector2Int grubgrubCell))
            {
                return grubgrubCell;
            }

            if (hatch.Kind == CritterKind.Sweetle && TryFindSweetleSulfurMoveCell(hatch, out Vector2Int sweetleCell))
            {
                return sweetleCell;
            }

            if (hatch.Kind == CritterKind.CuddlePip && TryFindCuddlePipEggMoveCell(hatch, out Vector2Int cuddlePipCell))
            {
                return cuddlePipCell;
            }

            if (hatch.Kind == CritterKind.ShoveVole && TryFindShoveVoleRegolithMoveCell(hatch, out Vector2Int shoveVoleCell))
            {
                return shoveVoleCell;
            }

            Vector2Int foodCell;
            if (hatch.Kind == CritterKind.Hatch && TryFindHatchFoodCell(hatch, out foodCell) && IsPassable(foodCell.x, foodCell.y))
            {
                return foodCell;
            }

            Vector2Int feederCell;
            if (hatch.Kind == CritterKind.Hatch && TryFindHatchFeeder(hatch, out feederCell) && IsPassable(feederCell.x, feederCell.y))
            {
                return feederCell;
            }

            Vector2Int[] offsets =
            {
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1),
                new Vector2Int(1, 1),
                new Vector2Int(-1, 1),
                new Vector2Int(1, -1),
                new Vector2Int(-1, -1)
            };

            int start = Mathf.Abs(Mathf.RoundToInt(hatch.Cell.x * 3 + hatch.Cell.y * 5 + elapsedTime * 2f)) % offsets.Length;
            for (int i = 0; i < offsets.Length; i++)
            {
                Vector2Int candidate = hatch.Cell + offsets[(start + i) % offsets.Length];
                if (CanCritterMoveTo(hatch.Kind, candidate))
                {
                    return candidate;
                }
            }

            return hatch.Cell;
        }

        private bool CanHatchMoveTo(Vector2Int cell)
        {
            return CanCritterMoveTo(CritterKind.Hatch, cell);
        }

        private bool CanCritterMoveTo(CritterKind kind, Vector2Int cell)
        {
            if (kind == CritterKind.Pacu)
            {
                return IsPacuSwimCell(cell);
            }

            if (!IsInside(cell.x, cell.y) ||
                !IsPassable(cell.x, cell.y) ||
                waterMass[cell.x, cell.y] > 0.05f)
            {
                return false;
            }

            if (kind == CritterKind.Slickster)
            {
                return temperature[cell.x, cell.y] > SlicksterMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < SlicksterMoveTemperatureMax;
            }

            if (kind == CritterKind.MoltenSlickster)
            {
                return temperature[cell.x, cell.y] > MoltenSlicksterMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < MoltenSlicksterMoveTemperatureMax;
            }

            if (kind == CritterKind.Drecko)
            {
                return temperature[cell.x, cell.y] > DreckoMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < DreckoMoveTemperatureMax;
            }

            if (kind == CritterKind.Puft)
            {
                return temperature[cell.x, cell.y] > PuftMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < PuftMoveTemperatureMax;
            }

            if (kind == CritterKind.Morb)
            {
                return temperature[cell.x, cell.y] > MorbMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < MorbMoveTemperatureMax;
            }

            if (kind == CritterKind.ShineBug)
            {
                return temperature[cell.x, cell.y] > ShineBugMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < ShineBugMoveTemperatureMax;
            }

            if (kind == CritterKind.Pip)
            {
                return temperature[cell.x, cell.y] > PipMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < PipMoveTemperatureMax;
            }

            if (kind == CritterKind.PlugSlug)
            {
                return temperature[cell.x, cell.y] > PlugSlugMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < PlugSlugMoveTemperatureMax;
            }

            if (kind == CritterKind.GassyMoo)
            {
                return temperature[cell.x, cell.y] > GassyMooMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < GassyMooMoveTemperatureMax;
            }

            if (kind == CritterKind.Beeta)
            {
                return temperature[cell.x, cell.y] > BeetaMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < BeetaMoveTemperatureMax;
            }

            if (kind == CritterKind.Grubgrub)
            {
                return temperature[cell.x, cell.y] > GrubgrubMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < GrubgrubMoveTemperatureMax;
            }

            if (kind == CritterKind.Sweetle)
            {
                return temperature[cell.x, cell.y] > SweetleMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < SweetleMoveTemperatureMax;
            }

            if (kind == CritterKind.CuddlePip)
            {
                return temperature[cell.x, cell.y] > CuddlePipMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < CuddlePipMoveTemperatureMax;
            }

            if (kind == CritterKind.ShoveVole)
            {
                return temperature[cell.x, cell.y] > ShoveVoleMoveTemperatureMin &&
                    temperature[cell.x, cell.y] < ShoveVoleMoveTemperatureMax;
            }

            return temperature[cell.x, cell.y] > -12f &&
                temperature[cell.x, cell.y] < 54f;
        }

        private bool TryFeedHatch(HatchCritter hatch)
        {
            if (hatch.Kind == CritterKind.ShineBug)
            {
                return TryFeedShineBug(hatch);
            }

            if (hatch.Kind == CritterKind.Pacu)
            {
                return TryFeedPacu(hatch);
            }

            if (hatch.Kind == CritterKind.Morb)
            {
                return TryFeedMorb(hatch);
            }

            if (hatch.Kind == CritterKind.Puft)
            {
                return TryFeedPuft(hatch);
            }

            if (hatch.Kind == CritterKind.Slickster)
            {
                return TryFeedSlickster(hatch);
            }

            if (hatch.Kind == CritterKind.MoltenSlickster)
            {
                return TryFeedMoltenSlickster(hatch);
            }

            if (hatch.Kind == CritterKind.Drecko)
            {
                return TryFeedDrecko(hatch);
            }

            if (hatch.Kind == CritterKind.Pip)
            {
                return TryFeedPip(hatch);
            }

            if (hatch.Kind == CritterKind.PlugSlug)
            {
                return TryFeedPlugSlug(hatch);
            }

            if (hatch.Kind == CritterKind.GassyMoo)
            {
                return TryFeedGassyMoo(hatch);
            }

            if (hatch.Kind == CritterKind.Beeta)
            {
                return TryFeedBeeta(hatch);
            }

            if (hatch.Kind == CritterKind.Grubgrub)
            {
                return TryFeedGrubgrub(hatch);
            }

            if (hatch.Kind == CritterKind.Sweetle)
            {
                return TryFeedSweetle(hatch);
            }

            if (hatch.Kind == CritterKind.CuddlePip)
            {
                return TryFeedCuddlePip(hatch);
            }

            if (hatch.Kind == CritterKind.ShoveVole)
            {
                return TryFeedShoveVole(hatch);
            }

            Vector2Int foodCell;
            if (!TryFindHatchFoodCell(hatch, out foodCell))
            {
                if (TryFeedHatchFromFeeder(hatch))
                {
                    return true;
                }

                hatch.Happiness = Mathf.Max(0f, hatch.Happiness - 4f);
                return false;
            }

            float eaten = Mathf.Min(HatchEatAmount, looseResourceAmount[foodCell.x, foodCell.y]);
            if (eaten <= 0.05f)
            {
                return false;
            }

            looseResourceAmount[foodCell.x, foodCell.y] -= eaten;
            if (looseResourceAmount[foodCell.x, foodCell.y] <= 0.05f)
            {
                looseResourceAmount[foodCell.x, foodCell.y] = 0f;
                looseResourceKind[foodCell.x, foodCell.y] = LooseResourceKind.None;
                hatchEggAge[foodCell.x, foodCell.y] = 0f;
            }

            CompleteHatchMeal(hatch, eaten, 3f);
            return true;
        }

        private bool TryFeedHatchFromFeeder(HatchCritter hatch)
        {
            if (hatch.Kind != CritterKind.Hatch)
            {
                return false;
            }

            Vector2Int feederCell;
            LooseResourceKind feedKind;
            float available;
            if (!TryFindHatchFeeder(hatch, out feederCell) || !TrySelectHatchFeedResource(out feedKind, out available))
            {
                return false;
            }

            if (!IsInside(feederCell.x, feederCell.y))
            {
                return false;
            }

            float eaten = ConsumeDryResource(feedKind, Mathf.Min(HatchEatAmount, available));
            if (eaten <= 0.05f)
            {
                return false;
            }

            hatchFeederMeals++;
            hatchFeederFoodConsumed += eaten;
            CompleteHatchMeal(hatch, eaten, 4f);
            if (hatchFeederMeals == 1)
            {
                Log("A Critter Feeder supplied stored feed to a hatch.");
            }

            return true;
        }

        private void CompleteHatchMeal(HatchCritter hatch, float eaten, float happinessGain)
        {
            float happinessScale = Mathf.Lerp(0.65f, 1.35f, Mathf.Clamp01(hatch.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(hatch.Cell, StableHatchCoalMultiplier);
            float coalAmount = eaten * HatchCoalYield * happinessScale * stableScale;
            AddLooseResource(hatch.Cell, LooseResourceKind.Coal, coalAmount);
            hatch.CoalProduced += coalAmount;
            hatchCoalProduced += coalAmount;
            hatch.Happiness = Mathf.Min(100f, hatch.Happiness + happinessGain);
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool TryFeedSlickster(HatchCritter slickster)
        {
            float consumed = RemoveCarbonDioxide(slickster.Cell, SlicksterCarbonDioxideMeal, SlicksterCarbonSearchRange);
            if (consumed <= 0.01f)
            {
                slickster.Happiness = Mathf.Max(0f, slickster.Happiness - 3.5f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.24f, Mathf.Clamp01(slickster.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(slickster.Cell, StableSlicksterCrudeMultiplier);
            float comfortScale = Mathf.Lerp(0.55f, 1.10f, SlicksterTemperatureComfort(slickster.Cell));
            float crudeProduced = consumed * SlicksterCrudeOilYield * happinessScale * stableScale * comfortScale;
            StoreCrudeOilInStorage(crudeProduced);
            slickster.CarbonDioxideConsumed += consumed;
            slickster.CrudeOilProduced += crudeProduced;
            slicksterCarbonConsumed += consumed;
            slicksterCrudeProduced += crudeProduced;
            slickster.Happiness = Mathf.Min(100f, slickster.Happiness + 3.5f);
            AddHeat(slickster.Cell, SlicksterMetabolicHeat * consumed, 1);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            if (slickster.CrudeOilProduced <= crudeProduced + 0.001f)
            {
                Log(slickster.Name + " converted CO2 into crude oil.");
            }

            return true;
        }

        private bool TryFeedMoltenSlickster(HatchCritter moltenSlickster)
        {
            float consumed = RemoveHotCarbonDioxide(moltenSlickster.Cell, SlicksterCarbonDioxideMeal, SlicksterCarbonSearchRange);
            if (consumed <= 0.01f)
            {
                moltenSlickster.Happiness = Mathf.Max(0f, moltenSlickster.Happiness - 3.8f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.70f, 1.22f, Mathf.Clamp01(moltenSlickster.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(moltenSlickster.Cell, StableMoltenSlicksterPetroleumMultiplier);
            float comfortScale = Mathf.Lerp(0.55f, 1.12f, MoltenSlicksterTemperatureComfort(moltenSlickster.Cell));
            float petroleumProduced = consumed * MoltenSlicksterPetroleumYield * happinessScale * stableScale * comfortScale;
            StorePetroleumInStorage(petroleumProduced);
            moltenSlickster.CarbonDioxideConsumed += consumed;
            moltenSlickster.CrudeOilProduced += petroleumProduced;
            moltenSlickster.Happiness = Mathf.Min(100f, moltenSlickster.Happiness + 3.3f);
            AddHeat(moltenSlickster.Cell, MoltenSlicksterMetabolicHeat * consumed, 1);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            if (moltenSlickster.CrudeOilProduced <= petroleumProduced + 0.001f)
            {
                Log(moltenSlickster.Name + " converted hot CO2 into petroleum.");
            }

            return true;
        }

        private bool TryFindSlicksterCarbonMoveCell(HatchCritter slickster, out Vector2Int carbonCell)
        {
            carbonCell = slickster.Cell;
            float bestScore = carbonDioxide[slickster.Cell.x, slickster.Cell.y];
            Vector2Int[] candidates =
            {
                slickster.Cell,
                slickster.TargetCell,
                new Vector2Int(slickster.Cell.x + 1, slickster.Cell.y),
                new Vector2Int(slickster.Cell.x - 1, slickster.Cell.y),
                new Vector2Int(slickster.Cell.x, slickster.Cell.y + 1),
                new Vector2Int(slickster.Cell.x, slickster.Cell.y - 1),
                new Vector2Int(slickster.Cell.x + 1, slickster.Cell.y + 1),
                new Vector2Int(slickster.Cell.x - 1, slickster.Cell.y + 1),
                new Vector2Int(slickster.Cell.x + 1, slickster.Cell.y - 1),
                new Vector2Int(slickster.Cell.x - 1, slickster.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Slickster, candidate))
                {
                    continue;
                }

                float score = carbonDioxide[candidate.x, candidate.y] * 10f + SlicksterTemperatureComfort(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    carbonCell = candidate;
                }
            }

            return carbonCell != slickster.Cell && bestScore > 0.05f;
        }

