        private bool TryFeedPuft(HatchCritter puft)
        {
            if (DryResourceFreeSpace() <= 0.001f)
            {
                puft.Happiness = Mathf.Max(0f, puft.Happiness - 3.5f);
                return false;
            }

            float consumed = RemovePollutedOxygen(puft.Cell, PuftPollutedOxygenMeal, PuftPollutedOxygenSearchRange);
            if (consumed <= 0.01f)
            {
                puft.Happiness = Mathf.Max(0f, puft.Happiness - 3.5f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.24f, Mathf.Clamp01(puft.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(puft.Cell, StablePuftSlimeMultiplier);
            float groomScale = puft.GroomedSeconds > 0f ? 1.18f : 0.68f;
            float produced = consumed * PuftSlimeYield * happinessScale * stableScale * groomScale;
            float stored = StoreDryResource(ref slime, produced);
            puft.PollutedOxygenConsumed += consumed;
            puft.SlimeProduced += stored;
            puftPollutedOxygenConsumed += consumed;
            puftSlimeProduced += stored;
            puft.Happiness = Mathf.Min(100f, puft.Happiness + 3.5f);
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
            if (stored > 0.001f && puft.SlimeProduced <= stored + 0.001f)
            {
                Log(puft.Name + " condensed polluted oxygen into slime.");
            }

            return true;
        }

        private bool TryFindPuftPollutedOxygenMoveCell(HatchCritter puft, out Vector2Int pollutedOxygenCell)
        {
            pollutedOxygenCell = puft.Cell;
            float bestScore = pollutedOxygen[puft.Cell.x, puft.Cell.y];
            Vector2Int[] candidates =
            {
                puft.Cell,
