                new Vector2Int(puft.Cell.x, puft.Cell.y + 1),
                new Vector2Int(puft.Cell.x, puft.Cell.y - 1),
                new Vector2Int(puft.Cell.x + 1, puft.Cell.y + 1),
                new Vector2Int(puft.Cell.x - 1, puft.Cell.y + 1),
                new Vector2Int(puft.Cell.x + 1, puft.Cell.y - 1),
                new Vector2Int(puft.Cell.x - 1, puft.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Puft, candidate))
                {
                    continue;
                }

                float score = pollutedOxygen[candidate.x, candidate.y] * 10f + SlimeCellsAround(candidate, 2) * 0.08f;
                if (score > bestScore)
