        private bool TryFeedPacu(HatchCritter pacu)
        {
            if (!IsPacuSwimCell(pacu.Cell))
            {
                pacu.Happiness = Mathf.Max(0f, pacu.Happiness - 5f);
                return false;
            }

            if (algae <= 0.05f)
            {
                pacu.Happiness = Mathf.Max(0f, pacu.Happiness - 3.5f);
                return false;
            }

            float eaten = Mathf.Min(PacuAlgaeMeal, algae);
            algae = Mathf.Max(0f, algae - eaten);
            float happinessScale = Mathf.Lerp(0.72f, 1.20f, Mathf.Clamp01(pacu.Happiness / 100f));
            float groomScale = pacu.GroomedSeconds > 0f ? PacuGroomedFoodMultiplier : 0.78f;
            float saltWaterScale = IsSaltWaterWorldLiquidAt(pacu.Cell.x, pacu.Cell.y) ? 1.08f : 1f;
            float produced = eaten * PacuSeafoodYield * happinessScale * groomScale * saltWaterScale;
            AddFreshFood(produced, PacuSeafoodFreshness, PacuSeafoodQuality, true, germs[pacu.Cell.x, pacu.Cell.y] * 0.08f);
            pacu.FoodConsumed += eaten;
            pacu.SeafoodProduced += produced;
            pacuAlgaeConsumed += eaten;
            pacuSeafoodProduced += produced;
            pacu.Happiness = Mathf.Min(100f, pacu.Happiness + 3.4f);
            terrainDirty = true;
            overlayDirty = true;
            if (pacu.SeafoodProduced <= produced + 0.001f)
            {
                Log(pacu.Name + " turned algae into fresh seafood.");
            }

            return true;
        }

        private bool TryFindPacuWaterMoveCell(HatchCritter pacu, out Vector2Int waterCell)
        {
            waterCell = pacu.Cell;
            float bestScore = PacuWaterScore(pacu.Cell);
            Vector2Int[] candidates =
            {
                pacu.Cell,
                pacu.TargetCell,
                new Vector2Int(pacu.Cell.x + 1, pacu.Cell.y),
                new Vector2Int(pacu.Cell.x - 1, pacu.Cell.y),
                new Vector2Int(pacu.Cell.x, pacu.Cell.y + 1),
                new Vector2Int(pacu.Cell.x, pacu.Cell.y - 1),
                new Vector2Int(pacu.Cell.x + 1, pacu.Cell.y + 1),
                new Vector2Int(pacu.Cell.x - 1, pacu.Cell.y + 1),
                new Vector2Int(pacu.Cell.x + 1, pacu.Cell.y - 1),
                new Vector2Int(pacu.Cell.x - 1, pacu.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Pacu, candidate))
                {
                    continue;
                }

                float score = PacuWaterScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    waterCell = candidate;
                }
            }

            return waterCell != pacu.Cell && bestScore > 0.20f;
        }

        private float PacuWaterScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPacuSwimCell(cell))
            {
                return 0f;
            }

            float temperatureComfort = 1f - Mathf.Abs(Mathf.InverseLerp(PacuMoveTemperatureMin, PacuMoveTemperatureMax, temperature[cell.x, cell.y]) - 0.52f);
            return waterMass[cell.x, cell.y] * 0.012f +
                (IsSaltWaterWorldLiquidAt(cell.x, cell.y) ? 0.18f : 0.10f) +
                temperatureComfort;
        }

        private bool IsPacuSwimCell(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            CellKind kind = cells[cell.x, cell.y];
            return (kind == CellKind.Water || kind == CellKind.SaltWater) &&
                waterMass[cell.x, cell.y] >= PacuMinimumWaterMass &&
                temperature[cell.x, cell.y] > PacuMoveTemperatureMin &&
                temperature[cell.x, cell.y] < PacuMoveTemperatureMax;
        }

        private bool TryFeedShineBug(HatchCritter shineBug)
        {
