        private bool TryFeedPip(HatchCritter pip)
        {
            if (!CanCritterMoveTo(CritterKind.Pip, pip.Cell))
            {
                pip.Happiness = Mathf.Max(0f, pip.Happiness - 4f);
                return false;
            }

            float eaten = 0f;
            if (lumber > 0.05f)
            {
                eaten = ConsumeDryResource(LooseResourceKind.Lumber, Mathf.Min(PipLumberMeal, lumber));
            }

            if (eaten <= 0.05f && TryNibblePipArborGrowth(pip.Cell, out float arborFeed))
            {
                eaten = arborFeed;
            }

            if (eaten <= 0.05f)
            {
                pip.Happiness = Mathf.Max(0f, pip.Happiness - 3.2f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.22f, Mathf.Clamp01(pip.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(pip.Cell, 1.14f);
            float groomScale = pip.GroomedSeconds > 0f ? 1.18f : 0.76f;
            float produced = eaten * PipDirtYield * happinessScale * stableScale * groomScale;
            float stored = StoreDryResource(ref dirt, produced);
            pip.FoodConsumed += eaten;
            pip.CoalProduced += stored;
            pip.Happiness = Mathf.Min(100f, pip.Happiness + 3.8f);
            TryPlantPipArborTree(pip);
            terrainDirty = true;
            overlayDirty = true;
            if (stored > 0.001f && pip.CoalProduced <= stored + 0.001f)
            {
                Log(pip.Name + " turned forest feed into dirt.");
            }

            return true;
        }

        private bool TryNibblePipArborGrowth(Vector2Int center, out float feed)
        {
            feed = 0f;
            Vector2Int tree = new Vector2Int(-1, -1);
            float bestScore = 0.14f;
            for (int dy = -PipArborSearchRange; dy <= PipArborSearchRange; dy++)
            {
                for (int dx = -PipArborSearchRange; dx <= PipArborSearchRange; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || cells[x, y] != CellKind.ArborTree || plantGrowth[x, y] <= 0.16f)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    float score = plantGrowth[x, y] - distance * 0.018f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        tree = new Vector2Int(x, y);
                    }
                }
            }

            if (tree.x < 0)
            {
                return false;
            }

            feed = Mathf.Min(PipArborNibble, Mathf.Max(0f, plantGrowth[tree.x, tree.y] - 0.06f));
            if (feed <= 0.01f)
            {
                return false;
            }

            plantGrowth[tree.x, tree.y] = Mathf.Max(0f, plantGrowth[tree.x, tree.y] - feed);
            cropStress[tree.x, tree.y] = Mathf.Min(CropWiltThresholdSeconds, cropStress[tree.x, tree.y] + feed);
            return true;
        }

        private bool TryFindPipArborMoveCell(HatchCritter pip, out Vector2Int arborCell)
        {
            arborCell = pip.Cell;
            float bestScore = PipArborMoveScore(pip.Cell);
            Vector2Int[] candidates =
            {
                pip.Cell,
                pip.TargetCell,
                new Vector2Int(pip.Cell.x + 1, pip.Cell.y),
                new Vector2Int(pip.Cell.x - 1, pip.Cell.y),
                new Vector2Int(pip.Cell.x, pip.Cell.y + 1),
                new Vector2Int(pip.Cell.x, pip.Cell.y - 1),
                new Vector2Int(pip.Cell.x + 1, pip.Cell.y + 1),
                new Vector2Int(pip.Cell.x - 1, pip.Cell.y + 1),
                new Vector2Int(pip.Cell.x + 1, pip.Cell.y - 1),
                new Vector2Int(pip.Cell.x - 1, pip.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Pip, candidate))
                {
                    continue;
                }

                float score = PipArborMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    arborCell = candidate;
                }
            }

            return arborCell != pip.Cell && bestScore > 0.20f;
        }

        private float PipArborMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return ArborTreesAround(cell, PipArborSearchRange) * 0.18f +
                ForestPocketCellsAround(cell, 4) * 0.04f +
                PipHabitatComfort(cell);
        }

        private bool TryPlantPipArborTree(HatchCritter pip)
        {
            if (pip == null || UnityEngine.Random.value > PipPlantChance || ArborTreesAround(pip.Cell, 3) >= 3)
            {
                return false;
            }

            if (!TryFindPipPlantCell(pip.Cell, out Vector2Int plantCell))
            {
                return false;
            }

            cells[plantCell.x, plantCell.y] = CellKind.ArborTree;
            waterMass[plantCell.x, plantCell.y] = 0f;
            oxygen[plantCell.x, plantCell.y] = Mathf.Max(oxygen[plantCell.x, plantCell.y], 0.14f);
            carbonDioxide[plantCell.x, plantCell.y] = Mathf.Max(carbonDioxide[plantCell.x, plantCell.y], 0.06f);
            pollutedOxygen[plantCell.x, plantCell.y] = Mathf.Max(pollutedOxygen[plantCell.x, plantCell.y], 0.01f);
            hydrogen[plantCell.x, plantCell.y] = 0f;
            steam[plantCell.x, plantCell.y] = 0f;
            chlorine[plantCell.x, plantCell.y] = 0f;
            naturalGas[plantCell.x, plantCell.y] = 0f;
            sourGas[plantCell.x, plantCell.y] = 0f;
            germs[plantCell.x, plantCell.y] = 0f;
            looseResourceKind[plantCell.x, plantCell.y] = LooseResourceKind.None;
            looseResourceAmount[plantCell.x, plantCell.y] = 0f;
            temperature[plantCell.x, plantCell.y] = Mathf.Clamp(temperature[plantCell.x, plantCell.y], ArborTreeTemperatureMin, ArborTreeTemperatureMax);
            plantGrowth[plantCell.x, plantCell.y] = 0.22f;
            cropTendedSeconds[plantCell.x, plantCell.y] = 0f;
            cropStress[plantCell.x, plantCell.y] = 0f;
            terrainDirty = true;
            overlayDirty = true;
            Log(pip.Name + " planted a wild Arbor Tree.");
            return true;
        }

        private bool TryFindPipPlantCell(Vector2Int center, out Vector2Int plantCell)
        {
            plantCell = new Vector2Int(-1, -1);
            for (int radius = 1; radius <= 3; radius++)
            {
                for (int y = center.y - radius; y <= center.y + radius; y++)
                {
                    for (int x = center.x - radius; x <= center.x + radius; x++)
                    {
                        if (Mathf.Abs(x - center.x) != radius && Mathf.Abs(y - center.y) != radius)
                        {
                            continue;
                        }

                        if (CanPipPlantArborTreeAt(x, y))
                        {
                            plantCell = new Vector2Int(x, y);
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool CanPipPlantArborTreeAt(int x, int y)
        {
            if (!CanPlaceArborTreeAt(x, y) || HatchAt(new Vector2Int(x, y)) != null)
            {
                return false;
            }

            return ArborTreesAround(new Vector2Int(x, y), 2) < 2;
        }

        private int ArborTreesAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.ArborTree)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TryFeedPlugSlug(HatchCritter plugSlug)
        {
            if (!CanCritterMoveTo(CritterKind.PlugSlug, plugSlug.Cell))
            {
                plugSlug.Happiness = Mathf.Max(0f, plugSlug.Happiness - 4f);
                return false;
            }

            float powerSpace = Mathf.Max(0f, maxPower - power);
            if (powerSpace <= 0.05f)
            {
                plugSlug.Happiness = Mathf.Max(0f, plugSlug.Happiness - 1f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.18f, Mathf.Clamp01(plugSlug.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(plugSlug.Cell, PlugSlugStablePowerMultiplier);
            float groomScale = plugSlug.GroomedSeconds > 0f ? 1.18f : 0.72f;
            float outputScale = happinessScale * stableScale * groomScale;
            float maxMealByStorage = powerSpace / Mathf.Max(0.001f, PlugSlugPowerYield * outputScale);
            if (!TrySelectPlugSlugMetalFeed(maxMealByStorage, out LooseResourceKind feedKind, out float meal))
            {
                plugSlug.Happiness = Mathf.Max(0f, plugSlug.Happiness - 3.2f);
                return false;
            }

            float eaten = ConsumeDryResource(feedKind, meal);
            if (eaten <= 0.02f)
            {
                plugSlug.Happiness = Mathf.Max(0f, plugSlug.Happiness - 3.2f);
                return false;
            }

            float generated = AddGeneratedPower(eaten * PlugSlugPowerYield * outputScale);
            float hydrogenProduced = eaten * PlugSlugHydrogenYield * Mathf.Lerp(0.80f, 1.18f, Mathf.Clamp01(plugSlug.Happiness / 100f));
            AddGasToTile(plugSlug.Cell.x, plugSlug.Cell.y, 0f, 0f, 0f, hydrogenProduced, 0f, 0f, 0f, temperature[plugSlug.Cell.x, plugSlug.Cell.y] + 4f);
            plugSlug.FoodConsumed += eaten;
            plugSlug.CoalProduced += generated;
            plugSlug.PollutedOxygenProduced += hydrogenProduced;
            plugSlug.Happiness = Mathf.Min(100f, plugSlug.Happiness + 3.6f);
            AddHeat(plugSlug.Cell, 0.05f * Mathf.Max(0.1f, eaten), 1);
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
            if (generated > 0.001f && plugSlug.CoalProduced <= generated + 0.001f)
            {
                Log(plugSlug.Name + " converted metal into battery power.");
            }

            return true;
        }

        private bool TrySelectPlugSlugMetalFeed(float maxMeal, out LooseResourceKind feedKind, out float meal)
        {
            feedKind = LooseResourceKind.None;
            meal = 0f;
            if (maxMeal <= 0.02f)
            {
                return false;
            }

            if (metal > 0.05f)
            {
                feedKind = LooseResourceKind.Metal;
                meal = Mathf.Min(PlugSlugMetalMeal, metal, maxMeal);
                return meal > 0.02f;
            }

            if (refinedMetal > 0.05f)
            {
                feedKind = LooseResourceKind.RefinedMetal;
                meal = Mathf.Min(PlugSlugRefinedMetalMeal, refinedMetal, maxMeal);
                return meal > 0.02f;
            }

            return false;
        }

        private bool HasPlugSlugMetalFeedAvailable()
        {
            return metal > 0.05f || refinedMetal > 0.05f;
        }

        private bool TryFindPlugSlugMetalMoveCell(HatchCritter plugSlug, out Vector2Int metalCell)
        {
            metalCell = plugSlug.Cell;
            float bestScore = PlugSlugMetalMoveScore(plugSlug.Cell);
            Vector2Int[] candidates =
            {
                plugSlug.Cell,
                plugSlug.TargetCell,
                new Vector2Int(plugSlug.Cell.x + 1, plugSlug.Cell.y),
                new Vector2Int(plugSlug.Cell.x - 1, plugSlug.Cell.y),
                new Vector2Int(plugSlug.Cell.x, plugSlug.Cell.y + 1),
                new Vector2Int(plugSlug.Cell.x, plugSlug.Cell.y - 1),
                new Vector2Int(plugSlug.Cell.x + 1, plugSlug.Cell.y + 1),
                new Vector2Int(plugSlug.Cell.x - 1, plugSlug.Cell.y + 1),
                new Vector2Int(plugSlug.Cell.x + 1, plugSlug.Cell.y - 1),
                new Vector2Int(plugSlug.Cell.x - 1, plugSlug.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.PlugSlug, candidate))
                {
                    continue;
                }

                float score = PlugSlugMetalMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    metalCell = candidate;
                }
            }

            return metalCell != plugSlug.Cell && bestScore > 0.18f;
        }

        private float PlugSlugMetalMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            float powerNeed = maxPower <= 0.001f ? 0f : 1f - Mathf.Clamp01(power / maxPower);
            return MetalOreCellsAround(cell, PlugSlugMetalSearchRange) * 0.16f +
                CountPowerStorageCellsAround(cell, 4) * 0.18f * Mathf.Lerp(0.35f, 1f, powerNeed) +
                PlugSlugHabitatComfort(cell);
        }

        private int MetalOreCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.MetalOre)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountPowerStorageCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    CellKind kind = cells[x, y];
                    if (kind == CellKind.Battery || kind == CellKind.JumboBattery || kind == CellKind.SmartBattery)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TryFeedGassyMoo(HatchCritter gassyMoo)
        {
            if (!CanCritterMoveTo(CritterKind.GassyMoo, gassyMoo.Cell))
            {
                gassyMoo.Happiness = Mathf.Max(0f, gassyMoo.Happiness - 4f);
                return false;
            }

            float gasSpace = Mathf.Max(0f, GasVentMaxPressure - TileGasTotal(gassyMoo.Cell.x, gassyMoo.Cell.y));
            if (gasSpace <= 0.01f)
            {
                gassyMoo.Happiness = Mathf.Max(0f, gassyMoo.Happiness - 2f);
                return false;
            }

            if (!TryConsumeGassyMooBristle(gassyMoo.Cell, out float feedUnits))
            {
                gassyMoo.Happiness = Mathf.Max(0f, gassyMoo.Happiness - 3.4f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.70f, 1.22f, Mathf.Clamp01(gassyMoo.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(gassyMoo.Cell, GassyMooStableGasMultiplier);
            float groomScale = gassyMoo.GroomedSeconds > 0f ? 1.16f : 0.72f;
            float produced = Mathf.Min(gasSpace, feedUnits * GassyMooNaturalGasYield * happinessScale * stableScale * groomScale);
            if (produced <= 0.001f)
            {
                gassyMoo.Happiness = Mathf.Max(0f, gassyMoo.Happiness - 2f);
                return false;
            }

            AddGasToTile(gassyMoo.Cell.x, gassyMoo.Cell.y, 0f, 0f, 0f, 0f, 0f, produced, 0f, temperature[gassyMoo.Cell.x, gassyMoo.Cell.y] + 2f);
            gassyMoo.FoodConsumed += feedUnits;
            gassyMoo.PollutedOxygenProduced += produced;
            gassyMoo.Happiness = Mathf.Min(100f, gassyMoo.Happiness + 3.5f);
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
            if (gassyMoo.PollutedOxygenProduced <= produced + 0.001f)
            {
                Log(gassyMoo.Name + " grazed bristle blossoms into natural gas.");
            }

            return true;
        }

        private bool TryConsumeGassyMooBristle(Vector2Int center, out float feedUnits)
        {
            feedUnits = 0f;
            Vector2Int crop = new Vector2Int(-1, -1);
            float bestScore = 0.14f;
            for (int dy = -GassyMooBristleSearchRange; dy <= GassyMooBristleSearchRange; dy++)
            {
                for (int dx = -GassyMooBristleSearchRange; dx <= GassyMooBristleSearchRange; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || cells[x, y] != CellKind.HydroponicFarm || plantGrowth[x, y] <= 0.16f)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    float score = plantGrowth[x, y] - distance * 0.018f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        crop = new Vector2Int(x, y);
                    }
                }
            }

            if (crop.x < 0)
            {
                return false;
            }

            feedUnits = Mathf.Min(GassyMooBristleNibble, Mathf.Max(0f, plantGrowth[crop.x, crop.y] - 0.06f));
            if (feedUnits <= 0.01f)
            {
                return false;
            }

            plantGrowth[crop.x, crop.y] = Mathf.Max(0f, plantGrowth[crop.x, crop.y] - feedUnits);
            cropStress[crop.x, crop.y] = Mathf.Min(CropWiltThresholdSeconds, cropStress[crop.x, crop.y] + feedUnits * 1.2f);
            return true;
        }

        private bool TryFindGassyMooBristleMoveCell(HatchCritter gassyMoo, out Vector2Int bristleCell)
        {
            bristleCell = gassyMoo.Cell;
            float bestScore = GassyMooBristleMoveScore(gassyMoo.Cell);
            Vector2Int[] candidates =
            {
                gassyMoo.Cell,
                gassyMoo.TargetCell,
                new Vector2Int(gassyMoo.Cell.x + 1, gassyMoo.Cell.y),
                new Vector2Int(gassyMoo.Cell.x - 1, gassyMoo.Cell.y),
                new Vector2Int(gassyMoo.Cell.x, gassyMoo.Cell.y + 1),
                new Vector2Int(gassyMoo.Cell.x, gassyMoo.Cell.y - 1),
                new Vector2Int(gassyMoo.Cell.x + 1, gassyMoo.Cell.y + 1),
                new Vector2Int(gassyMoo.Cell.x - 1, gassyMoo.Cell.y + 1),
                new Vector2Int(gassyMoo.Cell.x + 1, gassyMoo.Cell.y - 1),
                new Vector2Int(gassyMoo.Cell.x - 1, gassyMoo.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.GassyMoo, candidate))
                {
                    continue;
                }

                float score = GassyMooBristleMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    bristleCell = candidate;
                }
            }

            return bristleCell != gassyMoo.Cell && bestScore > 0.18f;
        }

        private float GassyMooBristleMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            float gasSpace = Mathf.Clamp01((GasVentMaxPressure - TileGasTotal(cell.x, cell.y)) / Mathf.Max(0.001f, GasVentMaxPressure));
            return BristleBlossomsAround(cell, GassyMooBristleSearchRange) * 0.18f +
                gasSpace * 0.20f +
                GassyMooHabitatComfort(cell);
        }

        private int BristleBlossomsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.HydroponicFarm)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TryFeedBeeta(HatchCritter beeta)
        {
            if (!CanCritterMoveTo(CritterKind.Beeta, beeta.Cell))
            {
                beeta.Happiness = Mathf.Max(0f, beeta.Happiness - 4f);
                return false;
            }

            float feedUnits = BeetaRadiationSourceScore(beeta.Cell);
            if (feedUnits < BeetaRadiationMinimum)
            {
                beeta.Happiness = Mathf.Max(0f, beeta.Happiness - 3.6f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.22f, Mathf.Clamp01(beeta.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(beeta.Cell, BeetaStableSampleMultiplier);
            float groomScale = beeta.GroomedSeconds > 0f ? 1.15f : 0.76f;
            float samplesProduced = feedUnits * BeetaSampleYield * happinessScale * stableScale * groomScale;
            float radboltProduced = feedUnits * BeetaRadboltChargeYield * happinessScale * groomScale;
            if (samplesProduced <= 0.001f && radboltProduced <= 0.001f)
            {
                beeta.Happiness = Mathf.Max(0f, beeta.Happiness - 2f);
                return false;
            }

            radiationSamples += samplesProduced;
            radboltCharge += radboltProduced;
            beeta.FoodConsumed += feedUnits;
            beeta.PollutedOxygenProduced += samplesProduced;
            beeta.CoalProduced += radboltProduced;
            beeta.Happiness = Mathf.Min(100f, beeta.Happiness + 3.4f);
            terrainDirty = true;
            overlayDirty = true;
            if (beeta.PollutedOxygenProduced <= samplesProduced + 0.001f)
            {
                Log(beeta.Name + " gathered radiation into research samples.");
            }

            return true;
        }

        private bool TryFindBeetaRadiationMoveCell(HatchCritter beeta, out Vector2Int radiationCell)
        {
            radiationCell = beeta.Cell;
            float bestScore = BeetaRadiationMoveScore(beeta.Cell);
            Vector2Int[] candidates =
            {
                beeta.Cell,
                beeta.TargetCell,
                new Vector2Int(beeta.Cell.x + 1, beeta.Cell.y),
                new Vector2Int(beeta.Cell.x - 1, beeta.Cell.y),
                new Vector2Int(beeta.Cell.x, beeta.Cell.y + 1),
                new Vector2Int(beeta.Cell.x, beeta.Cell.y - 1),
                new Vector2Int(beeta.Cell.x + 1, beeta.Cell.y + 1),
                new Vector2Int(beeta.Cell.x - 1, beeta.Cell.y + 1),
                new Vector2Int(beeta.Cell.x + 1, beeta.Cell.y - 1),
                new Vector2Int(beeta.Cell.x - 1, beeta.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Beeta, candidate))
                {
                    continue;
                }

                float score = BeetaRadiationMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    radiationCell = candidate;
                }
            }

            return radiationCell != beeta.Cell && bestScore > BeetaRadiationMinimum * 1.4f;
        }

        private float BeetaRadiationMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return BeetaRadiationSourceScore(cell) * 1.65f +
                RadiationTilesAround(cell, BeetaRadiationSearchRange) * 0.035f +
                BeetaHabitatComfort(cell);
        }

        private float BeetaRadiationSourceScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return 0f;
            }

            return RadiationAt(cell.x, cell.y);
        }

        private int RadiationTilesAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (RadiationAt(x, y) >= BeetaRadiationMinimum)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TryFeedGrubgrub(HatchCritter grubgrub)
        {
            if (!CanCritterMoveTo(CritterKind.Grubgrub, grubgrub.Cell) || DryResourceFreeSpace() <= 0.001f)
            {
                grubgrub.Happiness = Mathf.Max(0f, grubgrub.Happiness - 3.8f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.22f, Mathf.Clamp01(grubgrub.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(grubgrub.Cell, GrubgrubStableFertilizerMultiplier);
            float groomScale = grubgrub.GroomedSeconds > 0f ? 1.15f : 0.74f;
            float tendSeconds = GrubgrubTendSeconds * Mathf.Lerp(0.80f, 1.25f, Mathf.Clamp01(grubgrub.Happiness / 100f)) * (grubgrub.GroomedSeconds > 0f ? 1.15f : 1f);
            if (!TryRubGrubgrubCrop(grubgrub.Cell, tendSeconds, out float feedUnits))
            {
                grubgrub.Happiness = Mathf.Max(0f, grubgrub.Happiness - 3.4f);
                return false;
            }

            float produced = feedUnits * GrubgrubFertilizerYield * happinessScale * stableScale * groomScale;
            float stored = StoreDryResource(ref fertilizer, produced);
            if (stored <= 0.001f)
            {
                grubgrub.Happiness = Mathf.Max(0f, grubgrub.Happiness - 2f);
                return false;
            }

            fertilizerProduced += stored;
            grubgrub.FoodConsumed += feedUnits;
            grubgrub.CoalProduced += stored;
            grubgrub.PlasticProduced += tendSeconds;
            grubgrub.Happiness = Mathf.Min(100f, grubgrub.Happiness + 3.4f);
            terrainDirty = true;
            overlayDirty = true;
            if (grubgrub.CoalProduced <= stored + 0.001f)
            {
                Log(grubgrub.Name + " rubbed crops and produced fertilizer.");
            }

            return true;
        }

        private bool TryRubGrubgrubCrop(Vector2Int center, float tendSeconds, out float feedUnits)
        {
            feedUnits = 0f;
            Vector2Int crop = new Vector2Int(-1, -1);
            float bestScore = 0.10f;
            for (int dy = -GrubgrubCropSearchRange; dy <= GrubgrubCropSearchRange; dy++)
            {
                for (int dx = -GrubgrubCropSearchRange; dx <= GrubgrubCropSearchRange; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsCropKind(cells[x, y]) || plantGrowth[x, y] <= 0.04f)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    float tendNeed = cropTendedSeconds[x, y] <= 5f ? 0.50f : 0f;
                    float growthNeed = plantGrowth[x, y] < 1f ? 0.32f : 0.08f;
                    float score = tendNeed + growthNeed + plantGrowth[x, y] * 0.45f - distance * 0.018f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        crop = new Vector2Int(x, y);
                    }
                }
            }

            if (crop.x < 0)
            {
                return false;
            }

            feedUnits = Mathf.Min(GrubgrubCropNibble, Mathf.Max(0.02f, plantGrowth[crop.x, crop.y] * 0.12f));
            plantGrowth[crop.x, crop.y] = Mathf.Max(0.02f, plantGrowth[crop.x, crop.y] - feedUnits * 0.25f);
            cropTendedSeconds[crop.x, crop.y] = Mathf.Max(cropTendedSeconds[crop.x, crop.y], tendSeconds);
            cropStress[crop.x, crop.y] = Mathf.Max(0f, cropStress[crop.x, crop.y] - tendSeconds * 0.08f);
            return true;
        }

        private bool TryFindGrubgrubCropMoveCell(HatchCritter grubgrub, out Vector2Int cropCell)
        {
            cropCell = grubgrub.Cell;
            float bestScore = GrubgrubCropMoveScore(grubgrub.Cell);
            Vector2Int[] candidates =
            {
                grubgrub.Cell,
                grubgrub.TargetCell,
                new Vector2Int(grubgrub.Cell.x + 1, grubgrub.Cell.y),
                new Vector2Int(grubgrub.Cell.x - 1, grubgrub.Cell.y),
                new Vector2Int(grubgrub.Cell.x, grubgrub.Cell.y + 1),
                new Vector2Int(grubgrub.Cell.x, grubgrub.Cell.y - 1),
                new Vector2Int(grubgrub.Cell.x + 1, grubgrub.Cell.y + 1),
                new Vector2Int(grubgrub.Cell.x - 1, grubgrub.Cell.y + 1),
                new Vector2Int(grubgrub.Cell.x + 1, grubgrub.Cell.y - 1),
                new Vector2Int(grubgrub.Cell.x - 1, grubgrub.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Grubgrub, candidate))
                {
                    continue;
                }

                float score = GrubgrubCropMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    cropCell = candidate;
                }
            }

            return cropCell != grubgrub.Cell && bestScore > 0.18f;
        }

        private float GrubgrubCropMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return CropCellsAround(cell, GrubgrubCropSearchRange) * 0.12f +
                TendableCropCellsAround(cell, GrubgrubCropSearchRange) * 0.20f +
                GrubgrubHabitatComfort(cell);
        }

        private bool TryFeedSweetle(HatchCritter sweetle)
        {
            if (!CanCritterMoveTo(CritterKind.Sweetle, sweetle.Cell) || DryResourceFreeSpace() <= 0.001f)
            {
                sweetle.Happiness = Mathf.Max(0f, sweetle.Happiness - 3.6f);
                return false;
            }

            float eaten = ConsumeSweetleSulfur(sweetle.Cell, SweetleSulfurMeal, SweetleSulfurSearchRange);
            if (eaten <= 0.01f)
            {
                sweetle.Happiness = Mathf.Max(0f, sweetle.Happiness - 4.2f);
                return false;
            }

            float tendSeconds = SweetleCropRubSeconds * Mathf.Lerp(0.82f, 1.22f, Mathf.Clamp01(sweetle.Happiness / 100f)) * (sweetle.GroomedSeconds > 0f ? 1.12f : 1f);
            TryRubGrubgrubCrop(sweetle.Cell, tendSeconds, out float cropFeedUnits);
            float happinessScale = Mathf.Lerp(0.72f, 1.18f, Mathf.Clamp01(sweetle.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(sweetle.Cell, SweetleStableFertilizerMultiplier);
            float groomScale = sweetle.GroomedSeconds > 0f ? 1.10f : 0.78f;
            float produced = eaten * SweetleFertilizerYield * happinessScale * stableScale * groomScale;
            float stored = StoreDryResource(ref fertilizer, produced);
            if (stored <= 0.001f)
            {
                StoreLooseResource(LooseResourceKind.Sulfur, eaten);
                sweetle.Happiness = Mathf.Max(0f, sweetle.Happiness - 2f);
                return false;
            }

            fertilizerProduced += stored;
            sweetle.FoodConsumed += eaten;
            sweetle.CoalProduced += stored;
            sweetle.PlasticProduced += tendSeconds;
            sweetle.SlimeProduced += cropFeedUnits;
            sweetle.Happiness = Mathf.Min(100f, sweetle.Happiness + 3.2f);
            terrainDirty = true;
            overlayDirty = true;
            if (sweetle.CoalProduced <= stored + 0.001f)
            {
                Log(sweetle.Name + " ate sulfur and rubbed crops.");
            }

            return true;
        }

        private float ConsumeSweetleSulfur(Vector2Int center, float amount, int radius)
        {
            float consumed = 0f;
            Vector2Int sulfurCell = new Vector2Int(-1, -1);
            float bestScore = -1f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || looseResourceKind[x, y] != LooseResourceKind.Sulfur || looseResourceAmount[x, y] <= 0.01f)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > radius || !CanCritterMoveTo(CritterKind.Sweetle, new Vector2Int(x, y)))
                    {
                        continue;
                    }

                    float score = looseResourceAmount[x, y] - distance * 0.08f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        sulfurCell = new Vector2Int(x, y);
                    }
                }
            }

            if (sulfurCell.x >= 0)
            {
                consumed = Mathf.Min(amount, looseResourceAmount[sulfurCell.x, sulfurCell.y]);
                looseResourceAmount[sulfurCell.x, sulfurCell.y] = Mathf.Max(0f, looseResourceAmount[sulfurCell.x, sulfurCell.y] - consumed);
                if (looseResourceAmount[sulfurCell.x, sulfurCell.y] <= 0.01f)
                {
                    looseResourceKind[sulfurCell.x, sulfurCell.y] = LooseResourceKind.None;
                    looseResourceAmount[sulfurCell.x, sulfurCell.y] = 0f;
                }
            }

            if (consumed < amount)
            {
                consumed += ConsumeDryResource(LooseResourceKind.Sulfur, amount - consumed);
            }

            return consumed;
        }

        private bool TryFindSweetleSulfurMoveCell(HatchCritter sweetle, out Vector2Int targetCell)
        {
            targetCell = sweetle.Cell;
            float bestScore = SweetleMoveScore(sweetle.Cell);
            Vector2Int[] candidates =
            {
                sweetle.Cell,
                sweetle.TargetCell,
                new Vector2Int(sweetle.Cell.x + 1, sweetle.Cell.y),
                new Vector2Int(sweetle.Cell.x - 1, sweetle.Cell.y),
                new Vector2Int(sweetle.Cell.x, sweetle.Cell.y + 1),
                new Vector2Int(sweetle.Cell.x, sweetle.Cell.y - 1),
                new Vector2Int(sweetle.Cell.x + 1, sweetle.Cell.y + 1),
                new Vector2Int(sweetle.Cell.x - 1, sweetle.Cell.y + 1),
                new Vector2Int(sweetle.Cell.x + 1, sweetle.Cell.y - 1),
                new Vector2Int(sweetle.Cell.x - 1, sweetle.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Sweetle, candidate))
                {
                    continue;
                }

                float score = SweetleMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    targetCell = candidate;
                }
            }

            return targetCell != sweetle.Cell && bestScore > 0.20f;
        }

        private float SweetleMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return SulfurAround(cell, SweetleSulfurSearchRange) * 0.28f +
                CropCellsAround(cell, GrubgrubCropSearchRange) * 0.08f +
                TendableCropCellsAround(cell, GrubgrubCropSearchRange) * 0.12f +
                SweetleHabitatComfort(cell);
        }

        private float SulfurAround(Vector2Int center, int radius)
        {
            float total = sulfur * 0.20f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (looseResourceKind[x, y] == LooseResourceKind.Sulfur)
                    {
                        total += Mathf.Max(0f, looseResourceAmount[x, y]);
                    }
                }
            }

            return total;
        }

        private int CropCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (IsCropKind(cells[x, y]))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int TendableCropCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (IsCropKind(cells[x, y]) && plantGrowth[x, y] < 1f && cropTendedSeconds[x, y] <= 5f)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TryFeedCuddlePip(HatchCritter cuddlePip)
        {
            if (!CanCritterMoveTo(CritterKind.CuddlePip, cuddlePip.Cell))
            {
                cuddlePip.Happiness = Mathf.Max(0f, cuddlePip.Happiness - 3.4f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.72f, 1.22f, Mathf.Clamp01(cuddlePip.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(cuddlePip.Cell, CuddlePipStableBoostMultiplier);
            float groomScale = cuddlePip.GroomedSeconds > 0f ? 1.16f : 0.78f;
            float looseBoostSeconds = CuddlePipLooseEggBoostSeconds * happinessScale * stableScale * groomScale;
            float incubatorBoostSeconds = CuddlePipIncubatorBoostSeconds * happinessScale * stableScale * groomScale;
            if (!TryApplyCuddlePipBoost(cuddlePip.Cell, looseBoostSeconds, incubatorBoostSeconds, out float looseBoosted, out float incubatorBoosted))
            {
                cuddlePip.Happiness = Mathf.Max(0f, cuddlePip.Happiness - 3.0f);
                return false;
            }

            cuddlePip.FoodConsumed += 1f;
            cuddlePip.CoalProduced += looseBoosted;
            cuddlePip.PlasticProduced += incubatorBoosted;
            cuddlePip.Happiness = Mathf.Min(100f, cuddlePip.Happiness + 3.2f);
            terrainDirty = true;
            overlayDirty = true;
            if (cuddlePip.FoodConsumed <= 1.001f)
            {
                Log(cuddlePip.Name + " cuddled eggs toward hatching.");
            }

            return true;
        }

        private bool TryApplyCuddlePipBoost(Vector2Int center, float looseBoostSeconds, float incubatorBoostSeconds, out float looseBoosted, out float incubatorBoosted)
        {
            looseBoosted = 0f;
            incubatorBoosted = 0f;
            Vector2Int target = new Vector2Int(-1, -1);
            bool targetIncubator = false;
            float bestScore = 0.08f;
            for (int dy = -CuddlePipEggSearchRange; dy <= CuddlePipEggSearchRange; dy++)
            {
                for (int dx = -CuddlePipEggSearchRange; dx <= CuddlePipEggSearchRange; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (!IsInside(x, y) || distance > CuddlePipEggSearchRange)
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.Incubator && incubatorEggLoaded[x, y] && incubatorEggProgress[x, y] < 1f)
                    {
                        float score = 1.20f + (1f - incubatorEggProgress[x, y]) - distance * 0.03f;
                        if (score > bestScore)
                        {
                            bestScore = score;
                            target = new Vector2Int(x, y);
                            targetIncubator = true;
                        }
                    }

                    if (looseResourceKind[x, y] == LooseResourceKind.HatchEgg &&
                        looseResourceAmount[x, y] > 0.001f &&
                        hatchEggAge[x, y] < HatchEggIncubationSeconds)
                    {
                        float score = 0.70f + (1f - hatchEggAge[x, y] / HatchEggIncubationSeconds) - distance * 0.03f;
                        if (score > bestScore)
                        {
                            bestScore = score;
                            target = new Vector2Int(x, y);
                            targetIncubator = false;
                        }
                    }
                }
            }

            if (target.x < 0)
            {
                return false;
            }

            if (targetIncubator)
            {
                float before = incubatorEggProgress[target.x, target.y];
                incubatorEggProgress[target.x, target.y] = Mathf.Clamp01(before + incubatorBoostSeconds / HatchEggIncubationSeconds);
                incubatorBoosted = Mathf.Max(0f, incubatorEggProgress[target.x, target.y] - before) * HatchEggIncubationSeconds;
                TryCompleteIncubatorHatch(target);
                return incubatorBoosted > 0.001f;
            }

            float oldAge = hatchEggAge[target.x, target.y];
            hatchEggAge[target.x, target.y] = Mathf.Min(HatchEggIncubationSeconds, oldAge + looseBoostSeconds);
            looseBoosted = Mathf.Max(0f, hatchEggAge[target.x, target.y] - oldAge);
            return looseBoosted > 0.001f;
        }

        private bool TryFindCuddlePipEggMoveCell(HatchCritter cuddlePip, out Vector2Int eggCell)
        {
            eggCell = cuddlePip.Cell;
            float bestScore = CuddlePipEggMoveScore(cuddlePip.Cell);
            Vector2Int[] candidates =
            {
                cuddlePip.Cell,
                cuddlePip.TargetCell,
                new Vector2Int(cuddlePip.Cell.x + 1, cuddlePip.Cell.y),
                new Vector2Int(cuddlePip.Cell.x - 1, cuddlePip.Cell.y),
                new Vector2Int(cuddlePip.Cell.x, cuddlePip.Cell.y + 1),
                new Vector2Int(cuddlePip.Cell.x, cuddlePip.Cell.y - 1),
                new Vector2Int(cuddlePip.Cell.x + 1, cuddlePip.Cell.y + 1),
                new Vector2Int(cuddlePip.Cell.x - 1, cuddlePip.Cell.y + 1),
                new Vector2Int(cuddlePip.Cell.x + 1, cuddlePip.Cell.y - 1),
                new Vector2Int(cuddlePip.Cell.x - 1, cuddlePip.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.CuddlePip, candidate))
                {
                    continue;
                }

                float score = CuddlePipEggMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    eggCell = candidate;
                }
            }

            return eggCell != cuddlePip.Cell && bestScore > 0.18f;
        }

        private float CuddlePipEggMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return EggTargetsAround(cell, CuddlePipEggSearchRange) * 0.32f +
                ArborTreesAround(cell, PipArborSearchRange) * 0.05f +
                ForestPocketCellsAround(cell, 5) * 0.012f +
                CuddlePipHabitatComfort(cell);
        }

        private int EggTargetsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.Incubator && incubatorEggLoaded[x, y] && incubatorEggProgress[x, y] < 1f)
                    {
                        count++;
                    }

                    if (looseResourceKind[x, y] == LooseResourceKind.HatchEgg &&
                        looseResourceAmount[x, y] > 0.001f &&
                        hatchEggAge[x, y] < HatchEggIncubationSeconds)
                    {
                        count += Mathf.Max(1, Mathf.RoundToInt(looseResourceAmount[x, y]));
                    }
                }
            }

            return count;
        }

        private bool TryFeedShoveVole(HatchCritter shoveVole)
        {
            if (!CanCritterMoveTo(CritterKind.ShoveVole, shoveVole.Cell))
            {
                shoveVole.Happiness = Mathf.Max(0f, shoveVole.Happiness - 3.8f);
                return false;
            }

            float happinessScale = Mathf.Lerp(0.78f, 1.18f, Mathf.Clamp01(shoveVole.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(shoveVole.Cell, ShoveVoleStableClearingMultiplier);
            float groomScale = shoveVole.GroomedSeconds > 0f ? 1.12f : 0.78f;
            float clearingAmount = ShoveVoleRegolithMeal * happinessScale * stableScale * groomScale;
            if (!TryConsumeShoveVoleRegolith(shoveVole.Cell, clearingAmount, out float consumed))
            {
                shoveVole.Happiness = Mathf.Max(0f, shoveVole.Happiness - 3.2f);
                return false;
            }

            shoveVole.FoodConsumed += consumed;
            shoveVole.CoalProduced += 1f;
            shoveVole.Happiness = Mathf.Min(100f, shoveVole.Happiness + 3.0f);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            if (shoveVole.CoalProduced <= 1.001f)
            {
                Log(shoveVole.Name + " burrowed through regolith.");
            }

            return true;
        }

        private bool TryConsumeShoveVoleRegolith(Vector2Int center, float clearingAmount, out float consumed)
        {
            consumed = 0f;
            Vector2Int target = new Vector2Int(-1, -1);
            float bestScore = 0.08f;
            for (int dy = -ShoveVoleRegolithSearchRange; dy <= ShoveVoleRegolithSearchRange; dy++)
            {
                for (int dx = -ShoveVoleRegolithSearchRange; dx <= ShoveVoleRegolithSearchRange; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (!IsInside(x, y) || distance > ShoveVoleRegolithSearchRange || cells[x, y] != CellKind.Regolith)
                    {
                        continue;
                    }

                    bool adjacentOpen = IsPassable(x + 1, y) ||
                        IsPassable(x - 1, y) ||
                        IsPassable(x, y + 1) ||
                        IsPassable(x, y - 1);
                    float surfaceScore = Mathf.InverseLerp(WorldHeight - 18, WorldHeight - 3, y) * 0.24f;
                    float score = 1f + surfaceScore + (adjacentOpen ? 0.35f : 0f) - distance * 0.035f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        target = new Vector2Int(x, y);
                    }
                }
            }

            if (target.x < 0)
            {
                return false;
            }

            int targetX = target.x;
            int targetY = target.y;
            cells[targetX, targetY] = CellKind.Empty;
            equipmentCondition[targetX, targetY] = 0f;
            buildingDisabled[targetX, targetY] = false;
            looseResourceKind[targetX, targetY] = LooseResourceKind.None;
            looseResourceAmount[targetX, targetY] = 0f;
            hatchEggAge[targetX, targetY] = 0f;
            oxygen[targetX, targetY] = NeighborAverage(oxygen, targetX, targetY, 0.12f);
            carbonDioxide[targetX, targetY] = NeighborAverage(carbonDioxide, targetX, targetY, 0.04f);
            pollutedOxygen[targetX, targetY] = NeighborAverage(pollutedOxygen, targetX, targetY, 0f);
            hydrogen[targetX, targetY] = NeighborAverage(hydrogen, targetX, targetY, 0f);
            chlorine[targetX, targetY] = NeighborAverage(chlorine, targetX, targetY, 0f);
            naturalGas[targetX, targetY] = NeighborAverage(naturalGas, targetX, targetY, 0f);
            sourGas[targetX, targetY] = NeighborAverage(sourGas, targetX, targetY, 0f);
            consumed = Mathf.Max(0.1f, clearingAmount);
            meteorRegolithCleared += consumed;
            InvalidateRooms();
            return true;
        }

        private bool TryFindShoveVoleRegolithMoveCell(HatchCritter shoveVole, out Vector2Int regolithCell)
        {
            regolithCell = shoveVole.Cell;
            float bestScore = ShoveVoleRegolithMoveScore(shoveVole.Cell);
            Vector2Int[] candidates =
            {
                shoveVole.Cell,
                shoveVole.TargetCell,
                new Vector2Int(shoveVole.Cell.x + 1, shoveVole.Cell.y),
                new Vector2Int(shoveVole.Cell.x - 1, shoveVole.Cell.y),
                new Vector2Int(shoveVole.Cell.x, shoveVole.Cell.y + 1),
                new Vector2Int(shoveVole.Cell.x, shoveVole.Cell.y - 1),
                new Vector2Int(shoveVole.Cell.x + 1, shoveVole.Cell.y + 1),
                new Vector2Int(shoveVole.Cell.x - 1, shoveVole.Cell.y + 1),
                new Vector2Int(shoveVole.Cell.x + 1, shoveVole.Cell.y - 1),
                new Vector2Int(shoveVole.Cell.x - 1, shoveVole.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.ShoveVole, candidate))
                {
                    continue;
                }

                float score = ShoveVoleRegolithMoveScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    regolithCell = candidate;
                }
            }

            return regolithCell != shoveVole.Cell && bestScore > 0.20f;
        }

        private float ShoveVoleRegolithMoveScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return RegolithCellsAround(cell, ShoveVoleRegolithSearchRange) * 0.16f +
                ShoveVoleHabitatComfort(cell);
        }

        private int RegolithCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.Regolith)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private float ShineBugGlowTargetScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return 0f;
            }

            float score = Mathf.Clamp01(oxygen[cell.x, cell.y] + hydrogen[cell.x, cell.y]);
            for (int dy = -2; dy <= 2; dy++)
            {
                for (int dx = -2; dx <= 2; dx++)
                {
                    int x = cell.x + dx;
                    int y = cell.y + dy;
                    if (!IsInside(x, y))
                    {
                        continue;
                    }

                    CellKind kind = cells[x, y];
                    if (IsCropKind(kind))
                    {
                        score += 0.20f;
                    }
                    else if (kind == CellKind.Bed ||
                        kind == CellKind.ComfyBed ||
                        kind == CellKind.MessTable ||
                        kind == CellKind.ResearchStation ||
                        kind == CellKind.MicrobeMusher ||
                        kind == CellKind.RanchingStation ||
                        kind == CellKind.FarmStation)
                    {
                        score += 0.14f;
                    }
                }
            }

            for (int i = 0; i < workers.Count; i++)
            {
                Worker worker = workers[i];
                if (worker != null && worker.Health > 0f && Mathf.Abs(worker.Cell.x - cell.x) + Mathf.Abs(worker.Cell.y - cell.y) <= ShineBugLightRadius)
                {
                    score += 0.18f;
                }
            }

            return score;
        }

        private bool IsShineBugGlowing(HatchCritter shineBug)
        {
            return shineBug != null &&
                shineBug.Kind == CritterKind.ShineBug &&
                shineBug.Happiness >= ShineBugGlowHappinessThreshold &&
                CanCritterMoveTo(CritterKind.ShineBug, shineBug.Cell);
        }

        private float ShineBugLightScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float score = 0f;
            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter shineBug = hatches[i];
                if (!IsShineBugGlowing(shineBug))
                {
                    continue;
                }

                int distance = Mathf.Abs(shineBug.Cell.x - x) + Mathf.Abs(shineBug.Cell.y - y);
                if (distance > ShineBugLightRadius)
                {
                    continue;
                }

                score += Mathf.Lerp(0.12f, 1f, 1f - distance / (float)(ShineBugLightRadius + 1));
            }

            return Mathf.Clamp01(score);
        }

        private bool TryFeedMorb(HatchCritter morb)
        {
            float localPressure = TileGasTotal(morb.Cell.x, morb.Cell.y);
            if (localPressure >= GasVentMaxPressure)
            {
                morb.Happiness = Mathf.Max(0f, morb.Happiness - 2.5f);
                return false;
            }

            int pollutionSources = PollutionSourceCellsAround(morb.Cell, MorbPollutionSearchRange);
            float pressureScale = Mathf.Clamp01((GasVentMaxPressure - localPressure) / GasVentMaxPressure);
            float sourceScale = Mathf.Lerp(0.72f, 1.28f, Mathf.Clamp01(pollutionSources / 4f));
            float groomScale = morb.GroomedSeconds > 0f ? 0.58f : 1f;
            float emission = MorbPollutedOxygenEmission * pressureScale * sourceScale * groomScale;
            float emitted = VentPollutedOxygen(morb.Cell, emission, MorbGermEmission * sourceScale * groomScale);
            if (emitted <= 0.001f)
            {
                morb.Happiness = Mathf.Max(0f, morb.Happiness - 2.5f);
                return false;
            }

            float germsProduced = emitted * (0.12f + 0.08f * sourceScale);
            morb.PollutedOxygenProduced += emitted;
            morb.GermsProduced += germsProduced;
            morbPollutedOxygenProduced += emitted;
            morbGermsProduced += germsProduced;
            morb.Happiness = Mathf.Min(100f, morb.Happiness + (pollutionSources > 0 ? 2.5f : 0.5f));
            gasDirty = true;
            overlayDirty = true;
            if (morb.PollutedOxygenProduced <= emitted + 0.001f)
            {
                Log(morb.Name + " released germy polluted oxygen.");
            }

            return true;
        }

        private bool TryFindMorbPollutionMoveCell(HatchCritter morb, out Vector2Int pollutionCell)
        {
            pollutionCell = morb.Cell;
            float bestScore = MorbPollutionScore(morb.Cell);
            Vector2Int[] candidates =
            {
                morb.Cell,
                morb.TargetCell,
                new Vector2Int(morb.Cell.x + 1, morb.Cell.y),
                new Vector2Int(morb.Cell.x - 1, morb.Cell.y),
                new Vector2Int(morb.Cell.x, morb.Cell.y + 1),
                new Vector2Int(morb.Cell.x, morb.Cell.y - 1),
                new Vector2Int(morb.Cell.x + 1, morb.Cell.y + 1),
                new Vector2Int(morb.Cell.x - 1, morb.Cell.y + 1),
                new Vector2Int(morb.Cell.x + 1, morb.Cell.y - 1),
                new Vector2Int(morb.Cell.x - 1, morb.Cell.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanCritterMoveTo(CritterKind.Morb, candidate))
                {
                    continue;
                }

                float score = MorbPollutionScore(candidate);
                if (score > bestScore)
                {
                    bestScore = score;
                    pollutionCell = candidate;
                }
            }

            return pollutionCell != morb.Cell && bestScore > 0.08f;
        }

        private float MorbPollutionScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return pollutedOxygen[cell.x, cell.y] * 8f +
                germs[cell.x, cell.y] +
                PollutionSourceCellsAround(cell, 2) * 0.24f;
        }

        private bool TryFeedDrecko(HatchCritter drecko)
        {
            if (TryConsumeDreckoCrop(drecko.Cell, out float plantConsumed))
            {
                CompleteDreckoMeal(drecko, plantConsumed, 3.8f);
                return true;
            }

            if (TryFeedDreckoFromFeeder(drecko))
            {
                return true;
            }

            drecko.Happiness = Mathf.Max(0f, drecko.Happiness - 3.5f);
            return false;
        }

        private bool TryConsumeDreckoCrop(Vector2Int center, out float consumed)
        {
            consumed = 0f;
            Vector2Int crop = new Vector2Int(-1, -1);
            float bestScore = 0.10f;
            for (int dy = -DreckoPlantSearchRange; dy <= DreckoPlantSearchRange; dy++)
            {
                for (int dx = -DreckoPlantSearchRange; dx <= DreckoPlantSearchRange; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsDreckoFeedCropKind(cells[x, y]))
                    {
                        continue;
                    }

                    float growth = plantGrowth[x, y];
                    if (growth <= 0.10f)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    float score = growth - distance * 0.025f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        crop = new Vector2Int(x, y);
                    }
                }
            }

            if (crop.x < 0)
            {
                return false;
            }

            consumed = Mathf.Min(DreckoPlantBite, Mathf.Max(0f, plantGrowth[crop.x, crop.y] - 0.02f));
            if (consumed <= 0.01f)
            {
                return false;
            }

            plantGrowth[crop.x, crop.y] = Mathf.Max(0f, plantGrowth[crop.x, crop.y] - consumed);
            cropStress[crop.x, crop.y] = Mathf.Min(CropWiltThresholdSeconds, cropStress[crop.x, crop.y] + consumed * 1.5f);
            terrainDirty = true;
            overlayDirty = true;
            return true;
        }

        private bool TryFeedDreckoFromFeeder(HatchCritter drecko)
        {
            if (algae <= 0.05f || !TryFindHatchFeeder(drecko, out Vector2Int feederCell) || !IsInside(feederCell.x, feederCell.y))
            {
                return false;
            }

            float eaten = ConsumeDryResource(LooseResourceKind.Algae, Mathf.Min(DreckoAlgaeFeedAmount, algae));
            if (eaten <= 0.05f)
            {
                return false;
            }

            hatchFeederMeals++;
            hatchFeederFoodConsumed += eaten;
            CompleteDreckoMeal(drecko, eaten / DreckoAlgaeFeedAmount * DreckoAlgaeFeedUnits, 3.2f);
            return true;
        }

        private void CompleteDreckoMeal(HatchCritter drecko, float feedUnits, float happinessGain)
        {
            drecko.FoodConsumed += feedUnits;
            dreckoFoodConsumed += feedUnits;
            drecko.Happiness = Mathf.Min(100f, drecko.Happiness + happinessGain);
            if (DryResourceFreeSpace() <= 0.001f)
            {
                terrainDirty = true;
                overlayDirty = true;
                return;
            }

            float happinessScale = Mathf.Lerp(0.68f, 1.25f, Mathf.Clamp01(drecko.Happiness / 100f));
            float stableScale = StableCritterProductionMultiplier(drecko.Cell, StableDreckoPlasticMultiplier);
            float groomScale = drecko.GroomedSeconds > 0f ? 1.18f : 0.52f;
            bool hydrogenCoated = HydrogenAround(drecko.Cell, 3) >= DreckoHydrogenThreshold;
            float hydrogenScale = hydrogenCoated ? DreckoHydrogenPlasticMultiplier : 0.45f;
            float produced = feedUnits * DreckoPlasticYield * happinessScale * stableScale * groomScale * hydrogenScale;
            float stored = StoreDryResource(ref plastic, produced);
            float fiberProduced = feedUnits * DreckoReedFiberYield * happinessScale * stableScale * groomScale * (hydrogenCoated ? DreckoHydrogenReedFiberMultiplier : 1f);
            float storedFiber = StoreDryResource(ref reedFiber, fiberProduced);
            drecko.PlasticProduced += stored;
            dreckoPlasticProduced += stored;
            dreckoReedFiberProduced += storedFiber;
            AddHeat(drecko.Cell, 0.03f * Mathf.Max(0.1f, feedUnits), 1);
            terrainDirty = true;
            overlayDirty = true;
            if (stored > 0.001f && drecko.PlasticProduced <= stored + 0.001f)
            {
                Log(drecko.Name + " shed glossy scales into plastic.");
            }
            else if (storedFiber > 0.001f && dreckoReedFiberProduced <= storedFiber + 0.001f)
            {
                Log(drecko.Name + " shed reed fiber.");
            }
        }

        private bool TryFindDreckoGrazingTarget(HatchCritter drecko, out Vector2Int grazeCell)
        {
            grazeCell = drecko.Cell;
            float bestScore = float.MinValue;
            for (int dy = -DreckoPlantSearchRange; dy <= DreckoPlantSearchRange; dy++)
            {
                for (int dx = -DreckoPlantSearchRange; dx <= DreckoPlantSearchRange; dx++)
                {
                    int x = drecko.Cell.x + dx;
                    int y = drecko.Cell.y + dy;
                    if (!IsInside(x, y) || !IsDreckoFeedCropKind(cells[x, y]) || plantGrowth[x, y] <= 0.10f)
                    {
                        continue;
                    }

                    if (!TryFindDreckoStandNearCrop(new Vector2Int(x, y), out Vector2Int standCell))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(drecko.Cell.x - standCell.x) + Mathf.Abs(drecko.Cell.y - standCell.y);
                    float score = plantGrowth[x, y] * 3f + HydrogenAround(standCell, 3) - distance * 0.05f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        grazeCell = standCell;
                    }
                }
            }

            if (grazeCell != drecko.Cell)
            {
                return true;
            }

            if (algae > 0.05f && TryFindHatchFeeder(drecko, out Vector2Int feederCell) && IsPassable(feederCell.x, feederCell.y))
            {
                grazeCell = feederCell;
                return true;
            }

            return false;
        }

        private bool TryFindDreckoStandNearCrop(Vector2Int crop, out Vector2Int standCell)
        {
            Vector2Int[] offsets =
            {
                new Vector2Int(0, 1),
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, -1),
                new Vector2Int(1, 1),
                new Vector2Int(-1, 1),
                new Vector2Int(1, -1),
                new Vector2Int(-1, -1)
            };

            for (int i = 0; i < offsets.Length; i++)
            {
                Vector2Int candidate = crop + offsets[i];
                if (CanCritterMoveTo(CritterKind.Drecko, candidate))
                {
                    standCell = candidate;
                    return true;
                }
            }

            standCell = new Vector2Int(-1, -1);
            return false;
        }

        private bool TryFindHatchFoodCell(HatchCritter hatch, out Vector2Int foodCell)
        {
            foodCell = new Vector2Int(-1, -1);
            if (hatch.Kind != CritterKind.Hatch)
            {
                return false;
            }

            Vector2Int[] candidates =
            {
                hatch.Cell,
                hatch.TargetCell,
                new Vector2Int(hatch.Cell.x + 1, hatch.Cell.y),
                new Vector2Int(hatch.Cell.x - 1, hatch.Cell.y),
                new Vector2Int(hatch.Cell.x, hatch.Cell.y + 1),
                new Vector2Int(hatch.Cell.x, hatch.Cell.y - 1)
            };

            float bestAmount = 0.05f;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !IsHatchEdible(looseResourceKind[candidate.x, candidate.y]))
                {
                    continue;
                }

                float amount = looseResourceAmount[candidate.x, candidate.y];
                if (amount <= bestAmount)
                {
                    continue;
                }

                bestAmount = amount;
                foodCell = candidate;
            }

            return foodCell.x >= 0;
        }

        private bool IsHatchEdible(LooseResourceKind kind)
        {
            return kind == LooseResourceKind.Dirt ||
                kind == LooseResourceKind.Algae ||
                kind == LooseResourceKind.PollutedDirt;
        }

        private bool TryFindHatchFeeder(HatchCritter hatch, out Vector2Int feederCell)
        {
            feederCell = new Vector2Int(-1, -1);
            if (hatch == null || HatchFeedStorageAmount() <= 0.05f)
            {
                return false;
            }

            int bestDistance = int.MaxValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int candidate = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.CritterFeeder ||
                        !CanUseEquipment(candidate) ||
                        !IsCritterFeederInRange(hatch.Cell, candidate))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(hatch.Cell.x - x) + Mathf.Abs(hatch.Cell.y - y);
                    if (distance < bestDistance)
                    {
                        bestDistance = distance;
                        feederCell = candidate;
                    }
                }
            }

            return feederCell.x >= 0;
        }

        private bool IsCritterFeederInRange(Vector2Int hatchCell, Vector2Int feederCell)
        {
            RoomInfo hatchRoom = RoomAt(hatchCell.x, hatchCell.y);
            RoomInfo feederRoom = RoomAt(feederCell.x, feederCell.y);
            if (hatchRoom != null && feederRoom != null && hatchRoom.Id == feederRoom.Id && hatchRoom.Enclosed)
            {
                return true;
            }

            return Mathf.Abs(hatchCell.x - feederCell.x) + Mathf.Abs(hatchCell.y - feederCell.y) <= CritterFeederRange;
        }

        private bool TrySelectHatchFeedResource(out LooseResourceKind kind, out float amount)
        {
            kind = LooseResourceKind.None;
            amount = 0f;
            TrySelectDryResourceCandidate(LooseResourceKind.Dirt, dirt, ref kind, ref amount);
            TrySelectDryResourceCandidate(LooseResourceKind.PollutedDirt, pollutedDirt, ref kind, ref amount);
            TrySelectDryResourceCandidate(LooseResourceKind.Algae, algae, ref kind, ref amount);
            return kind != LooseResourceKind.None && amount > 0.05f;
        }

        private float HatchFeedStorageAmount()
        {
            return dirt + pollutedDirt + algae;
        }

        private bool HasHatchFeedAvailable()
        {
            return HasHatchEdibleDebris() ||
                (HatchFeedStorageAmount() > 0.05f && HasUsableCritterFeederFor(CritterKind.Hatch));
        }

        private bool HasUsableCritterFeederFor(CritterKind kind)
        {
            if (kind == CritterKind.Hatch && HatchFeedStorageAmount() <= 0.05f)
            {
                return false;
            }

            if (kind == CritterKind.Drecko && algae <= 0.05f)
            {
                return false;
            }

            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == kind && TryFindHatchFeeder(hatches[i], out _))
                {
                    return true;
                }
            }

            return false;
        }

        private int CountHatchesForFeeder(Vector2Int feederCell)
        {
            int count = 0;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.Hatch && IsCritterFeederInRange(hatches[i].Cell, feederCell))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountDreckosForFeeder(Vector2Int feederCell)
        {
            int count = 0;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.Drecko && IsCritterFeederInRange(hatches[i].Cell, feederCell))
                {
                    count++;
                }
            }

            return count;
        }

        private string CritterFeederReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.CritterFeeder)
            {
                return "Critter feeder blocked: feeder missing.";
            }

            if (!techFoodPreparation)
            {
                return "Critter feeder blocked: research Food Preparation.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Critter feeder blocked: needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Critter feeder blocked: feeder is submerged.";
            }

            int nearbyHatches = CountHatchesForFeeder(cell);
            int nearbyDreckos = CountDreckosForFeeder(cell);
            if (nearbyHatches == 0 && nearbyDreckos == 0)
            {
                return "Critter feeder idle: no hatches or dreckos in range.";
            }

            bool canFeedHatches = nearbyHatches > 0 && HatchFeedStorageAmount() > 0.05f;
            bool canFeedDreckos = nearbyDreckos > 0 && algae > 0.05f;
            if (canFeedHatches && canFeedDreckos)
            {
                return "Critter feeder ready: can feed nearby hatches and dreckos.";
            }

            if (canFeedHatches)
            {
                return "Critter feeder ready: can feed nearby hatches.";
            }

            if (canFeedDreckos)
            {
                return "Critter feeder ready: can feed nearby dreckos.";
            }

            if (nearbyHatches > 0 && nearbyDreckos == 0)
            {
                return "Critter feeder blocked: needs dirt, algae, or polluted dirt for nearby hatches.";
            }

            if (nearbyDreckos > 0 && nearbyHatches == 0)
            {
                return "Critter feeder blocked: needs algae for nearby dreckos.";
            }

            return "Critter feeder blocked: needs hatch or drecko feed stock.";
        }

        private HatchCritter HatchAt(Vector2Int cell)
        {
            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                if (hatch.Cell == cell || hatch.TargetCell == cell)
                {
                    return hatch;
                }
            }

            return null;
        }

        private HatchCritter FindCritterByName(string critterName)
        {
            if (string.IsNullOrEmpty(critterName))
            {
                return null;
            }

            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                if (hatch != null && hatch.Name == critterName)
                {
                    return hatch;
                }
            }

            return null;
        }

        private HatchCritter CritterTargetForJob(Job job)
        {
            if (job == null)
            {
                return null;
            }

            HatchCritter namedTarget = FindCritterByName(job.TargetCritterName);
            return namedTarget ?? HatchAt(job.Cell);
        }

        private HatchCritter ButcherTargetForJob(Job job)
        {
            return CritterTargetForJob(job);
        }

        private HatchCritter WrangleTargetForJob(Job job)
        {
            return CritterTargetForJob(job);
        }

        private bool TryGetCritterJobTargetCell(Job job, out Vector2Int cell)
        {
            HatchCritter target = CritterTargetForJob(job);
            if (target != null)
            {
                cell = target.Cell;
                return true;
            }

            cell = job != null ? job.Cell : Vector2Int.zero;
            return false;
        }

        private bool TryGetButcherTargetCell(Job job, out Vector2Int cell)
        {
            return TryGetCritterJobTargetCell(job, out cell);
        }

        private bool TryGetWrangleTargetCell(Job job, out Vector2Int cell)
        {
            return TryGetCritterJobTargetCell(job, out cell);
        }

        private Job FindButcherJobForCritter(HatchCritter critter)
        {
            return FindCritterJobForCritter(critter, JobType.ButcherCritter);
        }

        private Job FindWrangleJobForCritter(HatchCritter critter)
        {
            return FindCritterJobForCritter(critter, JobType.WrangleCritter);
        }

        private Job FindCritterJobForCritter(HatchCritter critter, JobType type)
        {
            if (critter == null)
            {
                return null;
            }

            for (int i = 0; i < jobs.Count; i++)
            {
                Job job = jobs[i];
                if (job == null || job.Cancelled || job.Type != type)
                {
                    continue;
                }

                if (!string.IsNullOrEmpty(job.TargetCritterName))
                {
                    if (job.TargetCritterName == critter.Name)
                    {
                        return job;
                    }
                }
                else if (job.Cell == critter.Cell)
                {
                    return job;
                }
            }

            return null;
        }

        private int CountCritters()
        {
            return hatches.Count;
        }

        private int CountCritters(CritterKind kind)
        {
            int count = 0;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == kind)
                {
                    count++;
                }
            }

            return count;
        }

        private float PipForestFeedConsumed()
        {
            float total = 0f;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.Pip)
                {
                    total += hatches[i].FoodConsumed;
                }
            }

            return total;
        }

        private float PipDirtProduced()
        {
            float total = 0f;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.Pip)
                {
                    total += hatches[i].CoalProduced;
                }
            }

            return total;
        }

        private float PlugSlugPowerGenerated()
        {
            float total = 0f;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.PlugSlug)
                {
                    total += hatches[i].CoalProduced;
                }
            }

            return total;
        }

        private float PlugSlugMetalConsumed()
        {
            float total = 0f;
            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.PlugSlug)
                {
                    total += hatches[i].FoodConsumed;
                }
            }

            return total;
        }

        private float PlugSlugHydrogenProduced()
        {
            float total = 0f;
            for (int i = 0; i < hatches.Count; i++)
            {
