        private bool HasDreckoFeedAvailable()
        {
            if (CountCritters(CritterKind.Drecko) == 0)
            {
                return CountDreckoFeedCrops() > 0 ||
                    (CountUsableCells(CellKind.CritterFeeder) > 0 && algae > 0.05f);
            }

            for (int i = 0; i < hatches.Count; i++)
            {
                if (hatches[i].Kind == CritterKind.Drecko && TryFindDreckoGrazingTarget(hatches[i], out _))
                {
                    return true;
                }
            }

            return HasUsableCritterFeederFor(CritterKind.Drecko);
        }

