                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void SimulateShipping(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.ConveyorLoader && CanPoweredMachineRun(cell))
                    {
                        changed |= RunConveyorLoader(cell, deltaTime);
                    }
                }
            }

            ResetShippingRailMeterFlowBudgets(deltaTime);
            float railStep = deltaTime / 3f;
            for (int i = 0; i < 3; i++)
            {
                changed |= MoveShippingRailPackets(railStep);
                changed |= RunShippingBridges(railStep);
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.ConveyorReceptacle && CanUseEquipment(cell))
                    {
                        changed |= RunConveyorReceptacle(cell, deltaTime);
                    }
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.ConveyorChute && CanUseEquipment(cell))
                    {
                        changed |= RunConveyorChute(cell, deltaTime);
                    }
                }
            }

            if (changed)
            {
                terrainDirty = true;
                overlayDirty = true;
            }
        }

        private bool RunConveyorLoader(Vector2Int loader, float deltaTime)
        {
            StorageFilter filter = ConveyorLoaderFilterAt(loader.x, loader.y);
            if (!TrySelectDryResourceForShipping(filter, out LooseResourceKind kind, out float available) ||
                !TryFindShippingRailWithSpace(loader, kind, out Vector2Int rail))
            {
                return false;
            }

            float requested = ConveyorLoaderTransferRate * deltaTime;
            float target = Mathf.Min(requested, Mathf.Min(available, ShippingRailFreeSpace(rail, kind)));
            if (target <= 0.001f)
            {
                return false;
            }

            float targetPower = ConveyorLoaderPowerRate * deltaTime * (target / Mathf.Max(0.001f, requested));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float consumed = ConsumeDryResource(kind, target * efficiency);
            float loaded = AddShippingRailPacket(rail, kind, consumed);
            if (loaded <= 0.001f)
            {
                StoreLooseResource(kind, consumed);
                return false;
            }

            ConsumeCyclePower(powerUsed * Mathf.Clamp01(loaded / Mathf.Max(0.001f, consumed)));
            if (loaded < consumed)
            {
                StoreLooseResource(kind, consumed - loaded);
            }

            AddHeat(loader, 0.025f * deltaTime * efficiency, 1);
            WearEquipment(loader, 0.00024f * deltaTime * efficiency);
            return true;
        }

        private bool RunConveyorReceptacle(Vector2Int receptacle, float deltaTime)
        {
            StorageFilter filter = ConveyorReceptacleFilterAt(receptacle.x, receptacle.y);
            if (!TryFindAdjacentShippingRailWithPacket(receptacle, filter, out Vector2Int rail))
            {
                return false;
            }

            LooseResourceKind kind = shippingRailKind[rail.x, rail.y];
            float target = Mathf.Min(shippingRailAmount[rail.x, rail.y], ConveyorReceptacleTransferRate * deltaTime);
            float stored = StoreLooseResource(kind, target, false);
            if (stored <= 0.001f)
            {
                return false;
            }

            shippingRailAmount[rail.x, rail.y] = Mathf.Max(0f, shippingRailAmount[rail.x, rail.y] - stored);
            if (shippingRailAmount[rail.x, rail.y] <= 0.001f)
            {
                shippingRailAmount[rail.x, rail.y] = 0f;
                shippingRailKind[rail.x, rail.y] = LooseResourceKind.None;
            }

            conveyorShippedResources += stored;
            milestoneShippingLogistics |= techAutomationLogistics && conveyorShippedResources >= 6f;
            WearEquipment(receptacle, 0.00004f * deltaTime);
            return true;
        }

        private bool MoveShippingRailPackets(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return false;
            }

            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!shippingRail[x, y] || shippingRailAmount[x, y] <= 0.001f || shippingRailKind[x, y] == LooseResourceKind.None)
                    {
                        continue;
                    }

                    Vector2Int rail = new Vector2Int(x, y);
                    if (IsClosedShippingRailShutoff(rail) || IsClosedShippingRailMeter(rail))
                    {
                        continue;
                    }

                    LooseResourceKind kind = shippingRailKind[x, y];
                    if (!TryFindNextShippingRailTowardDestination(rail, kind, out Vector2Int nextRail))
                    {
                        continue;
                    }

                    float move = Mathf.Min(shippingRailAmount[x, y], Mathf.Min(ShippingRailMoveRate * deltaTime, ShippingRailFreeSpace(nextRail, kind)));
                    move = LimitShippingRailMeterFlow(rail, move);
                    if (move <= 0.001f)
                    {
                        continue;
                    }

                    shippingRailAmount[x, y] = Mathf.Max(0f, shippingRailAmount[x, y] - move);
                    if (shippingRailAmount[x, y] <= 0.001f)
                    {
                        shippingRailAmount[x, y] = 0f;
                        shippingRailKind[x, y] = LooseResourceKind.None;
                    }

                    AddShippingRailPacket(nextRail, kind, move);
                    changed = true;
                }
            }

            return changed;
        }

        private bool IsClosedShippingRailShutoff(Vector2Int rail)
        {
            return IsInside(rail.x, rail.y) &&
                cells[rail.x, rail.y] == CellKind.ShippingRailShutoff &&
                shippingRail[rail.x, rail.y] &&
                !IsShippingRailShutoffOpen(rail);
        }

        private bool IsShippingRailShutoffOpen(Vector2Int rail)
        {
            if (!IsInside(rail.x, rail.y) ||
                cells[rail.x, rail.y] != CellKind.ShippingRailShutoff ||
                !shippingRail[rail.x, rail.y] ||
                !CanUseEquipment(rail))
            {
                return false;
            }

            return AutomationPortAllows(rail);
        }

        private void ResetShippingRailMeterFlowBudgets(float deltaTime)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int rail = new Vector2Int(x, y);
                    shippingRailMeterFlowRemaining[x, y] = IsShippingRailMeterOpen(rail)
                        ? Mathf.Max(0f, ShippingRailMeterFlowLimitAt(x, y) * deltaTime)
                        : 0f;
                }
            }
        }

        private float ShippingRailMeterFlowLimitAt(int x, int y)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.ShippingRailMeter)
            {
                return ShippingRailMeterDefaultFlow;
            }

            return Mathf.Clamp(
                shippingRailMeterFlowLimit[x, y] <= 0.001f ? ShippingRailMeterDefaultFlow : shippingRailMeterFlowLimit[x, y],
                ShippingRailMeterMinFlow,
                ShippingRailMeterMaxFlow);
        }

        private bool IsShippingRailMeter(Vector2Int rail)
        {
            return IsInside(rail.x, rail.y) &&
                cells[rail.x, rail.y] == CellKind.ShippingRailMeter &&
                shippingRail[rail.x, rail.y];
        }

        private bool IsClosedShippingRailMeter(Vector2Int rail)
        {
            return IsShippingRailMeter(rail) && !IsShippingRailMeterOpen(rail);
        }

        private bool IsShippingRailMeterOpen(Vector2Int rail)
        {
            if (!IsShippingRailMeter(rail) || !CanUseEquipment(rail))
            {
                return false;
            }

            return AutomationPortAllows(rail);
        }

        private float LimitShippingRailMeterFlow(Vector2Int from, float amount)
        {
            if (amount <= 0f)
            {
                return 0f;
            }

            if (!IsShippingRailMeter(from))
            {
                return amount;
            }

            if (!IsShippingRailMeterOpen(from))
            {
                return 0f;
            }

            float limited = Mathf.Min(amount, shippingRailMeterFlowRemaining[from.x, from.y]);
            if (limited <= 0.001f)
            {
                return 0f;
            }

            shippingRailMeterFlowRemaining[from.x, from.y] = Mathf.Max(0f, shippingRailMeterFlowRemaining[from.x, from.y] - limited);
            WearEquipment(from, 0.00004f * limited);
            return limited;
        }

        private bool IsDirectionalBridge(CellKind kind)
        {
            return kind == CellKind.PowerBridge ||
                kind == CellKind.AutomationBridge ||
                kind == CellKind.LiquidBridge ||
                kind == CellKind.GasBridge ||
                kind == CellKind.ShippingBridge;
        }

        private bool IsDoorAccessControlledKind(CellKind kind)
        {
            return kind == CellKind.ManualAirlock || kind == CellKind.MechanizedAirlock;
        }

        private DoorAccessMode DoorAccessModeAt(int x, int y)
        {
            if (!IsInside(x, y) || !IsDoorAccessControlledKind(cells[x, y]))
            {
                return DoorAccessMode.Both;
            }

            return doorAccessMode[x, y];
        }

        private DoorAccessMode NextDoorAccessMode(DoorAccessMode mode)
        {
            switch (mode)
            {
                case DoorAccessMode.LeftToRight:
                    return DoorAccessMode.RightToLeft;
                case DoorAccessMode.RightToLeft:
                    return DoorAccessMode.Emergency;
                case DoorAccessMode.Emergency:
                    return DoorAccessMode.Locked;
                case DoorAccessMode.Locked:
                    return DoorAccessMode.Both;
                default:
                    return DoorAccessMode.LeftToRight;
            }
        }

        private string DoorAccessModeName(DoorAccessMode mode)
        {
            switch (mode)
            {
                case DoorAccessMode.LeftToRight:
                    return "left to right";
                case DoorAccessMode.RightToLeft:
                    return "right to left";
                case DoorAccessMode.Emergency:
                    return "emergency only";
                case DoorAccessMode.Locked:
                    return "duplicants locked";
                default:
                    return "both directions";
            }
        }

        private string DoorAccessModeShortName(DoorAccessMode mode)
        {
            switch (mode)
            {
                case DoorAccessMode.LeftToRight:
                    return "L>R";
                case DoorAccessMode.RightToLeft:
                    return "R>L";
                case DoorAccessMode.Emergency:
                    return "EMRG";
                case DoorAccessMode.Locked:
                    return "LOCK";
                default:
                    return "BOTH";
            }
        }

        private bool CanUseDoorAccessControl(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (cells[cell.x, cell.y] == CellKind.ManualAirlock)
            {
                return true;
            }

            return cells[cell.x, cell.y] == CellKind.MechanizedAirlock && CanUseEquipment(cell);
        }

        private bool AnyUsableDoorAccessControl()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseDoorAccessControl(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyRestrictedDoorAccess()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseDoorAccessControl(new Vector2Int(x, y)) && doorAccessMode[x, y] != DoorAccessMode.Both)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private BridgeDirection BridgeDirectionAt(int x, int y)
        {
            if (!IsInside(x, y) || !IsDirectionalBridge(cells[x, y]))
            {
                return BridgeDirection.Right;
            }

            return bridgeDirection[x, y];
        }

        private BridgeDirection DefaultBridgeDirectionForExistingLayout(int x, int y, CellKind kind)
        {
            Vector2Int bridge = new Vector2Int(x, y);
            BridgeDirection[] directions =
            {
                BridgeDirection.Right,
                BridgeDirection.Up,
                BridgeDirection.Left,
                BridgeDirection.Down
            };

            for (int i = 0; i < directions.Length; i++)
            {
                BridgeDirection direction = directions[i];
                Vector2Int input = bridge + BridgeInputOffset(direction);
                Vector2Int output = bridge + BridgeOutputOffset(direction);
                if (HasBridgeEndpointForKind(kind, input) && HasBridgeEndpointForKind(kind, output))
                {
                    return direction;
                }
            }

            return BridgeDirection.Right;
        }

        private bool HasBridgeEndpointForKind(CellKind kind, Vector2Int endpoint)
        {
            if (!IsInside(endpoint.x, endpoint.y))
            {
                return false;
            }

            switch (kind)
            {
                case CellKind.PowerBridge:
                    return powerWire[endpoint.x, endpoint.y];
                case CellKind.AutomationBridge:
                    return automationWire[endpoint.x, endpoint.y];
                case CellKind.LiquidBridge:
                    return liquidPipe[endpoint.x, endpoint.y];
                case CellKind.GasBridge:
                    return gasPipe[endpoint.x, endpoint.y];
                case CellKind.ShippingBridge:
                    return shippingRail[endpoint.x, endpoint.y];
                default:
                    return false;
            }
        }

        private Vector2Int BridgeInputOffset(BridgeDirection direction)
        {
            switch (direction)
            {
                case BridgeDirection.Up:
                    return new Vector2Int(0, -1);
                case BridgeDirection.Left:
                    return new Vector2Int(1, 0);
                case BridgeDirection.Down:
                    return new Vector2Int(0, 1);
                default:
                    return new Vector2Int(-1, 0);
            }
        }

        private Vector2Int BridgeOutputOffset(BridgeDirection direction)
        {
            switch (direction)
            {
                case BridgeDirection.Up:
                    return new Vector2Int(0, 1);
                case BridgeDirection.Left:
                    return new Vector2Int(-1, 0);
                case BridgeDirection.Down:
                    return new Vector2Int(0, -1);
                default:
                    return new Vector2Int(1, 0);
            }
        }

        private string BridgeDirectionName(BridgeDirection direction)
        {
            switch (direction)
            {
                case BridgeDirection.Up:
                    return "South -> North";
                case BridgeDirection.Left:
                    return "East -> West";
                case BridgeDirection.Down:
                    return "North -> South";
                default:
                    return "West -> East";
            }
        }

        private string BridgeDirectionStatusPrefix(BridgeDirection direction)
        {
            switch (direction)
            {
                case BridgeDirection.Up:
                    return "South to north ";
                case BridgeDirection.Left:
                    return "East to west ";
                case BridgeDirection.Down:
                    return "North to south ";
                default:
                    return "West to east ";
            }
        }

        private BridgeDirection RotatedBridgeDirection(BridgeDirection current, int direction)
        {
            int count = Enum.GetValues(typeof(BridgeDirection)).Length;
            int next = ((int)current + direction) % count;
            if (next < 0)
            {
                next += count;
            }

            return (BridgeDirection)next;
        }

        private bool RunShippingBridges(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.ShippingBridge)
                    {
                        continue;
                    }

                    Vector2Int bridge = new Vector2Int(x, y);
                    if (!CanUseEquipment(bridge))
                    {
                        continue;
                    }

                    BridgeDirection direction = BridgeDirectionAt(x, y);
                    bool moved = MoveShippingBridgePair(bridge, BridgeInputOffset(direction), BridgeOutputOffset(direction), deltaTime);
                    if (moved)
                    {
                        WearEquipment(bridge, 0.00004f * deltaTime);
                        changed = true;
                    }
                }
            }

            return changed;
        }

        private bool MoveShippingBridgePair(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, float deltaTime)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsShippingBridgeEndpoint(input) || !IsShippingBridgeEndpoint(output))
            {
                return false;
            }

            if (IsClosedShippingRailShutoff(input) || IsClosedShippingRailShutoff(output) ||
                IsClosedShippingRailMeter(input) || IsClosedShippingRailMeter(output))
            {
                return false;
            }

            LooseResourceKind kind = shippingRailKind[input.x, input.y];
            if (kind == LooseResourceKind.None)
            {
                return false;
            }

            float amount = Mathf.Min(
                ShippingBridgeRate * deltaTime,
                Mathf.Min(shippingRailAmount[input.x, input.y], ShippingRailFreeSpace(output, kind)));
            amount = LimitShippingRailMeterFlow(input, amount);
            float moved = AddShippingRailPacket(output, kind, amount);
            if (moved <= 0.001f)
            {
                return false;
            }

            shippingRailAmount[input.x, input.y] = Mathf.Max(0f, shippingRailAmount[input.x, input.y] - moved);
            if (shippingRailAmount[input.x, input.y] <= 0.001f)
            {
                shippingRailAmount[input.x, input.y] = 0f;
                shippingRailKind[input.x, input.y] = LooseResourceKind.None;
            }

            shippingBridgeMovedMass += moved;
            return true;
        }

        private bool IsShippingBridgeEndpoint(Vector2Int rail)
        {
            return IsInside(rail.x, rail.y) && shippingRail[rail.x, rail.y];
        }

        private bool RunConveyorChute(Vector2Int chute, float deltaTime)
        {
            if (!CanUseEquipment(chute))
            {
                return false;
            }

            if (!TryFindAdjacentShippingRailWithPacket(chute, out Vector2Int rail))
            {
                return false;
            }

            LooseResourceKind kind = shippingRailKind[rail.x, rail.y];
            float amount = Mathf.Min(shippingRailAmount[rail.x, rail.y], ConveyorChuteDropRate * deltaTime);
            float dropped = DropLooseResourceNear(chute, kind, amount);
            if (dropped <= 0.001f)
            {
                return false;
            }

            shippingRailAmount[rail.x, rail.y] = Mathf.Max(0f, shippingRailAmount[rail.x, rail.y] - dropped);
            if (shippingRailAmount[rail.x, rail.y] <= 0.001f)
            {
                shippingRailAmount[rail.x, rail.y] = 0f;
                shippingRailKind[rail.x, rail.y] = LooseResourceKind.None;
            }

            conveyorShippedResources += dropped;
            milestoneShippingLogistics |= techAutomationLogistics && conveyorShippedResources >= 6f;
            return true;
        }

        private StorageFilter ConveyorLoaderFilterAt(int x, int y)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.ConveyorLoader)
            {
                return StorageFilter.All;
            }

            return conveyorLoaderFilter[x, y];
        }

        private StorageFilter ConveyorReceptacleFilterAt(int x, int y)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.ConveyorReceptacle)
            {
                return StorageFilter.All;
            }

            return conveyorReceptacleFilter[x, y];
        }

        private StorageFilter ShippingRailSensorFilterAt(int x, int y)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.ShippingRailSensor)
            {
                return StorageFilter.All;
            }

            return shippingRailSensorFilter[x, y];
        }

        private bool TrySelectDryResourceForShipping(out LooseResourceKind kind, out float amount)
        {
            return TrySelectDryResourceForShipping(StorageFilter.All, out kind, out amount);
        }

        private bool TrySelectDryResourceForShipping(StorageFilter filter, out LooseResourceKind kind, out float amount)
        {
            kind = LooseResourceKind.None;
            amount = 0f;
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Metal, metal, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Coal, coal, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.RefinedMetal, refinedMetal, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Steel, steel, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Ceramic, ceramic, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Glass, glass, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Niobium, niobium, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Thermium, thermium, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Fullerene, fullerene, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.SuperCoolant, superCoolant, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.CryogenicPropellant, cryogenicPropellant, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Algae, algae, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Slime, slime, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.BleachStone, bleachStone, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Plastic, plastic, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.HatchEgg, hatchEggs, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Peppernut, peppernut, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Lumber, lumber, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.ReedFiber, reedFiber, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Sulfur, sulfur, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.WheatGrain, wheatGrain, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.Dirt, dirt, ref kind, ref amount);
            TrySelectDryResourceCandidate(filter, LooseResourceKind.PollutedDirt, pollutedDirt, ref kind, ref amount);
            return kind != LooseResourceKind.None && amount > 0.001f;
        }

        private void TrySelectDryResourceCandidate(StorageFilter filter, LooseResourceKind candidateKind, float candidateAmount, ref LooseResourceKind bestKind, ref float bestAmount)
        {
            if (!StorageFilterAcceptsResource(filter, candidateKind) || candidateAmount <= bestAmount)
            {
                return;
            }

            bestKind = candidateKind;
            bestAmount = candidateAmount;
        }

        private void TrySelectDryResourceCandidate(LooseResourceKind candidateKind, float candidateAmount, ref LooseResourceKind bestKind, ref float bestAmount)
        {
            TrySelectDryResourceCandidate(StorageFilter.All, candidateKind, candidateAmount, ref bestKind, ref bestAmount);
        }

        private float ConsumeDryResource(LooseResourceKind kind, float amount)
        {
            if (amount <= 0f)
            {
                return 0f;
            }

            switch (kind)
            {
                case LooseResourceKind.Dirt:
                    return ConsumeDryResource(ref dirt, amount);
                case LooseResourceKind.Metal:
                    return ConsumeDryResource(ref metal, amount);
                case LooseResourceKind.Algae:
                    return ConsumeDryResource(ref algae, amount);
                case LooseResourceKind.Slime:
                    return ConsumeDryResource(ref slime, amount);
                case LooseResourceKind.BleachStone:
                    return ConsumeDryResource(ref bleachStone, amount);
                case LooseResourceKind.Plastic:
                    return ConsumeDryResource(ref plastic, amount);
                case LooseResourceKind.Coal:
                    return ConsumeDryResource(ref coal, amount);
                case LooseResourceKind.RefinedMetal:
                    return ConsumeDryResource(ref refinedMetal, amount);
                case LooseResourceKind.Steel:
                    return ConsumeDryResource(ref steel, amount);
                case LooseResourceKind.Ceramic:
                    return ConsumeDryResource(ref ceramic, amount);
                case LooseResourceKind.Glass:
                    return ConsumeDryResource(ref glass, amount);
                case LooseResourceKind.Niobium:
                    return ConsumeDryResource(ref niobium, amount);
                case LooseResourceKind.Thermium:
                    return ConsumeDryResource(ref thermium, amount);
                case LooseResourceKind.Fullerene:
                    return ConsumeDryResource(ref fullerene, amount);
                case LooseResourceKind.SuperCoolant:
                    return ConsumeDryResource(ref superCoolant, amount);
                case LooseResourceKind.CryogenicPropellant:
                    return ConsumeDryResource(ref cryogenicPropellant, amount);
                case LooseResourceKind.PollutedDirt:
                    return ConsumeDryResource(ref pollutedDirt, amount);
                case LooseResourceKind.HatchEgg:
                    return ConsumeDryResource(ref hatchEggs, amount);
                case LooseResourceKind.Peppernut:
                    return ConsumeDryResource(ref peppernut, amount);
                case LooseResourceKind.Lumber:
                    return ConsumeDryResource(ref lumber, amount);
                case LooseResourceKind.ReedFiber:
                    return ConsumeDryResource(ref reedFiber, amount);
                case LooseResourceKind.Sulfur:
                    return ConsumeDryResource(ref sulfur, amount);
                case LooseResourceKind.WheatGrain:
                    return ConsumeDryResource(ref wheatGrain, amount);
                default:
                    return 0f;
            }
        }

        private float ConsumeDryResource(ref float resource, float amount)
        {
            float consumed = Mathf.Min(Mathf.Max(0f, resource), Mathf.Max(0f, amount));
            resource = Mathf.Max(0f, resource - consumed);
            return consumed;
        }

        private bool TryFindShippingRailWithSpace(Vector2Int center, LooseResourceKind kind, out Vector2Int rail)
        {
            Vector2Int[] candidates =
            {
                center,
                new Vector2Int(center.x + 1, center.y),
                new Vector2Int(center.x - 1, center.y),
                new Vector2Int(center.x, center.y + 1),
                new Vector2Int(center.x, center.y - 1)
            };

            rail = new Vector2Int(-1, -1);
            float bestSpace = 0f;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (IsClosedShippingRailMeter(candidate))
                {
                    continue;
                }

                float space = ShippingRailFreeSpace(candidate, kind);
                if (space <= bestSpace)
                {
                    continue;
                }

                bestSpace = space;
                rail = candidate;
            }

            return rail.x >= 0;
        }

        private bool TryFindAdjacentShippingRailWithPacket(Vector2Int center, out Vector2Int rail)
        {
            return TryFindAdjacentShippingRailWithPacket(center, StorageFilter.All, out rail);
        }

        private bool TryFindAdjacentShippingRailWithPacket(Vector2Int center, StorageFilter filter, out Vector2Int rail)
        {
            Vector2Int[] candidates =
            {
                center,
                new Vector2Int(center.x + 1, center.y),
                new Vector2Int(center.x - 1, center.y),
                new Vector2Int(center.x, center.y + 1),
                new Vector2Int(center.x, center.y - 1)
            };

            rail = new Vector2Int(-1, -1);
            float bestAmount = 0f;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) ||
                    !shippingRail[candidate.x, candidate.y] ||
                    IsClosedShippingRailMeter(candidate) ||
                    shippingRailKind[candidate.x, candidate.y] == LooseResourceKind.None ||
                    !StorageFilterAcceptsResource(filter, shippingRailKind[candidate.x, candidate.y]) ||
                    shippingRailAmount[candidate.x, candidate.y] <= bestAmount)
                {
                    continue;
                }

                bestAmount = shippingRailAmount[candidate.x, candidate.y];
                rail = candidate;
            }

            return rail.x >= 0;
        }

        private bool TryFindNextShippingRailTowardDestination(Vector2Int rail, LooseResourceKind kind, out Vector2Int nextRail)
        {
            nextRail = new Vector2Int(-1, -1);
            int currentDistance = DistanceToNearestShippingDestination(rail, kind);
            if (currentDistance == int.MaxValue)
            {
                return false;
            }

            Vector2Int[] candidates =
            {
                new Vector2Int(rail.x + 1, rail.y),
                new Vector2Int(rail.x - 1, rail.y),
                new Vector2Int(rail.x, rail.y + 1),
                new Vector2Int(rail.x, rail.y - 1)
            };

            int bestDistance = currentDistance;
            float bestSpace = 0f;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (IsClosedShippingRailShutoff(candidate) || IsClosedShippingRailMeter(candidate))
                {
                    continue;
                }

                float space = ShippingRailFreeSpace(candidate, kind);
                if (space <= 0.001f)
                {
                    continue;
                }

                int distance = DistanceToNearestShippingDestination(candidate, kind);
                if (distance > bestDistance || (distance == bestDistance && space <= bestSpace))
                {
                    continue;
                }

                bestDistance = distance;
                bestSpace = space;
                nextRail = candidate;
            }

            return nextRail.x >= 0 && bestDistance < currentDistance;
        }

        private int DistanceToNearestShippingDestination(Vector2Int cell, LooseResourceKind kind)
        {
            int best = int.MaxValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.ConveyorChute &&
                        (cells[x, y] != CellKind.ConveyorReceptacle || !StorageFilterAcceptsResource(ConveyorReceptacleFilterAt(x, y), kind)))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(cell.x - x) + Mathf.Abs(cell.y - y);
                    if (distance < best)
                    {
                        best = distance;
                    }
                }
            }

            return best;
        }

        private float ShippingRailFreeSpace(Vector2Int rail, LooseResourceKind kind)
        {
            if (!IsInside(rail.x, rail.y) || !shippingRail[rail.x, rail.y])
            {
                return 0f;
            }

            LooseResourceKind currentKind = shippingRailKind[rail.x, rail.y];
            if (currentKind != LooseResourceKind.None && currentKind != kind)
            {
                return 0f;
            }

            return Mathf.Max(0f, ShippingRailCapacity - shippingRailAmount[rail.x, rail.y]);
        }

        private float AddShippingRailPacket(Vector2Int rail, LooseResourceKind kind, float amount)
        {
            if (kind == LooseResourceKind.None || amount <= 0f || ShippingRailFreeSpace(rail, kind) <= 0.001f)
            {
                return 0f;
            }

            float loaded = Mathf.Min(amount, ShippingRailCapacity - shippingRailAmount[rail.x, rail.y]);
            shippingRailKind[rail.x, rail.y] = kind;
            shippingRailAmount[rail.x, rail.y] += loaded;
            return loaded;
        }

        private float DropLooseResourceNear(Vector2Int origin, LooseResourceKind kind, float amount)
        {
            if (kind == LooseResourceKind.None || amount <= 0f || !TryFindLooseResourceDropCell(origin, kind, out Vector2Int dropCell))
            {
                return 0f;
            }

            float capacity = looseResourceKind[dropCell.x, dropCell.y] == LooseResourceKind.None ? 80f : 80f - looseResourceAmount[dropCell.x, dropCell.y];
            float dropped = Mathf.Min(amount, Mathf.Max(0f, capacity));
            if (dropped <= 0.001f)
            {
                return 0f;
            }

            bool wasEmpty = looseResourceKind[dropCell.x, dropCell.y] == LooseResourceKind.None;
            looseResourceKind[dropCell.x, dropCell.y] = kind;
            looseResourceAmount[dropCell.x, dropCell.y] += dropped;
            if (kind != LooseResourceKind.HatchEgg || wasEmpty)
            {
                hatchEggAge[dropCell.x, dropCell.y] = 0f;
            }

            return dropped;
        }

        private void ReleaseShippingRailContents(Vector2Int rail)
        {
            if (!IsInside(rail.x, rail.y) || shippingRailKind[rail.x, rail.y] == LooseResourceKind.None || shippingRailAmount[rail.x, rail.y] <= 0.001f)
            {
                return;
            }

            float dropped = DropLooseResourceNear(rail, shippingRailKind[rail.x, rail.y], shippingRailAmount[rail.x, rail.y]);
            if (dropped < shippingRailAmount[rail.x, rail.y])
            {
                StoreLooseResource(shippingRailKind[rail.x, rail.y], shippingRailAmount[rail.x, rail.y] - dropped);
            }
        }

        private void SimulatePlumbing(float deltaTime)
        {
            bool changed = false;
            changed |= RunPipedWaterPumps(deltaTime);
            changed |= RunLiquidBridges(deltaTime);
            changed |= EqualizePipeWater(deltaTime);
            changed |= RunLiquidReservoirs(deltaTime);
            changed |= RunLiquidVents(deltaTime);
            changed |= StepWorldLiquids(deltaTime);

            if (changed)
            {
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private bool RunPipedWaterPumps(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.WaterPump)
                    {
                        continue;
                    }

                    Vector2Int pump = new Vector2Int(x, y);
                    if (IsBrokenEquipment(pump) ||
                        !CanPoweredMachineRun(pump) ||
                        !TryFindAdjacentPipePumpLiquid(pump, out Vector2Int source) ||
                        !TryFindAdjacentLiquidPipeWithSpace(pump, out Vector2Int pipe))
                    {
                        continue;
                    }

                    float powerUsed = Mathf.Min(power, 0.24f * deltaTime);
                    float efficiency = powerUsed / Mathf.Max(0.001f, 0.24f * deltaTime);
                    float amount = Mathf.Min(
                        waterMass[source.x, source.y],
                        Mathf.Min(LiquidPumpRate * deltaTime * efficiency, LiquidPipeFreeCapacity(pipe.x, pipe.y)));
                    amount = LimitLiquidValveFlow(pipe, amount);
                    if (amount <= 0.001f)
                    {
                        continue;
                    }

                    bool petroleumSource = IsPetroleumWorldLiquidAt(source.x, source.y);
                    bool pollutedSource = IsPollutedWorldLiquidAt(source.x, source.y);
                    bool saltSource = IsSaltWaterWorldLiquidAt(source.x, source.y);
                    if (saltSource)
                    {
                        continue;
                    }

                    float added = petroleumSource
                        ? AddLiquidPipePetroleum(pipe, amount, temperature[source.x, source.y])
                        : pollutedSource
                            ? AddLiquidPipePollutedWater(pipe, amount, temperature[source.x, source.y], PollutedWaterSourceGermLevel(source))
                            : AddLiquidPipeWater(pipe, amount, temperature[source.x, source.y], CleanWaterSourceGermLevel(source));
                    if (added <= 0.001f)
                    {
                        continue;
                    }

                    ConsumeCyclePower(powerUsed);
                    waterMass[source.x, source.y] -= added;
                    if (!pollutedSource && !petroleumSource)
                    {
                        currentCycleReport.WaterProduced += added;
                        if (HasSteamVentNearby(source, 4))
                        {
                            steamVentWaterPumped += added;
                        }

                        if (HasWaterGeyserNearby(source, 4))
                        {
                            waterGeyserWaterPumped += added;
                        }
                    }
                    else if (pollutedSource && HasPollutedWaterVentNearby(source, 4))
                    {
                        pollutedWaterVentPollutedWaterPumped += added;
                    }

                    AddHeat(pump, 0.035f * deltaTime * efficiency, 1);
                    WearEquipment(pump, 0.00030f * deltaTime * efficiency);
                    changed = true;

                    if (waterMass[source.x, source.y] <= 0.5f)
                    {
                        DryWaterCell(
                            source,
                            NeighborAverage(oxygen, source.x, source.y, 0.12f),
                            NeighborAverage(carbonDioxide, source.x, source.y, 0.04f),
                            pollutedSource ? 0.04f : NeighborAverage(pollutedOxygen, source.x, source.y, 0f),
                            NeighborAverage(hydrogen, source.x, source.y, 0f),
                            NeighborAverage(chlorine, source.x, source.y, 0f),
                            NeighborAverage(naturalGas, source.x, source.y, 0f),
                            pollutedSource ? 0.08f : NeighborAverage(germs, source.x, source.y, 0f),
                            temperature[source.x, source.y],
                            NeighborAverage(sourGas, source.x, source.y, 0f));
                    }
                }
            }

            return changed;
        }

        private bool RunLiquidBridges(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.LiquidBridge)
                    {
                        continue;
                    }

                    Vector2Int bridge = new Vector2Int(x, y);
                    if (!CanUseEquipment(bridge))
                    {
                        continue;
                    }

                    BridgeDirection direction = BridgeDirectionAt(x, y);
                    bool moved = MoveLiquidBridgePair(bridge, BridgeInputOffset(direction), BridgeOutputOffset(direction), deltaTime);
                    if (moved)
                    {
                        WearEquipment(bridge, 0.00004f * deltaTime);
                        changed = true;
                    }
                }
            }

            return changed;
        }

        private bool MoveLiquidBridgePair(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, float deltaTime)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsLiquidBridgeEndpoint(input) || !IsLiquidBridgeEndpoint(output))
            {
                return false;
            }

            float amount = Mathf.Min(
                LiquidBridgeRate * deltaTime,
                Mathf.Min(LiquidPipeTotal(input.x, input.y), LiquidPipeFreeCapacity(output.x, output.y)));
            float moved = MoveLiquidPipeWater(input, output, amount);
            if (moved <= 0.001f)
            {
                return false;
            }

            liquidBridgeMovedMass += moved;
            return true;
        }

        private bool IsLiquidBridgeEndpoint(Vector2Int pipe)
        {
            return IsInside(pipe.x, pipe.y) &&
                liquidPipe[pipe.x, pipe.y] &&
                !IsLiquidConduitBlocked(pipe.x, pipe.y);
        }

        private bool EqualizePipeWater(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!liquidPipe[x, y])
                    {
                        continue;
                    }

                    changed |= EqualizePipePair(x, y, x + 1, y, deltaTime);
                    changed |= EqualizePipePair(x, y, x, y + 1, deltaTime);
                }
            }

            return changed;
        }

        private bool EqualizePipePair(int ax, int ay, int bx, int by, float deltaTime)
        {
            if (!IsInside(bx, by) ||
                !liquidPipe[ax, ay] ||
                !liquidPipe[bx, by] ||
                IsLiquidConduitBlocked(ax, ay) ||
                IsLiquidConduitBlocked(bx, by))
            {
                return false;
            }

            float aTotal = LiquidPipeTotal(ax, ay);
            float bTotal = LiquidPipeTotal(bx, by);
            float difference = aTotal - bTotal;
            if (Mathf.Abs(difference) < 0.02f)
            {
                return false;
            }

            float flow = Mathf.Clamp(difference * 0.35f * deltaTime, -LiquidPipeCapacity * 0.35f, LiquidPipeCapacity * 0.35f);
            if (flow > 0f)
            {
                flow = Mathf.Min(flow, aTotal, LiquidPipeFreeCapacity(bx, by));
            }
            else
            {
                float reverse = Mathf.Min(-flow, bTotal, LiquidPipeFreeCapacity(ax, ay));
                flow = -reverse;
            }

            if (Mathf.Abs(flow) <= 0.001f)
            {
                return false;
            }

            float moved = flow > 0f
                ? MoveLiquidPipeWater(new Vector2Int(ax, ay), new Vector2Int(bx, by), flow)
                : MoveLiquidPipeWater(new Vector2Int(bx, by), new Vector2Int(ax, ay), -flow);
            return moved > 0.001f;
        }

        private float LiquidPipeTotal(int x, int y)
        {
            return pipeWater[x, y] + pipePollutedWater[x, y] + pipePetroleum[x, y];
        }

        private float LiquidPipeFreeCapacity(int x, int y)
        {
            return Mathf.Max(0f, LiquidPipeCapacity - LiquidPipeTotal(x, y));
        }

        private float AddLiquidPipeWater(Vector2Int pipe, float amount, float sourceTemperature, float germLevel = 0f)
        {
            if (amount <= 0f || !IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            float oldMass = LiquidPipeTotal(pipe.x, pipe.y);
            float added = Mathf.Min(amount, LiquidPipeFreeCapacity(pipe.x, pipe.y));
            if (added <= 0.001f)
            {
                return 0f;
            }

            MixLiquidPipeTemperature(pipe, oldMass, sourceTemperature, added);
            pipeWaterGerms[pipe.x, pipe.y] = MixConcentration(pipeWaterGerms[pipe.x, pipe.y], pipeWater[pipe.x, pipe.y], germLevel, added);
            pipeWater[pipe.x, pipe.y] = Mathf.Min(LiquidPipeCapacity, pipeWater[pipe.x, pipe.y] + added);
            return added;
        }

        private float AddLiquidPipePollutedWater(Vector2Int pipe, float amount, float sourceTemperature, float germLevel = PollutedWaterDefaultGermLevel)
        {
            if (amount <= 0f || !IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            float oldMass = LiquidPipeTotal(pipe.x, pipe.y);
            float added = Mathf.Min(amount, LiquidPipeFreeCapacity(pipe.x, pipe.y));
            if (added <= 0.001f)
            {
                return 0f;
            }

            MixLiquidPipeTemperature(pipe, oldMass, sourceTemperature, added);
            pipePollutedWaterGerms[pipe.x, pipe.y] = MixConcentration(pipePollutedWaterGerms[pipe.x, pipe.y], pipePollutedWater[pipe.x, pipe.y], germLevel, added);
            pipePollutedWater[pipe.x, pipe.y] = Mathf.Min(LiquidPipeCapacity, pipePollutedWater[pipe.x, pipe.y] + added);
            return added;
        }

        private float AddLiquidPipePetroleum(Vector2Int pipe, float amount, float sourceTemperature)
        {
            if (amount <= 0f || !IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            float oldMass = LiquidPipeTotal(pipe.x, pipe.y);
            float added = Mathf.Min(amount, LiquidPipeFreeCapacity(pipe.x, pipe.y));
            if (added <= 0.001f)
            {
                return 0f;
            }

            MixLiquidPipeTemperature(pipe, oldMass, sourceTemperature, added);
            pipePetroleum[pipe.x, pipe.y] = Mathf.Min(LiquidPipeCapacity, pipePetroleum[pipe.x, pipe.y] + added);
            return added;
        }

        private float MoveLiquidPipeWater(Vector2Int from, Vector2Int to, float amount)
        {
            if (!IsInside(from.x, from.y))
            {
                return 0f;
            }

            return MoveLiquidPipeWaterAtTemperature(from, to, amount, temperature[from.x, from.y]);
        }

        private float MoveLiquidPipeWaterAtTemperature(Vector2Int from, Vector2Int to, float amount, float sourceTemperature)
        {
            if (amount <= 0f ||
                !IsInside(from.x, from.y) ||
                !IsInside(to.x, to.y) ||
                !liquidPipe[from.x, from.y] ||
                !liquidPipe[to.x, to.y])
            {
                return 0f;
            }

            float fromTotal = LiquidPipeTotal(from.x, from.y);
            float moved = LimitLiquidValveFlow(from, to, Mathf.Min(amount, fromTotal, LiquidPipeFreeCapacity(to.x, to.y)));
            if (moved <= 0.001f)
            {
                return 0f;
            }

            float cleanGerms = pipeWaterGerms[from.x, from.y];
            float pollutedGerms = pipePollutedWaterGerms[from.x, from.y];
            float cleanAmount = Mathf.Min(pipeWater[from.x, from.y], moved * pipeWater[from.x, from.y] / Mathf.Max(0.001f, fromTotal));
            float pollutedAmount = Mathf.Min(pipePollutedWater[from.x, from.y], moved * pipePollutedWater[from.x, from.y] / Mathf.Max(0.001f, fromTotal));
            float petroleumAmount = Mathf.Min(pipePetroleum[from.x, from.y], moved - cleanAmount - pollutedAmount);
            pipeWater[from.x, from.y] = Mathf.Max(0f, pipeWater[from.x, from.y] - cleanAmount);
            if (pipeWater[from.x, from.y] <= 0.001f)
            {
                pipeWaterGerms[from.x, from.y] = 0f;
            }

            pipePollutedWater[from.x, from.y] = Mathf.Max(0f, pipePollutedWater[from.x, from.y] - pollutedAmount);
            if (pipePollutedWater[from.x, from.y] <= 0.001f)
            {
                pipePollutedWaterGerms[from.x, from.y] = 0f;
            }

            pipePetroleum[from.x, from.y] = Mathf.Max(0f, pipePetroleum[from.x, from.y] - petroleumAmount);
            float addedClean = AddLiquidPipeWater(to, cleanAmount, sourceTemperature, cleanGerms);
            float addedPolluted = AddLiquidPipePollutedWater(to, pollutedAmount, sourceTemperature, pollutedGerms);
            float addedPetroleum = AddLiquidPipePetroleum(to, petroleumAmount, sourceTemperature);
            moved = addedClean + addedPolluted + addedPetroleum;
            TrackAutomatedConduitFlow(from.x, from.y, to.x, to.y, moved, false);
            return moved;
        }

        private float RemoveCleanWaterFromPipe(Vector2Int pipe, float amount)
        {
            return RemoveCleanWaterFromPipe(pipe, amount, out _);
        }

        private float RemoveCleanWaterFromPipe(Vector2Int pipe, float amount, out float germLevel)
        {
            germLevel = 0f;
            if (amount <= 0f || !IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            germLevel = pipeWaterGerms[pipe.x, pipe.y];
            float removed = LimitLiquidValveFlow(pipe, Mathf.Min(amount, pipeWater[pipe.x, pipe.y]));
            if (removed <= 0.001f)
            {
                return 0f;
            }

            pipeWater[pipe.x, pipe.y] = Mathf.Max(0f, pipeWater[pipe.x, pipe.y] - removed);
            if (pipeWater[pipe.x, pipe.y] <= 0.001f)
            {
                pipeWaterGerms[pipe.x, pipe.y] = 0f;
            }

            return removed;
        }

        private float RemovePollutedWaterFromPipe(Vector2Int pipe, float amount)
        {
            return RemovePollutedWaterFromPipe(pipe, amount, out _);
        }

        private float RemovePollutedWaterFromPipe(Vector2Int pipe, float amount, out float germLevel)
        {
            germLevel = 0f;
            if (amount <= 0f || !IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            germLevel = pipePollutedWaterGerms[pipe.x, pipe.y];
            float removed = LimitLiquidValveFlow(pipe, Mathf.Min(amount, pipePollutedWater[pipe.x, pipe.y]));
            if (removed <= 0.001f)
            {
                return 0f;
            }

            pipePollutedWater[pipe.x, pipe.y] = Mathf.Max(0f, pipePollutedWater[pipe.x, pipe.y] - removed);
            if (pipePollutedWater[pipe.x, pipe.y] <= 0.001f)
            {
                pipePollutedWaterGerms[pipe.x, pipe.y] = 0f;
            }

            return removed;
        }

        private float RemoveLiquidPipeContents(Vector2Int pipe, float amount, out float cleanAmount, out float pollutedAmount)
        {
            return RemoveLiquidPipeContents(pipe, amount, out cleanAmount, out pollutedAmount, out _, out _, out _);
        }

        private float RemoveLiquidPipeContents(Vector2Int pipe, float amount, out float cleanAmount, out float pollutedAmount, out float cleanGermLevel)
        {
            return RemoveLiquidPipeContents(pipe, amount, out cleanAmount, out pollutedAmount, out cleanGermLevel, out _, out _);
        }

        private float RemoveLiquidPipeContents(Vector2Int pipe, float amount, out float cleanAmount, out float pollutedAmount, out float cleanGermLevel, out float pollutedGermLevel)
        {
            return RemoveLiquidPipeContents(pipe, amount, out cleanAmount, out pollutedAmount, out cleanGermLevel, out pollutedGermLevel, out _);
        }

        private float RemoveLiquidPipeContents(Vector2Int pipe, float amount, out float cleanAmount, out float pollutedAmount, out float cleanGermLevel, out float pollutedGermLevel, out float petroleumAmount)
        {
            cleanAmount = 0f;
            pollutedAmount = 0f;
            cleanGermLevel = 0f;
            pollutedGermLevel = 0f;
            petroleumAmount = 0f;
            if (amount <= 0f || !IsInside(pipe.x, pipe.y) || !liquidPipe[pipe.x, pipe.y])
            {
                return 0f;
            }

            float total = LiquidPipeTotal(pipe.x, pipe.y);
            amount = LimitLiquidValveFlow(pipe, Mathf.Min(amount, total));
            if (amount <= 0.001f)
            {
                return 0f;
            }

            cleanGermLevel = pipeWaterGerms[pipe.x, pipe.y];
            pollutedGermLevel = pipePollutedWaterGerms[pipe.x, pipe.y];
            cleanAmount = Mathf.Min(pipeWater[pipe.x, pipe.y], amount * pipeWater[pipe.x, pipe.y] / Mathf.Max(0.001f, total));
            pollutedAmount = Mathf.Min(pipePollutedWater[pipe.x, pipe.y], amount * pipePollutedWater[pipe.x, pipe.y] / Mathf.Max(0.001f, total));
            petroleumAmount = Mathf.Min(pipePetroleum[pipe.x, pipe.y], amount - cleanAmount - pollutedAmount);
            pipeWater[pipe.x, pipe.y] = Mathf.Max(0f, pipeWater[pipe.x, pipe.y] - cleanAmount);
            if (pipeWater[pipe.x, pipe.y] <= 0.001f)
            {
                pipeWaterGerms[pipe.x, pipe.y] = 0f;
            }

            pipePollutedWater[pipe.x, pipe.y] = Mathf.Max(0f, pipePollutedWater[pipe.x, pipe.y] - pollutedAmount);
            if (pipePollutedWater[pipe.x, pipe.y] <= 0.001f)
            {
                pipePollutedWaterGerms[pipe.x, pipe.y] = 0f;
            }

            pipePetroleum[pipe.x, pipe.y] = Mathf.Max(0f, pipePetroleum[pipe.x, pipe.y] - petroleumAmount);
            return cleanAmount + pollutedAmount + petroleumAmount;
        }

        private void MixLiquidPipeTemperature(Vector2Int pipe, float oldMass, float incomingTemperature, float incomingMass)
        {
            if (incomingMass <= 0f)
            {
                return;
            }

            float totalMass = oldMass + incomingMass;
            if (totalMass <= 0.001f)
            {
                temperature[pipe.x, pipe.y] = Mathf.Clamp(incomingTemperature, -30f, 120f);
                return;
            }

            float mixed = ((temperature[pipe.x, pipe.y] * oldMass) + (incomingTemperature * incomingMass)) / totalMass;
            temperature[pipe.x, pipe.y] = Mathf.Clamp(mixed, -30f, 120f);
        }

        private float MixConcentration(float oldConcentration, float oldMass, float incomingConcentration, float incomingMass)
        {
            oldMass = Mathf.Max(0f, oldMass);
            incomingMass = Mathf.Max(0f, incomingMass);
            float totalMass = oldMass + incomingMass;
            if (totalMass <= 0.001f)
            {
                return 0f;
            }

            return Mathf.Clamp01((Mathf.Clamp01(oldConcentration) * oldMass + Mathf.Clamp01(incomingConcentration) * incomingMass) / totalMass);
        }

        private bool RunLiquidReservoirs(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.LiquidReservoir)
                    {
                        continue;
                    }

                    Vector2Int reservoir = new Vector2Int(x, y);
                    if (!CanUseEquipment(reservoir))
                    {
                        continue;
                    }

                    Vector2Int inputPipe = new Vector2Int(-1, -1);
                    float storedLiquid = LiquidReservoirTotal(x, y);
                    if (storedLiquid < LiquidReservoirCapacity - 0.001f &&
                        TryFindAdjacentLiquidPipeWithAnyLiquid(reservoir, out inputPipe))
                    {
                        float amount = Mathf.Min(
                            LiquidPipeTotal(inputPipe.x, inputPipe.y),
                            Mathf.Min(LiquidReservoirRate * deltaTime, LiquidReservoirCapacity - storedLiquid));
                        if (amount > 0.001f)
                        {
                            float incomingTemperature = temperature[inputPipe.x, inputPipe.y];
                            float moved = RemoveLiquidPipeContents(inputPipe, amount, out float cleanAmount, out float pollutedAmount, out float cleanGermLevel, out float pollutedGermLevel, out float petroleumAmount);
                            if (moved > 0.001f)
                            {
                                MixLiquidReservoirTemperature(reservoir, storedLiquid, incomingTemperature, moved);
                                liquidReservoirWaterGerms[x, y] = MixConcentration(liquidReservoirWaterGerms[x, y], liquidReservoirWater[x, y], cleanGermLevel, cleanAmount);
                                liquidReservoirWater[x, y] = Mathf.Min(LiquidReservoirCapacity, liquidReservoirWater[x, y] + cleanAmount);
                                liquidReservoirPollutedWaterGerms[x, y] = MixConcentration(liquidReservoirPollutedWaterGerms[x, y], liquidReservoirPollutedWater[x, y], pollutedGermLevel, pollutedAmount);
                                liquidReservoirPollutedWater[x, y] = Mathf.Min(LiquidReservoirCapacity - liquidReservoirWater[x, y], liquidReservoirPollutedWater[x, y] + pollutedAmount);
                                liquidReservoirPetroleum[x, y] = Mathf.Min(LiquidReservoirCapacity - liquidReservoirWater[x, y] - liquidReservoirPollutedWater[x, y], liquidReservoirPetroleum[x, y] + petroleumAmount);
                                reservoirBufferedMass += moved;
                                WearEquipment(reservoir, 0.00008f * deltaTime);
                                changed = true;
                            }
                        }
                    }

                    storedLiquid = LiquidReservoirTotal(x, y);
                    if (storedLiquid > 0.001f &&
                        TryFindAdjacentLiquidPipeWithSpaceExcluding(reservoir, inputPipe, out Vector2Int outputPipe))
                    {
                        float amount = Mathf.Min(
                            storedLiquid,
                            Mathf.Min(LiquidReservoirRate * deltaTime, LiquidPipeFreeCapacity(outputPipe.x, outputPipe.y)));
                        if (amount > 0.001f)
                        {
                            amount = LimitLiquidValveFlow(outputPipe, amount);
                            if (amount <= 0.001f)
                            {
                                continue;
                            }

                            float moved = MoveLiquidReservoirToPipe(reservoir, outputPipe, amount);
                            if (moved > 0.001f)
                            {
                                WearEquipment(reservoir, 0.00006f * deltaTime);
                                changed = true;
                            }
                        }
                    }
                }
            }

            return changed;
        }

        private void MixLiquidReservoirTemperature(Vector2Int reservoir, float oldMass, float incomingTemperature, float incomingMass)
        {
            if (!IsInside(reservoir.x, reservoir.y) || incomingMass <= 0f)
            {
                return;
            }

            oldMass = Mathf.Max(0f, oldMass);
            float totalMass = oldMass + incomingMass;
            if (totalMass <= 0.001f)
            {
                temperature[reservoir.x, reservoir.y] = Mathf.Clamp(incomingTemperature, -30f, 120f);
                return;
            }

            float mixed = ((temperature[reservoir.x, reservoir.y] * oldMass) + (incomingTemperature * incomingMass)) / totalMass;
            temperature[reservoir.x, reservoir.y] = Mathf.Clamp(mixed, -30f, 120f);
        }

        private float MoveLiquidReservoirToPipe(Vector2Int reservoir, Vector2Int pipe, float amount)
        {
            if (!IsInside(reservoir.x, reservoir.y) ||
                !IsInside(pipe.x, pipe.y) ||
                amount <= 0.001f)
            {
                return 0f;
            }

            float storedLiquid = LiquidReservoirTotal(reservoir.x, reservoir.y);
            if (storedLiquid <= 0.001f)
            {
                return 0f;
            }

            amount = Mathf.Min(amount, storedLiquid, LiquidPipeFreeCapacity(pipe.x, pipe.y));
            float cleanAmount = Mathf.Min(liquidReservoirWater[reservoir.x, reservoir.y], amount * liquidReservoirWater[reservoir.x, reservoir.y] / storedLiquid);
            float pollutedAmount = Mathf.Min(liquidReservoirPollutedWater[reservoir.x, reservoir.y], amount * liquidReservoirPollutedWater[reservoir.x, reservoir.y] / storedLiquid);
            float petroleumAmount = Mathf.Min(liquidReservoirPetroleum[reservoir.x, reservoir.y], amount - cleanAmount - pollutedAmount);
            float addedClean = AddLiquidPipeWater(pipe, cleanAmount, temperature[reservoir.x, reservoir.y], liquidReservoirWaterGerms[reservoir.x, reservoir.y]);
            float addedPolluted = AddLiquidPipePollutedWater(pipe, pollutedAmount, temperature[reservoir.x, reservoir.y], liquidReservoirPollutedWaterGerms[reservoir.x, reservoir.y]);
            float addedPetroleum = AddLiquidPipePetroleum(pipe, petroleumAmount, temperature[reservoir.x, reservoir.y]);
            float moved = addedClean + addedPolluted + addedPetroleum;
            liquidReservoirWater[reservoir.x, reservoir.y] = Mathf.Max(0f, liquidReservoirWater[reservoir.x, reservoir.y] - addedClean);
            if (liquidReservoirWater[reservoir.x, reservoir.y] <= 0.001f)
            {
                liquidReservoirWaterGerms[reservoir.x, reservoir.y] = 0f;
            }

            liquidReservoirPollutedWater[reservoir.x, reservoir.y] = Mathf.Max(0f, liquidReservoirPollutedWater[reservoir.x, reservoir.y] - addedPolluted);
            if (liquidReservoirPollutedWater[reservoir.x, reservoir.y] <= 0.001f)
            {
                liquidReservoirPollutedWaterGerms[reservoir.x, reservoir.y] = 0f;
            }

            liquidReservoirPetroleum[reservoir.x, reservoir.y] = Mathf.Max(0f, liquidReservoirPetroleum[reservoir.x, reservoir.y] - addedPetroleum);
            return moved;
        }

        private bool RunLiquidVents(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.LiquidVent)
                    {
                        continue;
                    }

                    Vector2Int vent = new Vector2Int(x, y);
                    if (!CanUseEquipment(vent))
                    {
                        continue;
                    }

                    if (!TryFindAdjacentLiquidPipeWithAnyLiquid(vent, out Vector2Int pipe) ||
                        !TryFindLiquidVentOutput(vent, out Vector2Int output))
                    {
                        continue;
                    }

                    float amount = Mathf.Min(LiquidPipeTotal(pipe.x, pipe.y), LiquidVentRate * deltaTime);
                    amount = Mathf.Min(amount, LiquidTileCapacity - waterMass[output.x, output.y]);
                    float moved = RemoveLiquidPipeContents(pipe, amount, out float cleanAmount, out float pollutedAmount, out float cleanGermLevel, out float pollutedGermLevel, out float petroleumAmount);
                    if (moved <= 0.001f)
                    {
                        continue;
                    }

                    if (cleanAmount > 0.001f)
                    {
                        ReleaseWaterToCell(output, cleanAmount, cleanGermLevel);
                    }

                    if (pollutedAmount > 0.001f)
                    {
                        ReleasePollutedWaterToCell(output, pollutedAmount, pollutedGermLevel);
                    }

                    if (petroleumAmount > 0.001f)
                    {
                        ReleasePetroleumToCell(output, petroleumAmount);
                    }

                    WearEquipment(vent, 0.00012f * deltaTime);
                    changed = true;
                }
            }

            return changed;
        }

        private void ReleaseWaterToCell(Vector2Int cell, float amount)
        {
            ReleaseWaterToCell(cell, amount, 0f);
        }

        private void ReleaseWaterToCell(Vector2Int cell, float amount, float germLevel)
        {
            if (amount <= 0f || !IsInside(cell.x, cell.y))
            {
                return;
            }

            ReleaseLiquidToCell(cell, amount, false);
            germs[cell.x, cell.y] = Mathf.Clamp01(germs[cell.x, cell.y] + Mathf.Clamp01(germLevel) * 0.55f);
        }

        private void ReleasePollutedWaterToCell(Vector2Int cell, float amount)
        {
            ReleasePollutedWaterToCell(cell, amount, PollutedWaterDefaultGermLevel);
        }

        private void ReleasePollutedWaterToCell(Vector2Int cell, float amount, float germLevel)
        {
            ReleaseLiquidToCell(cell, amount, true);
            pollutedOxygen[cell.x, cell.y] = Mathf.Min(2.2f, pollutedOxygen[cell.x, cell.y] + 0.08f + amount * 0.003f);
            germs[cell.x, cell.y] = Mathf.Clamp01(germs[cell.x, cell.y] + 0.18f + Mathf.Clamp01(germLevel) * PollutedWaterReleaseGermScale);
        }

        private void ReleasePetroleumToCell(Vector2Int cell, float amount)
        {
            if (amount <= 0f || !IsInside(cell.x, cell.y))
            {
                return;
            }

            ReleaseLiquidToCell(cell, amount, CellKind.Petroleum);
            naturalGas[cell.x, cell.y] = Mathf.Min(2.8f, naturalGas[cell.x, cell.y] + amount * 0.0015f);
        }

        private void ReleaseLiquidToCell(Vector2Int cell, float amount, bool polluted)
        {
            if (amount <= 0f || !IsInside(cell.x, cell.y))
            {
                return;
            }

            ReleaseLiquidToCell(cell, amount, polluted ? CellKind.PollutedWater : CellKind.Water);
        }

        private void ReleaseLiquidToCell(Vector2Int cell, float amount, CellKind liquidKind)
        {
            if (amount <= 0f || !IsInside(cell.x, cell.y))
            {
                return;
            }

            EnsureLiquidCell(cell, liquidKind);
            waterMass[cell.x, cell.y] = Mathf.Min(LiquidTileCapacity, waterMass[cell.x, cell.y] + amount);
            oxygen[cell.x, cell.y] = Mathf.Max(0f, oxygen[cell.x, cell.y] - amount * 0.004f);
            carbonDioxide[cell.x, cell.y] = Mathf.Max(0f, carbonDioxide[cell.x, cell.y] - amount * 0.002f);
            pollutedOxygen[cell.x, cell.y] = Mathf.Max(0f, pollutedOxygen[cell.x, cell.y] - amount * 0.003f);
            hydrogen[cell.x, cell.y] = Mathf.Max(0f, hydrogen[cell.x, cell.y] - amount * 0.004f);
            steam[cell.x, cell.y] = Mathf.Max(0f, steam[cell.x, cell.y] - amount * 0.004f);
            chlorine[cell.x, cell.y] = Mathf.Max(0f, chlorine[cell.x, cell.y] - amount * 0.004f);
            naturalGas[cell.x, cell.y] = Mathf.Max(0f, naturalGas[cell.x, cell.y] - amount * 0.004f);
            DisplaceWorkersFromLiquid(cell);
        }

        private void SimulateFlooding(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            bool brokeWire = false;
            int firstWireBreakX = -1;
            int firstWireBreakY = -1;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    float mass = Mathf.Max(0f, waterMass[x, y]);
                    if (mass <= 0.5f)
                    {
                        continue;
                    }

                    Vector2Int cell = new Vector2Int(x, y);
                    if (IsEquipmentSubmerged(cell))
                    {
                        float before = Mathf.Clamp01(equipmentCondition[x, y]);
                        float damage = SubmergedEquipmentDamageRate * deltaTime * Mathf.Clamp01(mass / LiquidTileCapacity);
                        DamageEquipment(cell, damage);
                        float after = Mathf.Clamp01(equipmentCondition[x, y]);
                        submergedEquipmentDamage += Mathf.Max(0f, before - after);
                        changed |= after < before;
                    }

                    if (IsPowerWireFlooded(x, y))
                    {
                        float stress = FloodedWireStressRate * deltaTime * Mathf.Clamp01(mass / LiquidTileCapacity);
                        wireOverloadStress[x, y] += stress;
                        AddHeat(cell, 0.012f * deltaTime, 1);
                        overlayDirty = true;
                        gasDirty = true;

                        if (wireOverloadStress[x, y] >= WireOverloadBreakStress)
                        {
                            powerWire[x, y] = false;
                            powerWireKind[x, y] = PowerWireKind.Normal;
                            poweredWire[x, y] = false;
                            overloadedWire[x, y] = false;
                            wireLoad[x, y] = 0f;
                            wireOverloadStress[x, y] = 0f;
                            floodedWireFailures++;
                            if (!brokeWire)
                            {
                                firstWireBreakX = x;
                                firstWireBreakY = y;
                            }

                            brokeWire = true;
                            changed = true;
                        }
                    }
                }
            }

            if (brokeWire)
            {
                UpdatePoweredWires();
                Log("Flooded Power Wire shorted out at " + firstWireBreakX + ", " + firstWireBreakY + ".");
            }

            if (changed)
            {
                terrainDirty = true;
                overlayDirty = true;
            }
        }

        private void SimulateEquipmentOverheating(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            bool failed = false;
            Vector2Int firstFailure = new Vector2Int(-1, -1);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    CellKind kind = cells[x, y];
                    if (!IsRepairableEquipment(kind))
                    {
                        continue;
                    }

                    Vector2Int cell = new Vector2Int(x, y);
                    if (IsBrokenEquipment(cell))
                    {
                        continue;
                    }

                    float severity = EquipmentOverheatSeverity(x, y);
                    if (severity <= 0.001f)
                    {
                        continue;
                    }

                    float before = Mathf.Clamp01(equipmentCondition[x, y]);
                    DamageEquipment(cell, EquipmentOverheatDamageRate * severity * deltaTime);
                    float after = Mathf.Clamp01(equipmentCondition[x, y]);
                    float damage = Mathf.Max(0f, before - after);
                    if (damage <= 0f)
                    {
                        continue;
                    }

                    overheatedEquipmentDamage += damage;
                    AddHeat(cell, 0.015f * severity * deltaTime, 1);
                    changed = true;
                    if (before > EquipmentBrokenThreshold && after <= EquipmentBrokenThreshold)
                    {
                        overheatedEquipmentFailures++;
                        if (!failed)
                        {
                            firstFailure = cell;
                        }

                        failed = true;
                    }
                }
            }

            if (failed)
            {
                Log(CellLabel(cells[firstFailure.x, firstFailure.y]) + " failed from overheating. Cool or insulate the machinery.");
            }

            if (changed)
            {
                terrainDirty = true;
                overlayDirty = true;
                gasDirty = true;
            }
        }

        private void SimulateLiquidPipeHeatExchange(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            Array.Copy(temperature, nextTemperature, temperature.Length);
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    float pipeMass = LiquidPipeTotal(x, y);
                    if (!liquidPipe[x, y] || pipeMass <= 0.001f)
                    {
                        continue;
                    }

                    float fill = Mathf.Clamp01(pipeMass / LiquidPipeCapacity);
                    float rate = Mathf.Clamp01(deltaTime * LiquidPipeHeatTransferCoefficient(liquidPipeKind[x, y]) * fill);
                    if (rate <= 0.0001f)
                    {
                        continue;
                    }

                    changed |= ExchangeLiquidPipeHeatWithTile(x, y, x + 1, y, rate);
                    changed |= ExchangeLiquidPipeHeatWithTile(x, y, x - 1, y, rate);
                    changed |= ExchangeLiquidPipeHeatWithTile(x, y, x, y + 1, rate);
                    changed |= ExchangeLiquidPipeHeatWithTile(x, y, x, y - 1, rate);
                }
            }

            if (!changed)
            {
                return;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    temperature[x, y] = Mathf.Clamp(nextTemperature[x, y], -30f, 120f);
                }
            }

            terrainDirty = true;
        }

        private bool ExchangeLiquidPipeHeatWithTile(int pipeX, int pipeY, int tileX, int tileY, float rate)
        {
            if (!IsInside(tileX, tileY))
            {
                return false;
            }

            float delta = temperature[pipeX, pipeY] - temperature[tileX, tileY];
            if (Mathf.Abs(delta) <= 0.01f)
            {
                return false;
            }

            float pipeCapacity = Mathf.Max(0.7f, 1f + LiquidPipeTotal(pipeX, pipeY) * 0.12f);
            float tileCapacity = Mathf.Max(0.1f, ThermalCapacityAt(tileX, tileY));
            float flow = delta * rate;
            nextTemperature[pipeX, pipeY] -= flow / pipeCapacity;
            nextTemperature[tileX, tileY] += flow / tileCapacity;
            return true;
        }

        private void SimulateGasPipeHeatExchange(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            Array.Copy(temperature, nextTemperature, temperature.Length);
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    float pipeMass = GasPipeTotal(x, y);
                    if (!gasPipe[x, y] || pipeMass <= 0.001f)
                    {
                        continue;
                    }

                    float fill = Mathf.Clamp01(pipeMass / GasPipeCapacity);
                    float rate = Mathf.Clamp01(deltaTime * GasPipeHeatTransferCoefficient(gasPipeKind[x, y]) * fill);
                    if (rate <= 0.0001f)
                    {
                        continue;
                    }

                    changed |= ExchangeGasPipeHeatWithTile(x, y, x + 1, y, rate);
                    changed |= ExchangeGasPipeHeatWithTile(x, y, x - 1, y, rate);
                    changed |= ExchangeGasPipeHeatWithTile(x, y, x, y + 1, rate);
                    changed |= ExchangeGasPipeHeatWithTile(x, y, x, y - 1, rate);
                }
            }

            if (!changed)
            {
                return;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    temperature[x, y] = Mathf.Clamp(nextTemperature[x, y], -30f, 120f);
                }
            }

            terrainDirty = true;
            gasDirty = true;
        }

        private bool ExchangeGasPipeHeatWithTile(int pipeX, int pipeY, int tileX, int tileY, float rate)
        {
            if (!IsInside(tileX, tileY))
            {
                return false;
            }

            float delta = temperature[pipeX, pipeY] - temperature[tileX, tileY];
            if (Mathf.Abs(delta) <= 0.01f)
            {
                return false;
            }

            float pipeCapacity = Mathf.Max(0.35f, 0.55f + GasPipeTotal(pipeX, pipeY) * 0.08f);
            float tileCapacity = Mathf.Max(0.1f, ThermalCapacityAt(tileX, tileY));
            float flow = delta * rate;
            nextTemperature[pipeX, pipeY] -= flow / pipeCapacity;
            nextTemperature[tileX, tileY] += flow / tileCapacity;
            return true;
        }

        private void SimulateLiquidPipePhaseRuptures(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            bool ruptured = false;
            bool firstBoiled = false;
            Vector2Int firstRupture = new Vector2Int(-1, -1);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    float pipeMass = LiquidPipeTotal(x, y);
                    if (!liquidPipe[x, y] || pipeMass <= PipePhaseRuptureMinimumMass)
                    {
                        continue;
                    }

                    bool boiling = IsLiquidPipeBoiling(x, y);
                    bool freezing = IsLiquidPipeFreezing(x, y);
                    if (!boiling && !freezing)
                    {
                        continue;
                    }

                    Vector2Int pipe = new Vector2Int(x, y);
                    float cleanAmount = pipeWater[x, y];
                    float pollutedAmount = pipePollutedWater[x, y];
                    float pollutedGermLevel = pipePollutedWaterGerms[x, y];
                    float petroleumAmount = pipePetroleum[x, y];
                    float amount = cleanAmount + pollutedAmount + petroleumAmount;
                    liquidPipe[x, y] = false;
                    liquidPipeKind[x, y] = LiquidPipeKind.Normal;
                    pipeWater[x, y] = 0f;
                    pipeWaterGerms[x, y] = 0f;
                    pipePollutedWater[x, y] = 0f;
                    pipePollutedWaterGerms[x, y] = 0f;
                    pipePetroleum[x, y] = 0f;
                    pipeBurstWater += amount;
                    pipeBurstEvents++;
                    if (boiling)
                    {
                        boiledPipeBursts++;
                        ReleaseBoilingPipeWater(pipe, cleanAmount);
                        ReleaseBoilingPollutedPipeWater(pipe, pollutedAmount, pollutedGermLevel);
                        ReleasePetroleumToCell(pipe, petroleumAmount);
                    }
                    else
                    {
                        frozenPipeBursts++;
                        ReleaseFrozenPipeWater(pipe, cleanAmount);
                        ReleaseFrozenPollutedPipeWater(pipe, pollutedAmount, pollutedGermLevel);
                        ReleasePetroleumToCell(pipe, petroleumAmount);
                    }

                    if (!ruptured)
                    {
                        firstRupture = pipe;
                        firstBoiled = boiling;
                    }

                    ruptured = true;
                    changed = true;
                }
            }

            if (ruptured)
            {
                Log((firstBoiled ? "Boiling" : "Freezing") + " liquid ruptured a Liquid Pipe at " + firstRupture.x + ", " + firstRupture.y + ".");
            }

            if (changed)
            {
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private bool IsLiquidPipeFreezing(int x, int y)
        {
            return liquidPipe[x, y] &&
                LiquidPipeTotal(x, y) > PipePhaseRuptureMinimumMass &&
                temperature[x, y] < LiquidPipeFreezeLimit(x, y);
        }

        private bool IsLiquidPipeBoiling(int x, int y)
        {
            return liquidPipe[x, y] &&
                LiquidPipeTotal(x, y) > PipePhaseRuptureMinimumMass &&
                temperature[x, y] > LiquidPipeBoilLimit(x, y);
        }

        private float LiquidPipeFreezeLimit(int x, int y)
        {
            float limit = float.NegativeInfinity;
            if (pipeWater[x, y] > 0.001f)
            {
                limit = Mathf.Max(limit, PipeFreezeTemperature);
            }

            if (pipePollutedWater[x, y] > 0.001f)
            {
                limit = Mathf.Max(limit, PollutedWaterFreezeTemperature);
            }

            if (pipePetroleum[x, y] > 0.001f)
            {
                limit = Mathf.Max(limit, PetroleumFreezeTemperature);
            }

            return float.IsNegativeInfinity(limit) ? PipeFreezeTemperature : limit;
        }

        private float LiquidPipeBoilLimit(int x, int y)
        {
            float limit = float.PositiveInfinity;
            if (pipeWater[x, y] > 0.001f)
            {
                limit = Mathf.Min(limit, PipeBoilTemperature);
            }

            if (pipePollutedWater[x, y] > 0.001f)
            {
                limit = Mathf.Min(limit, PollutedWaterEvaporationTemperature);
            }

            if (pipePetroleum[x, y] > 0.001f)
            {
                limit = Mathf.Min(limit, PetroleumEvaporationTemperature);
            }

            return float.IsPositiveInfinity(limit) ? PipeBoilTemperature : limit;
        }

        private void SimulateLiquidReservoirPhaseRuptures(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            bool ruptured = false;
            bool firstBoiled = false;
