                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.LiquidReservoir || LiquidReservoirTotal(x, y) <= PipePhaseRuptureMinimumMass)
                    {
                        continue;
                    }

                    bool boiling = IsLiquidReservoirBoiling(x, y);
                    bool freezing = IsLiquidReservoirFreezing(x, y);
                    if (!boiling && !freezing)
                    {
                        continue;
                    }

                    Vector2Int reservoir = new Vector2Int(x, y);
                    float cleanAmount = liquidReservoirWater[x, y];
                    float pollutedAmount = liquidReservoirPollutedWater[x, y];
                    float pollutedGermLevel = liquidReservoirPollutedWaterGerms[x, y];
                    float petroleumAmount = liquidReservoirPetroleum[x, y];
