                    liquidReservoirWater[x, y] = 0f;
                    liquidReservoirWaterGerms[x, y] = 0f;
                    liquidReservoirPollutedWater[x, y] = 0f;
                    liquidReservoirPollutedWaterGerms[x, y] = 0f;
                    liquidReservoirPetroleum[x, y] = 0f;
