                    ruptured = true;
                    changed = true;
                }
            }

            if (ruptured)
            {
                Log((firstBoiled ? "Boiling" : "Freezing") + " liquid ruptured a Liquid Reservoir at " + firstRupture.x + ", " + firstRupture.y + ".");
            }

            if (changed)
            {
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private bool IsLiquidReservoirFreezing(int x, int y)
        {
            return cells[x, y] == CellKind.LiquidReservoir &&
                LiquidReservoirTotal(x, y) > PipePhaseRuptureMinimumMass &&
                temperature[x, y] < LiquidReservoirFreezeLimit(x, y);
        }

        private bool IsLiquidReservoirBoiling(int x, int y)
        {
            return cells[x, y] == CellKind.LiquidReservoir &&
                LiquidReservoirTotal(x, y) > PipePhaseRuptureMinimumMass &&
                temperature[x, y] > LiquidReservoirBoilLimit(x, y);
        }

        private float LiquidReservoirFreezeLimit(int x, int y)
        {
            float limit = float.NegativeInfinity;
            if (liquidReservoirWater[x, y] > 0.001f)
            {
                limit = Mathf.Max(limit, PipeFreezeTemperature);
            }

            if (liquidReservoirPollutedWater[x, y] > 0.001f)
            {
                limit = Mathf.Max(limit, PollutedWaterFreezeTemperature);
            }

            if (liquidReservoirPetroleum[x, y] > 0.001f)
            {
                limit = Mathf.Max(limit, PetroleumFreezeTemperature);
            }

            return float.IsNegativeInfinity(limit) ? PipeFreezeTemperature : limit;
        }

        private float LiquidReservoirBoilLimit(int x, int y)
        {
            float limit = float.PositiveInfinity;
            if (liquidReservoirWater[x, y] > 0.001f)
            {
                limit = Mathf.Min(limit, PipeBoilTemperature);
            }

            if (liquidReservoirPollutedWater[x, y] > 0.001f)
            {
                limit = Mathf.Min(limit, PollutedWaterEvaporationTemperature);
            }

            if (liquidReservoirPetroleum[x, y] > 0.001f)
            {
                limit = Mathf.Min(limit, PetroleumEvaporationTemperature);
            }

            return float.IsPositiveInfinity(limit) ? PipeBoilTemperature : limit;
        }

        private void SimulateGasConduitSteamCondensation(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            bool rupturedPipe = false;
            bool condensedReservoir = false;
            Vector2Int firstPipe = new Vector2Int(-1, -1);
            Vector2Int firstReservoir = new Vector2Int(-1, -1);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsGasPipeSteamCondensing(x, y))
                    {
                        Vector2Int pipe = new Vector2Int(x, y);
                        float steamAmount = gasPipeSteam[x, y];
                        float germLevel = gasPipeGerms[x, y];
                        ReleaseGasPipeNonSteamContents(pipe);
                        gasPipe[x, y] = false;
                        gasPipeKind[x, y] = GasPipeKind.Normal;
                        gasSensorMode[x, y] = GasSensorMode.AnyGas;
                        gasPipeOxygen[x, y] = 0f;
                        gasPipeCarbonDioxide[x, y] = 0f;
                        gasPipePollutedOxygen[x, y] = 0f;
                        gasPipeHydrogen[x, y] = 0f;
                        gasPipeSteam[x, y] = 0f;
                        gasPipeChlorine[x, y] = 0f;
                        gasPipeNaturalGas[x, y] = 0f;
                        gasPipeSourGas[x, y] = 0f;
                        gasPipeGerms[x, y] = 0f;
                        ReleaseCondensedGasConduitSteam(pipe, steamAmount, germLevel, temperature[x, y]);
                        if (!rupturedPipe)
                        {
                            firstPipe = pipe;
                        }

                        rupturedPipe = true;
                        changed = true;
                    }

                    if (IsGasReservoirSteamCondensing(x, y))
                    {
                        Vector2Int reservoir = new Vector2Int(x, y);
                        float steamAmount = gasReservoirSteam[x, y];
                        float germLevel = gasReservoirGerms[x, y];
                        gasReservoirSteam[x, y] = 0f;
                        ReleaseCondensedGasConduitSteam(reservoir, steamAmount, germLevel, temperature[x, y]);
                        ClearGasReservoirGermsIfEmpty(x, y);
                        DamageEquipment(reservoir, 0.65f);
                        if (!condensedReservoir)
                        {
                            firstReservoir = reservoir;
                        }

                        condensedReservoir = true;
                        changed = true;
                    }
                }
            }

            if (rupturedPipe)
            {
                Log("Condensing steam ruptured a Gas Pipe at " + firstPipe.x + ", " + firstPipe.y + ".");
            }
            else if (condensedReservoir)
            {
                Log("Condensing steam damaged a Gas Reservoir at " + firstReservoir.x + ", " + firstReservoir.y + ".");
            }

            if (changed)
            {
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private bool IsGasPipeSteamCondensing(int x, int y)
        {
            return gasPipe[x, y] &&
                gasPipeSteam[x, y] > PipePhaseRuptureMinimumMass &&
                temperature[x, y] < SteamCondensationTemperature;
        }

        private bool IsGasReservoirSteamCondensing(int x, int y)
        {
            return cells[x, y] == CellKind.GasReservoir &&
                gasReservoirSteam[x, y] > PipePhaseRuptureMinimumMass &&
                temperature[x, y] < SteamCondensationTemperature;
        }

        private void ReleaseGasPipeNonSteamContents(Vector2Int pipe)
        {
            if (!IsInside(pipe.x, pipe.y) || GasPipeTotal(pipe.x, pipe.y) <= gasPipeSteam[pipe.x, pipe.y] + 0.001f)
            {
                return;
            }

            if (!TryFindPipeSteamOutput(pipe, out Vector2Int output))
            {
                return;
            }

            AddGasToTileWithSteam(
                output.x,
                output.y,
                gasPipeOxygen[pipe.x, pipe.y],
                gasPipeCarbonDioxide[pipe.x, pipe.y],
                gasPipePollutedOxygen[pipe.x, pipe.y],
                gasPipeHydrogen[pipe.x, pipe.y],
                0f,
                gasPipeChlorine[pipe.x, pipe.y],
                gasPipeNaturalGas[pipe.x, pipe.y],
                gasPipeGerms[pipe.x, pipe.y],
                temperature[pipe.x, pipe.y],
                gasPipeSourGas[pipe.x, pipe.y]);
        }

        private void ReleaseCondensedGasConduitSteam(Vector2Int conduit, float amount, float germLevel, float sourceTemperature)
        {
            if (amount <= 0.001f)
            {
                return;
            }

            if (TryFindPipeLiquidOutput(conduit, out Vector2Int output))
            {
                ReleaseWaterToCell(output, amount, germLevel);
                temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], Mathf.Min(SteamCondensationTemperature, sourceTemperature) + amount * 0.45f), -30f, 120f);
            }
            else
            {
                StoreCleanWaterInStorage(amount, germLevel);
            }

            steamCondensedMass += amount;
            gasConduitCondensedWater += amount;
            gasConduitCondensationEvents++;
        }

        private void ReleaseBoilingPipeWater(Vector2Int pipe, float amount)
        {
            if (amount <= 0.001f)
            {
                return;
            }

            if (TryFindPipeSteamOutput(pipe, out Vector2Int output))
            {
                float released = AddSteamToTile(output, amount);
                steamEvaporatedMass += released;
                temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], PipeBoilTemperature + released * 0.2f), -30f, 120f);
                if (released >= amount - 0.001f)
                {
                    return;
                }

                amount -= released;
            }

            if (TryFindPipeLiquidOutput(pipe, out Vector2Int liquidOutput))
            {
                ReleaseWaterToCell(liquidOutput, amount);
                temperature[liquidOutput.x, liquidOutput.y] = Mathf.Clamp(Mathf.Max(temperature[liquidOutput.x, liquidOutput.y], PipeBoilTemperature), -30f, 120f);
            }
        }

        private void ReleaseBoilingPollutedPipeWater(Vector2Int pipe, float amount, float germLevel = PollutedWaterDefaultGermLevel)
        {
            if (amount <= 0.001f)
            {
                return;
            }

            if (TryFindPipeSteamOutput(pipe, out Vector2Int output))
            {
                float released = AddSteamToTile(output, amount);
                VentPollutedOxygen(output, released * 0.008f, released * (0.018f + Mathf.Clamp01(germLevel) * 0.040f));
                temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], PollutedWaterEvaporationTemperature + released * 0.2f), -30f, 120f);
                if (released >= amount - 0.001f)
                {
                    return;
                }

                amount -= released;
            }

            if (TryFindPipeLiquidOutput(pipe, out Vector2Int liquidOutput))
            {
                ReleasePollutedWaterToCell(liquidOutput, amount, germLevel);
                temperature[liquidOutput.x, liquidOutput.y] = Mathf.Clamp(Mathf.Max(temperature[liquidOutput.x, liquidOutput.y], PollutedWaterEvaporationTemperature), -30f, 120f);
            }
        }

        private void ReleaseFrozenPipeWater(Vector2Int pipe, float amount)
        {
            if (amount <= 0.001f)
            {
                return;
            }

            Vector2Int output;
            if (!TryFindPipeLiquidOutput(pipe, out output))
            {
                return;
            }

            if (cells[output.x, output.y] == CellKind.Empty || IsWorldLiquidCell(cells[output.x, output.y]))
            {
                cells[output.x, output.y] = CellKind.Ice;
                waterMass[output.x, output.y] = 0f;
                equipmentCondition[output.x, output.y] = 0f;
                plantGrowth[output.x, output.y] = 0f;
                cropTendedSeconds[output.x, output.y] = 0f;
                cropStress[output.x, output.y] = 0f;
                oxygen[output.x, output.y] = 0f;
                carbonDioxide[output.x, output.y] = 0f;
                pollutedOxygen[output.x, output.y] = 0f;
                hydrogen[output.x, output.y] = 0f;
                steam[output.x, output.y] = 0f;
                chlorine[output.x, output.y] = 0f;
                naturalGas[output.x, output.y] = 0f;
                sourGas[output.x, output.y] = 0f;
                germs[output.x, output.y] = 0f;
                temperature[output.x, output.y] = Mathf.Clamp(Mathf.Min(-1.2f, temperature[pipe.x, pipe.y]), -30f, 120f);
                waterFrozenTiles++;
                CancelQueuedJobsAt(output);
                return;
            }

            ReleaseWaterToCell(output, amount);
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Min(temperature[output.x, output.y], PipeFreezeTemperature), -30f, 120f);
        }

        private void ReleaseFrozenPollutedPipeWater(Vector2Int pipe, float amount, float germLevel = PollutedWaterDefaultGermLevel)
        {
            if (amount <= 0.001f)
            {
                return;
            }

            if (!TryFindPipeLiquidOutput(pipe, out Vector2Int output))
            {
                StorePollutedWaterInStorage(amount, germLevel);
                return;
            }

            ReleasePollutedWaterToCell(output, amount, germLevel);
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Min(temperature[output.x, output.y], PollutedWaterFreezeTemperature), -30f, 120f);
        }

        private bool TryFindPipeSteamOutput(Vector2Int pipe, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                pipe,
                new Vector2Int(pipe.x, pipe.y + 1),
                new Vector2Int(pipe.x + 1, pipe.y),
                new Vector2Int(pipe.x - 1, pipe.y),
                new Vector2Int(pipe.x, pipe.y - 1)
            };

            float bestPressure = float.MaxValue;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !IsPassable(candidate.x, candidate.y))
                {
                    continue;
                }

                float pressure = TileGasTotal(candidate.x, candidate.y);
                if (pressure >= 2.78f || pressure >= bestPressure)
                {
                    continue;
                }

                bestPressure = pressure;
                output = candidate;
            }

            return output.x >= 0;
        }

        private bool TryFindPipeLiquidOutput(Vector2Int pipe, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                new Vector2Int(pipe.x, pipe.y - 1),
                pipe,
                new Vector2Int(pipe.x + 1, pipe.y),
                new Vector2Int(pipe.x - 1, pipe.y),
                new Vector2Int(pipe.x, pipe.y + 1)
            };

            float bestMass = float.MaxValue;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanLiquidOccupy(candidate.x, candidate.y))
                {
                    continue;
                }

                float free = LiquidFreeCapacity(candidate.x, candidate.y);
                float mass = LiquidMassAt(candidate.x, candidate.y);
                if (free <= LiquidMinimumRetainedMass || mass >= bestMass)
                {
                    continue;
                }

                bestMass = mass;
                output = candidate;
            }

            return output.x >= 0;
        }

        private float EquipmentOverheatSeverity(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float overheatTemperature = EquipmentOverheatTemperatureAt(x, y);
            float criticalOverheatTemperature = EquipmentCriticalOverheatTemperatureAt(x, y);
            float temperatureSeverity = temperature[x, y] <= overheatTemperature ? 0f :
                Mathf.Clamp01((temperature[x, y] - overheatTemperature) / Mathf.Max(0.001f, criticalOverheatTemperature - overheatTemperature));
            float steamSeverity = steam[x, y] <= EquipmentSteamOverheatMass || temperature[x, y] <= 52f ? 0f :
                Mathf.Clamp01(steam[x, y] / 2.8f) * Mathf.Clamp01((temperature[x, y] - 52f) / 48f);
            return Mathf.Clamp01(temperatureSeverity + steamSeverity);
        }

        private bool StepWorldLiquids(float deltaTime)
        {
            liquidTimer += deltaTime;
            if (liquidTimer < LiquidWorldStepInterval)
            {
                return false;
            }

            int steps = Mathf.Clamp(Mathf.FloorToInt(liquidTimer / LiquidWorldStepInterval), 1, 3);
            liquidTimer -= steps * LiquidWorldStepInterval;
            bool changed = false;
            for (int i = 0; i < steps; i++)
            {
                changed |= StepWorldLiquidOnce();
            }

            return changed;
        }

        private bool StepWorldLiquidOnce()
        {
            float movedMass = 0f;
            int movedEvents = 0;
            for (int y = 1; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!HasWorldLiquidAt(x, y))
                    {
                        continue;
                    }

                    float freeCapacity = LiquidFreeCapacity(x, y - 1);
                    if (freeCapacity <= LiquidMinimumRetainedMass)
                    {
                        continue;
                    }

                    float amount = Mathf.Min(LiquidVerticalStepMass, freeCapacity, waterMass[x, y]);
                    if (waterMass[x, y] - amount <= LiquidMinimumRetainedMass)
                    {
                        amount = waterMass[x, y];
                    }

                    float moved = MoveWorldLiquidMass(new Vector2Int(x, y), new Vector2Int(x, y - 1), amount);
                    if (moved > 0.001f)
                    {
                        movedMass += moved;
                        movedEvents++;
                    }
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!HasWorldLiquidAt(x, y) || CanLiquidFlowDown(x, y))
                    {
                        continue;
                    }

                    if (!TryFindLiquidSideTarget(x, y, out Vector2Int target))
                    {
                        continue;
                    }

                    float targetMass = LiquidMassAt(target.x, target.y);
                    float equalizingMass = Mathf.Max(0f, (waterMass[x, y] - targetMass) * 0.5f);
                    float amount = Mathf.Min(LiquidSideStepMass, equalizingMass, LiquidFreeCapacity(target.x, target.y));
                    if (amount <= 0.001f)
                    {
                        continue;
                    }

                    float moved = MoveWorldLiquidMass(new Vector2Int(x, y), target, amount);
                    if (moved > 0.001f)
                    {
                        movedMass += moved;
                        movedEvents++;
                    }
                }
            }

            if (movedMass <= 0.001f)
            {
                return false;
            }

            liquidFlowedMass += movedMass;
            liquidFlowEvents += movedEvents;
            return true;
        }

        private bool TryFindLiquidSideTarget(int x, int y, out Vector2Int target)
        {
            target = new Vector2Int(-1, -1);
            float sourceMass = LiquidMassAt(x, y);
            float bestMass = sourceMass;
            int firstDirection = ((x + y + liquidFlowEvents) & 1) == 0 ? -1 : 1;
            int secondDirection = -firstDirection;

            if (CanLiquidSpreadTo(x, y, x + firstDirection, y))
            {
                bestMass = LiquidMassAt(x + firstDirection, y);
                target = new Vector2Int(x + firstDirection, y);
            }

            if (CanLiquidSpreadTo(x, y, x + secondDirection, y))
            {
                float secondMass = LiquidMassAt(x + secondDirection, y);
                if (target.x < 0 || secondMass < bestMass - 0.001f)
                {
                    target = new Vector2Int(x + secondDirection, y);
                }
            }

            return target.x >= 0;
        }

        private float MoveWorldLiquidMass(Vector2Int from, Vector2Int to, float requestedAmount)
        {
            if (!IsInside(from.x, from.y) ||
                !IsInside(to.x, to.y) ||
                !HasWorldLiquidAt(from.x, from.y) ||
                !CanLiquidOccupy(to.x, to.y) ||
                requestedAmount <= 0.001f)
            {
                return 0f;
            }

            float sourceMass = waterMass[from.x, from.y];
            float targetMass = LiquidMassAt(to.x, to.y);
            float amount = Mathf.Min(requestedAmount, sourceMass, LiquidTileCapacity - targetMass);
            if (amount <= 0.001f)
            {
                return 0f;
            }

            bool targetWasEmpty = cells[to.x, to.y] == CellKind.Empty;
            bool sourcePolluted = IsPollutedWorldLiquidAt(from.x, from.y);
            bool targetPolluted = IsPollutedWorldLiquidAt(to.x, to.y);
            bool saltTransfer = IsSaltWaterWorldLiquidAt(from.x, from.y) || IsSaltWaterWorldLiquidAt(to.x, to.y);
            bool crudeTransfer = IsCrudeOilWorldLiquidAt(from.x, from.y) || IsCrudeOilWorldLiquidAt(to.x, to.y);
            bool petroleumTransfer = !crudeTransfer && (IsPetroleumWorldLiquidAt(from.x, from.y) || IsPetroleumWorldLiquidAt(to.x, to.y));
            float displacedOxygen = oxygen[to.x, to.y];
            float displacedCarbon = carbonDioxide[to.x, to.y];
            float displacedPolluted = pollutedOxygen[to.x, to.y];
            float displacedHydrogen = hydrogen[to.x, to.y];
            float displacedChlorine = chlorine[to.x, to.y];
            float displacedNaturalGas = naturalGas[to.x, to.y];
            float displacedSourGas = sourGas[to.x, to.y];
            float displacedGerms = germs[to.x, to.y];
            float sourceTemperature = temperature[from.x, from.y];
            float targetTemperature = temperature[to.x, to.y];
            float sourceGerms = germs[from.x, from.y];
            float targetGerms = targetWasEmpty ? 0f : germs[to.x, to.y];

            EnsureLiquidCell(to, crudeTransfer ? CellKind.CrudeOil : petroleumTransfer ? CellKind.Petroleum : sourcePolluted || targetPolluted ? CellKind.PollutedWater : saltTransfer ? CellKind.SaltWater : CellKind.Water);
            waterMass[from.x, from.y] = Mathf.Max(0f, sourceMass - amount);
            waterMass[to.x, to.y] = Mathf.Min(LiquidTileCapacity, targetMass + amount);

            float combinedMass = Mathf.Max(0.001f, targetMass + amount);
            temperature[to.x, to.y] = Mathf.Clamp(
                (targetTemperature * targetMass + sourceTemperature * amount) / combinedMass,
                -30f,
                120f);
            germs[to.x, to.y] = Mathf.Clamp01((targetGerms * targetMass + sourceGerms * amount) / combinedMass);
            oxygen[to.x, to.y] = 0f;
            carbonDioxide[to.x, to.y] = 0f;
            pollutedOxygen[to.x, to.y] = 0f;
            hydrogen[to.x, to.y] = 0f;
            steam[to.x, to.y] = 0f;
            chlorine[to.x, to.y] = 0f;
            naturalGas[to.x, to.y] = 0f;
            sourGas[to.x, to.y] = 0f;
            if (sourcePolluted || targetPolluted)
            {
                pollutedOxygen[to.x, to.y] = 0.04f;
                germs[to.x, to.y] = Mathf.Max(germs[to.x, to.y], 0.24f);
            }
            else if (crudeTransfer)
            {
                carbonDioxide[to.x, to.y] = 0.03f;
                naturalGas[to.x, to.y] = 0.02f;
            }

            if (waterMass[from.x, from.y] <= LiquidMinimumRetainedMass)
            {
                DryWaterCell(
                    from,
                    targetWasEmpty ? displacedOxygen : NeighborAverage(oxygen, from.x, from.y, 0.12f),
                    targetWasEmpty ? displacedCarbon : NeighborAverage(carbonDioxide, from.x, from.y, 0.04f),
                    targetWasEmpty ? displacedPolluted : NeighborAverage(pollutedOxygen, from.x, from.y, 0f),
                    targetWasEmpty ? displacedHydrogen : NeighborAverage(hydrogen, from.x, from.y, 0f),
                    targetWasEmpty ? displacedChlorine : NeighborAverage(chlorine, from.x, from.y, 0f),
                    targetWasEmpty ? displacedNaturalGas : NeighborAverage(naturalGas, from.x, from.y, 0f),
                    targetWasEmpty ? displacedGerms : NeighborAverage(germs, from.x, from.y, 0f),
                    Mathf.Lerp(sourceTemperature, targetTemperature, 0.35f),
                    targetWasEmpty ? displacedSourGas : NeighborAverage(sourGas, from.x, from.y, 0f));
                CancelQueuedJobsAt(from);
            }

            CancelQueuedJobsAt(to);
            DisplaceWorkersFromLiquid(to);
            return amount;
        }

        private void EnsureWaterCell(Vector2Int cell)
        {
            EnsureLiquidCell(cell, false);
        }

        private void EnsureLiquidCell(Vector2Int cell, bool polluted)
        {
            EnsureLiquidCell(cell, polluted ? CellKind.PollutedWater : CellKind.Water);
        }

        private void EnsureLiquidCell(Vector2Int cell, CellKind liquidKind)
        {
            if (!IsWorldLiquidCell(liquidKind))
            {
                liquidKind = CellKind.Water;
            }

            if (cells[cell.x, cell.y] != CellKind.Empty)
            {
                if (IsWorldLiquidCell(cells[cell.x, cell.y]))
                {
                    if (liquidKind == CellKind.CrudeOil || cells[cell.x, cell.y] == CellKind.CrudeOil)
                    {
                        cells[cell.x, cell.y] = CellKind.CrudeOil;
                    }
                    else if (liquidKind == CellKind.Petroleum || cells[cell.x, cell.y] == CellKind.Petroleum)
                    {
                        cells[cell.x, cell.y] = CellKind.Petroleum;
                    }
                    else if (liquidKind == CellKind.PollutedWater)
                    {
                        cells[cell.x, cell.y] = CellKind.PollutedWater;
                    }
                    else if (liquidKind == CellKind.SaltWater && cells[cell.x, cell.y] == CellKind.Water)
                    {
                        cells[cell.x, cell.y] = CellKind.SaltWater;
                    }
                }

                return;
            }

            cells[cell.x, cell.y] = liquidKind;
            waterMass[cell.x, cell.y] = 0f;
            equipmentCondition[cell.x, cell.y] = 0f;
            constructionMaterialGrade[cell.x, cell.y] = ConstructionMaterialGrade.Basic;
            plantGrowth[cell.x, cell.y] = 0f;
            cropTendedSeconds[cell.x, cell.y] = 0f;
            cropStress[cell.x, cell.y] = 0f;
            looseResourceKind[cell.x, cell.y] = LooseResourceKind.None;
            looseResourceAmount[cell.x, cell.y] = 0f;
        }

        private void DryWaterCell(Vector2Int cell, float restoredOxygen, float restoredCarbon, float restoredPolluted, float restoredHydrogen, float restoredChlorine, float restoredNaturalGas, float restoredGerms, float restoredTemperature, float restoredSourGas = 0f)
        {
            if (IsWorldLiquidCell(cells[cell.x, cell.y]))
            {
                cells[cell.x, cell.y] = CellKind.Empty;
                equipmentCondition[cell.x, cell.y] = 0f;
                constructionMaterialGrade[cell.x, cell.y] = ConstructionMaterialGrade.Basic;
            }

            waterMass[cell.x, cell.y] = 0f;
            oxygen[cell.x, cell.y] = Mathf.Max(0f, restoredOxygen);
            carbonDioxide[cell.x, cell.y] = Mathf.Max(0f, restoredCarbon);
            pollutedOxygen[cell.x, cell.y] = Mathf.Max(0f, restoredPolluted);
            hydrogen[cell.x, cell.y] = Mathf.Max(0f, restoredHydrogen);
            steam[cell.x, cell.y] = 0f;
            chlorine[cell.x, cell.y] = Mathf.Max(0f, restoredChlorine);
            naturalGas[cell.x, cell.y] = Mathf.Max(0f, restoredNaturalGas);
            sourGas[cell.x, cell.y] = Mathf.Max(0f, restoredSourGas);
            germs[cell.x, cell.y] = Mathf.Clamp01(restoredGerms);
            temperature[cell.x, cell.y] = Mathf.Clamp(restoredTemperature, -30f, 120f);
        }

        private bool CanLiquidOccupy(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            if (cells[x, y] == CellKind.MechanizedAirlock)
            {
                return IsMechanizedAirlockOpen(new Vector2Int(x, y));
            }

            return IsInside(x, y) &&
                (cells[x, y] == CellKind.Empty ||
                    IsWorldLiquidCell(cells[x, y]) ||
                    IsFloodableCellKind(cells[x, y]));
        }

        private bool HasWorldLiquidAt(int x, int y)
        {
            if (IsInside(x, y) && cells[x, y] == CellKind.MechanizedAirlock && !IsMechanizedAirlockOpen(new Vector2Int(x, y)))
            {
                return false;
            }

            return IsInside(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                (IsWorldLiquidCell(cells[x, y]) || IsFloodableCellKind(cells[x, y]));
        }

        private bool IsWorldLiquidCell(CellKind kind)
        {
            return kind == CellKind.Water || kind == CellKind.PollutedWater || kind == CellKind.SaltWater || kind == CellKind.CrudeOil || kind == CellKind.Petroleum;
        }

        private bool IsLiquidTepidizerBuildLiquid(CellKind kind)
        {
            return kind == CellKind.Water || kind == CellKind.PollutedWater || kind == CellKind.SaltWater;
        }

        private bool IsPollutedWorldLiquidAt(int x, int y)
        {
            return IsInside(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                (cells[x, y] == CellKind.PollutedWater || (IsFloodableCellKind(cells[x, y]) && IsPollutedMopCell(new Vector2Int(x, y))));
        }

        private bool IsCrudeOilWorldLiquidAt(int x, int y)
        {
            return IsInside(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                cells[x, y] == CellKind.CrudeOil;
        }

        private bool IsPetroleumWorldLiquidAt(int x, int y)
        {
            return IsInside(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                cells[x, y] == CellKind.Petroleum;
        }

        private bool IsSaltWaterWorldLiquidAt(int x, int y)
        {
            return IsInside(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                cells[x, y] == CellKind.SaltWater;
        }

        private float LiquidMassAt(int x, int y)
        {
            return CanLiquidOccupy(x, y) ? Mathf.Max(0f, waterMass[x, y]) : 0f;
        }

        private float LiquidFreeCapacity(int x, int y)
        {
            return CanLiquidOccupy(x, y) ? Mathf.Max(0f, LiquidTileCapacity - LiquidMassAt(x, y)) : 0f;
        }

        private bool CanLiquidFlowDown(int x, int y)
        {
            return IsInside(x, y) &&
                HasWorldLiquidAt(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                y > 0 &&
                LiquidFreeCapacity(x, y - 1) > LiquidMinimumRetainedMass;
        }

        private bool CanLiquidSpreadSideways(int x, int y)
        {
            return IsInside(x, y) &&
                HasWorldLiquidAt(x, y) &&
                waterMass[x, y] > LiquidMinimumRetainedMass &&
                !CanLiquidFlowDown(x, y) &&
                (CanLiquidSpreadTo(x, y, x - 1, y) || CanLiquidSpreadTo(x, y, x + 1, y));
        }

        private bool CanLiquidSpreadTo(int fromX, int fromY, int toX, int toY)
        {
            return CanLiquidOccupy(toX, toY) &&
                LiquidFreeCapacity(toX, toY) > LiquidMinimumRetainedMass &&
                LiquidMassAt(fromX, fromY) > LiquidMassAt(toX, toY) + 1.5f;
        }

        private int CountFlowingLiquidTiles()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (HasWorldLiquidAt(x, y) && (CanLiquidFlowDown(x, y) || CanLiquidSpreadSideways(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string LiquidFlowStateText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !HasWorldLiquidAt(cell.x, cell.y))
            {
                return string.Empty;
            }

            if (CanLiquidFlowDown(cell.x, cell.y))
            {
                return "Flowing: falling into open space below.";
            }

            if (CanLiquidSpreadSideways(cell.x, cell.y))
            {
                return "Flowing: spreading across the floor.";
            }

            return "Settled liquid.";
        }

        private bool IsFloodableCellKind(CellKind kind)
        {
            return kind == CellKind.Ladder ||
                kind == CellKind.FirePole ||
                kind == CellKind.MeshTile ||
                kind == CellKind.TempshiftPlate ||
                IsRepairableEquipment(kind);
        }

        private bool IsWaterTolerantEquipment(CellKind kind)
        {
            return kind == CellKind.WaterPump ||
                kind == CellKind.LiquidVent ||
                kind == CellKind.BottleEmptier ||
                kind == CellKind.LiquidReservoir ||
                kind == CellKind.LiquidPipeSensor ||
                kind == CellKind.LiquidShutoff ||
                kind == CellKind.LiquidValve ||
                kind == CellKind.LiquidTepidizer ||
                kind == CellKind.ThermoAquatuner ||
                kind == CellKind.HydroSensor ||
                kind == CellKind.MechanizedAirlock ||
                kind == CellKind.BunkerDoor;
        }

        private bool IsEquipmentSubmerged(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsRepairableEquipment(cells[cell.x, cell.y]) &&
                !IsWaterTolerantEquipment(cells[cell.x, cell.y]) &&
                waterMass[cell.x, cell.y] >= SubmergedEquipmentWaterMass;
        }

        private bool IsPowerWireFlooded(int x, int y)
        {
            return IsInside(x, y) &&
                powerWire[x, y] &&
                waterMass[x, y] >= FloodedWireWaterMass;
        }

        private int CountSubmergedEquipment()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsEquipmentSubmerged(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountFloodedPowerWires()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPowerWireFlooded(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void DisplaceWorkersFromLiquid(Vector2Int cell)
        {
            if (IsInside(cell.x, cell.y) && cells[cell.x, cell.y] == CellKind.MeshTile)
            {
                return;
            }

            Worker worker = WorkerAt(cell);
            if (worker == null || worker.Health <= 0f)
            {
                return;
            }

            ClearAssignment(worker);
            if (TryFindOpenSpawnNear(cell, out Vector2Int safeCell))
            {
                worker.Cell = safeCell;
                if (worker.Transform != null)
                {
                    worker.Transform.position = CellCenter(safeCell);
                }

                worker.Stress = Mathf.Min(100f, worker.Stress + 2.5f);
                worker.Activity = "Avoiding Water";
                return;
            }

            worker.Stress = Mathf.Min(100f, worker.Stress + 5f);
            worker.Health = Mathf.Max(0f, worker.Health - 1f);
            worker.Activity = "Trapped in Water";
        }

        private void SimulateVentilation(float deltaTime)
        {
            bool changed = false;
            changed |= RunGasPumps(deltaTime);
            changed |= RunGasBridges(deltaTime);
            changed |= EqualizeGasPipes(deltaTime);
            changed |= RunGasReservoirs(deltaTime);
            changed |= RunGasVents(deltaTime);

            if (changed)
            {
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private bool RunGasPumps(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.GasPump)
                    {
                        continue;
                    }

                    Vector2Int pump = new Vector2Int(x, y);
                    if (IsBrokenEquipment(pump) ||
                        !CanPoweredMachineRun(pump) ||
                        !TryFindGasSource(pump, out Vector2Int source) ||
                        !TryFindAdjacentGasPipeWithSpace(pump, out Vector2Int pipe))
                    {
                        continue;
                    }

                    float sourceTotal = TilePumpableGasTotal(source.x, source.y);
                    float pipeFree = GasPipeCapacity - GasPipeTotal(pipe.x, pipe.y);
                    float powerUsed = Mathf.Min(power, 0.20f * deltaTime);
                    float efficiency = powerUsed / Mathf.Max(0.001f, 0.20f * deltaTime);
                    float amount = Mathf.Min(sourceTotal, Mathf.Min(pipeFree, GasPumpRate * deltaTime * efficiency));
                    if (amount <= 0.001f)
                    {
                        continue;
                    }

                    float moved = MoveTileGasToPipe(source, pipe, amount);
                    if (moved <= 0.001f)
                    {
                        continue;
                    }

                    ConsumeCyclePower(powerUsed);
                    AddHeat(pump, 0.025f * deltaTime * efficiency, 1);
                    WearEquipment(pump, 0.00028f * deltaTime * efficiency);
                    changed = true;
                }
            }

            return changed;
        }

        private bool CanGasPumpRun(Vector2Int pump)
        {
            return IsInside(pump.x, pump.y) &&
                cells[pump.x, pump.y] == CellKind.GasPump &&
                !IsBrokenEquipment(pump) &&
                CanPoweredMachineRun(pump) &&
                TryFindGasSource(pump, out _) &&
                TryFindAdjacentGasPipeWithSpace(pump, out _);
        }

        private bool RunGasBridges(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.GasBridge)
                    {
                        continue;
                    }

                    Vector2Int bridge = new Vector2Int(x, y);
                    if (!CanUseEquipment(bridge))
                    {
                        continue;
                    }

                    BridgeDirection direction = BridgeDirectionAt(x, y);
                    bool moved = MoveGasBridgePair(bridge, BridgeInputOffset(direction), BridgeOutputOffset(direction), deltaTime);
                    if (moved)
                    {
                        WearEquipment(bridge, 0.00004f * deltaTime);
                        changed = true;
                    }
                }
            }

            return changed;
        }

        private bool MoveGasBridgePair(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, float deltaTime)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsGasBridgeEndpoint(input) || !IsGasBridgeEndpoint(output))
            {
                return false;
            }

            float sourceMass = GasPipeTotal(input.x, input.y);
            float outputFree = GasPipeCapacity - GasPipeTotal(output.x, output.y);
            float amount = Mathf.Min(GasBridgeRate * deltaTime, Mathf.Min(sourceMass, outputFree));
            if (amount <= 0.001f)
            {
                return false;
            }

            float moved = MoveGasPipeToPipe(input.x, input.y, output.x, output.y, amount);
            if (moved <= 0.001f)
            {
                return false;
            }

            TrackAutomatedConduitFlow(input.x, input.y, output.x, output.y, moved, true);
            gasBridgeMovedMass += moved;
            return true;
        }

        private bool IsGasBridgeEndpoint(Vector2Int pipe)
        {
            return IsInside(pipe.x, pipe.y) &&
                gasPipe[pipe.x, pipe.y] &&
                !IsGasConduitBlocked(pipe.x, pipe.y);
        }

        private bool EqualizeGasPipes(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!gasPipe[x, y])
                    {
                        continue;
                    }

                    changed |= EqualizeGasPipePair(x, y, x + 1, y, deltaTime);
                    changed |= EqualizeGasPipePair(x, y, x, y + 1, deltaTime);
                }
            }

            return changed;
        }

        private bool EqualizeGasPipePair(int ax, int ay, int bx, int by, float deltaTime)
        {
            if (!IsInside(bx, by) ||
                !gasPipe[ax, ay] ||
                !gasPipe[bx, by] ||
                IsGasConduitBlocked(ax, ay) ||
                IsGasConduitBlocked(bx, by))
            {
                return false;
            }

            float aTotal = GasPipeTotal(ax, ay);
            float bTotal = GasPipeTotal(bx, by);
            float difference = aTotal - bTotal;
            if (Mathf.Abs(difference) < 0.01f)
            {
                return false;
            }

            float flow = Mathf.Clamp(difference * 0.45f * deltaTime, -GasPipeCapacity * 0.45f, GasPipeCapacity * 0.45f);
            float moved;
            if (flow > 0f)
            {
                flow = Mathf.Min(flow, aTotal, GasPipeCapacity - bTotal);
                moved = MoveGasPipeToPipe(ax, ay, bx, by, flow);
                flow = moved;
            }
            else
            {
                float reverse = Mathf.Min(-flow, bTotal, GasPipeCapacity - aTotal);
                moved = MoveGasPipeToPipe(bx, by, ax, ay, reverse);
                flow = -moved;
            }

            moved = Mathf.Abs(flow);
            if (moved > 0.001f)
            {
                TrackAutomatedConduitFlow(ax, ay, bx, by, moved, true);
            }

            return moved > 0.001f;
        }

        private bool RunGasVents(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    CellKind kind = cells[x, y];
                    if (!IsGasVentKind(kind))
                    {
                        continue;
                    }

                    Vector2Int vent = new Vector2Int(x, y);
                    if (!CanUseEquipment(vent) ||
                        !TryFindAdjacentGasPipeWithGas(vent, out Vector2Int pipe) ||
                        !TryFindGasVentOutput(vent, kind, out Vector2Int output))
                    {
                        continue;
                    }

                    float outputFree = GasVentMaxPressureForKind(kind) - TileGasTotal(output.x, output.y);
                    float amount = Mathf.Min(GasPipeTotal(pipe.x, pipe.y), Mathf.Min(GasVentRateForKind(kind) * deltaTime, outputFree));
                    if (amount <= 0.001f)
                    {
                        continue;
                    }

                    float moved = MoveGasPipeToTile(pipe, output, amount);
                    if (moved <= 0.001f)
                    {
                        continue;
                    }

                    WearEquipment(vent, 0.00012f * deltaTime);
                    changed = true;
                }
            }

            return changed;
        }

        private bool IsGasVentKind(CellKind kind)
        {
            return kind == CellKind.GasVent || kind == CellKind.HighPressureGasVent;
        }

        private float GasVentRateForKind(CellKind kind)
        {
            return kind == CellKind.HighPressureGasVent ? HighPressureGasVentRate : GasVentRate;
        }

        private float GasVentOpenPressureForKind(CellKind kind)
        {
            return kind == CellKind.HighPressureGasVent ? HighPressureGasVentOpenPressure : GasVentOpenPressure;
        }

        private float GasVentMaxPressureForKind(CellKind kind)
        {
            return kind == CellKind.HighPressureGasVent ? HighPressureGasVentMaxPressure : GasVentMaxPressure;
        }

        private bool RunGasReservoirs(float deltaTime)
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.GasReservoir)
                    {
                        continue;
                    }

                    Vector2Int reservoir = new Vector2Int(x, y);
                    if (!CanUseEquipment(reservoir))
                    {
                        continue;
                    }

                    Vector2Int inputPipe = new Vector2Int(-1, -1);
                    float stored = GasReservoirTotal(x, y);
                    if (stored < GasReservoirCapacity - 0.001f &&
                        TryFindAdjacentGasPipeWithGas(reservoir, out inputPipe))
                    {
                        float amount = Mathf.Min(
                            GasPipeTotal(inputPipe.x, inputPipe.y),
                            Mathf.Min(GasReservoirRate * deltaTime, GasReservoirCapacity - stored));
                        if (amount > 0.001f)
                        {
                            float moved = MoveGasPipeToReservoir(inputPipe, reservoir, amount);
                            if (moved > 0.001f)
                            {
                                stored = GasReservoirTotal(x, y);
                                reservoirBufferedMass += moved;
                                WearEquipment(reservoir, 0.00008f * deltaTime);
                                changed = true;
                            }
                        }
                    }

                    if (stored > 0.001f &&
                        TryFindAdjacentGasPipeWithSpaceExcluding(reservoir, inputPipe, out Vector2Int outputPipe))
                    {
                        float amount = Mathf.Min(
                            stored,
                            Mathf.Min(GasReservoirRate * deltaTime, GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y)));
                        if (amount > 0.001f)
                        {
                            float moved = MoveGasReservoirToPipe(reservoir, outputPipe, amount);
                            if (moved <= 0.001f)
                            {
                                continue;
                            }

                            WearEquipment(reservoir, 0.00006f * deltaTime);
                            changed = true;
                        }
                    }
                }
            }

            return changed;
        }

        private bool IsLiquidConduitBlocked(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            return (cells[x, y] == CellKind.LiquidShutoff && !IsConduitShutoffOpen(cell)) ||
                (cells[x, y] == CellKind.LiquidValve && !IsConduitValveOpen(cell));
        }

        private bool IsGasConduitBlocked(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            return (cells[x, y] == CellKind.GasShutoff && !IsConduitShutoffOpen(cell)) ||
                (cells[x, y] == CellKind.GasValve && !IsConduitValveOpen(cell));
        }

        private void ResetConduitValveFlowBudgets(float deltaTime)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    liquidValveFlowRemaining[x, y] = cells[x, y] == CellKind.LiquidValve && IsConduitValveOpen(cell) ? Mathf.Max(0f, LiquidValveFlowLimitAt(x, y) * deltaTime) : 0f;
                    gasValveFlowRemaining[x, y] = cells[x, y] == CellKind.GasValve && IsConduitValveOpen(cell) ? Mathf.Max(0f, GasValveFlowLimitAt(x, y) * deltaTime) : 0f;
                }
            }
        }

        private float LiquidValveFlowLimitAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return LiquidValveMaxFlow;
            }

            return Mathf.Clamp(liquidValveFlowLimit[x, y] <= 0.001f ? LiquidValveMaxFlow : liquidValveFlowLimit[x, y], LiquidValveMinFlow, LiquidValveFlowLimitMax);
        }

        private float GasValveFlowLimitAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return GasValveMaxFlow;
            }

            return Mathf.Clamp(gasValveFlowLimit[x, y] <= 0.001f ? GasValveMaxFlow : gasValveFlowLimit[x, y], GasValveMinFlow, GasValveFlowLimitMax);
        }

        private bool IsConduitValveOpen(Vector2Int cell)
        {
            return CanUseEquipment(cell) && AutomationPortAllows(cell);
        }

        private bool IsLiquidValve(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && cells[cell.x, cell.y] == CellKind.LiquidValve;
        }

        private bool IsGasValve(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && cells[cell.x, cell.y] == CellKind.GasValve;
        }

        private float LimitLiquidValveFlow(Vector2Int pipe, float amount)
        {
            return LimitLiquidValveFlow(pipe, pipe, amount);
        }

        private float LimitLiquidValveFlow(Vector2Int from, Vector2Int to, float amount)
        {
            if (amount <= 0f)
            {
                return 0f;
            }

            bool fromValve = IsLiquidValve(from);
            bool toValve = to != from && IsLiquidValve(to);
            if ((fromValve && !IsConduitValveOpen(from)) || (toValve && !IsConduitValveOpen(to)))
            {
                return 0f;
            }

            float limited = amount;
            if (fromValve)
            {
                limited = Mathf.Min(limited, liquidValveFlowRemaining[from.x, from.y]);
            }

            if (toValve)
            {
                limited = Mathf.Min(limited, liquidValveFlowRemaining[to.x, to.y]);
            }

            if (limited <= 0.001f)
            {
                return 0f;
            }

            if (fromValve)
            {
                liquidValveFlowRemaining[from.x, from.y] = Mathf.Max(0f, liquidValveFlowRemaining[from.x, from.y] - limited);
            }

            if (toValve)
            {
                liquidValveFlowRemaining[to.x, to.y] = Mathf.Max(0f, liquidValveFlowRemaining[to.x, to.y] - limited);
            }

            return limited;
        }

        private float LimitGasValveFlow(Vector2Int pipe, float amount)
        {
            return LimitGasValveFlow(pipe, pipe, amount);
        }

        private float LimitGasValveFlow(Vector2Int from, Vector2Int to, float amount)
        {
            if (amount <= 0f)
            {
                return 0f;
            }

            bool fromValve = IsGasValve(from);
            bool toValve = to != from && IsGasValve(to);
            if ((fromValve && !IsConduitValveOpen(from)) || (toValve && !IsConduitValveOpen(to)))
            {
                return 0f;
            }

            float limited = amount;
            if (fromValve)
            {
                limited = Mathf.Min(limited, gasValveFlowRemaining[from.x, from.y]);
            }

            if (toValve)
            {
                limited = Mathf.Min(limited, gasValveFlowRemaining[to.x, to.y]);
            }

            if (limited <= 0.001f)
            {
                return 0f;
            }

            if (fromValve)
            {
                gasValveFlowRemaining[from.x, from.y] = Mathf.Max(0f, gasValveFlowRemaining[from.x, from.y] - limited);
            }

            if (toValve)
            {
                gasValveFlowRemaining[to.x, to.y] = Mathf.Max(0f, gasValveFlowRemaining[to.x, to.y] - limited);
            }

            return limited;
        }

        private bool IsConduitShutoffOpen(Vector2Int cell)
        {
            if (!CanUseEquipment(cell))
            {
                return false;
            }

            return AutomationPortAllows(cell);
        }

        private void TrackAutomatedConduitFlow(int ax, int ay, int bx, int by, float amount, bool gasConduit)
        {
            bool controlled = false;
            if (gasConduit)
            {
                controlled |= TrackAutomatedConduitEndpoint(ax, ay, CellKind.GasShutoff, amount);
                controlled |= TrackAutomatedConduitEndpoint(bx, by, CellKind.GasShutoff, amount);
                controlled |= TrackAutomatedConduitEndpoint(ax, ay, CellKind.GasValve, amount);
                controlled |= TrackAutomatedConduitEndpoint(bx, by, CellKind.GasValve, amount);
            }
            else
            {
                controlled |= TrackAutomatedConduitEndpoint(ax, ay, CellKind.LiquidShutoff, amount);
                controlled |= TrackAutomatedConduitEndpoint(bx, by, CellKind.LiquidShutoff, amount);
                controlled |= TrackAutomatedConduitEndpoint(ax, ay, CellKind.LiquidValve, amount);
                controlled |= TrackAutomatedConduitEndpoint(bx, by, CellKind.LiquidValve, amount);
            }

            if (controlled)
            {
                automatedConduitFlow += amount;
            }
        }

        private bool TrackAutomatedConduitEndpoint(int x, int y, CellKind shutoffKind, float amount)
        {
            if (cells[x, y] != shutoffKind || amount <= 0.001f || !HasCachedAutomationControl(new Vector2Int(x, y)))
            {
                return false;
            }

            WearEquipment(new Vector2Int(x, y), 0.00005f * amount);
            return true;
        }

        private float MoveTileGasToPipe(Vector2Int source, Vector2Int pipe, float amount)
        {
            float sourceTotal = TilePumpableGasTotal(source.x, source.y);
            if (sourceTotal <= 0.001f)
            {
                return 0f;
            }

            amount = LimitGasValveFlow(pipe, Mathf.Min(amount, GasPipeCapacity - GasPipeTotal(pipe.x, pipe.y)));
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(oxygen[source.x, source.y], amount * oxygen[source.x, source.y] / sourceTotal);
            float carbonAmount = Mathf.Min(carbonDioxide[source.x, source.y], amount * carbonDioxide[source.x, source.y] / sourceTotal);
            float pollutedAmount = Mathf.Min(pollutedOxygen[source.x, source.y], amount * pollutedOxygen[source.x, source.y] / sourceTotal);
            float hydrogenAmount = Mathf.Min(hydrogen[source.x, source.y], amount * hydrogen[source.x, source.y] / sourceTotal);
            float steamAmount = Mathf.Min(steam[source.x, source.y], amount * steam[source.x, source.y] / sourceTotal);
            float chlorineAmount = Mathf.Min(chlorine[source.x, source.y], amount * chlorine[source.x, source.y] / sourceTotal);
            float naturalGasAmount = Mathf.Min(naturalGas[source.x, source.y], amount * naturalGas[source.x, source.y] / sourceTotal);
            float sourGasAmount = Mathf.Min(sourGas[source.x, source.y], amount * sourGas[source.x, source.y] / sourceTotal);
            AddGasToPipeWithSteam(pipe.x, pipe.y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, germs[source.x, source.y], temperature[source.x, source.y], sourGasAmount);
            oxygen[source.x, source.y] = Mathf.Max(0f, oxygen[source.x, source.y] - oxygenAmount);
            carbonDioxide[source.x, source.y] = Mathf.Max(0f, carbonDioxide[source.x, source.y] - carbonAmount);
            pollutedOxygen[source.x, source.y] = Mathf.Max(0f, pollutedOxygen[source.x, source.y] - pollutedAmount);
            hydrogen[source.x, source.y] = Mathf.Max(0f, hydrogen[source.x, source.y] - hydrogenAmount);
            steam[source.x, source.y] = Mathf.Max(0f, steam[source.x, source.y] - steamAmount);
            chlorine[source.x, source.y] = Mathf.Max(0f, chlorine[source.x, source.y] - chlorineAmount);
            naturalGas[source.x, source.y] = Mathf.Max(0f, naturalGas[source.x, source.y] - naturalGasAmount);
            sourGas[source.x, source.y] = Mathf.Max(0f, sourGas[source.x, source.y] - sourGasAmount);
            if (TilePumpableGasTotal(source.x, source.y) <= 0.01f)
            {
                germs[source.x, source.y] = 0f;
            }

            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private float MoveGasPipeToPipe(int fromX, int fromY, int toX, int toY, float amount)
        {
            return MoveGasPipeToPipeAtTemperature(fromX, fromY, toX, toY, amount, temperature[fromX, fromY]);
        }

        private float MoveGasPipeToPipeAtTemperature(Vector2Int from, Vector2Int to, float amount, float sourceTemperature)
        {
            return MoveGasPipeToPipeAtTemperature(from.x, from.y, to.x, to.y, amount, sourceTemperature);
        }

        private float MoveGasPipeToPipeAtTemperature(int fromX, int fromY, int toX, int toY, float amount, float sourceTemperature)
        {
            float fromTotal = GasPipeTotal(fromX, fromY);
            if (fromTotal <= 0.001f || amount <= 0.001f)
            {
                return 0f;
            }

            amount = Mathf.Min(amount, Mathf.Min(fromTotal, GasPipeCapacity - GasPipeTotal(toX, toY)));
            amount = LimitGasValveFlow(new Vector2Int(fromX, fromY), new Vector2Int(toX, toY), amount);
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasPipeOxygen[fromX, fromY], amount * gasPipeOxygen[fromX, fromY] / fromTotal);
            float carbonAmount = Mathf.Min(gasPipeCarbonDioxide[fromX, fromY], amount * gasPipeCarbonDioxide[fromX, fromY] / fromTotal);
            float pollutedAmount = Mathf.Min(gasPipePollutedOxygen[fromX, fromY], amount * gasPipePollutedOxygen[fromX, fromY] / fromTotal);
            float hydrogenAmount = Mathf.Min(gasPipeHydrogen[fromX, fromY], amount * gasPipeHydrogen[fromX, fromY] / fromTotal);
            float steamAmount = Mathf.Min(gasPipeSteam[fromX, fromY], amount * gasPipeSteam[fromX, fromY] / fromTotal);
            float chlorineAmount = Mathf.Min(gasPipeChlorine[fromX, fromY], amount * gasPipeChlorine[fromX, fromY] / fromTotal);
            float naturalGasAmount = Mathf.Min(gasPipeNaturalGas[fromX, fromY], amount * gasPipeNaturalGas[fromX, fromY] / fromTotal);
            float sourGasAmount = Mathf.Min(gasPipeSourGas[fromX, fromY], amount * gasPipeSourGas[fromX, fromY] / fromTotal);
            AddGasToPipeWithSteam(toX, toY, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, gasPipeGerms[fromX, fromY], sourceTemperature, sourGasAmount);
            gasPipeOxygen[fromX, fromY] = Mathf.Max(0f, gasPipeOxygen[fromX, fromY] - oxygenAmount);
            gasPipeCarbonDioxide[fromX, fromY] = Mathf.Max(0f, gasPipeCarbonDioxide[fromX, fromY] - carbonAmount);
            gasPipePollutedOxygen[fromX, fromY] = Mathf.Max(0f, gasPipePollutedOxygen[fromX, fromY] - pollutedAmount);
            gasPipeHydrogen[fromX, fromY] = Mathf.Max(0f, gasPipeHydrogen[fromX, fromY] - hydrogenAmount);
            gasPipeSteam[fromX, fromY] = Mathf.Max(0f, gasPipeSteam[fromX, fromY] - steamAmount);
            gasPipeChlorine[fromX, fromY] = Mathf.Max(0f, gasPipeChlorine[fromX, fromY] - chlorineAmount);
            gasPipeNaturalGas[fromX, fromY] = Mathf.Max(0f, gasPipeNaturalGas[fromX, fromY] - naturalGasAmount);
            gasPipeSourGas[fromX, fromY] = Mathf.Max(0f, gasPipeSourGas[fromX, fromY] - sourGasAmount);
            ClearGasPipeGermsIfEmpty(fromX, fromY);

            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private float MoveGasPipeToTile(Vector2Int pipe, Vector2Int output, float amount)
        {
            float pipeTotal = GasPipeTotal(pipe.x, pipe.y);
            if (pipeTotal <= 0.001f || amount <= 0.001f)
            {
                return 0f;
            }

            amount = LimitGasValveFlow(pipe, amount);
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasPipeOxygen[pipe.x, pipe.y], amount * gasPipeOxygen[pipe.x, pipe.y] / pipeTotal);
            float carbonAmount = Mathf.Min(gasPipeCarbonDioxide[pipe.x, pipe.y], amount * gasPipeCarbonDioxide[pipe.x, pipe.y] / pipeTotal);
            float pollutedAmount = Mathf.Min(gasPipePollutedOxygen[pipe.x, pipe.y], amount * gasPipePollutedOxygen[pipe.x, pipe.y] / pipeTotal);
            float hydrogenAmount = Mathf.Min(gasPipeHydrogen[pipe.x, pipe.y], amount * gasPipeHydrogen[pipe.x, pipe.y] / pipeTotal);
            float steamAmount = Mathf.Min(gasPipeSteam[pipe.x, pipe.y], amount * gasPipeSteam[pipe.x, pipe.y] / pipeTotal);
            float chlorineAmount = Mathf.Min(gasPipeChlorine[pipe.x, pipe.y], amount * gasPipeChlorine[pipe.x, pipe.y] / pipeTotal);
            float naturalGasAmount = Mathf.Min(gasPipeNaturalGas[pipe.x, pipe.y], amount * gasPipeNaturalGas[pipe.x, pipe.y] / pipeTotal);
            float sourGasAmount = Mathf.Min(gasPipeSourGas[pipe.x, pipe.y], amount * gasPipeSourGas[pipe.x, pipe.y] / pipeTotal);
            AddGasToTileWithSteam(output.x, output.y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, gasPipeGerms[pipe.x, pipe.y], temperature[pipe.x, pipe.y], sourGasAmount);
            gasPipeOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeOxygen[pipe.x, pipe.y] - oxygenAmount);
            gasPipeCarbonDioxide[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeCarbonDioxide[pipe.x, pipe.y] - carbonAmount);
            gasPipePollutedOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipePollutedOxygen[pipe.x, pipe.y] - pollutedAmount);
            gasPipeHydrogen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeHydrogen[pipe.x, pipe.y] - hydrogenAmount);
            gasPipeSteam[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSteam[pipe.x, pipe.y] - steamAmount);
            gasPipeChlorine[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeChlorine[pipe.x, pipe.y] - chlorineAmount);
            gasPipeNaturalGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeNaturalGas[pipe.x, pipe.y] - naturalGasAmount);
            gasPipeSourGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSourGas[pipe.x, pipe.y] - sourGasAmount);
            ClearGasPipeGermsIfEmpty(pipe.x, pipe.y);

            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private float MoveGasPipeToReservoir(Vector2Int pipe, Vector2Int reservoir, float amount)
        {
            float pipeTotal = GasPipeTotal(pipe.x, pipe.y);
            float free = GasReservoirCapacity - GasReservoirTotal(reservoir.x, reservoir.y);
            amount = Mathf.Min(amount, Mathf.Min(pipeTotal, free));
            if (pipeTotal <= 0.001f || amount <= 0.001f)
            {
                return 0f;
            }

            amount = LimitGasValveFlow(pipe, amount);
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasPipeOxygen[pipe.x, pipe.y], amount * gasPipeOxygen[pipe.x, pipe.y] / pipeTotal);
            float carbonAmount = Mathf.Min(gasPipeCarbonDioxide[pipe.x, pipe.y], amount * gasPipeCarbonDioxide[pipe.x, pipe.y] / pipeTotal);
            float pollutedAmount = Mathf.Min(gasPipePollutedOxygen[pipe.x, pipe.y], amount * gasPipePollutedOxygen[pipe.x, pipe.y] / pipeTotal);
            float hydrogenAmount = Mathf.Min(gasPipeHydrogen[pipe.x, pipe.y], amount * gasPipeHydrogen[pipe.x, pipe.y] / pipeTotal);
            float steamAmount = Mathf.Min(gasPipeSteam[pipe.x, pipe.y], amount * gasPipeSteam[pipe.x, pipe.y] / pipeTotal);
            float chlorineAmount = Mathf.Min(gasPipeChlorine[pipe.x, pipe.y], amount * gasPipeChlorine[pipe.x, pipe.y] / pipeTotal);
            float naturalGasAmount = Mathf.Min(gasPipeNaturalGas[pipe.x, pipe.y], amount * gasPipeNaturalGas[pipe.x, pipe.y] / pipeTotal);
            float sourGasAmount = Mathf.Min(gasPipeSourGas[pipe.x, pipe.y], amount * gasPipeSourGas[pipe.x, pipe.y] / pipeTotal);
            AddGasToReservoirWithSteam(reservoir.x, reservoir.y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, gasPipeGerms[pipe.x, pipe.y], temperature[pipe.x, pipe.y], sourGasAmount);
            gasPipeOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeOxygen[pipe.x, pipe.y] - oxygenAmount);
            gasPipeCarbonDioxide[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeCarbonDioxide[pipe.x, pipe.y] - carbonAmount);
            gasPipePollutedOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipePollutedOxygen[pipe.x, pipe.y] - pollutedAmount);
            gasPipeHydrogen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeHydrogen[pipe.x, pipe.y] - hydrogenAmount);
            gasPipeSteam[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSteam[pipe.x, pipe.y] - steamAmount);
            gasPipeChlorine[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeChlorine[pipe.x, pipe.y] - chlorineAmount);
            gasPipeNaturalGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeNaturalGas[pipe.x, pipe.y] - naturalGasAmount);
            gasPipeSourGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSourGas[pipe.x, pipe.y] - sourGasAmount);
            ClearGasPipeGermsIfEmpty(pipe.x, pipe.y);

            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private float MoveGasReservoirToPipe(Vector2Int reservoir, Vector2Int pipe, float amount)
        {
            float reservoirTotal = GasReservoirTotal(reservoir.x, reservoir.y);
            float pipeFree = GasPipeCapacity - GasPipeTotal(pipe.x, pipe.y);
            amount = Mathf.Min(amount, Mathf.Min(reservoirTotal, pipeFree));
            if (reservoirTotal <= 0.001f || amount <= 0.001f)
            {
                return 0f;
            }

            amount = LimitGasValveFlow(pipe, amount);
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasReservoirOxygen[reservoir.x, reservoir.y], amount * gasReservoirOxygen[reservoir.x, reservoir.y] / reservoirTotal);
            float carbonAmount = Mathf.Min(gasReservoirCarbonDioxide[reservoir.x, reservoir.y], amount * gasReservoirCarbonDioxide[reservoir.x, reservoir.y] / reservoirTotal);
            float pollutedAmount = Mathf.Min(gasReservoirPollutedOxygen[reservoir.x, reservoir.y], amount * gasReservoirPollutedOxygen[reservoir.x, reservoir.y] / reservoirTotal);
            float hydrogenAmount = Mathf.Min(gasReservoirHydrogen[reservoir.x, reservoir.y], amount * gasReservoirHydrogen[reservoir.x, reservoir.y] / reservoirTotal);
            float steamAmount = Mathf.Min(gasReservoirSteam[reservoir.x, reservoir.y], amount * gasReservoirSteam[reservoir.x, reservoir.y] / reservoirTotal);
            float chlorineAmount = Mathf.Min(gasReservoirChlorine[reservoir.x, reservoir.y], amount * gasReservoirChlorine[reservoir.x, reservoir.y] / reservoirTotal);
            float naturalGasAmount = Mathf.Min(gasReservoirNaturalGas[reservoir.x, reservoir.y], amount * gasReservoirNaturalGas[reservoir.x, reservoir.y] / reservoirTotal);
            float sourGasAmount = Mathf.Min(gasReservoirSourGas[reservoir.x, reservoir.y], amount * gasReservoirSourGas[reservoir.x, reservoir.y] / reservoirTotal);
            AddGasToPipeWithSteam(pipe.x, pipe.y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, steamAmount, chlorineAmount, naturalGasAmount, gasReservoirGerms[reservoir.x, reservoir.y], temperature[reservoir.x, reservoir.y], sourGasAmount);
            gasReservoirOxygen[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirOxygen[reservoir.x, reservoir.y] - oxygenAmount);
            gasReservoirCarbonDioxide[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirCarbonDioxide[reservoir.x, reservoir.y] - carbonAmount);
            gasReservoirPollutedOxygen[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirPollutedOxygen[reservoir.x, reservoir.y] - pollutedAmount);
            gasReservoirHydrogen[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirHydrogen[reservoir.x, reservoir.y] - hydrogenAmount);
            gasReservoirSteam[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirSteam[reservoir.x, reservoir.y] - steamAmount);
            gasReservoirChlorine[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirChlorine[reservoir.x, reservoir.y] - chlorineAmount);
            gasReservoirNaturalGas[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirNaturalGas[reservoir.x, reservoir.y] - naturalGasAmount);
            gasReservoirSourGas[reservoir.x, reservoir.y] = Mathf.Max(0f, gasReservoirSourGas[reservoir.x, reservoir.y] - sourGasAmount);
            ClearGasReservoirGermsIfEmpty(reservoir.x, reservoir.y);

            return oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private void AddGasToPipe(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float chlorineAmount, float naturalGasAmount, float germLevel)
        {
            AddGasToPipe(x, y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, chlorineAmount, naturalGasAmount, germLevel, temperature[x, y]);
        }

        private void AddGasToPipe(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float chlorineAmount, float naturalGasAmount, float germLevel, float sourceTemperature)
        {
            AddGasToPipeWithSteam(x, y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, 0f, chlorineAmount, naturalGasAmount, germLevel, sourceTemperature);
        }

        private void AddGasToPipeWithSteam(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float steamAmount, float chlorineAmount, float naturalGasAmount, float germLevel, float sourceTemperature, float sourGasAmount = 0f)
        {
            float oldTotal = GasPipeTotal(x, y);
            float free = GasPipeCapacity - oldTotal;
            float amount = oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
            if (free <= 0f || amount <= 0f)
            {
                return;
            }

            float scale = Mathf.Min(1f, free / amount);
            gasPipeOxygen[x, y] += oxygenAmount * scale;
            gasPipeCarbonDioxide[x, y] += carbonAmount * scale;
            gasPipePollutedOxygen[x, y] += pollutedAmount * scale;
            gasPipeHydrogen[x, y] += hydrogenAmount * scale;
            gasPipeSteam[x, y] += steamAmount * scale;
            gasPipeChlorine[x, y] += chlorineAmount * scale;
            gasPipeNaturalGas[x, y] += naturalGasAmount * scale;
            gasPipeSourGas[x, y] += sourGasAmount * scale;
            float added = amount * scale;
            if (added > 0.001f)
            {
                MixGasTemperature(x, y, oldTotal, sourceTemperature, added);
                gasPipeGerms[x, y] = MixConcentration(gasPipeGerms[x, y], oldTotal, germLevel, added);
            }
        }

