        private void AddGasToReservoirWithSteam(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float steamAmount, float chlorineAmount, float naturalGasAmount, float germLevel, float sourceTemperature, float sourGasAmount = 0f)
        {
            float oldTotal = GasReservoirTotal(x, y);
            float free = GasReservoirCapacity - oldTotal;
            float amount = oxygenAmount + carbonAmount + pollutedAmount + hydrogenAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
            if (free <= 0f || amount <= 0f)
            {
                return;
            }

            float scale = Mathf.Min(1f, free / amount);
            gasReservoirOxygen[x, y] += oxygenAmount * scale;
            gasReservoirCarbonDioxide[x, y] += carbonAmount * scale;
            gasReservoirPollutedOxygen[x, y] += pollutedAmount * scale;
            gasReservoirHydrogen[x, y] += hydrogenAmount * scale;
            gasReservoirSteam[x, y] += steamAmount * scale;
            gasReservoirChlorine[x, y] += chlorineAmount * scale;
            gasReservoirNaturalGas[x, y] += naturalGasAmount * scale;
            gasReservoirSourGas[x, y] += sourGasAmount * scale;
            float added = amount * scale;
            if (added > 0.001f)
            {
                MixGasTemperature(x, y, oldTotal, sourceTemperature, added);
