        private void AddGasToTile(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float chlorineAmount, float naturalGasAmount, float germLevel)
        {
            AddGasToTile(x, y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, chlorineAmount, naturalGasAmount, germLevel, temperature[x, y]);
        }

        private void AddGasToTile(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float chlorineAmount, float naturalGasAmount, float germLevel, float sourceTemperature)
        {
            AddGasToTileWithSteam(x, y, oxygenAmount, carbonAmount, pollutedAmount, hydrogenAmount, 0f, chlorineAmount, naturalGasAmount, germLevel, sourceTemperature);
        }

        private void AddGasToTileWithSteam(int x, int y, float oxygenAmount, float carbonAmount, float pollutedAmount, float hydrogenAmount, float steamAmount, float chlorineAmount, float naturalGasAmount, float germLevel, float sourceTemperature, float sourGasAmount = 0f)
        {
            float oldTotal = TileGasTotal(x, y);
            oxygen[x, y] = Mathf.Min(2.8f, oxygen[x, y] + oxygenAmount);
            carbonDioxide[x, y] = Mathf.Min(2.8f, carbonDioxide[x, y] + carbonAmount);
            pollutedOxygen[x, y] = Mathf.Min(2.8f, pollutedOxygen[x, y] + pollutedAmount);
            hydrogen[x, y] = Mathf.Min(2.8f, hydrogen[x, y] + hydrogenAmount);
            steam[x, y] = Mathf.Min(2.8f, steam[x, y] + steamAmount);
            chlorine[x, y] = Mathf.Min(2.8f, chlorine[x, y] + chlorineAmount);
            naturalGas[x, y] = Mathf.Min(2.8f, naturalGas[x, y] + naturalGasAmount);
            sourGas[x, y] = Mathf.Min(2.8f, sourGas[x, y] + sourGasAmount);
            float added = Mathf.Max(0f, TileGasTotal(x, y) - oldTotal);
            if (added > 0.001f)
            {
                MixGasTemperature(x, y, oldTotal, sourceTemperature, added);
                germs[x, y] = MixConcentration(germs[x, y], oldTotal, germLevel, added);
            }
        }

        private void MixGasTemperature(int x, int y, float oldMass, float incomingTemperature, float incomingMass)
        {
            if (!IsInside(x, y) || incomingMass <= 0f)
            {
                return;
            }

            oldMass = Mathf.Max(0f, oldMass);
            float totalMass = oldMass + incomingMass;
            if (totalMass <= 0.001f)
            {
                temperature[x, y] = Mathf.Clamp(incomingTemperature, -30f, 120f);
                return;
            }

            float mixed = ((temperature[x, y] * oldMass) + (incomingTemperature * incomingMass)) / totalMass;
            temperature[x, y] = Mathf.Clamp(mixed, -30f, 120f);
        }

        private void ClearGasPipeGermsIfEmpty(int x, int y)
        {
            if (GasPipeTotal(x, y) <= 0.001f)
            {
                gasPipeGerms[x, y] = 0f;
            }
        }

        private void ClearGasReservoirGermsIfEmpty(int x, int y)
        {
            if (GasReservoirTotal(x, y) <= 0.001f)
            {
                gasReservoirGerms[x, y] = 0f;
            }
        }

        private void ReleaseGasPipeContents(Vector2Int pipe)
        {
            if (!IsInside(pipe.x, pipe.y) || !IsPassable(pipe.x, pipe.y))
            {
                return;
            }

            AddGasToTileWithSteam(
                pipe.x,
                pipe.y,
                gasPipeOxygen[pipe.x, pipe.y],
                gasPipeCarbonDioxide[pipe.x, pipe.y],
                gasPipePollutedOxygen[pipe.x, pipe.y],
                gasPipeHydrogen[pipe.x, pipe.y],
                gasPipeSteam[pipe.x, pipe.y],
                gasPipeChlorine[pipe.x, pipe.y],
                gasPipeNaturalGas[pipe.x, pipe.y],
                gasPipeGerms[pipe.x, pipe.y],
                temperature[pipe.x, pipe.y],
                gasPipeSourGas[pipe.x, pipe.y]);
        }

        private float VentPollutedOxygen(Vector2Int center, float amount, float germAmount)
        {
            float emitted = 0f;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        float before = pollutedOxygen[x, y];
                        pollutedOxygen[x, y] = Mathf.Min(2.4f, pollutedOxygen[x, y] + amount);
                        emitted += Mathf.Max(0f, pollutedOxygen[x, y] - before);
                        germs[x, y] = Mathf.Min(1f, germs[x, y] + germAmount);
                    }
                }
            }

            return emitted;
        }

        private float VentChlorine(Vector2Int center, float amount)
        {
            float emitted = 0f;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        float before = chlorine[x, y];
                        chlorine[x, y] = Mathf.Min(2.4f, chlorine[x, y] + amount);
                        emitted += Mathf.Max(0f, chlorine[x, y] - before);
                    }
                }
            }

            return emitted;
        }

        private void RunAirDeodorizer(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !CanUseEquipment(center))
            {
                return;
            }

            float fullCleanTarget = AirDeodorizerPollutedOxygenRate * deltaTime;
            float targetCleaned = Mathf.Min(PollutedOxygenAround(center, AirDeodorizerRadius), fullCleanTarget);
            if (targetCleaned <= 0.001f)
            {
                return;
            }

            float targetScale = targetCleaned / Mathf.Max(0.001f, fullCleanTarget);
            float targetPower = AirDeodorizerPowerRate * deltaTime * targetScale;
            float targetDirt = AirDeodorizerFilterDirtRate * deltaTime * targetScale;
            float powerScale = targetPower <= 0.001f ? 1f : Mathf.Clamp01(power / targetPower);
            float dirtScale = targetDirt <= 0.001f ? 1f : Mathf.Clamp01(dirt / targetDirt);
            float resourceScale = Mathf.Min(powerScale, dirtScale);
            if (resourceScale <= 0.001f)
            {
                return;
            }

            float requestedCleaned = targetCleaned * resourceScale;
            float cleaned = CleanPollutedOxygenAround(center, requestedCleaned, AirDeodorizerRadius, AirDeodorizerOxygenYield, AirDeodorizerGermReductionRate * deltaTime * resourceScale);
            if (cleaned <= 0.001f)
            {
                return;
            }

            float actualScale = cleaned / Mathf.Max(0.001f, targetCleaned);
            float powerUsed = Mathf.Min(power, targetPower * actualScale);
            float filterDirtUsed = Mathf.Min(dirt, targetDirt * actualScale);
            ConsumeCyclePower(powerUsed);
            dirt = Mathf.Max(0f, dirt - filterDirtUsed);
            float pollutedDirtProduced = cleaned * AirDeodorizerPollutedDirtYield;
            pollutedDirt += pollutedDirtProduced;
            pollutedOxygenFiltered += cleaned;
            if (HasPollutedOxygenVentNearby(center, AirDeodorizerRadius + 4))
            {
                pollutedOxygenVentPollutedOxygenFiltered += cleaned;
            }

            deodorizerFilterDirtUsed += filterDirtUsed;
            deodorizerPollutedDirtProduced += pollutedDirtProduced;
            AddHeat(center, 0.025f * deltaTime * actualScale, 1);
            WearEquipment(center, 0.00026f * deltaTime * actualScale);
            gasDirty = true;
            overlayDirty = true;
        }

        private string OxygenDiffuserReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.OxygenDiffuser)
            {
                return "Oxygen production blocked: Oxygen Diffuser missing.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (algae <= 0.02f)
            {
                return "Oxygen production blocked: Oxygen Diffuser needs algae.";
            }

            string poweredBlock = PoweredAtmosphereBlockText(cell);
            return string.IsNullOrEmpty(poweredBlock)
                ? "Oxygen production ready: Oxygen Diffuser can produce oxygen."
                : poweredBlock;
        }

        private string AirDeodorizerReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.AirDeodorizer)
            {
                return "Air cleaning blocked: Air Deodorizer missing.";
            }

            if (!techAirSystems)
            {
                return "Air cleaning blocked: research Air Systems.";
            }

            string poweredBlock = PoweredAtmosphereBlockText(cell);
            if (!string.IsNullOrEmpty(poweredBlock))
            {
                return poweredBlock;
            }

            if (PollutedOxygenAround(cell, AirDeodorizerRadius) <= 0.001f)
            {
                return "Air cleaning idle: no polluted oxygen nearby.";
            }

            if (dirt <= 0.05f)
            {
                return "Air cleaning blocked: needs filtration dirt.";
            }

            return "Air cleaning ready: Air Deodorizer can filter polluted oxygen.";
        }

