        private string WaterPumpReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.WaterPump)
            {
                return "Plumbing blocked: Water Pump missing.";
            }

            if (IsBrokenEquipment(cell))
            {
                return "Plumbing blocked: Water Pump needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Plumbing blocked: Water Pump is submerged.";
            }

            if (!TryFindAdjacentWater(cell, out _))
            {
                return "Plumbing blocked: Water Pump needs adjacent liquid.";
            }

            if (HasLiquidPipeAccess(cell))
            {
                if (!TryFindAdjacentPipePumpLiquid(cell, out _))
                {
                    return "Plumbing pipe output blocked: source cannot enter pump output pipe. Manual pumping can still store it.";
                }

                string poweredBlock = PoweredPlumbingBlockText(cell);
                if (!string.IsNullOrEmpty(poweredBlock))
                {
                    return poweredBlock;
                }

                if (!TryFindAdjacentLiquidPipeWithSpace(cell, out _))
                {
                    return "Plumbing pipe output blocked: output liquid pipe is full or blocked.";
                }

                return "Plumbing ready: Water Pump can send liquid into pipes.";
            }

            Job pumpJob = FindJobAt(cell, JobType.PumpWater);
            if (pumpJob != null)
            {
                return "Manual pumping ready: pump errand queued. " + JobReachabilityText(pumpJob);
            }

            if (CountActiveWorkers() == 0)
            {
                return "Manual pumping blocked: no active duplicants.";
            }

            Job testJob = new Job(JobType.PumpWater, cell, 2.5f);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Manual pumping blocked: ",
                "Manual pumping blocked: no reachable duplicant.");
            if (!string.IsNullOrEmpty(routeBlock))
            {
                return routeBlock;
            }

            return "Manual pumping ready: duplicants can pump adjacent liquid.";
        }

        private string LiquidVentReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.LiquidVent)
            {
                return "Liquid vent blocked: Liquid Vent missing.";
            }

            string equipmentBlock = FluidEquipmentBlockText(cell, "Liquid vent");
            if (!string.IsNullOrEmpty(equipmentBlock))
            {
                return equipmentBlock;
            }

            if (!TryFindAdjacentLiquidPipeWithAnyLiquid(cell, out _))
            {
                return "Liquid vent blocked: needs input liquid pipe with liquid.";
            }

            if (!TryFindLiquidVentOutput(cell, out _))
            {
                return "Liquid vent blocked: output cell is blocked or full.";
            }

            return "Liquid vent ready: can release piped liquid.";
        }

        private string GasPumpReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.GasPump)
            {
                return "Gas pump blocked: Gas Pump missing.";
            }

            string poweredBlock = PoweredVentilationBlockText(cell, "Gas pump");
            if (!string.IsNullOrEmpty(poweredBlock))
            {
                return poweredBlock;
            }

            if (!TryFindGasSource(cell, out _))
            {
                return "Gas pump idle: no pumpable gas nearby.";
            }

            if (!TryFindAdjacentGasPipeWithSpace(cell, out _))
            {
                return "Gas pump blocked: output gas pipe is full or blocked.";
            }

            return "Gas pump ready: can move nearby gas into pipes.";
        }

        private string GasVentReadinessText(Vector2Int cell)
        {
            CellKind kind = IsInside(cell.x, cell.y) ? cells[cell.x, cell.y] : CellKind.Empty;
            if (!IsGasVentKind(kind))
            {
                return kind == CellKind.HighPressureGasVent
                    ? "High pressure gas vent blocked: High Pressure Gas Vent missing."
                    : "Gas vent blocked: Gas Vent missing.";
            }

            string equipmentBlock = FluidEquipmentBlockText(cell, "Gas vent");
            if (!string.IsNullOrEmpty(equipmentBlock))
            {
                return equipmentBlock;
            }

            if (!TryFindAdjacentGasPipeWithGas(cell, out _))
            {
                return "Gas vent blocked: needs input gas pipe with packets.";
            }

            if (!TryFindGasVentOutput(cell, kind, out _))
            {
                return "Gas vent blocked: output cell is blocked or overpressured.";
            }

            return "Gas vent ready: can release piped gas.";
        }

        private string LiquidReservoirReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.LiquidReservoir)
            {
                return "Liquid reservoir blocked: Liquid Reservoir missing.";
            }

            string equipmentBlock = FluidEquipmentBlockText(cell, "Liquid reservoir");
            if (!string.IsNullOrEmpty(equipmentBlock))
            {
                return equipmentBlock;
            }

            float stored = LiquidReservoirTotal(cell.x, cell.y);
            Vector2Int inputPipe = new Vector2Int(-1, -1);
            bool canInput = stored < LiquidReservoirCapacity - 0.001f &&
                TryFindAdjacentLiquidPipeWithAnyLiquid(cell, out inputPipe);
            bool canOutput = stored > 0.001f &&
                TryFindAdjacentLiquidPipeWithSpaceExcluding(cell, inputPipe, out _);
            if (canInput && canOutput)
            {
                return "Liquid reservoir ready: buffering liquid flow.";
            }

            if (canInput)
            {
                return "Liquid reservoir ready: filling from input pipe.";
            }

            if (canOutput)
            {
                return "Liquid reservoir ready: draining to output pipe.";
            }

            if (stored >= LiquidReservoirCapacity - 0.001f)
            {
                return "Liquid reservoir idle: tank is full and output pipe is blocked.";
            }

            if (stored <= 0.001f)
            {
                return "Liquid reservoir idle: empty and no input liquid.";
            }

            return "Liquid reservoir idle: no input liquid or output pipe space.";
        }

