        private string FluidEquipmentBlockText(Vector2Int cell, string label)
        {
            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                switch (label)
                {
                    case "Gas pump":
                        return "Gas pump blocked: needs repair.";
                    case "Gas vent":
                        return "Gas vent blocked: needs repair.";
                    case "Gas reservoir":
                        return "Gas reservoir blocked: needs repair.";
                    case "Liquid vent":
                        return "Liquid vent blocked: needs repair.";
                    case "Liquid reservoir":
                        return "Liquid reservoir blocked: needs repair.";
                    default:
                        return "Plumbing blocked: needs repair.";
                }
            }

            if (IsEquipmentSubmerged(cell))
            {
                switch (label)
                {
                    case "Gas pump":
                        return "Gas pump blocked: pump is submerged.";
                    case "Gas vent":
                        return "Gas vent blocked: vent is submerged.";
                    case "Gas reservoir":
                        return "Gas reservoir blocked: reservoir is submerged.";
                    case "Liquid vent":
                        return "Liquid vent blocked: vent is submerged.";
                    case "Liquid reservoir":
                        return "Liquid reservoir blocked: reservoir is submerged.";
                    default:
                        return "Plumbing blocked: machine is submerged.";
                }
            }

            return string.Empty;
        }

