        private string WheezewortReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.Wheezewort)
            {
                return "Natural cooling blocked: Wheezewort missing.";
            }

            float localGas = TileGasTotal(cell.x, cell.y);
            if (localGas <= 0.04f)
            {
                return "Natural cooling idle: Wheezewort needs surrounding gas.";
            }

            float localTemperature = AverageTemperatureAround(cell, WheezewortCoolingRadius);
            if (localTemperature <= WheezewortDormantTemperature)
            {
                return "Natural cooling idle: Wheezewort is dormant below temperature threshold.";
            }

            float localHydrogen = HydrogenAround(cell, 2);
            if (localHydrogen >= WheezewortHydrogenThreshold)
            {
                return "Natural cooling ready: hydrogen cooling bonus active.";
            }

            return "Natural cooling ready: add hydrogen nearby for stronger cooling.";
        }

