            {
                return "AETN cooling blocked: nullifier missing.";
            }

            float localTemperature = AverageTemperatureAround(cell, AntiEntropyCoolingRadius);
            if (localTemperature <= AntiEntropyDormantTemperature)
            {
                return "AETN cooling idle: chamber is already below the nullifier threshold.";
            }

            float availableHydrogen = AntiEntropyHydrogenAvailable(cell);
            if (availableHydrogen < AntiEntropyHydrogenThreshold)
            {
                return "AETN cooling blocked: feed hydrogen by gas vent or uncover a hydrogen pocket.";
            }

            return "AETN cooling ready: hydrogen feed can delete heat from the chamber.";
        }

        private float PollutedOxygenAround(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        total += pollutedOxygen[x, y];
                    }
                }
            }

            return total;
        }

        private int SlimeCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && cells[x, y] == CellKind.Slime)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int AlgaeCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && cells[x, y] == CellKind.Algae)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int PollutionSourceCellsAround(Vector2Int center, int radius)
        {
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y))
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.Slime ||
                        cells[x, y] == CellKind.Compost ||
                        cells[x, y] == CellKind.Outhouse ||
                        looseResourceKind[x, y] == LooseResourceKind.PollutedDirt)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

