        private bool HasCoolSteamVentNearby(Vector2Int center, int radius)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && cells[x, y] == CellKind.CoolSteamVent)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private float RemovePollutedOxygen(Vector2Int center, float amount, int radius)
        {
            float remaining = Mathf.Max(0f, amount);
            float removedTotal = 0f;
            for (int dy = -radius; dy <= radius && remaining > 0.001f; dy++)
            {
                for (int dx = -radius; dx <= radius && remaining > 0.001f; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float removed = Mathf.Min(pollutedOxygen[x, y], remaining);
                    if (removed <= 0.001f)
                    {
                        continue;
                    }

                    pollutedOxygen[x, y] = Mathf.Max(0f, pollutedOxygen[x, y] - removed);
                    germs[x, y] = Mathf.Max(0f, germs[x, y] - removed * 0.035f);
                    remaining -= removed;
                    removedTotal += removed;
                }
            }

            return removedTotal;
        }

        private float CleanPollutedOxygenAround(Vector2Int center, float amount, int radius, float oxygenYield, float germReduction)
        {
            float remaining = Mathf.Max(0f, amount);
            float cleanedTotal = 0f;
            for (int dy = -radius; dy <= radius && remaining > 0.001f; dy++)
            {
                for (int dx = -radius; dx <= radius && remaining > 0.001f; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float cleaned = Mathf.Min(pollutedOxygen[x, y], remaining);
                    if (cleaned <= 0.001f)
                    {
                        continue;
                    }

                    pollutedOxygen[x, y] = Mathf.Max(0f, pollutedOxygen[x, y] - cleaned);
                    oxygen[x, y] = Mathf.Min(2.4f, oxygen[x, y] + cleaned * oxygenYield);
                    germs[x, y] = Mathf.Max(0f, germs[x, y] - germReduction);
                    remaining -= cleaned;
                    cleanedTotal += cleaned;
                }
            }

            return cleanedTotal;
        }

        private void RunElectrolyzer(Vector2Int center, float deltaTime)
        {
            float targetWater = ElectrolyzerWaterRate * deltaTime;
            float waterUsed = ConsumeMachineWater(center, targetWater, out float consumedWaterGerms);
            if (waterUsed <= 0.001f)
            {
                return;
            }

            float waterScale = waterUsed / Mathf.Max(0.001f, targetWater);
            float targetPower = ElectrolyzerPowerRate * deltaTime * waterScale;
            float powerUsed = Mathf.Min(power, targetPower);
            float powerEfficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float outputScale = waterScale * powerEfficiency;
            ConsumeCyclePower(powerUsed);
            AddOxygen(center, ElectrolyzerOxygenRate * deltaTime * outputScale);
            AddHydrogen(center, ElectrolyzerHydrogenRate * deltaTime * outputScale);
            float aerosolized = AddAirborneGerms(center, consumedWaterGerms * ElectrolyzerWaterGermAerosolRate * deltaTime * outputScale);
            electrolyzerGermsAerosolized += aerosolized;
            AddHeat(center, 0.42f * deltaTime * outputScale, 2);
            WearEquipment(center, 0.00042f * deltaTime * outputScale);
        }

        private void RunHydrogenFilter(Vector2Int center, float deltaTime)
        {
            if (!TryFindAdjacentMixedHydrogenPipe(center, out Vector2Int pipe) ||
                !TryFindHydrogenFilterOutput(center, out Vector2Int output))
            {
                return;
            }

            float nonHydrogen = PipeNonHydrogenTotal(pipe.x, pipe.y);
            float outputFree = Mathf.Max(0f, 2.8f - TileGasTotal(output.x, output.y));
            float target = Mathf.Min(nonHydrogen, Mathf.Min(outputFree, HydrogenFilterRate * deltaTime));
            if (target <= 0.001f)
            {
                return;
            }

            float targetPower = HydrogenFilterPowerRate * deltaTime * (target / Mathf.Max(0.001f, HydrogenFilterRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float filtered = RemoveNonHydrogenFromPipe(pipe, output, target * efficiency);
            if (filtered <= 0.001f)
            {
                return;
            }

            ConsumeCyclePower(powerUsed);
            hydrogenFilteredGas += filtered;
            AddHeat(center, 0.06f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00030f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;
            terrainDirty = true;
        }

        private bool RunGasFilter(Vector2Int center, float deltaTime)
        {
            GasFilterMode mode = gasFilterMode[center.x, center.y];
            if (!TryFindAdjacentGasPipeWithFilterGas(center, mode, out Vector2Int inputPipe) ||
                !TryFindAdjacentGasPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe))
            {
                return false;
            }

            float outputFree = Mathf.Max(0f, GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y));
            float target = Mathf.Min(GasPipeFilterAmount(inputPipe.x, inputPipe.y, mode), Mathf.Min(outputFree, GasFilterRate * deltaTime));
            if (target <= 0.001f)
            {
                return false;
            }

            float targetPower = GasFilterPowerRate * deltaTime * (target / Mathf.Max(0.001f, GasFilterRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float filtered = MoveFilteredGasPipeToPipe(inputPipe, outputPipe, mode, target * efficiency);
            if (filtered <= 0.001f)
            {
                return false;
            }

            ConsumeCyclePower(powerUsed);
            AddHeat(center, 0.045f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00030f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;
            terrainDirty = true;
            return true;
        }

        private bool RunSourGasCondenser(Vector2Int center, float deltaTime)
        {
            if (!TryFindAdjacentGasPipeWithFilterGas(center, GasFilterMode.SourGas, out Vector2Int inputPipe) ||
                !TryFindAdjacentGasPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe))
            {
                return false;
            }

            float outputFree = Mathf.Max(0f, GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y));
            float target = Mathf.Min(
                gasPipeSourGas[inputPipe.x, inputPipe.y],
                Mathf.Min(SourGasCondenserRate * deltaTime, outputFree / Mathf.Max(0.001f, SourGasCondenserNaturalGasYield)));
            target = LimitGasValveFlow(inputPipe, outputPipe, target);
            if (target <= 0.001f)
            {
                return false;
            }

            float targetPower = SourGasCondenserPowerRate * deltaTime * (target / Mathf.Max(0.001f, SourGasCondenserRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float consumed = Mathf.Min(gasPipeSourGas[inputPipe.x, inputPipe.y], target * efficiency);
            float producedNaturalGas = consumed * SourGasCondenserNaturalGasYield;
            if (consumed <= 0.001f || producedNaturalGas <= 0.001f)
            {
                return false;
            }

            float germLevel = gasPipeGerms[inputPipe.x, inputPipe.y] * 0.35f;
            float sourceTemperature = temperature[inputPipe.x, inputPipe.y];
            RemoveFilteredGasFromPipe(inputPipe.x, inputPipe.y, GasFilterMode.SourGas, consumed);
            AddGasToPipe(
                outputPipe.x,
                outputPipe.y,
                0f,
                0f,
                0f,
                0f,
                0f,
                producedNaturalGas,
                germLevel,
                Mathf.Max(-35f, sourceTemperature - 70f));
            ConsumeCyclePower(powerUsed);
            sourGasCondensed += consumed;
            sourGasCondenserNaturalGasProduced += producedNaturalGas;
            AddHeat(center, SourGasCondenserHeatPerKg * consumed, 1);
            WearEquipment(center, 0.00036f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;
            terrainDirty = true;
            return true;
        }

        private bool CanSourGasCondenserRun(Vector2Int center)
        {
            return CanPoweredMachineRun(center) &&
                TryFindAdjacentGasPipeWithFilterGas(center, GasFilterMode.SourGas, out Vector2Int inputPipe) &&
                TryFindAdjacentGasPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe) &&
                GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y) > 0.001f;
        }

        private bool RunLiquidFilter(Vector2Int center, float deltaTime)
        {
            LiquidFilterMode mode = liquidFilterMode[center.x, center.y];
            if (!TryFindAdjacentLiquidPipeWithFilterLiquid(center, mode, out Vector2Int inputPipe) ||
                !TryFindAdjacentLiquidPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe))
            {
                return false;
            }

            float outputFree = LiquidPipeFreeCapacity(outputPipe.x, outputPipe.y);
            float target = Mathf.Min(LiquidPipeFilterAmount(inputPipe.x, inputPipe.y, mode), Mathf.Min(outputFree, LiquidFilterRate * deltaTime));
            if (target <= 0.001f)
            {
                return false;
            }

            float targetPower = LiquidFilterPowerRate * deltaTime * (target / Mathf.Max(0.001f, LiquidFilterRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float filtered = MoveFilteredLiquidPipeToPipe(inputPipe, outputPipe, mode, target * efficiency);
            if (filtered <= 0.001f)
            {
                return false;
            }

            ConsumeCyclePower(powerUsed);
            liquidFilteredWater += filtered;
            AddHeat(center, 0.04f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00028f * deltaTime * efficiency);
            overlayDirty = true;
            terrainDirty = true;
            return true;
        }

        private float RemoveNonHydrogenFromPipe(Vector2Int pipe, Vector2Int output, float amount)
        {
            float nonHydrogen = PipeNonHydrogenTotal(pipe.x, pipe.y);
            if (amount <= 0.001f || nonHydrogen <= 0.001f)
            {
                return 0f;
            }

            amount = LimitGasValveFlow(pipe, amount);
            if (amount <= 0.001f)
            {
                return 0f;
            }

            float oxygenAmount = Mathf.Min(gasPipeOxygen[pipe.x, pipe.y], amount * gasPipeOxygen[pipe.x, pipe.y] / nonHydrogen);
            float carbonAmount = Mathf.Min(gasPipeCarbonDioxide[pipe.x, pipe.y], amount * gasPipeCarbonDioxide[pipe.x, pipe.y] / nonHydrogen);
            float pollutedAmount = Mathf.Min(gasPipePollutedOxygen[pipe.x, pipe.y], amount * gasPipePollutedOxygen[pipe.x, pipe.y] / nonHydrogen);
            float steamAmount = Mathf.Min(gasPipeSteam[pipe.x, pipe.y], amount * gasPipeSteam[pipe.x, pipe.y] / nonHydrogen);
            float chlorineAmount = Mathf.Min(gasPipeChlorine[pipe.x, pipe.y], amount * gasPipeChlorine[pipe.x, pipe.y] / nonHydrogen);
            float naturalGasAmount = Mathf.Min(gasPipeNaturalGas[pipe.x, pipe.y], amount * gasPipeNaturalGas[pipe.x, pipe.y] / nonHydrogen);
            float sourGasAmount = Mathf.Min(gasPipeSourGas[pipe.x, pipe.y], amount * gasPipeSourGas[pipe.x, pipe.y] / nonHydrogen);
            AddGasToTileWithSteam(output.x, output.y, oxygenAmount, carbonAmount, pollutedAmount, 0f, steamAmount, chlorineAmount, naturalGasAmount, gasPipeGerms[pipe.x, pipe.y], temperature[pipe.x, pipe.y], sourGasAmount);
            gasPipeOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeOxygen[pipe.x, pipe.y] - oxygenAmount);
            gasPipeCarbonDioxide[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeCarbonDioxide[pipe.x, pipe.y] - carbonAmount);
            gasPipePollutedOxygen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipePollutedOxygen[pipe.x, pipe.y] - pollutedAmount);
            gasPipeSteam[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSteam[pipe.x, pipe.y] - steamAmount);
            gasPipeChlorine[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeChlorine[pipe.x, pipe.y] - chlorineAmount);
            gasPipeNaturalGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeNaturalGas[pipe.x, pipe.y] - naturalGasAmount);
            gasPipeSourGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeSourGas[pipe.x, pipe.y] - sourGasAmount);
            ClearGasPipeGermsIfEmpty(pipe.x, pipe.y);

            return oxygenAmount + carbonAmount + pollutedAmount + steamAmount + chlorineAmount + naturalGasAmount + sourGasAmount;
        }

        private float MoveFilteredGasPipeToPipe(Vector2Int inputPipe, Vector2Int outputPipe, GasFilterMode mode, float amount)
        {
            if (!IsInside(inputPipe.x, inputPipe.y) ||
                !IsInside(outputPipe.x, outputPipe.y) ||
                !gasPipe[inputPipe.x, inputPipe.y] ||
                !gasPipe[outputPipe.x, outputPipe.y])
            {
                return 0f;
            }

            float moved = Mathf.Min(
                amount,
                Mathf.Min(GasPipeFilterAmount(inputPipe.x, inputPipe.y, mode), GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y)));
            moved = LimitGasValveFlow(inputPipe, outputPipe, moved);
            if (moved <= 0.001f)
            {
                return 0f;
            }

            float germLevel = gasPipeGerms[inputPipe.x, inputPipe.y];
            float sourceTemperature = temperature[inputPipe.x, inputPipe.y];
            RemoveFilteredGasFromPipe(inputPipe.x, inputPipe.y, mode, moved);
            AddFilteredGasToPipe(outputPipe.x, outputPipe.y, mode, moved, germLevel, sourceTemperature);
            return moved;
        }

        private float GasPipeFilterAmount(int x, int y, GasFilterMode mode)
        {
            switch (mode)
            {
                case GasFilterMode.Oxygen:
                    return gasPipeOxygen[x, y];
                case GasFilterMode.PollutedOxygen:
                    return gasPipePollutedOxygen[x, y];
                case GasFilterMode.Hydrogen:
                    return gasPipeHydrogen[x, y];
                case GasFilterMode.Steam:
                    return gasPipeSteam[x, y];
                case GasFilterMode.Chlorine:
                    return gasPipeChlorine[x, y];
                case GasFilterMode.NaturalGas:
                    return gasPipeNaturalGas[x, y];
                case GasFilterMode.SourGas:
                    return gasPipeSourGas[x, y];
                default:
                    return gasPipeCarbonDioxide[x, y];
            }
        }

        private void RemoveFilteredGasFromPipe(int x, int y, GasFilterMode mode, float amount)
        {
            switch (mode)
            {
                case GasFilterMode.Oxygen:
                    gasPipeOxygen[x, y] = Mathf.Max(0f, gasPipeOxygen[x, y] - amount);
                    break;
                case GasFilterMode.PollutedOxygen:
                    gasPipePollutedOxygen[x, y] = Mathf.Max(0f, gasPipePollutedOxygen[x, y] - amount);
                    break;
                case GasFilterMode.Hydrogen:
                    gasPipeHydrogen[x, y] = Mathf.Max(0f, gasPipeHydrogen[x, y] - amount);
                    break;
                case GasFilterMode.Steam:
                    gasPipeSteam[x, y] = Mathf.Max(0f, gasPipeSteam[x, y] - amount);
                    break;
                case GasFilterMode.Chlorine:
                    gasPipeChlorine[x, y] = Mathf.Max(0f, gasPipeChlorine[x, y] - amount);
                    break;
                case GasFilterMode.NaturalGas:
                    gasPipeNaturalGas[x, y] = Mathf.Max(0f, gasPipeNaturalGas[x, y] - amount);
                    break;
                case GasFilterMode.SourGas:
                    gasPipeSourGas[x, y] = Mathf.Max(0f, gasPipeSourGas[x, y] - amount);
                    break;
                default:
                    gasPipeCarbonDioxide[x, y] = Mathf.Max(0f, gasPipeCarbonDioxide[x, y] - amount);
                    break;
            }

            ClearGasPipeGermsIfEmpty(x, y);
        }

        private void AddFilteredGasToPipe(int x, int y, GasFilterMode mode, float amount, float germLevel, float sourceTemperature)
        {
            switch (mode)
            {
                case GasFilterMode.Oxygen:
                    AddGasToPipe(x, y, amount, 0f, 0f, 0f, 0f, 0f, germLevel, sourceTemperature);
                    break;
                case GasFilterMode.PollutedOxygen:
                    AddGasToPipe(x, y, 0f, 0f, amount, 0f, 0f, 0f, germLevel, sourceTemperature);
                    break;
                case GasFilterMode.Hydrogen:
                    AddGasToPipe(x, y, 0f, 0f, 0f, amount, 0f, 0f, germLevel, sourceTemperature);
                    break;
                case GasFilterMode.Steam:
                    AddGasToPipeWithSteam(x, y, 0f, 0f, 0f, 0f, amount, 0f, 0f, germLevel, sourceTemperature);
                    break;
                case GasFilterMode.Chlorine:
                    AddGasToPipe(x, y, 0f, 0f, 0f, 0f, amount, 0f, germLevel, sourceTemperature);
                    break;
                case GasFilterMode.NaturalGas:
                    AddGasToPipe(x, y, 0f, 0f, 0f, 0f, 0f, amount, germLevel, sourceTemperature);
                    break;
                case GasFilterMode.SourGas:
                    AddGasToPipeWithSteam(x, y, 0f, 0f, 0f, 0f, 0f, 0f, 0f, germLevel, sourceTemperature, amount);
                    break;
                default:
                    AddGasToPipe(x, y, 0f, amount, 0f, 0f, 0f, 0f, germLevel, sourceTemperature);
                    break;
            }
        }

        private float MovePollutedWaterPipeToPipe(Vector2Int inputPipe, Vector2Int outputPipe, float amount)
        {
            return MoveFilteredLiquidPipeToPipe(inputPipe, outputPipe, LiquidFilterMode.PollutedWater, amount);
        }

        private float MoveFilteredLiquidPipeToPipe(Vector2Int inputPipe, Vector2Int outputPipe, LiquidFilterMode mode, float amount)
        {
            if (!IsInside(inputPipe.x, inputPipe.y) ||
                !IsInside(outputPipe.x, outputPipe.y) ||
                !liquidPipe[inputPipe.x, inputPipe.y] ||
                !liquidPipe[outputPipe.x, outputPipe.y])
            {
                return 0f;
            }

            float moved = Mathf.Min(
                amount,
                Mathf.Min(LiquidPipeFilterAmount(inputPipe.x, inputPipe.y, mode), LiquidPipeFreeCapacity(outputPipe.x, outputPipe.y)));
            moved = LimitLiquidValveFlow(inputPipe, outputPipe, moved);
            if (moved <= 0.001f)
            {
                return 0f;
            }

            float inputGerms = mode == LiquidFilterMode.CleanWater
                ? pipeWaterGerms[inputPipe.x, inputPipe.y]
                : mode == LiquidFilterMode.PollutedWater
                    ? pipePollutedWaterGerms[inputPipe.x, inputPipe.y]
                    : 0f;
            float added = AddFilteredLiquidToPipe(outputPipe, mode, moved, temperature[inputPipe.x, inputPipe.y], inputGerms);
            if (added <= 0.001f)
            {
                return 0f;
            }

            RemoveFilteredLiquidFromPipe(inputPipe.x, inputPipe.y, mode, added);
            TrackAutomatedConduitFlow(inputPipe.x, inputPipe.y, outputPipe.x, outputPipe.y, added, false);
            return added;
        }

        private float LiquidPipeFilterAmount(int x, int y, LiquidFilterMode mode)
        {
            switch (mode)
            {
                case LiquidFilterMode.CleanWater:
                    return pipeWater[x, y];
                case LiquidFilterMode.Petroleum:
                    return pipePetroleum[x, y];
                default:
                    return pipePollutedWater[x, y];
            }
        }

        private void RemoveFilteredLiquidFromPipe(int x, int y, LiquidFilterMode mode, float amount)
        {
            if (mode == LiquidFilterMode.CleanWater)
            {
                pipeWater[x, y] = Mathf.Max(0f, pipeWater[x, y] - amount);
                if (pipeWater[x, y] <= 0.001f)
                {
                    pipeWaterGerms[x, y] = 0f;
                }
            }
            else if (mode == LiquidFilterMode.Petroleum)
            {
                pipePetroleum[x, y] = Mathf.Max(0f, pipePetroleum[x, y] - amount);
            }
            else
            {
                pipePollutedWater[x, y] = Mathf.Max(0f, pipePollutedWater[x, y] - amount);
                if (pipePollutedWater[x, y] <= 0.001f)
                {
                    pipePollutedWaterGerms[x, y] = 0f;
                }
            }
        }

        private float AddFilteredLiquidToPipe(Vector2Int pipe, LiquidFilterMode mode, float amount, float sourceTemperature, float germLevel)
        {
            switch (mode)
            {
                case LiquidFilterMode.CleanWater:
                    return AddLiquidPipeWater(pipe, amount, sourceTemperature, germLevel);
                case LiquidFilterMode.Petroleum:
                    return AddLiquidPipePetroleum(pipe, amount, sourceTemperature);
                default:
                    return AddLiquidPipePollutedWater(pipe, amount, sourceTemperature, germLevel);
            }
        }

        private bool CanAlgaeTerrariumRun(Vector2Int center)
        {
            return CanUseEquipment(center) &&
                algae > 0.001f &&
                HasMachineWaterFeed(center) &&
                CarbonDioxideAround(center, AlgaeTerrariumRadius) > 0.02f;
        }

        private bool RunAlgaeTerrarium(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !CanUseEquipment(center))
            {
                return false;
            }

            float localCarbon = CarbonDioxideAround(center, AlgaeTerrariumRadius);
            if (localCarbon <= 0.02f || algae <= 0.001f)
            {
                return false;
            }

            float fullCarbonTarget = Mathf.Min(localCarbon, AlgaeTerrariumCarbonRate * deltaTime);
            float rateScale = fullCarbonTarget / Mathf.Max(0.001f, AlgaeTerrariumCarbonRate * deltaTime);
            float algaeNeeded = AlgaeTerrariumAlgaeRate * deltaTime * rateScale;
            float waterNeeded = AlgaeTerrariumWaterRate * deltaTime * rateScale;
            if (algaeNeeded <= 0.001f || waterNeeded <= 0.001f)
            {
                return false;
            }

            float algaeScale = Mathf.Clamp01(algae / algaeNeeded);
            if (algaeScale <= 0.001f)
            {
                return false;
            }

            float waterUsed = ConsumeMachineWater(center, waterNeeded * algaeScale, out float terrariumWaterGerms);
            if (waterUsed <= 0.001f)
            {
                return false;
            }

            float resourceScale = Mathf.Min(algaeScale, waterUsed / Mathf.Max(0.001f, waterNeeded));
            float cleaned = RemoveCarbonDioxide(center, fullCarbonTarget * resourceScale, AlgaeTerrariumRadius);
            if (cleaned <= 0.001f)
            {
                return false;
            }

            float actualScale = cleaned / Mathf.Max(0.001f, fullCarbonTarget);
            float algaeUsed = Mathf.Min(algae, algaeNeeded * actualScale);
            float waterConverted = Mathf.Min(waterUsed, waterNeeded * actualScale);
            algae -= algaeUsed;
            StorePollutedWater(center, waterConverted * (AlgaeTerrariumPollutedWaterRate / AlgaeTerrariumWaterRate), Mathf.Clamp01(0.28f + terrariumWaterGerms * 0.45f));
            AddOxygen(center, AlgaeTerrariumOxygenRate * deltaTime * actualScale);
            AddHeat(center, 0.025f * deltaTime * actualScale, 1);
            WearEquipment(center, 0.00016f * deltaTime * actualScale);
            return true;
        }

        private void RunCarbonSkimmer(Vector2Int center, float deltaTime)
        {
            float localCarbon = CarbonDioxideAround(center, 3);
            if (localCarbon <= 0.05f)
            {
                return;
            }

            float targetWater = CarbonSkimmerWaterRate * deltaTime;
            float waterUsed = ConsumeMachineWater(center, targetWater, out float skimmerWaterGerms);
            if (waterUsed <= 0.001f)
            {
                return;
            }

            float targetPower = CarbonSkimmerPowerRate * deltaTime * (waterUsed / Mathf.Max(0.001f, targetWater));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float cleaned = RemoveCarbonDioxide(center, CarbonSkimmerCarbonRate * deltaTime * efficiency, 3);
            ConsumeCyclePower(powerUsed);
            StorePollutedWater(center, waterUsed * Mathf.Clamp01(cleaned / Mathf.Max(0.001f, CarbonSkimmerCarbonRate * deltaTime)), Mathf.Clamp01(0.22f + skimmerWaterGerms * 0.45f));
            AddHeat(center, 0.12f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00038f * deltaTime * efficiency);
        }

        private void RunWaterSieve(Vector2Int center, float deltaTime)
        {
            if (dirt <= 0.001f)
            {
                return;
            }

            float targetPollutedWater = WaterSievePollutedWaterRate * deltaTime;
            float pollutedUsed = Mathf.Min(PollutedWaterAvailableForSieve(center), targetPollutedWater);
            if (pollutedUsed <= 0.001f)
            {
                return;
            }

            float dirtNeeded = WaterSieveDirtRate * deltaTime * (pollutedUsed / Mathf.Max(0.001f, targetPollutedWater));
            float dirtUsed = Mathf.Min(dirt, dirtNeeded);
            float filterEfficiency = dirtUsed / Mathf.Max(0.001f, dirtNeeded);
            float targetPower = WaterSievePowerRate * deltaTime * filterEfficiency;
            float powerUsed = Mathf.Min(power, targetPower);
            float powerEfficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float cleaned = ConsumePollutedWaterForSieve(center, pollutedUsed * filterEfficiency * powerEfficiency, out float consumedPollutedWaterGerms);
            if (cleaned <= 0.001f)
            {
                return;
            }

            float outputGermLevel = WaterSieveOutputGermLevel(center, consumedPollutedWaterGerms);
            dirt = Mathf.Max(0f, dirt - dirtUsed * powerEfficiency);
            ConsumeCyclePower(powerUsed);
            StoreCleanWater(center, cleaned * 0.92f, outputGermLevel);
            recycledWater += cleaned * 0.92f;
            VentPollutedOxygen(center, 0.004f * deltaTime, 0.015f * deltaTime);
            AddHeat(center, 0.10f * deltaTime * powerEfficiency, 1);
            WearEquipment(center, 0.00036f * deltaTime * powerEfficiency);
        }

        private bool CanWaterSieveRun(Vector2Int center)
        {
            return techAirSystems &&
                CanPoweredMachineRun(center) &&
                dirt > 0.001f &&
                PollutedWaterAvailableForSieve(center) > 0.001f;
        }

        private void RunDesalinator(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || DryResourceFreeSpace() <= 0.001f)
            {
                return;
            }

            float targetSaltWater = Mathf.Min(SaltWaterAvailableForDesalinator(center), DesalinatorSaltWaterRate * deltaTime);
            targetSaltWater = Mathf.Min(targetSaltWater, DryResourceFreeSpace() / Mathf.Max(0.001f, DesalinatorSaltYield));
            if (targetSaltWater <= 0.001f)
            {
                return;
            }

            float targetPower = DesalinatorPowerRate * deltaTime * (targetSaltWater / Mathf.Max(0.001f, DesalinatorSaltWaterRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float consumed = ConsumeSaltWaterForDesalinator(center, targetSaltWater * efficiency);
            if (consumed <= 0.001f)
            {
                return;
            }

            float actualEfficiency = consumed / Mathf.Max(0.001f, targetSaltWater);
            float cleanOutput = consumed * DesalinatorCleanWaterYield;
            float saltOutput = consumed * DesalinatorSaltYield;
            float storedSalt = StoreDryResource(ref salt, saltOutput);
            StoreCleanWater(center, cleanOutput, 0f);
            desalinatedWater += cleanOutput;
            desalinationSaltProduced += storedSalt;
            ConsumeCyclePower(powerUsed);
            AddHeat(center, DesalinatorHeatRate * deltaTime * actualEfficiency, 1);
            WearEquipment(center, 0.00034f * deltaTime * actualEfficiency);
        }

        private bool CanDesalinatorRun(Vector2Int center)
        {
            return techAirSystems &&
                CanPoweredMachineRun(center) &&
                SaltWaterAvailableForDesalinator(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private void RunFertilizerSynthesizer(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f ||
                !techFoodPreparation ||
                dirt <= 0.001f ||
                DryResourceFreeSpace() <= 0.001f)
            {
                return;
            }

            float targetPollutedWater = Mathf.Min(PollutedWaterAvailableForSieve(center), FertilizerSynthesizerPollutedWaterRate * deltaTime);
            targetPollutedWater = Mathf.Min(targetPollutedWater, DryResourceFreeSpace() / Mathf.Max(0.001f, FertilizerSynthesizerFertilizerYield));
            if (targetPollutedWater <= 0.001f)
            {
                return;
            }

            float dirtNeeded = FertilizerSynthesizerDirtRate * deltaTime * (targetPollutedWater / Mathf.Max(0.001f, FertilizerSynthesizerPollutedWaterRate * deltaTime));
            float dirtUsed = Mathf.Min(dirt, dirtNeeded);
            float dirtEfficiency = dirtUsed / Mathf.Max(0.001f, dirtNeeded);
            float targetPower = FertilizerSynthesizerPowerRate * deltaTime * dirtEfficiency;
            float powerUsed = Mathf.Min(power, targetPower);
            float powerEfficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float consumedPollutedWater = ConsumePollutedWaterForSieve(center, targetPollutedWater * dirtEfficiency * powerEfficiency, out _);
            if (consumedPollutedWater <= 0.001f)
            {
                return;
            }

            float actualEfficiency = consumedPollutedWater / Mathf.Max(0.001f, targetPollutedWater);
            dirt = Mathf.Max(0f, dirt - dirtUsed * powerEfficiency);
            float fertilizerOutput = consumedPollutedWater * FertilizerSynthesizerFertilizerYield;
            float storedFertilizer = StoreDryResource(ref fertilizer, fertilizerOutput);
            float naturalGasOutput = consumedPollutedWater * FertilizerSynthesizerNaturalGasYield;

            fertilizerProduced += storedFertilizer;
            fertilizerPollutedWaterUsed += consumedPollutedWater;
            fertilizerNaturalGasVented += naturalGasOutput;
            ConsumeCyclePower(powerUsed);
            AddGasToTile(center.x, center.y, 0f, 0f, 0f, 0f, 0f, naturalGasOutput, 0f);
            AddHeat(center, FertilizerSynthesizerHeatRate * deltaTime * actualEfficiency, 1);
            WearEquipment(center, 0.00036f * deltaTime * actualEfficiency);
            gasDirty = true;
            overlayDirty = true;
        }

        private bool CanFertilizerSynthesizerRun(Vector2Int center)
        {
            return techFoodPreparation &&
                CanPoweredMachineRun(center) &&
                dirt > 0.001f &&
                PollutedWaterAvailableForSieve(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private void RunMetalRefinery(Vector2Int center, float deltaTime)
        {
            if (TryRunSuperCoolantRefinery(center, deltaTime))
            {
                return;
            }

            if (TryRunThermiumRefinery(center, deltaTime))
            {
                return;
            }

            if (TryRunSteelRefinery(center, deltaTime))
            {
                return;
            }

            if (deltaTime <= 0f ||
                !techPowerRegulation ||
                metal <= 0.001f ||
                DryResourceFreeSpace() <= 0.001f)
            {
                return;
            }

            float fullOreTarget = MetalRefineryOreRate * deltaTime;
            float targetOre = Mathf.Min(metal, fullOreTarget);
            targetOre = Mathf.Min(targetOre, DryResourceFreeSpace() / Mathf.Max(0.001f, MetalRefineryRefinedMetalYield));
            if (targetOre <= 0.001f)
            {
                return;
            }

            float runScale = targetOre / Mathf.Max(0.001f, fullOreTarget);
            float targetCoolant = MetalRefineryCoolantRate * deltaTime * runScale;
            if (targetCoolant <= 0.001f)
            {
                return;
            }

            float coolantEfficiency = Mathf.Clamp01(CleanWaterAvailableForMachine(center) / Mathf.Max(0.001f, targetCoolant));
            float targetPower = MetalRefineryPowerRate * deltaTime * runScale * coolantEfficiency;
            float powerUsed = Mathf.Min(power, targetPower);
            float powerEfficiency = targetPower <= 0.001f ? 0f : powerUsed / targetPower;
            float requestedOre = targetOre * coolantEfficiency * powerEfficiency;
            float requestedCoolant = targetCoolant * coolantEfficiency * powerEfficiency;
            if (requestedOre <= 0.001f || requestedCoolant <= 0.001f)
            {
                return;
            }

            float coolantUsed = ConsumeMachineWater(center, requestedCoolant, out float coolantGerms);
            if (coolantUsed <= 0.001f)
            {
                return;
            }

            float actualScale = Mathf.Clamp01(coolantUsed / Mathf.Max(0.001f, requestedCoolant));
            float oreUsed = Mathf.Min(metal, requestedOre * actualScale);
            if (oreUsed <= 0.001f)
            {
                return;
            }

            metal = Mathf.Max(0f, metal - oreUsed);
            float stored = StoreDryResource(ref refinedMetal, oreUsed * MetalRefineryRefinedMetalYield);
            float pollutedOutput = coolantUsed * MetalRefineryPollutedWaterYield;
            float powerConsumed = powerUsed * actualScale;

            refinedMetalProduced += stored;
            metalRefineryOreUsed += oreUsed;
            metalRefineryRefinedMetalProduced += stored;
            metalRefineryCoolantUsed += coolantUsed;
            metalRefineryPollutedWaterProduced += pollutedOutput;
            ConsumeCyclePower(powerConsumed);
            StorePollutedWater(center, pollutedOutput, Mathf.Clamp01(0.18f + coolantGerms * 0.35f));
            AddHeat(center, MetalRefineryHeatRate * deltaTime * Mathf.Clamp01(oreUsed / Mathf.Max(0.001f, fullOreTarget)), 2);
            WearEquipment(center, 0.00056f * deltaTime * Mathf.Clamp01(oreUsed / Mathf.Max(0.001f, fullOreTarget)));
            overlayDirty = true;
        }

        private bool TryRunSteelRefinery(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !CanSteelRefineryRun(center))
            {
                return false;
            }

            float coalPerRefinedMetal = SteelCoalRate / Mathf.Max(0.001f, SteelRefinedMetalRate);
            float availableRefinedMetal = Mathf.Max(0f, refinedMetal - SteelRefinedMetalReserve);
            float fullRefinedTarget = SteelRefinedMetalRate * deltaTime;
            float targetRefinedMetal = Mathf.Min(availableRefinedMetal, fullRefinedTarget);
            targetRefinedMetal = Mathf.Min(targetRefinedMetal, coal / Mathf.Max(0.001f, coalPerRefinedMetal));
            targetRefinedMetal = Mathf.Min(targetRefinedMetal, (SteelStockpileTarget - steel) / Mathf.Max(0.001f, SteelYield));
            targetRefinedMetal = Mathf.Min(targetRefinedMetal, DryResourceFreeSpace() / Mathf.Max(0.001f, SteelYield));
            if (targetRefinedMetal <= 0.001f)
            {
                return false;
            }

            float runScale = targetRefinedMetal / Mathf.Max(0.001f, fullRefinedTarget);
            float targetCoolant = SteelCoolantRate * deltaTime * runScale;
            float targetPower = SteelPowerRate * deltaTime * runScale;
            if (targetCoolant <= 0.001f || targetPower <= 0.001f)
            {
                return false;
            }

            float coolantEfficiency = Mathf.Clamp01(CleanWaterAvailableForMachine(center) / Mathf.Max(0.001f, targetCoolant));
            float powerEfficiency = Mathf.Clamp01(power / Mathf.Max(0.001f, targetPower));
            float efficiency = Mathf.Min(coolantEfficiency, powerEfficiency);
            if (efficiency <= 0.001f)
            {
                return false;
            }

            float requestedCoolant = targetCoolant * efficiency;
            float coolantUsed = ConsumeMachineWater(center, requestedCoolant, out float coolantGerms);
            if (coolantUsed <= 0.001f)
            {
                return false;
            }

            float actualScale = Mathf.Clamp01(coolantUsed / Mathf.Max(0.001f, requestedCoolant));
            float refinedUsed = targetRefinedMetal * efficiency * actualScale;
            float coalUsed = refinedUsed * coalPerRefinedMetal;
            if (refinedUsed <= 0.001f || coalUsed <= 0.001f)
            {
                return false;
            }

            refinedMetal = Mathf.Max(0f, refinedMetal - refinedUsed);
            coal = Mathf.Max(0f, coal - coalUsed);
            float stored = StoreDryResource(ref steel, refinedUsed * SteelYield);
            float pollutedOutput = coolantUsed * MetalRefineryPollutedWaterYield;
            float powerConsumed = targetPower * efficiency * actualScale;

            steelProduced += stored;
            metalRefineryCoolantUsed += coolantUsed;
            metalRefineryPollutedWaterProduced += pollutedOutput;
            ConsumeCyclePower(powerConsumed);
            StorePollutedWater(center, pollutedOutput, Mathf.Clamp01(0.18f + coolantGerms * 0.35f));
            AddHeat(center, SteelHeatRate * deltaTime * Mathf.Clamp01(refinedUsed / Mathf.Max(0.001f, fullRefinedTarget)), 2);
            WearEquipment(center, 0.00068f * deltaTime * Mathf.Clamp01(refinedUsed / Mathf.Max(0.001f, fullRefinedTarget)));
            overlayDirty = true;
            return true;
        }

        private bool TryRunSuperCoolantRefinery(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !CanSuperCoolantRefineryRun(center))
            {
                return false;
            }

            float fullerenePerThermium = SuperCoolantFullereneRate / Mathf.Max(0.001f, SuperCoolantThermiumRate);
            float waterPerThermium = SuperCoolantWaterRate / Mathf.Max(0.001f, SuperCoolantThermiumRate);
            float petroleumPerThermium = SuperCoolantPetroleumRate / Mathf.Max(0.001f, SuperCoolantThermiumRate);
            float radboltPerThermium = SuperCoolantRadboltRate / Mathf.Max(0.001f, SuperCoolantThermiumRate);
            float availableThermium = Mathf.Max(0f, thermium - SuperCoolantThermiumReserve);
            float fullThermiumTarget = SuperCoolantThermiumRate * deltaTime;
            float targetThermium = Mathf.Min(availableThermium, fullThermiumTarget);
            targetThermium = Mathf.Min(targetThermium, fullerene / Mathf.Max(0.001f, fullerenePerThermium));
            targetThermium = Mathf.Min(targetThermium, petroleum / Mathf.Max(0.001f, petroleumPerThermium));
            targetThermium = Mathf.Min(targetThermium, radboltCharge / Mathf.Max(0.001f, radboltPerThermium));
            targetThermium = Mathf.Min(targetThermium, CleanWaterAvailableForMachine(center) / Mathf.Max(0.001f, waterPerThermium));
            targetThermium = Mathf.Min(targetThermium, (SuperCoolantStockpileTarget - superCoolant) / Mathf.Max(0.001f, SuperCoolantYield));
            targetThermium = Mathf.Min(targetThermium, DryResourceFreeSpace() / Mathf.Max(0.001f, SuperCoolantYield * (1f + RadboltMaterialYieldBonus)));
            if (targetThermium <= 0.001f)
            {
                return false;
            }

            float runScale = targetThermium / Mathf.Max(0.001f, fullThermiumTarget);
            float targetPower = SuperCoolantPowerRate * deltaTime * runScale;
            float powerEfficiency = Mathf.Clamp01(power / Mathf.Max(0.001f, targetPower));
            if (powerEfficiency <= 0.001f)
            {
                return false;
            }

            float requestedWater = targetThermium * waterPerThermium * powerEfficiency;
            float waterUsed = ConsumeMachineWater(center, requestedWater, out float waterGerms);
            if (waterUsed <= 0.001f)
            {
                return false;
            }

            float actualScale = Mathf.Clamp01(waterUsed / Mathf.Max(0.001f, requestedWater));
            float thermiumUsed = targetThermium * powerEfficiency * actualScale;
            float fullereneUsed = thermiumUsed * fullerenePerThermium;
            float petroleumUsed = thermiumUsed * petroleumPerThermium;
            float radboltUsed = thermiumUsed * radboltPerThermium;
            if (thermiumUsed <= 0.001f || fullereneUsed <= 0.001f || petroleumUsed <= 0.001f || radboltUsed <= 0.001f)
            {
                return false;
            }

            thermium = Mathf.Max(0f, thermium - thermiumUsed);
            fullerene = Mathf.Max(0f, fullerene - fullereneUsed);
            petroleum = Mathf.Max(0f, petroleum - petroleumUsed);
            radboltCharge = Mathf.Max(0f, radboltCharge - radboltUsed);
            radboltsSpentOnMaterials += radboltUsed;
            float stored = StoreDryResource(ref superCoolant, thermiumUsed * SuperCoolantYield * (1f + RadboltMaterialYieldBonus));
            float pollutedOutput = waterUsed * MetalRefineryPollutedWaterYield;
            float powerConsumed = targetPower * powerEfficiency * actualScale;

            superCoolantProduced += stored;
            metalRefineryCoolantUsed += waterUsed;
            metalRefineryPollutedWaterProduced += pollutedOutput;
            ConsumeCyclePower(powerConsumed);
            StorePollutedWater(center, pollutedOutput, Mathf.Clamp01(0.12f + waterGerms * 0.28f));
            AddHeat(center, SuperCoolantHeatRate * deltaTime * Mathf.Clamp01(thermiumUsed / Mathf.Max(0.001f, fullThermiumTarget)), 2);
            WearEquipment(center, 0.00048f * deltaTime * Mathf.Clamp01(thermiumUsed / Mathf.Max(0.001f, fullThermiumTarget)));
            overlayDirty = true;
            return true;
        }

        private bool TryRunThermiumRefinery(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !CanThermiumRefineryRun(center))
            {
                return false;
            }

            float niobiumPerSteel = ThermiumNiobiumRate / Mathf.Max(0.001f, ThermiumSteelRate);
            float radboltPerSteel = ThermiumRadboltRate / Mathf.Max(0.001f, ThermiumSteelRate);
            float availableSteel = Mathf.Max(0f, steel - ThermiumSteelReserve);
            float fullSteelTarget = ThermiumSteelRate * deltaTime;
            float targetSteel = Mathf.Min(availableSteel, fullSteelTarget);
            targetSteel = Mathf.Min(targetSteel, niobium / Mathf.Max(0.001f, niobiumPerSteel));
            targetSteel = Mathf.Min(targetSteel, radboltCharge / Mathf.Max(0.001f, radboltPerSteel));
            targetSteel = Mathf.Min(targetSteel, (ThermiumStockpileTarget - thermium) / Mathf.Max(0.001f, ThermiumYield * (1f + RadboltMaterialYieldBonus)));
            targetSteel = Mathf.Min(targetSteel, DryResourceFreeSpace() / Mathf.Max(0.001f, ThermiumYield * (1f + RadboltMaterialYieldBonus)));
            if (targetSteel <= 0.001f)
            {
                return false;
            }

            float runScale = targetSteel / Mathf.Max(0.001f, fullSteelTarget);
            float targetCoolant = ThermiumCoolantRate * deltaTime * runScale;
            float targetPower = ThermiumPowerRate * deltaTime * runScale;
            if (targetCoolant <= 0.001f || targetPower <= 0.001f)
            {
                return false;
            }

            float coolantEfficiency = Mathf.Clamp01(CleanWaterAvailableForMachine(center) / Mathf.Max(0.001f, targetCoolant));
            float powerEfficiency = Mathf.Clamp01(power / Mathf.Max(0.001f, targetPower));
            float efficiency = Mathf.Min(coolantEfficiency, powerEfficiency);
            if (efficiency <= 0.001f)
            {
                return false;
            }

            float requestedCoolant = targetCoolant * efficiency;
            float coolantUsed = ConsumeMachineWater(center, requestedCoolant, out float coolantGerms);
            if (coolantUsed <= 0.001f)
            {
                return false;
            }

            float actualScale = Mathf.Clamp01(coolantUsed / Mathf.Max(0.001f, requestedCoolant));
            float steelUsed = targetSteel * efficiency * actualScale;
            float niobiumUsed = steelUsed * niobiumPerSteel;
            float radboltUsed = steelUsed * radboltPerSteel;
            if (steelUsed <= 0.001f || niobiumUsed <= 0.001f || radboltUsed <= 0.001f)
            {
                return false;
            }

            steel = Mathf.Max(0f, steel - steelUsed);
            niobium = Mathf.Max(0f, niobium - niobiumUsed);
            radboltCharge = Mathf.Max(0f, radboltCharge - radboltUsed);
            radboltsSpentOnMaterials += radboltUsed;
            float stored = StoreDryResource(ref thermium, steelUsed * ThermiumYield * (1f + RadboltMaterialYieldBonus));
            float pollutedOutput = coolantUsed * MetalRefineryPollutedWaterYield;
            float powerConsumed = targetPower * efficiency * actualScale;

            thermiumProduced += stored;
            metalRefineryCoolantUsed += coolantUsed;
            metalRefineryPollutedWaterProduced += pollutedOutput;
            ConsumeCyclePower(powerConsumed);
            StorePollutedWater(center, pollutedOutput, Mathf.Clamp01(0.18f + coolantGerms * 0.35f));
            AddHeat(center, ThermiumHeatRate * deltaTime * Mathf.Clamp01(steelUsed / Mathf.Max(0.001f, fullSteelTarget)), 2);
            WearEquipment(center, 0.00072f * deltaTime * Mathf.Clamp01(steelUsed / Mathf.Max(0.001f, fullSteelTarget)));
            int coated = RetrofitThermiumMachinery();
            if (coated > 0)
            {
                Log("Thermium coating upgraded " + coated + " hot machine(s).");
            }

            overlayDirty = true;
            return true;
        }

        private bool CanMetalRefineryRun(Vector2Int center)
        {
            return CanStandardMetalRefineryRun(center) || CanSteelRefineryRun(center) || CanThermiumRefineryRun(center) || CanSuperCoolantRefineryRun(center);
        }

        private bool CanStandardMetalRefineryRun(Vector2Int center)
        {
            return techPowerRegulation &&
                CanPoweredMachineRun(center) &&
                metal > 0.001f &&
                CleanWaterAvailableForMachine(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private bool CanSteelRefineryRun(Vector2Int center)
        {
            return techPowerRegulation &&
                milestoneRadiationResearch &&
                CanPoweredMachineRun(center) &&
                refinedMetal > SteelRefinedMetalReserve + 0.001f &&
                coal > 0.001f &&
                steel < SteelStockpileTarget - 0.001f &&
                CleanWaterAvailableForMachine(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private bool CanThermiumRefineryRun(Vector2Int center)
        {
            return techPowerRegulation &&
                milestoneDeepSpaceSurvey &&
                milestoneRadboltHarnessing &&
                CanPoweredMachineRun(center) &&
                steel > ThermiumSteelReserve + 0.001f &&
                niobium > 0.001f &&
                radboltCharge > 0.001f &&
                thermium < ThermiumStockpileTarget - 0.001f &&
                CleanWaterAvailableForMachine(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private bool CanSuperCoolantRefineryRun(Vector2Int center)
        {
            return techPowerRegulation &&
                milestoneThermiumMachinery &&
                milestoneRadboltHarnessing &&
                CanPoweredMachineRun(center) &&
                thermium > SuperCoolantThermiumReserve + 0.001f &&
                fullerene > 0.001f &&
                petroleum > 0.001f &&
                radboltCharge > 0.001f &&
                superCoolant < SuperCoolantStockpileTarget - 0.001f &&
                CleanWaterAvailableForMachine(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private void RunOilRefinery(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || crudeOil <= 0.001f)
            {
                return;
            }

            float targetCrude = Mathf.Min(crudeOil, OilRefineryCrudeRate * deltaTime);
            float targetPower = OilRefineryPowerRate * deltaTime * (targetCrude / Mathf.Max(0.001f, OilRefineryCrudeRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float processed = targetCrude * efficiency;
            if (processed <= 0.001f)
            {
                return;
            }

            crudeOil = Mathf.Max(0f, crudeOil - processed);
            float petroleumOutput = processed * OilRefineryPetroleumYield;
            StorePetroleumInStorage(petroleumOutput);
            petroleumRefined += petroleumOutput;
            float fissureProcessed = Mathf.Min(processed, Mathf.Max(0f, leakyOilFissureCrudeGenerated - leakyOilFissureCrudeRefined));
            leakyOilFissureCrudeRefined += fissureProcessed;
            ConsumeCyclePower(powerUsed);
            AddGasToTile(center.x, center.y, 0f, 0f, 0f, 0f, 0f, processed * OilRefineryNaturalGasYield, 0f);
            AddHeat(center, OilRefineryHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00042f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;
        }

        private void RunEthanolDistiller(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !techAdvancedPower || lumber <= 0.001f)
            {
                return;
            }

            float targetLumber = Mathf.Min(lumber, EthanolDistillerLumberRate * deltaTime);
            float targetPower = EthanolDistillerPowerRate * deltaTime * (targetLumber / Mathf.Max(0.001f, EthanolDistillerLumberRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float processed = targetLumber * efficiency;
            if (processed <= 0.001f)
            {
                return;
            }

            lumber = Mathf.Max(0f, lumber - processed);
            float fuelOutput = processed * EthanolDistillerPetroleumYield;
            StorePetroleumInStorage(fuelOutput);
            ethanolProduced += fuelOutput;
            ethanolLumberUsed += processed;
            ConsumeCyclePower(powerUsed);
            AddGasToTile(center.x, center.y, 0f, processed * EthanolDistillerCarbonRate, 0f, 0f, 0f, 0f, 0f);
            AddHeat(center, EthanolDistillerHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00036f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;
        }

        private void RunTextileLoom(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !techFoodPreparation || reedFiber <= 0.001f || !TrySelectTextileRecipe(out WorkerOutfit outfit, out float fiberCost))
            {
                return;
            }

            float stockNeed = Mathf.Max(0f, DesiredOutfitStockTarget(outfit) - OutfitStockAmount(outfit));
            float targetFiber = Mathf.Min(reedFiber, TextileLoomReedFiberRate * deltaTime);
            targetFiber = Mathf.Min(targetFiber, stockNeed * fiberCost);
            if (targetFiber <= 0.001f)
            {
                return;
            }

            float requestedPower = TextileLoomPowerRate * deltaTime * (targetFiber / Mathf.Max(0.001f, TextileLoomReedFiberRate * deltaTime));
            float powerUsed = Mathf.Min(power, requestedPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, requestedPower);
            float processed = targetFiber * efficiency;
            if (processed <= 0.001f)
            {
                return;
            }

            float beforeStock = TotalOutfitStock();
            reedFiber = Mathf.Max(0f, reedFiber - processed);
            AddOutfitStock(outfit, processed / fiberCost);
            reedFiberWoven += processed;
            int finishedOutfits = Mathf.Max(0, Mathf.FloorToInt(TotalOutfitStock()) - Mathf.FloorToInt(beforeStock));
            outfitsTailored += finishedOutfits;
            ConsumeCyclePower(powerUsed);
            AddHeat(center, TextileLoomHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00020f * deltaTime * efficiency);
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool CanEthanolDistillerRun(Vector2Int center)
        {
            return techAdvancedPower &&
                CanPoweredMachineRun(center) &&
                lumber > 0.001f;
        }

        private bool CanTextileLoomRun(Vector2Int center)
        {
            return techFoodPreparation &&
                CanPoweredMachineRun(center) &&
                reedFiber > 0.001f &&
                TrySelectTextileRecipe(out _, out _);
        }

        private bool TrySelectTextileRecipe(out WorkerOutfit outfit, out float fiberCost)
        {
            outfit = WorkerOutfit.None;
            fiberCost = 0f;

            float warmNeed = Mathf.Max(0f, DesiredOutfitStockTarget(WorkerOutfit.WarmCoat) - warmOutfits);
            float coolNeed = Mathf.Max(0f, DesiredOutfitStockTarget(WorkerOutfit.CoolVest) - coolOutfits);
            float snazzyNeed = Mathf.Max(0f, DesiredOutfitStockTarget(WorkerOutfit.SnazzySuit) - snazzySuits);
            if (warmNeed <= 0.001f && coolNeed <= 0.001f && snazzyNeed <= 0.001f)
            {
                return false;
            }

            if (warmNeed >= coolNeed && warmNeed >= snazzyNeed)
            {
                outfit = WorkerOutfit.WarmCoat;
                fiberCost = WarmOutfitFiberCost;
                return true;
            }

            if (coolNeed >= snazzyNeed)
            {
                outfit = WorkerOutfit.CoolVest;
                fiberCost = CoolOutfitFiberCost;
                return true;
            }

            outfit = WorkerOutfit.SnazzySuit;
            fiberCost = SnazzySuitFiberCost;
            return true;
        }

        private float DesiredOutfitStockTarget(WorkerOutfit outfit)
        {
            float baseTarget = Mathf.Max(MinimumOutfitStockTarget, workers.Count * OutfitStockTargetPerWorker);
            return outfit == WorkerOutfit.SnazzySuit ? Mathf.Max(1f, baseTarget * 0.75f) : baseTarget;
        }

        private float TotalOutfitStock()
        {
            return warmOutfits + coolOutfits + snazzySuits;
        }

        private float OutfitStockAmount(WorkerOutfit outfit)
        {
            switch (outfit)
            {
                case WorkerOutfit.WarmCoat:
                    return warmOutfits;
                case WorkerOutfit.CoolVest:
                    return coolOutfits;
                case WorkerOutfit.SnazzySuit:
                    return snazzySuits;
                default:
                    return 0f;
            }
        }

        private void AddOutfitStock(WorkerOutfit outfit, float amount)
        {
            if (amount <= 0f)
            {
                return;
            }

            switch (outfit)
            {
                case WorkerOutfit.WarmCoat:
                    warmOutfits += amount;
                    break;
                case WorkerOutfit.CoolVest:
                    coolOutfits += amount;
                    break;
                case WorkerOutfit.SnazzySuit:
                    snazzySuits += amount;
                    break;
            }
        }

        private void RunOilWell(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f ||
                !techAdvancedPower ||
                !TryFindOilReservoirAccess(center, OilWellReservoirRange, out _))
            {
                return;
            }

            float requestedWater = OilWellWaterRate * deltaTime;
            float requestedPower = OilWellPowerRate * deltaTime;
            float waterScale = CleanWaterAvailableForMachine(center) / Mathf.Max(0.001f, requestedWater);
            float powerScale = power / Mathf.Max(0.001f, requestedPower);
            float efficiency = Mathf.Clamp01(Mathf.Min(waterScale, powerScale));
            if (efficiency <= 0.001f)
            {
                return;
            }

            float waterUsed = ConsumeMachineWater(center, requestedWater * efficiency, out _);
            if (waterUsed <= 0.001f)
            {
                return;
            }

            float actualEfficiency = Mathf.Clamp01(waterUsed / Mathf.Max(0.001f, requestedWater));
            float powerUsed = Mathf.Min(power, requestedPower * actualEfficiency);
            float crudeProduced = waterUsed * OilWellCrudeYield;
            float naturalGasVented = waterUsed * OilWellNaturalGasYield;

            crudeOil += crudeProduced;
            oilWellWaterUsed += waterUsed;
            oilWellCrudeProduced += crudeProduced;
            oilWellNaturalGasVented += naturalGasVented;
            ConsumeCyclePower(powerUsed);
            AddGasToTile(center.x, center.y, 0f, 0f, 0f, 0f, 0f, naturalGasVented, 0f);
            AddHeat(center, OilWellHeatRate * deltaTime * actualEfficiency, 2);
            WearEquipment(center, 0.00040f * deltaTime * actualEfficiency);
            gasDirty = true;
            overlayDirty = true;
        }

        private bool CanOilWellRun(Vector2Int center)
        {
            return techAdvancedPower &&
                CanPoweredMachineRun(center) &&
                CleanWaterAvailableForMachine(center) > 0.001f &&
                TryFindOilReservoirAccess(center, OilWellReservoirRange, out _);
        }

        private void RunPolymerPress(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || petroleum <= 0.001f || DryResourceFreeSpace() <= 0.001f)
            {
                return;
            }

            float targetPetroleum = Mathf.Min(petroleum, PolymerPressPetroleumRate * deltaTime);
            targetPetroleum = Mathf.Min(targetPetroleum, DryResourceFreeSpace() / Mathf.Max(0.001f, PolymerPressPlasticYield));
            if (targetPetroleum <= 0.001f)
            {
                return;
            }

            float targetPower = PolymerPressPowerRate * deltaTime * (targetPetroleum / Mathf.Max(0.001f, PolymerPressPetroleumRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float processed = targetPetroleum * efficiency;
            if (processed <= 0.001f)
            {
                return;
            }

            petroleum = Mathf.Max(0f, petroleum - processed);
            float produced = processed * PolymerPressPlasticYield;
            float stored = StoreDryResource(ref plastic, produced);
            plasticPressed += stored;
            ConsumeCyclePower(powerUsed);
            AddGasToTile(center.x, center.y, 0f, processed * PolymerPressCarbonYield, 0f, 0f, 0f, 0f, 0f);
            AddHeat(center, PolymerPressHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00036f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;
        }

        private float ConsumeMachineWater(Vector2Int center, float requested)
        {
            return ConsumeMachineWater(center, requested, out _);
        }

        private float ConsumeMachineWater(Vector2Int center, float requested, out float consumedGerms)
        {
            consumedGerms = 0f;
            if (requested <= 0f)
            {
                return 0f;
            }

            float consumed = 0f;
            if (TryFindAdjacentLiquidPipeWithWater(center, out Vector2Int pipe))
            {
                float piped = RemoveCleanWaterFromPipe(pipe, requested, out float pipeGerms);
                consumedGerms = MixConcentration(consumedGerms, consumed, pipeGerms, piped);
                consumed += piped;
            }

            float remaining = requested - consumed;
            if (remaining > 0.001f && water > 0f)
            {
                float stored = Mathf.Min(remaining, water);
                consumedGerms = MixConcentration(consumedGerms, consumed, waterGerms, stored);
                water -= stored;
                if (water <= 0.001f)
                {
                    waterGerms = 0f;
                }

                consumed += stored;
            }

            currentCycleReport.WaterConsumed += consumed;
            return consumed;
        }

        private void StoreCleanWater(Vector2Int center, float amount)
        {
            StoreCleanWater(center, amount, 0f);
        }

        private void StoreCleanWater(Vector2Int center, float amount, float germLevel)
        {
            if (amount <= 0f)
            {
                return;
            }

            float storedAmount = amount;
            if (TryFindAdjacentLiquidPipeWithSpace(center, out Vector2Int pipe))
            {
                float pipeAttempt = LimitLiquidValveFlow(pipe, Mathf.Min(amount, LiquidPipeFreeCapacity(pipe.x, pipe.y)));
                float piped = AddLiquidPipeWater(pipe, pipeAttempt, temperature[center.x, center.y], germLevel);
                amount -= piped;
            }

            if (amount > 0f)
            {
                StoreCleanWaterInStorage(amount, germLevel);
            }

            currentCycleReport.WaterProduced += storedAmount;
        }

        private void StoreCleanWaterInStorage(float amount, float germLevel)
        {
            if (amount <= 0f)
            {
                return;
            }

            waterGerms = MixConcentration(waterGerms, water, germLevel, amount);
            water += amount;
        }

        private void StoreSaltWaterInStorage(float amount)
        {
            if (amount <= 0f)
            {
                return;
            }

            saltWater += amount;
        }

        private void StoreCrudeOilInStorage(float amount)
        {
            if (amount <= 0f)
            {
                return;
            }

            crudeOil += amount;
        }

        private void StorePetroleumInStorage(float amount)
        {
            if (amount <= 0f)
            {
                return;
            }

            petroleum += amount;
        }

        private float CleanWaterSourceGermLevel(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            return Mathf.Clamp01(germs[cell.x, cell.y] * 0.95f + pollutedOxygen[cell.x, cell.y] * 0.10f);
        }

        private float StoredPollutedWaterGermLevel()
        {
            return pollutedWater > 0.001f ? Mathf.Clamp01(pollutedWaterGerms) : 0f;
        }

        private float PollutedWaterSourceGermLevel(Vector2Int cell)
        {
            float storedRisk = StoredPollutedWaterGermLevel();
            if (!IsInside(cell.x, cell.y))
            {
                return storedRisk;
            }

            float localRisk = Mathf.Clamp01(germs[cell.x, cell.y] * 0.95f + pollutedOxygen[cell.x, cell.y] * 0.12f);
            if (IsPollutedWorldLiquidAt(cell.x, cell.y))
            {
                return Mathf.Max(localRisk, PollutedWaterDefaultGermLevel * 0.5f);
            }

            return Mathf.Max(storedRisk, localRisk * 0.55f);
        }

        private float MoppedPollutedWaterGermLevel(Vector2Int cell)
        {
            return Mathf.Clamp01(PollutedWaterDefaultGermLevel + PollutedWaterSourceGermLevel(cell) * 0.55f);
        }

        private float FixturePollutedWaterGermLevel(Vector2Int cell, Worker worker, float cleanWaterGerms, float fixtureBaseRisk)
        {
            float workerRisk = worker != null ? Mathf.Clamp01(worker.GermExposure / 100f) : 0f;
            float localRisk = IsInside(cell.x, cell.y) ? Mathf.Clamp01(germs[cell.x, cell.y] + pollutedOxygen[cell.x, cell.y] * 0.12f) : 0f;
            return Mathf.Clamp01(fixtureBaseRisk + Mathf.Clamp01(cleanWaterGerms) * 0.45f + workerRisk * 0.55f + localRisk * 0.25f);
        }

        private float WaterSieveOutputGermLevel(Vector2Int center, float consumedPollutedWaterGerms)
        {
            float sourceRisk = Mathf.Clamp01(consumedPollutedWaterGerms);
            if (TryFindAdjacentLiquidPipeWithPollutedWater(center, out Vector2Int pipe))
            {
                sourceRisk = Mathf.Max(sourceRisk, pipePollutedWaterGerms[pipe.x, pipe.y]);
            }

            if (IsInside(center.x, center.y))
            {
                sourceRisk = Mathf.Max(sourceRisk, germs[center.x, center.y] + pollutedOxygen[center.x, center.y] * 0.12f);
            }

            return Mathf.Clamp01(sourceRisk * WaterSieveCleanWaterGermCarryover);
        }

        private float CleanWaterHygieneQuality(float waterGermLevel)
        {
            return Mathf.Clamp01(1f - Mathf.Clamp01(waterGermLevel) * CleanWaterGermHygienePenalty);
        }

        private void RecordGermyWaterUse(float waterGermLevel)
        {
            if (waterGermLevel >= CleanWaterGermAlertThreshold)
            {
                germyWaterUses++;
            }
        }

        private void StorePollutedWater(Vector2Int center, float amount, float germLevel = PollutedWaterDefaultGermLevel)
        {
            if (amount <= 0f)
            {
                return;
            }

            germLevel = Mathf.Clamp01(germLevel);

            if (TryFindAdjacentLiquidPipeWithSpace(center, out Vector2Int pipe))
            {
                float pipeAttempt = LimitLiquidValveFlow(pipe, Mathf.Min(amount, LiquidPipeFreeCapacity(pipe.x, pipe.y)));
                float piped = AddLiquidPipePollutedWater(pipe, pipeAttempt, temperature[center.x, center.y], germLevel);
                amount -= piped;
            }

            if (amount > 0f)
            {
                StorePollutedWaterInStorage(amount, germLevel);
            }
        }

        private void StorePollutedWaterInStorage(float amount, float germLevel)
        {
            if (amount <= 0f)
            {
                return;
            }

            pollutedWaterGerms = MixConcentration(pollutedWaterGerms, pollutedWater, germLevel, amount);
            pollutedWater += amount;
        }

        private void SimulateChlorineLiquidSterilization(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            float sterilized = 0f;
            if (water > 0.001f && waterGerms > 0.001f)
            {
                float before = waterGerms;
                waterGerms = SterilizedLiquidGermLevel(waterGerms, ChlorineSterilizationPressure(StoredCleanWaterCell()), deltaTime);
                sterilized += SterilizedLiquidGermMass(before, waterGerms, water);
            }

            if (pollutedWater > 0.001f && pollutedWaterGerms > 0.001f)
            {
                float before = pollutedWaterGerms;
                pollutedWaterGerms = SterilizedLiquidGermLevel(pollutedWaterGerms, ChlorineSterilizationPressure(WasteStorageCell()), deltaTime);
                sterilized += SterilizedLiquidGermMass(before, pollutedWaterGerms, pollutedWater);
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    float pressure = ChlorineSterilizationPressure(cell);
                    if (liquidPipe[x, y])
                    {
                        if (pipeWater[x, y] > 0.001f && pipeWaterGerms[x, y] > 0.001f)
                        {
                            float before = pipeWaterGerms[x, y];
                            pipeWaterGerms[x, y] = SterilizedLiquidGermLevel(pipeWaterGerms[x, y], pressure, deltaTime);
                            sterilized += SterilizedLiquidGermMass(before, pipeWaterGerms[x, y], pipeWater[x, y]);
                        }

                        if (pipePollutedWater[x, y] > 0.001f && pipePollutedWaterGerms[x, y] > 0.001f)
                        {
                            float before = pipePollutedWaterGerms[x, y];
                            pipePollutedWaterGerms[x, y] = SterilizedLiquidGermLevel(pipePollutedWaterGerms[x, y], pressure, deltaTime);
                            sterilized += SterilizedLiquidGermMass(before, pipePollutedWaterGerms[x, y], pipePollutedWater[x, y]);
                        }
                    }

                    if (cells[x, y] != CellKind.LiquidReservoir)
                    {
                        continue;
                    }

                    if (liquidReservoirWater[x, y] > 0.001f && liquidReservoirWaterGerms[x, y] > 0.001f)
                    {
                        float before = liquidReservoirWaterGerms[x, y];
                        liquidReservoirWaterGerms[x, y] = SterilizedLiquidGermLevel(liquidReservoirWaterGerms[x, y], pressure, deltaTime);
                        sterilized += SterilizedLiquidGermMass(before, liquidReservoirWaterGerms[x, y], liquidReservoirWater[x, y]);
                    }

                    if (liquidReservoirPollutedWater[x, y] > 0.001f && liquidReservoirPollutedWaterGerms[x, y] > 0.001f)
                    {
                        float before = liquidReservoirPollutedWaterGerms[x, y];
                        liquidReservoirPollutedWaterGerms[x, y] = SterilizedLiquidGermLevel(liquidReservoirPollutedWaterGerms[x, y], pressure, deltaTime);
                        sterilized += SterilizedLiquidGermMass(before, liquidReservoirPollutedWaterGerms[x, y], liquidReservoirPollutedWater[x, y]);
                    }
                }
            }

            if (sterilized > 0.0001f)
            {
                chlorineSterilizedLiquidGerms += sterilized;
                overlayDirty = true;
            }
        }

        private float SterilizedLiquidGermLevel(float germLevel, float chlorinePressure, float deltaTime)
        {
            germLevel = Mathf.Clamp01(germLevel);
            if (germLevel <= 0.001f || chlorinePressure <= ChlorineExposureThreshold || deltaTime <= 0f)
            {
                return germLevel;
            }

            float reduction = (chlorinePressure - ChlorineExposureThreshold) * ChlorineLiquidSterilizeRate * deltaTime;
            return Mathf.Clamp01(Mathf.Max(0f, germLevel - reduction));
        }

        private float SterilizedLiquidGermMass(float beforeGermLevel, float afterGermLevel, float liquidMass)
        {
            if (liquidMass <= 0.001f)
            {
                return 0f;
            }

            return Mathf.Max(0f, Mathf.Clamp01(beforeGermLevel) - Mathf.Clamp01(afterGermLevel)) * liquidMass;
        }

        private float ChlorineSterilizationPressure(Vector2Int center)
        {
            if (!IsInside(center.x, center.y))
            {
                return 0f;
            }

            float pressure = 0f;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y))
                    {
                        pressure = Mathf.Max(pressure, chlorine[x, y]);
                    }
                }
            }

            return pressure;
        }

        private bool IsChlorineSterilizingLiquidAt(Vector2Int cell)
        {
            return ChlorineSterilizationPressure(cell) > ChlorineExposureThreshold && HasSterilizableLiquidGermsAt(cell);
        }

        private bool HasSterilizableLiquidGermsAt(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (liquidPipe[cell.x, cell.y] &&
                ((pipeWater[cell.x, cell.y] > 0.001f && pipeWaterGerms[cell.x, cell.y] > 0.001f) ||
                (pipePollutedWater[cell.x, cell.y] > 0.001f && pipePollutedWaterGerms[cell.x, cell.y] > 0.001f)))
            {
                return true;
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidReservoir &&
                ((liquidReservoirWater[cell.x, cell.y] > 0.001f && liquidReservoirWaterGerms[cell.x, cell.y] > 0.001f) ||
                (liquidReservoirPollutedWater[cell.x, cell.y] > 0.001f && liquidReservoirPollutedWaterGerms[cell.x, cell.y] > 0.001f)))
            {
                return true;
            }

            return (water > 0.001f && waterGerms > 0.001f && cell == StoredCleanWaterCell()) ||
                (pollutedWater > 0.001f && pollutedWaterGerms > 0.001f && cell == WasteStorageCell());
        }

        private void SimulateChlorineGasConduitSterilization(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            float sterilized = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (gasPipe[x, y] && gasPipeGerms[x, y] > 0.001f)
                    {
                        float total = GasPipeTotal(x, y);
                        if (total <= 0.001f)
                        {
                            gasPipeGerms[x, y] = 0f;
                            continue;
                        }

                        float before = gasPipeGerms[x, y];
                        gasPipeGerms[x, y] = SterilizedGasConduitGermLevel(
                            gasPipeGerms[x, y],
                            GasConduitChlorineFraction(gasPipeChlorine[x, y], total),
                            deltaTime);
                        sterilized += SterilizedGasConduitGermMass(before, gasPipeGerms[x, y], total);
                    }

                    if (cells[x, y] == CellKind.GasReservoir && gasReservoirGerms[x, y] > 0.001f)
                    {
                        float total = GasReservoirTotal(x, y);
                        if (total <= 0.001f)
                        {
                            gasReservoirGerms[x, y] = 0f;
                            continue;
                        }

                        float before = gasReservoirGerms[x, y];
                        gasReservoirGerms[x, y] = SterilizedGasConduitGermLevel(
                            gasReservoirGerms[x, y],
                            GasConduitChlorineFraction(gasReservoirChlorine[x, y], total),
                            deltaTime);
                        sterilized += SterilizedGasConduitGermMass(before, gasReservoirGerms[x, y], total);
                    }
                }
            }

            if (sterilized > 0.0001f)
            {
                chlorineSterilizedGerms += sterilized;
                overlayDirty = true;
            }
        }

        private float SterilizedGasConduitGermLevel(float germLevel, float chlorineFraction, float deltaTime)
        {
            germLevel = Mathf.Clamp01(germLevel);
            if (germLevel <= 0.001f || chlorineFraction <= ChlorineConduitSterilizeMinimumFraction || deltaTime <= 0f)
            {
                return germLevel;
            }

            float reduction = (chlorineFraction - ChlorineConduitSterilizeMinimumFraction) * ChlorineConduitSterilizeRate * deltaTime;
            return Mathf.Clamp01(Mathf.Max(0f, germLevel - reduction));
        }

        private float SterilizedGasConduitGermMass(float beforeGermLevel, float afterGermLevel, float gasMass)
        {
            if (gasMass <= 0.001f)
            {
                return 0f;
            }

            return Mathf.Max(0f, Mathf.Clamp01(beforeGermLevel) - Mathf.Clamp01(afterGermLevel)) * gasMass;
        }

        private float GasConduitChlorineFraction(float chlorineMass, float totalGas)
        {
            return totalGas <= 0.001f ? 0f : Mathf.Clamp01(chlorineMass / totalGas);
        }

        private bool IsChlorineSterilizingGasConduitAt(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (gasPipe[cell.x, cell.y] &&
                gasPipeGerms[cell.x, cell.y] > 0.001f &&
                GasConduitChlorineFraction(gasPipeChlorine[cell.x, cell.y], GasPipeTotal(cell.x, cell.y)) > ChlorineConduitSterilizeMinimumFraction)
            {
                return true;
            }

            return cells[cell.x, cell.y] == CellKind.GasReservoir &&
                gasReservoirGerms[cell.x, cell.y] > 0.001f &&
                GasConduitChlorineFraction(gasReservoirChlorine[cell.x, cell.y], GasReservoirTotal(cell.x, cell.y)) > ChlorineConduitSterilizeMinimumFraction;
        }

        private float PollutedWaterAvailableForSieve(Vector2Int center)
        {
            float available = pollutedWater;
            if (TryFindAdjacentLiquidPipeWithPollutedWater(center, out Vector2Int pipe))
            {
                available += pipePollutedWater[pipe.x, pipe.y];
            }

            return available;
        }

        private float PollutedWaterAvailableForThimbleReed(Vector2Int center)
        {
            return PollutedWaterAvailableForSieve(center) + PollutedWorldWaterAround(center, ThimbleReedPollutedWaterSearchRange);
        }

        private float PollutedWorldWaterAround(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || Mathf.Abs(dx) + Mathf.Abs(dy) > radius)
                    {
                        continue;
                    }

                    if (IsPollutedWorldLiquidAt(x, y))
                    {
                        total += waterMass[x, y];
                    }
                }
            }

            return total;
        }

        private float PollutedWaterGermLevelForSieve(Vector2Int center)
        {
            float available = 0f;
            float germLevel = 0f;
            if (TryFindAdjacentLiquidPipeWithPollutedWater(center, out Vector2Int pipe))
            {
                float piped = pipePollutedWater[pipe.x, pipe.y];
                germLevel = MixConcentration(germLevel, available, pipePollutedWaterGerms[pipe.x, pipe.y], piped);
                available += piped;
            }

            if (pollutedWater > 0.001f)
            {
                germLevel = MixConcentration(germLevel, available, pollutedWaterGerms, pollutedWater);
            }

            return germLevel;
        }

        private float ConsumePollutedWaterForSieve(Vector2Int center, float requested)
        {
            return ConsumePollutedWaterForSieve(center, requested, out _);
        }

        private float ConsumePollutedWaterForThimbleReed(Vector2Int center, float requested)
        {
            float consumed = ConsumePollutedWaterForSieve(center, requested);
            float remaining = requested - consumed;
            if (remaining > 0.001f)
            {
                consumed += ConsumePollutedWorldWaterAround(center, remaining, ThimbleReedPollutedWaterSearchRange);
            }

            return consumed;
        }

        private float ConsumePollutedWaterForSieve(Vector2Int center, float requested, out float consumedGerms)
        {
            consumedGerms = 0f;
            if (requested <= 0f)
            {
                return 0f;
            }

            float consumed = 0f;
            if (TryFindAdjacentLiquidPipeWithPollutedWater(center, out Vector2Int pipe))
            {
                float piped = RemovePollutedWaterFromPipe(pipe, requested, out float pipeGerms);
                consumedGerms = MixConcentration(consumedGerms, consumed, pipeGerms, piped);
                consumed += piped;
            }

            float remaining = requested - consumed;
            if (remaining > 0.001f && pollutedWater > 0f)
            {
                float stored = Mathf.Min(remaining, pollutedWater);
                consumedGerms = MixConcentration(consumedGerms, consumed, pollutedWaterGerms, stored);
                pollutedWater -= stored;
                if (pollutedWater <= 0.001f)
                {
                    pollutedWaterGerms = 0f;
                }

                consumed += stored;
            }

            return consumed;
        }

        private float ConsumePollutedWorldWaterAround(Vector2Int center, float requested, int radius)
        {
            if (requested <= 0f)
            {
                return 0f;
            }

            float consumed = 0f;
            for (int searchRadius = 0; searchRadius <= radius && consumed < requested; searchRadius++)
            {
                for (int y = center.y - searchRadius; y <= center.y + searchRadius && consumed < requested; y++)
                {
                    for (int x = center.x - searchRadius; x <= center.x + searchRadius && consumed < requested; x++)
                    {
                        if (Mathf.Abs(x - center.x) != searchRadius && Mathf.Abs(y - center.y) != searchRadius)
                        {
                            continue;
                        }

                        if (!IsInside(x, y) || Mathf.Abs(x - center.x) + Mathf.Abs(y - center.y) > radius || !IsPollutedWorldLiquidAt(x, y))
                        {
                            continue;
                        }

                        float remaining = requested - consumed;
                        float fromTile = Mathf.Min(remaining, waterMass[x, y]);
                        waterMass[x, y] -= fromTile;
                        consumed += fromTile;
                        if (waterMass[x, y] <= 0.5f)
                        {
                            Vector2Int source = new Vector2Int(x, y);
                            DryWaterCell(
                                source,
                                NeighborAverage(oxygen, x, y, 0.12f),
                                NeighborAverage(carbonDioxide, x, y, 0.04f),
                                0.04f,
                                NeighborAverage(hydrogen, x, y, 0f),
                                NeighborAverage(chlorine, x, y, 0f),
                                NeighborAverage(naturalGas, x, y, 0f),
                                0.08f,
                                temperature[x, y],
                                NeighborAverage(sourGas, x, y, 0f));
                            terrainDirty = true;
                            gasDirty = true;
                            InvalidateRooms();
                        }
                    }
                }
            }

            return consumed;
        }

        private float CarbonDioxideAround(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        total += carbonDioxide[x, y];
                    }
                }
            }

            return total;
        }

        private float HotCarbonDioxideAround(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y) && temperature[x, y] >= MoltenSlicksterMoveTemperatureMin)
                    {
                        total += carbonDioxide[x, y];
                    }
                }
            }

            return total;
        }

        private float RemoveCarbonDioxide(Vector2Int center, float capacity, int radius)
        {
            float removed = 0f;
            for (int dy = -radius; dy <= radius && removed < capacity; dy++)
            {
                for (int dx = -radius; dx <= radius && removed < capacity; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float amount = Mathf.Min(carbonDioxide[x, y], capacity - removed);
                    carbonDioxide[x, y] -= amount;
                    removed += amount;
                }
            }

            return removed;
        }

        private float RemoveHotCarbonDioxide(Vector2Int center, float capacity, int radius)
        {
            float removed = 0f;
            for (int dy = -radius; dy <= radius && removed < capacity; dy++)
            {
                for (int dx = -radius; dx <= radius && removed < capacity; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y) || temperature[x, y] < MoltenSlicksterMoveTemperatureMin)
                    {
                        continue;
                    }

                    float amount = Mathf.Min(carbonDioxide[x, y], capacity - removed);
                    carbonDioxide[x, y] -= amount;
                    removed += amount;
                }
            }

            return removed;
        }

        private void RunSpaceHeater(Vector2Int center, float deltaTime)
        {
            float localTemperature = AverageTemperatureAround(center, 3);
            if (localTemperature >= 24f)
            {
                return;
            }

            float powerUsed = Mathf.Min(power, 0.62f * deltaTime);
            float efficiency = powerUsed / Mathf.Max(0.001f, 0.62f * deltaTime);
            ConsumeCyclePower(powerUsed);
            AddHeat(center, 0.95f * deltaTime * efficiency, 3);
            WearEquipment(center, 0.00032f * deltaTime * efficiency);
        }

        private void RunLiquidTepidizer(Vector2Int center, float deltaTime)
        {
            if (!TryGetLiquidTepidizerLiquidSummary(center, out float liquidMass, out float averageTemperature) ||
                averageTemperature >= LiquidTepidizerTargetTemperature - 0.05f)
            {
                return;
            }

            float targetPower = LiquidTepidizerPowerRate * deltaTime;
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float heatBudget = LiquidTepidizerHeatRate * deltaTime * efficiency;
            if (heatBudget <= 0.001f)
            {
                return;
            }

            float heatApplied = HeatLiquidAround(center, heatBudget, LiquidTepidizerTargetTemperature);
            if (heatApplied <= 0.001f)
            {
                return;
            }

            float activeScale = Mathf.Clamp01(heatApplied / Mathf.Max(0.001f, heatBudget));
            ConsumeCyclePower(powerUsed * activeScale);
            liquidTepidizerHeatAdded += heatApplied;
            WearEquipment(center, 0.00034f * deltaTime * efficiency * activeScale * Mathf.Clamp01(liquidMass / 20f));
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool TryGetLiquidTepidizerLiquidSummary(Vector2Int center, out float totalMass, out float averageTemperature)
        {
            totalMass = 0f;
            float weightedTemperature = 0f;
            for (int y = center.y - LiquidTepidizerRadius; y <= center.y + LiquidTepidizerRadius; y++)
            {
                for (int x = center.x - LiquidTepidizerRadius; x <= center.x + LiquidTepidizerRadius; x++)
                {
                    if (!HasWorldLiquidAt(x, y))
                    {
                        continue;
                    }

                    float mass = Mathf.Max(0f, waterMass[x, y]);
                    totalMass += mass;
                    weightedTemperature += temperature[x, y] * mass;
                }
            }

            averageTemperature = totalMass > 0.001f ? weightedTemperature / totalMass : temperature[center.x, center.y];
            return totalMass > LiquidMinimumRetainedMass;
        }

        private float HeatLiquidAround(Vector2Int center, float heatBudget, float targetTemperature)
        {
            float remaining = Mathf.Max(0f, heatBudget);
            float applied = 0f;
            for (int y = center.y - LiquidTepidizerRadius; y <= center.y + LiquidTepidizerRadius; y++)
            {
                for (int x = center.x - LiquidTepidizerRadius; x <= center.x + LiquidTepidizerRadius; x++)
                {
                    if (remaining <= 0.001f)
                    {
                        return applied;
                    }

                    if (!HasWorldLiquidAt(x, y) || temperature[x, y] >= targetTemperature)
                    {
                        continue;
                    }

                    float capacity = Mathf.Max(0.35f, ThermalCapacityAt(x, y));
                    float heatNeeded = (targetTemperature - temperature[x, y]) * capacity;
                    float used = Mathf.Min(remaining, heatNeeded);
                    temperature[x, y] = Mathf.Clamp(temperature[x, y] + used / capacity, -30f, targetTemperature);
                    remaining -= used;
                    applied += used;
                }
            }

            return applied;
        }

        private void RunThermoRegulator(Vector2Int center, float deltaTime)
        {
            if (TryRunCryogenicPropellantPlant(center, deltaTime))
            {
                return;
            }

            if (!TryFindAdjacentGasPipeWithGas(center, out Vector2Int inputPipe) ||
                !TryFindAdjacentGasPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe))
            {
                return;
            }

            float requestedFlow = Mathf.Min(
                ThermoRegulatorGasRate * deltaTime,
                Mathf.Min(GasPipeTotal(inputPipe.x, inputPipe.y), GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y)));
            if (requestedFlow <= 0.001f)
            {
                return;
            }

            float targetPower = ThermoRegulatorPowerRate * deltaTime * (requestedFlow / Mathf.Max(0.001f, ThermoRegulatorGasRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float moved = requestedFlow * efficiency;
            if (moved <= 0.001f)
            {
                return;
            }

            float cooling = moved * ThermoRegulatorCoolingPerKg;
            float cooledTemperature = Mathf.Clamp(temperature[inputPipe.x, inputPipe.y] - cooling, -30f, 120f);
            float actualMoved = MoveGasPipeToPipeAtTemperature(inputPipe, outputPipe, moved, cooledTemperature);
            if (actualMoved <= 0.001f)
            {
                return;
            }

            ConsumeCyclePower(powerUsed);
            temperature[inputPipe.x, inputPipe.y] = Mathf.Clamp(temperature[inputPipe.x, inputPipe.y] - cooling * 0.15f, -30f, 120f);
            AddHeat(center, actualMoved * ThermoRegulatorHeatPerKg, 2);

            thermoRegulatorGasCooled += actualMoved;
            WearEquipment(center, 0.00038f * deltaTime * efficiency);
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool TryRunCryogenicPropellantPlant(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !CanCryogenicPropellantPlantRun(center))
            {
                return false;
            }

            float fullOxygenTarget = CryogenicPropellantOxygenRate * deltaTime;
            float fullHydrogenTarget = CryogenicPropellantHydrogenRate * deltaTime;
            float fullSuperCoolantTarget = CryogenicPropellantSuperCoolantRate * deltaTime;
            float fullPowerTarget = CryogenicPropellantPowerRate * deltaTime;
            float fullOutputTarget = (fullOxygenTarget + fullHydrogenTarget) * CryogenicPropellantYield;
            float scale = 1f;
            scale = Mathf.Min(scale, PipedOxygenAround(center) / Mathf.Max(0.001f, fullOxygenTarget));
            scale = Mathf.Min(scale, PipedHydrogenAround(center) / Mathf.Max(0.001f, fullHydrogenTarget));
            scale = Mathf.Min(scale, superCoolant / Mathf.Max(0.001f, fullSuperCoolantTarget));
            scale = Mathf.Min(scale, power / Mathf.Max(0.001f, fullPowerTarget));
            scale = Mathf.Min(scale, DryResourceFreeSpace() / Mathf.Max(0.001f, fullOutputTarget));
            scale = Mathf.Min(scale, (CryogenicPropellantStockpileTarget - cryogenicPropellant) / Mathf.Max(0.001f, fullOutputTarget));
            scale = Mathf.Clamp01(scale);
            if (scale <= 0.001f)
            {
                return false;
            }

            float requestedOxygen = fullOxygenTarget * scale;
            float requestedHydrogen = fullHydrogenTarget * scale;
            float oxygenUsed = RemovePipedOxygen(center, requestedOxygen);
            float hydrogenUsed = RemovePipedHydrogen(center, requestedHydrogen);
            float oxygenScale = requestedOxygen <= 0.001f ? 0f : oxygenUsed / requestedOxygen;
            float hydrogenScale = requestedHydrogen <= 0.001f ? 0f : hydrogenUsed / requestedHydrogen;
            float actualScale = Mathf.Clamp01(Mathf.Min(oxygenScale, hydrogenScale));
            if (actualScale <= 0.001f)
            {
                return false;
            }

            float superCoolantUsedForCryo = fullSuperCoolantTarget * scale * actualScale;
            float powerUsed = fullPowerTarget * scale * actualScale;
            float output = (oxygenUsed + hydrogenUsed) * CryogenicPropellantYield;
            float stored = StoreDryResource(ref cryogenicPropellant, output);
            if (stored <= 0.001f)
            {
                return false;
            }

            superCoolant = Mathf.Max(0f, superCoolant - superCoolantUsedForCryo);
            cryogenicPropellantProduced += stored;
            cryogenicPropellantCoolantUsed += superCoolantUsedForCryo;
            thermoRegulatorGasCooled += oxygenUsed + hydrogenUsed;
            ConsumeCyclePower(powerUsed);
            AddHeat(center, CryogenicPropellantHeatRate * deltaTime * scale * actualScale, 2);
            WearEquipment(center, 0.00044f * deltaTime * scale * actualScale);
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
            return true;
        }

        private bool CanCryogenicPropellantPlantRun(Vector2Int center)
        {
            return milestoneSuperCoolantLoop &&
                CanPoweredMachineRun(center) &&
                superCoolant > 0.001f &&
                cryogenicPropellant < CryogenicPropellantStockpileTarget - 0.001f &&
                PipedOxygenAround(center) > 0.001f &&
                PipedHydrogenAround(center) > 0.001f &&
                DryResourceFreeSpace() > 0.001f;
        }

        private bool CanThermoRegulatorCoolGas(Vector2Int center)
        {
            return CanPoweredMachineRun(center) &&
                TryFindAdjacentGasPipeWithGas(center, out Vector2Int inputPipe) &&
                TryFindAdjacentGasPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe) &&
                GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y) > 0.001f;
        }

        private void RunThermoAquatuner(Vector2Int center, float deltaTime)
        {
            if (!TryFindAdjacentLiquidPipeWithAnyLiquid(center, out Vector2Int inputPipe) ||
                !TryFindAdjacentLiquidPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe))
            {
                return;
            }

            float requestedFlow = Mathf.Min(
                ThermoAquatunerLiquidRate * deltaTime,
                Mathf.Min(LiquidPipeTotal(inputPipe.x, inputPipe.y), LiquidPipeFreeCapacity(outputPipe.x, outputPipe.y)));
            if (requestedFlow <= 0.001f)
            {
                return;
            }

            float targetPower = ThermoAquatunerPowerRate * deltaTime * (requestedFlow / Mathf.Max(0.001f, ThermoAquatunerLiquidRate * deltaTime));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float moved = requestedFlow * efficiency;
            if (moved <= 0.001f)
            {
                return;
            }

            float requestedSuperCoolant = moved * SuperCoolantUsePerKg;
            float superCoolantCharge = milestoneThermiumMachinery ? Mathf.Min(superCoolant, requestedSuperCoolant) : 0f;
            float superCoolantScale = requestedSuperCoolant <= 0.001f ? 0f : Mathf.Clamp01(superCoolantCharge / requestedSuperCoolant);
            float coolingMultiplier = Mathf.Lerp(1f, SuperCoolantCoolingMultiplier, superCoolantScale);
            float heatMultiplier = Mathf.Lerp(1f, SuperCoolantHeatMultiplier, superCoolantScale);
            float wearMultiplier = Mathf.Lerp(1f, SuperCoolantWearMultiplier, superCoolantScale);
            float cooling = moved * ThermoAquatunerCoolingPerKg * coolingMultiplier;
            float cooledTemperature = Mathf.Clamp(temperature[inputPipe.x, inputPipe.y] - cooling, -30f, 120f);
            float actualMoved = MoveLiquidPipeWaterAtTemperature(inputPipe, outputPipe, moved, cooledTemperature);
            if (actualMoved <= 0.001f)
            {
                return;
            }

            float actualMoveScale = Mathf.Clamp01(actualMoved / Mathf.Max(0.001f, moved));
            float actualSuperCoolant = superCoolantCharge * actualMoveScale;
            if (actualSuperCoolant > 0.001f)
            {
                superCoolant = Mathf.Max(0f, superCoolant - actualSuperCoolant);
                superCoolantUsed += actualSuperCoolant;
                if (CountUnsafeLiquidPipes() == 0 && CountUnsafeLiquidReservoirs() == 0)
                {
                    superCoolantCoolingSeconds = Mathf.Clamp(superCoolantCoolingSeconds + deltaTime * actualMoveScale, 0f, SuperCoolantLoopTargetSeconds);
                }
            }

            ConsumeCyclePower(powerUsed);
            temperature[inputPipe.x, inputPipe.y] = Mathf.Clamp(temperature[inputPipe.x, inputPipe.y] - cooling * 0.20f * actualMoveScale, -30f, 120f);
            AddHeat(center, actualMoved * ThermoAquatunerHeatPerKg * heatMultiplier, 2);

            thermoAquatunerWaterCooled += actualMoved;
            WearEquipment(center, 0.00046f * deltaTime * efficiency * wearMultiplier);
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool CanThermoAquatunerCoolLiquid(Vector2Int center)
        {
            return CanPoweredMachineRun(center) &&
                TryFindAdjacentLiquidPipeWithAnyLiquid(center, out Vector2Int inputPipe) &&
                TryFindAdjacentLiquidPipeWithSpaceExcluding(center, inputPipe, out Vector2Int outputPipe) &&
                LiquidPipeFreeCapacity(outputPipe.x, outputPipe.y) > 0.001f;
        }

        private void RunRefrigerator(Vector2Int center, float deltaTime)
        {
            float powerUsed = Mathf.Min(power, 0.32f * deltaTime);
            float efficiency = powerUsed / Mathf.Max(0.001f, 0.32f * deltaTime);
            ConsumeCyclePower(powerUsed);
            CoolArea(center, 0.12f * deltaTime * efficiency, 1);
            AddHeat(center, 0.06f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00018f * deltaTime * efficiency);
        }

        private void RunAutoSweeper(Vector2Int center, float deltaTime)
        {
            if (DryResourceFreeSpace() <= 0.01f || !TryFindAutoSweeperTarget(center, out Vector2Int target))
            {
                return;
            }

            LooseResourceKind resourceKind = looseResourceKind[target.x, target.y];
            float requestedTransfer = AutoSweeperTransferRate * deltaTime;
            float availableTransfer = Mathf.Min(requestedTransfer, Mathf.Min(looseResourceAmount[target.x, target.y], DryResourceFreeSpace(resourceKind, false)));
            if (availableTransfer <= 0.001f)
            {
                return;
            }

            float targetPower = AutoSweeperPowerRate * deltaTime * (availableTransfer / Mathf.Max(0.001f, requestedTransfer));
            float powerUsed = Mathf.Min(power, targetPower);
            float efficiency = powerUsed / Mathf.Max(0.001f, targetPower);
            float transfer = availableTransfer * efficiency;
            if (transfer <= 0.001f)
            {
                return;
            }

            float stored = StoreLooseResource(resourceKind, transfer, false);
            if (stored <= 0.001f)
            {
                return;
            }

            ConsumeCyclePower(powerUsed);
            looseResourceAmount[target.x, target.y] = Mathf.Max(0f, looseResourceAmount[target.x, target.y] - stored);
            if (looseResourceAmount[target.x, target.y] <= 0.05f)
            {
                looseResourceAmount[target.x, target.y] = 0f;
                looseResourceKind[target.x, target.y] = LooseResourceKind.None;
                hatchEggAge[target.x, target.y] = 0f;
            }

            sweptResources += stored;
            autoSweptResources += stored;
            milestoneResourceLogistics |= sweptResources >= 12f;
            milestoneAutoSweeping |= techAutomationLogistics && autoSweptResources >= 6f;
            AddHeat(center, 0.035f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00022f * deltaTime * efficiency);
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool TryFindAutoSweeperTarget(Vector2Int center, out Vector2Int target)
        {
            target = new Vector2Int(-1, -1);
            float bestScore = -1f;
            for (int y = center.y - AutoSweeperRange; y <= center.y + AutoSweeperRange; y++)
            {
                for (int x = center.x - AutoSweeperRange; x <= center.x + AutoSweeperRange; x++)
                {
                    if (!IsInside(x, y) || !HasLooseResource(new Vector2Int(x, y)) || !CanStoreLooseResource(looseResourceKind[x, y], false))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(center.x - x) + Mathf.Abs(center.y - y);
                    if (distance > AutoSweeperRange)
                    {
                        continue;
                    }

                    float score = AutoSweeperResourcePriority(looseResourceKind[x, y]) * 100f +
                        looseResourceAmount[x, y] +
                        (AutoSweeperRange - distance) * 0.25f;
                    if (score <= bestScore)
                    {
                        continue;
                    }

                    bestScore = score;
                    target = new Vector2Int(x, y);
                }
            }

            return target.x >= 0;
        }

        private int CountAutoSweeperTargets(Vector2Int center)
        {
            int count = 0;
            for (int y = center.y - AutoSweeperRange; y <= center.y + AutoSweeperRange; y++)
            {
                for (int x = center.x - AutoSweeperRange; x <= center.x + AutoSweeperRange; x++)
                {
                    if (!IsInside(x, y) || Mathf.Abs(center.x - x) + Mathf.Abs(center.y - y) > AutoSweeperRange)
                    {
                        continue;
                    }

                    if (HasLooseResource(new Vector2Int(x, y)) && CanStoreLooseResource(looseResourceKind[x, y], false))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private float AutoSweeperResourcePriority(LooseResourceKind kind)
        {
            switch (kind)
            {
                case LooseResourceKind.SuperCoolant:
                    return 8f;
                case LooseResourceKind.CryogenicPropellant:
                    return 8f;
                case LooseResourceKind.Thermium:
                    return 8f;
                case LooseResourceKind.Fullerene:
                    return 7f;
                case LooseResourceKind.Steel:
                    return 7f;
                case LooseResourceKind.Ceramic:
                    return 7f;
                case LooseResourceKind.Glass:
                    return 7f;
                case LooseResourceKind.Niobium:
                    return 7f;
                case LooseResourceKind.RefinedMetal:
                    return 6f;
                case LooseResourceKind.Metal:
                    return 5f;
                case LooseResourceKind.Plastic:
                    return 5f;
                case LooseResourceKind.Coal:
                    return 4f;
                case LooseResourceKind.Algae:
                    return 3f;
                case LooseResourceKind.Slime:
                case LooseResourceKind.BleachStone:
                    return 3f;
                case LooseResourceKind.PollutedDirt:
                    return 2f;
                case LooseResourceKind.HatchEgg:
                    return 1f;
                case LooseResourceKind.Peppernut:
                    return 1f;
                case LooseResourceKind.Lumber:
                    return 2f;
                case LooseResourceKind.ReedFiber:
                    return 2f;
                case LooseResourceKind.Dirt:
                    return 1f;
                default:
                    return 0f;
            }
        }

        private void UpdateGeneratorTuneUp(Vector2Int cell, float deltaTime)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return;
            }

            if (!IsTunableGenerator(cells[cell.x, cell.y]))
            {
                generatorTuneUpSeconds[cell.x, cell.y] = 0f;
                return;
            }

            float remaining = generatorTuneUpSeconds[cell.x, cell.y];
            if (remaining <= 0f)
            {
                return;
            }

            float updated = Mathf.Max(0f, remaining - deltaTime);
            generatorTuneUpSeconds[cell.x, cell.y] = updated;
            if (remaining > 0f && updated <= 0f)
            {
                overlayDirty = true;
                terrainDirty = true;
            }
        }

        private bool IsTunableGenerator(CellKind kind)
        {
            return kind == CellKind.CoalGenerator ||
                kind == CellKind.HydrogenGenerator ||
                kind == CellKind.NaturalGasGenerator ||
                kind == CellKind.PetroleumGenerator ||
                kind == CellKind.SteamTurbine ||
                kind == CellKind.SolarPanel ||
                kind == CellKind.ResearchReactor;
        }

        private float GeneratorTuneMultiplier(Vector2Int center)
        {
            return IsInside(center.x, center.y) && IsTunableGenerator(cells[center.x, center.y]) && generatorTuneUpSeconds[center.x, center.y] > 0f
                ? GeneratorTuneUpPowerMultiplier
                : 1f;
        }

        private int CountActiveGeneratorTuneUps()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsTunableGenerator(cells[x, y]) && generatorTuneUpSeconds[x, y] > 0f)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountPowerControlStationTargets(Vector2Int station)
        {
            int count = 0;
            for (int y = station.y - PowerControlStationRange; y <= station.y + PowerControlStationRange; y++)
            {
                for (int x = station.x - PowerControlStationRange; x <= station.x + PowerControlStationRange; x++)
                {
                    Vector2Int generator = new Vector2Int(x, y);
                    if (!IsInside(x, y) ||
                        Mathf.Abs(station.x - x) + Mathf.Abs(station.y - y) > PowerControlStationRange ||
                        !IsTunableGenerator(cells[x, y]))
                    {
                        continue;
                    }

                    count++;
                }
            }

            return count;
        }

        private bool TryFindPowerControlStationForGenerator(Vector2Int generator, out Vector2Int station)
        {
            station = new Vector2Int(-1, -1);
            if (!IsInside(generator.x, generator.y))
            {
                return false;
            }

            int bestDistance = int.MaxValue;
            for (int y = generator.y - PowerControlStationRange; y <= generator.y + PowerControlStationRange; y++)
            {
                for (int x = generator.x - PowerControlStationRange; x <= generator.x + PowerControlStationRange; x++)
                {
                    if (!IsInside(x, y) || cells[x, y] != CellKind.PowerControlStation || !CanUseEquipment(new Vector2Int(x, y)))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(generator.x - x) + Mathf.Abs(generator.y - y);
                    if (distance > PowerControlStationRange || distance >= bestDistance)
                    {
                        continue;
                    }

                    bestDistance = distance;
                    station = new Vector2Int(x, y);
                }
            }

            return station.x >= 0;
        }

        private bool CanTuneGeneratorAt(Vector2Int cell, bool requireNeedsTune)
        {
            return IsInside(cell.x, cell.y) &&
                techPowerRegulation &&
                IsTunableGenerator(cells[cell.x, cell.y]) &&
                CanUseEquipment(cell) &&
                HasWireAccess(cell) &&
                (!requireNeedsTune || generatorTuneUpSeconds[cell.x, cell.y] <= GeneratorTuneUpRefreshThreshold) &&
                TryFindPowerControlStationForGenerator(cell, out _);
        }

        private string GeneratorTuneStatusText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsTunableGenerator(cells[cell.x, cell.y]))
            {
                return string.Empty;
            }

            if (generatorTuneUpSeconds[cell.x, cell.y] > 0f)
            {
                return "Generator tune-up: +" + Mathf.RoundToInt((GeneratorTuneUpPowerMultiplier - 1f) * 100f) + "% output for " + generatorTuneUpSeconds[cell.x, cell.y].ToString("0") + "s" + (HasPowerPlantBonus(cell) ? "  Power Plant duration bonus active." : ".");
            }

            return TryFindPowerControlStationForGenerator(cell, out _)
                ? "Power Control Station can tune this generator" + (HasPowerPlantBonus(cell) ? " with Power Plant duration bonus." : ".")
                : "No Power Control Station in tune-up range.";
        }

        private string ManualGeneratorReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.ManualGenerator)
            {
                return "Manual generation blocked: Manual Generator missing.";
            }

            string equipmentBlock = GeneratorEquipmentBlockText(cell);
            if (!string.IsNullOrEmpty(equipmentBlock))
            {
                return equipmentBlock;
            }

            if (power >= maxPower - 4f)
            {
                return "Power generation idle: batteries are full.";
            }

            if (HasAutomationControl(cell) && !HasAutomationSignal(cell))
            {
                return "Power generation blocked: automation signal is red.";
            }

            Job operationJob = FindJobAt(cell, JobType.OperateGenerator);
            if (operationJob != null)
            {
                return "Manual generation ready: operation errand queued. " + JobReachabilityText(operationJob);
            }

            if (CountActiveWorkers() == 0)
            {
                return "Manual generation blocked: no active duplicants.";
            }

            Job testJob = new Job(JobType.OperateGenerator, cell, 3.2f);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Manual generation blocked: ",
                "Manual generation blocked: no reachable duplicant.");
            if (!string.IsNullOrEmpty(routeBlock))
            {
                return routeBlock;
            }

            return "Manual generation ready: duplicants can operate generator.";
        }

