        private string GeneratorBatteryIdleText(float batteryThreshold)
        {
            if (power >= maxPower - 1f)
            {
                return "Power generation idle: batteries are full.";
            }

            if (maxPower > 0.001f && power > maxPower * batteryThreshold)
            {
                return "Power generation idle: battery charge is above generator threshold.";
            }

            return string.Empty;
        }

