        private void RunSteamTurbine(Vector2Int center, float deltaTime)
        {
            if (!CanSteamTurbineRun(center))
            {
                return;
            }

            float powerRate = SteamTurbinePowerRate * GeneratorTuneMultiplier(center);
            float requestedPower = Mathf.Min(powerRate * deltaTime, Mathf.Max(0f, maxPower - power));
            if (requestedPower <= 0.001f)
            {
                return;
            }

            float requestedSteam = SteamTurbineSteamRate * deltaTime * (requestedPower / Mathf.Max(0.001f, powerRate * deltaTime));
            float steamUsed = RemoveHotSteam(center, requestedSteam, SteamTurbineRadius);
            if (steamUsed <= 0.001f)
            {
                return;
            }

            float efficiency = steamUsed / Mathf.Max(0.001f, requestedSteam);
            float generated = requestedPower * efficiency;
            float recoveredWater = steamUsed * SteamTurbineWaterYield;
            generated = AddGeneratedPower(generated);
            steamTurbinePowerGenerated += generated;
            steamTurbineWaterRecovered += recoveredWater;
            if (HasCoolSteamVentNearby(center, SteamTurbineRadius + 4))
            {
                coolSteamVentSteamHarvested += steamUsed;
            }

            StoreCleanWater(center, recoveredWater);
            CoolArea(center, 0.28f * deltaTime * efficiency, 2);
            AddHeat(center, 0.12f * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00058f * deltaTime * efficiency);
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool CanSteamTurbineRun(Vector2Int center)
        {
            if (!CanUseEquipment(center) || !HasWireAccess(center) || power >= maxPower - 1f || HotSteamAvailable(center, SteamTurbineRadius) <= 0.03f)
            {
                return false;
            }

            if (HasAutomationControl(center))
            {
                return HasAutomationSignal(center);
            }

            return power <= maxPower * 0.78f;
        }

        private void RunResearchReactor(Vector2Int center, float deltaTime)
        {
            if (!CanResearchReactorRun(center))
            {
                return;
            }

            float powerRate = ResearchReactorPowerRate * GeneratorTuneMultiplier(center);
            float requestedPower = Mathf.Min(powerRate * deltaTime, Mathf.Max(0f, maxPower - power));
            if (requestedPower <= 0.001f)
            {
                return;
            }

            float requestedSamples = ResearchReactorSampleRate * deltaTime * (requestedPower / Mathf.Max(0.001f, powerRate * deltaTime));
            float samplesUsed = Mathf.Min(radiationSamplesAnalyzed, requestedSamples);
            if (samplesUsed <= 0.001f)
            {
                return;
            }

            float efficiency = samplesUsed / Mathf.Max(0.001f, requestedSamples);
            float generated = AddGeneratedPower(requestedPower * efficiency);
            radiationSamplesAnalyzed = Mathf.Max(0f, radiationSamplesAnalyzed - samplesUsed);
            radiationSamples = Mathf.Max(radiationSamplesAnalyzed, radiationSamples - samplesUsed);
            nuclearPowerGenerated += generated;
            reactorSamplesFissioned += samplesUsed;
            AddHeat(center, ResearchReactorHeatRate * deltaTime * efficiency, 2);
            AddGasToTileWithSteam(center.x, center.y, 0f, 0f, 0f, 0f, ResearchReactorSteamRate * deltaTime * efficiency, 0f, 0f, 0f, temperature[center.x, center.y] + 45f);
            WearEquipment(center, 0.00086f * deltaTime * efficiency);
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool CanResearchReactorRun(Vector2Int center)
        {
            if (!milestoneRadiationResearch ||
                !CanUseEquipment(center) ||
                !HasWireAccess(center) ||
                power >= maxPower - 1f ||
                radiationSamplesAnalyzed <= 0.001f)
            {
                return false;
            }

            if (HasAutomationControl(center))
            {
                return HasAutomationSignal(center);
            }

            return power <= maxPower * 0.82f;
        }

        private void RunRadboltCollector(Vector2Int center, float deltaTime)
        {
            if (!CanRadboltCollectorRun(center) || deltaTime <= 0f)
            {
                return;
            }

            float localRadiation = RadiationAt(center.x, center.y);
            float radiationFactor = Mathf.Clamp01(localRadiation / Mathf.Max(0.001f, ResearchReactorRadiation));
            float requestedPower = RadboltCollectorPowerRate * deltaTime;
            float efficiency = Mathf.Clamp01(power / Mathf.Max(0.001f, requestedPower));
            if (efficiency <= 0.001f)
            {
                return;
            }

            float generated = RadboltCollectorChargeRate * radiationFactor * deltaTime * efficiency;
            if (generated <= 0.001f)
            {
                return;
            }

            radboltCharge += generated;
            radboltsGenerated += generated;
            ConsumeCyclePower(requestedPower * efficiency);
            AddHeat(center, RadboltCollectorHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00034f * deltaTime * efficiency);
            terrainDirty = true;
            overlayDirty = true;
        }

        private bool CanRadboltCollectorRun(Vector2Int center)
        {
            return IsInside(center.x, center.y) &&
                cells[center.x, center.y] == CellKind.RadboltCollector &&
                milestoneRadiationResearch &&
                CanPoweredMachineRun(center) &&
                RadiationAt(center.x, center.y) >= RadboltCollectorMinimumRadiation;
        }

