        private void RunSolarPanel(Vector2Int center, float deltaTime)
        {
            float irradiance = SolarIrradiance();
            if (irradiance <= 0.001f)
            {
                return;
            }

            if (!IsSolarPanelSkyExposed(center))
            {
                solarBlockedSeconds += deltaTime;
                return;
            }

            if (!CanSolarPanelRun(center))
            {
                return;
            }

            InstallSolarGlassLens(deltaTime);
            float generated = Mathf.Min(SolarPanelPowerRate * GeneratorTuneMultiplier(center) * SolarGlassMultiplier() * deltaTime * irradiance, Mathf.Max(0f, maxPower - power));
            if (generated <= 0.001f)
            {
                return;
            }

            generated = AddGeneratedPower(generated);
            solarPowerGenerated += generated;
            AddHeat(center, 0.018f * deltaTime * irradiance, 1);
            WearEquipment(center, 0.00018f * deltaTime * irradiance);
            terrainDirty = true;
            overlayDirty = true;
        }

        private float SolarGlassInstalledCapacity()
        {
            return Mathf.Max(0f, CountSolarLensTargetPanels() * SolarGlassCostPerPanel);
        }

        private float SolarGlassCoverage()
        {
            float capacity = SolarGlassInstalledCapacity();
            return capacity <= 0.001f ? 0f : Mathf.Clamp01(solarGlassInstalled / capacity);
        }

        private float SolarGlassMultiplier()
        {
            return 1f + SolarGlassPowerBoost * SolarGlassCoverage();
        }

        private void InstallSolarGlassLens(float deltaTime)
        {
            if (deltaTime <= 0f || glass <= 0.001f)
            {
                return;
            }

            float capacity = SolarGlassInstalledCapacity();
            if (capacity <= 0.001f)
            {
                solarGlassInstalled = 0f;
                return;
            }

            solarGlassInstalled = Mathf.Min(solarGlassInstalled, capacity);
            float remaining = capacity - solarGlassInstalled;
            if (remaining <= 0.001f)
            {
                return;
            }

            float installed = Mathf.Min(glass, Mathf.Min(remaining, SolarGlassInstallRate * deltaTime));
            glass = Mathf.Max(0f, glass - installed);
            solarGlassInstalled += installed;
        }

        private bool CanSolarPanelRun(Vector2Int center)
        {
            if (!CanUseEquipment(center) || !HasWireAccess(center) || power >= maxPower - 1f || SolarIrradiance() <= 0.01f || !IsSolarPanelSkyExposed(center))
            {
                return false;
            }

            if (HasAutomationControl(center))
            {
                return HasAutomationSignal(center);
            }

            return true;
        }

        private float SolarIrradiance()
        {
            float normalized = Mathf.Repeat(cycleTimer / CycleLengthSeconds, 1f);
            if (normalized <= SolarDayStart || normalized >= SolarDayEnd)
            {
                return 0f;
            }

            float dayProgress = Mathf.InverseLerp(SolarDayStart, SolarDayEnd, normalized);
            return Mathf.Clamp01(Mathf.Sin(dayProgress * Mathf.PI));
        }

        private bool IsSolarPanelSkyExposed(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            for (int y = cell.y + 1; y < WorldHeight; y++)
            {
                if (IsSolarBlockingCell(cell.x, y))
                {
                    return false;
                }
            }

            return true;
        }

        private bool IsSolarBlockingCell(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            if (cells[x, y] == CellKind.BunkerDoor && !IsBunkerDoorClosed(new Vector2Int(x, y)))
            {
                return waterMass[x, y] > 0.5f;
            }

            return cells[x, y] != CellKind.Empty || waterMass[x, y] > 0.5f;
        }

        private int CountSkyExposedSolarPanels()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.SolarPanel && IsSolarPanelSkyExposed(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool CanSolarPanelReceiveLens(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.SolarPanel &&
                CanUseEquipment(cell) &&
                IsSolarPanelSkyExposed(cell);
        }

        private int CountSolarLensTargetPanels()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanSolarPanelReceiveLens(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountPowerReadySolarPanels()
        {
            UpdateAutomationWires();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (CanSolarPanelReceiveLens(cell) && HasWireAccess(cell) && MachineAutomationAllows(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void SimulateMeteorShowers(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            if (meteorShowerSeconds > 0f)
            {
                meteorStrikeTimer -= deltaTime;
                while (meteorStrikeTimer <= 0f && meteorShowerSeconds > 0f)
                {
                    TriggerMeteorWave();
                    meteorStrikeTimer += MeteorStrikeIntervalSeconds;
                }

                meteorShowerSeconds = Mathf.Max(0f, meteorShowerSeconds - deltaTime);
                terrainDirty = true;
                overlayDirty = true;
                if (meteorShowerSeconds <= 0f)
                {
                    meteorCooldownSeconds = MeteorCooldownSeconds;
                    Log("Meteor shower passed. Clear regolith and repair exposed equipment.");
                }

                return;
            }

            meteorCooldownSeconds = Mathf.Max(0f, meteorCooldownSeconds - deltaTime);
            AdvanceAutomatedMeteorDefense(deltaTime);
            if (meteorCooldownSeconds <= 0f)
            {
                StartMeteorShower();
            }
        }

        private void AdvanceAutomatedMeteorDefense(float deltaTime)
        {
            if (deltaTime <= 0f ||
                IsMeteorShowerActive() ||
                !AnySpaceScannerSignalActive() ||
                CountAutomationClosedBunkerDoors() == 0)
            {
                return;
            }

            automatedMeteorDefenseSeconds += deltaTime;
        }

        private void StartMeteorShower()
        {
            meteorShowerSeconds = MeteorShowerDurationSeconds;
            meteorStrikeTimer = 0f;
            terrainDirty = true;
            overlayDirty = true;
            Log("Meteor shower incoming. Bunker Doors will close and exposed surface equipment may take damage.");
        }

        private void TriggerMeteorWave()
        {
            int seed = Mathf.Abs(cycle * 97 + Mathf.RoundToInt(cycleTimer * 31f) + meteorStrikes * 43);
            for (int i = 0; i < MeteorStrikesPerWave; i++)
            {
                int column = (seed + i * 29 + meteorStrikes * 7) % WorldWidth;
                ImpactMeteorColumn(column);
            }
        }

        private void ImpactMeteorColumn(int x)
        {
            meteorStrikes++;
            for (int y = WorldHeight - 1; y >= 0; y--)
            {
                if (!IsMeteorBlockingCell(x, y))
                {
                    continue;
                }

                Vector2Int impact = new Vector2Int(x, y);
                CellKind hitKind = cells[x, y];
                if (hitKind == CellKind.BunkerDoor && !IsBrokenEquipment(impact))
                {
                    meteorImpactsBlocked++;
                    bool steelReinforced = TryApplySteelBunkerReinforcement(out float steelUsed);
                    float damageScale = steelReinforced ? 1f - SteelMeteorDamageReduction : 1f;
                    DamageEquipment(impact, MeteorBunkerDoorDamage * damageScale);
                    AddHeat(impact, MeteorBunkerImpactHeat * Mathf.Lerp(1f, 0.45f, steelReinforced ? 1f : 0f), 1);
                    DepositRegolithAboveImpact(impact);
                    if (steelReinforced && steelUsedForBunkerRepairs <= steelUsed + 0.001f)
                    {
                        Log("Steel bunker reinforcement absorbed a meteor impact.");
                    }

                    if (IsBrokenEquipment(impact))
                    {
                        Log("A Bunker Door was breached by meteor impacts.");
                    }

                    terrainDirty = true;
                    overlayDirty = true;
                    return;
                }

                if (IsRepairableEquipment(hitKind))
                {
                    meteorDamageEvents++;
                    DamageEquipment(impact, MeteorEquipmentDamage);
                    AddHeat(impact, MeteorImpactHeat, 1);
                    DepositRegolithAboveImpact(impact);
                    Log("Meteor damaged " + CellLabel(hitKind) + " at " + x + ", " + y + ".");
                    terrainDirty = true;
                    overlayDirty = true;
                    return;
                }

                if (IsWorldLiquidCell(hitKind))
                {
                    bool pollutedLiquid = IsPollutedWorldLiquidAt(x, y);
                    waterMass[x, y] = Mathf.Max(0f, waterMass[x, y] - 10f);
                    steam[x, y] += 0.18f;
                    if (pollutedLiquid)
                    {
                        pollutedOxygen[x, y] = Mathf.Min(2.2f, pollutedOxygen[x, y] + 0.05f);
                        germs[x, y] = Mathf.Clamp01(germs[x, y] + 0.04f);
                    }

                    AddHeat(impact, MeteorImpactHeat, 1);
                    DepositRegolithAboveImpact(impact);
                    gasDirty = true;
                    terrainDirty = true;
                    overlayDirty = true;
                    return;
                }

                AddHeat(impact, MeteorImpactHeat * 0.55f, 1);
                DepositRegolithAboveImpact(impact);
                terrainDirty = true;
                overlayDirty = true;
                return;
            }
        }

        private bool TryApplySteelBunkerReinforcement(out float steelUsed)
        {
            steelUsed = 0f;
            if (steel < SteelBunkerRepairCost)
            {
                return false;
            }

            steelUsed = SteelBunkerRepairCost;
            steel = Mathf.Max(0f, steel - steelUsed);
            steelUsedForBunkerRepairs += steelUsed;
            return true;
        }

        private bool IsMeteorBlockingCell(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            if (cells[x, y] == CellKind.Empty && waterMass[x, y] <= 0.5f)
            {
                return false;
            }

            return cells[x, y] != CellKind.BunkerDoor || IsBunkerDoorClosed(new Vector2Int(x, y));
        }

        private void DepositRegolithAboveImpact(Vector2Int impact)
        {
            if (TryPlaceMeteorRegolith(impact.x, impact.y + 1))
            {
                return;
            }

            TryPlaceMeteorRegolith(impact.x + 1, impact.y + 1);
            TryPlaceMeteorRegolith(impact.x - 1, impact.y + 1);
        }

        private bool TryPlaceMeteorRegolith(int x, int y)
        {
            if (!CanPlaceMeteorRegolith(x, y))
            {
                return false;
            }

            Vector2Int cell = new Vector2Int(x, y);
            Worker worker = WorkerAt(cell);
            if (worker != null && worker.Health > 0f)
            {
                float damage = worker.LeadSuitEquipped ? 14f * LeadSuitMeteorDamageMultiplier : worker.SuitEquipped ? 7f : 14f;
                worker.Health = Mathf.Max(0f, worker.Health - damage);
                worker.Stress = Mathf.Min(100f, worker.Stress + 16f);
                ClearAssignment(worker);
                if (TryFindOpenSpawnNear(cell, out Vector2Int safeCell))
                {
                    worker.Cell = safeCell;
                    if (worker.Transform != null)
                    {
                        worker.Transform.position = CellCenter(safeCell);
                    }
                }

                worker.Activity = "Dodging Meteor Debris";
                Log(worker.Name + " was struck by meteor debris.");
            }

            cells[x, y] = CellKind.Regolith;
            equipmentCondition[x, y] = 0f;
            waterMass[x, y] = 0f;
            oxygen[x, y] = 0f;
            carbonDioxide[x, y] = 0f;
            pollutedOxygen[x, y] = 0f;
            hydrogen[x, y] = 0f;
            chlorine[x, y] = 0f;
            naturalGas[x, y] = 0f;
            steam[x, y] = 0f;
            sourGas[x, y] = 0f;
            germs[x, y] = 0f;
            temperature[x, y] = Mathf.Max(temperature[x, y], MeteorRegolithTemperature);
            meteorRegolithDeposited += 6f;
            CancelJobsAt(cell, false);
            InvalidateRooms();
            gasDirty = true;
            terrainDirty = true;
            overlayDirty = true;
            return true;
        }

        private bool CanPlaceMeteorRegolith(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.Empty &&
                waterMass[x, y] <= 0.05f &&
                !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                (looseResourceKind[x, y] == LooseResourceKind.None || looseResourceAmount[x, y] <= 0.01f);
        }

        private bool IsMeteorShowerActive()
        {
            return meteorShowerSeconds > 0f;
        }

        private bool IsBunkerDoorClosed(Vector2Int cell)
        {
            if (!CanUseBunkerDoor(cell))
            {
                return false;
            }

            if (IsMeteorShowerActive())
            {
                return true;
            }

            UpdateAutomationWires();
            return HasCachedAutomationControl(cell) && HasCachedAutomationSignal(cell);
        }

        private bool CanUseBunkerDoor(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.BunkerDoor &&
                CanUseEquipment(cell);
        }

        private int CountIntactBunkerDoors()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseBunkerDoor(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountDamagedBunkerDoors()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.BunkerDoor && NeedsRepair(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountAutomationClosedBunkerDoors()
        {
            UpdateAutomationWires();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.BunkerDoor &&
                        CanUseBunkerDoor(cell) &&
                        HasCachedAutomationControl(cell) &&
                        HasCachedAutomationSignal(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void RunSpaceScanner(Vector2Int center, float deltaTime)
        {
            if (!IsSpaceScannerSkyExposed(center))
            {
                spaceScannerBlockedSeconds += deltaTime;
                return;
            }

            if (!CanSpaceScannerScan(center))
            {
                return;
            }

            if (SpaceScannerSignalActive(center.x, center.y))
            {
                spaceScannerSignalSeconds += deltaTime;
            }

            float powerUsed = Mathf.Min(power, SpaceScannerPowerRate * deltaTime);
            float efficiency = powerUsed / Mathf.Max(0.001f, SpaceScannerPowerRate * deltaTime);
            ConsumeCyclePower(powerUsed);
            AddHeat(center, 0.012f * deltaTime, 1);
            WearEquipment(center, 0.00015f * deltaTime * efficiency);
            overlayDirty = true;
        }

        private bool CanSpaceScannerScan(Vector2Int cell)
        {
            return techSpaceSystems &&
                IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.SpaceScanner &&
                CanUseEquipment(cell) &&
                HasPoweredCircuit(cell) &&
                IsSpaceScannerSkyExposed(cell);
        }

        private bool SpaceScannerSignalActive(int x, int y)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.SpaceScanner)
            {
                return false;
            }

            Vector2Int cell = new Vector2Int(x, y);
            if (!CanSpaceScannerScan(cell))
            {
                return false;
            }

            return IsMeteorShowerActive() || meteorCooldownSeconds <= SpaceScannerWarningSeconds;
        }

        private bool AnySpaceScannerSignalActive()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (SpaceScannerSignalActive(x, y))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool HasOperationalLinkedSpaceScanner()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (CanSpaceScannerScan(cell) && HasAutomationWireAccess(cell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool IsSpaceScannerSkyExposed(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            for (int y = cell.y + 1; y < WorldHeight; y++)
            {
                CellKind kind = cells[cell.x, y];
                if (kind != CellKind.Empty || waterMass[cell.x, y] > 0.5f)
                {
                    return false;
                }
            }

            return true;
        }

        private int CountSkyExposedSpaceScanners()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.SpaceScanner && IsSpaceScannerSkyExposed(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountOperationalSpaceScanners()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanSpaceScannerScan(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string SpaceScannerReadinessText(Vector2Int cell)
        {
            if (!techSpaceSystems)
            {
                return "Scan blocked: research Space Systems.";
            }

            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.SpaceScanner)
            {
                return "Scan blocked: Space Scanner missing.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Scan blocked: Space Scanner needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Scan blocked: Space Scanner is submerged.";
            }

            if (!IsSpaceScannerSkyExposed(cell))
            {
                return "Scan blocked: clear the sky above the scanner.";
            }

            if (!HasWireAccess(cell))
            {
                return "Scan blocked: needs adjacent or under-floor power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Scan blocked: power circuit has no stored power.";
            }

            if (!HasAutomationWireAccess(cell))
            {
                return "Scan ready: add Automation Wire to control Bunker Doors.";
            }

            return SpaceScannerSignalActive(cell.x, cell.y)
                ? "Scan ready: meteor warning signal is green."
                : "Scan ready: watching for the next meteor warning.";
        }

        private void RunRocketPlatform(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !techSpaceSystems)
            {
                return;
            }

            if (!IsRocketPlatformSkyExposed(center) || !CanPoweredMachineRun(center))
            {
                return;
            }

            float requestedPetroleum = RocketPlatformPetroleumRate * deltaTime;
            float requestedPlastic = RocketPlatformPlasticRate * deltaTime;
            float requestedPower = RocketPlatformPowerRate * deltaTime;
            bool loadCryogenicPropellant = milestoneSuperCoolantLoop && cryogenicPropellant > 0.001f;
            float requestedCryogenicPropellant = loadCryogenicPropellant ? CryogenicRocketPropellantRate * deltaTime : 0f;
            float efficiency = Mathf.Min(
                petroleum / Mathf.Max(0.001f, requestedPetroleum),
                plastic / Mathf.Max(0.001f, requestedPlastic),
                power / Mathf.Max(0.001f, requestedPower));
            if (loadCryogenicPropellant)
            {
                efficiency = Mathf.Min(efficiency, cryogenicPropellant / Mathf.Max(0.001f, requestedCryogenicPropellant));
            }

            efficiency = Mathf.Clamp01(efficiency);
            if (efficiency <= 0.001f)
            {
                return;
            }

            float petroleumUsed = requestedPetroleum * efficiency;
            float plasticUsed = requestedPlastic * efficiency;
            float powerUsed = requestedPower * efficiency;
            float cryogenicPropellantUsedThisTick = requestedCryogenicPropellant * efficiency;
            petroleum = Mathf.Max(0f, petroleum - petroleumUsed);
            plastic = Mathf.Max(0f, plastic - plasticUsed);
            if (cryogenicPropellantUsedThisTick > 0.001f)
            {
                cryogenicPropellant = Mathf.Max(0f, cryogenicPropellant - cryogenicPropellantUsedThisTick);
                rocketCryoPropellantLoaded = Mathf.Clamp(rocketCryoPropellantLoaded + cryogenicPropellantUsedThisTick, 0f, CryogenicRocketPropellantTarget);
                cryogenicPropellantUsed += cryogenicPropellantUsedThisTick;
            }

            rocketPetroleumConsumed += petroleumUsed;
            rocketPlasticConsumed += plasticUsed;
            ConsumeCyclePower(powerUsed);
            rocketMissionProgress += deltaTime * efficiency;
            AddHeat(center, RocketPlatformHeatRate * deltaTime * efficiency, 1);
            AddGasToTile(center.x, center.y, 0f, 0.035f * deltaTime * efficiency, 0f, 0f, 0f, 0f, 0f);
            WearEquipment(center, 0.00044f * deltaTime * efficiency);
            gasDirty = true;
            overlayDirty = true;

            while (rocketMissionProgress >= RocketMissionPrepSeconds)
            {
                rocketMissionProgress -= RocketMissionPrepSeconds;
                CompleteRocketMission(center);
            }
        }

        private void CompleteRocketMission(Vector2Int center)
        {
            bool cryogenicMission = milestoneSuperCoolantLoop && rocketCryoPropellantLoaded >= CryogenicRocketPropellantTarget - 0.001f;
            rocketMissionsLaunched++;
            if (cryogenicMission)
            {
                cryogenicRocketMissionsLaunched++;
            }

            float scannerBonus = CountSkyExposedSpaceScanners() > 0 ? 1.18f : 1f;
            float missionBonus = cryogenicMission ? CryogenicRocketMissionRewardMultiplier : 1f;
            float researchReward = RocketMissionResearchReward * scannerBonus * missionBonus;
            float refinedMetalReward = RocketMissionRefinedMetalReward * scannerBonus * missionBonus;
            float dataReward = RocketMissionDataReward * scannerBonus * missionBonus;
            float artifactReward = RocketMissionArtifactReward * scannerBonus * missionBonus;
            float niobiumReward = milestoneDeepSpaceSurvey ? NiobiumRocketYield * scannerBonus : 0f;
            float fullereneReward = milestoneThermiumMachinery ? FullereneRocketYield * scannerBonus : 0f;
            if (cryogenicMission)
            {
                niobiumReward *= missionBonus;
                fullereneReward *= missionBonus;
                temporalTearFragmentsRecovered += TemporalTearFragmentReward * scannerBonus;
            }

            rocketCryoPropellantLoaded = 0f;
            researchPoints += researchReward;
            currentCycleReport.ResearchPoints += researchReward;
            rocketResearchRecovered += researchReward;
            orbitalData += dataReward;
            orbitalArtifactsRecovered += artifactReward;
            refinedMetal += refinedMetalReward;
            if (niobiumReward > 0.001f)
            {
                niobium += niobiumReward;
                niobiumRecovered += niobiumReward;
            }

            if (fullereneReward > 0.001f)
            {
                fullerene += fullereneReward;
                fullereneRecovered += fullereneReward;
            }

            AddHeat(center, 3.2f, 2);
            ApplyResearchUnlocks(true);
            terrainDirty = true;
            overlayDirty = true;
            if (cryogenicMission && niobiumReward > 0.001f && fullereneReward > 0.001f)
            {
                Log("Cryogenic rocket mission returned long-range data, artifact fragments, temporal coordinates, refined metal, niobium, and fullerene.");
            }
            else if (cryogenicMission)
            {
                Log("Cryogenic rocket mission returned long-range data, artifact fragments, temporal coordinates, and refined metal.");
            }
            else if (niobiumReward > 0.001f && fullereneReward > 0.001f)
            {
                Log("Rocket mission returned orbital data, artifact fragments, refined metal, niobium, and fullerene.");
            }
            else if (niobiumReward > 0.001f)
            {
                Log("Rocket mission returned orbital data, artifact fragments, refined metal, and niobium.");
            }
            else if (fullereneReward > 0.001f)
            {
                Log("Rocket mission returned orbital data, artifact fragments, refined metal, and fullerene.");
            }
            else
            {
                Log("Rocket mission returned orbital data, artifact fragments, and refined metal.");
            }
        }

        private float PendingOrbitalArtifacts()
        {
            return Mathf.Max(0f, orbitalArtifactsRecovered - orbitalArtifactsAnalyzed);
        }

        private float PendingRadiationSamples()
        {
            return Mathf.Max(0f, radiationSamples - radiationSamplesAnalyzed);
        }

        private float PendingTemporalTearFragments()
        {
            return Mathf.Max(0f, temporalTearFragmentsRecovered - temporalTearFragmentsAnalyzed);
        }

        private bool TemporalTearRouteCharted()
        {
            return temporalTearDataAnalyzed >= TemporalTearDataTarget - 0.001f &&
                temporalTearFragmentsAnalyzed >= TemporalTearFragmentTarget - 0.001f;
        }

        private bool CanTemporalTearSignalRun()
        {
            return milestoneCryogenicRocketProgram &&
                cryogenicRocketMissionsLaunched >= TemporalTearCryogenicMissionTarget &&
                TemporalTearRouteCharted() &&
                CountOperationalSpaceScanners() > 0 &&
                superCoolant >= TemporalTearSignalSuperCoolantReserve;
        }

        private float AnalyzeTemporalTearRoute(float dataUsed, float deltaTime, float efficiency)
        {
            if (!milestoneCryogenicRocketProgram || dataUsed <= 0.001f || deltaTime <= 0f || efficiency <= 0.001f)
            {
                return 0f;
            }

            if (temporalTearDataAnalyzed < TemporalTearDataTarget)
            {
                float dataProgress = Mathf.Min(dataUsed, TemporalTearDataTarget - temporalTearDataAnalyzed);
                temporalTearDataAnalyzed += dataProgress;
            }

            float pendingFragments = PendingTemporalTearFragments();
            if (pendingFragments <= 0.001f || temporalTearFragmentsAnalyzed >= TemporalTearFragmentTarget)
            {
                return 0f;
            }

            float requestedFragments = TemporalTearFragmentAnalysisRate * deltaTime * efficiency;
            float dataLimitedFragments = dataUsed / Mathf.Max(0.001f, TemporalTearDataCostPerFragment);
            float fragmentProgress = Mathf.Min(
                pendingFragments,
                TemporalTearFragmentTarget - temporalTearFragmentsAnalyzed,
                requestedFragments,
                dataLimitedFragments);
            if (fragmentProgress <= 0.001f)
            {
                return 0f;
            }

            temporalTearFragmentsAnalyzed += fragmentProgress;
            return fragmentProgress * TemporalTearFragmentResearchYield;
        }

        private void RunTemporalTearSignal(Vector2Int center, float deltaTime)
        {
            if (!CanTemporalTearSignalRun() || temporalTearSignalSeconds >= TemporalTearSignalTargetSeconds || deltaTime <= 0f)
            {
                return;
            }

            float requestedPower = TemporalTearSignalPowerRate * deltaTime;
            float efficiency = Mathf.Clamp01(power / Mathf.Max(0.001f, requestedPower));
            if (efficiency <= 0.001f)
            {
                return;
            }

            temporalTearSignalSeconds = Mathf.Min(TemporalTearSignalTargetSeconds, temporalTearSignalSeconds + deltaTime * efficiency);
            ConsumeCyclePower(requestedPower * efficiency);
            AddHeat(center, OrbitalDataBankHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00020f * deltaTime * efficiency);
            overlayDirty = true;
        }

        private float OrbitalArtifactDecorScore()
        {
            return Mathf.Clamp(orbitalArtifactsAnalyzed * OrbitalArtifactDecorBonus, 0f, OrbitalArtifactDecorMaxBonus);
        }

        private void RunOrbitalDataBank(Vector2Int center, float deltaTime)
        {
            if (deltaTime <= 0f || !techSpaceSystems || !CanPoweredMachineRun(center))
            {
                return;
            }

            bool hasOrbitalData = orbitalData > 0.001f;
            bool hasRadiationSamples = PendingRadiationSamples() > 0.001f;
            bool canStabilizeTemporalSignal = CanTemporalTearSignalRun() && temporalTearSignalSeconds < TemporalTearSignalTargetSeconds;
            if (!hasOrbitalData && !hasRadiationSamples && !canStabilizeTemporalSignal)
            {
                return;
            }

            if (!hasOrbitalData && canStabilizeTemporalSignal)
            {
                RunTemporalTearSignal(center, deltaTime);
                return;
            }

            if (!hasOrbitalData && hasRadiationSamples)
            {
                float requestedSamples = RadiationSampleAnalysisRate * deltaTime;
                float requestedSamplePower = RadiationSampleAnalysisPowerRate * deltaTime;
                float sampleEfficiency = Mathf.Min(
                    PendingRadiationSamples() / Mathf.Max(0.001f, requestedSamples),
                    power / Mathf.Max(0.001f, requestedSamplePower));
                sampleEfficiency = Mathf.Clamp01(sampleEfficiency);
                if (sampleEfficiency <= 0.001f)
                {
                    return;
                }

                float sampleUsed = requestedSamples * sampleEfficiency;
                float samplePowerUsed = requestedSamplePower * sampleEfficiency;
                radiationSamplesAnalyzed = Mathf.Min(radiationSamples, radiationSamplesAnalyzed + sampleUsed);
                float sampleResearchGenerated = sampleUsed * RadiationSampleResearchYield;
                researchPoints += sampleResearchGenerated;
                currentCycleReport.ResearchPoints += sampleResearchGenerated;
                ConsumeCyclePower(samplePowerUsed);
                AddHeat(center, OrbitalDataBankHeatRate * deltaTime * sampleEfficiency, 1);
                WearEquipment(center, 0.00024f * deltaTime * sampleEfficiency);
                ApplyResearchUnlocks(true);
                overlayDirty = true;
                return;
            }

            float requestedData = OrbitalDataBankDataRate * deltaTime;
            float requestedPower = OrbitalDataBankPowerRate * deltaTime;
            float efficiency = Mathf.Min(
                orbitalData / Mathf.Max(0.001f, requestedData),
                power / Mathf.Max(0.001f, requestedPower));
            efficiency = Mathf.Clamp01(efficiency);
            if (efficiency <= 0.001f)
            {
                return;
            }

            float dataUsed = requestedData * efficiency;
            float powerUsed = requestedPower * efficiency;
            float researchGenerated = dataUsed * OrbitalDataBankResearchYield;
            float artifactProgress = Mathf.Min(PendingOrbitalArtifacts(), dataUsed / OrbitalArtifactDataCost);
            if (artifactProgress > 0.001f)
            {
                orbitalArtifactsAnalyzed = Mathf.Min(orbitalArtifactsRecovered, orbitalArtifactsAnalyzed + artifactProgress);
                researchGenerated += artifactProgress * OrbitalArtifactResearchYield;
            }

            researchGenerated += AnalyzeTemporalTearRoute(dataUsed, deltaTime, efficiency);
            if (CanTemporalTearSignalRun())
            {
                temporalTearSignalSeconds = Mathf.Min(TemporalTearSignalTargetSeconds, temporalTearSignalSeconds + deltaTime * efficiency);
            }

            orbitalData = Mathf.Max(0f, orbitalData - dataUsed);
            orbitalDataAnalyzed += dataUsed;
            researchPoints += researchGenerated;
            currentCycleReport.ResearchPoints += researchGenerated;
            ConsumeCyclePower(powerUsed);
            AddHeat(center, OrbitalDataBankHeatRate * deltaTime * efficiency, 1);
            WearEquipment(center, 0.00028f * deltaTime * efficiency);
            ApplyResearchUnlocks(true);
            overlayDirty = true;
        }

        private bool CanOrbitalDataBankRun(Vector2Int center)
        {
            return techSpaceSystems &&
                CanPoweredMachineRun(center) &&
                (orbitalData > 0.001f ||
                    PendingRadiationSamples() > 0.001f ||
                    (CanTemporalTearSignalRun() && temporalTearSignalSeconds < TemporalTearSignalTargetSeconds));
        }

        private bool CanRocketPlatformRun(Vector2Int center)
        {
            return CanRocketPlatformPrepare(center) &&
                petroleum >= 0.01f &&
                plastic >= 0.01f;
        }

        private bool CanRocketPlatformPrepare(Vector2Int center)
        {
            return techSpaceSystems &&
                IsInside(center.x, center.y) &&
                cells[center.x, center.y] == CellKind.RocketPlatform &&
                IsRocketPlatformSkyExposed(center) &&
                CanUseEquipment(center) &&
                HasPoweredCircuit(center) &&
                MachineAutomationAllows(center);
        }

        private int CountOperationalRocketPlatforms()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanRocketPlatformPrepare(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string RocketPlatformReadinessText(Vector2Int cell)
        {
            if (!techSpaceSystems)
            {
                return "Launch blocked: research Space Systems.";
            }

            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.RocketPlatform)
            {
                return "Launch blocked: Rocket Platform missing.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Launch blocked: Rocket Platform needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Launch blocked: Rocket Platform is submerged.";
            }

            UpdateAutomationWires();
            if (!IsRocketPlatformSkyExposed(cell))
            {
                return "Launch blocked: clear vertical sky above the Rocket Platform.";
            }

            if (!HasWireAccess(cell))
            {
                return "Launch blocked: needs adjacent or under-floor power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Launch blocked: power circuit has no stored power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Launch blocked: automation signal is red.";
            }

            if (petroleum <= 0.01f)
            {
                return "Launch blocked: refine crude oil into petroleum.";
            }

            if (plastic <= 0.01f)
            {
                return "Launch blocked: press petroleum into plastic.";
            }

            if (milestoneSuperCoolantLoop)
            {
                if (rocketCryoPropellantLoaded >= CryogenicRocketPropellantTarget - 0.001f)
                {
                    return "Launch ready: next mission will be cryogenic long-range.";
                }

                return cryogenicPropellant > 0.001f
                    ? "Launch prep ready: loading cryogenic propellant for long-range mission."
                    : "Launch prep ready: no cryogenic propellant, regular orbital mission will continue.";
            }

            return "Launch prep ready: regular orbital mission can advance.";
        }

        private string OrbitalDataBankReadinessText(Vector2Int cell)
        {
            if (!techSpaceSystems)
            {
                return "Analysis blocked: research Space Systems.";
            }

            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.OrbitalDataBank)
            {
                return "Analysis blocked: Orbital Data Bank missing.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Analysis blocked: Orbital Data Bank needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Analysis blocked: Orbital Data Bank is submerged.";
            }

            UpdateAutomationWires();
            if (!HasWireAccess(cell))
            {
                return "Analysis blocked: needs adjacent or under-floor power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Analysis blocked: power circuit has no stored power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Analysis blocked: automation signal is red.";
            }

            if (orbitalData > 0.001f)
            {
                if (milestoneCryogenicRocketProgram && PendingTemporalTearFragments() > 0.001f && !TemporalTearRouteCharted())
                {
                    return "Analysis ready: charting temporal route from mission data.";
                }

                return PendingOrbitalArtifacts() > 0.001f
                    ? "Analysis ready: mission data and artifact fragments."
                    : "Analysis ready: mission data.";
            }

            if (PendingRadiationSamples() > 0.001f)
            {
                return "Analysis ready: radiation samples.";
            }

            if (CanTemporalTearSignalRun() && temporalTearSignalSeconds < TemporalTearSignalTargetSeconds)
            {
                return "Signal ready: stabilizing temporal tear.";
            }

            if (milestoneCryogenicRocketProgram && !milestoneTemporalTearSignal)
            {
                return TemporalTearReadinessText();
            }

            if (PendingOrbitalArtifacts() > 0.001f)
            {
                return "Analysis blocked: recovered artifacts need fresh orbital data.";
            }

            return "Analysis idle: launch a Rocket Platform mission for orbital data.";
        }

        private string TemporalTearReadinessText()
        {
            if (cryogenicRocketMissionsLaunched < TemporalTearCryogenicMissionTarget)
            {
                return "Temporal route blocked: launch more cryogenic long-range missions.";
            }

            if (!TemporalTearRouteCharted())
            {
                if (PendingTemporalTearFragments() <= 0.001f)
                {
                    return "Temporal route blocked: recover coordinate fragments with cryogenic missions.";
                }

                return orbitalData > 0.001f
                    ? "Temporal route ready for data-bank analysis."
                    : "Temporal route blocked: launch another cryogenic mission for long-range data.";
            }

            if (CountSkyExposedSpaceScanners() == 0)
            {
                return "Temporal signal blocked: needs open-sky Space Scanner.";
            }

            if (CountOperationalSpaceScanners() == 0)
            {
                return "Temporal signal blocked: repair, enable, and power the Space Scanner.";
            }

            if (superCoolant < TemporalTearSignalSuperCoolantReserve)
            {
                return "Temporal signal blocked: reserve super coolant.";
            }

            return temporalTearSignalSeconds >= TemporalTearSignalTargetSeconds
                ? "Temporal signal stabilized."
                : "Temporal signal ready: keep this data bank powered.";
        }

        private bool IsRocketPlatformSkyExposed(Vector2Int cell)
        {
            return IsSpaceScannerSkyExposed(cell);
        }

        private int CountSkyExposedRocketPlatforms()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.RocketPlatform && IsRocketPlatformSkyExposed(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private float HotSteamAvailable(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y) && temperature[x, y] >= SteamTurbineMinimumTemperature)
                    {
                        total += steam[x, y];
                    }
                }
            }

            return total;
        }

        private float RemoveHotSteam(Vector2Int center, float capacity, int radius)
        {
            float removed = 0f;
            for (int dy = radius; dy >= -radius && removed < capacity; dy--)
            {
                for (int dx = -radius; dx <= radius && removed < capacity; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y) || temperature[x, y] < SteamTurbineMinimumTemperature)
                    {
                        continue;
                    }

                    float amount = Mathf.Min(steam[x, y], capacity - removed);
                    if (amount <= 0.001f)
                    {
                        continue;
                    }

                    steam[x, y] = Mathf.Max(0f, steam[x, y] - amount);
                    temperature[x, y] = Mathf.Clamp(temperature[x, y] - amount * 8f, -30f, 120f);
                    removed += amount;
                }
            }

            return removed;
        }

        private float NaturalGasFuelAvailable(Vector2Int center)
        {
            return PipedNaturalGasAround(center) + NaturalGasAround(center, 3);
        }

        private float HydrogenFuelAvailable(Vector2Int center)
        {
            return PipedHydrogenAround(center) + HydrogenAround(center, 3);
        }

        private float PetroleumFuelAvailable(Vector2Int center)
        {
            return PipedPetroleumAround(center) + petroleum;
        }

        private float PipedNaturalGasAround(Vector2Int center)
        {
            float total = 0f;
            Vector2Int[] candidates =
            {
                center,
                new Vector2Int(center.x + 1, center.y),
                new Vector2Int(center.x - 1, center.y),
                new Vector2Int(center.x, center.y + 1),
                new Vector2Int(center.x, center.y - 1)
            };

            foreach (Vector2Int candidate in candidates)
            {
                if (IsInside(candidate.x, candidate.y) && gasPipe[candidate.x, candidate.y])
                {
                    total += Mathf.Max(0f, gasPipeNaturalGas[candidate.x, candidate.y]);
                }
            }

            return total;
        }

