                }
            }

            return total;
        }

        private float RemoveNaturalGasFuel(Vector2Int center, float capacity)
        {
            float removed = RemovePipedNaturalGas(center, capacity);
            if (removed < capacity)
            {
                removed += RemoveNaturalGas(center, capacity - removed, 3);
            }

            return removed;
        }

        private float RemoveHydrogenFuel(Vector2Int center, float capacity)
        {
            float removed = RemovePipedHydrogen(center, capacity);
            if (removed < capacity)
            {
                removed += RemoveHydrogen(center, capacity - removed, 3);
            }

            return removed;
        }

        private float RemovePetroleumFuel(Vector2Int center, float capacity)
        {
            float removed = RemovePipedPetroleum(center, capacity);
            if (removed < capacity)
            {
                float stored = Mathf.Min(petroleum, capacity - removed);
                petroleum = Mathf.Max(0f, petroleum - stored);
                removed += stored;
            }

            return removed;
        }

        private float RemovePipedNaturalGas(Vector2Int center, float capacity)
        {
            float removed = 0f;
            for (int i = 0; i < 5 && removed < capacity; i++)
            {
                Vector2Int pipe;
                if (!TryFindAdjacentGasPipeWithNaturalGas(center, out pipe))
                {
                    break;
                }

                float amount = Mathf.Min(gasPipeNaturalGas[pipe.x, pipe.y], capacity - removed);
                if (amount <= 0.001f)
                {
                    break;
                }

                gasPipeNaturalGas[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeNaturalGas[pipe.x, pipe.y] - amount);
                removed += amount;
            }

            return removed;
        }

        private float RemovePipedOxygen(Vector2Int center, float capacity)
        {
            float removed = 0f;
            for (int i = 0; i < 5 && removed < capacity; i++)
            {
                if (!TryFindAdjacentGasPipeWithFilterGas(center, GasFilterMode.Oxygen, out Vector2Int pipe))
                {
                    break;
                }

                float amount = Mathf.Min(gasPipeOxygen[pipe.x, pipe.y], capacity - removed);
                if (amount <= 0.001f)
                {
                    break;
                }

                RemoveFilteredGasFromPipe(pipe.x, pipe.y, GasFilterMode.Oxygen, amount);
                removed += amount;
            }

            return removed;
        }

        private float RemovePipedHydrogen(Vector2Int center, float capacity)
        {
            float removed = 0f;
            for (int i = 0; i < 5 && removed < capacity; i++)
            {
                if (!TryFindAdjacentGasPipeWithHydrogen(center, out Vector2Int pipe))
                {
                    break;
                }

                float amount = Mathf.Min(gasPipeHydrogen[pipe.x, pipe.y], capacity - removed);
                if (amount <= 0.001f)
                {
                    break;
                }

                gasPipeHydrogen[pipe.x, pipe.y] = Mathf.Max(0f, gasPipeHydrogen[pipe.x, pipe.y] - amount);
                removed += amount;
            }

            return removed;
        }

        private float RemovePipedPetroleum(Vector2Int center, float capacity)
        {
            float removed = 0f;
            for (int i = 0; i < 5 && removed < capacity; i++)
            {
                if (!TryFindAdjacentLiquidPipeWithPetroleum(center, out Vector2Int pipe))
                {
                    break;
                }

                float amount = Mathf.Min(pipePetroleum[pipe.x, pipe.y], capacity - removed);
                if (amount <= 0.001f)
                {
                    break;
                }

                pipePetroleum[pipe.x, pipe.y] = Mathf.Max(0f, pipePetroleum[pipe.x, pipe.y] - amount);
                removed += amount;
            }

            return removed;
        }

        private bool CanCoalGeneratorRun(Vector2Int center)
        {
            if (!CanUseEquipment(center) || coal <= 0.001f || !HasWireAccess(center) || power >= maxPower - 1f)
            {
                return false;
            }

            if (HasAutomationControl(center))
            {
                return HasAutomationSignal(center);
            }

            return power <= maxPower * 0.72f;
        }

        private float HydrogenAround(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        total += hydrogen[x, y];
                    }
                }
            }

            return total;
        }

        private float NaturalGasAround(Vector2Int center, int radius)
        {
            float total = 0f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        total += naturalGas[x, y];
                    }
                }
            }

            return total;
        }

        private float RemoveHydrogen(Vector2Int center, float capacity, int radius)
        {
            float removed = 0f;
            for (int dy = radius; dy >= -radius && removed < capacity; dy--)
            {
                for (int dx = -radius; dx <= radius && removed < capacity; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float amount = Mathf.Min(hydrogen[x, y], capacity - removed);
                    hydrogen[x, y] -= amount;
                    removed += amount;
                }
            }

            return removed;
        }

        private float RemoveNaturalGas(Vector2Int center, float capacity, int radius)
        {
            float removed = 0f;
            for (int dy = radius; dy >= -radius && removed < capacity; dy--)
            {
                for (int dx = -radius; dx <= radius && removed < capacity; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float amount = Mathf.Min(naturalGas[x, y], capacity - removed);
                    naturalGas[x, y] -= amount;
                    removed += amount;
                }
            }

            return removed;
        }

        private void RunAtmoSuitDock(Vector2Int center, float deltaTime)
        {
            float capacity = SuitOxygenCapacityTotal();
            if (capacity <= 0f || suitOxygen >= capacity - 0.01f || !CanPoweredMachineRun(center))
            {
                return;
            }

            if (!TryFindSuitDockOxygenSource(center, out Vector2Int source))
            {
                return;
            }

            float powerUsed = Mathf.Min(power, SuitDockPowerRate * deltaTime);
            float powerEfficiency = powerUsed / Mathf.Max(0.001f, SuitDockPowerRate * deltaTime);
            float amount = Mathf.Min(
                oxygen[source.x, source.y],
                Mathf.Min(SuitDockChargeRate * deltaTime * powerEfficiency, capacity - suitOxygen));
            if (amount <= 0.001f)
            {
                return;
            }

            ConsumeCyclePower(powerUsed);
            oxygen[source.x, source.y] = Mathf.Max(0f, oxygen[source.x, source.y] - amount);
            suitOxygen = Mathf.Min(capacity, suitOxygen + amount);
            AddHeat(center, 0.025f * deltaTime * powerEfficiency, 1);
            WearEquipment(center, 0.00022f * deltaTime * powerEfficiency);
            gasDirty = true;
            overlayDirty = true;
        }

        private void RunOxygenMaskDock(Vector2Int center, float deltaTime)
        {
            float capacity = OxygenMaskCapacityTotal();
            if (capacity <= 0f || maskOxygen >= capacity - 0.01f || !CanUseEquipment(center))
            {
                return;
            }

            if (!TryFindSuitDockOxygenSource(center, out Vector2Int source))
            {
                return;
            }

            float amount = Mathf.Min(
                oxygen[source.x, source.y],
                Mathf.Min(OxygenMaskDockChargeRate * deltaTime, capacity - maskOxygen));
            if (amount <= 0.001f)
            {
                return;
            }

            oxygen[source.x, source.y] = Mathf.Max(0f, oxygen[source.x, source.y] - amount);
            maskOxygen = Mathf.Min(capacity, maskOxygen + amount);
            AddHeat(center, 0.010f * deltaTime, 1);
            WearEquipment(center, 0.00012f * deltaTime);
            gasDirty = true;
            overlayDirty = true;
        }

        private bool TryFindSuitDockOxygenSource(Vector2Int center, out Vector2Int source)
        {
            source = center;
            float best = IsInside(center.x, center.y) && IsPassable(center.x, center.y) ? oxygen[center.x, center.y] : 0f;
            Vector2Int[] offsets =
            {
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1)
            };

            foreach (Vector2Int offset in offsets)
            {
                int x = center.x + offset.x;
                int y = center.y + offset.y;
                if (IsInside(x, y) && IsPassable(x, y) && oxygen[x, y] > best)
                {
                    best = oxygen[x, y];
                    source = new Vector2Int(x, y);
                }
            }

            return best > 0.03f;
        }

        private float SuitOxygenCapacityTotal()
        {
            return UsableSuitDockCount() * SuitDockOxygenCapacity;
        }

        private bool NeedsSuitProtection(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return false;
            }

            return oxygen[cell.x, cell.y] < 0.14f ||
                carbonDioxide[cell.x, cell.y] > 1.1f ||
                pollutedOxygen[cell.x, cell.y] > 0.16f ||
                hydrogen[cell.x, cell.y] > 0.42f ||
                chlorine[cell.x, cell.y] > ChlorineExposureThreshold ||
                sourGas[cell.x, cell.y] > SourGasExposureThreshold ||
                TileGasTotal(cell.x, cell.y) > OverpressureStressThreshold ||
                temperature[cell.x, cell.y] < 0f ||
                temperature[cell.x, cell.y] > 44f;
        }

        private bool UseSuitProtection(Worker worker, float deltaTime)
        {
            if (worker == null || !worker.SuitEquipped || !NeedsSuitProtection(worker.Cell) || suitOxygen <= 0.001f)
            {
                return false;
            }

            float requested = SuitBreathRate * deltaTime;
            float used = Mathf.Min(suitOxygen, requested);
            if (used <= 0.001f)
            {
                return false;
            }

            suitOxygen = Mathf.Max(0f, suitOxygen - used);
            suitOxygenUsed += used;
            overlayDirty = true;
            return used >= requested * 0.5f;
        }

        private bool HasChargedSuitOxygen()
        {
            return suitOxygen > SuitCheckpointMinimumCharge;
        }

        private float OxygenMaskCapacityTotal()
        {
            return UsableOxygenMaskDockCount() * OxygenMaskDockOxygenCapacity;
        }

        private bool NeedsOxygenMaskProtection(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsPassable(cell.x, cell.y) &&
                BreathableAirAt(cell.x, cell.y) < BreathRecoveryAirThreshold;
        }

        private bool UseOxygenMaskProtection(Worker worker, float deltaTime)
        {
            if (worker == null ||
                worker.SuitEquipped ||
                !worker.OxygenMaskEquipped ||
                !NeedsOxygenMaskProtection(worker.Cell) ||
                maskOxygen <= 0.001f)
            {
                return false;
            }

            float requested = OxygenMaskBreathRate * deltaTime;
            float used = Mathf.Min(maskOxygen, requested);
            if (used <= 0.001f)
            {
                return false;
            }

            maskOxygen = Mathf.Max(0f, maskOxygen - used);
            maskOxygenUsed += used;
            overlayDirty = true;
            return used >= requested * 0.5f;
        }

        private bool HasChargedOxygenMask()
        {
            return maskOxygen > OxygenMaskCheckpointMinimumCharge;
        }

        private bool HasWorkerBreathingGearOxygen(Worker worker)
        {
            return worker != null &&
                ((worker.SuitEquipped && HasChargedSuitOxygen()) ||
                (worker.OxygenMaskEquipped && HasChargedOxygenMask()));
        }

        private bool HasDepletedBreathingGearInUnsafeArea(Worker worker)
        {
            if (worker == null || worker.Health <= 0f || !IsInside(worker.Cell.x, worker.Cell.y))
            {
                return false;
            }

            if (worker.SuitEquipped)
            {
                return NeedsSuitProtection(worker.Cell) && !HasChargedSuitOxygen();
            }

            return worker.OxygenMaskEquipped &&
                NeedsOxygenMaskProtection(worker.Cell) &&
                !HasChargedOxygenMask();
        }

        private string DepletedBreathingGearName(Worker worker)
        {
            return worker != null && worker.SuitEquipped ? "Atmo suit" : "Oxygen mask";
        }

        private bool CanEquipOxygenMaskAtCheckpoint(Vector2Int checkpoint)
        {
            return IsOxygenMaskCheckpointCell(checkpoint) &&
                HasAdjacentOxygenMaskDock(checkpoint) &&
                OxygenMaskCapacityTotal() > 0f &&
                AvailableOxygenMaskCount() > 0 &&
                HasChargedOxygenMask();
        }

        private bool CanEquipSuitAtCheckpoint(Vector2Int checkpoint)
        {
            return IsSuitCheckpointCell(checkpoint) &&
                HasAdjacentSuitDock(checkpoint) &&
                SuitOxygenCapacityTotal() > 0f &&
                AvailableSuitCount() > 0 &&
                HasChargedSuitOxygen();
        }

        private bool CanEquipLeadSuitAtCheckpoint(Vector2Int checkpoint)
        {
            return IsLeadSuitCheckpointCell(checkpoint) &&
                HasAdjacentLeadSuitLocker(checkpoint) &&
                AvailableLeadSuitCount() > 0;
        }

        private bool CanTraversePathStep(Vector2Int from, Vector2Int to)
        {
            if (!CanCharacterTraversePathStep(from, to))
            {
                return false;
            }

            if (IsSuitCheckpointCell(from) && NeedsSuitProtection(to) && !CanEquipSuitAtCheckpoint(from))
            {
                return false;
            }

            if (IsOxygenMaskCheckpointCell(from) && NeedsOxygenMaskProtection(to) && !CanEquipOxygenMaskAtCheckpoint(from))
            {
                return false;
            }

            if (IsLeadSuitCheckpointCell(from) && NeedsLeadSuitProtection(to) && !CanEquipLeadSuitAtCheckpoint(from))
            {
                return false;
            }

            return true;
        }

        private bool CanWorkerTraversePathStep(Worker worker, Vector2Int from, Vector2Int to)
        {
            return CanWorkerTraversePathStepForJob(worker, worker == null ? null : worker.AssignedJob, from, to);
        }

        private bool CanWorkerTraversePathStepForJob(Worker worker, Job job, Vector2Int from, Vector2Int to)
        {
            if (!CanCharacterTraversePathStepForJob(worker, job, from, to))
            {
                return false;
            }

            if (IsSuitCheckpointCell(from) && NeedsSuitProtection(to))
            {
                if (worker != null && worker.SuitEquipped)
                {
                    return HasChargedSuitOxygen();
                }

                return CanEquipSuitAtCheckpoint(from);
            }

            if (IsOxygenMaskCheckpointCell(from) && NeedsOxygenMaskProtection(to))
            {
                if (HasWorkerBreathingGearOxygen(worker))
                {
                    return true;
                }

                return CanEquipOxygenMaskAtCheckpoint(from);
            }

            if (IsLeadSuitCheckpointCell(from) && NeedsLeadSuitProtection(to))
            {
                if (worker != null && worker.LeadSuitEquipped)
                {
                    return true;
                }

                return CanEquipLeadSuitAtCheckpoint(from);
            }

            return true;
        }

        private bool CanCharacterTraversePathStepForJob(Worker worker, Job job, Vector2Int from, Vector2Int to)
        {
            if (!IsCharacterPathCell(to, from))
            {
                return false;
            }

            int dx = Mathf.Abs(to.x - from.x);
            int dy = Mathf.Abs(to.y - from.y);
            if (dx + dy != 1)
            {
                return false;
            }

            if (!CanPassDoorAccess(from, to, worker, job))
            {
                return false;
            }

            if (dy > 0 && !CanCharacterMoveVertically(from, to))
            {
                return false;
            }

            return true;
        }

        private bool CanCharacterTraversePathStep(Vector2Int from, Vector2Int to)
        {
            if (!IsCharacterPathCell(to, from))
            {
                return false;
            }

            int dx = Mathf.Abs(to.x - from.x);
            int dy = Mathf.Abs(to.y - from.y);
            if (dx + dy != 1)
            {
                return false;
            }

            if (!CanPassDoorAccess(from, to))
            {
                return false;
            }

            if (dy > 0 && !CanCharacterMoveVertically(from, to))
            {
                return false;
            }

            return true;
        }

        private bool CanCharacterTraversePathStepIgnoringDoorRestrictions(Vector2Int from, Vector2Int to)
        {
            if (!IsCharacterPathCellIgnoringDoorRestrictions(to, from))
            {
                return false;
            }

            int dx = Mathf.Abs(to.x - from.x);
            int dy = Mathf.Abs(to.y - from.y);
            if (dx + dy != 1)
            {
                return false;
            }

            if (dy > 0 && !CanCharacterMoveVertically(from, to))
            {
                return false;
            }

            return true;
        }

        private bool CanPassDoorAccess(Vector2Int from, Vector2Int to)
        {
            return CanPassDoorAccess(from, to, null, null);
        }

        private bool CanPassDoorAccess(Vector2Int from, Vector2Int to, Worker worker, Job job)
        {
            Vector2Int door = IsInside(to.x, to.y) && IsDoorAccessControlledKind(cells[to.x, to.y])
                ? to
                : IsInside(from.x, from.y) && IsDoorAccessControlledKind(cells[from.x, from.y])
                    ? from
                    : new Vector2Int(-1, -1);
            if (door.x < 0)
            {
                return true;
            }

            DoorAccessMode mode = DoorAccessModeAt(door.x, door.y);
            if (mode == DoorAccessMode.Both)
            {
                return true;
            }

            if (mode == DoorAccessMode.Locked)
            {
                return false;
            }

            if (mode == DoorAccessMode.Emergency)
            {
                return IsEmergencyDoorAccessAllowed(worker, job);
            }

            if (from.y != to.y)
            {
                return true;
            }

            return mode == DoorAccessMode.LeftToRight
                ? to.x > from.x
                : to.x < from.x;
        }

        private bool IsEmergencyDoorAccessAllowed(Worker worker, Job job)
        {
            if (redAlertActive)
            {
                return true;
            }

            if (job != null && IsEmergencyDoorAccessJob(job.Type))
            {
                return true;
            }

            return worker != null &&
                worker.Health > 0f &&
                (NeedsSeekSafety(worker) || NeedsCatchBreath(worker));
        }

        private bool IsEmergencyDoorAccessJob(JobType type)
        {
            return type == JobType.Rescue ||
                type == JobType.Treat ||
                type == JobType.CatchBreath ||
                type == JobType.SeekSafety;
        }

        private bool IsCharacterStandableCell(Vector2Int cell)
        {
            return IsCharacterPathCell(cell, new Vector2Int(-1, -1));
        }

        private bool IsCharacterPathCell(Vector2Int cell, Vector2Int from)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return false;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (kind == CellKind.Ladder || kind == CellKind.FirePole || kind == CellKind.Floor || kind == CellKind.HydroponicFarm || kind == CellKind.MeshTile)
            {
                return true;
            }

            if (kind == CellKind.ManualAirlock)
            {
                return airlockOpen[cell.x, cell.y];
            }

            if (kind == CellKind.MechanizedAirlock)
            {
                return IsMechanizedAirlockOpen(cell);
            }

            if (kind == CellKind.BunkerDoor)
            {
                return !IsBunkerDoorClosed(cell);
            }

            if (kind == CellKind.Empty)
            {
                return HasCharacterFloorSupport(cell) || IsVerticalTransitCell(from);
            }

            return HasCharacterFloorSupport(cell) || IsCharacterSpecialStructure(cell);
        }

        private bool IsCharacterPathCellIgnoringDoorRestrictions(Vector2Int cell, Vector2Int from)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (IsDoorAccessControlledKind(kind) || kind == CellKind.BunkerDoor)
            {
                return true;
            }

            return IsCharacterPathCell(cell, from);
        }

        private bool CanCharacterMoveVertically(Vector2Int from, Vector2Int to)
        {
            return IsVerticalTransitCell(from) ||
                IsVerticalTransitCell(to) ||
                IsCharacterSpecialStructure(from) ||
                IsCharacterSpecialStructure(to);
        }

        private bool IsCharacterLadderCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && cells[cell.x, cell.y] == CellKind.Ladder;
        }

        private bool IsFirePoleCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && cells[cell.x, cell.y] == CellKind.FirePole;
        }

        private int FirePoleVerticalSpan()
        {
            int best = 0;
            for (int x = 0; x < WorldWidth; x++)
            {
                int current = 0;
                for (int y = 0; y < WorldHeight; y++)
                {
                    if (cells[x, y] == CellKind.FirePole)
                    {
                        current++;
                        best = Mathf.Max(best, current);
                    }
                    else
                    {
                        current = 0;
                    }
                }
            }

            return best;
        }

        private bool IsVerticalTransitCell(Vector2Int cell)
        {
            return IsCharacterLadderCell(cell) || IsFirePoleCell(cell);
        }

        private bool IsCharacterSpecialStructure(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (kind == CellKind.ManualAirlock)
            {
                return airlockOpen[cell.x, cell.y];
            }

            if (kind == CellKind.MechanizedAirlock)
            {
                return IsMechanizedAirlockOpen(cell);
            }

            if (kind == CellKind.BunkerDoor)
            {
                return !IsBunkerDoorClosed(cell);
            }

            return false;
        }

        private bool HasCharacterFloorSupport(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (cell.y <= 0)
            {
                return true;
            }

            Vector2Int belowCell = new Vector2Int(cell.x, cell.y - 1);
            CellKind below = cells[belowCell.x, belowCell.y];
            if (below == CellKind.Floor || below == CellKind.HydroponicFarm || below == CellKind.MeshTile || below == CellKind.MechanizedAirlock || IsSolidTile(below))
            {
                return true;
            }

            return IsCharacterSpecialStructure(belowCell);
        }

        private void DenySuitCheckpointEntry(Worker worker, Vector2Int checkpoint)
        {
            suitEntryDenials++;
            if (worker != null)
            {
                ClearAssignment(worker);
                worker.Activity = "Waiting for Atmo Suit";
                worker.Stress = Mathf.Min(100f, worker.Stress + 0.8f);
            }

            WearEquipment(checkpoint, 0.00015f);
            overlayDirty = true;
            if (IsSuitCheckpointCell(checkpoint) && HasAdjacentSuitDock(checkpoint) && AvailableSuitCount() <= 0)
            {
                Log("No available Atmo Suits at linked docks.");
            }
            else
            {
                Log((worker != null ? worker.Name + " " : string.Empty) + "cannot cross Atmo Suit Checkpoint without charged suit oxygen.");
            }
        }

        private bool UpdateSuitCheckpointCrossing(Worker worker, Vector2Int from, Vector2Int to)
        {
            if (worker == null || from == to)
            {
                return true;
            }

            bool fromCheckpoint = IsSuitCheckpointCell(from);
            bool toCheckpoint = IsSuitCheckpointCell(to);
            if (!fromCheckpoint && !toCheckpoint)
            {
                return true;
            }

            if (fromCheckpoint)
            {
                if (!IsInside(to.x, to.y) || !IsPassable(to.x, to.y))
                {
                    return true;
                }

                if (NeedsSuitProtection(to))
                {
                    if (worker.SuitEquipped)
                    {
                        return HasChargedSuitOxygen();
                    }

                    return EquipSuitAtCheckpoint(worker, from);
                }

                if (worker.SuitEquipped)
                {
                    ReturnSuitAtCheckpoint(worker, from);
                }
            }

            return true;
        }

        private bool EquipSuitAtCheckpoint(Worker worker, Vector2Int checkpoint)
        {
            if (worker == null || worker.SuitEquipped)
            {
                return worker != null && worker.SuitEquipped;
            }

            if (!IsSuitCheckpointCell(checkpoint) || !HasAdjacentSuitDock(checkpoint) || SuitOxygenCapacityTotal() <= 0f)
            {
                return false;
            }

            if (AvailableSuitCount() <= 0)
            {
                Log("No available Atmo Suits at linked docks.");
                return false;
            }

            if (suitOxygen <= SuitCheckpointMinimumCharge)
            {
                Log("Atmo Suit Checkpoint needs charged suit oxygen before entry.");
                return false;
            }

            worker.OxygenMaskEquipped = false;
            worker.LeadSuitEquipped = false;
            worker.SuitEquipped = true;
            suitCheckpointUses++;
            WearEquipment(checkpoint, 0.0007f);
            overlayDirty = true;
            Log(worker.Name + " equipped an atmo suit.");
            return true;
        }

        private void ReturnSuitAtCheckpoint(Worker worker, Vector2Int checkpoint)
        {
            if (worker == null || !worker.SuitEquipped || !IsSuitCheckpointCell(checkpoint))
            {
                return;
            }

            worker.SuitEquipped = false;
            suitCheckpointUses++;
            WearEquipment(checkpoint, 0.00035f);
            overlayDirty = true;
            Log(worker.Name + " returned an atmo suit.");
        }

        private bool IsSuitCheckpointCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.AtmoSuitCheckpoint &&
                CanUseEquipment(cell);
        }

        private bool HasAdjacentSuitDock(Vector2Int checkpoint)
        {
            return IsUsableSuitDock(checkpoint.x + 1, checkpoint.y) ||
                IsUsableSuitDock(checkpoint.x - 1, checkpoint.y) ||
                IsUsableSuitDock(checkpoint.x, checkpoint.y + 1) ||
                IsUsableSuitDock(checkpoint.x, checkpoint.y - 1);
        }

        private bool HasAdjacentSuitCheckpoint(Vector2Int dock)
        {
            return IsSuitCheckpointCell(new Vector2Int(dock.x + 1, dock.y)) ||
                IsSuitCheckpointCell(new Vector2Int(dock.x - 1, dock.y)) ||
                IsSuitCheckpointCell(new Vector2Int(dock.x, dock.y + 1)) ||
                IsSuitCheckpointCell(new Vector2Int(dock.x, dock.y - 1));
        }

        private bool IsUsableSuitDock(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.AtmoSuitDock &&
                CanUseEquipment(new Vector2Int(x, y));
        }

        private int UsableSuitDockCount()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsUsableSuitDock(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int AvailableSuitCount()
        {
            return Math.Max(0, UsableSuitDockCount() - CountSuitedWorkers());
        }

        private int CountSuitedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.SuitEquipped && worker.Health > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private void DenyOxygenMaskCheckpointEntry(Worker worker, Vector2Int checkpoint)
        {
            maskEntryDenials++;
            if (worker != null)
            {
                ClearAssignment(worker);
                worker.Activity = "Waiting for Oxygen Mask";
                worker.Stress = Mathf.Min(100f, worker.Stress + 0.55f);
            }

            WearEquipment(checkpoint, 0.00012f);
            overlayDirty = true;
            if (IsOxygenMaskCheckpointCell(checkpoint) && HasAdjacentOxygenMaskDock(checkpoint) && AvailableOxygenMaskCount() <= 0)
            {
                Log("No available Oxygen Masks at linked docks.");
            }
            else
            {
                Log((worker != null ? worker.Name + " " : string.Empty) + "cannot cross Oxygen Mask Checkpoint without charged mask oxygen.");
            }
        }

        private bool UpdateOxygenMaskCheckpointCrossing(Worker worker, Vector2Int from, Vector2Int to)
        {
            if (worker == null || from == to)
            {
                return true;
            }

            bool fromCheckpoint = IsOxygenMaskCheckpointCell(from);
            bool toCheckpoint = IsOxygenMaskCheckpointCell(to);
            if (!fromCheckpoint && !toCheckpoint)
            {
                return true;
            }

            if (fromCheckpoint)
            {
                if (!IsInside(to.x, to.y) || !IsPassable(to.x, to.y))
                {
                    return true;
                }

                if (NeedsOxygenMaskProtection(to))
                {
                    if (worker.SuitEquipped)
                    {
                        return HasChargedSuitOxygen();
                    }

                    if (worker.OxygenMaskEquipped)
                    {
                        return HasChargedOxygenMask();
                    }

                    return EquipOxygenMaskAtCheckpoint(worker, from);
                }

                if (worker.OxygenMaskEquipped)
                {
                    ReturnOxygenMaskAtCheckpoint(worker, from);
                }
            }

            return true;
        }

        private bool EquipOxygenMaskAtCheckpoint(Worker worker, Vector2Int checkpoint)
        {
            if (worker == null)
            {
                return false;
            }

            if (worker.SuitEquipped)
            {
                return HasChargedSuitOxygen();
            }

            if (worker.OxygenMaskEquipped)
            {
                return HasChargedOxygenMask();
            }

            if (!IsOxygenMaskCheckpointCell(checkpoint) || !HasAdjacentOxygenMaskDock(checkpoint) || OxygenMaskCapacityTotal() <= 0f)
            {
                return false;
            }

            if (AvailableOxygenMaskCount() <= 0)
            {
                Log("No available Oxygen Masks at linked docks.");
                return false;
            }

            if (maskOxygen <= OxygenMaskCheckpointMinimumCharge)
            {
                Log("Oxygen Mask Checkpoint needs charged mask oxygen before entry.");
                return false;
            }

            worker.OxygenMaskEquipped = true;
            maskCheckpointUses++;
            WearEquipment(checkpoint, 0.0005f);
            overlayDirty = true;
            Log(worker.Name + " equipped an oxygen mask.");
            return true;
        }

        private void ReturnOxygenMaskAtCheckpoint(Worker worker, Vector2Int checkpoint)
        {
            if (worker == null || !worker.OxygenMaskEquipped || !IsOxygenMaskCheckpointCell(checkpoint))
            {
                return;
            }

            worker.OxygenMaskEquipped = false;
            maskCheckpointUses++;
            WearEquipment(checkpoint, 0.00025f);
            overlayDirty = true;
            Log(worker.Name + " returned an oxygen mask.");
        }

        private bool IsOxygenMaskCheckpointCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.OxygenMaskCheckpoint &&
                CanUseEquipment(cell);
        }

        private bool HasAdjacentOxygenMaskDock(Vector2Int checkpoint)
        {
            return IsUsableOxygenMaskDock(checkpoint.x + 1, checkpoint.y) ||
                IsUsableOxygenMaskDock(checkpoint.x - 1, checkpoint.y) ||
                IsUsableOxygenMaskDock(checkpoint.x, checkpoint.y + 1) ||
                IsUsableOxygenMaskDock(checkpoint.x, checkpoint.y - 1);
        }

        private bool HasAdjacentOxygenMaskCheckpoint(Vector2Int dock)
        {
            return IsOxygenMaskCheckpointCell(new Vector2Int(dock.x + 1, dock.y)) ||
                IsOxygenMaskCheckpointCell(new Vector2Int(dock.x - 1, dock.y)) ||
                IsOxygenMaskCheckpointCell(new Vector2Int(dock.x, dock.y + 1)) ||
                IsOxygenMaskCheckpointCell(new Vector2Int(dock.x, dock.y - 1));
        }

        private bool IsUsableOxygenMaskDock(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.OxygenMaskDock &&
                CanUseEquipment(new Vector2Int(x, y));
        }

        private int UsableOxygenMaskDockCount()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsUsableOxygenMaskDock(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int AvailableOxygenMaskCount()
        {
            return Math.Max(0, UsableOxygenMaskDockCount() - CountMaskedWorkers());
        }

        private int CountMaskedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.OxygenMaskEquipped && worker.Health > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private float RadiationAt(int x, int y)
        {
            if (!IsInside(x, y) || !IsPassable(x, y))
            {
                return 0f;
            }

            float radiation = 0f;
            int spaceStart = WorldHeight - 8;
            if (y >= spaceStart)
            {
                radiation += 0.10f + (y - spaceStart) * 0.025f;
                if (meteorShowerSeconds > 0f)
                {
                    radiation += 0.14f;
                }
            }

            radiation += LocalRadiationFromCellKind(x, y, CellKind.Regolith, 3, 0.18f);
            radiation += LocalRadiationFromCellKind(x, y, CellKind.Wheezewort, 3, 0.16f);
            radiation += LocalRadiationFromCellKind(x, y, CellKind.Magma, 6, 0.38f);
            radiation += LocalRadiationFromCellKind(
                x,
                y,
                CellKind.RocketPlatform,
                4,
                rocketMissionProgress > 0f ? 0.18f : 0.09f);
            radiation += LocalRadiationFromCellKind(x, y, CellKind.ResearchReactor, 5, ResearchReactorRadiation);
            return Mathf.Clamp01(radiation);
        }

        private float LocalRadiationFromCellKind(int centerX, int centerY, CellKind sourceKind, int radius, float maxContribution)
        {
            float best = 0f;
            for (int y = Mathf.Max(0, centerY - radius); y <= Mathf.Min(WorldHeight - 1, centerY + radius); y++)
            {
                for (int x = Mathf.Max(0, centerX - radius); x <= Mathf.Min(WorldWidth - 1, centerX + radius); x++)
                {
                    if (cells[x, y] != sourceKind)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(centerX - x) + Mathf.Abs(centerY - y);
                    if (distance > radius)
                    {
                        continue;
                    }

                    float falloff = 1f - distance / (float)(radius + 1);
                    best = Mathf.Max(best, maxContribution * falloff);
                }
            }

            return best;
        }

        private bool NeedsLeadSuitProtection(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsPassable(cell.x, cell.y) &&
                RadiationAt(cell.x, cell.y) > RadiationExposureThreshold;
        }

        private void ApplyWorkerRadiationExposure(Worker worker, float deltaTime)
        {
            if (worker == null || deltaTime <= 0f || !IsInside(worker.Cell.x, worker.Cell.y) || !IsPassable(worker.Cell.x, worker.Cell.y))
            {
                return;
            }

            float radiation = RadiationAt(worker.Cell.x, worker.Cell.y);
            if (radiation <= RadiationExposureThreshold)
            {
                if (worker.LeadSuitEquipped)
                {
                    worker.Stress = Mathf.Max(0f, worker.Stress - RadiationRecoveryRate * deltaTime);
                }

                return;
            }

            radiationExposureSeconds += deltaTime;
            float effectiveRadiation = worker.LeadSuitEquipped ? radiation * LeadSuitRadiationMultiplier : radiation;
            float severity = Mathf.Clamp01((effectiveRadiation - RadiationExposureThreshold) / Mathf.Max(0.001f, 1f - RadiationExposureThreshold));
            if (techSpaceSystems && worker.LeadSuitEquipped)
            {
                float rawSeverity = Mathf.Clamp01((radiation - RadiationExposureThreshold) / Mathf.Max(0.001f, 1f - RadiationExposureThreshold));
                radiationSamples += rawSeverity * RadiationSampleCollectionRate * deltaTime;
            }

            if (severity <= 0.001f)
            {
                return;
            }

            worker.Stress = Mathf.Min(100f, worker.Stress + RadiationStressRate * severity * deltaTime);
            worker.Sickness = Mathf.Min(100f, worker.Sickness + RadiationSicknessRate * severity * deltaTime);
            if (!worker.LeadSuitEquipped && worker.Sickness >= RadiationSicknessContractThreshold)
            {
                ContractWorkerDisease(worker, WorkerDisease.RadiationSickness, RadiationSicknessContractThreshold, worker.Name + " developed Radiation Sickness. Use Lead Suits or leave radiation zones.");
            }

            float beforeHealth = worker.Health;
            worker.Health = Mathf.Max(0f, worker.Health - RadiationDamageRate * severity * deltaTime);
            radiationHealthDamage += Mathf.Max(0f, beforeHealth - worker.Health);
        }

        private void ApplyWorkerElectricalHazard(Worker worker, bool suitProtected, float deltaTime)
        {
            if (worker == null || deltaTime <= 0f || !IsInside(worker.Cell.x, worker.Cell.y) || !powerWire[worker.Cell.x, worker.Cell.y])
            {
                return;
            }

            int x = worker.Cell.x;
            int y = worker.Cell.y;
            bool liveWire = poweredWire[x, y];
            bool overloaded = liveWire && overloadedWire[x, y];
            bool flooded = liveWire && IsPowerWireFlooded(x, y);
            if (!overloaded && !flooded)
            {
                return;
            }

            float severity = 0f;
            if (overloaded)
            {
                float limit = Mathf.Max(0.001f, PowerLoadLimitForWire(x, y));
                float overloadRatio = Mathf.Clamp01((wireLoad[x, y] - limit) / limit);
                severity = Mathf.Max(severity, Mathf.Lerp(0.45f, 1f, overloadRatio));
            }

            if (flooded)
            {
                float floodSeverity = Mathf.Clamp01(waterMass[x, y] / LiquidTileCapacity);
                severity = Mathf.Max(severity, floodSeverity * FloodedElectricalHazardMultiplier);
            }

            if (severity <= 0.001f)
            {
                return;
            }

            float protectionMultiplier = suitProtected || worker.LeadSuitEquipped ? SuitElectricalHazardMultiplier : 1f;
            float effectiveSeverity = severity * protectionMultiplier;
            worker.Stress = Mathf.Min(100f, worker.Stress + ElectricalHazardStressRate * effectiveSeverity * deltaTime);
            worker.Health = Mathf.Max(0f, worker.Health - ElectricalHazardDamageRate * effectiveSeverity * deltaTime);
        }

        private void DenyLeadSuitCheckpointEntry(Worker worker, Vector2Int checkpoint)
        {
            leadSuitEntryDenials++;
            if (worker != null)
            {
                ClearAssignment(worker);
                worker.Activity = "Waiting for Lead Suit";
                worker.Stress = Mathf.Min(100f, worker.Stress + 0.65f);
            }

            WearEquipment(checkpoint, 0.00014f);
            overlayDirty = true;
            if (IsLeadSuitCheckpointCell(checkpoint) && HasAdjacentLeadSuitLocker(checkpoint) && AvailableLeadSuitCount() <= 0)
            {
                Log("No available Lead Suits at linked lockers.");
            }
            else
            {
                Log((worker != null ? worker.Name + " " : string.Empty) + "cannot cross Lead Suit Checkpoint without an adjacent locker.");
            }
        }

        private bool UpdateLeadSuitCheckpointCrossing(Worker worker, Vector2Int from, Vector2Int to)
        {
            if (worker == null || from == to)
            {
                return true;
            }

            bool fromCheckpoint = IsLeadSuitCheckpointCell(from);
            bool toCheckpoint = IsLeadSuitCheckpointCell(to);
            if (!fromCheckpoint && !toCheckpoint)
            {
                return true;
            }

            if (fromCheckpoint)
            {
                if (!IsInside(to.x, to.y) || !IsPassable(to.x, to.y))
                {
                    return true;
                }

                if (NeedsLeadSuitProtection(to))
                {
                    if (worker.LeadSuitEquipped)
                    {
                        return true;
                    }

                    return EquipLeadSuitAtCheckpoint(worker, from);
                }

                if (worker.LeadSuitEquipped)
                {
                    ReturnLeadSuitAtCheckpoint(worker, from);
                }
            }

            return true;
        }

        private bool EquipLeadSuitAtCheckpoint(Worker worker, Vector2Int checkpoint)
        {
            if (worker == null)
            {
                return false;
            }

            if (worker.LeadSuitEquipped)
            {
                return true;
            }

            if (worker.SuitEquipped || !IsLeadSuitCheckpointCell(checkpoint) || !HasAdjacentLeadSuitLocker(checkpoint))
            {
                return false;
            }

            if (AvailableLeadSuitCount() <= 0)
            {
                Log("No available Lead Suits at linked lockers.");
                return false;
            }

            worker.LeadSuitEquipped = true;
            leadSuitCheckpointUses++;
            WearEquipment(checkpoint, 0.00055f);
            overlayDirty = true;
            Log(worker.Name + " equipped a lead suit.");
            return true;
        }

        private void ReturnLeadSuitAtCheckpoint(Worker worker, Vector2Int checkpoint)
        {
            if (worker == null || !worker.LeadSuitEquipped || !IsLeadSuitCheckpointCell(checkpoint))
            {
                return;
            }

            worker.LeadSuitEquipped = false;
            leadSuitCheckpointUses++;
            WearEquipment(checkpoint, 0.00028f);
            overlayDirty = true;
            Log(worker.Name + " returned a lead suit.");
        }

        private bool IsLeadSuitCheckpointCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.LeadSuitCheckpoint &&
                CanUseEquipment(cell);
        }

        private bool HasAdjacentLeadSuitLocker(Vector2Int checkpoint)
        {
            return IsUsableLeadSuitLocker(checkpoint.x + 1, checkpoint.y) ||
                IsUsableLeadSuitLocker(checkpoint.x - 1, checkpoint.y) ||
                IsUsableLeadSuitLocker(checkpoint.x, checkpoint.y + 1) ||
                IsUsableLeadSuitLocker(checkpoint.x, checkpoint.y - 1);
        }

        private bool HasAdjacentLeadSuitCheckpoint(Vector2Int locker)
        {
            return IsLeadSuitCheckpointCell(new Vector2Int(locker.x + 1, locker.y)) ||
                IsLeadSuitCheckpointCell(new Vector2Int(locker.x - 1, locker.y)) ||
                IsLeadSuitCheckpointCell(new Vector2Int(locker.x, locker.y + 1)) ||
                IsLeadSuitCheckpointCell(new Vector2Int(locker.x, locker.y - 1));
        }

        private bool IsUsableLeadSuitLocker(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.LeadSuitLocker &&
                CanUseEquipment(new Vector2Int(x, y));
        }

        private int UsableLeadSuitLockerCount()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsUsableLeadSuitLocker(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int AvailableLeadSuitCount()
        {
            return Math.Max(0, UsableLeadSuitLockerCount() - CountLeadSuitedWorkers());
        }

        private int CountLeadSuitedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.LeadSuitEquipped && worker.Health > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private void SimulateFoodSpoilage(float deltaTime)
        {
            if (food <= 0f)
            {
                food = 0f;
                foodFreshness = 1f;
                foodQuality = DefaultFoodQuality;
                foodGerms = 0f;
                return;
            }

            int refrigerators = CountUsableCells(CellKind.Refrigerator);
            int poweredRefrigerators = CountPoweredRefrigerators();
            float storageTemperature = AverageFoodStorageTemperature();
            float temperatureFactor = storageTemperature > 38f ? 2.3f :
                storageTemperature > 28f ? 1.55f :
                storageTemperature < 8f ? 0.55f : 1f;
            float storageFactor = FoodStorageSpoilageFactor(refrigerators, poweredRefrigerators);
            float decayRate = 0.00022f * temperatureFactor * storageFactor;
            float spoiled = Mathf.Min(food, food * decayRate * deltaTime);

            food -= spoiled;
            currentCycleReport.FoodSpoiled += spoiled;
            if (spoiled > 0.001f)
            {
                AddPollutedDirt(spoiled * 0.16f, FoodWasteCell());
            }

            foodFreshness = Mathf.Clamp01(foodFreshness - decayRate * deltaTime * 4.5f);
            SimulateFoodGermStorage(deltaTime, poweredRefrigerators);
            SimulateRottenFoodBreakdown(deltaTime);
            if (food <= 1f)
            {
                food = 0f;
                foodFreshness = 1f;
                foodQuality = DefaultFoodQuality;
                foodGerms = 0f;
            }
        }

        private void SimulateRottenFoodBreakdown(float deltaTime)
        {
            if (deltaTime <= 0f || food <= 1f || foodFreshness > SpoiledFoodRotFreshnessThreshold)
            {
                return;
            }

            float severity = Mathf.InverseLerp(SpoiledFoodRotFreshnessThreshold, 0f, foodFreshness);
            if (severity <= 0f)
            {
                return;
            }

            float rotKcalPerSecond = Mathf.Max(SpoiledFoodRotMinimumKcalPerSecond, food * SpoiledFoodRotRate);
            float rottenFood = Mathf.Min(food, rotKcalPerSecond * severity * deltaTime);
            if (rottenFood <= 0.001f)
            {
                return;
            }

            food = Mathf.Max(0f, food - rottenFood);
            currentCycleReport.FoodSpoiled += rottenFood;

            float pollutedDirtProduced = rottenFood * SpoiledFoodRotPollutedDirtYield;
            pollutedDirt += pollutedDirtProduced;
            spoiledFoodRotPollutedDirt += pollutedDirtProduced;

            Vector2Int source = FoodWasteCell();
            float clampedWaste = Mathf.Clamp(pollutedDirtProduced, 0.1f, 8f);
            float emitted = VentPollutedOxygen(
                source,
                SpoiledFoodRotOffgasPerDirtKg * clampedWaste,
                SpoiledFoodRotGermPerDirtKg * clampedWaste + foodGerms * 0.08f * severity);
            spoiledFoodRotPollutedOxygen += emitted;
            gasDirty = true;
            overlayDirty = true;
        }

        private void SimulatePollutedDirtOffgas(float deltaTime)
        {
            float availablePollutedDirt = PollutedDirtOffgasAvailableMass();
            if (deltaTime <= 0f || availablePollutedDirt <= PollutedDirtOffgasMinimum)
            {
                return;
            }

            CollectPollutedDirtOffgasSources(pollutedDirtOffgasSources);
            if (pollutedDirtOffgasSources.Count == 0)
            {
                return;
            }

            float emitted = 0f;
            float sublimated = 0f;
            float sourceScale = 1f / Mathf.Sqrt(Mathf.Max(1, pollutedDirtOffgasSources.Count));
            bool hasStoredSource = pollutedDirt > PollutedDirtOffgasMinimum;
            Vector2Int storedSource = hasStoredSource ? WasteStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                float pressure = Mathf.Clamp01(pollutedDirt / 80f);
                float sourceEmitted = VentPollutedOxygen(storedSource, (0.006f + pressure * 0.026f) * deltaTime * sourceScale, (0.018f + pressure * 0.055f) * deltaTime * sourceScale);
                emitted += sourceEmitted;
                sublimated += SublimateStoredPollutedDirt(sourceEmitted);
            }

            for (int i = 0; i < pollutedDirtOffgasSources.Count; i++)
            {
                Vector2Int source = pollutedDirtOffgasSources[i];
                if ((hasStoredSource && storedSource == source) || !IsLoosePollutedDirtOffgasSource(source.x, source.y))
                {
                    continue;
                }

                float localMass = looseResourceAmount[source.x, source.y];
                float pressure = Mathf.Clamp01(localMass / 24f);
                float sourceEmitted = VentPollutedOxygen(source, (0.004f + pressure * 0.020f) * deltaTime * sourceScale, (0.012f + pressure * 0.045f) * deltaTime * sourceScale);
                emitted += sourceEmitted;
                sublimated += SublimateLoosePollutedDirt(source, sourceEmitted);
            }

            if (emitted > 0.001f)
            {
                pollutedDirtOffgassedMass += emitted;
                pollutedDirtOffgasEvents++;
                gasDirty = true;
                overlayDirty = true;
            }

            if (sublimated > 0.001f)
            {
                pollutedDirtSublimatedMass += sublimated;
                terrainDirty = true;
                overlayDirty = true;
            }
        }

        private float SublimateStoredPollutedDirt(float emittedPollutedOxygen)
        {
            if (emittedPollutedOxygen <= 0f || pollutedDirt <= 0f)
            {
                return 0f;
            }

            float consumed = Mathf.Min(pollutedDirt, emittedPollutedOxygen * PollutedDirtSublimationMassPerPollutedOxygen);
            pollutedDirt = Mathf.Max(0f, pollutedDirt - consumed);
            return consumed;
        }

        private float SublimateLoosePollutedDirt(Vector2Int source, float emittedPollutedOxygen)
        {
            if (emittedPollutedOxygen <= 0f || !IsLoosePollutedDirtOffgasSource(source.x, source.y))
            {
                return 0f;
            }

            float consumed = Mathf.Min(looseResourceAmount[source.x, source.y], emittedPollutedOxygen * PollutedDirtSublimationMassPerPollutedOxygen);
            looseResourceAmount[source.x, source.y] = Mathf.Max(0f, looseResourceAmount[source.x, source.y] - consumed);
            if (looseResourceAmount[source.x, source.y] <= 0.05f)
            {
                looseResourceAmount[source.x, source.y] = 0f;
                looseResourceKind[source.x, source.y] = LooseResourceKind.None;
            }

            return consumed;
        }

        private float PollutedDirtOffgasAvailableMass()
        {
            return pollutedDirt + TotalLoosePollutedDirt();
        }

        private void CollectPollutedDirtOffgasSources(List<Vector2Int> sources)
        {
            sources.Clear();
            bool hasStoredSource = pollutedDirt > PollutedDirtOffgasMinimum;
            Vector2Int storedSource = hasStoredSource ? WasteStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                sources.Add(storedSource);
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsLoosePollutedDirtOffgasSource(x, y) && (!hasStoredSource || storedSource.x != x || storedSource.y != y))
                    {
                        sources.Add(new Vector2Int(x, y));
                    }
                }
            }
        }

        private int CountPollutedDirtOffgasSources()
        {
            if (PollutedDirtOffgasAvailableMass() <= PollutedDirtOffgasMinimum)
            {
                return 0;
            }

            bool hasStoredSource = pollutedDirt > PollutedDirtOffgasMinimum;
            Vector2Int storedSource = hasStoredSource ? WasteStorageCell() : new Vector2Int(-1, -1);
            int count = hasStoredSource ? 1 : 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsLoosePollutedDirtOffgasSource(x, y) && (!hasStoredSource || storedSource.x != x || storedSource.y != y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsPollutedDirtOffgasSource(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            if (IsLoosePollutedDirtOffgasSource(x, y))
            {
                return true;
            }

            if (pollutedDirt <= PollutedDirtOffgasMinimum)
            {
                return false;
            }

            Vector2Int waste = WasteStorageCell();
            return waste.x == x && waste.y == y;
        }

        private bool IsLoosePollutedDirtOffgasSource(int x, int y)
        {
            return IsInside(x, y) &&
                looseResourceKind[x, y] == LooseResourceKind.PollutedDirt &&
                looseResourceAmount[x, y] > LoosePollutedDirtOffgasMinimum;
        }

        private float TotalLoosePollutedDirt()
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (looseResourceKind[x, y] == LooseResourceKind.PollutedDirt)
                    {
                        total += Mathf.Max(0f, looseResourceAmount[x, y]);
                    }
                }
            }

            return total;
        }

        private float CompostablePollutedDirt()
        {
            return pollutedDirt + TotalLoosePollutedDirt();
        }

        private float ConsumePollutedDirtForCompost(Vector2Int compostCell, float amount)
        {
            if (amount <= 0f)
            {
                return 0f;
            }

            float consumed = ConsumeNearestLoosePollutedDirtForCompost(compostCell, amount);
            float remaining = amount - consumed;
            if (remaining > 0.001f && pollutedDirt > 0f)
            {
                float stored = Mathf.Min(pollutedDirt, remaining);
                pollutedDirt = Mathf.Max(0f, pollutedDirt - stored);
                consumed += stored;
            }

            return consumed;
        }

        private float ConsumeNearestLoosePollutedDirtForCompost(Vector2Int compostCell, float amount)
        {
            float consumed = 0f;
            float remaining = amount;
            while (remaining > 0.001f)
            {
                Vector2Int bestCell = new Vector2Int(-1, -1);
                int bestDistance = int.MaxValue;
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        if (looseResourceKind[x, y] != LooseResourceKind.PollutedDirt || looseResourceAmount[x, y] <= 0.05f)
                        {
                            continue;
                        }

                        int distance = Mathf.Abs(x - compostCell.x) + Mathf.Abs(y - compostCell.y);
                        if (distance < bestDistance)
                        {
                            bestDistance = distance;
                            bestCell = new Vector2Int(x, y);
                        }
                    }
                }

                if (bestCell.x < 0)
                {
                    break;
                }

                float taken = Mathf.Min(remaining, looseResourceAmount[bestCell.x, bestCell.y]);
                looseResourceAmount[bestCell.x, bestCell.y] = Mathf.Max(0f, looseResourceAmount[bestCell.x, bestCell.y] - taken);
                if (looseResourceAmount[bestCell.x, bestCell.y] <= 0.05f)
                {
                    looseResourceAmount[bestCell.x, bestCell.y] = 0f;
                    looseResourceKind[bestCell.x, bestCell.y] = LooseResourceKind.None;
                }

                remaining -= taken;
                consumed += taken;
                terrainDirty = true;
                overlayDirty = true;
            }

            return consumed;
        }

        private void SimulateSlimeOffgas(float deltaTime)
        {
            float availableSlime = SlimeOffgasAvailableMass();
            if (deltaTime <= 0f || availableSlime <= SlimeOffgasMinimum)
            {
                return;
            }

            CollectSlimeOffgasSources(slimeOffgasSources);
            if (slimeOffgasSources.Count == 0)
            {
                return;
            }

            float emitted = 0f;
            float sublimated = 0f;
            float sourceScale = 1f / Mathf.Sqrt(Mathf.Max(1, slimeOffgasSources.Count));
            bool hasStoredSource = slime > SlimeOffgasMinimum && !IsSlimeOffgasSuppressed(SlimeStorageCell());
            Vector2Int storedSource = hasStoredSource ? SlimeStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                float pressure = Mathf.Clamp01(slime / 80f);
                float sourceEmitted = VentPollutedOxygen(storedSource, (0.005f + pressure * 0.024f) * deltaTime * sourceScale, (0.040f + pressure * 0.085f) * deltaTime * sourceScale);
                emitted += sourceEmitted;
                sublimated += SublimateStoredSlime(sourceEmitted);
            }

            for (int i = 0; i < slimeOffgasSources.Count; i++)
            {
                Vector2Int source = slimeOffgasSources[i];
                if ((hasStoredSource && storedSource == source) || !IsLooseSlimeOffgasSource(source.x, source.y))
                {
                    continue;
                }

                float localMass = looseResourceAmount[source.x, source.y];
                float pressure = Mathf.Clamp01(localMass / 24f);
                float sourceEmitted = VentPollutedOxygen(source, (0.006f + pressure * 0.026f) * deltaTime * sourceScale, (0.045f + pressure * 0.095f) * deltaTime * sourceScale);
                emitted += sourceEmitted;
                sublimated += SublimateLooseSlime(source, sourceEmitted);
            }

            if (emitted > 0.001f)
            {
                slimeOffgassedMass += emitted;
                slimeOffgasEvents++;
                gasDirty = true;
                overlayDirty = true;
            }

            if (sublimated > 0.001f)
            {
                slimeSublimatedMass += sublimated;
                terrainDirty = true;
                overlayDirty = true;
            }
        }

        private float SublimateStoredSlime(float emittedPollutedOxygen)
        {
            if (emittedPollutedOxygen <= 0f || slime <= 0f)
            {
                return 0f;
            }

            float consumed = Mathf.Min(slime, emittedPollutedOxygen * SlimeSublimationMassPerPollutedOxygen);
            slime = Mathf.Max(0f, slime - consumed);
            return consumed;
        }

        private float SublimateLooseSlime(Vector2Int source, float emittedPollutedOxygen)
        {
            if (emittedPollutedOxygen <= 0f || !IsLooseSlimeOffgasSource(source.x, source.y))
            {
                return 0f;
            }

            float consumed = Mathf.Min(looseResourceAmount[source.x, source.y], emittedPollutedOxygen * SlimeSublimationMassPerPollutedOxygen);
            looseResourceAmount[source.x, source.y] = Mathf.Max(0f, looseResourceAmount[source.x, source.y] - consumed);
            if (looseResourceAmount[source.x, source.y] <= 0.05f)
            {
                looseResourceAmount[source.x, source.y] = 0f;
                looseResourceKind[source.x, source.y] = LooseResourceKind.None;
            }

            return consumed;
        }

        private float SlimeOffgasAvailableMass()
        {
            return slime + TotalLooseSlime();
        }

        private void CollectSlimeOffgasSources(List<Vector2Int> sources)
        {
            sources.Clear();
            bool hasStoredSource = slime > SlimeOffgasMinimum && !IsSlimeOffgasSuppressed(SlimeStorageCell());
            Vector2Int storedSource = hasStoredSource ? SlimeStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                sources.Add(storedSource);
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsLooseSlimeOffgasSource(x, y) && (!hasStoredSource || storedSource.x != x || storedSource.y != y))
                    {
                        sources.Add(new Vector2Int(x, y));
                    }
                }
            }
        }

        private int CountSlimeOffgasSources()
        {
            if (SlimeOffgasAvailableMass() <= SlimeOffgasMinimum)
            {
                return 0;
            }

            int count = 0;
            bool hasStoredSource = slime > SlimeOffgasMinimum && !IsSlimeOffgasSuppressed(SlimeStorageCell());
            Vector2Int storedSource = hasStoredSource ? SlimeStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                count++;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsLooseSlimeOffgasSource(x, y) && (!hasStoredSource || storedSource.x != x || storedSource.y != y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsSlimeOffgasSource(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            if (IsLooseSlimeOffgasSource(x, y))
            {
                return true;
            }

            if (slime <= SlimeOffgasMinimum)
            {
                return false;
            }

            Vector2Int storage = SlimeStorageCell();
            return storage.x == x && storage.y == y && !IsSlimeOffgasSuppressed(storage);
        }

        private bool IsLooseSlimeOffgasSource(int x, int y)
        {
            return IsInside(x, y) &&
                looseResourceKind[x, y] == LooseResourceKind.Slime &&
                looseResourceAmount[x, y] > SlimeOffgasMinimum &&
                !IsSlimeOffgasSuppressed(new Vector2Int(x, y));
        }

        private bool IsSlimeOffgasSuppressed(Vector2Int cell)
        {
            return !IsInside(cell.x, cell.y) ||
                waterMass[cell.x, cell.y] > 1f ||
                ChlorineSterilizationPressure(cell) > SlimeOffgasChlorineSuppression;
        }

        private float TotalLooseSlime()
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (looseResourceKind[x, y] == LooseResourceKind.Slime)
                    {
                        total += Mathf.Max(0f, looseResourceAmount[x, y]);
                    }
                }
            }

            return total;
        }

        private void SimulateBleachStoneOffgas(float deltaTime)
        {
            float availableBleachStone = BleachStoneOffgasAvailableMass();
            if (deltaTime <= 0f || availableBleachStone <= BleachStoneOffgasMinimum)
            {
                return;
            }

            CollectBleachStoneOffgasSources(bleachStoneOffgasSources);
            if (bleachStoneOffgasSources.Count == 0)
            {
                return;
            }

            float emitted = 0f;
            float sublimated = 0f;
            float sourceScale = 1f / Mathf.Sqrt(Mathf.Max(1, bleachStoneOffgasSources.Count));
            bool hasStoredSource = bleachStone > BleachStoneOffgasMinimum && !IsBleachStoneOffgasSuppressed(BleachStoneStorageCell());
            Vector2Int storedSource = hasStoredSource ? BleachStoneStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                float pressure = Mathf.Clamp01(bleachStone / 80f);
                float sourceEmitted = VentChlorine(storedSource, (0.004f + pressure * 0.018f) * deltaTime * sourceScale);
                emitted += sourceEmitted;
                sublimated += SublimateStoredBleachStone(sourceEmitted);
            }

            for (int i = 0; i < bleachStoneOffgasSources.Count; i++)
            {
                Vector2Int source = bleachStoneOffgasSources[i];
                if ((hasStoredSource && storedSource == source) || !IsLooseBleachStoneOffgasSource(source.x, source.y))
                {
                    continue;
                }

                float localMass = looseResourceAmount[source.x, source.y];
                float pressure = Mathf.Clamp01(localMass / 24f);
                float sourceEmitted = VentChlorine(source, (0.005f + pressure * 0.020f) * deltaTime * sourceScale);
                emitted += sourceEmitted;
                sublimated += SublimateLooseBleachStone(source, sourceEmitted);
            }

            if (emitted > 0.001f)
            {
                bleachStoneOffgassedMass += emitted;
                bleachStoneOffgasEvents++;
                gasDirty = true;
                overlayDirty = true;
            }

            if (sublimated > 0.001f)
            {
                bleachStoneSublimatedMass += sublimated;
                terrainDirty = true;
                overlayDirty = true;
            }
        }

        private float SublimateStoredBleachStone(float emittedChlorine)
        {
            if (emittedChlorine <= 0f || bleachStone <= 0f)
            {
                return 0f;
            }

            float consumed = Mathf.Min(bleachStone, emittedChlorine * BleachStoneSublimationMassPerChlorine);
            bleachStone = Mathf.Max(0f, bleachStone - consumed);
            return consumed;
        }

        private float SublimateLooseBleachStone(Vector2Int source, float emittedChlorine)
        {
            if (emittedChlorine <= 0f || !IsLooseBleachStoneOffgasSource(source.x, source.y))
            {
                return 0f;
            }

            float consumed = Mathf.Min(looseResourceAmount[source.x, source.y], emittedChlorine * BleachStoneSublimationMassPerChlorine);
            looseResourceAmount[source.x, source.y] = Mathf.Max(0f, looseResourceAmount[source.x, source.y] - consumed);
            if (looseResourceAmount[source.x, source.y] <= 0.05f)
            {
                looseResourceAmount[source.x, source.y] = 0f;
                looseResourceKind[source.x, source.y] = LooseResourceKind.None;
            }

            return consumed;
        }

        private float BleachStoneOffgasAvailableMass()
        {
            return bleachStone + TotalLooseBleachStone();
        }

        private void CollectBleachStoneOffgasSources(List<Vector2Int> sources)
        {
            sources.Clear();
            bool hasStoredSource = bleachStone > BleachStoneOffgasMinimum && !IsBleachStoneOffgasSuppressed(BleachStoneStorageCell());
            Vector2Int storedSource = hasStoredSource ? BleachStoneStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                sources.Add(storedSource);
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsLooseBleachStoneOffgasSource(x, y) && (!hasStoredSource || storedSource.x != x || storedSource.y != y))
                    {
                        sources.Add(new Vector2Int(x, y));
                    }
                }
            }
        }

        private int CountBleachStoneOffgasSources()
        {
            if (BleachStoneOffgasAvailableMass() <= BleachStoneOffgasMinimum)
            {
                return 0;
            }

            int count = 0;
            bool hasStoredSource = bleachStone > BleachStoneOffgasMinimum && !IsBleachStoneOffgasSuppressed(BleachStoneStorageCell());
            Vector2Int storedSource = hasStoredSource ? BleachStoneStorageCell() : new Vector2Int(-1, -1);
            if (hasStoredSource)
            {
                count++;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsLooseBleachStoneOffgasSource(x, y) && (!hasStoredSource || storedSource.x != x || storedSource.y != y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsBleachStoneOffgasSource(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            if (IsLooseBleachStoneOffgasSource(x, y))
            {
                return true;
            }

            if (bleachStone <= BleachStoneOffgasMinimum)
            {
                return false;
            }

            Vector2Int storage = BleachStoneStorageCell();
            return storage.x == x && storage.y == y && !IsBleachStoneOffgasSuppressed(storage);
        }

        private bool IsLooseBleachStoneOffgasSource(int x, int y)
        {
            return IsInside(x, y) &&
                looseResourceKind[x, y] == LooseResourceKind.BleachStone &&
                looseResourceAmount[x, y] > BleachStoneOffgasMinimum &&
                !IsBleachStoneOffgasSuppressed(new Vector2Int(x, y));
        }

        private bool IsBleachStoneOffgasSuppressed(Vector2Int cell)
        {
            return !IsInside(cell.x, cell.y) || waterMass[cell.x, cell.y] > 1f;
        }

        private float TotalLooseBleachStone()
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (looseResourceKind[x, y] == LooseResourceKind.BleachStone)
                    {
                        total += Mathf.Max(0f, looseResourceAmount[x, y]);
                    }
                }
            }

            return total;
        }

        private void SimulatePollutedWaterOffgas(float deltaTime)
        {
            float availablePollutedWater = PollutedWaterOffgasAvailableMass();
            if (deltaTime <= 0f || availablePollutedWater <= PollutedWaterOffgasMinimum)
            {
                return;
            }

            CollectPollutedWaterOffgasSources(pollutedWaterOffgasSources);
            if (pollutedWaterOffgasSources.Count == 0)
            {
                return;
            }

            float pressure = Mathf.Clamp01(availablePollutedWater / 120f);
            float sourceScale = 1f / Mathf.Sqrt(Mathf.Max(1, pollutedWaterOffgasSources.Count));
            float emitted = 0f;
            for (int i = 0; i < pollutedWaterOffgasSources.Count; i++)
            {
                float sourceGermLevel = PollutedWaterSourceGermLevel(pollutedWaterOffgasSources[i]);
                float amount = (0.0035f + pressure * 0.014f) * deltaTime * sourceScale;
                float germsAdded = (0.008f + pressure * 0.032f + sourceGermLevel * 0.040f) * deltaTime * sourceScale;
                emitted += VentPollutedOxygen(pollutedWaterOffgasSources[i], amount, germsAdded);
            }

            if (emitted > 0.001f)
            {
                pollutedWaterOffgassedMass += emitted;
                pollutedWaterOffgasEvents++;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private void CollectPollutedWaterOffgasSources(List<Vector2Int> sources)
        {
            sources.Clear();
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPollutedWaterOffgasSource(x, y))
                    {
                        sources.Add(new Vector2Int(x, y));
                    }
                }
            }

            if (sources.Count == 0)
            {
                sources.Add(WasteStorageCell());
            }
        }

        private int CountPollutedWaterOffgasSources()
        {
            if (PollutedWaterOffgasAvailableMass() <= PollutedWaterOffgasMinimum)
            {
                return 0;
            }

            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPollutedWaterOffgasSource(x, y))
                    {
                        count++;
                    }
                }
            }

            return Mathf.Max(1, count);
        }

        private bool IsPollutedWaterOffgasSource(int x, int y)
        {
            return IsInside(x, y) && (IsPollutedWorldLiquidAt(x, y) || IsPollutedWaterOffgasSource(cells[x, y]));
        }

        private bool IsPollutedWaterOffgasSource(CellKind kind)
        {
            return kind == CellKind.BottleEmptier ||
                kind == CellKind.AlgaeTerrarium ||
                kind == CellKind.CarbonSkimmer ||
                kind == CellKind.WaterSieve ||
                kind == CellKind.WashBasin;
        }

        private float PollutedWaterOffgasAvailableMass()
        {
            return pollutedWater + TotalWorldPollutedWater();
        }

        private void SimulateFallingSand()
        {
            bool changed = false;
            int moved = 0;
            for (int y = 1; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsFallingSolid(cells[x, y]) || !CanSandFallInto(x, y - 1))
                    {
                        continue;
                    }

                    MoveSandDown(new Vector2Int(x, y), new Vector2Int(x, y - 1));
                    changed = true;
                    moved++;
                }
            }

            if (!changed)
            {
                return;
            }

            sandFalls += moved;
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            if (moved >= 3)
            {
                Log("Unstable loose terrain collapsed " + moved + " tiles.");
            }
        }

        private bool IsFallingSolid(CellKind kind)
        {
            return kind == CellKind.Sand || kind == CellKind.Regolith;
        }

        private bool CanSandFallInto(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.Empty &&
                waterMass[x, y] <= 0.05f &&
                !powerWire[x, y] &&
                !automationWire[x, y] &&
                !liquidPipe[x, y] &&
                !gasPipe[x, y] &&
                !shippingRail[x, y] &&
                (looseResourceKind[x, y] == LooseResourceKind.None || looseResourceAmount[x, y] <= 0.01f);
        }

        private void MoveSandDown(Vector2Int from, Vector2Int to)
        {
            float displacedOxygen = oxygen[to.x, to.y];
            float displacedCarbon = carbonDioxide[to.x, to.y];
            float displacedPolluted = pollutedOxygen[to.x, to.y];
            float displacedHydrogen = hydrogen[to.x, to.y];
            float displacedChlorine = chlorine[to.x, to.y];
            float displacedNaturalGas = naturalGas[to.x, to.y];
            float displacedSourGas = sourGas[to.x, to.y];
            float displacedGerms = germs[to.x, to.y];
            float sourceTemperature = temperature[from.x, from.y];
            float displacedTemperature = temperature[to.x, to.y];

            CellKind fallingKind = cells[from.x, from.y];
            cells[to.x, to.y] = fallingKind;
            cells[from.x, from.y] = CellKind.Empty;
            equipmentCondition[to.x, to.y] = 0f;
            equipmentCondition[from.x, from.y] = 0f;
            plantGrowth[to.x, to.y] = 0f;
            cropTendedSeconds[to.x, to.y] = 0f;
            cropStress[to.x, to.y] = 0f;

            oxygen[from.x, from.y] = displacedOxygen;
            carbonDioxide[from.x, from.y] = displacedCarbon;
            pollutedOxygen[from.x, from.y] = displacedPolluted;
            hydrogen[from.x, from.y] = displacedHydrogen;
            chlorine[from.x, from.y] = displacedChlorine;
            naturalGas[from.x, from.y] = displacedNaturalGas;
            sourGas[from.x, from.y] = displacedSourGas;
            germs[from.x, from.y] = displacedGerms;

            oxygen[to.x, to.y] = 0f;
            carbonDioxide[to.x, to.y] = 0f;
            pollutedOxygen[to.x, to.y] = 0f;
            hydrogen[to.x, to.y] = 0f;
            chlorine[to.x, to.y] = 0f;
            naturalGas[to.x, to.y] = 0f;
            sourGas[to.x, to.y] = 0f;
            germs[to.x, to.y] = 0f;
            temperature[to.x, to.y] = Mathf.Lerp(displacedTemperature, sourceTemperature, 0.75f);
            temperature[from.x, from.y] = Mathf.Lerp(sourceTemperature, displacedTemperature, 0.35f);

            CancelJobsAt(to, false);
            DisplaceWorkersFromFallingSand(from, to);
        }

        private void DisplaceWorkersFromFallingSand(Vector2Int from, Vector2Int to)
        {
            for (int i = 0; i < workers.Count; i++)
            {
                Worker worker = workers[i];
                if (worker == null || worker.Health <= 0f)
                {
                    continue;
                }

                Vector2Int workerCell = worker.Cell;
                if (worker.Transform != null)
                {
                    workerCell = WorldToCell(worker.Transform.position);
                }

                if (workerCell != to)
                {
                    continue;
                }

                sandStrikeInjuries++;
                float damage = worker.LeadSuitEquipped ? 9f * LeadSuitMeteorDamageMultiplier : worker.SuitEquipped ? 4f : 9f;
                worker.Health = Mathf.Max(0f, worker.Health - damage);
                worker.Stress = Mathf.Min(100f, worker.Stress + 12f);
                ClearAssignment(worker);
                worker.Cell = from;
                if (worker.Transform != null)
                {
                    worker.Transform.position = CellCenter(from);
                }

                worker.Activity = "Dodging Falling Sand";
                Log(worker.Name + " was struck by falling sand.");
            }
        }

        private int CountUnstableSandTiles()
        {
            int count = 0;
            for (int y = 1; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsFallingSolid(cells[x, y]) && CanSandFallInto(x, y - 1))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void AddPollutedDirt(float amount, Vector2Int source)
        {
            if (amount <= 0f)
            {
                return;
            }

            pollutedDirt += amount;
            VentPollutedOxygen(source, 0.01f * Mathf.Clamp(amount, 0.1f, 6f), 0.018f * Mathf.Clamp(amount, 0.1f, 6f));
            gasDirty = true;
            overlayDirty = true;
        }

        private Vector2Int FoodWasteCell()
        {
            Vector2Int refrigerator = FirstCellOfKind(CellKind.Refrigerator);
            if (refrigerator.x >= 0)
            {
                return refrigerator;
            }

            Vector2Int rationBox = FirstCellOfKind(CellKind.RationBox);
            if (rationBox.x >= 0)
            {
                return rationBox;
            }

            Vector2Int storage = FirstCellOfKind(CellKind.StorageBin);
            if (storage.x >= 0)
            {
                return storage;
            }

            return WasteStorageCell();
        }

        private Vector2Int SlimeStorageCell()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.StorageBin && StorageFilterAcceptsResource(storageBinFilter[x, y], LooseResourceKind.Slime))
                    {
                        return new Vector2Int(x, y);
                    }
                }
            }

            Vector2Int storage = FirstCellOfKind(CellKind.StorageBin);
            if (storage.x >= 0)
            {
                return storage;
            }

            return WasteStorageCell();
        }

        private Vector2Int BleachStoneStorageCell()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.StorageBin && StorageFilterAcceptsResource(storageBinFilter[x, y], LooseResourceKind.BleachStone))
                    {
                        return new Vector2Int(x, y);
                    }
                }
            }

            Vector2Int storage = FirstCellOfKind(CellKind.StorageBin);
            if (storage.x >= 0)
            {
                return storage;
            }

            return WasteStorageCell();
        }

        private Vector2Int StoredCleanWaterCell()
        {
            Vector2Int bottleEmptier = FirstCellOfKind(CellKind.BottleEmptier);
            if (bottleEmptier.x >= 0)
            {
                return bottleEmptier;
            }

            Vector2Int pump = FirstCellOfKind(CellKind.WaterPump);
            if (pump.x >= 0)
            {
                return pump;
            }

            Vector2Int sieve = FirstCellOfKind(CellKind.WaterSieve);
            if (sieve.x >= 0)
            {
                return sieve;
            }

            if (workers.Count > 0)
            {
                return workers[0].Cell;
            }

            return new Vector2Int(WorldWidth / 2, WorldHeight / 2);
        }

        private Vector2Int WasteStorageCell()
        {
            Vector2Int compost = FirstCellOfKind(CellKind.Compost);
            if (compost.x >= 0)
            {
                return compost;
            }

            Vector2Int outhouse = FirstCellOfKind(CellKind.Outhouse);
            if (outhouse.x >= 0)
            {
                return outhouse;
            }

            if (workers.Count > 0)
            {
                return workers[0].Cell;
            }

            return new Vector2Int(WorldWidth / 2, WorldHeight / 2);
        }

        private Vector2Int FirstCellOfKind(CellKind kind)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == kind)
                    {
                        return new Vector2Int(x, y);
                    }
                }
            }

            return new Vector2Int(-1, -1);
        }

        private float AverageFoodStorageTemperature()
        {
            float total = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsUsableFoodStorageCell(x, y))
                    {
                        continue;
                    }

                    if (cells[x, y] == CellKind.Refrigerator)
                    {
                        total += IsPoweredRefrigeratorAt(x, y) ? 3f : temperature[x, y];
                        count++;
                    }
                    else if (cells[x, y] == CellKind.RationBox)
                    {
                        total += temperature[x, y];
                        count++;
                    }
                }
            }

            return count == 0 ? AverageTemperature() : total / count;
        }

        private float FoodStorageSpoilageFactor(int refrigerators, int poweredRefrigerators)
        {
            float applianceFactor;
            if (poweredRefrigerators > 0)
            {
                applianceFactor = 0.18f;
            }
            else if (refrigerators > 0)
            {
                applianceFactor = 0.78f;
            }
            else
            {
                float rationBoxCoverage = RationBoxFoodCoverage();
                applianceFactor = Mathf.Lerp(1f, RationBoxSpoilageFactor, rationBoxCoverage);
            }

            return Mathf.Clamp(applianceFactor * FoodStorageAtmosphereSpoilageFactor(), 0.05f, 1f);
        }

        private float FoodStorageAtmosphereSpoilageFactor()
        {
            return Mathf.Lerp(1f, FoodSterileAtmosphereSpoilageFactor, AverageFoodStorageSterilityScore());
        }

        private void SimulateFoodGermStorage(float deltaTime, int poweredRefrigerators)
        {
            if (deltaTime <= 0f || food <= 0f)
            {
                return;
            }

            float contaminationScore = AverageFoodStorageContaminationScore();
            float sterilityScore = AverageFoodStorageSterilityScore();
            float chlorineSterilityScore = AverageFoodStorageChlorineSterilityScore();
            foodGerms += contaminationScore * FoodGermStorageGrowthRate * deltaTime;
            foodGerms -= sterilityScore * FoodGermSterileDecayRate * deltaTime;
            if (poweredRefrigerators > 0)
            {
                foodGerms -= FoodGermPoweredRefrigeratorDecayRate * deltaTime;
            }

            if (chlorineSterilityScore > 0f && foodGerms > 0f)
            {
                float chlorineRemoved = Mathf.Min(foodGerms, chlorineSterilityScore * FoodGermChlorineSterilizeRate * deltaTime);
                foodGerms -= chlorineRemoved;
                if (chlorineRemoved > 0.0001f)
                {
                    chlorineSterilizedFoodGerms += chlorineRemoved * Mathf.Max(1f, food / 700f);
                    overlayDirty = true;
                }
            }

            foodGerms = Mathf.Clamp01(foodGerms);
        }

        private float AverageFoodStorageSterilityScore()
        {
            float score = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsUsableFoodStorageCell(x, y))
                    {
                        continue;
                    }

                    score += FoodStorageSterilityScoreAt(x, y);
                    count++;
                }
            }

            if (count == 0)
            {
                return 0f;
            }

            return Mathf.Clamp01(score / count);
        }

        private float AverageFoodStorageChlorineSterilityScore()
        {
            float score = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsUsableFoodStorageCell(x, y))
                    {
                        continue;
                    }

                    score += FoodStorageChlorineSterilityScoreAt(x, y);
                    count++;
                }
            }

            if (count == 0)
            {
                return 0f;
            }

            return Mathf.Clamp01(score / count);
        }

        private float AverageFoodStorageContaminationScore()
        {
            float score = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsUsableFoodStorageCell(x, y))
                    {
                        continue;
                    }

                    score += FoodStorageContaminationScoreAt(x, y);
                    count++;
                }
            }

            if (count == 0)
            {
                return Mathf.Clamp01(0.08f + AverageGas(pollutedOxygen) * 0.08f + AverageGas(germs) * 0.30f);
            }

            return Mathf.Clamp01(score / count);
        }

        private bool IsFoodStorageCell(int x, int y)
        {
            return IsInside(x, y) && (cells[x, y] == CellKind.RationBox || cells[x, y] == CellKind.Refrigerator);
        }

        private bool IsUsableFoodStorageCell(int x, int y)
        {
            if (!IsFoodStorageCell(x, y))
            {
                return false;
            }

            return CanUseEquipment(new Vector2Int(x, y));
        }

        private int CountUsableFoodStorageCells()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsUsableFoodStorageCell(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountUsableRationBoxes()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.RationBox && CanUseEquipment(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private float FoodStorageSterilityScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float pressure = TileGasTotal(x, y);
            if (pressure <= 0.04f)
            {
                return 0.75f;
            }

            float sterileGas = carbonDioxide[x, y] + chlorine[x, y];
            float pressureScore = Mathf.InverseLerp(FoodSterileAtmosphereMinimumPressure, FoodSterileAtmosphereFullPressure, sterileGas);
            float purityScore = Mathf.Clamp01(sterileGas / Mathf.Max(0.001f, pressure));
            float dirtyPenalty = Mathf.Clamp01(pollutedOxygen[x, y] * 1.4f + germs[x, y] * 0.55f);
            return Mathf.Clamp01(Mathf.Min(pressureScore, purityScore * 1.15f) * (1f - dirtyPenalty * 0.45f));
        }

        private float FoodStorageChlorineSterilityScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float pressure = TileGasTotal(x, y);
            if (pressure <= 0.04f || chlorine[x, y] <= ChlorineExposureThreshold)
            {
                return 0f;
            }

            float pressureScore = Mathf.InverseLerp(FoodSterileAtmosphereMinimumPressure, FoodSterileAtmosphereFullPressure, chlorine[x, y]);
            float purityScore = Mathf.Clamp01(chlorine[x, y] / Mathf.Max(0.001f, pressure));
            float dirtyPenalty = Mathf.Clamp01(pollutedOxygen[x, y] * 1.4f + germs[x, y] * 0.55f);
            return Mathf.Clamp01(Mathf.Min(pressureScore, purityScore * 1.15f) * (1f - dirtyPenalty * 0.45f));
        }

        private float FoodStorageContaminationScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float pressure = TileGasTotal(x, y);
            float pollutedGasPurity = pressure <= 0.001f ? 0f : pollutedOxygen[x, y] / pressure;
            float liquidPenalty = IsPollutedWorldLiquidAt(x, y) ? 0.35f : 0f;
            float localGerms = germs[x, y] * 1.15f;
            float pollutedGas = pollutedOxygen[x, y] * 0.18f + pollutedGasPurity * 0.32f;
            return Mathf.Clamp01(localGerms + pollutedGas + liquidPenalty);
        }

        private string FoodStorageAtmosphereText(Vector2Int cell)
        {
            float score = FoodStorageSterilityScoreAt(cell.x, cell.y);
            float chlorineScore = FoodStorageChlorineSterilityScoreAt(cell.x, cell.y);
            string rateText = " Spoilage rate " + Mathf.RoundToInt(FoodStorageSpoilageFactor(CountUsableCells(CellKind.Refrigerator), CountPoweredRefrigerators()) * 100f) + "%. Food contamination " + Mathf.RoundToInt(foodGerms * 100f) + "%. Food sterilized " + chlorineSterilizedFoodGerms.ToString("0.0") + ".";
            if (chlorineScore >= 0.75f)
            {
                return "Chlorine food atmosphere: actively sterilizes stored food and slows spoilage." + rateText;
            }

            if (score >= 0.75f)
            {
                return "Sterile food atmosphere: CO2 or chlorine slows spoilage." + rateText;
            }

            if (score >= 0.35f)
            {
                return "Partly sterile food atmosphere: add more CO2 or chlorine to slow spoilage." + rateText;
            }

            return "Normal food atmosphere: store food in CO2 or chlorine to slow spoilage." + rateText;
        }

        private float RationBoxFoodCoverage()
        {
            if (food <= 0.001f)
            {
                return 0f;
            }

            return Mathf.Clamp01(CountUsableRationBoxes() * RationBoxFoodCapacity / food);
        }

        private int CountPoweredRefrigerators()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPoweredRefrigeratorAt(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsPoweredRefrigeratorAt(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.Refrigerator &&
                CanPoweredMachineRun(new Vector2Int(x, y));
        }

        private void AddHeat(Vector2Int center, float amount, int radius)
        {
            AdjustTemperatureArea(center, Mathf.Abs(amount) * MachineRoomHeatMultiplierAt(center), radius);
        }

        private void CoolArea(Vector2Int center, float amount, int radius)
        {
            AdjustTemperatureArea(center, -Mathf.Abs(amount), radius);
        }

        private void SimulateWheezeworts(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool cooled = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.Wheezewort)
                    {
                        continue;
                    }

                    Vector2Int cell = new Vector2Int(x, y);
                    float localGas = TileGasTotal(x, y);
                    float localTemperature = AverageTemperatureAround(cell, WheezewortCoolingRadius);
                    if (localGas <= 0.04f || localTemperature <= WheezewortDormantTemperature)
                    {
                        continue;
                    }

                    float hydrogenScale = Mathf.Lerp(1f, WheezewortHydrogenCoolingMultiplier, Mathf.Clamp01(HydrogenAround(cell, 2) / Mathf.Max(0.001f, WheezewortHydrogenThreshold * 2f)));
                    float pressureScale = Mathf.Clamp01(localGas / 0.35f);
                    float warmthScale = Mathf.Clamp01((localTemperature - WheezewortDormantTemperature) / 30f);
                    float cooling = WheezewortCoolingRate * deltaTime * hydrogenScale * pressureScale * warmthScale;
                    if (cooling <= 0.001f)
                    {
                        continue;
                    }

                    CoolArea(cell, cooling, WheezewortCoolingRadius);
                    wheezewortCoolingApplied += cooling;
                    cooled = true;
                }
            }

            if (cooled)
            {
                terrainDirty = true;
                overlayDirty = true;
            }
        }

        private void SimulateAntiEntropyThermoNullifiers(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool cooled = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.AntiEntropyThermoNullifier)
                    {
                        continue;
                    }

                    Vector2Int cell = new Vector2Int(x, y);
                    float localTemperature = AverageTemperatureAround(cell, AntiEntropyCoolingRadius);
                    if (localTemperature <= AntiEntropyDormantTemperature)
                    {
                        continue;
                    }

                    float availableHydrogen = AntiEntropyHydrogenAvailable(cell);
                    if (availableHydrogen < AntiEntropyHydrogenThreshold)
                    {
                        continue;
                    }

                    float desiredHydrogen = AntiEntropyHydrogenUseRate * deltaTime;
                    float consumedHydrogen = RemoveHydrogenFuel(cell, desiredHydrogen);
                    if (consumedHydrogen <= 0.001f)
                    {
                        continue;
                    }

                    float fuelScale = Mathf.Clamp01(consumedHydrogen / Mathf.Max(0.001f, desiredHydrogen));
                    float warmthScale = Mathf.Clamp01((localTemperature - AntiEntropyDormantTemperature) / 36f);
                    float cooling = AntiEntropyCoolingRate * deltaTime * fuelScale * warmthScale;
                    if (cooling <= 0.001f)
                    {
                        continue;
                    }

                    CoolArea(cell, cooling, AntiEntropyCoolingRadius);
                    antiEntropyHydrogenConsumed += consumedHydrogen;
                    antiEntropyCoolingApplied += cooling;
                    cooled = true;
                }
            }

            if (cooled)
            {
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private void AdjustTemperatureArea(Vector2Int center, float amount, int radius)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || (!IsPassable(x, y) && !IsWorldLiquidCell(cells[x, y])))
                    {
                        continue;
                    }

                    float distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    float falloff = 1f / (1f + distance);
                    temperature[x, y] = Mathf.Clamp(temperature[x, y] + amount * falloff, -30f, 120f);
                }
            }
        }

        private float AverageTemperatureAround(Vector2Int center, int radius)
        {
            float total = 0f;
            int count = 0;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && (IsPassable(x, y) || IsWorldLiquidCell(cells[x, y])))
                    {
                        total += temperature[x, y];
                        count++;
                    }
                }
            }

            return count == 0 ? temperature[center.x, center.y] : total / count;
        }

        private void AddOxygen(Vector2Int center, float amount)
        {
            float share = amount / 9f;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (IsInside(x, y) && IsPassable(x, y))
                    {
                        oxygen[x, y] = Mathf.Min(2.2f, oxygen[x, y] + share);
                    }
                }
            }
        }

        private float AddAirborneGerms(Vector2Int center, float amount)
        {
            if (amount <= 0f)
            {
                return 0f;
            }

            float share = amount / 9f;
            float added = 0f;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    float before = germs[x, y];
                    germs[x, y] = Mathf.Clamp01(germs[x, y] + share);
                    added += Mathf.Max(0f, germs[x, y] - before);
                }
            }

            return added;
        }

        private void AddHydrogen(Vector2Int center, float amount)
        {
            float share = amount / 6f;
            Vector2Int[] offsets =
            {
                new Vector2Int(0, 1),
                new Vector2Int(1, 1),
                new Vector2Int(-1, 1),
                new Vector2Int(0, 0),
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0)
            };

            foreach (Vector2Int offset in offsets)
            {
                int x = center.x + offset.x;
                int y = center.y + offset.y;
                if (IsInside(x, y) && IsPassable(x, y))
                {
                    hydrogen[x, y] = Mathf.Min(2.8f, hydrogen[x, y] + share);
                }
            }
        }

        private void StepGas(float deltaTime)
        {
            Array.Copy(oxygen, nextOxygen, oxygen.Length);
            Array.Copy(carbonDioxide, nextCarbonDioxide, carbonDioxide.Length);
            Array.Copy(pollutedOxygen, nextPollutedOxygen, pollutedOxygen.Length);
            Array.Copy(hydrogen, nextHydrogen, hydrogen.Length);
            Array.Copy(steam, nextSteam, steam.Length);
            Array.Copy(chlorine, nextChlorine, chlorine.Length);
            Array.Copy(naturalGas, nextNaturalGas, naturalGas.Length);
            Array.Copy(sourGas, nextSourGas, sourGas.Length);

            float flowRate = Mathf.Clamp01(deltaTime * 0.75f);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    float gasMass = TileGasTotal(x, y);
                    nextGermMass[x, y] = Mathf.Clamp01(germs[x, y]) * gasMass;
                    nextGasHeat[x, y] = temperature[x, y] * gasMass;
                    if (!IsGasExchangeCell(x, y))
                    {
                        nextOxygen[x, y] = 0f;
                        nextCarbonDioxide[x, y] = 0f;
                        nextPollutedOxygen[x, y] = 0f;
                        nextHydrogen[x, y] = 0f;
                        nextSteam[x, y] = 0f;
                        nextChlorine[x, y] = 0f;
                        nextNaturalGas[x, y] = 0f;
                        nextSourGas[x, y] = 0f;
                        nextGermMass[x, y] = 0f;
                        nextGasHeat[x, y] = 0f;
                        continue;
                    }
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsGasExchangeCell(x, y))
                    {
                        continue;
                    }

                    EqualizeGas(x, y, x + 1, y, flowRate);
                    EqualizeGas(x, y, x, y + 1, flowRate);
                }
            }

            for (int y = 1; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsGasExchangeCell(x, y) || !IsGasExchangeCell(x, y - 1))
                    {
                        continue;
                    }

                    float settlingFactor = Mathf.Min(TileGasPermeability(x, y), TileGasPermeability(x, y - 1));
                    float settle = Mathf.Min(nextCarbonDioxide[x, y] * 0.045f * deltaTime * settlingFactor, 0.05f);
                    MoveNextGasGerms(x, y, x, y - 1, settle);
                    MoveNextGasHeat(x, y, x, y - 1, settle);
                    nextCarbonDioxide[x, y] -= settle;
                    nextCarbonDioxide[x, y - 1] += settle;
                    float chlorineSettle = Mathf.Min(nextChlorine[x, y] * 0.032f * deltaTime * settlingFactor, 0.04f);
                    MoveNextGasGerms(x, y, x, y - 1, chlorineSettle);
                    MoveNextGasHeat(x, y, x, y - 1, chlorineSettle);
                    nextChlorine[x, y] -= chlorineSettle;
                    nextChlorine[x, y - 1] += chlorineSettle;
                    float sourGasSettle = Mathf.Min(nextSourGas[x, y] * 0.038f * deltaTime * settlingFactor, 0.045f);
                    MoveNextGasGerms(x, y, x, y - 1, sourGasSettle);
                    MoveNextGasHeat(x, y, x, y - 1, sourGasSettle);
                    nextSourGas[x, y] -= sourGasSettle;
                    nextSourGas[x, y - 1] += sourGasSettle;
                }
            }

            for (int y = 0; y < WorldHeight - 1; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsGasExchangeCell(x, y) || !IsGasExchangeCell(x, y + 1))
                    {
                        continue;
                    }

                    float liftFactor = Mathf.Min(TileGasPermeability(x, y), TileGasPermeability(x, y + 1));
                    float lift = Mathf.Min(nextHydrogen[x, y] * 0.060f * deltaTime * liftFactor, 0.06f);
                    MoveNextGasGerms(x, y, x, y + 1, lift);
                    MoveNextGasHeat(x, y, x, y + 1, lift);
                    nextHydrogen[x, y] -= lift;
                    nextHydrogen[x, y + 1] += lift;

                    float steamLift = Mathf.Min(nextSteam[x, y] * 0.035f * deltaTime * liftFactor, 0.045f);
                    MoveNextGasGerms(x, y, x, y + 1, steamLift);
                    MoveNextGasHeat(x, y, x, y + 1, steamLift);
                    nextSteam[x, y] -= steamLift;
                    nextSteam[x, y + 1] += steamLift;

                    float naturalGasLift = Mathf.Min(nextNaturalGas[x, y] * 0.032f * deltaTime * liftFactor, 0.04f);
                    MoveNextGasGerms(x, y, x, y + 1, naturalGasLift);
                    MoveNextGasHeat(x, y, x, y + 1, naturalGasLift);
                    nextNaturalGas[x, y] -= naturalGasLift;
                    nextNaturalGas[x, y + 1] += naturalGasLift;
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    oxygen[x, y] = Mathf.Clamp(nextOxygen[x, y], 0f, 2.8f);
                    carbonDioxide[x, y] = Mathf.Clamp(nextCarbonDioxide[x, y], 0f, 2.8f);
                    pollutedOxygen[x, y] = Mathf.Clamp(nextPollutedOxygen[x, y], 0f, 2.8f);
                    hydrogen[x, y] = Mathf.Clamp(nextHydrogen[x, y], 0f, 2.8f);
                    steam[x, y] = Mathf.Clamp(nextSteam[x, y], 0f, 2.8f);
                    chlorine[x, y] = Mathf.Clamp(nextChlorine[x, y], 0f, 2.8f);
                    naturalGas[x, y] = Mathf.Clamp(nextNaturalGas[x, y], 0f, 2.8f);
                    sourGas[x, y] = Mathf.Clamp(nextSourGas[x, y], 0f, 2.8f);
                    float gasTotal = TileGasTotal(x, y);
                    nextGerms[x, y] = gasTotal <= 0.001f ? 0f : Mathf.Clamp01(nextGermMass[x, y] / gasTotal);
                    float sterilized = Mathf.Min(nextGerms[x, y], chlorine[x, y] * ChlorineSterilizeRate * deltaTime);
                    if (sterilized > 0.0001f)
                    {
                        chlorineSterilizedGerms += sterilized;
                    }

                    nextGerms[x, y] = gasTotal <= 0.001f ? 0f : Mathf.Max(0f, nextGerms[x, y] - sterilized);
                    germs[x, y] = IsGasExchangeCell(x, y) ? Mathf.Clamp01(nextGerms[x, y] - 0.012f * deltaTime) : germs[x, y];
                    if (IsGasExchangeCell(x, y) && gasTotal > 0.001f)
                    {
                        float gasTemperature = Mathf.Clamp(nextGasHeat[x, y] / gasTotal, -30f, 120f);
                        float gasInfluence = Mathf.Clamp01(gasTotal / 2.8f) * 0.35f;
                        temperature[x, y] = Mathf.Lerp(temperature[x, y], gasTemperature, gasInfluence);
                    }
                }
            }
        }

        private void StepTemperature(float deltaTime)
        {
            Array.Copy(temperature, nextTemperature, temperature.Length);

            float rate = Mathf.Clamp01(deltaTime * 0.38f);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    EqualizeTemperature(x, y, x + 1, y, rate);
                    EqualizeTemperature(x, y, x, y + 1, rate);
                }
            }

            ApplyTempshiftPlates(deltaTime);

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    float value = nextTemperature[x, y];
                    if (cells[x, y] == CellKind.Magma)
                    {
                        value = MagmaTemperature;
                    }
                    else if (y <= 2 && cells[x, y] == CellKind.Rock)
                    {
                        value = Mathf.MoveTowards(value, 68f, 0.18f * deltaTime);
                    }
                    else if (y >= 40 && IsPassable(x, y))
                    {
                        value = Mathf.MoveTowards(value, -8f, 0.1f * deltaTime);
                    }

                    if (cells[x, y] == CellKind.Ice && value > 1f)
                    {
                        MeltIceCell(x, y, value);
                        value = temperature[x, y];
                    }
                    else if (IsWorldLiquidCell(cells[x, y]) && value < LiquidFreezeTemperatureAt(x, y))
                    {
                        FreezeWaterCell(x, y, value);
                        value = temperature[x, y];
                    }

                    float boilTemperature = LiquidBoilTemperatureAt(x, y);
                    if (HasWorldLiquidAt(x, y) && waterMass[x, y] > LiquidMinimumRetainedMass && value > boilTemperature)
                    {
                        if (IsPetroleumWorldLiquidAt(x, y))
                        {
                            VaporizePetroleumCell(x, y, value, deltaTime);
                        }
                        else
                        {
                            EvaporateWaterCell(x, y, value, deltaTime);
                        }

                        value = temperature[x, y];
                    }
                    else if (steam[x, y] > 0.02f && value < SteamCondensationTemperature)
                    {
                        CondenseSteamCell(x, y, value, deltaTime);
                        value = temperature[x, y];
                    }

                    temperature[x, y] = Mathf.Clamp(value, -30f, 120f);
                }
            }
        }

        private void SimulateMagmaHeat(float deltaTime)
        {
            if (deltaTime <= 0f || CountCells(CellKind.Magma) == 0)
            {
                return;
            }

            float transferred = 0f;
            float flashed = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.Magma)
                    {
                        continue;
                    }

                    temperature[x, y] = MagmaTemperature;
                    for (int dy = -2; dy <= 2; dy++)
                    {
                        for (int dx = -2; dx <= 2; dx++)
                        {
                            int tx = x + dx;
                            int ty = y + dy;
                            if (!IsInside(tx, ty) || (dx == 0 && dy == 0) || cells[tx, ty] == CellKind.Magma)
                            {
                                continue;
                            }

                            int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                            if (distance > 3)
                            {
                                continue;
                            }

                            float falloff = 1f / (distance + 1f);
                            float heat = MagmaHeatRate * deltaTime * falloff;
                            float capacity = Mathf.Max(0.1f, ThermalCapacityAt(tx, ty));
                            temperature[tx, ty] = Mathf.Clamp(temperature[tx, ty] + heat / capacity, -30f, MagmaTemperature);
                            transferred += heat;
                            TryFlashMagmaSteam(tx, ty, deltaTime * falloff, ref flashed);
                        }
                    }
                }
            }

            if (transferred > 0.001f || flashed > 0.001f)
            {
                magmaHeatTransferred += transferred;
                magmaSteamFlashed += flashed;
                terrainDirty = true;
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private void SimulateCrudeOilThermalCracking(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            float cracked = 0f;
            float petroleumProduced = 0f;
            float naturalGasProduced = 0f;
            Vector2Int firstCracked = new Vector2Int(-1, -1);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsCrudeOilWorldLiquidAt(x, y) ||
                        temperature[x, y] < CrudeOilThermalCrackingTemperature ||
                        waterMass[x, y] <= LiquidMinimumRetainedMass)
                    {
                        continue;
                    }

                    Vector2Int source = new Vector2Int(x, y);
                    float crudeMass = waterMass[x, y];
                    float petroleumMass = Mathf.Min(LiquidTileCapacity, crudeMass * CrudeOilThermalPetroleumYield);
                    float naturalGasMass = Mathf.Max(0f, crudeMass * CrudeOilThermalNaturalGasYield);
                    cells[x, y] = CellKind.Petroleum;
                    waterMass[x, y] = petroleumMass;
                    equipmentCondition[x, y] = 0f;
                    germs[x, y] = 0f;
                    temperature[x, y] = Mathf.Clamp(Mathf.Max(CrudeOilThermalCrackingTemperature, temperature[x, y] - naturalGasMass * 0.25f), -30f, 120f);

                    float ventedNaturalGasMass = 0f;
                    if (naturalGasMass > 0.001f && TryFindSteamOutput(source, out Vector2Int output))
                    {
                        AddGasToTile(output.x, output.y, 0f, 0f, 0f, 0f, 0f, naturalGasMass, 0f, temperature[x, y]);
                        temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], temperature[x, y]), -30f, 120f);
                        ventedNaturalGasMass = naturalGasMass;
                    }

                    cracked += crudeMass;
                    petroleumProduced += petroleumMass;
                    naturalGasProduced += ventedNaturalGasMass;
                    if (firstCracked.x < 0)
                    {
                        firstCracked = source;
                    }
                }
            }

            if (cracked <= 0.001f)
            {
                return;
            }

            crudeOilThermallyCracked += cracked;
            thermalPetroleumProduced += petroleumProduced;
            thermalCrackingNaturalGasVented += naturalGasProduced;
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            if (firstCracked.x >= 0)
            {
                Log("Hot crude oil cracked into petroleum at " + firstCracked.x + ", " + firstCracked.y + ".");
            }
        }

        private void TryFlashMagmaSteam(int x, int y, float deltaTime, ref float flashed)
        {
            if (!HasWorldLiquidAt(x, y) || IsCrudeOilWorldLiquidAt(x, y) || IsPetroleumWorldLiquidAt(x, y) || waterMass[x, y] <= LiquidMinimumRetainedMass)
            {
                return;
            }

            float boilTemperature = LiquidBoilTemperatureAt(x, y);
            if (temperature[x, y] < boilTemperature - 0.5f)
            {
                return;
            }

            Vector2Int source = new Vector2Int(x, y);
            if (!TryFindSteamOutput(source, out Vector2Int output))
            {
                return;
            }

            float amount = Mathf.Min(waterMass[x, y], MagmaSteamFlashRate * deltaTime);
            float free = Mathf.Max(0f, 2.8f - TileGasTotal(output.x, output.y));
            amount = Mathf.Min(amount, free);
            if (amount <= 0.001f)
            {
                return;
            }

            bool polluted = IsPollutedWorldLiquidAt(x, y);
            waterMass[x, y] = Mathf.Max(0f, waterMass[x, y] - amount);
            float added = AddSteamToTile(output, amount);
            if (added <= 0.001f)
            {
                return;
            }

            flashed += added;
            steamEvaporatedMass += added;
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], boilTemperature + 2f), -30f, MagmaTemperature);
            temperature[x, y] = Mathf.Clamp(Mathf.Max(temperature[x, y], boilTemperature), -30f, MagmaTemperature);
            if (polluted)
            {
                VentPollutedOxygen(output, added * 0.004f, added * 0.012f);
            }

            if (waterMass[x, y] <= LiquidMinimumRetainedMass)
            {
                DryWaterCell(source, 0.02f, 0.02f, polluted ? 0.04f : 0f, 0f, 0f, 0f, polluted ? 0.08f : 0f, boilTemperature);
            }
        }

        private void MeltIceCell(int x, int y, float temperatureValue)
        {
            cells[x, y] = CellKind.Water;
            waterMass[x, y] = 35f;
            equipmentCondition[x, y] = 0f;
            oxygen[x, y] = 0f;
            carbonDioxide[x, y] = 0f;
            pollutedOxygen[x, y] = 0f;
            hydrogen[x, y] = 0f;
            steam[x, y] = 0f;
            chlorine[x, y] = 0f;
            naturalGas[x, y] = 0f;
            sourGas[x, y] = 0f;
            germs[x, y] = 0f;
            powerWire[x, y] = false;
            powerWireKind[x, y] = PowerWireKind.Normal;
            poweredWire[x, y] = false;
            iceMeltedTiles++;
            temperature[x, y] = Mathf.Clamp(Mathf.Max(1.2f, temperatureValue), -30f, 120f);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private void FreezeWaterCell(int x, int y, float temperatureValue)
        {
            Vector2Int cell = new Vector2Int(x, y);
            cells[x, y] = CellKind.Ice;
            waterMass[x, y] = 0f;
            equipmentCondition[x, y] = 0f;
            plantGrowth[x, y] = 0f;
            cropTendedSeconds[x, y] = 0f;
            cropStress[x, y] = 0f;
            oxygen[x, y] = 0f;
            carbonDioxide[x, y] = 0f;
            pollutedOxygen[x, y] = 0f;
            hydrogen[x, y] = 0f;
            steam[x, y] = 0f;
            chlorine[x, y] = 0f;
            naturalGas[x, y] = 0f;
            sourGas[x, y] = 0f;
            germs[x, y] = 0f;
            looseResourceKind[x, y] = LooseResourceKind.None;
            looseResourceAmount[x, y] = 0f;
            powerWire[x, y] = false;
            powerWireKind[x, y] = PowerWireKind.Normal;
            poweredWire[x, y] = false;
            wireLoad[x, y] = 0f;
            overloadedWire[x, y] = false;
            wireOverloadStress[x, y] = 0f;
            automationWire[x, y] = false;
            automationControlledWire[x, y] = false;
            automationSignalWire[x, y] = false;
            liquidPipe[x, y] = false;
            liquidPipeKind[x, y] = LiquidPipeKind.Normal;
            pipeWater[x, y] = 0f;
            pipeWaterGerms[x, y] = 0f;
            pipePollutedWater[x, y] = 0f;
            pipePollutedWaterGerms[x, y] = 0f;
            pipePetroleum[x, y] = 0f;
            gasPipe[x, y] = false;
            gasPipeKind[x, y] = GasPipeKind.Normal;
            gasPipeOxygen[x, y] = 0f;
            gasPipeCarbonDioxide[x, y] = 0f;
            gasPipePollutedOxygen[x, y] = 0f;
            gasPipeHydrogen[x, y] = 0f;
            gasPipeSteam[x, y] = 0f;
            gasPipeChlorine[x, y] = 0f;
            gasPipeNaturalGas[x, y] = 0f;
            gasPipeSourGas[x, y] = 0f;
            gasPipeGerms[x, y] = 0f;
            shippingRail[x, y] = false;
            shippingRailKind[x, y] = LooseResourceKind.None;
            shippingRailAmount[x, y] = 0f;
            shippingRailMeterFlowRemaining[x, y] = 0f;
            waterFrozenTiles++;
            temperature[x, y] = Mathf.Clamp(Mathf.Min(-1.2f, temperatureValue), -30f, 120f);
            CancelJobsAt(cell, false);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private void EvaporateWaterCell(int x, int y, float temperatureValue, float deltaTime)
        {
            if (!HasWorldLiquidAt(x, y))
            {
                return;
            }

            Vector2Int source = new Vector2Int(x, y);
            Vector2Int output;
            if (!TryFindSteamOutput(source, out output))
            {
                return;
            }

            bool polluted = IsPollutedWorldLiquidAt(x, y);
            float boilTemperature = LiquidBoilTemperatureAt(x, y);
            float heatDrive = Mathf.Max(0f, temperatureValue - boilTemperature);
            float requested = heatDrive * WaterEvaporationRate * deltaTime;
            float outputFree = Mathf.Max(0f, 2.8f - TileGasTotal(output.x, output.y));
            float amount = Mathf.Min(Mathf.Min(waterMass[x, y], requested), outputFree);
            if (amount <= 0.001f)
            {
                return;
            }

            waterMass[x, y] = Mathf.Max(0f, waterMass[x, y] - amount);
            if (waterMass[x, y] <= LiquidMinimumRetainedMass)
            {
                if (IsWorldLiquidCell(cells[x, y]))
                {
                    DryWaterCell(source, 0.04f, 0.02f, polluted ? 0.08f : 0f, 0f, 0f, 0f, polluted ? 0.15f : 0f, Mathf.Min(temperatureValue, boilTemperature));
                }
                else
                {
                    waterMass[x, y] = 0f;
                }
            }

            float added = AddSteamToTile(output, amount);
            if (added <= 0.001f)
            {
                return;
            }

            steamEvaporatedMass += added;
            if (polluted)
            {
                VentPollutedOxygen(output, added * 0.006f, added * 0.020f);
            }

            temperature[x, y] = Mathf.Clamp(temperatureValue - added * 0.8f, -30f, 120f);
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], boilTemperature + added * 0.25f), -30f, 120f);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private void VaporizePetroleumCell(int x, int y, float temperatureValue, float deltaTime)
        {
            if (!IsPetroleumWorldLiquidAt(x, y))
            {
                return;
            }

            Vector2Int source = new Vector2Int(x, y);
            if (!TryFindSteamOutput(source, out Vector2Int output))
            {
                return;
            }

            float heatDrive = Mathf.Max(0f, temperatureValue - PetroleumEvaporationTemperature);
            float requested = heatDrive * PetroleumVaporizationRate * deltaTime;
            float gasFree = Mathf.Max(0f, 2.8f - TileGasTotal(output.x, output.y));
            float sourGasFree = Mathf.Max(0f, 2.8f - sourGas[output.x, output.y]);
            float capacity = Mathf.Min(gasFree, sourGasFree) / Mathf.Max(0.001f, PetroleumVaporizationSourGasYield);
            float amount = Mathf.Min(waterMass[x, y], requested, capacity);
            if (amount <= 0.001f)
            {
                return;
            }

            waterMass[x, y] = Mathf.Max(0f, waterMass[x, y] - amount);
            if (waterMass[x, y] <= LiquidMinimumRetainedMass)
            {
                DryWaterCell(source, 0.02f, 0.02f, 0f, 0f, 0f, 0f, 0f, Mathf.Min(temperatureValue, PetroleumEvaporationTemperature));
            }

            float sourGasAmount = amount * PetroleumVaporizationSourGasYield;
            AddGasToTileWithSteam(output.x, output.y, 0f, 0f, 0f, 0f, 0f, 0f, 0f, 0f, temperatureValue, sourGasAmount);
            petroleumVaporizedMass += amount;
            petroleumVaporizedSourGas += sourGasAmount;
            temperature[x, y] = Mathf.Clamp(temperatureValue - amount * 0.65f, -30f, 120f);
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], PetroleumEvaporationTemperature + sourGasAmount * 0.2f), -30f, 120f);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private float LiquidBoilTemperatureAt(int x, int y)
        {
            if (IsCrudeOilWorldLiquidAt(x, y))
            {
                return 260f;
            }

            if (IsPetroleumWorldLiquidAt(x, y))
            {
                return PetroleumEvaporationTemperature;
            }

            return IsSaltWaterWorldLiquidAt(x, y) ? SaltWaterEvaporationTemperature : cells[x, y] == CellKind.PollutedWater || IsPollutedWorldLiquidAt(x, y) ? PollutedWaterEvaporationTemperature : WaterEvaporationTemperature;
        }

        private float LiquidFreezeTemperatureAt(int x, int y)
        {
            if (IsCrudeOilWorldLiquidAt(x, y))
            {
                return -40f;
            }

            if (IsPetroleumWorldLiquidAt(x, y))
            {
                return PetroleumFreezeTemperature;
            }

            return IsSaltWaterWorldLiquidAt(x, y) ? SaltWaterFreezeTemperature : cells[x, y] == CellKind.PollutedWater || IsPollutedWorldLiquidAt(x, y) ? PollutedWaterFreezeTemperature : PipeFreezeTemperature;
        }

        private void CondenseSteamCell(int x, int y, float temperatureValue, float deltaTime)
        {
            if (!IsPassable(x, y) || steam[x, y] <= 0.001f)
            {
                return;
            }

            Vector2Int source = new Vector2Int(x, y);
            Vector2Int output;
            if (!TryFindCondensateOutput(source, out output))
            {
                return;
            }

            float chillDrive = Mathf.Max(0f, SteamCondensationTemperature - temperatureValue);
            float requested = chillDrive * SteamCondensationRate * deltaTime;
            float amount = Mathf.Min(Mathf.Min(steam[x, y], requested), LiquidFreeCapacity(output.x, output.y));
            if (amount <= 0.001f)
            {
                return;
            }

            steam[x, y] = Mathf.Max(0f, steam[x, y] - amount);
            ReleaseWaterToCell(output, amount);
            temperature[output.x, output.y] = Mathf.Clamp(Mathf.Max(temperature[output.x, output.y], temperatureValue + amount * 1.4f), -30f, 120f);
            temperature[x, y] = Mathf.Clamp(temperatureValue + amount * 0.8f, -30f, 120f);
            steamCondensedMass += amount;
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private bool TryFindSteamOutput(Vector2Int source, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                source,
                new Vector2Int(source.x, source.y + 1),
                new Vector2Int(source.x + 1, source.y + 1),
                new Vector2Int(source.x - 1, source.y + 1),
                new Vector2Int(source.x + 1, source.y),
                new Vector2Int(source.x - 1, source.y),
                new Vector2Int(source.x, source.y + 2),
                new Vector2Int(source.x, source.y - 1)
            };

            float bestPressure = float.MaxValue;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !IsPassable(candidate.x, candidate.y))
                {
                    continue;
                }

                float pressure = TileGasTotal(candidate.x, candidate.y);
                if (pressure >= 2.78f || pressure >= bestPressure)
                {
                    continue;
                }

                bestPressure = pressure;
                output = candidate;
            }

            return output.x >= 0;
        }

        private bool TryFindCondensateOutput(Vector2Int source, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                source,
                new Vector2Int(source.x, source.y - 1),
                new Vector2Int(source.x + 1, source.y),
                new Vector2Int(source.x - 1, source.y),
                new Vector2Int(source.x, source.y + 1)
            };

            float bestMass = float.MaxValue;
            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !CanLiquidOccupy(candidate.x, candidate.y))
                {
                    continue;
                }

                float free = LiquidFreeCapacity(candidate.x, candidate.y);
                float mass = LiquidMassAt(candidate.x, candidate.y);
                if (free <= LiquidMinimumRetainedMass || mass >= bestMass)
                {
                    continue;
                }

                bestMass = mass;
                output = candidate;
            }

            return output.x >= 0;
        }

        private float AddSteamToTile(Vector2Int cell, float amount)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y) || amount <= 0f)
            {
                return 0f;
            }

            float free = Mathf.Max(0f, 2.8f - TileGasTotal(cell.x, cell.y));
            float added = Mathf.Min(amount, free);
            if (added <= 0.001f)
            {
                return 0f;
            }

            steam[cell.x, cell.y] = Mathf.Min(2.8f, steam[cell.x, cell.y] + added);
            return added;
        }

        private int CountMeltingIceTiles()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.Ice && temperature[x, y] > 1f)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountFreezingWaterTiles()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsWorldLiquidCell(cells[x, y]) && temperature[x, y] < LiquidFreezeTemperatureAt(x, y))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void EqualizeTemperature(int ax, int ay, int bx, int by, float rate)
        {
            if (!IsInside(bx, by))
            {
                return;
            }

            float conductivity = Mathf.Min(TileThermalConductivity(ax, ay), TileThermalConductivity(bx, by));
            if (conductivity <= 0f)
            {
                return;
            }

            float flow = (temperature[ax, ay] - temperature[bx, by]) * conductivity * rate;
            nextTemperature[ax, ay] -= flow / ThermalCapacityAt(ax, ay);
            nextTemperature[bx, by] += flow / ThermalCapacityAt(bx, by);
        }

        private void ApplyTempshiftPlates(float deltaTime)
        {
            float rate = Mathf.Clamp01(deltaTime * TempshiftPlateExchangeRate);
            if (rate <= 0f)
            {
                return;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.TempshiftPlate)
                    {
                        ApplyTempshiftPlateAt(x, y, rate);
                    }
                }
            }
        }

        private void ApplyTempshiftPlateAt(int centerX, int centerY, float rate)
        {
            float totalHeat = 0f;
            float totalCapacity = 0f;
            for (int y = centerY - TempshiftPlateRadius; y <= centerY + TempshiftPlateRadius; y++)
            {
                for (int x = centerX - TempshiftPlateRadius; x <= centerX + TempshiftPlateRadius; x++)
                {
                    if (!IsInside(x, y))
                    {
                        continue;
                    }

                    float capacity = Mathf.Max(0.1f, ThermalCapacityAt(x, y));
                    totalHeat += temperature[x, y] * capacity;
                    totalCapacity += capacity;
                }
            }

            if (totalCapacity <= 0f)
            {
                return;
            }

            float targetTemperature = totalHeat / totalCapacity;
            for (int y = centerY - TempshiftPlateRadius; y <= centerY + TempshiftPlateRadius; y++)
            {
                for (int x = centerX - TempshiftPlateRadius; x <= centerX + TempshiftPlateRadius; x++)
                {
                    if (!IsInside(x, y))
                    {
                        continue;
                    }

                    float conductivityFactor = Mathf.Clamp01(TileThermalConductivity(x, y) / 0.30f);
                    if (conductivityFactor <= 0.001f)
                    {
                        continue;
                    }

                    float distance = Mathf.Max(Mathf.Abs(x - centerX), Mathf.Abs(y - centerY));
                    float falloff = 1f - 0.14f * distance;
                    nextTemperature[x, y] += (targetTemperature - temperature[x, y]) * rate * falloff * conductivityFactor;
                }
            }
        }

        private float ThermalConductivity(CellKind kind)
        {
            switch (kind)
            {
                case CellKind.Empty:
                    return 0.08f;
                case CellKind.Water:
                case CellKind.PollutedWater:
                    return 0.18f;
                case CellKind.Ice:
                    return 0.16f;
                case CellKind.InsulatedTile:
                    return 0.018f;
                case CellKind.Tile:
                    return 0.16f;
                case CellKind.AirflowTile:
                    return 0.28f;
                case CellKind.MeshTile:
                    return 0.30f;
                case CellKind.HydroponicFarm:
                    return 0.22f;
                case CellKind.Wheezewort:
                    return 0.24f;
                case CellKind.AntiEntropyThermoNullifier:
                    return 0.34f;
                case CellKind.TempshiftPlate:
                    return 0.68f;
                case CellKind.Regolith:
                    return 0.10f;
                case CellKind.Magma:
                    return 0.46f;
                case CellKind.MetalOre:
                case CellKind.Battery:
                case CellKind.JumboBattery:
                case CellKind.PowerControlStation:
                case CellKind.ManualGenerator:
                case CellKind.CoalGenerator:
                case CellKind.HydrogenGenerator:
                case CellKind.NaturalGasGenerator:
                case CellKind.PetroleumGenerator:
                case CellKind.SteamTurbine:
                case CellKind.SolarPanel:
                case CellKind.BunkerDoor:
                case CellKind.SpaceScanner:
                case CellKind.VentAnalyzer:
                case CellKind.RocketPlatform:
                case CellKind.ArcadeCabinet:
                case CellKind.OrbitalDataBank:
                case CellKind.HydrogenFilter:
                case CellKind.GasFilter:
                case CellKind.SourGasCondenser:
                case CellKind.LiquidFilter:
                case CellKind.RockCrusher:
                case CellKind.MetalRefinery:
                case CellKind.OxygenMaskDock:
                case CellKind.OxygenMaskCheckpoint:
                case CellKind.AtmoSuitDock:
                case CellKind.AtmoSuitCheckpoint:
                case CellKind.ThermoAquatuner:
                case CellKind.LiquidReservoir:
                case CellKind.GasReservoir:
                case CellKind.LiquidBridge:
                case CellKind.GasBridge:
                case CellKind.ShippingBridge:
                case CellKind.HighPressureGasVent:
                case CellKind.AutomationBridge:
                case CellKind.AutomationNotGate:
                case CellKind.AutomationAndGate:
                case CellKind.AutomationOrGate:
                case CellKind.AutomationXorGate:
                case CellKind.AutomationBufferGate:
                case CellKind.AutomationFilterGate:
                case CellKind.AutomationMemoryGate:
                case CellKind.AutomationCycleSensor:
                case CellKind.AutomationTimerSensor:
                case CellKind.DuplicantMotionSensor:
                case CellKind.GermSensor:
                case CellKind.WeightPlate:
                case CellKind.PowerBridge:
                case CellKind.PowerShutoff:
                case CellKind.LiquidPipeSensor:
                case CellKind.LiquidShutoff:
                case CellKind.LiquidValve:
                case CellKind.GasPipeSensor:
                case CellKind.GasShutoff:
                case CellKind.GasValve:
                case CellKind.ShippingRailSensor:
                case CellKind.ShippingRailShutoff:
                case CellKind.ShippingRailMeter:
                case CellKind.SteamVent:
                case CellKind.WaterGeyser:
                case CellKind.CoolSteamVent:
                case CellKind.LeakyOilFissure:
                case CellKind.SaltWaterGeyser:
                case CellKind.CoolSlushGeyser:
                case CellKind.PollutedWaterVent:
                case CellKind.ChlorineGasVent:
                case CellKind.CarbonDioxideVent:
                case CellKind.PollutedOxygenVent:
                case CellKind.HydrogenVent:
                case CellKind.NaturalGasVent:
                case CellKind.MetalVolcano:
                case CellKind.MagmaVolcano:
                case CellKind.SpaceHeater:
                case CellKind.LiquidTepidizer:
                case CellKind.ThermoRegulator:
                    return 0.32f;
                case CellKind.ManualAirlock:
                case CellKind.MechanizedAirlock:
                    return 0.045f;
                case CellKind.Floor:
                case CellKind.Ladder:
                case CellKind.FirePole:
                    return 0.24f;
                case CellKind.Rock:
                    return 0.12f;
                default:
                    return 0.18f;
            }
        }

        private float TileThermalConductivity(int x, int y)
        {
            CellKind kind = cells[x, y];
            if (kind == CellKind.ManualAirlock)
            {
                return airlockOpen[x, y] ? 0.20f : 0.026f;
            }

            if (kind == CellKind.MechanizedAirlock)
            {
                return IsMechanizedAirlockOpen(new Vector2Int(x, y)) ? 0.24f : 0.022f;
            }

            if (kind == CellKind.InsulatedTile &&
                constructionMaterialGrade[x, y] == ConstructionMaterialGrade.HighGrade)
            {
                return ThermalConductivity(kind) * CeramicInsulatedConductivityMultiplier;
            }

            return ThermalConductivity(kind);
        }

        private float ThermalCapacityAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 1f;
            }

            float capacity = ThermalCapacity(cells[x, y]);
            if (waterMass[x, y] > 0.001f)
            {
                capacity += Mathf.Min(8f, waterMass[x, y] * 0.018f);
            }

            if (liquidPipe[x, y])
            {
                capacity += LiquidPipeTotal(x, y) * 0.09f;
            }

            if (cells[x, y] == CellKind.LiquidReservoir)
            {
                capacity += LiquidReservoirTotal(x, y) * 0.030f;
            }

            if (gasPipe[x, y])
            {
                capacity += GasPipeTotal(x, y) * 0.045f;
            }

            if (cells[x, y] == CellKind.GasReservoir)
            {
                capacity += GasReservoirTotal(x, y) * 0.055f;
            }

            return Mathf.Max(0.1f, capacity);
        }

        private float ThermalCapacity(CellKind kind)
        {
            switch (kind)
            {
                case CellKind.Empty:
                    return 1f;
                case CellKind.Water:
                case CellKind.PollutedWater:
                    return 4f;
                case CellKind.Rock:
                case CellKind.Regolith:
                case CellKind.Coal:
                case CellKind.Ice:
                    return 3f;
                case CellKind.Magma:
                    return 5f;
                case CellKind.MetalOre:
                    return 2.4f;
                case CellKind.SteamVent:
                case CellKind.WaterGeyser:
                case CellKind.CoolSteamVent:
                case CellKind.LeakyOilFissure:
                case CellKind.SaltWaterGeyser:
                case CellKind.CoolSlushGeyser:
                case CellKind.PollutedWaterVent:
                case CellKind.ChlorineGasVent:
                case CellKind.CarbonDioxideVent:
                case CellKind.PollutedOxygenVent:
                case CellKind.HydrogenVent:
                case CellKind.NaturalGasVent:
                case CellKind.MagmaVolcano:
                case CellKind.AntiEntropyThermoNullifier:
                    return 2.8f;
                case CellKind.SteamTurbine:
                    return 2.4f;
                case CellKind.SolarPanel:
                    return 1.9f;
                case CellKind.SpaceScanner:
                    return 1.7f;
                case CellKind.VentAnalyzer:
                    return 1.8f;
                case CellKind.RocketPlatform:
                    return 2.5f;
                case CellKind.ArcadeCabinet:
                    return 1.9f;
                case CellKind.OrbitalDataBank:
                    return 2.1f;
                case CellKind.InsulatedTile:
                    return 3.6f;
                case CellKind.Tile:
                    return 2.6f;
                case CellKind.AirflowTile:
                    return 2.0f;
                case CellKind.MeshTile:
                    return 1.8f;
                case CellKind.HydroponicFarm:
                    return 2.0f;
                case CellKind.TempshiftPlate:
                    return 2.8f;
                case CellKind.ThermoAquatuner:
                case CellKind.LiquidTepidizer:
                case CellKind.PowerControlStation:
                case CellKind.LiquidBridge:
                case CellKind.GasBridge:
                case CellKind.ShippingBridge:
                case CellKind.HighPressureGasVent:
                case CellKind.AutomationBridge:
                case CellKind.AutomationNotGate:
                case CellKind.AutomationAndGate:
                case CellKind.AutomationOrGate:
                case CellKind.AutomationXorGate:
                case CellKind.AutomationBufferGate:
                case CellKind.AutomationFilterGate:
                case CellKind.AutomationMemoryGate:
                case CellKind.AutomationCycleSensor:
                case CellKind.AutomationTimerSensor:
                case CellKind.DuplicantMotionSensor:
                case CellKind.GermSensor:
                case CellKind.WeightPlate:
                case CellKind.PowerBridge:
                case CellKind.PowerShutoff:
                case CellKind.ShippingRailSensor:
                case CellKind.ShippingRailShutoff:
                case CellKind.ShippingRailMeter:
                    return 2.6f;
                case CellKind.ManualAirlock:
                case CellKind.MechanizedAirlock:
                case CellKind.BunkerDoor:
                    return 2.1f;
                default:
                    return 1.6f;
            }
        }

        private void EqualizeGas(int ax, int ay, int bx, int by, float flowRate)
        {
            if (!IsInside(bx, by) || !IsGasExchangeCell(ax, ay) || !IsGasExchangeCell(bx, by))
            {
                return;
            }

            flowRate *= Mathf.Min(TileGasPermeability(ax, ay), TileGasPermeability(bx, by));
            float oxygenFlow = (oxygen[ax, ay] - oxygen[bx, by]) * flowRate * 0.5f;
            float co2Flow = (carbonDioxide[ax, ay] - carbonDioxide[bx, by]) * flowRate * 0.5f;
            float pollutedFlow = (pollutedOxygen[ax, ay] - pollutedOxygen[bx, by]) * flowRate * 0.5f;
            float hydrogenFlow = (hydrogen[ax, ay] - hydrogen[bx, by]) * flowRate * 0.5f;
            float steamFlow = (steam[ax, ay] - steam[bx, by]) * flowRate * 0.5f;
            float chlorineFlow = (chlorine[ax, ay] - chlorine[bx, by]) * flowRate * 0.5f;
            float naturalGasFlow = (naturalGas[ax, ay] - naturalGas[bx, by]) * flowRate * 0.5f;
            float sourGasFlow = (sourGas[ax, ay] - sourGas[bx, by]) * flowRate * 0.5f;
            float aToBMass =
                Mathf.Max(0f, oxygenFlow) +
                Mathf.Max(0f, co2Flow) +
                Mathf.Max(0f, pollutedFlow) +
                Mathf.Max(0f, hydrogenFlow) +
                Mathf.Max(0f, steamFlow) +
                Mathf.Max(0f, chlorineFlow) +
                Mathf.Max(0f, naturalGasFlow) +
                Mathf.Max(0f, sourGasFlow);
            float bToAMass =
                Mathf.Max(0f, -oxygenFlow) +
                Mathf.Max(0f, -co2Flow) +
                Mathf.Max(0f, -pollutedFlow) +
                Mathf.Max(0f, -hydrogenFlow) +
                Mathf.Max(0f, -steamFlow) +
                Mathf.Max(0f, -chlorineFlow) +
                Mathf.Max(0f, -naturalGasFlow) +
                Mathf.Max(0f, -sourGasFlow);
            ExchangeNextGasGerms(ax, ay, bx, by, aToBMass, bToAMass);
            ExchangeNextGasHeat(ax, ay, bx, by, aToBMass, bToAMass);

            nextOxygen[ax, ay] -= oxygenFlow;
            nextOxygen[bx, by] += oxygenFlow;
            nextCarbonDioxide[ax, ay] -= co2Flow;
            nextCarbonDioxide[bx, by] += co2Flow;
            nextPollutedOxygen[ax, ay] -= pollutedFlow;
            nextPollutedOxygen[bx, by] += pollutedFlow;
            nextHydrogen[ax, ay] -= hydrogenFlow;
            nextHydrogen[bx, by] += hydrogenFlow;
            nextSteam[ax, ay] -= steamFlow;
            nextSteam[bx, by] += steamFlow;
            nextChlorine[ax, ay] -= chlorineFlow;
            nextChlorine[bx, by] += chlorineFlow;
            nextNaturalGas[ax, ay] -= naturalGasFlow;
            nextNaturalGas[bx, by] += naturalGasFlow;
            nextSourGas[ax, ay] -= sourGasFlow;
            nextSourGas[bx, by] += sourGasFlow;
        }

        private void ExchangeNextGasGerms(int ax, int ay, int bx, int by, float aToBMass, float bToAMass)
        {
            float aMoved = GasGermMassMoved(ax, ay, aToBMass, TileGasTotal(ax, ay));
            float bMoved = GasGermMassMoved(bx, by, bToAMass, TileGasTotal(bx, by));
            nextGermMass[ax, ay] = Mathf.Max(0f, nextGermMass[ax, ay] - aMoved + bMoved);
            nextGermMass[bx, by] = Mathf.Max(0f, nextGermMass[bx, by] - bMoved + aMoved);
        }

        private void ExchangeNextGasHeat(int ax, int ay, int bx, int by, float aToBMass, float bToAMass)
        {
            float aMoved = GasHeatMoved(ax, ay, aToBMass, TileGasTotal(ax, ay));
            float bMoved = GasHeatMoved(bx, by, bToAMass, TileGasTotal(bx, by));
            nextGasHeat[ax, ay] = nextGasHeat[ax, ay] - aMoved + bMoved;
            nextGasHeat[bx, by] = nextGasHeat[bx, by] - bMoved + aMoved;
        }

        private void MoveNextGasGerms(int fromX, int fromY, int toX, int toY, float movedMass)
        {
            float fromTotal = NextGasTotal(fromX, fromY);
            float moved = GasGermMassMoved(fromX, fromY, movedMass, fromTotal);
            if (moved <= 0f)
            {
                return;
            }

            nextGermMass[fromX, fromY] = Mathf.Max(0f, nextGermMass[fromX, fromY] - moved);
            nextGermMass[toX, toY] = Mathf.Max(0f, nextGermMass[toX, toY] + moved);
        }

        private void MoveNextGasHeat(int fromX, int fromY, int toX, int toY, float movedMass)
        {
            float fromTotal = NextGasTotal(fromX, fromY);
            float moved = GasHeatMoved(fromX, fromY, movedMass, fromTotal);
            if (Mathf.Abs(moved) <= 0.0001f)
            {
                return;
            }

            nextGasHeat[fromX, fromY] -= moved;
            nextGasHeat[toX, toY] += moved;
        }

        private float GasGermMassMoved(int x, int y, float movedMass, float gasTotal)
        {
            if (movedMass <= 0f || gasTotal <= 0.001f || nextGermMass[x, y] <= 0f)
            {
                return 0f;
            }

            return Mathf.Min(nextGermMass[x, y], nextGermMass[x, y] * Mathf.Clamp01(movedMass / gasTotal));
        }

        private float GasHeatMoved(int x, int y, float movedMass, float gasTotal)
        {
            if (movedMass <= 0f || gasTotal <= 0.001f)
            {
                return 0f;
            }

            return nextGasHeat[x, y] * Mathf.Clamp01(movedMass / gasTotal);
        }

        private float NextGasTotal(int x, int y)
        {
            return Mathf.Max(0f,
                nextOxygen[x, y] +
                nextCarbonDioxide[x, y] +
                nextPollutedOxygen[x, y] +
                nextHydrogen[x, y] +
                nextSteam[x, y] +
                nextChlorine[x, y] +
                nextNaturalGas[x, y] +
                nextSourGas[x, y]);
        }

        private float GasPermeability(CellKind kind)
        {
            return kind == CellKind.InsulatedTile ? 0.02f :
                kind == CellKind.AirflowTile ? 1f :
                kind == CellKind.MeshTile ? 1f :
                kind == CellKind.Tile ? 0.03f :
                kind == CellKind.BunkerDoor ? 0.12f :
                kind == CellKind.MechanizedAirlock ? 0.14f :
                kind == CellKind.ManualAirlock ? 0.16f :
                1f;
        }

        private float TileGasPermeability(int x, int y)
        {
            CellKind kind = cells[x, y];
            if (kind == CellKind.ManualAirlock)
            {
                return airlockOpen[x, y] ? 0.92f : 0.02f;
            }

            if (kind == CellKind.MechanizedAirlock)
            {
                return IsMechanizedAirlockOpen(new Vector2Int(x, y)) ? 0.94f : 0.018f;
            }

            if (kind == CellKind.BunkerDoor)
            {
                return IsBunkerDoorClosed(new Vector2Int(x, y)) ? 0.015f : 0.88f;
            }

            return GasPermeability(kind);
        }

        private bool TryCreateRepairJob()
        {
            if (metal < RepairMetalCost)
            {
                return false;
            }

            Vector2Int bestCell = new Vector2Int(-1, -1);
            float bestScore = float.MinValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (!NeedsAutoRepair(cell) || FindAnyJobAt(cell) != null)
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Repair, cell, RepairWorkRequired(cell))
                    {
                        BuildKind = cells[x, y]
                    };

                    if (!CanAnyActiveWorkerReachJob(testJob))
                    {
                        continue;
                    }

                    float score = 1f - Mathf.Clamp01(equipmentCondition[x, y]);
                    if (IsBrokenEquipment(cell))
                    {
                        score += 2f;
                    }

                    if (RequiresPower(cells[x, y]) || cells[x, y] == CellKind.ManualGenerator || cells[x, y] == CellKind.JumboBattery || cells[x, y] == CellKind.CoalGenerator || cells[x, y] == CellKind.HydrogenGenerator || cells[x, y] == CellKind.NaturalGasGenerator || cells[x, y] == CellKind.PetroleumGenerator || cells[x, y] == CellKind.SteamTurbine || cells[x, y] == CellKind.SolarPanel || cells[x, y] == CellKind.ResearchReactor)
                    {
                        score += 0.35f;
                    }

                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCell = cell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.Repair, bestCell, RepairWorkRequired(bestCell))
            {
                AutoGenerated = true,
                BuildKind = cells[bestCell.x, bestCell.y],
                Priority = IsBrokenEquipment(bestCell) ? 8 : 5
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool TryCreateTuneGeneratorJob()
        {
            if (!techPowerRegulation ||
                refinedMetal < (CountQueuedTuneGeneratorJobs() + 1) * PowerControlStationRefinedMetalCost ||
                CountCells(CellKind.PowerControlStation) == 0)
            {
                return false;
            }

            Vector2Int bestCell = new Vector2Int(-1, -1);
            float bestScore = float.MinValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (!CanTuneGeneratorAt(cell, true) || FindJobAt(cell, JobType.TuneGenerator) != null)
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.TuneGenerator, cell, PowerControlStationWorkRequired);
                    if (!CanAnyActiveWorkerReachJob(testJob))
                    {
                        continue;
                    }

                    float score = GeneratorTuneUpDuration - generatorTuneUpSeconds[x, y];
                    if (power < maxPower * 0.45f)
                    {
                        score += 24f;
                    }

                    if (cells[x, y] == CellKind.CoalGenerator || cells[x, y] == CellKind.NaturalGasGenerator || cells[x, y] == CellKind.PetroleumGenerator)
                    {
                        score += 4f;
                    }

                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCell = cell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.TuneGenerator, bestCell, PowerControlStationWorkRequired)
            {
                AutoGenerated = true,
                Priority = power < maxPower * 0.30f ? 7 : 5
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private int CountQueuedTuneGeneratorJobs()
        {
            int count = 0;
            for (int i = 0; i < jobs.Count; i++)
            {
                if (jobs[i].Type == JobType.TuneGenerator)
                {
                    count++;
                }
            }

            return count;
        }

        private bool TryCreateSculptJob()
        {
            if (CountCells(CellKind.SculptingBlock) == 0)
            {
                return false;
            }

            int lowMoraleWorkers = CountLowMoraleWorkers();
            Vector2Int bestCell = new Vector2Int(-1, -1);
            float bestScore = float.MinValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (!NeedsSculpting(cell) || FindAnyJobAt(cell) != null)
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Sculpt, cell, SculptingBlockWorkRequired);
                    if (!CanAnyActiveWorkerReachJob(testJob))
                    {
                        continue;
                    }

                    RoomKind roomKind = RoomKindAt(x, y);
                    float score = 1f - DecorScoreAt(x, y);
                    if (roomKind == RoomKind.GreatHall || roomKind == RoomKind.RecreationRoom || roomKind == RoomKind.Bedroom)
                    {
                        score += 2f;
                    }

                    if (lowMoraleWorkers > 0)
                    {
                        score += 1.5f;
                    }

                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCell = cell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.Sculpt, bestCell, SculptingBlockWorkRequired)
            {
                AutoGenerated = true,
                Priority = lowMoraleWorkers > 0 ? 6 : 4
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool NeedsSculpting(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.SculptingBlock &&
                !sculptingBlockFinished[cell.x, cell.y];
        }

        private bool TryCreateSweepJob()
        {
            if (DryResourceFreeSpace() <= 0.01f)
            {
                return false;
            }

            Vector2Int bestCell = new Vector2Int(-1, -1);
            float bestScore = float.MinValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (!HasLooseResource(cell) || FindAnyJobAt(cell) != null || !CanStoreLooseResource(looseResourceKind[x, y], true))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Sweep, cell, SweepWorkRequired(cell));
                    if (!CanAnyActiveWorkerReachJob(testJob))
                    {
                        continue;
                    }

                    float score = looseResourceAmount[x, y];
                    if (looseResourceKind[x, y] == LooseResourceKind.Metal || looseResourceKind[x, y] == LooseResourceKind.Coal)
                    {
                        score += 8f;
                    }

                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCell = cell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.Sweep, bestCell, SweepWorkRequired(bestCell))
            {
                AutoGenerated = true,
                Priority = looseResourceKind[bestCell.x, bestCell.y] == LooseResourceKind.Metal ? 5 : 4
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool TryCreateEmptyBottleJob()
        {
            if (!HasStoredLiquidForBottleEmptier())
            {
                return false;
            }

            Vector2Int bestCell = new Vector2Int(-1, -1);
            float bestScore = float.MinValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.BottleEmptier ||
                        !CanUseEquipment(cell) ||
                        FindAnyJobAt(cell) != null ||
                        !CanEmptyBottleAt(cell))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.EmptyBottle, cell, BottleEmptierWorkRequired);
                    if (!CanAnyActiveWorkerReachJob(testJob))
                    {
                        continue;
                    }

                    float score = pollutedWater > 0.5f ? 20f + pollutedWater : CleanWaterAvailableForBottleEmptier();
                    if (TryFindBottleEmptierOutput(cell, out Vector2Int output) && output.y < cell.y)
                    {
                        score += 2f;
                    }

                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCell = cell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.EmptyBottle, bestCell, BottleEmptierWorkRequired)
            {
                AutoGenerated = true,
                Priority = pollutedWater > 0.5f ? 6 : 4
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool CanAnyActiveWorkerReachJob(Job job)
        {
            return CanAnyActiveWorkerReachJob(job, out _);
        }

        private void EnsureMaintenanceJobs()
        {
            for (int i = jobs.Count - 1; i >= 0; i--)
            {
                Job job = jobs[i];
                if (job.AutoGenerated && job.AssignedWorker == null && !IsJobValid(job))
                {
                    jobs.RemoveAt(i);
                    overlayDirty = true;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsRescue(worker) && !HasRescueJobFor(worker.Name) && TryCreateRescueJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsTreatment(worker) && !HasTreatmentJobFor(worker.Name) && TryCreateTreatmentJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsSeekSafety(worker) && !HasSeekSafetyJobFor(worker.Name) && TryCreateSeekSafetyJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsCatchBreath(worker) &&
                    !HasSeekSafetyJobFor(worker.Name) &&
                    !HasCatchBreathJobFor(worker.Name) &&
                    TryCreateCatchBreathJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsToilet(worker) && !HasToiletJobFor(worker.Name) && TryCreateToiletJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsShower(worker) && !HasShowerJobFor(worker.Name) && TryCreateShowerJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsHandWash(worker) && !HasWashHandsJobFor(worker.Name) && TryCreateWashHandsJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsFood(worker) && !HasEatJobFor(worker.Name) && TryCreateEatJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsRelaxation(worker) && !HasRelaxJobFor(worker.Name) && TryCreateRelaxJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsSkillScrub(worker) && !HasSkillScrubJobFor(worker.Name) && TryCreateSkillScrubJob(worker))
                {
                    return;
                }
            }

            foreach (Worker worker in workers)
            {
                if (NeedsMedicalRest(worker) && !HasMedicalRestJobFor(worker.Name) && TryCreateMedicalRestJob(worker))
                {
                    return;
                }
            }

            if (TryCreateSweepJob())
            {
                return;
            }

            if (TryCreateRepairJob())
            {
                return;
            }

            if (TryCreateTuneGeneratorJob())
            {
                return;
            }

            if (TryCreateSculptJob())
            {
                return;
            }

            if (TryCreateGroomHatchJob())
            {
                return;
            }

            if (power < maxPower * 0.55f)
            {
                UpdateAutomationWires();
                bool controlledGenerators = CountAutomationControlledGenerators() > 0;
                float requestThreshold = controlledGenerators ? maxPower * HighestSmartBatteryLowThreshold() : maxPower * 0.55f;
                if (power < requestThreshold)
                {
                    for (int y = 0; y < WorldHeight; y++)
                    {
                        for (int x = 0; x < WorldWidth; x++)
                        {
                            Vector2Int cell = new Vector2Int(x, y);
                            if (cells[x, y] == CellKind.ManualGenerator && CanGeneratorOperate(cell) && FindJobAt(cell, JobType.OperateGenerator) == null)
                            {
                                Job job = new Job(JobType.OperateGenerator, cell, 3.2f)
                                {
                                    AutoGenerated = true,
                                    Priority = power < maxPower * 0.18f ? 9 : 6
                                };
                                jobs.Add(job);
                                overlayDirty = true;
                                return;
                            }
                        }
                    }
                }
            }

            if (water < 160f)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.WaterPump &&
                            CanUseEquipment(cell) &&
                            TryFindAdjacentPipePumpLiquid(cell, out _) &&
                            FindJobAt(cell, JobType.PumpWater) == null)
                        {
                            Job job = new Job(JobType.PumpWater, cell, 2.5f)
                            {
                                AutoGenerated = true,
                                Priority = water < workers.Count * 12f ? 8 : 5
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if ((CountCells(CellKind.OilRefinery) > 0 || CountCells(CellKind.PolymerPress) > 0) && crudeOil < 240f)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.WaterPump &&
                            CanUseEquipment(cell) &&
                            TryFindAdjacentCrudeOil(cell, out _) &&
                            FindJobAt(cell, JobType.PumpWater) == null)
                        {
                            Job job = new Job(JobType.PumpWater, cell, 2.5f)
                            {
                                AutoGenerated = true,
                                Priority = petroleum < 40f ? 6 : 4
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (TryCreateEmptyBottleJob())
            {
                return;
            }

            if (TryCreateMedicineJob())
            {
                return;
            }

            if (HasLockedResearch() && researchPoints < MaxResearchRequirement() + 4f && power > 4f)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.ResearchStation && CanPoweredMachineRun(cell) && FindJobAt(cell, JobType.Research) == null)
                        {
                            Job job = new Job(JobType.Research, cell, 4.8f)
                            {
                                AutoGenerated = true,
                                Priority = ResearchJobPriority()
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (techFoodPreparation && food < workers.Count * 2100f && hatchEggs >= 1f)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.EggCracker && CanUseEquipment(cell) && FindJobAt(cell, JobType.Cook) == null)
                        {
                            Job job = new Job(JobType.Cook, cell, 2.4f)
                            {
                                AutoGenerated = true,
                                Priority = food < workers.Count * 1200f ? 8 : 5
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (techFoodPreparation && food < workers.Count * 2100f && water >= 4f && dirt >= 1f && power > 2f)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.MicrobeMusher && CanPoweredMachineRun(cell) && FindJobAt(cell, JobType.Cook) == null)
                        {
                            Job job = new Job(JobType.Cook, cell, 3f)
                            {
                                AutoGenerated = true,
                                Priority = food < workers.Count * 1200f ? 8 : 5
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (ShouldPrepareGrilledMeals() || ShouldPrepareFrostBuns())
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.ElectricGrill && CanCookAt(cell) && FindJobAt(cell, JobType.Cook) == null)
                        {
                            Job job = new Job(JobType.Cook, cell, 2.8f)
                            {
                                AutoGenerated = true,
                                Priority = CountLowMoraleWorkers() > 0 ? 7 : 4
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (techFoodPreparation && CanSupplyCropTending() && TryCreateTendCropJob())
            {
                return;
            }

            if (techPowerRegulation && refinedMetal < 40f && metal >= RockCrusherOrePerJob && power > RockCrusherPowerCost)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.RockCrusher && CanPoweredMachineRun(cell) && FindJobAt(cell, JobType.RefineMetal) == null)
                        {
                            Job job = new Job(JobType.RefineMetal, cell, 3.6f)
                            {
                                AutoGenerated = true,
                                Priority = refinedMetal < 8f ? 7 : 4
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (CanAnyRockCrusherProduceGlass() && (refinedMetal >= 8f || metal < RockCrusherOrePerJob))
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.RockCrusher && CanRockCrusherProduceGlass(cell) && FindJobAt(cell, JobType.RefineMetal) == null)
                        {
                            Job job = new Job(JobType.RefineMetal, cell, 3.8f)
                            {
                                AutoGenerated = true,
                                Priority = milestoneSolarLensing ? 4 : 6
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            if (CanAnyRockCrusherProduceCeramic() && (refinedMetal >= 8f || metal < RockCrusherOrePerJob))
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.RockCrusher && CanRockCrusherProduceCeramic(cell) && FindJobAt(cell, JobType.RefineMetal) == null)
                        {
                            Job job = new Job(JobType.RefineMetal, cell, 3.8f)
                            {
                                AutoGenerated = true,
                                Priority = CountCeramicInsulatedTiles() < CeramicInsulatedTileTarget ? 6 : 4
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            float compostablePollutedDirt = CompostablePollutedDirt();
            if (compostablePollutedDirt >= 4f)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cell = new Vector2Int(x, y);
                        if (cells[x, y] == CellKind.Compost && CanUseEquipment(cell) && FindJobAt(cell, JobType.Compost) == null)
                        {
                            Job job = new Job(JobType.Compost, cell, 3.1f)
                            {
                                AutoGenerated = true,
                                Priority = compostablePollutedDirt > 28f ? 7 : 5
                            };
                            jobs.Add(job);
                            overlayDirty = true;
                            return;
                        }
                    }
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsCropKind(cells[x, y]) && plantGrowth[x, y] >= 1f && CanHarvestCrop(new Vector2Int(x, y)) && FindJobAt(new Vector2Int(x, y), JobType.Harvest) == null)
                    {
                        Job job = new Job(JobType.Harvest, new Vector2Int(x, y), 2f)
                        {
                            AutoGenerated = true,
                            Priority = food < workers.Count * 1500f ? 7 : 4
                        };
                        jobs.Add(job);
                        overlayDirty = true;
                    }
                }
            }
        }

        private bool TryCreateTendCropJob()
        {
            if (CountCells(CellKind.FarmStation) == 0 || !CanSupplyCropTending())
            {
                return false;
            }

            Vector2Int bestCrop = new Vector2Int(-1, -1);
            float bestScore = -1f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int crop = new Vector2Int(x, y);
                    if (!IsCropTendingTarget(crop) || FindJobAt(crop, JobType.TendCrop) != null || !TryFindFarmStationForCrop(crop, out _))
                    {
                        continue;
                    }

                    float score = (1f - plantGrowth[x, y]) * 100f + Mathf.Clamp(12f - cropTendedSeconds[x, y], 0f, 12f);
                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCrop = crop;
                    }
                }
            }

            if (bestCrop.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.TendCrop, bestCrop, 2.4f)
            {
                AutoGenerated = true,
                Priority = food < workers.Count * 1800f ? 6 : 4
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool CanCookAt(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !techFoodPreparation)
            {
                return false;
            }

            if (cells[cell.x, cell.y] == CellKind.MicrobeMusher)
            {
                return water >= 4f && dirt >= 1f && power > 1f && CanPoweredMachineRun(cell);
            }

            if (cells[cell.x, cell.y] == CellKind.ElectricGrill)
            {
                return (ShouldPrepareGrilledMeals() || ShouldPrepareFrostBuns()) && CanPoweredMachineRun(cell);
            }

            return cells[cell.x, cell.y] == CellKind.EggCracker && hatchEggs >= 1f && CanUseEquipment(cell);
        }

        private bool IsCookingStationCell(CellKind kind)
        {
            return kind == CellKind.MicrobeMusher ||
                kind == CellKind.EggCracker ||
                kind == CellKind.ElectricGrill;
        }

        private bool CanUseCookingStationAt(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !techFoodPreparation)
            {
                return false;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (kind == CellKind.MicrobeMusher || kind == CellKind.ElectricGrill)
            {
                return CanPoweredMachineRun(cell);
            }

            return kind == CellKind.EggCracker && CanUseEquipment(cell);
        }

        private int CountCookingStations()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsCookingStationCell(cells[x, y]))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountUsableCookingStations()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseCookingStationAt(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountReadyCookingStations()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanCookAt(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string CookingReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return "Cooking blocked: station missing.";
            }

            if (!techFoodPreparation)
            {
                return "Cooking blocked: research Food Preparation.";
            }

            CellKind kind = cells[cell.x, cell.y];
            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (kind == CellKind.MicrobeMusher)
            {
                if (water < 4f)
                {
                    return "Cooking blocked: Microbe Musher needs clean water.";
                }

                if (dirt < 1f)
                {
                    return "Cooking blocked: Microbe Musher needs dirt.";
                }

                if (power <= 1f)
                {
                    return "Cooking blocked: Microbe Musher needs stored power.";
                }

                string poweredBlock = PoweredCookingBlockText(cell);
                if (!string.IsNullOrEmpty(poweredBlock))
                {
                    return poweredBlock;
                }

                return CookingReadyOrRouteBlockedText(
                    cell,
                    3f,
                    food < workers.Count * 1200f ? 8 : 5,
                    "Cooking ready: Microbe Musher can cook mush bars.");
            }

            if (kind == CellKind.EggCracker)
            {
                if (hatchEggs < 1f)
                {
                    return "Cooking blocked: Egg Cracker needs stored hatch eggs.";
                }

                if (IsBrokenEquipment(cell))
                {
                    return "Cooking blocked: Egg Cracker needs repair.";
                }

                if (IsEquipmentSubmerged(cell))
                {
                    return "Cooking blocked: Egg Cracker is submerged.";
                }

                return CookingReadyOrRouteBlockedText(
                    cell,
                    2.4f,
                    food < workers.Count * 1200f ? 8 : 5,
                    "Cooking ready: Egg Cracker can crack stored hatch eggs.");
            }

            if (kind == CellKind.ElectricGrill)
            {
                float requiredFood = Mathf.Max(ElectricGrillInputFood, workers.Count * 1400f);
                bool canBakeFrostBuns = wheatGrain >= FrostBunWheatGrainCost;
                if (!canBakeFrostBuns && food < requiredFood)
                {
                    return "Cooking blocked: Electric Grill needs prepared food or wheat grain.";
                }

                if (!canBakeFrostBuns &&
                    foodQuality >= ElectricGrillQualityTarget &&
                    (peppernut < PeppernutSeasoningCost || foodQuality >= PeppernutGrillQualityTarget))
                {
                    return "Cooking blocked: food quality target already met.";
                }

                if (power < ElectricGrillPowerCost)
                {
                    return "Cooking blocked: Electric Grill needs stored power.";
                }

                string poweredBlock = PoweredCookingBlockText(cell);
                if (!string.IsNullOrEmpty(poweredBlock))
                {
                    return poweredBlock;
                }

                return CookingReadyOrRouteBlockedText(
                    cell,
                    2.8f,
                    CountLowMoraleWorkers() > 0 ? 7 : 4,
                    canBakeFrostBuns ? "Cooking ready: Electric Grill can bake frost buns." : "Cooking ready: Electric Grill can prepare quality meals.");
            }

            return "Cooking blocked: station missing.";
        }

        private string CookingReadyOrRouteBlockedText(Vector2Int cell, float workRequired, int priority, string readyText)
        {
            Job cookJob = FindJobAt(cell, JobType.Cook);
            if (cookJob != null)
            {
                return "Cooking ready: cook errand queued. " + JobReachabilityText(cookJob);
            }

            Job testJob = new Job(JobType.Cook, cell, workRequired)
            {
                Priority = priority
            };
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Cooking blocked: ",
                "Cooking blocked: no reachable duplicant path to station.");
            return string.IsNullOrEmpty(routeBlock) ? readyText : routeBlock;
        }

        private string PoweredCookingBlockText(Vector2Int cell)
        {
            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Cooking blocked: cooking station needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Cooking blocked: cooking station is submerged.";
            }

            if (!HasWireAccess(cell))
            {
                return "Cooking blocked: needs power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Cooking blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Cooking blocked: automation signal is red.";
            }

            return string.Empty;
        }

        private bool ShouldPrepareGrilledMeals()
        {
            return techFoodPreparation &&
                food >= Mathf.Max(ElectricGrillInputFood, workers.Count * 1400f) &&
                (foodQuality < ElectricGrillQualityTarget || (peppernut >= PeppernutSeasoningCost && foodQuality < PeppernutGrillQualityTarget)) &&
                power >= ElectricGrillPowerCost;
        }

        private bool ShouldPrepareFrostBuns()
        {
            return techFoodPreparation &&
                wheatGrain >= FrostBunWheatGrainCost &&
                power >= ElectricGrillPowerCost;
        }

        private string CookingBlockedAlertText()
        {
            if (!techFoodPreparation || CountReadyCookingStations() > 0)
            {
                return string.Empty;
            }

            int cookingStations = CountCookingStations();
            if (cookingStations == 0)
            {
                return "no cooking station";
            }

            if (CountUsableCookingStations() == 0)
            {
                return "cooking station offline";
            }

            if (CountCells(CellKind.MicrobeMusher) > 0)
            {
                if (water < 4f)
                {
                    return "musher lacks water";
                }

                if (dirt < 1f)
                {
                    return "musher lacks dirt";
                }

                if (power <= 1f)
                {
                    return "musher lacks power";
                }
            }

            if (CountCells(CellKind.EggCracker) > 0 && hatchEggs < 1f)
            {
                return "egg cracker lacks eggs";
            }

            if (CountCells(CellKind.ElectricGrill) > 0)
            {
                if (food < Mathf.Max(ElectricGrillInputFood, workers.Count * 1400f))
                {
                    return "grill lacks prepared food";
                }

                if (power < ElectricGrillPowerCost)
                {
                    return "grill lacks power";
                }
            }

            return "cooking blocked";
        }

        private string FoodEmergencyActionText()
        {
            if (!techFoodPreparation)
            {
                return "Harvest mealwood and research Food Preparation for cooked food.";
            }

            string cookingBlock = CookingBlockedAlertText();
            if (!string.IsNullOrEmpty(cookingBlock))
            {
                switch (cookingBlock)
                {
                    case "no cooking station":
                        return "Build a Microbe Musher, Egg Cracker, or Electric Grill, and harvest crops before food runs out.";
                    case "cooking station offline":
                        return "Repair, enable, wire, or power a cooking station, and harvest crops before food runs out.";
                    case "musher lacks water":
                        return "Supply clean water to the Microbe Musher, and harvest crops before food runs out.";
                    case "musher lacks dirt":
                        return "Supply dirt to the Microbe Musher, and harvest crops before food runs out.";
                    case "musher lacks power":
                        return "Store power for the Microbe Musher, and harvest crops before food runs out.";
                    case "egg cracker lacks eggs":
                        return "Store hatch eggs for the Egg Cracker, and harvest crops before food runs out.";
                    case "grill lacks prepared food":
                        return "Cook or harvest enough prepared food before grilling quality meals.";
                    case "grill lacks power":
                        return "Store power for the Electric Grill, and harvest crops before food runs out.";
                    default:
                        return "Clear the cooking block, and harvest crops before food runs out.";
                }
            }

            return "Cook at the Microbe Musher, crack hatch eggs, grill quality meals, or harvest mealwood, bristle berries, dusk caps, and grubfruit before food runs out.";
        }

        private bool TryCreateMedicineJob()
        {
            if (!ShouldProduceMedicine())
            {
                return false;
            }

            Vector2Int bestCell = new Vector2Int(-1, -1);
            float bestScore = -1f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (!CanProduceMedicineAt(cell) || FindJobAt(cell, JobType.ProduceMedicine) != null)
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.ProduceMedicine, cell, MedicineWorkRequired())
                    {
                        Priority = MedicineJobPriority()
                    };
                    if (!CanAnyActiveWorkerReachJob(testJob))
                    {
                        continue;
                    }

                    float score = (DesiredMedicineStock() - medicine) * 8f + (AnyWorkerNeedsTreatment() ? 24f : 0f);
                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestCell = cell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.ProduceMedicine, bestCell, MedicineWorkRequired())
            {
                AutoGenerated = true,
                Priority = MedicineJobPriority()
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool ShouldProduceMedicine()
        {
            return medicine < DesiredMedicineStock() && CountMedicineReadyApothecaries() > 0;
        }

        private float DesiredMedicineStock()
        {
            float target;
            float minimum;
            float maximum;
            switch (medicineStockMode)
            {
                case MedicineStockMode.Low:
                    target = 1f + workers.Count * 0.25f;
                    minimum = 1f;
                    maximum = 3f;
                    break;
                case MedicineStockMode.High:
                    target = 2f + workers.Count * 0.75f;
                    minimum = 2f;
                    maximum = 8f;
                    break;
                default:
                    target = 1f + workers.Count * 0.5f;
                    minimum = 1f;
                    maximum = 5f;
                    break;
            }

            if (AnyWorkerNeedsTreatment())
            {
                target += medicineStockMode == MedicineStockMode.High ? 2f : 1f;
            }

            return Mathf.Clamp(target, minimum, maximum);
        }

        private string MedicineStockModeLabel(MedicineStockMode mode)
        {
            switch (mode)
            {
                case MedicineStockMode.Low:
                    return "LOW";
                case MedicineStockMode.High:
                    return "HIGH";
                default:
                    return "NORM";
            }
        }

        private string MedicineStockModeDescription()
        {
            switch (medicineStockMode)
            {
                case MedicineStockMode.Low:
                    return "Medicine stock mode LOW: conserve algae and water.";
                case MedicineStockMode.High:
                    return "Medicine stock mode HIGH: keep a deeper treatment reserve.";
                default:
                    return "Medicine stock mode NORM: maintain a balanced reserve.";
            }
        }

        private float MedicineWorkRequired()
        {
            return 2.6f;
        }

        private int MedicineJobPriority()
        {
            return AnyWorkerNeedsTreatment() && medicine < MedicineTreatmentUse ? 8 : 4;
        }

        private bool CanProduceMedicineAt(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.Apothecary &&
                water >= ApothecaryWaterUse &&
                algae >= ApothecaryAlgaeUse &&
                power >= ApothecaryPowerCost &&
                CanPoweredMachineRun(cell);
        }

        private int CountMedicineReadyApothecaries()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanProduceMedicineAt(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string MedicalCotDetailText(Vector2Int cell)
        {
            StringBuilder builder = new StringBuilder();
            int treatmentNeeds = CountWorkersNeedingTreatment();
            int treatmentJobs = CountJobsOfType(JobType.Treat);
            int medicalRestNeeds = CountWorkersNeedingMedicalRest();
            int medicalRestJobs = CountJobsOfType(JobType.MedicalRest);
            builder.AppendLine("Treatment demand " + treatmentNeeds + "  Treatment errands " + treatmentJobs + "  Recovery rest " + medicalRestNeeds + "/" + medicalRestJobs + "  Disease cases " + CountDiseasedWorkers() + ".");

            Job treatmentJob = FindJobAt(cell, JobType.Treat);
            if (treatmentJob != null)
            {
                builder.AppendLine(TreatmentReservationText(treatmentJob));
                builder.AppendLine(JobReachabilityText(treatmentJob));
            }
            else if (FindJobAt(cell, JobType.MedicalRest) is Job medicalRestJob)
            {
                builder.AppendLine(MedicalRestReservationText(medicalRestJob));
                builder.AppendLine(JobReachabilityText(medicalRestJob));
            }
            else if (TryFindMedicalCotPatient(cell, out Worker patient))
            {
                builder.AppendLine("Patient resting " + patient.Name + "  Health " + Mathf.RoundToInt(patient.Health) + "%  Sick " + Mathf.RoundToInt(patient.Sickness) + "%  Germs " + Mathf.RoundToInt(patient.GermExposure) + "%.");
            }
            else
            {
                builder.AppendLine(treatmentNeeds > 0
                    ? "Cot open for treatment; waiting for a reachable patient."
                    : medicalRestNeeds > 0 ? "Cot open for recovery rest; waiting for a reachable patient." : "Cot open; no duplicant currently needs treatment.");
            }

            bool clinic = RoomKindAt(cell.x, cell.y) == RoomKind.Clinic;
            builder.AppendLine("Passive recovery x" + (clinic ? ClinicPassiveRecoveryMultiplier : 1f).ToString("0.00") + (clinic ? "  Clinic recovery bonus active." : "  Seal medical fixtures into a Clinic for faster recovery."));
            builder.AppendLine("Medical isolation emissions x" + (clinic ? ClinicIsolationEmissionMultiplier : MedicalCotIsolationEmissionMultiplier).ToString("0.00") + (clinic ? "  Clinic isolation bonus active." : "  Clinic improves airborne containment.") + "  Contained germs " + medicalIsolationGermsContained.ToString("0.0") + ".");
            builder.Append("Medicine target " + medicine.ToString("0.0") + "/" + DesiredMedicineStock().ToString("0.0") + " packs  Stock " + MedicineStockModeLabel(medicineStockMode) + "  Medicine errands " + CountJobsOfType(JobType.ProduceMedicine) + ".");
            return builder.ToString();
        }

        private string ApothecaryDetailText(Vector2Int cell)
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("Medicine target " + medicine.ToString("0.0") + "/" + DesiredMedicineStock().ToString("0.0") + " packs  Stock " + MedicineStockModeLabel(medicineStockMode) + "  Medicine errands " + CountJobsOfType(JobType.ProduceMedicine) + ".");
            builder.AppendLine(MedicineStockModeDescription());
            builder.AppendLine("Inputs water " + water.ToString("0.0") + "/" + ApothecaryWaterUse.ToString("0.0") + " kg  algae " + algae.ToString("0.0") + "/" + ApothecaryAlgaeUse.ToString("0.0") + " kg  power " + power.ToString("0.0") + "/" + ApothecaryPowerCost.ToString("0.0") + ".");

            Job medicineJob = FindJobAt(cell, JobType.ProduceMedicine);
            if (medicineJob != null)
            {
                builder.AppendLine("Production errand " + JobProgressPercentText(medicineJob) + "  Priority " + EffectiveJobPriority(medicineJob) + ".");
                builder.AppendLine(JobReachabilityText(medicineJob));
            }
            else
            {
                builder.AppendLine(MedicineProductionReadinessText(cell));
            }

            string automationText = MachineAutomationStateText(cell);
            if (!string.IsNullOrEmpty(automationText))
            {
                builder.Append(automationText);
            }

            return builder.ToString();
        }

        private string MedicineProductionReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.Apothecary)
            {
                return "Medicine production blocked: apothecary missing.";
            }

            if (medicine >= DesiredMedicineStock())
            {
                return "Medicine stock target met.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (water < ApothecaryWaterUse)
            {
                return "Medicine production blocked: needs clean water.";
            }

            if (algae < ApothecaryAlgaeUse)
            {
                return "Medicine production blocked: needs algae.";
            }

            if (power < ApothecaryPowerCost)
            {
                return "Medicine production blocked: needs stored power.";
            }

            if (IsBrokenEquipment(cell))
            {
                return "Medicine production blocked: apothecary needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Medicine production blocked: apothecary is submerged.";
            }

            if (!HasWireAccess(cell))
            {
                return "Medicine production blocked: needs power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Medicine production blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Medicine production blocked: automation signal is red.";
            }

            Job medicineJob = FindJobAt(cell, JobType.ProduceMedicine);
            if (medicineJob != null)
            {
                return "Medicine production ready: production errand queued. " + JobReachabilityText(medicineJob);
            }

            Job testJob = new Job(JobType.ProduceMedicine, cell, MedicineWorkRequired())
            {
                Priority = MedicineJobPriority()
            };
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Medicine production blocked: ",
                "Medicine production blocked: no reachable duplicant path to Apothecary.");
            return string.IsNullOrEmpty(routeBlock) ? "Ready to compound medicine." : routeBlock;
        }

        private string CareStationBlockText(Vector2Int cell, CellKind expectedKind, string missingText, string repairText, string submergedText)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != expectedKind)
            {
                return missingText;
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return repairText;
            }

            if (IsEquipmentSubmerged(cell))
            {
                return submergedText;
            }

            return string.Empty;
        }

        private bool HasReachableWorkerForPersonalStation(Vector2Int cell, JobType jobType, Func<Worker, bool> predicate)
        {
            foreach (Worker worker in workers)
            {
                if (worker == null ||
                    worker.Health <= 0f ||
                    !predicate(worker) ||
                    !CanWorkerUsePersonalStation(cell, worker))
                {
                    continue;
                }

                Job testJob = new Job(jobType, cell, 1f)
                {
                    TargetWorkerName = worker.Name
                };
                if (TryFindSafePathToJob(worker, testJob, out _))
                {
                    return true;
                }
            }

            return false;
        }

        private int CountWorkersMatching(Func<Worker, bool> predicate)
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker != null && worker.Health > 0f && predicate(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountWorkersNear(Vector2Int cell, int radius)
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker == null || worker.Health <= 0f)
                {
                    continue;
                }

                int distance = Mathf.Abs(worker.Cell.x - cell.x) + Mathf.Abs(worker.Cell.y - cell.y);
                if (distance <= radius)
                {
                    count++;
                }
            }

            return count;
        }

        private string CommandReadinessText(Vector2Int cell, CommandMode mode)
        {
            switch (mode)
            {
                case CommandMode.Dig:
                    return DigReadinessText(cell);
                case CommandMode.Cancel:
                    return CancelReadinessText(cell);
                case CommandMode.Harvest:
                    return HarvestReadinessText(cell);
                case CommandMode.WrangleCritter:
                    return WrangleReadinessText(cell);
                case CommandMode.ButcherCritter:
                    return ButcherReadinessText(cell);
                case CommandMode.PriorityUp:
                    return PriorityReadinessText(cell, 1);
                case CommandMode.PriorityDown:
                    return PriorityReadinessText(cell, -1);
                case CommandMode.YellowAlert:
                    return YellowAlertReadinessText(cell);
                case CommandMode.ToggleBuildingEnabled:
                    return BuildingToggleReadinessText(cell);
                case CommandMode.CopySettings:
                    return CopySettingsReadinessText(cell);
                case CommandMode.MoveHere:
                    return MoveOrderReadinessText(cell);
                default:
                    return BuildPlacementReadinessText(cell, mode);
            }
        }

        private string MoveOrderReadinessText(Vector2Int cell)
        {
            Worker worker = SelectedCrewWorker();
            if (worker == null)
            {
                return "Move order blocked: no duplicant selected.";
            }

            if (worker.Health <= 0f)
            {
                return "Move order blocked: selected duplicant is incapacitated.";
            }

            if (!IsCharacterStandableCell(cell))
            {
                return "Move order blocked: target tile is not standable.";
            }

            if (worker.Cell == cell)
            {
                return "Move order ready: " + worker.Name + " is already here.";
            }

            Job moveJob = CreateMoveToJob(worker, cell);
            if (!TryFindPathToJob(worker.Cell, moveJob, out _))
            {
                return "Move order blocked: no reachable path for " + worker.Name + ".";
            }

            if (!TryFindSafePathToJob(worker, moveJob, out List<Vector2Int> path))
            {
                return "Move order blocked: route is unsafe for " + worker.Name + ".";
            }

            return "Move order ready: " + worker.Name + " can move here in " + path.Count + " steps.";
        }

        private string DigReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return string.Empty;
            }

            if (!IsNaturalSolid(cells[cell.x, cell.y]))
            {
                return "Dig blocked: target is not a natural solid tile.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Dig
                    ? "Dig ready: dig errand queued. " + JobReachabilityText(existingJob)
                    : "Dig blocked: another errand is already queued here.";
            }

            Job testJob = new Job(JobType.Dig, cell, DigWorkRequired(cells[cell.x, cell.y]))
            {
                Priority = 5
            };
            string reachabilityText = JobReachabilityText(testJob);
            return reachabilityText.StartsWith("Job reachable:", StringComparison.Ordinal)
                ? "Dig ready: reachable duplicant can excavate this tile. " + reachabilityText
                : "Dig blocked: " + reachabilityText;
        }

        private string CancelReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return string.Empty;
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                if (HasJobMaterialCost(existingJob))
                {
                    return "Cancel ready: will cancel queued errand and refund " +
                        BuildCostText(existingJob.DirtCost, existingJob.MetalCost, existingJob.AlgaeCost, existingJob.RefinedMetalCost) + ".";
                }

                return "Cancel ready: will cancel queued errand. " + JobReachabilityText(existingJob);
            }

            string removalLabel = CancelInstantRemovalLabel(cell);
            if (!string.IsNullOrEmpty(removalLabel))
            {
                return "Cancel ready: will remove " + removalLabel + " and try to recover materials.";
            }

            return "Cancel idle: no queued errand, wire, pipe, or rail here.";
        }

        private string CancelInstantRemovalLabel(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return string.Empty;
            }

            if (powerWire[cell.x, cell.y])
            {
                return PowerWireKindName(powerWireKind[cell.x, cell.y]);
            }

            if (automationWire[cell.x, cell.y])
            {
                return "Automation Wire";
            }

            if (liquidPipe[cell.x, cell.y])
            {
                return LiquidPipeKindName(liquidPipeKind[cell.x, cell.y]);
            }

            if (gasPipe[cell.x, cell.y])
            {
                return GasPipeKindName(gasPipeKind[cell.x, cell.y]);
            }

            if (shippingRail[cell.x, cell.y])
            {
                return "Shipping Rail";
            }

            return string.Empty;
        }

        private string HarvestReadinessText(Vector2Int cell)
        {
            if (!IsCropCell(cell))
            {
                return "Harvest idle: no crop here.";
            }

            if (plantGrowth[cell.x, cell.y] < 1f)
            {
                return "Harvest blocked: crop is not mature.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Harvest
                    ? "Harvest ready: harvest errand queued. " + JobReachabilityText(existingJob)
                    : "Harvest blocked: another errand is already queued here.";
            }

            if (!CanHarvestCrop(cell))
            {
                return "Harvest blocked: dry storage is full.";
            }

            Job testJob = new Job(JobType.Harvest, cell, 2f);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Harvest blocked: ",
                "Harvest blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Harvest ready: reachable duplicant can harvest this crop."
                : routeBlock;
        }

        private string WrangleReadinessText(Vector2Int cell)
        {
            HatchCritter critter = HatchAt(cell);
            if (critter == null)
            {
                return "Wrangle idle: no critter here.";
            }

            if (IsCritterSettledInStable(critter))
            {
                return "Wrangle idle: critter is already settled in a Stable.";
            }

            Job wrangleJob = FindWrangleJobForCritter(critter);
            if (wrangleJob != null)
            {
                return "Wrangle ready: wrangle errand queued. " + JobReachabilityText(wrangleJob);
            }

            if (FindButcherJobForCritter(critter) != null)
            {
                return "Wrangle blocked: critter is already marked for butcher.";
            }

            if (!TryFindWrangleDestination(critter, out _))
            {
                return "Wrangle blocked: no Stable has a valid destination cell.";
            }

            Job existingJob = FindAnyJobAt(critter.Cell);
            if (existingJob != null)
            {
                return "Wrangle blocked: another errand is already queued here.";
            }

            Job testJob = new Job(JobType.WrangleCritter, critter.Cell, CritterWrangleWorkRequired)
            {
                TargetCritterName = critter.Name
            };
            string reachabilityText = JobReachabilityText(testJob);
            return reachabilityText.StartsWith("Job reachable:", StringComparison.Ordinal)
                ? "Wrangle ready: reachable duplicant can move this critter to a Stable. " + reachabilityText
                : "Wrangle blocked: " + reachabilityText;
        }

        private string ButcherReadinessText(Vector2Int cell)
        {
            HatchCritter critter = HatchAt(cell);
            if (critter == null)
            {
                return "Butcher idle: no critter here.";
            }

            Job butcherJob = FindButcherJobForCritter(critter);
            if (butcherJob != null)
            {
                return "Butcher ready: butcher errand queued. " + JobReachabilityText(butcherJob);
            }

            Job existingJob = FindAnyJobAt(critter.Cell);
            if (existingJob != null)
            {
                return "Butcher blocked: another errand is already queued here.";
            }

            Job testJob = new Job(JobType.ButcherCritter, critter.Cell, CritterButcherWorkRequired)
            {
                TargetCritterName = critter.Name
            };
            string reachabilityText = JobReachabilityText(testJob);
            return reachabilityText.StartsWith("Job reachable:", StringComparison.Ordinal)
                ? "Butcher ready: reachable duplicant can butcher this critter. " + reachabilityText
                : "Butcher blocked: " + reachabilityText;
        }

        private string PriorityReadinessText(Vector2Int cell, int delta)
        {
            Job job = FindAnyJobAt(cell);
            if (job == null)
            {
                return delta > 0
                    ? "Priority up idle: no errand here."
                    : "Priority down idle: no errand here.";
            }

            int currentPriority = JobPriority(job);
            int nextPriority = Mathf.Clamp(currentPriority + delta, 1, 10);
            if (nextPriority == currentPriority)
            {
                return delta > 0
                    ? "Priority up blocked: errand is already priority 10."
                    : "Priority down blocked: errand is already priority 1.";
            }

            return (delta > 0 ? "Priority up ready: " : "Priority down ready: ") +
                JobLabel(job) +
                " priority " +
                currentPriority +
                " -> " +
                nextPriority +
                ".";
        }

        private string YellowAlertReadinessText(Vector2Int cell)
        {
            Job job = FindAnyJobAt(cell);
            if (job == null)
            {
                return "Yellow Alert idle: no errand here.";
            }

            return job.YellowAlert
                ? "Yellow Alert ready: click to clear emergency dispatch."
                : "Yellow Alert ready: click to mark this errand for emergency dispatch.";
        }

        private string BuildingToggleReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsDisablableBuilding(cells[cell.x, cell.y]))
            {
                return "Enable tool idle: no controllable building here.";
            }

            return buildingDisabled[cell.x, cell.y]
                ? "Enable tool ready: click to enable this building."
                : "Disable tool ready: click to disable this building.";
        }

        private string CopySettingsReadinessText(Vector2Int cell)
        {
            if (!HasCopyableBuildingSettings(cell))
            {
                return "Copy settings idle: no configurable building here.";
            }

            CellKind kind = cells[cell.x, cell.y];
            if (!copiedSettingsAvailable || copiedSettingsKind != kind)
            {
                return "Copy settings ready: click to copy this building's settings.";
            }

            if (cell == copiedSettingsSourceCell)
            {
                return "Copy settings source selected: click another matching building to paste.";
            }

            return "Copy settings ready: click to paste copied settings here.";
        }

        private string MopReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) ||
                (!IsWorldLiquidCell(cells[cell.x, cell.y]) && !IsFloodableCellKind(cells[cell.x, cell.y])))
            {
                return "Mop blocked: no spill target here.";
            }

            if (waterMass[cell.x, cell.y] <= 0.5f)
            {
                return "Mop idle: no shallow spill here.";
            }

            if (waterMass[cell.x, cell.y] > MoppableSpillMaxMass)
            {
                return "Mop blocked: spill is too deep; use a Water Pump.";
            }

            if (!HasAdjacentPassableCell(cell))
            {
                return "Mop blocked: needs adjacent passable access.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Mop
                    ? "Mop ready: mop errand queued. " + JobReachabilityText(existingJob)
                    : "Mop blocked: another errand is already queued here.";
            }

            Job testJob = new Job(JobType.Mop, cell, MopWorkRequired(cell));
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Mop blocked: ",
                "Mop blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Mop ready: reachable duplicant can recover shallow spill."
                : routeBlock;
        }

        private string DisinfectReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return "Disinfect blocked: target must be passable.";
            }

            if (germs[cell.x, cell.y] < DisinfectGermThreshold)
            {
                return "Disinfect idle: germs are below the threshold.";
            }

            if (!IsCharacterStandableCell(cell) && !HasAdjacentPassableCell(cell))
            {
                return "Disinfect blocked: needs standable or adjacent access.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Disinfect
                    ? "Disinfect ready: disinfect errand queued. " + JobReachabilityText(existingJob)
                    : "Disinfect blocked: another errand is already queued here.";
            }

            Job testJob = new Job(JobType.Disinfect, cell, DisinfectWorkRequired(cell));
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Disinfect blocked: ",
                "Disinfect blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Disinfect ready: reachable duplicant can clean germs."
                : routeBlock;
        }

        private string SweepReadinessText(Vector2Int cell)
        {
            if (!HasLooseResource(cell))
            {
                return "Sweep idle: no loose resource here.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Sweep
                    ? "Sweep ready: sweep errand queued. " + JobReachabilityText(existingJob)
                    : "Sweep blocked: another errand is already queued here.";
            }

            if (DryResourceFreeSpace() <= 0.01f)
            {
                return "Sweep blocked: dry storage is full.";
            }

            LooseResourceKind kind = looseResourceKind[cell.x, cell.y];
            if (!CanStoreLooseResource(kind, true))
            {
                return "Sweep blocked: no Storage Bin accepts this resource.";
            }

            Job testJob = new Job(JobType.Sweep, cell, SweepWorkRequired(cell));
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Sweep blocked: ",
                "Sweep blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Sweep ready: reachable duplicant can store this resource."
                : routeBlock;
        }

        private string RepairReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsRepairableEquipment(cells[cell.x, cell.y]))
            {
                return "Repair idle: target is not repairable equipment.";
            }

            if (!NeedsRepair(cell))
            {
                return "Repair idle: equipment is already in good condition.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Repair
                    ? "Repair ready: repair errand queued. " + JobReachabilityText(existingJob)
                    : "Repair blocked: another errand is already queued here.";
            }

            if (metal < RepairMetalCost)
            {
                return "Repair blocked: not enough metal.";
            }

            Job testJob = new Job(JobType.Repair, cell, RepairWorkRequired(cell))
            {
                BuildKind = cells[cell.x, cell.y]
            };
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Repair blocked: ",
                "Repair blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Repair ready: reachable duplicant can restore equipment."
                : routeBlock;
        }

        private string DeconstructReadinessText(Vector2Int cell)
        {
            if (!TryGetDeconstructTarget(cell, out CellKind targetKind, out bool removePowerWire, out bool removeAutomationWire, out bool removeLiquidPipe, out bool removeGasPipe, out bool removeShippingRail))
            {
                return "Deconstruct blocked: no removable building, conduit, wire, or rail here.";
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Deconstruct
                    ? "Deconstruct ready: deconstruct errand queued. " + JobReachabilityText(existingJob)
                    : "Deconstruct blocked: another errand is already queued here.";
            }

            Job testJob = new Job(
                JobType.Deconstruct,
                cell,
                DeconstructWorkRequired(targetKind, removePowerWire, removeAutomationWire, removeLiquidPipe, removeGasPipe, removeShippingRail))
            {
                BuildKind = targetKind,
                RemovePowerWire = removePowerWire,
                RemoveAutomationWire = removeAutomationWire,
                RemoveLiquidPipe = removeLiquidPipe,
                RemoveGasPipe = removeGasPipe,
                RemoveShippingRail = removeShippingRail
            };

            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Deconstruct blocked: ",
                "Deconstruct blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Deconstruct ready: reachable duplicant can remove target."
                : routeBlock;
        }

        private string BuildPlacementReadinessText(Vector2Int cell, CommandMode mode)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return string.Empty;
            }

            if (mode == CommandMode.PowerWire || mode == CommandMode.ConductiveWire || mode == CommandMode.HeavyWattWire)
            {
                return PowerWirePlacementReadinessText(cell, PowerWireKindForMode(mode));
            }

            if (mode == CommandMode.AutomationWire)
            {
                return AutomationWirePlacementReadinessText(cell);
            }

            if (mode == CommandMode.LiquidPipe || mode == CommandMode.RadiantLiquidPipe || mode == CommandMode.InsulatedLiquidPipe)
            {
                return LiquidPipePlacementReadinessText(cell, LiquidPipeKindForMode(mode));
            }

            if (mode == CommandMode.GasPipe || mode == CommandMode.RadiantGasPipe || mode == CommandMode.InsulatedGasPipe)
            {
                return GasPipePlacementReadinessText(cell, GasPipeKindForMode(mode));
            }

            if (mode == CommandMode.ShippingRail)
            {
                return ShippingRailPlacementReadinessText(cell);
            }

            BuildSpec spec = BuildSpecForMode(mode);
            if (spec.Kind == CellKind.Empty)
            {
                return string.Empty;
            }

            Job testJob = new Job(JobType.Build, cell, spec.Work)
            {
                BuildKind = spec.Kind,
                DirtCost = spec.Dirt,
                MetalCost = spec.Metal,
                AlgaeCost = spec.Algae,
                RefinedMetalCost = spec.RefinedMetal
            };

            if (!IsBuildUnlocked(spec.Kind, false))
            {
                return "Build placement blocked: selected construction is locked by research.";
            }

            if (!CanPlaceBuild(cell, spec.Kind))
            {
                return "Build placement blocked: " + BuildInvalidReasonText(testJob);
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.Build && existingJob.BuildKind == spec.Kind
                    ? "Build placement ready: build errand queued. " + JobReachabilityText(existingJob)
                    : "Build placement blocked: another errand is already queued here.";
            }

            string resourceBlock = BuildResourceBlockText(spec.Label, spec.Dirt, spec.Metal, spec.Algae, spec.RefinedMetal);
            if (!string.IsNullOrEmpty(resourceBlock))
            {
                return resourceBlock;
            }

            return BuildPlacementReachabilityText(testJob, "Build placement ready: reachable duplicant can build selected construction. ");
        }

        private string PowerWirePlacementReadinessText(Vector2Int cell, PowerWireKind kind)
        {
            if (!IsPowerWireKindUnlocked(kind, false))
            {
                return "Build placement blocked: selected construction is locked by research.";
            }

            if (!CanPlacePowerWire(cell, kind))
            {
                return BuildConduitPlacementBlockText(cell, powerWire[cell.x, cell.y] && powerWireKind[cell.x, cell.y] == kind, cells[cell.x, cell.y] == CellKind.PowerBridge);
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.BuildWire && existingJob.PowerWireKind == kind
                    ? "Build placement ready: build errand queued. " + JobReachabilityText(existingJob)
                    : "Build placement blocked: another errand is already queued here.";
            }

            float metalCost = PowerWireMetalCost(kind);
            float refinedMetalCost = PowerWireRefinedMetalCost(kind);
            string resourceBlock = BuildResourceBlockText(PowerWireKindName(kind), 0f, metalCost, 0f, refinedMetalCost);
            if (!string.IsNullOrEmpty(resourceBlock))
            {
                return resourceBlock;
            }

            Job testJob = new Job(JobType.BuildWire, cell, PowerWireWorkRequired(kind))
            {
                MetalCost = metalCost,
                RefinedMetalCost = refinedMetalCost,
                BuildWire = true,
                PowerWireKind = kind
            };
            return BuildPlacementReachabilityText(testJob, "Build placement ready: reachable duplicant can build selected conduit. ");
        }

        private string AutomationWirePlacementReadinessText(Vector2Int cell)
        {
            if (!techAutomationLogistics)
            {
                return "Build placement blocked: selected construction is locked by research.";
            }

            if (!CanPlaceAutomationWire(cell))
            {
                bool occupiedByAutomationPort = cells[cell.x, cell.y] == CellKind.AutomationBridge ||
                    cells[cell.x, cell.y] == CellKind.AutomationNotGate ||
                    cells[cell.x, cell.y] == CellKind.AutomationAndGate ||
                    cells[cell.x, cell.y] == CellKind.AutomationOrGate ||
                    cells[cell.x, cell.y] == CellKind.AutomationXorGate ||
                    cells[cell.x, cell.y] == CellKind.AutomationBufferGate ||
                    cells[cell.x, cell.y] == CellKind.AutomationFilterGate ||
                    cells[cell.x, cell.y] == CellKind.AutomationMemoryGate;
                return BuildConduitPlacementBlockText(cell, automationWire[cell.x, cell.y], occupiedByAutomationPort);
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.BuildAutomationWire
                    ? "Build placement ready: build errand queued. " + JobReachabilityText(existingJob)
                    : "Build placement blocked: another errand is already queued here.";
            }

            string resourceBlock = BuildResourceBlockText("Automation Wire", 0f, 1f, 0f, 0f);
            if (!string.IsNullOrEmpty(resourceBlock))
            {
                return resourceBlock;
            }

            Job testJob = new Job(JobType.BuildAutomationWire, cell, 0.75f)
            {
                MetalCost = 1f
            };
            return BuildPlacementReachabilityText(testJob, "Build placement ready: reachable duplicant can build selected conduit. ");
        }

        private string LiquidPipePlacementReadinessText(Vector2Int cell, LiquidPipeKind kind)
        {
            if (kind != LiquidPipeKind.Normal && !techThermalEngineering)
            {
                return "Build placement blocked: selected construction is locked by research.";
            }

            if (!CanPlaceLiquidPipe(cell, kind))
            {
                return BuildConduitPlacementBlockText(cell, liquidPipe[cell.x, cell.y] && liquidPipeKind[cell.x, cell.y] == kind, false);
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.BuildPipe && existingJob.LiquidPipeKind == kind
                    ? "Build placement ready: build errand queued. " + JobReachabilityText(existingJob)
                    : "Build placement blocked: another errand is already queued here.";
            }

            float metalCost = LiquidPipeMetalCost(kind);
            float refinedMetalCost = LiquidPipeRefinedMetalCost(kind);
            string resourceBlock = BuildResourceBlockText(LiquidPipeKindName(kind), 0f, metalCost, 0f, refinedMetalCost);
            if (!string.IsNullOrEmpty(resourceBlock))
            {
                return resourceBlock;
            }

            Job testJob = new Job(JobType.BuildPipe, cell, LiquidPipeWorkRequired(kind))
            {
                MetalCost = metalCost,
                RefinedMetalCost = refinedMetalCost,
                BuildPipe = true,
                LiquidPipeKind = kind
            };
            return BuildPlacementReachabilityText(testJob, "Build placement ready: reachable duplicant can build selected conduit. ");
        }

        private string GasPipePlacementReadinessText(Vector2Int cell, GasPipeKind kind)
        {
            if (!techAirSystems || (kind != GasPipeKind.Normal && !techThermalEngineering))
            {
                return "Build placement blocked: selected construction is locked by research.";
            }

            if (!CanPlaceGasPipe(cell, kind))
            {
                return BuildConduitPlacementBlockText(cell, gasPipe[cell.x, cell.y] && gasPipeKind[cell.x, cell.y] == kind, false);
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.BuildGasPipe && existingJob.GasPipeKind == kind
                    ? "Build placement ready: build errand queued. " + JobReachabilityText(existingJob)
                    : "Build placement blocked: another errand is already queued here.";
            }

            float metalCost = GasPipeMetalCost(kind);
            float refinedMetalCost = GasPipeRefinedMetalCost(kind);
            string resourceBlock = BuildResourceBlockText(GasPipeKindName(kind), 0f, metalCost, 0f, refinedMetalCost);
            if (!string.IsNullOrEmpty(resourceBlock))
            {
                return resourceBlock;
            }

            Job testJob = new Job(JobType.BuildGasPipe, cell, GasPipeWorkRequired(kind))
            {
                MetalCost = metalCost,
                RefinedMetalCost = refinedMetalCost,
                BuildGasPipe = true,
                GasPipeKind = kind
            };
            return BuildPlacementReachabilityText(testJob, "Build placement ready: reachable duplicant can build selected conduit. ");
        }

        private string ShippingRailPlacementReadinessText(Vector2Int cell)
        {
            if (!techAutomationLogistics)
            {
                return "Build placement blocked: selected construction is locked by research.";
            }

            if (!CanPlaceShippingRail(cell))
            {
                return BuildConduitPlacementBlockText(cell, shippingRail[cell.x, cell.y], cells[cell.x, cell.y] == CellKind.ShippingBridge);
            }

            Job existingJob = FindAnyJobAt(cell);
            if (existingJob != null)
            {
                return existingJob.Type == JobType.BuildShippingRail
                    ? "Build placement ready: build errand queued. " + JobReachabilityText(existingJob)
                    : "Build placement blocked: another errand is already queued here.";
            }

            string resourceBlock = BuildResourceBlockText("Shipping Rail", 0f, 1f, 0f, 0f);
            if (!string.IsNullOrEmpty(resourceBlock))
            {
                return resourceBlock;
            }

            Job testJob = new Job(JobType.BuildShippingRail, cell, 0.75f)
            {
                MetalCost = 1f,
                BuildShippingRail = true
            };
            return BuildPlacementReachabilityText(testJob, "Build placement ready: reachable duplicant can build selected conduit. ");
        }

        private string BuildConduitPlacementBlockText(Vector2Int cell, bool sameConstructionExists, bool blockedByBridge)
        {
            if (IsWorldLiquidCell(cells[cell.x, cell.y]))
            {
                return "Build placement blocked: route cannot pass through open liquid.";
            }

            if (sameConstructionExists)
            {
                return "Build placement blocked: same construction already exists here.";
            }

            if (blockedByBridge)
            {
                return "Build placement blocked: existing bridge occupies this route.";
            }

            return "Build placement blocked: route is blocked or already built.";
        }

        private string BuildResourceBlockText(string label, float dirtCost, float metalCost, float algaeCost, float refinedMetalCost)
        {
            return dirt < dirtCost || metal < metalCost || algae < algaeCost || refinedMetal < refinedMetalCost
                ? BuildCostFailureText(label, dirtCost, metalCost, algaeCost, refinedMetalCost)
                : string.Empty;
        }

        private string BuildPlacementReachabilityText(Job testJob, string readyText)
        {
            if (CanAnyActiveWorkerReachJob(testJob))
            {
                return readyText + JobReachabilityText(testJob);
            }

            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Build placement blocked: ",
                "Build placement blocked: build ladder/floor/door access to a work cell.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Build placement blocked: build ladder/floor/door access to a work cell."
                : routeBlock;
        }

