                "Atmo suit dock blocked: needs repair.",
                "Atmo suit dock blocked: dock is submerged.");
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            if (!techThermalEngineering)
            {
                return "Atmo suit dock blocked: research Thermal Engineering.";
            }

            if (!HasWireAccess(cell))
            {
