        private string ProtectionCheckpointReadyText(Vector2Int cell, string readyText, string blockedPrefix, string fallback)
        {
            string routeText = ProtectionCheckpointRouteText(cell, blockedPrefix, fallback);
            return routeText.StartsWith("Checkpoint route ready:", StringComparison.Ordinal)
                ? readyText + " " + routeText
                : routeText;
        }

        private string ProtectionCheckpointRouteText(Vector2Int cell, string blockedPrefix, string fallback)
        {
            if (CountActiveWorkers() == 0)
            {
                return blockedPrefix + "no active duplicants.";
            }

            int shortestPath = int.MaxValue;
            string firstRouteBlock = string.Empty;
            foreach (Worker worker in workers)
            {
                if (worker == null || worker.Health <= 0f)
                {
                    continue;
                }

                Job testJob = CreateMoveToJob(worker, cell);
                if (!IsJobValid(testJob))
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path))
                {
                    shortestPath = Mathf.Min(shortestPath, path.Count);
                    continue;
                }

                if (string.IsNullOrEmpty(firstRouteBlock) &&
                    TryGetPersonalNeedJobRouteBlockText(worker, testJob, out string routeBlockText))
                {
                    firstRouteBlock = RouteBlockTextWithPrefix(routeBlockText, blockedPrefix);
                }
            }

            if (shortestPath < int.MaxValue)
            {
                return "Checkpoint route ready: reachable duplicant can access checkpoint in " + shortestPath + " steps.";
            }

            return string.IsNullOrEmpty(firstRouteBlock) ? fallback : firstRouteBlock;
        }

        private string MedicalCotReadinessText(Vector2Int cell)
        {
            string block = CareStationBlockText(
                cell,
                CellKind.MedicalCot,
                "Medical cot blocked: cot missing.",
                "Medical cot blocked: needs repair.",
                "Medical cot blocked: cot is submerged.");
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            if (IsMedicalCotReserved(cell))
            {
                return "Medical cot ready: patient reserved or recovering.";
            }

            if (CountIncapacitatedWorkers() > 0)
            {
                return "Medical cot ready: rescue capacity available.";
            }

            string assignedWorkerName = PersonalStationAssignedWorkerName(cell);
            if (!string.IsNullOrEmpty(assignedWorkerName))
            {
                Worker assignedPatient = FindWorkerByName(assignedWorkerName);
                if (assignedPatient == null || assignedPatient.Health <= 0f)
                {
                    return "Medical cot blocked: assigned patient is unavailable.";
                }

                if (NeedsTreatment(assignedPatient))
                {
                    Job assignedTreatmentJob = new Job(JobType.Treat, cell, TreatmentWorkRequired(assignedPatient))
                    {
                        TargetWorkerName = assignedPatient.Name
                    };
                    string treatmentRouteBlock = AssignedStationRouteBlockText(
                        assignedPatient,
                        assignedTreatmentJob,
                        "Medical cot blocked: ",
                        "Medical cot blocked: assigned patient cannot reach this cot.");
                    return string.IsNullOrEmpty(treatmentRouteBlock)
                        ? "Medical cot ready: assigned patient can receive treatment."
                        : treatmentRouteBlock;
                }

                if (NeedsMedicalRest(assignedPatient))
                {
                    if (AnyWorkerNeedsTreatment())
                    {
                        return "Medical cot waiting: assigned patient needs rest, but treatment patients have priority.";
                    }

                    Job assignedRestJob = new Job(JobType.MedicalRest, cell, MedicalRestWorkRequired)
                    {
                        TargetWorkerName = assignedPatient.Name
                    };
                    string restRouteBlock = AssignedStationRouteBlockText(
                        assignedPatient,
                        assignedRestJob,
                        "Medical cot blocked: ",
                        "Medical cot blocked: assigned patient cannot reach this cot.");
                    return string.IsNullOrEmpty(restRouteBlock)
                        ? "Medical cot ready: assigned patient can recover here."
                        : restRouteBlock;
                }

                return "Medical cot idle: assigned patient does not need care.";
            }

            if (CountWorkersNeedingTreatment() <= 0)
            {
                int medicalRestNeeds = CountWorkersNeedingMedicalRest();
                if (medicalRestNeeds <= 0)
                {
                    return "Medical cot idle: no duplicant needs treatment.";
                }

                return HasReachableWorkerForPersonalStation(cell, JobType.MedicalRest, NeedsMedicalRest)
                    ? "Medical cot ready: reachable patient can recover here."
                    : "Medical cot blocked: no reachable recovery patient path.";
            }

            return HasReachableWorkerForPersonalStation(cell, JobType.Treat, NeedsTreatment)
                ? "Medical cot ready: reachable patient can receive treatment."
                : "Medical cot blocked: no reachable patient path.";
        }

