        private string WashStationReadinessText(Vector2Int cell)
        {
            CellKind kind = IsInside(cell.x, cell.y) ? cells[cell.x, cell.y] : CellKind.Empty;
            bool sanitizer = kind == CellKind.HandSanitizer;
            string block = CareStationBlockText(
                cell,
                sanitizer ? CellKind.HandSanitizer : CellKind.WashBasin,
                sanitizer ? "Hand sanitizer blocked: station missing." : "Wash basin blocked: station missing.",
                sanitizer ? "Hand sanitizer blocked: needs repair." : "Wash basin blocked: needs repair.",
                sanitizer ? "Hand sanitizer blocked: station is submerged." : "Wash basin blocked: station is submerged.");
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            if (sanitizer)
            {
                if (bleachStone < HandSanitizerBleachStoneUse)
                {
                    return "Hand sanitizer blocked: needs bleach stone.";
                }
            }
            else if (CleanWaterAvailableForMachine(cell) <= 0.05f)
            {
                return "Wash basin blocked: needs clean water.";
            }

            if (IsWashBasinReserved(cell))
            {
                return sanitizer ? "Hand sanitizer ready: hand wash errand reserved." : "Wash basin ready: hand wash errand reserved.";
            }

            if (CountWorkersMatching(NeedsHandWash) <= 0)
            {
                return sanitizer ? "Hand sanitizer idle: no duplicant needs hand cleaning." : "Wash basin idle: no duplicant needs hand washing.";
            }

            string routePrefix = sanitizer ? "Hand sanitizer blocked: " : "Wash basin blocked: ";
            string fallback = sanitizer
                ? "Hand sanitizer blocked: no reachable duplicant path."
                : "Wash basin blocked: no reachable duplicant path.";
            string routeBlock = ReachableWorkerRouteBlockText(
                cell,
                JobType.WashHands,
                NeedsHandWash,
                routePrefix,
                fallback);
            if (string.IsNullOrEmpty(routeBlock))
            {
                return sanitizer
                    ? "Hand sanitizer ready: reachable duplicant can sanitize hands."
                    : "Wash basin ready: reachable duplicant can wash hands.";
            }

            return routeBlock;
        }

        private string RecreationReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsRelaxationStationCell(cells[cell.x, cell.y]))
            {
                return "Recreation blocked: fixture missing.";
            }

            CellKind kind = cells[cell.x, cell.y];
            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Recreation blocked: fixture needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Recreation blocked: fixture is submerged.";
            }

            if (kind == CellKind.WaterCooler && CleanWaterAvailableForMachine(cell) < WaterCoolerWaterUse)
            {
                return "Recreation blocked: Water Cooler needs clean water.";
            }

            if (kind == CellKind.ArcadeCabinet)
            {
                if (!HasWireAccess(cell))
                {
                    return "Recreation blocked: Arcade Cabinet needs power wire.";
                }

                if (!HasPoweredCircuit(cell))
                {
                    return "Recreation blocked: wire circuit has no power.";
