            if (IsRelaxationStationReserved(cell))
            {
                return "Recreation ready: relaxation errand reserved.";
            }

            if (!AnyWorkerNeedsRelaxation())
            {
                return "Recreation idle: stress and downtime demand are low.";
            }

            string routeBlock = ReachableWorkerRouteBlockText(
                cell,
                JobType.Relax,
                NeedsRelaxation,
                "Recreation blocked: ",
                "Recreation blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Recreation ready: reachable duplicant can relax."
