                return "Comfy bed blocked: bed is flooded.";
            }

            if (IsBedReserved(cell))
            {
                return "Comfy bed ready: sleep errand reserved.";
            }

            string assignedWorkerName = PersonalStationAssignedWorkerName(cell);
            if (!string.IsNullOrEmpty(assignedWorkerName))
            {
                Worker assignedWorker = FindWorkerByName(assignedWorkerName);
                if (assignedWorker != null && !ShouldSleep(assignedWorker))
                {
                    return "Comfy bed idle: assigned duplicant does not need sleep.";
                }
            }

            if (!AnyWorkerNeedsSleep())
            {
                return "Comfy bed idle: no duplicant needs sleep.";
            }

            return HasReachableWorkerForPersonalStation(cell, JobType.Sleep, ShouldSleep)
                ? "Comfy bed ready: reachable duplicant can sleep."
                : "Comfy bed blocked: no reachable duplicant path.";
        }

        private string BedReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsBedKind(cells[cell.x, cell.y]))
            {
                return "Bed blocked: bed missing.";
            }

            bool comfy = cells[cell.x, cell.y] == CellKind.ComfyBed;
            if (comfy && !techPowerRegulation)
            {
                return "Comfy bed blocked: research Power Regulation.";
            }

            if (IsBedSubmerged(cell))
            {
                return comfy ? "Comfy bed blocked: bed is flooded." : "Bed blocked: bed is flooded.";
            }

            if (IsBedReserved(cell))
            {
                return comfy ? "Comfy bed ready: sleep errand reserved." : "Bed ready: sleep errand reserved.";
            }

            string assignedWorkerName = PersonalStationAssignedWorkerName(cell);
            if (!string.IsNullOrEmpty(assignedWorkerName))
            {
                Worker assignedWorker = FindWorkerByName(assignedWorkerName);
                if (assignedWorker == null || assignedWorker.Health <= 0f)
                {
                    return comfy ? "Comfy bed blocked: assigned duplicant is unavailable." : "Bed blocked: assigned duplicant is unavailable.";
                }

                if (!ShouldSleep(assignedWorker))
                {
                    return comfy ? "Comfy bed idle: assigned duplicant does not need sleep." : "Bed idle: assigned duplicant does not need sleep.";
                }

                Job assignedSleepJob = new Job(JobType.Sleep, cell, SleepWorkRequired(assignedWorker))
                {
                    TargetWorkerName = assignedWorker.Name
                };
                string sleepRouteBlock = AssignedStationRouteBlockText(
                    assignedWorker,
                    assignedSleepJob,
                    comfy ? "Comfy bed blocked: " : "Bed blocked: ",
                    comfy ? "Comfy bed blocked: assigned duplicant cannot reach this bed." : "Bed blocked: assigned duplicant cannot reach this bed.");
                if (!string.IsNullOrEmpty(sleepRouteBlock))
                {
                    return sleepRouteBlock;
                }

                return comfy ? "Comfy bed ready: assigned duplicant can sleep." : "Bed ready: assigned duplicant can sleep.";
            }

            if (!AnyWorkerNeedsSleep())
            {
                return comfy ? "Comfy bed idle: no duplicant needs sleep." : "Bed idle: no duplicant needs sleep.";
            }

            bool reachable = HasReachableWorkerForPersonalStation(cell, JobType.Sleep, ShouldSleep);
            if (comfy)
            {
                return reachable
                    ? "Comfy bed ready: reachable duplicant can sleep."
                    : "Comfy bed blocked: no reachable duplicant path.";
            }

            return reachable
                ? "Bed ready: reachable duplicant can sleep."
                : "Bed blocked: no reachable duplicant path.";
        }

        private string MessTableReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.MessTable)
            {
                return "Dining blocked: Mess Table missing.";
            }

            if (IsMessTableReserved(cell))
            {
                return "Dining ready: meal errand reserved.";
            }

            if (food < 700f)
            {
                return "Dining blocked: needs at least 700 kcal prepared food.";
            }

            string assignedWorkerName = PersonalStationAssignedWorkerName(cell);
            if (!string.IsNullOrEmpty(assignedWorkerName))
            {
                Worker assignedWorker = FindWorkerByName(assignedWorkerName);
                if (assignedWorker == null || assignedWorker.Health <= 0f)
                {
                    return "Dining blocked: assigned duplicant is unavailable.";
                }

                if (!NeedsFood(assignedWorker))
                {
                    return "Dining idle: assigned duplicant does not need food.";
                }

                Job assignedMealJob = new Job(JobType.Eat, cell, 1f)
                {
                    TargetWorkerName = assignedWorkerName
                };
                string mealRouteBlock = AssignedStationRouteBlockText(
                    assignedWorker,
                    assignedMealJob,
                    "Dining blocked: ",
                    "Dining blocked: assigned duplicant cannot reach this table.");
                if (!string.IsNullOrEmpty(mealRouteBlock))
                {
                    return mealRouteBlock;
                }

                return "Dining ready: assigned hungry duplicant can eat here.";
            }

            if (CountWorkersMatching(NeedsFood) <= 0)
            {
                return "Dining idle: no hungry duplicant needs a table.";
            }

            return HasReachableWorkerForPersonalStation(cell, JobType.Eat, NeedsFood)
                ? "Dining ready: reachable hungry duplicant can eat here."
                : "Dining blocked: no reachable duplicant path to table.";
        }

        private string DecorPlantReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.DecorPlant)
            {
                return "Decor blocked: plant missing.";
            }

            int nearbyWorkers = CountWorkersNear(cell, DecorPlantRadius);
            if (nearbyWorkers > 0)
            {
                return "Decor ready: improving nearby duplicant morale routes.";
            }

            return AverageWorkerDecor() < DrabDecorThreshold || CountLowMoraleWorkers() > 0
                ? "Decor idle: place along daily routes or living rooms for morale benefit."
                : "Decor ready: colony morale routes are already covered.";
        }

        private string SculptingBlockReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.SculptingBlock)
            {
                return "Sculpting blocked: block missing.";
            }

            if (sculptingBlockFinished[cell.x, cell.y])
            {
                return CountWorkersNear(cell, SculptingBlockRadius) > 0
                    ? "Sculpture ready: decor bonus reaches nearby duplicants."
                    : "Sculpture ready: strong decor source active.";
            }

            Job sculptJob = FindJobAt(cell, JobType.Sculpt);
            if (sculptJob != null)
            {
                return "Sculpting ready: sculpt errand queued. " + JobReachabilityText(sculptJob);
            }

            Job testJob = new Job(JobType.Sculpt, cell, SculptingBlockWorkRequired);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Sculpting blocked: ",
                "Sculpting blocked: no reachable duplicant path.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Sculpting ready: reachable duplicant can finish it."
                : routeBlock;
        }

        private string TreatmentReservationText(Job job)
        {
            string patientName = string.IsNullOrEmpty(job.TargetWorkerName) ? "unknown patient" : job.TargetWorkerName;
            string assigneeText = job.AssignedWorker == null ? "Waiting for medical duplicant." : "Assigned to " + job.AssignedWorker.Name + ".";
            return "Reserved patient " + patientName + "  " + JobProgressPercentText(job) + "  Priority " + EffectiveJobPriority(job) + ". " + assigneeText;
        }

        private string MedicalRestReservationText(Job job)
        {
            string patientName = string.IsNullOrEmpty(job.TargetWorkerName) ? "unknown patient" : job.TargetWorkerName;
            string assigneeText = job.AssignedWorker == null ? "Waiting for recovering duplicant." : "Recovering " + job.AssignedWorker.Name + ".";
            return "Recovery rest patient " + patientName + "  " + JobProgressPercentText(job) + "  Priority " + EffectiveJobPriority(job) + ". " + assigneeText;
        }

        private string JobProgressPercentText(Job job)
        {
            if (job == null)
            {
                return "Progress 0%";
            }

            int progress = Mathf.RoundToInt(Mathf.Clamp01(job.Progress / Mathf.Max(0.001f, job.WorkRequired)) * 100f);
            return "Progress " + progress + "%";
        }

        private bool TryFindMedicalCotPatient(Vector2Int cotCell, out Worker patient)
        {
            foreach (Worker worker in workers)
            {
                if (worker == null ||
                    worker.Health <= 0f ||
                    worker.Cell != cotCell)
                {
                    continue;
                }

                if (worker.Activity == "Receiving Treatment" ||
                    worker.Activity == "Recovering" ||
                    NeedsTreatment(worker))
                {
                    patient = worker;
                    return true;
                }
            }

            patient = null;
            return false;
        }

        private int CountJobsOfType(JobType type)
        {
            int count = 0;
            foreach (Job job in jobs)
            {
                if (job.Type == type)
                {
                    count++;
                }
            }

            return count;
        }

        private bool TryCreateGroomHatchJob()
        {
            if (!techFoodPreparation || hatches.Count == 0 || CountUsableCells(CellKind.RanchingStation) == 0)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int station = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.RanchingStation ||
                        !CanUseEquipment(station) ||
                        FindJobAt(station, JobType.GroomHatch) != null ||
                        FindGroomableHatch(station) == null)
                    {
                        continue;
                    }

                    Job job = new Job(JobType.GroomHatch, station, 2.6f)
                    {
                        AutoGenerated = true,
                        Priority = CountUngroomedCritters() > 1 ? 6 : 4
                    };
                    if (!CanAnyActiveWorkerReachJob(job))
                    {
                        continue;
                    }

                    jobs.Add(job);
                    overlayDirty = true;
                    return true;
                }
            }

            return false;
        }

        private string RanchingStationReadinessText(Vector2Int station)
        {
            if (!IsInside(station.x, station.y) || cells[station.x, station.y] != CellKind.RanchingStation)
            {
                return "Ranching blocked: station missing.";
            }

            if (!techFoodPreparation)
            {
                return "Ranching blocked: research Food Preparation.";
            }

            string disabledBlock = DisabledBuildingBlockText(station);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(station))
            {
                return "Ranching blocked: station needs repair.";
            }

            if (IsEquipmentSubmerged(station))
            {
                return "Ranching blocked: station is submerged.";
            }

            if (hatches.Count == 0)
            {
                return "Ranching idle: no critters available.";
            }

            HatchCritter target = FindGroomableHatch(station);
            if (target == null)
            {
                return CountUngroomedCritters() == 0
                    ? "Ranching idle: all nearby critters are already groomed."
                    : "Ranching idle: no ungroomed critter in range.";
            }

            Job groomJob = FindJobAt(station, JobType.GroomHatch);
            if (groomJob != null)
            {
                return "Ranching ready: grooming errand queued. " + JobReachabilityText(groomJob);
            }

            Job testJob = new Job(JobType.GroomHatch, station, 2.6f);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Ranching blocked: ",
                "Ranching blocked: no reachable duplicant path to station.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Ranching ready: can groom nearby critter."
                : routeBlock;
        }

        private HatchCritter FindGroomableHatch(Vector2Int station)
        {
            if (!CanUseEquipment(station))
            {
                return null;
            }

            HatchCritter best = null;
            float bestScore = float.MaxValue;
            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                if (hatch == null || hatch.GroomedSeconds > 8f)
                {
                    continue;
                }

                int distance = Mathf.Abs(hatch.Cell.x - station.x) + Mathf.Abs(hatch.Cell.y - station.y);
                if (distance > HatchGroomRange)
                {
                    continue;
                }

                float score = distance + hatch.Happiness * 0.04f;
                if (score < bestScore)
                {
                    bestScore = score;
                    best = hatch;
                }
            }

            return best;
        }

