        private void UpdateWorkers(float deltaTime)
        {
            int activeWorkers = 0;
            foreach (Worker worker in workers)
            {
                UpdateWorkerVitals(worker, deltaTime);
                if (worker.Health <= 0f)
                {
                    ClearAssignment(worker);
                    worker.Activity = "Incapacitated";
                    continue;
                }

                activeWorkers++;

                if (worker.StressBreakSeconds > 0f)
                {
                    UpdateStressBreak(worker, deltaTime);
                    continue;
                }

                if (ShouldTriggerStressBreak(worker))
                {
                    StartStressBreak(worker);
                    UpdateStressBreak(worker, deltaTime);
                    continue;
                }

                if (UpdateExhaustedCollapse(worker, deltaTime))
                {
                    continue;
                }

                if (UpdateNarcolepticNap(worker, deltaTime))
                {
                    continue;
                }

                if (worker.AssignedJob == null || !IsJobValid(worker.AssignedJob) || ShouldInterruptForSchedule(worker))
                {
                    ClearAssignment(worker);
                    AssignBestJob(worker);
                }

                if (worker.AssignedJob == null)
                {
                    worker.Activity = NeedsMedicalLeave(worker) ? "Medical leave" : "Idle";
                    continue;
                }

                MoveOrWork(worker, deltaTime);
            }

            if (activeWorkers == 0 && workers.Count > 0)
            {
                TriggerColonyFailure("All duplicants are incapacitated.");
            }

            if (HasDuplicantMotionSensors() || HasWeightPlates())
            {
                UpdateAutomationWires();
                overlayDirty = true;
            }

            if (currentOverlayMode == OverlayMode.Vitals ||
                currentOverlayMode == OverlayMode.Medical ||
                currentOverlayMode == OverlayMode.Morale ||
                currentOverlayMode == OverlayMode.Suit ||
                currentOverlayMode == OverlayMode.Errands)
            {
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private void UpdateWorkerVitals(Worker worker, float deltaTime)
        {
            worker.Cell = WorldToCell(worker.Transform.position);
            if (worker.Health <= 0f)
            {
                worker.Health = 0f;
                worker.IncapacitatedSeconds += deltaTime;
                worker.Activity = "Incapacitated";
                return;
            }

            worker.IncapacitatedSeconds = 0f;

            bool sleeping = IsSleeping(worker) || worker.NarcolepticNapSeconds > 0f || worker.ExhaustedCollapseSeconds > 0f;
            worker.Bladder = Mathf.Clamp(worker.Bladder + (sleeping ? 0.18f : 0.34f) * WorkerBladderFillMultiplier(worker) * deltaTime, 0f, 100f);
            if (worker.Bladder >= 100f)
            {
                TriggerBladderAccident(worker);
            }
            else if (worker.Bladder >= 86f)
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + 1.2f * deltaTime);
            }

            if (!sleeping)
            {
                float fatigueRate = IsRestTime(worker) ? 0.72f : IsDowntime(worker) ? 0.22f : 0.34f;
                if (redAlertActive)
                {
                    fatigueRate *= 1.35f;
                    worker.Stress = Mathf.Min(100f, worker.Stress + RedAlertStressRate * deltaTime);
                }

                worker.Fatigue = Mathf.Min(100f, worker.Fatigue + fatigueRate * deltaTime);
            }

            UpdateDrowsyStress(worker, sleeping, deltaTime);
            ApplySchedulePressure(worker, sleeping, deltaTime);
            UpdateSoggyFeet(worker, deltaTime);
            UpdateSoppingWet(worker, deltaTime);
            UpdateGermyHands(worker, deltaTime);
            worker.FoodSafeHandsSeconds = Mathf.Max(0f, worker.FoodSafeHandsSeconds - deltaTime);
            UpdateDarkStress(worker, sleeping, deltaTime);
            UpdateBrightSleep(worker, deltaTime);
            UpdateSoreBack(worker, deltaTime);
            UpdateAteWithoutTable(worker, deltaTime);
            UpdateAccidentShame(worker, deltaTime);
            UpdateNauseous(worker, deltaTime);

            if (IsInside(worker.Cell.x, worker.Cell.y) && IsPassable(worker.Cell.x, worker.Cell.y))
            {
                UpdateFlatulence(worker, deltaTime);
                bool suitProtected = UseSuitProtection(worker, deltaTime);
                bool breathingProtected = suitProtected || UseOxygenMaskProtection(worker, deltaTime);
                if (!breathingProtected)
                {
                    float breath = 0.018f * WorkerBreathRateMultiplier(worker) * WorkerDiseaseBreathRateMultiplier(worker) * deltaTime;
                    ConsumeBreathableAir(worker.Cell, breath);
                    if (pollutedOxygen[worker.Cell.x, worker.Cell.y] > 0.12f)
                    {
                        float exposure = pollutedOxygen[worker.Cell.x, worker.Cell.y] *
                            (0.7f + germs[worker.Cell.x, worker.Cell.y] * 1.8f) *
                            WorkerAirborneGermExposureMultiplier(worker) *
                            deltaTime;
                        worker.GermExposure = Mathf.Min(100f, worker.GermExposure + exposure);
                        worker.Stress = Mathf.Min(100f, worker.Stress + 0.7f * deltaTime);
                    }
                    else if (germs[worker.Cell.x, worker.Cell.y] >= AirborneGermExposureThreshold)
                    {
                        float exposure = germs[worker.Cell.x, worker.Cell.y] *
                            AirborneGermExposureRate *
                            WorkerAirborneGermExposureMultiplier(worker) *
                            deltaTime;
                        worker.GermExposure = Mathf.Min(100f, worker.GermExposure + exposure);
                    }
                    else
                    {
                        worker.GermExposure = Mathf.Max(0f, worker.GermExposure - 0.18f * deltaTime);
                    }
                }
                else if (suitProtected)
                {
                    worker.GermExposure = Mathf.Max(0f, worker.GermExposure - 0.12f * deltaTime);
                }

                UpdateYuckyLungs(worker, breathingProtected, deltaTime);
                UpdateIrritatedEyes(worker, suitProtected, deltaTime);
                UpdateAllergicReaction(worker, breathingProtected, sleeping, deltaTime);
                UpdateSuitFatigue(worker, sleeping, deltaTime);

                if (!breathingProtected)
                {
                    ShedWorkerAirborneDiseaseGerms(worker, sleeping, deltaTime);
                }

                if (!suitProtected && chlorine[worker.Cell.x, worker.Cell.y] > ChlorineExposureThreshold)
                {
                    float chlorineSeverity = Mathf.Clamp01(chlorine[worker.Cell.x, worker.Cell.y] / 1.4f);
                    chlorineExposureSeconds += deltaTime;
                    worker.Stress = Mathf.Min(100f, worker.Stress + 1.7f * chlorineSeverity * deltaTime);
                    float beforeHealth = worker.Health;
                    worker.Health = Mathf.Max(0f, worker.Health - ChlorineDamageRate * chlorineSeverity * deltaTime);
                    chlorineHealthDamage += Mathf.Max(0f, beforeHealth - worker.Health);
                }

                if (worker.GermExposure >= 40f)
                {
                    worker.Sickness = Mathf.Min(100f, worker.Sickness + 0.42f * deltaTime);
                }
                else
                {
                    worker.Sickness = Mathf.Max(0f, worker.Sickness - 0.08f * deltaTime);
                }

                ApplyWorkerSourGasExposure(worker, breathingProtected, deltaTime);

                if (!breathingProtected &&
                    pollutedOxygen[worker.Cell.x, worker.Cell.y] >= SlimelungPollutedOxygenThreshold &&
                    germs[worker.Cell.x, worker.Cell.y] >= SlimelungTileGermThreshold &&
                    worker.GermExposure >= SlimelungGermExposureThreshold)
                {
                    ContractWorkerDisease(worker, WorkerDisease.Slimelung, 38f, worker.Name + " contracted Slimelung from germy polluted oxygen.");
                }

                float fatigueWorkFactor = worker.Fatigue > 88f ? 0.55f : worker.Fatigue > DrowsyFatigueThreshold ? 0.75f : 1f;
                float sicknessWorkFactor = worker.Sickness > 65f ? 0.7f : worker.Sickness > 35f ? 0.85f : 1f;
                float localTemperature = temperature[worker.Cell.x, worker.Cell.y];
                UpdateWorkerOutfit(worker, localTemperature);
                float effectiveTemperature = WorkerOutfitAdjustedTemperature(worker, localTemperature);
                float temperatureWorkFactor = effectiveTemperature < 0f || effectiveTemperature > 52f ? 0.58f :
                    effectiveTemperature < 8f || effectiveTemperature > 40f ? 0.82f : 1f;
                float lightWorkFactor = IsCellLit(worker.Cell.x, worker.Cell.y) ? CeilingLightWorkSpeedMultiplier : 1f;
                float localPressure = TileGasTotal(worker.Cell.x, worker.Cell.y);
                UpdatePoppedEardrums(worker, suitProtected, localPressure, deltaTime);
                float effectiveWorkSpeed =
                    WorkerSkillSpeedMultiplier(worker) *
                    WorkerTraitPassiveWorkSpeedMultiplier(worker) *
                    WorkerOverjoyedPassiveWorkSpeedMultiplier(worker) *
                    WorkerDiseaseWorkSpeedMultiplier(worker) *
                    WorkerNauseousWorkSpeedMultiplier(worker) *
                    WorkerSoppingWetWorkSpeedMultiplier(worker) *
                    WorkerYuckyLungsWorkSpeedMultiplier(worker) *
                    WorkerPoppedEardrumsWorkSpeedMultiplier(worker) *
                    WorkerIrritatedEyesWorkSpeedMultiplier(worker) *
                    WorkerScaldedWorkSpeedMultiplier(worker) *
                    WorkerThermalDiscomfortWorkSpeedMultiplier(worker) *
                    WorkerAllergicReactionWorkSpeedMultiplier(worker) *
                    WorkerSuitFatigueWorkSpeedMultiplier(worker) *
                    WorkerDarkStressWorkSpeedMultiplier(worker) *
                    WorkerSoreBackWorkSpeedMultiplier(worker) *
                    WorkerAccidentShameWorkSpeedMultiplier(worker) *
                    fatigueWorkFactor *
                    sicknessWorkFactor *
                    temperatureWorkFactor *
                    lightWorkFactor *
                    (redAlertActive ? RedAlertWorkSpeedMultiplier : 1f);
                float localDecor = DecorScoreAt(worker.Cell.x, worker.Cell.y);
                ApplyWorkerThermalExposure(worker, localTemperature, steam[worker.Cell.x, worker.Cell.y], suitProtected, deltaTime);
                ApplyWorkerRadiationExposure(worker, deltaTime);
                ApplyWorkerElectricalHazard(worker, suitProtected, deltaTime);

                if (!suitProtected && localPressure > OverpressureStressThreshold)
                {
                    float pressureSeverity = Mathf.Clamp01((localPressure - OverpressureStressThreshold) / Mathf.Max(0.001f, 2.8f - OverpressureStressThreshold));
                    worker.Stress = Mathf.Min(100f, worker.Stress + OverpressureStressRate * pressureSeverity * deltaTime);
                    overpressureExposureSeconds += deltaTime;
                    if (localPressure > OverpressureDamageThreshold)
                    {
                        float beforeHealth = worker.Health;
                        worker.Health = Mathf.Max(0f, worker.Health - OverpressureDamageRate * pressureSeverity * deltaTime);
                        overpressureHealthDamage += Mathf.Max(0f, beforeHealth - worker.Health);
                    }
                }

                float breathableAir = BreathableAirAt(worker.Cell.x, worker.Cell.y);
                bool breathingComfortably = breathingProtected || breathableAir >= BreathRecoveryAirThreshold;
                bool holdingBreath = !breathingProtected && breathableAir < BreathLowAirThreshold;
                if (breathingComfortably)
                {
                    worker.Breath = Mathf.Min(BreathCapacity, worker.Breath + BreathRecoveryRate * deltaTime);
                }
                else if (holdingBreath)
                {
                    float breathLoss = BreathDepletionRate *
                        WorkerBreathRateMultiplier(worker) *
                        WorkerDiseaseBreathRateMultiplier(worker) *
                        deltaTime;
                    worker.Breath = Mathf.Max(0f, worker.Breath - breathLoss);
                    worker.Stress = Mathf.Min(100f, worker.Stress + BreathSuffocationStressRate * (1f - worker.Breath / BreathCapacity) * deltaTime);
                }

                if (holdingBreath && worker.Breath <= 0f)
                {
                    worker.Stress = Mathf.Min(100f, worker.Stress + BreathSuffocationStressRate * deltaTime);
                    worker.Health = Mathf.Max(0f, worker.Health - BreathSuffocationDamageRate * deltaTime);
                    worker.WorkSpeed = Mathf.Min(0.65f, effectiveWorkSpeed);
                }
                else
                {
                    if (breathingComfortably)
                    {
                        worker.Stress = Mathf.Max(0f, worker.Stress - 0.6f * deltaTime);
                        if (worker.Calories > 500f)
                        {
                            worker.Health = Mathf.Min(100f, worker.Health + 0.35f * deltaTime);
                        }
                    }

                    worker.WorkSpeed = holdingBreath ? Mathf.Min(0.82f, effectiveWorkSpeed) : effectiveWorkSpeed;
                }

                if (!sleeping && localDecor > 0.05f)
                {
                    worker.Stress = Mathf.Max(0f, worker.Stress - DecorStressReliefRate(localDecor) * deltaTime);
                }

                UpdateDrabSurroundings(worker, sleeping, localDecor, deltaTime);

                if (!sleeping && IsDowntime(worker))
                {
                    worker.Stress = Mathf.Max(0f, worker.Stress - 0.45f * deltaTime);
                    worker.Morale = Mathf.Min(10f, worker.Morale + 0.04f * deltaTime);
                }

                float roomRelief = RoomPassiveStressReliefRate(worker.Cell.x, worker.Cell.y);
                if (!sleeping && roomRelief > 0f)
                {
                    worker.Stress = Mathf.Max(0f, worker.Stress - roomRelief * deltaTime);
                }

                UpdateWorkerMorale(worker, deltaTime);
                UpdateWorkerOverjoyed(worker, deltaTime);
            }

            if (!sleeping && worker.Trait == WorkerTrait.Anxious)
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + 0.18f * deltaTime);
            }

            if (worker.Sickness >= 70f)
            {
                worker.Health = Mathf.Max(0f, worker.Health - 0.9f * deltaTime);
                worker.Stress = Mathf.Min(100f, worker.Stress + 1.1f * deltaTime);
            }

            UpdateWorkerDisease(worker, deltaTime);
            UpdateMedicalCotRecovery(worker, sleeping, deltaTime);

            if (worker.Fatigue >= ExhaustedFatigueThreshold && !sleeping)
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + 2.4f * deltaTime);
                worker.Health = Mathf.Max(0f, worker.Health - 0.8f * deltaTime);
            }

            worker.Calories = Mathf.Max(0f, worker.Calories - (sleeping ? 0.05f : 0.22f) * WorkerCalorieBurnMultiplier(worker) * (redAlertActive && !sleeping ? RedAlertCalorieBurnMultiplier : 1f) * deltaTime);
            if (worker.Calories < 900f &&
                CanWorkerEatStoredFood(worker) &&
                (CountCells(CellKind.MessTable) == 0 || worker.Calories < 250f))
            {
                EatStoredFood(worker, false);
            }

            if (worker.Calories <= 0f)
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + 5f * deltaTime);
                worker.Health = Mathf.Max(0f, worker.Health - 4.5f * deltaTime);
            }
        }

        private void ApplySchedulePressure(Worker worker, bool sleeping, float deltaTime)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                sleeping ||
                worker.StressBreakSeconds > 0f ||
                redAlertActive ||
                (worker.AssignedJob != null && worker.AssignedJob.YellowAlert))
            {
                return;
            }

            JobType? current = worker.AssignedJob != null ? worker.AssignedJob.Type : (JobType?)null;
            if (IsMealTime(worker) &&
                current != JobType.Eat &&
                worker.Calories < ScheduledMealCalorieThreshold)
            {
                float severity = Mathf.Clamp01((ScheduledMealCalorieThreshold - worker.Calories) / ScheduledMealCalorieThreshold);
                worker.Stress = Mathf.Min(100f, worker.Stress + MissedMealStressRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
                worker.Morale = Mathf.Max(0f, worker.Morale - MissedMealMoraleDropRate * severity * deltaTime);
            }

            if (IsDowntime(worker) &&
                current != JobType.Relax &&
                CountUsableRelaxationStations() > 0 &&
                worker.Stress >= ScheduledDowntimeStressThreshold)
            {
                float severity = Mathf.Clamp01((worker.Stress - ScheduledDowntimeStressThreshold) / Mathf.Max(0.001f, 100f - ScheduledDowntimeStressThreshold));
                worker.Stress = Mathf.Min(100f, worker.Stress + MissedDowntimeStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
                worker.Morale = Mathf.Max(0f, worker.Morale - MissedDowntimeMoraleDropRate * severity * deltaTime);
            }
        }

        private void UpdateDrowsyStress(Worker worker, bool sleeping, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || sleeping || deltaTime <= 0f || worker.Fatigue < DrowsyFatigueThreshold)
            {
                return;
            }

            float severity = Mathf.InverseLerp(DrowsyFatigueThreshold, ExhaustedCollapseTriggerFatigue, worker.Fatigue);
            float stressRate = worker.Fatigue >= VeryTiredFatigueThreshold
                ? Mathf.Lerp(DrowsyStressRate, VeryTiredStressRate, severity)
                : DrowsyStressRate * Mathf.Lerp(0.35f, 1f, severity);
            worker.Stress = Mathf.Min(100f, worker.Stress + stressRate * deltaTime);
        }

        private void UpdateDrabSurroundings(Worker worker, bool sleeping, float localDecor, float deltaTime)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                sleeping ||
                deltaTime <= 0f ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                !IsPassable(worker.Cell.x, worker.Cell.y))
            {
                return;
            }

            float severity = DrabDecorSeverity(localDecor);
            if (severity <= 0f)
            {
                return;
            }

            worker.Stress = Mathf.Min(100f, worker.Stress + DrabDecorStressRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
        }

        private void ApplyCommutePressure(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            worker.CommuteSeconds = Mathf.Min(CycleLengthSeconds, worker.CommuteSeconds + deltaTime);
            if (worker.CommuteSeconds <= LongCommuteThresholdSeconds)
            {
                return;
            }

            float severity = Mathf.Clamp01((worker.CommuteSeconds - LongCommuteThresholdSeconds) / Mathf.Max(0.001f, LongCommuteSevereThresholdSeconds - LongCommuteThresholdSeconds));
            worker.Stress = Mathf.Min(100f, worker.Stress + LongCommuteStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + LongCommuteFatigueRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
        }

        private bool UpdateExhaustedCollapse(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return false;
            }

            if (IsSleeping(worker) || worker.NarcolepticNapSeconds > 0f)
            {
                worker.ExhaustedCollapseSeconds = 0f;
                return false;
            }

            if (worker.ExhaustedCollapseSeconds <= 0f)
            {
                if (worker.Fatigue < ExhaustedCollapseTriggerFatigue)
                {
                    return false;
                }

                StartExhaustedCollapse(worker);
            }

            worker.Activity = "Exhausted Collapse";
            worker.ExhaustedCollapseSeconds = Mathf.Max(0f, worker.ExhaustedCollapseSeconds - deltaTime);
            worker.Fatigue = Mathf.Max(0f, worker.Fatigue - ExhaustedCollapseRestRate * deltaTime);
            worker.Stress = Mathf.Min(100f, worker.Stress + ExhaustedCollapseStressRate * deltaTime);

            if (worker.ExhaustedCollapseSeconds <= 0f || worker.Fatigue <= ExhaustedCollapseWakeFatigue)
            {
                worker.ExhaustedCollapseSeconds = 0f;
                worker.Fatigue = Mathf.Min(worker.Fatigue, ExhaustedCollapseWakeFatigue);
                AddSoreBack(worker, ExhaustedCollapseSoreBackSeconds);
                worker.Activity = "Idle";
                Log(worker.Name + " woke sore from an exhaustion collapse.");
            }

            return true;
        }

        private void StartExhaustedCollapse(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return;
            }

            ClearAssignment(worker);
            worker.ExhaustedCollapseSeconds = ExhaustedCollapseDurationSeconds;
            worker.Stress = Mathf.Min(100f, worker.Stress + 2f);
            worker.Activity = "Exhausted Collapse";
            overlayDirty = true;
            Log(worker.Name + " collapsed from exhaustion.");
        }

        private bool UpdateNarcolepticNap(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || worker.Trait != WorkerTrait.Narcoleptic)
            {
                if (worker != null)
                {
                    worker.NarcolepticNapSeconds = 0f;
                    worker.NarcolepticCooldownSeconds = 0f;
                }

                return false;
            }

            if (IsSleeping(worker))
            {
                worker.NarcolepticNapSeconds = 0f;
                worker.NarcolepticCooldownSeconds = Mathf.Max(worker.NarcolepticCooldownSeconds, NarcolepticNapCooldownSeconds * 0.35f);
                return false;
            }

            if (worker.NarcolepticNapSeconds <= 0f)
            {
                worker.NarcolepticCooldownSeconds = Mathf.Max(0f, worker.NarcolepticCooldownSeconds - deltaTime);
                if (worker.NarcolepticCooldownSeconds > 0f || worker.Fatigue < 18f)
                {
                    return false;
                }

                StartNarcolepticNap(worker);
            }

            worker.Activity = "Narcoleptic Nap";
            worker.NarcolepticNapSeconds = Mathf.Max(0f, worker.NarcolepticNapSeconds - deltaTime);
            worker.Fatigue = Mathf.Max(0f, worker.Fatigue - NarcolepticNapRestRate * deltaTime);
            worker.Stress = Mathf.Max(0f, worker.Stress - NarcolepticNapStressReliefRate * deltaTime);
            if (worker.NarcolepticNapSeconds <= 0f)
            {
                worker.NarcolepticCooldownSeconds = NarcolepticNapCooldownSeconds + Mathf.Abs(workers.IndexOf(worker) % 5) * NarcolepticNapStaggerSeconds;
                worker.Activity = "Idle";
                Log(worker.Name + " woke from a narcoleptic nap.");
            }

            return true;
        }

        private void StartNarcolepticNap(Worker worker)
        {
            ClearAssignment(worker);
            worker.Path.Clear();
            worker.PathIndex = 0;
            worker.NarcolepticNapSeconds = NarcolepticNapDurationSeconds;
            worker.Activity = "Narcoleptic Nap";
            Log(worker.Name + " fell into a narcoleptic nap.");
            overlayDirty = true;
        }

        private void UpdateFlatulence(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || worker.Trait != WorkerTrait.Flatulent)
            {
                if (worker != null)
                {
                    worker.FlatulenceCooldownSeconds = 0f;
                }

                return;
            }

            worker.FlatulenceCooldownSeconds = Mathf.Max(0f, worker.FlatulenceCooldownSeconds - deltaTime);
            if (worker.FlatulenceCooldownSeconds > 0f)
            {
                return;
            }

            float beforeGas = TileGasTotal(worker.Cell.x, worker.Cell.y);
            AddGasToTile(worker.Cell.x, worker.Cell.y, 0f, 0f, 0f, 0f, 0f, FlatulentNaturalGasAmount, 0f);
            float added = Mathf.Max(0f, TileGasTotal(worker.Cell.x, worker.Cell.y) - beforeGas);
            worker.FlatulenceGasProduced += added;
            worker.Stress = Mathf.Max(0f, worker.Stress - FlatulentStressRelief);
            worker.FlatulenceCooldownSeconds = FlatulentIntervalSeconds + Mathf.Abs(workers.IndexOf(worker) % 6) * FlatulentStaggerSeconds;
            if (added > 0.001f)
            {
                gasDirty = true;
                overlayDirty = currentOverlayMode == OverlayMode.Gas || currentOverlayMode == OverlayMode.Ventilation;
                Log(worker.Name + " released natural gas.");
            }
        }

        private void UpdateSoggyFeet(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            bool protectedSuit = worker.SuitEquipped || worker.LeadSuitEquipped;
            bool standingInLiquid = !protectedSuit && IsInside(worker.Cell.x, worker.Cell.y) && HasWorldLiquidAt(worker.Cell.x, worker.Cell.y);
            if (standingInLiquid)
            {
                float massFactor = Mathf.Clamp01(waterMass[worker.Cell.x, worker.Cell.y] / Mathf.Max(1f, MoppableSpillMaxMass));
                worker.SoggyFeetSeconds = Mathf.Min(SoggyFeetDurationSeconds, worker.SoggyFeetSeconds + Mathf.Lerp(1.0f, 2.2f, massFactor) * deltaTime);
                ApplyPollutedLiquidFootExposure(worker, massFactor, deltaTime);
            }
            else
            {
                worker.SoggyFeetSeconds = Mathf.Max(0f, worker.SoggyFeetSeconds - SoggyFeetDryRate * deltaTime);
            }

            if (worker.SoggyFeetSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.SoggyFeetSeconds / SoggyFeetDurationSeconds);
            float stressMultiplier = IsInside(worker.Cell.x, worker.Cell.y) && IsPollutedWorldLiquidAt(worker.Cell.x, worker.Cell.y)
                ? SoggyFeetPollutedStressMultiplier
                : 1f;
            worker.Stress = Mathf.Min(100f, worker.Stress + SoggyFeetStressRate * stressMultiplier * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + SoggyFeetFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void ApplyPollutedLiquidFootExposure(Worker worker, float massFactor, float deltaTime)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                deltaTime <= 0f ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                !IsPollutedWorldLiquidAt(worker.Cell.x, worker.Cell.y))
            {
                return;
            }

            float sourceGerms = Mathf.Max(PollutedWaterSourceGermLevel(worker.Cell), PollutedWaterDefaultGermLevel * 0.45f);
            float exposure = PollutedLiquidFootGermExposureRate *
                Mathf.Lerp(0.45f, 1.35f, Mathf.Clamp01(massFactor)) *
                Mathf.Lerp(0.65f, 1.45f, Mathf.Clamp01(sourceGerms)) *
                WorkerFoodIllnessMultiplier(worker) *
                deltaTime;
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + exposure);
        }

        private void UpdateSoppingWet(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            bool protectedSuit = worker.SuitEquipped || worker.LeadSuitEquipped;
            bool deepLiquid =
                !protectedSuit &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                HasWorldLiquidAt(worker.Cell.x, worker.Cell.y) &&
                waterMass[worker.Cell.x, worker.Cell.y] >= SoppingWetLiquidMassThreshold;

            if (deepLiquid)
            {
                float massFactor = Mathf.InverseLerp(SoppingWetLiquidMassThreshold, LiquidTileCapacity, waterMass[worker.Cell.x, worker.Cell.y]);
                worker.SoppingWetSeconds = Mathf.Min(SoppingWetDurationSeconds, worker.SoppingWetSeconds + Mathf.Lerp(0.8f, 1.7f, massFactor) * deltaTime);
            }
            else
            {
                worker.SoppingWetSeconds = Mathf.Max(0f, worker.SoppingWetSeconds - SoppingWetRecoveryRate * deltaTime);
            }

            if (worker.SoppingWetSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.SoppingWetSeconds / SoppingWetDurationSeconds);
            float stressMultiplier = IsInside(worker.Cell.x, worker.Cell.y) && IsPollutedWorldLiquidAt(worker.Cell.x, worker.Cell.y)
                ? SoppingWetPollutedStressMultiplier
                : 1f;
            worker.Stress = Mathf.Min(100f, worker.Stress + SoppingWetStressRate * stressMultiplier * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + SoppingWetFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void UpdateGermyHands(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f || worker.GermyHandsSeconds <= 0f)
            {
                return;
            }

            worker.GermyHandsSeconds = Mathf.Max(0f, worker.GermyHandsSeconds - GermyHandsDecayRate * deltaTime);
            if (worker.GermyHandsSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.GermyHandsSeconds / GermyHandsDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + GermyHandsStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void UpdateDarkStress(Worker worker, bool sleeping, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            bool darkSensitive = worker.Trait == WorkerTrait.Nyctophobic;
            bool standingInDark =
                darkSensitive &&
                !sleeping &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                IsPassable(worker.Cell.x, worker.Cell.y) &&
                !IsCellLit(worker.Cell.x, worker.Cell.y);

            if (standingInDark)
            {
                worker.DarkStressSeconds = Mathf.Min(DarkStressDurationSeconds, worker.DarkStressSeconds + deltaTime);
            }
            else
            {
                worker.DarkStressSeconds = Mathf.Max(0f, worker.DarkStressSeconds - DarkStressRecoveryRate * deltaTime);
            }

            if (worker.DarkStressSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.DarkStressSeconds / DarkStressDurationSeconds);
            if (darkSensitive)
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + NyctophobicDarkStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
                worker.Fatigue = Mathf.Min(100f, worker.Fatigue + DarkStressFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            }
        }

        private void UpdateBrightSleep(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            bool sleepingInLight =
                IsSleeping(worker) &&
                worker.AssignedJob != null &&
                IsCellLit(worker.AssignedJob.Cell.x, worker.AssignedJob.Cell.y);

            if (sleepingInLight)
            {
                worker.BrightSleepSeconds = Mathf.Min(BrightSleepDurationSeconds, worker.BrightSleepSeconds + deltaTime);
            }
            else
            {
                worker.BrightSleepSeconds = Mathf.Max(0f, worker.BrightSleepSeconds - BrightSleepRecoveryRate * deltaTime);
            }

            if (!sleepingInLight || worker.BrightSleepSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.BrightSleepSeconds / BrightSleepDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + BrightSleepStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            worker.Morale = Mathf.Max(0f, worker.Morale - BrightSleepMoraleDropRate * severity * deltaTime);
        }

        private void UpdateSoreBack(Worker worker, float deltaTime)
