            float severity = Mathf.Clamp01(worker.SoreBackSeconds / SoreBackDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + SoreBackStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + SoreBackFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void AddSoreBack(Worker worker, float seconds)
        {
            if (worker == null || worker.Health <= 0f || seconds <= 0f)
