        private void UpdateNauseous(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f || worker.NauseousSeconds <= 0f)
            {
                return;
            }

            worker.NauseousSeconds = Mathf.Max(0f, worker.NauseousSeconds - NauseousRecoveryRate * deltaTime);
            if (worker.NauseousSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.NauseousSeconds / NauseousDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + NauseousStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + NauseousFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            worker.Bladder = Mathf.Min(100f, worker.Bladder + NauseousBladderRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            ApplyNauseousContamination(worker, severity, deltaTime);
        }

        private void ApplyNauseousContamination(Worker worker, float severity, float deltaTime)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                deltaTime <= 0f ||
                severity <= 0f ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                !IsPassable(worker.Cell.x, worker.Cell.y))
            {
                return;
            }

            float diseaseFactor = worker.Disease == WorkerDisease.FoodPoisoning ? 1.35f : 1f;
            float emissionMultiplier = MedicalIsolationEmissionMultiplier(worker);
            float pressure = Mathf.Max(0.05f, TileGasTotal(worker.Cell.x, worker.Cell.y));
            float amount = NauseousPollutedOxygenRate * diseaseFactor * Mathf.Lerp(0.35f, 1f, severity) * deltaTime * emissionMultiplier;
            float germEmission = NauseousGermSheddingRate * diseaseFactor * Mathf.Lerp(0.25f, 1f, severity) * deltaTime;
            medicalIsolationGermsContained += germEmission * (1f - emissionMultiplier) * pressure;
            pollutedOxygen[worker.Cell.x, worker.Cell.y] = Mathf.Min(2.5f, pollutedOxygen[worker.Cell.x, worker.Cell.y] + amount);
            germs[worker.Cell.x, worker.Cell.y] = Mathf.Clamp01(germs[worker.Cell.x, worker.Cell.y] + germEmission * emissionMultiplier);
            gasDirty = true;
            overlayDirty = true;
        }

        private float MedicalIsolationEmissionMultiplier(Worker worker)
        {
            if (!IsWorkerInMedicalIsolation(worker))
            {
                return 1f;
            }

            return RoomKindAt(worker.Cell.x, worker.Cell.y) == RoomKind.Clinic
                ? ClinicIsolationEmissionMultiplier
                : MedicalCotIsolationEmissionMultiplier;
        }

        private bool IsWorkerInMedicalIsolation(Worker worker)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                cells[worker.Cell.x, worker.Cell.y] != CellKind.MedicalCot)
            {
                return false;
            }

            return (worker.AssignedJob != null &&
                (worker.AssignedJob.Type == JobType.Treat || worker.AssignedJob.Type == JobType.MedicalRest)) ||
                worker.Activity == "Receiving Treatment" ||
                worker.Activity == "Recovering" ||
                NeedsTreatment(worker) ||
                NeedsMedicalRest(worker);
        }

        private void AddNauseous(Worker worker, float seconds)
        {
            if (worker == null || worker.Health <= 0f || seconds <= 0f)
            {
                return;
            }

            worker.NauseousSeconds = Mathf.Min(NauseousDurationSeconds, Mathf.Max(worker.NauseousSeconds, seconds));
        }

        private void AddGermyHands(Worker worker, float seconds, float germExposure)
        {
            if (worker == null || worker.Health <= 0f || seconds <= 0f)
            {
                return;
            }

            worker.GermyHandsSeconds = Mathf.Min(GermyHandsDurationSeconds, Mathf.Max(worker.GermyHandsSeconds, seconds));
            worker.FoodSafeHandsSeconds = 0f;
            if (germExposure > 0f)
            {
                worker.GermExposure = Mathf.Min(100f, worker.GermExposure + germExposure);
            }
        }

        private void CleanGermyHands(Worker worker, float quality)
        {
            if (worker == null || worker.GermyHandsSeconds <= 0f)
            {
                return;
            }

            worker.GermyHandsSeconds = Mathf.Max(0f, worker.GermyHandsSeconds - GermyHandsDurationSeconds * Mathf.Clamp01(quality));
        }

        private void MarkFoodSafeHands(Worker worker, float quality)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return;
            }

            worker.FoodSafeHandsSeconds = Mathf.Max(worker.FoodSafeHandsSeconds, FoodSafeHandsDurationSeconds * Mathf.Clamp01(quality));
        }

        private void UpdateYuckyLungs(Worker worker, bool breathingProtected, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            bool breathingPollutedAir =
                !breathingProtected &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                IsPassable(worker.Cell.x, worker.Cell.y) &&
                pollutedOxygen[worker.Cell.x, worker.Cell.y] >= YuckyLungsPollutedOxygenThreshold;

            if (breathingPollutedAir)
            {
                float localSeverity = Mathf.InverseLerp(YuckyLungsPollutedOxygenThreshold, 0.75f, pollutedOxygen[worker.Cell.x, worker.Cell.y]);
                worker.YuckyLungsSeconds = Mathf.Min(YuckyLungsDurationSeconds, worker.YuckyLungsSeconds + Mathf.Lerp(0.9f, 1.8f, localSeverity) * deltaTime);
            }
            else
            {
                worker.YuckyLungsSeconds = Mathf.Max(0f, worker.YuckyLungsSeconds - YuckyLungsRecoveryRate * deltaTime);
            }

            if (worker.YuckyLungsSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.YuckyLungsSeconds / YuckyLungsDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + YuckyLungsStressRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + YuckyLungsFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void UpdatePoppedEardrums(Worker worker, bool suitProtected, float localPressure, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            if (!suitProtected && localPressure > OverpressureStressThreshold)
            {
                float pressureSeverity = Mathf.InverseLerp(OverpressureStressThreshold, OverpressureDamageThreshold, localPressure);
                worker.PoppedEardrumsSeconds = Mathf.Min(PoppedEardrumsDurationSeconds, worker.PoppedEardrumsSeconds + Mathf.Lerp(0.7f, 1.7f, pressureSeverity) * deltaTime);
            }
            else
            {
                worker.PoppedEardrumsSeconds = Mathf.Max(0f, worker.PoppedEardrumsSeconds - PoppedEardrumsRecoveryRate * deltaTime);
            }

            if (worker.PoppedEardrumsSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.PoppedEardrumsSeconds / PoppedEardrumsDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + PoppedEardrumsStressRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + PoppedEardrumsFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void UpdateIrritatedEyes(Worker worker, bool suitProtected, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            bool chlorineExposure =
                !suitProtected &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                IsPassable(worker.Cell.x, worker.Cell.y) &&
                chlorine[worker.Cell.x, worker.Cell.y] > ChlorineExposureThreshold;

            if (chlorineExposure)
            {
                float localSeverity = Mathf.InverseLerp(ChlorineExposureThreshold, ChlorineExposureThreshold * 8f, chlorine[worker.Cell.x, worker.Cell.y]);
                worker.IrritatedEyesSeconds = Mathf.Min(IrritatedEyesDurationSeconds, worker.IrritatedEyesSeconds + Mathf.Lerp(0.8f, 1.8f, localSeverity) * deltaTime);
            }
            else
            {
                worker.IrritatedEyesSeconds = Mathf.Max(0f, worker.IrritatedEyesSeconds - IrritatedEyesRecoveryRate * deltaTime);
            }

            if (worker.IrritatedEyesSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.IrritatedEyesSeconds / IrritatedEyesDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + IrritatedEyesStressRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + IrritatedEyesFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private void UpdateScalded(Worker worker, float scaldSeverity, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            if (scaldSeverity > 0.001f)
            {
                worker.ScaldedSeconds = Mathf.Min(ScaldedDurationSeconds, worker.ScaldedSeconds + Mathf.Lerp(0.8f, 1.8f, Mathf.Clamp01(scaldSeverity)) * deltaTime);
            }
            else
            {
                worker.ScaldedSeconds = Mathf.Max(0f, worker.ScaldedSeconds - ScaldedRecoveryRate * deltaTime);
            }

            if (worker.ScaldedSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.ScaldedSeconds / ScaldedDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + ScaldedStressRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + ScaldedFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
        }

        private float BreathableAirAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            return oxygen[x, y] + pollutedOxygen[x, y] * PollutedOxygenBreathability;
        }

        private bool IsWorkerHoldingBreath(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                IsPassable(worker.Cell.x, worker.Cell.y) &&
                !HasWorkerBreathingGearOxygen(worker) &&
                BreathableAirAt(worker.Cell.x, worker.Cell.y) < BreathLowAirThreshold;
        }

        private void ConsumeBreathableAir(Vector2Int cell, float amount)
        {
            if (!IsInside(cell.x, cell.y) || amount <= 0f)
            {
                return;
            }

            float oxygenUsed = Mathf.Min(oxygen[cell.x, cell.y], amount);
            oxygen[cell.x, cell.y] = Mathf.Max(0f, oxygen[cell.x, cell.y] - oxygenUsed);
            float remainingBreath = Mathf.Max(0f, amount - oxygenUsed);
            float pollutedUsed = 0f;
            if (remainingBreath > 0f && pollutedOxygen[cell.x, cell.y] > 0f)
            {
                pollutedUsed = Mathf.Min(pollutedOxygen[cell.x, cell.y], remainingBreath / PollutedOxygenBreathability);
                pollutedOxygen[cell.x, cell.y] = Mathf.Max(0f, pollutedOxygen[cell.x, cell.y] - pollutedUsed);
            }

            float consumedBreath = oxygenUsed + pollutedUsed * PollutedOxygenBreathability;
            carbonDioxide[cell.x, cell.y] = Mathf.Min(2.5f, carbonDioxide[cell.x, cell.y] + consumedBreath * 0.82f);
        }

        private void ShedWorkerAirborneDiseaseGerms(Worker worker, bool sleeping, float deltaTime)
        {
            if (worker == null ||
                worker.Disease != WorkerDisease.Slimelung ||
                deltaTime <= 0f ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                !IsPassable(worker.Cell.x, worker.Cell.y) ||
                BreathableAirAt(worker.Cell.x, worker.Cell.y) < BreathLowAirThreshold)
            {
                return;
            }

            float sicknessFactor = Mathf.Lerp(0.45f, 1.35f, Mathf.Clamp01(worker.Sickness / 100f));
            if (worker.Sickness >= SlimelungSevereSheddingThreshold)
            {
                sicknessFactor *= 1.35f;
            }

            if (pollutedOxygen[worker.Cell.x, worker.Cell.y] > SlimelungPollutedOxygenThreshold)
            {
                sicknessFactor *= 1.25f;
            }

            if (sleeping)
            {
                sicknessFactor *= 0.65f;
            }

            float emissionMultiplier = MedicalIsolationEmissionMultiplier(worker);
            float germBefore = germs[worker.Cell.x, worker.Cell.y];
            float rawGermAdded = Mathf.Min(1f - germBefore, SlimelungAirborneSheddingRate * sicknessFactor * deltaTime);
            float germAdded = rawGermAdded * emissionMultiplier;
            if (germAdded <= 0f)
            {
                return;
            }

            float pressure = Mathf.Max(0.05f, TileGasTotal(worker.Cell.x, worker.Cell.y));
            germs[worker.Cell.x, worker.Cell.y] = Mathf.Clamp01(germBefore + germAdded);
            pollutedOxygen[worker.Cell.x, worker.Cell.y] = Mathf.Min(
                2.8f,
                pollutedOxygen[worker.Cell.x, worker.Cell.y] + SlimelungPollutedOxygenSheddingRate * sicknessFactor * deltaTime * emissionMultiplier);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + SlimelungSickAirwayExposure * deltaTime);
            airborneDiseaseGermsShed += germAdded * pressure;
            medicalIsolationGermsContained += (rawGermAdded - germAdded) * pressure;
            gasDirty = true;
            overlayDirty = true;
        }

        private void UpdateAllergicReaction(Worker worker, bool breathingProtected, bool sleeping, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            if (worker.Trait != WorkerTrait.Allergic)
            {
                worker.AllergicReactionSeconds = Mathf.Max(0f, worker.AllergicReactionSeconds - AllergicReactionRecoveryRate * deltaTime);
                return;
            }

            float allergen = !breathingProtected && IsInside(worker.Cell.x, worker.Cell.y) && IsPassable(worker.Cell.x, worker.Cell.y)
                ? FloralAllergenScoreAt(worker.Cell.x, worker.Cell.y)
                : 0f;
            if (allergen > 0.05f)
            {
                float gainRate = Mathf.Lerp(0.45f, 1.35f, Mathf.Clamp01(allergen));
                worker.AllergicReactionSeconds = Mathf.Min(AllergicReactionDurationSeconds, worker.AllergicReactionSeconds + gainRate * (sleeping ? 0.55f : 1f) * deltaTime);
            }
            else
            {
                worker.AllergicReactionSeconds = Mathf.Max(0f, worker.AllergicReactionSeconds - AllergicReactionRecoveryRate * deltaTime);
            }

            if (worker.AllergicReactionSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.AllergicReactionSeconds / AllergicReactionDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + AllergicReactionStressRate * Mathf.Lerp(0.35f, 1f, severity) * (sleeping ? 0.45f : 1f) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + AllergicReactionFatigueRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);

            if (breathingProtected ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                !IsPassable(worker.Cell.x, worker.Cell.y) ||
                BreathableAirAt(worker.Cell.x, worker.Cell.y) < BreathLowAirThreshold)
            {
                return;
            }

            float germBefore = germs[worker.Cell.x, worker.Cell.y];
            float germAdded = Mathf.Min(1f - germBefore, AllergicReactionGermShedRate * Mathf.Lerp(0.30f, 1.20f, severity) * deltaTime);
            if (germAdded <= 0f)
            {
                return;
            }

            float pressure = Mathf.Max(0.05f, TileGasTotal(worker.Cell.x, worker.Cell.y));
            germs[worker.Cell.x, worker.Cell.y] = Mathf.Clamp01(germBefore + germAdded);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + 0.04f * Mathf.Lerp(0.5f, 1.25f, severity) * deltaTime);
            airborneDiseaseGermsShed += germAdded * pressure;
            gasDirty = true;
            overlayDirty = true;
        }

        private float FloralAllergenScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float score = 0f;
            for (int dy = -FloralAllergenRadius; dy <= FloralAllergenRadius; dy++)
            {
                for (int dx = -FloralAllergenRadius; dx <= FloralAllergenRadius; dx++)
                {
                    int nx = x + dx;
                    int ny = y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > FloralAllergenRadius || !IsInside(nx, ny))
                    {
                        continue;
                    }

                    float source = FloralAllergenSourceAt(nx, ny);
                    if (source <= 0f)
                    {
                        continue;
                    }

                    score += source * Mathf.Lerp(0.10f, 1f, 1f - distance / (float)(FloralAllergenRadius + 1));
                }
            }

            return Mathf.Clamp01(score);
        }

        private float FloralAllergenSourceAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            CellKind kind = cells[x, y];
            if (kind == CellKind.DecorPlant)
            {
                return 1f;
            }

            if (kind == CellKind.HydroponicFarm)
            {
                float growth = Mathf.Clamp01(plantGrowth[x, y]);
                return growth >= 0.25f ? Mathf.Lerp(0.20f, 0.85f, Mathf.InverseLerp(0.25f, 1f, growth)) : 0f;
            }

            if (kind == CellKind.PepperPlant)
            {
                float growth = Mathf.Clamp01(plantGrowth[x, y]);
                return growth >= 0.25f ? Mathf.Lerp(0.15f, 0.65f, Mathf.InverseLerp(0.25f, 1f, growth)) : 0f;
            }

            return 0f;
        }

        private void UpdateSuitFatigue(Worker worker, bool sleeping, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            float gearLoad = WorkerSuitFatigueLoad(worker);
            if (gearLoad > 0f)
            {
                float loadRate = gearLoad * (sleeping ? 0.40f : 1f);
                worker.SuitFatigueSeconds = Mathf.Min(SuitFatigueDurationSeconds, worker.SuitFatigueSeconds + loadRate * deltaTime);
            }
            else
            {
                worker.SuitFatigueSeconds = Mathf.Max(0f, worker.SuitFatigueSeconds - SuitFatigueRecoveryRate * deltaTime);
            }

            if (worker.SuitFatigueSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.SuitFatigueSeconds / SuitFatigueDurationSeconds);
            worker.Stress = Mathf.Min(100f, worker.Stress + SuitFatigueStressRate * Mathf.Lerp(0.25f, 1f, severity) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + SuitFatigueFatigueRate * Mathf.Lerp(0.35f, 1f, severity) * deltaTime);
        }

        private void ApplyWorkerSourGasExposure(Worker worker, bool breathingProtected, float deltaTime)
        {
            if (worker == null || breathingProtected || !IsInside(worker.Cell.x, worker.Cell.y) || !IsPassable(worker.Cell.x, worker.Cell.y))
            {
                return;
            }

            if (sourGas[worker.Cell.x, worker.Cell.y] <= SourGasExposureThreshold)
            {
                return;
            }

            float severity = SourGasSeverity(worker.Cell);
            sourGasExposureSeconds += deltaTime;
            worker.Stress = Mathf.Min(100f, worker.Stress + SourGasStressRate * severity * deltaTime);
            worker.Sickness = Mathf.Min(100f, worker.Sickness + SourGasSicknessRate * severity * deltaTime);
            worker.YuckyLungsSeconds = Mathf.Min(YuckyLungsDurationSeconds, worker.YuckyLungsSeconds + Mathf.Lerp(0.7f, 1.5f, severity) * deltaTime);
            worker.IrritatedEyesSeconds = Mathf.Min(IrritatedEyesDurationSeconds, worker.IrritatedEyesSeconds + Mathf.Lerp(0.5f, 1.25f, severity) * deltaTime);

            float beforeHealth = worker.Health;
            worker.Health = Mathf.Max(0f, worker.Health - SourGasDamageRate * severity * deltaTime);
            sourGasHealthDamage += Mathf.Max(0f, beforeHealth - worker.Health);
        }

        private float WorkerSuitFatigueLoad(Worker worker)
        {
            if (worker == null)
            {
                return 0f;
            }

            if (worker.LeadSuitEquipped)
            {
                return 1.35f;
            }

            if (worker.SuitEquipped)
            {
                return 1.0f;
            }

            return worker.OxygenMaskEquipped ? 0.45f : 0f;
        }

        private float EnvironmentalDangerScore(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return 1f;
            }

            float localTemperature = temperature[cell.x, cell.y];
            float heatSeverity = localTemperature <= ThermalHeatStressTemperature ? 0f :
                Mathf.InverseLerp(ThermalHeatStressTemperature, ThermalHeatDamageTemperature, localTemperature);
            float coldSeverity = localTemperature >= ThermalColdStressTemperature ? 0f :
                Mathf.InverseLerp(ThermalColdStressTemperature, ThermalColdDamageTemperature, localTemperature);
            float scaldSeverity = steam[cell.x, cell.y] <= SteamScaldMassThreshold || localTemperature <= 52f ? 0f :
                Mathf.Clamp01(steam[cell.x, cell.y] / 2.8f) * Mathf.Clamp01((localTemperature - 52f) / 48f);
            float chlorineSeverity = chlorine[cell.x, cell.y] <= ChlorineExposureThreshold ? 0f :
                Mathf.InverseLerp(ChlorineExposureThreshold, ChlorineExposureThreshold * 4f, chlorine[cell.x, cell.y]);
            float sourGasSeverity = SourGasSeverity(cell);
            float pressureSeverity = TileGasTotal(cell.x, cell.y) <= OverpressureStressThreshold ? 0f :
                Mathf.InverseLerp(OverpressureStressThreshold, OverpressureDamageThreshold, TileGasTotal(cell.x, cell.y));
            return Mathf.Clamp01(Mathf.Max(heatSeverity, coldSeverity, scaldSeverity, chlorineSeverity, sourGasSeverity, pressureSeverity));
        }

        private float SourGasSeverity(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y) || sourGas[cell.x, cell.y] <= SourGasExposureThreshold)
            {
                return 0f;
            }

            return Mathf.InverseLerp(SourGasExposureThreshold, 1.4f, sourGas[cell.x, cell.y]);
        }

        private bool IsSafetyRecoveryCell(Vector2Int cell)
        {
            return IsCharacterStandableCell(cell) &&
                BreathableAirAt(cell.x, cell.y) >= BreathRecoveryAirThreshold &&
                EnvironmentalDangerScore(cell) < SafetyDangerThreshold * 0.5f;
        }

        private bool IsWorkerEnvironmentDangerous(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            float radiation = RadiationAt(worker.Cell.x, worker.Cell.y);
            if (worker.SuitEquipped && HasChargedSuitOxygen() && (worker.LeadSuitEquipped || radiation < RadiationExposureThreshold))
            {
                return false;
            }

            if (!worker.LeadSuitEquipped && radiation >= RadiationExposureThreshold)
            {
                return true;
            }

            return Mathf.Max(worker.HeatExposure, worker.ChillExposure) >= SafetyExposureThreshold ||
                EnvironmentalDangerScore(worker.Cell) >= SafetyDangerThreshold;
        }

        private bool HasRecoveredFromEnvironmentDanger(Worker worker)
        {
            return worker != null &&
                IsSafetyRecoveryCell(worker.Cell) &&
                Mathf.Max(worker.HeatExposure, worker.ChillExposure) <= SafetyExposureReleaseThreshold;
        }

        private bool IsSafetyCriticalJob(JobType type)
        {
            return type == JobType.Rescue ||
                type == JobType.Treat ||
                type == JobType.CatchBreath ||
                type == JobType.SeekSafety;
        }

        private bool CanWorkerPerformJobSafely(Worker worker, Job job, List<Vector2Int> path)
        {
            if (worker == null || job == null || worker.Health <= 0f)
            {
                return false;
            }

            if (IsSafetyCriticalJob(job.Type))
            {
                return true;
            }

            bool suitProtected = worker.SuitEquipped && HasChargedSuitOxygen();
            bool breathingProtected = suitProtected || (worker.OxygenMaskEquipped && HasChargedOxygenMask());
            Vector2Int previous = worker.Cell;
            if (path != null)
            {
                foreach (Vector2Int step in path)
                {
                    if (!CanWorkerEnterRoutineCellSafely(previous, step, ref suitProtected, ref breathingProtected))
                    {
                        return false;
                    }

                    previous = step;
                }
            }

            List<Vector2Int> workPositions = GetWorkPositions(job);
            if (workPositions.Count == 0)
            {
                return false;
            }

            if (path != null && path.Count > 0)
            {
                return CanWorkerStandForRoutineJob(path[path.Count - 1], suitProtected, breathingProtected);
            }

            foreach (Vector2Int workPosition in workPositions)
            {
                if (CanWorkerStandForRoutineJob(workPosition, suitProtected, breathingProtected))
                {
                    return true;
                }
            }

            return false;
        }

        private bool CanWorkerEnterRoutineCellSafely(Vector2Int from, Vector2Int to, ref bool suitProtected, ref bool breathingProtected)
        {
            if (suitProtected)
            {
                return true;
            }

            if (CanWorkerStandForRoutineJob(to, false, breathingProtected))
            {
                return true;
            }

            if (IsSuitCheckpointCell(from) && CanEquipSuitAtCheckpoint(from))
            {
                suitProtected = true;
                breathingProtected = true;
                return true;
            }

            if (IsOxygenMaskCheckpointCell(from) && NeedsOxygenMaskProtection(to) && CanEquipOxygenMaskAtCheckpoint(from))
            {
                breathingProtected = true;
                return true;
            }

            return false;
        }

        private bool CanWorkerStandForRoutineJob(Vector2Int cell, bool suitProtected, bool breathingProtected)
        {
            if (!IsCharacterStandableCell(cell))
            {
                return false;
            }

            if (suitProtected)
            {
                return true;
            }

            if (breathingProtected)
            {
                return EnvironmentalDangerScore(cell) < SafetyDangerThreshold;
            }

            return BreathableAirAt(cell.x, cell.y) >= BreathRecoveryAirThreshold &&
                !NeedsSuitProtection(cell) &&
                EnvironmentalDangerScore(cell) < SafetyDangerThreshold;
        }

        private void ApplyWorkerThermalExposure(Worker worker, float localTemperature, float localSteam, bool suitProtected, float deltaTime)
        {
            if (worker == null)
            {
                return;
            }

            if (suitProtected)
            {
                worker.HeatExposure = Mathf.Max(0f, worker.HeatExposure - ThermalExposureRecoveryRate * deltaTime);
                worker.ChillExposure = Mathf.Max(0f, worker.ChillExposure - ThermalExposureRecoveryRate * deltaTime);
                UpdateScalded(worker, 0f, deltaTime);
                return;
            }

            float heatStressTemperature = ThermalHeatStressTemperature + WorkerOutfitHeatProtection(worker);
            float heatDamageTemperature = ThermalHeatDamageTemperature + WorkerOutfitHeatProtection(worker);
            float coldStressTemperature = ThermalColdStressTemperature - WorkerOutfitColdProtection(worker);
            float coldDamageTemperature = ThermalColdDamageTemperature - WorkerOutfitColdProtection(worker);
            float heatSeverity = localTemperature <= heatStressTemperature ? 0f :
                Mathf.Clamp01((localTemperature - heatStressTemperature) / Mathf.Max(0.001f, heatDamageTemperature - heatStressTemperature));
            float coldSeverity = localTemperature >= coldStressTemperature ? 0f :
                Mathf.Clamp01((coldStressTemperature - localTemperature) / Mathf.Max(0.001f, coldStressTemperature - coldDamageTemperature));
            float scaldSeverity = localSteam <= SteamScaldMassThreshold || localTemperature <= 52f ? 0f :
                Mathf.Clamp01(localSteam / 2.8f) * Mathf.Clamp01((localTemperature - 52f) / 48f);
            UpdateScalded(worker, scaldSeverity, deltaTime);
            heatSeverity = Mathf.Clamp01(heatSeverity + scaldSeverity * 1.35f);

            if (heatSeverity > 0.001f)
            {
                float previous = worker.HeatExposure;
                worker.HeatExposure = Mathf.Min(100f, worker.HeatExposure + heatSeverity * ThermalExposureBuildRate * deltaTime);
                worker.ChillExposure = Mathf.Max(0f, worker.ChillExposure - ThermalExposureRecoveryRate * 0.65f * deltaTime);
                worker.Stress = Mathf.Min(100f, worker.Stress + Mathf.Lerp(1.2f, 3.2f, heatSeverity) * deltaTime);
                thermalExposureSeconds += deltaTime;
                if (previous < ThermalInjuryExposureThreshold && worker.HeatExposure >= ThermalInjuryExposureThreshold)
                {
                    heatStrokeCases++;
                    ContractWorkerDisease(worker, WorkerDisease.HeatStroke, 32f, worker.Name + " developed Heat Stroke. Cool the area or use atmo suits.");
                }

                if (worker.HeatExposure >= ThermalInjuryExposureThreshold || localTemperature > heatDamageTemperature || scaldSeverity > 0.08f)
                {
                    float damageSeverity = Mathf.Max(heatSeverity, Mathf.InverseLerp(ThermalInjuryExposureThreshold, 100f, worker.HeatExposure));
                    float beforeHealth = worker.Health;
                    worker.Health = Mathf.Max(0f, worker.Health - ThermalExposureDamageRate * damageSeverity * deltaTime);
                    thermalHealthDamage += Mathf.Max(0f, beforeHealth - worker.Health);
                }
            }
            else
            {
                worker.HeatExposure = Mathf.Max(0f, worker.HeatExposure - ThermalExposureRecoveryRate * deltaTime);
            }

            if (coldSeverity > 0.001f)
            {
                float previous = worker.ChillExposure;
                worker.ChillExposure = Mathf.Min(100f, worker.ChillExposure + coldSeverity * ThermalExposureBuildRate * deltaTime);
                worker.HeatExposure = Mathf.Max(0f, worker.HeatExposure - ThermalExposureRecoveryRate * 0.65f * deltaTime);
                worker.Stress = Mathf.Min(100f, worker.Stress + Mathf.Lerp(1.0f, 2.8f, coldSeverity) * deltaTime);
                thermalExposureSeconds += deltaTime;
                if (previous < ThermalInjuryExposureThreshold && worker.ChillExposure >= ThermalInjuryExposureThreshold)
                {
                    hypothermiaCases++;
                    ContractWorkerDisease(worker, WorkerDisease.Hypothermia, 32f, worker.Name + " developed Hypothermia. Warm the area or use atmo suits.");
                }

                if (worker.ChillExposure >= ThermalInjuryExposureThreshold || localTemperature < coldDamageTemperature)
                {
                    float damageSeverity = Mathf.Max(coldSeverity, Mathf.InverseLerp(ThermalInjuryExposureThreshold, 100f, worker.ChillExposure));
                    float beforeHealth = worker.Health;
                    worker.Health = Mathf.Max(0f, worker.Health - ThermalExposureDamageRate * damageSeverity * deltaTime);
                    thermalHealthDamage += Mathf.Max(0f, beforeHealth - worker.Health);
                }
            }
            else
            {
                worker.ChillExposure = Mathf.Max(0f, worker.ChillExposure - ThermalExposureRecoveryRate * deltaTime);
            }
        }

        private void TriggerBladderAccident(Worker worker)
        {
            worker.Bladder = 18f;
            worker.Stress = Mathf.Min(100f, worker.Stress + 18f);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + 16f);
            AddGermyHands(worker, 64f, 8f);
            AddAccidentShame(worker);

            if (IsInside(worker.Cell.x, worker.Cell.y) && IsPassable(worker.Cell.x, worker.Cell.y))
            {
                pollutedOxygen[worker.Cell.x, worker.Cell.y] = Mathf.Min(2.5f, pollutedOxygen[worker.Cell.x, worker.Cell.y] + 0.75f);
                germs[worker.Cell.x, worker.Cell.y] = Mathf.Clamp01(germs[worker.Cell.x, worker.Cell.y] + 0.55f);
                gasDirty = true;
                overlayDirty = true;
            }

            Log(worker.Name + " had an accident. Build more outhouses.");
        }

        private bool ShouldTriggerStressBreak(Worker worker)
        {
            return worker != null && worker.Health > 0f && worker.StressBreakSeconds <= 0f && worker.Stress >= 98f;
        }

        private void StartStressBreak(Worker worker)
        {
            ClearAssignment(worker);
            worker.OverjoyedSeconds = 0f;
            worker.OverjoyedCooldownSeconds = OverjoyedCooldownSeconds;
            worker.StressBreakSeconds = StressReactionDuration(worker);
            worker.StressBreakPulseTimer = 0f;
            worker.Activity = StressReactionActivity(worker);
            ApplyStressReactionPulse(worker, true);
            Log(worker.Name + " hit critical stress: " + WorkerStressReactionName(worker.StressReaction) + ".");
        }

        private void UpdateStressBreak(Worker worker, float deltaTime)
        {
            if (worker.AssignedJob != null)
            {
                ClearAssignment(worker);
            }

            worker.Activity = StressReactionActivity(worker);
            worker.Path.Clear();
            worker.PathIndex = 0;
            worker.StressBreakSeconds = Mathf.Max(0f, worker.StressBreakSeconds - deltaTime);
            worker.StressBreakPulseTimer -= deltaTime;
            worker.Stress = Mathf.Max(54f, worker.Stress - StressReactionRecoveryRate(worker) * deltaTime);
            worker.Fatigue = Mathf.Min(100f, worker.Fatigue + StressReactionFatigueRate(worker) * deltaTime);
            worker.Calories = Mathf.Max(0f, worker.Calories - StressReactionCalorieBurnRate(worker) * deltaTime);

            if (worker.StressBreakPulseTimer <= 0f)
            {
                worker.StressBreakPulseTimer = StressReactionPulseInterval(worker);
                ApplyStressReactionPulse(worker, false);
            }

            if (worker.StressBreakSeconds <= 0f)
            {
                worker.Stress = Mathf.Min(worker.Stress, 60f);
                worker.Activity = "Idle";
                Log(worker.Name + " recovered from a stress break.");
            }
        }

        private void AddStressBreakPollution(Worker worker, float pollutedAmount, float germAmount)
        {
            if (worker == null || !IsInside(worker.Cell.x, worker.Cell.y) || !IsPassable(worker.Cell.x, worker.Cell.y))
            {
                return;
            }

            pollutedOxygen[worker.Cell.x, worker.Cell.y] = Mathf.Min(2.5f, pollutedOxygen[worker.Cell.x, worker.Cell.y] + pollutedAmount);
            germs[worker.Cell.x, worker.Cell.y] = Mathf.Clamp01(germs[worker.Cell.x, worker.Cell.y] + germAmount);
            gasDirty = true;
            overlayDirty = true;
        }

        private void ApplyStressReactionPulse(Worker worker, bool initial)
        {
            if (worker == null)
            {
                return;
            }

            switch (worker.StressReaction)
            {
                case WorkerStressReaction.BingeEater:
                    ApplyBingeEatingPulse(worker, initial);
                    break;
                case WorkerStressReaction.Destructive:
                    ApplyDestructiveStressPulse(worker, initial);
                    break;
                case WorkerStressReaction.Crier:
                    ApplyCryingStressPulse(worker, initial);
                    break;
                default:
                    ApplyVomitingStressPulse(worker, initial);
                    break;
            }
        }

        private void ApplyVomitingStressPulse(Worker worker, bool initial)
        {
            float pollutedGas = initial ? 0.34f : 0.12f;
            float germsAdded = initial ? 0.16f : 0.06f;
            AddStressBreakPollution(worker, pollutedGas, germsAdded);
            AddContaminatedStressSpill(worker.Cell, initial ? 7f : 2.5f, 0.18f);
        }

        private void ApplyBingeEatingPulse(Worker worker, bool initial)
        {
            float amount = Mathf.Min(food, initial ? 520f : 260f);
            if (amount <= 0.01f)
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + (initial ? 2.5f : 1.1f));
                AddStressBreakPollution(worker, initial ? 0.10f : 0.04f, initial ? 0.04f : 0.02f);
                return;
            }

            food = Mathf.Max(0f, food - amount);
            if (food <= 1f)
            {
                food = 0f;
                foodFreshness = 1f;
                foodQuality = DefaultFoodQuality;
                foodGerms = 0f;
            }

            currentCycleReport.FoodConsumed += amount;
            worker.Calories = Mathf.Min(3600f, worker.Calories + amount * 0.72f);
            worker.Stress = Mathf.Max(48f, worker.Stress - (initial ? 1.8f : 0.9f));
            worker.Morale = Mathf.Max(0f, worker.Morale - (initial ? 0.25f : 0.10f));
        }

        private void ApplyDestructiveStressPulse(Worker worker, bool initial)
        {
            if (TryFindStressBreakDamageTarget(worker.Cell, out Vector2Int target))
            {
                DamageEquipment(target, initial ? 0.18f : 0.07f);
                worker.Stress = Mathf.Max(50f, worker.Stress - (initial ? 0.7f : 0.25f));
                overlayDirty = true;
                return;
            }

            AddStressBreakPollution(worker, initial ? 0.12f : 0.05f, initial ? 0.04f : 0.02f);
        }

        private void ApplyCryingStressPulse(Worker worker, bool initial)
        {
            AddContaminatedStressSpill(worker.Cell, initial ? 2.2f : 0.8f, 0.06f);
            AddStressBreakPollution(worker, initial ? 0.08f : 0.03f, initial ? 0.03f : 0.01f);
            SpreadCryingStress(worker, initial);
            worker.Stress = Mathf.Max(46f, worker.Stress - (initial ? 1.2f : 0.45f));
        }

        private void SpreadCryingStress(Worker source, bool initial)
        {
            if (source == null)
            {
                return;
            }

            float addedStress = initial ? CrierInitialNearbyStress : CrierPulseNearbyStress;
            foreach (Worker worker in workers)
            {
                if (worker == null || worker == source || worker.Health <= 0f || worker.StressBreakSeconds > 0f)
                {
                    continue;
                }

                int distance = Mathf.Abs(worker.Cell.x - source.Cell.x) + Mathf.Abs(worker.Cell.y - source.Cell.y);
                if (distance > CrierStressRadius)
                {
                    continue;
                }

                float falloff = 1f - (distance / (CrierStressRadius + 1f));
                worker.Stress = Mathf.Min(100f, worker.Stress + addedStress * Mathf.Max(0.25f, falloff));
                worker.Morale = Mathf.Max(0f, worker.Morale - CrierNearbyMoraleDrop * Mathf.Max(0.35f, falloff));
            }
        }

        private void AddContaminatedStressSpill(Vector2Int cell, float amount, float germAmount)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y) || amount <= 0f)
            {
                return;
            }

            waterMass[cell.x, cell.y] = Mathf.Min(MoppableSpillMaxMass, waterMass[cell.x, cell.y] + amount);
            pollutedOxygen[cell.x, cell.y] = Mathf.Min(2.5f, pollutedOxygen[cell.x, cell.y] + amount * 0.018f);
            germs[cell.x, cell.y] = Mathf.Clamp01(germs[cell.x, cell.y] + germAmount);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
        }

        private bool TryFindStressBreakDamageTarget(Vector2Int center, out Vector2Int target)
        {
            target = default;
            int bestDistance = int.MaxValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsRepairableEquipment(cells[x, y]) || equipmentCondition[x, y] <= EquipmentBrokenThreshold)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(center.x - x) + Mathf.Abs(center.y - y);
                    if (distance > 7 || distance >= bestDistance)
                    {
                        continue;
                    }

                    bestDistance = distance;
                    target = new Vector2Int(x, y);
                }
            }

            return bestDistance < int.MaxValue;
        }

        private float StressReactionDuration(Worker worker)
        {
            if (worker != null && worker.StressReaction == WorkerStressReaction.Destructive)
            {
                return 10.5f;
            }

            return worker != null && worker.StressReaction == WorkerStressReaction.Crier ? 8f : 9f;
        }

        private float StressReactionPulseInterval(Worker worker)
        {
            if (worker != null && worker.StressReaction == WorkerStressReaction.BingeEater)
            {
                return 2.0f;
            }

            return worker != null && worker.StressReaction == WorkerStressReaction.Destructive ? 1.8f : 1.5f;
        }

        private float StressReactionRecoveryRate(Worker worker)
        {
            if (worker != null && worker.StressReaction == WorkerStressReaction.Crier)
            {
                return 5.6f;
            }

            return worker != null && worker.StressReaction == WorkerStressReaction.Destructive ? 3.8f : 4.4f;
        }

        private float StressReactionFatigueRate(Worker worker)
        {
            return worker != null && worker.StressReaction == WorkerStressReaction.Destructive ? 0.24f : 0.16f;
        }

        private float StressReactionCalorieBurnRate(Worker worker)
        {
            return worker != null && worker.StressReaction == WorkerStressReaction.BingeEater ? 0f : 0.08f;
        }

        private void AssignBestJob(Worker worker)
        {
            if (NeedsTreatment(worker) && (TryAssignTreatmentJob(worker) || (TryCreateTreatmentJob(worker) && TryAssignTreatmentJob(worker))))
            {
                return;
            }

            if (NeedsSeekSafety(worker) && (TryAssignSeekSafetyJob(worker) || (TryCreateSeekSafetyJob(worker) && TryAssignSeekSafetyJob(worker))))
            {
                return;
            }

            if (NeedsCatchBreath(worker) && (TryAssignCatchBreathJob(worker) || (TryCreateCatchBreathJob(worker) && TryAssignCatchBreathJob(worker))))
            {
                return;
            }

            if (NeedsToilet(worker) && (TryAssignToiletJob(worker) || (TryCreateToiletJob(worker) && TryAssignToiletJob(worker))))
            {
                return;
            }

            if (NeedsShower(worker) && (TryAssignShowerJob(worker) || (TryCreateShowerJob(worker) && TryAssignShowerJob(worker))))
            {
                return;
            }

            if (NeedsHandWash(worker) && (TryAssignWashHandsJob(worker) || (TryCreateWashHandsJob(worker) && TryAssignWashHandsJob(worker))))
            {
                return;
            }

            if (NeedsFood(worker) && (TryAssignEatJob(worker) || (TryCreateEatJob(worker) && TryAssignEatJob(worker))))
            {
                return;
            }

            if (NeedsRelaxation(worker) && (TryAssignRelaxJob(worker) || (TryCreateRelaxJob(worker) && TryAssignRelaxJob(worker))))
            {
                return;
            }

            if (NeedsSkillScrub(worker) && (TryAssignSkillScrubJob(worker) || (TryCreateSkillScrubJob(worker) && TryAssignSkillScrubJob(worker))))
            {
                return;
            }

            if (ShouldSleep(worker) && TryAssignSleepJob(worker))
            {
                return;
            }

            if (NeedsMedicalRest(worker) && (TryAssignMedicalRestJob(worker) || (TryCreateMedicalRestJob(worker) && TryAssignMedicalRestJob(worker))))
            {
                return;
            }

            if (NeedsMedicalLeave(worker))
            {
                return;
            }

            Job bestJob = null;
            List<Vector2Int> bestPath = null;
            int bestScore = int.MinValue;

            foreach (Job job in jobs)
            {
                if (!CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, job, out List<Vector2Int> path))
                {
                    int score = JobAssignmentScore(worker, job, path.Count);
                    if (score > bestScore)
                    {
                        bestScore = score;
                        bestPath = path;
                        bestJob = job;
                    }
                }
            }

            if (bestJob == null)
            {
                return;
            }

            AssignJob(worker, bestJob, bestPath);
        }

        private bool ShouldInterruptForSchedule(Worker worker)
        {
            if (ShouldInterruptAssignedJobForYellowAlert(worker))
            {
                return true;
            }

            if (worker == null || worker.AssignedJob == null || worker.AssignedJob.AssignedWorker != worker)
            {
                return false;
            }

            JobType current = worker.AssignedJob.Type;
            if (NeedsSeekSafety(worker) && current != JobType.Rescue && current != JobType.Treat && current != JobType.SeekSafety)
            {
                return true;
            }

            if (NeedsCatchBreath(worker) &&
                current != JobType.Rescue &&
                current != JobType.Treat &&
                current != JobType.SeekSafety &&
                current != JobType.CatchBreath)
            {
                return true;
            }

            if (NeedsMedicalLeave(worker) && !IsMedicalLeaveAllowedJob(current))
            {
                return true;
            }

            if (ShouldInterruptMedicalRest(worker))
            {
                return true;
            }

            if (redAlertActive)
            {
                return false;
            }

            if (current == JobType.Rescue ||
                current == JobType.Treat ||
                current == JobType.SeekSafety ||
                current == JobType.CatchBreath ||
                current == JobType.UseToilet ||
                current == JobType.WashHands ||
                current == JobType.Shower ||
                current == JobType.Eat ||
                current == JobType.Relax ||
                current == JobType.ScrubSkill ||
                current == JobType.Sleep ||
                current == JobType.MoveTo ||
                current == JobType.MedicalRest)
            {
                return false;
            }

            if (IsRestTime(worker) && ShouldSleep(worker))
            {
                return true;
            }

            if (IsMealTime(worker) && NeedsFood(worker))
            {
                return true;
            }

            return IsDowntime(worker) && NeedsRelaxation(worker);
        }

        private bool ShouldInterruptAssignedJobForYellowAlert(Worker worker)
        {
            if (worker == null || worker.AssignedJob == null || worker.AssignedJob.YellowAlert)
            {
                return false;
            }

            if (ShouldProtectAssignedJobFromYellowAlert(worker))
            {
                return false;
            }

            return HasOpenYellowAlertJobFor(worker);
        }

        private bool ShouldInterruptMedicalRest(Worker worker)
        {
            if (worker == null || worker.AssignedJob == null || worker.AssignedJob.Type != JobType.MedicalRest)
            {
                return false;
            }

            return NeedsTreatment(worker) ||
                NeedsToilet(worker) ||
                NeedsShower(worker) ||
                NeedsHandWash(worker) ||
                NeedsFood(worker) ||
                NeedsRelaxation(worker) ||
                NeedsSkillScrub(worker) ||
                ShouldSleep(worker);
        }

        private bool ShouldProtectAssignedJobFromYellowAlert(Worker worker)
        {
            if (worker == null || worker.AssignedJob == null)
            {
                return false;
            }

            switch (worker.AssignedJob.Type)
            {
                case JobType.Rescue:
                case JobType.Treat:
                case JobType.SeekSafety:
                case JobType.CatchBreath:
                case JobType.UseToilet:
                case JobType.WashHands:
                case JobType.Shower:
                case JobType.ScrubSkill:
                case JobType.MedicalRest:
                    return true;
                case JobType.Eat:
                    return worker.Calories < 850f;
                case JobType.Sleep:
                    return worker.Fatigue >= 96f || worker.Stress >= 98f;
                case JobType.Relax:
                    return worker.Stress >= 82f;
                default:
                    return false;
            }
        }

        private bool HasOpenYellowAlertJobFor(Worker worker, bool validateJobs = true)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            foreach (Job job in jobs)
            {
                if (!job.YellowAlert || job.AssignedWorker != null)
                {
                    continue;
                }

                if (validateJobs)
                {
                    if (!CanWorkerTakeJob(worker, job))
                    {
                        continue;
                    }
                }
                else if (!CanWorkerTargetJob(worker, job))
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, job, out _))
                {
                    return true;
                }
            }

            return false;
        }

        private bool CanWorkerTargetJob(Worker worker, Job job)
        {
            if (worker == null || job == null || job.AssignedWorker != null || job.Cancelled)
            {
                return false;
            }

            if (job.Type == JobType.Rescue)
            {
                Worker patient = FindWorkerByName(job.TargetWorkerName);
                return patient != null && patient != worker && worker.Health > 0f;
            }

            return string.IsNullOrEmpty(job.TargetWorkerName) || job.TargetWorkerName == worker.Name;
        }

        private bool TryFindSafePathToJob(Worker worker, Job job, out List<Vector2Int> path)
        {
            path = null;
            return worker != null &&
                TryFindPathToJob(worker.Cell, worker, job, out path) &&
                CanWorkerPerformJobSafely(worker, job, path);
        }

        private bool AssignJob(Worker worker, Job job, List<Vector2Int> path)
        {
            if (!CanWorkerPerformJobSafely(worker, job, path))
            {
                return false;
            }

            job.AssignedWorker = worker;
            worker.AssignedJob = job;
            worker.Path = path ?? new List<Vector2Int>();
            worker.PathIndex = 0;
            worker.Activity = "Going to " + JobLabel(job);
            overlayDirty = true;
            return true;
        }

        private bool CanWorkerTakeJob(Worker worker, Job job)
        {
            if (job.AssignedWorker != null || !IsJobValid(job))
            {
                return false;
            }

            return IsJobAllowedByLaborPolicy(job) &&
                IsJobAllowedByMedicalLeave(worker, job) &&
                CanWorkerHandleFoodJob(worker, job) &&
                CanWorkerTargetJob(worker, job) &&
                CanWorkerUseJobPersonalStation(worker, job);
        }

        private bool CanWorkerHandleFoodJob(Worker worker, Job job)
        {
            if (!IsFoodHandlingJob(job) || !IsFoodHandlingHygieneRisk(worker) || IsFoodHandlingEmergency())
            {
                return true;
            }

            return !HasCleanerFoodHandlerFor(job, worker);
        }

        private bool IsFoodHandlingJob(Job job)
        {
            return job != null && job.Type == JobType.Cook;
        }

        private bool IsFoodHandlingEmergency()
        {
            return food < Mathf.Max(700f, workers.Count * 700f);
        }

        private bool IsFoodHandlingHygieneRisk(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            bool germyHands = worker.GermyHandsSeconds >= GermyHandsDurationSeconds * FoodHandlingHygieneHandsRatio;
            bool highExposure = worker.GermExposure >= FoodHandlingHygieneGermThreshold;
            bool sickWithGerms = worker.Sickness >= FoodHandlingHygieneSicknessThreshold &&
                worker.GermExposure >= FoodHandlingHygieneSickGermFloor;
            bool contagiousDisease = worker.Disease == WorkerDisease.FoodPoisoning ||
                worker.Disease == WorkerDisease.Slimelung;
            return germyHands || highExposure || sickWithGerms || contagiousDisease;
        }

        private bool HasCleanerFoodHandlerFor(Job job, Worker blockedWorker)
        {
            if (!IsFoodHandlingJob(job) ||
                job.AssignedWorker != null ||
                !IsJobValid(job) ||
                !IsJobAllowedByLaborPolicy(job))
            {
                return false;
            }

            foreach (Worker candidate in workers)
            {
                if (candidate == null ||
                    candidate == blockedWorker ||
                    candidate.Health <= 0f ||
                    IsFoodHandlingHygieneRisk(candidate) ||
                    !IsJobAllowedByMedicalLeave(candidate, job) ||
                    !CanWorkerTargetJob(candidate, job) ||
                    !CanWorkerUseJobPersonalStation(candidate, job))
                {
                    continue;
                }

                if (TryFindSafePathToJob(candidate, job, out _))
                {
                    return true;
                }
            }

            return false;
        }

        private bool IsJobAllowedByMedicalLeave(Worker worker, Job job)
        {
            return !NeedsMedicalLeave(worker) || job == null || IsMedicalLeaveAllowedJob(job.Type);
        }

        private bool IsMedicalLeaveAllowedJob(JobType type)
        {
            switch (type)
            {
                case JobType.Rescue:
                case JobType.Treat:
                case JobType.SeekSafety:
                case JobType.CatchBreath:
                case JobType.UseToilet:
                case JobType.WashHands:
                case JobType.Shower:
                case JobType.Eat:
                case JobType.Relax:
                case JobType.ScrubSkill:
                case JobType.Sleep:
                case JobType.MoveTo:
                case JobType.MedicalRest:
                    return true;
                default:
                    return false;
            }
        }

        private void UpdateJobAges(float deltaTime)
        {
            if (deltaTime <= 0f || jobs.Count == 0)
            {
                return;
            }

            foreach (Job job in jobs)
            {
                if (job.AssignedWorker == null && !job.Cancelled)
                {
                    job.AgeSeconds = Mathf.Min(JobAgingMaxSeconds, job.AgeSeconds + deltaTime);
                }
                else if (job.AssignedWorker != null)
                {
                    job.AgeSeconds = Mathf.Max(0f, job.AgeSeconds - deltaTime * 0.5f);
                }
            }
        }

        private bool TryCreateRescueJob(Worker patient)
        {
            if (!NeedsRescue(patient) || !HasUsableMedicalCot())
            {
                return false;
            }

            Job job = new Job(JobType.Rescue, patient.Cell, RescueWorkRequired(patient))
            {
                AutoGenerated = true,
                Priority = RescuePriority(patient),
                TargetWorkerName = patient.Name
            };

            if (!CanAnyOtherActiveWorkerReachJob(patient, job))
            {
                return false;
            }

            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool CanAnyOtherActiveWorkerReachJob(Worker patient, Job job)
        {
            foreach (Worker worker in workers)
            {
                if (worker == patient || worker.Health <= 0f)
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, job, out _))
                {
                    return true;
                }
            }

            return false;
        }

