        private bool TryCreateMedicalRestJob(Worker worker)
        {
            if (!NeedsMedicalRest(worker) || HasMedicalRestJobFor(worker.Name))
            {
                return false;
            }

            Vector2Int bestCell = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;

            if (!AnyWorkerNeedsTreatment())
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int cotCell = new Vector2Int(x, y);
                        if (cells[x, y] != CellKind.MedicalCot ||
                            !CanUseEquipment(cotCell) ||
                            !CanWorkerUsePersonalStation(cotCell, worker) ||
                            IsMedicalCotReserved(cotCell, worker))
                        {
                            continue;
                        }

                        Job testJob = new Job(JobType.MedicalRest, cotCell, MedicalRestWorkRequired)
                        {
                            TargetWorkerName = worker.Name
                        };

                        if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                        {
                            bestDistance = path.Count;
                            bestCell = cotCell;
                        }
                    }
                }
            }

            if (bestCell.x < 0)
            {
                if (!IsFloorMedicalRestCell(worker.Cell) || !IsPersonalRecoveryCellOpen(worker.Cell, worker))
                {
                    return false;
                }

                Job floorJob = new Job(JobType.MedicalRest, worker.Cell, MedicalRestWorkRequired * FloorMedicalRestWorkRequiredMultiplier)
                {
                    AutoGenerated = true,
                    Priority = Mathf.Max(1, MedicalRestPriority(worker) - 1),
                    TargetWorkerName = worker.Name
                };
                jobs.Add(floorJob);
                overlayDirty = true;
                return true;
            }

            Job job = new Job(JobType.MedicalRest, bestCell, MedicalRestWorkRequired)
            {
                AutoGenerated = true,
                Priority = MedicalRestPriority(worker),
                TargetWorkerName = worker.Name
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

