        private bool TryFindSafetyCell(Worker worker, out Vector2Int safeCell)
        {
            safeCell = new Vector2Int(-1, -1);
            if (worker == null)
            {
                return false;
            }

            List<Vector2Int> targets = BuildSafetyRecoveryTargets(worker, true);

            Job pathProbe = new Job(JobType.SeekSafety, worker.Cell, SafetyWorkRequired)
            {
                TargetWorkerName = worker.Name
            };
            if (!TryFindPathForJob(worker.Cell, targets, worker, pathProbe, out List<Vector2Int> path) || path.Count == 0)
            {
                return false;
            }

            safeCell = path[path.Count - 1];
            return true;
        }

        private List<Vector2Int> BuildSafetyRecoveryTargets(Worker worker, bool requireOpen)
        {
            List<Vector2Int> targets = new List<Vector2Int>();
            if (worker == null)
            {
                return targets;
            }

            int minX = Mathf.Max(0, worker.Cell.x - SafetySearchRadius);
            int maxX = Mathf.Min(WorldWidth - 1, worker.Cell.x + SafetySearchRadius);
            int minY = Mathf.Max(0, worker.Cell.y - SafetySearchRadius);
            int maxY = Mathf.Min(WorldHeight - 1, worker.Cell.y + SafetySearchRadius);
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    Vector2Int candidate = new Vector2Int(x, y);
                    if (candidate != worker.Cell &&
                        IsSafetyRecoveryCell(candidate) &&
                        (!requireOpen || IsPersonalRecoveryCellOpen(candidate, worker)))
                    {
                        targets.Add(candidate);
                    }
                }
            }

            return targets;
        }

