        private List<Vector2Int> BuildCatchBreathRecoveryTargets(Worker worker, bool requireOpen)
        {
            List<Vector2Int> targets = new List<Vector2Int>();
            if (worker == null)
            {
                return targets;
            }

            int minX = Mathf.Max(0, worker.Cell.x - CatchBreathSearchRadius);
            int maxX = Mathf.Min(WorldWidth - 1, worker.Cell.x + CatchBreathSearchRadius);
            int minY = Mathf.Max(0, worker.Cell.y - CatchBreathSearchRadius);
            int maxY = Mathf.Min(WorldHeight - 1, worker.Cell.y + CatchBreathSearchRadius);
            for (int y = minY; y <= maxY; y++)
            {
                for (int x = minX; x <= maxX; x++)
                {
                    Vector2Int candidate = new Vector2Int(x, y);
                    if (candidate != worker.Cell &&
                        IsCharacterStandableCell(candidate) &&
                        BreathableAirAt(x, y) >= BreathRecoveryAirThreshold &&
                        EnvironmentalDangerScore(candidate) < SafetyDangerThreshold &&
                        (!requireOpen || IsPersonalRecoveryCellOpen(candidate, worker)))
                    {
                        targets.Add(candidate);
                    }
                }
            }

            return targets;
        }

