        private bool TryCreateEatJob(Worker worker)
        {
            Vector2Int bestCell = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int tableCell = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.MessTable ||
                        IsMessTableReserved(tableCell) ||
                        !CanWorkerUsePersonalStation(tableCell, worker))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Eat, tableCell, EatWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path))
                    {
                        int stationDistance = path.Count - (IsPersonalStationAssignedToWorker(tableCell, worker) ? 1000 : 0);
                        if (stationDistance >= bestDistance)
                        {
                            continue;
                        }

                        bestDistance = stationDistance;
                        bestCell = tableCell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                if (!IsFloorEatCell(worker.Cell) || !IsPersonalRecoveryCellOpen(worker.Cell, worker))
                {
                    return false;
                }

                Job floorJob = new Job(JobType.Eat, worker.Cell, EatWorkRequired(worker) * 0.85f)
                {
                    AutoGenerated = true,
                    Priority = EatPriority(worker),
                    TargetWorkerName = worker.Name
                };
                jobs.Add(floorJob);
                overlayDirty = true;
                return true;
            }

            Job job = new Job(JobType.Eat, bestCell, EatWorkRequired(worker))
            {
                AutoGenerated = true,
                Priority = EatPriority(worker),
                TargetWorkerName = worker.Name
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

