            int bestDistance = int.MaxValue;

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int stationCell = new Vector2Int(x, y);
                    if (!CanUseSkillScrubberAt(stationCell) || IsSkillScrubberReserved(stationCell))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.ScrubSkill, stationCell, SkillScrubberWorkRequired)
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                        bestCell = stationCell;
                    }
                }
            }

            if (bestCell.x < 0)
            {
                return false;
            }

            Job job = new Job(JobType.ScrubSkill, bestCell, SkillScrubberWorkRequired)
            {
                AutoGenerated = true,
                Priority = SkillScrubPriority(worker),
                TargetWorkerName = worker.Name
            };
            jobs.Add(job);
            overlayDirty = true;
            return true;
        }

        private bool TryAssignSleepJob(Worker worker)
        {
            Job bestJob = null;
            List<Vector2Int> bestPath = null;
            int bestDistance = int.MaxValue;

            foreach (Job job in jobs)
            {
                if (job.Type != JobType.Sleep ||
                    job.AssignedWorker != null ||
                    (!string.IsNullOrEmpty(job.TargetWorkerName) && job.TargetWorkerName != worker.Name) ||
                    !IsJobValid(job))
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, job, out List<Vector2Int> path) && path.Count < bestDistance)
                {
                    bestDistance = path.Count;
                    bestPath = path;
                    bestJob = job;
                }
            }

            if (bestJob == null)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Vector2Int bedCell = new Vector2Int(x, y);
                        if (!CanUseBedAt(bedCell) ||
                            IsBedReserved(bedCell) ||
                            !CanWorkerUsePersonalStation(bedCell, worker))
                        {
                            continue;
                        }

                        Job sleepJob = new Job(JobType.Sleep, bedCell, SleepWorkRequired(worker))
                        {
                            AutoGenerated = true,
                            Priority = SleepPriority(worker),
                            TargetWorkerName = worker.Name
                        };

                        if (TryFindSafePathToJob(worker, sleepJob, out List<Vector2Int> path))
                        {
                            int stationDistance = path.Count - (IsPersonalStationAssignedToWorker(bedCell, worker) ? 1000 : 0);
                            if (stationDistance >= bestDistance)
                            {
                                continue;
                            }

                            bestDistance = stationDistance;
                            bestPath = path;
                            bestJob = sleepJob;
                        }
                    }
                }

                if (bestJob != null)
                {
                    jobs.Add(bestJob);
                }
            }

            if (bestJob == null && TryFindFloorSleepCell(worker, out Vector2Int floorSleepCell, out List<Vector2Int> floorSleepPath))
            {
                bestJob = new Job(JobType.Sleep, floorSleepCell, SleepWorkRequired(worker) * FloorSleepWorkRequiredMultiplier)
                {
                    AutoGenerated = true,
                    Priority = Mathf.Max(1, SleepPriority(worker) - 1),
                    TargetWorkerName = worker.Name
                };
                bestPath = floorSleepPath;
                jobs.Add(bestJob);
            }

            if (bestJob == null)
            {
                return false;
            }

            bestJob.Priority = IsFloorSleepJob(bestJob) ? Mathf.Max(1, SleepPriority(worker) - 1) : SleepPriority(worker);
            return AssignJob(worker, bestJob, bestPath);
        }

        private bool TryFindFloorSleepCell(Worker worker, out Vector2Int floorSleepCell, out List<Vector2Int> floorSleepPath)
        {
            floorSleepCell = Vector2Int.zero;
            floorSleepPath = null;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            int bestDistance = int.MaxValue;
            for (int distance = 0; distance <= 8; distance++)
            {
                for (int dy = -distance; dy <= distance; dy++)
                {
                    int dxLimit = distance - Mathf.Abs(dy);
                    for (int dx = -dxLimit; dx <= dxLimit; dx++)
                    {
                        if (Mathf.Abs(dx) + Mathf.Abs(dy) != distance)
                        {
                            continue;
                        }

                        Vector2Int candidate = worker.Cell + new Vector2Int(dx, dy);
                        Worker occupant = WorkerAt(candidate);
                        if (!IsFloorSleepCell(candidate) ||
                            IsFloorSleepCellReserved(candidate) ||
                            (occupant != null && occupant != worker))
                        {
                            continue;
                        }

                        Job sleepJob = new Job(JobType.Sleep, candidate, SleepWorkRequired(worker) * FloorSleepWorkRequiredMultiplier)
                        {
                            AutoGenerated = true,
                            TargetWorkerName = worker.Name
                        };

                        if (TryFindSafePathToJob(worker, sleepJob, out List<Vector2Int> path) && path.Count < bestDistance)
                        {
                            bestDistance = path.Count;
                            floorSleepPath = path;
                            floorSleepCell = candidate;
                        }
                    }
                }
            }

            return floorSleepPath != null;
        }

        private void MoveOrWork(Worker worker, float deltaTime)
        {
            if (worker.PathIndex < worker.Path.Count)
            {
                Vector2Int targetCell = worker.Path[worker.PathIndex];
                if (!CanWorkerTraversePathStep(worker, worker.Cell, targetCell))
                {
                    if (IsSuitCheckpointCell(worker.Cell) && NeedsSuitProtection(targetCell))
                    {
                        DenySuitCheckpointEntry(worker, worker.Cell);
                    }
                    else if (IsOxygenMaskCheckpointCell(worker.Cell) && NeedsOxygenMaskProtection(targetCell))
                    {
                        DenyOxygenMaskCheckpointEntry(worker, worker.Cell);
                    }
                    else if (IsLeadSuitCheckpointCell(worker.Cell) && NeedsLeadSuitProtection(targetCell))
                    {
                        DenyLeadSuitCheckpointEntry(worker, worker.Cell);
                    }
                    else
                    {
                        ClearAssignment(worker);
                    }

                    return;
                }

                Vector3 target = CellCenter(targetCell);
                worker.Transform.position = Vector3.MoveTowards(worker.Transform.position, target, WorkerMoveSpeedForStep(worker, targetCell) * deltaTime);
                worker.Renderer.flipX = target.x < worker.Transform.position.x;
                worker.Activity = "Moving";
                ApplyCommutePressure(worker, deltaTime);

                if ((worker.Transform.position - target).sqrMagnitude < 0.0025f)
                {
                    Vector2Int previousCell = worker.Cell;
                    worker.Cell = targetCell;
                    worker.PathIndex++;
                    if (!UpdateSuitCheckpointCrossing(worker, previousCell, worker.Cell))
                    {
                        worker.Cell = previousCell;
                        worker.Transform.position = CellCenter(previousCell);
                        DenySuitCheckpointEntry(worker, previousCell);
                    }
                    else if (!UpdateOxygenMaskCheckpointCrossing(worker, previousCell, worker.Cell))
                    {
                        worker.Cell = previousCell;
                        worker.Transform.position = CellCenter(previousCell);
                        DenyOxygenMaskCheckpointEntry(worker, previousCell);
                    }
                    else if (!UpdateLeadSuitCheckpointCrossing(worker, previousCell, worker.Cell))
                    {
                        worker.Cell = previousCell;
                        worker.Transform.position = CellCenter(previousCell);
                        DenyLeadSuitCheckpointEntry(worker, previousCell);
                    }
                    else
                    {
                        RecordFirePoleTransitStep(previousCell, worker.Cell);
                    }
                }

                return;
            }

            Job job = worker.AssignedJob;
            worker.Activity = JobLabel(job);
            if (job.Type == JobType.Sleep)
            {
                bool floorSleep = IsFloorSleepJob(job);
                worker.Activity = floorSleep ? "Floor Sleeping" : "Sleeping";
                RoomKind sleepRoom = RoomKindAt(job.Cell.x, job.Cell.y);
                float restRate = sleepRoom == RoomKind.Bedroom ? 8.4f : sleepRoom == RoomKind.Barracks ? 7.6f : 6.5f;
                float stressRelief = sleepRoom == RoomKind.Bedroom ? 2.8f : sleepRoom == RoomKind.Barracks ? 2.2f : 1.4f;
                float moraleGain = sleepRoom == RoomKind.Bedroom ? 0.22f : sleepRoom == RoomKind.Barracks ? 0.16f : 0.08f;
                if (IsComfyBedCell(job.Cell))
                {
                    restRate *= ComfyBedRestMultiplier;
                    stressRelief += ComfyBedStressReliefBonus;
                    moraleGain += ComfyBedMoraleGainBonus;
                }

                if (floorSleep)
                {
                    restRate *= FloorSleepRestMultiplier;
                    stressRelief *= FloorSleepStressReliefMultiplier;
                    moraleGain = 0f;
                    worker.Morale = Mathf.Max(0f, worker.Morale - FloorSleepMoraleDropRate * deltaTime);
                }

                float sleepDisruption = SleepDisruptionFactor(worker);
                if (sleepDisruption > 0f)
                {
                    restRate *= Mathf.Lerp(1f, LoudSleeperRestMultiplier, sleepDisruption);
                    stressRelief *= Mathf.Lerp(1f, LoudSleeperStressReliefMultiplier, sleepDisruption);
                    worker.Stress = Mathf.Min(100f, worker.Stress + LoudSleeperStressRate * sleepDisruption * deltaTime);
                    worker.Morale = Mathf.Max(0f, worker.Morale - LoudSleeperMoraleDropRate * sleepDisruption * deltaTime);
                }

                float brightSleep = Mathf.Clamp01(worker.BrightSleepSeconds / BrightSleepDurationSeconds);
                if (brightSleep > 0f)
                {
                    restRate *= Mathf.Lerp(1f, BrightSleepRestMultiplier, brightSleep);
                    stressRelief *= Mathf.Lerp(1f, BrightSleepStressReliefMultiplier, brightSleep);
                    moraleGain *= Mathf.Lerp(1f, 0.55f, brightSleep);
                }

                worker.Fatigue = Mathf.Max(0f, worker.Fatigue - restRate * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - stressRelief * deltaTime);
                worker.Morale = Mathf.Min(10f, worker.Morale + moraleGain * deltaTime);
                if (worker.Calories > 400f)
                {
                    worker.Health = Mathf.Min(100f, worker.Health + 0.7f * deltaTime);
                }

                job.Progress += deltaTime;
                if (job.Progress >= job.WorkRequired || (!IsRestTime(worker) && worker.Fatigue < 28f) || worker.Fatigue < 8f)
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.Treat)
            {
                worker.Activity = "Receiving Treatment";
                float clinicFactor = RoomKindAt(job.Cell.x, job.Cell.y) == RoomKind.Clinic ? 1.25f : 1f;
                float careFactor = (water >= 1f ? 1f : 0.65f) *
                    clinicFactor *
                    WorkerRoleJobSpeedMultiplier(worker, job.Type);
                worker.GermExposure = Mathf.Max(0f, worker.GermExposure - 4.5f * careFactor * deltaTime);
                worker.Sickness = Mathf.Max(0f, worker.Sickness - 2.8f * careFactor * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - 1.8f * deltaTime);
                if (worker.Calories > 350f)
                {
                    worker.Health = Mathf.Min(100f, worker.Health + 1.4f * careFactor * deltaTime);
                }

                job.Progress += deltaTime * careFactor;
                if (job.Progress >= job.WorkRequired || !NeedsTreatment(worker))
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.MedicalRest)
            {
                bool floorMedicalRest = IsFloorMedicalRestJob(job);
                worker.Activity = "Recovering";
                float clinicFactor = !floorMedicalRest && RoomKindAt(job.Cell.x, job.Cell.y) == RoomKind.Clinic ? ClinicPassiveRecoveryMultiplier : 1f;
                float calorieFactor = worker.Calories > 350f ? 1f : 0.62f;
                float recoveryFactor = clinicFactor * calorieFactor;
                float medicalRecoveryFactor = recoveryFactor * (floorMedicalRest ? FloorMedicalRestRecoveryMultiplier : 1f);
                float healthRecoveryFactor = recoveryFactor * (floorMedicalRest ? FloorMedicalRestHealthRecoveryMultiplier : 1f);
                float stressRecoveryFactor = recoveryFactor * (floorMedicalRest ? FloorMedicalRestStressReliefMultiplier : 1f);
                float fatigueRecoveryFactor = recoveryFactor * (floorMedicalRest ? FloorMedicalRestFatigueRecoveryMultiplier : 1f);
                worker.GermExposure = Mathf.Max(0f, worker.GermExposure - MedicalRestGermRecoveryRate * medicalRecoveryFactor * deltaTime);
                worker.Sickness = Mathf.Max(0f, worker.Sickness - MedicalRestSicknessRecoveryRate * medicalRecoveryFactor * deltaTime);
                worker.HeatExposure = Mathf.Max(0f, worker.HeatExposure - MedicalRestThermalRecoveryRate * medicalRecoveryFactor * deltaTime);
                worker.ChillExposure = Mathf.Max(0f, worker.ChillExposure - MedicalRestThermalRecoveryRate * medicalRecoveryFactor * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - MedicalRestStressReliefRate * stressRecoveryFactor * deltaTime);
                worker.Fatigue = Mathf.Max(0f, worker.Fatigue - MedicalRestFatigueRecoveryRate * fatigueRecoveryFactor * deltaTime);
                worker.Calories = Mathf.Max(0f, worker.Calories - 0.035f * deltaTime);
                if (worker.Calories > 350f)
                {
                    worker.Health = Mathf.Min(100f, worker.Health + MedicalRestHealthRecoveryRate * healthRecoveryFactor * deltaTime);
                }

                if (floorMedicalRest)
                {
                    worker.Morale = Mathf.Max(0f, worker.Morale - FloorMedicalRestMoraleDropRate * deltaTime);
                }

                ClearRecoveredDisease(worker);
                job.Progress = Mathf.Min(job.WorkRequired, job.Progress + deltaTime * medicalRecoveryFactor);
                if (!NeedsMedicalRest(worker) || NeedsTreatment(worker))
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.CatchBreath)
            {
                worker.Activity = "Catching Breath";
                float breathableAir = BreathableAirAt(worker.Cell.x, worker.Cell.y);
                float recoveryFactor = breathableAir >= BreathRecoveryAirThreshold ? 1.25f : 0.35f;
                worker.Breath = Mathf.Min(BreathCapacity, worker.Breath + BreathRecoveryRate * recoveryFactor * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - 1.2f * recoveryFactor * deltaTime);
                ConsumeBreathableAir(worker.Cell, 0.010f * recoveryFactor * deltaTime);
                job.Progress += deltaTime * recoveryFactor;
                if (worker.Breath >= CatchBreathReleaseThreshold ||
                    (job.Progress >= job.WorkRequired && worker.Breath >= CatchBreathThreshold))
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.SeekSafety)
            {
                worker.Activity = "Seeking Safety";
                float recoveryFactor = IsSafetyRecoveryCell(worker.Cell) ? 1.35f : 0.45f;
                worker.HeatExposure = Mathf.Max(0f, worker.HeatExposure - ThermalExposureRecoveryRate * recoveryFactor * deltaTime);
                worker.ChillExposure = Mathf.Max(0f, worker.ChillExposure - ThermalExposureRecoveryRate * recoveryFactor * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - 1.6f * recoveryFactor * deltaTime);
                if (BreathableAirAt(worker.Cell.x, worker.Cell.y) >= BreathRecoveryAirThreshold)
                {
                    worker.Breath = Mathf.Min(BreathCapacity, worker.Breath + BreathRecoveryRate * 0.75f * recoveryFactor * deltaTime);
                }

                job.Progress += deltaTime * recoveryFactor;
                if ((job.Progress >= job.WorkRequired && HasRecoveredFromEnvironmentDanger(worker)) ||
                    (!NeedsSeekSafety(worker) && IsSafetyRecoveryCell(worker.Cell)))
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.UseToilet)
            {
                worker.Activity = IsInside(job.Cell.x, job.Cell.y) && cells[job.Cell.x, job.Cell.y] == CellKind.Lavatory ? "Using Lavatory" : "Using Outhouse";
                worker.Bladder = Mathf.Max(0f, worker.Bladder - 38f * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - 0.8f * deltaTime);
                job.Progress += deltaTime;
                if (job.Progress >= job.WorkRequired || worker.Bladder <= 5f)
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.WashHands)
            {
                worker.Activity = "Washing Hands";
                float washFactor = HandWashWorkFactor(job.Cell);
                worker.GermExposure = Mathf.Max(0f, worker.GermExposure - 6.5f * washFactor * deltaTime);
                job.Progress += deltaTime * washFactor;
                if (job.Progress >= job.WorkRequired || worker.GermExposure <= 2f)
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.Shower)
            {
                worker.Activity = "Showering";
                float showerFactor = water >= ShowerWaterUse ? 1f : 0.25f;
                worker.GermExposure = Mathf.Max(0f, worker.GermExposure - 8.5f * showerFactor * deltaTime);
                worker.Sickness = Mathf.Max(0f, worker.Sickness - 0.6f * showerFactor * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - 2.0f * showerFactor * deltaTime);
                job.Progress += deltaTime * showerFactor;
                if (job.Progress >= job.WorkRequired || (worker.GermExposure <= 8f && worker.Stress <= 30f))
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.Eat)
            {
                bool floorMeal = IsFloorEatJob(job);
                worker.Activity = "Eating";
                RoomKind diningRoom = RoomKindAt(job.Cell.x, job.Cell.y);
                float mealRoomFactor = floorMeal ? 0.65f : diningRoom == RoomKind.GreatHall ? 1.8f : diningRoom == RoomKind.MessHall ? 1.45f : 1f;
                worker.Stress = Mathf.Max(0f, worker.Stress - 1.4f * mealRoomFactor * deltaTime);
                job.Progress += deltaTime;
                if (job.Progress >= job.WorkRequired || worker.Calories >= 2100f)
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.Relax)
            {
                bool takeBreak = IsTakeBreakJob(job);
                worker.Activity = "Relaxing";
                CellKind relaxationKind = cells[job.Cell.x, job.Cell.y];
                RoomKind relaxationRoom = RoomKindAt(job.Cell.x, job.Cell.y);
                float recreationFactor = relaxationRoom == RoomKind.RecreationRoom ? 1.25f : relaxationRoom == RoomKind.GreatHall ? 1.12f : 1f;
                float stationFactor = takeBreak ? TakeBreakStressReliefMultiplier : relaxationKind == CellKind.ArcadeCabinet ? 1.38f : relaxationKind == CellKind.WaterCooler ? 0.68f : 1f;
                float moraleFactor = takeBreak ? TakeBreakMoraleMultiplier : Mathf.Lerp(0.65f, 1f, stationFactor);
                float waterFactor = !takeBreak && relaxationKind == CellKind.WaterCooler && water < WaterCoolerWaterUse ? 0.35f : 1f;
                float arcadeFactor = !takeBreak && relaxationKind == CellKind.ArcadeCabinet && (!CanPoweredMachineRun(job.Cell) || plastic < ArcadeCabinetPlasticUse) ? 0.28f : 1f;
                worker.Stress = Mathf.Max(0f, worker.Stress - 7.5f * recreationFactor * stationFactor * waterFactor * arcadeFactor * deltaTime);
                worker.Morale = Mathf.Min(10f, worker.Morale + 0.42f * recreationFactor * moraleFactor * waterFactor * arcadeFactor * deltaTime);
                worker.Fatigue = Mathf.Min(100f, worker.Fatigue + 0.08f * deltaTime);
                worker.Calories = Mathf.Max(0f, worker.Calories - 0.04f * deltaTime);
                job.Progress += deltaTime * waterFactor * arcadeFactor;
                if (job.Progress >= job.WorkRequired || worker.Stress <= (takeBreak ? TakeBreakStressCapAt(job.Cell) : 32f))
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            if (job.Type == JobType.MoveTo)
            {
                worker.Activity = "Holding Position";
                job.Progress += deltaTime;
                if (job.Progress >= job.WorkRequired)
                {
                    CompleteJob(job, worker);
                }

                return;
            }

            bool hasBreathingGearOxygen = HasWorkerBreathingGearOxygen(worker);
            float oxygenFactor = IsInside(worker.Cell.x, worker.Cell.y) && !hasBreathingGearOxygen && oxygen[worker.Cell.x, worker.Cell.y] < 0.12f ? 0.45f : 1f;
            job.Progress += deltaTime *
                worker.WorkSpeed *
                WorkerTraitJobSpeedMultiplier(worker, job.Type) *
                WorkerInterestJobSpeedMultiplier(worker, job.Type) *
                WorkerRoleJobSpeedMultiplier(worker, job.Type) *
                oxygenFactor;

            if (job.Type == JobType.OperateGenerator)
            {
                worker.Calories -= 0.65f * deltaTime;
            }
            else if (job.Type == JobType.Research)
            {
                worker.Calories -= 0.18f * deltaTime;
            }
            else if (job.Type == JobType.ProduceMedicine)
            {
                worker.Calories -= 0.16f * deltaTime;
            }
            else if (job.Type == JobType.PumpWater)
            {
                worker.Calories -= 0.28f * deltaTime;
            }
            else if (job.Type == JobType.EmptyBottle)
            {
                worker.Calories -= 0.16f * deltaTime;
            }
            else if (job.Type == JobType.Disinfect)
            {
                worker.Calories -= 0.12f * deltaTime;
            }
            else if (job.Type == JobType.GroomHatch)
            {
                worker.Calories -= 0.12f * deltaTime;
                worker.Stress = Mathf.Max(0f, worker.Stress - 0.35f * deltaTime);
            }
            else if (job.Type == JobType.WrangleCritter)
            {
                worker.Calories -= 0.16f * deltaTime;
                worker.Stress = Mathf.Min(100f, worker.Stress + 0.08f * deltaTime);
            }
            else if (job.Type == JobType.ButcherCritter)
            {
                worker.Calories -= 0.14f * deltaTime;
            }

            if (job.Progress >= job.WorkRequired)
            {
                CompleteJob(job, worker);
            }
        }

        private float WorkerMoveSpeedForStep(Worker worker, Vector2Int targetCell)
        {
            if (worker == null)
            {
                return 0f;
            }

            float speed = worker.MoveSpeed *
                WorkerTraitMoveSpeedMultiplier(worker) *
                WorkerOverjoyedMoveSpeedMultiplier(worker) *
                WorkerSuitFatigueMoveSpeedMultiplier(worker) *
                WorkerSoreBackMoveSpeedMultiplier(worker);
            if (worker.LeadSuitEquipped)
            {
                speed *= 0.88f;
            }

            if (targetCell.y < worker.Cell.y && (IsFirePoleCell(worker.Cell) || IsFirePoleCell(targetCell)))
            {
                speed *= 2.25f;
            }

            return redAlertActive ? speed * RedAlertMoveSpeedMultiplier : speed;
        }

        private void RecordFirePoleTransitStep(Vector2Int from, Vector2Int to)
        {
            if (to.y >= from.y || (!IsFirePoleCell(from) && !IsFirePoleCell(to)))
            {
                return;
            }

            firePoleDescentTiles += Mathf.Max(1, from.y - to.y);
            firePoleDescentEvents++;
        }

        private void CompleteJob(Job job, Worker worker)
        {
            switch (job.Type)
            {
                case JobType.Dig:
                    CompleteDig(job);
                    break;
                case JobType.Build:
                    CompleteBuild(job);
                    break;
                case JobType.BuildWire:
                    CompletePowerWire(job);
                    break;
                case JobType.BuildAutomationWire:
                    CompleteAutomationWire(job);
                    break;
                case JobType.BuildPipe:
                    CompleteLiquidPipe(job);
                    break;
                case JobType.BuildGasPipe:
                    CompleteGasPipe(job);
                    break;
                case JobType.BuildShippingRail:
                    CompleteShippingRail(job);
                    break;
                case JobType.Deconstruct:
                    CompleteDeconstruct(job, worker);
                    break;
                case JobType.Mop:
                    CompleteMop(job, worker);
                    break;
                case JobType.Disinfect:
                    CompleteDisinfect(job, worker);
                    break;
                case JobType.Repair:
                    CompleteRepair(job, worker);
                    break;
                case JobType.Rescue:
                    CompleteRescue(job, worker);
                    break;
                case JobType.Sweep:
                    CompleteSweep(job, worker);
                    break;
                case JobType.OperateGenerator:
                    AddGeneratedPower(38f * WorkerJobOutputMultiplier(worker, job.Type));
                    AddHeat(job.Cell, 4.5f, 1);
                    WearEquipment(job.Cell, 0.018f);
                    Log(worker.Name + " generated power.");
                    break;
                case JobType.TuneGenerator:
                    CompleteTuneGenerator(job, worker);
                    break;
                case JobType.Sculpt:
                    CompleteSculpt(job, worker);
                    break;
                case JobType.Harvest:
                    CellKind cropKind = cells[job.Cell.x, job.Cell.y];
                    float harvestYield = CropHarvestYield(cropKind) * WorkerJobOutputMultiplier(worker, job.Type);
                    float harvestQuality = Mathf.Clamp01(CropFoodQuality(cropKind) + WorkerRoleFoodQualityBonus(worker, job.Type));
                    if (cropKind == CellKind.PepperPlant)
                    {
                        float storedPeppernut = StoreDryResource(ref peppernut, harvestYield);
                        peppernutHarvests++;
                        peppernutProduced += storedPeppernut;
                    }
                    else if (cropKind == CellKind.ThimbleReed)
                    {
                        float storedReedFiber = StoreDryResource(ref reedFiber, harvestYield);
                        thimbleReedHarvests++;
                        thimbleReedFiberHarvested += storedReedFiber;
                    }
                    else if (cropKind == CellKind.SleetWheat)
                    {
                        float storedWheatGrain = StoreDryResource(ref wheatGrain, harvestYield);
                        sleetWheatHarvests++;
                        wheatGrainHarvested += storedWheatGrain;
                    }
                    else if (cropKind == CellKind.ArborTree)
                    {
                        float storedLumber = StoreDryResource(ref lumber, harvestYield);
                        arborTreeHarvests++;
                        lumberHarvested += storedLumber;
                    }
                    else
                    {
                        AddFreshFood(harvestYield, CropHarvestFreshness(cropKind), harvestQuality, true, FoodHandlingContaminationAt(job.Cell, worker) * 0.35f);
                    }

                    if (cropKind == CellKind.HydroponicFarm)
                    {
                        bristleBerryHarvests++;
                        bristleBerryFoodProduced += harvestYield;
                    }
                    else if (cropKind == CellKind.FungalFarm)
                    {
                        duskCapHarvests++;
                        duskCapFoodProduced += harvestYield;
                    }
                    else if (cropKind == CellKind.GrubfruitPlant)
                    {
                        grubfruitHarvests++;
                        grubfruitFoodProduced += harvestYield;
                    }

                    plantGrowth[job.Cell.x, job.Cell.y] = 0f;
                    cropTendedSeconds[job.Cell.x, job.Cell.y] = 0f;
                    cropStress[job.Cell.x, job.Cell.y] = 0f;
                    Log(worker.Name + " harvested " + (cropKind == CellKind.HydroponicFarm ? "bristle berries." : cropKind == CellKind.FungalFarm ? "dusk caps." : cropKind == CellKind.PepperPlant ? "peppernuts." : cropKind == CellKind.GrubfruitPlant ? "grubfruit." : cropKind == CellKind.ThimbleReed ? "reed fiber." : cropKind == CellKind.SleetWheat ? "wheat grain." : cropKind == CellKind.ArborTree ? "lumber." : "mealwood."));
                    break;
                case JobType.PumpWater:
                    CompletePumpWater(job, worker);
                    break;
                case JobType.EmptyBottle:
                    CompleteEmptyBottle(job, worker);
                    break;
                case JobType.TendCrop:
                    CompleteTendCrop(job, worker);
                    break;
                case JobType.Research:
                    ResearchFocus researchFocusBefore = selectedResearchFocus;
                    bool wasUnlocked = IsResearchUnlocked(researchFocusBefore);
                    float researchGain = 6f * WorkerJobOutputMultiplier(worker, job.Type);
                    researchPoints += researchGain;
                    currentCycleReport.ResearchPoints += researchGain;
                    ConsumeCyclePower(4f);
                    AddHeat(job.Cell, 0.7f, 1);
                    WearEquipment(job.Cell, 0.014f);
                    ApplyResearchUnlocks(false);
                    if (!wasUnlocked && IsResearchUnlocked(researchFocusBefore))
                    {
                        Log("Research unlocked: " + ResearchFocusName(researchFocusBefore) + ".");
                    }
                    else
                    {
                        Log(worker.Name + " completed research.");
                    }
                    break;
                case JobType.Cook:
                    CompleteCook(job, worker);
                    break;
                case JobType.RefineMetal:
                    CompleteRefineMetal(job, worker);
                    break;
                case JobType.Sleep:
                    if (IsFloorSleepJob(job))
                    {
                        worker.Fatigue = Mathf.Min(worker.Fatigue, 32f);
                        worker.Stress = Mathf.Max(0f, worker.Stress - 3f);
                        AddSoreBack(worker, SoreBackDurationSeconds);
                        Log(worker.Name + " woke sore after sleeping on the floor.");
                    }
                    else if (IsComfyBedCell(job.Cell))
                    {
                        worker.Fatigue = Mathf.Min(worker.Fatigue, 12f);
                        worker.Stress = Mathf.Max(0f, worker.Stress - 8f - ComfyBedWakeStressRelief);
                        worker.Morale = Mathf.Min(10f, worker.Morale + ComfyBedWakeMoraleGain);
                        Log(worker.Name + " woke rested from a Comfy Bed.");
                    }
                    else
                    {
                        worker.Fatigue = Mathf.Min(worker.Fatigue, 18f);
                        worker.Stress = Mathf.Max(0f, worker.Stress - 8f);
                        Log(worker.Name + " finished resting.");
                    }
                    break;
                case JobType.Treat:
                    CompleteTreatment(job, worker);
                    break;
                case JobType.MedicalRest:
                    CompleteMedicalRest(job, worker);
                    break;
                case JobType.CatchBreath:
                    CompleteCatchBreath(job, worker);
                    break;
                case JobType.SeekSafety:
                    CompleteSeekSafety(job, worker);
                    break;
                case JobType.MoveTo:
                    Log(worker.Name + " arrived at move target.");
                    break;
                case JobType.ProduceMedicine:
                    CompleteProduceMedicine(job, worker);
                    break;
                case JobType.UseToilet:
                    CompleteToiletUse(job, worker);
                    break;
                case JobType.WashHands:
                    CompleteWashHands(job, worker);
                    break;
                case JobType.Shower:
                    CompleteShower(job, worker);
                    break;
                case JobType.Eat:
                    CompleteEat(job, worker);
                    break;
                case JobType.Relax:
                    CompleteRelaxation(job, worker);
                    break;
                case JobType.ScrubSkill:
                    CompleteSkillScrub(job, worker);
                    break;
                case JobType.Compost:
                    CompleteCompost(job, worker);
                    break;
                case JobType.GroomHatch:
                    CompleteGroomHatch(job, worker);
                    break;
                case JobType.WrangleCritter:
                    CompleteWrangleCritter(job, worker);
                    break;
                case JobType.ButcherCritter:
                    CompleteButcherCritter(job, worker);
                    break;
            }

            if (job.Type != JobType.MoveTo && job.Type != JobType.MedicalRest)
            {
                GrantWorkerExperience(worker, job);
            }

            jobs.Remove(job);
            ClearAssignment(worker);
            overlayDirty = true;
        }

        private void CompleteTuneGenerator(Job job, Worker worker)
        {
            if (!CanTuneGeneratorAt(job.Cell, false))
            {
                Log("Generator tune-up target is unavailable.");
                return;
            }

            if (refinedMetal < PowerControlStationRefinedMetalCost)
            {
                Log("Not enough refined metal for generator tune-up.");
                return;
            }

            refinedMetal = Mathf.Max(0f, refinedMetal - PowerControlStationRefinedMetalCost);
            generatorTuneUpSeconds[job.Cell.x, job.Cell.y] = GeneratorTuneUpDuration * WorkerJobOutputMultiplier(worker, job.Type) * PowerPlantTuneUpDurationMultiplierAt(job.Cell);
            generatorTuneUpsCompleted++;
            WearEquipment(job.Cell, 0.004f);
            AddHeat(job.Cell, 0.35f, 1);
            if (TryFindPowerControlStationForGenerator(job.Cell, out Vector2Int station))
            {
                WearEquipment(station, 0.003f);
                AddHeat(station, 0.25f, 1);
            }

            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            Log(worker.Name + " tuned " + CellLabel(cells[job.Cell.x, job.Cell.y]) + " for +" + Mathf.RoundToInt((GeneratorTuneUpPowerMultiplier - 1f) * 100f) + "% output" + (HasPowerPlantBonus(job.Cell) ? " with Power Plant support." : "."));
        }

        private void CompleteSculpt(Job job, Worker worker)
        {
            if (!NeedsSculpting(job.Cell))
            {
                Log("Sculpting target is unavailable.");
                return;
            }

            sculptingBlockFinished[job.Cell.x, job.Cell.y] = true;
            sculpturesCompleted++;
            if (worker != null)
            {
                worker.Morale = Mathf.Min(10f, worker.Morale + 0.25f);
                worker.Stress = Mathf.Max(0f, worker.Stress - 1.5f);
                Log(worker.Name + " completed a Sculpting Block.");
            }
            else
            {
                Log("Sculpting Block completed.");
            }

            terrainDirty = true;
            overlayDirty = true;
            InvalidateRooms();
        }

        private void CompleteCook(Job job, Worker worker)
        {
            if (cells[job.Cell.x, job.Cell.y] == CellKind.EggCracker)
            {
                if (!CrackHatchEggAt(job.Cell, worker))
                {
                    Log(worker.Name + " found no stored hatch egg to crack.");
                }

                return;
            }

            if (cells[job.Cell.x, job.Cell.y] == CellKind.ElectricGrill)
            {
                CompleteElectricGrill(job, worker);
                return;
            }

            ConsumeCycleWater(4f, out float cookingWaterGerms);
            RecordGermyWaterUse(cookingWaterGerms);
            dirt = Mathf.Max(0f, dirt - 1f);
            ConsumeCyclePower(2f);
            float contamination = FoodHandlingContaminationAt(job.Cell, worker) * 0.70f + cookingWaterGerms * CleanWaterGermFoodContaminationScale;
            AddFreshFood(
                900f * WorkerJobOutputMultiplier(worker, job.Type),
                0.96f,
                Mathf.Clamp01(MushBarFoodQuality + WorkerRoleFoodQualityBonus(worker, job.Type)),
                true,
                contamination);
            AddHeat(job.Cell, 1.1f, 1);
            WearEquipment(job.Cell, 0.014f);
            Log(worker.Name + " cooked mush bars.");
        }

        private void CompleteElectricGrill(Job job, Worker worker)
        {
            if (!CanCookAt(job.Cell))
            {
                Log("Electric Grill needs power and prepared food or wheat grain.");
                return;
            }

            if (ShouldPrepareFrostBuns())
            {
                float consumed = ConsumeDryResource(LooseResourceKind.WheatGrain, FrostBunWheatGrainCost);
                if (consumed < FrostBunWheatGrainCost - 0.001f)
                {
                    StoreLooseResource(LooseResourceKind.WheatGrain, consumed);
                    Log("Electric Grill needs wheat grain.");
                    return;
                }

                ConsumeCyclePower(ElectricGrillPowerCost);
                float frostBunOutputFood = FrostBunOutputFood * WorkerJobOutputMultiplier(worker, job.Type);
                float frostBunOutputQuality = Mathf.Clamp01(FrostBunFoodQuality + WorkerRoleFoodQualityBonus(worker, job.Type));
                AddFreshFood(frostBunOutputFood, FrostBunFreshness, frostBunOutputQuality, false, FoodHandlingContaminationAt(job.Cell, worker) * 0.12f);
                frostBunsBaked++;
                frostBunFoodPrepared += frostBunOutputFood;
                grilledMealsCooked++;
                grilledFoodPrepared += frostBunOutputFood;
                AddHeat(job.Cell, 0.85f, 1);
                WearEquipment(job.Cell, 0.012f);
                terrainDirty = true;
                overlayDirty = true;
                Log(worker.Name + " baked frost buns from wheat grain.");
                return;
            }

            float inputFoodGerms = foodGerms;
            food = Mathf.Max(0f, food - ElectricGrillInputFood);
            if (food <= 0.001f)
            {
                food = 0f;
                foodFreshness = 1f;
                foodQuality = DefaultFoodQuality;
                foodGerms = 0f;
            }

            ConsumeCyclePower(ElectricGrillPowerCost);
            float grilledContamination = inputFoodGerms * FoodGermElectricGrillMultiplier + FoodHandlingContaminationAt(job.Cell, worker) * 0.12f;
            bool seasoned = peppernut >= PeppernutSeasoningCost;
            if (seasoned)
            {
                peppernut = Mathf.Max(0f, peppernut - PeppernutSeasoningCost);
                peppernutUsed += PeppernutSeasoningCost;
            }

            float outputFood = ElectricGrillOutputFood * WorkerJobOutputMultiplier(worker, job.Type);
            float outputQuality = Mathf.Clamp01((seasoned ? PeppernutGrillFoodQuality : ElectricGrillFoodQuality) + WorkerRoleFoodQualityBonus(worker, job.Type));
            AddFreshFood(outputFood, ElectricGrillFreshness, outputQuality, false, grilledContamination);
            grilledMealsCooked++;
            grilledFoodPrepared += outputFood;
            if (seasoned)
            {
                spicedMealsPrepared++;
                spicedFoodPrepared += outputFood;
            }

            AddHeat(job.Cell, 0.85f, 1);
            WearEquipment(job.Cell, 0.012f);
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + (seasoned ? " seasoned grilled meals with peppernuts." : " grilled quality meals."));
        }

        private bool CrackHatchEggAt(Vector2Int cell, Worker worker)
        {
            if (!IsInside(cell.x, cell.y) ||
                cells[cell.x, cell.y] != CellKind.EggCracker ||
                !CanUseEquipment(cell) ||
                hatchEggs < 1f)
            {
                return false;
            }

            float consumed = ConsumeDryResource(LooseResourceKind.HatchEgg, 1f);
            if (consumed < 0.999f)
            {
                StoreLooseResource(LooseResourceKind.HatchEgg, consumed);
                return false;
            }

            float omeletteFood = HatchEggFoodYield * WorkerJobOutputMultiplier(worker, JobType.Cook);
            float omeletteQuality = Mathf.Clamp01(HatchEggFoodQuality + WorkerRoleFoodQualityBonus(worker, JobType.Cook));
            AddFreshFood(omeletteFood, HatchEggFoodFreshness, omeletteQuality, true, FoodHandlingContaminationAt(cell, worker) * 0.45f);
            hatchEggsCooked++;
            hatchEggFoodCooked += omeletteFood;
            AddHeat(cell, 0.45f, 1);
            WearEquipment(cell, 0.009f);
            terrainDirty = true;
            overlayDirty = true;
            Log((worker != null ? worker.Name : "Duplicant") + " cracked a hatch egg into omelette.");
            return true;
        }

        private void CompleteProduceMedicine(Job job, Worker worker)
        {
            if (!CanProduceMedicineAt(job.Cell))
            {
                Log("Apothecary needs power, water, and algae.");
                return;
            }

            ConsumeCycleWater(ApothecaryWaterUse);
            algae = Mathf.Max(0f, algae - ApothecaryAlgaeUse);
            ConsumeCyclePower(ApothecaryPowerCost);
            medicine += ApothecaryMedicineYield * WorkerJobOutputMultiplier(worker, job.Type);
            medicineProduced++;
            AddHeat(job.Cell, 0.55f, 1);
            WearEquipment(job.Cell, 0.010f);
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + " compounded a medicine pack at the Apothecary.");
        }

        private void CompletePowerWire(Job job)
        {
            powerWire[job.Cell.x, job.Cell.y] = true;
            powerWireKind[job.Cell.x, job.Cell.y] = job.PowerWireKind;
            poweredWire[job.Cell.x, job.Cell.y] = false;
            wireLoad[job.Cell.x, job.Cell.y] = 0f;
            overloadedWire[job.Cell.x, job.Cell.y] = false;
            wireOverloadStress[job.Cell.x, job.Cell.y] = 0f;
            gasDirty = true;
            overlayDirty = true;
            Log("Built " + PowerWireKindName(job.PowerWireKind) + ".");
        }

        private void CompleteAutomationWire(Job job)
        {
            automationWire[job.Cell.x, job.Cell.y] = true;
            overlayDirty = true;
            Log("Built Automation Wire.");
        }

        private void CompleteLiquidPipe(Job job)
        {
            liquidPipe[job.Cell.x, job.Cell.y] = true;
            liquidPipeKind[job.Cell.x, job.Cell.y] = job.LiquidPipeKind;
            pipeWater[job.Cell.x, job.Cell.y] = Mathf.Clamp(pipeWater[job.Cell.x, job.Cell.y], 0f, LiquidPipeCapacity);
            pipeWaterGerms[job.Cell.x, job.Cell.y] = pipeWater[job.Cell.x, job.Cell.y] > 0.001f ? Mathf.Clamp01(pipeWaterGerms[job.Cell.x, job.Cell.y]) : 0f;
            pipePollutedWater[job.Cell.x, job.Cell.y] = Mathf.Clamp(pipePollutedWater[job.Cell.x, job.Cell.y], 0f, LiquidPipeCapacity - pipeWater[job.Cell.x, job.Cell.y]);
            pipePollutedWaterGerms[job.Cell.x, job.Cell.y] = pipePollutedWater[job.Cell.x, job.Cell.y] > 0.001f ? Mathf.Clamp01(pipePollutedWaterGerms[job.Cell.x, job.Cell.y]) : 0f;
            pipePetroleum[job.Cell.x, job.Cell.y] = Mathf.Clamp(pipePetroleum[job.Cell.x, job.Cell.y], 0f, LiquidPipeCapacity - pipeWater[job.Cell.x, job.Cell.y] - pipePollutedWater[job.Cell.x, job.Cell.y]);
            overlayDirty = true;
            Log("Built " + LiquidPipeKindName(job.LiquidPipeKind) + ".");
        }

        private void CompleteGasPipe(Job job)
        {
            gasPipe[job.Cell.x, job.Cell.y] = true;
            gasPipeKind[job.Cell.x, job.Cell.y] = job.GasPipeKind;
            gasPipeOxygen[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeOxygen[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipeCarbonDioxide[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeCarbonDioxide[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipePollutedOxygen[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipePollutedOxygen[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipeHydrogen[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeHydrogen[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipeSteam[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeSteam[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipeChlorine[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeChlorine[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipeNaturalGas[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeNaturalGas[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            gasPipeSourGas[job.Cell.x, job.Cell.y] = Mathf.Clamp(gasPipeSourGas[job.Cell.x, job.Cell.y], 0f, GasPipeCapacity);
            overlayDirty = true;
            Log("Built " + GasPipeKindName(job.GasPipeKind) + ".");
        }

        private void CompleteShippingRail(Job job)
        {
            shippingRail[job.Cell.x, job.Cell.y] = true;
            shippingRailKind[job.Cell.x, job.Cell.y] = shippingRailAmount[job.Cell.x, job.Cell.y] > 0.001f ? shippingRailKind[job.Cell.x, job.Cell.y] : LooseResourceKind.None;
            shippingRailAmount[job.Cell.x, job.Cell.y] = Mathf.Clamp(shippingRailAmount[job.Cell.x, job.Cell.y], 0f, ShippingRailCapacity);
            overlayDirty = true;
            Log("Built Shipping Rail.");
        }

        private void CompleteDeconstruct(Job job, Worker worker)
        {
            if (!IsDeconstructJobValid(job))
            {
                Log("Deconstruction target no longer exists.");
                return;
            }

            string label = DeconstructTargetLabel(job);
            if (job.BuildKind != CellKind.Empty)
            {
                RemoveBuiltCell(job.Cell, job.BuildKind);
            }
            else if (job.RemovePowerWire)
            {
                PowerWireKind removedKind = powerWireKind[job.Cell.x, job.Cell.y];
                powerWire[job.Cell.x, job.Cell.y] = false;
                powerWireKind[job.Cell.x, job.Cell.y] = PowerWireKind.Normal;
                poweredWire[job.Cell.x, job.Cell.y] = false;
                wireLoad[job.Cell.x, job.Cell.y] = 0f;
                overloadedWire[job.Cell.x, job.Cell.y] = false;
                wireOverloadStress[job.Cell.x, job.Cell.y] = 0f;
                RefundPowerWireMaterials(removedKind);
                gasDirty = true;
                overlayDirty = true;
            }
            else if (job.RemoveAutomationWire)
            {
                automationWire[job.Cell.x, job.Cell.y] = false;
                automationControlledWire[job.Cell.x, job.Cell.y] = false;
                automationSignalWire[job.Cell.x, job.Cell.y] = false;
                StoreDryResource(ref metal, 0.5f);
                overlayDirty = true;
            }
            else if (job.RemoveLiquidPipe)
            {
                float drained = pipeWater[job.Cell.x, job.Cell.y];
                float drainedGerms = pipeWaterGerms[job.Cell.x, job.Cell.y];
                float pollutedDrained = pipePollutedWater[job.Cell.x, job.Cell.y];
                float pollutedDrainedGerms = pipePollutedWaterGerms[job.Cell.x, job.Cell.y];
                float petroleumDrained = pipePetroleum[job.Cell.x, job.Cell.y];
                LiquidPipeKind removedKind = liquidPipeKind[job.Cell.x, job.Cell.y];
                liquidPipe[job.Cell.x, job.Cell.y] = false;
                liquidPipeKind[job.Cell.x, job.Cell.y] = LiquidPipeKind.Normal;
                liquidSensorMode[job.Cell.x, job.Cell.y] = LiquidSensorMode.AnyLiquid;
                pipeWater[job.Cell.x, job.Cell.y] = 0f;
                pipeWaterGerms[job.Cell.x, job.Cell.y] = 0f;
                pipePollutedWater[job.Cell.x, job.Cell.y] = 0f;
                pipePollutedWaterGerms[job.Cell.x, job.Cell.y] = 0f;
                pipePetroleum[job.Cell.x, job.Cell.y] = 0f;
                StoreCleanWaterInStorage(drained, drainedGerms);
                StorePollutedWaterInStorage(pollutedDrained, pollutedDrainedGerms);
                StorePetroleumInStorage(petroleumDrained);
                RefundLiquidPipeMaterials(removedKind);
                overlayDirty = true;
            }
            else if (job.RemoveGasPipe)
            {
                GasPipeKind removedKind = gasPipeKind[job.Cell.x, job.Cell.y];
                ReleaseGasPipeContents(job.Cell);
                gasPipe[job.Cell.x, job.Cell.y] = false;
                gasPipeKind[job.Cell.x, job.Cell.y] = GasPipeKind.Normal;
                gasSensorMode[job.Cell.x, job.Cell.y] = GasSensorMode.AnyGas;
                gasPipeOxygen[job.Cell.x, job.Cell.y] = 0f;
                gasPipeCarbonDioxide[job.Cell.x, job.Cell.y] = 0f;
                gasPipePollutedOxygen[job.Cell.x, job.Cell.y] = 0f;
                gasPipeHydrogen[job.Cell.x, job.Cell.y] = 0f;
                gasPipeSteam[job.Cell.x, job.Cell.y] = 0f;
                gasPipeChlorine[job.Cell.x, job.Cell.y] = 0f;
                gasPipeNaturalGas[job.Cell.x, job.Cell.y] = 0f;
                gasPipeSourGas[job.Cell.x, job.Cell.y] = 0f;
                gasPipeGerms[job.Cell.x, job.Cell.y] = 0f;
                RefundGasPipeMaterials(removedKind);
                gasDirty = true;
                overlayDirty = true;
            }
            else if (job.RemoveShippingRail)
            {
                ReleaseShippingRailContents(job.Cell);
                shippingRail[job.Cell.x, job.Cell.y] = false;
                shippingRailKind[job.Cell.x, job.Cell.y] = LooseResourceKind.None;
                shippingRailAmount[job.Cell.x, job.Cell.y] = 0f;
                shippingRailMeterFlowRemaining[job.Cell.x, job.Cell.y] = 0f;
                StoreDryResource(ref metal, 0.5f);
                overlayDirty = true;
            }

            deconstructionsCompleted++;
            Log(worker.Name + " deconstructed " + label + ".");
        }

        private void RemoveBuiltCell(Vector2Int cell, CellKind removedKind)
        {
            float releasedReservoirOxygen = removedKind == CellKind.GasReservoir ? gasReservoirOxygen[cell.x, cell.y] : 0f;
            float releasedReservoirCarbon = removedKind == CellKind.GasReservoir ? gasReservoirCarbonDioxide[cell.x, cell.y] : 0f;
            float releasedReservoirPolluted = removedKind == CellKind.GasReservoir ? gasReservoirPollutedOxygen[cell.x, cell.y] : 0f;
            float releasedReservoirHydrogen = removedKind == CellKind.GasReservoir ? gasReservoirHydrogen[cell.x, cell.y] : 0f;
            float releasedReservoirSteam = removedKind == CellKind.GasReservoir ? gasReservoirSteam[cell.x, cell.y] : 0f;
            float releasedReservoirChlorine = removedKind == CellKind.GasReservoir ? gasReservoirChlorine[cell.x, cell.y] : 0f;
            float releasedReservoirNaturalGas = removedKind == CellKind.GasReservoir ? gasReservoirNaturalGas[cell.x, cell.y] : 0f;
            float releasedReservoirSourGas = removedKind == CellKind.GasReservoir ? gasReservoirSourGas[cell.x, cell.y] : 0f;
            float releasedReservoirGerms = removedKind == CellKind.GasReservoir ? gasReservoirGerms[cell.x, cell.y] : 0f;
            bool releasedIncubatorEgg = removedKind == CellKind.Incubator && incubatorEggLoaded[cell.x, cell.y];
            ConstructionMaterialGrade removedGrade = constructionMaterialGrade[cell.x, cell.y];
            cells[cell.x, cell.y] = CellKind.Empty;
            buildingDisabled[cell.x, cell.y] = false;
            constructionMaterialGrade[cell.x, cell.y] = ConstructionMaterialGrade.Basic;
            if (removedKind == CellKind.Battery)
            {
                maxPower = Mathf.Max(100f, maxPower - (techPowerRegulation ? 100f : 60f));
                power = Mathf.Min(power, maxPower);
            }
            else if (removedKind == CellKind.JumboBattery)
            {
                maxPower = Mathf.Max(100f, maxPower - JumboBatteryCapacity);
                power = Mathf.Min(power, maxPower);
            }
            else if (removedKind == CellKind.SmartBattery)
            {
                maxPower = Mathf.Max(100f, maxPower - SmartBatteryCapacity);
                power = Mathf.Min(power, maxPower);
                smartBatteryLowThreshold[cell.x, cell.y] = SmartBatteryLowThreshold;
                smartBatteryHighThreshold[cell.x, cell.y] = SmartBatteryHighThreshold;
                smartBatterySignalState[cell.x, cell.y] = false;
            }
            else if (IsCropKind(removedKind))
            {
                plantGrowth[cell.x, cell.y] = 0f;
                cropTendedSeconds[cell.x, cell.y] = 0f;
                cropStress[cell.x, cell.y] = 0f;
            }
            else if (removedKind == CellKind.AtmoSuitDock)
            {
                suitOxygen = Mathf.Min(suitOxygen, SuitOxygenCapacityTotal());
            }
            else if (removedKind == CellKind.OxygenMaskDock)
            {
                maskOxygen = Mathf.Min(maskOxygen, OxygenMaskCapacityTotal());
            }
            else if (removedKind == CellKind.PrintingPod && CountCells(CellKind.PrintingPod) == 0)
            {
                printingPodProgress = 0f;
                ClearPrintingPodOffers();
            }
            else if (removedKind == CellKind.LiquidReservoir)
            {
                StoreCleanWaterInStorage(liquidReservoirWater[cell.x, cell.y], liquidReservoirWaterGerms[cell.x, cell.y]);
                StorePollutedWaterInStorage(liquidReservoirPollutedWater[cell.x, cell.y], liquidReservoirPollutedWaterGerms[cell.x, cell.y]);
                StorePetroleumInStorage(liquidReservoirPetroleum[cell.x, cell.y]);
            }
            else if (releasedIncubatorEgg)
            {
                DropLooseResourceNear(cell, LooseResourceKind.HatchEgg, 1f);
            }

            waterMass[cell.x, cell.y] = 0f;
            generatorTuneUpSeconds[cell.x, cell.y] = 0f;
            sculptingBlockFinished[cell.x, cell.y] = false;
            liquidReservoirWater[cell.x, cell.y] = 0f;
