        private void CompleteSweep(Job job, Worker worker)
        {
            Vector2Int cell = job.Cell;
            if (!HasLooseResource(cell))
            {
                Log(worker.Name + " found no debris to sweep.");
                return;
            }

            LooseResourceKind kind = looseResourceKind[cell.x, cell.y];
            float amount = looseResourceAmount[cell.x, cell.y];
            float stored = StoreLooseResource(kind, amount, true);
            looseResourceAmount[cell.x, cell.y] = Mathf.Max(0f, amount - stored);
            if (looseResourceAmount[cell.x, cell.y] <= 0.05f)
            {
                looseResourceAmount[cell.x, cell.y] = 0f;
                looseResourceKind[cell.x, cell.y] = LooseResourceKind.None;
                hatchEggAge[cell.x, cell.y] = 0f;
            }

            sweptResources += stored;
            if (kind == LooseResourceKind.Slime || kind == LooseResourceKind.PollutedDirt)
            {
                AddGermyHands(worker, kind == LooseResourceKind.Slime ? 26f : 20f, kind == LooseResourceKind.Slime ? 3.5f : 2.5f);
            }

            milestoneResourceLogistics |= sweptResources >= 12f;
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + " swept " + stored.ToString("0.#") + " kg " + LooseResourceLabel(kind) + ".");
        }

        private void CompleteTendCrop(Job job, Worker worker)
        {
            Vector2Int crop = job.Cell;
            if (!IsCropTendingTarget(crop) || !TryFindFarmStationForCrop(crop, out Vector2Int station))
            {
                Log(worker.Name + " found no crop to tend.");
                return;
            }

            bool usedFertilizer = fertilizer >= CropTendFertilizerCost;
            bool usedPollutedDirt = !usedFertilizer && pollutedDirt >= CropTendPollutedDirtCost;
            if (usedFertilizer)
            {
                fertilizer = Mathf.Max(0f, fertilizer - CropTendFertilizerCost);
                fertilizerUsedForCrops += CropTendFertilizerCost;
            }
            else if (usedPollutedDirt)
            {
                pollutedDirt = Mathf.Max(0f, pollutedDirt - CropTendPollutedDirtCost);
            }
            else if (dirt >= CropTendDirtFallbackCost)
            {
                dirt = Mathf.Max(0f, dirt - CropTendDirtFallbackCost);
            }
            else
            {
                Log("Farm Station needs fertilizer, polluted dirt, or dirt for crop tending.");
                return;
            }

            float baseTendedSeconds = usedFertilizer ? FertilizedCropTendedSeconds : CropTendedSeconds;
            cropTendedSeconds[crop.x, crop.y] = baseTendedSeconds * WorkerJobOutputMultiplier(worker, job.Type);
            cropsTended++;
            WearEquipment(station, 0.004f);
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + " tended " + CropDisplayName(cells[crop.x, crop.y]).ToLowerInvariant() + " with " + (usedFertilizer ? "fertilizer." : usedPollutedDirt ? "polluted dirt." : "dirt."));
        }

        private bool EatStoredFood(Worker worker, bool seated)
        {
            if (!CanWorkerEatStoredFood(worker))
            {
                if (worker != null && food >= 700f && EffectiveFoodPolicyMode(worker) == FoodPolicyMode.Safe && IsStoredFoodUnsafe())
                {
                    unsafeMealsBlockedByPolicy++;
                    Log(worker.Name + " skipped unsafe stored food due to " + (worker.FoodPolicyOverride == WorkerFoodPolicyMode.Safe ? "personal " : string.Empty) + "Food SAFE policy.");
                }

                return false;
            }

            float mealQuality = Mathf.Clamp01(foodQuality);
            bool emergencyUnsafeMeal = EffectiveFoodPolicyMode(worker) == FoodPolicyMode.Safe &&
                IsStoredFoodUnsafe() &&
                IsFoodPolicyEmergencyMeal(worker);
            food -= 700f;
            currentCycleReport.FoodConsumed += 700f;
            worker.Calories = Mathf.Min(3200f, worker.Calories + (seated ? 1450f : 1200f));
            if (seated)
            {
                RoomKind diningRoom = RoomKindAt(worker.Cell.x, worker.Cell.y);
                worker.Stress = Mathf.Max(0f, worker.Stress - DiningStressRelief(worker.Cell));
                worker.Morale = Mathf.Min(10f, worker.Morale + (diningRoom == RoomKind.GreatHall ? 1.55f : diningRoom == RoomKind.MessHall ? 1.1f : 0.7f));
                mealsEatenAtTable++;
                Log(worker.Name + (diningRoom == RoomKind.GreatHall ? " ate in the Great Hall." : " ate at a Mess Table."));
            }
            else
            {
                worker.Stress = Mathf.Min(100f, worker.Stress + 1.5f);
                worker.Morale = Mathf.Max(0f, worker.Morale - 0.25f);
                AddAteWithoutTable(worker);
                Log(worker.Name + " ate without a table.");
            }

            ApplyMealQualityEffects(worker, seated, mealQuality);
            ApplyGermyHandsMealEffects(worker, seated);
            ApplyFoodQualityEffects(worker, seated);
            if (emergencyUnsafeMeal)
            {
                emergencyUnsafeMealsEaten++;
                Log(worker.Name + " ate unsafe food under emergency Food SAFE rules.");
            }

            if (food <= 1f)
            {
                food = 0f;
                foodFreshness = 1f;
                foodQuality = DefaultFoodQuality;
            }

            return true;
        }

        private void ApplyGermyHandsMealEffects(Worker worker, bool seated)
        {
            if (worker == null || worker.GermyHandsSeconds <= 0f)
            {
                return;
            }

            float severity = Mathf.Clamp01(worker.GermyHandsSeconds / GermyHandsDurationSeconds);
            float contamination = Mathf.Lerp(0.04f, GermyHandsFoodContaminationScale, severity);
            if (worker.FoodSafeHandsSeconds > 0f)
            {
                contamination *= FoodSafeHandsGermyHandsContaminationMultiplier;
            }

            foodGerms = Mathf.Clamp01(foodGerms + contamination * (food > 0f ? 0.55f : 0.25f));
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + Mathf.Lerp(4f, 14f, severity) * WorkerFoodIllnessMultiplier(worker));
            worker.Stress = Mathf.Min(100f, worker.Stress + (seated ? 0.35f : 0.75f) * Mathf.Lerp(0.35f, 1f, severity));
            if (severity >= 0.45f)
            {
                Log(worker.Name + " contaminated food with germy hands.");
            }
        }

        private float FoodHandlingContaminationAt(Vector2Int cell, Worker worker)
        {
            float contamination = 0f;
            if (IsInside(cell.x, cell.y))
            {
                contamination += FoodStorageContaminationScoreAt(cell.x, cell.y) * 0.45f;
                if (IsPollutedWorldLiquidAt(cell.x, cell.y))
                {
                    contamination += 0.18f;
                }
            }

            if (worker != null)
            {
                float exposureMultiplier = worker.FoodSafeHandsSeconds > 0f ? FoodSafeHandsExposureContaminationMultiplier : 1f;
                float handsMultiplier = worker.FoodSafeHandsSeconds > 0f ? FoodSafeHandsGermyHandsContaminationMultiplier : 1f;
                contamination += Mathf.Clamp01(worker.GermExposure / 100f) * 0.32f * exposureMultiplier;
                contamination += Mathf.Clamp01(worker.GermyHandsSeconds / GermyHandsDurationSeconds) * 0.34f * handsMultiplier;
                if (worker.Disease == WorkerDisease.FoodPoisoning)
                {
                    contamination += 0.08f;
                }
            }

            return Mathf.Clamp01(contamination);
        }

        private void ApplyMealQualityEffects(Worker worker, bool seated, float mealQuality)
        {
            if (worker == null)
            {
                return;
            }

            if (mealQuality >= 0.55f)
            {
                float bonus = Mathf.InverseLerp(0.55f, ElectricGrillFoodQuality, mealQuality);
                worker.Morale = Mathf.Min(10f, worker.Morale + Mathf.Lerp(0.25f, seated ? 0.85f : 0.45f, bonus));
                worker.Stress = Mathf.Max(0f, worker.Stress - Mathf.Lerp(0.6f, seated ? 2.8f : 1.4f, bonus));
                if (mealQuality >= ElectricGrillQualityTarget)
                {
                    Log(worker.Name + (seated ? " enjoyed a quality meal." : " ate a quality ration."));
                }
            }
            else if (mealQuality < 0.25f)
            {
                float penalty = Mathf.InverseLerp(0.25f, 0f, mealQuality);
                worker.Morale = Mathf.Max(0f, worker.Morale - 0.25f * penalty);
                worker.Stress = Mathf.Min(100f, worker.Stress + 0.8f * penalty);
            }

            ApplyGourmetMealEffects(worker, seated, mealQuality);
        }

        private void ApplyGourmetMealEffects(Worker worker, bool seated, float mealQuality)
        {
            if (worker == null || worker.Trait != WorkerTrait.Gourmet)
            {
                return;
            }

            if (mealQuality >= GourmetHighQualityThreshold)
            {
                float quality = Mathf.InverseLerp(GourmetHighQualityThreshold, PeppernutGrillFoodQuality, mealQuality);
                worker.Morale = Mathf.Min(10f, worker.Morale + Mathf.Lerp(0.35f, seated ? 1.0f : 0.55f, quality));
                worker.Stress = Mathf.Max(0f, worker.Stress - Mathf.Lerp(0.4f, seated ? 1.8f : 0.9f, quality));
            }
            else if (mealQuality < GourmetLowQualityThreshold)
            {
                float disappointment = Mathf.InverseLerp(GourmetLowQualityThreshold, 0f, mealQuality);
                worker.Morale = Mathf.Max(0f, worker.Morale - Mathf.Lerp(0.15f, 0.55f, disappointment));
                worker.Stress = Mathf.Min(100f, worker.Stress + Mathf.Lerp(0.35f, seated ? 0.85f : 1.25f, disappointment));
            }
        }

        private void ApplyFoodQualityEffects(Worker worker, bool seated)
        {
            if (worker == null)
            {
                return;
            }

            bool loggedFoodRisk = false;
            if (foodFreshness < StaleFoodFreshnessThreshold)
            {
                staleMealsEaten++;
                float staleSeverity = Mathf.Clamp01((StaleFoodFreshnessThreshold - foodFreshness) / StaleFoodFreshnessThreshold);
                staleSeverity *= WorkerFoodIllnessMultiplier(worker);
                worker.Stress = Mathf.Min(100f, worker.Stress + (seated ? 1.2f : 2.1f) * staleSeverity);
                worker.Morale = Mathf.Max(0f, worker.Morale - 0.35f * staleSeverity);
                worker.GermExposure = Mathf.Min(100f, worker.GermExposure + 8f * staleSeverity);

                if (foodFreshness < FoodPoisoningFreshnessThreshold)
                {
                    float poisonSeverity = Mathf.Clamp01((FoodPoisoningFreshnessThreshold - foodFreshness) / FoodPoisoningFreshnessThreshold);
                    poisonSeverity *= WorkerFoodIllnessMultiplier(worker);
                    ApplyFoodPoisoning(worker, poisonSeverity, worker.Name + " developed Food Poisoning from spoiled food.");
                    loggedFoodRisk = true;
                }
                else
                {
                    Log(worker.Name + " ate stale food. Fresh storage is needed.");
                    loggedFoodRisk = true;
                }
            }

            ApplyFoodContaminationEffects(worker, seated, loggedFoodRisk);
        }

        private void ApplyFoodContaminationEffects(Worker worker, bool seated, bool alreadyLogged)
        {
            if (worker == null || foodGerms < FoodGermExposureThreshold)
            {
                return;
            }

            contaminatedMealsEaten++;
            float severity = Mathf.InverseLerp(FoodGermExposureThreshold, 1f, foodGerms);
            severity *= WorkerFoodIllnessMultiplier(worker);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + 18f * severity);
            worker.Stress = Mathf.Min(100f, worker.Stress + (seated ? 1.0f : 1.8f) * severity);
            worker.Morale = Mathf.Max(0f, worker.Morale - 0.25f * severity);

            if (foodGerms >= FoodGermPoisoningThreshold)
            {
                float poisonSeverity = Mathf.InverseLerp(FoodGermPoisoningThreshold, 1f, foodGerms);
                poisonSeverity *= WorkerFoodIllnessMultiplier(worker);
                ApplyFoodPoisoning(worker, poisonSeverity, worker.Name + " developed Food Poisoning from contaminated food.");
                return;
            }

            if (!alreadyLogged)
            {
                Log(worker.Name + " ate contaminated food. Improve hygiene or sterilize storage.");
            }
        }

        private void ApplyFoodPoisoning(Worker worker, float severity, string logMessage)
        {
            if (worker == null || severity <= 0f)
            {
                return;
            }

            worker.Sickness = Mathf.Min(100f, worker.Sickness + 18f * severity);
            ContractWorkerDisease(worker, WorkerDisease.FoodPoisoning, 22f * severity, logMessage);
            worker.Health = Mathf.Max(0f, worker.Health - 5f * severity);
            worker.Stress = Mathf.Min(100f, worker.Stress + 4f * severity);
            AddNauseous(worker, Mathf.Lerp(16f, NauseousDurationSeconds, Mathf.Clamp01(severity)));
            foodPoisoningCases++;
            if (IsInside(worker.Cell.x, worker.Cell.y))
            {
                germs[worker.Cell.x, worker.Cell.y] = Mathf.Clamp01(germs[worker.Cell.x, worker.Cell.y] + 0.12f * severity);
                pollutedOxygen[worker.Cell.x, worker.Cell.y] = Mathf.Min(2.5f, pollutedOxygen[worker.Cell.x, worker.Cell.y] + 0.04f * severity);
                gasDirty = true;
                overlayDirty = true;
            }
        }

        private float WorkerFoodIllnessMultiplier(Worker worker)
        {
            return worker != null && worker.Trait == WorkerTrait.IronGut ? 0.45f : 1f;
        }

        private void CompleteRefineMetal(Job job, Worker worker)
        {
            if (CanRockCrusherProduceGlass(job.Cell) && (refinedMetal >= 8f || metal < RockCrusherOrePerJob || glass <= 0.001f))
            {
                CompleteProduceGlass(job, worker);
                return;
            }

            if (CanRockCrusherProduceCeramic(job.Cell) && (refinedMetal >= 8f || metal < RockCrusherOrePerJob || ceramic <= 0.001f))
            {
                CompleteProduceCeramic(job, worker);
                return;
            }

            float oreUsed = Mathf.Min(metal, RockCrusherOrePerJob);
            if (oreUsed <= 0.5f || power < RockCrusherPowerCost || !CanPoweredMachineRun(job.Cell))
            {
                Log("Rock Crusher needs metal ore and power.");
                return;
            }

            metal = Mathf.Max(0f, metal - oreUsed);
            ConsumeCyclePower(RockCrusherPowerCost);
            float produced = RockCrusherRefinedMetalYield * (oreUsed / RockCrusherOrePerJob) * WorkerJobOutputMultiplier(worker, JobType.RefineMetal);
            float stored = StoreDryResource(ref refinedMetal, produced);
            refinedMetalProduced += stored;
            AddHeat(job.Cell, 1.8f, 1);
            WearEquipment(job.Cell, 0.020f);
            Log(worker.Name + " refined " + stored.ToString("0.0") + " kg metal.");
        }

        private void CompleteProduceCeramic(Job job, Worker worker)
        {
            if (!CanRockCrusherProduceCeramic(job.Cell))
            {
                Log("Rock Crusher needs Thermal Engineering, dirt, coal, power, and storage for ceramic.");
                return;
            }

            dirt = Mathf.Max(0f, dirt - CeramicDirtPerJob);
            coal = Mathf.Max(0f, coal - CeramicCoalPerJob);
            ConsumeCyclePower(CeramicPowerCost);
            float produced = CeramicYieldPerJob * WorkerJobOutputMultiplier(worker, JobType.RefineMetal);
            float stored = StoreDryResource(ref ceramic, produced);
            ceramicProduced += stored;
            AddHeat(job.Cell, CeramicHeatPerJob, 1);
            WearEquipment(job.Cell, 0.024f);
            int retrofits = RetrofitCeramicInsulatedTiles();
            Log(worker.Name + " fired " + stored.ToString("0.0") + " kg ceramic." + (retrofits > 0 ? " Upgraded " + retrofits + " Insulated Tile(s)." : string.Empty));
        }

        private void CompleteProduceGlass(Job job, Worker worker)
        {
            if (!CanRockCrusherProduceGlass(job.Cell))
            {
                Log("Rock Crusher needs Space Systems, dirt, ceramic flux, power, and storage for glass.");
                return;
            }

            dirt = Mathf.Max(0f, dirt - GlassDirtPerJob);
            ceramic = Mathf.Max(0f, ceramic - GlassCeramicFluxPerJob);
            ConsumeCyclePower(GlassPowerCost);
            float produced = GlassYieldPerJob * WorkerJobOutputMultiplier(worker, JobType.RefineMetal);
            float stored = StoreDryResource(ref glass, produced);
            glassProduced += stored;
            AddHeat(job.Cell, GlassHeatPerJob, 1);
            WearEquipment(job.Cell, 0.026f);
            Log(worker.Name + " melted " + stored.ToString("0.0") + " kg glass.");
        }

        private bool CanAnyRockCrusherProduceGlass()
        {
            if (!ShouldProduceGlass())
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.RockCrusher && CanRockCrusherProduceGlass(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool CanRockCrusherProduceGlass(Vector2Int cell)
        {
            return ShouldProduceGlass() &&
                IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.RockCrusher &&
                power >= GlassPowerCost &&
                CanPoweredMachineRun(cell);
        }

        private bool ShouldProduceGlass()
        {
            return techSpaceSystems &&
                milestoneCeramicInsulation &&
                CountCells(CellKind.SolarPanel) > 0 &&
                glass < GlassStockpileTarget - 0.001f &&
                dirt >= GlassDirtPerJob &&
                ceramic >= GlassCeramicFluxPerJob &&
                DryResourceFreeSpace() > 0.001f;
        }

        private bool CanAnyRockCrusherProduceCeramic()
        {
            if (!ShouldProduceCeramic())
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.RockCrusher && CanRockCrusherProduceCeramic(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool CanRockCrusherProduceCeramic(Vector2Int cell)
        {
            return ShouldProduceCeramic() &&
                IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.RockCrusher &&
                power >= CeramicPowerCost &&
                CanPoweredMachineRun(cell);
        }

        private bool ShouldProduceCeramic()
        {
            return techThermalEngineering &&
                milestoneInsulation &&
                ceramic < CeramicStockpileTarget - 0.001f &&
                dirt >= CeramicDirtPerJob &&
                coal >= CeramicCoalPerJob &&
                DryResourceFreeSpace() > 0.001f;
        }

        private string RockCrusherReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.RockCrusher)
            {
                return "Refining blocked: Rock Crusher missing.";
            }

            if (!techPowerRegulation)
            {
                return "Refining blocked: research Power Regulation.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Refining blocked: Rock Crusher needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Refining blocked: Rock Crusher is submerged.";
            }

            if (!HasWireAccess(cell))
            {
                return "Refining blocked: needs power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Refining blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Refining blocked: automation signal is red.";
            }

            if (CanRockCrusherProduceGlass(cell))
            {
                return RockCrusherReadyOrRouteBlockedText(
                    cell,
                    3.8f,
                    milestoneSolarLensing ? 4 : 6,
                    "Glass production ready: Rock Crusher can melt solar glass.");
            }

            if (CanRockCrusherProduceCeramic(cell))
            {
                return RockCrusherReadyOrRouteBlockedText(
                    cell,
                    3.8f,
                    CountCeramicInsulatedTiles() < CeramicInsulatedTileTarget ? 6 : 4,
                    "Ceramic production ready: Rock Crusher can fire ceramic.");
            }

            if (ShouldProduceGlass() && power < GlassPowerCost)
            {
                return "Glass production blocked: needs stored power.";
            }

            if (ShouldProduceCeramic() && power < CeramicPowerCost)
            {
                return "Ceramic production blocked: needs stored power.";
            }

            if (refinedMetal >= 40f && !ShouldProduceGlass() && !ShouldProduceCeramic())
            {
                return "Refining blocked: refined metal stock target met.";
            }

            if (power < RockCrusherPowerCost)
            {
                return "Refining blocked: needs stored power.";
            }

            if (DryResourceFreeSpace() <= 0.001f)
            {
                return "Refining blocked: dry storage is full.";
            }

            if (metal < RockCrusherOrePerJob)
            {
                return "Refining blocked: needs metal ore.";
            }

            return RockCrusherReadyOrRouteBlockedText(
                cell,
                3.6f,
                refinedMetal < 8f ? 7 : 4,
                "Refining ready: Rock Crusher can refine metal ore.");
        }

        private string RockCrusherReadyOrRouteBlockedText(Vector2Int cell, float workRequired, int priority, string readyText)
        {
            Job refineJob = FindJobAt(cell, JobType.RefineMetal);
            if (refineJob != null)
            {
                return "Refining ready: Rock Crusher errand queued. " + JobReachabilityText(refineJob);
            }

            Job testJob = new Job(JobType.RefineMetal, cell, workRequired)
            {
                Priority = priority
            };
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Refining blocked: ",
                "Refining blocked: no reachable duplicant path to Rock Crusher.");
            return string.IsNullOrEmpty(routeBlock) ? readyText : routeBlock;
        }

        private int RetrofitCeramicInsulatedTiles()
        {
            int upgraded = 0;
            for (int y = 0; y < WorldHeight && ceramic >= CeramicInsulatedTileCost; y++)
            {
                for (int x = 0; x < WorldWidth && ceramic >= CeramicInsulatedTileCost; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (TryApplyCeramicInsulation(cell))
                    {
                        upgraded++;
                    }
                }
            }

            if (upgraded > 0)
            {
                terrainDirty = true;
                overlayDirty = true;
            }

            return upgraded;
        }

        private bool TryApplyCeramicInsulation(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) ||
                cells[cell.x, cell.y] != CellKind.InsulatedTile ||
                constructionMaterialGrade[cell.x, cell.y] == ConstructionMaterialGrade.HighGrade ||
                ceramic < CeramicInsulatedTileCost)
            {
                return false;
            }

            ceramic = Mathf.Max(0f, ceramic - CeramicInsulatedTileCost);
            ceramicUsedForInsulation += CeramicInsulatedTileCost;
            constructionMaterialGrade[cell.x, cell.y] = ConstructionMaterialGrade.HighGrade;
            return true;
        }

        private int CountCeramicInsulatedTiles()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.InsulatedTile &&
                        constructionMaterialGrade[x, y] == ConstructionMaterialGrade.HighGrade)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int RetrofitThermiumMachinery()
        {
            int upgraded = 0;
            for (int y = 0; y < WorldHeight && thermium >= ThermiumCoatingCost; y++)
            {
                for (int x = 0; x < WorldWidth && thermium >= ThermiumCoatingCost; x++)
                {
                    if (TryApplyThermiumCoating(new Vector2Int(x, y)))
                    {
                        upgraded++;
                    }
                }
            }

            return upgraded;
        }

        private bool TryApplyThermiumCoating(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) ||
                !IsThermiumCoatingTarget(cells[cell.x, cell.y]) ||
                constructionMaterialGrade[cell.x, cell.y] == ConstructionMaterialGrade.Thermium ||
                thermium < ThermiumCoatingCost)
            {
                return false;
            }

            thermium = Mathf.Max(0f, thermium - ThermiumCoatingCost);
            thermiumUsedForCoating += ThermiumCoatingCost;
            constructionMaterialGrade[cell.x, cell.y] = ConstructionMaterialGrade.Thermium;
            equipmentCondition[cell.x, cell.y] = Mathf.Max(equipmentCondition[cell.x, cell.y], EquipmentAutoRepairThreshold);
            terrainDirty = true;
            overlayDirty = true;
            return true;
        }

        private bool IsThermiumCoatingTarget(CellKind kind)
        {
            return kind == CellKind.MetalRefinery ||
                kind == CellKind.OilRefinery ||
                kind == CellKind.OilWell ||
                kind == CellKind.EthanolDistiller ||
                kind == CellKind.TextileLoom ||
                kind == CellKind.PolymerPress ||
                kind == CellKind.PetroleumGenerator ||
                kind == CellKind.SteamTurbine ||
                kind == CellKind.ThermoAquatuner ||
                kind == CellKind.SourGasCondenser ||
                kind == CellKind.BunkerDoor ||
                kind == CellKind.RocketPlatform;
        }

        private int CountThermiumCoatedEquipment()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsThermiumCoatingTarget(cells[x, y]) &&
                        constructionMaterialGrade[x, y] == ConstructionMaterialGrade.Thermium)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private void GrantWorkerExperience(Worker worker, Job job)
        {
            if (worker == null || job == null || worker.Health <= 0f)
            {
                return;
            }

            float amount =
                ExperienceForJob(job.Type) *
                WorkerExperienceMultiplier(worker) *
                WorkerInterestExperienceMultiplier(worker, job.Type) *
                WorkerOverjoyedExperienceMultiplier(worker);
            if (amount <= 0f)
            {
                return;
            }

            bool interestedWork = WorkerInterestMatchesJob(worker, job.Type);
            int oldLevel = WorkerSkillLevel(worker);
            worker.Experience = Mathf.Min(MaxWorkerExperience(), Mathf.Max(0f, worker.Experience) + amount);
            if (interestedWork)
            {
                worker.Morale = Mathf.Min(10f, worker.Morale + 0.10f);
                worker.Stress = Mathf.Max(0f, worker.Stress - 0.35f);
            }

            int newLevel = WorkerSkillLevel(worker);
            ApplyWorkerRoleCompletionEffects(worker, job);
            if (newLevel > oldLevel)
            {
                worker.Stress = Mathf.Max(0f, worker.Stress - 2f);
                string roleTrainingUnlock = WorkerRoleMasteryUnlockLogText(worker, oldLevel, newLevel);
                Log(worker.Name + " reached Skill Lv " + newLevel + ". Work speed improved; morale need is " + WorkerMoraleNeed(worker).ToString("0.0") + "." + roleTrainingUnlock);
            }
            else if (interestedWork && amount >= 10f)
            {
                Log(worker.Name + " enjoyed " + JobCategoryName(worker.Interest).ToLowerInvariant() + " work.");
            }
        }

        private float ExperienceForJob(JobType type)
        {
            switch (type)
            {
                case JobType.Research:
                    return 28f;
                case JobType.Treat:
                    return 24f;
                case JobType.ProduceMedicine:
                    return 18f;
                case JobType.Shower:
                    return 12f;
                case JobType.WashHands:
                    return 10f;
                case JobType.Cook:
                    return 20f;
                case JobType.RefineMetal:
                    return 18f;
                case JobType.Build:
                    return 18f;
                case JobType.Dig:
                    return 16f;
                case JobType.OperateGenerator:
                case JobType.PumpWater:
                case JobType.EmptyBottle:
                    return 14f;
                case JobType.TendCrop:
                    return 14f;
                case JobType.BuildWire:
                case JobType.BuildAutomationWire:
                case JobType.BuildPipe:
                case JobType.BuildGasPipe:
                case JobType.BuildShippingRail:
                case JobType.Deconstruct:
                case JobType.Mop:
                case JobType.Disinfect:
                case JobType.Repair:
                case JobType.Rescue:
                case JobType.Sweep:
                case JobType.Harvest:
                    return 12f;
                case JobType.Compost:
                    return 14f;
                case JobType.GroomHatch:
                case JobType.WrangleCritter:
                case JobType.ButcherCritter:
                    return 16f;
                case JobType.ScrubSkill:
                    return 0f;
                default:
                    return 0f;
            }
        }

        private int WorkerSkillLevel(Worker worker)
        {
            if (worker == null)
            {
                return 1;
            }

            return Mathf.Clamp(1 + Mathf.FloorToInt(Mathf.Max(0f, worker.Experience) / SkillExperiencePerLevel), 1, MaxWorkerSkillLevel);
        }

        private float WorkerSkillSpeedMultiplier(Worker worker)
        {
            return 0.94f + WorkerSkillLevel(worker) * 0.06f;
        }

        private float WorkerTraitPassiveWorkSpeedMultiplier(Worker worker)
        {
            if (worker == null)
            {
                return 1f;
            }

            return worker.Trait == WorkerTrait.Anxious ? 1.04f : 1f;
        }

        private float WorkerOverjoyedPassiveWorkSpeedMultiplier(Worker worker)
        {
            if (!IsWorkerOverjoyed(worker))
            {
                return 1f;
            }

            switch (worker.OverjoyedResponse)
            {
                case WorkerOverjoyedResponse.SparkleStreak:
                    return 1.12f;
                case WorkerOverjoyedResponse.SuperProductive:
                    return 1.08f;
                default:
                    return 1f;
            }
        }

        private float WorkerTraitJobSpeedMultiplier(Worker worker, JobType type)
        {
            if (worker == null)
            {
                return 1f;
            }

            switch (worker.Trait)
            {
                case WorkerTrait.MoleHands:
                    return IsConstructionOrDiggingJob(type) ? 1.16f : 1f;
                case WorkerTrait.Gearhead:
                    return IsMachineJob(type) ? 1.14f : 1f;
                case WorkerTrait.Anxious:
                    return 1.04f;
                default:
                    return 1f;
            }
        }

        private bool WorkerInterestMatchesJob(Worker worker, JobType type)
        {
            return worker != null && JobCategoryFor(type) == worker.Interest;
        }

        private bool WorkerRoleMatchesJob(Worker worker, JobType type)
        {
            return worker != null && JobCategoryFor(type) == worker.Role;
        }

        private int WorkerRoleMasteryTier(Worker worker)
        {
            return worker == null ? 0 : WorkerRoleMasteryTierForLevel(WorkerSkillLevel(worker));
        }

        private int WorkerRoleMasteryTierForLevel(int skillLevel)
        {
            if (skillLevel >= MaxWorkerSkillLevel)
            {
                return 3;
            }

            if (skillLevel >= 3)
            {
                return 2;
            }

            return skillLevel >= 2 ? 1 : 0;
        }

        private string WorkerRoleMasteryName(int tier)
        {
            switch (tier)
            {
                case 1:
                    return "Apprentice";
                case 2:
                    return "Specialist";
                case 3:
                    return "Expert";
                default:
                    return "Untrained";
            }
        }

        private float WorkerRoleSpeedMultiplierForTier(int tier)
        {
            switch (tier)
            {
                case 1:
                    return WorkerRoleApprenticeSpeedMultiplier;
                case 2:
                    return WorkerRoleSpecialistSpeedMultiplier;
                case 3:
                    return WorkerRoleExpertSpeedMultiplier;
                default:
                    return 1f;
            }
        }

        private float WorkerRoleOutputMultiplierForTier(int tier)
        {
            switch (tier)
            {
                case 1:
                    return WorkerRoleApprenticeOutputMultiplier;
                case 2:
                    return WorkerRoleSpecialistOutputMultiplier;
                case 3:
                    return WorkerRoleExpertOutputMultiplier;
                default:
                    return 1f;
            }
        }

        private float WorkerRoleJobSpeedMultiplier(Worker worker, JobType type)
        {
            if (!WorkerRoleMatchesJob(worker, type))
            {
                return 1f;
            }

            return WorkerRoleSpeedMultiplierForTier(WorkerRoleMasteryTier(worker));
        }

        private float WorkerRoleOutputMultiplier(Worker worker, JobType type)
        {
            if (!WorkerRoleMatchesJob(worker, type))
            {
                return 1f;
            }

            return WorkerRoleOutputMultiplierForTier(WorkerRoleMasteryTier(worker));
        }

        private float WorkerOverjoyedOutputMultiplier(Worker worker)
        {
            return IsWorkerOverjoyed(worker) && worker.OverjoyedResponse == WorkerOverjoyedResponse.SuperProductive
                ? SuperProductiveOutputMultiplier
                : 1f;
        }

        private float WorkerJobOutputMultiplier(Worker worker, JobType type)
        {
            return WorkerRoleOutputMultiplier(worker, type) * WorkerOverjoyedOutputMultiplier(worker);
        }

        private float WorkerRoleFoodQualityBonus(Worker worker, JobType type)
        {
            return WorkerRoleMatchesJob(worker, type) ? WorkerRoleMasteryTier(worker) * WorkerRoleFoodQualityBonusPerTier : 0f;
        }

        private float WorkerRoleMoraleBonus(Worker worker)
        {
            int tier = WorkerRoleMasteryTier(worker);
            return 0.20f + tier * 0.15f;
        }

        private void ApplyWorkerRoleCompletionEffects(Worker worker, Job job)
        {
            if (worker == null || job == null || !WorkerRoleMatchesJob(worker, job.Type))
            {
                return;
            }

            int tier = WorkerRoleMasteryTier(worker);
            if (tier <= 0)
            {
                return;
            }

            worker.Morale = Mathf.Min(10f, worker.Morale + 0.04f * tier);
            worker.Stress = Mathf.Max(0f, worker.Stress - (0.20f + 0.30f * tier));
        }

        private string WorkerRoleMasteryUnlockLogText(Worker worker, int oldLevel, int newLevel)
        {
            int oldTier = WorkerRoleMasteryTierForLevel(oldLevel);
            int newTier = WorkerRoleMasteryTierForLevel(newLevel);
            if (worker == null || newTier <= oldTier)
            {
                return string.Empty;
            }

            return " Unlocked " + WorkerRoleMasteryName(newTier) + " " + JobCategoryName(worker.Role) + " training.";
        }

        private float WorkerInterestJobSpeedMultiplier(Worker worker, JobType type)
        {
            return WorkerInterestMatchesJob(worker, type) ? 1.12f : 1f;
        }

        private float WorkerInterestExperienceMultiplier(Worker worker, JobType type)
        {
            return WorkerInterestMatchesJob(worker, type) ? 1.22f : 1f;
        }

        private float WorkerOverjoyedExperienceMultiplier(Worker worker)
        {
            return IsWorkerOverjoyed(worker) && worker.OverjoyedResponse == WorkerOverjoyedResponse.SuperProductive ? 1.30f : 1f;
        }

        private float WorkerDiseaseWorkSpeedMultiplier(Worker worker)
        {
            if (worker == null)
            {
                return 1f;
            }

            switch (worker.Disease)
            {
                case WorkerDisease.FoodPoisoning:
                    return worker.Sickness >= 15f ? 0.90f : 1f;
                case WorkerDisease.Slimelung:
                    return 0.84f;
                case WorkerDisease.HeatStroke:
                    return 0.78f;
                case WorkerDisease.Hypothermia:
                    return 0.82f;
                case WorkerDisease.RadiationSickness:
                    return 0.86f;
                default:
                    return 1f;
            }
        }

        private float WorkerDiseaseBreathRateMultiplier(Worker worker)
        {
            return worker != null && worker.Disease == WorkerDisease.Slimelung ? 1.22f : 1f;
        }

        private float WorkerNauseousWorkSpeedMultiplier(Worker worker)
        {
            if (worker == null || worker.NauseousSeconds <= 0f)
            {
                return 1f;
            }

            return Mathf.Lerp(1f, NauseousWorkSpeedMultiplier, Mathf.Clamp01(worker.NauseousSeconds / NauseousDurationSeconds));
        }

        private float WorkerSoppingWetWorkSpeedMultiplier(Worker worker)
        {
            if (worker == null || worker.SoppingWetSeconds <= 0f)
