            }

            return Mathf.Lerp(1f, ScaldedWorkSpeedMultiplier, Mathf.Clamp01(worker.ScaldedSeconds / ScaldedDurationSeconds));
        }

        private float WorkerThermalDiscomfortWorkSpeedMultiplier(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return 1f;
            }

            float exposure = Mathf.Max(worker.HeatExposure, worker.ChillExposure);
            if (exposure < ThermalDiscomfortExposureThreshold)
            {
                return 1f;
            }

            float severity = Mathf.InverseLerp(ThermalDiscomfortExposureThreshold, ThermalInjuryExposureThreshold, exposure);
            return Mathf.Lerp(1f, ThermalDiscomfortWorkSpeedMultiplier, severity);
        }

        private float WorkerAllergicReactionWorkSpeedMultiplier(Worker worker)
        {
            if (worker == null || worker.AllergicReactionSeconds <= 0f)
