        private bool IsConstructionOrDiggingJob(JobType type)
        {
            switch (type)
            {
                case JobType.Dig:
                case JobType.Build:
                case JobType.BuildWire:
                case JobType.BuildAutomationWire:
                case JobType.BuildPipe:
                case JobType.BuildGasPipe:
                case JobType.BuildShippingRail:
                case JobType.Deconstruct:
                    return true;
                default:
                    return false;
            }
        }

        private bool IsMachineJob(JobType type)
        {
            switch (type)
            {
                case JobType.OperateGenerator:
                case JobType.Repair:
                case JobType.RefineMetal:
                case JobType.PumpWater:
                case JobType.EmptyBottle:
                case JobType.Research:
                    return true;
                default:
                    return false;
            }
        }

        private float WorkerExperienceMultiplier(Worker worker)
        {
            return worker != null && worker.Trait == WorkerTrait.QuickLearner ? 1.35f : 1f;
        }

        private float WorkerBreathRateMultiplier(Worker worker)
        {
            if (worker == null)
            {
                return 1f;
            }

            switch (worker.Trait)
            {
                case WorkerTrait.DiversLungs:
                    return 0.68f;
                case WorkerTrait.MouthBreather:
                    return MouthBreatherBreathMultiplier;
                default:
                    return 1f;
            }
        }

        private float WorkerAirborneGermExposureMultiplier(Worker worker)
        {
            return worker != null && worker.Trait == WorkerTrait.DiversLungs ? 0.68f : 1f;
        }

        private float WorkerBladderFillMultiplier(Worker worker)
        {
            return worker != null && worker.Trait == WorkerTrait.SmallBladder ? SmallBladderFillMultiplier : 1f;
        }

        private float WorkerCalorieBurnMultiplier(Worker worker)
        {
            if (worker == null)
            {
                return 1f;
            }

            switch (worker.Trait)
            {
                case WorkerTrait.IronGut:
                    return 0.94f;
                case WorkerTrait.BottomlessStomach:
                    return BottomlessStomachCalorieBurnMultiplier;
                case WorkerTrait.MoleHands:
                case WorkerTrait.Gearhead:
                    return 1.04f;
                default:
                    return 1f;
            }
        }

        private float WorkerTraitMoveSpeedMultiplier(Worker worker)
        {
            return worker != null && worker.Trait == WorkerTrait.Twinkletoes ? TwinkletoesMoveSpeedMultiplier : 1f;
        }

        private float MaxWorkerExperience()
        {
            return SkillExperiencePerLevel * MaxWorkerSkillLevel;
        }

        private string WorkerSkillText(Worker worker)
        {
            int level = WorkerSkillLevel(worker);
            string text = "Skill Lv " + level + "  Work x" + WorkerSkillSpeedMultiplier(worker).ToString("0.00");
            if (level >= MaxWorkerSkillLevel)
            {
                return text + "  XP max";
            }

            float nextExperience = SkillExperiencePerLevel * level;
            return text + "  XP " + Mathf.FloorToInt(Mathf.Max(0f, worker.Experience)) + "/" + Mathf.FloorToInt(nextExperience);
        }

