        private string WorkerOverjoyedResponseText(Worker worker)
        {
            if (worker == null)
            {
                return "Overjoyed Sparkle Streak: high morale can trigger faster work, movement, and stress relief.";
            }

            string status = IsWorkerOverjoyed(worker)
                ? " Active " + worker.OverjoyedSeconds.ToString("0") + "s."
                : worker.OverjoyedCooldownSeconds > 0f
                    ? " Cooling down " + worker.OverjoyedCooldownSeconds.ToString("0") + "s."
                    : string.Empty;

            switch (worker.OverjoyedResponse)
            {
                case WorkerOverjoyedResponse.SuperProductive:
                    return "Overjoyed Super Productive: high morale can trigger faster work, 30% more XP, and 12% more selected output." + status;
                case WorkerOverjoyedResponse.JoyfulCaretaker:
                    return "Overjoyed Joyful Caretaker: high morale can trigger nearby stress relief." + status;
                case WorkerOverjoyedResponse.DecorInspired:
                    return "Overjoyed Decor Inspired: high morale creates a temporary decor aura that improves nearby morale." + status;
                default:
                    return "Overjoyed Sparkle Streak: high morale can trigger faster work, movement, and stress relief." + status;
            }
        }

