        private string WorkerDiseaseText(Worker worker)
        {
            if (worker == null || worker.Disease == WorkerDisease.None)
            {
                return "Disease None: no active disease.";
            }

            string status = " Sickness " + worker.Sickness.ToString("0") + "%  Germs " + worker.GermExposure.ToString("0") + "%.";
            switch (worker.Disease)
            {
                case WorkerDisease.FoodPoisoning:
                    return "Disease Food Poisoning: spoiled or contaminated meals raise bladder, stress, and can contaminate nearby air." + status;
                case WorkerDisease.Slimelung:
                    return "Disease Slimelung: raises oxygen use, slows work, and sheds airborne germs." + status;
                case WorkerDisease.HeatStroke:
                    return "Disease Heat Stroke: high heat exposure slows work and damages health." + status;
                case WorkerDisease.Hypothermia:
                    return "Disease Hypothermia: cold exposure slows work and damages health." + status;
                case WorkerDisease.RadiationSickness:
                    return "Disease Radiation Sickness: radiation exposure slows work and can keep damaging health." + status;
                default:
                    return "Disease None: no active disease.";
            }
        }

        private string WorkerTreatmentDiagnosticText(Worker worker)
        {
            if (worker == null)
            {
                return string.Empty;
            }

            if (NeedsRescue(worker))
            {
                if (CountCells(CellKind.MedicalCot) == 0)
                {
                    return "Medical rescue blocked: build a Medical Cot.";
                }

                return HasUsableMedicalCot()
                    ? "Medical rescue needed: waiting for a reachable rescuer and Medical Cot."
                    : "Medical rescue blocked: enable or repair a Medical Cot.";
            }

            bool needsTreatment = NeedsTreatment(worker);
            bool shouldMonitor = worker.Disease != WorkerDisease.None ||
                worker.Sickness >= 18f ||
                worker.GermExposure >= 45f ||
                worker.Health <= 85f;
            if (!needsTreatment && !shouldMonitor)
            {
                return string.Empty;
            }

            StringBuilder builder = new StringBuilder(needsTreatment ? "Treatment needed: " : "Treatment monitor: ");
            builder.Append("thresholds sick ");
            builder.Append(Mathf.RoundToInt(worker.Sickness));
            builder.Append("/35, germs ");
            builder.Append(Mathf.RoundToInt(worker.GermExposure));
            builder.Append("/70, health ");
            builder.Append(Mathf.RoundToInt(worker.Health));
            builder.Append("/72. ");

            builder.Append(WorkerTreatmentRouteText(worker));
            string medicalRestRouteText = WorkerMedicalRestRouteText(worker);
            if (!string.IsNullOrEmpty(medicalRestRouteText))
            {
                builder.Append(" ");
                builder.Append(medicalRestRouteText);
            }

            builder.Append(" Medicine ");
            builder.Append(medicine.ToString("0.0"));
            builder.Append("/");
            builder.Append(MedicineTreatmentUse.ToString("0.0"));
            if (medicine >= MedicineTreatmentUse)
            {
                builder.Append(" packs ready.");
            }
            else if (CountCells(CellKind.Apothecary) == 0)
            {
                builder.Append(" packs; build Apothecary for medicine.");
            }
            else if (CountMedicineReadyApothecaries() > 0)
            {
                builder.Append(" packs; Apothecary can improve recovery.");
            }
            else
            {
                builder.Append(" packs; Apothecary needs power, water, algae, or repair.");
            }

            return builder.ToString();
        }

        private string WorkerTreatmentRouteText(Worker worker)
        {
            if (!NeedsTreatment(worker))
            {
                return "Below treatment threshold.";
            }

            if (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.Treat)
            {
                return "Treatment active: assigned to Medical Cot.";
            }

            if (HasTreatmentJobFor(worker.Name))
            {
                return "Treatment errand queued.";
            }

            if (CountCells(CellKind.MedicalCot) == 0)
            {
                return "Treatment blocked: build a Medical Cot.";
            }

            if (!HasUsableMedicalCot())
            {
                return "Treatment blocked: enable or repair a Medical Cot.";
            }

            if (TryFindReachableMedicalCot(worker, out int distance))
            {
                return "Treatment route ready: open Medical Cot " + distance + " steps away.";
            }

            if (HasOpenMedicalCotFor(worker) &&
                TryGetPersonalNeedRouteBlockText(worker, JobType.Treat, out string treatmentRouteBlockText))
            {
                return RouteBlockTextWithPrefix(treatmentRouteBlockText, "Treatment blocked: ");
            }

            return HasOpenMedicalCotFor(worker)
                ? "Treatment blocked: no safe route to an open Medical Cot."
                : "Treatment blocked: all Medical Cots are reserved.";
        }

        private string WorkerMedicalRestRouteText(Worker worker)
        {
            if (!NeedsMedicalRest(worker))
            {
                return string.Empty;
            }

            if (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.MedicalRest)
            {
                return IsFloorMedicalRestJob(worker.AssignedJob)
                    ? "Medical rest active: resting on safe floor."
                    : "Medical rest active: recovering at Medical Cot.";
            }

            Job queuedMedicalRest = FindMedicalRestJobFor(worker.Name);
            if (queuedMedicalRest != null)
            {
                return IsFloorMedicalRestJob(queuedMedicalRest)
                    ? "Medical rest fallback ready: safe floor recovery."
                    : "Medical rest errand queued.";
            }

            if (CountCells(CellKind.MedicalCot) == 0)
            {
                if (IsFloorMedicalRestCell(worker.Cell) && IsPersonalRecoveryCellOpen(worker.Cell, worker))
                {
                    return "Medical rest fallback ready: safe floor recovery.";
                }

                if (IsFloorMedicalRestCell(worker.Cell))
                {
                    return "Medical rest waiting: safe floor recovery spot is occupied or reserved.";
                }

                return "Medical rest blocked: build a Medical Cot.";
            }

            if (!HasUsableMedicalCot())
            {
                if (IsFloorMedicalRestCell(worker.Cell) && IsPersonalRecoveryCellOpen(worker.Cell, worker))
                {
                    return "Medical rest fallback ready: safe floor recovery.";
                }

                if (IsFloorMedicalRestCell(worker.Cell))
                {
                    return "Medical rest waiting: safe floor recovery spot is occupied or reserved.";
                }

                return "Medical rest blocked: enable or repair a Medical Cot.";
            }

            if (AnyWorkerNeedsTreatment())
            {
                if (IsFloorMedicalRestCell(worker.Cell) && IsPersonalRecoveryCellOpen(worker.Cell, worker))
                {
                    return "Medical rest fallback ready: treatment patients have cot priority.";
                }

                return IsFloorMedicalRestCell(worker.Cell)
                    ? "Medical rest waiting: safe floor recovery spot is occupied or reserved."
                    : "Medical rest waiting: treatment patients have cot priority.";
            }

            if (TryFindReachableMedicalRestCot(worker, out int distance))
            {
                return "Medical rest route ready: open Medical Cot " + distance + " steps away.";
            }

            if (IsFloorMedicalRestCell(worker.Cell) && IsPersonalRecoveryCellOpen(worker.Cell, worker))
            {
                return "Medical rest fallback ready: safe floor recovery.";
            }

            if (IsFloorMedicalRestCell(worker.Cell))
            {
                return "Medical rest waiting: safe floor recovery spot is occupied or reserved.";
            }

            if (HasOpenMedicalCotFor(worker) &&
                TryGetPersonalNeedRouteBlockText(worker, JobType.MedicalRest, out string medicalRestRouteBlockText))
            {
                return RouteBlockTextWithPrefix(medicalRestRouteBlockText, "Medical rest blocked: ");
            }

            return HasOpenMedicalCotFor(worker)
                ? "Medical rest blocked: no safe route to an open Medical Cot."
                : "Medical rest blocked: all Medical Cots are reserved.";
        }

        private bool TryFindReachableMedicalCot(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cotCell = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.MedicalCot ||
                        !CanUseEquipment(cotCell) ||
                        !CanWorkerUsePersonalStation(cotCell, worker) ||
                        IsMedicalCotReserved(cotCell, worker))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Treat, cotCell, TreatmentWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path))
                    {
                        bestDistance = Mathf.Min(bestDistance, path.Count);
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool TryFindReachableMedicalRestCot(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cotCell = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.MedicalCot ||
                        !CanUseEquipment(cotCell) ||
                        !CanWorkerUsePersonalStation(cotCell, worker) ||
                        IsMedicalCotReserved(cotCell, worker))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.MedicalRest, cotCell, MedicalRestWorkRequired)
                    {
                        TargetWorkerName = worker.Name
                    };
                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path))
                    {
                        bestDistance = Mathf.Min(bestDistance, path.Count);
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool HasOpenMedicalCotFor(Worker worker)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cotCell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.MedicalCot &&
                        CanUseEquipment(cotCell) &&
                        CanWorkerUsePersonalStation(cotCell, worker) &&
                        !IsMedicalCotReserved(cotCell, worker))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private string WorkerNauseousText(Worker worker)
        {
            if (worker == null || worker.NauseousSeconds <= 0f)
            {
                return string.Empty;
            }

            return "Nauseous " + worker.NauseousSeconds.ToString("0") + "s remaining";
        }

        private string WorkerInterestText(Worker worker)
        {
            if (worker == null)
            {
                return "Interest Construction: matching errands are preferred and 12% faster.";
            }

            return "Interest " + JobCategoryName(worker.Interest) + ": matching errands are preferred, 12% faster, and grant 22% more XP.";
        }

        private string WorkerRoleText(Worker worker)
        {
            if (worker == null)
            {
                return "Role Construction: assigned errands get strong dispatch preference.";
            }

            string text = "Role " + JobCategoryName(worker.Role) + ": assigned errands get strong dispatch preference.";
            int tier = WorkerRoleMasteryTier(worker);
            if (tier > 0)
            {
                text += " " + WorkerRoleMasteryName(tier) + " training: role jobs work x" +
                    WorkerRoleSpeedMultiplierForTier(tier).ToString("0.00") +
                    ", selected output and care x" +
                    WorkerRoleOutputMultiplierForTier(tier).ToString("0.00") +
                    ", and reduce completion stress.";
            }

            if (worker.Role == worker.Interest)
            {
                text += " Matches interest.";
            }

            return text;
        }

        private void UpdateWorkerMorale(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return;
            }

            float target = WorkerMoraleTarget(worker);
            float current = Mathf.Clamp(worker.Morale, 0f, 10f);
            float adjustRate = MoraleAdjustRate * (target < current ? 0.65f : 1f);
            worker.Morale = Mathf.MoveTowards(current, target, adjustRate * deltaTime);

            float deficit = WorkerMoraleDeficit(worker);
            if (deficit > 0.05f)
            {
                float beforeStress = worker.Stress;
                worker.Stress = Mathf.Min(100f, worker.Stress + deficit * MoraleDeficitStressRate * deltaTime);
                moralePressureSeconds += deltaTime;
                moraleStressAdded += Mathf.Max(0f, worker.Stress - beforeStress);
                return;
            }

            float surplus = Mathf.Clamp(worker.Morale - WorkerMoraleNeed(worker), 0f, 6f);
            if (surplus > 0.05f)
            {
                worker.Stress = Mathf.Max(0f, worker.Stress - surplus * MoraleSurplusStressReliefRate * deltaTime);
            }
        }

        private void UpdateWorkerOverjoyed(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return;
            }

            if (worker.OverjoyedCooldownSeconds > 0f)
            {
                worker.OverjoyedCooldownSeconds = Mathf.Max(0f, worker.OverjoyedCooldownSeconds - deltaTime);
            }

            if (worker.StressBreakSeconds > 0f)
            {
                worker.OverjoyedSeconds = 0f;
                return;
            }

            if (worker.OverjoyedSeconds > 0f)
            {
                worker.OverjoyedSeconds = Mathf.Max(0f, worker.OverjoyedSeconds - deltaTime);
                ApplyOverjoyedPassiveEffects(worker, deltaTime);
                if (worker.OverjoyedSeconds <= 0f)
                {
                    worker.OverjoyedCooldownSeconds = OverjoyedCooldownSeconds;
                }

                return;
            }

            if (ShouldTriggerOverjoyed(worker))
            {
                StartOverjoyed(worker);
                ApplyOverjoyedPassiveEffects(worker, deltaTime);
            }
        }

        private bool ShouldTriggerOverjoyed(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                worker.StressBreakSeconds <= 0f &&
                worker.OverjoyedCooldownSeconds <= 0f &&
                worker.Stress <= OverjoyedTriggerStressMax &&
                worker.Morale - WorkerMoraleNeed(worker) >= OverjoyedTriggerMoraleSurplus;
        }

        private void StartOverjoyed(Worker worker)
        {
            worker.OverjoyedSeconds = OverjoyedDurationSeconds;
            worker.OverjoyedCooldownSeconds = 0f;
            worker.Stress = Mathf.Max(0f, worker.Stress - 1.5f);
            Log(worker.Name + " is overjoyed: " + WorkerOverjoyedResponseName(worker.OverjoyedResponse) + ".");
        }

        private bool IsWorkerOverjoyed(Worker worker)
        {
            return worker != null && worker.OverjoyedSeconds > 0f && worker.Health > 0f && worker.StressBreakSeconds <= 0f;
        }

        private void ApplyOverjoyedPassiveEffects(Worker worker, float deltaTime)
        {
            switch (worker.OverjoyedResponse)
            {
                case WorkerOverjoyedResponse.JoyfulCaretaker:
                    RelieveNearbyOverjoyedStress(worker, deltaTime);
                    break;
                case WorkerOverjoyedResponse.DecorInspired:
                    ApplyDecorInspiredAura(worker, deltaTime);
                    break;
                default:
                    worker.Stress = Mathf.Max(0f, worker.Stress - 0.18f * deltaTime);
                    break;
            }
        }

        private void ApplyDecorInspiredAura(Worker source, float deltaTime)
        {
            if (source == null || source.Health <= 0f || deltaTime <= 0f)
            {
                return;
            }

            foreach (Worker worker in workers)
            {
                if (worker == null || worker.Health <= 0f)
                {
                    continue;
                }

                int distance = Mathf.Abs(worker.Cell.x - source.Cell.x) + Mathf.Abs(worker.Cell.y - source.Cell.y);
                if (distance > DecorInspiredAuraRadius)
                {
                    continue;
                }

                float falloff = 1f - distance / (float)(DecorInspiredAuraRadius + 1);
                if (worker == source)
                {
                    worker.Morale = Mathf.Min(10f, worker.Morale + DecorInspiredSelfMoraleRate * deltaTime);
                    worker.Stress = Mathf.Max(0f, worker.Stress - (0.18f + DecorScoreAt(worker.Cell.x, worker.Cell.y)) * deltaTime);
                    continue;
                }

                worker.Morale = Mathf.Min(10f, worker.Morale + DecorInspiredNearbyMoraleRate * Mathf.Max(0.25f, falloff) * deltaTime);
                worker.Stress = Mathf.Max(0f, worker.Stress - DecorInspiredNearbyStressReliefRate * Mathf.Max(0.25f, falloff) * deltaTime);
            }
        }

        private void RelieveNearbyOverjoyedStress(Worker source, float deltaTime)
        {
            foreach (Worker worker in workers)
            {
                if (worker == null || worker.Health <= 0f)
                {
                    continue;
                }

                int distance = Mathf.Abs(worker.Cell.x - source.Cell.x) + Mathf.Abs(worker.Cell.y - source.Cell.y);
                if (distance > 5)
                {
                    continue;
                }

                float relief = worker == source ? 0.36f : 0.24f;
                worker.Stress = Mathf.Max(0f, worker.Stress - relief * deltaTime);
                if (worker != source)
                {
                    worker.Morale = Mathf.Min(10f, worker.Morale + 0.02f * deltaTime);
                }
            }
        }

        private WorkerDisease InferWorkerDisease(Worker worker)
        {
            if (worker == null)
            {
                return WorkerDisease.None;
            }

            if (worker.HeatExposure >= ThermalInjuryExposureThreshold)
            {
                return WorkerDisease.HeatStroke;
            }

            if (worker.ChillExposure >= ThermalInjuryExposureThreshold)
            {
                return WorkerDisease.Hypothermia;
            }

            if (worker.Sickness >= RadiationSicknessContractThreshold &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                RadiationAt(worker.Cell.x, worker.Cell.y) >= RadiationExposureThreshold)
            {
                return WorkerDisease.RadiationSickness;
            }

            if (worker.Sickness >= 35f && worker.GermExposure >= SlimelungGermExposureThreshold)
            {
                return WorkerDisease.Slimelung;
            }

            return worker.Sickness >= 35f ? WorkerDisease.FoodPoisoning : WorkerDisease.None;
        }

        private int WorkerDiseasePriority(WorkerDisease disease)
        {
            switch (disease)
            {
                case WorkerDisease.HeatStroke:
                case WorkerDisease.Hypothermia:
                case WorkerDisease.RadiationSickness:
                    return 3;
                case WorkerDisease.Slimelung:
                    return 2;
                case WorkerDisease.FoodPoisoning:
                    return 1;
                default:
                    return 0;
            }
        }

        private bool ContractWorkerDisease(Worker worker, WorkerDisease disease, float sicknessFloor, string logMessage)
        {
            if (worker == null || disease == WorkerDisease.None)
            {
                return false;
            }

            bool changed = worker.Disease == WorkerDisease.None || WorkerDiseasePriority(disease) > WorkerDiseasePriority(worker.Disease);
            if (worker.Disease == disease)
            {
                changed = false;
            }

            if (changed)
            {
                worker.Disease = disease;
                if (!string.IsNullOrEmpty(logMessage))
                {
                    Log(logMessage);
                }
            }

            worker.Sickness = Mathf.Max(worker.Sickness, sicknessFloor);
            return changed;
        }

        private void UpdateWorkerDisease(Worker worker, float deltaTime)
        {
            if (worker == null || worker.Health <= 0f || worker.Disease == WorkerDisease.None)
            {
                return;
            }

            switch (worker.Disease)
            {
                case WorkerDisease.FoodPoisoning:
                    worker.Bladder = Mathf.Min(100f, worker.Bladder + 0.55f * deltaTime);
                    worker.Calories = Mathf.Max(0f, worker.Calories - 0.10f * deltaTime);
                    worker.Stress = Mathf.Min(100f, worker.Stress + 0.22f * deltaTime);
                    break;
                case WorkerDisease.Slimelung:
                    worker.Stress = Mathf.Min(100f, worker.Stress + 0.42f * deltaTime);
                    if (worker.Sickness >= 55f)
                    {
                        worker.Health = Mathf.Max(0f, worker.Health - 0.18f * deltaTime);
                    }
                    break;
                case WorkerDisease.HeatStroke:
                    worker.Stress = Mathf.Min(100f, worker.Stress + 0.48f * deltaTime);
                    if (worker.HeatExposure < ThermalInjuryExposureThreshold)
                    {
                        worker.Sickness = Mathf.Max(0f, worker.Sickness - 0.28f * deltaTime);
                    }
                    break;
                case WorkerDisease.Hypothermia:
                    worker.Stress = Mathf.Min(100f, worker.Stress + 0.42f * deltaTime);
                    if (worker.ChillExposure < ThermalInjuryExposureThreshold)
                    {
                        worker.Sickness = Mathf.Max(0f, worker.Sickness - 0.24f * deltaTime);
                    }
                    break;
                case WorkerDisease.RadiationSickness:
                    worker.Stress = Mathf.Min(100f, worker.Stress + 0.36f * deltaTime);
                    if (RadiationAt(worker.Cell.x, worker.Cell.y) <= RadiationExposureThreshold)
                    {
                        worker.Sickness = Mathf.Max(0f, worker.Sickness - 0.22f * deltaTime);
                    }

                    if (worker.Sickness >= 55f)
                    {
                        worker.Health = Mathf.Max(0f, worker.Health - RadiationSicknessHealthDamageRate * deltaTime);
                    }
                    break;
            }

            ClearRecoveredDisease(worker);
        }

        private void UpdateMedicalCotRecovery(Worker worker, bool sleeping, float deltaTime)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                deltaTime <= 0f ||
                !IsInside(worker.Cell.x, worker.Cell.y) ||
                cells[worker.Cell.x, worker.Cell.y] != CellKind.MedicalCot)
            {
                return;
            }

            bool needsCare = worker.Health < 100f ||
                worker.Sickness > 0f ||
                worker.GermExposure > 0f ||
                worker.HeatExposure > 0f ||
                worker.ChillExposure > 0f ||
                worker.Disease != WorkerDisease.None;
            if (!needsCare)
            {
                return;
            }

            float clinicFactor = RoomKindAt(worker.Cell.x, worker.Cell.y) == RoomKind.Clinic ? ClinicPassiveRecoveryMultiplier : 1f;
            float restFactor = sleeping || worker.Activity == "Receiving Treatment" || worker.Activity == "Recovering" ? 1f : 0.55f;
            float recovery = clinicFactor * restFactor * deltaTime;
            worker.GermExposure = Mathf.Max(0f, worker.GermExposure - MedicalCotPassiveGermRecoveryRate * recovery);
            worker.Sickness = Mathf.Max(0f, worker.Sickness - MedicalCotPassiveSicknessRecoveryRate * recovery);
            worker.HeatExposure = Mathf.Max(0f, worker.HeatExposure - MedicalCotPassiveThermalRecoveryRate * recovery);
            worker.ChillExposure = Mathf.Max(0f, worker.ChillExposure - MedicalCotPassiveThermalRecoveryRate * recovery);
            worker.Stress = Mathf.Max(0f, worker.Stress - MedicalCotPassiveStressReliefRate * recovery);
            if (worker.Calories > 350f)
            {
                worker.Health = Mathf.Min(100f, worker.Health + MedicalCotPassiveHealthRecoveryRate * recovery);
            }

            ClearRecoveredDisease(worker);
        }

        private void ClearRecoveredDisease(Worker worker)
        {
            if (worker == null || worker.Disease == WorkerDisease.None)
            {
                return;
            }

            bool recovered;
            switch (worker.Disease)
            {
                case WorkerDisease.HeatStroke:
                    recovered = worker.HeatExposure <= DiseaseRecoveryThermalThreshold && worker.Health >= 72f && worker.Sickness <= 18f;
                    break;
                case WorkerDisease.Hypothermia:
                    recovered = worker.ChillExposure <= DiseaseRecoveryThermalThreshold && worker.Health >= 72f && worker.Sickness <= 18f;
                    break;
                case WorkerDisease.RadiationSickness:
                    recovered = RadiationAt(worker.Cell.x, worker.Cell.y) <= RadiationExposureThreshold &&
                        worker.Health >= 72f &&
                        worker.Sickness <= 18f;
                    break;
                default:
                    recovered = worker.Sickness <= DiseaseRecoverySicknessThreshold && worker.GermExposure <= DiseaseRecoveryGermThreshold;
                    break;
            }

            if (recovered)
            {
                string diseaseName = WorkerDiseaseName(worker.Disease);
                worker.Disease = WorkerDisease.None;
                Log(worker.Name + " recovered from " + diseaseName + ".");
            }
        }

        private float WorkerMoraleNeed(Worker worker)
        {
            int skillLevel = WorkerSkillLevel(worker);
            return Mathf.Max(0f, BaseWorkerMorale + Mathf.Max(0, skillLevel - 1) * MoraleNeedPerSkillLevel + WorkerTraitMoraleNeedOffset(worker));
        }

        private float WorkerTraitMoraleNeedOffset(Worker worker)
        {
            if (worker == null)
            {
                return 0f;
            }

            switch (worker.Trait)
            {
                case WorkerTrait.QuickLearner:
                    return 0.25f;
                case WorkerTrait.MoleHands:
                case WorkerTrait.Gearhead:
                    return 0.15f;
                case WorkerTrait.Anxious:
                    return 0.45f;
                case WorkerTrait.Gourmet:
                    return 0.20f;
                case WorkerTrait.Twinkletoes:
                    return 0.15f;
                case WorkerTrait.IronGut:
                    return -0.10f;
                default:
                    return 0f;
            }
        }

        private float WorkerMoraleTarget(Worker worker)
        {
            if (worker == null || !IsInside(worker.Cell.x, worker.Cell.y))
            {
                return BaseWorkerMorale;
            }

            float morale = BaseWorkerMorale;
            switch (RoomKindAt(worker.Cell.x, worker.Cell.y))
            {
                case RoomKind.Barracks:
                    morale += worker.Activity == "Sleeping" ? 1.45f : 0.65f;
                    break;
                case RoomKind.Bedroom:
                    morale += worker.Activity == "Sleeping" ? 2.05f : 1.05f;
                    break;
                case RoomKind.MessHall:
                    morale += 1.8f;
                    break;
                case RoomKind.GreatHall:
                    morale += 2.7f;
                    break;
                case RoomKind.Washroom:
                    morale += 0.7f;
                    break;
                case RoomKind.Clinic:
                    morale += worker.Sickness > 0f || worker.Health < 80f ? 0.8f : 0.35f;
                    break;
                case RoomKind.RecreationRoom:
                    morale += worker.Activity == "Relaxing" ? 2.2f : 1.25f;
                    break;
                case RoomKind.Stable:
                    morale += 0.25f;
                    break;
                case RoomKind.BasicRoom:
                    morale += 0.35f;
                    break;
            }

            float localDecor = DecorScoreAt(worker.Cell.x, worker.Cell.y);
            morale += localDecor * 3f;
            morale -= DrabDecorMoralePenalty(localDecor);
            if (worker.Calories > 2200f)
            {
                morale += 0.7f;
            }
            else if (worker.Calories > 1400f)
            {
                morale += 0.35f;
            }

            if (CountCells(CellKind.MessTable) >= workers.Count && food > 700f)
            {
                morale += foodFreshness >= 0.65f ? 0.65f : 0.35f;
                morale += Mathf.Lerp(0f, 0.75f, Mathf.InverseLerp(0.45f, ElectricGrillFoodQuality, foodQuality));
                if (worker.Trait == WorkerTrait.Gourmet)
                {
                    morale += foodQuality >= GourmetHighQualityThreshold
                        ? Mathf.Lerp(0.20f, 0.85f, Mathf.InverseLerp(GourmetHighQualityThreshold, PeppernutGrillFoodQuality, foodQuality))
                        : -Mathf.Lerp(0f, 0.45f, Mathf.InverseLerp(GourmetLowQualityThreshold, 0f, foodQuality));
                }
            }

            if (worker.Fatigue < 45f)
            {
                morale += 0.4f;
            }

            morale += WorkerOutfitMoraleBonus(worker);

            if (worker.AssignedJob != null && WorkerInterestMatchesJob(worker, worker.AssignedJob.Type))
            {
                morale += 0.45f;
            }

            if (worker.AssignedJob != null && WorkerRoleMatchesJob(worker, worker.AssignedJob.Type))
            {
                morale += WorkerRoleMoraleBonus(worker);
            }

            if (IsWorkerOverjoyed(worker))
            {
                morale += worker.OverjoyedResponse == WorkerOverjoyedResponse.DecorInspired ? 0.70f : 0.35f;
            }

            if (worker.GermExposure > 35f || worker.Sickness > 20f)
            {
                morale -= 0.55f;
            }

            if (worker.StressBreakSeconds > 0f)
            {
                morale -= 1f;
            }

            return Mathf.Clamp(morale, 0f, 10f);
        }

        private void UpdateWorkerOutfit(Worker worker, float localTemperature)
        {
            if (worker == null || worker.Health <= 0f || worker.SuitEquipped || worker.LeadSuitEquipped)
            {
                return;
            }

            WorkerOutfit desired = DesiredWorkerOutfit(worker, localTemperature);
            if (desired == WorkerOutfit.None || desired == worker.Outfit || !TryConsumeOutfitStock(desired))
            {
                return;
            }

            ReturnWorkerOutfit(worker.Outfit);
            worker.Outfit = desired;
            overlayDirty = true;
            Log(worker.Name + " equipped a " + WorkerOutfitName(desired) + ".");
        }

        private WorkerOutfit DesiredWorkerOutfit(Worker worker, float localTemperature)
        {
            if (localTemperature >= ThermalHeatStressTemperature - 2f)
            {
                return WorkerOutfit.CoolVest;
            }

            if (localTemperature <= ThermalColdStressTemperature + 2f)
            {
                return WorkerOutfit.WarmCoat;
            }

            return WorkerMoraleDeficit(worker) > 0.75f ? WorkerOutfit.SnazzySuit : WorkerOutfit.None;
        }

        private bool TryConsumeOutfitStock(WorkerOutfit outfit)
        {
            switch (outfit)
            {
                case WorkerOutfit.WarmCoat:
                    if (warmOutfits < 1f)
                    {
                        return false;
                    }

                    warmOutfits -= 1f;
                    return true;
                case WorkerOutfit.CoolVest:
                    if (coolOutfits < 1f)
                    {
                        return false;
                    }

                    coolOutfits -= 1f;
                    return true;
                case WorkerOutfit.SnazzySuit:
                    if (snazzySuits < 1f)
                    {
                        return false;
                    }

                    snazzySuits -= 1f;
                    return true;
                default:
                    return false;
            }
        }

        private void ReturnWorkerOutfit(WorkerOutfit outfit)
        {
            switch (outfit)
            {
                case WorkerOutfit.WarmCoat:
                    warmOutfits += 1f;
                    break;
                case WorkerOutfit.CoolVest:
                    coolOutfits += 1f;
                    break;
                case WorkerOutfit.SnazzySuit:
                    snazzySuits += 1f;
                    break;
            }
        }

        private float WorkerOutfitAdjustedTemperature(Worker worker, float localTemperature)
        {
            if (worker == null)
            {
                return localTemperature;
            }

            switch (worker.Outfit)
            {
                case WorkerOutfit.WarmCoat:
                    return localTemperature <= ThermalColdStressTemperature + WarmOutfitColdProtection
                        ? localTemperature + WarmOutfitColdProtection
                        : localTemperature;
                case WorkerOutfit.CoolVest:
                    return localTemperature >= ThermalHeatStressTemperature - CoolOutfitHeatProtection
                        ? localTemperature - CoolOutfitHeatProtection
                        : localTemperature;
                default:
                    return localTemperature;
            }
        }

        private float WorkerOutfitHeatProtection(Worker worker)
        {
            return worker != null && worker.Outfit == WorkerOutfit.CoolVest ? CoolOutfitHeatProtection : 0f;
        }

        private float WorkerOutfitColdProtection(Worker worker)
        {
            return worker != null && worker.Outfit == WorkerOutfit.WarmCoat ? WarmOutfitColdProtection : 0f;
        }

        private float WorkerOutfitMoraleBonus(Worker worker)
        {
            return worker != null && worker.Outfit == WorkerOutfit.SnazzySuit ? SnazzySuitMoraleBonus : 0f;
        }

        private string WorkerOutfitName(WorkerOutfit outfit)
        {
            switch (outfit)
            {
                case WorkerOutfit.WarmCoat:
                    return "warm coat";
                case WorkerOutfit.CoolVest:
                    return "cool vest";
                case WorkerOutfit.SnazzySuit:
                    return "snazzy suit";
                default:
                    return "no outfit";
            }
        }

        private string WorkerOutfitShortName(WorkerOutfit outfit)
        {
            switch (outfit)
            {
                case WorkerOutfit.WarmCoat:
                    return "Warm";
                case WorkerOutfit.CoolVest:
                    return "Cool";
                case WorkerOutfit.SnazzySuit:
                    return "Snazzy";
                default:
                    return "None";
            }
        }

        private float WorkerMoraleDeficit(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return 0f;
            }

            return Mathf.Max(0f, WorkerMoraleNeed(worker) - worker.Morale);
        }

        private float AverageWorkerMorale()
        {
            float total = 0f;
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f)
                {
                    continue;
                }

                total += Mathf.Clamp(worker.Morale, 0f, 10f);
                count++;
            }

            return count == 0 ? 0f : total / count;
        }

        private float AverageWorkerMoraleNeed()
        {
            float total = 0f;
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f)
                {
                    continue;
                }

                total += WorkerMoraleNeed(worker);
                count++;
            }

            return count == 0 ? BaseWorkerMorale : total / count;
        }

        private int CountLowMoraleWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (WorkerMoraleDeficit(worker) > 0.5f)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountLongCommuteWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && worker.CommuteSeconds >= LongCommuteSevereThresholdSeconds)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountSleepDisruptedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (SleepDisruptionFactor(worker) > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountNarcolepticNappers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && worker.NarcolepticNapSeconds > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private float MaxWorkerMoraleDeficit()
        {
            float maxDeficit = 0f;
            foreach (Worker worker in workers)
            {
                maxDeficit = Mathf.Max(maxDeficit, WorkerMoraleDeficit(worker));
            }

            return maxDeficit;
        }

        private string WorkerMoraleText(Worker worker)
        {
            float need = WorkerMoraleNeed(worker);
            float morale = Mathf.Clamp(worker == null ? BaseWorkerMorale : worker.Morale, 0f, 10f);
            float deficit = Mathf.Max(0f, need - morale);
            string text = "Morale " + morale.ToString("0.0") + "/" + need.ToString("0.0");
            if (deficit > 0.05f)
            {
                text += "  Deficit " + deficit.ToString("0.0");
            }
            else
            {
                text += "  Stable";
            }

            return text;
        }

        private float DecorScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float score = 0f;
            for (int dy = -DecorPlantRadius; dy <= DecorPlantRadius; dy++)
            {
                for (int dx = -DecorPlantRadius; dx <= DecorPlantRadius; dx++)
                {
                    int nx = x + dx;
                    int ny = y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > DecorPlantRadius || !IsInside(nx, ny))
                    {
                        continue;
                    }

                    if (cells[nx, ny] == CellKind.DecorPlant)
                    {
                        score += Mathf.Lerp(0.12f, 1f, 1f - distance / (float)(DecorPlantRadius + 1));
                    }
                    else if (cells[nx, ny] == CellKind.MessTable || cells[nx, ny] == CellKind.MassageTable || cells[nx, ny] == CellKind.WaterCooler || cells[nx, ny] == CellKind.ArcadeCabinet)
                    {
                        score += Mathf.Lerp(0.03f, 0.18f, 1f - distance / (float)(DecorPlantRadius + 1));
                    }
                }
            }

            for (int dy = -SculptingBlockRadius; dy <= SculptingBlockRadius; dy++)
            {
                for (int dx = -SculptingBlockRadius; dx <= SculptingBlockRadius; dx++)
                {
                    int nx = x + dx;
                    int ny = y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > SculptingBlockRadius ||
                        !IsInside(nx, ny) ||
                        cells[nx, ny] != CellKind.SculptingBlock ||
                        !sculptingBlockFinished[nx, ny])
                    {
                        continue;
                    }

                    score += Mathf.Lerp(0.16f, SculptingBlockDecorBonus, 1f - distance / (float)(SculptingBlockRadius + 1));
                }
            }

            score += PoweredCeilingLightScoreAt(x, y) * CeilingLightDecorBonus;
            score += ShineBugLightScoreAt(x, y) * ShineBugDecorBonus;
            score += DecorInspiredAuraScoreAt(x, y);
            score += OrbitalArtifactDecorScore();

            for (int dy = -HeavyWattWireDecorRadius; dy <= HeavyWattWireDecorRadius; dy++)
            {
                for (int dx = -HeavyWattWireDecorRadius; dx <= HeavyWattWireDecorRadius; dx++)
                {
                    int nx = x + dx;
                    int ny = y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > HeavyWattWireDecorRadius ||
                        !IsInside(nx, ny) ||
                        !powerWire[nx, ny] ||
                        powerWireKind[nx, ny] != PowerWireKind.HeavyWatt)
                    {
                        continue;
                    }

                    score -= Mathf.Lerp(0.04f, HeavyWattWireDecorPenalty, 1f - distance / (float)(HeavyWattWireDecorRadius + 1));
                }
            }

            return Mathf.Clamp01(score);
        }

        private float DecorInspiredAuraScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float score = 0f;
            foreach (Worker worker in workers)
            {
                if (!IsWorkerOverjoyed(worker) ||
                    worker.OverjoyedResponse != WorkerOverjoyedResponse.DecorInspired)
                {
                    continue;
                }

                int distance = Mathf.Abs(worker.Cell.x - x) + Mathf.Abs(worker.Cell.y - y);
                if (distance > DecorInspiredAuraRadius)
                {
                    continue;
                }

                score += Mathf.Lerp(0.04f, DecorInspiredAuraDecorBonus, 1f - distance / (float)(DecorInspiredAuraRadius + 1));
            }

            return Mathf.Clamp(score, 0f, DecorInspiredAuraDecorBonus * 1.8f);
        }

        private int CountFinishedSculptingBlocks()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.SculptingBlock && sculptingBlockFinished[x, y])
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsCellLit(int x, int y)
        {
            return PoweredCeilingLightScoreAt(x, y) > 0.01f || ShineBugLightScoreAt(x, y) > 0.01f;
        }

        private float PoweredCeilingLightScoreAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float score = 0f;
            for (int dy = -CeilingLightRadius; dy <= CeilingLightRadius; dy++)
            {
                for (int dx = -CeilingLightRadius; dx <= CeilingLightRadius; dx++)
                {
                    int nx = x + dx;
                    int ny = y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (distance > CeilingLightRadius || !IsPoweredCeilingLightAt(nx, ny))
                    {
                        continue;
                    }

                    score += Mathf.Lerp(0.10f, 1f, 1f - distance / (float)(CeilingLightRadius + 1));
                }
            }

            return Mathf.Clamp01(score);
        }

        private bool IsPoweredCeilingLightAt(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.CeilingLight &&
                CanPoweredMachineRun(new Vector2Int(x, y));
        }

        private float DecorStressReliefRate(float decorScore)
        {
            return Mathf.Lerp(0.25f, 1.25f, Mathf.Clamp01(decorScore));
        }

        private float DrabDecorSeverity(float decorScore)
        {
            return Mathf.Clamp01((DrabDecorThreshold - Mathf.Clamp01(decorScore)) / DrabDecorThreshold);
        }

        private float DrabDecorMoralePenalty(float decorScore)
        {
            return DrabDecorMoralePenaltyMax * DrabDecorSeverity(decorScore);
        }

        private float AverageWorkerDecor()
        {
            float total = 0f;
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f)
                {
                    continue;
                }

                total += DecorScoreAt(worker.Cell.x, worker.Cell.y);
                count++;
            }

            return count == 0 ? 0f : total / count;
        }

        private void EnsureRooms()
        {
            if (!roomsDirty)
            {
                return;
            }

            rooms.Clear();
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    roomIds[x, y] = -1;
                }
            }

            Queue<Vector2Int> queue = new Queue<Vector2Int>();
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (roomIds[x, y] >= 0 || !IsRoomInteriorCell(x, y))
                    {
                        continue;
                    }

                    RoomInfo room = new RoomInfo
                    {
                        Id = rooms.Count,
                        Enclosed = true
                    };
                    rooms.Add(room);
                    roomIds[x, y] = room.Id;
                    queue.Enqueue(new Vector2Int(x, y));

                    while (queue.Count > 0)
                    {
                        Vector2Int cell = queue.Dequeue();
                        AccumulateRoomCell(room, cell.x, cell.y);

                        AddRoomNeighbor(queue, room, cell.x + 1, cell.y);
                        AddRoomNeighbor(queue, room, cell.x - 1, cell.y);
                        AddRoomNeighbor(queue, room, cell.x, cell.y + 1);
                        AddRoomNeighbor(queue, room, cell.x, cell.y - 1);
                    }

                    if (room.Tiles > 0)
                    {
                        room.AverageOxygen /= room.Tiles;
                        room.AverageTemperature /= room.Tiles;
                    }

                    room.Kind = ClassifyRoom(room);
                }
            }

            roomsDirty = false;
        }

        private void AddRoomNeighbor(Queue<Vector2Int> queue, RoomInfo room, int x, int y)
        {
            if (!IsInside(x, y))
            {
                room.Enclosed = false;
                return;
            }

            if (!IsRoomInteriorCell(x, y) || roomIds[x, y] >= 0)
            {
                return;
            }

            roomIds[x, y] = room.Id;
            queue.Enqueue(new Vector2Int(x, y));
        }

        private void AccumulateRoomCell(RoomInfo room, int x, int y)
        {
            room.Tiles++;
            room.AverageOxygen += oxygen[x, y];
            room.AverageTemperature += temperature[x, y];

            switch (cells[x, y])
            {
                case CellKind.PowerControlStation:
                    room.PowerControlStations++;
                    break;
                case CellKind.Bed:
                    room.Beds++;
                    break;
                case CellKind.ComfyBed:
                    room.Beds++;
                    room.ComfyBeds++;
                    break;
                case CellKind.MessTable:
                    room.MessTables++;
                    break;
                case CellKind.Outhouse:
                case CellKind.Lavatory:
                case CellKind.Shower:
                    room.Outhouses++;
                    break;
                case CellKind.WashBasin:
                case CellKind.HandSanitizer:
                    room.WashBasins++;
                    break;
                case CellKind.MedicalCot:
                case CellKind.Apothecary:
                    room.MedicalCots++;
                    break;
                case CellKind.MassageTable:
                    room.MassageTables++;
                    break;
                case CellKind.WaterCooler:
                case CellKind.ArcadeCabinet:
                    room.RecreationFixtures++;
                    break;
                case CellKind.SkillScrubber:
                    room.RecreationFixtures++;
                    break;
                case CellKind.RationBox:
                case CellKind.StorageBin:
                    room.StorageBins++;
                    break;
                case CellKind.DecorPlant:
                case CellKind.CeilingLight:
                    room.DecorPlants++;
                    break;
                case CellKind.SculptingBlock:
                    if (sculptingBlockFinished[x, y])
                    {
                        room.DecorPlants++;
                    }

                    break;
                case CellKind.RanchingStation:
                case CellKind.Incubator:
                case CellKind.CritterFeeder:
                    room.RanchingStations++;
                    break;
            }

            if (IsRoomMachine(cells[x, y]))
            {
                room.MachineBuildings++;
                if (IsTunableGenerator(cells[x, y]))
                {
                    room.TunableGenerators++;
                }
            }
        }

        private bool IsRoomInteriorCell(int x, int y)
        {
            return IsInside(x, y) &&
                IsPassable(x, y) &&
                cells[x, y] != CellKind.ManualAirlock &&
                cells[x, y] != CellKind.MechanizedAirlock;
        }

