        private RoomKind ClassifyRoom(RoomInfo room)
        {
            if (!room.Enclosed || room.Tiles < 4 || room.Tiles > MaxRecognizedRoomTiles)
            {
                return RoomKind.OpenArea;
            }

            if (CountRoomCategories(room) > 1)
            {
                return RoomKind.MixedRoom;
            }

            if (room.Beds > 0)
            {
                return room.Beds <= 2 && (room.DecorPlants > 0 || room.ComfyBeds > 0) ? RoomKind.Bedroom : RoomKind.Barracks;
            }

            if (room.MessTables > 0)
            {
                return (room.DecorPlants > 0 || room.RecreationFixtures > 0) && room.Tiles >= 12 ? RoomKind.GreatHall : RoomKind.MessHall;
            }

            if (room.RanchingStations > 0)
            {
                return RoomKind.Stable;
            }

            if (room.Outhouses > 0 || room.WashBasins > 0)
            {
                return RoomKind.Washroom;
            }

            if (room.MedicalCots > 0)
            {
                return RoomKind.Clinic;
            }

            if (room.MassageTables > 0 || room.RecreationFixtures > 0 || room.DecorPlants >= 2)
            {
                return RoomKind.RecreationRoom;
            }

            if (room.MachineBuildings > 0)
            {
                if (room.PowerControlStations > 0 && room.TunableGenerators > 0)
                {
                    return RoomKind.PowerPlant;
                }

                return RoomKind.MachineRoom;
            }

            if (room.StorageBins > 0)
            {
                return RoomKind.StorageRoom;
            }

            return RoomKind.BasicRoom;
        }

        private int CountRoomCategories(RoomInfo room)
        {
            if (room == null)
            {
                return 0;
            }

            int categories = 0;
            if (room.Beds > 0)
            {
                categories++;
            }

            if (room.MessTables > 0)
            {
                categories++;
            }

            if (room.RanchingStations > 0)
            {
                categories++;
            }

            if (room.Outhouses > 0 || room.WashBasins > 0)
            {
                categories++;
            }

            if (room.MedicalCots > 0)
            {
                categories++;
            }

            if (room.MassageTables > 0 || (room.RecreationFixtures > 0 && room.MessTables == 0))
            {
                categories++;
            }

            if (room.MachineBuildings > 0)
            {
                categories++;
            }

            if (room.StorageBins > 0)
            {
                categories++;
            }

            return categories;
        }

        private RoomInfo RoomAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return null;
            }

            EnsureRooms();
            int id = roomIds[x, y];
            return id >= 0 && id < rooms.Count ? rooms[id] : null;
        }

        private RoomKind RoomKindAt(int x, int y)
        {
            RoomInfo room = RoomAt(x, y);
            return room == null ? RoomKind.None : room.Kind;
        }

        private int CountRoomsOfKind(RoomKind kind)
        {
            EnsureRooms();
            int count = 0;
            for (int i = 0; i < rooms.Count; i++)
            {
                if (rooms[i].Kind == kind)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountOvercrowdedStables()
        {
            EnsureRooms();
            int count = 0;
            for (int i = 0; i < rooms.Count; i++)
            {
                if (IsStableOvercrowded(rooms[i]))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountSleepingRooms()
        {
            EnsureRooms();
            int count = 0;
            for (int i = 0; i < rooms.Count; i++)
            {
                if (rooms[i].Kind == RoomKind.Barracks || rooms[i].Kind == RoomKind.Bedroom)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountDiningRooms()
        {
            EnsureRooms();
            int count = 0;
            for (int i = 0; i < rooms.Count; i++)
            {
                if (rooms[i].Kind == RoomKind.MessHall || rooms[i].Kind == RoomKind.GreatHall)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountCrittersInRoom(RoomInfo room)
        {
            if (room == null)
            {
                return 0;
            }

            EnsureRooms();
            int count = 0;
            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                if (hatch == null || !IsInside(hatch.Cell.x, hatch.Cell.y))
                {
                    continue;
                }

                if (roomIds[hatch.Cell.x, hatch.Cell.y] == room.Id)
                {
                    count++;
                }
            }

            return count;
        }

        private int StableCritterCapacity(RoomInfo room)
        {
            return room != null && room.Kind == RoomKind.Stable
                ? Mathf.Max(1, room.Tiles / StableTilesPerCritter)
                : 0;
        }

        private bool IsCritterSettledInStable(HatchCritter critter)
        {
            if (critter == null || !IsInside(critter.Cell.x, critter.Cell.y))
            {
                return false;
            }

            RoomInfo room = RoomAt(critter.Cell.x, critter.Cell.y);
            return room != null && room.Kind == RoomKind.Stable && !IsStableOvercrowded(room);
        }

        private bool TryFindWrangleDestination(HatchCritter critter, out Vector2Int destination)
        {
            destination = Vector2Int.zero;
            if (critter == null || !IsInside(critter.Cell.x, critter.Cell.y))
            {
                return false;
            }

            EnsureRooms();
            RoomInfo currentRoom = RoomAt(critter.Cell.x, critter.Cell.y);
            int bestScore = int.MaxValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    RoomInfo room = RoomAt(x, y);
                    if (room == null || room.Kind != RoomKind.Stable || !room.Enclosed)
                    {
                        continue;
                    }

                    bool sameRoom = currentRoom != null && currentRoom.Id == room.Id;
                    if (sameRoom && !IsStableOvercrowded(room))
                    {
                        continue;
                    }

                    int occupancyWithoutTarget = CountCrittersInRoom(room) - (sameRoom ? 1 : 0);
                    if (occupancyWithoutTarget >= StableCritterCapacity(room))
                    {
                        continue;
                    }

                    Vector2Int candidate = new Vector2Int(x, y);
                    if (candidate == critter.Cell || !CanCritterMoveTo(critter.Kind, candidate))
                    {
                        continue;
                    }

                    HatchCritter occupant = HatchAt(candidate);
                    if (occupant != null && occupant != critter)
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(candidate.x - critter.Cell.x) + Mathf.Abs(candidate.y - critter.Cell.y);
                    int score = distance + (sameRoom ? 1000 : 0);
                    if (score < bestScore)
                    {
                        bestScore = score;
                        destination = candidate;
                    }
                }
            }

            return bestScore < int.MaxValue;
        }

        private bool IsStableOvercrowded(RoomInfo room)
        {
            return room != null &&
                room.Kind == RoomKind.Stable &&
                CountCrittersInRoom(room) > StableCritterCapacity(room);
        }

        private bool IsStableOvercrowded(Vector2Int cell)
        {
            RoomInfo room = RoomAt(cell.x, cell.y);
            return IsStableOvercrowded(room);
        }

        private float StableCritterProductionMultiplier(Vector2Int cell, float stableBonus)
        {
            RoomInfo room = RoomAt(cell.x, cell.y);
            if (room == null || room.Kind != RoomKind.Stable)
            {
                return 1f;
            }

            return IsStableOvercrowded(room) ? StableOvercrowdedProductionMultiplier : stableBonus;
        }

        private string StableOccupancyText(Vector2Int cell)
        {
            RoomInfo room = RoomAt(cell.x, cell.y);
            if (room == null || room.Kind != RoomKind.Stable)
            {
                return string.Empty;
            }

            return "Stable occupancy " + CountCrittersInRoom(room) + "/" + StableCritterCapacity(room) + " critters.";
        }

        private string RoomSummary()
        {
            EnsureRooms();
            int barracks = 0;
            int bedrooms = 0;
            int messHalls = 0;
            int greatHalls = 0;
            int washrooms = 0;
            int clinics = 0;
            int recreation = 0;
            int stables = 0;
            int other = 0;
            for (int i = 0; i < rooms.Count; i++)
            {
                switch (rooms[i].Kind)
                {
                    case RoomKind.Barracks:
                        barracks++;
                        break;
                    case RoomKind.Bedroom:
                        bedrooms++;
                        break;
                    case RoomKind.MessHall:
                        messHalls++;
                        break;
                    case RoomKind.GreatHall:
                        greatHalls++;
                        break;
                    case RoomKind.Washroom:
                        washrooms++;
                        break;
                    case RoomKind.Clinic:
                        clinics++;
                        break;
                    case RoomKind.RecreationRoom:
                        recreation++;
                        break;
                    case RoomKind.Stable:
                        stables++;
                        break;
                    case RoomKind.BasicRoom:
                    case RoomKind.MachineRoom:
                    case RoomKind.PowerPlant:
                    case RoomKind.StorageRoom:
                    case RoomKind.MixedRoom:
                        other++;
                        break;
                }
            }

            return "B" + barracks + " Bd" + bedrooms + " M" + messHalls + " G" + greatHalls + " W" + washrooms + " C" + clinics + " R" + recreation + " S" + stables + " O" + other;
        }

        private float RoomPassiveStressReliefRate(int x, int y)
        {
            switch (RoomKindAt(x, y))
            {
                case RoomKind.Barracks:
                    return 0.30f;
                case RoomKind.Bedroom:
                    return 0.42f;
                case RoomKind.MessHall:
                    return 0.22f;
                case RoomKind.GreatHall:
                    return 0.36f;
                case RoomKind.Washroom:
                case RoomKind.Clinic:
                    return 0.18f;
                case RoomKind.RecreationRoom:
                    return 0.46f;
                case RoomKind.Stable:
                    return 0.08f;
                case RoomKind.BasicRoom:
                    return 0.12f;
                default:
                    return 0f;
            }
        }

        private bool HasMachineRoomBonus(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsRoomMachine(cells[cell.x, cell.y]) &&
                (RoomKindAt(cell.x, cell.y) == RoomKind.MachineRoom || RoomKindAt(cell.x, cell.y) == RoomKind.PowerPlant);
        }

        private bool HasPowerPlantBonus(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && RoomKindAt(cell.x, cell.y) == RoomKind.PowerPlant;
        }

        private float PowerPlantTuneUpDurationMultiplierAt(Vector2Int cell)
