        }

        private float MachineRoomHeatMultiplierAt(Vector2Int cell)
        {
            return HasMachineRoomBonus(cell) ? MachineRoomHeatMultiplier : 1f;
        }

        private float MachineRoomWearMultiplierAt(Vector2Int cell)
        {
            return HasMachineRoomBonus(cell) ? MachineRoomWearMultiplier : 1f;
        }

