        private string RoomDiagnosticText(RoomInfo room)
        {
            if (room == null)
            {
                return string.Empty;
            }

            StringBuilder builder = new StringBuilder(RoomContentSummaryText(room));
            string status = RoomDiagnosticStatusText(room);
            if (!string.IsNullOrEmpty(status))
            {
                builder.AppendLine();
                builder.Append(status);
            }

            return builder.ToString();
        }

        private string RoomContentSummaryText(RoomInfo room)
        {
            StringBuilder builder = new StringBuilder("Room contents:");
            bool hasContents = false;
            AppendRoomContent(builder, "  Beds ", room.Beds, ref hasContents);
            AppendRoomContent(builder, "  Tables ", room.MessTables, ref hasContents);
            AppendRoomContent(builder, "  Toilets ", room.Outhouses, ref hasContents);
            AppendRoomContent(builder, "  Wash ", room.WashBasins, ref hasContents);
            AppendRoomContent(builder, "  Med ", room.MedicalCots, ref hasContents);
            AppendRoomContent(builder, "  Rec ", room.MassageTables + room.RecreationFixtures, ref hasContents);
            AppendRoomContent(builder, "  Ranch ", room.RanchingStations, ref hasContents);
            AppendRoomContent(builder, "  Machines ", room.MachineBuildings, ref hasContents);
            AppendRoomContent(builder, "  Storage ", room.StorageBins, ref hasContents);
            AppendRoomContent(builder, "  Decor ", room.DecorPlants, ref hasContents);
            if (!hasContents)
            {
                builder.Append("  No specialty fixtures.");
            }

            builder.Append("  Categories ");
            builder.Append(CountRoomCategories(room));
            builder.Append(".");
            return builder.ToString();
        }

        private void AppendRoomContent(StringBuilder builder, string label, int count, ref bool hasContents)
        {
            if (count <= 0)
            {
                return;
            }

            builder.Append(label);
            builder.Append(count);
            hasContents = true;
        }

        private string RoomDiagnosticStatusText(RoomInfo room)
        {
            if (!room.Enclosed)
            {
                return "Room diagnostic: open boundary; seal with tiles or airlocks.";
            }

            if (room.Tiles < 4)
            {
                return "Room diagnostic: too small for room bonus.";
            }

            if (room.Tiles > MaxRecognizedRoomTiles)
            {
                return "Room diagnostic: too large for specialty bonus.";
            }

            if (CountRoomCategories(room) > 1)
            {
                return "Room diagnostic: mixed categories; split conflicting fixtures.";
            }

            if (room.Kind == RoomKind.Stable && IsStableOvercrowded(room))
            {
                return "Stable diagnostic: overcrowded; add room tiles or split critters.";
            }

            switch (room.Kind)
            {
                case RoomKind.Barracks:
                    return room.Beds > 2
                        ? "Bedroom upgrade: keep two or fewer beds and add decor or Comfy Beds."
                        : "Bedroom upgrade: add decor or Comfy Beds.";
                case RoomKind.MessHall:
                    if (room.Tiles < 12 && room.DecorPlants <= 0 && room.RecreationFixtures <= 0)
                    {
                        return "Great Hall upgrade: expand to at least 12 tiles and add decor or recreation.";
                    }

                    if (room.Tiles < 12)
                    {
                        return "Great Hall upgrade: expand to at least 12 tiles.";
                    }

                    return "Great Hall upgrade: add decor or a recreation fixture.";
                case RoomKind.Washroom:
                    return room.WashBasins > 0
                        ? "Room diagnostic: specialty bonus active."
                        : "Washroom upgrade: add a Wash Basin to lower sickness risk.";
                case RoomKind.MachineRoom:
                    return room.PowerControlStations > 0 && room.TunableGenerators > 0
                        ? "Room diagnostic: specialty bonus active."
                        : "Power Plant upgrade: add a Power Control Station and generator in one room.";
                case RoomKind.BasicRoom:
                    return "Room diagnostic: add a specialty fixture for a stronger room bonus.";
                case RoomKind.OpenArea:
                    return "Room diagnostic: add boundaries and fit size limits for a room bonus.";
                default:
                    return "Room diagnostic: specialty bonus active.";
            }
        }

        private void LogMiningResult(CellKind mined, string resourceName, float minedAmount, float droppedAmount)
        {
            string minedLabel = CellLabel(mined).ToLowerInvariant();
            if (string.IsNullOrEmpty(resourceName))
            {
                Log("Mined " + minedLabel + ".");
                return;
            }

            if (droppedAmount >= minedAmount - 0.01f)
            {
                Log("Mined " + minedLabel + ". Dropped " + droppedAmount.ToString("0.#") + " " + resourceName + " debris.");
                return;
            }

            Log("Mined " + minedLabel + ". Storage full; lost " + Mathf.Max(0f, minedAmount - droppedAmount).ToString("0.#") + " " + resourceName + ".");
        }

        private void CompleteBuild(Job job)
        {
            cells[job.Cell.x, job.Cell.y] = job.BuildKind;
            equipmentCondition[job.Cell.x, job.Cell.y] = DefaultEquipmentCondition(job.BuildKind);
            buildingDisabled[job.Cell.x, job.Cell.y] = false;
            constructionMaterialGrade[job.Cell.x, job.Cell.y] = ConstructionMaterialGradeForBuild(job);
            TryApplyCeramicInsulation(job.Cell);
            looseResourceKind[job.Cell.x, job.Cell.y] = LooseResourceKind.None;
            looseResourceAmount[job.Cell.x, job.Cell.y] = 0f;
            hatchEggAge[job.Cell.x, job.Cell.y] = 0f;
            incubatorEggLoaded[job.Cell.x, job.Cell.y] = false;
            incubatorEggProgress[job.Cell.x, job.Cell.y] = 0f;
            generatorTuneUpSeconds[job.Cell.x, job.Cell.y] = 0f;
            sculptingBlockFinished[job.Cell.x, job.Cell.y] = false;
            if (job.BuildKind == CellKind.ManualAirlock || job.BuildKind == CellKind.MechanizedAirlock)
            {
                airlockOpen[job.Cell.x, job.Cell.y] = true;
                doorAccessMode[job.Cell.x, job.Cell.y] = DoorAccessMode.Both;
            }

            if (!IsPassable(job.Cell.x, job.Cell.y))
            {
                oxygen[job.Cell.x, job.Cell.y] = 0f;
                carbonDioxide[job.Cell.x, job.Cell.y] = 0f;
                pollutedOxygen[job.Cell.x, job.Cell.y] = 0f;
                hydrogen[job.Cell.x, job.Cell.y] = 0f;
                chlorine[job.Cell.x, job.Cell.y] = 0f;
                naturalGas[job.Cell.x, job.Cell.y] = 0f;
                sourGas[job.Cell.x, job.Cell.y] = 0f;
                germs[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.Battery)
            {
                maxPower += techPowerRegulation ? 100f : 60f;
            }

            if (job.BuildKind == CellKind.JumboBattery)
            {
                maxPower += JumboBatteryCapacity;
            }

            if (job.BuildKind == CellKind.SmartBattery)
            {
                maxPower += SmartBatteryCapacity;
                smartBatteryLowThreshold[job.Cell.x, job.Cell.y] = SmartBatteryLowThreshold;
                smartBatteryHighThreshold[job.Cell.x, job.Cell.y] = SmartBatteryHighThreshold;
                smartBatterySignalState[job.Cell.x, job.Cell.y] = false;
            }

            if (IsCropKind(job.BuildKind))
            {
                plantGrowth[job.Cell.x, job.Cell.y] = 0f;
                cropTendedSeconds[job.Cell.x, job.Cell.y] = 0f;
                cropStress[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.SignalSwitch)
            {
                automationSwitchState[job.Cell.x, job.Cell.y] = false;
            }

            if (job.BuildKind == CellKind.AutomationBufferGate)
            {
                automationBufferHoldSeconds[job.Cell.x, job.Cell.y] = AutomationBufferHoldDefaultSeconds;
                automationBufferRemainingSeconds[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.AutomationFilterGate)
            {
                automationFilterDelaySeconds[job.Cell.x, job.Cell.y] = AutomationFilterDelayDefaultSeconds;
                automationFilterProgressSeconds[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.AutomationMemoryGate)
            {
                automationMemoryState[job.Cell.x, job.Cell.y] = false;
            }

            if (job.BuildKind == CellKind.AutomationCycleSensor)
            {
                automationCycleSensorStart[job.Cell.x, job.Cell.y] = AutomationCycleSensorDefaultStart;
                automationCycleSensorEnd[job.Cell.x, job.Cell.y] = AutomationCycleSensorDefaultEnd;
            }

            if (job.BuildKind == CellKind.AutomationTimerSensor)
            {
                automationTimerGreenSeconds[job.Cell.x, job.Cell.y] = AutomationTimerDefaultGreenSeconds;
                automationTimerRedSeconds[job.Cell.x, job.Cell.y] = AutomationTimerDefaultRedSeconds;
                automationTimerElapsedSeconds[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.StorageBin)
            {
                storageBinFilter[job.Cell.x, job.Cell.y] = StorageFilter.All;
                storageSweepOnly[job.Cell.x, job.Cell.y] = false;
            }

            if (job.BuildKind == CellKind.ConveyorLoader)
            {
                conveyorLoaderFilter[job.Cell.x, job.Cell.y] = StorageFilter.All;
            }

            if (job.BuildKind == CellKind.ConveyorReceptacle)
            {
                conveyorReceptacleFilter[job.Cell.x, job.Cell.y] = StorageFilter.All;
            }

            if (job.BuildKind == CellKind.ShippingRailSensor)
            {
                shippingRailSensorFilter[job.Cell.x, job.Cell.y] = StorageFilter.All;
            }

            if (job.BuildKind == CellKind.ShippingRailMeter)
            {
                shippingRailMeterFlowLimit[job.Cell.x, job.Cell.y] = ShippingRailMeterDefaultFlow;
                shippingRailMeterFlowRemaining[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.LiquidPipeSensor)
            {
                liquidSensorMode[job.Cell.x, job.Cell.y] = LiquidSensorMode.AnyLiquid;
            }

            if (job.BuildKind == CellKind.AtmoSensor)
            {
                atmoSensorThreshold[job.Cell.x, job.Cell.y] = AtmoSensorPressureThreshold;
                atmoSensorCondition[job.Cell.x, job.Cell.y] = ThresholdSensorCondition.AboveOrEqual;
            }

            if (job.BuildKind == CellKind.ThermoSensor)
            {
                thermoSensorThreshold[job.Cell.x, job.Cell.y] = ThermoSensorTemperatureThreshold;
                thermoSensorCondition[job.Cell.x, job.Cell.y] = ThresholdSensorCondition.AboveOrEqual;
            }

            if (job.BuildKind == CellKind.HydroSensor)
            {
                hydroSensorThreshold[job.Cell.x, job.Cell.y] = HydroSensorLiquidThreshold;
                hydroSensorCondition[job.Cell.x, job.Cell.y] = ThresholdSensorCondition.AboveOrEqual;
            }

            if (job.BuildKind == CellKind.GermSensor)
            {
                germSensorThreshold[job.Cell.x, job.Cell.y] = GermSensorThreshold;
                germSensorCondition[job.Cell.x, job.Cell.y] = ThresholdSensorCondition.AboveOrEqual;
            }

            if (job.BuildKind == CellKind.WeightPlate)
            {
                weightPlateThreshold[job.Cell.x, job.Cell.y] = WeightPlateThreshold;
                weightPlateCondition[job.Cell.x, job.Cell.y] = ThresholdSensorCondition.AboveOrEqual;
            }

            if (job.BuildKind == CellKind.CritterSensor)
            {
                critterSensorThreshold[job.Cell.x, job.Cell.y] = CritterSensorThreshold;
                critterSensorCondition[job.Cell.x, job.Cell.y] = ThresholdSensorCondition.AboveOrEqual;
            }

            if (job.BuildKind == CellKind.LiquidFilter)
            {
                liquidFilterMode[job.Cell.x, job.Cell.y] = LiquidFilterMode.PollutedWater;
            }

            if (job.BuildKind == CellKind.LiquidValve)
            {
                liquidValveFlowLimit[job.Cell.x, job.Cell.y] = LiquidValveMaxFlow;
                liquidValveFlowRemaining[job.Cell.x, job.Cell.y] = 0f;
            }

            if (job.BuildKind == CellKind.GasPipeSensor)
            {
                gasSensorMode[job.Cell.x, job.Cell.y] = GasSensorMode.AnyGas;
            }

            if (job.BuildKind == CellKind.GasFilter)
            {
                gasFilterMode[job.Cell.x, job.Cell.y] = GasFilterMode.CarbonDioxide;
            }

            if (job.BuildKind == CellKind.GasValve)
            {
                gasValveFlowLimit[job.Cell.x, job.Cell.y] = GasValveMaxFlow;
                gasValveFlowRemaining[job.Cell.x, job.Cell.y] = 0f;
            }

            if (IsDirectionalBridge(job.BuildKind))
            {
                bridgeDirection[job.Cell.x, job.Cell.y] = BridgeDirection.Right;
            }

            terrainDirty = true;
            InvalidateRooms();
            Log("Built " + CellLabel(job.BuildKind) + ".");
        }

        private void CompletePumpWater(Job job, Worker worker)
        {
            Vector2Int crudeSource = new Vector2Int(-1, -1);
            bool preferCrude = water >= 160f &&
                (CountCells(CellKind.OilRefinery) > 0 || CountCells(CellKind.PolymerPress) > 0) &&
                crudeOil < 240f &&
                TryFindAdjacentCrudeOil(job.Cell, out crudeSource);
            Vector2Int source = new Vector2Int(-1, -1);
            if (!preferCrude && !TryFindAdjacentWater(job.Cell, out source))
            {
                Log(worker.Name + " found no water to pump.");
                return;
            }

            if (preferCrude)
            {
                source = crudeSource;
            }

            float pumped = Mathf.Min(24f * WorkerJobOutputMultiplier(worker, job.Type), waterMass[source.x, source.y]);
            bool sourceIsCrude = IsCrudeOilWorldLiquidAt(source.x, source.y);
            bool sourceIsPetroleum = IsPetroleumWorldLiquidAt(source.x, source.y);
            bool pollutedSource = IsPollutedWorldLiquidAt(source.x, source.y);
            bool saltSource = IsSaltWaterWorldLiquidAt(source.x, source.y);
            waterMass[source.x, source.y] -= pumped;
            if (sourceIsCrude)
            {
                StoreCrudeOilInStorage(pumped);
                crudeOilPumped += pumped;
            }
            else if (sourceIsPetroleum)
            {
                StorePetroleumInStorage(pumped);
            }
            else if (saltSource)
            {
                StoreSaltWaterInStorage(pumped);
                saltWaterPumped += pumped;
            }
            else if (pollutedSource)
            {
                StorePollutedWaterInStorage(pumped, PollutedWaterSourceGermLevel(source));
                if (HasPollutedWaterVentNearby(source, 4))
                {
                    pollutedWaterVentPollutedWaterPumped += pumped;
                }
            }
            else
            {
                StoreCleanWaterInStorage(pumped, CleanWaterSourceGermLevel(source));
                currentCycleReport.WaterProduced += pumped;
                if (HasSteamVentNearby(source, 4))
                {
                    steamVentWaterPumped += pumped;
                }

                if (HasWaterGeyserNearby(source, 4))
                {
                    waterGeyserWaterPumped += pumped;
                }
            }

            WearEquipment(job.Cell, 0.012f);

            if (waterMass[source.x, source.y] <= 0.5f)
            {
                DryWaterCell(
                    source,
                    NeighborAverage(oxygen, source.x, source.y, 0.12f),
                    NeighborAverage(carbonDioxide, source.x, source.y, 0.04f),
                    pollutedSource && !sourceIsCrude && !saltSource ? 0.04f : NeighborAverage(pollutedOxygen, source.x, source.y, 0f),
                    NeighborAverage(hydrogen, source.x, source.y, 0f),
                    NeighborAverage(chlorine, source.x, source.y, 0f),
                    NeighborAverage(naturalGas, source.x, source.y, 0f),
                    pollutedSource && !sourceIsCrude && !saltSource ? 0.08f : NeighborAverage(germs, source.x, source.y, 0f),
                    temperature[source.x, source.y],
                    NeighborAverage(sourGas, source.x, source.y, 0f));
                terrainDirty = true;
                gasDirty = true;
                InvalidateRooms();
            }

            Log(worker.Name + " pumped " + pumped.ToString("0") + " kg " + (sourceIsCrude ? "crude oil." : sourceIsPetroleum ? "petroleum." : saltSource ? "salt water." : pollutedSource ? "polluted water." : "water."));
        }

        private void CompleteMop(Job job, Worker worker)
        {
            Vector2Int cell = job.Cell;
            if (!IsMoppableSpill(cell))
            {
                Log(worker.Name + " found no shallow spill to mop.");
                return;
            }

            float amount = Mathf.Min(waterMass[cell.x, cell.y], MoppableSpillMaxMass);
            float recovered = amount * MopRecoveryEfficiency * WorkerJobOutputMultiplier(worker, job.Type);
            bool crude = IsCrudeOilWorldLiquidAt(cell.x, cell.y);
            bool petroleumLiquid = IsPetroleumWorldLiquidAt(cell.x, cell.y);
            bool salt = IsSaltWaterWorldLiquidAt(cell.x, cell.y);
            bool polluted = IsPollutedMopCell(cell);
            if (crude)
            {
                StoreCrudeOilInStorage(recovered);
                crudeOilPumped += recovered;
            }
            else if (petroleumLiquid)
            {
                StorePetroleumInStorage(recovered);
            }
            else if (salt)
            {
                StoreSaltWaterInStorage(recovered);
                saltWaterPumped += recovered;
            }
            else if (polluted)
            {
                StorePollutedWaterInStorage(recovered, MoppedPollutedWaterGermLevel(cell));
                ReduceContaminationAround(cell, 1, 0.34f);
                AddGermyHands(worker, 28f, 3.5f);
            }
            else
            {
                StoreCleanWaterInStorage(recovered, CleanWaterSourceGermLevel(cell));
                currentCycleReport.WaterProduced += recovered;
            }

            moppedLiquid += amount;
            waterMass[cell.x, cell.y] = 0f;
            if (IsWorldLiquidCell(cells[cell.x, cell.y]))
            {
                cells[cell.x, cell.y] = CellKind.Empty;
                equipmentCondition[cell.x, cell.y] = 0f;
            }

            oxygen[cell.x, cell.y] = NeighborAverage(oxygen, cell.x, cell.y, 0.14f);
            carbonDioxide[cell.x, cell.y] = NeighborAverage(carbonDioxide, cell.x, cell.y, 0.04f);
            pollutedOxygen[cell.x, cell.y] = polluted && !crude ? NeighborAverage(pollutedOxygen, cell.x, cell.y, 0f) * 0.25f : NeighborAverage(pollutedOxygen, cell.x, cell.y, 0f);
            hydrogen[cell.x, cell.y] = NeighborAverage(hydrogen, cell.x, cell.y, 0f);
            chlorine[cell.x, cell.y] = NeighborAverage(chlorine, cell.x, cell.y, 0f);
            naturalGas[cell.x, cell.y] = NeighborAverage(naturalGas, cell.x, cell.y, 0f);
            sourGas[cell.x, cell.y] = NeighborAverage(sourGas, cell.x, cell.y, 0f);
            germs[cell.x, cell.y] = polluted && !crude ? Mathf.Clamp01(NeighborAverage(germs, cell.x, cell.y, 0f) * 0.2f) : Mathf.Clamp01(NeighborAverage(germs, cell.x, cell.y, 0f));

            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            InvalidateRooms();
            Log(worker.Name + " mopped " + amount.ToString("0") + " kg " + (crude ? "crude oil spill." : petroleumLiquid ? "petroleum spill." : polluted ? "polluted spill." : "spill water."));
        }

        private void CompleteDisinfect(Job job, Worker worker)
        {
            Vector2Int cell = job.Cell;
            if (!IsDisinfectableCell(cell))
            {
                Log(worker.Name + " found no germy tile to disinfect.");
                return;
            }

            float centerBefore = germs[cell.x, cell.y];
            float removed = DisinfectAreaAround(cell);
            disinfectionsCompleted++;
            disinfectedGerms += removed;
            if (worker != null)
            {
                worker.GermExposure = Mathf.Min(100f, worker.GermExposure + centerBefore * DisinfectWorkerExposure);
                AddGermyHands(worker, Mathf.Lerp(12f, 30f, Mathf.Clamp01(centerBefore)), centerBefore * 4f);
            }

            gasDirty = true;
            overlayDirty = true;
            Log(worker.Name + " disinfected a germy tile; removed " + Mathf.RoundToInt(removed * 100f) + "% contamination.");
        }

        private float DisinfectAreaAround(Vector2Int center)
        {
            float removed = 0f;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    if (Mathf.Abs(dx) + Mathf.Abs(dy) > 1)
                    {
                        continue;
                    }

                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y) || !IsPassable(x, y))
                    {
                        continue;
                    }

                    bool isCenter = dx == 0 && dy == 0;
                    float before = germs[x, y];
                    float germMultiplier = isCenter ? DisinfectCenterGermMultiplier : DisinfectAdjacentGermMultiplier;
                    float pollutedMultiplier = isCenter ? DisinfectCenterPollutedOxygenMultiplier : DisinfectAdjacentPollutedOxygenMultiplier;
                    germs[x, y] = Mathf.Clamp01(germs[x, y] * germMultiplier);
                    pollutedOxygen[x, y] = Mathf.Max(0f, pollutedOxygen[x, y] * pollutedMultiplier);
                    removed += Mathf.Max(0f, before - germs[x, y]);
                }
            }

            return removed;
        }

        private void CompleteEmptyBottle(Job job, Worker worker)
        {
            Vector2Int emptier = job.Cell;
            if (!CanEmptyBottleAt(emptier))
            {
                Log(worker.Name + " found no valid bottle emptying target.");
                return;
            }

            bool polluted = pollutedWater > 0.5f;
            float available = polluted ? pollutedWater : CleanWaterAvailableForBottleEmptier();
            if (available <= 0.01f)
            {
                Log(worker.Name + " found no bottled liquid to empty.");
                return;
            }

            if (!TryFindBottleEmptierOutput(emptier, out Vector2Int output))
            {
                Log("Bottle Emptier output is blocked or full.");
                return;
            }

            float amount = Mathf.Min(BottleEmptierPourAmount, available);
            amount = Mathf.Min(amount, 120f - waterMass[output.x, output.y]);
            if (amount <= 0.01f)
            {
                Log("Bottle Emptier output is full.");
                return;
            }

            if (polluted)
            {
                float emptiedPollutedGerms = pollutedWaterGerms;
                pollutedWater = Mathf.Max(0f, pollutedWater - amount);
                if (pollutedWater <= 0.001f)
                {
                    pollutedWaterGerms = 0f;
                }
                ReleasePollutedWaterToCell(output, amount, emptiedPollutedGerms);
                AddGermyHands(worker, 22f, 2.8f);
            }
            else
            {
                float emptiedGerms = waterGerms;
                water = Mathf.Max(0f, water - amount);
                if (water <= 0.001f)
                {
                    waterGerms = 0f;
                }

                ReleaseWaterToCell(output, amount, emptiedGerms);
            }

            bottleEmptiedLiquid += amount;
            milestoneBottleEmptying |= bottleEmptiedLiquid >= 12f;
            WearEquipment(emptier, 0.006f);
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            InvalidateRooms();
            Log(worker.Name + " emptied " + amount.ToString("0.#") + " kg " + (polluted ? "polluted water." : "water."));
        }

        private bool CanEmptyBottleAt(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.BottleEmptier &&
                CanUseEquipment(cell) &&
                HasStoredLiquidForBottleEmptier() &&
                TryFindBottleEmptierOutput(cell, out _);
        }

        private bool HasStoredLiquidForBottleEmptier()
        {
            return pollutedWater > 0.5f || CleanWaterAvailableForBottleEmptier() > 0.5f;
        }

        private float CleanWaterAvailableForBottleEmptier()
        {
            return Mathf.Max(0f, water - BottleEmptierCleanWaterReserve);
        }

        private bool TryFindBottleEmptierOutput(Vector2Int emptier, out Vector2Int output)
        {
            Vector2Int[] offsets =
            {
                new Vector2Int(0, -1),
                new Vector2Int(-1, 0),
                new Vector2Int(1, 0),
                new Vector2Int(0, 1)
            };

            foreach (Vector2Int offset in offsets)
            {
                Vector2Int candidate = new Vector2Int(emptier.x + offset.x, emptier.y + offset.y);
                if (!IsInside(candidate.x, candidate.y))
                {
                    continue;
                }

                if (CanLiquidOccupy(candidate.x, candidate.y) &&
                    LiquidFreeCapacity(candidate.x, candidate.y) > LiquidTileCapacity - 120f)
                {
                    output = candidate;
                    return true;
                }
            }

            output = default;
            return false;
        }

        private bool AnyBottleEmptierHasOutput()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.BottleEmptier &&
                        TryFindBottleEmptierOutput(new Vector2Int(x, y), out _))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private void ReduceContaminationAround(Vector2Int center, int radius, float multiplier)
        {
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    if (!IsInside(x, y))
                    {
                        continue;
                    }

                    pollutedOxygen[x, y] = Mathf.Max(0f, pollutedOxygen[x, y] * multiplier);
                    germs[x, y] = Mathf.Clamp01(germs[x, y] * multiplier);
                }
            }
        }

        private void CompleteRepair(Job job, Worker worker)
        {
            Vector2Int cell = job.Cell;
            if (!NeedsRepair(cell))
            {
                Log(worker.Name + " found no repair needed.");
                return;
            }

            if (metal < RepairMetalCost)
            {
                Log("Repair needs " + RepairMetalCost.ToString("0.#") + " kg metal.");
                return;
            }

            metal = Mathf.Max(0f, metal - RepairMetalCost);
            equipmentCondition[cell.x, cell.y] = 1f;
            repairsCompleted++;
            milestoneMaintenance = true;
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + " repaired " + CellLabel(cells[cell.x, cell.y]) + ".");
        }

        private void CompleteRescue(Job job, Worker rescuer)
        {
            Worker patient = FindWorkerByName(job.TargetWorkerName);
            if (!NeedsRescue(patient))
            {
                Log(rescuer.Name + " found no incapacitated duplicant to rescue.");
                return;
            }

            if (!TryFindRescueCot(patient, out Vector2Int cotCell))
            {
                Log("No Medical Cot available for rescue.");
                return;
            }

            ClearAssignment(patient);
            patient.Cell = cotCell;
            if (patient.Transform != null)
            {
                patient.Transform.position = CellCenter(cotCell);
            }

            patient.Health = 18f;
            patient.Fatigue = Mathf.Min(100f, Mathf.Max(patient.Fatigue, 82f));
            patient.Stress = Mathf.Min(100f, Mathf.Max(patient.Stress, 78f));
            patient.Calories = Mathf.Max(patient.Calories, 450f);
            patient.IncapacitatedSeconds = 0f;
            patient.Activity = "Recovering";
            rescuesCompleted++;
            milestoneEmergencyResponse = true;
            overlayDirty = true;
            gasDirty = true;
            Log(rescuer.Name + " rescued " + patient.Name + " to a Medical Cot.");

            if (NeedsTreatment(patient) && !HasTreatmentJobFor(patient.Name))
            {
                TryCreateTreatmentJob(patient);
            }
        }

        private bool TryFindRescueCot(Worker patient, out Vector2Int cotCell)
        {
            cotCell = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int candidate = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.MedicalCot || !CanUseEquipment(candidate) || !IsPassable(x, y) || IsMedicalCotReserved(candidate))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(patient.Cell.x - x) + Mathf.Abs(patient.Cell.y - y);
                    if (distance < bestDistance)
                    {
                        bestDistance = distance;
                        cotCell = candidate;
                    }
                }
            }

            if (cotCell.x >= 0)
            {
                return true;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int candidate = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.MedicalCot && CanUseEquipment(candidate) && IsPassable(x, y))
                    {
                        cotCell = candidate;
                        return true;
                    }
                }
            }

            return false;
        }

        private void CompleteTreatment(Job job, Worker worker)
        {
            float waterUsed = ConsumeCycleWater(3f, out float treatmentWaterGerms);
            RecordGermyWaterUse(treatmentWaterGerms);
            float clinicFactor = RoomKindAt(job.Cell.x, job.Cell.y) == RoomKind.Clinic ? 1.22f : 1f;
            bool usedMedicine = medicine >= MedicineTreatmentUse;
            if (usedMedicine)
            {
                medicine = Mathf.Max(0f, medicine - MedicineTreatmentUse);
                medicineUsed++;
            }

            float medicineFactor = usedMedicine ? MedicineTreatmentQualityBonus : 1f;
            float careQuality = (waterUsed >= 1f ? 1f : 0.55f) *
                clinicFactor *
                medicineFactor *
                WorkerJobOutputMultiplier(worker, job.Type) *
                CleanWaterHygieneQuality(treatmentWaterGerms);
            worker.GermExposure = Mathf.Max(0f, worker.GermExposure - 42f * careQuality);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + treatmentWaterGerms * 5f);
            worker.Sickness = Mathf.Max(0f, worker.Sickness - 34f * careQuality);
            worker.Health = Mathf.Min(100f, worker.Health + 22f * careQuality);
            worker.Stress = Mathf.Max(0f, worker.Stress - 14f);
            ClearRecoveredDisease(worker);
            Log(worker.Name + (usedMedicine ? " received medicine-assisted treatment." : " received treatment."));
        }

        private void CompleteMedicalRest(Job job, Worker worker)
        {
            if (NeedsTreatment(worker))
            {
                Log(worker.Name + " needs treatment after medical rest.");
                return;
            }

            if (IsFloorMedicalRestJob(job))
            {
                Log(worker.Name + " rested on the floor for recovery.");
                return;
            }

            Log(worker.Name + " finished medical rest.");
        }

        private void CompleteCatchBreath(Job job, Worker worker)
        {
            worker.Breath = Mathf.Max(worker.Breath, CatchBreathThreshold);
            worker.Stress = Mathf.Max(0f, worker.Stress - 2.5f);
            gasDirty = true;
            overlayDirty = true;
            Log(worker.Name + " caught breath.");
        }

        private void CompleteSeekSafety(Job job, Worker worker)
        {
            worker.HeatExposure = Mathf.Min(worker.HeatExposure, SafetyExposureReleaseThreshold);
            worker.ChillExposure = Mathf.Min(worker.ChillExposure, SafetyExposureReleaseThreshold);
            worker.Stress = Mathf.Max(0f, worker.Stress - 3.5f);
            gasDirty = true;
            overlayDirty = true;
            Log(worker.Name + " reached safety.");
        }

        private void CompleteToiletUse(Job job, Worker worker)
        {
            bool washroom = RoomKindAt(job.Cell.x, job.Cell.y) == RoomKind.Washroom;
            bool lavatory = IsInside(job.Cell.x, job.Cell.y) && cells[job.Cell.x, job.Cell.y] == CellKind.Lavatory;
            if (lavatory)
            {
                float waterUsed = ConsumeMachineWater(job.Cell, LavatoryWaterUse, out float lavatoryWaterGerms);
                if (waterUsed <= 0.05f)
                {
                    Log("Lavatory needs clean water.");
                    return;
                }

                float pollutedOutput = waterUsed * (LavatoryPollutedWaterOutput / LavatoryWaterUse);
                StorePollutedWater(job.Cell, pollutedOutput, FixturePollutedWaterGermLevel(job.Cell, worker, lavatoryWaterGerms, washroom ? 0.42f : 0.54f));
                RecordGermyWaterUse(lavatoryWaterGerms);
                lavatoryUses++;
                lavatoryWaterUsed += waterUsed;
                lavatoryPollutedWaterProduced += pollutedOutput;
                worker.Bladder = 0f;
                worker.Stress = Mathf.Max(0f, worker.Stress - (washroom ? 10f : 7f));
                worker.GermExposure = Mathf.Min(100f, worker.GermExposure + (washroom ? 3f : 5f));
                AddGermyHands(worker, washroom ? 32f : 42f, washroom ? 1.5f : 2.5f);
                germs[job.Cell.x, job.Cell.y] = Mathf.Clamp01(germs[job.Cell.x, job.Cell.y] + 0.04f);
                pollutedOxygen[job.Cell.x, job.Cell.y] = Mathf.Min(1.8f, pollutedOxygen[job.Cell.x, job.Cell.y] + 0.035f);
                WearEquipment(job.Cell, 0.007f);
                gasDirty = true;
                overlayDirty = true;
                Log(worker.Name + " used the lavatory. Polluted water entered plumbing.");
                if (NeedsHandWash(worker) && !HasWashHandsJobFor(worker.Name))
                {
                    TryCreateWashHandsJob(worker);
                }

                return;
            }

            worker.Bladder = 0f;
            worker.Stress = Mathf.Max(0f, worker.Stress - (washroom ? 8f : 5f));
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + (washroom ? 8f : 14f));
            AddGermyHands(worker, washroom ? 46f : 58f, washroom ? 3f : 6f);
            if (IsInside(job.Cell.x, job.Cell.y))
            {
                pollutedOxygen[job.Cell.x, job.Cell.y] = Mathf.Min(1.8f, pollutedOxygen[job.Cell.x, job.Cell.y] + (washroom ? 0.10f : 0.18f));
                germs[job.Cell.x, job.Cell.y] = Mathf.Clamp01(germs[job.Cell.x, job.Cell.y] + (washroom ? 0.08f : 0.16f));
                AddPollutedDirt(3.5f, job.Cell);
                gasDirty = true;
                overlayDirty = true;
            }

            Log(worker.Name + " used the outhouse. Polluted dirt accumulated.");
            if (NeedsHandWash(worker) && !HasWashHandsJobFor(worker.Name))
            {
                TryCreateWashHandsJob(worker);
            }
        }

        private void CompleteWashHands(Job job, Worker worker)
        {
            if (IsInside(job.Cell.x, job.Cell.y) && cells[job.Cell.x, job.Cell.y] == CellKind.HandSanitizer)
            {
                if (bleachStone < HandSanitizerBleachStoneUse)
                {
                    Log("Hand Sanitizer needs bleach stone.");
                    return;
                }

                bleachStone = Mathf.Max(0f, bleachStone - HandSanitizerBleachStoneUse);
                handSanitizerBleachStoneUsed += HandSanitizerBleachStoneUse;
                worker.GermExposure = Mathf.Max(0f, worker.GermExposure - HandSanitizerGermReduction);
                worker.Sickness = Mathf.Max(0f, worker.Sickness - 7f);
                worker.Stress = Mathf.Max(0f, worker.Stress - 1.0f);
                CleanGermyHands(worker, 1f);
                MarkFoodSafeHands(worker, 1f);
                ClearRecoveredDisease(worker);
                germs[job.Cell.x, job.Cell.y] = Mathf.Clamp01(germs[job.Cell.x, job.Cell.y] * 0.10f);
                pollutedOxygen[job.Cell.x, job.Cell.y] = Mathf.Max(0f, pollutedOxygen[job.Cell.x, job.Cell.y] - 0.03f);
                WearEquipment(job.Cell, 0.0045f);
                handsWashed++;
                handSanitizerUses++;
                milestoneHygiene |= worker.GermExposure <= 30f;
                milestoneHandSanitizer |= handSanitizerUses > 0 && handSanitizerBleachStoneUsed >= HandSanitizerBleachStoneUse && worker.GermExposure <= 30f;
                gasDirty = true;
                overlayDirty = true;
                Log(worker.Name + " sanitized hands with bleach stone.");
                return;
            }

            float waterUsed = ConsumeMachineWater(job.Cell, WashBasinWaterUse, out float washWaterGerms);
            if (waterUsed <= 0.05f)
            {
                Log("Wash Basin needs clean water.");
                return;
            }

            float handGermsBefore = worker.GermExposure;
            StorePollutedWater(job.Cell, waterUsed * WashBasinPollutedWaterOutput, FixturePollutedWaterGermLevel(job.Cell, worker, washWaterGerms, Mathf.Lerp(0.18f, 0.72f, Mathf.Clamp01(handGermsBefore / 100f))));
            RecordGermyWaterUse(washWaterGerms);
            float washQuality = Mathf.Clamp01(waterUsed / WashBasinWaterUse) * CleanWaterHygieneQuality(washWaterGerms);
            worker.GermExposure = Mathf.Max(0f, worker.GermExposure - WashBasinGermReduction * washQuality);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + washWaterGerms * 7f);
            worker.Sickness = Mathf.Max(0f, worker.Sickness - 5f * washQuality);
            worker.Stress = Mathf.Max(0f, worker.Stress - 1.5f);
            CleanGermyHands(worker, washQuality);
            MarkFoodSafeHands(worker, washQuality);
            ClearRecoveredDisease(worker);
            if (IsInside(job.Cell.x, job.Cell.y))
            {
                germs[job.Cell.x, job.Cell.y] = Mathf.Clamp01(germs[job.Cell.x, job.Cell.y] * 0.25f);
                pollutedOxygen[job.Cell.x, job.Cell.y] = Mathf.Max(0f, pollutedOxygen[job.Cell.x, job.Cell.y] - 0.06f * washQuality);
                WearEquipment(job.Cell, 0.006f);
                gasDirty = true;
                overlayDirty = true;
            }

            handsWashed++;
            milestoneHygiene |= worker.GermExposure <= 30f;
            Log(worker.Name + " washed hands at the Wash Basin.");
        }

        private void CompleteShower(Job job, Worker worker)
        {
            float waterUsed = ConsumeMachineWater(job.Cell, ShowerWaterUse, out float showerWaterGerms);
            if (waterUsed <= 0.05f)
            {
                Log("Shower needs clean water.");
                return;
            }

            float pollutedOutput = waterUsed * (ShowerPollutedWaterOutput / ShowerWaterUse);
            RecordGermyWaterUse(showerWaterGerms);
            float showerQuality = Mathf.Clamp01(waterUsed / ShowerWaterUse) * CleanWaterHygieneQuality(showerWaterGerms);
            float showerGermsBefore = worker.GermExposure;
            StorePollutedWater(job.Cell, pollutedOutput, FixturePollutedWaterGermLevel(job.Cell, worker, showerWaterGerms, Mathf.Lerp(0.12f, 0.58f, Mathf.Clamp01(showerGermsBefore / 100f))));
            worker.GermExposure = Mathf.Max(0f, worker.GermExposure - ShowerGermReduction * showerQuality);
            worker.GermExposure = Mathf.Min(100f, worker.GermExposure + showerWaterGerms * 4f);
            worker.Sickness = Mathf.Max(0f, worker.Sickness - 8f * showerQuality);
            worker.Stress = Mathf.Max(0f, worker.Stress - ShowerStressRelief * showerQuality);
            worker.Morale = Mathf.Min(10f, worker.Morale + 0.35f * showerQuality);
            CleanGermyHands(worker, Mathf.Min(1f, showerQuality * 1.15f));
            MarkFoodSafeHands(worker, Mathf.Min(1f, showerQuality * 1.15f));
            ClearRecoveredDisease(worker);
            if (IsInside(job.Cell.x, job.Cell.y))
            {
                germs[job.Cell.x, job.Cell.y] = Mathf.Clamp01(germs[job.Cell.x, job.Cell.y] * 0.20f);
                pollutedOxygen[job.Cell.x, job.Cell.y] = Mathf.Max(0f, pollutedOxygen[job.Cell.x, job.Cell.y] - 0.04f * showerQuality);
                WearEquipment(job.Cell, 0.008f);
                gasDirty = true;
                overlayDirty = true;
            }

            showersTaken++;
            showerWaterUsed += waterUsed;
            showerPollutedWaterProduced += pollutedOutput;
            milestoneHygiene |= worker.GermExposure <= 30f;
            Log(worker.Name + " took a shower. Polluted water entered plumbing.");
        }

        private void CompleteRelaxation(Job job, Worker worker)
        {
            RoomKind roomKind = RoomKindAt(job.Cell.x, job.Cell.y);
            bool recreationRoom = roomKind == RoomKind.RecreationRoom;
            bool greatHall = roomKind == RoomKind.GreatHall;
            if (IsTakeBreakJob(job))
            {
                worker.Stress = Mathf.Min(worker.Stress, TakeBreakStressCapAt(job.Cell));
                worker.Morale = Mathf.Min(10f, worker.Morale + ((recreationRoom || greatHall) ? TakeBreakMoraleGain : TakeBreakMoraleGain * 0.45f));
                Log(worker.Name + " took a short break.");
                return;
            }

            if (IsInside(job.Cell.x, job.Cell.y) && cells[job.Cell.x, job.Cell.y] == CellKind.WaterCooler)
            {
                float waterUsed = ConsumeMachineWater(job.Cell, WaterCoolerWaterUse, out float coolerWaterGerms);
                if (waterUsed <= 0.05f)
                {
                    Log("Water Cooler needs clean water.");
                    return;
                }

                RecordGermyWaterUse(coolerWaterGerms);
                float waterQuality = Mathf.Clamp01(waterUsed / WaterCoolerWaterUse) * CleanWaterHygieneQuality(coolerWaterGerms);
                waterCoolerVisits++;
                waterCoolerWaterUsed += waterUsed;
                worker.GermExposure = Mathf.Min(100f, worker.GermExposure + coolerWaterGerms * 6f);
                worker.Stress = Mathf.Min(worker.Stress, WaterCoolerStressCap - (recreationRoom || greatHall ? 4f : 0f));
                worker.Morale = Mathf.Min(10f, worker.Morale + WaterCoolerMoraleGain * waterQuality * (recreationRoom || greatHall ? 1.35f : 1f));
                WearEquipment(job.Cell, 0.004f);
                Log(worker.Name + " took a break at the Water Cooler.");
                return;
            }

            if (IsInside(job.Cell.x, job.Cell.y) && cells[job.Cell.x, job.Cell.y] == CellKind.ArcadeCabinet)
            {
                if (!CanPoweredMachineRun(job.Cell))
                {
                    Log("Arcade Cabinet needs power and green automation.");
                    return;
                }

                if (plastic < ArcadeCabinetPlasticUse)
                {
                    Log("Arcade Cabinet needs plastic replacement parts.");
                    return;
                }

                plastic = Mathf.Max(0f, plastic - ArcadeCabinetPlasticUse);
                arcadePlasticUsed += ArcadeCabinetPlasticUse;
                arcadeSessions++;
                ConsumeCyclePower(ArcadeCabinetPowerRate * 2.2f);
                AddHeat(job.Cell, ArcadeCabinetHeatRate, 1);
                WearEquipment(job.Cell, 0.006f);
                worker.Stress = Mathf.Min(worker.Stress, ArcadeCabinetStressCap - (recreationRoom || greatHall ? 3f : 0f));
                worker.Morale = Mathf.Min(10f, worker.Morale + ArcadeCabinetMoraleGain * (recreationRoom || greatHall ? 1.25f : 1f));
                worker.Fatigue = Mathf.Max(0f, worker.Fatigue - 1.5f);
                terrainDirty = true;
                overlayDirty = true;
                Log(worker.Name + " played the Arcade Cabinet.");
                return;
            }

            worker.Stress = Mathf.Min(worker.Stress, recreationRoom ? 22f : 30f);
            worker.Morale = Mathf.Min(10f, worker.Morale + (recreationRoom ? 1.2f : 0.8f));
            Log(worker.Name + " finished stress relief.");
        }

        private void CompleteSkillScrub(Job job, Worker worker)
        {
            if (!CanUseSkillScrubberAt(job.Cell))
            {
                Log("Skill Scrubber needs power and usable equipment.");
                return;
            }

            if (worker == null || WorkerSkillLevel(worker) <= 1)
            {
                Log("Skill Scrubber target has no skills to scrub.");
                return;
            }

            int oldLevel = WorkerSkillLevel(worker);
            float oldNeed = WorkerMoraleNeed(worker);
            ConsumeCyclePower(SkillScrubberPowerRate * 4f);
            worker.Experience = 0f;
            worker.Role = worker.Interest;
            worker.Stress = Mathf.Max(0f, worker.Stress - SkillScrubberStressRelief);
            worker.Morale = Mathf.Max(worker.Morale, BaseWorkerMorale);
            worker.WorkSpeed = WorkerSkillSpeedMultiplier(worker);
            worker.OverjoyedSeconds = 0f;
            skillScrubsCompleted++;
            WearEquipment(job.Cell, 0.010f);
            AddHeat(job.Cell, 0.45f, 1);
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + " used the Skill Scrubber. Skill Lv " + oldLevel + " reset to 1; morale need " + oldNeed.ToString("0.0") + " -> " + WorkerMoraleNeed(worker).ToString("0.0") + ".");
        }

        private void CompleteEat(Job job, Worker worker)
        {
            bool seated = !IsFloorEatJob(job);
            if (!EatStoredFood(worker, seated))
            {
                Log(seated ? worker.Name + " found no food at the Mess Table." : worker.Name + " found no food for a floor meal.");
            }
        }

        private void CompleteCompost(Job job, Worker worker)
        {
            string workerName = worker != null ? worker.Name : "A duplicant";
            float processed = ConsumePollutedDirtForCompost(job.Cell, Mathf.Min(CompostablePollutedDirt(), 8f));
            if (processed <= 0.01f)
            {
                Log(workerName + " found no polluted dirt to compost.");
                return;
            }

            float recovered = StoreDryResource(ref dirt, processed * 0.78f);
            compostedPollutedDirt += processed;
            VentPollutedOxygen(job.Cell, 0.04f, 0.08f);
            AddHeat(job.Cell, 0.35f, 1);
            Log(workerName + " composted " + processed.ToString("0.#") + " kg polluted dirt into " + recovered.ToString("0.#") + " kg dirt.");
        }

        private string CompostReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.Compost)
            {
                return "Compost blocked: compost station missing.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Compost blocked: compost station needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Compost blocked: compost station is submerged.";
            }

            if (CompostablePollutedDirt() < 4f)
            {
                return "Compost blocked: needs polluted dirt.";
            }

            Job compostJob = FindJobAt(cell, JobType.Compost);
            if (compostJob != null)
            {
                return "Compost ready: compost errand queued. " + JobReachabilityText(compostJob);
            }

            Job testJob = new Job(JobType.Compost, cell, 3.1f)
            {
                Priority = CompostablePollutedDirt() > 28f ? 7 : 5
            };
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Compost blocked: ",
                "Compost blocked: no reachable duplicant path to station.");
            return string.IsNullOrEmpty(routeBlock) ? "Compost ready: can process polluted dirt." : routeBlock;
        }

        private void CompleteGroomHatch(Job job, Worker worker)
        {
            HatchCritter hatch = FindGroomableHatch(job.Cell);
            if (hatch == null)
            {
                Log(worker.Name + " found no critter ready for grooming.");
                return;
            }

            bool stable = RoomKindAt(job.Cell.x, job.Cell.y) == RoomKind.Stable;
            int masteryTier = WorkerRoleMasteryTier(worker);
            float groomingMultiplier = WorkerJobOutputMultiplier(worker, job.Type);
            hatch.GroomedSeconds = HatchGroomedSeconds * (stable ? StableGroomedSecondsMultiplier : 1f) * groomingMultiplier;
            hatch.Happiness = Mathf.Max(hatch.Happiness, (stable ? 86f : 78f) + masteryTier * 1.5f);
            hatchesGroomed++;
            worker.Stress = Mathf.Max(0f, worker.Stress - (stable ? 4.5f : 3f) * groomingMultiplier);
            string output = hatch.Kind == CritterKind.Slickster
                ? "Slickster crude output improved."
                : hatch.Kind == CritterKind.MoltenSlickster
                    ? "Molten slickster petroleum output improved."
                    : hatch.Kind == CritterKind.Drecko
                        ? "Drecko plastic output improved."
                    : hatch.Kind == CritterKind.Puft
                        ? "Puft slime output improved."
                        : hatch.Kind == CritterKind.Morb
                            ? "Morb emissions temporarily reduced."
                            : hatch.Kind == CritterKind.Pacu
                                ? "Pacu seafood output improved."
                            : hatch.Kind == CritterKind.ShineBug
                                ? "Shine bug glow output improved."
                                : hatch.Kind == CritterKind.Pip
                                    ? "Pip planting and dirt output improved."
                                    : hatch.Kind == CritterKind.PlugSlug
                                        ? "Plug slug power output improved."
                                        : hatch.Kind == CritterKind.GassyMoo
                                            ? "Gassy moo natural gas output improved."
                                            : hatch.Kind == CritterKind.Beeta
                                                ? "Beeta radiation gathering improved."
                                                : hatch.Kind == CritterKind.Grubgrub
                                                    ? "Grubgrub crop tending improved."
                                                    : hatch.Kind == CritterKind.Sweetle
                                                        ? "Sweetle sulfur tending improved."
                                                        : hatch.Kind == CritterKind.CuddlePip
                                                            ? "Cuddle pip incubation care improved."
                                                            : hatch.Kind == CritterKind.ShoveVole ? "Shove vole regolith clearing improved." : "Hatch coal output improved.";
            Log(worker.Name + " groomed " + hatch.Name + (stable ? " in a Stable. " : ". ") + output);
        }

        private void CompleteWrangleCritter(Job job, Worker worker)
        {
            HatchCritter critter = WrangleTargetForJob(job);
            if (critter == null)
            {
                Log(worker.Name + " found no wrangle target.");
                return;
            }

            if (!TryFindWrangleDestination(critter, out Vector2Int destination))
            {
                Log(worker.Name + " found no open Stable destination.");
                return;
            }

            string critterLabel = CritterKindName(critter.Kind) + " " + critter.Name;
            critter.Cell = destination;
            critter.TargetCell = destination;
            critter.MoveTimer = HatchMoveIntervalSeconds;
            if (critter.Transform != null)
            {
                critter.Transform.position = CellCenter(destination);
            }

            critter.Happiness = Mathf.Max(critter.Happiness, 38f);
            worker.Stress = Mathf.Min(100f, worker.Stress + 0.8f);
            InvalidateRooms();
            terrainDirty = true;
            overlayDirty = true;
            Log(worker.Name + " wrangled " + critterLabel + " to a Stable.");
        }

        private void CompleteButcherCritter(Job job, Worker worker)
        {
            HatchCritter critter = ButcherTargetForJob(job);
            if (critter == null)
            {
                Log(worker.Name + " found no butcher target.");
                return;
            }

            Vector2Int cell = critter.Cell;
            CritterKind kind = critter.Kind;
            string critterLabel = CritterKindName(kind) + " " + critter.Name;
            float foodProduced = CritterButcherFoodYield(kind) * WorkerJobOutputMultiplier(worker, job.Type);
            float foodQualityProduced = Mathf.Clamp01(CritterButcherFoodQualityFor(kind) + WorkerRoleFoodQualityBonus(worker, job.Type));
            float contamination = FoodHandlingContaminationAt(cell, worker) * 0.35f;
            if (IsInside(cell.x, cell.y))
            {
                contamination += Mathf.Clamp01(germs[cell.x, cell.y]) * 0.08f;
            }

            AddFreshFood(foodProduced, CritterButcherFreshnessFor(kind), foodQualityProduced, true, contamination);
            if (kind == CritterKind.Pacu)
            {
                pacuSeafoodProduced += foodProduced;
            }

            RemoveCritter(critter);
            InvalidateRooms();
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            Log(worker.Name + " butchered " + critterLabel + ". Food +" + foodProduced.ToString("0") + " kcal.");
        }

        private float CritterButcherFoodYield(CritterKind kind)
        {
            switch (kind)
            {
                case CritterKind.Hatch:
                    return HatchButcherFoodYield;
                case CritterKind.Slickster:
                case CritterKind.MoltenSlickster:
                case CritterKind.Drecko:
                    return LargeCritterButcherFoodYield;
                case CritterKind.Puft:
                case CritterKind.PlugSlug:
                case CritterKind.GassyMoo:
                case CritterKind.Grubgrub:
                case CritterKind.Sweetle:
                case CritterKind.CuddlePip:
                case CritterKind.ShoveVole:
                    return MediumCritterButcherFoodYield;
                case CritterKind.Morb:
                    return MorbButcherFoodYield;
                case CritterKind.Pacu:
                    return PacuSeafoodYield;
                case CritterKind.ShineBug:
                case CritterKind.Beeta:
                    return ShineBugButcherFoodYield;
                default:
                    return MediumCritterButcherFoodYield;
            }
        }

        private float CritterButcherFreshnessFor(CritterKind kind)
        {
            return kind == CritterKind.Pacu ? PacuSeafoodFreshness : kind == CritterKind.Morb ? 0.70f : CritterButcherFoodFreshness;
        }

        private float CritterButcherFoodQualityFor(CritterKind kind)
        {
            return kind == CritterKind.Pacu ? PacuSeafoodQuality : kind == CritterKind.Morb || kind == CritterKind.ShineBug || kind == CritterKind.Beeta ? 0.32f : CritterButcherFoodQuality;
        }

        private void RemoveCritter(HatchCritter critter)
        {
            if (critter == null)
            {
                return;
            }

            if (critter.Transform != null)
            {
                DestroyRuntimeObject(critter.Transform.gameObject);
            }

            hatches.Remove(critter);
        }

        private void AddFreshFood(float amount, float freshness)
        {
            AddFreshFood(amount, freshness, DefaultFoodQuality, true, 0f);
        }

        private void AddFreshFood(float amount, float freshness, float quality)
        {
            AddFreshFood(amount, freshness, quality, true, 0f);
        }

        private void AddFreshFood(float amount, float freshness, float quality, bool countAsProduced)
        {
            AddFreshFood(amount, freshness, quality, countAsProduced, 0f);
        }

        private void AddFreshFood(float amount, float freshness, float quality, bool countAsProduced, float contamination)
        {
            if (amount <= 0f)
            {
                return;
            }

            float totalFood = food + amount;
            foodFreshness = totalFood <= 0f
                ? Mathf.Clamp01(freshness)
                : Mathf.Clamp01((foodFreshness * food + Mathf.Clamp01(freshness) * amount) / totalFood);
            foodQuality = totalFood <= 0f
                ? Mathf.Clamp01(quality)
                : Mathf.Clamp01((foodQuality * food + Mathf.Clamp01(quality) * amount) / totalFood);
            foodGerms = totalFood <= 0f
                ? Mathf.Clamp01(contamination)
                : Mathf.Clamp01((foodGerms * food + Mathf.Clamp01(contamination) * amount) / totalFood);
            food = totalFood;
            if (countAsProduced)
            {
                currentCycleReport.FoodProduced += amount;
            }
        }

        private float NeighborAverage(float[,] gas, int x, int y, float fallback)
        {
            float total = 0f;
            int count = 0;
            for (int dy = -1; dy <= 1; dy++)
            {
                for (int dx = -1; dx <= 1; dx++)
                {
                    if (Mathf.Abs(dx) + Mathf.Abs(dy) != 1)
                    {
                        continue;
                    }

                    int nx = x + dx;
                    int ny = y + dy;
                    if (IsInside(nx, ny) && IsPassable(nx, ny))
                    {
                        total += gas[nx, ny];
                        count++;
                    }
                }
            }

            return count == 0 ? fallback : total / count;
        }

        private void ClearAssignment(Worker worker)
        {
            if (worker.AssignedJob != null && worker.AssignedJob.AssignedWorker == worker)
            {
                worker.AssignedJob.AssignedWorker = null;
            }

            worker.AssignedJob = null;
            worker.Path.Clear();
            worker.PathIndex = 0;
            worker.Activity = "Idle";
        }

        private bool TryFindPathToJob(Vector2Int start, Job job, out List<Vector2Int> path)
        {
            List<Vector2Int> targets = GetWorkPositions(job);
            return TryFindPath(start, targets, out path);
        }

        private bool TryFindPathToJob(Vector2Int start, Worker worker, Job job, out List<Vector2Int> path)
        {
            List<Vector2Int> targets = GetWorkPositions(job);
            return TryFindPathForJob(start, targets, worker, job, out path);
        }

        private bool TryFindPathToJobIgnoringProtectionCheckpoints(Vector2Int start, Job job, out List<Vector2Int> path)
        {
            List<Vector2Int> targets = GetWorkPositions(job);
            return TryFindPathIgnoringProtectionCheckpoints(start, targets, out path);
        }

        private bool TryFindPathToJobIgnoringDoorRestrictions(Vector2Int start, Job job, out List<Vector2Int> path)
        {
            List<Vector2Int> targets = GetWorkPositions(job);
            return TryFindPathIgnoringDoorRestrictions(start, targets, out path);
        }

        private int CountUnreachableJobs(int probeLimit = int.MaxValue)
        {
            int count = 0;
            int probedJobs = 0;
            bool hasActiveWorkers = CountActiveWorkers() > 0;
            foreach (Job job in jobs)
            {
                if (job.AssignedWorker != null || !IsJobValid(job))
                {
                    continue;
                }

                if (!hasActiveWorkers)
                {
                    count++;
                    continue;
                }

                if (probedJobs >= probeLimit)
                {
                    break;
                }

                probedJobs++;
                if (!CanAnyActiveWorkerReachJob(job, out _))
                {
                    count++;
                }
            }

            return count;
        }

        private bool CanAnyActiveWorkerReachJob(Job job, out int shortestPath)
        {
            shortestPath = int.MaxValue;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f || !CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, job, out List<Vector2Int> path))
                {
                    shortestPath = Mathf.Min(shortestPath, path.Count);
                }
            }

            return shortestPath < int.MaxValue;
        }

        private bool CanAnyActiveWorkerReachJobIgnoringSafety(Job job, out int shortestPath)
        {
            shortestPath = int.MaxValue;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f || !CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                if (TryFindPathToJob(worker.Cell, worker, job, out List<Vector2Int> path))
                {
                    shortestPath = Mathf.Min(shortestPath, path.Count);
                }
            }

            return shortestPath < int.MaxValue;
        }

        private string JobReachabilityText(Job job)
        {
            if (job == null)
            {
                return string.Empty;
            }

            if (job.AssignedWorker != null)
            {
                return "Assigned to " + job.AssignedWorker.Name + ".";
            }

            if (!IsJobValid(job))
            {
                return JobInvalidText(job);
            }

            List<Vector2Int> workPositions = GetWorkPositions(job);
            if (workPositions.Count == 0)
            {
                return "Job blocked: no standable work cell. Build floor/ladder access.";
            }

            if (CountActiveWorkers() == 0)
            {
                return "Job blocked: no active duplicants.";
            }

            if (CanAnyActiveWorkerReachJob(job, out int shortestPath))
            {
                return "Job reachable: " + shortestPath + " steps.";
            }

            if (TryGetProtectionCheckpointBlockText(job, out string checkpointBlockText))
            {
                return checkpointBlockText;
            }

            if (TryGetDoorPathBlockText(job, out string doorBlockText))
            {
                return doorBlockText;
            }

            if (!IsSafetyCriticalJob(job.Type) && CanAnyActiveWorkerReachJobIgnoringSafety(job, out _))
            {
                return "Job blocked: unsafe route or work cell. Build atmo suits or make the area safe.";
            }

            return string.IsNullOrEmpty(job.TargetWorkerName)
                ? "Job unreachable: build ladder/floor/door access to a work cell."
                : "Job blocked: assigned duplicant is unavailable.";
        }

        private string JobReachabilityBlockText(Job job, string prefix, string fallback)
        {
            string reachabilityText = JobReachabilityText(job);
            if (string.IsNullOrEmpty(reachabilityText) ||
                reachabilityText.StartsWith("Job reachable:", StringComparison.Ordinal))
            {
                return string.Empty;
            }

            const string jobBlockedPrefix = "Job blocked: ";
            if (reachabilityText.StartsWith(jobBlockedPrefix, StringComparison.Ordinal))
            {
                return prefix + reachabilityText.Substring(jobBlockedPrefix.Length);
            }

            const string jobUnreachablePrefix = "Job unreachable: ";
            if (reachabilityText.StartsWith(jobUnreachablePrefix, StringComparison.Ordinal))
            {
                return prefix + reachabilityText.Substring(jobUnreachablePrefix.Length);
            }

            return fallback;
        }

        private bool TryGetProtectionCheckpointBlockText(Job job, out string text)
        {
            text = string.Empty;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f || !CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                if (!TryFindPathToJobIgnoringProtectionCheckpoints(worker.Cell, job, out List<Vector2Int> path))
                {
                    continue;
                }

                text = ProtectionCheckpointBlockText(worker, path);
                if (!string.IsNullOrEmpty(text))
                {
                    return true;
                }
            }

            return false;
        }

        private string ProtectionCheckpointBlockText(Worker worker, List<Vector2Int> path)
        {
            if (worker == null || path == null)
            {
                return string.Empty;
            }

            Vector2Int previous = worker.Cell;
            foreach (Vector2Int step in path)
            {
                if (IsSuitCheckpointCell(previous) && NeedsSuitProtection(step) && !CanEquipSuitAtCheckpoint(previous))
                {
                    return AtmoSuitCheckpointBlockText(previous);
                }

                if (IsOxygenMaskCheckpointCell(previous) && NeedsOxygenMaskProtection(step) && !CanEquipOxygenMaskAtCheckpoint(previous))
                {
                    return OxygenMaskCheckpointBlockText(previous);
                }

                if (IsLeadSuitCheckpointCell(previous) && NeedsLeadSuitProtection(step) && !CanEquipLeadSuitAtCheckpoint(previous))
                {
                    return LeadSuitCheckpointBlockText(previous);
                }

                previous = step;
            }

            return string.Empty;
        }

        private bool TryGetDoorPathBlockText(Job job, out string text)
        {
            text = string.Empty;
            foreach (Worker worker in workers)
            {
                if (worker.Health <= 0f || !CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                if (!TryFindPathToJobIgnoringDoorRestrictions(worker.Cell, job, out List<Vector2Int> path))
                {
                    continue;
                }

                text = DoorPathBlockText(worker, job, path);
                if (!string.IsNullOrEmpty(text))
                {
                    return true;
                }
            }

            return false;
        }

        private string DoorPathBlockText(Worker worker, Job job, List<Vector2Int> path)
        {
            if (worker == null || path == null)
            {
                return string.Empty;
            }

            Vector2Int previous = worker.Cell;
            foreach (Vector2Int step in path)
            {
                Vector2Int door = DoorPathBlockCell(previous, step);
                if (door.x >= 0)
                {
                    if (!IsDoorOpenForPathing(door))
                    {
                        return DoorClosedBlockText(door);
                    }

                    if (!CanPassDoorAccess(previous, step, worker, job))
                    {
                        return DoorAccessBlockText(door);
                    }
                }

                previous = step;
            }

            return string.Empty;
        }

        private Vector2Int DoorPathBlockCell(Vector2Int from, Vector2Int to)
        {
            if (IsInside(to.x, to.y) && IsDoorAccessControlledKind(cells[to.x, to.y]))
            {
                return to;
            }

            if (IsInside(from.x, from.y) && IsDoorAccessControlledKind(cells[from.x, from.y]))
            {
                return from;
            }

            if (IsInside(to.x, to.y) && cells[to.x, to.y] == CellKind.BunkerDoor)
            {
                return to;
            }

            if (IsInside(from.x, from.y) && cells[from.x, from.y] == CellKind.BunkerDoor)
            {
                return from;
            }

            return new Vector2Int(-1, -1);
        }

        private bool IsDoorOpenForPathing(Vector2Int door)
        {
            if (!IsInside(door.x, door.y))
            {
                return false;
            }

            if (cells[door.x, door.y] == CellKind.ManualAirlock)
            {
                return airlockOpen[door.x, door.y];
            }

            if (cells[door.x, door.y] == CellKind.MechanizedAirlock)
            {
                return IsMechanizedAirlockOpen(door);
            }

            if (cells[door.x, door.y] == CellKind.BunkerDoor)
            {
                return !IsBunkerDoorClosed(door);
            }

            return true;
        }

        private string DoorClosedBlockText(Vector2Int door)
        {
            if (!IsInside(door.x, door.y))
            {
                return string.Empty;
            }

            if (cells[door.x, door.y] == CellKind.ManualAirlock)
            {
                return "Job blocked: Manual Airlock is closed.";
            }

            if (cells[door.x, door.y] == CellKind.MechanizedAirlock)
            {
                return "Job blocked: Mechanized Airlock is closed by automation or damage.";
            }

            if (cells[door.x, door.y] == CellKind.BunkerDoor)
            {
                return "Job blocked: Bunker Door is closed.";
            }

            return string.Empty;
        }

        private string DoorAccessBlockText(Vector2Int door)
        {
            DoorAccessMode mode = DoorAccessModeAt(door.x, door.y);
            if (mode == DoorAccessMode.Locked)
            {
                return "Job blocked: door access is locked for duplicants.";
            }

            if (mode == DoorAccessMode.Emergency)
            {
                return "Job blocked: door access only allows emergency errands.";
            }

            return "Job blocked: door access only allows " + DoorAccessModeName(mode) + ".";
        }

        private string AtmoSuitCheckpointBlockText(Vector2Int checkpoint)
        {
            if (!HasAdjacentSuitDock(checkpoint))
            {
                return "Job blocked: Atmo Suit Checkpoint needs an adjacent repaired Atmo Suit Dock.";
            }

            if (AvailableSuitCount() <= 0)
            {
                return "Job blocked: all Atmo Suits are in use.";
            }

            if (!HasChargedSuitOxygen())
            {
                return "Job blocked: Atmo Suit Checkpoint needs charged suit oxygen.";
            }

            return "Job blocked: Atmo Suit Checkpoint is not ready.";
        }

