        private string JobInvalidText(Job job)
        {
            string reason = JobInvalidReasonText(job);
            if (IsBuildReservationJob(job))
            {
                reason += " Cancel to refund " + BuildCostText(job.DirtCost, job.MetalCost, job.AlgaeCost, job.RefinedMetalCost) + ".";
            }

            return reason;
        }

        private string JobInvalidReasonText(Job job)
        {
            if (job == null)
            {
                return string.Empty;
            }

            if (!IsInside(job.Cell.x, job.Cell.y))
            {
                return "Job invalid: target cell is out of bounds.";
            }

            if (IsJobBlockedByDisabledBuilding(job))
            {
                return "Job invalid: building is disabled.";
            }

            switch (job.Type)
            {
                case JobType.Dig:
                    return "Job invalid: dig target is no longer natural solid.";
                case JobType.Build:
                    return BuildInvalidReasonText(job);
                case JobType.BuildWire:
                    return IsPowerWireKindUnlocked(job.PowerWireKind, false)
                        ? "Job invalid: wire route is blocked or already built."
                        : "Job invalid: building is locked by missing research.";
                case JobType.BuildAutomationWire:
                    return techAutomationLogistics
                        ? "Job invalid: automation route is blocked or already built."
                        : "Job invalid: building is locked by missing research.";
                case JobType.BuildPipe:
                    return "Job invalid: liquid pipe route is blocked or already built.";
                case JobType.BuildGasPipe:
                    return techAirSystems && (job.GasPipeKind == GasPipeKind.Normal || techThermalEngineering)
                        ? "Job invalid: gas pipe route is blocked or already built."
                        : "Job invalid: building is locked by missing research.";
                case JobType.BuildShippingRail:
                    return techAutomationLogistics
                        ? "Job invalid: shipping rail route is blocked or already built."
                        : "Job invalid: building is locked by missing research.";
                case JobType.Deconstruct:
                    return "Job invalid: deconstruct target no longer exists.";
                case JobType.Mop:
                    return "Job invalid: spill target dried up.";
                case JobType.Disinfect:
                    return "Job invalid: germ target is already clean.";
                case JobType.Repair:
                    return metal < RepairMetalCost
                        ? "Job invalid: repair needs metal."
                        : "Job invalid: repair target changed.";
                case JobType.Rescue:
                    return HasUsableMedicalCot()
                        ? "Job invalid: target changed or resources missing."
                        : "Job invalid: no enabled Medical Cot available.";
                case JobType.Treat:
                    return "Job invalid: Medical Cot is unavailable for this patient.";
                case JobType.MedicalRest:
                    if (IsFloorMedicalRestJob(job))
                    {
                        Worker restPatient = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                        if (restPatient != null &&
                            IsFloorMedicalRestCell(job.Cell) &&
                            !IsPersonalRecoveryCellOpen(job.Cell, restPatient, job))
                        {
                            return "Job invalid: safe floor recovery spot is occupied or reserved.";
                        }

                        return "Job invalid: floor medical rest target changed.";
                    }

                    return HasUsableMedicalCot()
                        ? "Job invalid: Medical Cot is unavailable for this patient."
                        : "Job invalid: no enabled Medical Cot available.";
                case JobType.Sweep:
                    return "Job invalid: sweep target changed or storage is full.";
                case JobType.Harvest:
                    return "Job invalid: harvest target changed or storage is full.";
                case JobType.WrangleCritter:
                    return "Job invalid: wrangle target or Stable destination changed.";
                case JobType.ButcherCritter:
                    return "Job invalid: butcher target moved away or no longer exists.";
                case JobType.MoveTo:
                    return "Job invalid: move target is no longer reachable.";
                case JobType.Sleep:
                    if (IsFloorSleepJob(job))
                    {
                        Worker sleeper = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                        if (sleeper != null &&
                            IsFloorSleepCell(job.Cell) &&
                            !IsPersonalRecoveryCellOpen(job.Cell, sleeper, job))
                        {
                            return "Job invalid: floor sleep spot is occupied or reserved.";
                        }

                        return "Job invalid: floor sleep spot changed.";
                    }

                    return "Job invalid: bed is unavailable.";
                case JobType.CatchBreath:
                    Worker breather = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    if (breather != null &&
                        IsCharacterStandableCell(job.Cell) &&
                        BreathableAirAt(job.Cell.x, job.Cell.y) >= BreathRecoveryAirThreshold &&
                        !IsPersonalRecoveryCellOpen(job.Cell, breather, job))
                    {
                        return "Job invalid: breathable air spot is occupied or reserved.";
                    }

                    return "Job invalid: breathable air target changed.";
                case JobType.SeekSafety:
                    Worker safetyTarget = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    if (safetyTarget != null &&
                        IsSafetyRecoveryCell(job.Cell) &&
                        !IsPersonalRecoveryCellOpen(job.Cell, safetyTarget, job))
                    {
                        return "Job invalid: safe refuge is occupied or reserved.";
                    }

                    return "Job invalid: safe refuge target changed.";
                case JobType.Eat:
                    if (IsFloorEatJob(job))
                    {
                        Worker diner = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                        if (diner != null &&
                            IsFloorEatCell(job.Cell) &&
                            !IsPersonalRecoveryCellOpen(job.Cell, diner, job))
                        {
                            return "Job invalid: floor eat spot is occupied or reserved.";
                        }

                        return "Job invalid: floor eat spot changed.";
                    }

                    return "Job invalid: dining target changed or food is unavailable.";
                case JobType.Relax:
                    if (IsTakeBreakJob(job))
                    {
                        Worker stressedWorker = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                        if (stressedWorker != null &&
                            IsTakeBreakCell(job.Cell) &&
                            !IsPersonalRecoveryCellOpen(job.Cell, stressedWorker, job))
                        {
                            return "Job invalid: safe break spot is occupied or reserved.";
                        }

                        return "Job invalid: safe break spot changed.";
                    }

                    return "Job invalid: recreation target changed.";
                case JobType.TuneGenerator:
                    return "Job invalid: generator tune-up needs refined metal or a valid target.";
                default:
                    return "Job invalid: target changed or resources missing.";
            }
        }

        private bool IsJobBlockedByDisabledBuilding(Job job)
        {
            if (job == null || !IsInside(job.Cell.x, job.Cell.y) || !IsBuildingDisabled(job.Cell))
            {
                return false;
            }

            switch (job.Type)
            {
                case JobType.OperateGenerator:
                case JobType.PumpWater:
                case JobType.Research:
                case JobType.Cook:
                case JobType.UseToilet:
                case JobType.Relax:
                case JobType.Compost:
                case JobType.RefineMetal:
                case JobType.WashHands:
                case JobType.EmptyBottle:
                case JobType.Shower:
                case JobType.ProduceMedicine:
                case JobType.TuneGenerator:
                case JobType.ScrubSkill:
                case JobType.Treat:
                case JobType.MedicalRest:
                case JobType.GroomHatch:
                    return true;
                default:
                    return false;
            }
        }

        private string BuildInvalidReasonText(Job job)
        {
            if (!IsBuildUnlocked(job.BuildKind, false))
            {
                return "Job invalid: building is locked by missing research.";
            }

            CellKind current = cells[job.Cell.x, job.Cell.y];
            if (IsSolidTile(current) ||
                (current != CellKind.Empty && (job.BuildKind != CellKind.LiquidTepidizer || !IsLiquidTepidizerBuildLiquid(current))))
            {
                return "Job invalid: build site is occupied.";
            }

            if (HasLooseResource(job.Cell))
            {
                return "Job invalid: build site has loose debris.";
            }

            if (RequiresFloorSupport(job.BuildKind) && !HasFloorSupport(job.Cell))
            {
                return "Job invalid: build site lost floor support.";
            }

            if (RequiresCeilingSupport(job.BuildKind) && !HasCeilingSupport(job.Cell))
            {
                return "Job invalid: build site lost ceiling support.";
            }

            if (job.BuildKind == CellKind.WaterPump && !HasAdjacentWater(job.Cell))
            {
                return "Job invalid: water pump needs adjacent liquid.";
            }

            if (job.BuildKind == CellKind.PowerShutoff && !powerWire[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: power shutoff needs an existing wire.";
            }

            if ((job.BuildKind == CellKind.LiquidPipeSensor || job.BuildKind == CellKind.LiquidShutoff || job.BuildKind == CellKind.LiquidValve) &&
                !liquidPipe[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: liquid control needs an existing liquid pipe.";
            }

            if ((job.BuildKind == CellKind.GasPipeSensor || job.BuildKind == CellKind.GasShutoff || job.BuildKind == CellKind.GasValve) &&
                !gasPipe[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: gas control needs an existing gas pipe.";
            }

            if ((job.BuildKind == CellKind.ShippingRailSensor || job.BuildKind == CellKind.ShippingRailShutoff || job.BuildKind == CellKind.ShippingRailMeter) &&
                !shippingRail[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: shipping control needs an existing rail.";
            }

            if ((job.BuildKind == CellKind.LiquidBridge || job.BuildKind == CellKind.GasBridge) &&
                (liquidPipe[job.Cell.x, job.Cell.y] || gasPipe[job.Cell.x, job.Cell.y]))
            {
                return "Job invalid: bridge endpoint is occupied.";
            }

            if (job.BuildKind == CellKind.ShippingBridge && shippingRail[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: bridge endpoint is occupied.";
            }

            if (job.BuildKind == CellKind.PowerBridge && powerWire[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: bridge endpoint is occupied.";
            }

            if ((job.BuildKind == CellKind.AutomationBridge ||
                job.BuildKind == CellKind.AutomationNotGate ||
                job.BuildKind == CellKind.AutomationAndGate ||
                job.BuildKind == CellKind.AutomationOrGate ||
                job.BuildKind == CellKind.AutomationXorGate ||
                job.BuildKind == CellKind.AutomationBufferGate ||
                job.BuildKind == CellKind.AutomationFilterGate ||
                job.BuildKind == CellKind.AutomationMemoryGate) &&
                automationWire[job.Cell.x, job.Cell.y])
            {
                return "Job invalid: bridge endpoint is occupied.";
            }

            return "Job invalid: build site is blocked or lost support.";
        }

        private List<Vector2Int> GetWorkPositions(Job job)
        {
            List<Vector2Int> targets = new List<Vector2Int>();
            if (job.Type == JobType.Dig ||
                job.Type == JobType.Mop ||
                (job.Type == JobType.Deconstruct && job.BuildKind != CellKind.Empty && IsSolidTile(job.BuildKind)))
            {
                AddPassableTarget(targets, job.Cell.x + 1, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x - 1, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x, job.Cell.y + 1);
                AddPassableTarget(targets, job.Cell.x, job.Cell.y - 1);
            }
            else if (job.Type == JobType.Rescue)
            {
                AddPassableTarget(targets, job.Cell.x, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x + 1, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x - 1, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x, job.Cell.y + 1);
                AddPassableTarget(targets, job.Cell.x, job.Cell.y - 1);
            }
            else if (job.Type == JobType.ButcherCritter || job.Type == JobType.WrangleCritter)
            {
                TryGetCritterJobTargetCell(job, out Vector2Int targetCell);
                AddPassableTarget(targets, targetCell.x, targetCell.y);
                AddPassableTarget(targets, targetCell.x + 1, targetCell.y);
                AddPassableTarget(targets, targetCell.x - 1, targetCell.y);
                AddPassableTarget(targets, targetCell.x, targetCell.y + 1);
                AddPassableTarget(targets, targetCell.x, targetCell.y - 1);
            }
            else if (job.Type == JobType.Sleep || job.Type == JobType.Treat || job.Type == JobType.MedicalRest || job.Type == JobType.CatchBreath || job.Type == JobType.SeekSafety || job.Type == JobType.MoveTo || job.Type == JobType.UseToilet || job.Type == JobType.Shower || job.Type == JobType.Relax)
            {
                AddPassableTarget(targets, job.Cell.x, job.Cell.y);
            }
            else
            {
                AddPassableTarget(targets, job.Cell.x, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x + 1, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x - 1, job.Cell.y);
                AddPassableTarget(targets, job.Cell.x, job.Cell.y + 1);
                AddPassableTarget(targets, job.Cell.x, job.Cell.y - 1);
            }

            return targets;
        }

        private void AddPassableTarget(List<Vector2Int> targets, int x, int y)
        {
            if (IsCharacterStandableCell(new Vector2Int(x, y)))
            {
                targets.Add(new Vector2Int(x, y));
            }
        }

        private bool TryFindPath(Vector2Int start, List<Vector2Int> targets, out List<Vector2Int> path)
        {
            path = null;
            if (targets.Count == 0 || !IsInside(start.x, start.y))
            {
                return false;
            }

            HashSet<int> targetKeys = new HashSet<int>();
            foreach (Vector2Int target in targets)
            {
                targetKeys.Add(Key(target.x, target.y));
            }

            bool[,] visited = new bool[WorldWidth, WorldHeight];
            Vector2Int[,] previous = new Vector2Int[WorldWidth, WorldHeight];
            Queue<Vector2Int> frontier = new Queue<Vector2Int>();
            frontier.Enqueue(start);
            visited[start.x, start.y] = true;
            previous[start.x, start.y] = new Vector2Int(-1, -1);

            Vector2Int found = new Vector2Int(-1, -1);
            while (frontier.Count > 0)
            {
                Vector2Int current = frontier.Dequeue();
                if (targetKeys.Contains(Key(current.x, current.y)))
                {
                    found = current;
                    break;
                }

                EnqueuePathNeighbor(current, 1, 0, visited, previous, frontier);
                EnqueuePathNeighbor(current, -1, 0, visited, previous, frontier);
                EnqueuePathNeighbor(current, 0, 1, visited, previous, frontier);
                EnqueuePathNeighbor(current, 0, -1, visited, previous, frontier);
            }

            if (found.x < 0)
            {
                return false;
            }

            List<Vector2Int> reversed = new List<Vector2Int>();
            Vector2Int step = found;
            while (step != start)
            {
                reversed.Add(step);
                step = previous[step.x, step.y];
            }

            reversed.Reverse();
            path = reversed;
            return true;
        }

