        private void EnqueuePathNeighbor(Vector2Int current, int dx, int dy, bool[,] visited, Vector2Int[,] previous, Queue<Vector2Int> frontier)
        {
            int nx = current.x + dx;
            int ny = current.y + dy;
            if (!IsInside(nx, ny) || visited[nx, ny])
            {
                return;
            }

            Vector2Int next = new Vector2Int(nx, ny);
            if (!CanTraversePathStep(current, next))
            {
                return;
            }

            visited[nx, ny] = true;
            previous[nx, ny] = current;
            frontier.Enqueue(new Vector2Int(nx, ny));
        }

        private void EnqueuePathNeighborForJob(Vector2Int current, int dx, int dy, Worker worker, Job job, bool[,] visited, Vector2Int[,] previous, Queue<Vector2Int> frontier)
        {
            int nx = current.x + dx;
            int ny = current.y + dy;
            if (!IsInside(nx, ny) || visited[nx, ny])
            {
                return;
            }

            Vector2Int next = new Vector2Int(nx, ny);
            if (!CanWorkerTraversePathStepForJob(worker, job, current, next))
            {
                return;
            }

            visited[nx, ny] = true;
            previous[nx, ny] = current;
            frontier.Enqueue(new Vector2Int(nx, ny));
        }

