        private void EnqueuePathNeighborIgnoringDoorRestrictions(Vector2Int current, int dx, int dy, bool[,] visited, Vector2Int[,] previous, Queue<Vector2Int> frontier)
        {
            int nx = current.x + dx;
            int ny = current.y + dy;
            if (!IsInside(nx, ny) || visited[nx, ny])
            {
                return;
            }

            Vector2Int next = new Vector2Int(nx, ny);
            if (!CanCharacterTraversePathStepIgnoringDoorRestrictions(current, next))
            {
                return;
            }

            visited[nx, ny] = true;
            previous[nx, ny] = current;
            frontier.Enqueue(new Vector2Int(nx, ny));
        }

        private bool IsJobValid(Job job)
        {
            if (job == null || job.Cancelled || !IsInside(job.Cell.x, job.Cell.y))
            {
                return false;
            }

            if (IsJobBlockedByDisabledBuilding(job))
            {
                return false;
            }

            switch (job.Type)
            {
                case JobType.Dig:
                    return IsNaturalSolid(cells[job.Cell.x, job.Cell.y]);
                case JobType.Build:
                    return CanPlaceBuild(job.Cell, job.BuildKind);
                case JobType.BuildWire:
                    return IsPowerWireKindUnlocked(job.PowerWireKind, false) && CanPlacePowerWire(job.Cell, job.PowerWireKind);
                case JobType.BuildAutomationWire:
                    return CanPlaceAutomationWire(job.Cell) && techAutomationLogistics;
                case JobType.BuildPipe:
                    return CanPlaceLiquidPipe(job.Cell, job.LiquidPipeKind);
                case JobType.BuildGasPipe:
                    return CanPlaceGasPipe(job.Cell, job.GasPipeKind) && techAirSystems && (job.GasPipeKind == GasPipeKind.Normal || techThermalEngineering);
                case JobType.BuildShippingRail:
                    return CanPlaceShippingRail(job.Cell) && techAutomationLogistics;
                case JobType.Deconstruct:
                    return IsDeconstructJobValid(job);
                case JobType.Mop:
                    return IsMoppableSpill(job.Cell);
                case JobType.Disinfect:
                    return IsDisinfectableCell(job.Cell);
                case JobType.Repair:
                    return cells[job.Cell.x, job.Cell.y] == job.BuildKind && NeedsRepair(job.Cell) && metal >= RepairMetalCost;
                case JobType.Rescue:
                    Worker rescueTarget = FindWorkerByName(job.TargetWorkerName);
                    return rescueTarget != null &&
                        rescueTarget.Health <= 0f &&
                        rescueTarget.Cell == job.Cell &&
                        HasUsableMedicalCot();
                case JobType.Sweep:
                    return HasLooseResource(job.Cell) && CanStoreLooseResource(looseResourceKind[job.Cell.x, job.Cell.y], true);
                case JobType.OperateGenerator:
                    return cells[job.Cell.x, job.Cell.y] == CellKind.ManualGenerator && CanGeneratorOperate(job.Cell);
                case JobType.TuneGenerator:
                    return CanTuneGeneratorAt(job.Cell, job.AssignedWorker == null) &&
                        (job.AssignedWorker != null || refinedMetal >= PowerControlStationRefinedMetalCost);
                case JobType.Sculpt:
                    return NeedsSculpting(job.Cell);
                case JobType.Harvest:
                    return IsCropCell(job.Cell) && plantGrowth[job.Cell.x, job.Cell.y] >= 1f && CanHarvestCrop(job.Cell);
                case JobType.TendCrop:
                    return IsCropTendingTarget(job.Cell) &&
                        techFoodPreparation &&
                        CanSupplyCropTending() &&
                        TryFindFarmStationForCrop(job.Cell, out _);
                case JobType.PumpWater:
                    return cells[job.Cell.x, job.Cell.y] == CellKind.WaterPump && CanUseEquipment(job.Cell) && TryFindAdjacentWater(job.Cell, out _);
                case JobType.EmptyBottle:
                    return CanEmptyBottleAt(job.Cell);
                case JobType.Research:
                    return cells[job.Cell.x, job.Cell.y] == CellKind.ResearchStation && HasLockedResearch() && power > 1f && CanPoweredMachineRun(job.Cell);
                case JobType.Cook:
                    return CanCookAt(job.Cell);
                case JobType.RefineMetal:
                    return cells[job.Cell.x, job.Cell.y] == CellKind.RockCrusher &&
                        ((techPowerRegulation && metal >= RockCrusherOrePerJob && power >= RockCrusherPowerCost && CanPoweredMachineRun(job.Cell)) ||
                        CanRockCrusherProduceGlass(job.Cell) ||
                        CanRockCrusherProduceCeramic(job.Cell));
                case JobType.Compost:
                    return cells[job.Cell.x, job.Cell.y] == CellKind.Compost && CanUseEquipment(job.Cell) && CompostablePollutedDirt() >= 4f;
                case JobType.Sleep:
                    Worker sleeper = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    bool floorSleep = IsFloorSleepJob(job);
                    return IsSleepJobCell(job) &&
                        CanWorkerUseJobPersonalStation(sleeper, job) &&
                        (!floorSleep || IsPersonalRecoveryCellOpen(job.Cell, sleeper, job)) &&
                        (job.AssignedWorker != null || IsRestTime(sleeper) || AnyWorkerNeedsSleep());
                case JobType.Treat:
                    Worker patient = FindWorkerByName(job.TargetWorkerName);
                    return cells[job.Cell.x, job.Cell.y] == CellKind.MedicalCot &&
                        CanUseEquipment(job.Cell) &&
                        CanWorkerUseJobPersonalStation(patient, job) &&
                        patient != null &&
                        patient.Health > 0f &&
                        (job.AssignedWorker != null || NeedsTreatment(patient));
                case JobType.MedicalRest:
                    Worker restPatient = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    bool cotRest = restPatient != null &&
                        cells[job.Cell.x, job.Cell.y] == CellKind.MedicalCot &&
                        CanUseEquipment(job.Cell) &&
                        CanWorkerUseJobPersonalStation(restPatient, job);
                    bool floorRest = restPatient != null &&
                        IsFloorMedicalRestJob(job) &&
                        job.Cell == restPatient.Cell &&
                        IsFloorMedicalRestCell(job.Cell) &&
                        IsPersonalRecoveryCellOpen(job.Cell, restPatient, job);
                    return restPatient != null &&
                        restPatient.Health > 0f &&
                        !NeedsTreatment(restPatient) &&
                        (cotRest || floorRest) &&
                        (job.AssignedWorker != null || NeedsMedicalRest(restPatient));
                case JobType.CatchBreath:
                    Worker breather = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    return IsCharacterStandableCell(job.Cell) &&
                        BreathableAirAt(job.Cell.x, job.Cell.y) >= BreathRecoveryAirThreshold &&
                        breather != null &&
                        breather.Health > 0f &&
                        IsPersonalRecoveryCellOpen(job.Cell, breather, job) &&
                        (job.AssignedWorker != null || NeedsCatchBreath(breather));
                case JobType.SeekSafety:
                    Worker safetyTarget = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    return IsSafetyRecoveryCell(job.Cell) &&
                        safetyTarget != null &&
                        safetyTarget.Health > 0f &&
                        IsPersonalRecoveryCellOpen(job.Cell, safetyTarget, job) &&
                        (job.AssignedWorker != null || NeedsSeekSafety(safetyTarget));
                case JobType.MoveTo:
                    Worker moveTarget = FindWorkerByName(job.TargetWorkerName);
                    return IsCharacterStandableCell(job.Cell) &&
                        moveTarget != null &&
                        moveTarget.Health > 0f;
                case JobType.ProduceMedicine:
                    return CanProduceMedicineAt(job.Cell) && (job.AssignedWorker != null || medicine < DesiredMedicineStock());
                case JobType.UseToilet:
                    Worker toiletUser = FindWorkerByName(job.TargetWorkerName);
                    return IsToiletCell(job.Cell) &&
                        CanUseToiletAt(job.Cell) &&
                        toiletUser != null &&
                        toiletUser.Health > 0f &&
                        (job.AssignedWorker != null || NeedsToilet(toiletUser));
                case JobType.WashHands:
                    Worker washer = FindWorkerByName(job.TargetWorkerName);
                    return IsHandWashStationCell(job.Cell) &&
                        CanUseHandWashStationAt(job.Cell) &&
                        washer != null &&
                        washer.Health > 0f &&
                        (job.AssignedWorker != null || NeedsHandWash(washer));
                case JobType.Shower:
                    Worker showerUser = FindWorkerByName(job.TargetWorkerName);
                    return cells[job.Cell.x, job.Cell.y] == CellKind.Shower &&
                        CanUseEquipment(job.Cell) &&
                        CleanWaterAvailableForMachine(job.Cell) >= ShowerWaterUse &&
                        showerUser != null &&
                        showerUser.Health > 0f &&
                        (job.AssignedWorker != null || NeedsShower(showerUser));
                case JobType.Eat:
                    Worker diner = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    return diner != null &&
                        diner.Health > 0f &&
                        ((cells[job.Cell.x, job.Cell.y] == CellKind.MessTable &&
                            CanWorkerUsePersonalStation(job.Cell, diner)) ||
                            (IsFloorEatJob(job) &&
                                job.Cell == diner.Cell &&
                                IsFloorEatCell(job.Cell) &&
                                IsPersonalRecoveryCellOpen(job.Cell, diner, job))) &&
                        CanWorkerEatStoredFood(diner) &&
                        (job.AssignedWorker != null || NeedsFood(diner));
                case JobType.Relax:
                    Worker stressedWorker = job.AssignedWorker ?? FindWorkerByName(job.TargetWorkerName);
                    return stressedWorker != null &&
                        stressedWorker.Health > 0f &&
                        (CanUseRelaxationStationAt(job.Cell) ||
                            (IsTakeBreakJob(job) &&
                                job.Cell == stressedWorker.Cell &&
                                IsTakeBreakCell(job.Cell) &&
                                IsPersonalRecoveryCellOpen(job.Cell, stressedWorker, job))) &&
                        (job.AssignedWorker != null || NeedsRelaxation(stressedWorker));
                case JobType.ScrubSkill:
                    Worker scrubTarget = FindWorkerByName(job.TargetWorkerName);
                    return CanUseSkillScrubberAt(job.Cell) &&
                        scrubTarget != null &&
                        scrubTarget.Health > 0f &&
                        WorkerSkillLevel(scrubTarget) > 1 &&
                        (job.AssignedWorker != null || NeedsSkillScrub(scrubTarget));
                case JobType.GroomHatch:
                    return cells[job.Cell.x, job.Cell.y] == CellKind.RanchingStation &&
                        CanUseEquipment(job.Cell) &&
                        techFoodPreparation &&
                        (job.AssignedWorker != null || FindGroomableHatch(job.Cell) != null);
                case JobType.WrangleCritter:
                    HatchCritter wrangleTarget = WrangleTargetForJob(job);
                    if (wrangleTarget == null ||
                        IsCritterSettledInStable(wrangleTarget) ||
                        !TryFindWrangleDestination(wrangleTarget, out _))
                    {
                        return false;
                    }

                    Vector2Int wrangleCell = wrangleTarget.Cell;
                    if (job.AssignedWorker != null && job.Cell != wrangleCell)
                    {
                        job.Cell = wrangleCell;
                        return false;
                    }

                    job.Cell = wrangleCell;
                    return true;
                case JobType.ButcherCritter:
                    HatchCritter butcherTarget = ButcherTargetForJob(job);
                    if (butcherTarget == null)
                    {
                        return false;
                    }

                    Vector2Int butcherCell = butcherTarget.Cell;
                    if (job.AssignedWorker != null && job.Cell != butcherCell)
                    {
                        job.Cell = butcherCell;
                        return false;
                    }

                    job.Cell = butcherCell;
                    return true;
                default:
                    return false;
            }
        }

        private bool IsDeconstructJobValid(Job job)
        {
            if (job == null || !IsInside(job.Cell.x, job.Cell.y))
            {
                return false;
            }

            if (job.BuildKind != CellKind.Empty)
            {
                return cells[job.Cell.x, job.Cell.y] == job.BuildKind && IsDeconstructableBuilding(job.BuildKind);
            }

            return (job.RemovePowerWire && powerWire[job.Cell.x, job.Cell.y]) ||
                (job.RemoveAutomationWire && automationWire[job.Cell.x, job.Cell.y]) ||
                (job.RemoveLiquidPipe && liquidPipe[job.Cell.x, job.Cell.y]) ||
                (job.RemoveGasPipe && gasPipe[job.Cell.x, job.Cell.y]) ||
                (job.RemoveShippingRail && shippingRail[job.Cell.x, job.Cell.y]);
        }

        private string DeconstructTargetLabel(Job job)
        {
            if (job.BuildKind != CellKind.Empty)
            {
                return CellLabel(job.BuildKind);
            }

            if (job.RemovePowerWire)
            {
                return IsInside(job.Cell.x, job.Cell.y) ? PowerWireKindName(powerWireKind[job.Cell.x, job.Cell.y]) : "Power Wire";
            }

            if (job.RemoveAutomationWire)
            {
                return "Automation Wire";
            }

            if (job.RemoveLiquidPipe)
            {
                return IsInside(job.Cell.x, job.Cell.y) ? LiquidPipeKindName(liquidPipeKind[job.Cell.x, job.Cell.y]) : "Liquid Pipe";
            }

            if (job.RemoveGasPipe)
            {
                return IsInside(job.Cell.x, job.Cell.y) ? GasPipeKindName(gasPipeKind[job.Cell.x, job.Cell.y]) : "Gas Pipe";
            }

            if (job.RemoveShippingRail)
            {
                return "Shipping Rail";
            }

            return "Structure";
        }

        private void UpdatePoweredWires()
        {
            UpdateAutomationWires();
            Array.Clear(poweredWire, 0, poweredWire.Length);
            Queue<Vector2Int> frontier = new Queue<Vector2Int>();
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (powerWire[x, y] && !IsPowerShutoffBlockingWire(x, y) && IsWireTouchingPowerInfrastructure(x, y))
                    {
                        poweredWire[x, y] = true;
                        frontier.Enqueue(new Vector2Int(x, y));
                    }
                }
            }

            while (frontier.Count > 0)
            {
                Vector2Int cell = frontier.Dequeue();
                AddPoweredWireNeighbor(cell.x + 1, cell.y, frontier);
                AddPoweredWireNeighbor(cell.x - 1, cell.y, frontier);
                AddPoweredWireNeighbor(cell.x, cell.y + 1, frontier);
                AddPoweredWireNeighbor(cell.x, cell.y - 1, frontier);
                AddPowerBridgeOutputs(cell, frontier);
            }
        }

        private void AddPowerBridgeOutputs(Vector2Int inputWire, Queue<Vector2Int> frontier)
        {
            AddPowerBridgeOutput(inputWire, BridgeDirection.Right, frontier);
            AddPowerBridgeOutput(inputWire, BridgeDirection.Up, frontier);
            AddPowerBridgeOutput(inputWire, BridgeDirection.Left, frontier);
            AddPowerBridgeOutput(inputWire, BridgeDirection.Down, frontier);
        }

        private void AddPowerBridgeOutput(Vector2Int inputWire, BridgeDirection direction, Queue<Vector2Int> frontier)
        {
            Vector2Int inputOffset = BridgeInputOffset(direction);
            Vector2Int outputOffset = BridgeOutputOffset(direction);
            Vector2Int bridge = new Vector2Int(inputWire.x - inputOffset.x, inputWire.y - inputOffset.y);
            if (!IsInside(bridge.x, bridge.y) ||
                cells[bridge.x, bridge.y] != CellKind.PowerBridge ||
                !CanUseEquipment(bridge) ||
                BridgeDirectionAt(bridge.x, bridge.y) != direction)
            {
                return;
            }

            Vector2Int outputWire = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            AddPoweredWireNeighbor(outputWire.x, outputWire.y, frontier);
        }

        private void UpdatePowerLoad(float deltaTime, bool applyEffects)
        {
            RecalculatePowerLoad(applyEffects ? Mathf.Max(0f, deltaTime) : 0f);
            if (!applyEffects)
            {
                return;
            }

            if (ApplyWireOverloadEffects(deltaTime))
            {
                UpdatePoweredWires();
                RecalculatePowerLoad(0f);
            }
        }

        private void RecalculatePowerLoad(float deliveredDeltaTime)
        {
            Array.Clear(wireLoad, 0, wireLoad.Length);
            Array.Clear(overloadedWire, 0, overloadedWire.Length);

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    CellKind kind = cells[x, y];
                    Vector2Int cell = new Vector2Int(x, y);
                    if (!RequiresPower(kind) || IsBrokenEquipment(cell) || IsEquipmentSubmerged(cell) || !HasPoweredCircuit(cell) || !MachineAutomationAllows(cell))
                    {
                        continue;
                    }

                    AddPowerDemandNear(cell, PowerDemandForKind(kind), deliveredDeltaTime);
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (powerWire[x, y] && poweredWire[x, y] && wireLoad[x, y] > PowerLoadLimitForWire(x, y) + 0.001f)
                    {
                        overloadedWire[x, y] = true;
                    }
                }
            }
        }

        private bool ApplyWireOverloadEffects(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return false;
            }

            bool brokeWire = false;
            int firstBreakX = -1;
            int firstBreakY = -1;
            int overloadedCount = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (powerWire[x, y] && poweredWire[x, y] && overloadedWire[x, y])
                    {
                        overloadedCount++;
                        float limit = Mathf.Max(0.001f, PowerLoadLimitForWire(x, y));
                        float overloadRatio = Mathf.Clamp01((wireLoad[x, y] - limit) / limit);
                        wireOverloadStress[x, y] += deltaTime * (0.65f + overloadRatio);
                        AddHeat(new Vector2Int(x, y), WireOverloadHeatRate * deltaTime * (1f + overloadRatio), 1);

                        if (wireOverloadStress[x, y] >= WireOverloadBreakStress)
                        {
                            powerWire[x, y] = false;
                            powerWireKind[x, y] = PowerWireKind.Normal;
                            poweredWire[x, y] = false;
                            overloadedWire[x, y] = false;
                            wireLoad[x, y] = 0f;
                            wireOverloadStress[x, y] = 0f;
                            if (!brokeWire)
                            {
                                firstBreakX = x;
                                firstBreakY = y;
                            }

                            brokeWire = true;
                        }
                    }
                    else
                    {
                        wireOverloadStress[x, y] = Mathf.Max(0f, wireOverloadStress[x, y] - deltaTime * 0.5f);
                    }
                }
            }

            if (overloadedCount > 0)
            {
                overloadedWireSeconds += deltaTime;
                gasDirty = true;
                overlayDirty = true;
            }

            if (brokeWire)
            {
                gasDirty = true;
                overlayDirty = true;
                Log("Power Wire overloaded and burned out at " + firstBreakX + ", " + firstBreakY + ".");
            }

            return brokeWire;
        }

        private void AddPowerDemandNear(Vector2Int cell, float demand, float deliveredDeltaTime)
        {
            if (demand <= 0f)
            {
                return;
            }

            int wireCount = CountNearbyPoweredWires(cell);
            if (wireCount <= 0)
            {
                return;
            }

            float share = demand / wireCount;
            AddPowerDemandToWire(cell.x, cell.y, share, deliveredDeltaTime);
            AddPowerDemandToWire(cell.x + 1, cell.y, share, deliveredDeltaTime);
            AddPowerDemandToWire(cell.x - 1, cell.y, share, deliveredDeltaTime);
            AddPowerDemandToWire(cell.x, cell.y + 1, share, deliveredDeltaTime);
            AddPowerDemandToWire(cell.x, cell.y - 1, share, deliveredDeltaTime);
        }

        private int CountNearbyPoweredWires(Vector2Int cell)
        {
            int count = 0;
            count += IsPoweredWireCell(cell.x, cell.y) ? 1 : 0;
            count += IsPoweredWireCell(cell.x + 1, cell.y) ? 1 : 0;
            count += IsPoweredWireCell(cell.x - 1, cell.y) ? 1 : 0;
            count += IsPoweredWireCell(cell.x, cell.y + 1) ? 1 : 0;
            count += IsPoweredWireCell(cell.x, cell.y - 1) ? 1 : 0;
            return count;
        }

        private void AddPowerDemandToWire(int x, int y, float amount, float deliveredDeltaTime)
        {
            if (!IsPoweredWireCell(x, y))
            {
                return;
            }

            wireLoad[x, y] += amount;
            if (deliveredDeltaTime > 0f && HasTransformerProtection(x, y))
            {
                transformedPowerDelivered += amount * deliveredDeltaTime;
            }
        }

        private bool IsPoweredWireCell(int x, int y)
        {
            return IsInside(x, y) && powerWire[x, y] && poweredWire[x, y];
        }

        private float PowerLoadLimitForWire(int x, int y)
        {
            if (!IsInside(x, y) || !powerWire[x, y])
            {
                return 0f;
            }

            return PowerWireSafeLoad(powerWireKind[x, y]) + (HasTransformerProtection(x, y) ? PowerTransformerLoadBonus : 0f);
        }

        private bool HasTransformerProtection(int x, int y)
        {
            return IsPowerTransformerCell(x, y) ||
                IsPowerTransformerCell(x + 1, y) ||
                IsPowerTransformerCell(x - 1, y) ||
                IsPowerTransformerCell(x, y + 1) ||
                IsPowerTransformerCell(x, y - 1);
        }

        private bool IsPowerTransformerCell(int x, int y)
        {
            return IsInside(x, y) && cells[x, y] == CellKind.PowerTransformer && !IsBrokenEquipment(new Vector2Int(x, y));
        }

        private float PowerDemandForKind(CellKind kind)
        {
            switch (kind)
            {
                case CellKind.OxygenDiffuser:
                    return 0.95f;
                case CellKind.AirDeodorizer:
                    return 0.18f;
                case CellKind.ResearchStation:
                    return 0.40f;
                case CellKind.MicrobeMusher:
                    return 0.42f;
                case CellKind.ElectricGrill:
                    return 0.48f;
                case CellKind.Apothecary:
                    return 0.36f;
                case CellKind.RockCrusher:
                    return 1.20f;
                case CellKind.AtmoSuitDock:
                    return SuitDockPowerRate;
                case CellKind.GasPump:
                    return 0.50f;
                case CellKind.Electrolyzer:
                    return ElectrolyzerPowerRate;
                case CellKind.CarbonSkimmer:
                    return CarbonSkimmerPowerRate;
                case CellKind.WaterSieve:
                    return WaterSievePowerRate;
                case CellKind.Desalinator:
                    return DesalinatorPowerRate;
                case CellKind.FertilizerSynthesizer:
                    return FertilizerSynthesizerPowerRate;
                case CellKind.MetalRefinery:
                    return MetalRefineryPowerRate;
                case CellKind.OilRefinery:
                    return OilRefineryPowerRate;
                case CellKind.EthanolDistiller:
                    return EthanolDistillerPowerRate;
                case CellKind.TextileLoom:
                    return TextileLoomPowerRate;
                case CellKind.OilWell:
                    return OilWellPowerRate;
                case CellKind.PolymerPress:
                    return PolymerPressPowerRate;
                case CellKind.RocketPlatform:
                    return RocketPlatformPowerRate;
                case CellKind.OrbitalDataBank:
                    return OrbitalDataBankPowerRate;
                case CellKind.RadboltCollector:
                    return RadboltCollectorPowerRate;
                case CellKind.VentAnalyzer:
                    return VentAnalyzerPowerRate;
                case CellKind.HydrogenFilter:
                    return HydrogenFilterPowerRate;
                case CellKind.GasFilter:
                    return GasFilterPowerRate;
                case CellKind.SourGasCondenser:
                    return SourGasCondenserPowerRate;
                case CellKind.LiquidFilter:
                    return LiquidFilterPowerRate;
                case CellKind.ThermoAquatuner:
                    return ThermoAquatunerPowerRate;
                case CellKind.SpaceScanner:
                    return SpaceScannerPowerRate;
                case CellKind.Refrigerator:
                    return 0.24f;
                case CellKind.AutoSweeper:
                    return AutoSweeperPowerRate;
                case CellKind.ConveyorLoader:
                    return ConveyorLoaderPowerRate;
                case CellKind.Incubator:
                    return IncubatorPowerRate;
                case CellKind.CeilingLight:
                    return CeilingLightPowerRate;
                case CellKind.SkillScrubber:
                    return SkillScrubberPowerRate;
                case CellKind.ArcadeCabinet:
                    return ArcadeCabinetPowerRate;
                case CellKind.SpaceHeater:
                    return 0.80f;
                case CellKind.LiquidTepidizer:
                    return LiquidTepidizerPowerRate;
                case CellKind.ThermoRegulator:
                    return ThermoRegulatorPowerRate;
                default:
                    return 0f;
            }
        }

        private int CountOverloadedPowerWires()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (overloadedWire[x, y])
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private float MaxPowerWireLoad()
        {
            float maxLoad = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (wireLoad[x, y] > maxLoad)
                    {
                        maxLoad = wireLoad[x, y];
                    }
                }
            }

            return maxLoad;
        }

        private bool IsCropKind(CellKind kind)
        {
            return kind == CellKind.Planter || kind == CellKind.HydroponicFarm || kind == CellKind.FungalFarm || kind == CellKind.PepperPlant || kind == CellKind.GrubfruitPlant || kind == CellKind.ThimbleReed || kind == CellKind.SleetWheat || kind == CellKind.ArborTree;
        }

        private bool IsDreckoFeedCropKind(CellKind kind)
        {
            return kind == CellKind.Planter || kind == CellKind.HydroponicFarm;
        }

        private string CropDisplayName(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm ? "Bristle Blossom" : kind == CellKind.FungalFarm ? "Dusk Cap" : kind == CellKind.PepperPlant ? "Pincha Pepperplant" : kind == CellKind.GrubfruitPlant ? "Grubfruit Plant" : kind == CellKind.ThimbleReed ? "Thimble Reed" : kind == CellKind.SleetWheat ? "Sleet Wheat" : kind == CellKind.ArborTree ? "Arbor Tree" : "Mealwood";
        }

        private bool CropRequiresLight(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm;
        }

        private bool CropRequiresDarkness(CellKind kind)
        {
            return kind == CellKind.FungalFarm;
        }

        private bool CropLightSatisfied(CellKind kind, bool lit)
        {
            if (CropRequiresLight(kind))
            {
                return lit;
            }

            return !CropRequiresDarkness(kind) || !lit;
        }

        private bool CropAtmosphereSatisfied(CellKind kind, int x, int y)
        {
            if (kind == CellKind.FungalFarm)
            {
                return carbonDioxide[x, y] >= DuskCapCarbonDioxideThreshold;
            }

            if (kind == CellKind.PepperPlant)
            {
                return TileGasTotal(x, y) > 0.18f;
            }

            if (kind == CellKind.GrubfruitPlant)
            {
                return TileGasTotal(x, y) > 0.12f;
            }

            if (kind == CellKind.ThimbleReed)
            {
                return oxygen[x, y] + pollutedOxygen[x, y] > 0.14f;
            }

            if (kind == CellKind.SleetWheat)
            {
                return oxygen[x, y] > 0.14f;
            }

            if (kind == CellKind.ArborTree)
            {
                return TileGasTotal(x, y) > 0.12f;
            }

            return oxygen[x, y] > 0.18f;
        }

        private bool CropComfortableTemperature(CellKind kind, float localTemperature)
        {
            if (kind == CellKind.PepperPlant)
            {
                return localTemperature >= PepperPlantTemperatureMin && localTemperature <= PepperPlantTemperatureMax;
            }

            if (kind == CellKind.ArborTree)
            {
                return localTemperature >= ArborTreeTemperatureMin && localTemperature <= ArborTreeTemperatureMax;
            }

            if (kind == CellKind.GrubfruitPlant)
            {
                return localTemperature >= GrubfruitPlantTemperatureMin && localTemperature <= GrubfruitPlantTemperatureMax;
            }

            if (kind == CellKind.ThimbleReed)
            {
                return localTemperature >= ThimbleReedTemperatureMin && localTemperature <= ThimbleReedTemperatureMax;
            }

            if (kind == CellKind.SleetWheat)
            {
                return localTemperature >= SleetWheatTemperatureMin && localTemperature <= SleetWheatTemperatureMax;
            }

            return localTemperature >= 8f && localTemperature <= 34f;
        }

        private bool CropLethalTemperature(CellKind kind, float localTemperature)
        {
            if (kind == CellKind.PepperPlant)
            {
                return localTemperature < PepperPlantLethalTemperatureMin || localTemperature > PepperPlantLethalTemperatureMax;
            }

            if (kind == CellKind.ArborTree)
            {
                return localTemperature < ArborTreeLethalTemperatureMin || localTemperature > ArborTreeLethalTemperatureMax;
            }

            if (kind == CellKind.GrubfruitPlant)
            {
                return localTemperature < GrubfruitPlantLethalTemperatureMin || localTemperature > GrubfruitPlantLethalTemperatureMax;
            }

            if (kind == CellKind.ThimbleReed)
            {
                return localTemperature < ThimbleReedLethalTemperatureMin || localTemperature > ThimbleReedLethalTemperatureMax;
            }

            if (kind == CellKind.SleetWheat)
            {
                return localTemperature < SleetWheatLethalTemperatureMin || localTemperature > SleetWheatLethalTemperatureMax;
            }

            return localTemperature < -2f || localTemperature > 45f;
        }

        private float CropBaseGrowthRate(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm ? BristleBlossomBaseGrowthRate : kind == CellKind.FungalFarm ? DuskCapBaseGrowthRate : kind == CellKind.PepperPlant ? PepperPlantBaseGrowthRate : kind == CellKind.GrubfruitPlant ? GrubfruitPlantBaseGrowthRate : kind == CellKind.ThimbleReed ? ThimbleReedBaseGrowthRate : kind == CellKind.SleetWheat ? SleetWheatBaseGrowthRate : kind == CellKind.ArborTree ? ArborTreeBaseGrowthRate : MealwoodBaseGrowthRate;
        }

        private float CropWaterRateFor(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm ? BristleBlossomWaterRate : kind == CellKind.SleetWheat ? SleetWheatWaterRate : (kind == CellKind.FungalFarm || kind == CellKind.PepperPlant || kind == CellKind.GrubfruitPlant || kind == CellKind.ThimbleReed || kind == CellKind.ArborTree) ? 0f : CropWaterRate;
        }

        private float CropConsumableRateFor(CellKind kind)
        {
            return kind == CellKind.FungalFarm ? DuskCapSlimeRate : kind == CellKind.PepperPlant ? PepperPlantPollutedWaterRate : kind == CellKind.GrubfruitPlant ? GrubfruitPlantSulfurRate : kind == CellKind.ThimbleReed ? ThimbleReedPollutedWaterRate : CropWaterRateFor(kind);
        }

        private float CropHarvestYield(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm ? BristleBerryHarvestYield : kind == CellKind.FungalFarm ? DuskCapHarvestYield : kind == CellKind.PepperPlant ? PeppernutHarvestYield : kind == CellKind.GrubfruitPlant ? GrubfruitHarvestYield : kind == CellKind.ThimbleReed ? ThimbleReedReedFiberYield : kind == CellKind.SleetWheat ? SleetWheatWheatGrainYield : kind == CellKind.ArborTree ? ArborTreeLumberYield : MealwoodHarvestYield;
        }

        private float CropHarvestFreshness(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm ? 0.88f : kind == CellKind.FungalFarm ? 0.82f : kind == CellKind.GrubfruitPlant ? 0.84f : 0.78f;
        }

        private float CropFoodQuality(CellKind kind)
        {
            return kind == CellKind.HydroponicFarm ? BristleBerryFoodQuality : kind == CellKind.FungalFarm ? DuskCapFoodQuality : kind == CellKind.GrubfruitPlant ? GrubfruitFoodQuality : MealwoodFoodQuality;
        }

        private bool IsCropCell(Vector2Int crop)
        {
            return IsInside(crop.x, crop.y) && IsCropKind(cells[crop.x, crop.y]);
        }

        private bool CanHarvestCrop(Vector2Int crop)
        {
            if (!IsCropCell(crop))
            {
                return true;
            }

            CellKind kind = cells[crop.x, crop.y];
            return (kind != CellKind.PepperPlant && kind != CellKind.ThimbleReed && kind != CellKind.SleetWheat && kind != CellKind.ArborTree) || DryResourceFreeSpace() > 0.01f;
        }

        private bool HasCropIrrigation(Vector2Int crop)
        {
            if (!IsCropCell(crop))
            {
                return false;
            }

            if (cells[crop.x, crop.y] == CellKind.HydroponicFarm)
            {
                return HasMachineWaterFeed(crop);
            }

            if (cells[crop.x, crop.y] == CellKind.FungalFarm)
            {
                return slime > 0.02f;
            }

            if (cells[crop.x, crop.y] == CellKind.PepperPlant)
            {
                return PollutedWaterAvailableForSieve(crop) > 0.02f;
            }

            if (cells[crop.x, crop.y] == CellKind.ThimbleReed)
            {
                return PollutedWaterAvailableForThimbleReed(crop) > 0.02f;
            }

            if (cells[crop.x, crop.y] == CellKind.SleetWheat)
            {
                return water > 0.02f || HasMachineWaterFeed(crop);
            }

            if (cells[crop.x, crop.y] == CellKind.GrubfruitPlant)
            {
                return SulfurAround(crop, GrubfruitSulfurSearchRange) > 0.02f;
            }

            if (cells[crop.x, crop.y] == CellKind.ArborTree)
            {
                return true;
            }

            return water > 0.05f;
        }

        private float ConsumeCropIrrigationWater(Vector2Int crop, float requested)
        {
            if (requested <= 0f)
            {
                return 0f;
            }

            if (IsCropCell(crop) && cells[crop.x, crop.y] == CellKind.HydroponicFarm)
            {
                return ConsumeMachineWater(crop, requested);
            }

            if (IsCropCell(crop) && cells[crop.x, crop.y] == CellKind.FungalFarm)
            {
                float consumed = Mathf.Min(slime, requested);
                slime = Mathf.Max(0f, slime - consumed);
                duskCapSlimeConsumed += consumed;
                return consumed;
            }

            if (IsCropCell(crop) && cells[crop.x, crop.y] == CellKind.PepperPlant)
            {
                float consumed = ConsumePollutedWaterForSieve(crop, requested);
                pepperPlantPollutedWaterUsed += consumed;
                return consumed;
            }

            if (IsCropCell(crop) && cells[crop.x, crop.y] == CellKind.ThimbleReed)
            {
                float consumed = ConsumePollutedWaterForThimbleReed(crop, requested);
                thimbleReedPollutedWaterUsed += consumed;
                return consumed;
            }

            if (IsCropCell(crop) && cells[crop.x, crop.y] == CellKind.SleetWheat)
            {
                float consumed = ConsumeMachineWater(crop, requested);
                sleetWheatWaterUsed += consumed;
                return consumed;
            }

            if (IsCropCell(crop) && cells[crop.x, crop.y] == CellKind.GrubfruitPlant)
            {
                float consumed = ConsumeSulfurForCrop(crop, requested, GrubfruitSulfurSearchRange);
                grubfruitSulfurConsumed += consumed;
                return consumed;
            }

            return ConsumeCycleWater(requested);
        }

        private float ConsumeSulfurForCrop(Vector2Int center, float amount, int radius)
        {
            float consumed = 0f;
            Vector2Int sulfurCell = new Vector2Int(-1, -1);
            float bestScore = -1f;
            for (int dy = -radius; dy <= radius; dy++)
            {
                for (int dx = -radius; dx <= radius; dx++)
                {
                    int x = center.x + dx;
                    int y = center.y + dy;
                    int distance = Mathf.Abs(dx) + Mathf.Abs(dy);
                    if (!IsInside(x, y) || distance > radius || looseResourceKind[x, y] != LooseResourceKind.Sulfur || looseResourceAmount[x, y] <= 0.01f)
                    {
                        continue;
                    }

                    float score = looseResourceAmount[x, y] - distance * 0.06f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        sulfurCell = new Vector2Int(x, y);
                    }
                }
            }

            if (sulfurCell.x >= 0)
            {
                consumed = Mathf.Min(amount, looseResourceAmount[sulfurCell.x, sulfurCell.y]);
                looseResourceAmount[sulfurCell.x, sulfurCell.y] = Mathf.Max(0f, looseResourceAmount[sulfurCell.x, sulfurCell.y] - consumed);
                if (looseResourceAmount[sulfurCell.x, sulfurCell.y] <= 0.01f)
                {
                    looseResourceKind[sulfurCell.x, sulfurCell.y] = LooseResourceKind.None;
                    looseResourceAmount[sulfurCell.x, sulfurCell.y] = 0f;
                }
            }

            if (consumed < amount)
            {
                consumed += ConsumeDryResource(LooseResourceKind.Sulfur, amount - consumed);
            }

            return consumed;
        }

        private bool IsCropTendingTarget(Vector2Int crop)
        {
            return IsCropCell(crop) &&
                plantGrowth[crop.x, crop.y] < 1f &&
                cropStress[crop.x, crop.y] < CropWiltThresholdSeconds &&
                cropTendedSeconds[crop.x, crop.y] <= 5f;
        }

        private bool CanSupplyCropTending()
        {
            return fertilizer >= CropTendFertilizerCost ||
                pollutedDirt >= CropTendPollutedDirtCost ||
                dirt >= CropTendDirtFallbackCost;
        }

        private string CropStressReason(Vector2Int crop)
        {
            if (!IsCropCell(crop))
            {
                return "no crop";
            }

            if (waterMass[crop.x, crop.y] >= CropFloodWaterMass)
            {
                return "flooding";
            }

            float localTemperature = temperature[crop.x, crop.y];
            CellKind kind = cells[crop.x, crop.y];
            if (CropLethalTemperature(kind, localTemperature))
            {
                return "lethal temperature";
            }

            if (!CropComfortableTemperature(kind, localTemperature))
            {
                return kind == CellKind.PepperPlant ? "needs warm temperature" : kind == CellKind.GrubfruitPlant ? "needs mild temperature" : kind == CellKind.ThimbleReed ? "needs warm swamp temperature" : kind == CellKind.SleetWheat ? "needs freezing temperature" : kind == CellKind.ArborTree ? "needs mild temperature" : "bad temperature";
            }

            if (kind == CellKind.FungalFarm && carbonDioxide[crop.x, crop.y] < DuskCapCarbonDioxideThreshold)
            {
                return "needs carbon dioxide";
            }

            if (kind == CellKind.PepperPlant && TileGasTotal(crop.x, crop.y) <= 0.18f)
            {
                return "low pressure";
            }

            if (kind == CellKind.GrubfruitPlant && TileGasTotal(crop.x, crop.y) <= 0.12f)
            {
                return "low pressure";
            }

            if (kind == CellKind.ArborTree && TileGasTotal(crop.x, crop.y) <= 0.12f)
            {
                return "low pressure";
            }

            if (kind == CellKind.ThimbleReed && oxygen[crop.x, crop.y] + pollutedOxygen[crop.x, crop.y] <= 0.14f)
            {
                return "low pressure";
            }

            if (kind == CellKind.SleetWheat && oxygen[crop.x, crop.y] <= 0.14f)
            {
                return "low oxygen";
            }

            if (kind != CellKind.FungalFarm && kind != CellKind.PepperPlant && kind != CellKind.GrubfruitPlant && kind != CellKind.ThimbleReed && kind != CellKind.SleetWheat && kind != CellKind.ArborTree && oxygen[crop.x, crop.y] <= 0.18f)
            {
                return "low oxygen";
            }

            if (TileGasTotal(crop.x, crop.y) > OverpressureDamageThreshold)
            {
                return "overpressure";
            }

            if (CropRequiresLight(kind) && !IsCellLit(crop.x, crop.y))
            {
                return "needs light";
            }

            if (CropRequiresDarkness(kind) && IsCellLit(crop.x, crop.y))
            {
                return "too bright";
            }

            if (kind == CellKind.FungalFarm && slime <= 0.02f)
            {
                return "no slime";
            }

            if (kind == CellKind.PepperPlant && PollutedWaterAvailableForSieve(crop) <= 0.02f)
            {
                return "no polluted water";
            }

            if (kind == CellKind.ThimbleReed && PollutedWaterAvailableForThimbleReed(crop) <= 0.02f)
            {
                return "no polluted water";
            }

            if (kind == CellKind.SleetWheat && !HasCropIrrigation(crop))
            {
                return "no clean water";
            }

            if (kind == CellKind.GrubfruitPlant && SulfurAround(crop, GrubfruitSulfurSearchRange) <= 0.02f)
            {
                return "no sulfur";
            }

            if (!HasCropIrrigation(crop))
            {
                return "no irrigation water";
            }

            return cropStress[crop.x, crop.y] > 0.05f ? "recovering" : "healthy";
        }

