        private bool TryFindFarmStationForCrop(Vector2Int crop, out Vector2Int station)
        {
            station = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;
            for (int y = Mathf.Max(0, crop.y - FarmStationRange); y <= Mathf.Min(WorldHeight - 1, crop.y + FarmStationRange); y++)
            {
                for (int x = Mathf.Max(0, crop.x - FarmStationRange); x <= Mathf.Min(WorldWidth - 1, crop.x + FarmStationRange); x++)
                {
                    if (cells[x, y] != CellKind.FarmStation || !CanUseEquipment(new Vector2Int(x, y)))
                    {
                        continue;
                    }

                    int distance = Mathf.Abs(crop.x - x) + Mathf.Abs(crop.y - y);
                    if (distance <= FarmStationRange && distance < bestDistance)
                    {
                        bestDistance = distance;
                        station = new Vector2Int(x, y);
                    }
                }
            }

            return station.x >= 0;
        }

        private int CountCropTendingTargets()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsCropTendingTarget(new Vector2Int(x, y)) && TryFindFarmStationForCrop(new Vector2Int(x, y), out _))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string CropReadinessText(Vector2Int crop)
        {
            if (!IsCropCell(crop))
            {
                return "Crop blocked: plant missing.";
            }

            CellKind kind = cells[crop.x, crop.y];
            if (!techFoodPreparation && kind != CellKind.ArborTree)
            {
                return "Crop blocked: research Food Preparation.";
            }

            if (waterMass[crop.x, crop.y] >= CropFloodWaterMass)
            {
                return "Crop blocked: flooding.";
            }

            float localTemperature = temperature[crop.x, crop.y];
            if (CropLethalTemperature(kind, localTemperature))
            {
                return "Crop blocked: lethal temperature.";
            }

            if (!CropComfortableTemperature(kind, localTemperature))
            {
                return kind == CellKind.PepperPlant
                    ? "Crop blocked: Pepper Plant needs 35C-85C warmth."
                    : kind == CellKind.GrubfruitPlant
                        ? "Crop blocked: Grubfruit Plant needs 10C-50C mild temperature."
                    : kind == CellKind.ThimbleReed
                        ? "Crop blocked: Thimble Reed needs 18C-42C swamp temperature."
                    : kind == CellKind.SleetWheat
                        ? "Crop blocked: Sleet Wheat needs -55C-5C freezing temperature."
                    : kind == CellKind.ArborTree
                        ? "Crop blocked: Arbor Tree needs 12C-55C mild temperature."
                    : "Crop blocked: bad temperature.";
            }

            if (kind == CellKind.FungalFarm && carbonDioxide[crop.x, crop.y] < DuskCapCarbonDioxideThreshold)
            {
                return "Crop blocked: Dusk Cap needs carbon dioxide.";
            }

            if (kind == CellKind.PepperPlant && TileGasTotal(crop.x, crop.y) <= 0.18f)
            {
                return "Crop blocked: Pepper Plant needs gas pressure.";
            }

            if (kind == CellKind.GrubfruitPlant && TileGasTotal(crop.x, crop.y) <= 0.12f)
            {
                return "Crop blocked: Grubfruit Plant needs gas pressure.";
            }

            if (kind == CellKind.ThimbleReed && oxygen[crop.x, crop.y] + pollutedOxygen[crop.x, crop.y] <= 0.14f)
            {
                return "Crop blocked: Thimble Reed needs oxygen or polluted oxygen pressure.";
            }

            if (kind == CellKind.SleetWheat && oxygen[crop.x, crop.y] <= 0.14f)
            {
                return "Crop blocked: Sleet Wheat needs breathable oxygen pressure.";
            }

            if (kind == CellKind.ArborTree && TileGasTotal(crop.x, crop.y) <= 0.12f)
            {
                return "Crop blocked: Arbor Tree needs gas pressure.";
            }

            if (kind != CellKind.FungalFarm && kind != CellKind.PepperPlant && kind != CellKind.GrubfruitPlant && kind != CellKind.ThimbleReed && kind != CellKind.SleetWheat && kind != CellKind.ArborTree && oxygen[crop.x, crop.y] <= 0.18f)
            {
                return "Crop blocked: needs breathable oxygen.";
            }

            if (TileGasTotal(crop.x, crop.y) > OverpressureDamageThreshold)
            {
                return "Crop blocked: overpressure.";
            }

            if (CropRequiresLight(kind) && !IsCellLit(crop.x, crop.y))
            {
                return "Crop blocked: needs light.";
            }

            if (CropRequiresDarkness(kind) && IsCellLit(crop.x, crop.y))
            {
                return "Crop blocked: needs darkness.";
            }

            if (kind == CellKind.FungalFarm && slime <= 0.02f)
            {
                return "Crop blocked: needs stored slime.";
            }

            if (kind == CellKind.PepperPlant && PollutedWaterAvailableForSieve(crop) <= 0.02f)
            {
                return "Crop blocked: needs polluted water feed.";
            }

            if (kind == CellKind.ThimbleReed && PollutedWaterAvailableForThimbleReed(crop) <= 0.02f)
            {
                return "Crop blocked: Thimble Reed needs polluted water feed.";
            }

            if (kind == CellKind.SleetWheat && !HasCropIrrigation(crop))
            {
                return "Crop blocked: Sleet Wheat needs clean water feed.";
            }

            if (kind == CellKind.GrubfruitPlant && SulfurAround(crop, GrubfruitSulfurSearchRange) <= 0.02f)
            {
                return "Crop blocked: needs sulfur feed.";
            }

            if (!HasCropIrrigation(crop))
            {
                return "Crop blocked: needs irrigation water.";
            }

            if (plantGrowth[crop.x, crop.y] >= 1f)
            {
                Job harvestJob = FindJobAt(crop, JobType.Harvest);
                if (harvestJob != null)
                {
                    return "Crop ready: harvest errand queued. " + JobReachabilityText(harvestJob);
                }

                if (!CanHarvestCrop(crop))
                {
                    return "Crop blocked: dry storage is full for harvest.";
                }

                Job testJob = new Job(JobType.Harvest, crop, 2f);
                string routeBlock = JobReachabilityBlockText(
                    testJob,
                    "Crop blocked: ",
                    "Crop blocked: no reachable duplicant path for harvest.");
                return string.IsNullOrEmpty(routeBlock)
                    ? "Crop ready: reachable duplicant can harvest."
                    : routeBlock;
            }

            Job tendJob = FindJobAt(crop, JobType.TendCrop);
            if (tendJob != null)
            {
                return "Crop ready: tending errand queued. " + JobReachabilityText(tendJob);
            }

            if (cropTendedSeconds[crop.x, crop.y] > 0f)
            {
                return "Crop ready: tended growth boost active.";
            }

            if (cropStress[crop.x, crop.y] > 0.05f)
            {
                return "Crop recovering: healthy conditions restored; stress is falling.";
            }

            if (TryFindFarmStationForCrop(crop, out _))
            {
                if (!CanSupplyCropTending())
                {
                    return "Crop growing: Farm Station lacks fertilizer, polluted dirt, or dirt.";
                }

                Job testJob = new Job(JobType.TendCrop, crop, 2.4f);
                string routeBlock = JobReachabilityBlockText(
                    testJob,
                    "Crop blocked: ",
                    "Crop blocked: no reachable duplicant path for tending.");
                return string.IsNullOrEmpty(routeBlock)
                    ? "Crop ready: reachable duplicant can tend it."
                    : routeBlock;
            }

            return "Crop ready: growing under current conditions.";
        }

        private string FarmStationReadinessText(Vector2Int station)
        {
            if (!IsInside(station.x, station.y) || cells[station.x, station.y] != CellKind.FarmStation)
            {
                return "Farm Station blocked: station missing.";
            }

            if (!techFoodPreparation)
            {
                return "Farm Station blocked: research Food Preparation.";
            }

            string disabledBlock = DisabledBuildingBlockText(station);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(station))
            {
                return "Farm Station blocked: needs repair.";
            }

            if (IsEquipmentSubmerged(station))
            {
                return "Farm Station blocked: station is submerged.";
            }

            if (!CanSupplyCropTending())
            {
                return "Farm Station blocked: needs fertilizer, polluted dirt, or dirt.";
            }

            int localTargets = CountCropTendingTargetsForStation(station);
            if (localTargets == 0)
            {
                if (CountCropCells() == 0)
                {
                    return "Farm Station idle: no crops planted.";
                }

                return CountCropTendingTargets() > 0
                    ? "Farm Station idle: no tendable crops in range."
                    : "Farm Station idle: nearby crops are grown, wilting, or already tended.";
            }

            if (!TryFindCropTendingTargetForStation(station, true, out Vector2Int target))
            {
                if (TryFindCropTendingTargetForStation(station, false, out Vector2Int queuedTarget))
                {
                    Job queuedJob = FindJobAt(queuedTarget, JobType.TendCrop);
                    if (queuedJob != null)
                    {
                        return "Farm Station ready: tending errand queued. " + JobReachabilityText(queuedJob);
                    }
                }

                return "Farm Station ready: tending errand queued.";
            }

            Job testJob = new Job(JobType.TendCrop, target, 2.4f);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Farm Station blocked: ",
                "Farm Station blocked: no reachable duplicant path to tend crop.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Farm Station ready: can tend nearby crops."
                : routeBlock;
        }

        private int CountCropTendingTargetsForStation(Vector2Int station)
        {
            int count = 0;
            for (int y = Mathf.Max(0, station.y - FarmStationRange); y <= Mathf.Min(WorldHeight - 1, station.y + FarmStationRange); y++)
            {
                for (int x = Mathf.Max(0, station.x - FarmStationRange); x <= Mathf.Min(WorldWidth - 1, station.x + FarmStationRange); x++)
                {
                    Vector2Int crop = new Vector2Int(x, y);
                    int distance = Mathf.Abs(station.x - x) + Mathf.Abs(station.y - y);
                    if (distance <= FarmStationRange && IsCropTendingTarget(crop))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool TryFindCropTendingTargetForStation(Vector2Int station, bool requireNoJob, out Vector2Int target)
        {
            target = new Vector2Int(-1, -1);
            float bestScore = -1f;
            for (int y = Mathf.Max(0, station.y - FarmStationRange); y <= Mathf.Min(WorldHeight - 1, station.y + FarmStationRange); y++)
            {
                for (int x = Mathf.Max(0, station.x - FarmStationRange); x <= Mathf.Min(WorldWidth - 1, station.x + FarmStationRange); x++)
                {
                    Vector2Int crop = new Vector2Int(x, y);
                    int distance = Mathf.Abs(station.x - x) + Mathf.Abs(station.y - y);
                    if (distance > FarmStationRange ||
                        !IsCropTendingTarget(crop) ||
                        (requireNoJob && FindJobAt(crop, JobType.TendCrop) != null))
                    {
                        continue;
                    }

                    float score = (1f - plantGrowth[x, y]) * 100f + Mathf.Clamp(12f - cropTendedSeconds[x, y], 0f, 12f) - distance * 0.15f;
                    if (score > bestScore)
                    {
                        bestScore = score;
                        target = crop;
                    }
                }
            }

            return target.x >= 0;
        }

        private void UpdateAutomationWires()
        {
            Array.Clear(automationControlledWire, 0, automationControlledWire.Length);
            Array.Clear(automationSignalWire, 0, automationSignalWire.Length);
            Queue<Vector2Int> frontier = new Queue<Vector2Int>();

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (automationWire[x, y] && TryGetAutomationSourceSignalNearWire(x, y, out bool signalActive))
                    {
                        automationControlledWire[x, y] = true;
                        automationSignalWire[x, y] = signalActive;
                        frontier.Enqueue(new Vector2Int(x, y));
                    }
                }
            }

            while (frontier.Count > 0)
            {
                Vector2Int cell = frontier.Dequeue();
                bool signalActive = automationSignalWire[cell.x, cell.y];
                AddAutomationWireNeighbor(cell.x + 1, cell.y, signalActive, frontier);
                AddAutomationWireNeighbor(cell.x - 1, cell.y, signalActive, frontier);
                AddAutomationWireNeighbor(cell.x, cell.y + 1, signalActive, frontier);
                AddAutomationWireNeighbor(cell.x, cell.y - 1, signalActive, frontier);
                AddAutomationBridgeOutputs(cell, signalActive, frontier);
                AddAutomationNotGateOutput(cell, new Vector2Int(1, 0), new Vector2Int(2, 0), signalActive, frontier);
                AddAutomationNotGateOutput(cell, new Vector2Int(0, 1), new Vector2Int(0, 2), signalActive, frontier);
                AddAutomationAndGateOutputs(cell, frontier);
                AddAutomationOrGateOutputs(cell, frontier);
                AddAutomationXorGateOutputs(cell, frontier);
                AddAutomationBufferGateOutputs(cell, frontier);
                AddAutomationFilterGateOutputs(cell, frontier);
                AddAutomationMemoryGateOutputs(cell, frontier);
            }
        }

        private void AdvanceAutomationTimerSensors(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.AutomationTimerSensor)
                    {
                        automationTimerElapsedSeconds[x, y] = 0f;
                        continue;
                    }

                    float cycleSeconds = AutomationTimerCycleSecondsAt(x, y);
                    float before = AutomationTimerElapsedSecondsAt(x, y);
                    float after = Mathf.Repeat(before + deltaTime, cycleSeconds);
                    if (!Mathf.Approximately(before, after))
                    {
                        automationTimerElapsedSeconds[x, y] = after;
                        changed = true;
                    }
                }
            }

            if (changed)
            {
                overlayDirty = true;
            }
        }

        private void AdvanceAutomationBufferGates(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.AutomationBufferGate)
                    {
                        automationBufferRemainingSeconds[x, y] = 0f;
                        continue;
                    }

                    float holdSeconds = AutomationBufferHoldSecondsAt(x, y);
                    bool inputGreen = TryGetAutomationBufferGateInputs(new Vector2Int(x, y), out _, out bool westSignal, out bool southSignal) && (westSignal || southSignal);
                    float before = automationBufferRemainingSeconds[x, y];
                    float after = inputGreen ? holdSeconds : Mathf.Max(0f, before - deltaTime);
                    if (!Mathf.Approximately(before, after))
                    {
                        automationBufferRemainingSeconds[x, y] = after;
                        changed = true;
                    }
                }
            }

            if (changed)
            {
                overlayDirty = true;
            }
        }

        private void AdvanceAutomationFilterGates(float deltaTime)
        {
            if (deltaTime <= 0f)
            {
                return;
            }

            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.AutomationFilterGate)
                    {
                        automationFilterProgressSeconds[x, y] = 0f;
                        continue;
                    }

                    float delaySeconds = AutomationFilterDelaySecondsAt(x, y);
                    bool inputGreen = TryGetAutomationFilterGateInputs(new Vector2Int(x, y), out _, out bool westSignal, out bool southSignal) && (westSignal || southSignal);
                    float before = automationFilterProgressSeconds[x, y];
                    float after = inputGreen ? Mathf.Min(delaySeconds, before + deltaTime) : 0f;
                    if (!Mathf.Approximately(before, after))
                    {
                        automationFilterProgressSeconds[x, y] = after;
                        changed = true;
                    }
                }
            }

            if (changed)
            {
                overlayDirty = true;
            }
        }

        private void UpdateAutomationMemoryGates()
        {
            bool changed = false;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] != CellKind.AutomationMemoryGate)
                    {
                        automationMemoryState[x, y] = false;
                        continue;
                    }

                    Vector2Int gate = new Vector2Int(x, y);
                    if (!TryGetAutomationMemoryGateInputs(gate, out _, out bool setSignal, out bool resetSignal))
                    {
                        continue;
                    }

                    bool before = automationMemoryState[x, y];
                    if (resetSignal)
                    {
                        automationMemoryState[x, y] = false;
                    }
                    else if (setSignal)
                    {
                        automationMemoryState[x, y] = true;
                    }

                    changed |= before != automationMemoryState[x, y];
                }
            }

            if (changed)
            {
                overlayDirty = true;
            }
        }

        private void AddAutomationBridgeOutputs(Vector2Int inputWire, bool signalActive, Queue<Vector2Int> frontier)
        {
            AddAutomationBridgeOutput(inputWire, BridgeDirection.Right, signalActive, frontier);
            AddAutomationBridgeOutput(inputWire, BridgeDirection.Up, signalActive, frontier);
            AddAutomationBridgeOutput(inputWire, BridgeDirection.Left, signalActive, frontier);
            AddAutomationBridgeOutput(inputWire, BridgeDirection.Down, signalActive, frontier);
        }

        private void AddAutomationBridgeOutput(Vector2Int inputWire, BridgeDirection direction, bool signalActive, Queue<Vector2Int> frontier)
        {
            Vector2Int inputOffset = BridgeInputOffset(direction);
            Vector2Int outputOffset = BridgeOutputOffset(direction);
            Vector2Int bridge = new Vector2Int(inputWire.x - inputOffset.x, inputWire.y - inputOffset.y);
            if (!IsInside(bridge.x, bridge.y) ||
                cells[bridge.x, bridge.y] != CellKind.AutomationBridge ||
                !CanUseEquipment(bridge) ||
                BridgeDirectionAt(bridge.x, bridge.y) != direction)
            {
                return;
            }

            Vector2Int outputWire = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            AddAutomationWireNeighbor(outputWire.x, outputWire.y, signalActive, frontier);
        }

        private void AddAutomationNotGateOutput(Vector2Int inputWire, Vector2Int gateOffset, Vector2Int outputOffset, bool signalActive, Queue<Vector2Int> frontier)
        {
            Vector2Int gate = new Vector2Int(inputWire.x + gateOffset.x, inputWire.y + gateOffset.y);
            if (!IsInside(gate.x, gate.y) ||
                cells[gate.x, gate.y] != CellKind.AutomationNotGate ||
                !CanUseEquipment(gate))
            {
                return;
            }

            Vector2Int outputWire = new Vector2Int(inputWire.x + outputOffset.x, inputWire.y + outputOffset.y);
            AddAutomationWireNeighbor(outputWire.x, outputWire.y, !signalActive, frontier);
        }

        private void AddAutomationAndGateOutputs(Vector2Int inputWire, Queue<Vector2Int> frontier)
        {
            TryAddAutomationAndGateOutputs(new Vector2Int(inputWire.x + 1, inputWire.y), frontier);
            TryAddAutomationAndGateOutputs(new Vector2Int(inputWire.x, inputWire.y + 1), frontier);
        }

        private void TryAddAutomationAndGateOutputs(Vector2Int gate, Queue<Vector2Int> frontier)
        {
            if (!TryGetAutomationAndGateSignal(gate, out bool outputSignal))
            {
                return;
            }

            AddAutomationWireNeighbor(gate.x + 1, gate.y, outputSignal, frontier);
            AddAutomationWireNeighbor(gate.x, gate.y + 1, outputSignal, frontier);
        }

        private bool TryGetAutomationAndGateSignal(Vector2Int gate, out bool outputSignal)
        {
            outputSignal = false;
            if (!IsInside(gate.x, gate.y) ||
                cells[gate.x, gate.y] != CellKind.AutomationAndGate ||
                !CanUseEquipment(gate))
            {
                return false;
            }

            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            if (!IsControlledAutomationWire(westInput) || !IsControlledAutomationWire(southInput))
            {
                return false;
            }

            outputSignal = automationSignalWire[westInput.x, westInput.y] && automationSignalWire[southInput.x, southInput.y];
            return true;
        }

        private void AddAutomationOrGateOutputs(Vector2Int inputWire, Queue<Vector2Int> frontier)
        {
            TryAddAutomationOrGateOutputs(new Vector2Int(inputWire.x + 1, inputWire.y), frontier);
            TryAddAutomationOrGateOutputs(new Vector2Int(inputWire.x, inputWire.y + 1), frontier);
        }

