        private bool TryGetAutomationOrGateSignal(Vector2Int gate, out bool outputSignal)
        {
            outputSignal = false;
            if (!IsInside(gate.x, gate.y) ||
                cells[gate.x, gate.y] != CellKind.AutomationOrGate ||
                !CanUseEquipment(gate))
            {
                return false;
            }

            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            if (!IsInside(westInput.x, westInput.y) ||
                !automationWire[westInput.x, westInput.y] ||
                !IsInside(southInput.x, southInput.y) ||
                !automationWire[southInput.x, southInput.y])
            {
                return false;
            }

            bool westControlled = automationControlledWire[westInput.x, westInput.y];
            bool southControlled = automationControlledWire[southInput.x, southInput.y];
            if (!westControlled && !southControlled)
            {
                return false;
            }

            outputSignal = (westControlled && automationSignalWire[westInput.x, westInput.y]) ||
                (southControlled && automationSignalWire[southInput.x, southInput.y]);
            return true;
        }

