        private bool TryGetAutomationBufferGateSignal(Vector2Int gate, out bool outputSignal)
        {
            outputSignal = false;
            if (!TryGetAutomationBufferGateInputs(gate, out bool inputControlled, out bool westSignal, out bool southSignal))
            {
                return false;
            }

            bool heldSignal = automationBufferRemainingSeconds[gate.x, gate.y] > 0.001f;
            bool inputSignal = inputControlled && (westSignal || southSignal);
            outputSignal = inputSignal || heldSignal;
            return inputControlled || heldSignal;
        }

        private bool TryGetAutomationBufferGateInputs(Vector2Int gate, out bool inputControlled, out bool westSignal, out bool southSignal)
        {
            inputControlled = false;
            westSignal = false;
            southSignal = false;
            if (!IsInside(gate.x, gate.y) ||
                cells[gate.x, gate.y] != CellKind.AutomationBufferGate ||
                !CanUseEquipment(gate))
            {
                return false;
            }

            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            bool hasWestInput = IsInside(westInput.x, westInput.y) && automationWire[westInput.x, westInput.y];
            bool hasSouthInput = IsInside(southInput.x, southInput.y) && automationWire[southInput.x, southInput.y];
            if (!hasWestInput && !hasSouthInput)
            {
                return false;
            }

            bool westControlled = hasWestInput && automationControlledWire[westInput.x, westInput.y];
            bool southControlled = hasSouthInput && automationControlledWire[southInput.x, southInput.y];
            inputControlled = westControlled || southControlled;
            westSignal = westControlled && automationSignalWire[westInput.x, westInput.y];
            southSignal = southControlled && automationSignalWire[southInput.x, southInput.y];
            return true;
        }

