            AddAutomationWireNeighbor(gate.x + 1, gate.y, outputSignal, frontier);
            AddAutomationWireNeighbor(gate.x, gate.y + 1, outputSignal, frontier);
        }

        private bool TryGetAutomationFilterGateSignal(Vector2Int gate, out bool outputSignal)
        {
            outputSignal = false;
            if (!TryGetAutomationFilterGateInputs(gate, out bool inputControlled, out bool westSignal, out bool southSignal))
            {
                return false;
            }

            bool inputSignal = inputControlled && (westSignal || southSignal);
            float delaySeconds = AutomationFilterDelaySecondsAt(gate.x, gate.y);
            outputSignal = inputSignal && automationFilterProgressSeconds[gate.x, gate.y] >= delaySeconds - 0.001f;
            return inputControlled;
        }

        private bool TryGetAutomationFilterGateInputs(Vector2Int gate, out bool inputControlled, out bool westSignal, out bool southSignal)
        {
            inputControlled = false;
            westSignal = false;
            southSignal = false;
            if (!IsInside(gate.x, gate.y) ||
                cells[gate.x, gate.y] != CellKind.AutomationFilterGate ||
                !CanUseEquipment(gate))
            {
                return false;
            }

            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            bool hasWestInput = IsInside(westInput.x, westInput.y) && automationWire[westInput.x, westInput.y];
            bool hasSouthInput = IsInside(southInput.x, southInput.y) && automationWire[southInput.x, southInput.y];
            if (!hasWestInput && !hasSouthInput)
            {
                return false;
            }

            bool westControlled = hasWestInput && automationControlledWire[westInput.x, westInput.y];
            bool southControlled = hasSouthInput && automationControlledWire[southInput.x, southInput.y];
            inputControlled = westControlled || southControlled;
            westSignal = westControlled && automationSignalWire[westInput.x, westInput.y];
            southSignal = southControlled && automationSignalWire[southInput.x, southInput.y];
            return true;
        }

        private void AddAutomationMemoryGateOutputs(Vector2Int inputWire, Queue<Vector2Int> frontier)
        {
            TryAddAutomationMemoryGateOutputs(new Vector2Int(inputWire.x + 1, inputWire.y), frontier);
            TryAddAutomationMemoryGateOutputs(new Vector2Int(inputWire.x, inputWire.y + 1), frontier);
        }

        private void TryAddAutomationMemoryGateOutputs(Vector2Int gate, Queue<Vector2Int> frontier)
        {
            if (!TryGetAutomationMemoryGateSignal(gate, out bool outputSignal))
            {
                return;
            }

            AddAutomationWireNeighbor(gate.x + 1, gate.y, outputSignal, frontier);
            AddAutomationWireNeighbor(gate.x, gate.y + 1, outputSignal, frontier);
        }

        private bool TryGetAutomationMemoryGateSignal(Vector2Int gate, out bool outputSignal)
        {
            outputSignal = false;
            if (!TryGetAutomationMemoryGateInputs(gate, out _, out _, out _))
            {
                return false;
            }

            outputSignal = automationMemoryState[gate.x, gate.y];
            return true;
        }

        private bool TryGetAutomationMemoryGateInputs(Vector2Int gate, out bool inputControlled, out bool setSignal, out bool resetSignal)
        {
            inputControlled = false;
            setSignal = false;
            resetSignal = false;
            if (!IsInside(gate.x, gate.y) ||
                cells[gate.x, gate.y] != CellKind.AutomationMemoryGate ||
                !CanUseEquipment(gate))
            {
                return false;
            }

            Vector2Int setInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int resetInput = new Vector2Int(gate.x, gate.y - 1);
            bool hasSetInput = IsInside(setInput.x, setInput.y) && automationWire[setInput.x, setInput.y];
            bool hasResetInput = IsInside(resetInput.x, resetInput.y) && automationWire[resetInput.x, resetInput.y];
            if (!hasSetInput && !hasResetInput)
            {
                return false;
            }

            bool setControlled = hasSetInput && automationControlledWire[setInput.x, setInput.y];
            bool resetControlled = hasResetInput && automationControlledWire[resetInput.x, resetInput.y];
            inputControlled = setControlled || resetControlled;
            setSignal = setControlled && automationSignalWire[setInput.x, setInput.y];
            resetSignal = resetControlled && automationSignalWire[resetInput.x, resetInput.y];
            return true;
        }

        private bool IsControlledAutomationWire(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                automationWire[cell.x, cell.y] &&
                automationControlledWire[cell.x, cell.y];
        }

        private void AddAutomationWireNeighbor(int x, int y, bool signalActive, Queue<Vector2Int> frontier)
        {
            if (!IsInside(x, y) || !automationWire[x, y])
            {
                return;
            }

            if (automationControlledWire[x, y] && (!signalActive || automationSignalWire[x, y]))
            {
                return;
            }

            automationControlledWire[x, y] = true;
            automationSignalWire[x, y] |= signalActive;
            frontier.Enqueue(new Vector2Int(x, y));
        }

        private bool TryGetAutomationSourceSignalNearWire(int x, int y, out bool signalActive)
        {
            signalActive = false;
            bool foundSource = false;
            foundSource |= TryMergeAutomationSourceSignal(x, y, ref signalActive);
            foundSource |= TryMergeAutomationSourceSignal(x + 1, y, ref signalActive);
            foundSource |= TryMergeAutomationSourceSignal(x - 1, y, ref signalActive);
            foundSource |= TryMergeAutomationSourceSignal(x, y + 1, ref signalActive);
            foundSource |= TryMergeAutomationSourceSignal(x, y - 1, ref signalActive);
            return foundSource;
        }

        private bool TryMergeAutomationSourceSignal(int x, int y, ref bool signalActive)
        {
            if (!TryGetAutomationSourceSignal(x, y, out bool sourceSignal))
            {
                return false;
            }

            signalActive |= sourceSignal;
            return true;
        }

        private bool TryGetAutomationSourceSignal(int x, int y, out bool signalActive)
        {
            signalActive = false;
            if (!IsInside(x, y))
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind == CellKind.SmartBattery)
            {
                signalActive = SmartBatterySignalActive(x, y);
                return true;
            }

            if (kind == CellKind.LiquidPipeSensor)
            {
                signalActive = LiquidSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.GasPipeSensor)
            {
                signalActive = GasSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.ShippingRailSensor)
            {
                signalActive = ShippingRailSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.AtmoSensor)
            {
                signalActive = AtmoSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.ThermoSensor)
            {
                signalActive = ThermoSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.HydroSensor)
            {
                signalActive = HydroSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.GermSensor)
            {
                signalActive = GermSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.WeightPlate)
            {
                signalActive = WeightPlateSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.AutomationCycleSensor)
            {
                signalActive = AutomationCycleSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.AutomationTimerSensor)
            {
                signalActive = AutomationTimerSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.DuplicantMotionSensor)
            {
                signalActive = DuplicantMotionSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.CritterSensor)
            {
                signalActive = CritterSensorSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.SpaceScanner)
            {
                signalActive = SpaceScannerSignalActive(x, y);
                return true;
            }

            if (kind == CellKind.SignalSwitch)
            {
                signalActive = SignalSwitchSignalActive(x, y);
                return true;
            }

            return false;
        }

        private bool SignalSwitchSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.SignalSwitch &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                automationSwitchState[x, y];
        }

        private bool LiquidSensorSignalActive(int x, int y)
        {
            if (!IsInside(x, y) ||
                cells[x, y] != CellKind.LiquidPipeSensor ||
                !liquidPipe[x, y] ||
                !CanUseEquipment(new Vector2Int(x, y)))
            {
                return false;
            }

            switch (liquidSensorMode[x, y])
            {
                case LiquidSensorMode.CleanWater:
                    return pipeWater[x, y] >= LiquidSensorThreshold;
                case LiquidSensorMode.PollutedWater:
                    return pipePollutedWater[x, y] >= LiquidSensorThreshold;
                case LiquidSensorMode.Petroleum:
                    return pipePetroleum[x, y] >= LiquidSensorThreshold;
                default:
                    return LiquidPipeTotal(x, y) >= LiquidSensorThreshold;
            }
        }

        private bool GasSensorSignalActive(int x, int y)
        {
            if (!IsInside(x, y) ||
                cells[x, y] != CellKind.GasPipeSensor ||
                !gasPipe[x, y] ||
                !CanUseEquipment(new Vector2Int(x, y)))
            {
                return false;
            }

            switch (gasSensorMode[x, y])
            {
                case GasSensorMode.Oxygen:
                    return gasPipeOxygen[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.CarbonDioxide:
                    return gasPipeCarbonDioxide[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.PollutedOxygen:
                    return gasPipePollutedOxygen[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.Hydrogen:
                    return gasPipeHydrogen[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.Steam:
                    return gasPipeSteam[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.Chlorine:
                    return gasPipeChlorine[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.NaturalGas:
                    return gasPipeNaturalGas[x, y] >= GasSensorElementThreshold;
                case GasSensorMode.SourGas:
                    return gasPipeSourGas[x, y] >= GasSensorElementThreshold;
                default:
                    return GasPipeTotal(x, y) >= GasSensorPressureThreshold || gasPipeHydrogen[x, y] >= GasSensorElementThreshold;
            }
        }

        private bool ShippingRailSensorSignalActive(int x, int y)
        {
            if (!IsInside(x, y) ||
                cells[x, y] != CellKind.ShippingRailSensor ||
                !shippingRail[x, y] ||
                shippingRailKind[x, y] == LooseResourceKind.None ||
                shippingRailAmount[x, y] <= ShippingRailSensorThreshold ||
                !CanUseEquipment(new Vector2Int(x, y)))
            {
                return false;
            }

            return StorageFilterAcceptsResource(ShippingRailSensorFilterAt(x, y), shippingRailKind[x, y]);
        }

        private bool AtmoSensorSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.AtmoSensor &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                ThresholdSensorConditionMatches(TileGasTotal(x, y), AtmoSensorThresholdAt(x, y), ThresholdSensorConditionAt(x, y));
        }

        private bool ThermoSensorSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.ThermoSensor &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                ThresholdSensorConditionMatches(temperature[x, y], ThermoSensorThresholdAt(x, y), ThresholdSensorConditionAt(x, y));
        }

        private bool HydroSensorSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.HydroSensor &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                ThresholdSensorConditionMatches(waterMass[x, y], HydroSensorThresholdAt(x, y), ThresholdSensorConditionAt(x, y));
        }

        private bool GermSensorSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.GermSensor &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                ThresholdSensorConditionMatches(germs[x, y], GermSensorThresholdAt(x, y), ThresholdSensorConditionAt(x, y));
        }

        private bool WeightPlateSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.WeightPlate &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                ThresholdSensorConditionMatches(WeightPlateMassAt(x, y), WeightPlateThresholdAt(x, y), ThresholdSensorConditionAt(x, y));
        }

        private float AtmoSensorThresholdAt(int x, int y)
        {
            return Mathf.Clamp(atmoSensorThreshold[x, y] <= 0.001f ? AtmoSensorPressureThreshold : atmoSensorThreshold[x, y], AtmoSensorPressureMin, AtmoSensorPressureMax);
        }

        private float ThermoSensorThresholdAt(int x, int y)
        {
            return Mathf.Clamp(thermoSensorThreshold[x, y], ThermoSensorTemperatureMin, ThermoSensorTemperatureMax);
        }

        private float HydroSensorThresholdAt(int x, int y)
        {
            return Mathf.Clamp(hydroSensorThreshold[x, y] <= 0.001f ? HydroSensorLiquidThreshold : hydroSensorThreshold[x, y], HydroSensorLiquidMin, HydroSensorLiquidMax);
        }

        private float GermSensorThresholdAt(int x, int y)
        {
            return Mathf.Clamp(germSensorThreshold[x, y] <= 0.001f ? GermSensorThreshold : germSensorThreshold[x, y], GermSensorMin, GermSensorMax);
        }

        private float WeightPlateThresholdAt(int x, int y)
        {
            return Mathf.Clamp(weightPlateThreshold[x, y] <= 0.001f ? WeightPlateThreshold : weightPlateThreshold[x, y], WeightPlateMin, WeightPlateMax);
        }

        private float CritterSensorThresholdAt(int x, int y)
        {
            return Mathf.Clamp(critterSensorThreshold[x, y], CritterSensorMin, CritterSensorMax);
        }

        private float WeightPlateMassAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            float mass = looseResourceKind[x, y] == LooseResourceKind.None ? 0f : Mathf.Max(0f, looseResourceAmount[x, y]);
            Vector2Int cell = new Vector2Int(x, y);
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && worker.Cell == cell)
                {
                    mass += WeightPlateWorkerWeight;
                }
            }

            foreach (HatchCritter hatch in hatches)
            {
                if (hatch.Cell == cell)
                {
                    mass += WeightPlateHatchWeight;
                }
            }

            return mass;
        }

        private float AutomationBufferHoldSecondsAt(int x, int y)
        {
            return Mathf.Clamp(
                automationBufferHoldSeconds[x, y] <= 0.001f ? AutomationBufferHoldDefaultSeconds : automationBufferHoldSeconds[x, y],
                AutomationBufferHoldMinSeconds,
                AutomationBufferHoldMaxSeconds);
        }

        private float AutomationFilterDelaySecondsAt(int x, int y)
        {
            return Mathf.Clamp(
                automationFilterDelaySeconds[x, y] <= 0.001f ? AutomationFilterDelayDefaultSeconds : automationFilterDelaySeconds[x, y],
                AutomationFilterDelayMinSeconds,
                AutomationFilterDelayMaxSeconds);
        }

        private bool AutomationTimerSensorSignalActive(int x, int y)
        {
            if (!IsInside(x, y) ||
                cells[x, y] != CellKind.AutomationTimerSensor ||
                !CanUseEquipment(new Vector2Int(x, y)))
            {
                return false;
            }

            return AutomationTimerElapsedSecondsAt(x, y) < AutomationTimerGreenSecondsAt(x, y);
        }

        private float AutomationTimerGreenSecondsAt(int x, int y)
        {
            return Mathf.Clamp(
                automationTimerGreenSeconds[x, y] <= 0.001f ? AutomationTimerDefaultGreenSeconds : automationTimerGreenSeconds[x, y],
                AutomationTimerMinSeconds,
                AutomationTimerMaxSeconds);
        }

        private float AutomationTimerRedSecondsAt(int x, int y)
        {
            return Mathf.Clamp(
                automationTimerRedSeconds[x, y] <= 0.001f ? AutomationTimerDefaultRedSeconds : automationTimerRedSeconds[x, y],
                AutomationTimerMinSeconds,
                AutomationTimerMaxSeconds);
        }

        private float AutomationTimerCycleSecondsAt(int x, int y)
        {
            return AutomationTimerGreenSecondsAt(x, y) + AutomationTimerRedSecondsAt(x, y);
        }

        private float AutomationTimerElapsedSecondsAt(int x, int y)
        {
            return Mathf.Repeat(Mathf.Max(0f, automationTimerElapsedSeconds[x, y]), AutomationTimerCycleSecondsAt(x, y));
        }

        private bool DuplicantMotionSensorSignalActive(int x, int y)
        {
            if (!IsInside(x, y) ||
                cells[x, y] != CellKind.DuplicantMotionSensor ||
                !CanUseEquipment(new Vector2Int(x, y)))
            {
                return false;
            }

            return CountDuplicantsForMotionSensor(new Vector2Int(x, y)) > 0;
        }

        private int CountDuplicantsForMotionSensor(Vector2Int center)
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && IsDuplicantMotionSensorCellInRange(center, worker.Cell))
                {
                    count++;
                }
            }

            return count;
        }

        private bool IsDuplicantMotionSensorCellInRange(Vector2Int center, Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                Mathf.Abs(cell.x - center.x) + Mathf.Abs(cell.y - center.y) <= DuplicantMotionSensorRange;
        }

        private bool HasDuplicantMotionSensors()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.DuplicantMotionSensor)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool HasWeightPlates()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.WeightPlate)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AutomationCycleSensorSignalActive(int x, int y)
        {
            if (!IsInside(x, y) ||
                cells[x, y] != CellKind.AutomationCycleSensor ||
                !CanUseEquipment(new Vector2Int(x, y)))
            {
                return false;
            }

            return IsWithinCycleWindow(
                cycleTimer / CycleLengthSeconds,
                CycleSensorStartAt(x, y),
                CycleSensorWindowDuration(x, y));
        }

        private float CycleSensorStartAt(int x, int y)
        {
            return NormalizeCycleTime(automationCycleSensorStart[x, y]);
        }

        private float CycleSensorEndAt(int x, int y)
        {
            return NormalizeCycleTime(automationCycleSensorEnd[x, y]);
        }

        private float CycleSensorWindowDuration(int x, int y)
        {
            return CycleWindowDuration(CycleSensorStartAt(x, y), CycleSensorEndAt(x, y));
        }

        private float CycleWindowDuration(float start, float end)
        {
            start = NormalizeCycleTime(start);
            end = NormalizeCycleTime(end);
            float duration = start <= end ? end - start : 1f - start + end;
            return Mathf.Clamp(duration, AutomationCycleSensorMinWindow, 1f);
        }

        private ThresholdSensorCondition ThresholdSensorConditionAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return ThresholdSensorCondition.AboveOrEqual;
            }

            if (cells[x, y] == CellKind.ThermoSensor)
            {
                return thermoSensorCondition[x, y];
            }

            if (cells[x, y] == CellKind.HydroSensor)
            {
                return hydroSensorCondition[x, y];
            }

            if (cells[x, y] == CellKind.GermSensor)
            {
                return germSensorCondition[x, y];
            }

            if (cells[x, y] == CellKind.WeightPlate)
            {
                return weightPlateCondition[x, y];
            }

            if (cells[x, y] == CellKind.CritterSensor)
            {
                return critterSensorCondition[x, y];
            }

            return cells[x, y] == CellKind.AtmoSensor ? atmoSensorCondition[x, y] : ThresholdSensorCondition.AboveOrEqual;
        }

        private bool ThresholdSensorConditionMatches(float value, float threshold, ThresholdSensorCondition condition)
        {
            return condition == ThresholdSensorCondition.BelowOrEqual ? value <= threshold : value >= threshold;
        }

        private bool CritterSensorSignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.CritterSensor &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                ThresholdSensorConditionMatches(CountCrittersForSensor(new Vector2Int(x, y)), CritterSensorThresholdAt(x, y), ThresholdSensorConditionAt(x, y));
        }

        private int CountCrittersForSensor(Vector2Int center)
        {
            RoomInfo room = RoomAt(center.x, center.y);
            bool useRoomScope = room != null && room.Enclosed && room.Kind != RoomKind.OpenArea;
            int count = 0;

            for (int i = 0; i < hatches.Count; i++)
            {
                if (IsCritterSensorCellInScope(center, room, useRoomScope, hatches[i].Cell))
                {
                    count++;
                }
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsCritterSensorCellInScope(center, room, useRoomScope, new Vector2Int(x, y)))
                    {
                        continue;
                    }

                    if (looseResourceKind[x, y] == LooseResourceKind.HatchEgg && looseResourceAmount[x, y] > 0.001f)
                    {
                        count++;
                    }

                    if (cells[x, y] == CellKind.Incubator && incubatorEggLoaded[x, y])
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsCritterSensorCellInScope(Vector2Int center, RoomInfo room, bool useRoomScope, Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (useRoomScope)
            {
                EnsureRooms();
                return roomIds[cell.x, cell.y] == room.Id;
            }

            return Mathf.Abs(cell.x - center.x) + Mathf.Abs(cell.y - center.y) <= CritterSensorRange;
        }

        private bool IsAutomationWireTouchingSmartBattery(int x, int y)
        {
            return IsSmartBatteryCell(x, y) ||
                IsSmartBatteryCell(x + 1, y) ||
                IsSmartBatteryCell(x - 1, y) ||
                IsSmartBatteryCell(x, y + 1) ||
                IsSmartBatteryCell(x, y - 1);
        }

        private bool IsSmartBatteryCell(int x, int y)
        {
            return IsInside(x, y) && cells[x, y] == CellKind.SmartBattery;
        }

        private bool SmartBatterySignalActive(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.SmartBattery &&
                CanUseEquipment(new Vector2Int(x, y)) &&
                UpdateSmartBatterySignalState(x, y);
        }

        private bool UpdateSmartBatterySignalState(int x, int y)
        {
            float charge = maxPower <= 0.001f ? 0f : Mathf.Clamp01(power / maxPower);
            if (charge <= SmartBatteryLowThresholdAt(x, y))
            {
                smartBatterySignalState[x, y] = true;
            }
            else if (charge >= SmartBatteryHighThresholdAt(x, y))
            {
                smartBatterySignalState[x, y] = false;
            }

            return smartBatterySignalState[x, y];
        }

        private float SmartBatteryLowThresholdAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return SmartBatteryLowThreshold;
            }

            return Mathf.Clamp(
                smartBatteryLowThreshold[x, y] <= 0.001f ? SmartBatteryLowThreshold : smartBatteryLowThreshold[x, y],
                SmartBatteryThresholdMin,
                SmartBatteryThresholdMax - SmartBatteryThresholdMinGap);
        }

        private float SmartBatteryHighThresholdAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return SmartBatteryHighThreshold;
            }

            float lowThreshold = SmartBatteryLowThresholdAt(x, y);
            return Mathf.Clamp(
                smartBatteryHighThreshold[x, y] <= 0.001f ? SmartBatteryHighThreshold : smartBatteryHighThreshold[x, y],
                lowThreshold + SmartBatteryThresholdMinGap,
                SmartBatteryThresholdMax);
        }

        private float HighestSmartBatteryLowThreshold()
        {
            float threshold = SmartBatteryLowThreshold;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.SmartBattery && HasAutomationWireAccess(new Vector2Int(x, y)))
                    {
                        threshold = Mathf.Max(threshold, SmartBatteryLowThresholdAt(x, y));
                    }
                }
            }

            return threshold;
        }

        private bool AnySignalSwitchLinked()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.SignalSwitch && HasAutomationWireAccess(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyUsableSignalSwitchLinked()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.SignalSwitch &&
                        CanUseEquipment(cell) &&
                        HasAutomationWireAccess(cell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnySignalSwitchGreen()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (SignalSwitchSignalActive(x, y))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyClosedAirlock()
        {
            return CountClosedAirlocks() > 0;
        }

        private int CountAirlocks()
        {
            return CountCells(CellKind.ManualAirlock) + CountCells(CellKind.MechanizedAirlock);
        }

        private int CountClosedMechanizedAirlocks()
        {
            UpdateAutomationWires();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsMechanizedAirlockClosedByCachedAutomation(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountPressureControlledClosedAirlocks()
        {
            UpdateAutomationWires();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if ((cells[x, y] == CellKind.ManualAirlock && !airlockOpen[x, y]) ||
                        IsMechanizedAirlockClosedByCachedAutomation(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool HasAutomationControl(Vector2Int cell)
        {
            UpdateAutomationWires();
            return HasCachedAutomationControl(cell);
        }

        private bool HasAutomationSignal(Vector2Int cell)
        {
            UpdateAutomationWires();
            return HasCachedAutomationSignal(cell);
        }

        private bool HasCachedAutomationControl(Vector2Int cell)
        {
            return IsAutomationWireCell(cell.x, cell.y, true, false) ||
                IsAutomationWireCell(cell.x + 1, cell.y, true, false) ||
                IsAutomationWireCell(cell.x - 1, cell.y, true, false) ||
                IsAutomationWireCell(cell.x, cell.y + 1, true, false) ||
                IsAutomationWireCell(cell.x, cell.y - 1, true, false);
        }

        private bool HasCachedAutomationSignal(Vector2Int cell)
        {
            return IsAutomationWireCell(cell.x, cell.y, true, true) ||
                IsAutomationWireCell(cell.x + 1, cell.y, true, true) ||
                IsAutomationWireCell(cell.x - 1, cell.y, true, true) ||
                IsAutomationWireCell(cell.x, cell.y + 1, true, true) ||
                IsAutomationWireCell(cell.x, cell.y - 1, true, true);
        }

        private bool IsAutomationWireCell(int x, int y, bool requireControlled, bool requireSignal)
        {
            if (!IsInside(x, y) || !automationWire[x, y])
            {
                return false;
            }

            if (requireControlled && !automationControlledWire[x, y])
            {
                return false;
            }

            return !requireSignal || automationSignalWire[x, y];
        }

        private bool CanGeneratorOperate(Vector2Int cell)
        {
            if (!CanUseEquipment(cell) || !HasWireAccess(cell) || power >= maxPower - 4f)
            {
                return false;
            }

            if (!HasAutomationControl(cell))
            {
                return true;
            }

            return HasAutomationSignal(cell);
        }

        private void AddPoweredWireNeighbor(int x, int y, Queue<Vector2Int> frontier)
        {
            if (!IsInside(x, y) || !powerWire[x, y] || poweredWire[x, y] || IsPowerShutoffBlockingWire(x, y))
            {
                return;
            }

            poweredWire[x, y] = true;
            frontier.Enqueue(new Vector2Int(x, y));
        }

        private bool IsPowerShutoffBlockingWire(int x, int y)
        {
            return IsInside(x, y) &&
                cells[x, y] == CellKind.PowerShutoff &&
                !IsPowerShutoffOpen(new Vector2Int(x, y));
        }

        private bool IsPowerShutoffOpen(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.PowerShutoff)
            {
                return true;
            }

            if (!CanUseEquipment(cell))
            {
                return false;
            }

            return AutomationPortAllows(cell);
        }

        private bool IsWireTouchingPowerInfrastructure(int x, int y)
        {
            return IsPowerInfrastructureCell(x, y) ||
                IsPowerInfrastructureCell(x + 1, y) ||
                IsPowerInfrastructureCell(x - 1, y) ||
                IsPowerInfrastructureCell(x, y + 1) ||
                IsPowerInfrastructureCell(x, y - 1);
        }

        private bool IsPowerInfrastructureCell(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            return cells[x, y] == CellKind.ManualGenerator || cells[x, y] == CellKind.CoalGenerator || cells[x, y] == CellKind.HydrogenGenerator || cells[x, y] == CellKind.NaturalGasGenerator || cells[x, y] == CellKind.PetroleumGenerator || cells[x, y] == CellKind.SteamTurbine || cells[x, y] == CellKind.SolarPanel || cells[x, y] == CellKind.ResearchReactor || cells[x, y] == CellKind.Battery || cells[x, y] == CellKind.JumboBattery || cells[x, y] == CellKind.SmartBattery;
        }

        private bool HasWireAccess(Vector2Int cell)
        {
            return HasWireNear(cell, false);
        }

        private bool HasAutomationWireAccess(Vector2Int cell)
        {
            return IsAutomationWireRaw(cell.x, cell.y) ||
                IsAutomationWireRaw(cell.x + 1, cell.y) ||
                IsAutomationWireRaw(cell.x - 1, cell.y) ||
                IsAutomationWireRaw(cell.x, cell.y + 1) ||
                IsAutomationWireRaw(cell.x, cell.y - 1);
        }

        private bool IsAutomationWireRaw(int x, int y)
        {
            return IsInside(x, y) && automationWire[x, y];
        }

        private bool HasPoweredCircuit(Vector2Int cell)
        {
            return power > 0.05f && HasWireNear(cell, true);
        }

        private bool CanPoweredMachineRun(Vector2Int cell)
        {
            return CanUseEquipment(cell) &&
                HasPoweredCircuit(cell) &&
                MachineAutomationAllows(cell);
        }

        private bool MachineAutomationAllows(Vector2Int cell)
        {
            return !HasCachedAutomationControl(cell) || HasCachedAutomationSignal(cell);
        }

        private bool AutomationPortAllows(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && (!HasCachedAutomationControl(cell) || HasCachedAutomationSignal(cell));
        }

        private string MachineAutomationStateText(Vector2Int cell)
        {
            UpdateAutomationWires();
            if (!RequiresPower(cells[cell.x, cell.y]))
            {
                return string.Empty;
            }

            if (!HasCachedAutomationControl(cell))
            {
                return "Automation: no signal, defaults enabled.";
            }

            return HasCachedAutomationSignal(cell)
                ? "Automation: green signal, machine enabled."
                : "Automation: red signal, machine disabled.";
        }

        private bool HasWireNear(Vector2Int cell, bool requirePowered)
        {
            return IsWireCell(cell.x, cell.y, requirePowered) ||
                IsWireCell(cell.x + 1, cell.y, requirePowered) ||
                IsWireCell(cell.x - 1, cell.y, requirePowered) ||
                IsWireCell(cell.x, cell.y + 1, requirePowered) ||
                IsWireCell(cell.x, cell.y - 1, requirePowered);
        }

        private bool IsWireCell(int x, int y, bool requirePowered)
        {
            if (!IsInside(x, y) || !powerWire[x, y])
            {
                return false;
            }

            return !requirePowered || poweredWire[x, y];
        }

        private bool RequiresPower(CellKind kind)
        {
            return kind == CellKind.OxygenDiffuser ||
                kind == CellKind.AirDeodorizer ||
                kind == CellKind.ResearchStation ||
                kind == CellKind.MicrobeMusher ||
                kind == CellKind.ElectricGrill ||
                kind == CellKind.Apothecary ||
                kind == CellKind.RockCrusher ||
                kind == CellKind.AtmoSuitDock ||
                kind == CellKind.GasPump ||
                kind == CellKind.Electrolyzer ||
                kind == CellKind.CarbonSkimmer ||
                kind == CellKind.WaterSieve ||
                kind == CellKind.Desalinator ||
                kind == CellKind.FertilizerSynthesizer ||
                kind == CellKind.MetalRefinery ||
                kind == CellKind.OilRefinery ||
                kind == CellKind.OilWell ||
                kind == CellKind.EthanolDistiller ||
                kind == CellKind.TextileLoom ||
                kind == CellKind.PolymerPress ||
                kind == CellKind.RocketPlatform ||
                kind == CellKind.OrbitalDataBank ||
                kind == CellKind.RadboltCollector ||
                kind == CellKind.VentAnalyzer ||
                kind == CellKind.HydrogenFilter ||
                kind == CellKind.GasFilter ||
                kind == CellKind.SourGasCondenser ||
                kind == CellKind.LiquidFilter ||
                kind == CellKind.ThermoAquatuner ||
                kind == CellKind.SpaceScanner ||
                kind == CellKind.Refrigerator ||
                kind == CellKind.AutoSweeper ||
                kind == CellKind.ConveyorLoader ||
                kind == CellKind.Incubator ||
                kind == CellKind.CeilingLight ||
                kind == CellKind.SkillScrubber ||
                kind == CellKind.ArcadeCabinet ||
                kind == CellKind.SpaceHeater ||
                kind == CellKind.LiquidTepidizer ||
                kind == CellKind.ThermoRegulator;
        }

        private void RenderTerrain()
        {
            UpdateAutomationWires();
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    terrainTexture.SetPixel(x, y, TerrainColor(x, y, cells[x, y]));
                }
            }

            terrainTexture.Apply(false, false);
            terrainDirty = false;
        }

        private void RenderGas()
        {
            UpdatePoweredWires();
            UpdateAutomationWires();
            UpdatePowerLoad(0f, false);

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    gasTexture.SetPixel(x, y, OverlayColor(x, y));
                }
            }

            gasTexture.Apply(false, false);
            gasDirty = false;
        }

        private void RenderOverlay()
        {
            UpdateAutomationWires();
            Color clear = new Color(0f, 0f, 0f, 0f);
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    overlayTexture.SetPixel(x, y, clear);
                }
            }

            if (currentOverlayMode == OverlayMode.Power ||
                currentMode == CommandMode.PowerWire ||
                currentMode == CommandMode.ConductiveWire ||
                currentMode == CommandMode.HeavyWattWire ||
                currentMode == CommandMode.PowerBridge ||
                currentMode == CommandMode.PowerShutoff)
            {
                UpdatePoweredWires();
                UpdateAutomationWires();
                UpdatePowerLoad(0f, false);
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        if (powerWire[x, y])
                        {
                            overlayTexture.SetPixel(x, y, PowerWireOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.PowerBridge)
                        {
                            overlayTexture.SetPixel(x, y, PowerBridgeOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.PowerShutoff)
                        {
                            overlayTexture.SetPixel(x, y, PowerShutoffOverlayColor(x, y));
                        }
                    }
                }
            }

            if (currentOverlayMode == OverlayMode.Power ||
                currentOverlayMode == OverlayMode.Automation ||
                currentMode == CommandMode.AutomationWire ||
                currentMode == CommandMode.AutomationBridge ||
                currentMode == CommandMode.AutomationNotGate ||
                currentMode == CommandMode.AutomationAndGate ||
                currentMode == CommandMode.AutomationOrGate ||
                currentMode == CommandMode.AutomationXorGate ||
                currentMode == CommandMode.AutomationBufferGate ||
                currentMode == CommandMode.AutomationFilterGate ||
                currentMode == CommandMode.AutomationMemoryGate ||
                currentMode == CommandMode.AutomationCycleSensor ||
                currentMode == CommandMode.AutomationTimerSensor ||
                currentMode == CommandMode.DuplicantMotionSensor ||
                currentMode == CommandMode.PowerShutoff ||
                currentMode == CommandMode.SignalSwitch ||
                currentMode == CommandMode.AtmoSensor ||
                currentMode == CommandMode.ThermoSensor ||
                currentMode == CommandMode.HydroSensor ||
                currentMode == CommandMode.GermSensor ||
                currentMode == CommandMode.WeightPlate ||
                currentMode == CommandMode.ShippingRailSensor ||
                currentMode == CommandMode.ShippingRailShutoff ||
                currentMode == CommandMode.ShippingRailMeter)
            {
                UpdateAutomationWires();
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        if (automationWire[x, y])
                        {
                            overlayTexture.SetPixel(x, y, automationControlledWire[x, y]
                                ? automationSignalWire[x, y] ? new Color(0.28f, 1f, 0.32f, 0.72f) : new Color(1f, 0.18f, 0.10f, 0.66f)
                                : new Color(0.52f, 0.42f, 0.85f, 0.42f));
                        }
                        else if (cells[x, y] == CellKind.AutomationBridge)
                        {
                            overlayTexture.SetPixel(x, y, AutomationBridgeOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationNotGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationNotGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationAndGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationAndGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationOrGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationOrGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationXorGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationXorGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationBufferGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationBufferGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationFilterGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationFilterGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationMemoryGate)
                        {
                            overlayTexture.SetPixel(x, y, AutomationMemoryGateOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationCycleSensor)
                        {
                            overlayTexture.SetPixel(x, y, AutomationCycleSensorOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.AutomationTimerSensor)
                        {
                            overlayTexture.SetPixel(x, y, AutomationTimerSensorOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.DuplicantMotionSensor)
                        {
                            overlayTexture.SetPixel(x, y, DuplicantMotionSensorOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.PowerShutoff)
                        {
                            overlayTexture.SetPixel(x, y, PowerShutoffOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.SignalSwitch)
                        {
                            overlayTexture.SetPixel(x, y, SignalSwitchSignalActive(x, y) ? new Color(0.28f, 1f, 0.32f, 0.68f) : new Color(1f, 0.18f, 0.10f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.AtmoSensor)
                        {
                            overlayTexture.SetPixel(x, y, AtmoSensorSignalActive(x, y) ? new Color(0.28f, 1f, 0.32f, 0.68f) : new Color(1f, 0.20f, 0.12f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.ThermoSensor)
                        {
                            overlayTexture.SetPixel(x, y, ThermoSensorSignalActive(x, y) ? new Color(0.28f, 1f, 0.32f, 0.68f) : new Color(1f, 0.20f, 0.12f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.HydroSensor)
                        {
                            overlayTexture.SetPixel(x, y, HydroSensorSignalActive(x, y) ? new Color(0.28f, 1f, 0.32f, 0.68f) : new Color(1f, 0.20f, 0.12f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.GermSensor)
                        {
                            overlayTexture.SetPixel(x, y, GermSensorSignalActive(x, y) ? new Color(0.28f, 1f, 0.32f, 0.68f) : new Color(1f, 0.20f, 0.12f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.WeightPlate)
                        {
                            overlayTexture.SetPixel(x, y, WeightPlateSignalActive(x, y) ? new Color(0.28f, 1f, 0.32f, 0.68f) : new Color(1f, 0.20f, 0.12f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.ShippingRailSensor)
                        {
                            overlayTexture.SetPixel(x, y, ShippingRailSensorOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.ShippingRailShutoff)
                        {
                            overlayTexture.SetPixel(x, y, ShippingRailShutoffOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.ShippingRailMeter)
                        {
                            overlayTexture.SetPixel(x, y, ShippingRailMeterOverlayColor(x, y));
                        }
                    }
                }
            }

            if (currentOverlayMode == OverlayMode.Plumbing ||
                currentMode == CommandMode.LiquidPipe ||
                currentMode == CommandMode.RadiantLiquidPipe ||
                currentMode == CommandMode.InsulatedLiquidPipe ||
                currentMode == CommandMode.LiquidBridge ||
                currentMode == CommandMode.LiquidPipeSensor ||
                currentMode == CommandMode.LiquidShutoff ||
                currentMode == CommandMode.LiquidValve ||
                currentMode == CommandMode.LiquidFilter ||
                currentMode == CommandMode.LiquidReservoir ||
                currentMode == CommandMode.BottleEmptier)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        if (cells[x, y] == CellKind.LiquidPipeSensor)
                        {
                            overlayTexture.SetPixel(x, y, LiquidSensorSignalActive(x, y) ? new Color(0.26f, 1f, 0.38f, 0.80f) : new Color(1f, 0.20f, 0.12f, 0.72f));
                        }
                        else if (cells[x, y] == CellKind.LiquidShutoff)
                        {
                            overlayTexture.SetPixel(x, y, IsConduitShutoffOpen(new Vector2Int(x, y)) ? new Color(0.30f, 0.95f, 1f, 0.78f) : new Color(1f, 0.18f, 0.12f, 0.78f));
                        }
                        else if (cells[x, y] == CellKind.LiquidValve)
                        {
                            overlayTexture.SetPixel(x, y, IsConduitValveOpen(new Vector2Int(x, y)) ? new Color(0.12f, 0.96f, 0.72f, 0.78f) : new Color(1f, 0.18f, 0.12f, 0.78f));
                        }
                        else if (cells[x, y] == CellKind.LiquidFilter)
                        {
                            overlayTexture.SetPixel(x, y, TryFindAdjacentLiquidPipeWithFilterLiquid(new Vector2Int(x, y), liquidFilterMode[x, y], out _) ? new Color(0.16f, 0.92f, 0.64f, 0.78f) : new Color(0.24f, 0.48f, 0.50f, 0.62f));
                        }
                        else if (cells[x, y] == CellKind.LiquidBridge)
                        {
                            overlayTexture.SetPixel(x, y, new Color(0.02f, 0.88f, 1f, 0.72f));
                        }
                        else if (liquidPipe[x, y])
                        {
                            overlayTexture.SetPixel(x, y, LiquidPipeOverlayColor(x, y, 0.08f));
                        }
                        else if (cells[x, y] == CellKind.LiquidReservoir)
                        {
                            float fill = Mathf.Clamp01(LiquidReservoirTotal(x, y) / LiquidReservoirCapacity);
                            float pollutedShare = LiquidReservoirPollutedShare(x, y);
                            overlayTexture.SetPixel(x, y, new Color(0.08f + pollutedShare * 0.06f, 0.58f + fill * 0.30f, 1f - pollutedShare * 0.58f, 0.34f + fill * 0.48f));
                        }
                        else if (cells[x, y] == CellKind.BottleEmptier)
                        {
                            overlayTexture.SetPixel(x, y, CanEmptyBottleAt(new Vector2Int(x, y)) ? new Color(0.10f, 0.92f, 0.86f, 0.72f) : new Color(0.42f, 0.54f, 0.56f, 0.54f));
                        }
                    }
                }
            }

            if (currentOverlayMode == OverlayMode.Ventilation ||
                currentMode == CommandMode.GasPipe ||
                currentMode == CommandMode.GasBridge ||
                currentMode == CommandMode.GasPipeSensor ||
                currentMode == CommandMode.GasShutoff ||
                currentMode == CommandMode.GasValve ||
                currentMode == CommandMode.GasReservoir ||
                currentMode == CommandMode.HighPressureGasVent)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        if (cells[x, y] == CellKind.GasPipeSensor)
                        {
                            overlayTexture.SetPixel(x, y, GasSensorSignalActive(x, y) ? new Color(0.28f, 1f, 0.36f, 0.80f) : new Color(1f, 0.20f, 0.12f, 0.72f));
                        }
                        else if (cells[x, y] == CellKind.GasShutoff)
                        {
                            overlayTexture.SetPixel(x, y, IsConduitShutoffOpen(new Vector2Int(x, y)) ? new Color(0.52f, 0.96f, 1f, 0.78f) : new Color(1f, 0.18f, 0.12f, 0.78f));
                        }
                        else if (cells[x, y] == CellKind.GasValve)
                        {
                            overlayTexture.SetPixel(x, y, IsConduitValveOpen(new Vector2Int(x, y)) ? new Color(0.72f, 0.98f, 0.86f, 0.78f) : new Color(1f, 0.18f, 0.12f, 0.78f));
                        }
                        else if (cells[x, y] == CellKind.GasBridge)
                        {
                            overlayTexture.SetPixel(x, y, new Color(0.58f, 0.92f, 1f, 0.72f));
                        }
                        else if (gasPipe[x, y])
                        {
                            overlayTexture.SetPixel(x, y, GasPipeOverlayColor(x, y));
                        }
                        else if (cells[x, y] == CellKind.GasReservoir)
                        {
                            float fill = Mathf.Clamp01(GasReservoirTotal(x, y) / GasReservoirCapacity);
                            overlayTexture.SetPixel(x, y, new Color(0.45f, 0.92f, 1f, 0.32f + fill * 0.48f));
                        }
                        else if (cells[x, y] == CellKind.HighPressureGasVent)
                        {
                            overlayTexture.SetPixel(x, y, new Color(0.24f, 0.98f, 0.86f, 0.76f));
                        }
                    }
                }
            }

            if (currentOverlayMode == OverlayMode.Logistics ||
                currentMode == CommandMode.ShippingRail ||
                currentMode == CommandMode.ShippingBridge ||
                currentMode == CommandMode.ConveyorLoader ||
                currentMode == CommandMode.ConveyorReceptacle ||
                currentMode == CommandMode.ShippingRailSensor ||
                currentMode == CommandMode.ShippingRailShutoff ||
                currentMode == CommandMode.ShippingRailMeter ||
                currentMode == CommandMode.ConveyorChute)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Color color = LogisticsOverlayColor(x, y);
                        if (color.a > 0f)
                        {
                            overlayTexture.SetPixel(x, y, color);
                        }
                    }
                }
            }

            if (currentOverlayMode == OverlayMode.Radiation)
            {
                for (int y = 0; y < WorldHeight; y++)
                {
                    for (int x = 0; x < WorldWidth; x++)
                    {
                        Color color = RadiationOverlayColor(x, y);
                        if (color.a > 0f)
                        {
                            overlayTexture.SetPixel(x, y, color);
                        }
                    }
                }
            }

            foreach (Job job in jobs)
            {
                Color color = currentOverlayMode == OverlayMode.Errands ? ErrandOverlayColor(job) : JobOverlayColor(job);
                overlayTexture.SetPixel(job.Cell.x, job.Cell.y, color);
            }

            if (currentOverlayMode == OverlayMode.Vitals)
            {
                RenderVitalsWorkerOverlay();
            }
            else if (currentOverlayMode == OverlayMode.Errands)
            {
                RenderErrandWorkerOverlay();
            }

            if (inspectedCell.HasValue)
            {
                Vector2Int cell = inspectedCell.Value;
                if (IsInside(cell.x, cell.y))
                {
                    overlayTexture.SetPixel(cell.x, cell.y, new Color(1f, 1f, 1f, 0.42f));
                }
            }

            overlayTexture.Apply(false, false);
            overlayDirty = false;
        }

        private void RenderVitalsWorkerOverlay()
        {
            foreach (Worker worker in workers)
            {
                if (worker == null || !IsInside(worker.Cell.x, worker.Cell.y))
                {
                    continue;
                }

                Color color = WorkerVitalsOverlayColor(worker);
                overlayTexture.SetPixel(worker.Cell.x, worker.Cell.y, color);

                Color halo = color;
                halo.a *= 0.45f;
                SetVitalsHaloPixel(worker.Cell.x + 1, worker.Cell.y, halo);
                SetVitalsHaloPixel(worker.Cell.x - 1, worker.Cell.y, halo);
                SetVitalsHaloPixel(worker.Cell.x, worker.Cell.y + 1, halo);
                SetVitalsHaloPixel(worker.Cell.x, worker.Cell.y - 1, halo);
            }
        }

        private void SetVitalsHaloPixel(int x, int y, Color color)
        {
            if (IsInside(x, y))
            {
                overlayTexture.SetPixel(x, y, color);
            }
        }

        private void RenderErrandWorkerOverlay()
        {
            foreach (Worker worker in workers)
            {
                if (worker == null || !IsInside(worker.Cell.x, worker.Cell.y))
                {
                    continue;
                }

                Color color = ErrandWorkerOverlayColor(worker);
                overlayTexture.SetPixel(worker.Cell.x, worker.Cell.y, color);

                Color halo = color;
                halo.a *= 0.40f;
                SetErrandHaloPixel(worker.Cell.x + 1, worker.Cell.y, halo);
                SetErrandHaloPixel(worker.Cell.x - 1, worker.Cell.y, halo);
                SetErrandHaloPixel(worker.Cell.x, worker.Cell.y + 1, halo);
                SetErrandHaloPixel(worker.Cell.x, worker.Cell.y - 1, halo);
            }
        }

        private void SetErrandHaloPixel(int x, int y, Color color)
        {
            if (IsInside(x, y))
            {
                overlayTexture.SetPixel(x, y, color);
            }
        }

        private Color TerrainColor(int x, int y, CellKind kind)
        {
            float variation = ((x * 31 + y * 17) % 11) / 100f;
            if (IsBrokenEquipment(new Vector2Int(x, y)))
            {
                return new Color(0.72f, 0.12f, 0.10f, 1f);
            }

            if (IsRepairableEquipment(kind) && equipmentCondition[x, y] <= EquipmentAutoRepairThreshold)
            {
                return new Color(0.92f, 0.46f, 0.18f, 1f);
            }

            if (kind == CellKind.Empty && looseResourceKind[x, y] != LooseResourceKind.None && looseResourceAmount[x, y] > 0.05f)
            {
                return LooseResourceColor(looseResourceKind[x, y]);
            }

            switch (kind)
            {
                case CellKind.Empty:
                    return new Color(0.035f, 0.042f + y * 0.0008f, 0.055f + y * 0.001f, 1f);
                case CellKind.Dirt:
                    return new Color(0.38f + variation, 0.25f + variation * 0.5f, 0.14f, 1f);
                case CellKind.Rock:
                    return new Color(0.30f + variation, 0.32f + variation, 0.34f + variation, 1f);
                case CellKind.Sand:
                    return new Color(0.66f + variation, 0.56f + variation, 0.31f, 1f);
                case CellKind.Regolith:
                    return new Color(0.58f + variation * 0.4f, 0.55f + variation * 0.35f, 0.50f + variation * 0.25f, 1f);
                case CellKind.Magma:
                    return new Color(1f, 0.18f + variation * 1.8f, 0.03f, 1f);
                case CellKind.MetalOre:
                    return new Color(0.32f, 0.45f + variation, 0.50f + variation, 1f);
                case CellKind.Algae:
                    return new Color(0.26f, 0.54f + variation, 0.24f, 1f);
                case CellKind.Coal:
                    return new Color(0.10f + variation * 0.25f, 0.105f + variation * 0.18f, 0.095f + variation * 0.12f, 1f);
                case CellKind.Slime:
                    return new Color(0.18f, 0.46f + variation, 0.30f, 1f);
                case CellKind.BleachStone:
                    return new Color(0.78f + variation * 0.20f, 0.86f + variation * 0.15f, 0.70f, 1f);
                case CellKind.Ice:
                    return new Color(0.62f, 0.88f + variation * 0.3f, 0.98f, 1f);
                case CellKind.Ladder:
                    return new Color(0.78f, 0.64f, 0.35f, 1f);
                case CellKind.FirePole:
                    return new Color(0.86f, 0.52f, 0.20f, 1f);
                case CellKind.Floor:
                    return new Color(0.48f, 0.50f, 0.52f, 1f);
                case CellKind.OxygenDiffuser:
                    return new Color(0.55f, 0.84f, 0.92f, 1f);
                case CellKind.AlgaeTerrarium:
                    return CanAlgaeTerrariumRun(new Vector2Int(x, y)) ? new Color(0.38f, 0.86f, 0.46f, 1f) : new Color(0.28f, 0.48f, 0.30f, 1f);
                case CellKind.ManualGenerator:
                    return new Color(0.92f, 0.55f, 0.25f, 1f);
                case CellKind.Battery:
                    return new Color(0.94f, 0.82f, 0.26f, 1f);
                case CellKind.JumboBattery:
                    return power > maxPower * 0.55f ? new Color(1f, 0.74f, 0.20f, 1f) : new Color(0.58f, 0.44f, 0.20f, 1f);
                case CellKind.SmartBattery:
                    return SmartBatterySignalActive(x, y) ? new Color(0.38f, 0.92f, 0.36f, 1f) : new Color(0.92f, 0.36f, 0.26f, 1f);
                case CellKind.PowerTransformer:
                    return new Color(0.28f, 0.76f, 0.96f, 1f);
                case CellKind.PowerControlStation:
                    return new Color(0.30f, 0.88f, 0.78f, 1f);
                case CellKind.SkillScrubber:
                    return CanPoweredMachineRun(new Vector2Int(x, y)) ? new Color(0.78f, 0.54f, 1f, 1f) : new Color(0.38f, 0.28f, 0.48f, 1f);
                case CellKind.PowerBridge:
                    return new Color(1f, 0.78f, 0.22f, 1f);
                case CellKind.PowerShutoff:
                    return IsPowerShutoffOpen(new Vector2Int(x, y)) ? new Color(0.96f, 0.76f, 0.18f, 1f) : new Color(0.78f, 0.22f, 0.18f, 1f);
                case CellKind.CoalGenerator:
                    return CanCoalGeneratorRun(new Vector2Int(x, y)) ? new Color(0.98f, 0.62f, 0.20f, 1f) : new Color(0.43f, 0.32f, 0.24f, 1f);
                case CellKind.HydrogenGenerator:
                    return CanHydrogenGeneratorRun(new Vector2Int(x, y)) ? new Color(0.82f, 0.42f, 1f, 1f) : new Color(0.38f, 0.25f, 0.48f, 1f);
                case CellKind.NaturalGasGenerator:
                    return CanNaturalGasGeneratorRun(new Vector2Int(x, y)) ? new Color(1f, 0.70f, 0.26f, 1f) : new Color(0.48f, 0.30f, 0.16f, 1f);
                case CellKind.PetroleumGenerator:
                    return CanPetroleumGeneratorRun(new Vector2Int(x, y)) ? new Color(0.90f, 0.58f, 0.22f, 1f) : new Color(0.42f, 0.28f, 0.16f, 1f);
                case CellKind.SteamTurbine:
                    return CanSteamTurbineRun(new Vector2Int(x, y)) ? new Color(0.62f, 0.94f, 1f, 1f) : new Color(0.36f, 0.50f, 0.58f, 1f);
                case CellKind.ResearchReactor:
                    return CanResearchReactorRun(new Vector2Int(x, y)) ? new Color(0.86f, 0.34f, 1f, 1f) : new Color(0.34f, 0.18f, 0.42f, 1f);
                case CellKind.RadboltCollector:
                    return CanRadboltCollectorRun(new Vector2Int(x, y)) ? new Color(0.28f, 1f, 0.86f, 1f) : new Color(0.18f, 0.36f, 0.42f, 1f);
                case CellKind.SolarPanel:
                    return CanSolarPanelRun(new Vector2Int(x, y)) ? new Color(1f, 0.92f, 0.22f, 1f) : IsSolarPanelSkyExposed(new Vector2Int(x, y)) ? new Color(0.42f, 0.54f, 0.64f, 1f) : new Color(0.22f, 0.26f, 0.30f, 1f);
                case CellKind.BunkerDoor:
                    return IsBunkerDoorClosed(new Vector2Int(x, y)) ? new Color(0.24f, 0.32f, 0.36f, 1f) : new Color(0.58f, 0.68f, 0.72f, 1f);
                case CellKind.SpaceScanner:
                    return SpaceScannerSignalActive(x, y) ? new Color(0.48f, 1f, 0.82f, 1f) : IsSpaceScannerSkyExposed(new Vector2Int(x, y)) ? new Color(0.34f, 0.64f, 0.86f, 1f) : new Color(0.22f, 0.28f, 0.34f, 1f);
                case CellKind.VentAnalyzer:
                    return AllNaturalVentsAnalyzed() ? new Color(0.24f, 0.86f, 0.72f, 1f) : CanVentAnalyzerRun(new Vector2Int(x, y)) ? new Color(0.40f, 0.94f, 0.82f, 1f) : new Color(0.22f, 0.38f, 0.42f, 1f);
                case CellKind.RocketPlatform:
                    return CanRocketPlatformRun(new Vector2Int(x, y)) ? new Color(1f, 0.48f, 0.24f, 1f) : IsRocketPlatformSkyExposed(new Vector2Int(x, y)) ? new Color(0.66f, 0.46f, 0.36f, 1f) : new Color(0.25f, 0.24f, 0.28f, 1f);
                case CellKind.OrbitalDataBank:
                    return CanOrbitalDataBankRun(new Vector2Int(x, y)) ? new Color(0.42f, 0.96f, 1f, 1f) : orbitalData > 0.001f ? new Color(0.28f, 0.56f, 0.72f, 1f) : new Color(0.20f, 0.32f, 0.42f, 1f);
                case CellKind.HydrogenFilter:
                    return TryFindAdjacentMixedHydrogenPipe(new Vector2Int(x, y), out _) ? new Color(0.88f, 0.50f, 1f, 1f) : new Color(0.46f, 0.34f, 0.56f, 1f);
                case CellKind.GasFilter:
                    return TryFindAdjacentGasPipeWithFilterGas(new Vector2Int(x, y), gasFilterMode[x, y], out _) ? new Color(0.78f, 0.88f, 0.46f, 1f) : new Color(0.40f, 0.48f, 0.32f, 1f);
                case CellKind.SourGasCondenser:
                    return CanSourGasCondenserRun(new Vector2Int(x, y)) ? new Color(0.90f, 0.76f, 0.30f, 1f) : new Color(0.44f, 0.36f, 0.22f, 1f);
                case CellKind.LiquidFilter:
                    return TryFindAdjacentLiquidPipeWithFilterLiquid(new Vector2Int(x, y), liquidFilterMode[x, y], out _) ? new Color(0.16f, 0.84f, 0.70f, 1f) : new Color(0.18f, 0.44f, 0.46f, 1f);
                case CellKind.RockCrusher:
                    return new Color(0.64f, 0.58f, 0.50f, 1f);
                case CellKind.OxygenMaskDock:
                    return CanUseEquipment(new Vector2Int(x, y)) && maskOxygen > 0.12f ? new Color(0.62f, 0.92f, 0.62f, 1f) : new Color(0.34f, 0.46f, 0.36f, 1f);
                case CellKind.OxygenMaskCheckpoint:
                    return IsOxygenMaskCheckpointCell(new Vector2Int(x, y)) && HasAdjacentOxygenMaskDock(new Vector2Int(x, y)) ? new Color(0.76f, 1f, 0.64f, 1f) : new Color(0.40f, 0.56f, 0.34f, 1f);
                case CellKind.LeadSuitLocker:
                    return CanUseEquipment(new Vector2Int(x, y)) && HasAdjacentLeadSuitCheckpoint(new Vector2Int(x, y)) ? new Color(0.62f, 0.68f, 0.82f, 1f) : new Color(0.34f, 0.36f, 0.46f, 1f);
                case CellKind.LeadSuitCheckpoint:
                    return IsLeadSuitCheckpointCell(new Vector2Int(x, y)) && HasAdjacentLeadSuitLocker(new Vector2Int(x, y)) ? new Color(0.78f, 0.78f, 0.56f, 1f) : new Color(0.46f, 0.42f, 0.30f, 1f);
                case CellKind.AtmoSuitDock:
                    return CanPoweredMachineRun(new Vector2Int(x, y)) && suitOxygen > 0.25f ? new Color(0.42f, 0.86f, 0.98f, 1f) : new Color(0.32f, 0.42f, 0.48f, 1f);
                case CellKind.AtmoSuitCheckpoint:
                    return IsSuitCheckpointCell(new Vector2Int(x, y)) && HasAdjacentSuitDock(new Vector2Int(x, y)) ? new Color(0.56f, 0.98f, 0.92f, 1f) : new Color(0.30f, 0.54f, 0.56f, 1f);
                case CellKind.InsulatedTile:
                    return new Color(0.50f, 0.58f, 0.62f, 1f);
                case CellKind.Tile:
                    return new Color(0.44f, 0.46f, 0.44f, 1f);
                case CellKind.AirflowTile:
                    return new Color(0.40f, 0.72f, 0.74f, 1f);
                case CellKind.MeshTile:
                    return waterMass[x, y] > 0.5f
                        ? IsPollutedWorldLiquidAt(x, y) ? new Color(0.16f, 0.56f, 0.42f, 1f) : new Color(0.20f, 0.58f, 0.86f, 1f)
                        : new Color(0.56f, 0.70f, 0.72f, 1f);
                case CellKind.PrintingPod:
                    return printingPodProgress >= 0.98f ? new Color(0.68f, 1f, 0.82f, 1f) : new Color(0.38f, 0.84f, 0.78f, 1f);
                case CellKind.Bed:
                    return new Color(0.45f, 0.65f, 0.92f, 1f);
                case CellKind.ComfyBed:
                    return new Color(0.64f, 0.78f, 1f, 1f);
                case CellKind.Planter:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.58f, 0.34f, 0.14f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.78f, 0.72f, 0.26f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f ? new Color(0.56f, 0.92f, 0.38f, 1f) : new Color(0.31f, 0.62f, 0.26f, 1f);
                case CellKind.HydroponicFarm:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.54f, 0.30f, 0.16f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.82f, 0.72f, 0.22f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(0.92f, 0.58f, 0.94f, 1f)
                        : HasCropIrrigation(new Vector2Int(x, y)) && IsCellLit(x, y) ? new Color(0.42f, 0.70f, 0.88f, 1f) : new Color(0.24f, 0.44f, 0.48f, 1f);
                case CellKind.FungalFarm:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.42f, 0.24f, 0.16f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.64f, 0.48f, 0.24f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(0.66f, 0.52f, 0.86f, 1f)
                        : HasCropIrrigation(new Vector2Int(x, y)) && !IsCellLit(x, y) && carbonDioxide[x, y] >= DuskCapCarbonDioxideThreshold ? new Color(0.34f, 0.28f, 0.50f, 1f) : new Color(0.22f, 0.20f, 0.30f, 1f);
                case CellKind.PepperPlant:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.46f, 0.20f, 0.12f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.86f, 0.50f, 0.18f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(1f, 0.28f, 0.18f, 1f)
                        : HasCropIrrigation(new Vector2Int(x, y)) && CropComfortableTemperature(CellKind.PepperPlant, temperature[x, y]) ? new Color(0.76f, 0.32f, 0.18f, 1f) : new Color(0.36f, 0.22f, 0.16f, 1f);
                case CellKind.GrubfruitPlant:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.42f, 0.24f, 0.12f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.86f, 0.66f, 0.20f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(0.98f, 0.86f, 0.24f, 1f)
                        : HasCropIrrigation(new Vector2Int(x, y)) && CropComfortableTemperature(CellKind.GrubfruitPlant, temperature[x, y]) ? new Color(0.54f, 0.78f, 0.24f, 1f) : new Color(0.30f, 0.40f, 0.16f, 1f);
                case CellKind.ThimbleReed:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.16f, 0.28f, 0.20f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.50f, 0.64f, 0.34f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(0.58f, 0.88f, 0.72f, 1f)
                        : HasCropIrrigation(new Vector2Int(x, y)) && CropComfortableTemperature(CellKind.ThimbleReed, temperature[x, y]) && CropAtmosphereSatisfied(CellKind.ThimbleReed, x, y) ? new Color(0.32f, 0.66f, 0.48f, 1f) : new Color(0.20f, 0.36f, 0.26f, 1f);
                case CellKind.SleetWheat:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.22f, 0.30f, 0.36f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.58f, 0.72f, 0.86f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(0.92f, 0.98f, 1f, 1f)
                        : HasCropIrrigation(new Vector2Int(x, y)) && CropComfortableTemperature(CellKind.SleetWheat, temperature[x, y]) && CropAtmosphereSatisfied(CellKind.SleetWheat, x, y) ? new Color(0.62f, 0.86f, 0.96f, 1f) : new Color(0.26f, 0.42f, 0.48f, 1f);
                case CellKind.ArborTree:
                    if (cropStress[x, y] >= CropWiltThresholdSeconds)
                    {
                        return new Color(0.34f, 0.20f, 0.10f, 1f);
                    }

                    if (cropStress[x, y] >= CropStressThresholdSeconds)
                    {
                        return new Color(0.70f, 0.54f, 0.18f, 1f);
                    }

                    return plantGrowth[x, y] >= 1f
                        ? new Color(0.58f, 0.88f, 0.36f, 1f)
                        : CropComfortableTemperature(CellKind.ArborTree, temperature[x, y]) && CropAtmosphereSatisfied(CellKind.ArborTree, x, y) ? new Color(0.38f, 0.64f, 0.26f, 1f) : new Color(0.26f, 0.34f, 0.18f, 1f);
                case CellKind.FarmStation:
                    return CountCropTendingTargets() > 0 ? new Color(0.82f, 0.96f, 0.42f, 1f) : new Color(0.48f, 0.64f, 0.26f, 1f);
                case CellKind.Water:
                    return new Color(0.06f, 0.31f, 0.86f + Mathf.Clamp01(waterMass[x, y] / 140f) * 0.08f, 1f);
                case CellKind.PollutedWater:
                    return new Color(0.13f, 0.48f + Mathf.Clamp01(waterMass[x, y] / 140f) * 0.08f, 0.38f, 1f);
                case CellKind.SaltWater:
                    return new Color(0.05f, 0.48f, 0.66f + Mathf.Clamp01(waterMass[x, y] / 140f) * 0.08f, 1f);
                case CellKind.CrudeOil:
                    return new Color(0.08f, 0.07f + Mathf.Clamp01(waterMass[x, y] / 140f) * 0.05f, 0.05f, 1f);
                case CellKind.Petroleum:
                    return new Color(0.20f, 0.13f + Mathf.Clamp01(waterMass[x, y] / 140f) * 0.08f, 0.06f, 1f);
                case CellKind.WaterPump:
                    return new Color(0.18f, 0.62f, 0.92f, 1f);
                case CellKind.BottleEmptier:
                    return CanEmptyBottleAt(new Vector2Int(x, y)) ? new Color(0.18f, 0.82f, 0.78f, 1f) : new Color(0.28f, 0.48f, 0.52f, 1f);
                case CellKind.ResearchStation:
                    return new Color(0.72f, 0.42f, 0.95f, 1f);
                case CellKind.MicrobeMusher:
                    return new Color(0.78f, 0.72f, 0.32f, 1f);
                case CellKind.EggCracker:
                    return hatchEggs >= 1f ? new Color(0.96f, 0.74f, 0.30f, 1f) : new Color(0.46f, 0.36f, 0.22f, 1f);
                case CellKind.ElectricGrill:
                    return CanCookAt(new Vector2Int(x, y)) ? new Color(1f, 0.58f, 0.28f, 1f) : new Color(0.48f, 0.30f, 0.20f, 1f);
                case CellKind.AirDeodorizer:
                    return new Color(0.72f, 0.90f, 0.78f, 1f);
                case CellKind.MedicalCot:
                    return new Color(0.95f, 0.78f, 0.84f, 1f);
                case CellKind.Apothecary:
                    return CanProduceMedicineAt(new Vector2Int(x, y)) ? new Color(0.86f, 0.94f, 0.54f, 1f) : new Color(0.46f, 0.48f, 0.34f, 1f);
                case CellKind.SpaceHeater:
                    return new Color(0.95f, 0.40f, 0.24f, 1f);
                case CellKind.LiquidTepidizer:
                    return CanPoweredMachineRun(new Vector2Int(x, y)) ? new Color(1f, 0.64f, 0.22f, 1f) : new Color(0.54f, 0.32f, 0.20f, 1f);
                case CellKind.ThermoRegulator:
                    return new Color(0.34f, 0.72f, 0.96f, 1f);
                case CellKind.ThermoAquatuner:
                    return CanPoweredMachineRun(new Vector2Int(x, y)) ? new Color(0.18f, 0.86f, 0.96f, 1f) : new Color(0.22f, 0.48f, 0.58f, 1f);
                case CellKind.TempshiftPlate:
                    return new Color(0.74f, 0.66f, 0.50f, 1f);
                case CellKind.Wheezewort:
                    return HydrogenAround(new Vector2Int(x, y), 2) >= WheezewortHydrogenThreshold ? new Color(0.55f, 0.96f, 0.92f, 1f) : new Color(0.42f, 0.74f, 0.86f, 1f);
                case CellKind.AntiEntropyThermoNullifier:
                    return CanAntiEntropyThermoNullifierRun(new Vector2Int(x, y)) ? new Color(0.20f, 0.96f, 1f, 1f) : new Color(0.16f, 0.36f, 0.48f, 1f);
                case CellKind.Outhouse:
                    return new Color(0.74f, 0.86f, 0.72f, 1f);
                case CellKind.Lavatory:
                    return CleanWaterAvailableForMachine(new Vector2Int(x, y)) >= LavatoryWaterUse && CanUseEquipment(new Vector2Int(x, y)) ? new Color(0.52f, 0.88f, 0.96f, 1f) : new Color(0.36f, 0.50f, 0.56f, 1f);
                case CellKind.Shower:
                    return CleanWaterAvailableForMachine(new Vector2Int(x, y)) >= ShowerWaterUse && CanUseEquipment(new Vector2Int(x, y)) ? new Color(0.42f, 0.80f, 1f, 1f) : new Color(0.30f, 0.42f, 0.56f, 1f);
                case CellKind.WashBasin:
                    return CleanWaterAvailableForMachine(new Vector2Int(x, y)) >= WashBasinWaterUse ? new Color(0.42f, 0.86f, 0.96f, 1f) : new Color(0.38f, 0.52f, 0.58f, 1f);
                case CellKind.HandSanitizer:
                    return bleachStone >= HandSanitizerBleachStoneUse && CanUseEquipment(new Vector2Int(x, y)) ? new Color(0.74f, 0.92f, 0.46f, 1f) : new Color(0.44f, 0.50f, 0.28f, 1f);
                case CellKind.MassageTable:
                    return new Color(0.70f, 0.56f, 0.90f, 1f);
                case CellKind.WaterCooler:
                    return CleanWaterAvailableForMachine(new Vector2Int(x, y)) >= WaterCoolerWaterUse && CanUseEquipment(new Vector2Int(x, y)) ? new Color(0.58f, 0.92f, 0.98f, 1f) : new Color(0.34f, 0.48f, 0.56f, 1f);
                case CellKind.ArcadeCabinet:
                    return CanPoweredMachineRun(new Vector2Int(x, y)) && plastic >= ArcadeCabinetPlasticUse ? new Color(0.88f, 0.48f, 1f, 1f) : new Color(0.36f, 0.26f, 0.48f, 1f);
                case CellKind.ManualAirlock:
                    return airlockOpen[x, y] ? new Color(0.64f, 0.78f, 0.82f, 1f) : new Color(0.34f, 0.46f, 0.54f, 1f);
                case CellKind.MechanizedAirlock:
                    return IsMechanizedAirlockOpen(new Vector2Int(x, y)) ? new Color(0.72f, 0.84f, 0.88f, 1f) : new Color(0.28f, 0.40f, 0.48f, 1f);
                case CellKind.Refrigerator:
                    return IsPoweredRefrigeratorAt(x, y) ? new Color(0.38f, 0.82f, 0.96f, 1f) : new Color(0.46f, 0.55f, 0.60f, 1f);
                case CellKind.RationBox:
                    return food > 0f ? new Color(0.78f, 0.58f, 0.28f, 1f) : new Color(0.48f, 0.38f, 0.24f, 1f);
                case CellKind.CeilingLight:
