        private Color GasColor(int x, int y)
        {
            if (!IsPassable(x, y))
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            float o2 = oxygen[x, y];
            float co2 = carbonDioxide[x, y];
            float po2 = pollutedOxygen[x, y];
            float h2 = hydrogen[x, y];
            float st = steam[x, y];
            float cl = chlorine[x, y];
            float ng = naturalGas[x, y];
            float sg = sourGas[x, y];
            if (st > 0.05f && st > o2 * 0.72f && st > co2 * 0.72f && st > po2 * 0.72f && st > h2 * 0.72f && st > cl * 0.72f && st > ng * 0.72f && st > sg * 0.72f)
            {
                float alpha = Mathf.Clamp01(st * 0.32f + 0.12f);
                return new Color(0.92f, 0.96f, 1f, alpha);
            }

            if (sg > 0.05f && sg > o2 * 0.72f && sg > co2 * 0.72f && sg > po2 * 0.72f && sg > h2 * 0.72f && sg > st * 0.72f && sg > cl * 0.72f && sg > ng * 0.72f)
            {
                return new Color(0.78f, 0.62f, 0.22f, Mathf.Clamp01(sg * 0.34f + 0.10f));
            }

            if (ng > 0.05f && ng > o2 * 0.72f && ng > co2 * 0.72f && ng > po2 * 0.72f && ng > h2 * 0.72f && ng > st * 0.72f && ng > cl * 0.72f && ng > sg * 0.72f)
            {
                return new Color(1f, 0.58f, 0.16f, Mathf.Clamp01(ng * 0.34f + 0.10f));
            }

            if (cl > 0.05f && cl > o2 * 0.72f && cl > co2 * 0.72f && cl > po2 * 0.72f && cl > h2 * 0.72f && cl > st * 0.72f && cl > ng * 0.72f && cl > sg * 0.72f)
            {
                return new Color(0.72f, 0.95f, 0.16f, Mathf.Clamp01(cl * 0.34f + 0.10f));
            }

            if (h2 > o2 * 0.72f && h2 > co2 * 0.72f && h2 > po2 * 0.72f && h2 > st * 0.72f && h2 > cl * 0.72f && h2 > ng * 0.72f && h2 > sg * 0.72f)
            {
                return new Color(0.82f, 0.38f, 1f, Mathf.Clamp01(h2 * 0.30f));
            }

            if (po2 > o2 * 0.72f && po2 > co2 * 0.72f && po2 > st * 0.72f && po2 > cl * 0.72f && po2 > ng * 0.72f && po2 > sg * 0.72f)
            {
                float alpha = Mathf.Clamp01(po2 * 0.34f + germs[x, y] * 0.18f);
                return new Color(0.28f, 0.92f, 0.36f, alpha);
            }

            if (o2 < 0.05f && co2 < 0.05f && po2 < 0.05f && h2 < 0.05f && st < 0.05f && cl < 0.05f && ng < 0.05f && sg < 0.05f)
            {
                return new Color(0f, 0f, 0f, 0.45f);
            }

            if (co2 > o2 * 0.85f)
            {
                float alpha = Mathf.Clamp01(co2 * 0.35f);
                return new Color(0.85f, 0.34f, 0.16f, alpha);
            }

            return new Color(0.2f, 0.72f, 1f, Mathf.Clamp01(o2 * 0.22f));
        }

        private Color OverlayColor(int x, int y)
        {
            switch (currentOverlayMode)
            {
                case OverlayMode.Temperature:
                    return TemperatureOverlayColor(x, y);
                case OverlayMode.Materials:
                    return MaterialsOverlayColor(x, y);
                case OverlayMode.Food:
                    return FoodOverlayColor(x, y);
                case OverlayMode.Errands:
                    return ErrandsOverlayColor(x, y);
                case OverlayMode.Farming:
                    return FarmingOverlayColor(x, y);
                case OverlayMode.Light:
                    return LightOverlayColor(x, y);
                case OverlayMode.Power:
                    return PowerOverlayColor(x, y);
                case OverlayMode.Automation:
                    return AutomationOverlayColor(x, y);
                case OverlayMode.Germs:
                    return GermOverlayColor(x, y);
                case OverlayMode.Vitals:
                    return VitalsOverlayColor(x, y);
                case OverlayMode.Medical:
                    return MedicalOverlayColor(x, y);
                case OverlayMode.Morale:
                    return MoraleOverlayColor(x, y);
                case OverlayMode.Suit:
                    return SuitOverlayColor(x, y);
                case OverlayMode.Plumbing:
                    return PlumbingOverlayColor(x, y);
                case OverlayMode.Ventilation:
                    return VentilationOverlayColor(x, y);
                case OverlayMode.Logistics:
                    return LogisticsOverlayColor(x, y);
                case OverlayMode.Decor:
                    return DecorOverlayColor(x, y);
                case OverlayMode.Rooms:
                    return RoomOverlayColor(x, y);
                default:
                    return GasColor(x, y);
            }
        }

        private Color ErrandsOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            Job job = FindAnyJobAt(cell);
            if (job != null)
            {
                Color color = ErrandOverlayColor(job);
                color.a *= 0.72f;
                return color;
            }

            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                Color color = ErrandWorkerOverlayColor(worker);
                color.a *= 0.60f;
                return color;
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color ErrandOverlayColor(Job job)
        {
            if (job == null)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (!IsJobValid(job))
            {
                return new Color(1f, 0.12f, 0.10f, 0.92f);
            }

            if (job.YellowAlert)
            {
                return new Color(1f, 0.94f, 0.16f, 0.96f);
            }

            if (job.AssignedWorker != null)
            {
                return new Color(0.22f, 0.88f, 1f, 0.88f);
            }

            int priority = DispatchJobPriority(job);
            if (priority >= 9)
            {
                return new Color(1f, 0.36f, 0.12f, 0.90f);
            }

            if (priority >= 7)
            {
                return new Color(1f, 0.64f, 0.18f, 0.84f);
            }

            if (priority >= 5)
            {
                return new Color(0.36f, 1f, 0.42f, 0.72f);
            }

            return new Color(0.48f, 0.54f, 0.62f, 0.58f);
        }

        private Color ErrandWorkerOverlayColor(Worker worker)
        {
            if (worker == null)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (worker.Health <= 0f)
            {
                return new Color(1f, 0.10f, 0.45f, 0.94f);
            }

            if (worker.StressBreakSeconds > 0f)
            {
                return new Color(1f, 0.34f, 0.92f, 0.88f);
            }

            if (worker.AssignedJob != null)
            {
                return new Color(0.22f, 0.88f, 1f, 0.86f);
            }

            return new Color(0.62f, 0.68f, 0.74f, 0.70f);
        }

        private Color LightOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            CellKind kind = cells[x, y];
            if (kind == CellKind.CeilingLight)
            {
                return IsPoweredCeilingLightAt(x, y)
                    ? new Color(1f, 0.92f, 0.28f, 0.92f)
                    : HasWireAccess(cell) ? new Color(0.62f, 0.52f, 0.24f, 0.58f) : new Color(0.40f, 0.34f, 0.22f, 0.44f);
            }

            HatchCritter hatch = HatchAt(cell);
            if (hatch != null && hatch.Kind == CritterKind.ShineBug)
            {
                return IsShineBugGlowing(hatch)
                    ? new Color(0.82f, 1f, 0.42f, 0.92f)
                    : new Color(0.38f, 0.48f, 0.26f, 0.50f);
            }

            if (kind == CellKind.SolarPanel)
            {
                if (!IsSolarPanelSkyExposed(cell))
                {
                    return new Color(0.35f, 0.38f, 0.44f, 0.58f);
                }

                float irradiance = SolarIrradiance();
                return irradiance > 0.01f
                    ? new Color(1f, 0.86f, 0.20f, 0.62f + irradiance * 0.28f)
                    : new Color(0.34f, 0.48f, 0.72f, 0.42f);
            }

            if (IsCropKind(kind))
            {
                bool lit = IsCellLit(x, y);
                if (CropRequiresLight(kind))
                {
                    return lit ? new Color(0.92f, 1f, 0.32f, 0.76f) : new Color(0.18f, 0.34f, 0.78f, 0.72f);
                }

                if (CropRequiresDarkness(kind))
                {
                    return lit ? new Color(0.90f, 0.30f, 1f, 0.76f) : new Color(0.16f, 0.28f, 0.48f, 0.58f);
                }
            }

            float ceilingLight = PoweredCeilingLightScoreAt(x, y);
            float shineLight = ShineBugLightScoreAt(x, y);
            float light = Mathf.Clamp01(ceilingLight + shineLight);
            if (light > 0.01f)
            {
                Color color = Color.Lerp(new Color(0.24f, 0.38f, 0.76f, 0.28f), new Color(1f, 0.92f, 0.24f, 0.76f), light);
                color.a = Mathf.Clamp01(color.a + shineLight * 0.12f);
                return color;
            }

            if (IsSkyExposedAt(x, y))
            {
                float irradiance = SolarIrradiance();
                return irradiance > 0.01f
                    ? new Color(0.52f, 0.72f, 1f, 0.22f + irradiance * 0.26f)
                    : new Color(0.12f, 0.20f, 0.38f, 0.20f);
            }

            return IsPassable(x, y)
                ? new Color(0.02f, 0.04f, 0.10f, 0.36f)
                : new Color(0f, 0f, 0f, 0f);
        }

        private bool IsSkyExposedAt(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            for (int checkY = y + 1; checkY < WorldHeight; checkY++)
            {
                if (IsSolarBlockingCell(x, checkY))
                {
                    return false;
                }
            }

            return true;
        }

        private Color FarmingOverlayColor(int x, int y)
        {
            CellKind kind = cells[x, y];
            if (IsCropKind(kind))
            {
                return CropOverlayColor(x, y, kind);
            }

            if (kind == CellKind.FarmStation)
            {
                bool hasTargets = CountCropTendingTargets() > 0;
                bool supplied = CanSupplyCropTending();
                return hasTargets && supplied
                    ? new Color(0.34f, 1f, 0.50f, 0.76f)
                    : hasTargets ? new Color(1f, 0.46f, 0.12f, 0.74f) : new Color(0.34f, 0.58f, 0.40f, 0.42f);
            }

            if (kind == CellKind.FertilizerSynthesizer)
            {
                return CanFertilizerSynthesizerRun(new Vector2Int(x, y))
                    ? new Color(0.50f, 0.96f, 0.30f, 0.70f)
                    : new Color(0.36f, 0.46f, 0.26f, 0.42f);
            }

            if (kind == CellKind.MicrobeMusher ||
                kind == CellKind.ElectricGrill ||
                kind == CellKind.EggCracker)
            {
                return CanCookAt(new Vector2Int(x, y))
                    ? new Color(1f, 0.78f, 0.24f, 0.64f)
                    : new Color(0.54f, 0.38f, 0.18f, 0.36f);
            }

            if (kind == CellKind.RationBox || kind == CellKind.Refrigerator)
            {
                float foodCoverage = workers.Count <= 0 ? 0f : Mathf.Clamp01(food / Mathf.Max(1f, workers.Count * 2600f));
                return new Color(1f, 0.64f + foodCoverage * 0.22f, 0.22f, 0.32f + foodCoverage * 0.38f);
            }

            if (looseResourceKind[x, y] == LooseResourceKind.Peppernut ||
                looseResourceKind[x, y] == LooseResourceKind.Lumber ||
                looseResourceKind[x, y] == LooseResourceKind.ReedFiber ||
                looseResourceKind[x, y] == LooseResourceKind.WheatGrain ||
                looseResourceKind[x, y] == LooseResourceKind.HatchEgg)
            {
                return LooseResourceOverlayColor(looseResourceKind[x, y], looseResourceAmount[x, y]);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color CropOverlayColor(int x, int y, CellKind kind)
        {
            Vector2Int crop = new Vector2Int(x, y);
            if (cropStress[x, y] >= CropWiltThresholdSeconds)
            {
                return new Color(1f, 0.10f, 0.08f, 0.92f);
            }

            if (cropStress[x, y] >= CropStressThresholdSeconds)
            {
                return new Color(1f, 0.48f, 0.12f, 0.86f);
            }

            if (plantGrowth[x, y] >= 1f)
            {
                return CanHarvestCrop(crop)
                    ? new Color(1f, 0.88f, 0.18f, 0.92f)
                    : new Color(0.62f, 0.54f, 0.26f, 0.62f);
            }

            if (!HasCropIrrigation(crop))
            {
                return new Color(0.18f, 0.52f, 1f, 0.76f);
            }

            if (!CropAtmosphereSatisfied(kind, x, y))
            {
                return new Color(0.70f, 0.38f, 1f, 0.74f);
            }

            if (!CropLightSatisfied(kind, IsCellLit(x, y)))
            {
                return new Color(0.86f, 0.42f, 1f, 0.74f);
            }

            if (!CropComfortableTemperature(kind, temperature[x, y]) ||
                waterMass[x, y] >= CropFloodWaterMass ||
                TileGasTotal(x, y) > OverpressureDamageThreshold)
            {
                return new Color(1f, 0.32f, 0.18f, 0.78f);
            }

            if (cropTendedSeconds[x, y] > 0f)
            {
                return cropTendedSeconds[x, y] > CropTendedSeconds
                    ? new Color(0.36f, 1f, 0.78f, 0.88f)
                    : new Color(0.44f, 1f, 0.38f, 0.82f);
            }

            float growth = Mathf.Clamp01(plantGrowth[x, y]);
            return new Color(0.22f + growth * 0.34f, 0.72f + growth * 0.24f, 0.24f, 0.36f + growth * 0.42f);
        }

        private Color MaterialsOverlayColor(int x, int y)
        {
            if (looseResourceKind[x, y] != LooseResourceKind.None && looseResourceAmount[x, y] > 0.05f)
            {
                return LooseResourceOverlayColor(looseResourceKind[x, y], looseResourceAmount[x, y]);
            }

            if (shippingRail[x, y] && shippingRailKind[x, y] != LooseResourceKind.None && shippingRailAmount[x, y] > 0.001f)
            {
                return LooseResourceOverlayColor(shippingRailKind[x, y], shippingRailAmount[x, y] * 6f);
            }

            CellKind kind = cells[x, y];
            if ((IsWorldLiquidCell(kind) || IsFloodableCellKind(kind)) && waterMass[x, y] > 0.5f)
            {
                return LiquidMaterialOverlayColor(x, y, kind);
            }

            if (kind == CellKind.Magma)
            {
                return new Color(1f, 0.22f, 0.04f, 0.84f);
            }

            if (IsNaturalSolid(kind))
            {
                return NaturalMaterialOverlayColor(kind);
            }

            if (kind == CellKind.StorageBin)
            {
                return StorageFilterMaterialColor(storageBinFilter[x, y], 0.62f);
            }

            if (kind == CellKind.ConveyorLoader)
            {
                return StorageFilterMaterialColor(conveyorLoaderFilter[x, y], 0.66f);
            }

            if (kind == CellKind.ConveyorReceptacle)
            {
                return StorageFilterMaterialColor(conveyorReceptacleFilter[x, y], 0.58f);
            }

            if (kind == CellKind.ShippingRailSensor)
            {
                return StorageFilterMaterialColor(shippingRailSensorFilter[x, y], 0.58f);
            }

            if (kind == CellKind.RationBox)
            {
                return new Color(1f, 0.78f, 0.26f, 0.58f);
            }

            if (kind == CellKind.Refrigerator)
            {
                return IsPoweredRefrigeratorAt(x, y)
                    ? new Color(0.42f, 0.92f, 1f, 0.64f)
                    : new Color(0.62f, 0.66f, 0.70f, 0.46f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color FoodOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                Color workerColor = WorkerFoodOverlayColor(worker);
                if (workerColor.a > 0f)
                {
                    return workerColor;
                }
            }

            CellKind kind = cells[x, y];
            if (IsFoodStorageCell(x, y))
            {
                return FoodStorageOverlayColor(x, y, kind);
            }

            if (kind == CellKind.MicrobeMusher ||
                kind == CellKind.EggCracker ||
                kind == CellKind.ElectricGrill)
            {
                return CanCookAt(cell)
                    ? new Color(0.42f, 1f, 0.48f, 0.78f)
                    : new Color(0.58f, 0.36f, 0.22f, techFoodPreparation ? 0.62f : 0.42f);
            }

            if (IsCropKind(kind))
            {
                if (plantGrowth[x, y] >= 1f && CanHarvestCrop(cell))
                {
                    return new Color(0.46f, 1f, 0.34f, 0.72f);
                }

                if (cropStress[x, y] >= CropStressThresholdSeconds)
                {
                    return new Color(1f, 0.46f, 0.16f, 0.58f);
                }

                return food < workers.Count * 1500f
                    ? new Color(0.28f, 0.68f, 0.30f, 0.30f)
                    : new Color(0f, 0f, 0f, 0f);
            }

            if (looseResourceKind[x, y] == LooseResourceKind.HatchEgg && looseResourceAmount[x, y] > 0.05f)
            {
                return new Color(1f, 0.74f, 0.28f, 0.68f);
            }

            if (looseResourceKind[x, y] == LooseResourceKind.Peppernut && looseResourceAmount[x, y] > 0.05f)
            {
                return new Color(1f, 0.30f, 0.18f, 0.56f);
            }

            if (looseResourceKind[x, y] == LooseResourceKind.Lumber && looseResourceAmount[x, y] > 0.05f)
            {
                return new Color(0.62f, 0.42f, 0.20f, 0.54f);
            }

            if (looseResourceKind[x, y] == LooseResourceKind.WheatGrain && looseResourceAmount[x, y] > 0.05f)
            {
                return new Color(0.82f, 0.94f, 1f, 0.54f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color FoodStorageOverlayColor(int x, int y, CellKind kind)
        {
            if (food <= 0.001f)
            {
                return kind == CellKind.Refrigerator && IsPoweredRefrigeratorAt(x, y)
                    ? new Color(0.32f, 0.58f, 0.66f, 0.40f)
                    : new Color(0.32f, 0.30f, 0.26f, 0.34f);
            }

            float contamination = Mathf.Max(foodGerms, FoodStorageContaminationScoreAt(x, y));
            float sterility = FoodStorageSterilityScoreAt(x, y);
            float chlorineSterility = FoodStorageChlorineSterilityScoreAt(x, y);

            if (foodFreshness <= SpoiledFoodRotFreshnessThreshold)
            {
                return new Color(0.42f, 0.06f, 0.04f, 0.92f);
            }

            if (foodFreshness <= FoodPoisoningFreshnessThreshold || contamination >= FoodGermPoisoningThreshold)
            {
                return new Color(1f, 0.16f, 0.08f, 0.86f);
            }

            if (foodFreshness <= StaleFoodFreshnessThreshold || contamination >= FoodGermExposureThreshold)
            {
                return new Color(1f, 0.56f, 0.14f, 0.78f);
            }

            if (IsPoweredRefrigeratorAt(x, y))
            {
                return new Color(0.28f, 0.88f, 1f, 0.78f);
            }

            if (chlorineSterility >= 0.75f)
            {
                return new Color(0.74f, 1f, 0.20f, 0.78f);
            }

            if (sterility >= 0.75f)
            {
                return new Color(0.34f, 1f, 0.42f, 0.72f);
            }

            if (sterility >= 0.35f)
            {
                return new Color(0.84f, 0.92f, 0.24f, 0.64f);
            }

            if (temperature[x, y] > 38f)
            {
                return new Color(1f, 0.36f, 0.12f, 0.72f);
            }

            return kind == CellKind.RationBox
                ? new Color(1f, 0.76f, 0.24f, 0.58f)
                : new Color(0.48f, 0.56f, 0.62f, 0.50f);
        }

        private Color WorkerFoodOverlayColor(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (worker.Calories <= 350f)
            {
                return new Color(1f, 0.08f, 0.04f, 0.92f);
            }

            if (worker.Calories <= 850f)
            {
                return new Color(1f, 0.42f, 0.10f, 0.82f);
            }

            if (worker.Calories <= 1400f)
            {
                return new Color(1f, 0.82f, 0.18f, 0.70f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color LooseResourceOverlayColor(LooseResourceKind kind, float amount)
        {
            Color color = LooseResourceColor(kind);
            float massScale = kind == LooseResourceKind.HatchEgg
                ? 0.86f
                : Mathf.Clamp01(0.45f + Mathf.Sqrt(Mathf.Clamp01(amount / 80f)) * 0.42f);
            color.a = massScale;
            return color;
        }

        private Color LiquidMaterialOverlayColor(int x, int y, CellKind kind)
        {
            float fill = Mathf.Clamp01(waterMass[x, y] / LiquidTileCapacity);
            Color color;
            if (kind == CellKind.CrudeOil)
            {
                color = new Color(0.12f, 0.10f, 0.08f, 1f);
            }
            else if (kind == CellKind.SaltWater)
            {
                color = new Color(0.10f, 0.64f, 0.82f, 1f);
            }
            else if (kind == CellKind.PollutedWater || IsPollutedMopCell(new Vector2Int(x, y)))
            {
                color = new Color(0.18f, 0.70f, 0.42f, 1f);
            }
            else
            {
                color = new Color(0.12f, 0.48f, 1f, 1f);
            }

            color.a = 0.42f + fill * 0.42f;
            return color;
        }

        private Color NaturalMaterialOverlayColor(CellKind kind)
        {
            switch (kind)
            {
                case CellKind.Dirt:
                    return new Color(0.58f, 0.38f, 0.18f, 0.72f);
                case CellKind.Rock:
                    return new Color(0.50f, 0.54f, 0.58f, 0.70f);
                case CellKind.Sand:
                    return new Color(0.86f, 0.72f, 0.34f, 0.74f);
                case CellKind.Regolith:
                    return new Color(0.72f, 0.70f, 0.64f, 0.72f);
                case CellKind.MetalOre:
                    return new Color(0.44f, 0.70f, 0.82f, 0.78f);
                case CellKind.Algae:
                    return new Color(0.34f, 0.82f, 0.30f, 0.78f);
                case CellKind.Coal:
                    return new Color(0.24f, 0.24f, 0.22f, 0.86f);
                case CellKind.Slime:
                    return new Color(0.18f, 0.74f, 0.34f, 0.80f);
                case CellKind.BleachStone:
                    return new Color(0.88f, 0.96f, 0.58f, 0.78f);
                case CellKind.Ice:
                    return new Color(0.58f, 0.94f, 1f, 0.76f);
                default:
                    return new Color(0.58f, 0.52f, 0.42f, 0.68f);
            }
        }

        private Color StorageFilterMaterialColor(StorageFilter filter, float alpha)
        {
            if (filter == StorageFilter.All)
            {
                return new Color(0.76f, 0.78f, 0.82f, alpha);
            }

            Color color = LooseResourceColor(LooseResourceForStorageFilter(filter));
            color.a = alpha;
            return color;
        }

        private LooseResourceKind LooseResourceForStorageFilter(StorageFilter filter)
        {
            switch (filter)
            {
                case StorageFilter.Dirt:
                    return LooseResourceKind.Dirt;
                case StorageFilter.Metal:
                    return LooseResourceKind.Metal;
                case StorageFilter.Algae:
                    return LooseResourceKind.Algae;
                case StorageFilter.Coal:
                    return LooseResourceKind.Coal;
                case StorageFilter.RefinedMetal:
                    return LooseResourceKind.RefinedMetal;
                case StorageFilter.Steel:
                    return LooseResourceKind.Steel;
                case StorageFilter.Ceramic:
                    return LooseResourceKind.Ceramic;
                case StorageFilter.Glass:
                    return LooseResourceKind.Glass;
                case StorageFilter.Niobium:
                    return LooseResourceKind.Niobium;
                case StorageFilter.Thermium:
                    return LooseResourceKind.Thermium;
                case StorageFilter.Fullerene:
                    return LooseResourceKind.Fullerene;
                case StorageFilter.SuperCoolant:
                    return LooseResourceKind.SuperCoolant;
                case StorageFilter.CryogenicPropellant:
                    return LooseResourceKind.CryogenicPropellant;
                case StorageFilter.PollutedDirt:
                    return LooseResourceKind.PollutedDirt;
                case StorageFilter.HatchEgg:
                    return LooseResourceKind.HatchEgg;
                case StorageFilter.Slime:
                    return LooseResourceKind.Slime;
                case StorageFilter.BleachStone:
                    return LooseResourceKind.BleachStone;
                case StorageFilter.Plastic:
                    return LooseResourceKind.Plastic;
                case StorageFilter.Peppernut:
                    return LooseResourceKind.Peppernut;
                case StorageFilter.Lumber:
                    return LooseResourceKind.Lumber;
                case StorageFilter.ReedFiber:
                    return LooseResourceKind.ReedFiber;
                case StorageFilter.Sulfur:
                    return LooseResourceKind.Sulfur;
                case StorageFilter.WheatGrain:
                    return LooseResourceKind.WheatGrain;
                default:
                    return LooseResourceKind.None;
            }
        }

        private Color RoomOverlayColor(int x, int y)
        {
            if (cells[x, y] == CellKind.ManualAirlock ||
                cells[x, y] == CellKind.MechanizedAirlock ||
                cells[x, y] == CellKind.Tile ||
                cells[x, y] == CellKind.AirflowTile ||
                cells[x, y] == CellKind.InsulatedTile)
            {
                return new Color(0.82f, 0.90f, 0.94f, 0.50f);
            }

            RoomInfo room = RoomAt(x, y);
            if (room == null)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            bool overcrowdedStable = room.Kind == RoomKind.Stable && IsStableOvercrowded(room);
            Color color = overcrowdedStable
                ? OvercrowdedStableRoomColor()
                : RoomKindColor(room.Kind);
            if (room.Kind == RoomKind.OpenArea)
            {
                color.a = 0.08f;
                return color;
            }

            color.a = overcrowdedStable ? 0.62f : room.Kind == RoomKind.MixedRoom ? 0.34f : 0.46f;
            return color;
        }

        private Color OvercrowdedStableRoomColor()
        {
            return new Color(1f, 0.34f, 0.18f, 1f);
        }

        private Color RoomKindColor(RoomKind kind)
        {
            switch (kind)
            {
                case RoomKind.Barracks:
                    return new Color(0.28f, 0.60f, 1f, 1f);
                case RoomKind.Bedroom:
                    return new Color(0.48f, 0.72f, 1f, 1f);
                case RoomKind.MessHall:
                    return new Color(1f, 0.82f, 0.28f, 1f);
                case RoomKind.GreatHall:
                    return new Color(1f, 0.68f, 0.22f, 1f);
                case RoomKind.Washroom:
                    return new Color(0.28f, 0.90f, 0.86f, 1f);
                case RoomKind.Clinic:
                    return new Color(1f, 0.52f, 0.66f, 1f);
                case RoomKind.RecreationRoom:
                    return new Color(0.72f, 0.50f, 1f, 1f);
                case RoomKind.Stable:
                    return new Color(0.75f, 0.58f, 0.34f, 1f);
                case RoomKind.MachineRoom:
                    return new Color(1f, 0.48f, 0.20f, 1f);
                case RoomKind.PowerPlant:
                    return new Color(1f, 0.62f, 0.16f, 1f);
                case RoomKind.StorageRoom:
                    return new Color(0.50f, 0.82f, 0.52f, 1f);
                case RoomKind.MixedRoom:
                    return new Color(0.78f, 0.78f, 0.74f, 1f);
                case RoomKind.BasicRoom:
                    return new Color(0.46f, 0.76f, 0.48f, 1f);
                default:
                    return new Color(0.20f, 0.24f, 0.28f, 1f);
            }
        }

        private Color DecorOverlayColor(int x, int y)
        {
            if (powerWire[x, y] && powerWireKind[x, y] == PowerWireKind.HeavyWatt)
            {
                return new Color(1f, 0.18f, 0.10f, 0.56f);
            }

            if (cells[x, y] == CellKind.SculptingBlock)
            {
                return sculptingBlockFinished[x, y]
                    ? new Color(1f, 0.58f, 0.92f, 0.84f)
                    : new Color(0.58f, 0.54f, 0.62f, 0.38f);
            }

            float decor = DecorScoreAt(x, y);
            if (decor <= 0.01f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (cells[x, y] == CellKind.DecorPlant)
            {
                return new Color(1f, 0.54f, 0.96f, 0.82f);
            }

            return new Color(0.92f, 0.44f + decor * 0.22f, 1f, 0.12f + decor * 0.54f);
        }

        private Color PlumbingOverlayColor(int x, int y)
        {
            if (cells[x, y] == CellKind.LiquidPipeSensor)
            {
                return LiquidSensorSignalActive(x, y) ? new Color(0.26f, 1f, 0.38f, 0.70f) : new Color(1f, 0.20f, 0.12f, 0.62f);
            }

            if (cells[x, y] == CellKind.LiquidShutoff)
            {
                return IsConduitShutoffOpen(new Vector2Int(x, y)) ? new Color(0.30f, 0.95f, 1f, 0.70f) : new Color(1f, 0.18f, 0.12f, 0.68f);
            }

            if (cells[x, y] == CellKind.LiquidValve)
            {
                return IsConduitValveOpen(new Vector2Int(x, y)) ? new Color(0.12f, 0.96f, 0.72f, 0.70f) : new Color(1f, 0.18f, 0.12f, 0.68f);
            }

            if (liquidPipe[x, y])
            {
                return LiquidPipeOverlayColor(x, y, 0f);
            }

            if (cells[x, y] == CellKind.LiquidBridge)
            {
                return new Color(0.02f, 0.88f, 1f, 0.70f);
            }

            if (cells[x, y] == CellKind.LiquidReservoir)
            {
                float fill = Mathf.Clamp01(LiquidReservoirTotal(x, y) / LiquidReservoirCapacity);
                float pollutedShare = LiquidReservoirPollutedShare(x, y);
                return new Color(0.10f + pollutedShare * 0.05f, 0.62f + fill * 0.24f, 1f - pollutedShare * 0.52f, 0.26f + fill * 0.48f);
            }

            if (cells[x, y] == CellKind.LiquidVent || cells[x, y] == CellKind.WaterPump || cells[x, y] == CellKind.WaterSieve)
            {
                return new Color(0.12f, 0.72f, 1f, 0.36f);
            }

            if (cells[x, y] == CellKind.SteamVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(1f, 0.54f, 0.18f, 0.72f) : new Color(0.34f, 0.78f, 1f, 0.34f);
            }

            if (cells[x, y] == CellKind.WaterGeyser)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.22f, 0.82f, 1f, 0.72f) : new Color(0.22f, 0.58f, 0.78f, 0.34f);
            }

            if (cells[x, y] == CellKind.CoolSteamVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.96f, 0.76f, 0.48f, 0.76f) : new Color(0.40f, 0.56f, 0.62f, 0.36f);
            }

            if (cells[x, y] == CellKind.LeakyOilFissure)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.22f, 0.12f, 0.04f, 0.76f) : new Color(0.14f, 0.10f, 0.06f, 0.36f);
            }

            if (cells[x, y] == CellKind.SaltWaterGeyser)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.16f, 0.92f, 1f, 0.72f) : new Color(0.24f, 0.66f, 0.74f, 0.34f);
            }

            if (cells[x, y] == CellKind.CoolSlushGeyser)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.18f, 1f, 0.58f, 0.72f) : new Color(0.18f, 0.62f, 0.42f, 0.34f);
            }

            if (cells[x, y] == CellKind.PollutedWaterVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.42f, 0.92f, 0.24f, 0.72f) : new Color(0.26f, 0.56f, 0.22f, 0.34f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color LiquidPipeOverlayColor(int x, int y, float alphaBoost)
        {
            float total = LiquidPipeTotal(x, y);
            float fill = Mathf.Clamp01(total / LiquidPipeCapacity);
            float pollutedShare = total > 0.001f ? Mathf.Clamp01(pipePollutedWater[x, y] / total) : 0f;
            Color cleanColor;
            switch (liquidPipeKind[x, y])
            {
                case LiquidPipeKind.Radiant:
                    cleanColor = new Color(0.05f, 0.88f + fill * 0.10f, 1f, Mathf.Clamp01(0.42f + alphaBoost + fill * 0.44f));
                    break;
                case LiquidPipeKind.Insulated:
                    cleanColor = new Color(0.18f, 0.34f + fill * 0.16f, 0.72f, Mathf.Clamp01(0.28f + alphaBoost + fill * 0.34f));
                    break;
                default:
                    cleanColor = new Color(0.08f, 0.58f + fill * 0.25f, 1f, Mathf.Clamp01(0.30f + alphaBoost + fill * 0.40f));
                    break;
            }

            Color pollutedColor = new Color(0.30f, 0.90f, 0.22f, cleanColor.a);
            return Color.Lerp(cleanColor, pollutedColor, pollutedShare);
        }

        private Color VentilationOverlayColor(int x, int y)
        {
            if (cells[x, y] == CellKind.GasPipeSensor)
            {
                return GasSensorSignalActive(x, y) ? new Color(0.28f, 1f, 0.36f, 0.70f) : new Color(1f, 0.20f, 0.12f, 0.62f);
            }

            if (cells[x, y] == CellKind.GasShutoff)
            {
                return IsConduitShutoffOpen(new Vector2Int(x, y)) ? new Color(0.52f, 0.96f, 1f, 0.70f) : new Color(1f, 0.18f, 0.12f, 0.68f);
            }

            if (cells[x, y] == CellKind.GasValve)
            {
                return IsConduitValveOpen(new Vector2Int(x, y)) ? new Color(0.72f, 0.98f, 0.86f, 0.70f) : new Color(1f, 0.18f, 0.12f, 0.68f);
            }

            if (gasPipe[x, y])
            {
                return GasPipeOverlayColor(x, y);
            }

            if (cells[x, y] == CellKind.GasBridge)
            {
                return new Color(0.58f, 0.92f, 1f, 0.70f);
            }

            if (cells[x, y] == CellKind.GasReservoir)
            {
                float fill = Mathf.Clamp01(GasReservoirTotal(x, y) / GasReservoirCapacity);
                return new Color(0.45f, 0.92f, 1f, 0.28f + fill * 0.48f);
            }

            if (cells[x, y] == CellKind.GasPump || cells[x, y] == CellKind.GasVent)
            {
                return new Color(0.38f, 0.90f, 1f, 0.42f);
            }

            if (cells[x, y] == CellKind.HighPressureGasVent)
            {
                return new Color(0.24f, 0.98f, 0.86f, 0.70f);
            }

            if (cells[x, y] == CellKind.HydrogenVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.90f, 0.30f, 1f, 0.76f) : new Color(0.52f, 0.34f, 0.72f, 0.36f);
            }

            if (cells[x, y] == CellKind.ChlorineGasVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.78f, 1f, 0.20f, 0.76f) : new Color(0.42f, 0.58f, 0.18f, 0.36f);
            }

            if (cells[x, y] == CellKind.CarbonDioxideVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.62f, 0.70f, 0.86f, 0.76f) : new Color(0.36f, 0.40f, 0.54f, 0.36f);
            }

            if (cells[x, y] == CellKind.PollutedOxygenVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(0.34f, 0.94f, 0.32f, 0.76f) : new Color(0.24f, 0.52f, 0.24f, 0.36f);
            }

            if (cells[x, y] == CellKind.NaturalGasVent)
            {
                return NaturalVentActive(new Vector2Int(x, y)) ? new Color(1f, 0.62f, 0.16f, 0.76f) : new Color(0.62f, 0.42f, 0.20f, 0.36f);
            }

            return GasColor(x, y);
        }

        private Color LogisticsOverlayColor(int x, int y)
        {
            if (cells[x, y] == CellKind.ShippingBridge)
            {
                return new Color(1f, 0.66f, 0.18f, 0.72f);
            }

            if (cells[x, y] == CellKind.ShippingRailSensor)
            {
                return ShippingRailSensorSignalActive(x, y) ? new Color(0.30f, 1f, 0.34f, 0.70f) : new Color(1f, 0.22f, 0.12f, 0.62f);
            }

            if (cells[x, y] == CellKind.ShippingRailShutoff)
            {
                return ShippingRailShutoffOverlayColor(x, y);
            }

            if (cells[x, y] == CellKind.ShippingRailMeter)
            {
                return ShippingRailMeterOverlayColor(x, y);
            }

            if (shippingRail[x, y])
            {
                float fill = Mathf.Clamp01(shippingRailAmount[x, y] / ShippingRailCapacity);
                return new Color(1f, 0.56f + fill * 0.20f, 0.12f, 0.34f + fill * 0.48f);
            }

            if (cells[x, y] == CellKind.ConveyorLoader)
            {
                return CanPoweredMachineRun(new Vector2Int(x, y)) ? new Color(1f, 0.72f, 0.20f, 0.66f) : new Color(1f, 0.22f, 0.12f, 0.60f);
            }

            if (cells[x, y] == CellKind.ConveyorReceptacle)
            {
                return CanUseEquipment(new Vector2Int(x, y)) ? new Color(0.90f, 0.66f, 0.22f, 0.62f) : new Color(0.62f, 0.42f, 0.22f, 0.38f);
            }

            if (cells[x, y] == CellKind.ConveyorChute)
            {
                return new Color(0.95f, 0.48f, 0.12f, 0.62f);
            }

            if (cells[x, y] == CellKind.AutoSweeper)
            {
                return new Color(0.95f, 0.82f, 0.20f, 0.42f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color AutomationOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            if (automationWire[x, y])
            {
                return automationControlledWire[x, y]
                    ? AutomationSignalColor(automationSignalWire[x, y])
                    : AutomationNoSignalColor();
            }

            if (TryGetAutomationSourceSignal(x, y, out bool sourceSignal))
            {
                return AutomationSignalColor(sourceSignal);
            }

            CellKind kind = cells[x, y];
            switch (kind)
            {
                case CellKind.AutomationBridge:
                    return AutomationBridgeOverlayColor(x, y);
                case CellKind.AutomationNotGate:
                    return AutomationNotGateOverlayColor(x, y);
                case CellKind.AutomationAndGate:
                    return AutomationAndGateOverlayColor(x, y);
                case CellKind.AutomationOrGate:
                    return AutomationOrGateOverlayColor(x, y);
                case CellKind.AutomationXorGate:
                    return AutomationXorGateOverlayColor(x, y);
                case CellKind.AutomationBufferGate:
                    return AutomationBufferGateOverlayColor(x, y);
                case CellKind.AutomationFilterGate:
                    return AutomationFilterGateOverlayColor(x, y);
                case CellKind.AutomationMemoryGate:
                    return AutomationMemoryGateOverlayColor(x, y);
                case CellKind.PowerShutoff:
                case CellKind.LiquidShutoff:
                case CellKind.LiquidValve:
                case CellKind.GasShutoff:
                case CellKind.GasValve:
                case CellKind.ShippingRailShutoff:
                case CellKind.ShippingRailMeter:
                case CellKind.MechanizedAirlock:
                case CellKind.BunkerDoor:
                    return AutomationPortColor(cell);
                default:
                    return RequiresPower(kind) && HasCachedAutomationControl(cell)
                        ? AutomationPortColor(cell)
                        : new Color(0f, 0f, 0f, 0f);
            }
        }

        private Color AutomationSignalColor(bool signalActive)
        {
            return signalActive
                ? new Color(0.28f, 1f, 0.32f, 0.72f)
                : new Color(1f, 0.18f, 0.10f, 0.66f);
        }

        private Color AutomationNoSignalColor()
        {
            return new Color(0.52f, 0.42f, 0.85f, 0.42f);
        }

        private Color AutomationPortColor(Vector2Int cell)
        {
            if (!CanUseEquipment(cell))
            {
                return new Color(1f, 0.18f, 0.10f, 0.58f);
            }

            if (!HasCachedAutomationControl(cell))
            {
                return AutomationNoSignalColor();
            }

            return AutomationSignalColor(HasCachedAutomationSignal(cell));
        }

        private Color VitalsOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                return WorkerVitalsOverlayColor(worker);
            }

            if (!IsPassable(x, y))
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            float danger = EnvironmentalDangerScore(cell);
            float breathable = BreathableAirAt(x, y);
            float radiation = RadiationAt(x, y);
            float germLevel = germs[x, y];

            if (radiation >= RadiationExposureThreshold)
            {
                float severity = Mathf.Clamp01((radiation - RadiationExposureThreshold) / Mathf.Max(0.001f, 1f - RadiationExposureThreshold));
                return new Color(0.68f + severity * 0.32f, 0.22f + severity * 0.38f, 0.88f - severity * 0.48f, 0.46f + severity * 0.36f);
            }

            if (danger >= SafetyDangerThreshold)
            {
                return new Color(1f, 0.18f + danger * 0.18f, 0.10f, 0.34f + danger * 0.52f);
            }

            if (breathable < BreathLowAirThreshold)
            {
                return new Color(0.24f, 0.36f, 0.92f, 0.58f);
            }

            if (breathable < BreathRecoveryAirThreshold)
            {
                return new Color(0.34f, 0.62f, 1f, 0.42f);
            }

            if (germLevel >= 0.28f || pollutedOxygen[x, y] >= 0.18f)
            {
                float germSeverity = Mathf.Clamp01(germLevel + pollutedOxygen[x, y] * 0.25f);
                return new Color(0.48f + germSeverity * 0.30f, 1f, 0.20f, 0.24f + germSeverity * 0.32f);
            }

            return new Color(0.20f, 0.96f, 0.78f, 0.18f);
        }

        private Color WorkerVitalsOverlayColor(Worker worker)
        {
            if (worker == null)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (worker.Health <= 0f)
            {
                return new Color(1f, 0.10f, 0.45f, 0.96f);
            }

            if (worker.StressBreakSeconds > 0f)
            {
                return new Color(1f, 0.32f, 0.92f, 0.92f);
            }

            if (worker.Breath <= 0.01f || worker.Health <= 35f || NeedsSeekSafety(worker))
            {
                return new Color(1f, 0.12f, 0.08f, 0.94f);
            }

            if (worker.Breath <= 22f ||
                worker.Sickness >= 70f ||
                Mathf.Max(worker.HeatExposure, worker.ChillExposure) >= ThermalInjuryExposureThreshold)
            {
                return new Color(1f, 0.58f, 0.12f, 0.90f);
            }

            if (worker.Stress >= 90f || worker.GermExposure >= 85f || WorkerMoraleDeficit(worker) > 1.25f)
            {
                return new Color(1f, 0.88f, 0.18f, 0.86f);
            }

            return new Color(0.34f, 1f, 0.58f, 0.82f);
        }

        private Color MoraleOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                return WorkerMoraleOverlayColor(worker);
            }

            CellKind kind = cells[x, y];
            if (IsRelaxationStationCell(kind))
            {
                return CanUseRelaxationStationAt(cell)
                    ? new Color(0.72f, 0.50f, 1f, 0.78f)
                    : new Color(0.52f, 0.36f, 0.24f, 0.58f);
            }

            if (kind == CellKind.SkillScrubber)
            {
                if (!CanUseSkillScrubberAt(cell))
                {
                    return new Color(0.52f, 0.30f, 0.22f, 0.58f);
                }

                return CountSkillScrubCandidates() > 0
                    ? new Color(0.26f, 0.96f, 0.86f, 0.78f)
                    : new Color(0.48f, 0.80f, 0.76f, 0.48f);
            }

            if (kind == CellKind.DecorPlant ||
                kind == CellKind.SculptingBlock ||
                kind == CellKind.CeilingLight)
            {
                float decor = DecorScoreAt(x, y);
                if (kind == CellKind.SculptingBlock && !sculptingBlockFinished[x, y])
                {
                    return new Color(0.54f, 0.50f, 0.58f, 0.42f);
                }

                return new Color(1f, 0.52f + decor * 0.24f, 0.96f, 0.48f + decor * 0.34f);
            }

            RoomInfo room = RoomAt(x, y);
            if (room != null && room.Kind != RoomKind.OpenArea)
            {
                switch (room.Kind)
                {
                    case RoomKind.GreatHall:
                        return new Color(1f, 0.68f, 0.22f, 0.46f);
                    case RoomKind.MessHall:
                        return new Color(1f, 0.82f, 0.28f, 0.40f);
                    case RoomKind.Bedroom:
                        return new Color(0.48f, 0.72f, 1f, 0.42f);
                    case RoomKind.Barracks:
                        return new Color(0.28f, 0.60f, 1f, 0.34f);
                    case RoomKind.RecreationRoom:
                        return new Color(0.72f, 0.50f, 1f, 0.44f);
                    case RoomKind.Washroom:
                        return new Color(0.28f, 0.90f, 0.86f, 0.32f);
                    case RoomKind.Clinic:
                        return new Color(1f, 0.52f, 0.66f, 0.32f);
                }
            }

            float aura = DecorScoreAt(x, y);
            if (aura > 0.08f)
            {
                return new Color(0.92f, 0.54f + aura * 0.18f, 1f, 0.12f + aura * 0.32f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color WorkerMoraleOverlayColor(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (worker.StressBreakSeconds > 0f)
            {
                return new Color(1f, 0.26f, 0.92f, 0.94f);
            }

            if (IsWorkerOverjoyed(worker))
            {
                return new Color(0.18f, 1f, 0.90f, 0.94f);
            }

            float deficit = WorkerMoraleDeficit(worker);
            if (deficit >= 2.0f)
            {
                return new Color(1f, 0.16f, 0.08f, 0.94f);
            }

            if (deficit >= 0.5f)
            {
                return new Color(1f, 0.72f, 0.14f, 0.88f);
            }

            float surplus = Mathf.Clamp(worker.Morale - WorkerMoraleNeed(worker), 0f, 6f);
            if (surplus >= OverjoyedTriggerMoraleSurplus)
            {
                return new Color(0.36f, 1f, 0.58f, 0.88f);
            }

            if (worker.Role == worker.Interest || WorkerRoleMasteryTier(worker) > 0)
            {
                return new Color(0.42f, 0.84f, 1f, 0.74f);
            }

            return new Color(0.48f, 0.86f, 0.52f, 0.62f);
        }

        private Color MedicalOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                Color workerColor = WorkerMedicalOverlayColor(worker);
                if (workerColor.a > 0f)
                {
                    return workerColor;
                }
            }

            CellKind kind = cells[x, y];
            if (kind == CellKind.MedicalCot)
            {
                bool reserved = IsMedicalCotReserved(cell);
                if (reserved)
                {
                    return new Color(0.24f, 0.88f, 1f, 0.82f);
                }

                if (AnyWorkerNeedsRescue() || AnyWorkerNeedsTreatment())
                {
                    return new Color(0.34f, 1f, 0.58f, 0.72f);
                }

                if (CountWorkersNeedingMedicalRest() > 0)
                {
                    return new Color(0.30f, 0.92f, 0.82f, 0.62f);
                }

                return new Color(0.34f, 0.56f, 0.72f, 0.46f);
            }

            if (kind == CellKind.Apothecary)
            {
                if (CanProduceMedicineAt(cell))
                {
                    return medicine < DesiredMedicineStock()
                        ? new Color(0.72f, 1f, 0.30f, 0.78f)
                        : new Color(0.42f, 0.92f, 0.62f, 0.56f);
                }

                return new Color(0.56f, 0.38f, 0.28f, 0.58f);
            }

            if (kind == CellKind.WashBasin || kind == CellKind.HandSanitizer || kind == CellKind.Shower)
            {
                bool supplied = kind == CellKind.HandSanitizer
                    ? bleachStone >= HandSanitizerBleachStoneUse
                    : CleanWaterAvailableForMachine(cell) > 0.05f;
                return supplied
                    ? new Color(0.40f, 0.92f, 0.88f, 0.42f)
                    : new Color(0.56f, 0.42f, 0.26f, 0.42f);
            }

            if (germs[x, y] >= AirborneGermExposureThreshold || pollutedOxygen[x, y] >= SlimelungPollutedOxygenThreshold)
            {
                float risk = Mathf.Clamp01(germs[x, y] + pollutedOxygen[x, y] * 0.35f);
                return new Color(0.48f + risk * 0.32f, 1f, 0.18f, 0.24f + risk * 0.38f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color WorkerMedicalOverlayColor(Worker worker)
        {
            if (worker == null)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (worker.Health <= 0f)
            {
                return new Color(1f, 0.08f, 0.38f, 0.96f);
            }

            if (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.Treat)
            {
                return new Color(0.24f, 0.88f, 1f, 0.92f);
            }

            if (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.MedicalRest)
            {
                return new Color(0.30f, 0.92f, 0.82f, 0.86f);
            }

            if (worker.Health <= 35f)
            {
                return new Color(1f, 0.16f, 0.08f, 0.94f);
            }

            if (worker.Disease != WorkerDisease.None || worker.Sickness >= 70f)
            {
                return new Color(1f, 0.52f, 0.10f, 0.90f);
            }

            if (NeedsTreatment(worker))
            {
                return new Color(1f, 0.82f, 0.16f, 0.82f);
            }

            if (NeedsMedicalRest(worker))
            {
                return new Color(0.58f, 1f, 0.70f, 0.70f);
            }

            if (worker.GermExposure >= 65f)
            {
                return new Color(0.74f, 1f, 0.20f, 0.74f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private bool NeedsAtmoSuitProtection(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPassable(cell.x, cell.y))
            {
                return false;
            }

            return carbonDioxide[cell.x, cell.y] > 1.1f ||
                pollutedOxygen[cell.x, cell.y] > 0.16f ||
                hydrogen[cell.x, cell.y] > 0.42f ||
                sourGas[cell.x, cell.y] > SourGasExposureThreshold ||
                TileGasTotal(cell.x, cell.y) > OverpressureStressThreshold ||
                temperature[cell.x, cell.y] < 0f ||
                temperature[cell.x, cell.y] > 44f;
        }

        private Color SuitOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                Color workerColor = WorkerSuitOverlayColor(worker);
                if (workerColor.a > 0f)
                {
                    return workerColor;
                }
            }

            CellKind kind = cells[x, y];
            if (kind == CellKind.AtmoSuitDock)
            {
                float capacity = SuitOxygenCapacityTotal();
                float fill = capacity > 0.001f ? Mathf.Clamp01(suitOxygen / capacity) : 0f;
                if (!CanUseEquipment(cell))
                {
                    return new Color(0.70f, 0.26f, 0.18f, 0.64f);
                }

                if (!HasAdjacentSuitCheckpoint(cell))
                {
                    return new Color(0.40f, 0.52f, 0.56f, 0.48f);
                }

                if (fill > SuitCheckpointMinimumCharge / Mathf.Max(0.001f, capacity))
                {
                    return new Color(0.08f, 0.86f, 1f, 0.42f + fill * 0.44f);
                }

                return CanPoweredMachineRun(cell) && TryFindSuitDockOxygenSource(cell, out _)
                    ? new Color(0.28f, 0.74f, 0.84f, 0.58f)
                    : new Color(0.56f, 0.38f, 0.24f, 0.56f);
            }

            if (kind == CellKind.AtmoSuitCheckpoint)
            {
                if (!CanUseEquipment(cell))
                {
                    return new Color(0.70f, 0.26f, 0.18f, 0.64f);
                }

                if (CanEquipSuitAtCheckpoint(cell))
                {
                    return new Color(0.22f, 0.90f, 1f, 0.82f);
                }

                return HasAdjacentSuitDock(cell)
                    ? new Color(0.92f, 0.58f, 0.18f, 0.66f)
                    : new Color(0.70f, 0.26f, 0.18f, 0.62f);
            }

            if (kind == CellKind.OxygenMaskDock)
            {
                float capacity = OxygenMaskCapacityTotal();
                float fill = capacity > 0.001f ? Mathf.Clamp01(maskOxygen / capacity) : 0f;
                if (!CanUseEquipment(cell))
                {
                    return new Color(0.70f, 0.26f, 0.18f, 0.64f);
                }

                if (!HasAdjacentOxygenMaskCheckpoint(cell))
                {
                    return new Color(0.32f, 0.50f, 0.66f, 0.48f);
                }

                if (fill > OxygenMaskCheckpointMinimumCharge / Mathf.Max(0.001f, capacity))
                {
                    return new Color(0.20f, 0.62f, 1f, 0.42f + fill * 0.40f);
                }

                return TryFindSuitDockOxygenSource(cell, out _)
                    ? new Color(0.28f, 0.56f, 0.90f, 0.56f)
                    : new Color(0.54f, 0.38f, 0.24f, 0.54f);
            }

            if (kind == CellKind.OxygenMaskCheckpoint)
            {
                if (!CanUseEquipment(cell))
                {
                    return new Color(0.70f, 0.26f, 0.18f, 0.64f);
                }

                if (CanEquipOxygenMaskAtCheckpoint(cell))
                {
                    return new Color(0.30f, 0.72f, 1f, 0.78f);
                }

                return HasAdjacentOxygenMaskDock(cell)
                    ? new Color(0.88f, 0.58f, 0.20f, 0.62f)
                    : new Color(0.70f, 0.26f, 0.18f, 0.60f);
            }

            if (kind == CellKind.LeadSuitLocker)
            {
                if (!CanUseEquipment(cell))
                {
                    return new Color(0.70f, 0.26f, 0.18f, 0.64f);
                }

                return HasAdjacentLeadSuitCheckpoint(cell)
                    ? new Color(0.96f, 0.86f, 0.36f, 0.78f)
                    : new Color(0.52f, 0.46f, 0.28f, 0.48f);
            }

            if (kind == CellKind.LeadSuitCheckpoint)
            {
                if (!CanUseEquipment(cell))
                {
                    return new Color(0.70f, 0.26f, 0.18f, 0.64f);
                }

                return CanEquipLeadSuitAtCheckpoint(cell)
                    ? new Color(0.96f, 0.76f, 0.26f, 0.82f)
                    : new Color(0.70f, 0.26f, 0.18f, 0.62f);
            }

            if (!IsPassable(x, y))
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (NeedsLeadSuitProtection(cell))
            {
                float radiation = RadiationAt(x, y);
                float severity = Mathf.Clamp01((radiation - RadiationExposureThreshold) / Mathf.Max(0.001f, 1f - RadiationExposureThreshold));
                return new Color(0.72f + severity * 0.24f, 0.24f + severity * 0.30f, 0.86f - severity * 0.48f, 0.40f + severity * 0.40f);
            }

            if (NeedsAtmoSuitProtection(cell))
            {
                float danger = Mathf.Max(EnvironmentalDangerScore(cell), 0.45f);
                return new Color(1f, 0.24f + danger * 0.24f, 0.10f, 0.32f + danger * 0.46f);
            }

            if (NeedsOxygenMaskProtection(cell))
            {
                float lack = Mathf.Clamp01((BreathRecoveryAirThreshold - BreathableAirAt(x, y)) / Mathf.Max(0.001f, BreathRecoveryAirThreshold));
                return new Color(0.30f, 0.62f, 1f, 0.26f + lack * 0.42f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color WorkerSuitOverlayColor(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            bool leadDanger = NeedsLeadSuitProtection(worker.Cell);
            bool atmoSuitDanger = NeedsAtmoSuitProtection(worker.Cell);
            bool maskDanger = NeedsOxygenMaskProtection(worker.Cell);
            if (leadDanger && !worker.LeadSuitEquipped)
            {
                return new Color(1f, 0.22f, 0.12f, 0.94f);
            }

            if (atmoSuitDanger && !worker.SuitEquipped)
            {
                return new Color(1f, 0.18f, 0.08f, 0.92f);
            }

            if (maskDanger && !HasWorkerBreathingGearOxygen(worker))
            {
                return new Color(1f, 0.58f, 0.14f, 0.86f);
            }

            if (worker.SuitEquipped)
            {
                return HasChargedSuitOxygen()
                    ? new Color(0.08f, 0.90f, 1f, 0.94f)
                    : new Color(1f, 0.50f, 0.14f, 0.90f);
            }

            if (worker.OxygenMaskEquipped)
            {
                return HasChargedOxygenMask()
                    ? new Color(0.30f, 0.72f, 1f, 0.88f)
                    : new Color(1f, 0.58f, 0.14f, 0.86f);
            }

            if (worker.LeadSuitEquipped)
            {
                return new Color(0.96f, 0.86f, 0.36f, 0.90f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color RadiationOverlayColor(int x, int y)
        {
            if (cells[x, y] == CellKind.LeadSuitLocker)
            {
                return HasAdjacentLeadSuitCheckpoint(new Vector2Int(x, y))
                    ? new Color(0.96f, 0.86f, 0.36f, 0.78f)
                    : new Color(0.52f, 0.46f, 0.28f, 0.48f);
            }

            if (cells[x, y] == CellKind.LeadSuitCheckpoint)
            {
                return HasAdjacentLeadSuitLocker(new Vector2Int(x, y))
                    ? new Color(1f, 0.74f, 0.22f, 0.82f)
                    : new Color(0.70f, 0.26f, 0.18f, 0.62f);
            }

            float radiation = RadiationAt(x, y);
            if (radiation <= 0.01f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            if (radiation <= RadiationExposureThreshold)
            {
                float safeScale = Mathf.Clamp01(radiation / RadiationExposureThreshold);
                return new Color(0.26f + safeScale * 0.20f, 0.20f, 0.70f + safeScale * 0.12f, 0.16f + safeScale * 0.24f);
            }

            float dangerScale = Mathf.Clamp01((radiation - RadiationExposureThreshold) / Mathf.Max(0.001f, 1f - RadiationExposureThreshold));
            return new Color(0.58f + dangerScale * 0.42f, 0.20f + dangerScale * 0.58f, 0.78f - dangerScale * 0.58f, 0.42f + dangerScale * 0.48f);
        }

        private Color GasPipeOverlayColor(int x, int y)
        {
            float total = GasPipeTotal(x, y);
            float fill = Mathf.Clamp01(total / GasPipeCapacity);
            if (total <= 0.001f)
            {
                return new Color(0.48f, 0.72f, 0.86f, 0.38f);
            }

            float dominant = gasPipeOxygen[x, y];
            dominant = Mathf.Max(dominant, gasPipeCarbonDioxide[x, y]);
            dominant = Mathf.Max(dominant, gasPipePollutedOxygen[x, y]);
            dominant = Mathf.Max(dominant, gasPipeHydrogen[x, y]);
            dominant = Mathf.Max(dominant, gasPipeSteam[x, y]);
            dominant = Mathf.Max(dominant, gasPipeChlorine[x, y]);
            dominant = Mathf.Max(dominant, gasPipeNaturalGas[x, y]);
            dominant = Mathf.Max(dominant, gasPipeSourGas[x, y]);

            if (gasPipeSteam[x, y] >= dominant)
            {
                return new Color(0.86f, 0.96f, 1f, 0.42f + fill * 0.42f);
            }

            if (gasPipeNaturalGas[x, y] >= dominant)
            {
                return new Color(1f, 0.58f, 0.14f, 0.42f + fill * 0.42f);
            }

            if (gasPipeSourGas[x, y] >= dominant)
            {
                return new Color(0.78f, 0.62f, 0.20f, 0.42f + fill * 0.42f);
            }

            if (gasPipeChlorine[x, y] >= dominant)
            {
                return new Color(0.76f, 1f, 0.18f, 0.42f + fill * 0.42f);
            }

            if (gasPipeHydrogen[x, y] >= dominant)
            {
                return new Color(0.86f, 0.36f, 1f, 0.42f + fill * 0.42f);
            }

            if (gasPipePollutedOxygen[x, y] >= dominant)
            {
                return new Color(0.28f, 1f, 0.32f, 0.42f + fill * 0.42f);
            }

            if (gasPipeCarbonDioxide[x, y] >= dominant)
            {
                return new Color(0.95f, 0.42f, 0.18f, 0.40f + fill * 0.40f);
            }

            return new Color(0.20f, 0.84f, 1f, 0.40f + fill * 0.42f);
        }

        private Color TemperatureOverlayColor(int x, int y)
        {
            float temp = temperature[x, y];
            if (temp > 34f)
            {
                return new Color(1f, 0.16f, 0.04f, Mathf.Clamp01((temp - 28f) * 0.018f + 0.16f));
            }

            if (temp < 8f)
            {
                return new Color(0.18f, 0.58f, 1f, Mathf.Clamp01((12f - temp) * 0.025f + 0.16f));
            }

            return new Color(0.2f, 1f, 0.55f, 0.08f);
        }

        private Color PowerWireOverlayColor(int x, int y)
        {
            if (cells[x, y] == CellKind.PowerShutoff)
            {
                return PowerShutoffOverlayColor(x, y);
            }

            if (overloadedWire[x, y])
            {
                return new Color(1f, 0.14f, 0.04f, 0.84f);
            }

            if (powerWireKind[x, y] == PowerWireKind.Conductive)
            {
                return poweredWire[x, y] ? new Color(1f, 0.96f, 0.42f, 0.80f) : new Color(0.64f, 0.42f, 0.12f, 0.62f);
            }

            if (powerWireKind[x, y] == PowerWireKind.HeavyWatt)
            {
                return poweredWire[x, y] ? new Color(0.96f, 0.62f, 0.18f, 0.86f) : new Color(0.46f, 0.24f, 0.08f, 0.70f);
            }

            return poweredWire[x, y] ? new Color(1f, 0.86f, 0.18f, 0.78f) : new Color(0.52f, 0.30f, 0.08f, 0.58f);
        }

        private Color PowerOverlayColor(int x, int y)
        {
            if (powerWire[x, y])
            {
                return PowerWireOverlayColor(x, y);
            }

            CellKind kind = cells[x, y];
            if (kind == CellKind.PowerTransformer)
            {
                return new Color(0.30f, 0.88f, 1f, 0.62f);
            }

            if (kind == CellKind.PowerBridge)
            {
                return PowerBridgeOverlayColor(x, y);
            }

            if (kind == CellKind.PowerShutoff)
            {
                return PowerShutoffOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationBridge)
            {
                return AutomationBridgeOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationNotGate)
            {
                return AutomationNotGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationAndGate)
            {
                return AutomationAndGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationOrGate)
            {
                return AutomationOrGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationXorGate)
            {
                return AutomationXorGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationBufferGate)
            {
                return AutomationBufferGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationFilterGate)
            {
                return AutomationFilterGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationMemoryGate)
            {
                return AutomationMemoryGateOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationCycleSensor)
            {
                return AutomationCycleSensorOverlayColor(x, y);
            }

            if (kind == CellKind.AutomationTimerSensor)
            {
                return AutomationTimerSensorOverlayColor(x, y);
            }

            if (kind == CellKind.DuplicantMotionSensor)
            {
                return DuplicantMotionSensorOverlayColor(x, y);
            }

            if (kind == CellKind.GermSensor)
            {
                return GermSensorOverlayColor(x, y);
            }

            if (kind == CellKind.WeightPlate)
            {
                return WeightPlateOverlayColor(x, y);
            }

            if (kind == CellKind.ShippingRailSensor)
            {
                return ShippingRailSensorOverlayColor(x, y);
            }

            if (kind == CellKind.ShippingRailShutoff)
            {
                return ShippingRailShutoffOverlayColor(x, y);
            }

            if (kind == CellKind.ShippingRailMeter)
            {
                return ShippingRailMeterOverlayColor(x, y);
            }

            if (IsTunableGenerator(kind) && generatorTuneUpSeconds[x, y] > 0f)
            {
                return new Color(0.34f, 1f, 0.54f, 0.64f);
            }

            if (kind == CellKind.PowerControlStation)
            {
                return new Color(0.30f, 0.95f, 0.88f, 0.52f);
            }

            if (kind == CellKind.SkillScrubber)
            {
                return CanPoweredMachineRun(new Vector2Int(x, y))
                    ? new Color(0.78f, 0.48f, 1f, 0.58f)
                    : new Color(1f, 0.12f, 0.08f, 0.62f);
            }

            if (kind == CellKind.ManualGenerator || kind == CellKind.CoalGenerator || kind == CellKind.HydrogenGenerator || kind == CellKind.NaturalGasGenerator || kind == CellKind.PetroleumGenerator || kind == CellKind.SteamTurbine || kind == CellKind.SolarPanel || kind == CellKind.ResearchReactor || kind == CellKind.Battery || kind == CellKind.JumboBattery || kind == CellKind.SmartBattery)
            {
                return new Color(1f, 0.72f, 0.18f, 0.5f);
            }

            if (RequiresPower(kind))
            {
                return CanPoweredMachineRun(new Vector2Int(x, y))
                    ? new Color(0.35f, 1f, 0.44f, 0.52f)
                    : new Color(1f, 0.12f, 0.08f, 0.62f);
            }

            return new Color(0f, 0f, 0f, 0f);
        }

        private Color PowerBridgeOverlayColor(int x, int y)
        {
            Vector2Int bridge = new Vector2Int(x, y);
            if (!CanUseEquipment(bridge))
            {
                return new Color(1f, 0.14f, 0.04f, 0.70f);
            }

            BridgeDirection direction = BridgeDirectionAt(x, y);
            bool powered = IsPowerBridgePairPowered(bridge, BridgeInputOffset(direction), BridgeOutputOffset(direction));
            return powered ? new Color(1f, 0.88f, 0.22f, 0.78f) : new Color(0.72f, 0.42f, 0.08f, 0.58f);
        }

        private Color PowerShutoffOverlayColor(int x, int y)
        {
            Vector2Int cell = new Vector2Int(x, y);
            if (!CanUseEquipment(cell))
            {
                return new Color(1f, 0.14f, 0.04f, 0.80f);
            }

            if (!HasCachedAutomationControl(cell))
            {
                return new Color(1f, 0.78f, 0.18f, 0.76f);
            }

            return IsPowerShutoffOpen(cell)
                ? new Color(0.28f, 1f, 0.32f, 0.78f)
                : new Color(1f, 0.18f, 0.10f, 0.78f);
        }

        private bool IsPowerBridgePairPowered(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset)
        {
            int inputX = bridge.x + inputOffset.x;
            int inputY = bridge.y + inputOffset.y;
            int outputX = bridge.x + outputOffset.x;
            int outputY = bridge.y + outputOffset.y;
            return IsInside(inputX, inputY) &&
                IsInside(outputX, outputY) &&
                powerWire[inputX, inputY] &&
                powerWire[outputX, outputY] &&
                poweredWire[inputX, inputY];
        }

        private Color AutomationBridgeOverlayColor(int x, int y)
        {
            Vector2Int bridge = new Vector2Int(x, y);
            if (!CanUseEquipment(bridge))
            {
                return new Color(1f, 0.18f, 0.10f, 0.68f);
            }

            bool controlled = false;
            bool signal = false;
            BridgeDirection direction = BridgeDirectionAt(x, y);
            if (AutomationBridgePairInputSignal(bridge, BridgeInputOffset(direction), BridgeOutputOffset(direction), out bool bridgeSignal))
            {
                controlled = true;
                signal |= bridgeSignal;
            }

            if (controlled)
            {
                return signal ? new Color(0.28f, 1f, 0.32f, 0.76f) : new Color(1f, 0.18f, 0.10f, 0.68f);
            }

            return new Color(0.60f, 0.44f, 1f, 0.50f);
        }

        private Color AutomationNotGateOverlayColor(int x, int y)
        {
            Vector2Int gate = new Vector2Int(x, y);
            if (!CanUseEquipment(gate))
            {
                return new Color(1f, 0.18f, 0.10f, 0.68f);
            }

            bool controlled = false;
            bool outputSignal = false;
            if (AutomationBridgePairInputSignal(gate, new Vector2Int(-1, 0), new Vector2Int(1, 0), out bool westSignal))
            {
                controlled = true;
                outputSignal |= !westSignal;
            }

            if (AutomationBridgePairInputSignal(gate, new Vector2Int(0, -1), new Vector2Int(0, 1), out bool southSignal))
            {
                controlled = true;
                outputSignal |= !southSignal;
            }

            if (controlled)
            {
                return outputSignal ? new Color(0.28f, 1f, 0.32f, 0.76f) : new Color(1f, 0.18f, 0.10f, 0.68f);
            }

            return new Color(1f, 0.42f, 0.86f, 0.52f);
        }

