        private bool AutomationBridgePairInputSignal(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, out bool signal)
        {
            signal = false;
            int inputX = bridge.x + inputOffset.x;
            int inputY = bridge.y + inputOffset.y;
            int outputX = bridge.x + outputOffset.x;
            int outputY = bridge.y + outputOffset.y;
            if (!IsInside(inputX, inputY) ||
                !IsInside(outputX, outputY) ||
                !automationWire[inputX, inputY] ||
                !automationWire[outputX, outputY] ||
                !automationControlledWire[inputX, inputY])
            {
                return false;
            }

            signal = automationSignalWire[inputX, inputY];
            return true;
        }

        private Color GermOverlayColor(int x, int y)
        {
            if (!IsPassable(x, y))
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            float germLevel = germs[x, y];
            float po2 = pollutedOxygen[x, y];
            if (germLevel <= 0.01f && po2 <= 0.02f)
            {
                return new Color(0f, 0f, 0f, 0f);
            }

            float alpha = Mathf.Clamp01(germLevel * 0.75f + po2 * 0.2f);
            return new Color(0.2f + germLevel * 0.55f, 1f, 0.18f, Mathf.Max(0.16f, alpha));
        }

        private Color JobOverlayColor(Job job)
        {
            float alpha = job.AssignedWorker == null ? 0.62f : 0.85f;
            switch (job.Type)
            {
                case JobType.Dig:
                    return new Color(1f, 0.86f, 0.22f, alpha);
                case JobType.Build:
                    return new Color(0.3f, 1f, 0.55f, alpha);
