        private bool IsRestTime()
        {
            float normalized = cycleTimer / CycleLengthSeconds;
            return sleepStartCycleTime <= sleepEndCycleTime
                ? normalized >= sleepStartCycleTime && normalized <= sleepEndCycleTime
                : normalized >= sleepStartCycleTime || normalized <= sleepEndCycleTime;
        }

        private bool IsRestTime(Worker worker)
        {
            if (worker == null)
            {
                return IsRestTime();
            }

            float start = WorkerSleepStartCycleTime(worker);
            float end = WorkerSleepEndCycleTime(worker);
            float normalized = cycleTimer / CycleLengthSeconds;
            return start <= end
                ? normalized >= start && normalized <= end
                : normalized >= start || normalized <= end;
        }

        private bool IsMealTime()
        {
            return !IsRestTime() && IsWithinCycleWindow(cycleTimer / CycleLengthSeconds, sleepEndCycleTime, MealWindowDuration);
        }

        private bool IsMealTime(Worker worker)
        {
            return worker == null
                ? IsMealTime()
                : !IsRestTime(worker) && IsWithinCycleWindow(cycleTimer / CycleLengthSeconds, WorkerSleepEndCycleTime(worker), MealWindowDuration);
        }

        private bool IsDowntime()
        {
            float downtimeStart = NormalizeCycleTime(sleepStartCycleTime - DowntimeWindowDuration);
            return !IsRestTime() && IsWithinCycleWindow(cycleTimer / CycleLengthSeconds, downtimeStart, DowntimeWindowDuration);
        }

        private bool IsDowntime(Worker worker)
        {
            if (worker == null)
            {
                return IsDowntime();
            }

            float downtimeStart = NormalizeCycleTime(WorkerSleepStartCycleTime(worker) - DowntimeWindowDuration);
            return !IsRestTime(worker) && IsWithinCycleWindow(cycleTimer / CycleLengthSeconds, downtimeStart, DowntimeWindowDuration);
        }

        private float WorkerScheduleOffsetCycleTime(Worker worker)
        {
            return worker == null ? 0f : NormalizeCrewScheduleOffset(worker.ScheduleOffsetSteps) * CrewScheduleOffsetStep;
        }

        private float WorkerSleepStartCycleTime(Worker worker)
        {
            return NormalizeCycleTime(sleepStartCycleTime + WorkerScheduleOffsetCycleTime(worker));
        }

        private float WorkerSleepEndCycleTime(Worker worker)
        {
            return NormalizeCycleTime(sleepEndCycleTime + WorkerScheduleOffsetCycleTime(worker));
        }

        private bool IsWithinCycleWindow(float normalized, float start, float duration)
        {
            normalized = NormalizeCycleTime(normalized);
            start = NormalizeCycleTime(start);
            duration = Mathf.Clamp01(duration);
            if (duration <= 0f)
            {
                return false;
            }

            if (duration >= 0.999f)
            {
                return true;
            }

            float end = NormalizeCycleTime(start + duration);
            return start <= end
                ? normalized >= start && normalized < end
                : normalized >= start || normalized < end;
        }

        private string ScheduleLabel()
        {
            if (IsRestTime())
            {
                return "Sleep " + SleepWindowLabel();
            }

            if (IsMealTime())
            {
                return "Meal " + SleepWindowLabel();
            }

            return IsDowntime() ? "Downtime " + SleepWindowLabel() : "Work " + SleepWindowLabel();
        }

        private string SleepWindowLabel()
        {
            return CycleClockLabel(sleepStartCycleTime) + "-" + CycleClockLabel(sleepEndCycleTime);
        }

        private string WorkerSleepWindowLabel(Worker worker)
        {
            return CycleClockLabel(WorkerSleepStartCycleTime(worker)) + "-" + CycleClockLabel(WorkerSleepEndCycleTime(worker));
        }

        private string SchedulePlanLabel()
        {
            float mealStart = sleepEndCycleTime;
            float mealEnd = NormalizeCycleTime(mealStart + MealWindowDuration);
            float downtimeStart = NormalizeCycleTime(sleepStartCycleTime - DowntimeWindowDuration);
            return "Sleep " + SleepWindowLabel() +
                "  Meal " + CycleClockLabel(mealStart) + "-" + CycleClockLabel(mealEnd) +
                "  Down " + CycleClockLabel(downtimeStart) + "-" + CycleClockLabel(sleepStartCycleTime);
        }

        private string WorkerSchedulePlanLabel(Worker worker)
        {
            float mealStart = WorkerSleepEndCycleTime(worker);
            float mealEnd = NormalizeCycleTime(mealStart + MealWindowDuration);
            float downtimeStart = NormalizeCycleTime(WorkerSleepStartCycleTime(worker) - DowntimeWindowDuration);
            return "Shift " + CrewScheduleOffsetLabel(worker == null ? 0 : worker.ScheduleOffsetSteps) +
                "  Sleep " + WorkerSleepWindowLabel(worker) +
                "  Meal " + CycleClockLabel(mealStart) + "-" + CycleClockLabel(mealEnd) +
                "  Down " + CycleClockLabel(downtimeStart) + "-" + CycleClockLabel(WorkerSleepStartCycleTime(worker));
        }

        private string WorkerSchedulePressureText(Worker worker)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                redAlertActive ||
                (worker.AssignedJob != null && worker.AssignedJob.YellowAlert))
            {
                return string.Empty;
            }

            JobType? current = worker.AssignedJob != null ? worker.AssignedJob.Type : (JobType?)null;
            if (IsMealTime(worker) &&
                current != JobType.Eat &&
                worker.Calories < ScheduledMealCalorieThreshold)
            {
                return "Schedule pressure: missing meal time while hungry.";
            }

            if (IsDowntime(worker) &&
                current != JobType.Relax &&
                CountUsableRelaxationStations() > 0 &&
                worker.Stress >= ScheduledDowntimeStressThreshold)
            {
                return "Schedule pressure: downtime stress care skipped.";
            }

            return string.Empty;
        }

        private string WorkerCommuteText(Worker worker)
        {
            if (worker == null || worker.Health <= 0f || worker.CommuteSeconds < CommuteNoticeSeconds)
            {
                return string.Empty;
