            string prefix = worker.CommuteSeconds >= LongCommuteSevereThresholdSeconds
                ? "Long commute severe "
                : worker.CommuteSeconds >= LongCommuteThresholdSeconds ? "Long commute " : "Commute ";
            return prefix + worker.CommuteSeconds.ToString("0") + "s this cycle.";
        }

