        private string CycleClockLabel(float normalized)
        {
            normalized = NormalizeCycleTime(normalized);
            int minutes = Mathf.RoundToInt(normalized * 24f * 60f) % (24 * 60);
            int hour = minutes / 60;
            int minute = minutes % 60;
            return hour.ToString("00") + ":" + minute.ToString("00");
        }

        private bool IsSleeping(Worker worker)
        {
            return worker.AssignedJob != null && worker.AssignedJob.Type == JobType.Sleep && worker.PathIndex >= worker.Path.Count;
        }

        private bool IsWorkerDrowsy(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                worker.Fatigue >= DrowsyFatigueThreshold &&
                !IsSleeping(worker) &&
                worker.NarcolepticNapSeconds <= 0f &&
                worker.ExhaustedCollapseSeconds <= 0f;
        }

        private bool IsWorkerInDrabSurroundings(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                !IsSleeping(worker) &&
                worker.NarcolepticNapSeconds <= 0f &&
                worker.ExhaustedCollapseSeconds <= 0f &&
                IsInside(worker.Cell.x, worker.Cell.y) &&
                IsPassable(worker.Cell.x, worker.Cell.y) &&
                DecorScoreAt(worker.Cell.x, worker.Cell.y) < DrabDecorThreshold;
        }

        private int CountNearbyLoudSleepers(Worker worker)
        {
            if (worker == null || worker.Health <= 0f || !IsSleeping(worker))
            {
                return 0;
            }

            int count = 0;
            foreach (Worker other in workers)
            {
                if (other == worker ||
                    other.Health <= 0f ||
                    other.Trait != WorkerTrait.LoudSleeper ||
                    !IsSleeping(other))
                {
                    continue;
                }

                int distance = Mathf.Abs(worker.Cell.x - other.Cell.x) + Mathf.Abs(worker.Cell.y - other.Cell.y);
                if (distance <= LoudSleeperRadius)
                {
                    count++;
                }
            }

            return count;
        }

        private float SleepDisruptionFactor(Worker worker)
        {
            return Mathf.Clamp01(CountNearbyLoudSleepers(worker) / 2f);
        }

        private bool ShouldSleep(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            if (redAlertActive || HasOpenYellowAlertJobFor(worker))
            {
                return worker.Fatigue >= 96f || worker.Stress >= 98f;
            }

            return worker.Fatigue >= 88f || worker.Stress >= 94f || (IsRestTime(worker) && worker.Fatigue >= 35f);
        }

        private string WorkerSleepBlockedText(Worker worker)
        {
            if (!ShouldSleep(worker))
            {
                return string.Empty;
            }

            if (HasSleepJobFor(worker.Name) || (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.Sleep))
            {
                return string.Empty;
            }

            if (TryFindReachableSleepPlace(worker, out _))
            {
                return string.Empty;
            }

            bool hasAnyFloorSleepCell = HasAnyFloorSleepCellNear(worker);
            bool hasOpenFloorSleepCell = HasOpenFloorSleepCellNear(worker);

            if (CountBeds() == 0 && !hasAnyFloorSleepCell)
            {
                return "Personal need blocked: build a Bed or open a safe floor sleep spot.";
            }

            if (!AnyUsableBedFor(worker) && !hasAnyFloorSleepCell)
            {
                if (AnyComfyBedBlockedByResearch())
                {
                    return "Personal need blocked: research Power Regulation for Comfy Bed.";
                }

                if (AnyBedSubmerged())
                {
                    return "Personal need blocked: no usable bed; check flooded beds or assignments.";
                }
            }

            if (hasAnyFloorSleepCell && !hasOpenFloorSleepCell)
            {
                return "Personal need blocked: safe floor sleep spots are occupied or reserved.";
            }

            if (!HasOpenBedFor(worker) && !hasOpenFloorSleepCell)
            {
                return "Personal need blocked: all beds are reserved or assigned.";
            }

            if (TryGetPersonalNeedRouteBlockText(worker, JobType.Sleep, out string sleepRouteBlockText))
            {
                return sleepRouteBlockText;
            }

            return "Personal need blocked: no safe place to sleep.";
        }

        private bool TryFindReachableSleepPlace(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int bedCell = new Vector2Int(x, y);
                    if (!CanUseBedAt(bedCell) ||
                        IsBedReserved(bedCell) ||
                        !CanWorkerUsePersonalStation(bedCell, worker))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Sleep, bedCell, SleepWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            if (TryFindFloorSleepCell(worker, out _, out List<Vector2Int> floorSleepPath))
            {
                bestDistance = Mathf.Min(bestDistance, floorSleepPath.Count);
            }

            return bestDistance < int.MaxValue;
        }

        private bool HasOpenBedFor(Worker worker)
        {
            if (worker == null)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int bedCell = new Vector2Int(x, y);
                    if (CanUseBedAt(bedCell) &&
                        !IsBedReserved(bedCell) &&
                        CanWorkerUsePersonalStation(bedCell, worker))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyUsableBedFor(Worker worker)
        {
            if (worker == null)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int bedCell = new Vector2Int(x, y);
                    if (CanUseBedAt(bedCell) && CanWorkerUsePersonalStation(bedCell, worker))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyComfyBedBlockedByResearch()
        {
            if (techPowerRegulation)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.ComfyBed)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyBedSubmerged()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsBedSubmerged(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool HasOpenFloorSleepCellNear(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int distance = 0; distance <= 8; distance++)
            {
                for (int dy = -distance; dy <= distance; dy++)
                {
                    int dxLimit = distance - Mathf.Abs(dy);
                    for (int dx = -dxLimit; dx <= dxLimit; dx++)
                    {
                        if (Mathf.Abs(dx) + Mathf.Abs(dy) != distance)
                        {
                            continue;
                        }

                        Vector2Int candidate = worker.Cell + new Vector2Int(dx, dy);
                        Worker occupant = WorkerAt(candidate);
                        if (IsFloorSleepCell(candidate) &&
                            !IsFloorSleepCellReserved(candidate) &&
                            (occupant == null || occupant == worker))
                        {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool HasAnyFloorSleepCellNear(Worker worker)
        {
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int distance = 0; distance <= 8; distance++)
            {
                for (int dy = -distance; dy <= distance; dy++)
                {
                    int dxLimit = distance - Mathf.Abs(dy);
                    for (int dx = -dxLimit; dx <= dxLimit; dx++)
                    {
                        if (Mathf.Abs(dx) + Mathf.Abs(dy) != distance)
                        {
                            continue;
                        }

                        if (IsFloorSleepCell(worker.Cell + new Vector2Int(dx, dy)))
                        {
                            return true;
                        }
                    }
                }
            }

            return false;
        }

        private bool AnyWorkerNeedsSleep()
        {
            foreach (Worker worker in workers)
            {
                if (ShouldSleep(worker))
                {
                    return true;
                }
            }

            return false;
        }

        private bool IsPersonalAssignableStation(CellKind kind)
        {
            return IsBedKind(kind) || kind == CellKind.MessTable || kind == CellKind.MedicalCot;
        }

        private string PersonalStationAssignedWorkerName(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsPersonalAssignableStation(cells[cell.x, cell.y]))
            {
                return string.Empty;
            }

            string workerName = IsBedKind(cells[cell.x, cell.y])
                ? bedAssignedWorkerName[cell.x, cell.y]
                : cells[cell.x, cell.y] == CellKind.MessTable
                    ? messTableAssignedWorkerName[cell.x, cell.y]
                    : medicalCotAssignedWorkerName[cell.x, cell.y];
            if (string.IsNullOrEmpty(workerName))
            {
                return string.Empty;
            }

            if (FindWorkerByName(workerName) != null)
            {
                return workerName;
            }

            SetPersonalStationAssignedWorkerName(cell, string.Empty);
            return string.Empty;
        }

        private void SetPersonalStationAssignedWorkerName(Vector2Int cell, string workerName)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return;
            }

            workerName = string.IsNullOrEmpty(workerName) ? string.Empty : workerName;
            if (IsBedKind(cells[cell.x, cell.y]))
            {
                bedAssignedWorkerName[cell.x, cell.y] = workerName;
            }
            else if (cells[cell.x, cell.y] == CellKind.MessTable)
            {
                messTableAssignedWorkerName[cell.x, cell.y] = workerName;
            }
            else if (cells[cell.x, cell.y] == CellKind.MedicalCot)
            {
                medicalCotAssignedWorkerName[cell.x, cell.y] = workerName;
            }
        }

        private bool IsPersonalStationAssignedToWorker(Vector2Int cell, Worker worker)
        {
            return worker != null && PersonalStationAssignedWorkerName(cell) == worker.Name;
        }

        private bool CanWorkerUsePersonalStation(Vector2Int cell, Worker worker)
        {
            string assignedWorker = PersonalStationAssignedWorkerName(cell);
            return string.IsNullOrEmpty(assignedWorker) || (worker != null && assignedWorker == worker.Name);
        }

        private bool CanWorkerUseJobPersonalStation(Worker worker, Job job)
        {
            if (job == null)
            {
                return false;
            }

            if ((job.Type != JobType.Sleep && job.Type != JobType.Eat && job.Type != JobType.Treat && job.Type != JobType.MedicalRest) ||
                !IsInside(job.Cell.x, job.Cell.y) ||
                !IsPersonalAssignableStation(cells[job.Cell.x, job.Cell.y]))
            {
                return true;
            }

            return CanWorkerUsePersonalStation(job.Cell, worker);
        }

        private string PersonalStationAssignmentText(Vector2Int cell)
        {
            string workerName = PersonalStationAssignedWorkerName(cell);
            return string.IsNullOrEmpty(workerName)
                ? "Assignment: any duplicant."
                : "Assignment: " + workerName + ".";
        }

        private string PersonalStationAssignmentButtonText(Vector2Int cell)
        {
            string workerName = PersonalStationAssignedWorkerName(cell);
            return string.IsNullOrEmpty(workerName) ? "Assign\nAny" : "Assign\n" + ShortWorkerName(workerName);
        }

        private string ShortWorkerName(string workerName)
        {
            if (string.IsNullOrEmpty(workerName) || workerName.Length <= 5)
            {
                return string.IsNullOrEmpty(workerName) ? "Any" : workerName;
            }

            return workerName.Substring(0, 5);
        }

        private bool IsBedReserved(Vector2Int bedCell)
        {
            foreach (Job job in jobs)
            {
                if (job.Type == JobType.Sleep && job.Cell == bedCell)
                {
                    return true;
                }
            }

            return false;
        }

        private bool IsMedicalCotReserved(Vector2Int cotCell)
        {
            return IsMedicalCotReserved(cotCell, null);
        }

        private bool HasUsableMedicalCot()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cotCell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.MedicalCot && CanUseEquipment(cotCell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool IsMedicalCotReserved(Vector2Int cotCell, Worker allowedOccupant)
        {
            foreach (Job job in jobs)
            {
                if ((job.Type == JobType.Treat || job.Type == JobType.MedicalRest) && job.Cell == cotCell)
                {
                    if (allowedOccupant != null && job.TargetWorkerName == allowedOccupant.Name)
                    {
                        continue;
                    }

                    return true;
                }

                if (job.Type == JobType.Rescue && job.AssignedWorker != null)
                {
                    return true;
                }
            }

            foreach (Worker worker in workers)
            {
                if (worker == null ||
                    worker == allowedOccupant ||
                    worker.Health <= 0f ||
                    worker.Cell != cotCell)
                {
                    continue;
                }

                if (worker.Activity == "Receiving Treatment" ||
                    worker.Activity == "Recovering" ||
                    NeedsTreatment(worker))
                {
                    return true;
                }
            }

            return false;
        }

