        private bool IsPersonalRecoveryCellReserved(Vector2Int cell, Job ignoredJob = null)
        {
            foreach (Job job in jobs)
            {
                if (job == null || job == ignoredJob || job.Cell != cell)
                {
                    continue;
                }

                if (job.Type == JobType.CatchBreath ||
                    job.Type == JobType.SeekSafety ||
                    IsFloorSleepJob(job) ||
                    IsFloorEatJob(job) ||
                    IsFloorMedicalRestJob(job) ||
                    IsTakeBreakJob(job))
                {
                    return true;
                }
            }

            return false;
        }

        private bool IsPersonalRecoveryCellOpen(Vector2Int cell, Worker worker, Job ignoredJob = null)
        {
            if (IsPersonalRecoveryCellReserved(cell, ignoredJob))
            {
                return false;
            }

            Worker occupant = WorkerAt(cell);
            return occupant == null || occupant == worker;
        }

        private float TakeBreakStressCapAt(Vector2Int cell)
        {
            RoomKind roomKind = RoomKindAt(cell.x, cell.y);
            return roomKind == RoomKind.RecreationRoom || roomKind == RoomKind.GreatHall
                ? TakeBreakRoomStressCap
                : TakeBreakStressCap;
        }

        private bool IsComfyBedCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && cells[cell.x, cell.y] == CellKind.ComfyBed;
