        private bool IsBedKind(CellKind kind)
        {
            return kind == CellKind.Bed || kind == CellKind.ComfyBed;
        }

        private bool IsToiletCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                (cells[cell.x, cell.y] == CellKind.Outhouse || cells[cell.x, cell.y] == CellKind.Lavatory);
        }

        private bool CanUseToiletAt(Vector2Int cell)
        {
            if (!IsToiletCell(cell) || !CanUseEquipment(cell))
            {
                return false;
            }

            if (cells[cell.x, cell.y] == CellKind.Lavatory)
            {
                return CleanWaterAvailableForMachine(cell) >= LavatoryWaterUse;
            }

            return true;
        }

        private bool IsHandWashStationCell(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                (cells[cell.x, cell.y] == CellKind.WashBasin || cells[cell.x, cell.y] == CellKind.HandSanitizer);
        }

        private bool CanUseHandWashStationAt(Vector2Int cell)
        {
            if (!IsHandWashStationCell(cell) || !CanUseEquipment(cell))
            {
                return false;
            }

            if (cells[cell.x, cell.y] == CellKind.HandSanitizer)
            {
                return bleachStone >= HandSanitizerBleachStoneUse;
            }

            return CleanWaterAvailableForMachine(cell) > 0.05f;
        }

        private float HandWashWorkFactor(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return 0f;
            }

            if (cells[cell.x, cell.y] == CellKind.HandSanitizer)
            {
                return bleachStone >= HandSanitizerBleachStoneUse ? 1.18f : 0.20f;
            }

            return CleanWaterAvailableForMachine(cell) > 0.05f ? 1f : 0.35f;
        }

