        private bool IsRelaxationStationCell(CellKind kind)
        {
            return kind == CellKind.MassageTable || kind == CellKind.WaterCooler || kind == CellKind.ArcadeCabinet;
        }

        private bool CanUseRelaxationStationAt(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y))
            {
                return false;
            }

            if (!IsRelaxationStationCell(cells[cell.x, cell.y]))
            {
                return false;
            }

            if (cells[cell.x, cell.y] == CellKind.MassageTable)
            {
                return CanUseEquipment(cell);
            }

            if (cells[cell.x, cell.y] == CellKind.ArcadeCabinet)
            {
                return CanPoweredMachineRun(cell) && plastic >= ArcadeCabinetPlasticUse;
            }

            return cells[cell.x, cell.y] == CellKind.WaterCooler &&
                CanUseEquipment(cell) &&
                CleanWaterAvailableForMachine(cell) >= WaterCoolerWaterUse;
        }

