        private int CountUnprotectedRadiationExposedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f &&
                    !worker.LeadSuitEquipped &&
                    RadiationAt(worker.Cell.x, worker.Cell.y) > RadiationExposureThreshold)
                {
                    count++;
                }
            }

            return count;
        }

        private void UpdatePowerRecoveryProgress(bool force)
        {
            if (!IsPowerRecoveryStable())
            {
                powerRecoverySeconds = 0f;
                return;
            }

            if (!force)
            {
                powerRecoverySeconds = Mathf.Min(
                    PowerRecoveryTargetSeconds,
                    powerRecoverySeconds + ObjectiveRefreshSeconds);
            }
        }

        private bool IsPowerRecoveryStable()
        {
            return milestonePowerLoadManagement &&
                milestoneAutomation &&
                maxPower >= 160f &&
                power >= maxPower * PowerRecoveryMinimumBuffer &&
                CountCells(CellKind.SmartBattery) > 0 &&
                CountAutomationControlledGenerators() > 0 &&
                CountPoweredBuildings() > 0 &&
                CountUnwiredPowerBuildings() == 0 &&
                CountOverloadedPowerWires() == 0 &&
                MaxPowerWireLoad() <= WireSafeLoad + PowerTransformerLoadBonus + 0.001f &&
                CountFloodedPowerWires() == 0 &&
                !AnyWorkerNeedsRescue();
        }

        private void UpdateColonyMonumentProgress(bool force, int finishedSculptingBlocks, float averageWorkerDecor, int lowMoraleWorkers, int brokenEquipment)
        {
            if (!IsColonyMonumentStable(finishedSculptingBlocks, averageWorkerDecor, lowMoraleWorkers, brokenEquipment))
            {
                colonyMonumentCeremonySeconds = 0f;
                return;
            }

            if (!force)
            {
                colonyMonumentCeremonySeconds = Mathf.Min(
                    ColonyMonumentCeremonyTargetSeconds,
                    colonyMonumentCeremonySeconds + ObjectiveRefreshSeconds);
            }
        }

        private bool IsColonyMonumentStable(int finishedSculptingBlocks, float averageWorkerDecor, int lowMoraleWorkers, int brokenEquipment)
        {
            EnsureRooms();
            return milestoneDeepSpaceSurvey &&
                milestoneSustainableOperations &&
                milestoneDecorComfort &&
                finishedSculptingBlocks >= ColonyMonumentMinimumSculptures &&
                averageWorkerDecor >= ColonyMonumentMinimumDecor &&
                lowMoraleWorkers == 0 &&
                HighestStress() <= ColonyMonumentMaximumStress &&
                CountRoomsOfKind(RoomKind.RecreationRoom) + CountRoomsOfKind(RoomKind.GreatHall) > 0 &&
                brokenEquipment == 0 &&
                CountLongCommuteWorkers() == 0 &&
                CountActiveWorkers() > 0 &&
                !AnyWorkerNeedsRescue();
        }

        private void UpdateCoolingLoopStabilityProgress(bool force)
        {
            if (!IsCoolingLoopStable())
            {
                ResetCoolingLoopStabilityProgress();
                return;
            }

            if (pipeBurstEvents != coolingLoopPipeBurstBaseline ||
                reservoirBurstEvents != coolingLoopReservoirBurstBaseline)
            {
                ResetCoolingLoopStabilityProgress();
                return;
            }

            if (!force)
            {
                coolingLoopStableSeconds = Mathf.Min(
                    CoolingLoopTargetSeconds,
                    coolingLoopStableSeconds + ObjectiveRefreshSeconds);
            }
        }

        private void ResetCoolingLoopStabilityProgress()
        {
            coolingLoopStableSeconds = 0f;
            coolingLoopPipeBurstBaseline = pipeBurstEvents;
            coolingLoopReservoirBurstBaseline = reservoirBurstEvents;
        }

        private bool IsCoolingLoopStable()
        {
            return techThermalEngineering &&
                milestoneMetalRefinery &&
                CountCells(CellKind.ThermoAquatuner) > 0 &&
                CountRunningThermoAquatuners() > 0 &&
                thermoAquatunerWaterCooled >= CoolingLoopMinimumAquatunedLiquid &&
                CountLiquidPipeTiles() >= 6 &&
                CountUnsafeLiquidPipes() == 0 &&
                CountUnsafeLiquidReservoirs() == 0 &&
                CountUnsafeTemperatureTiles() < 20 &&
                AverageTemperature() >= 10f &&
                AverageTemperature() <= 36f &&
                !AnyWorkerNeedsRescue();
        }

        private void UpdateIndustrialSaunaProgress(bool force)
        {
            if (!IsIndustrialSaunaStable())
            {
                ResetIndustrialSaunaProgress();
                return;
            }

            if (equipmentFailures != industrialSaunaEquipmentFailureBaseline ||
                pipeBurstEvents != industrialSaunaPipeBurstBaseline ||
                reservoirBurstEvents != industrialSaunaReservoirBurstBaseline ||
                heatStrokeCases != industrialSaunaHeatStrokeBaseline)
            {
                ResetIndustrialSaunaProgress();
                return;
            }

            if (!force)
            {
                industrialSaunaStableSeconds = Mathf.Min(
                    IndustrialSaunaTargetSeconds,
                    industrialSaunaStableSeconds + ObjectiveRefreshSeconds);
            }
        }

        private void ResetIndustrialSaunaProgress()
        {
            industrialSaunaStableSeconds = 0f;
            industrialSaunaEquipmentFailureBaseline = equipmentFailures;
            industrialSaunaPipeBurstBaseline = pipeBurstEvents;
            industrialSaunaReservoirBurstBaseline = reservoirBurstEvents;
            industrialSaunaHeatStrokeBaseline = heatStrokeCases;
        }

        private bool IsIndustrialSaunaStable()
        {
            return milestoneCoolingLoop &&
                milestoneSteamPower &&
                milestoneInsulation &&
                techAdvancedPower &&
                techThermalEngineering &&
                CountCells(CellKind.InsulatedTile) >= 8 &&
                CountIndustrialSaunaRooms() > 0 &&
                CountIndustrialSaunaReadyMachines() > 0 &&
                CountHeatRecoverySteamTurbines() > 0 &&
                steamTurbinePowerGenerated >= IndustrialSaunaMinimumSteamPower &&
                CountBrokenEquipment() == 0 &&
                CountSubmergedEquipment() == 0 &&
                CountUnsafeLiquidPipes() == 0 &&
                CountUnsafeLiquidReservoirs() == 0 &&
                CountCriticalThermalExposureWorkers() == 0 &&
                !AnyWorkerNeedsRescue();
        }

        private int CountIndustrialSaunaRooms()
        {
            EnsureRooms();
            int count = 0;
            for (int i = 0; i < rooms.Count; i++)
            {
                if (IsIndustrialSaunaRoom(rooms[i]))
                {
                    count++;
                }
            }

            return count;
        }

        private bool IsIndustrialSaunaRoom(RoomInfo room)
        {
            float averageTemperature = room == null ? 22f : RoomAverageTemperature(room.Id);
            return room != null &&
                room.Enclosed &&
                (room.Kind == RoomKind.MachineRoom || room.Kind == RoomKind.PowerPlant) &&
                averageTemperature >= IndustrialSaunaMinimumRoomTemperature &&
                averageTemperature <= IndustrialSaunaMaximumRoomTemperature &&
                RoomHotSteamMass(room.Id) >= IndustrialSaunaMinimumSteamMass &&
                RoomContainsIndustrialHeatProducer(room.Id);
        }

        private float RoomAverageTemperature(int roomId)
        {
            float total = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (roomIds[x, y] == roomId)
                    {
                        total += temperature[x, y];
                        count++;
                    }
                }
            }

            return count == 0 ? 22f : total / count;
        }

        private float RoomHotSteamMass(int roomId)
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (roomIds[x, y] == roomId && temperature[x, y] >= IndustrialSaunaMinimumRoomTemperature)
                    {
                        total += steam[x, y];
                    }
                }
            }

            return total;
        }

        private bool RoomContainsIndustrialHeatProducer(int roomId)
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (roomIds[x, y] == roomId && IsIndustrialSaunaHeatProducer(cells[x, y]))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private int CountIndustrialSaunaReadyMachines()
        {
            EnsureRooms();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    int roomId = roomIds[x, y];
                    if (roomId < 0 || roomId >= rooms.Count || !IsIndustrialSaunaRoom(rooms[roomId]))
                    {
                        continue;
                    }

                    if (CanIndustrialSaunaHeatProducerOperate(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsIndustrialSaunaHeatProducer(CellKind kind)
        {
            return kind == CellKind.MetalRefinery ||
                kind == CellKind.OilRefinery ||
                kind == CellKind.EthanolDistiller ||
                kind == CellKind.PolymerPress ||
                kind == CellKind.PetroleumGenerator ||
                kind == CellKind.ThermoAquatuner ||
                kind == CellKind.SourGasCondenser ||
                kind == CellKind.ResearchReactor ||
                kind == CellKind.RadboltCollector;
        }

        private int CountIndustrialSaunaHeatProducers()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsIndustrialSaunaHeatProducer(cells[x, y]))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool CanIndustrialSaunaHeatProducerOperate(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || !IsIndustrialSaunaHeatProducer(cells[cell.x, cell.y]))
            {
                return false;
            }

            switch (cells[cell.x, cell.y])
            {
                case CellKind.MetalRefinery:
                    return CanMetalRefineryRun(cell);
                case CellKind.OilRefinery:
                    return techAdvancedPower && CanPoweredMachineRun(cell) && crudeOil > 0.001f;
                case CellKind.EthanolDistiller:
                    return CanEthanolDistillerRun(cell);
                case CellKind.PolymerPress:
                    return CanPoweredMachineRun(cell) && petroleum > 0.001f && DryResourceFreeSpace() > 0.001f;
                case CellKind.PetroleumGenerator:
                    return techAdvancedPower &&
                        CanUseEquipment(cell) &&
                        HasWireAccess(cell) &&
                        PetroleumFuelAvailable(cell) > 0.01f &&
                        (!HasAutomationControl(cell) || HasAutomationSignal(cell));
                case CellKind.ThermoAquatuner:
                    return CanThermoAquatunerCoolLiquid(cell);
                case CellKind.SourGasCondenser:
                    return CanSourGasCondenserRun(cell);
                case CellKind.ResearchReactor:
                    return CanResearchReactorRun(cell);
                case CellKind.RadboltCollector:
                    return CanRadboltCollectorRun(cell);
                default:
                    return false;
            }
        }

