        }

        private void UpdateRadiationContainmentProgress(bool force)
        {
            if (!IsRadiationContainmentStable())
            {
                radiationContainmentSeconds = 0f;
                return;
            }

            if (!force)
            {
                radiationContainmentSeconds = Mathf.Min(
                    RadiationContainmentTargetSeconds,
                    radiationContainmentSeconds + ObjectiveRefreshSeconds);
            }
        }

        private bool IsRadiationContainmentStable()
        {
            return milestoneLeadSuits &&
                techSpaceSystems &&
                UsableLeadSuitLockerCount() > 0 &&
                CountUsableCells(CellKind.LeadSuitCheckpoint) > 0 &&
                CountRadiationDangerTiles() > 0 &&
                leadSuitCheckpointUses >= 2 &&
                CountUnprotectedRadiationExposedWorkers() == 0 &&
                CountWorkersWithDisease(WorkerDisease.RadiationSickness) == 0 &&
                !AnyWorkerNeedsRescue();
        }

        private bool AnyWorkerNeedsRescue()
        {
            foreach (Worker worker in workers)
            {
                if (NeedsRescue(worker))
                {
                    return true;
                }
            }

            return false;
        }

