        private int CountSkillScrubCandidates()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (NeedsSkillScrub(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private bool NeedsTreatment(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                (worker.Sickness >= 35f || worker.GermExposure >= 70f || worker.Health <= 72f);
        }

        private bool NeedsMedicalLeave(Worker worker)
        {
            return medicalLeavePolicyActive &&
                worker != null &&
                worker.Health > 0f &&
                (worker.Disease != WorkerDisease.None ||
                    worker.Sickness >= MedicalLeaveSicknessThreshold ||
                    worker.GermExposure >= MedicalLeaveGermThreshold ||
                    worker.Health <= MedicalLeaveHealthThreshold);
        }

        private bool NeedsMedicalRest(Worker worker)
        {
            return NeedsMedicalLeave(worker) &&
                !NeedsTreatment(worker) &&
                !NeedsRescue(worker);
        }

        private bool NeedsRescue(Worker worker)
        {
            return worker != null && worker.Health <= 0f;
        }

        private bool NeedsCatchBreath(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                !HasWorkerBreathingGearOxygen(worker) &&
                worker.Breath < CatchBreathThreshold &&
                BreathableAirAt(worker.Cell.x, worker.Cell.y) < BreathRecoveryAirThreshold;
        }

        private bool NeedsSeekSafety(Worker worker)
        {
            if (HasDepletedBreathingGearInUnsafeArea(worker))
            {
                return true;
            }

            return IsWorkerEnvironmentDangerous(worker) && !HasRecoveredFromEnvironmentDanger(worker);
        }

        private string WorkerCatchBreathBlockedText(Worker worker)
        {
            if (!NeedsCatchBreath(worker))
            {
                return string.Empty;
            }

            if (HasSeekSafetyJobFor(worker.Name) ||
                HasCatchBreathJobFor(worker.Name) ||
                (worker.AssignedJob != null && (worker.AssignedJob.Type == JobType.SeekSafety || worker.AssignedJob.Type == JobType.CatchBreath)))
            {
                return string.Empty;
            }

            if (TryFindCatchBreathCell(worker, out _))
            {
                return string.Empty;
            }

            bool hasBreathableCell = HasBreathableRecoveryCellNear(worker);
            List<Vector2Int> openBreathableTargets = BuildCatchBreathRecoveryTargets(worker, true);
            if (hasBreathableCell && openBreathableTargets.Count == 0)
            {
                return "Personal need blocked: all breathable safe air spots are occupied or reserved.";
            }

            if (openBreathableTargets.Count > 0 &&
                TryGetPersonalRecoveryRouteBlockText(worker, JobType.CatchBreath, openBreathableTargets, out string breathRouteBlockText))
            {
                return breathRouteBlockText;
            }

            return hasBreathableCell
                ? "Personal need blocked: no safe route to breathable air."
                : "Personal need blocked: no breathable safe air found nearby.";
        }

        private string WorkerSeekSafetyBlockedText(Worker worker)
        {
            if (!NeedsSeekSafety(worker))
            {
                return string.Empty;
            }

            if (HasSeekSafetyJobFor(worker.Name) || (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.SeekSafety))
            {
                return string.Empty;
            }

            if (TryFindSafetyCell(worker, out _))
            {
                return string.Empty;
            }

            bool hasSafetyCell = HasSafetyRecoveryCellNear(worker);
            List<Vector2Int> openSafetyTargets = BuildSafetyRecoveryTargets(worker, true);
            if (hasSafetyCell && openSafetyTargets.Count == 0)
            {
                return "Personal need blocked: all safe refuges are occupied or reserved.";
            }

            if (openSafetyTargets.Count > 0 &&
                TryGetPersonalRecoveryRouteBlockText(worker, JobType.SeekSafety, openSafetyTargets, out string safetyRouteBlockText))
            {
                return safetyRouteBlockText;
            }

            return hasSafetyCell
                ? "Personal need blocked: no safe route to a refuge."
                : "Personal need blocked: no safe refuge found nearby.";
        }

        private bool HasBreathableRecoveryCellNear(Worker worker, bool requireOpen = false)
        {
            if (worker == null)
            {
                return false;
            }

            return BuildCatchBreathRecoveryTargets(worker, requireOpen).Count > 0;
        }

        private bool HasSafetyRecoveryCellNear(Worker worker, bool requireOpen = false)
        {
            if (worker == null)
            {
                return false;
            }

            return BuildSafetyRecoveryTargets(worker, requireOpen).Count > 0;
        }

        private bool TryGetPersonalRecoveryRouteBlockText(Worker worker, JobType jobType, List<Vector2Int> targets, out string text)
        {
            text = string.Empty;
            if (worker == null || targets == null || targets.Count == 0)
            {
                return false;
            }

            if (TryFindPathIgnoringProtectionCheckpoints(worker.Cell, targets, out List<Vector2Int> protectionPath))
            {
                text = PersonalProtectionCheckpointBlockText(worker, protectionPath);
                if (!string.IsNullOrEmpty(text))
                {
                    return true;
                }
            }

            Job pathProbe = new Job(jobType, worker.Cell, jobType == JobType.CatchBreath ? CatchBreathWorkRequired : SafetyWorkRequired)
            {
                TargetWorkerName = worker.Name
            };
            if (TryFindPathIgnoringDoorRestrictions(worker.Cell, targets, out List<Vector2Int> doorPath))
            {
                text = PersonalDoorPathBlockText(worker, pathProbe, doorPath);
                if (!string.IsNullOrEmpty(text))
                {
                    return true;
                }
            }

            return false;
        }

        private string PersonalProtectionCheckpointBlockText(Worker worker, List<Vector2Int> path)
        {
            if (worker == null || path == null)
            {
                return string.Empty;
            }

            Vector2Int previous = worker.Cell;
            foreach (Vector2Int step in path)
            {
                if (IsSuitCheckpointCell(previous) && NeedsSuitProtection(step) && !CanEquipSuitAtCheckpoint(previous))
                {
                    return PersonalAtmoSuitCheckpointBlockText(previous);
                }

                if (IsOxygenMaskCheckpointCell(previous) && NeedsOxygenMaskProtection(step) && !CanEquipOxygenMaskAtCheckpoint(previous))
                {
                    return PersonalOxygenMaskCheckpointBlockText(previous);
                }

                if (IsLeadSuitCheckpointCell(previous) && NeedsLeadSuitProtection(step) && !CanEquipLeadSuitAtCheckpoint(previous))
                {
                    return PersonalLeadSuitCheckpointBlockText(previous);
                }

                previous = step;
            }

            return string.Empty;
        }

        private string PersonalAtmoSuitCheckpointBlockText(Vector2Int checkpoint)
        {
            if (!HasAdjacentSuitDock(checkpoint))
            {
                return "Personal need blocked: Atmo Suit Checkpoint needs an adjacent repaired Atmo Suit Dock.";
            }

            if (AvailableSuitCount() <= 0)
            {
                return "Personal need blocked: all Atmo Suits are in use.";
            }

            if (!HasChargedSuitOxygen())
            {
                return "Personal need blocked: Atmo Suit Checkpoint needs charged suit oxygen.";
            }

            return "Personal need blocked: Atmo Suit Checkpoint is not ready.";
        }

        private string PersonalOxygenMaskCheckpointBlockText(Vector2Int checkpoint)
        {
            if (!HasAdjacentOxygenMaskDock(checkpoint))
            {
                return "Personal need blocked: Oxygen Mask Checkpoint needs an adjacent repaired Oxygen Mask Dock.";
            }

            if (AvailableOxygenMaskCount() <= 0)
            {
                return "Personal need blocked: all Oxygen Masks are in use.";
            }

            if (!HasChargedOxygenMask())
            {
                return "Personal need blocked: Oxygen Mask Checkpoint needs charged mask oxygen.";
            }

            return "Personal need blocked: Oxygen Mask Checkpoint is not ready.";
        }

        private string PersonalLeadSuitCheckpointBlockText(Vector2Int checkpoint)
        {
            if (!HasAdjacentLeadSuitLocker(checkpoint))
            {
                return "Personal need blocked: Lead Suit Checkpoint needs an adjacent repaired Lead Suit Locker.";
            }

            if (AvailableLeadSuitCount() <= 0)
            {
                return "Personal need blocked: all Lead Suits are in use.";
            }

            return "Personal need blocked: Lead Suit Checkpoint is not ready.";
        }

        private string PersonalDoorPathBlockText(Worker worker, Job job, List<Vector2Int> path)
        {
            if (worker == null || path == null)
            {
                return string.Empty;
            }

            Vector2Int previous = worker.Cell;
            foreach (Vector2Int step in path)
            {
                Vector2Int door = DoorPathBlockCell(previous, step);
                if (door.x >= 0)
                {
                    if (!IsDoorOpenForPathing(door))
                    {
                        return PersonalDoorClosedBlockText(door);
                    }

                    if (!CanPassDoorAccess(previous, step, worker, job))
                    {
                        return PersonalDoorAccessBlockText(door);
                    }
                }

                previous = step;
            }

            return string.Empty;
        }

        private string PersonalDoorClosedBlockText(Vector2Int door)
        {
            if (!IsInside(door.x, door.y))
            {
                return string.Empty;
            }

            if (cells[door.x, door.y] == CellKind.ManualAirlock)
            {
                return "Personal need blocked: Manual Airlock is closed.";
            }

            if (cells[door.x, door.y] == CellKind.MechanizedAirlock)
            {
                return "Personal need blocked: Mechanized Airlock is closed by automation or damage.";
            }

            if (cells[door.x, door.y] == CellKind.BunkerDoor)
            {
                return "Personal need blocked: Bunker Door is closed.";
            }

            return string.Empty;
        }

        private string PersonalDoorAccessBlockText(Vector2Int door)
        {
            DoorAccessMode mode = DoorAccessModeAt(door.x, door.y);
            if (mode == DoorAccessMode.Locked)
            {
                return "Personal need blocked: door access is locked for duplicants.";
            }

            if (mode == DoorAccessMode.Emergency)
            {
                return "Personal need blocked: door access only allows emergency errands.";
            }

            return "Personal need blocked: door access only allows " + DoorAccessModeName(mode) + ".";
        }

        private bool TryGetPersonalNeedRouteBlockText(Worker worker, JobType jobType, out string text)
        {
            text = string.Empty;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            foreach (Job testJob in BuildPersonalNeedRouteProbeJobs(worker, jobType))
            {
                if (TryFindSafePathToJob(worker, testJob, out _))
                {
                    return false;
                }

                if (TryGetPersonalNeedJobRouteBlockText(worker, testJob, out text))
                {
                    return true;
                }
            }

            return false;
        }

        private bool TryGetPersonalNeedJobRouteBlockText(Worker worker, Job job, out string text)
        {
            text = string.Empty;
            if (worker == null || job == null)
            {
                return false;
            }

            if (TryFindPathToJobIgnoringProtectionCheckpoints(worker.Cell, job, out List<Vector2Int> protectionPath))
            {
                text = PersonalProtectionCheckpointBlockText(worker, protectionPath);
                if (!string.IsNullOrEmpty(text))
                {
                    return true;
                }
            }

            if (TryFindPathToJobIgnoringDoorRestrictions(worker.Cell, job, out List<Vector2Int> doorPath))
            {
                text = PersonalDoorPathBlockText(worker, job, doorPath);
                if (!string.IsNullOrEmpty(text))
                {
                    return true;
                }
            }

            if (!IsSafetyCriticalJob(job.Type) && TryFindPathToJob(worker.Cell, worker, job, out _))
            {
                text = "Personal need blocked: route or work cell is unsafe. Build protective gear or make the area safe.";
                return true;
            }

            return false;
        }

        private string RouteBlockTextWithPrefix(string routeBlockText, string prefix)
        {
            const string personalPrefix = "Personal need blocked: ";
            if (string.IsNullOrEmpty(routeBlockText) || !routeBlockText.StartsWith(personalPrefix))
            {
                return routeBlockText;
            }

            return prefix + routeBlockText.Substring(personalPrefix.Length);
        }

        private string AssignedStationRouteBlockText(Worker worker, Job job, string prefix, string fallback)
        {
            if (worker == null || worker.Health <= 0f || job == null)
            {
                return fallback;
            }

            if (TryFindSafePathToJob(worker, job, out _))
            {
                return string.Empty;
            }

            return TryGetPersonalNeedJobRouteBlockText(worker, job, out string routeBlockText)
                ? RouteBlockTextWithPrefix(routeBlockText, prefix)
                : fallback;
        }

        private string ReachableWorkerRouteBlockText(Vector2Int cell, JobType jobType, Func<Worker, bool> predicate, string prefix, string fallback)
        {
            string firstRouteBlock = string.Empty;
            foreach (Worker worker in workers)
            {
                if (worker == null || worker.Health <= 0f || !predicate(worker))
                {
                    continue;
                }

                Job testJob = PersonalNeedRouteProbeJob(worker, jobType, cell);
                if (testJob == null)
                {
                    continue;
                }

                if (TryFindSafePathToJob(worker, testJob, out _))
                {
                    return string.Empty;
                }

                if (string.IsNullOrEmpty(firstRouteBlock) &&
                    TryGetPersonalNeedJobRouteBlockText(worker, testJob, out string routeBlockText))
                {
                    firstRouteBlock = RouteBlockTextWithPrefix(routeBlockText, prefix);
                }
            }

            return string.IsNullOrEmpty(firstRouteBlock) ? fallback : firstRouteBlock;
        }

        private List<Job> BuildPersonalNeedRouteProbeJobs(Worker worker, JobType jobType)
        {
            List<Job> probes = new List<Job>();
            if (worker == null)
            {
                return probes;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    Job probe = PersonalNeedRouteProbeJob(worker, jobType, cell);
                    if (probe != null)
                    {
                        probes.Add(probe);
                    }
                }
            }

            if (jobType == JobType.Sleep)
            {
                AddFloorSleepRouteProbeJobs(worker, probes);
            }

            return probes;
        }

        private Job PersonalNeedRouteProbeJob(Worker worker, JobType jobType, Vector2Int cell)
        {
            switch (jobType)
            {
                case JobType.UseToilet:
                    if (!IsToiletCell(cell) || !CanUseToiletAt(cell) || IsToiletReserved(cell))
                    {
                        return null;
                    }

                    return new Job(JobType.UseToilet, cell, ToiletWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.Shower:
                    if (cells[cell.x, cell.y] != CellKind.Shower ||
                        !CanUseEquipment(cell) ||
                        IsShowerReserved(cell) ||
                        CleanWaterAvailableForMachine(cell) < ShowerWaterUse)
                    {
                        return null;
                    }

                    return new Job(JobType.Shower, cell, ShowerWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.WashHands:
                    if (!IsHandWashStationCell(cell) ||
                        !CanUseHandWashStationAt(cell) ||
                        IsWashBasinReserved(cell) ||
                        HandWashWorkFactor(cell) <= 0.05f)
                    {
                        return null;
                    }

                    return new Job(JobType.WashHands, cell, WashHandsWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.Eat:
                    if (cells[cell.x, cell.y] != CellKind.MessTable ||
                        IsMessTableReserved(cell) ||
                        !CanWorkerUsePersonalStation(cell, worker))
                    {
                        return null;
                    }

                    return new Job(JobType.Eat, cell, EatWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.Relax:
                    if (!CanUseRelaxationStationAt(cell) || IsRelaxationStationReserved(cell))
                    {
                        return null;
                    }

                    return new Job(JobType.Relax, cell, RelaxWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.ScrubSkill:
                    if (!CanUseSkillScrubberAt(cell) || IsSkillScrubberReserved(cell))
                    {
                        return null;
                    }

                    return new Job(JobType.ScrubSkill, cell, SkillScrubberWorkRequired)
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.Sleep:
                    if (!CanUseBedAt(cell) ||
                        IsBedReserved(cell) ||
                        !CanWorkerUsePersonalStation(cell, worker))
                    {
                        return null;
                    }

                    return new Job(JobType.Sleep, cell, SleepWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.Treat:
                    if (cells[cell.x, cell.y] != CellKind.MedicalCot ||
                        !CanUseEquipment(cell) ||
                        !CanWorkerUsePersonalStation(cell, worker) ||
                        IsMedicalCotReserved(cell, worker))
                    {
                        return null;
                    }

                    return new Job(JobType.Treat, cell, TreatmentWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };
                case JobType.MedicalRest:
                    if (cells[cell.x, cell.y] != CellKind.MedicalCot ||
                        !CanUseEquipment(cell) ||
                        !CanWorkerUsePersonalStation(cell, worker) ||
                        IsMedicalCotReserved(cell, worker))
                    {
                        return null;
                    }

                    return new Job(JobType.MedicalRest, cell, MedicalRestWorkRequired)
                    {
                        TargetWorkerName = worker.Name
                    };
                default:
                    return null;
            }
        }

        private void AddFloorSleepRouteProbeJobs(Worker worker, List<Job> probes)
        {
            for (int distance = 0; distance <= 8; distance++)
            {
                for (int dy = -distance; dy <= distance; dy++)
                {
                    int dxLimit = distance - Mathf.Abs(dy);
                    for (int dx = -dxLimit; dx <= dxLimit; dx++)
                    {
                        if (Mathf.Abs(dx) + Mathf.Abs(dy) != distance)
                        {
                            continue;
                        }

                        Vector2Int candidate = worker.Cell + new Vector2Int(dx, dy);
                        Worker occupant = WorkerAt(candidate);
                        if (!IsFloorSleepCell(candidate) ||
                            IsFloorSleepCellReserved(candidate) ||
                            (occupant != null && occupant != worker))
                        {
                            continue;
                        }

                        probes.Add(new Job(JobType.Sleep, candidate, SleepWorkRequired(worker) * FloorSleepWorkRequiredMultiplier)
                        {
                            AutoGenerated = true,
                            TargetWorkerName = worker.Name
                        });
                    }
                }
            }
        }

        private bool NeedsToilet(Worker worker)
        {
            return worker != null && worker.Health > 0f && worker.Bladder >= 68f;
        }

        private string WorkerToiletBlockedText(Worker worker)
        {
            if (!NeedsToilet(worker))
            {
                return string.Empty;
            }

            int outhouses = CountCells(CellKind.Outhouse);
            int lavatories = CountCells(CellKind.Lavatory);
            if (outhouses + lavatories == 0)
            {
                return "Personal need blocked: build an Outhouse or Lavatory.";
            }

            if (HasToiletJobFor(worker.Name))
            {
                return string.Empty;
            }

            if (!AnyUsableToilet())
            {
                if (AnyLavatoryNeedsCleanWater())
                {
                    return "Personal need blocked: Lavatory needs clean water.";
                }

                return "Personal need blocked: toilet needs repair or is submerged.";
            }

            if (!AnyOpenUsableToilet())
            {
                return "Personal need blocked: all toilets are reserved.";
            }

            if (!TryFindReachableToilet(worker, out _))
            {
                if (TryGetPersonalNeedRouteBlockText(worker, JobType.UseToilet, out string toiletRouteBlockText))
                {
                    return toiletRouteBlockText;
                }

                return "Personal need blocked: no safe route to a toilet.";
            }

            return string.Empty;
        }

        private bool AnyUsableToilet()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseToiletAt(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private int CountUsableToilets()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseToiletAt(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool AnyOpenUsableToilet()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int toiletCell = new Vector2Int(x, y);
                    if (CanUseToiletAt(toiletCell) && !IsToiletReserved(toiletCell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyLavatoryNeedsCleanWater()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.Lavatory &&
                        CanUseEquipment(cell) &&
                        CleanWaterAvailableForMachine(cell) < LavatoryWaterUse)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool TryFindReachableToilet(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int toiletCell = new Vector2Int(x, y);
                    if (!IsToiletCell(toiletCell) ||
                        !CanUseToiletAt(toiletCell) ||
                        IsToiletReserved(toiletCell))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.UseToilet, toiletCell, ToiletWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool NeedsHandWash(Worker worker)
        {
            return NeedsHandWashDemand(worker) &&
                AnyUsableHandWashStation();
        }

        private bool NeedsHandWashDemand(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                (worker.GermExposure >= 8f || worker.GermyHandsSeconds >= 4f);
        }

        private bool AnyUsableHandWashStation()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseHandWashStationAt(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private int CountUsableHandWashStations()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseHandWashStationAt(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountUsableHandSanitizers()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.HandSanitizer && CanUseHandWashStationAt(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool NeedsShower(Worker worker)
        {
            return NeedsShowerDemand(worker) &&
                AnyUsableWaterFixture(CellKind.Shower, ShowerWaterUse);
        }

        private bool NeedsShowerDemand(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                worker.StressBreakSeconds <= 0f &&
                (worker.GermExposure >= 32f || worker.Sickness >= 18f || worker.Stress >= 52f);
        }

        private bool AnyUsableWaterFixture(CellKind kind, float requiredCleanWater)
        {
            return CountUsableWaterFixtures(kind, requiredCleanWater) > 0;
        }

        private int CountUsableWaterFixtures(CellKind kind, float requiredCleanWater)
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == kind &&
                        CanUseEquipment(cell) &&
                        CleanWaterAvailableForMachine(cell) >= requiredCleanWater)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountUsableHygieneFixtures()
        {
            return CountUsableHandWashStations() + CountUsableWaterFixtures(CellKind.Shower, ShowerWaterUse);
        }

        private string WorkerHygieneBlockedText(Worker worker)
        {
            if (NeedsShowerDemand(worker))
            {
                if (CountCells(CellKind.Shower) == 0)
                {
                    return "Personal need blocked: build a Shower.";
                }

                if (!AnyUsableWaterFixture(CellKind.Shower, ShowerWaterUse))
                {
                    return AnyShowerNeedsCleanWater()
                        ? "Personal need blocked: Shower needs clean water."
                        : "Personal need blocked: hygiene fixture needs repair or is submerged.";
                }

                if (!TryFindReachableShower(worker, out _))
                {
                    if (TryGetPersonalNeedRouteBlockText(worker, JobType.Shower, out string showerRouteBlockText))
                    {
                        return showerRouteBlockText;
                    }

                    return "Personal need blocked: no safe route to a Shower.";
                }
            }

            if (NeedsHandWashDemand(worker))
            {
                int washBasins = CountCells(CellKind.WashBasin);
                int handSanitizers = CountCells(CellKind.HandSanitizer);
                if (washBasins + handSanitizers == 0)
                {
                    return "Personal need blocked: build a Wash Basin or Hand Sanitizer.";
                }

                if (!AnyUsableHandWashStation())
                {
                    if (washBasins > 0 && AnyWashBasinNeedsCleanWater())
                    {
                        return "Personal need blocked: Wash Basin needs clean water.";
                    }

                    if (handSanitizers > 0 && bleachStone < HandSanitizerBleachStoneUse)
                    {
                        return "Personal need blocked: Hand Sanitizer needs bleach stone.";
                    }

                    return "Personal need blocked: hygiene fixture needs repair or is submerged.";
                }

                if (!TryFindReachableHandWashStation(worker, out _))
                {
                    if (TryGetPersonalNeedRouteBlockText(worker, JobType.WashHands, out string hygieneRouteBlockText))
                    {
                        return hygieneRouteBlockText;
                    }

                    return "Personal need blocked: no safe route to a hygiene fixture.";
                }
            }

            return string.Empty;
        }

        private bool TryFindReachableShower(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int showerCell = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.Shower ||
                        !CanUseEquipment(showerCell) ||
                        IsShowerReserved(showerCell) ||
                        CleanWaterAvailableForMachine(showerCell) < ShowerWaterUse)
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Shower, showerCell, ShowerWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool TryFindReachableHandWashStation(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int basinCell = new Vector2Int(x, y);
                    if (!IsHandWashStationCell(basinCell) ||
                        !CanUseHandWashStationAt(basinCell) ||
                        IsWashBasinReserved(basinCell) ||
                        HandWashWorkFactor(basinCell) <= 0.05f)
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.WashHands, basinCell, WashHandsWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool AnyShowerNeedsCleanWater()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.Shower &&
                        CanUseEquipment(cell) &&
                        CleanWaterAvailableForMachine(cell) < ShowerWaterUse)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyWashBasinNeedsCleanWater()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.WashBasin &&
                        CanUseEquipment(cell) &&
                        CleanWaterAvailableForMachine(cell) <= 0.05f)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool CanWorkerEatStoredFood(Worker worker)
        {
            if (worker == null || worker.Health <= 0f || food < 700f)
            {
                return false;
            }

            if (EffectiveFoodPolicyMode(worker) == FoodPolicyMode.All || !IsStoredFoodUnsafe())
            {
                return true;
            }

            return IsFoodPolicyEmergencyMeal(worker);
        }

        private FoodPolicyMode EffectiveFoodPolicyMode(Worker worker)
        {
            if (worker == null || worker.FoodPolicyOverride == WorkerFoodPolicyMode.Colony)
            {
                return foodPolicyMode;
            }

            return worker.FoodPolicyOverride == WorkerFoodPolicyMode.All ? FoodPolicyMode.All : FoodPolicyMode.Safe;
        }

        private string WorkerFoodPolicyLabel(WorkerFoodPolicyMode mode)
        {
            switch (mode)
            {
                case WorkerFoodPolicyMode.Safe:
                    return "SAFE";
                case WorkerFoodPolicyMode.All:
                    return "ALL";
                default:
                    return "COLONY";
            }
        }

        private string WorkerFoodPolicyShortLabel(WorkerFoodPolicyMode mode)
        {
            switch (mode)
            {
                case WorkerFoodPolicyMode.Safe:
                    return "SAFE";
                case WorkerFoodPolicyMode.All:
                    return "ALL";
                default:
                    return "COL";
            }
        }

        private string WorkerFoodPolicyPlanLabel(Worker worker)
        {
            if (worker == null)
            {
                return "COLONY";
            }

            if (worker.FoodPolicyOverride == WorkerFoodPolicyMode.Colony)
            {
                return "COLONY (" + (foodPolicyMode == FoodPolicyMode.Safe ? "SAFE" : "ALL") + ")";
            }

            return WorkerFoodPolicyLabel(worker.FoodPolicyOverride);
        }

        private bool IsStoredFoodUnsafe()
        {
            return food >= 700f &&
                (foodFreshness < StaleFoodFreshnessThreshold || foodGerms >= FoodGermExposureThreshold);
        }

        private bool IsFoodPolicyEmergencyMeal(Worker worker)
        {
            return worker != null && worker.Calories <= FoodPolicyEmergencyCalories;
        }

        private bool IsFoodPolicyBlockingHungryWorker(Worker worker)
        {
            return worker != null &&
                worker.Health > 0f &&
                EffectiveFoodPolicyMode(worker) == FoodPolicyMode.Safe &&
                IsStoredFoodUnsafe() &&
                !IsFoodPolicyEmergencyMeal(worker) &&
                (worker.Calories < 1100f || (IsMealTime(worker) && worker.Calories < ScheduledMealCalorieThreshold));
        }

        private int CountFoodPolicyBlockedHungryWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (IsFoodPolicyBlockingHungryWorker(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private string FoodPolicyStoredFoodStateText()
        {
            if (food < 700f)
            {
                return "no full meal";
            }

            if (!IsStoredFoodUnsafe())
            {
                return "stored food allowed";
            }

            return foodPolicyMode == FoodPolicyMode.Safe
                ? "unsafe food blocked except critical starvation"
                : "unsafe food allowed";
        }

        private bool NeedsFood(Worker worker)
        {
            return NeedsFoodDemand(worker) &&
                CanWorkerEatStoredFood(worker);
        }

        private bool NeedsFoodDemand(Worker worker)
        {
            if ((redAlertActive || HasOpenYellowAlertJobFor(worker, false)) && worker != null && worker.Calories >= 850f)
            {
                return false;
            }

            return worker != null &&
                worker.Health > 0f &&
                (worker.Calories < 1100f || (IsMealTime(worker) && worker.Calories < ScheduledMealCalorieThreshold));
        }

        private string WorkerFoodBlockedText(Worker worker)
        {
            if (!NeedsFoodDemand(worker))
            {
                return string.Empty;
            }

            if (HasEatJobFor(worker.Name))
            {
                return string.Empty;
            }

            if (food < 700f)
            {
                return "Personal need blocked: no full stored meal.";
            }

            if (IsFoodPolicyBlockingHungryWorker(worker))
            {
                return "Personal need blocked: Food SAFE policy is holding unsafe stored food.";
            }

            if (!CanWorkerEatStoredFood(worker))
            {
                return "Personal need blocked: stored food is unavailable.";
            }

            if (!TryFindReachableMealPlace(worker, out _))
            {
                if (IsFloorEatCell(worker.Cell) && !IsPersonalRecoveryCellOpen(worker.Cell, worker))
                {
                    return "Personal need blocked: safe floor eat spot is occupied or reserved.";
                }

                if (TryGetPersonalNeedRouteBlockText(worker, JobType.Eat, out string mealRouteBlockText))
                {
                    return mealRouteBlockText;
                }

                return "Personal need blocked: no safe place to eat.";
            }

            return string.Empty;
        }

        private bool TryFindReachableMealPlace(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f || !CanWorkerEatStoredFood(worker))
            {
                return false;
            }

            if (IsFloorEatCell(worker.Cell) && IsPersonalRecoveryCellOpen(worker.Cell, worker))
            {
                bestDistance = 0;
                return true;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int tableCell = new Vector2Int(x, y);
                    if (cells[x, y] != CellKind.MessTable ||
                        IsMessTableReserved(tableCell) ||
                        !CanWorkerUsePersonalStation(tableCell, worker))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Eat, tableCell, EatWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool NeedsRelaxation(Worker worker)
        {
            if ((redAlertActive || HasOpenYellowAlertJobFor(worker, false)) && worker != null && worker.Stress < 82f)
            {
                return false;
            }

            return worker != null &&
                worker.Health > 0f &&
                worker.StressBreakSeconds <= 0f &&
                (worker.Stress >= 62f || (IsDowntime(worker) && worker.Stress >= ScheduledDowntimeStressThreshold && CountUsableRelaxationStations() > 0));
        }

        private string WorkerRelaxationBlockedText(Worker worker)
        {
            if (!NeedsRelaxation(worker))
            {
                return string.Empty;
            }

            if (HasRelaxJobFor(worker.Name) || (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.Relax))
            {
                return string.Empty;
            }

            if (TryFindReachableRelaxationPlace(worker, out _))
            {
                return string.Empty;
            }

            if (CountRelaxationStations() == 0 && !IsTakeBreakCell(worker.Cell))
            {
                return "Personal need blocked: build recreation or reach a safe break spot.";
            }

            if (!AnyUsableRelaxationStation() && !IsTakeBreakCell(worker.Cell))
            {
                if (AnyWaterCoolerNeedsCleanWater())
                {
                    return "Personal need blocked: Water Cooler needs clean water.";
                }

                if (AnyArcadeCabinetNeedsPlastic())
                {
                    return "Personal need blocked: Arcade Cabinet needs plastic parts.";
                }

                if (AnyArcadeCabinetNeedsPower())
                {
                    return "Personal need blocked: Arcade Cabinet needs power.";
                }

                return "Personal need blocked: recreation fixture needs repair or is submerged.";
            }

            if (!AnyOpenUsableRelaxationStation() && !IsTakeBreakCell(worker.Cell))
            {
                return "Personal need blocked: all recreation fixtures are reserved.";
            }

            if (IsTakeBreakCell(worker.Cell) && !IsPersonalRecoveryCellOpen(worker.Cell, worker))
            {
                return "Personal need blocked: safe break spot is occupied or reserved.";
            }

            if (TryGetPersonalNeedRouteBlockText(worker, JobType.Relax, out string relaxationRouteBlockText))
            {
                return relaxationRouteBlockText;
            }

            return "Personal need blocked: no safe place to take a break.";
        }

        private bool TryFindReachableRelaxationPlace(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            if (IsTakeBreakCell(worker.Cell) && IsPersonalRecoveryCellOpen(worker.Cell, worker))
            {
                bestDistance = 0;
                return true;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int stationCell = new Vector2Int(x, y);
                    if (!CanUseRelaxationStationAt(stationCell) || IsRelaxationStationReserved(stationCell))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.Relax, stationCell, RelaxWorkRequired(worker))
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool AnyUsableRelaxationStation()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseRelaxationStationAt(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyOpenUsableRelaxationStation()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int stationCell = new Vector2Int(x, y);
                    if (CanUseRelaxationStationAt(stationCell) && !IsRelaxationStationReserved(stationCell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyWaterCoolerNeedsCleanWater()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.WaterCooler &&
                        CanUseEquipment(cell) &&
                        CleanWaterAvailableForMachine(cell) < WaterCoolerWaterUse)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyArcadeCabinetNeedsPlastic()
        {
            if (plastic >= ArcadeCabinetPlasticUse)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.ArcadeCabinet &&
                        CanUseEquipment(cell) &&
                        HasWireAccess(cell) &&
                        HasPoweredCircuit(cell) &&
                        MachineAutomationAllows(cell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyArcadeCabinetNeedsPower()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.ArcadeCabinet &&
                        CanUseEquipment(cell) &&
                        plastic >= ArcadeCabinetPlasticUse &&
                        (!HasWireAccess(cell) || !HasPoweredCircuit(cell) || !MachineAutomationAllows(cell)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool NeedsSkillScrub(Worker worker)
        {
            return NeedsSkillScrubDemand(worker) && techPowerRegulation;
        }

        private bool NeedsSkillScrubDemand(Worker worker)
        {
            if (worker == null ||
                worker.Health <= 0f ||
                worker.StressBreakSeconds > 0f ||
                WorkerSkillLevel(worker) <= 1)
            {
                return false;
            }

            float deficit = WorkerMoraleDeficit(worker);
            int level = WorkerSkillLevel(worker);
            return (level >= 4 && deficit >= 0.65f && worker.Stress >= 34f) ||
                (level >= 3 && deficit >= 1.20f && worker.Stress >= 45f) ||
                (deficit >= 1.75f && worker.Stress >= 58f);
        }

        private string WorkerSkillScrubBlockedText(Worker worker)
        {
            if (!NeedsSkillScrubDemand(worker))
            {
                return string.Empty;
            }

            if (HasSkillScrubJobFor(worker.Name) || (worker.AssignedJob != null && worker.AssignedJob.Type == JobType.ScrubSkill))
            {
                return string.Empty;
            }

            if (!techPowerRegulation)
            {
                return "Personal need blocked: research Power Regulation for Skill Scrubber.";
            }

            if (TryFindReachableSkillScrubber(worker, out _))
            {
                return string.Empty;
            }

            if (CountCells(CellKind.SkillScrubber) == 0)
            {
                return "Personal need blocked: build a Skill Scrubber.";
            }

            if (!AnyUsableSkillScrubber())
            {
                if (AnySkillScrubberNeedsPower())
                {
                    return "Personal need blocked: Skill Scrubber needs power.";
                }

                return "Personal need blocked: Skill Scrubber needs repair or is submerged.";
            }

            if (!AnyOpenUsableSkillScrubber())
            {
                return "Personal need blocked: all Skill Scrubbers are reserved.";
            }

            if (TryGetPersonalNeedRouteBlockText(worker, JobType.ScrubSkill, out string skillScrubRouteBlockText))
            {
                return skillScrubRouteBlockText;
            }

            return "Personal need blocked: no safe route to a Skill Scrubber.";
        }

        private bool TryFindReachableSkillScrubber(Worker worker, out int bestDistance)
        {
            bestDistance = int.MaxValue;
            if (worker == null || worker.Health <= 0f)
            {
                return false;
            }

            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int stationCell = new Vector2Int(x, y);
                    if (!CanUseSkillScrubberAt(stationCell) || IsSkillScrubberReserved(stationCell))
                    {
                        continue;
                    }

                    Job testJob = new Job(JobType.ScrubSkill, stationCell, SkillScrubberWorkRequired)
                    {
                        TargetWorkerName = worker.Name
                    };

                    if (TryFindSafePathToJob(worker, testJob, out List<Vector2Int> path) && path.Count < bestDistance)
                    {
                        bestDistance = path.Count;
                    }
                }
            }

            return bestDistance < int.MaxValue;
        }

        private bool AnyUsableSkillScrubber()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanUseSkillScrubberAt(new Vector2Int(x, y)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyOpenUsableSkillScrubber()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int stationCell = new Vector2Int(x, y);
                    if (CanUseSkillScrubberAt(stationCell) && !IsSkillScrubberReserved(stationCell))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnySkillScrubberNeedsPower()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.SkillScrubber &&
                        CanUseEquipment(cell) &&
                        (!HasWireAccess(cell) || !HasPoweredCircuit(cell) || !MachineAutomationAllows(cell)))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool CanUseSkillScrubberAt(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.SkillScrubber &&
                CanPoweredMachineRun(cell);
        }

        private bool IsSkillScrubberReserved(Vector2Int cell)
        {
            foreach (Job job in jobs)
            {
                if (job.Cell == cell && job.Type == JobType.ScrubSkill)
                {
                    return true;
                }
            }

            return false;
        }

        private float TreatmentWorkRequired(Worker worker)
        {
            float severity = Mathf.Max(
                Mathf.Clamp01(worker.Sickness / 100f),
                Mathf.Clamp01((100f - worker.Health) / 100f));
            return Mathf.Lerp(3.5f, 8f, severity);
        }

        private float RescueWorkRequired(Worker worker)
        {
            float urgency = Mathf.Clamp01((worker == null ? 0f : worker.IncapacitatedSeconds) / 45f);
            return Mathf.Lerp(2.6f, 4.8f, urgency);
        }

        private int RescuePriority(Worker worker)
        {
            return worker != null && worker.IncapacitatedSeconds > 30f ? 10 : 9;
        }

        private int TreatmentPriority(Worker worker)
        {
            if (worker.Health <= 45f || worker.Sickness >= 70f)
            {
                return 10;
            }

            if (worker.Health <= 62f || worker.Sickness >= 50f || worker.GermExposure >= 85f)
            {
                return 9;
            }

            return 7;
        }

        private int MedicalRestPriority(Worker worker)
        {
            if (worker == null)
            {
                return 8;
            }

            if (worker.Disease != WorkerDisease.None || worker.Health <= 72f || worker.Sickness >= 35f || worker.GermExposure >= 70f)
            {
                return 9;
            }

            return 8;
        }

        private int CatchBreathPriority(Worker worker)
        {
            if (worker == null)
            {
                return 8;
            }

            if (worker.Breath <= 12f)
            {
                return 10;
            }

            if (worker.Breath <= 28f)
            {
                return 9;
            }

            return 8;
        }

        private int SeekSafetyPriority(Worker worker)
        {
            if (worker == null)
            {
                return 8;
            }

            float exposure = Mathf.Max(worker.HeatExposure, worker.ChillExposure);
            float danger = EnvironmentalDangerScore(worker.Cell);
            if (worker.Health <= 45f || exposure >= ThermalInjuryExposureThreshold || danger >= 0.82f)
            {
                return 10;
            }

            if (exposure >= SafetyExposureThreshold || danger >= 0.55f)
            {
                return 9;
            }

            return 8;
        }

        private float ToiletWorkRequired(Worker worker)
        {
            return Mathf.Lerp(2.4f, 4.2f, Mathf.Clamp01(worker.Bladder / 100f));
        }

        private int ToiletPriority(Worker worker)
        {
            if (worker.Bladder >= 94f)
            {
                return 10;
            }

            if (worker.Bladder >= 82f)
            {
                return 9;
            }

            return 7;
        }

        private float WashHandsWorkRequired(Worker worker)
        {
            return Mathf.Lerp(1.4f, 3.0f, Mathf.Clamp01((worker == null ? 0f : worker.GermExposure) / 100f));
        }

        private int WashHandsPriority(Worker worker)
        {
            if (worker != null && worker.GermExposure >= 70f)
            {
                return 9;
            }

            if (worker != null && worker.GermExposure >= 35f)
            {
                return 8;
            }

            return 7;
        }

        private float ShowerWorkRequired(Worker worker)
        {
            float severity = Mathf.Max(
                Mathf.Clamp01((worker == null ? 0f : worker.GermExposure) / 100f),
                Mathf.Clamp01((worker == null ? 0f : worker.Stress) / 100f));
            return Mathf.Lerp(3.2f, 6.4f, severity);
        }

        private int ShowerPriority(Worker worker)
        {
            if (worker != null && (worker.GermExposure >= 75f || worker.Sickness >= 40f))
            {
                return 9;
            }

            if (worker != null && worker.Stress >= 78f)
            {
                return 8;
            }

            return 7;
        }

        private float EatWorkRequired(Worker worker)
        {
            return Mathf.Lerp(1.4f, 3.4f, Mathf.Clamp01((1400f - worker.Calories) / 1400f));
        }

        private int EatPriority(Worker worker)
        {
            if (IsMealTime(worker) && worker.Calories < ScheduledMealCalorieThreshold)
            {
                return worker.Calories <= 850f ? 10 : 8;
            }

            if (worker.Calories <= 350f)
            {
                return 10;
            }

            if (worker.Calories <= 850f)
            {
                return 9;
            }

            return 7;
        }

        private float DiningStressRelief(Vector2Int cell)
        {
            float relief = CountCells(CellKind.MessTable) >= workers.Count ? 7f : 4f;
            RoomKind diningRoom = RoomKindAt(cell.x, cell.y);
            if (diningRoom == RoomKind.GreatHall)
            {
                relief += 7f;
            }
            else if (diningRoom == RoomKind.MessHall)
            {
                relief += 4f;
            }

            return relief;
        }

        private float RelaxWorkRequired(Worker worker)
        {
            return Mathf.Lerp(4f, 10f, Mathf.Clamp01(worker.Stress / 100f));
        }

        private int RelaxPriority(Worker worker)
        {
            if (IsDowntime(worker) && worker.Stress >= ScheduledDowntimeStressThreshold)
            {
                return worker.Stress >= 76f ? 9 : 8;
            }

            if (worker.Stress >= 90f)
            {
                return 10;
            }

            if (worker.Stress >= 76f)
            {
                return 9;
            }

            return 7;
        }

        private int SkillScrubPriority(Worker worker)
        {
            if (worker == null)
            {
                return 6;
            }

            if (WorkerMoraleDeficit(worker) >= 1.75f || worker.Stress >= 78f)
            {
                return 8;
            }

            return 6;
        }

        private float SleepWorkRequired(Worker worker)
        {
            return Mathf.Lerp(4f, 12f, Mathf.Clamp01(worker.Fatigue / 100f));
        }

        private int SleepPriority(Worker worker)
        {
            if (worker.Fatigue >= 95f || worker.Stress >= 96f)
            {
                return 10;
            }

            return IsRestTime(worker) ? 9 : 7;
        }

        private int JobPriority(Job job)
        {
            if (job.Priority > 0)
            {
                return job.Priority;
            }

            return DefaultPriority(job.Type);
        }

        private int EffectiveJobPriority(Job job)
        {
            int basePriority = JobPriority(job);
            if (basePriority >= 8)
            {
                return basePriority;
            }

            int maxBoost = job.AutoGenerated ? 1 : 2;
            int boost = Mathf.Clamp(Mathf.FloorToInt(job.AgeSeconds / JobAgingPriorityStepSeconds), 0, maxBoost);
            return Mathf.Min(8, basePriority + boost);
        }

        private int JobAssignmentScore(Worker worker, Job job, int pathLength)
        {
            int score = DispatchJobPriority(job) * 1000;
            if (WorkerRoleMatchesJob(worker, job.Type))
            {
                score += WorkerRoleDispatchBonus;
            }

            if (WorkerInterestMatchesJob(worker, job.Type))
            {
                score += WorkerInterestDispatchBonus;
            }

            score -= Mathf.Max(0, pathLength) * 8;
            score -= Mathf.RoundToInt(job.Progress);
            score += Mathf.Min(220, Mathf.RoundToInt(job.AgeSeconds * 0.8f));
            return score;
        }

        private string JobDispatchCandidateText(Job job)
        {
            if (job == null || job.AssignedWorker != null || !IsJobValid(job))
            {
                return string.Empty;
            }

            JobCategory category = JobCategoryFor(job.Type);
            if (IsJobCategoryDisabled(category))
            {
                return "Dispatch blocked: labor policy disables " + JobCategoryName(category) + " errands.";
            }

            Worker bestIdleWorker = null;
            Worker bestBusyWorker = null;
            int bestIdleScore = int.MinValue;
            int bestBusyScore = int.MinValue;
            int bestIdlePath = 0;
            int bestBusyPath = 0;
            int eligibleWorkers = 0;
            int unsafeReachableWorkers = 0;
            int hygieneBlockedWorkers = 0;

            foreach (Worker worker in workers)
            {
                if (worker == null || worker.Health <= 0f)
                {
                    continue;
                }

                if (!CanWorkerHandleFoodJob(worker, job))
                {
                    hygieneBlockedWorkers++;
                    continue;
                }

                if (!CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                eligibleWorkers++;
                if (TryFindSafePathToJob(worker, job, out List<Vector2Int> path))
                {
                    int score = JobAssignmentScore(worker, job, path.Count);
                    if (worker.AssignedJob == null)
                    {
                        if (bestIdleWorker == null || score > bestIdleScore)
                        {
                            bestIdleWorker = worker;
                            bestIdleScore = score;
                            bestIdlePath = path.Count;
                        }
                    }
                    else if (bestBusyWorker == null || score > bestBusyScore)
                    {
                        bestBusyWorker = worker;
                        bestBusyScore = score;
                        bestBusyPath = path.Count;
                    }
                }
                else if (!IsSafetyCriticalJob(job.Type) && TryFindPathToJob(worker.Cell, worker, job, out _))
                {
                    unsafeReachableWorkers++;
                }
            }

            if (bestIdleWorker != null)
            {
                return JobDispatchCandidateLine("Dispatch candidate: ", bestIdleWorker, job, bestIdlePath, bestIdleScore);
            }

            if (bestBusyWorker != null)
            {
                return JobDispatchCandidateLine("Dispatch waiting: all reachable duplicants are busy. Next best ", bestBusyWorker, job, bestBusyPath, bestBusyScore);
            }

            if (eligibleWorkers == 0 && hygieneBlockedWorkers > 0)
            {
                return "Dispatch blocked: food handling hygiene is reserving cooking for cleaner duplicants.";
            }

            if (eligibleWorkers == 0 && !string.IsNullOrEmpty(job.TargetWorkerName))
            {
                return "Dispatch blocked: target duplicant cannot take this errand.";
            }

            if (unsafeReachableWorkers > 0)
            {
                return "Dispatch blocked: reachable routes are unsafe for available duplicants.";
            }

            return string.Empty;
        }

        private string JobDispatchCandidateLine(string prefix, Worker worker, Job job, int pathLength, int score)
        {
            StringBuilder builder = new StringBuilder();
            builder.Append(prefix);
            builder.Append(worker.Name);
            builder.Append("  ");
            builder.Append(pathLength);
            builder.Append(" steps  score ");
            builder.Append(score);
            builder.Append(".");

            if (WorkerRoleMatchesJob(worker, job.Type))
            {
                builder.Append(" Role match.");
            }

            if (WorkerInterestMatchesJob(worker, job.Type))
            {
                builder.Append(" Interest match.");
            }

            int policyAdjustment = JobCategoryPriorityAdjustment(JobCategoryFor(job.Type));
            if (policyAdjustment != 0)
            {
                builder.Append(" Policy ");
                builder.Append(JobCategoryName(JobCategoryFor(job.Type)));
                builder.Append(" ");
                builder.Append(JobCategoryPriorityLabel(policyAdjustment));
                builder.Append(".");
            }

            return builder.ToString();
        }

        private string WorkerNextErrandText(Worker worker)
        {
            if (worker == null)
            {
                return string.Empty;
            }

            if (worker.Health <= 0f)
            {
                return "Next errand blocked: incapacitated.";
            }

            if (worker.AssignedJob != null)
            {
                return "Current errand: " + JobLabel(worker.AssignedJob) + "  " + JobProgressPercentText(worker.AssignedJob) + ".";
            }

            string personalNeedText = WorkerPersonalNeedErrandText(worker);
            if (!string.IsNullOrEmpty(personalNeedText))
            {
                return personalNeedText;
            }

            Job bestJob = null;
            int bestScore = int.MinValue;
            int bestPath = 0;
            int openJobs = 0;
            int targetableJobs = 0;
            int unsafeReachableJobs = 0;
            int policyBlockedJobs = 0;
            int medicalLeaveBlockedJobs = 0;
            int hygieneBlockedJobs = 0;

            foreach (Job job in jobs)
            {
                if (job.AssignedWorker != null)
                {
                    continue;
                }

                openJobs++;
                if (!IsJobValid(job))
                {
                    continue;
                }

                if (!IsJobAllowedByLaborPolicy(job))
                {
                    policyBlockedJobs++;
                    continue;
                }

                if (NeedsMedicalLeave(worker) && !IsMedicalLeaveAllowedJob(job.Type))
                {
                    medicalLeaveBlockedJobs++;
                    continue;
                }

                if (!CanWorkerHandleFoodJob(worker, job))
                {
                    hygieneBlockedJobs++;
                    continue;
                }

                if (!CanWorkerTakeJob(worker, job))
                {
                    continue;
                }

                targetableJobs++;
                if (TryFindSafePathToJob(worker, job, out List<Vector2Int> path))
                {
                    int score = JobAssignmentScore(worker, job, path.Count);
                    if (bestJob == null || score > bestScore)
                    {
                        bestJob = job;
                        bestScore = score;
                        bestPath = path.Count;
                    }
                }
                else if (!IsSafetyCriticalJob(job.Type) && TryFindPathToJob(worker.Cell, worker, job, out _))
                {
                    unsafeReachableJobs++;
                }
            }

            if (bestJob != null)
            {
                return WorkerNextErrandCandidateLine(worker, bestJob, bestPath, bestScore);
            }

            if (openJobs == 0)
            {
                return "Next errand idle: no open queued errands.";
            }

            if (targetableJobs == 0)
            {
                if (policyBlockedJobs > 0)
                {
                    return "Next errand blocked: labor policy disables available errand categories.";
                }

                if (medicalLeaveBlockedJobs > 0)
                {
                    return "Next errand blocked: medical leave policy is holding routine errands until vitals recover.";
                }

                if (hygieneBlockedJobs > 0)
                {
                    return "Next errand blocked: food handling hygiene is reserving cooking for cleaner duplicants.";
                }

                return "Next errand blocked: open errands are invalid or reserved for another duplicant.";
            }

            if (unsafeReachableJobs > 0)
            {
                return "Next errand blocked: reachable errands need safer routes or protective gear.";
            }

            return "Next errand blocked: no safe reachable queued errands.";
        }

        private string WorkerPersonalNeedErrandText(Worker worker)
        {
            if (NeedsTreatment(worker))
            {
                return "Personal need: treatment takes priority over routine errands.";
            }

            if (NeedsSeekSafety(worker))
            {
                string seekSafetyBlockedText = WorkerSeekSafetyBlockedText(worker);
                if (!string.IsNullOrEmpty(seekSafetyBlockedText))
                {
                    return seekSafetyBlockedText;
                }

                if (HasDepletedBreathingGearInUnsafeArea(worker))
                {
                    return "Personal need: depleted breathing gear oxygen forces a return to safe air.";
                }

                return "Personal need: seeking safety takes priority over routine errands.";
            }

            if (NeedsCatchBreath(worker))
            {
                string catchBreathBlockedText = WorkerCatchBreathBlockedText(worker);
                if (!string.IsNullOrEmpty(catchBreathBlockedText))
                {
                    return catchBreathBlockedText;
                }

                return "Personal need: catching breath takes priority over routine errands.";
            }

            if (NeedsToilet(worker))
            {
                string toiletBlockedText = WorkerToiletBlockedText(worker);
                if (!string.IsNullOrEmpty(toiletBlockedText))
                {
                    return toiletBlockedText;
                }

                return "Personal need: toilet break takes priority over routine errands.";
            }

            if (NeedsShower(worker))
            {
                if (!HasShowerJobFor(worker.Name) && !TryFindReachableShower(worker, out _))
                {
                    if (TryGetPersonalNeedRouteBlockText(worker, JobType.Shower, out string showerRouteBlockText))
                    {
                        return showerRouteBlockText;
                    }

                    return "Personal need blocked: no safe route to a Shower.";
                }

                return "Personal need: shower takes priority over routine errands.";
            }

            if (NeedsHandWash(worker))
            {
                if (!HasWashHandsJobFor(worker.Name) && !TryFindReachableHandWashStation(worker, out _))
                {
                    if (TryGetPersonalNeedRouteBlockText(worker, JobType.WashHands, out string hygieneRouteBlockText))
                    {
                        return hygieneRouteBlockText;
                    }

                    return "Personal need blocked: no safe route to a hygiene fixture.";
                }

                return "Personal need: hand washing takes priority over routine errands.";
            }

            string hygieneBlockedText = WorkerHygieneBlockedText(worker);
            if (!string.IsNullOrEmpty(hygieneBlockedText))
            {
                return hygieneBlockedText;
            }

            string foodBlockedText = WorkerFoodBlockedText(worker);
            if (!string.IsNullOrEmpty(foodBlockedText))
            {
                return foodBlockedText;
            }

            if (NeedsFood(worker))
            {
                return "Personal need: meal takes priority over routine errands.";
            }

            string relaxationBlockedText = WorkerRelaxationBlockedText(worker);
            if (!string.IsNullOrEmpty(relaxationBlockedText))
            {
                return relaxationBlockedText;
            }

            if (NeedsRelaxation(worker))
            {
                return "Personal need: stress relief takes priority over routine errands.";
            }

            string skillScrubBlockedText = WorkerSkillScrubBlockedText(worker);
            if (!string.IsNullOrEmpty(skillScrubBlockedText))
            {
                return skillScrubBlockedText;
            }

            if (NeedsSkillScrub(worker))
            {
                return "Personal need: skill scrub takes priority over routine errands.";
            }

            string sleepBlockedText = WorkerSleepBlockedText(worker);
            if (!string.IsNullOrEmpty(sleepBlockedText))
            {
                return sleepBlockedText;
            }

            if (ShouldSleep(worker))
            {
                return "Personal need: sleep takes priority over routine errands.";
            }

            if (NeedsMedicalRest(worker))
            {
                return "Personal need: medical rest at a Medical Cot takes priority over routine errands.";
            }

            if (NeedsMedicalLeave(worker))
            {
                return "Personal need: medical leave blocks routine errands until vitals recover.";
            }

            return string.Empty;
        }

        private string WorkerNextErrandCandidateLine(Worker worker, Job job, int pathLength, int score)
        {
            StringBuilder builder = new StringBuilder();
            builder.Append("Next errand candidate: ");
            builder.Append(JobLabel(job));
            builder.Append("  ");
            builder.Append(pathLength);
            builder.Append(" steps  score ");
            builder.Append(score);
            builder.Append("  dispatch ");
            builder.Append(DispatchJobPriority(job));
            builder.Append(".");

            if (WorkerRoleMatchesJob(worker, job.Type))
            {
                builder.Append(" Role match.");
            }

            if (WorkerInterestMatchesJob(worker, job.Type))
            {
                builder.Append(" Interest match.");
            }

            return builder.ToString();
        }

        private string JobWaitText(Job job)
        {
            if (job == null)
            {
                return string.Empty;
            }

            int effectivePriority = EffectiveJobPriority(job);
            int basePriority = JobPriority(job);
            string text = "Waiting " + job.AgeSeconds.ToString("0") + "s";
            if (effectivePriority != basePriority)
            {
                text += "  Effective priority " + effectivePriority;
            }

            int dispatchPriority = DispatchJobPriority(job);
            if (dispatchPriority != effectivePriority)
            {
                text += "  Dispatch priority " + dispatchPriority;
            }

            if (job.YellowAlert)
            {
                text += "  Yellow Alert";
            }

            return text;
        }

        private int DispatchJobPriority(Job job)
        {
            if (job == null)
            {
                return 1;
            }

            if (!IsJobAllowedByLaborPolicy(job))
            {
                return 0;
            }

            if (job.YellowAlert)
            {
                return YellowAlertDispatchPriority;
            }

            int priority = EffectiveJobPriority(job) + JobCategoryPriorityAdjustment(JobCategoryFor(job.Type));
            if (job.Type == JobType.Rescue || job.Type == JobType.Treat || job.Type == JobType.CatchBreath || job.Type == JobType.SeekSafety)
            {
                priority = Mathf.Max(priority, 9);
            }
            else if (job.Type == JobType.MedicalRest)
            {
                priority = Mathf.Max(priority, 8);
            }

            return Mathf.Clamp(priority, 1, 10);
        }

        private int JobCategoryPriorityAdjustment(JobCategory category)
        {
            int index = (int)category;
            if (jobCategoryPriorityAdjustments == null || index < 0 || index >= jobCategoryPriorityAdjustments.Length)
            {
                return 0;
            }

            return NormalizeJobCategoryPolicyAdjustment(category, jobCategoryPriorityAdjustments[index]);
        }

        private bool IsJobCategoryDisabled(JobCategory category)
        {
            return JobCategoryPriorityAdjustment(category) == JobCategoryPriorityDisabled;
        }

        private bool IsJobAllowedByLaborPolicy(Job job)
        {
            return job != null && !IsJobCategoryDisabled(JobCategoryFor(job.Type));
        }

        private string JobPolicyText(Job job)
        {
            if (job == null)
            {
                return string.Empty;
            }

            JobCategory category = JobCategoryFor(job.Type);
            int adjustment = JobCategoryPriorityAdjustment(category);
            if (adjustment == JobCategoryPriorityDisabled)
            {
                return "Policy " + JobCategoryName(category) + " OFF: no duplicant will take this errand.";
            }

            if (adjustment == 0)
            {
                return string.Empty;
            }

            return "Policy " + JobCategoryName(category) + " " + JobCategoryPriorityLabel(adjustment) +
                "  Dispatch priority " + DispatchJobPriority(job);
        }

        private string JobCategoryPriorityLabel(int adjustment)
        {
            if (adjustment == JobCategoryPriorityDisabled)
            {
                return "OFF";
            }

            return adjustment >= 0 ? "+" + adjustment : adjustment.ToString();
        }

        private string BuildJobQueueText(int assignedJobs, int openJobs)
        {
            EnsureJobCategoryPolicy();
            int categoryCount = Enum.GetValues(typeof(JobCategory)).Length;
            int[] openByCategory = new int[categoryCount];
            int[] assignedByCategory = new int[categoryCount];
            int[] blockedByCategory = new int[categoryCount];
            int blockedJobs = 0;
            int policyBlockedJobs = 0;
            int invalidJobs = 0;
            int invalidBuildReservationJobs = 0;
            float invalidReservedDirt = 0f;
            float invalidReservedMetal = 0f;
            float invalidReservedAlgae = 0f;
            float invalidReservedRefinedMetal = 0f;
            int activeWorkers = CountActiveWorkers();
            int yellowAlertJobs = 0;
            Job oldestOpenJob = null;
            Job highestPriorityOpenJob = null;
            int highestPriority = int.MinValue;

            foreach (Job job in jobs)
            {
                int categoryIndex = (int)JobCategoryFor(job.Type);
                if (job.AssignedWorker != null)
                {
                    if (job.YellowAlert)
                    {
                        yellowAlertJobs++;
                    }

                    assignedByCategory[categoryIndex]++;
                    continue;
                }

                if (job.YellowAlert)
                {
                    yellowAlertJobs++;
                }

                openByCategory[categoryIndex]++;
                if (!IsJobValid(job))
                {
                    invalidJobs++;
                    blockedJobs++;
                    blockedByCategory[categoryIndex]++;
                    if (IsBuildReservationJob(job))
                    {
                        invalidBuildReservationJobs++;
                        invalidReservedDirt += job.DirtCost;
                        invalidReservedMetal += job.MetalCost;
                        invalidReservedAlgae += job.AlgaeCost;
                        invalidReservedRefinedMetal += job.RefinedMetalCost;
                    }

                    continue;
                }

                if (!IsJobAllowedByLaborPolicy(job))
                {
                    policyBlockedJobs++;
                    blockedJobs++;
                    blockedByCategory[categoryIndex]++;
                    continue;
                }

                if (oldestOpenJob == null || job.AgeSeconds > oldestOpenJob.AgeSeconds)
                {
                    oldestOpenJob = job;
                }

                int effectivePriority = DispatchJobPriority(job);
                if (highestPriorityOpenJob == null ||
                    effectivePriority > highestPriority ||
                    (effectivePriority == highestPriority && job.AgeSeconds > highestPriorityOpenJob.AgeSeconds))
                {
                    highestPriorityOpenJob = job;
                    highestPriority = effectivePriority;
                }
            }

            int routeBlockedJobs = Mathf.Max(0, unreachableJobCount - blockedJobs);
            blockedJobs += routeBlockedJobs;
            int reachableJobs = Mathf.Max(0, openJobs - blockedJobs);
            StringBuilder builder = new StringBuilder();
            builder.Append("Errands ");
            builder.Append(assignedJobs);
            builder.Append("/");
            builder.Append(jobs.Count);
            builder.Append("  Active ");
            builder.Append(activeWorkers);
            builder.AppendLine();
            builder.Append("Open ");
            builder.Append(openJobs);
            builder.Append("  Reachable ");
            builder.Append(reachableJobs);
            builder.Append("  Blocked ");
            builder.Append(blockedJobs);
            if (routeBlockedJobs > 0)
            {
                builder.Append("  Route ");
                builder.Append(routeBlockedJobs);
            }

            if (policyBlockedJobs > 0)
            {
                builder.Append("  PolicyOff ");
                builder.Append(policyBlockedJobs);
            }

            builder.Append("  Assigned ");
            builder.Append(assignedJobs);
            if (invalidJobs > 0)
            {
                builder.Append("  Invalid ");
                builder.Append(invalidJobs);
            }

            if (invalidBuildReservationJobs > 0)
            {
                builder.Append("  Invalid reserved ");
                builder.Append(invalidBuildReservationJobs);
            }

            if (yellowAlertJobs > 0)
            {
                builder.Append("  Yellow ");
                builder.Append(yellowAlertJobs);
            }

            builder.AppendLine();
            builder.Append("Focus: ");
            builder.Append(BuildJobQueueFocusText(
                openJobs,
                assignedJobs,
                blockedJobs,
                policyBlockedJobs,
                invalidJobs,
                invalidBuildReservationJobs,
                invalidReservedDirt,
                invalidReservedMetal,
                invalidReservedAlgae,
                invalidReservedRefinedMetal,
                activeWorkers,
                highestPriorityOpenJob));
            builder.AppendLine();
            builder.Append("Categories (open/assigned/blocked): ");
            builder.Append(TopJobCategorySummary(openByCategory, assignedByCategory, blockedByCategory));

            if (invalidBuildReservationJobs > 0)
            {
                builder.AppendLine();
                builder.Append("Invalid build reservations ");
                builder.Append(invalidBuildReservationJobs);
                builder.Append(": ");
                builder.Append(BuildCostText(invalidReservedDirt, invalidReservedMetal, invalidReservedAlgae, invalidReservedRefinedMetal));
                builder.Append(" refundable.");
            }

            if (oldestOpenJob != null)
            {
                builder.AppendLine();
                builder.Append("Oldest: ");
                builder.Append(JobLabel(oldestOpenJob));
                builder.Append("  ");
                builder.Append(JobWaitText(oldestOpenJob));
            }

            return builder.ToString();
        }

        private string BuildJobQueueFocusText(
            int openJobs,
            int assignedJobs,
            int blockedJobs,
            int policyBlockedJobs,
            int invalidJobs,
            int invalidBuildReservationJobs,
            float invalidReservedDirt,
            float invalidReservedMetal,
            float invalidReservedAlgae,
            float invalidReservedRefinedMetal,
            int activeWorkers,
            Job highestPriorityOpenJob)
        {
            if (activeWorkers == 0)
            {
                return "No active duplicants.";
            }

            if (invalidBuildReservationJobs > 0)
            {
                return "Cancel invalid build reservations to refund " +
                    BuildCostText(invalidReservedDirt, invalidReservedMetal, invalidReservedAlgae, invalidReservedRefinedMetal) +
                    ".";
            }

            if (invalidJobs > 0)
            {
                return "Invalid jobs need cancellation.";
            }

            if (policyBlockedJobs > 0)
            {
                return "Labor policy is blocking " + policyBlockedJobs + " errands.";
            }

            if (blockedJobs > 0)
            {
                return "Build access to blocked work cells.";
            }

            if (openJobs == 0 && assignedJobs == 0)
            {
                return "No queued errands.";
            }

            if (openJobs == 0)
            {
                return "Duplicants are working.";
            }

            if (openJobs > Mathf.Max(1, activeWorkers) * 3)
            {
                return "Reduce backlog with priorities.";
            }

            if (highestPriorityOpenJob != null)
            {
                if (highestPriorityOpenJob.YellowAlert)
                {
                    return "Yellow Alert: " + JobLabel(highestPriorityOpenJob) +
                        " dispatch " +
                        DispatchJobPriority(highestPriorityOpenJob);
                }

                return JobCategoryName(JobCategoryFor(highestPriorityOpenJob.Type)) +
                    " priority " +
                    DispatchJobPriority(highestPriorityOpenJob);
            }

            return "Duplicants are working.";
        }

        private string BuildJobPolicyText()
        {
            EnsureJobCategoryPolicy();
            StringBuilder builder = new StringBuilder();
            int selectedAdjustment = JobCategoryPriorityAdjustment(selectedJobCategory);
            builder.Append("Labor Policy ");
            builder.Append(JobCategoryName(selectedJobCategory));
            builder.Append(" ");
            builder.Append(JobCategoryPriorityLabel(selectedAdjustment));
            builder.AppendLine();
            builder.Append("Active policies: ");
            builder.Append(ActiveJobPolicySummary());
            builder.AppendLine();
            builder.Append("Food Policy ");
            builder.Append(foodPolicyMode == FoodPolicyMode.Safe ? "SAFE" : "ALL");
            builder.Append(": ");
            builder.Append(FoodPolicyStoredFoodStateText());
            int personalFoodPolicies = CountPersonalFoodPolicyOverrides();
            if (personalFoodPolicies > 0)
            {
                builder.Append("  Personal ");
                builder.Append(personalFoodPolicies);
            }

            int blockedHungryWorkers = CountFoodPolicyBlockedHungryWorkers();
            if (blockedHungryWorkers > 0 || unsafeMealsBlockedByPolicy > 0 || emergencyUnsafeMealsEaten > 0)
            {
                builder.Append("  BlockedNow ");
                builder.Append(blockedHungryWorkers);
                builder.Append("  Blocked ");
                builder.Append(unsafeMealsBlockedByPolicy);
                builder.Append("  Emergency ");
                builder.Append(emergencyUnsafeMealsEaten);
            }

            builder.AppendLine();
            builder.Append("Food Handling Hygiene: ");
            builder.Append(IsFoodHandlingEmergency()
                ? "food emergency lets any cook help"
                : "germy cooks wait for cleaner duplicants");
            int hygieneRiskWorkers = CountFoodHandlingHygieneRiskWorkers();
            if (hygieneRiskWorkers > 0)
            {
                builder.Append("  Risk ");
                builder.Append(hygieneRiskWorkers);
            }

            int foodSafeHandsWorkers = CountFoodSafeHandsWorkers();
            if (foodSafeHandsWorkers > 0)
            {
                builder.Append("  Prepared ");
                builder.Append(foodSafeHandsWorkers);
            }

            builder.AppendLine();
            builder.Append("Medical Leave ");
            builder.Append(medicalLeavePolicyActive ? "ON" : "OFF");
            builder.Append(": ");
            builder.Append(medicalLeavePolicyActive ? "sick duplicants avoid routine errands" : "sick duplicants work normally");
            int medicalLeaveWorkers = CountMedicalLeaveWorkers();
            if (medicalLeaveWorkers > 0)
            {
                builder.Append("  Resting ");
                builder.Append(medicalLeaveWorkers);
            }

            return builder.ToString();
        }

        private int CountFoodHandlingHygieneRiskWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (IsFoodHandlingHygieneRisk(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountFoodSafeHandsWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker != null && worker.Health > 0f && worker.FoodSafeHandsSeconds > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountPersonalFoodPolicyOverrides()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker != null && worker.FoodPolicyOverride != WorkerFoodPolicyMode.Colony)
                {
                    count++;
                }
            }

            return count;
        }

        private string ActiveJobPolicySummary()
        {
            EnsureJobCategoryPolicy();
            StringBuilder builder = new StringBuilder();
            int added = 0;
            for (int i = 0; i < jobCategoryPriorityAdjustments.Length; i++)
            {
                int adjustment = JobCategoryPriorityAdjustment((JobCategory)i);
                if (adjustment == 0)
                {
                    continue;
                }

                if (added > 0)
                {
                    builder.Append(" | ");
                }

                builder.Append(JobCategoryName((JobCategory)i));
                builder.Append(" ");
                builder.Append(JobCategoryPriorityLabel(adjustment));
                added++;
            }

            return added == 0 ? "all neutral" : builder.ToString();
        }

        private string TopJobCategorySummary(int[] openByCategory, int[] assignedByCategory, int[] blockedByCategory)
        {
            bool[] used = new bool[openByCategory.Length];
            StringBuilder builder = new StringBuilder();
            int added = 0;

            for (int slot = 0; slot < 4; slot++)
            {
                int bestIndex = -1;
                int bestTotal = 0;
                for (int i = 0; i < openByCategory.Length; i++)
                {
                    int total = openByCategory[i] + assignedByCategory[i] + blockedByCategory[i];
                    if (!used[i] && total > bestTotal)
                    {
                        bestIndex = i;
                        bestTotal = total;
                    }
                }

                if (bestIndex < 0)
                {
                    break;
                }

                if (added > 0)
                {
                    builder.Append(" | ");
                }

                used[bestIndex] = true;
                added++;
                builder.Append(JobCategoryName((JobCategory)bestIndex));
                builder.Append(" ");
                builder.Append(openByCategory[bestIndex]);
                builder.Append("/");
                builder.Append(assignedByCategory[bestIndex]);
                builder.Append("/");
                builder.Append(blockedByCategory[bestIndex]);
                int adjustment = JobCategoryPriorityAdjustment((JobCategory)bestIndex);
                if (adjustment != 0)
                {
                    builder.Append("(");
                    builder.Append(JobCategoryPriorityLabel(adjustment));
                    builder.Append(")");
                }
            }

            return added == 0 ? "none" : builder.ToString();
        }

        private JobCategory JobCategoryFor(JobType type)
        {
            switch (type)
            {
                case JobType.Sleep:
                case JobType.UseToilet:
                case JobType.WashHands:
                case JobType.Shower:
                case JobType.Eat:
                case JobType.Treat:
                case JobType.MedicalRest:
                case JobType.CatchBreath:
                case JobType.SeekSafety:
                case JobType.ProduceMedicine:
                case JobType.Rescue:
                case JobType.MoveTo:
                    return JobCategory.Survival;
                case JobType.Build:
                case JobType.BuildWire:
                case JobType.BuildAutomationWire:
                case JobType.BuildPipe:
                case JobType.BuildGasPipe:
                case JobType.BuildShippingRail:
                case JobType.Deconstruct:
                    return JobCategory.Construction;
                case JobType.PumpWater:
                case JobType.EmptyBottle:
                    return JobCategory.LifeSupport;
                case JobType.Harvest:
                case JobType.Cook:
                case JobType.TendCrop:
                    return JobCategory.FoodOps;
                case JobType.OperateGenerator:
                case JobType.TuneGenerator:
                    return JobCategory.PowerOps;
                case JobType.Research:
                    return JobCategory.ResearchOps;
                case JobType.Sweep:
                    return JobCategory.Logistics;
                case JobType.Mop:
                case JobType.Disinfect:
                case JobType.Repair:
                case JobType.Compost:
                    return JobCategory.Maintenance;
                case JobType.RefineMetal:
                    return JobCategory.Industry;
                case JobType.GroomHatch:
                case JobType.WrangleCritter:
                case JobType.ButcherCritter:
                    return JobCategory.Ranching;
                case JobType.Sculpt:
                case JobType.Relax:
                    return JobCategory.MoraleCare;
                case JobType.ScrubSkill:
                    return JobCategory.MoraleCare;
                default:
                    return JobCategory.Logistics;
            }
        }

