                    return 9;
                case JobType.Treat:
                case JobType.CatchBreath:
                case JobType.SeekSafety:
                case JobType.MoveTo:
                    return 9;
                case JobType.Sleep:
                case JobType.MedicalRest:
                case JobType.UseToilet:
                case JobType.WashHands:
                case JobType.Shower:
                case JobType.Eat:
                case JobType.Relax:
                case JobType.ScrubSkill:
                    return 8;
                case JobType.OperateGenerator:
                    return 6;
                case JobType.ProduceMedicine:
                    return 6;
                case JobType.Cook:
                    return 6;
                case JobType.Mop:
                case JobType.Disinfect:
                    return 6;
                case JobType.Repair:
                    return 6;
                case JobType.EmptyBottle:
                    return 6;
                case JobType.RefineMetal:
                    return 5;
                case JobType.PumpWater:
                    return 5;
                case JobType.TendCrop:
                    return 5;
                case JobType.Compost:
                case JobType.GroomHatch:
                case JobType.WrangleCritter:
                case JobType.ButcherCritter:
                case JobType.Sculpt:
                    return 5;
                case JobType.Sweep:
                    return 4;
                case JobType.Build:
                case JobType.BuildWire:
                case JobType.BuildAutomationWire:
                case JobType.BuildPipe:
                case JobType.BuildGasPipe:
                case JobType.BuildShippingRail:
                case JobType.Dig:
                case JobType.Deconstruct:
                    return 5;
                case JobType.Harvest:
                    return 4;
                case JobType.Research:
                    return 4;
                default:
                    return 3;
            }
