            milestoneResearchProgram |= usableResearchStations > 0 && techAirSystems;
            milestoneStableOxygen |= (diffusers > 0 || algaeTerrariums > 0) && averageOxygen >= 0.34f;
            milestoneFoodPreparation |= techFoodPreparation && usableCookingStations > 0;
            milestoneFoodProduction |= planters >= 3 || food >= 5200f || (usableCookingStations > 0 && food >= 4200f);
            milestoneCropTending |= techFoodPreparation && farmStations > 0 && cropsTended > 0 && CountCropTendingTargets() == 0;
            milestoneBristleBlossomFarming |= techFoodPreparation && CountCells(CellKind.HydroponicFarm) > 0 && CountLitHydroponicFarms() > 0 && AnyHydroponicFarmHasIrrigation() && bristleBerryHarvests > 0 && bristleBerryFoodProduced >= BristleBerryHarvestYield;
