            milestoneThimbleReedFarming |= techFoodPreparation && thimbleReeds > 0 && CountComfortableThimbleReeds() > 0 && AnyThimbleReedHasPollutedWater() && thimbleReedPollutedWaterUsed >= 0.05f && thimbleReedHarvests > 0 && thimbleReedFiberHarvested >= ThimbleReedHarvestTarget;
            milestoneSleetWheatCuisine |= techFoodPreparation && sleetWheatPlants > 0 && CountComfortableSleetWheat() > 0 && AnySleetWheatHasWater() && sleetWheatWaterUsed >= 0.05f && sleetWheatHarvests > 0 && wheatGrainHarvested >= SleetWheatGrainHarvestTarget && frostBunsBaked > 0 && frostBunFoodPrepared >= FrostBunOutputFood;
            milestonePeppernutSeasoning |= techFoodPreparation && CountCells(CellKind.PepperPlant) > 0 && CountWarmPepperPlants() > 0 && AnyPepperPlantHasPollutedWater() && pepperPlantPollutedWaterUsed >= 0.05f && peppernutHarvests > 0 && peppernutUsed >= PeppernutSeasoningCost && spicedMealsPrepared > 0;
