        private void ApplyResearchUnlocks(bool announce)
        {
            NormalizeResearchFocus();
            if (TryUnlockResearchFocus(selectedResearchFocus, announce))
            {
                SelectNextLockedResearchFocus();
                return;
            }

            if (IsResearchUnlocked(selectedResearchFocus))
            {
                SelectNextLockedResearchFocus();
                TryUnlockResearchFocus(selectedResearchFocus, announce);
            }
        }

        private bool TryUnlockResearchFocus(ResearchFocus focus, bool announce)
        {
            if (IsResearchUnlocked(focus) || researchPoints < ResearchRequirement(focus))
            {
                return false;
            }

            switch (focus)
            {
                case ResearchFocus.AirSystems:
                    techAirSystems = true;
                    break;
                case ResearchFocus.FoodPreparation:
                    techFoodPreparation = true;
                    break;
                case ResearchFocus.PowerRegulation:
                    techPowerRegulation = true;
                    maxPower += CountCells(CellKind.Battery) * 25f;
                    break;
                case ResearchFocus.AutomationLogistics:
                    techAutomationLogistics = true;
                    break;
                case ResearchFocus.ThermalEngineering:
                    techThermalEngineering = true;
                    break;
                case ResearchFocus.AdvancedPower:
                    techAdvancedPower = true;
                    break;
                case ResearchFocus.SpaceSystems:
                    techSpaceSystems = true;
                    break;
                default:
                    return false;
            }

            if (announce)
            {
                Log("Research unlocked: " + ResearchFocusName(focus) + ".");
            }

            return true;
        }

        private string BuildAlertText(float averageOxygen, float averagePollutedOxygen, float averageHydrogen, float averageNaturalGas, float averageSourGas, float averageTemperature, int unsafeTemperatureTiles, int unwiredPowerBuildings, int overloadedWires, float maxWireLoad, float maxWorkerGermExposure, int unreachableJobs)
        {
            if (colonyFailed)
            {
                return "Colony failed. Load a save or start a new run.";
            }

            StringBuilder builder = new StringBuilder();
            int medicalCots = CountCells(CellKind.MedicalCot);
            int usableMedicalCots = CountUsableCells(CellKind.MedicalCot);
            int apothecaries = CountCells(CellKind.Apothecary);
            int medicineReadyApothecaries = CountMedicineReadyApothecaries();
            int relaxationStations = CountRelaxationStations();
            int usableRelaxationStations = CountUsableRelaxationStations();
            int toilets = CountCells(CellKind.Outhouse) + CountCells(CellKind.Lavatory);
            int usableToilets = CountUsableToilets();
            int hygieneFixtures = CountCells(CellKind.WashBasin) + CountCells(CellKind.HandSanitizer) + CountCells(CellKind.Shower);
            int usableHygieneFixtures = CountUsableHygieneFixtures();
            int handSanitizers = CountCells(CellKind.HandSanitizer);
            int usableHandSanitizers = CountUsableHandSanitizers();
            int rationBoxes = CountCells(CellKind.RationBox);
            int refrigerators = CountCells(CellKind.Refrigerator);
            int usableFoodStorageCells = CountUsableFoodStorageCells();
            int poweredRefrigerators = CountPoweredRefrigerators();
            int researchStations = CountCells(CellKind.ResearchStation);
            int usableResearchStations = CountUsableResearchStations();
            int ranchingStations = CountCells(CellKind.RanchingStation);
            int usableRanchingStations = CountUsableCells(CellKind.RanchingStation);
            int suitDocks = CountCells(CellKind.AtmoSuitDock);
            int usableSuitDocks = UsableSuitDockCount();
            int suitCheckpoints = CountCells(CellKind.AtmoSuitCheckpoint);
            int usableSuitCheckpoints = CountUsableCells(CellKind.AtmoSuitCheckpoint);
            int maskDocks = CountCells(CellKind.OxygenMaskDock);
            int usableMaskDocks = UsableOxygenMaskDockCount();
            int maskCheckpoints = CountCells(CellKind.OxygenMaskCheckpoint);
            int usableMaskCheckpoints = CountUsableCells(CellKind.OxygenMaskCheckpoint);
            int leadSuitLockers = CountCells(CellKind.LeadSuitLocker);
            int usableLeadSuitLockers = UsableLeadSuitLockerCount();
            int leadSuitCheckpoints = CountCells(CellKind.LeadSuitCheckpoint);
            int usableLeadSuitCheckpoints = CountUsableCells(CellKind.LeadSuitCheckpoint);
            int usableMetalRefineries = CountUsableCells(CellKind.MetalRefinery);
            int usableThermoAquatuners = CountUsableCells(CellKind.ThermoAquatuner);
            int usableThermoRegulators = CountUsableCells(CellKind.ThermoRegulator);
            int matureArborTrees = CountMatureArborTrees();
            int ethanolDistillers = CountCells(CellKind.EthanolDistiller);

            if (redAlertActive)
            {
                AppendAlert(builder, "red alert active");
            }

            int yellowAlertJobs = CountYellowAlertJobs();
            if (yellowAlertJobs > 0)
            {
                AppendAlert(builder, yellowAlertJobs + " yellow alert errands");
            }

            int suffocatingWorkers = CountSuffocatingWorkers();
            if (suffocatingWorkers > 0)
            {
                AppendAlert(builder, suffocatingWorkers + " suffocating duplicants");
            }
            else
            {
                int lowBreathWorkers = CountLowBreathWorkers();
                if (lowBreathWorkers > 0)
                {
                    AppendAlert(builder, lowBreathWorkers + " low breath duplicants");
                }
            }

            int depletedBreathingGearWorkers = CountDepletedBreathingGearWorkers();
            if (depletedBreathingGearWorkers > 0)
            {
                AppendAlert(builder, depletedBreathingGearWorkers + " depleted breathing gear");
            }

            if (!milestoneArborForestry && matureArborTrees > 0)
            {
                AppendAlert(builder, "wild arbor ready");
            }

            if (ethanolDistillers > 0 && !techAdvancedPower)
            {
                AppendAlert(builder, "ethanol distiller locked");
            }
            else if (ethanolDistillers > 0 && lumber <= 0.05f)
            {
                AppendAlert(builder, "ethanol distiller lacks lumber");
            }

            int unsafeEnvironmentWorkers = CountUnsafeEnvironmentWorkers();
            if (unsafeEnvironmentWorkers > 0)
            {
                AppendAlert(builder, unsafeEnvironmentWorkers + " unsafe duplicants");
            }

            int unsafeRoutineJobs = CountUnsafeRoutineJobs();
            if (unsafeRoutineJobs > 0)
            {
                AppendAlert(builder, unsafeRoutineJobs + " unsafe errands");
            }

            if (averageOxygen < 0.18f)
            {
                AppendAlert(builder, "low oxygen");
            }

            if (unreachableJobs > 0)
            {
                AppendAlert(builder, unreachableJobs + " unreachable jobs");
                if (AnyRestrictedDoorAccess())
                {
                    AppendAlert(builder, "door access restricted");
                }
            }

            if (AnyWorkerNeedsRescue())
            {
                AppendAlert(builder, "duplicant down");
                if (medicalCots == 0)
                {
                    AppendAlert(builder, "no rescue cot");
                }
                else if (usableMedicalCots == 0)
                {
                    AppendAlert(builder, "rescue cot offline");
                }
            }

            if (averagePollutedOxygen > 0.16f)
