            if (milestoneVentAnalysis && !milestoneSaltWaterGeyserTaming && CountCells(CellKind.SaltWaterGeyser) > 0)
            {
                if (CountCells(CellKind.Desalinator) == 0)
                {
                    AppendAlert(builder, "salt geyser needs desalinator");
                }
                else if (saltWaterGeyserSaltWaterGenerated >= 0.5f && CountRunningDesalinators() == 0)
                {
                    AppendAlert(builder, "geyser brine not desalinating");
                }
            }

            if (milestoneVentAnalysis && !milestoneCoolSlushGeyserTaming && CountCells(CellKind.CoolSlushGeyser) > 0)
            {
                if (CountCells(CellKind.WaterSieve) == 0)
                {
                    AppendAlert(builder, "cool slush needs water sieve");
                }
                else if (coolSlushGeyserPollutedWaterGenerated >= 0.5f && CountRunningWaterSieves() == 0)
                {
                    AppendAlert(builder, "cool slush not recycling");
                }
            }

            if (milestoneVentAnalysis && !milestonePollutedWaterVentTaming && CountCells(CellKind.PollutedWaterVent) > 0)
            {
                if (CountCells(CellKind.WaterPump) == 0)
                {
                    AppendAlert(builder, "polluted water vent needs water pump");
                }
                else if (CountCells(CellKind.LiquidReservoir) == 0)
                {
                    AppendAlert(builder, "polluted water vent needs reservoir");
                }
                else if (CountCells(CellKind.WaterSieve) == 0)
                {
                    AppendAlert(builder, "polluted water vent needs water sieve");
                }
                else if (pollutedWaterVentPollutedWaterGenerated >= 0.4f && pollutedWaterVentPollutedWaterPumped < PollutedWaterVentPumpTarget && CountRunningWaterPumps() == 0)
                {
                    AppendAlert(builder, "polluted water vent not pumped");
                }
                else if (pollutedWaterVentPollutedWaterPumped >= 0.1f && TotalLiquidReservoirPollutedWater() < PollutedWaterVentStorageTarget)
                {
                    AppendAlert(builder, "polluted water vent not buffered");
                }
                else if (TotalLiquidReservoirPollutedWater() >= 0.1f && CountRunningWaterSieves() == 0)
                {
                    AppendAlert(builder, "polluted water vent not sieving");
                }
            }

            if (milestoneVentAnalysis && !milestoneChlorineVentTaming && CountCells(CellKind.ChlorineGasVent) > 0)
            {
                if (CountCells(CellKind.GasPump) == 0)
                {
                    AppendAlert(builder, "chlorine vent needs gas pump");
                }
                else if (CountCells(CellKind.GasReservoir) == 0)
                {
                    AppendAlert(builder, "chlorine vent needs reservoir");
                }
                else if (chlorineVentChlorineGenerated >= 0.2f && TotalGasReservoirChlorine() < ChlorineVentStorageTarget && CountRunningGasPumps() == 0)
                {
                    AppendAlert(builder, "chlorine vent not contained");
                }
            }

            if (milestoneVentAnalysis && !milestoneCarbonDioxideVentTaming && CountCells(CellKind.CarbonDioxideVent) > 0)
            {
                if (CountCells(CellKind.GasPump) == 0)
                {
                    AppendAlert(builder, "carbon vent needs gas pump");
                }
                else if (CountCells(CellKind.GasReservoir) == 0)
                {
                    AppendAlert(builder, "carbon vent needs reservoir");
                }
                else if (carbonDioxideVentCarbonGenerated >= 0.2f && TotalGasReservoirCarbonDioxide() < CarbonDioxideVentStorageTarget && CountRunningGasPumps() == 0)
                {
                    AppendAlert(builder, "carbon vent not contained");
                }
            }

            if (milestoneVentAnalysis && !milestonePollutedOxygenVentTaming && CountCells(CellKind.PollutedOxygenVent) > 0)
            {
                if (CountCells(CellKind.AirDeodorizer) == 0)
                {
                    AppendAlert(builder, "polluted oxygen vent needs deodorizer");
                }
                else if (dirt <= 0.05f)
                {
                    AppendAlert(builder, "polluted oxygen vent needs filter dirt");
                }
                else if (pollutedOxygenVentPollutedOxygenGenerated >= 0.2f && pollutedOxygenVentPollutedOxygenFiltered < PollutedOxygenVentFilterTarget && CountRunningAirDeodorizers() == 0)
                {
                    AppendAlert(builder, "polluted oxygen vent not filtered");
                }
            }

            if (milestoneVentAnalysis && !milestoneCoolSteamVentTaming && CountCells(CellKind.CoolSteamVent) > 0)
            {
                if (CountCells(CellKind.SteamTurbine) == 0)
                {
                    AppendAlert(builder, "cool steam vent needs turbine");
                }
                else if (coolSteamVentSteamGenerated >= 0.2f && coolSteamVentSteamHarvested < CoolSteamVentHarvestTarget && CountRunningSteamTurbines() == 0)
                {
                    AppendAlert(builder, "cool steam vent not harvested");
                }
            }

            if (milestoneVentAnalysis && !milestoneMagmaVolcanoTaming && CountCells(CellKind.MagmaVolcano) > 0)
            {
                if (CountCells(CellKind.SteamTurbine) == 0)
                {
                    AppendAlert(builder, "magma volcano needs turbine");
                }
                else if (CountCells(CellKind.InsulatedTile) < 4)
                {
                    AppendAlert(builder, "magma volcano needs insulation");
                }
                else if (magmaVolcanoMagmaGenerated >= 0.1f && magmaSteamFlashed < MagmaVolcanoSteamFlashTarget && CountRunningSteamTurbines() == 0)
                {
                    AppendAlert(builder, "magma volcano heat not harvested");
                }
            }

            if (milestoneVentAnalysis && !milestoneLeakyOilFissureTaming && CountCells(CellKind.LeakyOilFissure) > 0)
            {
                if (CountCells(CellKind.OilRefinery) == 0)
                {
                    AppendAlert(builder, "leaky oil fissure needs refinery");
                }
                else if (leakyOilFissureCrudeGenerated >= 0.2f && leakyOilFissureCrudeRefined < LeakyOilFissureRefineTarget && CountRunningOilRefineries() == 0)
                {
                    AppendAlert(builder, "leaky oil fissure not refined");
                }
            }

            if (CountCells(CellKind.MetalVolcano) > 0 &&
                volcanicRefinedMetalGenerated > 0.05f &&
                CountCells(CellKind.InsulatedTile) == 0)
            {
                AppendAlert(builder, "hot metal volcano exposed");
            }

            if (CountCells(CellKind.MagmaVolcano) > 0 &&
                magmaVolcanoMagmaGenerated > 0.05f &&
                CountCells(CellKind.InsulatedTile) == 0)
            {
                AppendAlert(builder, "hot magma volcano exposed");
            }

            if (CountCritters() > 0 && ranchingStations == 0)
            {
                AppendAlert(builder, "wild critters");
            }

            if (CountCritters() > 0 && ranchingStations > 0 && usableRanchingStations == 0)
            {
                AppendAlert(builder, "ranching station offline");
            }
            else if (CountCritters() > 0 && usableRanchingStations > 0 && CountUngroomedCritters() > 0)
            {
                AppendAlert(builder, "critters need grooming");
            }

            if (usableRanchingStations > 0 && CountRoomsOfKind(RoomKind.Stable) == 0)
            {
                AppendAlert(builder, "no stable room");
            }

            int overcrowdedStables = CountOvercrowdedStables();
            if (overcrowdedStables > 0)
            {
                AppendAlert(builder, overcrowdedStables + " overcrowded stables");
            }

            if (CountCritters(CritterKind.Hatch) > 0 && !HasHatchFeedAvailable())
            {
                AppendAlert(builder, "hatches need debris");
            }

            if (CountCritters(CritterKind.Slickster) > 0 && CarbonDioxideNearSlicksters() <= 0.05f)
            {
                AppendAlert(builder, "slicksters need CO2");
            }

            if (CountCritters(CritterKind.MoltenSlickster) > 0 && CarbonDioxideNearMoltenSlicksters() <= 0.05f)
            {
                AppendAlert(builder, "molten slicksters need hot CO2");
            }

            if (CountCritters(CritterKind.Drecko) > 0 && !HasDreckoFeedAvailable())
            {
                AppendAlert(builder, "dreckos need mealwood or algae");
            }

            if (CountCritters(CritterKind.Drecko) > 0 && HydrogenNearDreckos() < DreckoHydrogenThreshold)
            {
                AppendAlert(builder, "dreckos need hydrogen");
            }

            if (CountCritters(CritterKind.Puft) > 0 && PollutedOxygenNearPufts() <= 0.05f)
            {
                AppendAlert(builder, "pufts need polluted oxygen");
            }

            if (CountCritters(CritterKind.Morb) > 0 && CountCells(CellKind.AirDeodorizer) == 0)
            {
                AppendAlert(builder, "morbs spreading polluted oxygen");
            }

            if (CountCritters(CritterKind.Pacu) > 0 && algae <= 0.05f)
            {
                AppendAlert(builder, "pacu need algae");
            }

            if (CountCritters(CritterKind.ShineBug) > 0 && algae <= 0.02f)
            {
                AppendAlert(builder, "shine bugs need algae");
            }

            if (CountCritters(CritterKind.Beeta) > 0 && BeetaRadiationTilesNearBeetas() == 0)
            {
                AppendAlert(builder, "beetas need radiation");
            }

            if (CountCritters(CritterKind.Grubgrub) > 0 && CropCellsNearGrubgrubs() == 0)
            {
                AppendAlert(builder, "grubgrubs need crops");
            }

            if (CountCritters(CritterKind.Sweetle) > 0 && SulfurNearSweetles() <= 0.05f)
            {
                AppendAlert(builder, "sweetles need sulfur");
            }

            if (CountCritters(CritterKind.CuddlePip) > 0 && EggTargetsNearCuddlePips() == 0)
            {
                AppendAlert(builder, "cuddle pips need eggs");
            }

            if (CountCritters(CritterKind.ShoveVole) > 0 && RegolithCellsNearShoveVoles() == 0)
            {
                AppendAlert(builder, "shove voles need regolith");
            }

            int strandedPacus = CountStrandedPacus();
            if (strandedPacus > 0)
            {
                AppendAlert(builder, strandedPacus + " pacu stranded");
            }

            if (techFoodPreparation && CountCropCells() >= 3 && CountCells(CellKind.FarmStation) == 0)
            {
                AppendAlert(builder, "untended crops");
            }
            else if (CountCells(CellKind.FarmStation) > 0 && CountCropTendingTargets() > 0 && !CanSupplyCropTending())
            {
                AppendAlert(builder, "farm needs fertilizer");
            }

            if (CountCells(CellKind.HydroponicFarm) > 0)
            {
                if (!AnyHydroponicFarmHasIrrigation())
                {
                    AppendAlert(builder, "bristle blossoms need water");
                }

                if (CountLitHydroponicFarms() == 0)
                {
                    AppendAlert(builder, "bristle blossoms need light");
                }
            }

            if (CountCells(CellKind.FungalFarm) > 0)
            {
                if (slime <= 0.02f)
                {
                    AppendAlert(builder, "dusk caps need slime");
                }

                if (CountCarbonDioxideFungalFarms() == 0)
                {
                    AppendAlert(builder, "dusk caps need CO2");
                }

                if (CountDarkFungalFarms() == 0)
                {
                    AppendAlert(builder, "dusk caps need darkness");
                }
            }

            if (CountCells(CellKind.PepperPlant) > 0)
            {
                if (!AnyPepperPlantHasPollutedWater())
                {
                    AppendAlert(builder, "pepperplants need polluted water");
                }

                if (CountWarmPepperPlants() == 0)
                {
                    AppendAlert(builder, "pepperplants need heat");
                }
            }

            if (CountCells(CellKind.GrubfruitPlant) > 0)
            {
                if (!AnyGrubfruitPlantHasSulfur())
                {
                    AppendAlert(builder, "grubfruit plants need sulfur");
                }

                if (CountComfortableGrubfruitPlants() == 0)
                {
                    AppendAlert(builder, "grubfruit plants need mild gas");
                }
            }

            if (CountCells(CellKind.ThimbleReed) > 0)
            {
                if (!AnyThimbleReedHasPollutedWater())
                {
                    AppendAlert(builder, "thimble reeds need polluted water");
                }

                if (CountComfortableThimbleReeds() == 0)
                {
                    AppendAlert(builder, "thimble reeds need swamp pressure");
                }
            }

            if (CountCells(CellKind.SleetWheat) > 0)
            {
                if (!AnySleetWheatHasWater())
                {
                    AppendAlert(builder, "sleet wheat needs clean water");
                }

                if (CountComfortableSleetWheat() == 0)
                {
                    AppendAlert(builder, "sleet wheat needs freezing oxygen");
                }
            }

            int wiltingCrops = CountWiltingCrops();
            if (wiltingCrops > 0)
            {
                AppendAlert(builder, wiltingCrops + " crop wilting");
            }
            else
            {
                int stressedCrops = CountStressedCrops();
                if (stressedCrops > 0)
                {
                    AppendAlert(builder, stressedCrops + " crop stifled");
                }
            }

            if (unsafeTemperatureTiles > 12 && CountCells(CellKind.InsulatedTile) == 0)
            {
                AppendAlert(builder, "no insulated tiles");
            }

            if (CountBeds() > 0 && CountSleepingRooms() == 0)
            {
                AppendAlert(builder, "no barracks room");
            }

            if (CountCells(CellKind.MessTable) > 0 && CountDiningRooms() == 0)
            {
                AppendAlert(builder, "no mess hall room");
            }

            if (CountCells(CellKind.PrintingPod) > 0 && workers.Count < MaxWorkers && printingPodProgress >= 0.98f && !TryFindPrintingPodSpawn(out _))
            {
                AppendAlert(builder, "printing pod blocked");
            }

            if (algae < 8f)
            {
                AppendAlert(builder, "low algae");
            }

            float dryUsed = DryResourceAmount();
            float dryCapacity = DryResourceCapacity();
            if (CountLooseResourceTiles() > 0 && DryResourceFreeSpace() > 0.01f)
            {
                AppendAlert(builder, "loose debris");
                if (techAutomationLogistics && CountCells(CellKind.AutoSweeper) == 0 && CountLooseResourceTiles() >= 4)
                {
                    AppendAlert(builder, "no auto-sweeper");
                }
            }

            if (techAutomationLogistics && CountCells(CellKind.ConveyorLoader) > 0)
            {
                if (CountShippingRailTiles() == 0)
                {
                    AppendAlert(builder, "no shipping rail");
                }
                else if (CountCells(CellKind.ConveyorChute) == 0)
                {
                    AppendAlert(builder, "no conveyor chute");
                }
            }

            if (techAutomationLogistics && CountCells(CellKind.SignalSwitch) > 0 && !AnySignalSwitchLinked())
            {
                AppendAlert(builder, "unwired signal switch");
            }

            if (dryUsed >= dryCapacity - 0.5f)
            {
                AppendAlert(builder, "dry storage full");
            }
            else if (CountCells(CellKind.StorageBin) == 0 && dryUsed > dryCapacity * 0.75f)
            {
                AppendAlert(builder, "no storage bin");
            }

            if (water < workers.Count * 12f)
            {
                AppendAlert(builder, "low water");
            }
            else if (waterGerms >= CleanWaterGermAlertThreshold)
            {
                AppendAlert(builder, "clean water germy");
            }

            if (pollutedWater > 0.5f && pollutedWaterGerms >= PollutedWaterGermAlertThreshold)
            {
                AppendAlert(builder, "polluted water germy");
            }

            if (AnyElectrolyzerHasGermyWaterFeed())
            {
                AppendAlert(builder, "germy electrolyzer feed");
            }

            if (germyWaterUses > 0)
            {
                AppendAlert(builder, germyWaterUses + " germy water uses");
            }

            if (CountMoppableSpills() > 0)
            {
                AppendAlert(builder, "liquid spill");
            }

            if (pollutedWater > 80f)
            {
                AppendAlert(builder, "polluted water stored");
            }
            if (PollutedWaterOffgasAvailableMass() > 5f && CountPollutedWaterOffgasSources() > 0)
            {
                AppendAlert(builder, "polluted water offgassing");
            }
            if (pollutedWater > 20f && CountCells(CellKind.BottleEmptier) == 0)
            {
                AppendAlert(builder, "no bottle emptier");
            }
            else if (pollutedWater > 20f && CountCells(CellKind.WaterSieve) == 0)
            {
                AppendAlert(builder, "no water sieve");
            }

            if (PollutedDirtOffgasAvailableMass() > 5f && CountPollutedDirtOffgasSources() > 0)
            {
                AppendAlert(builder, "polluted dirt offgassing");
            }
            else if (CompostablePollutedDirt() > 10f && CountCells(CellKind.Compost) == 0)
            {
                AppendAlert(builder, "no compost");
            }

            float pipeStoredLiquid = TotalPipeLiquid();
            int pipeTiles = CountLiquidPipeTiles();
            int liquidVents = CountCells(CellKind.LiquidVent);
            int unsafeLiquidPipes = CountUnsafeLiquidPipes();
            int unsafeLiquidReservoirs = CountUnsafeLiquidReservoirs();
            if (unsafeLiquidPipes > 0)
            {
                AppendAlert(builder, unsafeLiquidPipes + " pipe phase risk");
            }
            else if (pipeBurstEvents > 0)
            {
                AppendAlert(builder, pipeBurstEvents + " pipe burst");
            }

            if (unsafeLiquidReservoirs > 0)
            {
                AppendAlert(builder, unsafeLiquidReservoirs + " reservoir phase risk");
            }
            else if (reservoirBurstEvents > 0)
            {
                AppendAlert(builder, reservoirBurstEvents + " reservoir burst");
            }

            if (pipeStoredLiquid > LiquidPipeCapacity && liquidVents == 0)
            {
                AppendAlert(builder, "pipe water backed up");
            }
            else if (pipeStoredLiquid > LiquidPipeCapacity && CountCells(CellKind.LiquidReservoir) == 0)
            {
                AppendAlert(builder, "no liquid reservoir");
            }
            else if (liquidVents > 0 && pipeTiles == 0)
            {
                AppendAlert(builder, "unconnected liquid vent");
            }

            float pipeStoredGas = TotalGasPipeMass();
            int gasPipeTiles = CountGasPipeTiles();
            int gasPumps = CountCells(CellKind.GasPump);
            int gasVents = CountCells(CellKind.GasVent) + CountCells(CellKind.HighPressureGasVent);
            int condensingGasPipes = CountCondensingGasPipes();
            int condensingGasReservoirs = CountCondensingGasReservoirs();
            if (condensingGasPipes > 0)
            {
                AppendAlert(builder, condensingGasPipes + " gas pipe steam condensation");
            }
            else if (condensingGasReservoirs > 0)
            {
                AppendAlert(builder, condensingGasReservoirs + " gas reservoir steam condensation");
            }
            else if (gasConduitCondensationEvents > 0)
            {
                AppendAlert(builder, gasConduitCondensationEvents + " gas conduit condensation");
            }

            if (pipeStoredGas > GasPipeCapacity && gasVents == 0)
            {
                AppendAlert(builder, "gas pipe backed up");
            }
            else if (pipeStoredGas > GasPipeCapacity && CountCells(CellKind.GasReservoir) == 0)
            {
                AppendAlert(builder, "no gas reservoir");
            }
            else if (gasPumps > 0 && gasPipeTiles == 0)
            {
                AppendAlert(builder, "unconnected gas pump");
            }
            else if (gasVents > 0 && gasPipeTiles == 0)
            {
                AppendAlert(builder, "unconnected gas vent");
            }

            if (AnyGermyGasConduit())
            {
                AppendAlert(builder, "germy gas conduit");
            }

            if (food < workers.Count * 700f)
            {
                AppendAlert(builder, "low food");
                string cookingBlock = CookingBlockedAlertText();
                if (!string.IsNullOrEmpty(cookingBlock))
                {
                    AppendAlert(builder, cookingBlock);
                }
            }

            int foodPolicyBlockedHungryWorkers = CountFoodPolicyBlockedHungryWorkers();
            if (foodPolicyBlockedHungryWorkers > 0)
            {
                AppendAlert(builder, foodPolicyBlockedHungryWorkers == 1
                    ? "1 hungry duplicant blocked by Food SAFE"
                    : foodPolicyBlockedHungryWorkers + " hungry duplicants blocked by Food SAFE");
            }

            if (food >= workers.Count * 700f && CountCells(CellKind.MessTable) < workers.Count)
            {
                AppendAlert(builder, "not enough mess tables");
            }

            if (food > workers.Count * 900f && rationBoxes + refrigerators == 0)
            {
                AppendAlert(builder, "no food storage");
            }
            else if (food > workers.Count * 900f && usableFoodStorageCells == 0)
            {
                AppendAlert(builder, "food storage offline");
            }
            else if (food > workers.Count * 900f && rationBoxes == 0 && refrigerators > 0 && poweredRefrigerators == 0)
            {
                AppendAlert(builder, "refrigerator unpowered");
            }
            else if (foodGerms >= FoodGermExposureThreshold)
            {
                AppendAlert(builder, "food contaminated");
            }
            else if (food > 1f && foodFreshness <= SpoiledFoodRotFreshnessThreshold)
            {
                AppendAlert(builder, "food rotting");
            }
            else if (foodFreshness < 0.35f)
            {
                AppendAlert(builder, "food spoiling");
            }

            if (foodPoisoningCases > 0)
            {
                AppendAlert(builder, foodPoisoningCases + " food poison");
            }
            else if (contaminatedMealsEaten > 0)
            {
                AppendAlert(builder, contaminatedMealsEaten + " contaminated meals");
            }
            else if (staleMealsEaten > 0)
            {
                AppendAlert(builder, staleMealsEaten + " stale meals");
            }

            if (HasLockedResearch() && researchStations > 0 && usableResearchStations == 0)
            {
                AppendAlert(builder, "research station offline");
            }
            else if (HasLockedResearch() && usableResearchStations > 0)
            {
                AppendAlert(builder, "research pending");
            }

            if (IsRestTime() && CountBeds() < workers.Count)
            {
                AppendAlert(builder, "not enough beds");
            }

            if (toilets == 0)
            {
                AppendAlert(builder, "no toilet");
            }
            else if (usableToilets == 0)
            {
                AppendAlert(builder, AnyLavatoryNeedsCleanWater() ? "lavatory lacks water" : "toilet offline");
            }

            bool workerNeedsTreatment = AnyWorkerNeedsTreatment();
            if (workerNeedsTreatment && medicalCots == 0)
            {
                AppendAlert(builder, "no medical cot");
            }
            else if (workerNeedsTreatment && usableMedicalCots == 0)
            {
                AppendAlert(builder, "medical cot offline");
            }
            else if (workerNeedsTreatment && medicine < MedicineTreatmentUse && apothecaries == 0)
            {
                AppendAlert(builder, "no medicine");
            }
            else if (workerNeedsTreatment && medicine < MedicineTreatmentUse && medicineReadyApothecaries == 0)
            {
                AppendAlert(builder, "medicine blocked");
            }

            bool workerNeedsRelaxation = AnyWorkerNeedsRelaxation();
            if (workerNeedsRelaxation && relaxationStations == 0)
            {
                AppendAlert(builder, "no stress relief");
            }
            else if (workerNeedsRelaxation && usableRelaxationStations == 0)
            {
                if (AnyWaterCoolerNeedsCleanWater())
                {
                    AppendAlert(builder, "water cooler dry");
                }
                else if (AnyArcadeCabinetNeedsPlastic())
                {
                    AppendAlert(builder, "arcade lacks plastic");
                }
                else if (AnyArcadeCabinetNeedsPower())
                {
                    AppendAlert(builder, "arcade unpowered");
                }
                else
                {
                    AppendAlert(builder, "stress relief offline");
                }
            }

            int skillScrubCandidates = CountSkillScrubCandidates();
            if (skillScrubCandidates > 0 && CountCells(CellKind.SkillScrubber) == 0 && techPowerRegulation)
            {
                AppendAlert(builder, "skill scrubber needed");
            }

            if (HighestStress() > 45f && AverageWorkerDecor() < 0.18f)
            {
                AppendAlert(builder, "low decor");
            }

            foreach (Worker worker in workers)
            {
                if (worker.StressBreakSeconds > 0f)
                {
                    AppendAlert(builder, worker.Name + " stress break");
                    break;
                }

                if (worker.Bladder > 88f)
                {
                    AppendAlert(builder, worker.Name + " needs toilet");
                    break;
                }

                if (worker.Fatigue > 88f)
                {
                    AppendAlert(builder, worker.Name + " exhausted");
                    break;
                }

                if (worker.Sickness > 45f)
                {
                    AppendAlert(builder, worker.Name + " sick");
                    break;
                }

                if (worker.Health < 45f)
                {
                    AppendAlert(builder, worker.Name + " injured");
                    break;
                }

                if (worker.Stress > 80f)
                {
                    AppendAlert(builder, worker.Name + " stressed");
                    break;
                }
            }

            return builder.Length == 0 ? "Stable." : builder.ToString();
        }

        private void AppendAlert(StringBuilder builder, string alert)
        {
            if (builder.Length > 0)
            {
                builder.Append(", ");
            }

            builder.Append(alert);
        }

        private void TriggerColonyFailure(string reason)
        {
            if (colonyFailed)
            {
                return;
            }

            colonyFailed = true;
            paused = true;
            Log("Colony failed: " + reason);
            UpdateColonyStatus(true);
        }

        private int CountCells(CellKind kind)
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == kind)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountBeds()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsBedKind(cells[x, y]))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountClosedAirlocks()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if ((cells[x, y] == CellKind.ManualAirlock && !airlockOpen[x, y]) ||
                        (cells[x, y] == CellKind.MechanizedAirlock && !IsMechanizedAirlockOpen(new Vector2Int(x, y))))
                    {
                        count++;
                    }
                }
            }

            return count;
