            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsRepairableEquipment(cells[x, y]) &&
                        !IsBrokenEquipment(new Vector2Int(x, y)) &&
                        EquipmentOverheatSeverity(x, y) > 0.001f)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountUncontainedOverheatingEquipment()
        {
            EnsureRooms();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (!IsRepairableEquipment(cells[x, y]) ||
                        IsBrokenEquipment(new Vector2Int(x, y)) ||
                        EquipmentOverheatSeverity(x, y) <= 0.001f)
                    {
                        continue;
                    }

                    int roomId = roomIds[x, y];
                    if (roomId >= 0 && roomId < rooms.Count && IsIndustrialSaunaRoom(rooms[roomId]))
                    {
                        continue;
                    }

                    count++;
                }
            }

            return count;
        }

