        private float TotalMixedHydrogenPipeGas()
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (gasPipe[x, y] && gasPipeHydrogen[x, y] > 0.01f)
                    {
                        total += PipeNonHydrogenTotal(x, y);
                    }
                }
            }

            return total;
        }

        private float TotalMixedLiquidPipe()
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    int liquidKinds = 0;
                    if (pipeWater[x, y] > 0.05f)
                    {
                        liquidKinds++;
                    }

                    if (pipePollutedWater[x, y] > 0.05f)
                    {
                        liquidKinds++;
                    }

                    if (pipePetroleum[x, y] > 0.05f)
                    {
                        liquidKinds++;
                    }

                    if (liquidPipe[x, y] && liquidKinds >= 2)
                    {
                        total += LiquidPipeTotal(x, y);
                    }
                }
            }

            return total;
        }

