        private float DryResourceAmount()
        {
            return dirt + metal + algae + slime + bleachStone + salt + fertilizer + plastic + peppernut + lumber + reedFiber + sulfur + wheatGrain + coal + refinedMetal + steel + ceramic + glass + niobium + thermium + fullerene + superCoolant + cryogenicPropellant + pollutedDirt + hatchEggs;
        }

        private float DryResourceAmount(LooseResourceKind kind)
        {
            switch (kind)
            {
                case LooseResourceKind.Dirt:
                    return dirt;
                case LooseResourceKind.Metal:
                    return metal;
                case LooseResourceKind.Algae:
                    return algae;
                case LooseResourceKind.Slime:
                    return slime;
                case LooseResourceKind.BleachStone:
                    return bleachStone;
                case LooseResourceKind.Plastic:
                    return plastic;
                case LooseResourceKind.Coal:
                    return coal;
                case LooseResourceKind.RefinedMetal:
                    return refinedMetal;
                case LooseResourceKind.Steel:
                    return steel;
                case LooseResourceKind.Ceramic:
                    return ceramic;
                case LooseResourceKind.Glass:
                    return glass;
                case LooseResourceKind.Niobium:
                    return niobium;
                case LooseResourceKind.Thermium:
                    return thermium;
                case LooseResourceKind.Fullerene:
                    return fullerene;
                case LooseResourceKind.SuperCoolant:
                    return superCoolant;
                case LooseResourceKind.CryogenicPropellant:
                    return cryogenicPropellant;
                case LooseResourceKind.PollutedDirt:
                    return pollutedDirt;
                case LooseResourceKind.HatchEgg:
                    return hatchEggs;
                case LooseResourceKind.Peppernut:
                    return peppernut;
                case LooseResourceKind.Lumber:
                    return lumber;
                case LooseResourceKind.ReedFiber:
                    return reedFiber;
                case LooseResourceKind.Sulfur:
                    return sulfur;
                case LooseResourceKind.WheatGrain:
                    return wheatGrain;
                default:
                    return 0f;
            }
        }

        private float DryResourceAmount(StorageFilter filter)
        {
            if (filter == StorageFilter.All)
            {
                return DryResourceAmount();
            }

            float total = 0f;
            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Dirt))
            {
                total += dirt;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Metal))
            {
                total += metal;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Algae))
            {
                total += algae;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Slime))
            {
                total += slime;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.BleachStone))
            {
                total += bleachStone;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Plastic))
            {
                total += plastic;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Coal))
            {
                total += coal;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.RefinedMetal))
            {
                total += refinedMetal;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Steel))
            {
                total += steel;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Ceramic))
            {
                total += ceramic;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Glass))
            {
                total += glass;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Niobium))
            {
                total += niobium;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Thermium))
            {
                total += thermium;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Fullerene))
            {
                total += fullerene;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.SuperCoolant))
            {
                total += superCoolant;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.CryogenicPropellant))
            {
                total += cryogenicPropellant;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.PollutedDirt))
            {
                total += pollutedDirt;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.HatchEgg))
            {
                total += hatchEggs;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Peppernut))
            {
                total += peppernut;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Lumber))
            {
                total += lumber;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.ReedFiber))
            {
                total += reedFiber;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.Sulfur))
            {
                total += sulfur;
            }

            if (StorageFilterAcceptsResource(filter, LooseResourceKind.WheatGrain))
            {
                total += wheatGrain;
            }

            return total;
        }

        private float DryResourceCapacity()
        {
            return BaseDryResourceCapacity + StorageBinCapacityTotal();
        }

        private float DryResourceFreeSpace()
        {
            return Mathf.Max(0f, DryResourceCapacity() - DryResourceAmount());
        }

        private float DryResourceCapacity(LooseResourceKind kind, bool manualSweepDelivery)
        {
            if (kind == LooseResourceKind.None)
            {
                return 0f;
            }

            float capacity = BaseDryResourceCapacity;
            capacity += StorageBinCapacityAcceptingResource(kind, manualSweepDelivery);
            return capacity;
        }

        private float StorageBinCapacityTotal()
        {
            float capacity = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    capacity += StorageBinCapacityAt(x, y);
                }
            }

            return capacity;
        }

        private float StorageBinCapacityAcceptingResource(LooseResourceKind kind, bool manualSweepDelivery)
        {
            float capacity = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (StorageBinAcceptsResource(x, y, kind, manualSweepDelivery))
                    {
                        capacity += StorageBinCapacityAt(x, y);
                    }
                }
            }

            return capacity;
        }

        private float StorageBinCapacityAt(int x, int y)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.StorageBin)
            {
                return 0f;
            }

            return RoomKindAt(x, y) == RoomKind.StorageRoom
                ? StorageBinCapacity * StorageRoomBinCapacityMultiplier
                : StorageBinCapacity;
        }

        private int CountStorageBinsAcceptingResource(LooseResourceKind kind, bool manualSweepDelivery)
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (StorageBinAcceptsResource(x, y, kind, manualSweepDelivery))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private float DryResourceFreeSpace(LooseResourceKind kind, bool manualSweepDelivery)
        {
            if (kind == LooseResourceKind.None)
            {
                return 0f;
            }

            float sharedBaseFree = Mathf.Max(0f, BaseDryResourceCapacity - DryResourceAmount());
            float filteredFree = sharedBaseFree + StorageBinCapacityAcceptingResource(kind, manualSweepDelivery);
            return Mathf.Min(DryResourceFreeSpace(), filteredFree);
        }

        private bool CanStoreLooseResource(LooseResourceKind kind, bool manualSweepDelivery)
        {
            return DryResourceFreeSpace(kind, manualSweepDelivery) > 0.01f;
        }

        private bool StorageBinAcceptsResource(int x, int y, LooseResourceKind kind, bool manualSweepDelivery)
        {
            if (!IsInside(x, y) || cells[x, y] != CellKind.StorageBin || kind == LooseResourceKind.None)
            {
                return false;
            }

            if (storageSweepOnly[x, y] && !manualSweepDelivery)
            {
                return false;
            }

            return StorageFilterAcceptsResource(storageBinFilter[x, y], kind);
        }

        private bool StorageFilterAcceptsResource(StorageFilter filter, LooseResourceKind kind)
        {
            return kind != LooseResourceKind.None && (filter == StorageFilter.All || filter == StorageFilterForLooseResource(kind));
        }

        private int CountUnwiredPowerBuildings()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (RequiresPower(cells[x, y]) && !HasWireAccess(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountAutomationControlledGenerators()
        {
            UpdateAutomationWires();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanRecoverPowerWithAutomatedGenerator(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountAutomaticGeneratorCells()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsAutomaticGenerator(cells[x, y]))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool IsAutomaticGenerator(CellKind kind)
        {
            return kind == CellKind.CoalGenerator ||
                kind == CellKind.HydrogenGenerator ||
                kind == CellKind.NaturalGasGenerator ||
                kind == CellKind.PetroleumGenerator ||
                kind == CellKind.SteamTurbine ||
                kind == CellKind.ResearchReactor;
        }

        private bool CanRecoverPowerWithAutomatedGenerator(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) ||
                !CanUseEquipment(cell) ||
                !HasWireAccess(cell) ||
                !HasCachedAutomationControl(cell))
            {
                return false;
            }

            switch (cells[cell.x, cell.y])
            {
                case CellKind.CoalGenerator:
                    return coal > 0.001f;
                case CellKind.HydrogenGenerator:
                    return HydrogenFuelAvailable(cell) > 0.01f;
                case CellKind.NaturalGasGenerator:
                    return NaturalGasFuelAvailable(cell) > 0.01f;
                case CellKind.PetroleumGenerator:
                    return PetroleumFuelAvailable(cell) > 0.01f;
                case CellKind.SteamTurbine:
                    return HotSteamAvailable(cell, SteamTurbineRadius) > 0.03f;
                case CellKind.ResearchReactor:
                    return milestoneRadiationResearch && radiationSamplesAnalyzed > 0.001f;
                default:
                    return false;
            }
        }

        private int CountAutomationControlledConduitShutoffs()
        {
            UpdateAutomationWires();
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (CanAutomateConduitFlow(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool CanAutomateConduitFlow(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) ||
                !CanUseEquipment(cell) ||
                !HasCachedAutomationControl(cell))
            {
                return false;
            }

            CellKind kind = cells[cell.x, cell.y];
            if (kind == CellKind.LiquidShutoff || kind == CellKind.LiquidValve)
            {
                return liquidPipe[cell.x, cell.y];
            }

            if (kind == CellKind.GasShutoff || kind == CellKind.GasValve)
            {
                return gasPipe[cell.x, cell.y];
            }

            return false;
        }

        private int CountPoweredBuildings()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (RequiresPower(cells[x, y]) && CanPoweredMachineRun(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountActiveWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountYellowAlertJobs()
        {
            int count = 0;
            foreach (Job job in jobs)
            {
                if (job.YellowAlert)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountLowBreathWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && worker.Breath < CatchBreathThreshold)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountDepletedBreathingGearWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (HasDepletedBreathingGearInUnsafeArea(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountSuitCheckpointsMissingDock()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.AtmoSuitCheckpoint &&
                        CanUseEquipment(cell) &&
                        !HasAdjacentSuitDock(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountOxygenMaskCheckpointsMissingDock()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.OxygenMaskCheckpoint &&
                        CanUseEquipment(cell) &&
                        !HasAdjacentOxygenMaskDock(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountLeadSuitCheckpointsMissingLocker()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    Vector2Int cell = new Vector2Int(x, y);
                    if (cells[x, y] == CellKind.LeadSuitCheckpoint &&
                        CanUseEquipment(cell) &&
                        !HasAdjacentLeadSuitLocker(cell))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private int CountSourGasExposedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f &&
                    IsInside(worker.Cell.x, worker.Cell.y) &&
                    sourGas[worker.Cell.x, worker.Cell.y] > SourGasExposureThreshold &&
                    !HasBreathingProtectionAvailable(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private bool HasBreathingProtectionAvailable(Worker worker)
        {
            if (worker == null)
            {
                return false;
            }

            return (worker.SuitEquipped && HasChargedSuitOxygen()) ||
                (worker.OxygenMaskEquipped && HasChargedOxygenMask());
        }

        private int CountUnsafeEnvironmentWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (NeedsSeekSafety(worker))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountUnsafeRoutineJobs()
        {
            int count = 0;
            foreach (Job job in jobs)
            {
                if (job.AssignedWorker != null || IsSafetyCriticalJob(job.Type) || !IsJobValid(job))
                {
                    continue;
                }

                if (!CanAnyActiveWorkerReachJob(job, out _) && CanAnyActiveWorkerReachJobIgnoringSafety(job, out _))
                {
                    count++;
                }
            }

            return count;
        }

        private int CountSuffocatingWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && worker.Breath <= 0.01f)
                {
                    count++;
                }
            }

            return count;
        }

        private float LowestWorkerBreath()
        {
            float lowest = BreathCapacity;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f)
                {
                    lowest = Mathf.Min(lowest, worker.Breath);
                }
            }

            return lowest;
        }

        private float HighestStress()
        {
            float highest = 0f;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f)
                {
                    highest = Mathf.Max(highest, worker.Stress);
                }
            }

            return highest;
        }

        private int HighestWorkerSkillLevel()
        {
            int highest = 1;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f)
                {
                    highest = Mathf.Max(highest, WorkerSkillLevel(worker));
                }
            }

            return highest;
        }

        private void SaveGame(bool autosave)
        {
            try
            {
                string directory = Path.GetDirectoryName(SaveFilePath);
                if (!string.IsNullOrEmpty(directory))
                {
                    Directory.CreateDirectory(directory);
                }

                SaveData data = CaptureSaveData();
                File.WriteAllText(SaveFilePath, JsonUtility.ToJson(data, true));
                Log(autosave ? "Autosaved colony." : "Game saved.");
            }
            catch (Exception exception)
            {
                Debug.LogException(exception);
                Log("Save failed: " + exception.Message);
            }
        }

        private void LoadGame(bool silent)
        {
            try
            {
                if (!File.Exists(SaveFilePath))
                {
                    if (!silent)
                    {
                        Log("No save file found.");
                    }

                    return;
                }

                SaveData data = JsonUtility.FromJson<SaveData>(File.ReadAllText(SaveFilePath));
                if (data == null || data.width != WorldWidth || data.height != WorldHeight || data.cells == null)
                {
                    Log("Save file is incompatible.");
                    return;
                }

                ApplySaveData(data);
                HideStartStatePanel(false);
                Log("Game loaded.");
            }
            catch (Exception exception)
            {
                Debug.LogException(exception);
                Log("Load failed: " + exception.Message);
            }
        }

