            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    int index = Key(x, y);
                    data.cells[index] = (int)cells[x, y];
                    data.oxygen[index] = oxygen[x, y];
                    data.carbonDioxide[index] = carbonDioxide[x, y];
                    data.pollutedOxygen[index] = pollutedOxygen[x, y];
                    data.hydrogen[index] = hydrogen[x, y];
                    data.steam[index] = steam[x, y];
                    data.chlorine[index] = chlorine[x, y];
                    data.naturalGas[index] = naturalGas[x, y];
                    data.sourGas[index] = sourGas[x, y];
                    data.germs[index] = germs[x, y];
                    data.plantGrowth[index] = plantGrowth[x, y];
                    data.cropTendedSeconds[index] = IsCropKind(cells[x, y]) ? Mathf.Max(0f, cropTendedSeconds[x, y]) : 0f;
                    data.cropStress[index] = IsCropKind(cells[x, y]) ? Mathf.Max(0f, cropStress[x, y]) : 0f;
                    data.hatchEggAge[index] = looseResourceKind[x, y] == LooseResourceKind.HatchEgg ? Mathf.Max(0f, hatchEggAge[x, y]) : 0f;
                    data.incubatorEggLoaded[index] = cells[x, y] == CellKind.Incubator && incubatorEggLoaded[x, y];
                    data.incubatorEggProgress[index] = cells[x, y] == CellKind.Incubator && incubatorEggLoaded[x, y] ? Mathf.Clamp01(incubatorEggProgress[x, y]) : 0f;
                    data.waterMass[index] = waterMass[x, y];
                    data.temperature[index] = temperature[x, y];
                    data.equipmentCondition[index] = IsRepairableEquipment(cells[x, y]) ? Mathf.Clamp01(equipmentCondition[x, y]) : 0f;
                    data.buildingDisabled[index] = IsDisablableBuilding(cells[x, y]) && buildingDisabled[x, y];
                    data.constructionMaterialGrade[index] = ShouldSaveConstructionMaterialGrade(x, y) ? (int)constructionMaterialGrade[x, y] : (int)ConstructionMaterialGrade.Basic;
                    data.atmoSensorThreshold[index] = cells[x, y] == CellKind.AtmoSensor ? AtmoSensorThresholdAt(x, y) : AtmoSensorPressureThreshold;
                    data.thermoSensorThreshold[index] = cells[x, y] == CellKind.ThermoSensor ? ThermoSensorThresholdAt(x, y) : ThermoSensorTemperatureThreshold;
                    data.hydroSensorThreshold[index] = cells[x, y] == CellKind.HydroSensor ? HydroSensorThresholdAt(x, y) : HydroSensorLiquidThreshold;
                    data.germSensorThreshold[index] = cells[x, y] == CellKind.GermSensor ? GermSensorThresholdAt(x, y) : GermSensorThreshold;
                    data.weightPlateThreshold[index] = cells[x, y] == CellKind.WeightPlate ? WeightPlateThresholdAt(x, y) : WeightPlateThreshold;
                    data.critterSensorThreshold[index] = cells[x, y] == CellKind.CritterSensor ? CritterSensorThresholdAt(x, y) : CritterSensorThreshold;
                    data.atmoSensorCondition[index] = cells[x, y] == CellKind.AtmoSensor ? (int)ThresholdSensorConditionAt(x, y) : (int)ThresholdSensorCondition.AboveOrEqual;
                    data.thermoSensorCondition[index] = cells[x, y] == CellKind.ThermoSensor ? (int)ThresholdSensorConditionAt(x, y) : (int)ThresholdSensorCondition.AboveOrEqual;
                    data.hydroSensorCondition[index] = cells[x, y] == CellKind.HydroSensor ? (int)ThresholdSensorConditionAt(x, y) : (int)ThresholdSensorCondition.AboveOrEqual;
                    data.germSensorCondition[index] = cells[x, y] == CellKind.GermSensor ? (int)ThresholdSensorConditionAt(x, y) : (int)ThresholdSensorCondition.AboveOrEqual;
                    data.weightPlateCondition[index] = cells[x, y] == CellKind.WeightPlate ? (int)ThresholdSensorConditionAt(x, y) : (int)ThresholdSensorCondition.AboveOrEqual;
                    data.critterSensorCondition[index] = cells[x, y] == CellKind.CritterSensor ? (int)ThresholdSensorConditionAt(x, y) : (int)ThresholdSensorCondition.AboveOrEqual;
                    data.looseResourceKind[index] = (int)looseResourceKind[x, y];
                    data.looseResourceAmount[index] = looseResourceKind[x, y] == LooseResourceKind.None ? 0f : Mathf.Max(0f, looseResourceAmount[x, y]);
                    data.storageBinFilter[index] = cells[x, y] == CellKind.StorageBin ? (int)storageBinFilter[x, y] : 0;
                    data.storageSweepOnly[index] = cells[x, y] == CellKind.StorageBin && storageSweepOnly[x, y];
                    data.bedAssignedWorkerName[index] = IsBedKind(cells[x, y]) ? PersonalStationAssignedWorkerName(new Vector2Int(x, y)) : string.Empty;
                    data.messTableAssignedWorkerName[index] = cells[x, y] == CellKind.MessTable ? PersonalStationAssignedWorkerName(new Vector2Int(x, y)) : string.Empty;
                    data.medicalCotAssignedWorkerName[index] = cells[x, y] == CellKind.MedicalCot ? PersonalStationAssignedWorkerName(new Vector2Int(x, y)) : string.Empty;
                    data.conveyorLoaderFilter[index] = cells[x, y] == CellKind.ConveyorLoader ? (int)ConveyorLoaderFilterAt(x, y) : (int)StorageFilter.All;
                    data.conveyorReceptacleFilter[index] = cells[x, y] == CellKind.ConveyorReceptacle ? (int)ConveyorReceptacleFilterAt(x, y) : (int)StorageFilter.All;
                    data.shippingRailSensorFilter[index] = cells[x, y] == CellKind.ShippingRailSensor ? (int)ShippingRailSensorFilterAt(x, y) : (int)StorageFilter.All;
                    data.shippingRailMeterFlowLimit[index] = cells[x, y] == CellKind.ShippingRailMeter ? ShippingRailMeterFlowLimitAt(x, y) : ShippingRailMeterDefaultFlow;
                    data.powerWire[index] = powerWire[x, y];
                    data.powerWireKind[index] = powerWire[x, y] ? (int)powerWireKind[x, y] : (int)PowerWireKind.Normal;
                    data.smartBatteryLowThreshold[index] = cells[x, y] == CellKind.SmartBattery ? SmartBatteryLowThresholdAt(x, y) : SmartBatteryLowThreshold;
                    data.smartBatteryHighThreshold[index] = cells[x, y] == CellKind.SmartBattery ? SmartBatteryHighThresholdAt(x, y) : SmartBatteryHighThreshold;
                    data.smartBatterySignalState[index] = cells[x, y] == CellKind.SmartBattery && smartBatterySignalState[x, y];
                    data.generatorTuneUpSeconds[index] = IsTunableGenerator(cells[x, y]) ? Mathf.Max(0f, generatorTuneUpSeconds[x, y]) : 0f;
                    data.naturalVentAnalysisProgress[index] = IsNaturalVentKind(cells[x, y]) ? NaturalVentAnalysisProgress(new Vector2Int(x, y)) : 0f;
                    data.sculptingBlockFinished[index] = cells[x, y] == CellKind.SculptingBlock && sculptingBlockFinished[x, y];
                    data.automationWire[index] = automationWire[x, y];
                    data.automationSwitchState[index] = cells[x, y] == CellKind.SignalSwitch && automationSwitchState[x, y];
                    data.automationBufferHoldSeconds[index] = cells[x, y] == CellKind.AutomationBufferGate ? AutomationBufferHoldSecondsAt(x, y) : AutomationBufferHoldDefaultSeconds;
                    data.automationBufferRemainingSeconds[index] = cells[x, y] == CellKind.AutomationBufferGate ? Mathf.Clamp(automationBufferRemainingSeconds[x, y], 0f, AutomationBufferHoldSecondsAt(x, y)) : 0f;
                    data.automationFilterDelaySeconds[index] = cells[x, y] == CellKind.AutomationFilterGate ? AutomationFilterDelaySecondsAt(x, y) : AutomationFilterDelayDefaultSeconds;
                    data.automationFilterProgressSeconds[index] = cells[x, y] == CellKind.AutomationFilterGate ? Mathf.Clamp(automationFilterProgressSeconds[x, y], 0f, AutomationFilterDelaySecondsAt(x, y)) : 0f;
                    data.automationMemoryState[index] = cells[x, y] == CellKind.AutomationMemoryGate && automationMemoryState[x, y];
                    data.automationCycleSensorStart[index] = cells[x, y] == CellKind.AutomationCycleSensor ? CycleSensorStartAt(x, y) : AutomationCycleSensorDefaultStart;
                    data.automationCycleSensorEnd[index] = cells[x, y] == CellKind.AutomationCycleSensor ? CycleSensorEndAt(x, y) : AutomationCycleSensorDefaultEnd;
                    data.automationTimerGreenSeconds[index] = cells[x, y] == CellKind.AutomationTimerSensor ? AutomationTimerGreenSecondsAt(x, y) : AutomationTimerDefaultGreenSeconds;
                    data.automationTimerRedSeconds[index] = cells[x, y] == CellKind.AutomationTimerSensor ? AutomationTimerRedSecondsAt(x, y) : AutomationTimerDefaultRedSeconds;
                    data.automationTimerElapsedSeconds[index] = cells[x, y] == CellKind.AutomationTimerSensor ? AutomationTimerElapsedSecondsAt(x, y) : 0f;
                    data.airlockOpen[index] = (cells[x, y] == CellKind.ManualAirlock || cells[x, y] == CellKind.MechanizedAirlock) && airlockOpen[x, y];
                    data.doorAccessMode[index] = IsDoorAccessControlledKind(cells[x, y]) ? (int)DoorAccessModeAt(x, y) : (int)DoorAccessMode.Both;
                    data.bridgeDirection[index] = IsDirectionalBridge(cells[x, y]) ? (int)BridgeDirectionAt(x, y) : (int)BridgeDirection.Right;
                    data.shippingRail[index] = shippingRail[x, y];
                    data.shippingRailKind[index] = (int)shippingRailKind[x, y];
                    data.shippingRailAmount[index] = shippingRail[x, y] && shippingRailKind[x, y] != LooseResourceKind.None ? Mathf.Max(0f, shippingRailAmount[x, y]) : 0f;
                    data.liquidPipe[index] = liquidPipe[x, y];
                    data.liquidPipeKind[index] = liquidPipe[x, y] ? (int)liquidPipeKind[x, y] : (int)LiquidPipeKind.Normal;
                    data.liquidSensorMode[index] = cells[x, y] == CellKind.LiquidPipeSensor ? (int)liquidSensorMode[x, y] : (int)LiquidSensorMode.AnyLiquid;
                    data.liquidFilterMode[index] = cells[x, y] == CellKind.LiquidFilter ? (int)liquidFilterMode[x, y] : (int)LiquidFilterMode.PollutedWater;
                    data.liquidValveFlowLimit[index] = cells[x, y] == CellKind.LiquidValve ? LiquidValveFlowLimitAt(x, y) : LiquidValveMaxFlow;
                    data.pipeWater[index] = pipeWater[x, y];
                    data.pipeWaterGerms[index] = pipeWater[x, y] > 0.001f ? Mathf.Clamp01(pipeWaterGerms[x, y]) : 0f;
                    data.pipePollutedWater[index] = pipePollutedWater[x, y];
                    data.pipePollutedWaterGerms[index] = pipePollutedWater[x, y] > 0.001f ? Mathf.Clamp01(pipePollutedWaterGerms[x, y]) : 0f;
                    data.pipePetroleum[index] = pipePetroleum[x, y];
                    data.liquidReservoirWater[index] = liquidReservoirWater[x, y];
                    data.liquidReservoirWaterGerms[index] = liquidReservoirWater[x, y] > 0.001f ? Mathf.Clamp01(liquidReservoirWaterGerms[x, y]) : 0f;
                    data.liquidReservoirPollutedWater[index] = liquidReservoirPollutedWater[x, y];
                    data.liquidReservoirPollutedWaterGerms[index] = liquidReservoirPollutedWater[x, y] > 0.001f ? Mathf.Clamp01(liquidReservoirPollutedWaterGerms[x, y]) : 0f;
                    data.liquidReservoirPetroleum[index] = liquidReservoirPetroleum[x, y];
                    data.gasPipe[index] = gasPipe[x, y];
                    data.gasPipeKind[index] = gasPipe[x, y] ? (int)gasPipeKind[x, y] : (int)GasPipeKind.Normal;
                    data.gasSensorMode[index] = cells[x, y] == CellKind.GasPipeSensor ? (int)gasSensorMode[x, y] : (int)GasSensorMode.AnyGas;
                    data.gasFilterMode[index] = cells[x, y] == CellKind.GasFilter ? (int)gasFilterMode[x, y] : (int)GasFilterMode.CarbonDioxide;
                    data.gasValveFlowLimit[index] = cells[x, y] == CellKind.GasValve ? GasValveFlowLimitAt(x, y) : GasValveMaxFlow;
                    data.gasPipeOxygen[index] = gasPipeOxygen[x, y];
                    data.gasPipeCarbonDioxide[index] = gasPipeCarbonDioxide[x, y];
                    data.gasPipePollutedOxygen[index] = gasPipePollutedOxygen[x, y];
                    data.gasPipeHydrogen[index] = gasPipeHydrogen[x, y];
                    data.gasPipeSteam[index] = gasPipeSteam[x, y];
                    data.gasPipeChlorine[index] = gasPipeChlorine[x, y];
                    data.gasPipeNaturalGas[index] = gasPipeNaturalGas[x, y];
                    data.gasPipeSourGas[index] = gasPipeSourGas[x, y];
                    data.gasPipeGerms[index] = gasPipeGerms[x, y];
                    data.gasReservoirOxygen[index] = gasReservoirOxygen[x, y];
                    data.gasReservoirCarbonDioxide[index] = gasReservoirCarbonDioxide[x, y];
                    data.gasReservoirPollutedOxygen[index] = gasReservoirPollutedOxygen[x, y];
                    data.gasReservoirHydrogen[index] = gasReservoirHydrogen[x, y];
                    data.gasReservoirSteam[index] = gasReservoirSteam[x, y];
                    data.gasReservoirChlorine[index] = gasReservoirChlorine[x, y];
                    data.gasReservoirNaturalGas[index] = gasReservoirNaturalGas[x, y];
                    data.gasReservoirSourGas[index] = gasReservoirSourGas[x, y];
                    data.gasReservoirGerms[index] = gasReservoirGerms[x, y];
                }
            }

            for (int i = 0; i < workers.Count; i++)
            {
                Worker worker = workers[i];
                Vector2Int cell = WorldToCell(worker.Transform.position);
                data.workers[i] = new WorkerSave
                {
                    name = worker.Name,
                    cellX = cell.x,
                    cellY = cell.y,
                    positionX = worker.Transform.position.x,
                    positionY = worker.Transform.position.y,
                    calories = worker.Calories,
                    stress = worker.Stress,
                    health = worker.Health,
                    breath = worker.Breath,
                    morale = worker.Morale,
                    fatigue = worker.Fatigue,
                    bladder = worker.Bladder,
                    germExposure = worker.GermExposure,
                    sickness = worker.Sickness,
                    heatExposure = worker.HeatExposure,
                    chillExposure = worker.ChillExposure,
                    stressBreakSeconds = worker.StressBreakSeconds,
                    overjoyedSeconds = worker.OverjoyedSeconds,
                    overjoyedCooldownSeconds = worker.OverjoyedCooldownSeconds,
                    incapacitatedSeconds = worker.IncapacitatedSeconds,
                    experience = worker.Experience,
                    commuteSeconds = worker.CommuteSeconds,
                    narcolepticNapSeconds = worker.NarcolepticNapSeconds,
                    narcolepticCooldownSeconds = worker.NarcolepticCooldownSeconds,
                    flatulenceCooldownSeconds = worker.FlatulenceCooldownSeconds,
                    flatulenceGasProduced = worker.FlatulenceGasProduced,
                    soggyFeetSeconds = worker.SoggyFeetSeconds,
                    soppingWetSeconds = worker.SoppingWetSeconds,
                    yuckyLungsSeconds = worker.YuckyLungsSeconds,
                    poppedEardrumsSeconds = worker.PoppedEardrumsSeconds,
                    irritatedEyesSeconds = worker.IrritatedEyesSeconds,
                    scaldedSeconds = worker.ScaldedSeconds,
                    allergicReactionSeconds = worker.AllergicReactionSeconds,
                    suitFatigueSeconds = worker.SuitFatigueSeconds,
                    germyHandsSeconds = worker.GermyHandsSeconds,
                    foodSafeHandsSeconds = worker.FoodSafeHandsSeconds,
                    darkStressSeconds = worker.DarkStressSeconds,
                    brightSleepSeconds = worker.BrightSleepSeconds,
                    soreBackSeconds = worker.SoreBackSeconds,
                    exhaustedCollapseSeconds = worker.ExhaustedCollapseSeconds,
                    ateWithoutTableSeconds = worker.AteWithoutTableSeconds,
                    accidentShameSeconds = worker.AccidentShameSeconds,
                    nauseousSeconds = worker.NauseousSeconds,
                    trait = (int)worker.Trait,
                    interest = (int)worker.Interest,
                    role = (int)worker.Role,
                    scheduleOffsetSteps = NormalizeCrewScheduleOffset(worker.ScheduleOffsetSteps),
                    foodPolicyOverride = (int)worker.FoodPolicyOverride,
                    stressReaction = (int)worker.StressReaction,
                    overjoyedResponse = (int)worker.OverjoyedResponse,
                    disease = (int)worker.Disease,
                    suitEquipped = worker.SuitEquipped,
                    oxygenMaskEquipped = worker.OxygenMaskEquipped,
                    leadSuitEquipped = worker.LeadSuitEquipped,
                    outfit = (int)worker.Outfit
                };
            }

            for (int i = 0; i < hatches.Count; i++)
            {
                HatchCritter hatch = hatches[i];
                Vector2Int cell = hatch.Transform == null ? hatch.Cell : WorldToCell(hatch.Transform.position);
                Vector3 position = hatch.Transform == null ? CellCenter(cell) : hatch.Transform.position;
                data.hatches[i] = new HatchSave
                {
                    kind = (int)hatch.Kind,
                    name = hatch.Name,
                    cellX = cell.x,
                    cellY = cell.y,
                    positionX = position.x,
                    positionY = position.y,
                    moveTimer = hatch.MoveTimer,
                    eatTimer = hatch.EatTimer,
                    groomedSeconds = hatch.GroomedSeconds,
                    reproduction = hatch.Reproduction,
                    happiness = hatch.Happiness,
                    coalProduced = hatch.CoalProduced,
                    crudeOilProduced = hatch.CrudeOilProduced,
                    carbonDioxideConsumed = hatch.CarbonDioxideConsumed,
                    plasticProduced = hatch.PlasticProduced,
                    foodConsumed = hatch.FoodConsumed,
                    slimeProduced = hatch.SlimeProduced,
                    pollutedOxygenConsumed = hatch.PollutedOxygenConsumed,
                    pollutedOxygenProduced = hatch.PollutedOxygenProduced,
                    germsProduced = hatch.GermsProduced,
                    seafoodProduced = hatch.SeafoodProduced
                };
            }

            for (int i = 0; i < jobs.Count; i++)
            {
                Job job = jobs[i];
                data.jobs[i] = new JobSave
                {
                    type = (int)job.Type,
                    cellX = job.Cell.x,
                    cellY = job.Cell.y,
                    buildKind = (int)job.BuildKind,
                    workRequired = job.WorkRequired,
                    progress = job.Progress,
                    dirtCost = job.DirtCost,
                    metalCost = job.MetalCost,
                    algaeCost = job.AlgaeCost,
                    refinedMetalCost = job.RefinedMetalCost,
                    priority = job.Priority,
                    yellowAlert = job.YellowAlert,
                    ageSeconds = job.AgeSeconds,
                    autoGenerated = job.AutoGenerated,
                    targetWorkerName = job.TargetWorkerName,
                    targetCritterName = job.TargetCritterName,
                    buildWire = job.BuildWire,
                    powerWireKind = (int)job.PowerWireKind,
                    buildPipe = job.BuildPipe,
                    liquidPipeKind = (int)job.LiquidPipeKind,
                    buildGasPipe = job.BuildGasPipe,
                    gasPipeKind = (int)job.GasPipeKind,
                    buildShippingRail = job.BuildShippingRail,
                    removePowerWire = job.RemovePowerWire,
                    removeAutomationWire = job.RemoveAutomationWire,
                    removeLiquidPipe = job.RemoveLiquidPipe,
                    removeGasPipe = job.RemoveGasPipe,
                    removeShippingRail = job.RemoveShippingRail
                };
            }

            return data;
        }

