        private void RestorePrintingPodOffers(SaveData data)
        {
            ClearPrintingPodOffers();
            if (data == null || data.version < 78 || !data.printingPodOfferReady)
            {
                if (data != null && data.version < 78 && printingPodProgress >= 0.98f && CountCells(CellKind.PrintingPod) > 0)
                {
                    GeneratePrintingPodOffers(false);
                }

                return;
            }

            EnsurePrintingPodOfferArray();
            for (int i = 0; i < PrintingPodOfferCount; i++)
            {
                PrintingPodOfferKind kind = NormalizePrintingPodOfferKind(ReadSaveInt(data.printingPodOfferKinds, i, 0));
                float amount = Mathf.Max(0f, ReadSaveFloat(data.printingPodOfferAmounts, i, 0f));
                string workerName = data.printingPodOfferWorkerNames == null || i >= data.printingPodOfferWorkerNames.Length
                    ? string.Empty
                    : data.printingPodOfferWorkerNames[i];
                WorkerTrait trait = NormalizeWorkerTrait(ReadSaveInt(data.printingPodOfferTraits, i, 0));
                JobCategory interest = data.version >= 79
                    ? NormalizeJobCategory(ReadSaveInt(data.printingPodOfferInterests, i, (int)DefaultWorkerInterest(i)))
                    : DefaultWorkerInterest(i);
                printingPodOffers[i] = new PrintingPodOffer(kind, amount, workerName, trait, interest);
            }

            printingPodOfferReady = CountCells(CellKind.PrintingPod) > 0;
            printingPodProgress = printingPodOfferReady ? 1f : Mathf.Clamp01(printingPodProgress);
        }

        private PrintingPodOfferKind NormalizePrintingPodOfferKind(int kind)
        {
            int max = Enum.GetValues(typeof(PrintingPodOfferKind)).Length - 1;
            return (PrintingPodOfferKind)Mathf.Clamp(kind, 0, max);
        }

        private int[] CaptureJobCategoryPriorityAdjustments()
        {
            EnsureJobCategoryPolicy();
            int[] adjustments = new int[jobCategoryPriorityAdjustments.Length];
            Array.Copy(jobCategoryPriorityAdjustments, adjustments, adjustments.Length);
            return adjustments;
        }

        private void ApplyJobCategoryPriorityAdjustments(int[] savedAdjustments, int savedSelectedCategory)
        {
            EnsureJobCategoryPolicy();
            for (int i = 0; i < jobCategoryPriorityAdjustments.Length; i++)
            {
                int savedValue = savedAdjustments == null || i >= savedAdjustments.Length ? 0 : savedAdjustments[i];
                jobCategoryPriorityAdjustments[i] = NormalizeJobCategoryPolicyAdjustment((JobCategory)i, savedValue);
            }

            selectedJobCategory = (JobCategory)Mathf.Clamp(savedSelectedCategory, 0, jobCategoryPriorityAdjustments.Length - 1);
            InvalidateJobPolicyUi();
        }

        private void ApplySaveData(SaveData data)
        {
            EnsureWorkerRecords();
            int cellKindMax = Enum.GetValues(typeof(CellKind)).Length - 1;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    int index = Key(x, y);
                    int cellValue = Mathf.Clamp(data.cells[index], 0, cellKindMax);
                    cells[x, y] = (CellKind)cellValue;
                    oxygen[x, y] = ReadSaveFloat(data.oxygen, index, 0f);
                    carbonDioxide[x, y] = ReadSaveFloat(data.carbonDioxide, index, 0f);
                    pollutedOxygen[x, y] = ReadSaveFloat(data.pollutedOxygen, index, 0f);
                    hydrogen[x, y] = data.version >= 37 ? ReadSaveFloat(data.hydrogen, index, 0f) : 0f;
                    steam[x, y] = data.version >= 61 ? Mathf.Clamp(ReadSaveFloat(data.steam, index, 0f), 0f, 2.8f) : 0f;
                    chlorine[x, y] = data.version >= 67 ? Mathf.Clamp(ReadSaveFloat(data.chlorine, index, 0f), 0f, 2.8f) : 0f;
                    naturalGas[x, y] = data.version >= 68 ? Mathf.Clamp(ReadSaveFloat(data.naturalGas, index, 0f), 0f, 2.8f) : 0f;
                    sourGas[x, y] = data.version >= 250 ? Mathf.Clamp(ReadSaveFloat(data.sourGas, index, 0f), 0f, 2.8f) : 0f;
                    germs[x, y] = ReadSaveFloat(data.germs, index, cells[x, y] == CellKind.Slime ? 0.85f : 0f);
                    plantGrowth[x, y] = ReadSaveFloat(data.plantGrowth, index, 0f);
                    cropTendedSeconds[x, y] = data.version >= 46 && IsCropKind(cells[x, y]) ? Mathf.Max(0f, ReadSaveFloat(data.cropTendedSeconds, index, 0f)) : 0f;
                    cropStress[x, y] = data.version >= 60 && IsCropKind(cells[x, y]) ? Mathf.Max(0f, ReadSaveFloat(data.cropStress, index, 0f)) : 0f;
                    hatchEggAge[x, y] = data.version >= 86 ? Mathf.Max(0f, ReadSaveFloat(data.hatchEggAge, index, 0f)) : 0f;
                    incubatorEggLoaded[x, y] = data.version >= 87 && cells[x, y] == CellKind.Incubator && ReadSaveBool(data.incubatorEggLoaded, index, false);
                    incubatorEggProgress[x, y] = incubatorEggLoaded[x, y] ? Mathf.Clamp01(ReadSaveFloat(data.incubatorEggProgress, index, 0f)) : 0f;
                    waterMass[x, y] = ReadSaveFloat(data.waterMass, index, IsWorldLiquidCell(cells[x, y]) ? 80f : 0f);
                    temperature[x, y] = ReadSaveFloat(data.temperature, index, InitialTemperature(x, y, cells[x, y]));
                    bool migratedBatteryRepairState = data.version < 166 && (cells[x, y] == CellKind.Battery || cells[x, y] == CellKind.SmartBattery);
                    equipmentCondition[x, y] = IsRepairableEquipment(cells[x, y])
                        ? Mathf.Clamp01(data.version >= 34 && !migratedBatteryRepairState ? ReadSaveFloat(data.equipmentCondition, index, DefaultEquipmentCondition(cells[x, y])) : DefaultEquipmentCondition(cells[x, y]))
                        : 0f;
                    buildingDisabled[x, y] = data.version >= 276 && IsDisablableBuilding(cells[x, y]) && ReadSaveBool(data.buildingDisabled, index, false);
                    constructionMaterialGrade[x, y] = data.version >= 166 && ShouldSaveConstructionMaterialGrade(x, y)
                        ? NormalizeConstructionMaterialGrade(ReadSaveInt(data.constructionMaterialGrade, index, 0))
                        : DefaultConstructionMaterialGrade(cells[x, y]);
                    atmoSensorThreshold[x, y] = data.version >= 129 && cells[x, y] == CellKind.AtmoSensor ? Mathf.Clamp(ReadSaveFloat(data.atmoSensorThreshold, index, AtmoSensorPressureThreshold), AtmoSensorPressureMin, AtmoSensorPressureMax) : AtmoSensorPressureThreshold;
                    thermoSensorThreshold[x, y] = data.version >= 129 && cells[x, y] == CellKind.ThermoSensor ? Mathf.Clamp(ReadSaveFloat(data.thermoSensorThreshold, index, ThermoSensorTemperatureThreshold), ThermoSensorTemperatureMin, ThermoSensorTemperatureMax) : ThermoSensorTemperatureThreshold;
                    hydroSensorThreshold[x, y] = data.version >= 129 && cells[x, y] == CellKind.HydroSensor ? Mathf.Clamp(ReadSaveFloat(data.hydroSensorThreshold, index, HydroSensorLiquidThreshold), HydroSensorLiquidMin, HydroSensorLiquidMax) : HydroSensorLiquidThreshold;
                    germSensorThreshold[x, y] = data.version >= 140 && cells[x, y] == CellKind.GermSensor ? Mathf.Clamp(ReadSaveFloat(data.germSensorThreshold, index, GermSensorThreshold), GermSensorMin, GermSensorMax) : GermSensorThreshold;
                    weightPlateThreshold[x, y] = data.version >= 141 && cells[x, y] == CellKind.WeightPlate ? Mathf.Clamp(ReadSaveFloat(data.weightPlateThreshold, index, WeightPlateThreshold), WeightPlateMin, WeightPlateMax) : WeightPlateThreshold;
                    critterSensorThreshold[x, y] = data.version >= 142 && cells[x, y] == CellKind.CritterSensor ? Mathf.Clamp(ReadSaveFloat(data.critterSensorThreshold, index, CritterSensorThreshold), CritterSensorMin, CritterSensorMax) : CritterSensorThreshold;
                    atmoSensorCondition[x, y] = data.version >= 130 && cells[x, y] == CellKind.AtmoSensor ? NormalizeThresholdSensorCondition(ReadSaveInt(data.atmoSensorCondition, index, 0)) : ThresholdSensorCondition.AboveOrEqual;
                    thermoSensorCondition[x, y] = data.version >= 130 && cells[x, y] == CellKind.ThermoSensor ? NormalizeThresholdSensorCondition(ReadSaveInt(data.thermoSensorCondition, index, 0)) : ThresholdSensorCondition.AboveOrEqual;
                    hydroSensorCondition[x, y] = data.version >= 130 && cells[x, y] == CellKind.HydroSensor ? NormalizeThresholdSensorCondition(ReadSaveInt(data.hydroSensorCondition, index, 0)) : ThresholdSensorCondition.AboveOrEqual;
                    germSensorCondition[x, y] = data.version >= 140 && cells[x, y] == CellKind.GermSensor ? NormalizeThresholdSensorCondition(ReadSaveInt(data.germSensorCondition, index, 0)) : ThresholdSensorCondition.AboveOrEqual;
                    weightPlateCondition[x, y] = data.version >= 141 && cells[x, y] == CellKind.WeightPlate ? NormalizeThresholdSensorCondition(ReadSaveInt(data.weightPlateCondition, index, 0)) : ThresholdSensorCondition.AboveOrEqual;
                    critterSensorCondition[x, y] = data.version >= 142 && cells[x, y] == CellKind.CritterSensor ? NormalizeThresholdSensorCondition(ReadSaveInt(data.critterSensorCondition, index, 0)) : ThresholdSensorCondition.AboveOrEqual;
                    int looseMax = Enum.GetValues(typeof(LooseResourceKind)).Length - 1;
                    looseResourceKind[x, y] = data.version >= 36 ? (LooseResourceKind)Mathf.Clamp(ReadSaveInt(data.looseResourceKind, index, 0), 0, looseMax) : LooseResourceKind.None;
                    looseResourceAmount[x, y] = looseResourceKind[x, y] == LooseResourceKind.None ? 0f : Mathf.Max(0f, ReadSaveFloat(data.looseResourceAmount, index, 0f));
                    if (looseResourceKind[x, y] != LooseResourceKind.HatchEgg)
                    {
                        hatchEggAge[x, y] = 0f;
                    }

                    storageBinFilter[x, y] = data.version >= 85 && cells[x, y] == CellKind.StorageBin
                        ? NormalizeStorageFilter(ReadSaveInt(data.storageBinFilter, index, 0))
                        : StorageFilter.All;
                    storageSweepOnly[x, y] = data.version >= 85 && cells[x, y] == CellKind.StorageBin && ReadSaveBool(data.storageSweepOnly, index, false);
                    bedAssignedWorkerName[x, y] = data.version >= 280 && IsBedKind(cells[x, y])
                        ? ReadSaveString(data.bedAssignedWorkerName, index, string.Empty)
                        : string.Empty;
                    messTableAssignedWorkerName[x, y] = data.version >= 280 && cells[x, y] == CellKind.MessTable
