                        ? data.version >= 225 ? Mathf.Clamp(workerSave.flatulenceCooldownSeconds, 0f, FlatulentIntervalSeconds + FlatulentStaggerSeconds * 6f) : InitialFlatulenceCooldownSeconds(i, worker.Trait)
                        : 0f;
                    worker.FlatulenceGasProduced = worker.Trait == WorkerTrait.Flatulent && data.version >= 225 ? Mathf.Max(0f, workerSave.flatulenceGasProduced) : 0f;
                    worker.SoggyFeetSeconds = data.version >= 227 ? Mathf.Clamp(workerSave.soggyFeetSeconds, 0f, SoggyFeetDurationSeconds) : 0f;
                    worker.SoppingWetSeconds = data.version >= 230 ? Mathf.Clamp(workerSave.soppingWetSeconds, 0f, SoppingWetDurationSeconds) : 0f;
                    worker.YuckyLungsSeconds = data.version >= 228 ? Mathf.Clamp(workerSave.yuckyLungsSeconds, 0f, YuckyLungsDurationSeconds) : 0f;
                    worker.PoppedEardrumsSeconds = data.version >= 229 ? Mathf.Clamp(workerSave.poppedEardrumsSeconds, 0f, PoppedEardrumsDurationSeconds) : 0f;
                    worker.IrritatedEyesSeconds = data.version >= 231 ? Mathf.Clamp(workerSave.irritatedEyesSeconds, 0f, IrritatedEyesDurationSeconds) : 0f;
                    worker.ScaldedSeconds = data.version >= 233 ? Mathf.Clamp(workerSave.scaldedSeconds, 0f, ScaldedDurationSeconds) : 0f;
                    worker.AllergicReactionSeconds = data.version >= 234 ? Mathf.Clamp(workerSave.allergicReactionSeconds, 0f, AllergicReactionDurationSeconds) : 0f;
                    worker.SuitFatigueSeconds = data.version >= 236 ? Mathf.Clamp(workerSave.suitFatigueSeconds, 0f, SuitFatigueDurationSeconds) : 0f;
                    worker.GermyHandsSeconds = data.version >= 237 ? Mathf.Clamp(workerSave.germyHandsSeconds, 0f, GermyHandsDurationSeconds) : 0f;
                    worker.FoodSafeHandsSeconds = data.version >= 292 ? Mathf.Clamp(workerSave.foodSafeHandsSeconds, 0f, FoodSafeHandsDurationSeconds) : 0f;
                    if (worker.GermyHandsSeconds > 0f)
                    {
                        worker.FoodSafeHandsSeconds = 0f;
                    }

                    worker.DarkStressSeconds = data.version >= 238 ? Mathf.Clamp(workerSave.darkStressSeconds, 0f, DarkStressDurationSeconds) : 0f;
                    worker.BrightSleepSeconds = data.version >= 239 ? Mathf.Clamp(workerSave.brightSleepSeconds, 0f, BrightSleepDurationSeconds) : 0f;
                    worker.SoreBackSeconds = data.version >= 240 ? Mathf.Clamp(workerSave.soreBackSeconds, 0f, SoreBackDurationSeconds) : 0f;
                    worker.ExhaustedCollapseSeconds = data.version >= 241 ? Mathf.Clamp(workerSave.exhaustedCollapseSeconds, 0f, ExhaustedCollapseDurationSeconds) : 0f;
                    worker.AteWithoutTableSeconds = data.version >= 242 ? Mathf.Clamp(workerSave.ateWithoutTableSeconds, 0f, AteWithoutTableDurationSeconds) : 0f;
                    worker.AccidentShameSeconds = data.version >= 243 ? Mathf.Clamp(workerSave.accidentShameSeconds, 0f, AccidentShameDurationSeconds) : 0f;
                    worker.NauseousSeconds = data.version >= 244 ? Mathf.Clamp(workerSave.nauseousSeconds, 0f, NauseousDurationSeconds) : 0f;
                    worker.Interest = data.version >= 79 ? NormalizeJobCategory(workerSave.interest) : DefaultWorkerInterest(i);
                    worker.Role = data.version >= 80 ? NormalizeJobCategory(workerSave.role) : worker.Interest;
                    worker.ScheduleOffsetSteps = data.version >= 283 ? NormalizeCrewScheduleOffset(workerSave.scheduleOffsetSteps) : 0;
                    worker.FoodPolicyOverride = data.version >= 285 ? NormalizeWorkerFoodPolicyMode(workerSave.foodPolicyOverride) : WorkerFoodPolicyMode.Colony;
                    worker.StressReaction = data.version >= 81 ? NormalizeWorkerStressReaction(workerSave.stressReaction) : DefaultWorkerStressReaction(i);
                    worker.OverjoyedResponse = data.version >= 82 ? NormalizeWorkerOverjoyedResponse(workerSave.overjoyedResponse) : DefaultWorkerOverjoyedResponse(i);
                    worker.Disease = data.version >= 83 ? NormalizeWorkerDisease(workerSave.disease) : InferWorkerDisease(worker);
            worker.SuitEquipped = data.version >= 39 && workerSave.suitEquipped;
            worker.OxygenMaskEquipped = data.version >= 201 && workerSave.oxygenMaskEquipped && !worker.SuitEquipped;
            worker.LeadSuitEquipped = data.version >= 203 && workerSave.leadSuitEquipped && !worker.SuitEquipped;
            worker.Outfit = data.version >= 314 ? NormalizeWorkerOutfit(workerSave.outfit) : WorkerOutfit.None;
            worker.WorkSpeed = WorkerSkillSpeedMultiplier(worker);
                    worker.Activity = worker.Health <= 0f ? "Incapacitated" : worker.StressBreakSeconds > 0f ? StressReactionActivity(worker) : worker.ExhaustedCollapseSeconds > 0f ? "Exhausted Collapse" : worker.NarcolepticNapSeconds > 0f ? "Narcoleptic Nap" : "Idle";
                    if (!IsCharacterStandableCell(worker.Cell) && TryFindCharacterStandableCellNear(worker.Cell, 10, worker, out Vector2Int safeWorkerCell))
                    {
                        worker.Cell = safeWorkerCell;
                        if (worker.Transform != null)
                        {
                            worker.Transform.position = CellCenter(safeWorkerCell);
                        }
                    }
                }
            }

            RestorePrintingPodOffers(data);

            ClearHatches();
            if (data.version >= 43 && data.hatches != null)
            {
                for (int i = 0; i < data.hatches.Length && i < MaxWildHatches; i++)
                {
                    HatchSave hatchSave = data.hatches[i];
                    CritterKind kind = data.version >= 191
                        ? (CritterKind)Mathf.Clamp(hatchSave.kind, 0, Enum.GetValues(typeof(CritterKind)).Length - 1)
                        : CritterKind.Hatch;
                    Vector2Int cell = new Vector2Int(
                        Mathf.Clamp(hatchSave.cellX, 0, WorldWidth - 1),
                        Mathf.Clamp(hatchSave.cellY, 0, WorldHeight - 1));
                    if (!CanCritterMoveTo(kind, cell))
                    {
                        Vector2Int fallbackCell;
                        if (TryFindCritterSpawnCell(kind, cell, 6, out fallbackCell))
                        {
                            cell = fallbackCell;
                        }
                    }

                    HatchCritter hatch = SpawnCritter(
                        kind,
                        hatchSave.name,
                        cell,
                        hatchSave.happiness,
                        hatchSave.groomedSeconds,
                        hatchSave.moveTimer,
                        hatchSave.eatTimer,
                        data.version >= 86 ? hatchSave.reproduction : 0f,
                        hatchSave.coalProduced,
                        data.version >= 191 ? hatchSave.crudeOilProduced : 0f,
                        data.version >= 191 ? hatchSave.carbonDioxideConsumed : 0f,
                        data.version >= 192 ? hatchSave.plasticProduced : 0f,
                        data.version >= 192 ? hatchSave.foodConsumed : 0f,
                        data.version >= 193 ? hatchSave.slimeProduced : 0f,
                        data.version >= 193 ? hatchSave.pollutedOxygenConsumed : 0f,
                        data.version >= 195 ? hatchSave.pollutedOxygenProduced : 0f,
                        data.version >= 195 ? hatchSave.germsProduced : 0f,
                        data.version >= 196 ? hatchSave.seafoodProduced : 0f);
                    Vector3 position = new Vector3(hatchSave.positionX, hatchSave.positionY, 0f);
                    if (position.sqrMagnitude > 0.01f && hatch.Transform != null)
                    {
                        hatch.Transform.position = position;
                    }
                }

                if (data.version < 191 && CountCritters(CritterKind.Slickster) == 0)
                {
                    SeedSlicksters();
                }

                if (data.version < 192 && CountCritters(CritterKind.Drecko) == 0)
                {
                    SeedDreckos();
                }

                if (data.version < 193 && CountCritters(CritterKind.Puft) == 0)
                {
                    SeedPufts();
                }

                if (data.version < 195 && CountCritters(CritterKind.Morb) == 0)
                {
                    SeedMorbs();
                }

                if (data.version < 196 && CountCritters(CritterKind.Pacu) == 0)
                {
                    SeedPacus();
                }

                if (data.version < 197 && CountCritters(CritterKind.ShineBug) == 0)
                {
                    SeedShineBugs();
                }

                if (data.version < 316 && CountCritters(CritterKind.Pip) == 0)
                {
                    SeedPips();
                }

                if (data.version < 317 && CountCritters(CritterKind.PlugSlug) == 0)
                {
                    SeedPlugSlugs();
                }

                if (data.version < 318 && CountCritters(CritterKind.GassyMoo) == 0)
                {
                    SeedGassyMoos();
                }

                if (data.version < 319 && CountCritters(CritterKind.Beeta) == 0)
                {
                    SeedBeetas();
                }

                if (data.version < 320 && CountCritters(CritterKind.Grubgrub) == 0)
                {
                    SeedGrubgrubs();
                }

                if (data.version < 321 && CountCritters(CritterKind.CuddlePip) == 0)
                {
                    SeedCuddlePips();
                }

                if (data.version < 322 && CountCritters(CritterKind.ShoveVole) == 0)
                {
                    EnsureSurfaceRegolithPatches();
                    SeedShoveVoles();
                }

                if (data.version < 323 && CountCritters(CritterKind.MoltenSlickster) == 0)
                {
                    SeedMoltenSlicksters();
                }

                if (data.version < 324 && CountCritters(CritterKind.Sweetle) == 0)
                {
                    EnsureSulfurPatches();
                    SeedSweetles();
                }
            }
            else
            {
                SeedHatches();
            }

            if (data.version < 325 && CountCells(CellKind.GrubfruitPlant) == 0)
            {
                EnsureSulfurPatches();
                SeedGrubfruitPlants();
            }

            if (data.version < 326 && CountCells(CellKind.ThimbleReed) == 0)
            {
                if (CountCells(CellKind.PollutedWater) == 0)
                {
                    SeedPollutedWaterPockets();
                }

                SeedThimbleReeds();
            }

            if (data.version < 327 && CountCells(CellKind.SleetWheat) == 0)
            {
                SeedSleetWheat();
            }

            jobs.Clear();
            if (data.jobs != null)
            {
                int jobTypeMax = Enum.GetValues(typeof(JobType)).Length - 1;
                for (int i = 0; i < data.jobs.Length; i++)
                {
                    JobSave jobSave = data.jobs[i];
                    Vector2Int cell = new Vector2Int(jobSave.cellX, jobSave.cellY);
                    if (!IsInside(cell.x, cell.y))
                    {
                        continue;
                    }

                    Job job = new Job((JobType)Mathf.Clamp(jobSave.type, 0, jobTypeMax), cell, jobSave.workRequired)
                    {
                        BuildKind = (CellKind)Mathf.Clamp(jobSave.buildKind, 0, cellKindMax),
                        Progress = Mathf.Max(0f, jobSave.progress),
                        DirtCost = jobSave.dirtCost,
                        MetalCost = jobSave.metalCost,
                        AlgaeCost = jobSave.algaeCost,
                        RefinedMetalCost = data.version >= 28 ? jobSave.refinedMetalCost : 0f,
                        Priority = jobSave.priority > 0 ? jobSave.priority : DefaultPriority((JobType)Mathf.Clamp(jobSave.type, 0, jobTypeMax)),
                        YellowAlert = data.version >= 160 && jobSave.yellowAlert,
                        AgeSeconds = data.version >= 74 ? Mathf.Clamp(jobSave.ageSeconds, 0f, JobAgingMaxSeconds) : 0f,
                        AutoGenerated = jobSave.autoGenerated,
                        TargetWorkerName = jobSave.targetWorkerName,
                        TargetCritterName = data.version >= 278 ? jobSave.targetCritterName : string.Empty,
                        BuildWire = jobSave.buildWire,
                        PowerWireKind = data.version >= 117 ? NormalizePowerWireKind(jobSave.powerWireKind) : PowerWireKind.Normal,
                        BuildPipe = jobSave.buildPipe,
                        LiquidPipeKind = data.version >= 110 ? NormalizeLiquidPipeKind(jobSave.liquidPipeKind) : LiquidPipeKind.Normal,
                        BuildGasPipe = jobSave.buildGasPipe,
                        GasPipeKind = data.version >= 247 ? NormalizeGasPipeKind(jobSave.gasPipeKind) : GasPipeKind.Normal,
                        BuildShippingRail = data.version >= 48 && jobSave.buildShippingRail,
                        RemovePowerWire = data.version >= 31 && jobSave.removePowerWire,
                        RemoveAutomationWire = data.version >= 31 && jobSave.removeAutomationWire,
                        RemoveLiquidPipe = data.version >= 31 && jobSave.removeLiquidPipe,
                        RemoveGasPipe = data.version >= 31 && jobSave.removeGasPipe,
                        RemoveShippingRail = data.version >= 48 && jobSave.removeShippingRail
                    };
                    jobs.Add(job);
                }
            }

            int modeMax = Enum.GetValues(typeof(CommandMode)).Length - 1;
            int savedCommandMode = data.currentMode;
            if (data.version < 276 && savedCommandMode >= (int)CommandMode.ToggleBuildingEnabled)
            {
                savedCommandMode++;
            }

            if (data.version < 277 && savedCommandMode >= (int)CommandMode.CopySettings)
            {
                savedCommandMode++;
            }

            currentMode = (CommandMode)Mathf.Clamp(savedCommandMode, 0, modeMax);
            copiedSettingsAvailable = false;
            if (!string.IsNullOrEmpty(data.language) && Enum.TryParse(data.language, out ProjectONLanguage savedLanguage))
            {
                currentLanguage = savedLanguage;
            }

            RefreshLocalizedStaticTexts();
            RefreshRedAlertButtonLabel();
            RefreshMedicalLeaveButtonLabel();
            SetMode(currentMode);
            int overlayModeMax = Enum.GetValues(typeof(OverlayMode)).Length - 1;
            currentOverlayMode = (OverlayMode)Mathf.Clamp(data.currentOverlayMode, 0, overlayModeMax);
            SetOverlayMode(currentOverlayMode);
            inspectedCell = null;
            lastLog = string.IsNullOrEmpty(data.lastLog) ? "Game loaded." : data.lastLog;
            UpdatePoweredWires();
            UpdateAutomationWires();
            terrainDirty = true;
            gasDirty = true;
            overlayDirty = true;
            ResetCycleReports();
            UpdateColonyStatus(true);
        }

        private float ReadSaveFloat(float[] values, int index, float fallback)
        {
            return values == null || index < 0 || index >= values.Length ? fallback : values[index];
        }

        private int ReadSaveInt(int[] values, int index, int fallback)
        {
            return values == null || index < 0 || index >= values.Length ? fallback : values[index];
        }

        private bool ReadSaveBool(bool[] values, int index, bool fallback)
        {
            return values == null || index < 0 || index >= values.Length ? fallback : values[index];
        }

        private string ReadSaveString(string[] values, int index, string fallback)
        {
            if (values == null || index < 0 || index >= values.Length)
            {
                return fallback;
            }

            return string.IsNullOrEmpty(values[index]) ? fallback : values[index];
        }

        private void UpdateHudThrottled()
        {
            float now = Time.unscaledTime;
            if (now < nextHudRefreshTime)
            {
                return;
            }

            UpdateHud();
        }

        private void UpdateHud()
        {
            if (!hudElementsBound && !TryBindHudElements())
            {
                return;
            }

            if (statsText == null)
            {
                return;
            }

            nextHudRefreshTime = Time.unscaledTime + HudRefreshIntervalSeconds;
            RefreshModeButtonLabels();

            float averageOxygen = AverageGas(oxygen);
            float averageCo2 = AverageGas(carbonDioxide);
            float averageTemperature = AverageTemperature();
            int openJobs = 0;
            int assignedJobs = 0;
            foreach (Job job in jobs)
            {
                if (job.AssignedWorker == null)
                {
                    openJobs++;
                }
                else
                {
                    assignedJobs++;
                }
            }

            string hudText = BuildTopStatusText(averageOxygen, averageCo2, averageTemperature, assignedJobs, openJobs);
            float unscaledNow = Time.unscaledTime;
            SetLocalizedText(statsText, hudText);
            SetLocalizedText(modeText, BuildModeStatusText());
            if (scenarioText != null)
            {
                SetLocalizedText(scenarioText, BuildScenarioText());
            }

            if (jobQueueText != null)
            {
                if (unscaledNow >= nextJobQueueRefreshTime || renderedJobQueueLanguage != currentLanguage || string.IsNullOrEmpty(jobQueueTextCache))
                {
                    jobQueueTextCache = Localize(BuildJobQueueText(assignedJobs, openJobs));
                    renderedJobQueueLanguage = currentLanguage;
                    nextJobQueueRefreshTime = unscaledNow + JobQueueRefreshIntervalSeconds;
                }

                SetTextIfChanged(jobQueueText, jobQueueTextCache);
            }

            if (jobPolicyText != null)
            {
                SetLocalizedText(jobPolicyText, BuildJobPolicyText());
            }

            if (crewVitalsText != null)
            {
                SetLocalizedText(crewVitalsText, BuildCrewVitalsText());
            }
            RefreshCrewScheduleButtonLabel();
            RefreshCrewFoodPolicyButtonLabel();

            if (colonyForecastText != null)
            {
                if (unscaledNow >= nextColonyForecastRefreshTime || renderedColonyForecastLanguage != currentLanguage || string.IsNullOrEmpty(colonyForecastTextCache))
                {
                    colonyForecastTextCache = Localize(BuildColonyForecastText(averageOxygen, averageCo2, averageTemperature, assignedJobs, openJobs));
                    renderedColonyForecastLanguage = currentLanguage;
                    nextColonyForecastRefreshTime = unscaledNow + ColonyForecastRefreshIntervalSeconds;
                }

                SetTextIfChanged(colonyForecastText, colonyForecastTextCache);
            }

            UpdatePrintingPodOfferHud();
            RefreshRedAlertButtonLabel();
            RefreshFoodPolicyButtonLabel();
            RefreshMedicalLeaveButtonLabel();

            UpdateOverlayLegend();
            SetLocalizedText(logText, lastLog);
            SetLocalizedText(infoText, BuildInspectText());
            UpdateInspectControls();
            UpdateEndStatePanel();
            UpdateStartStatePanel();
        }

        private void UpdatePrintingPodOfferHud()
        {
            if (printingPodOfferPanel == null)
            {
                return;
            }

            bool visible = printingPodOfferReady && CountCells(CellKind.PrintingPod) > 0;
            SetVisible(printingPodOfferPanel, visible);
            if (!visible)
            {
                return;
            }

            if (printingPodOfferText != null)
            {
                SetLocalizedText(printingPodOfferText, BuildPrintingPodOfferText());
            }

            UpdatePrintingPodOfferButton(printingPodOfferButton0, 0);
            UpdatePrintingPodOfferButton(printingPodOfferButton1, 1);
            UpdatePrintingPodOfferButton(printingPodOfferButton2, 2);
        }

        private void UpdatePrintingPodOfferButton(Button button, int optionIndex)
        {
            if (button == null)
            {
                return;
            }

            SetLocalizedText(button, BuildPrintingPodOfferButtonText(optionIndex));
            button.SetEnabled(CanClaimPrintingPodOffer(optionIndex));
        }

        private void UpdateOverlayLegend()
        {
            if (overlayLegendRows == null || overlayLegendTitleText == null)
            {
                return;
            }

            if (renderedLegendOverlayMode == currentOverlayMode && renderedLegendLanguage == currentLanguage)
            {
                return;
            }

            renderedLegendOverlayMode = currentOverlayMode;
            renderedLegendLanguage = currentLanguage;
            overlayLegendRows.Clear();
            overlayLegendTitleText.text = Localize("Legend: " + OverlayName(currentOverlayMode));

            switch (currentOverlayMode)
            {
                case OverlayMode.Temperature:
                    AddOverlayLegendRow(new Color(0.18f, 0.58f, 1f, 0.90f), "Cold");
                    AddOverlayLegendRow(new Color(0.20f, 1f, 0.55f, 0.45f), "Comfort");
                    AddOverlayLegendRow(new Color(1f, 0.16f, 0.04f, 0.90f), "Hot");
                    AddOverlayLegendRow(new Color(1f, 0.72f, 0.20f, 0.90f), "Steam risk");
                    break;
                case OverlayMode.Materials:
                    AddOverlayLegendRow(new Color(0.58f, 0.38f, 0.18f, 0.85f), "Diggable earth");
                    AddOverlayLegendRow(new Color(0.44f, 0.70f, 0.82f, 0.85f), "Metal ore");
                    AddOverlayLegendRow(new Color(0.34f, 0.82f, 0.30f, 0.85f), "Organics");
                    AddOverlayLegendRow(new Color(0.24f, 0.24f, 0.22f, 0.85f), "Fuel material");
                    AddOverlayLegendRow(new Color(0.12f, 0.48f, 1f, 0.85f), "Liquid resource");
                    AddOverlayLegendRow(new Color(0.96f, 0.78f, 0.32f, 0.85f), "Loose debris");
                    AddOverlayLegendRow(new Color(0.76f, 0.78f, 0.82f, 0.85f), "Storage accepts");
