                    AddOverlayLegendRow(new Color(0.74f, 1f, 0.20f, 0.85f), "Sterile food storage");
                    AddOverlayLegendRow(new Color(1f, 0.76f, 0.24f, 0.85f), "Fresh food storage");
                    AddOverlayLegendRow(new Color(1f, 0.56f, 0.14f, 0.85f), "Stale or contaminated");
