                    AddOverlayLegendRow(new Color(1f, 0.36f, 0.12f, 0.90f), "Critical priority");
                    AddOverlayLegendRow(new Color(1f, 0.64f, 0.18f, 0.85f), "High priority");
                    AddOverlayLegendRow(new Color(0.36f, 1f, 0.42f, 0.75f), "Normal priority");
                    AddOverlayLegendRow(new Color(0.48f, 0.54f, 0.62f, 0.65f), "Low priority");
                    AddOverlayLegendRow(new Color(0.22f, 0.88f, 1f, 0.85f), "Assigned errand");
                    AddOverlayLegendRow(new Color(1f, 0.12f, 0.10f, 0.90f), "Invalid errand");
                    AddOverlayLegendRow(new Color(0.62f, 0.68f, 0.74f, 0.75f), "Idle duplicant");
                    break;
                case OverlayMode.Power:
                    AddOverlayLegendRow(new Color(1f, 0.86f, 0.18f, 0.90f), "Powered wire");
                    AddOverlayLegendRow(new Color(0.52f, 0.30f, 0.08f, 0.90f), "Unpowered wire");
                    AddOverlayLegendRow(new Color(1f, 0.96f, 0.42f, 0.90f), "Conductive wire");
                    AddOverlayLegendRow(new Color(0.96f, 0.62f, 0.18f, 0.90f), "Heavy-watt wire");
                    AddOverlayLegendRow(new Color(1f, 0.88f, 0.22f, 0.85f), "Power bridge");
                    AddOverlayLegendRow(new Color(1f, 0.78f, 0.18f, 0.85f), "Power shutoff connected");
                    AddOverlayLegendRow(new Color(1f, 0.18f, 0.10f, 0.85f), "Power shutoff disconnected");
                    AddOverlayLegendRow(new Color(1f, 0.14f, 0.04f, 0.95f), "Overload");
                    AddOverlayLegendRow(new Color(0.35f, 1f, 0.44f, 0.80f), "Machine running");
                    AddOverlayLegendRow(new Color(0.28f, 1f, 0.32f, 0.85f), "Automation green");
                    AddOverlayLegendRow(new Color(1f, 0.18f, 0.10f, 0.85f), "Automation red");
                    AddOverlayLegendRow(new Color(0.60f, 0.44f, 1f, 0.75f), "Automation bridge");
                    AddOverlayLegendRow(new Color(1f, 0.42f, 0.86f, 0.75f), "Automation NOT");
                    break;
                case OverlayMode.Automation:
