        private void AddOverlayLegendRow(Color color, string label)
        {
            VisualElement row = new VisualElement();
            row.AddToClassList("overlay-legend-row");

            VisualElement swatch = new VisualElement();
            swatch.AddToClassList("overlay-legend-swatch");
            swatch.style.backgroundColor = new StyleColor(color);
            row.Add(swatch);

            Label text = new Label(Localize(label));
            text.AddToClassList("overlay-legend-label");
            ApplyRuntimeFont(text);
            row.Add(text);

            overlayLegendRows.Add(row);
        }

        private void UpdateEndStatePanel()
        {
            if (endStatePanel == null)
            {
                return;
            }

            bool showFailure = colonyFailed;
            bool showVictory = colonyVictory && !colonyVictoryAcknowledged;
            bool showPanel = showFailure || showVictory;
            SetVisible(endStatePanel, showPanel);
            if (!showPanel)
            {
                return;
            }

            if (showFailure)
            {
                SetLocalizedText(endStateTitleText, "Colony failed");
                SetLocalizedText(endStateBodyText, BuildFailureSummaryText());
                SetVisible(endStateLoadButton, true);
                SetVisible(endStateNewRunButton, true);
                SetVisible(endStateContinueButton, false);
            }
            else
            {
                SetLocalizedText(endStateTitleText, "Colony Charter complete");
                SetLocalizedText(endStateBodyText, BuildVictorySummaryText());
                SetVisible(endStateLoadButton, true);
                SetVisible(endStateNewRunButton, true);
                SetVisible(endStateContinueButton, true);
            }
        }

        private void UpdateStartStatePanel()
        {
            if (startStatePanel == null)
            {
                return;
            }

            SetVisible(startStatePanel, startStateVisible);
            if (!startStateVisible)
            {
                return;
            }

            SetLocalizedText(startStateTitleText, "Project ON: Colony Charter");
            SetLocalizedText(startStateBodyText, BuildStartStateBodyText());
            SetVisible(startStateBeginButton, true);
            SetVisible(startStateLoadButton, true);
            SetVisible(startStateContinueButton, true);
        }

        private string BuildStartStateBodyText()
        {
            StringBuilder builder = new StringBuilder();
            builder.AppendLine("Complete the 122-step asteroid charter: oxygen, food, power, heat, disease, automation, industry, rockets, radiation, and the temporal tear chain.");
            builder.Append("Start a fresh colony, load the last save, or continue the generated run already waiting behind this briefing.");
            builder.AppendLine();
            builder.Append(File.Exists(SaveFilePath) ? "Save detected." : "No save detected.");
            builder.Append("  First goal: ");
            builder.Append(objectiveText);
            return builder.ToString();
        }

        private string BuildFailureSummaryText()
        {
            int completed = CountCompletedScenarioMilestones();
            StringBuilder builder = new StringBuilder();
            builder.Append("Charter run failed on cycle ");
            builder.Append(cycle);
            builder.Append(". Progress ");
            builder.Append(completed);
            builder.Append("/");
            builder.Append(ScenarioMilestoneTotal);
            builder.AppendLine(".");
            builder.Append("Reason: ");
            builder.Append(FailureReasonText());
            builder.AppendLine();
            builder.Append("Load Save or start a New Run.");
            return builder.ToString();
        }

        private string BuildVictorySummaryText()
        {
            StringBuilder builder = new StringBuilder();
            builder.Append("Charter completed on cycle ");
            builder.Append(cycle);
            builder.Append(". Crew alive ");
            builder.Append(CountActiveWorkers());
            builder.Append("/");
            builder.Append(workers.Count);
            builder.AppendLine(".");
            builder.Append("Food ");
            builder.Append(food.ToString("0"));
            builder.Append("  Water ");
            builder.Append(water.ToString("0"));
            builder.Append("  Power ");
            builder.Append(power.ToString("0"));
            builder.Append("/");
            builder.Append(maxPower.ToString("0"));
            builder.AppendLine(".");
            builder.Append("Freeplay is unlocked. Expand, optimize, or start a fresh asteroid.");
            return builder.ToString();
        }

        private string FailureReasonText()
        {
            const string failurePrefix = "Colony failed: ";
            if (!string.IsNullOrEmpty(lastLog) && lastLog.StartsWith(failurePrefix, StringComparison.Ordinal))
            {
                return lastLog.Substring(failurePrefix.Length);
            }

            return "All duplicants are incapacitated.";
        }

        private string BuildTopStatusText(float averageOxygen, float averageCo2, float averageTemperature, int assignedJobs, int openJobs)
        {
            UpdateCycleReportBalances();

            StringBuilder builder = new StringBuilder();
            builder.Append("Cycle ");
            builder.Append(cycle);
            builder.Append("  ");
            builder.Append(paused ? "PAUSED" : "x" + simulationSpeed.ToString("0"));
            if (redAlertActive)
            {
                builder.Append("  RED ALERT");
            }

            builder.Append("  Schedule ");
            builder.Append(ScheduleLabel());
            builder.Append("    O2 ");
            builder.Append(averageOxygen.ToString("0.00"));
            builder.Append("  CO2 ");
            builder.Append(averageCo2.ToString("0.00"));
            builder.Append("  Temp ");
            builder.Append(averageTemperature.ToString("0"));
            builder.Append("C  Power ");
            builder.Append(power.ToString("0"));
            builder.Append("/");
            builder.Append(maxPower.ToString("0"));
            builder.Append("  Print ");
            builder.Append(printingPodOfferReady ? "READY" : Mathf.RoundToInt(printingPodProgress * 100f) + "%");
            builder.AppendLine();
            builder.Append("Food ");
            builder.Append(food.ToString("0"));
            builder.Append(" ");
            builder.Append(foodPolicyMode == FoodPolicyMode.Safe ? "SAFE" : "ALL");
            if (foodPolicyMode == FoodPolicyMode.Safe && (foodGerms >= FoodGermExposureThreshold || foodFreshness <= SpoiledFoodRotFreshnessThreshold))
            {
                builder.Append("/BLOCK");
            }

            builder.Append("  Water ");
            builder.Append(water.ToString("0"));
            AppendCycleNetSummary(builder, currentCycleReport);
            builder.Append("  Algae ");
            builder.Append(algae.ToString("0"));
            builder.Append("  Metal ");
            builder.Append(metal.ToString("0"));
            builder.Append("/");
            builder.Append(refinedMetal.ToString("0"));
            builder.Append("/");
            builder.Append(steel.ToString("0"));
            builder.Append("  Research ");
            builder.Append(researchPoints.ToString("0"));
            builder.Append("  Morale ");
            builder.Append(AverageWorkerMorale().ToString("0.0"));
            builder.Append("  Stress ");
            builder.Append(HighestStress().ToString("0"));
            builder.Append("%");
            float lowestBreath = LowestWorkerBreath();
            if (lowestBreath < 70f)
            {
                builder.Append("  Breath ");
                builder.Append(lowestBreath.ToString("0"));
                builder.Append("%");
            }

            builder.Append("  Jobs ");
            builder.Append(assignedJobs);
            builder.Append("/");
            builder.Append(jobs.Count);
            builder.Append(" (");
            builder.Append(openJobs);
            builder.Append(" open)  Alert: ");
            if (unreachableJobCount > 0)
            {
                builder.Append("Blocked ");
                builder.Append(unreachableJobCount);
                builder.Append("  ");
            }

            builder.Append(CompactAlertText(alertText, 3));
            return builder.ToString();
        }

        private string BuildModeStatusText()
        {
            StringBuilder builder = new StringBuilder();
            builder.Append("Mode: ");
            builder.Append(ModeName(currentMode));
            builder.Append("    Overlay: ");
            builder.Append(OverlayName(currentOverlayMode));
            builder.AppendLine();
            builder.Append("Rooms: ");
            builder.Append(RoomSummary());
            builder.Append("    Tech: ");
            builder.Append(TechSummary());
            builder.AppendLine();
            builder.Append("Workers: ");
            builder.Append(CountActiveWorkers());
            builder.Append("/");
            builder.Append(workers.Count);
            if (redAlertActive)
            {
                builder.Append("  Red Alert ");
                builder.Append(redAlertSeconds.ToString("0"));
                builder.Append("s");
            }

            int incapacitated = CountIncapacitatedWorkers();
            if (incapacitated > 0)
            {
                builder.Append("  Down ");
                builder.Append(incapacitated);
            }

            int lowMorale = CountLowMoraleWorkers();
            if (lowMorale > 0)
            {
                builder.Append("  Low morale ");
                builder.Append(lowMorale);
            }

            string buildReservation = QueuedBuildReservationText();
            if (!string.IsNullOrEmpty(buildReservation))
            {
                builder.AppendLine();
                builder.Append(buildReservation);
            }

            return builder.ToString();
        }

        private string BuildScenarioText()
        {
            int completed = CountCompletedScenarioMilestones();
            int percent = Mathf.RoundToInt(completed * 100f / ScenarioMilestoneTotal);
            StringBuilder builder = new StringBuilder();
            if (colonyFailed)
            {
                builder.Append("Scenario: Colony failed");
            }
            else if (colonyVictory)
            {
                builder.Append("Scenario: Colony Charter complete");
            }
            else
            {
                builder.Append("Scenario: Colony Charter");
            }

            builder.Append("  ");
            builder.Append(completed);
            builder.Append("/");
            builder.Append(ScenarioMilestoneTotal);
            builder.Append(" (");
            builder.Append(percent);
            builder.AppendLine("%)");
            builder.AppendLine("Phase: " + ScenarioPhaseName(completed) + " - " + ScenarioPhaseGoal(completed));
            builder.AppendLine("Next: " + objectiveText);
            AppendCharterFocusLine(builder);
            builder.Append("Critical: ");
            builder.Append(CompactAlertText(alertText, 4));
            return builder.ToString();
        }

        private string ScenarioPhaseName(int completedMilestones)
        {
            if (colonyVictory)
            {
                return "Freeplay";
            }

            if (completedMilestones < 12)
            {
                return "Survival";
            }

            if (completedMilestones < 24)
            {
                return "Base Systems";
            }

            if (completedMilestones < 36)
            {
                return "Industry";
            }

            if (completedMilestones < 47)
            {
                return "Automation";
            }

            return "Surface & Space";
        }

        private string ScenarioPhaseGoal(int completedMilestones)
        {
            if (colonyVictory)
            {
                return "Expand, optimize, and survive indefinitely.";
            }

            if (completedMilestones < 12)
            {
                return "Beds, toilets, oxygen, food, and water.";
            }

            if (completedMilestones < 24)
            {
                return "Research, rooms, morale, power, and storage.";
            }

            if (completedMilestones < 36)
            {
                return "Pipes, vents, suits, refining, and backup power.";
            }

            if (completedMilestones < 47)
            {
                return "Sensors, sweepers, shipping, ranching, and vents.";
            }

            return "Advanced industry, renewable vents, surface defense, rockets, radiation, temporal tear, and the final charter.";
        }

        private void AppendCharterFocusLine(StringBuilder builder)
        {
            int shown = 0;
            AppendCharterFocus(builder, "survival", milestoneBasicShelter && milestoneSanitation && milestoneHygiene && milestoneStableOxygen && milestoneFoodProduction, ref shown);
            AppendCharterFocus(builder, "base systems", milestoneResearchProgram && milestonePowerGrid && milestoneRoomPlanning && milestoneFoodStorage && milestoneMaterialStorage, ref shown);
            AppendCharterFocus(builder, "utilities", milestonePlumbing && milestoneVentilation && milestoneReservoirBuffering && milestoneAdvancedAtmosphere && milestoneWaterRecycling, ref shown);
            AppendCharterFocus(builder, "automation", milestoneAutomation && milestoneSignalSwitching && milestoneConduitAutomation && milestoneAutoSweeping && milestoneShippingLogistics, ref shown);
            AppendCharterFocus(builder, "industry", milestoneMetalRefinery && milestoneSteelProduction && milestoneCeramicInsulation && milestoneOilWell && milestoneSourGasProcessing, ref shown);
            AppendCharterFocus(builder, "renewables", milestoneRenewableVents && milestoneVentAnalysis && milestoneSteamVentTaming && milestoneWaterGeyserTaming && milestoneHydrogenVentTaming && milestoneNaturalGasVentTaming, ref shown);
            AppendCharterFocus(builder, "surface", milestoneSolarPower && milestoneMeteorShielding && milestoneSurfaceRecovery && milestoneSpaceScanning && milestoneAutomatedMeteorDefense, ref shown);
            AppendCharterFocus(builder, "space", milestoneOrbitalMission && milestoneOrbitalDataAnalysis && milestoneDeepSpaceSurvey && milestoneCryogenicRocketProgram && milestoneTemporalTearSignal, ref shown);
            AppendCharterFocus(builder, "radiation", milestoneLeadSuits && milestoneRadiationContainment && milestoneRadiationResearch && milestoneRadboltHarnessing && milestoneNuclearPower, ref shown);
            AppendCharterFocus(builder, "final charter", milestoneSustainableOperations && milestoneColonyMonument && milestoneThermiumMachinery && milestoneSuperCoolantLoop && colonyVictory, ref shown);

            if (shown == 0)
            {
                builder.AppendLine("Focus: freeplay expansion, redundancy, and performance tuning");
            }
            else if (shown < 4)
            {
                builder.AppendLine();
            }
        }

        private void AppendCharterFocus(StringBuilder builder, string label, bool complete, ref int shown)
        {
            if (complete || shown >= 4)
            {
                return;
            }

            if (shown == 0)
            {
                builder.Append("Focus: ");
            }
            else
            {
                builder.Append(" | ");
            }

            builder.Append(label);
            shown++;
            if (shown == 4)
            {
                builder.AppendLine();
            }
        }

        private string CompactAlertText(string alerts, int maxAlerts)
        {
            if (string.IsNullOrEmpty(alerts))
            {
                return "Stable.";
            }

            string[] alertParts = alerts.Split(new[] { ", " }, StringSplitOptions.None);
            if (alertParts.Length <= maxAlerts)
            {
                return alerts;
            }

            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < maxAlerts; i++)
            {
                if (i > 0)
                {
                    builder.Append(", ");
                }

                builder.Append(alertParts[i]);
            }

            builder.Append(", +");
            builder.Append(alertParts.Length - maxAlerts);
            builder.Append(" more");
            return builder.ToString();
        }

