        private void GrantCharterMilestoneRewards(int previousCount, int nextCount)
        {
            int completed = Mathf.Max(0, nextCount - previousCount);
            if (completed <= 0)
            {
                return;
            }

            float foodReward = workers.Count * 35f * completed;
            float waterReward = 2.5f * completed;
            float dirtReward = 5f * completed;
            float metalReward = 3.5f * completed;
            float algaeReward = 0f;
            float coalReward = 0f;
            float refinedMetalReward = 0f;
            float researchReward = 0f;
            float powerCapacityReward = 0f;

            if (CrossedScenarioMilestone(previousCount, nextCount, 12))
            {
                foodReward += workers.Count * 80f;
                waterReward += 30f;
                algaeReward += 25f;
            }

            if (CrossedScenarioMilestone(previousCount, nextCount, 24))
            {
                metalReward += 25f;
                researchReward += 2f;
                powerCapacityReward += 25f;
            }

            if (CrossedScenarioMilestone(previousCount, nextCount, 36))
            {
                coalReward += 35f;
                refinedMetalReward += 12f;
            }

            if (CrossedScenarioMilestone(previousCount, nextCount, 47))
            {
                waterReward += 40f;
                refinedMetalReward += 18f;
                powerCapacityReward += 25f;
            }

            if (CrossedScenarioMilestone(previousCount, nextCount, ScenarioMilestoneTotal))
            {
                foodReward += workers.Count * 300f;
                waterReward += 75f;
                refinedMetalReward += 30f;
            }

            food += foodReward;
            StoreCleanWaterInStorage(waterReward, 0f);
            currentCycleReport.FoodProduced += foodReward;
            currentCycleReport.WaterProduced += waterReward;
            dirt += dirtReward;
            metal += metalReward;
            algae += algaeReward;
            coal += coalReward;
            refinedMetal += refinedMetalReward;
            researchPoints += researchReward;
            currentCycleReport.ResearchPoints += researchReward;
            maxPower += powerCapacityReward;

            if (researchReward > 0f)
            {
                ApplyResearchUnlocks(true);
            }

            overlayDirty = true;
            StringBuilder builder = new StringBuilder();
            builder.Append("Charter milestone reward delivered: ");
            bool hasReward = false;
            AppendReward(builder, ref hasReward, foodReward, "food");
            AppendReward(builder, ref hasReward, waterReward, "water");
            AppendReward(builder, ref hasReward, dirtReward, "dirt");
            AppendReward(builder, ref hasReward, metalReward, "metal");
            AppendReward(builder, ref hasReward, algaeReward, "algae");
            AppendReward(builder, ref hasReward, coalReward, "coal");
            AppendReward(builder, ref hasReward, refinedMetalReward, "refined metal");
            AppendReward(builder, ref hasReward, researchReward, "research");
            AppendReward(builder, ref hasReward, powerCapacityReward, "power capacity");
            builder.Append(" (");
            builder.Append(nextCount);
            builder.Append("/");
            builder.Append(ScenarioMilestoneTotal);
            builder.Append(").");
            Log(builder.ToString());
        }

        private bool CrossedScenarioMilestone(int previousCount, int nextCount, int threshold)
        {
            return previousCount < threshold && nextCount >= threshold;
        }

        private void AppendReward(StringBuilder builder, ref bool hasReward, float amount, string label)
        {
            if (amount <= 0.01f)
            {
                return;
            }

            if (hasReward)
            {
                builder.Append(", ");
            }

            builder.Append("+");
            builder.Append(amount >= 10f ? amount.ToString("0") : amount.ToString("0.0"));
            builder.Append(" ");
            builder.Append(label);
            hasReward = true;
        }

        private void RefreshModeButtonLabels()
        {
            foreach (KeyValuePair<CommandMode, Button> pair in modeButtons)
            {
                string nextLabel = Localize(ModeButtonLabel(pair.Key));
                if (pair.Value.text != nextLabel)
                {
                    pair.Value.text = nextLabel;
                }
            }

            RefreshLanguageButtonLabel();
        }

        private string LiquidBridgePairStatus(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, string label)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsInside(input.x, input.y) ||
                !IsInside(output.x, output.y) ||
                !liquidPipe[input.x, input.y] ||
                !liquidPipe[output.x, output.y])
            {
                return label + "needs input and output Liquid Pipes.";
            }

            if (IsLiquidConduitBlocked(input.x, input.y) || IsLiquidConduitBlocked(output.x, output.y))
            {
                return label + "blocked by shutoff or valve.";
            }

            return label +
                LiquidPipeTotal(input.x, input.y).ToString("0.0") +
                " kg in, " +
                LiquidPipeFreeCapacity(output.x, output.y).ToString("0.0") +
                " kg output free.";
        }

        private string GasBridgePairStatus(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, string label)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsInside(input.x, input.y) ||
                !IsInside(output.x, output.y) ||
                !gasPipe[input.x, input.y] ||
                !gasPipe[output.x, output.y])
            {
                return label + "needs input and output Gas Pipes.";
            }

            if (IsGasConduitBlocked(input.x, input.y) || IsGasConduitBlocked(output.x, output.y))
            {
                return label + "blocked by shutoff or valve.";
            }

            return label +
                GasPipeTotal(input.x, input.y).ToString("0.00") +
                " kg in, " +
                (GasPipeCapacity - GasPipeTotal(output.x, output.y)).ToString("0.00") +
                " kg output free.";
        }

        private string ShippingBridgePairStatus(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, string label)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsInside(input.x, input.y) ||
                !IsInside(output.x, output.y) ||
                !shippingRail[input.x, input.y] ||
                !shippingRail[output.x, output.y])
            {
                return label + "needs input and output Shipping Rails.";
            }

            LooseResourceKind kind = shippingRailKind[input.x, input.y];
            float outputFree = kind == LooseResourceKind.None ? 0f : ShippingRailFreeSpace(output, kind);
            string payload = kind == LooseResourceKind.None ? "empty" : LooseResourceLabel(kind);
            return label +
                shippingRailAmount[input.x, input.y].ToString("0.0") +
                " kg in, " +
                outputFree.ToString("0.0") +
                " kg output free. " +
                payload +
                ".";
        }

        private string AutomationBridgePairStatus(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, string label)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
            if (!IsInside(input.x, input.y) ||
                !IsInside(output.x, output.y) ||
                !automationWire[input.x, input.y] ||
                !automationWire[output.x, output.y])
            {
                return label + "needs input and output Automation Wires.";
            }

            if (!CanUseEquipment(bridge))
            {
                return label + "bridge disabled.";
            }

            if (!automationControlledWire[input.x, input.y])
            {
                return label + "input has no signal source.";
            }

            return label +
                (automationSignalWire[input.x, input.y] ? "green" : "red") +
                " in, " +
                (automationControlledWire[output.x, output.y] ? automationSignalWire[output.x, output.y] ? "green" : "red" : "no signal") +
                " output.";
        }

        private string PowerBridgePairStatus(Vector2Int bridge, Vector2Int inputOffset, Vector2Int outputOffset, string label)
        {
            Vector2Int input = new Vector2Int(bridge.x + inputOffset.x, bridge.y + inputOffset.y);
            Vector2Int output = new Vector2Int(bridge.x + outputOffset.x, bridge.y + outputOffset.y);
