        private string AutomationAndGateStatus(Vector2Int gate)
        {
            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            Vector2Int eastOutput = new Vector2Int(gate.x + 1, gate.y);
            Vector2Int northOutput = new Vector2Int(gate.x, gate.y + 1);
            if (!IsInside(westInput.x, westInput.y) ||
                !IsInside(southInput.x, southInput.y) ||
                !automationWire[westInput.x, westInput.y] ||
                !automationWire[southInput.x, southInput.y])
            {
                return "AND gate needs west and south input Automation Wires.";
            }

            if (!IsInside(eastOutput.x, eastOutput.y) ||
                !IsInside(northOutput.x, northOutput.y) ||
                (!automationWire[eastOutput.x, eastOutput.y] && !automationWire[northOutput.x, northOutput.y]))
            {
                return "AND gate needs an east or north output Automation Wire.";
            }

            if (!CanUseEquipment(gate))
            {
                return "gate disabled.";
            }

            if (!automationControlledWire[westInput.x, westInput.y] || !automationControlledWire[southInput.x, southInput.y])
            {
                return "AND gate input has no signal source.";
            }

            bool westSignal = automationSignalWire[westInput.x, westInput.y];
            bool southSignal = automationSignalWire[southInput.x, southInput.y];
            return "West " +
                (westSignal ? "green" : "red") +
                ", south " +
                (southSignal ? "green" : "red") +
                "; AND output " +
                (westSignal && southSignal ? "green" : "red") +
                ".";
        }

        private string AutomationOrGateStatus(Vector2Int gate)
        {
            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            Vector2Int eastOutput = new Vector2Int(gate.x + 1, gate.y);
            Vector2Int northOutput = new Vector2Int(gate.x, gate.y + 1);
            if (!IsInside(westInput.x, westInput.y) ||
                !IsInside(southInput.x, southInput.y) ||
                !automationWire[westInput.x, westInput.y] ||
                !automationWire[southInput.x, southInput.y])
            {
                return "OR gate needs west and south input Automation Wires.";
            }

            if (!IsInside(eastOutput.x, eastOutput.y) ||
                !IsInside(northOutput.x, northOutput.y) ||
                (!automationWire[eastOutput.x, eastOutput.y] && !automationWire[northOutput.x, northOutput.y]))
            {
                return "OR gate needs an east or north output Automation Wire.";
            }

            if (!CanUseEquipment(gate))
            {
                return "gate disabled.";
            }

            if (!automationControlledWire[westInput.x, westInput.y] && !automationControlledWire[southInput.x, southInput.y])
            {
                return "OR gate input has no signal source.";
            }

            bool westSignal = automationControlledWire[westInput.x, westInput.y] && automationSignalWire[westInput.x, westInput.y];
            bool southSignal = automationControlledWire[southInput.x, southInput.y] && automationSignalWire[southInput.x, southInput.y];
            return "West " +
                (westSignal ? "green" : "red") +
                ", south " +
                (southSignal ? "green" : "red") +
                "; OR output " +
                (westSignal || southSignal ? "green" : "red") +
                ".";
        }

        private string AutomationXorGateStatus(Vector2Int gate)
        {
            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            Vector2Int eastOutput = new Vector2Int(gate.x + 1, gate.y);
