        private string AutomationBufferGateStatus(Vector2Int gate)
        {
            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            Vector2Int eastOutput = new Vector2Int(gate.x + 1, gate.y);
            Vector2Int northOutput = new Vector2Int(gate.x, gate.y + 1);
            bool hasWestInput = IsInside(westInput.x, westInput.y) && automationWire[westInput.x, westInput.y];
            bool hasSouthInput = IsInside(southInput.x, southInput.y) && automationWire[southInput.x, southInput.y];
            if (!hasWestInput && !hasSouthInput)
            {
                return "Buffer gate needs west or south input Automation Wire.";
            }

            if (!IsInside(eastOutput.x, eastOutput.y) ||
                !IsInside(northOutput.x, northOutput.y) ||
                (!automationWire[eastOutput.x, eastOutput.y] && !automationWire[northOutput.x, northOutput.y]))
            {
                return "Buffer gate needs an east or north output Automation Wire.";
            }

            if (!CanUseEquipment(gate))
            {
                return "gate disabled.";
            }

            TryGetAutomationBufferGateInputs(gate, out bool inputControlled, out bool westSignal, out bool southSignal);
            bool heldSignal = automationBufferRemainingSeconds[gate.x, gate.y] > 0.001f;
            if (!inputControlled && !heldSignal)
            {
                return "Buffer gate input has no signal source.";
            }

            bool outputSignal = (inputControlled && (westSignal || southSignal)) || heldSignal;
            return "West " +
                (westSignal ? "green" : "red") +
                ", south " +
                (southSignal ? "green" : "red") +
                "; buffer hold " +
                AutomationBufferHoldSecondsAt(gate.x, gate.y).ToString("0") +
                "s, remaining " +
                automationBufferRemainingSeconds[gate.x, gate.y].ToString("0.0") +
                "s; buffer output " +
                (outputSignal ? "green" : "red") +
                ".";
        }

        private string AutomationFilterGateStatus(Vector2Int gate)
        {
            Vector2Int westInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int southInput = new Vector2Int(gate.x, gate.y - 1);
            Vector2Int eastOutput = new Vector2Int(gate.x + 1, gate.y);
            Vector2Int northOutput = new Vector2Int(gate.x, gate.y + 1);
            bool hasWestInput = IsInside(westInput.x, westInput.y) && automationWire[westInput.x, westInput.y];
            bool hasSouthInput = IsInside(southInput.x, southInput.y) && automationWire[southInput.x, southInput.y];
            if (!hasWestInput && !hasSouthInput)
            {
                return "Filter gate needs west or south input Automation Wire.";
            }

            if (!IsInside(eastOutput.x, eastOutput.y) ||
                !IsInside(northOutput.x, northOutput.y) ||
                (!automationWire[eastOutput.x, eastOutput.y] && !automationWire[northOutput.x, northOutput.y]))
            {
                return "Filter gate needs an east or north output Automation Wire.";
            }

            if (!CanUseEquipment(gate))
            {
                return "gate disabled.";
            }

            TryGetAutomationFilterGateInputs(gate, out bool inputControlled, out bool westSignal, out bool southSignal);
            if (!inputControlled)
            {
                return "Filter gate input has no signal source.";
            }

            float delaySeconds = AutomationFilterDelaySecondsAt(gate.x, gate.y);
            bool inputSignal = westSignal || southSignal;
            bool outputSignal = inputSignal && automationFilterProgressSeconds[gate.x, gate.y] >= delaySeconds - 0.001f;
            return "West " +
                (westSignal ? "green" : "red") +
                ", south " +
                (southSignal ? "green" : "red") +
                "; filter delay " +
                delaySeconds.ToString("0") +
                "s, progress " +
                automationFilterProgressSeconds[gate.x, gate.y].ToString("0.0") +
                "s; filter output " +
                (outputSignal ? "green" : "red") +
                ".";
        }

        private string AutomationMemoryGateStatus(Vector2Int gate)
        {
            Vector2Int setInput = new Vector2Int(gate.x - 1, gate.y);
            Vector2Int resetInput = new Vector2Int(gate.x, gate.y - 1);
            Vector2Int eastOutput = new Vector2Int(gate.x + 1, gate.y);
            Vector2Int northOutput = new Vector2Int(gate.x, gate.y + 1);
            bool hasSetInput = IsInside(setInput.x, setInput.y) && automationWire[setInput.x, setInput.y];
            bool hasResetInput = IsInside(resetInput.x, resetInput.y) && automationWire[resetInput.x, resetInput.y];
            if (!hasSetInput && !hasResetInput)
            {
                return "Memory gate needs west set or south reset input Automation Wire.";
            }

            if (!IsInside(eastOutput.x, eastOutput.y) ||
                !IsInside(northOutput.x, northOutput.y) ||
                (!automationWire[eastOutput.x, eastOutput.y] && !automationWire[northOutput.x, northOutput.y]))
            {
                return "Memory gate needs an east or north output Automation Wire.";
            }

            if (!CanUseEquipment(gate))
            {
                return "gate disabled.";
            }

            TryGetAutomationMemoryGateInputs(gate, out bool inputControlled, out bool setSignal, out bool resetSignal);
            bool latchedSignal = automationMemoryState[gate.x, gate.y];
            if (!inputControlled)
            {
                return "Memory gate input has no signal source; latched " +
                    (latchedSignal ? "green" : "red") +
                    ".";
            }

            return "Set " +
                (setSignal ? "green" : "red") +
                ", reset " +
                (resetSignal ? "green" : "red") +
                "; memory latched " +
                (latchedSignal ? "green" : "red") +
                ".";
        }

        private string AutomationCycleSensorStatus(Vector2Int sensor)
        {
            if (!HasAutomationWireAccess(sensor))
            {
                return "Needs adjacent or under-floor Automation Wire.";
            }

            if (!CanUseEquipment(sensor))
            {
                return "sensor disabled.";
            }

            bool signalActive = AutomationCycleSensorSignalActive(sensor.x, sensor.y);
            return "Cycle window " +
                CycleClockLabel(CycleSensorStartAt(sensor.x, sensor.y)) +
                "-" +
                CycleClockLabel(CycleSensorEndAt(sensor.x, sensor.y)) +
                "; current " +
                CycleClockLabel(cycleTimer / CycleLengthSeconds) +
                "; sensor signal " +
                (signalActive ? "green" : "red") +
                ".";
        }

        private string AutomationTimerSensorStatus(Vector2Int sensor)
        {
            if (!HasAutomationWireAccess(sensor))
            {
                return "Needs adjacent or under-floor Automation Wire.";
            }

            if (!CanUseEquipment(sensor))
            {
                return "sensor disabled.";
            }

            float elapsed = AutomationTimerElapsedSecondsAt(sensor.x, sensor.y);
            float greenSeconds = AutomationTimerGreenSecondsAt(sensor.x, sensor.y);
            float redSeconds = AutomationTimerRedSecondsAt(sensor.x, sensor.y);
            bool signalActive = AutomationTimerSensorSignalActive(sensor.x, sensor.y);
            return "Timer green " +
                greenSeconds.ToString("0") +
                "s, red " +
                redSeconds.ToString("0") +
                "s, elapsed " +
                elapsed.ToString("0.0") +
                "s; timer signal " +
                (signalActive ? "green" : "red") +
                ".";
        }

        private string DuplicantMotionSensorStatus(Vector2Int sensor)
        {
            if (!HasAutomationWireAccess(sensor))
            {
                return "Needs adjacent or under-floor Automation Wire.";
            }

            if (!CanUseEquipment(sensor))
            {
                return "sensor disabled.";
            }

            int detected = CountDuplicantsForMotionSensor(sensor);
            bool signalActive = DuplicantMotionSensorSignalActive(sensor.x, sensor.y);
            return "Motion sensor detected " +
                detected +
                " duplicants within " +
                DuplicantMotionSensorRange +
                " tiles; motion signal " +
                (signalActive ? "green" : "red") +
                ".";
        }

        private string AutomationEquipmentBlockText(
            Vector2Int cell,
            CellKind expectedKind,
            bool requiresPowerRegulation = false,
            bool requiresAirSystems = false,
            bool requiresFoodPreparation = false)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != expectedKind)
            {
                return "Automation blocked: equipment missing.";
            }

            if (requiresPowerRegulation && (!techPowerRegulation || !techAutomationLogistics))
            {
                return "Automation blocked: research Power Regulation and Automation Logistics.";
            }

            if (requiresAirSystems && (!techAirSystems || !techAutomationLogistics))
            {
                return "Automation blocked: research Air Systems and Automation Logistics.";
            }

            if (requiresFoodPreparation && (!techFoodPreparation || !techAutomationLogistics))
            {
                return "Automation blocked: research Food Preparation and Automation Logistics.";
            }

            if (!techAutomationLogistics)
            {
                return "Automation blocked: research Automation Logistics.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Automation blocked: needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Automation blocked: equipment is submerged.";
            }

            return string.Empty;
        }

        private string AutomationPortReadinessText(Vector2Int cell, string unlinkedText, string greenText, string redText)
        {
            UpdateAutomationWires();
            if (!HasCachedAutomationControl(cell))
            {
                return unlinkedText;
            }

            return HasCachedAutomationSignal(cell) ? greenText : redText;
        }

        private bool HasAutomationWireAt(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) && automationWire[cell.x, cell.y];
        }

        private bool HasAutomationGateOutputWire(Vector2Int gate)
        {
            return HasAutomationWireAt(new Vector2Int(gate.x + 1, gate.y)) ||
                HasAutomationWireAt(new Vector2Int(gate.x, gate.y + 1));
        }

        private string PowerShutoffReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.PowerShutoff, requiresPowerRegulation: true);
            if (!string.IsNullOrEmpty(block))
            {
