                "Power shutoff ready: no automation signal, defaults connected.",
                "Power shutoff ready: green signal connects the circuit.",
                "Power shutoff active: red signal isolates the circuit.");
        }

        private string SignalSwitchReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.SignalSwitch);
            if (!string.IsNullOrEmpty(block))
