        private string AutomationBridgeReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.AutomationBridge);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
            Vector2Int input = cell + BridgeInputOffset(direction);
            Vector2Int output = cell + BridgeOutputOffset(direction);
            if (!HasAutomationWireAt(input) || !HasAutomationWireAt(output))
            {
                return "Automation bridge blocked: needs input and output automation wires.";
            }

            if (!automationControlledWire[input.x, input.y])
            {
                return "Automation bridge idle: input wire has no signal source.";
            }

            return "Automation bridge ready: signal is routed to output.";
        }

        private string AutomationNotGateReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.AutomationNotGate);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            bool hasLane = false;
            bool hasControlledInput = false;
            TrackAutomationLane(cell, new Vector2Int(-1, 0), new Vector2Int(1, 0), ref hasLane, ref hasControlledInput);
            TrackAutomationLane(cell, new Vector2Int(0, -1), new Vector2Int(0, 1), ref hasLane, ref hasControlledInput);
            if (!hasLane)
            {
                return "Automation gate blocked: needs input and output automation wires.";
            }

            return hasControlledInput
                ? "Automation gate ready: output signal is being driven."
                : "Automation gate idle: input wire has no signal source.";
        }

        private void TrackAutomationLane(
            Vector2Int origin,
            Vector2Int inputOffset,
            Vector2Int outputOffset,
            ref bool hasLane,
            ref bool hasControlledInput)
        {
            Vector2Int input = origin + inputOffset;
            Vector2Int output = origin + outputOffset;
            if (!HasAutomationWireAt(input) || !HasAutomationWireAt(output))
            {
                return;
            }

            hasLane = true;
            hasControlledInput |= automationControlledWire[input.x, input.y];
        }

        private string DualInputAutomationGateReadinessText(Vector2Int cell, CellKind expectedKind, bool requireBothInputSignals)
        {
            string block = AutomationEquipmentBlockText(cell, expectedKind);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            Vector2Int westInput = new Vector2Int(cell.x - 1, cell.y);
            Vector2Int southInput = new Vector2Int(cell.x, cell.y - 1);
            if (!HasAutomationWireAt(westInput) || !HasAutomationWireAt(southInput))
            {
                return "Automation gate blocked: needs required input automation wires.";
            }

            if (!HasAutomationGateOutputWire(cell))
            {
                return "Automation gate blocked: needs output automation wire.";
            }

            bool westControlled = automationControlledWire[westInput.x, westInput.y];
            bool southControlled = automationControlledWire[southInput.x, southInput.y];
            bool hasSignals = requireBothInputSignals ? westControlled && southControlled : westControlled || southControlled;
            return hasSignals
                ? "Automation gate ready: output signal is being driven."
                : "Automation gate idle: input wire has no signal source.";
        }

        private string OptionalInputAutomationGateReadinessText(Vector2Int cell, CellKind expectedKind, bool allowHeldOutput)
        {
            string block = AutomationEquipmentBlockText(cell, expectedKind);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            Vector2Int westInput = new Vector2Int(cell.x - 1, cell.y);
            Vector2Int southInput = new Vector2Int(cell.x, cell.y - 1);
            if (!HasAutomationWireAt(westInput) && !HasAutomationWireAt(southInput))
            {
                return "Automation gate blocked: needs required input automation wires.";
            }

            if (!HasAutomationGateOutputWire(cell))
            {
                return "Automation gate blocked: needs output automation wire.";
            }

            bool inputControlled;
            if (expectedKind == CellKind.AutomationBufferGate)
            {
                inputControlled = TryGetAutomationBufferGateInputs(cell, out bool bufferInputControlled, out _, out _) && bufferInputControlled;
            }
            else
            {
                inputControlled = TryGetAutomationFilterGateInputs(cell, out bool filterInputControlled, out _, out _) && filterInputControlled;
            }

            if (inputControlled)
            {
                return "Automation gate ready: output signal is being driven.";
            }

            if (allowHeldOutput && automationBufferRemainingSeconds[cell.x, cell.y] > 0.001f)
            {
                return "Automation gate ready: buffer hold is driving output.";
            }

            return "Automation gate idle: input wire has no signal source.";
        }

        private string AutomationMemoryGateReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.AutomationMemoryGate);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            Vector2Int setInput = new Vector2Int(cell.x - 1, cell.y);
            Vector2Int resetInput = new Vector2Int(cell.x, cell.y - 1);
            if (!HasAutomationWireAt(setInput) && !HasAutomationWireAt(resetInput))
            {
                return "Automation gate blocked: needs required input automation wires.";
            }

            if (!HasAutomationGateOutputWire(cell))
            {
                return "Automation gate blocked: needs output automation wire.";
            }

            if (!TryGetAutomationMemoryGateInputs(cell, out bool inputControlled, out _, out _))
            {
                return "Automation gate idle: input wire has no signal source.";
            }

            return inputControlled
                ? "Automation gate ready: output signal is being driven."
                : "Automation gate ready: memory latch is holding output.";
        }

