        private string StorageBinReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return "Storage bin blocked: bin missing.";
            }

            if (DryResourceFreeSpace() <= 0.01f)
            {
                return "Storage bin blocked: dry storage is full.";
            }

            if (storageSweepOnly[cell.x, cell.y])
            {
                return "Storage bin ready: accepts manual sweep deliveries only.";
            }

            return storageBinFilter[cell.x, cell.y] == StorageFilter.All
                ? "Storage bin ready: accepts automatic dry deliveries."
                : "Storage bin ready: accepts filtered automatic deliveries.";
        }

        private string StorageBinEmptyReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.StorageBin)
            {
                return "Empty storage blocked: Storage Bin missing.";
            }

            float available = StorageBinEmptyableResourceAmount(cell);
            if (available <= 0.05f)
            {
                return "Empty storage idle: no stored resources match this bin's filter.";
            }

            if (!HasStorageBinDropSpace(cell))
            {
                return "Empty storage blocked: no adjacent loose-resource drop space.";
            }

            float amount = Mathf.Min(StorageBinCapacityAt(cell.x, cell.y), available);
            return "Empty storage ready: Empty Bin can drop up to " + amount.ToString("0") + " kg.";
        }

        private string PipeEmptyReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || (!liquidPipe[cell.x, cell.y] && !gasPipe[cell.x, cell.y]))
            {
                return "Empty pipe blocked: selected pipe missing.";
            }

            float liquidAmount = liquidPipe[cell.x, cell.y] ? LiquidPipeTotal(cell.x, cell.y) : 0f;
            float gasAmount = gasPipe[cell.x, cell.y] ? GasPipeTotal(cell.x, cell.y) : 0f;
            if (liquidAmount <= 0.001f && gasAmount <= 0.001f)
            {
                return "Empty pipe idle: selected pipe has no contents.";
            }

            Vector2Int liquidOutput = default;
            Vector2Int gasOutput = default;
            bool liquidReady = liquidAmount > 0.001f && TryFindPipeLiquidOutput(cell, out liquidOutput) && LiquidFreeCapacity(liquidOutput.x, liquidOutput.y) > 0.001f;
            bool gasReady = gasAmount > 0.001f && TryFindPipeGasOutput(cell, out gasOutput) && TileGasTotal(gasOutput.x, gasOutput.y) < GasVentMaxPressure - 0.02f;
            if (!liquidReady && !gasReady)
            {
                if (liquidAmount > 0.001f && gasAmount > 0.001f)
                {
                    return "Empty pipe blocked: no liquid spill or gas release space.";
                }

                return liquidAmount > 0.001f
                    ? "Empty pipe blocked: no liquid spill space."
                    : "Empty pipe blocked: no gas release space.";
            }

            float releaseLiquid = liquidReady ? Mathf.Min(liquidAmount, LiquidFreeCapacity(liquidOutput.x, liquidOutput.y)) : 0f;
            float releaseGas = gasReady ? Mathf.Min(gasAmount, Mathf.Max(0f, GasVentMaxPressure - TileGasTotal(gasOutput.x, gasOutput.y))) : 0f;
            return "Empty pipe ready: can release " + PipeEmptyAmountSummary(releaseLiquid, releaseGas) + ".";
        }

        private string ReservoirEmptyReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || (cells[cell.x, cell.y] != CellKind.LiquidReservoir && cells[cell.x, cell.y] != CellKind.GasReservoir))
            {
                return "Empty reservoir blocked: selected reservoir missing.";
            }

            bool liquidReservoir = cells[cell.x, cell.y] == CellKind.LiquidReservoir;
            float liquidAmount = liquidReservoir ? LiquidReservoirTotal(cell.x, cell.y) : 0f;
            float gasAmount = liquidReservoir ? 0f : GasReservoirTotal(cell.x, cell.y);
            if (liquidAmount <= 0.001f && gasAmount <= 0.001f)
            {
                return "Empty reservoir idle: selected reservoir has no contents.";
            }

            if (liquidReservoir)
            {
                if (!TryFindPipeLiquidOutput(cell, out Vector2Int liquidOutput) || LiquidFreeCapacity(liquidOutput.x, liquidOutput.y) <= 0.001f)
                {
                    return "Empty reservoir blocked: no liquid spill space.";
                }

                float releaseLiquid = Mathf.Min(liquidAmount, LiquidFreeCapacity(liquidOutput.x, liquidOutput.y));
                return "Empty reservoir ready: can release " + PipeEmptyAmountSummary(releaseLiquid, 0f) + ".";
            }

            if (!TryFindPipeGasOutput(cell, out Vector2Int gasOutput) || TileGasTotal(gasOutput.x, gasOutput.y) >= GasVentMaxPressure - 0.02f)
            {
                return "Empty reservoir blocked: no gas release space.";
            }

            float releaseGas = Mathf.Min(gasAmount, Mathf.Max(0f, GasVentMaxPressure - TileGasTotal(gasOutput.x, gasOutput.y)));
            return "Empty reservoir ready: can release " + PipeEmptyAmountSummary(0f, releaseGas) + ".";
        }

        private string ShippingRailDropReadinessText(Vector2Int rail)
        {
            if (!IsInside(rail.x, rail.y) || !shippingRail[rail.x, rail.y])
            {
                return "Rail drop blocked: selected rail missing.";
            }

            LooseResourceKind kind = shippingRailKind[rail.x, rail.y];
            float amount = shippingRailAmount[rail.x, rail.y];
            if (kind == LooseResourceKind.None || amount <= 0.001f)
            {
                return "Rail drop idle: selected rail has no packet.";
            }

            if (!TryFindLooseResourceDropCell(rail, kind, out _))
            {
                return "Rail drop blocked: no adjacent loose-resource drop space.";
            }

            return "Rail drop ready: can drop " + amount.ToString("0.#") + " kg " + LooseResourceLabel(kind) + ".";
        }

        private string AutoSweeperReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.AutoSweeper);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
