                return "Auto-sweeper blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Auto-sweeper blocked: automation signal is red.";
            }

            if (DryResourceFreeSpace() <= 0.01f)
            {
                return "Auto-sweeper blocked: dry storage is full.";
            }

            return TryFindAutoSweeperTarget(cell, out _)
                ? "Auto-sweeper ready: storable debris is in range."
                : "Auto-sweeper idle: no storable debris in range.";
        }

        private string ConveyorLoaderReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.ConveyorLoader);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            if (!HasWireAccess(cell))
            {
                return "Conveyor loader blocked: needs power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Conveyor loader blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Conveyor loader blocked: automation signal is red.";
            }

            StorageFilter filter = ConveyorLoaderFilterAt(cell.x, cell.y);
            if (!TrySelectDryResourceForShipping(filter, out LooseResourceKind kind, out _))
            {
                return "Conveyor loader idle: no matching stored dry resource.";
            }

            if (!TryFindShippingRailWithSpace(cell, kind, out _))
            {
                return HasShippingRailAccess(cell)
                    ? "Conveyor loader blocked: adjacent rail is full or holds another resource."
                    : "Conveyor loader blocked: needs adjacent shipping rail.";
            }

            return "Conveyor loader ready: can load matching resources.";
        }

        private string ConveyorReceptacleReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.ConveyorReceptacle);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            StorageFilter filter = ConveyorReceptacleFilterAt(cell.x, cell.y);
            if (!TryFindAdjacentShippingRailWithPacket(cell, filter, out Vector2Int rail))
            {
                return HasShippingRailAccess(cell)
                    ? "Conveyor receptacle idle: no matching packet on adjacent rail."
                    : "Conveyor receptacle blocked: needs adjacent shipping rail.";
            }

            LooseResourceKind kind = shippingRailKind[rail.x, rail.y];
