        }

        private string ConveyorChuteReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.ConveyorChute)
            {
                return "Conveyor chute blocked: chute missing.";
            }

            if (!techAutomationLogistics)
            {
                return "Conveyor chute blocked: research Automation Logistics.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Conveyor chute blocked: needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Conveyor chute blocked: chute is submerged.";
            }

            if (!TryFindAdjacentShippingRailWithPacket(cell, out Vector2Int rail))
            {
                return HasShippingRailAccess(cell)
                    ? "Conveyor chute idle: no packet on adjacent rail."
                    : "Conveyor chute blocked: needs adjacent shipping rail.";
            }

            LooseResourceKind kind = shippingRailKind[rail.x, rail.y];
            if (!TryFindLooseResourceDropCell(cell, kind, out _))
            {
                return "Conveyor chute blocked: no drop space for packet.";
            }

            return "Conveyor chute ready: can drop adjacent rail packet.";
        }

        private string ShippingBridgeReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.ShippingBridge);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
            Vector2Int input = cell + BridgeInputOffset(direction);
            Vector2Int output = cell + BridgeOutputOffset(direction);
            if (!IsInside(input.x, input.y) ||
                !IsInside(output.x, output.y) ||
                !shippingRail[input.x, input.y] ||
                !shippingRail[output.x, output.y])
            {
                return "Shipping bridge blocked: needs input and output rails.";
            }

            if (IsClosedShippingRailShutoff(input) || IsClosedShippingRailShutoff(output))
            {
                return "Shipping bridge blocked: rail shutoff is closed.";
            }

            if (IsClosedShippingRailMeter(input) || IsClosedShippingRailMeter(output))
            {
                return "Shipping bridge blocked: conveyor meter is closed.";
            }

            LooseResourceKind kind = shippingRailKind[input.x, input.y];
            if (kind == LooseResourceKind.None || shippingRailAmount[input.x, input.y] <= 0.001f)
            {
                return "Shipping bridge idle: input rail has no packet.";
            }

            if (ShippingRailFreeSpace(output, kind) <= 0.001f)
            {
                return "Shipping bridge blocked: output rail has no space.";
            }

            return "Shipping bridge ready: packet can cross bridge.";
        }

