        private string ShippingRailMeterReadinessText(Vector2Int cell)
        {
            string block = AutomationEquipmentBlockText(cell, CellKind.ShippingRailMeter);
            if (!string.IsNullOrEmpty(block))
            {
                return block;
            }

            if (!shippingRail[cell.x, cell.y])
            {
                return "Shipping automation blocked: needs under-floor shipping rail.";
            }

            return AutomationPortReadinessText(
                cell,
                "Conveyor meter ready: no automation signal, regulating packets.",
                "Conveyor meter ready: green signal regulates packets.",
                "Conveyor meter active: red signal blocks packets.");
        }

        private string BuildInspectText()
        {
            if (!inspectedCell.HasValue)
            {
                return "Select a tile.";
            }

            Vector2Int cell = inspectedCell.Value;
            if (!IsInside(cell.x, cell.y))
            {
                return string.Empty;
            }

            StringBuilder builder = new StringBuilder();
            UpdatePoweredWires();
            UpdateAutomationWires();
            UpdatePowerLoad(0f, false);
            builder.AppendLine("Tile " + cell.x + ", " + cell.y);
            builder.AppendLine(CellLabel(cells[cell.x, cell.y]));
            string commandReadinessText = CommandReadinessText(cell, currentMode);
            if (!string.IsNullOrEmpty(commandReadinessText))
            {
                builder.AppendLine(commandReadinessText);
            }

            if (IsDisablableBuilding(cells[cell.x, cell.y]))
            {
                builder.AppendLine(buildingDisabled[cell.x, cell.y] ? "Building disabled: errands and machine output are paused." : "Building enabled.");
            }

            builder.AppendLine("Schedule " + SchedulePlanLabel());
            builder.AppendLine("Temp " + temperature[cell.x, cell.y].ToString("0.0") + " C");
            float localPressure = TileGasTotal(cell.x, cell.y);
            builder.AppendLine("Pressure " + localPressure.ToString("0.00") + " kg" +
                (localPressure > OverpressureDamageThreshold ? "  DANGEROUS" : localPressure > OverpressureStressThreshold ? "  HIGH" : string.Empty));
            if (cells[cell.x, cell.y] == CellKind.Sand)
            {
                builder.AppendLine(CanSandFallInto(cell.x, cell.y - 1) ? "Unstable sand: will fall into open space below." : "Supported sand.");
                builder.AppendLine("Sand falls " + sandFalls + "  Worker hits " + sandStrikeInjuries);
            }
            else if (cells[cell.x, cell.y] == CellKind.Regolith)
            {
                builder.AppendLine(CanSandFallInto(cell.x, cell.y - 1) ? "Loose regolith: will fall into open space below." : "Regolith deposited by meteor impacts.");
                builder.AppendLine("Meteor regolith " + meteorRegolithDeposited.ToString("0") + " kg  Strikes " + meteorStrikes);
            }

            if (powerWire[cell.x, cell.y])
            {
                string wireLabel = PowerWireKindName(powerWireKind[cell.x, cell.y]);
                builder.AppendLine(poweredWire[cell.x, cell.y] ? wireLabel + ": connected" : wireLabel + ": unpowered");
                builder.AppendLine("Load " + wireLoad[cell.x, cell.y].ToString("0.00") + "/" + PowerLoadLimitForWire(cell.x, cell.y).ToString("0.00") + " kW" + (overloadedWire[cell.x, cell.y] ? "  OVERLOAD" : string.Empty));
                if (IsPowerWireFlooded(cell.x, cell.y))
                {
                    builder.AppendLine("Flooded wire: shorting risk " + wireOverloadStress[cell.x, cell.y].ToString("0.0") + "/" + WireOverloadBreakStress.ToString("0") + ".");
                }

                if (poweredWire[cell.x, cell.y] && (overloadedWire[cell.x, cell.y] || IsPowerWireFlooded(cell.x, cell.y)))
                {
                    builder.AppendLine("Live overloaded or flooded wire shocks duplicants standing on it.");
                }

                if (HasTransformerProtection(cell.x, cell.y))
                {
                    builder.AppendLine("Transformer-protected circuit.");
                }

                if (powerWireKind[cell.x, cell.y] == PowerWireKind.HeavyWatt)
                {
                    builder.AppendLine("Heavy-watt wire decor penalty radius " + HeavyWattWireDecorRadius + ".");
                }
            }

            if (cells[cell.x, cell.y] == CellKind.PowerBridge)
            {
                BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
                builder.AppendLine("Power bridge. Routes power along the configured direction without crossing through the bridge tile.");
                builder.AppendLine("Bridge direction " + BridgeDirectionName(direction) + ".");
                builder.AppendLine(PowerBridgePairStatus(cell, BridgeInputOffset(direction), BridgeOutputOffset(direction), BridgeDirectionStatusPrefix(direction)));
            }

            if (cells[cell.x, cell.y] == CellKind.PowerShutoff)
            {
                builder.AppendLine(techPowerRegulation && techAutomationLogistics ? "Power shutoff. Green automation connects the wire; red isolates the circuit." : "Locked: research Power Regulation and Automation Logistics.");
                builder.AppendLine(PowerShutoffReadinessText(cell));
                builder.AppendLine(IsPowerShutoffOpen(cell) ? "Switch state: connected." : "Switch state: disconnected.");
                builder.AppendLine(HasAutomationControl(cell)
                    ? HasAutomationSignal(cell) ? "Automation: green signal." : "Automation: red signal."
                    : "Automation: no signal, defaults connected.");
                builder.AppendLine(powerWire[cell.x, cell.y] ? "Power wire linked." : "Needs an under-floor Power Wire.");
            }

            if (RequiresPower(cells[cell.x, cell.y]))
            {
                builder.AppendLine(HasWireAccess(cell) ? "Machine power: wired  Demand " + PowerDemandForKind(cells[cell.x, cell.y]).ToString("0.00") + " kW" : "Machine power: no wire connection");
                builder.AppendLine(MachineAutomationStateText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.OxygenDiffuser)
            {
                builder.AppendLine("Oxygen diffuser. Consumes algae and power to release breathable oxygen.");
                builder.AppendLine("Algae " + algae.ToString("0.0") + " kg  Output bonus " + (techAirSystems ? "Air Systems" : "Basic") + ".");
                builder.AppendLine(OxygenDiffuserReadinessText(cell));
            }

            if (automationWire[cell.x, cell.y])
            {
                UpdateAutomationWires();
                builder.AppendLine(automationControlledWire[cell.x, cell.y]
                    ? automationSignalWire[cell.x, cell.y] ? "Automation Wire: green signal" : "Automation Wire: red signal"
                    : "Automation Wire: no signal source");
            }

            if (cells[cell.x, cell.y] == CellKind.SignalSwitch)
            {
                builder.AppendLine(techAutomationLogistics ? "Manual automation source. Toggle to send green or red signal." : "Locked: research Automation Logistics.");
                builder.AppendLine(SignalSwitchReadinessText(cell));
                builder.AppendLine("Signal " + (SignalSwitchSignalActive(cell.x, cell.y) ? "green" : "red") + "  Toggles " + signalSwitchesToggled);
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationBridge)
            {
                BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
                builder.AppendLine(techAutomationLogistics ? "Automation bridge. Routes automation signals along the configured direction without crossing through the bridge tile." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationBridgeReadinessText(cell));
                builder.AppendLine("Bridge direction " + BridgeDirectionName(direction) + ".");
                builder.AppendLine(AutomationBridgePairStatus(cell, BridgeInputOffset(direction), BridgeOutputOffset(direction), BridgeDirectionStatusPrefix(direction)));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationNotGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation NOT gate. Inverts automation signals west to east and south to north without crossing through the gate tile." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationNotGateReadinessText(cell));
                builder.AppendLine(AutomationNotGatePairStatus(cell, new Vector2Int(-1, 0), new Vector2Int(1, 0), "West to east "));
                builder.AppendLine(AutomationNotGatePairStatus(cell, new Vector2Int(0, -1), new Vector2Int(0, 1), "South to north "));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationAndGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation AND gate. Sends green when west and south inputs are both green, with east and north outputs." : "Locked: research Automation Logistics.");
                builder.AppendLine(DualInputAutomationGateReadinessText(cell, CellKind.AutomationAndGate, true));
                builder.AppendLine(AutomationAndGateStatus(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationOrGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation OR gate. Sends green when either west or south input is green, with east and north outputs." : "Locked: research Automation Logistics.");
                builder.AppendLine(DualInputAutomationGateReadinessText(cell, CellKind.AutomationOrGate, false));
                builder.AppendLine(AutomationOrGateStatus(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationXorGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation XOR gate. Sends green when exactly one of west or south inputs is green, with east and north outputs." : "Locked: research Automation Logistics.");
                builder.AppendLine(DualInputAutomationGateReadinessText(cell, CellKind.AutomationXorGate, false));
                builder.AppendLine(AutomationXorGateStatus(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationBufferGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation Buffer gate. Sends green while west or south input is green, then holds green for the configured time." : "Locked: research Automation Logistics.");
                builder.AppendLine(OptionalInputAutomationGateReadinessText(cell, CellKind.AutomationBufferGate, true));
                builder.AppendLine(AutomationBufferGateStatus(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationFilterGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation Filter gate. Sends green only after west or south input stays green for the configured time." : "Locked: research Automation Logistics.");
                builder.AppendLine(OptionalInputAutomationGateReadinessText(cell, CellKind.AutomationFilterGate, false));
                builder.AppendLine(AutomationFilterGateStatus(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationMemoryGate)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation Memory gate. West set turns output green; south reset turns output red, and reset wins." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationMemoryGateReadinessText(cell));
                builder.AppendLine(AutomationMemoryGateStatus(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationCycleSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation Cycle sensor. Sends green during its configured cycle window." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.AutomationCycleSensor, AutomationCycleSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine(AutomationCycleSensorStatus(cell));
                builder.AppendLine(cycleSensorEditingEnd ? "Editing end time with Time +/-." : "Editing start time with Time +/-.");
            }

            if (cells[cell.x, cell.y] == CellKind.AutomationTimerSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Automation Timer sensor. Repeats green and red signal durations." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.AutomationTimerSensor, AutomationTimerSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine(AutomationTimerSensorStatus(cell));
                builder.AppendLine(timerSensorEditingRed ? "Editing red time with Time +/-." : "Editing green time with Time +/-.");
            }

            if (cells[cell.x, cell.y] == CellKind.DuplicantMotionSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Duplicant motion sensor. Sends green when an active duplicant is nearby." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.DuplicantMotionSensor, DuplicantMotionSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine(DuplicantMotionSensorStatus(cell));
                builder.AppendLine("Detection range " + DuplicantMotionSensorRange + " tiles.");
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingRailSensor)
            {
                StorageFilter filter = ShippingRailSensorFilterAt(cell.x, cell.y);
                string packet = shippingRail[cell.x, cell.y] && shippingRailKind[cell.x, cell.y] != LooseResourceKind.None
                    ? shippingRailAmount[cell.x, cell.y].ToString("0.0") + " kg " + LooseResourceLabel(shippingRailKind[cell.x, cell.y])
                    : "none";
                builder.AppendLine(techAutomationLogistics ? "Shipping rail sensor. Sends green when the rail packet matches its filter." : "Locked: research Automation Logistics.");
                builder.AppendLine(ShippingRailSensorReadinessText(cell));
                builder.AppendLine("Filter " + StorageFilterName(filter) + "  Packet " + packet + ".");
                builder.AppendLine(ShippingRailSensorSignalActive(cell.x, cell.y) ? "Sensor signal: green." : "Sensor signal: red.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingRailShutoff)
            {
                builder.AppendLine(techAutomationLogistics ? "Shipping rail shutoff. Green automation lets rail packets pass; red blocks the rail." : "Locked: research Automation Logistics.");
                builder.AppendLine(ShippingRailShutoffReadinessText(cell));
                builder.AppendLine(IsShippingRailShutoffOpen(cell) ? "Switch state: open." : "Switch state: closed.");
                builder.AppendLine(HasAutomationControl(cell)
                    ? HasAutomationSignal(cell) ? "Automation: green signal." : "Automation: red signal."
                    : "Automation: no signal, defaults open.");
                builder.AppendLine(shippingRail[cell.x, cell.y] ? "Shipping rail linked." : "Needs an under-floor Shipping Rail.");
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingRailMeter)
            {
                builder.AppendLine(techAutomationLogistics ? "Conveyor meter. Limits Shipping Rail packet flow to its configured kg/s rate." : "Locked: research Automation Logistics.");
                builder.AppendLine(ShippingRailMeterReadinessText(cell));
                builder.AppendLine("Flow limit " + ShippingRailMeterFlowLimitAt(cell.x, cell.y).ToString("0.0") + " kg/s.");
                builder.AppendLine(IsShippingRailMeterOpen(cell) ? "Meter state: regulating." : "Meter state: blocked.");
                builder.AppendLine(HasAutomationControl(cell)
                    ? HasAutomationSignal(cell) ? "Automation: green signal." : "Automation: red signal."
                    : "Automation: no signal, defaults open.");
                builder.AppendLine(shippingRail[cell.x, cell.y] ? "Shipping rail linked." : "Needs an under-floor Shipping Rail.");
            }

            if (cells[cell.x, cell.y] == CellKind.AtmoSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Atmo sensor. Sends green when local gas pressure matches the condition." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.AtmoSensor, AtmoSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine("Local pressure " + TileGasTotal(cell.x, cell.y).ToString("0.00") + "/" + AtmoSensorThresholdAt(cell.x, cell.y).ToString("0.0") + " kg.");
                builder.AppendLine("Signal condition " + ThresholdSensorConditionName(ThresholdSensorConditionAt(cell.x, cell.y)) + ".");
                builder.AppendLine(AtmoSensorSignalActive(cell.x, cell.y) ? "Sensor signal: green." : "Sensor signal: red.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.ThermoSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Thermo sensor. Sends green when local temperature matches the condition." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.ThermoSensor, ThermoSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine("Local temperature " + temperature[cell.x, cell.y].ToString("0.0") + "/" + ThermoSensorThresholdAt(cell.x, cell.y).ToString("0") + " C.");
                builder.AppendLine("Signal condition " + ThresholdSensorConditionName(ThresholdSensorConditionAt(cell.x, cell.y)) + ".");
                builder.AppendLine(ThermoSensorSignalActive(cell.x, cell.y) ? "Sensor signal: green." : "Sensor signal: red.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.HydroSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Hydro sensor. Sends green when local liquid mass matches the condition." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.HydroSensor, HydroSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine("Local liquid " + waterMass[cell.x, cell.y].ToString("0.0") + "/" + HydroSensorThresholdAt(cell.x, cell.y).ToString("0") + " kg.");
                builder.AppendLine("Signal condition " + ThresholdSensorConditionName(ThresholdSensorConditionAt(cell.x, cell.y)) + ".");
                builder.AppendLine(HydroSensorSignalActive(cell.x, cell.y) ? "Sensor signal: green." : "Sensor signal: red.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.GermSensor)
            {
                builder.AppendLine(techAutomationLogistics ? "Germ sensor. Sends green when local germs match the condition." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.GermSensor, GermSensorSignalActive(cell.x, cell.y)));
                builder.AppendLine("Local germs " + Mathf.RoundToInt(germs[cell.x, cell.y] * 100f) + "/" + Mathf.RoundToInt(GermSensorThresholdAt(cell.x, cell.y) * 100f) + "%.");
                builder.AppendLine("Signal condition " + ThresholdSensorConditionName(ThresholdSensorConditionAt(cell.x, cell.y)) + ".");
                builder.AppendLine(GermSensorSignalActive(cell.x, cell.y) ? "Sensor signal: green." : "Sensor signal: red.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.WeightPlate)
            {
                builder.AppendLine(techAutomationLogistics ? "Weight plate. Sends green when mass on the tile matches the condition." : "Locked: research Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.WeightPlate, WeightPlateSignalActive(cell.x, cell.y)));
                builder.AppendLine("Plate mass " + WeightPlateMassAt(cell.x, cell.y).ToString("0.#") + "/" + WeightPlateThresholdAt(cell.x, cell.y).ToString("0") + " kg.");
                builder.AppendLine("Signal condition " + ThresholdSensorConditionName(ThresholdSensorConditionAt(cell.x, cell.y)) + ".");
                builder.AppendLine(WeightPlateSignalActive(cell.x, cell.y) ? "Sensor signal: green." : "Sensor signal: red.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.CritterSensor)
            {
                int detected = CountCrittersForSensor(cell);
                builder.AppendLine(techFoodPreparation && techAutomationLogistics ? "Critter sensor. Sends green when critters and eggs match the condition." : "Locked: research Food Preparation and Automation Logistics.");
                builder.AppendLine(AutomationSensorReadinessText(cell, CellKind.CritterSensor, CritterSensorSignalActive(cell.x, cell.y), requiresFoodPreparation: true));
                builder.AppendLine("Detected " + detected + "/" + CritterSensorThresholdAt(cell.x, cell.y).ToString("0") + "  Signal " + (CritterSensorSignalActive(cell.x, cell.y) ? "green" : "red"));
                builder.AppendLine("Signal condition " + ThresholdSensorConditionName(ThresholdSensorConditionAt(cell.x, cell.y)) + ".");
                builder.AppendLine(RoomAt(cell.x, cell.y) != null && RoomAt(cell.x, cell.y).Enclosed ? "Scope: sealed room." : "Scope: " + CritterSensorRange + " tile radius.");
                builder.AppendLine(HasAutomationWireAccess(cell) ? "Automation wire linked." : "Needs adjacent or under-floor Automation Wire.");
            }

            if (cells[cell.x, cell.y] == CellKind.CritterFeeder)
            {
                builder.AppendLine(techFoodPreparation ? "Critter feeder. Dispenses stored dirt, algae, or polluted dirt to hatches, and algae to dreckos." : "Locked: research Food Preparation.");
                builder.AppendLine(CritterFeederReadinessText(cell));
                builder.AppendLine("Feed stock " + HatchFeedStorageAmount().ToString("0") + " kg  Meals " + hatchFeederMeals + "  Fed " + hatchFeederFoodConsumed.ToString("0.0") + " kg");
                builder.AppendLine("Nearby hatches " + CountHatchesForFeeder(cell) + "  Dreckos " + CountDreckosForFeeder(cell) + "  Range " + CritterFeederRange + " tiles");
                builder.AppendLine(RoomAt(cell.x, cell.y) != null && RoomAt(cell.x, cell.y).Enclosed ? "Scope: sealed room." : "Scope: " + CritterFeederRange + " tile radius.");
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidBridge)
            {
                BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
                builder.AppendLine("Liquid bridge. Routes liquid along the configured direction without mixing through the bridge tile.");
                builder.AppendLine("Bridge direction " + BridgeDirectionName(direction) + ".");
                builder.AppendLine(LiquidBridgePairStatus(cell, BridgeInputOffset(direction), BridgeOutputOffset(direction), BridgeDirectionStatusPrefix(direction)));
                builder.AppendLine("Bridge moved " + liquidBridgeMovedMass.ToString("0.0") + " kg liquid.");
            }

            if (cells[cell.x, cell.y] == CellKind.GasBridge)
            {
                BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
                builder.AppendLine(techAirSystems ? "Gas bridge. Routes gas along the configured direction without mixing through the bridge tile." : "Locked: research Air Systems.");
                builder.AppendLine("Bridge direction " + BridgeDirectionName(direction) + ".");
                builder.AppendLine(GasBridgePairStatus(cell, BridgeInputOffset(direction), BridgeOutputOffset(direction), BridgeDirectionStatusPrefix(direction)));
                builder.AppendLine("Bridge moved " + gasBridgeMovedMass.ToString("0.00") + " kg gas.");
            }

            if (cells[cell.x, cell.y] == CellKind.ShippingBridge)
            {
                BridgeDirection direction = BridgeDirectionAt(cell.x, cell.y);
                builder.AppendLine(techAutomationLogistics ? "Shipping bridge. Routes rail packets along the configured direction without crossing through the bridge tile." : "Locked: research Automation Logistics.");
                builder.AppendLine("Bridge direction " + BridgeDirectionName(direction) + ".");
                builder.AppendLine(ShippingBridgePairStatus(cell, BridgeInputOffset(direction), BridgeOutputOffset(direction), BridgeDirectionStatusPrefix(direction)));
                builder.AppendLine("Bridge moved " + shippingBridgeMovedMass.ToString("0.0") + " kg resources.");
                builder.AppendLine(ShippingBridgeReadinessText(cell));
            }

            if (liquidPipe[cell.x, cell.y])
            {
                LiquidPipeKind kind = liquidPipeKind[cell.x, cell.y];
                float totalLiquid = LiquidPipeTotal(cell.x, cell.y);
                builder.AppendLine(LiquidPipeKindName(kind) + ": " + totalLiquid.ToString("0.0") + "/" + LiquidPipeCapacity.ToString("0") + " kg liquid  Clean " + pipeWater[cell.x, cell.y].ToString("0.0") + " kg  Germs " + Mathf.RoundToInt(pipeWaterGerms[cell.x, cell.y] * 100f) + "%  Polluted " + pipePollutedWater[cell.x, cell.y].ToString("0.0") + " kg  P-Water germs " + Mathf.RoundToInt(pipePollutedWaterGerms[cell.x, cell.y] * 100f) + "%  Petroleum " + pipePetroleum[cell.x, cell.y].ToString("0.0") + " kg  Temp " + temperature[cell.x, cell.y].ToString("0") + " C");
                builder.AppendLine("Heat transfer " + LiquidPipeHeatTransferCoefficient(kind).ToString("0.000") + "  Pipe type " + LiquidPipeKindName(kind));
                if (totalLiquid > PipePhaseRuptureMinimumMass)
                {
                    float freezeLimit = LiquidPipeFreezeLimit(cell.x, cell.y);
                    float boilLimit = LiquidPipeBoilLimit(cell.x, cell.y);
                    if (temperature[cell.x, cell.y] < freezeLimit)
                    {
                        builder.AppendLine("Pipe contents freezing: liquid pipe will rupture.");
                    }
                    else if (temperature[cell.x, cell.y] > boilLimit)
                    {
                        builder.AppendLine("Pipe contents boiling: liquid pipe will rupture.");
                    }
                    else
                    {
                        builder.AppendLine("Pipe contents stable between " + freezeLimit.ToString("0") + " C and " + boilLimit.ToString("0") + " C.");
                    }
                }

                builder.AppendLine("Pipe bursts " + pipeBurstEvents + "  Liquid released " + pipeBurstWater.ToString("0.0") + " kg  Frozen/boiled " + frozenPipeBursts + "/" + boiledPipeBursts);
            }

            if (gasPipe[cell.x, cell.y])
            {
                GasPipeKind kind = gasPipeKind[cell.x, cell.y];
                builder.AppendLine(GasPipeKindName(kind) + ": " + GasPipeTotal(cell.x, cell.y).ToString("0.00") + "/" + GasPipeCapacity.ToString("0") + " kg  Temp " + temperature[cell.x, cell.y].ToString("0.0") + " C");
                builder.AppendLine("Heat transfer " + GasPipeHeatTransferCoefficient(kind).ToString("0.000") + "  Pipe type " + GasPipeKindName(kind));
                builder.AppendLine("Pipe O2 " + gasPipeOxygen[cell.x, cell.y].ToString("0.00") + " CO2 " + gasPipeCarbonDioxide[cell.x, cell.y].ToString("0.00") + " PO2 " + gasPipePollutedOxygen[cell.x, cell.y].ToString("0.00"));
                builder.AppendLine("Pipe H2 " + gasPipeHydrogen[cell.x, cell.y].ToString("0.00") + " Steam " + gasPipeSteam[cell.x, cell.y].ToString("0.00") + " Cl " + gasPipeChlorine[cell.x, cell.y].ToString("0.00") + " NG " + gasPipeNaturalGas[cell.x, cell.y].ToString("0.00") + " Sour " + gasPipeSourGas[cell.x, cell.y].ToString("0.00") + " Purity " + Mathf.RoundToInt(PipeHydrogenPurity(cell.x, cell.y) * 100f) + "%  Germs " + Mathf.RoundToInt(gasPipeGerms[cell.x, cell.y] * 100f) + "%");
                if (IsChlorineSterilizingGasConduitAt(cell))
                {
                    builder.AppendLine("Chlorine in stored gas is sterilizing gas germs.");
                }

                if (IsGasPipeSteamCondensing(cell.x, cell.y))
                {
