            if (cells[cell.x, cell.y] == CellKind.Lavatory)
            {
                builder.AppendLine("Flush toilet. Uses clean water and sends polluted water to plumbing.");
                builder.AppendLine("Clean water " + CleanWaterAvailableForMachine(cell).ToString("0.0") + " kg available  Polluted storage " + pollutedWater.ToString("0.0") + " kg  PW germs " + Mathf.RoundToInt(pollutedWaterGerms * 100f) + "%");
                builder.AppendLine("Lavatory uses " + lavatoryUses + "  Water " + lavatoryWaterUsed.ToString("0.0") + " kg  Output " + lavatoryPollutedWaterProduced.ToString("0.0") + " kg");
                builder.AppendLine(LavatoryReadinessText(cell));
                builder.AppendLine(RoomKindAt(cell.x, cell.y) == RoomKind.Washroom ? "Washroom hygiene bonus active." : "Place with a Wash Basin or Hand Sanitizer to form a Washroom.");
            }

            if (cells[cell.x, cell.y] == CellKind.Shower)
            {
                builder.AppendLine("Hygiene fixture. Uses clean water to remove germs and stress.");
                builder.AppendLine("Clean water " + CleanWaterAvailableForMachine(cell).ToString("0.0") + " kg available  Polluted storage " + pollutedWater.ToString("0.0") + " kg  PW germs " + Mathf.RoundToInt(pollutedWaterGerms * 100f) + "%");
                builder.AppendLine("Showers " + showersTaken + "  Water " + showerWaterUsed.ToString("0.0") + " kg  Output " + showerPollutedWaterProduced.ToString("0.0") + " kg");
                builder.AppendLine(ShowerReadinessText(cell));
                builder.AppendLine(RoomKindAt(cell.x, cell.y) == RoomKind.Washroom ? "Washroom hygiene bonus active." : "Place with toilets, a Wash Basin, or a Hand Sanitizer to form a Washroom.");
            }

            if (cells[cell.x, cell.y] == CellKind.WashBasin)
            {
                builder.AppendLine("Hygiene station. Duplicants wash germy hands here before sickness builds.");
                builder.AppendLine("Clean water " + CleanWaterAvailableForMachine(cell).ToString("0.0") + " kg available  Polluted storage " + pollutedWater.ToString("0.0") + " kg  PW germs " + Mathf.RoundToInt(pollutedWaterGerms * 100f) + "%");
                builder.AppendLine("Hands washed " + handsWashed + "  Uses " + WashBasinWaterUse.ToString("0.0") + " kg water.");
                builder.AppendLine(WashStationReadinessText(cell));
                builder.AppendLine(RoomKindAt(cell.x, cell.y) == RoomKind.Washroom ? "Washroom hygiene bonus active." : "Place with an outhouse to form a Washroom.");
            }

            if (cells[cell.x, cell.y] == CellKind.HandSanitizer)
            {
                builder.AppendLine("Waterless hygiene station. Uses bleach stone to remove germs from duplicants.");
                builder.AppendLine("Bleach stone " + bleachStone.ToString("0.0") + " kg  Uses " + HandSanitizerBleachStoneUse.ToString("0.0") + " kg per wash.");
                builder.AppendLine("Sanitizer uses " + handSanitizerUses + "  Bleach consumed " + handSanitizerBleachStoneUsed.ToString("0.0") + " kg.");
                builder.AppendLine(WashStationReadinessText(cell));
                builder.AppendLine(RoomKindAt(cell.x, cell.y) == RoomKind.Washroom ? "Washroom hygiene bonus active." : "Place with toilets to form a Washroom.");
            }

            if (cells[cell.x, cell.y] == CellKind.Compost)
            {
                builder.AppendLine("Processes polluted dirt into reusable dirt.");
                builder.AppendLine("Polluted dirt " + pollutedDirt.ToString("0.0") + " kg  Loose " + TotalLoosePollutedDirt().ToString("0.0") + " kg");
                builder.AppendLine("Composted " + compostedPollutedDirt.ToString("0.0") + "/6 kg");
                builder.AppendLine(CompostReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.MassageTable)
            {
                builder.AppendLine("Stress relief station. One duplicant relaxes here at a time.");
                builder.AppendLine(RecreationReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.WaterCooler)
            {
                builder.AppendLine("Recreation fixture. Uses a little clean water for downtime stress care.");
                builder.AppendLine("Clean water " + CleanWaterAvailableForMachine(cell).ToString("0.0") + " kg available  Visits " + waterCoolerVisits + "  Used " + waterCoolerWaterUsed.ToString("0.0") + " kg");
                builder.AppendLine(RecreationReadinessText(cell));
                builder.AppendLine(RoomKindAt(cell.x, cell.y) == RoomKind.RecreationRoom || RoomKindAt(cell.x, cell.y) == RoomKind.GreatHall
                    ? "Room recreation bonus active."
                    : "Place in a sealed Recreation Room or Great Hall for better morale.");
            }

            if (cells[cell.x, cell.y] == CellKind.ArcadeCabinet)
            {
                builder.AppendLine("Powered recreation fixture. Uses plastic parts for high morale downtime.");
                builder.AppendLine("Plastic " + plastic.ToString("0.0") + " kg  Sessions " + arcadeSessions + "  Used " + arcadePlasticUsed.ToString("0.00") + " kg");
                builder.AppendLine(RecreationReadinessText(cell));
                builder.AppendLine(RoomKindAt(cell.x, cell.y) == RoomKind.RecreationRoom || RoomKindAt(cell.x, cell.y) == RoomKind.GreatHall
                    ? "Room recreation bonus active."
                    : "Place in a sealed Recreation Room or Great Hall for better morale.");
            }

            if (cells[cell.x, cell.y] == CellKind.ManualAirlock)
            {
                builder.AppendLine(airlockOpen[cell.x, cell.y] ? "Door state: open. Duplicants and gas can pass." : "Door state: closed. Pathing and pressure are sealed.");
                builder.AppendLine("Duplicant access " + DoorAccessModeName(DoorAccessModeAt(cell.x, cell.y)) + "  Changes " + doorAccessChanges + ".");
                builder.AppendLine("Gas permeability " + TileGasPermeability(cell.x, cell.y).ToString("0.00") + "  Conductivity " + TileThermalConductivity(cell.x, cell.y).ToString("0.000"));
                builder.AppendLine("Door toggles " + airlockToggles + ".");
            }

            if (cells[cell.x, cell.y] == CellKind.MechanizedAirlock)
            {
                bool doorOpen = IsMechanizedAirlockOpen(cell);
                bool controlled = HasAutomationControl(cell);
                builder.AppendLine("Mechanized airlock. Defaults open, but a red automation signal closes it to seal pathing, gas, and heat.");
                builder.AppendLine(doorOpen
                    ? "Door state: open by automation. Duplicants and gas can pass."
                    : CanUseEquipment(cell)
                    ? "Door state: closed by automation. Pathing and pressure are sealed."
                    : "Door state: closed by damage or disabled equipment. Repair or enable it before automation can open it.");
                if (!CanUseEquipment(cell))
                {
                    builder.AppendLine(IsBrokenEquipment(cell)
                        ? "Automation: door is damaged and cannot respond."
                        : "Automation: door cannot respond until unblocked.");
                    builder.AppendLine("Duplicant access blocked: repair or enable the door before permissions count.");
                }
                else
                {
                    builder.AppendLine(controlled
                        ? HasAutomationSignal(cell) ? "Automation: green signal opens the door." : "Automation: red signal closes the door."
                        : "Automation: unlinked, default open.");
                }
                builder.AppendLine("Duplicant access " + DoorAccessModeName(DoorAccessModeAt(cell.x, cell.y)) + "  Changes " + doorAccessChanges + ".");
                builder.AppendLine("Gas permeability " + TileGasPermeability(cell.x, cell.y).ToString("0.00") + "  Conductivity " + TileThermalConductivity(cell.x, cell.y).ToString("0.000"));
            }

            if (cells[cell.x, cell.y] == CellKind.SpaceHeater)
            {
                builder.AppendLine("Consumes power to warm cold rooms.");
                builder.AppendLine(SpaceHeaterReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.LiquidTepidizer)
            {
                builder.AppendLine(techThermalEngineering ? "Liquid tepidizer. Heats submerged liquid until it reaches the target temperature." : "Locked: research Thermal Engineering.");
                if (TryGetLiquidTepidizerLiquidSummary(cell, out float liquidMass, out float averageTemperature))
                {
                    builder.AppendLine("Nearby liquid " + liquidMass.ToString("0.0") + " kg  Average " + averageTemperature.ToString("0.0") + " C  Target " + LiquidTepidizerTargetTemperature.ToString("0") + " C.");
                }
                else
                {
                    builder.AppendLine("Needs liquid in this tile or adjacent tiles.");
                }

                builder.AppendLine("Heat added " + liquidTepidizerHeatAdded.ToString("0.0") + "  Radius " + LiquidTepidizerRadius + " tiles");
                builder.AppendLine(LiquidTepidizerReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.ThermoRegulator)
            {
                builder.AppendLine(techThermalEngineering ? "Thermo regulator. Moves gas between adjacent gas pipes, cooling the output pipe and dumping heat nearby. After super coolant loops, it condenses piped oxygen and hydrogen into cryogenic propellant." : "Locked: research Thermal Engineering.");
                if (TryFindAdjacentGasPipeWithGas(cell, out Vector2Int inputPipe))
                {
                    builder.AppendLine("Input gas pipe " + GasPipeTotal(inputPipe.x, inputPipe.y).ToString("0.00") + " kg  O2 " + gasPipeOxygen[inputPipe.x, inputPipe.y].ToString("0.00") + "  CO2 " + gasPipeCarbonDioxide[inputPipe.x, inputPipe.y].ToString("0.00") + "  H2 " + gasPipeHydrogen[inputPipe.x, inputPipe.y].ToString("0.00") + "  Temp " + temperature[inputPipe.x, inputPipe.y].ToString("0") + " C");
                    builder.AppendLine(TryFindAdjacentGasPipeWithSpaceExcluding(cell, inputPipe, out Vector2Int outputPipe)
                        ? "Output gas pipe free " + (GasPipeCapacity - GasPipeTotal(outputPipe.x, outputPipe.y)).ToString("0.00") + " kg  Temp " + temperature[outputPipe.x, outputPipe.y].ToString("0") + " C"
                        : "Needs a different adjacent gas pipe with output space.");
                }
                else
                {
                    builder.AppendLine("Needs adjacent gas pipe containing gas.");
                }

                builder.AppendLine("Processed gas " + thermoRegulatorGasCooled.ToString("0.00") + " kg  Cooling " + ThermoRegulatorCoolingPerKg.ToString("0.00") + " C/kg");
                builder.AppendLine("Cryogenic propellant " + cryogenicPropellant.ToString("0.0") + " kg  Produced " + cryogenicPropellantProduced.ToString("0.0") + "/" + CryogenicPropellantProductionTarget.ToString("0.0") + " kg  O2 pipe " + PipedOxygenAround(cell).ToString("0.00") + " kg  H2 pipe " + PipedHydrogenAround(cell).ToString("0.00") + " kg");
                builder.AppendLine(ThermoRegulatorReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.ThermoAquatuner)
            {
                builder.AppendLine(techThermalEngineering ? "Thermo aquatuner. Moves liquid between adjacent liquid pipes, cooling the output pipe and dumping heat nearby. Super coolant charge improves late-game cooling." : "Locked: research Thermal Engineering.");
                if (TryFindAdjacentLiquidPipeWithAnyLiquid(cell, out Vector2Int inputPipe))
                {
                    builder.AppendLine("Input pipe liquid " + LiquidPipeTotal(inputPipe.x, inputPipe.y).ToString("0.0") + " kg  Clean " + pipeWater[inputPipe.x, inputPipe.y].ToString("0.0") + "  Polluted " + pipePollutedWater[inputPipe.x, inputPipe.y].ToString("0.0") + "  Petroleum " + pipePetroleum[inputPipe.x, inputPipe.y].ToString("0.0") + "  PW germs " + Mathf.RoundToInt(pipePollutedWaterGerms[inputPipe.x, inputPipe.y] * 100f) + "%  Temp " + temperature[inputPipe.x, inputPipe.y].ToString("0") + " C");
                    builder.AppendLine(TryFindAdjacentLiquidPipeWithSpaceExcluding(cell, inputPipe, out Vector2Int outputPipe)
                        ? "Output pipe free " + LiquidPipeFreeCapacity(outputPipe.x, outputPipe.y).ToString("0.0") + " kg  Temp " + temperature[outputPipe.x, outputPipe.y].ToString("0") + " C"
                        : "Needs a different adjacent liquid pipe with output space.");
                }
                else
                {
                    builder.AppendLine("Needs adjacent liquid pipe containing liquid.");
                }

                float shownCoolingMultiplier = superCoolant > 0.001f ? SuperCoolantCoolingMultiplier : 1f;
                builder.AppendLine("Processed liquid " + thermoAquatunerWaterCooled.ToString("0.0") + " kg  Cooling " + ThermoAquatunerCoolingPerKg.ToString("0.00") + " C/kg x" + shownCoolingMultiplier.ToString("0.00"));
                builder.AppendLine("Super coolant " + superCoolant.ToString("0.0") + " kg  Used " + superCoolantUsed.ToString("0.00") + " kg  Stable " + Mathf.RoundToInt(superCoolantCoolingSeconds) + "/" + Mathf.RoundToInt(SuperCoolantLoopTargetSeconds) + "s");
                builder.AppendLine(ThermoAquatunerReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.Wheezewort)
            {
                float localHydrogen = HydrogenAround(cell, 2);
                float localGas = TileGasTotal(cell.x, cell.y);
                float localTemperature = AverageTemperatureAround(cell, WheezewortCoolingRadius);
                builder.AppendLine("Natural cooling plant. Removes heat from nearby gas without power.");
                builder.AppendLine("Cooling " + wheezewortCoolingApplied.ToString("0.00") + " C applied  Radius " + WheezewortCoolingRadius + " tiles");
                builder.AppendLine("Local gas " + localGas.ToString("0.00") + " kg  H2 " + localHydrogen.ToString("0.00") + " kg  Temp " + localTemperature.ToString("0.0") + " C");
                builder.AppendLine(localTemperature <= WheezewortDormantTemperature
                    ? "Dormant below " + WheezewortDormantTemperature.ToString("0") + " C."
                    : localHydrogen >= WheezewortHydrogenThreshold ? "Hydrogen cooling bonus active." : "Works in gas; hydrogen greatly improves cooling.");
                builder.AppendLine(WheezewortReadinessText(cell));
            }

            if (cells[cell.x, cell.y] == CellKind.AntiEntropyThermoNullifier)
            {
                float availableHydrogen = AntiEntropyHydrogenAvailable(cell);
                float localTemperature = AverageTemperatureAround(cell, AntiEntropyCoolingRadius);
                builder.AppendLine("Anti Entropy Thermo-Nullifier. Consumes hydrogen gas to delete heat from a sealed chamber.");
                builder.AppendLine("Cooling " + antiEntropyCoolingApplied.ToString("0.00") + "/" + AntiEntropyCoolingTarget.ToString("0.00") + " C applied  H2 consumed " + antiEntropyHydrogenConsumed.ToString("0.00") + "/" + AntiEntropyHydrogenTarget.ToString("0.00") + " kg");
                builder.AppendLine("Available H2 " + availableHydrogen.ToString("0.00") + " kg  Pipe H2 " + PipedHydrogenAround(cell).ToString("0.00") + " kg  Local temp " + localTemperature.ToString("0.0") + " C  Radius " + AntiEntropyCoolingRadius + " tiles");
                builder.AppendLine(CanAntiEntropyThermoNullifierRun(cell)
                    ? "Nullifier active: hydrogen feed is deleting heat."
                    : localTemperature <= AntiEntropyDormantTemperature ? "Dormant below " + AntiEntropyDormantTemperature.ToString("0") + " C." : "Needs hydrogen from a gas vent or pocket.");
                builder.AppendLine(AntiEntropyReadinessText(cell));
            }

            if (TryGetDeconstructTarget(cell, out CellKind deconstructKind, out bool removePower, out bool removeAutomation, out bool removeLiquid, out bool removeGas, out bool removeShipping))
            {
                Job preview = new Job(JobType.Deconstruct, cell, 1f)
                {
                    BuildKind = deconstructKind,
                    RemovePowerWire = removePower,
                    RemoveAutomationWire = removeAutomation,
                    RemoveLiquidPipe = removeLiquid,
                    RemoveGasPipe = removeGas,
                    RemoveShippingRail = removeShipping
                };
                builder.AppendLine("Deconstruct target: " + DeconstructTargetLabel(preview) + " returns about half its materials.");
                builder.AppendLine(DeconstructReadinessText(cell));
            }

            Job job = FindAnyJobAt(cell);
            if (job != null)
            {
                builder.AppendLine("Job: " + JobLabel(job));
                if (!string.IsNullOrEmpty(job.TargetWorkerName))
                {
                    builder.AppendLine("Target " + job.TargetWorkerName);
                }

                builder.AppendLine("Priority " + JobPriority(job));
                if (job.YellowAlert)
                {
                    builder.AppendLine("Yellow Alert: duplicants may interrupt routine errands.");
                }

                builder.AppendLine(JobWaitText(job));
                string jobPolicyTextLine = JobPolicyText(job);
                if (!string.IsNullOrEmpty(jobPolicyTextLine))
                {
                    builder.AppendLine(jobPolicyTextLine);
                }

                builder.AppendLine("Progress " + Mathf.RoundToInt(job.Progress / job.WorkRequired * 100f) + "%");
                builder.AppendLine(JobReachabilityText(job));
                string dispatchCandidateText = JobDispatchCandidateText(job);
                if (!string.IsNullOrEmpty(dispatchCandidateText))
                {
                    builder.AppendLine(dispatchCandidateText);
                }

                if (HasJobMaterialCost(job))
                {
                    builder.AppendLine("Reserved materials " + BuildCostText(job.DirtCost, job.MetalCost, job.AlgaeCost, job.RefinedMetalCost));
                }
            }

            Worker worker = WorkerAt(cell);
            if (worker != null)
            {
                builder.AppendLine(worker.Name + " - " + worker.Activity);
                builder.AppendLine("Health " + worker.Health.ToString("0") + "%  Calories " + worker.Calories.ToString("0"));
                builder.AppendLine("Breath " + worker.Breath.ToString("0") + "%  Local breathable air " + BreathableAirAt(worker.Cell.x, worker.Cell.y).ToString("0.00") + "  Sour " + sourGas[worker.Cell.x, worker.Cell.y].ToString("0.00"));
                string holdingBreathText = WorkerHoldingBreathText(worker);
                if (!string.IsNullOrEmpty(holdingBreathText))
                {
                    builder.AppendLine(holdingBreathText);
                }

                string breathingGearOxygenText = WorkerBreathingGearOxygenText(worker);
                if (!string.IsNullOrEmpty(breathingGearOxygenText))
                {
                    builder.AppendLine(breathingGearOxygenText);
                }

                builder.AppendLine("Environment danger " + Mathf.RoundToInt(EnvironmentalDangerScore(worker.Cell) * 100f) + "%  Sour exposure " + sourGasExposureSeconds.ToString("0") + "s/" + sourGasHealthDamage.ToString("0.0"));
                float localRadiation = RadiationAt(worker.Cell.x, worker.Cell.y);
                builder.AppendLine("Radiation " + Mathf.RoundToInt(localRadiation * 100f) + "%  Lead suit " + (worker.LeadSuitEquipped ? "equipped" : "none"));
                builder.AppendLine("Outfit " + WorkerOutfitName(worker.Outfit) + "  Stock warm/cool/snazzy " + warmOutfits.ToString("0.0") + "/" + coolOutfits.ToString("0.0") + "/" + snazzySuits.ToString("0.0"));
                builder.AppendLine("Stress " + worker.Stress.ToString("0") + "%  Fatigue " + worker.Fatigue.ToString("0") + "%");
                string drowsyText = WorkerDrowsyText(worker);
                if (!string.IsNullOrEmpty(drowsyText))
                {
                    builder.AppendLine(drowsyText);
                }

                builder.AppendLine("Bladder " + worker.Bladder.ToString("0") + "%  Exposure " + worker.GermExposure.ToString("0") + "%");
                builder.AppendLine("Sickness " + worker.Sickness.ToString("0") + "%");
                builder.AppendLine(WorkerDiseaseText(worker));
                if (worker.FoodSafeHandsSeconds > 0f)
                {
                    builder.AppendLine("Food handling prep " + worker.FoodSafeHandsSeconds.ToString("0") + "s: cooking contamination reduced.");
                }

                string treatmentDiagnosticText = WorkerTreatmentDiagnosticText(worker);
                if (!string.IsNullOrEmpty(treatmentDiagnosticText))
                {
                    builder.AppendLine(treatmentDiagnosticText);
                }

                string nauseousText = WorkerNauseousText(worker);
                if (!string.IsNullOrEmpty(nauseousText))
                {
                    builder.AppendLine(nauseousText);
                }

                if (worker.HeatExposure > 0.5f || worker.ChillExposure > 0.5f)
                {
                    builder.AppendLine("Thermal exposure heat " + worker.HeatExposure.ToString("0") + "%  chill " + worker.ChillExposure.ToString("0") + "%");
                    builder.AppendLine("Thermal injuries heat/chill " + heatStrokeCases + "/" + hypothermiaCases + "  Damage " + thermalHealthDamage.ToString("0.0"));
                }

                builder.AppendLine(WorkerSkillText(worker));
                builder.AppendLine(WorkerTraitText(worker));
                builder.AppendLine(WorkerStressReactionText(worker));
                builder.AppendLine(WorkerOverjoyedResponseText(worker));
                builder.AppendLine(WorkerInterestText(worker));
                builder.AppendLine(WorkerRoleText(worker));
                builder.AppendLine("Personal schedule " + WorkerSchedulePlanLabel(worker));
                builder.AppendLine("Food policy " + WorkerFoodPolicyPlanLabel(worker));
                string nextErrandText = WorkerNextErrandText(worker);
                if (!string.IsNullOrEmpty(nextErrandText))
                {
                    builder.AppendLine(nextErrandText);
                }

                builder.AppendLine(WorkerMoraleText(worker));
                string drabSurroundingsText = WorkerDrabSurroundingsText(worker);
                if (!string.IsNullOrEmpty(drabSurroundingsText))
                {
                    builder.AppendLine(drabSurroundingsText);
                }

                string commuteText = WorkerCommuteText(worker);
                if (!string.IsNullOrEmpty(commuteText))
                {
                    builder.AppendLine(commuteText);
                }

                string sleepDisruptionText = WorkerSleepDisruptionText(worker);
                if (!string.IsNullOrEmpty(sleepDisruptionText))
                {
                    builder.AppendLine(sleepDisruptionText);
                }

                string brightSleepText = WorkerBrightSleepText(worker);
                if (!string.IsNullOrEmpty(brightSleepText))
                {
                    builder.AppendLine(brightSleepText);
                }

                string soreBackText = WorkerSoreBackText(worker);
                if (!string.IsNullOrEmpty(soreBackText))
                {
                    builder.AppendLine(soreBackText);
                }

                string exhaustedCollapseText = WorkerExhaustedCollapseText(worker);
                if (!string.IsNullOrEmpty(exhaustedCollapseText))
                {
                    builder.AppendLine(exhaustedCollapseText);
                }

                string narcolepsyText = WorkerNarcolepsyText(worker);
                if (!string.IsNullOrEmpty(narcolepsyText))
                {
                    builder.AppendLine(narcolepsyText);
                }

                string flatulenceText = WorkerFlatulenceText(worker);
                if (!string.IsNullOrEmpty(flatulenceText))
                {
                    builder.AppendLine(flatulenceText);
                }

                string soggyFeetText = WorkerSoggyFeetText(worker);
                if (!string.IsNullOrEmpty(soggyFeetText))
                {
                    builder.AppendLine(soggyFeetText);
                }

                string soppingWetText = WorkerSoppingWetText(worker);
                if (!string.IsNullOrEmpty(soppingWetText))
                {
                    builder.AppendLine(soppingWetText);
                }

                string yuckyLungsText = WorkerYuckyLungsText(worker);
                if (!string.IsNullOrEmpty(yuckyLungsText))
                {
                    builder.AppendLine(yuckyLungsText);
                }

                string poppedEardrumsText = WorkerPoppedEardrumsText(worker);
                if (!string.IsNullOrEmpty(poppedEardrumsText))
                {
                    builder.AppendLine(poppedEardrumsText);
                }

                string irritatedEyesText = WorkerIrritatedEyesText(worker);
                if (!string.IsNullOrEmpty(irritatedEyesText))
                {
                    builder.AppendLine(irritatedEyesText);
                }

                string scaldedText = WorkerScaldedText(worker);
                if (!string.IsNullOrEmpty(scaldedText))
                {
                    builder.AppendLine(scaldedText);
                }

                string thermalDiscomfortText = WorkerThermalDiscomfortText(worker);
                if (!string.IsNullOrEmpty(thermalDiscomfortText))
                {
                    builder.AppendLine(thermalDiscomfortText);
                }

                string allergicReactionText = WorkerAllergicReactionText(worker);
                if (!string.IsNullOrEmpty(allergicReactionText))
                {
                    builder.AppendLine(allergicReactionText);
                }

                string suitFatigueText = WorkerSuitFatigueText(worker);
                if (!string.IsNullOrEmpty(suitFatigueText))
                {
                    builder.AppendLine(suitFatigueText);
                }

                string germyHandsText = WorkerGermyHandsText(worker);
                if (!string.IsNullOrEmpty(germyHandsText))
                {
                    builder.AppendLine(germyHandsText);
                }

                string darkStressText = WorkerDarkStressText(worker);
                if (!string.IsNullOrEmpty(darkStressText))
                {
                    builder.AppendLine(darkStressText);
                }

                string schedulePressure = WorkerSchedulePressureText(worker);
                if (!string.IsNullOrEmpty(schedulePressure))
                {
                    builder.AppendLine(schedulePressure);
                }

                string ateWithoutTableText = WorkerAteWithoutTableText(worker);
                if (!string.IsNullOrEmpty(ateWithoutTableText))
                {
                    builder.AppendLine(ateWithoutTableText);
                }

                string accidentShameText = WorkerAccidentShameText(worker);
                if (!string.IsNullOrEmpty(accidentShameText))
                {
                    builder.AppendLine(accidentShameText);
                }

                if (foodFreshness < StaleFoodFreshnessThreshold || foodGerms >= FoodGermExposureThreshold)
                {
                    builder.AppendLine("Food risk " + Mathf.RoundToInt(foodFreshness * 100f) + "% fresh  Germs " + Mathf.RoundToInt(foodGerms * 100f) + "%  Stale meals " + staleMealsEaten + "  Contaminated meals " + contaminatedMealsEaten + "  Poisonings " + foodPoisoningCases);
                }

                builder.AppendLine("Local decor " + Mathf.RoundToInt(DecorScoreAt(worker.Cell.x, worker.Cell.y) * 100f) + "%");
                if (worker.Health <= 0f)
                {
                    builder.AppendLine("Incapacitated " + worker.IncapacitatedSeconds.ToString("0.0") + "s. Needs rescue to a Medical Cot.");
                }

                if (worker.StressBreakSeconds > 0f)
                {
                    builder.AppendLine("Stress break " + WorkerStressReactionName(worker.StressReaction) + " " + worker.StressBreakSeconds.ToString("0.0") + "s remaining");
                }
            }

            return builder.ToString();
        }

        private string TechSummary()
        {
            StringBuilder builder = new StringBuilder();
            AppendTechSummary(builder, ResearchFocus.AirSystems, "Air");
            builder.Append(" | ");
            AppendTechSummary(builder, ResearchFocus.FoodPreparation, "Food");
            builder.Append(" | ");
            AppendTechSummary(builder, ResearchFocus.PowerRegulation, "Power");
            builder.Append(" | ");
            AppendTechSummary(builder, ResearchFocus.AutomationLogistics, "Auto");
            builder.Append(" | ");
            AppendTechSummary(builder, ResearchFocus.ThermalEngineering, "Thermal");
            builder.Append(" | ");
            AppendTechSummary(builder, ResearchFocus.AdvancedPower, "AdvP");
            builder.Append(" | ");
            AppendTechSummary(builder, ResearchFocus.SpaceSystems, "Space");
            builder.Append(" | Focus ");
            builder.Append(ResearchFocusStatusText());
            return builder.ToString();
        }

        private void AppendTechSummary(StringBuilder builder, ResearchFocus focus, string shortName)
        {
            builder.Append(shortName);
            if (!IsResearchUnlocked(focus))
            {
                builder.Append(" ");
                builder.Append(Mathf.Clamp(ResearchRequirement(focus) - researchPoints, 0f, ResearchRequirement(focus)).ToString("0"));
                builder.Append("RP");
            }
        }

        private string ResearchFocusStatusText()
        {
            NormalizeResearchFocus();
            if (!HasLockedResearch())
            {
                return "complete";
            }

            float required = ResearchRequirement(selectedResearchFocus);
            float remaining = Mathf.Max(0f, required - researchPoints);
            return ResearchFocusName(selectedResearchFocus) + (IsResearchUnlocked(selectedResearchFocus) ? " complete" : " " + remaining.ToString("0") + "RP");
        }

        private void NormalizeResearchFocus()
        {
            int max = Enum.GetValues(typeof(ResearchFocus)).Length - 1;
            selectedResearchFocus = (ResearchFocus)Mathf.Clamp((int)selectedResearchFocus, 0, max);
        }

        private bool HasLockedResearch()
        {
            return !techAirSystems ||
                !techFoodPreparation ||
                !techPowerRegulation ||
                !techAutomationLogistics ||
                !techThermalEngineering ||
                !techAdvancedPower ||
                !techSpaceSystems;
        }

        private void SelectNextLockedResearchFocus()
        {
            if (!HasLockedResearch())
            {
                return;
            }

            NormalizeResearchFocus();
            int focusCount = Enum.GetValues(typeof(ResearchFocus)).Length;
            for (int i = 1; i <= focusCount; i++)
            {
                ResearchFocus candidate = (ResearchFocus)(((int)selectedResearchFocus + i) % focusCount);
                if (!IsResearchUnlocked(candidate))
                {
                    selectedResearchFocus = candidate;
                    return;
                }
            }
        }

        private bool IsResearchUnlocked(ResearchFocus focus)
        {
            switch (focus)
            {
                case ResearchFocus.AirSystems:
                    return techAirSystems;
                case ResearchFocus.FoodPreparation:
                    return techFoodPreparation;
                case ResearchFocus.PowerRegulation:
                    return techPowerRegulation;
                case ResearchFocus.AutomationLogistics:
                    return techAutomationLogistics;
                case ResearchFocus.ThermalEngineering:
                    return techThermalEngineering;
                case ResearchFocus.AdvancedPower:
                    return techAdvancedPower;
                case ResearchFocus.SpaceSystems:
                    return techSpaceSystems;
                default:
                    return false;
            }
        }

        private float ResearchRequirement(ResearchFocus focus)
        {
            switch (focus)
            {
                case ResearchFocus.AirSystems:
                    return 8f;
                case ResearchFocus.FoodPreparation:
                    return 16f;
                case ResearchFocus.PowerRegulation:
                    return 28f;
                case ResearchFocus.AutomationLogistics:
                    return 42f;
                case ResearchFocus.ThermalEngineering:
                    return 52f;
                case ResearchFocus.AdvancedPower:
                    return 62f;
                case ResearchFocus.SpaceSystems:
                    return 74f;
                default:
                    return 8f;
            }
        }

        private float MaxResearchRequirement()
        {
            float max = 0f;
            foreach (ResearchFocus focus in Enum.GetValues(typeof(ResearchFocus)))
            {
                max = Mathf.Max(max, ResearchRequirement(focus));
            }

            return max;
        }

        private string ResearchFocusName(ResearchFocus focus)
        {
            switch (focus)
            {
                case ResearchFocus.AirSystems:
                    return "Air Systems";
                case ResearchFocus.FoodPreparation:
                    return "Food Preparation";
                case ResearchFocus.PowerRegulation:
                    return "Power Regulation";
                case ResearchFocus.AutomationLogistics:
                    return "Automation Logistics";
                case ResearchFocus.ThermalEngineering:
                    return "Thermal Engineering";
                case ResearchFocus.AdvancedPower:
                    return "Advanced Power";
                case ResearchFocus.SpaceSystems:
                    return "Space Systems";
                default:
                    return "Air Systems";
            }
        }

        private int ResearchJobPriority()
        {
            NormalizeResearchFocus();
            if (!HasLockedResearch())
            {
                return 3;
            }

            return IsResearchUnlocked(selectedResearchFocus) ? 4 : 8;
        }

        private string ResearchStationReadinessText(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.ResearchStation)
            {
                return "Research blocked: Research Station missing.";
            }

            if (!HasLockedResearch())
            {
                return "Research complete: all colony technologies unlocked.";
            }

            string disabledBlock = DisabledBuildingBlockText(cell);
            if (!string.IsNullOrEmpty(disabledBlock))
            {
                return disabledBlock;
            }

            if (IsBrokenEquipment(cell))
            {
                return "Research blocked: Research Station needs repair.";
            }

            if (IsEquipmentSubmerged(cell))
            {
                return "Research blocked: Research Station is submerged.";
            }

            if (!HasWireAccess(cell))
            {
                return "Research blocked: needs power wire.";
            }

            if (!HasPoweredCircuit(cell))
            {
                return "Research blocked: wire circuit has no power.";
            }

            if (!MachineAutomationAllows(cell))
            {
                return "Research blocked: automation signal is red.";
            }

            if (power <= 1f)
            {
                return "Research blocked: needs stored power.";
            }

            Job researchJob = FindJobAt(cell, JobType.Research);
            if (researchJob != null)
            {
                return "Research ready: research errand queued. " + JobReachabilityText(researchJob);
            }

            Job testJob = new Job(JobType.Research, cell, 4.8f);
            string routeBlock = JobReachabilityBlockText(
                testJob,
                "Research blocked: ",
                "Research blocked: no reachable duplicant path to station.");
            return string.IsNullOrEmpty(routeBlock)
                ? "Research ready: reachable duplicant can research focused technology."
                : routeBlock;
        }

        private int CountUsableResearchStations()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.ResearchStation && CanPoweredMachineRun(new Vector2Int(x, y)))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private string BuildCrewVitalsText()
        {
            NormalizeSelectedCrewIndex();
            StringBuilder builder = new StringBuilder();
            builder.Append("Crew Vitals ");
            builder.Append(CountActiveWorkers());
            builder.Append("/");
            builder.Append(workers.Count);
            int incapacitated = CountIncapacitatedWorkers();
            if (incapacitated > 0)
            {
                builder.Append("  Down ");
                builder.Append(incapacitated);
            }

            Worker selected = SelectedCrewWorker();
            if (selected != null)
            {
                builder.Append("  Selected ");
                builder.Append(selected.Name);
                builder.Append("  Role ");
                builder.Append(JobCategoryShortName(selected.Role));
                builder.Append("  Shift ");
                builder.Append(CrewScheduleOffsetLabel(selected.ScheduleOffsetSteps));
                builder.Append("  Diet ");
                builder.Append(WorkerFoodPolicyPlanLabel(selected));
            }

            builder.AppendLine();
            Worker riskiest = HighestRiskWorker(out string riskText);
            builder.Append("Worst: ");
            builder.Append(riskiest == null ? "none" : riskiest.Name + " - " + riskText);

            if (workers.Count == 0)
            {
                builder.AppendLine();
                builder.Append("No duplicants.");
                return builder.ToString();
            }

            for (int i = 0; i < workers.Count; i++)
            {
                Worker worker = workers[i];
                builder.AppendLine();
                builder.Append(i == selectedCrewIndex ? "> " : "  ");
                builder.Append(worker.Name);
                builder.Append(" ");
                builder.Append(CrewVitalsLine(worker));
            }

            return builder.ToString();
        }

        private string CrewVitalsLine(Worker worker)
        {
            if (worker == null)
            {
                return string.Empty;
            }

            if (worker.Health <= 0f)
            {
                return "Down " + worker.IncapacitatedSeconds.ToString("0") + "s  " + WorkerRiskText(worker);
            }

            StringBuilder builder = new StringBuilder();
            builder.Append("H");
            builder.Append(worker.Health.ToString("0"));
            builder.Append(" Cal");
            builder.Append(worker.Calories.ToString("0"));
            builder.Append(" S");
            builder.Append(worker.Stress.ToString("0"));
            builder.Append(" F");
            builder.Append(worker.Fatigue.ToString("0"));
            builder.Append(" B");
            builder.Append(worker.Bladder.ToString("0"));
            builder.Append(" M");
            builder.Append(Mathf.Clamp(worker.Morale, 0f, 10f).ToString("0.0"));
            builder.Append("/");
            builder.Append(WorkerMoraleNeed(worker).ToString("0.0"));
            if (worker.Outfit != WorkerOutfit.None)
            {
                builder.Append(" O ");
                builder.Append(WorkerOutfitShortName(worker.Outfit));
            }

            builder.Append(" T ");
            builder.Append(WorkerTraitShortName(worker.Trait));
            builder.Append(" SR ");
            builder.Append(WorkerStressReactionShortName(worker.StressReaction));
            builder.Append(" OJ ");
            builder.Append(WorkerOverjoyedResponseShortName(worker.OverjoyedResponse));
            if (IsWorkerOverjoyed(worker))
            {
                builder.Append(worker.OverjoyedSeconds.ToString("0"));
            }

            if (worker.Disease != WorkerDisease.None)
            {
                builder.Append(" D ");
                builder.Append(WorkerDiseaseShortName(worker.Disease));
            }

            if (worker.NauseousSeconds > 0f)
            {
                builder.Append(" Nausea");
                builder.Append(worker.NauseousSeconds.ToString("0"));
            }

            if (IsWorkerDrowsy(worker))
            {
                builder.Append(worker.Fatigue >= VeryTiredFatigueThreshold ? " Tired" : " Drowsy");
                builder.Append(worker.Fatigue.ToString("0"));
            }

            if (worker.CommuteSeconds >= LongCommuteThresholdSeconds)
            {
                builder.Append(" Commute");
                builder.Append(worker.CommuteSeconds.ToString("0"));
            }

            if (IsWorkerHoldingBreath(worker))
            {
                builder.Append(" Hold");
                builder.Append(worker.Breath.ToString("0"));
            }

            if (SleepDisruptionFactor(worker) > 0f)
            {
                builder.Append(" Snore");
            }

            if (worker.BrightSleepSeconds > 0f)
            {
                builder.Append(" Bright");
                builder.Append(worker.BrightSleepSeconds.ToString("0"));
            }

            if (worker.SoreBackSeconds > 0f)
            {
                builder.Append(" Sore");
                builder.Append(worker.SoreBackSeconds.ToString("0"));
            }

            if (worker.AteWithoutTableSeconds > 0f)
            {
                builder.Append(" NoTable");
                builder.Append(worker.AteWithoutTableSeconds.ToString("0"));
            }

            if (worker.AccidentShameSeconds > 0f)
            {
                builder.Append(" Mess");
                builder.Append(worker.AccidentShameSeconds.ToString("0"));
            }

            if (worker.ExhaustedCollapseSeconds > 0f)
            {
                builder.Append(" Collapse");
                builder.Append(worker.ExhaustedCollapseSeconds.ToString("0"));
            }

            if (worker.NarcolepticNapSeconds > 0f)
            {
                builder.Append(" Nap");
                builder.Append(worker.NarcolepticNapSeconds.ToString("0"));
            }

            if (worker.SoggyFeetSeconds > 0f)
            {
                builder.Append(" Soggy");
                builder.Append(worker.SoggyFeetSeconds.ToString("0"));
            }

            if (worker.SoppingWetSeconds > 0f)
            {
                builder.Append(" Wet");
                builder.Append(worker.SoppingWetSeconds.ToString("0"));
            }

            if (worker.YuckyLungsSeconds > 0f)
            {
                builder.Append(" Lung");
                builder.Append(worker.YuckyLungsSeconds.ToString("0"));
            }

            if (worker.PoppedEardrumsSeconds > 0f)
            {
                builder.Append(" Ear");
                builder.Append(worker.PoppedEardrumsSeconds.ToString("0"));
            }

            if (worker.IrritatedEyesSeconds > 0f)
            {
                builder.Append(" Eye");
                builder.Append(worker.IrritatedEyesSeconds.ToString("0"));
            }

            if (worker.ScaldedSeconds > 0f)
            {
                builder.Append(" Scald");
                builder.Append(worker.ScaldedSeconds.ToString("0"));
            }

            if (worker.HeatExposure >= ThermalDiscomfortExposureThreshold && worker.HeatExposure >= worker.ChillExposure)
            {
                builder.Append(" Hot");
                builder.Append(worker.HeatExposure.ToString("0"));
            }
            else if (worker.ChillExposure >= ThermalDiscomfortExposureThreshold)
            {
                builder.Append(" Cold");
                builder.Append(worker.ChillExposure.ToString("0"));
            }

            if (worker.AllergicReactionSeconds > 0f)
            {
                builder.Append(" Allergy");
                builder.Append(worker.AllergicReactionSeconds.ToString("0"));
            }

            if (worker.SuitFatigueSeconds > 0f)
            {
                builder.Append(" SuitF");
                builder.Append(worker.SuitFatigueSeconds.ToString("0"));
            }

            if (worker.GermyHandsSeconds > 0f)
            {
                builder.Append(" Hands");
                builder.Append(worker.GermyHandsSeconds.ToString("0"));
            }

            if (NeedsMedicalLeave(worker))
            {
                builder.Append(" MedLeave");
            }

            if (worker.DarkStressSeconds > 0f)
            {
                builder.Append(" Dark");
                builder.Append(worker.DarkStressSeconds.ToString("0"));
            }

            if (IsWorkerInDrabSurroundings(worker))
            {
                builder.Append(" Drab");
                builder.Append(Mathf.RoundToInt(DecorScoreAt(worker.Cell.x, worker.Cell.y) * 100f));
            }

            builder.Append(" I ");
            builder.Append(JobCategoryShortName(worker.Interest));
            builder.Append(" R ");
            builder.Append(JobCategoryShortName(worker.Role));
            builder.Append(" Sh");
            builder.Append(CrewScheduleOffsetLabel(worker.ScheduleOffsetSteps));
            builder.Append(" ");
            builder.Append(WorkerRiskText(worker));
            if (!string.IsNullOrEmpty(worker.Activity))
            {
                builder.Append("  ");
                builder.Append(worker.Activity);
            }

            return builder.ToString();
        }

        private string BuildColonyForecastText(float averageOxygen, float averageCo2, float averageTemperature, int assignedJobs, int openJobs)
        {
            UpdateCycleReportBalances();
            int activeWorkers = CountActiveWorkers();
            int livingWorkers = Mathf.Max(1, activeWorkers > 0 ? activeWorkers : workers.Count);
            float averagePollutedOxygen = AverageGas(pollutedOxygen);
            float foodCycles = ForecastRunwayCycles(food, livingWorkers * 700f);
            float cleanWaterReserve = TotalCleanWaterStock();
            float waterCycles = ForecastRunwayCycles(cleanWaterReserve, livingWorkers * 12f);
            float oxygenDiffuserDemand = CountCells(CellKind.OxygenDiffuser) * 0.075f * CycleLengthSeconds;
            float algaeCycles = oxygenDiffuserDemand <= 0.001f ? float.PositiveInfinity : ForecastRunwayCycles(algae, oxygenDiffuserDemand);
            float powerBuffer = maxPower <= 0.001f ? 0f : Mathf.Clamp01(power / maxPower);
            int overloadedWires = CountOverloadedPowerWires();
            float maxWireLoad = MaxPowerWireLoad();

            StringBuilder builder = new StringBuilder();
            builder.AppendLine("Colony Forecast");
            builder.Append("Runway: Food ");
            builder.Append(FormatRunway(foodCycles));
            builder.Append("  Water ");
            builder.Append(FormatRunway(waterCycles));
            builder.Append("  Algae ");
            builder.Append(FormatRunway(algaeCycles));
            builder.Append("  Fresh ");
            builder.Append(Mathf.RoundToInt(foodFreshness * 100f));
            builder.Append("%  Quality ");
            builder.Append(Mathf.RoundToInt(foodQuality * 100f));
            builder.AppendLine("%");
            builder.Append("Food Safety: ");
            builder.Append(FoodSafetyStateText());
            builder.Append("  Germ ");
            builder.Append(Mathf.RoundToInt(foodGerms * 100f));
            builder.Append("%");
            builder.AppendLine();

            builder.Append("Atmosphere: ");
            builder.Append(ForecastAtmosphereState(averageOxygen, averageCo2));
            builder.Append("  O2 ");
            builder.Append(averageOxygen.ToString("0.00"));
            builder.Append("  CO2 ");
            builder.Append(averageCo2.ToString("0.00"));
            builder.Append("  PO2 ");
            builder.Append(averagePollutedOxygen.ToString("0.00"));
            builder.Append("  Temp ");
            builder.Append(averageTemperature.ToString("0"));
            builder.AppendLine("C");
            builder.AppendLine();
            builder.Append("Power: Buffer ");
            builder.Append(Mathf.RoundToInt(powerBuffer * 100f));
            builder.Append("%  Load ");
            builder.Append(maxWireLoad.ToString("0.0"));
            builder.Append("/");
            builder.Append((WireSafeLoad + PowerTransformerLoadBonus).ToString("0.0"));
            builder.Append("  Over ");
            builder.Append(overloadedWires);
            builder.AppendLine();
            builder.Append("Research: Focus ");
            builder.Append(ResearchFocusStatusText());
            if (HasLockedResearch())
            {
                builder.Append("  Total ");
                builder.Append(researchPoints.ToString("0"));
                builder.Append("RP");
            }
            else
            {
                builder.Append("  No research left");
            }

            builder.AppendLine();
            builder.Append("Labor: Active ");
            builder.Append(activeWorkers);
            builder.Append("/");
            builder.Append(workers.Count);
            builder.Append("  Jobs ");
            builder.Append(assignedJobs);
            builder.Append(" assigned, ");
            builder.Append(openJobs);
            builder.Append(" open jobs");
            if (unreachableJobCount > 0)
            {
                builder.Append(", ");
                builder.Append(unreachableJobCount);
                builder.Append(" blocked jobs");
            }

            builder.AppendLine();
            builder.Append("Forecast Risk: ");
            if (activeWorkers <= 0)
            {
                builder.Append("No active duplicants.");
            }
            else if (foodCycles < 1f)
            {
                builder.Append("Food reserves are critical.");
            }
            else if (waterCycles < 1f)
            {
                builder.Append("Clean water reserve is critical.");
            }
            else if (averageOxygen < 0.18f)
            {
                builder.Append("Oxygen is too low.");
            }
            else if (averageCo2 > 0.30f)
            {
                builder.Append("CO2 pressure is rising.");
            }
            else if (powerBuffer < 0.15f)
            {
                builder.Append("Power buffer is low.");
            }
            else if (overloadedWires > 0 || maxWireLoad > WireSafeLoad + PowerTransformerLoadBonus)
            {
                builder.Append("Power wire overload risk.");
            }
            else if (openJobs > activeWorkers * 4)
            {
                builder.Append("Errand backlog is high.");
            }
            else
            {
                builder.Append("Stable.");
            }

            return builder.ToString();
        }

