        private string FoodSafetyStateText()
        {
            if (foodPoisoningCases > 0 || foodGerms >= FoodGermPoisoningThreshold)
            {
                return "food poisoning risk";
            }

            if (foodGerms >= FoodGermExposureThreshold || contaminatedMealsEaten > 0)
            {
                return "food contaminated";
            }

            if (food > 1f && (foodFreshness <= SpoiledFoodRotFreshnessThreshold || staleMealsEaten > 0))
            {
                return "food rotting";
            }

            if (food > 1f && foodFreshness < 0.45f)
            {
                return "food spoiling";
            }

            return "food safe";
        }

        private string BuildThermalManagementText(float averageTemperature)
        {
            int unsafeTemperatureTiles = CountUnsafeTemperatureTiles();
