            builder.Append("/");
            builder.Append(Mathf.RoundToInt(CoolingLoopTargetSeconds));
            builder.Append("  PipeRisk ");
            builder.Append(unsafeLiquidPipes);
            builder.Append("/");
            builder.Append(unsafeLiquidReservoirs);
            builder.Append("  Burst ");
            builder.Append(pipeBurstEvents);
            builder.Append("/");
            builder.Append(reservoirBurstEvents);
            builder.Append("  Cryo ");
            builder.Append(cryogenicPropellantProduced.ToString("0.0"));
            builder.Append("/");
            builder.Append(cryogenicRocketMissionsLaunched);
            builder.Append("  Unsafe ");
            builder.Append(unsafeTemperatureTiles);
            return builder.ToString();
        }

        private string ThermalManagementStateText(float averageTemperature, int unsafeTemperatureTiles, int unsafeLiquidPipes, int unsafeLiquidReservoirs)
        {
            if (unsafeLiquidPipes > 0 || unsafeLiquidReservoirs > 0)
            {
                return "coolant phase risk";
            }

            if (milestoneCoolingLoop)
            {
                return "coolant loop stable";
            }

            if (!techThermalEngineering)
            {
                return "passive cooling";
            }

            if (CountCells(CellKind.ThermoAquatuner) == 0)
            {
                return "active cooling missing";
            }

            if (CountRunningThermoAquatuners() == 0)
            {
                return "coolant stalled";
            }

            if (averageTemperature < 10f || averageTemperature > 36f || unsafeTemperatureTiles >= 20)
            {
                return "temperature unstable";
            }

            return "cooling loop proving";
        }

