        private string IndustrialHeatStateText(int saunaRooms, int readyMachines, int heatRecoveryTurbines, int brokenEquipment, int criticalThermalWorkers)
        {
            if (milestoneIndustrialSauna)
            {
                return "industrial sauna stable";
            }

            if (!milestoneCoolingLoop)
            {
                return "cooling prerequisite";
            }

            if (CountCells(CellKind.InsulatedTile) < 8)
            {
                return "needs insulated shell";
            }

            if (saunaRooms == 0)
            {
                return "hot room missing";
            }

            if (readyMachines == 0)
            {
                return "industry idle";
            }

            if (heatRecoveryTurbines == 0)
            {
                return "heat recovery missing";
            }

            if (steamTurbinePowerGenerated < IndustrialSaunaMinimumSteamPower)
            {
                return "recovering heat";
            }

            if (brokenEquipment > 0)
            {
                return "repair industrial damage";
            }

            if (criticalThermalWorkers > 0)
            {
                return "thermal safety risk";
            }

            return "sauna proving";
        }

        private string BuildRadiationSafetyText()
        {
            int dangerTiles = CountRadiationDangerTiles();
            int unprotectedWorkers = CountUnprotectedRadiationExposedWorkers();
            int radiationSicknessWorkers = CountWorkersWithDisease(WorkerDisease.RadiationSickness);
            StringBuilder builder = new StringBuilder();
            builder.Append("Radiation Safety: ");
            builder.Append(RadiationSafetyStateText(dangerTiles, unprotectedWorkers, radiationSicknessWorkers));
            builder.Append("  Danger ");
            builder.Append(dangerTiles);
            builder.Append("  Unprotected ");
            builder.Append(unprotectedWorkers);
            builder.Append("  Sick ");
            builder.Append(radiationSicknessWorkers);
            builder.Append("  Lead ");
            builder.Append(CountLeadSuitedWorkers());
            builder.Append("  Contain ");
            builder.Append(Mathf.RoundToInt(Mathf.Min(RadiationContainmentTargetSeconds, radiationContainmentSeconds)));
            builder.Append("/");
            builder.Append(Mathf.RoundToInt(RadiationContainmentTargetSeconds));
            builder.Append("  Radbolt ");
            builder.Append(radboltCharge.ToString("0.00"));
            builder.Append("@");
            builder.Append(CountRunningRadboltCollectors());
            return builder.ToString();
        }

        private string RadiationSafetyStateText(int dangerTiles, int unprotectedWorkers, int radiationSicknessWorkers)
        {
