            builder.Append(damagedEquipment);
            builder.Append("  Heat ");
            builder.Append(overheatingEquipment);
            builder.Append("  Flood ");
            builder.Append(submergedEquipment);
            builder.Append("/");
            builder.Append(floodedPowerWires);
            builder.Append("  Pressure ");
            builder.Append(dangerousPressureTiles);
            builder.Append("/");
            builder.Append(highPressureTiles);
            builder.Append(IsMeteorShowerActive() ? "  Meteor active " + meteorShowerSeconds.ToString("0") + "s" : "  Meteor in " + meteorCooldownSeconds.ToString("0") + "s");
            builder.Append("  Shield ");
            builder.Append(CountIntactBunkerDoors());
            builder.Append("/");
            builder.Append(bunkerDoors);
            builder.Append("  Scan ");
            builder.Append(CountSkyExposedSpaceScanners());
            builder.Append("/");
            builder.Append(scanners);
            builder.Append("  AutoShield ");
            builder.Append(Mathf.RoundToInt(Mathf.Min(AutomatedMeteorDefenseTargetSeconds, automatedMeteorDefenseSeconds)));
            builder.Append("/");
            builder.Append(Mathf.RoundToInt(AutomatedMeteorDefenseTargetSeconds));
            builder.Append("  Regolith ");
