            {
                builder.Append("  BuildQ ");
                builder.Append(queuedBuildJobs);
                builder.Append(" ");
                builder.Append(BuildCostText(queuedDirt, queuedMetal, queuedAlgae, queuedRefinedMetal));
            }
            return builder.ToString();
        }

        private string BuildCycleReportText()
        {
            UpdateCycleReportBalances();
            CycleReport report = hasLastCycleReport ? lastCycleReport : currentCycleReport;
            int reportCycle = report.Cycle > 0 ? report.Cycle : Mathf.Max(1, cycle);

            StringBuilder builder = new StringBuilder();
            builder.Append("Cycle Report: C");
            builder.Append(reportCycle);
            builder.Append(" Food +");
            builder.Append(FormatCycleAmount(report.FoodProduced));
            builder.Append("/-");
            builder.Append(FormatCycleAmount(report.FoodConsumed));
            builder.Append(" Spoil ");
            builder.Append(FormatCycleAmount(report.FoodSpoiled));
            builder.Append("  Water +");
            builder.Append(FormatCycleAmount(report.WaterProduced));
            builder.Append("/-");
            builder.Append(FormatCycleAmount(report.WaterConsumed));
            builder.Append("  Power +");
            builder.Append(FormatCycleAmount(report.PowerGenerated));
            builder.Append("/-");
            builder.Append(FormatCycleAmount(report.PowerConsumed));
            if (report.PowerLeaked > 0.001f)
            {
                builder.Append(" Leak ");
                builder.Append(FormatCycleAmount(report.PowerLeaked));
            }

            AppendCycleNetSummary(builder, report);
            builder.Append("  Research +");
            builder.Append(FormatCycleAmount(report.ResearchPoints));
            return builder.ToString();
        }

