        private string BuildLegacyText()
        {
            EnsureRooms();
            int finishedSculptingBlocks = CountFinishedSculptingBlocks();
            float averageDecor = AverageWorkerDecor();
            float highestStress = HighestStress();
            int lowMoraleWorkers = CountLowMoraleWorkers();
            int recreationRooms = CountRoomsOfKind(RoomKind.RecreationRoom) + CountRoomsOfKind(RoomKind.GreatHall);
            int brokenEquipment = CountBrokenEquipment();
            int longCommutes = CountLongCommuteWorkers();

            StringBuilder builder = new StringBuilder();
            builder.Append("Legacy: ");
            builder.Append(ColonyMonumentStateText(finishedSculptingBlocks, averageDecor, highestStress, lowMoraleWorkers, recreationRooms, brokenEquipment, longCommutes));
            builder.Append("  Sculpt ");
            builder.Append(Mathf.Min(ColonyMonumentMinimumSculptures, finishedSculptingBlocks));
            builder.Append("/");
            builder.Append(ColonyMonumentMinimumSculptures);
            builder.Append("  Decor ");
            builder.Append(Mathf.RoundToInt(averageDecor * 100f));
            builder.Append("%  Stress ");
            builder.Append(highestStress.ToString("0"));
            builder.Append("%  Rec ");
            builder.Append(recreationRooms);
            builder.Append("  Ceremony ");
            builder.Append(Mathf.RoundToInt(Mathf.Min(ColonyMonumentCeremonyTargetSeconds, colonyMonumentCeremonySeconds)));
            builder.Append("/");
            builder.Append(Mathf.RoundToInt(ColonyMonumentCeremonyTargetSeconds));
            builder.Append("  Tear ");
            builder.Append(Mathf.RoundToInt(Mathf.Min(TemporalTearSignalTargetSeconds, temporalTearSignalSeconds)));
            builder.Append("/");
            builder.Append(Mathf.RoundToInt(TemporalTearSignalTargetSeconds));
            if (lowMoraleWorkers > 0)
            {
                builder.Append("  LowMorale ");
                builder.Append(lowMoraleWorkers);
            }

            if (brokenEquipment > 0)
            {
                builder.Append("  Broken ");
                builder.Append(brokenEquipment);
            }

            if (longCommutes > 0)
            {
                builder.Append("  Long ");
                builder.Append(longCommutes);
            }

            return builder.ToString();
        }

        private string ColonyMonumentStateText(int finishedSculptingBlocks, float averageDecor, float highestStress, int lowMoraleWorkers, int recreationRooms, int brokenEquipment, int longCommutes)
        {
            if (milestoneColonyMonument)
            {
                return "monument dedicated";
            }

            if (!milestoneDeepSpaceSurvey)
            {
                return "awaiting deep survey";
            }

            if (!milestoneTemporalTearSignal)
            {
                return "awaiting temporal signal";
            }

            if (!milestoneSustainableOperations)
            {
                return "awaiting sustainability";
            }

            if (finishedSculptingBlocks < ColonyMonumentMinimumSculptures)
            {
                return "needs sculptures";
            }

            if (averageDecor < ColonyMonumentMinimumDecor)
            {
                return "decor low";
            }

            if (recreationRooms == 0)
            {
                return "ceremony room missing";
            }

            if (lowMoraleWorkers > 0)
            {
                return "morale fragile";
            }

            if (highestStress > ColonyMonumentMaximumStress)
            {
                return "stress high";
            }

            if (brokenEquipment > 0)
            {
                return "repairs pending";
            }

            if (longCommutes > 0)
            {
                return "commutes long";
            }

            return "ceremony holding";
        }

        private string SustainabilityStateText(CycleReport report, bool hasTrendSample)
        {
            if (milestoneSustainableOperations)
            {
                return "proven";
            }

            if (!milestoneSafetyOperations || !milestoneRoomSpecialization)
            {
                return "foundations missing";
            }

            if (!hasTrendSample)
            {
                return "sampling";
            }

            return IsSustainableCycle(report) ? "stable cycle" : "at risk";
        }

        private bool HasCycleDeficit(float delta, float threshold)
        {
            return delta < -threshold;
        }

        private void AppendCycleNetSummary(StringBuilder builder, CycleReport report)
        {
            builder.Append("  Net F/W/P/O ");
            builder.Append(FormatCycleSignedAmount(report.FoodEnd - report.FoodStart));
            builder.Append("/");
            builder.Append(FormatCycleSignedAmount(report.WaterEnd - report.WaterStart));
            builder.Append("/");
            builder.Append(FormatCycleSignedAmount(report.PowerEnd - report.PowerStart));
            builder.Append("/");
            builder.Append(FormatCycleSignedAmount(report.OxygenEnd - report.OxygenStart));
        }

        private string FormatCycleSignedAmount(float amount)
        {
            if (Mathf.Abs(amount) < 0.05f)
            {
                amount = 0f;
            }

            return amount >= 0f ? "+" + FormatCycleAmount(amount) : "-" + FormatCycleAmount(-amount);
        }

        private string FormatCycleAmount(float amount)
        {
            amount = Mathf.Max(0f, amount);
            return amount >= 10f ? amount.ToString("0") : amount.ToString("0.0");
        }

        private float ForecastRunwayCycles(float amount, float demandPerCycle)
        {
            if (demandPerCycle <= 0.001f)
            {
                return float.PositiveInfinity;
            }

            return Mathf.Max(0f, amount) / demandPerCycle;
        }

        private string FormatRunway(float cycles)
        {
            if (float.IsPositiveInfinity(cycles))
            {
                return "idle";
            }

            if (cycles <= 0.05f)
            {
                return "empty";
            }

            if (cycles < 1f)
            {
                return "<1c";
            }

            if (cycles > 99f)
            {
                return "99c+";
            }

            return cycles.ToString("0.0") + "c";
        }

