        private string ForecastAtmosphereState(float averageOxygen, float averageCo2)
        {
            if (averageOxygen < 0.12f)
            {
                return "suffocating";
            }

            if (averageOxygen < 0.20f)
            {
                return "thin oxygen";
            }

            if (averageCo2 > 0.32f)
            {
                return "CO2 rising";
            }

            if (averageOxygen > 0.50f && CountHighPressureTiles() > 0)
            {
                return "overpressured";
            }

            return "stable";
        }

        private string ForecastProtectiveGearRouteRisk()
        {
            int suitCheckpointsMissingDock = CountSuitCheckpointsMissingDock();
            if (suitCheckpointsMissingDock > 0)
            {
                return suitCheckpointsMissingDock == 1
                    ? "Place a repaired Atmo Suit Dock next to the Atmo Suit Checkpoint before routing unsafe errands."
                    : "Place repaired Atmo Suit Docks next to every Atmo Suit Checkpoint before routing unsafe errands.";
            }

            int oxygenMaskCheckpointsMissingDock = CountOxygenMaskCheckpointsMissingDock();
            if (oxygenMaskCheckpointsMissingDock > 0)
            {
                return oxygenMaskCheckpointsMissingDock == 1
                    ? "Place a repaired Oxygen Mask Dock next to the Oxygen Mask Checkpoint before routing low-oxygen errands."
                    : "Place repaired Oxygen Mask Docks next to every Oxygen Mask Checkpoint before routing low-oxygen errands.";
            }

            int leadSuitCheckpointsMissingLocker = CountLeadSuitCheckpointsMissingLocker();
            if (leadSuitCheckpointsMissingLocker > 0)
            {
                return leadSuitCheckpointsMissingLocker == 1
                    ? "Place a repaired Lead Suit Locker next to the Lead Suit Checkpoint before routing radiation errands."
                    : "Place repaired Lead Suit Lockers next to every Lead Suit Checkpoint before routing radiation errands.";
            }

            return string.Empty;
        }

        private string ForecastRiskText(
            float foodCycles,
            float waterCycles,
            float algaeCycles,
            float averageOxygen,
            float averageCo2,
            float averagePollutedOxygen,
            float averageTemperature,
            float powerBuffer,
            float maxWireLoad,
            int overloadedWires,
            int activeWorkers,
            int openJobs,
            CycleReport trendReport,
            bool hasTrendSample)
        {
            if (colonyFailed)
            {
                return "Colony failed. Load a save or start a new run.";
            }

            if (AnyWorkerNeedsRescue())
            {
                if (CountCells(CellKind.MedicalCot) == 0)
                {
                    return "Build a Medical Cot and rescue the downed duplicant.";
                }

                return CountUsableCells(CellKind.MedicalCot) == 0
                    ? "Enable or repair a Medical Cot and rescue the downed duplicant."
                    : "Prioritize rescue errands for downed duplicants.";
            }

            if (foodCycles < 1f)
            {
                return FoodEmergencyActionText();
            }

            if (waterCycles < 1f)
            {
                return CountCells(CellKind.WaterSieve) > 0 ? "Recycle polluted water and pump clean reserves into storage." : "Pump a water pocket or build a Water Sieve for polluted reserves.";
            }

            if (averageOxygen < 0.18f)
            {
                return techAirSystems ? "Run diffusers, electrolyzers, or gas vents to restore breathable oxygen." : "Build an Oxygen Diffuser and research Air Systems.";
            }

            int depletedBreathingGearWorkers = CountDepletedBreathingGearWorkers();
            if (depletedBreathingGearWorkers > 0)
            {
                return depletedBreathingGearWorkers == 1
                    ? "Recharge suit or mask docks so the depleted duplicant can return safely."
                    : "Recharge suit or mask docks so depleted duplicants can return safely.";
            }

            string protectiveGearRouteRisk = ForecastProtectiveGearRouteRisk();
            if (!string.IsNullOrEmpty(protectiveGearRouteRisk))
            {
                return protectiveGearRouteRisk;
            }

            if (!float.IsPositiveInfinity(algaeCycles) && algaeCycles < 1f && CountCells(CellKind.Electrolyzer) == 0)
            {
                return techAirSystems ? "Switch oxygen production toward electrolyzers before algae is exhausted." : "Mine algae and research Air Systems before the diffuser supply fails.";
            }

            string trendRisk = ForecastCycleTrendRisk(trendReport, hasTrendSample, foodCycles, waterCycles, averageOxygen, powerBuffer);
            if (!string.IsNullOrEmpty(trendRisk))
            {
                return trendRisk;
            }

            string foodSafetyRisk = ForecastFoodSafetyRisk();
            if (!string.IsNullOrEmpty(foodSafetyRisk))
            {
                return foodSafetyRisk;
            }

            string infrastructureRisk = ForecastInfrastructureRisk();
            if (!string.IsNullOrEmpty(infrastructureRisk))
            {
                return infrastructureRisk;
            }

            string coolingLoopRisk = ForecastCoolingLoopRisk(averageTemperature);
            if (!string.IsNullOrEmpty(coolingLoopRisk))
            {
                return coolingLoopRisk;
            }

            string industrialSaunaRisk = ForecastIndustrialSaunaRisk();
            if (!string.IsNullOrEmpty(industrialSaunaRisk))
            {
                return industrialSaunaRisk;
            }

            string radiationRisk = ForecastRadiationRisk();
            if (!string.IsNullOrEmpty(radiationRisk))
            {
                return radiationRisk;
            }

            string powerRecoveryRisk = ForecastPowerRecoveryRisk(powerBuffer, maxWireLoad, overloadedWires);
            if (!string.IsNullOrEmpty(powerRecoveryRisk))
            {
                return powerRecoveryRisk;
            }

            string transitRisk = ForecastTransitRisk();
            if (!string.IsNullOrEmpty(transitRisk))
            {
                return transitRisk;
            }

            string roomRisk = ForecastRoomRisk();
            if (!string.IsNullOrEmpty(roomRisk))
            {
                return roomRisk;
            }

            string sustainabilityRisk = ForecastSustainabilityRisk(trendReport, hasTrendSample);
            if (!string.IsNullOrEmpty(sustainabilityRisk))
            {
                return sustainabilityRisk;
            }

            string naturalVentRisk = ForecastNaturalVentRisk();
            if (!string.IsNullOrEmpty(naturalVentRisk))
            {
                return naturalVentRisk;
            }

            string monumentRisk = ForecastColonyMonumentRisk();
            if (!string.IsNullOrEmpty(monumentRisk))
            {
                return monumentRisk;
            }

            if (AnyElectrolyzerHasGermyWaterFeed())
            {
                return "Clean water germs can aerosolize through Electrolyzers.";
            }

            if (averageCo2 > 0.28f)
            {
                return techAirSystems ? "Build a Carbon Skimmer or vent CO2 away from living spaces." : "Research Air Systems so CO2 scrubbing becomes available.";
            }

            if (averagePollutedOxygen > 0.12f && CountCells(CellKind.AirDeodorizer) > 0 && dirt <= 0.05f)
            {
                return "Mine dirt or sand so Air Deodorizers can filter polluted oxygen.";
            }

            if (averagePollutedOxygen > 0.12f && CountCells(CellKind.AirDeodorizer) == 0)
            {
                return techAirSystems ? "Build Air Deodorizers near polluted oxygen pockets." : "Research Air Systems so Air Deodorizers can clean polluted oxygen.";
            }

            if (HasLockedResearch() && CountCells(CellKind.ResearchStation) == 0)
            {
                return "Build a Research Station and pick the next colony technology.";
            }

            if (HasLockedResearch() && CountUsableResearchStations() == 0)
            {
                return "Repair, enable, wire, or power the Research Station before technology progress stalls.";
            }

            if (HasLockedResearch() && researchPoints < ResearchRequirement(selectedResearchFocus))
            {
                return "Keep the Research Station powered until the focused technology unlocks.";
            }

            if (powerBuffer < 0.12f)
            {
                return "Generate power and expand battery capacity before machines shut down.";
            }

            if (ActiveBatteryLeakRate() >= BatteryLeakRate + JumboBatteryLeakRate - 0.001f && CountCells(CellKind.SmartBattery) == 0)
            {
                return "Battery leakage is wasting stored power; add Smart Batteries or automate generators.";
            }

            if (overloadedWires > 0 || maxWireLoad > WireSafeLoad + PowerTransformerLoadBonus)
            {
                return "Split overloaded circuits with transformers and separate heavy generators.";
            }

            if (unreachableJobCount > 0)
            {
                return "Build ladder, floor, or door access to blocked errands.";
            }

            if (CountWiltingCrops() > 0)
            {
                return "Fix crop atmosphere, water, temperature, or pressure before harvests fail.";
            }

            if (CountMoppableSpills() > 0)
            {
                return "Mop spills before they flood equipment and wires.";
            }

            if (averageTemperature > 38f || averageTemperature < 6f)
            {
                return "Insulate living areas and add thermal machines to stabilize temperature.";
            }

            if (IsMeteorShowerActive())
            {
                return "Keep duplicants under cover and repair bunker doors after impacts.";
            }

            if (openJobs > Mathf.Max(1, activeWorkers) * 3)
            {
                return "Use labor policy and priority controls to reduce the errand backlog.";
            }

            return objectiveText;
        }

        private string ForecastCycleTrendRisk(CycleReport report, bool hasTrendSample, float foodCycles, float waterCycles, float averageOxygen, float powerBuffer)
        {
            if (!hasTrendSample)
            {
                return string.Empty;
            }

            float foodDelta = report.FoodEnd - report.FoodStart;
            float waterDelta = report.WaterEnd - report.WaterStart;
            float powerDelta = report.PowerEnd - report.PowerStart;
            float oxygenDelta = report.OxygenEnd - report.OxygenStart;
            if (HasCycleDeficit(foodDelta, 350f) && foodCycles < 4f)
            {
                return "Food is trending down this cycle; expand farms, cooking, or ranching before reserves slip.";
            }

            if (HasCycleDeficit(waterDelta, 6f) && waterCycles < 4f)
            {
                return "Clean water is trending down this cycle; pump or recycle water and pause optional consumers.";
            }

            if (HasCycleDeficit(oxygenDelta, 0.35f) && averageOxygen < 0.24f)
            {
                return "Breathable oxygen is trending down; increase oxygen production or move gas through vents.";
            }

            if (HasCycleDeficit(powerDelta, 8f) && powerBuffer < 0.35f)
            {
                return "Stored power is trending down; add generation, automation, or battery capacity before the grid browns out.";
            }

            return string.Empty;
        }

        private string ForecastFoodSafetyRisk()
        {
            int treatmentNeeds = CountWorkersNeedingTreatment();
            int medicalCots = CountCells(CellKind.MedicalCot);
            int usableMedicalCots = CountUsableCells(CellKind.MedicalCot);
            int apothecaries = CountCells(CellKind.Apothecary);
            int medicineReadyApothecaries = CountMedicineReadyApothecaries();
            int foodPolicyBlockedHungryWorkers = CountFoodPolicyBlockedHungryWorkers();
            if (foodPolicyBlockedHungryWorkers > 0)
            {
                return foodPolicyBlockedHungryWorkers == 1
                    ? "Food SAFE is blocking a hungry duplicant; cook safer meals, sterilize storage, or allow emergency food."
                    : "Food SAFE is blocking hungry duplicants; cook safer meals, sterilize storage, or allow emergency food.";
            }

            if (foodPoisoningCases > 0 && medicalCots == 0)
            {
                return "Food poisoning is active; build a Medical Cot and stabilize sick duplicants.";
            }

            if (foodPoisoningCases > 0 && usableMedicalCots == 0)
            {
                return "Food poisoning is active; enable or repair a Medical Cot and stabilize sick duplicants.";
            }

            if (treatmentNeeds > 0 && medicalCots == 0)
            {
                return "Sick duplicants need treatment; build a Medical Cot and produce medicine.";
            }

            if (treatmentNeeds > 0 && usableMedicalCots == 0)
            {
                return "Sick duplicants need treatment; enable or repair a Medical Cot and produce medicine.";
            }

            if (treatmentNeeds > 0 && medicine < MedicineTreatmentUse && apothecaries == 0)
            {
                return "Sick duplicants need treatment; build an Apothecary and compound medicine.";
            }

            if (treatmentNeeds > 0 && medicine < MedicineTreatmentUse && medicineReadyApothecaries == 0)
            {
                return "Sick duplicants need medicine; repair, enable, power, and supply the Apothecary.";
            }

            if (treatmentNeeds > 0 && medicine < MedicineTreatmentUse)
            {
                return "Sick duplicants need medicine; prioritize Apothecary production errands.";
            }

            if (foodGerms >= FoodGermPoisoningThreshold)
            {
                return "Food contamination can cause poisoning; grill meals or store food in sterile refrigeration.";
            }

            if (foodGerms >= FoodGermExposureThreshold &&
                CountPoweredRefrigerators() == 0 &&
                AverageFoodStorageChlorineSterilityScore() < 0.15f)
            {
                return "Food is contaminated; move it to powered refrigeration or sterile chlorine storage.";
            }

            if (food > workers.Count * 900f &&
                foodFreshness < 0.45f &&
                CountUsableFoodStorageCells() == 0)
            {
                return CountCells(CellKind.RationBox) + CountCells(CellKind.Refrigerator) == 0
                    ? "Food is spoiling without storage; build a Ration Box or powered Refrigerator."
                    : "Food is spoiling; repair, enable, or power food storage.";
            }

            return string.Empty;
        }

        private string ForecastInfrastructureRisk()
        {
            if (CountBrokenEquipment() > 0)
            {
                return "Broken equipment is blocking systems; queue repairs before failures cascade.";
            }

            if (CountSubmergedEquipment() > 0 || CountFloodedPowerWires() > 0)
            {
                return "Flooding is damaging infrastructure; mop water and protect power wires.";
            }

            if (CountUncontainedOverheatingEquipment() > 0)
            {
                return "Equipment is overheating; cool rooms or move heat before machines break.";
            }

            if (CountDangerousPressureTiles() > 0)
            {
                return "Dangerous pressure pockets can injure duplicants; vent gas or add high-pressure outlets.";
            }

            if (IsMeteorShowerActive())
            {
                return CountIntactBunkerDoors() > 0 ? "Meteor shower active; keep bunker doors closed and repair impacts." : "Meteor shower active; keep duplicants under cover and build bunker doors after impact.";
            }

            if (techSpaceSystems &&
                milestoneMeteorShielding &&
                !milestoneSurfaceRecovery &&
                CountCells(CellKind.Regolith) > 0)
            {
                return "Clear meteor regolith before it blocks solar panels, scanners, or bunker door access.";
            }

            if (techSpaceSystems &&
                milestoneMeteorShielding &&
                CountDamagedBunkerDoors() > 0)
            {
                return "Repair damaged Bunker Doors before the next meteor shower.";
            }

            if (techSpaceSystems &&
                meteorCooldownSeconds < SpaceScannerWarningSeconds * 1.5f &&
                CountCells(CellKind.SpaceScanner) > 0 &&
                CountSkyExposedSpaceScanners() == 0)
            {
                return "Meteor warning is near but scanners are blocked; clear sky access above Space Scanners.";
            }

            if (techSpaceSystems &&
                meteorCooldownSeconds < CycleLengthSeconds &&
                CountCells(CellKind.SolarPanel) > 0 &&
                CountIntactBunkerDoors() == 0)
            {
                return "Meteor shower is approaching exposed surface machines; build Bunker Doors for shielding.";
            }

            if (techSpaceSystems &&
                milestoneSpaceScanning &&
                !milestoneAutomatedMeteorDefense &&
                meteorCooldownSeconds < SpaceScannerWarningSeconds * 1.5f &&
                CountCells(CellKind.BunkerDoor) > 0 &&
                CountAutomationClosedBunkerDoors() == 0)
            {
                return "Link Space Scanner automation to Bunker Doors so the surface seals before impacts.";
            }

            return string.Empty;
        }

        private string ForecastRadiationRisk()
        {
            int dangerTiles = CountRadiationDangerTiles();
            if (dangerTiles <= 0)
            {
                return string.Empty;
            }

            if (CountUnprotectedRadiationExposedWorkers() > 0)
            {
                return "Unprotected duplicants are in radiation; pull them back or route them through Lead Suit Checkpoints.";
            }

            if (CountWorkersWithDisease(WorkerDisease.RadiationSickness) > 0)
            {
                return "Radiation sickness is active; treat duplicants and keep them out of radiation zones.";
            }

            if (!techSpaceSystems)
            {
                return "Research Space Systems before expanding into radiation zones.";
            }

            int leadSuitLockers = CountCells(CellKind.LeadSuitLocker);
            int leadSuitCheckpoints = CountCells(CellKind.LeadSuitCheckpoint);
            if (leadSuitLockers == 0 || leadSuitCheckpoints == 0)
            {
                return "Build Lead Suit Lockers and Checkpoints before routing duplicants through radiation.";
            }

            if (UsableLeadSuitLockerCount() == 0 || CountUsableCells(CellKind.LeadSuitCheckpoint) == 0)
            {
                return "Repair, enable, or drain the Lead Suit route before routing duplicants through radiation.";
            }

            if (CountLeadSuitCheckpointsMissingLocker() > 0)
            {
                return "Place repaired Lead Suit Lockers directly beside radiation-route checkpoints.";
            }

            if (!milestoneRadiationContainment && milestoneLeadSuits)
            {
                return "Keep the lead-suit route stable with no unprotected radiation exposure until containment is proven.";
            }

            return string.Empty;
        }

        private string ForecastCoolingLoopRisk(float averageTemperature)
        {
            if (milestoneCoolingLoop || !milestoneWheezewortCooling)
            {
                return string.Empty;
            }

            if (!techThermalEngineering)
            {
                return "Research Thermal Engineering before building an active coolant loop.";
            }

            if (CountCells(CellKind.ThermoAquatuner) == 0)
            {
                return "Build a Thermo Aquatuner and connect liquid pipes for active cooling.";
            }

            if (CountLiquidPipeTiles() < 6)
            {
                return "Run Liquid Pipe through the Thermo Aquatuner input and output to form a coolant loop.";
            }

            if (CountRunningThermoAquatuners() == 0)
            {
                return "Feed coolant through the Thermo Aquatuner and keep output pipe capacity free.";
            }

            if (CountUnsafeLiquidPipes() > 0 || CountUnsafeLiquidReservoirs() > 0)
            {
                return "Move coolant away from freezing or boiling temperatures before pipes rupture.";
            }

            if (averageTemperature < 10f || averageTemperature > 36f || CountUnsafeTemperatureTiles() >= 20)
            {
                return "Use insulated and radiant pipes to move heat until colony temperature stabilizes.";
            }

            if (thermoAquatunerWaterCooled < CoolingLoopMinimumAquatunedLiquid)
            {
                return "Let the Thermo Aquatuner process enough coolant to establish active cooling.";
            }

            return "Keep the coolant loop running without pipe or reservoir ruptures until stability is proven.";
        }

        private string ForecastIndustrialSaunaRisk()
        {
            if (milestoneIndustrialSauna || !milestoneGeothermalPower)
            {
                return string.Empty;
            }

            if (!milestoneCoolingLoop)
            {
                return "Finish active coolant loop stability before enclosing a hot industrial sauna.";
            }

            if (!techAdvancedPower || !techThermalEngineering)
            {
                return "Research Advanced Power and Thermal Engineering before building an industrial sauna.";
            }

            if (CountCells(CellKind.InsulatedTile) < 8)
            {
                return "Add insulated tiles around the industrial heat room before trapping steam.";
            }

            if (CountIndustrialSaunaHeatProducers() == 0)
            {
                return "Place a refinery, polymer press, petroleum generator, aquatuner, or sour gas condenser inside the industrial room.";
            }

            if (CountIndustrialSaunaRooms() == 0)
            {
                return "Enclose a hot Machine Room or Power Plant with steam so industrial heat can collect.";
            }

            if (CountIndustrialSaunaReadyMachines() == 0)
            {
                return "Power and fuel one industrial machine inside the steam room.";
            }

            if (CountHeatRecoverySteamTurbines() == 0)
            {
                return "Wire a Steam Turbine within range of hot steam for industrial heat recovery.";
            }

            if (steamTurbinePowerGenerated < IndustrialSaunaMinimumSteamPower)
            {
                return "Let the Steam Turbine recover more industrial heat before the sauna can be proven.";
            }

            if (CountBrokenEquipment() > 0)
            {
                return "Repair broken equipment before proving industrial sauna stability.";
            }

            if (CountUnsafeLiquidPipes() > 0 || CountUnsafeLiquidReservoirs() > 0)
            {
                return "Stabilize coolant pipes and reservoirs before proving industrial sauna stability.";
            }

            if (CountCriticalThermalExposureWorkers() > 0)
            {
                return "Route duplicants away from scalding industry or through suits before proving sauna safety.";
            }

            return "Keep industrial machines, coolant, and Steam Turbines stable until the sauna is proven.";
        }

        private string ForecastPowerRecoveryRisk(float powerBuffer, float maxWireLoad, int overloadedWires)
        {
            if (milestonePowerRecovery || !milestonePowerLoadManagement || !milestoneAutomation)
            {
                return string.Empty;
            }

            if (powerBuffer < PowerRecoveryMinimumBuffer)
            {
                return "Recharge batteries above 35% before the automated grid can prove brownout recovery.";
            }

            if (CountCells(CellKind.SmartBattery) == 0 || CountAutomationControlledGenerators() == 0)
            {
                return "Link a Smart Battery to a repaired, fueled automatic generator before proving automated power recovery.";
            }

            if (CountUnwiredPowerBuildings() > 0)
            {
                return "Wire every powered building before proving automated power recovery.";
            }

            if (overloadedWires > 0 || maxWireLoad > WireSafeLoad + PowerTransformerLoadBonus)
            {
                return "Clear wire overloads before proving automated power recovery.";
            }

            return "Hold the automated grid stable until brownout recovery is proven.";
        }

        private string ForecastTransitRisk()
        {
            if (milestoneTransitSpine || !milestoneColonyExpansion)
            {
                return string.Empty;
            }

            int firePoles = CountCells(CellKind.FirePole);
            int verticalSpan = FirePoleVerticalSpan();
            if (firePoles == 0)
            {
                return "Build Fire Poles beside the main ladder shaft to shorten vertical commutes.";
            }

            if (firePoles < TransitSpineMinimumFirePoleTiles || verticalSpan < TransitSpineMinimumVerticalSpan)
            {
                return "Extend the Fire Pole spine through more floors before transit can be proven.";
            }

            if (firePoleDescentTiles < TransitSpineDescentTargetTiles)
            {
                return "Send duplicants down the Fire Pole spine until vertical transit is proven.";
            }

            if (CountLongCommuteWorkers() > 0)
            {
                return "Severe long commutes are active; add more vertical access and shorten errands.";
            }

            return "Keep the Fire Pole spine clear until fast vertical transit is proven.";
        }

        private string ForecastRoomRisk()
        {
            EnsureRooms();
            int sleepRooms = CountSleepingRooms();
            int diningRooms = CountDiningRooms();
            int washroomRooms = CountRoomsOfKind(RoomKind.Washroom);
            int clinicRooms = CountRoomsOfKind(RoomKind.Clinic);
            int recreationRooms = CountRoomsOfKind(RoomKind.RecreationRoom) + CountRoomsOfKind(RoomKind.GreatHall);
            int stableRooms = CountRoomsOfKind(RoomKind.Stable);
            int storageRooms = CountRoomsOfKind(RoomKind.StorageRoom);
            int powerRooms = CountRoomsOfKind(RoomKind.PowerPlant) + CountRoomsOfKind(RoomKind.MachineRoom);
            int mixedRooms = CountRoomsOfKind(RoomKind.MixedRoom);

            if (sleepRooms == 0 && CountBeds() > 0)
            {
                return "Seal beds behind tiles or airlocks to form a Barracks or Bedroom.";
            }

            if (diningRooms == 0 && CountCells(CellKind.MessTable) > 0)
            {
                return "Seal Mess Tables into a Mess Hall or Great Hall so meals improve morale.";
            }

            if (washroomRooms == 0 &&
                (CountUsableToilets() > 0 || CountUsableHygieneFixtures() > 0))
            {
                return "Seal toilets with basins, sanitizer, or showers to form a Washroom.";
            }

            if (storageRooms == 0 && CountCells(CellKind.StorageBin) + CountCells(CellKind.RationBox) > 0)
            {
                return "Seal Storage Bins or Ration Boxes into a Storage Room for better dry capacity.";
            }

            if (mixedRooms > 0)
            {
                return "Split mixed rooms with tiles or airlocks so specialty room bonuses activate.";
            }

            if (CountUsableCells(CellKind.MedicalCot) > 0 && clinicRooms == 0)
            {
                return "Seal Medical Cots and Apothecaries into a Clinic to speed recovery.";
            }

            if (CountUsableCells(CellKind.RanchingStation) > 0 && stableRooms == 0)
            {
                return "Seal Ranching Stations and feeders into Stable rooms before critter output falls.";
            }

            if (CountUsableMoraleCareStations() > 0 && recreationRooms == 0)
            {
                return "Seal recreation fixtures into a Recreation Room or Great Hall for stronger stress relief.";
            }

            if (CountCells(CellKind.PowerControlStation) > 0 && powerRooms == 0)
            {
                return "Seal generators with a Power Control Station into a Power Plant to extend tune-ups.";
            }

            return string.Empty;
        }

        private string ForecastSustainabilityRisk(CycleReport report, bool hasTrendSample)
        {
            if (milestoneSustainableOperations)
            {
                return string.Empty;
            }

            if (!milestoneSafetyOperations || !milestoneRoomSpecialization)
            {
                return string.Empty;
            }

            if (!hasTrendSample)
            {
                return "Let the colony run long enough to sample food, water, power, and oxygen balance.";
            }

            if (!IsSustainableCycle(report))
            {
                return "Stabilize cycle balance: finish a cycle without food, water, power, oxygen, health, or infrastructure losses.";
            }

            int remaining = Mathf.Max(0, SustainableCycleTarget - sustainableCycleStreak);
            return remaining > 0
                ? "Keep the colony stable for " + remaining + " more cycle(s) to prove long-term sustainability."
                : string.Empty;
        }

        private string ForecastNaturalVentRisk()
        {
            int naturalVents = CountNaturalVents();
            if (naturalVents <= 0)
            {
                return string.Empty;
            }

            if (!milestoneRenewableVents)
            {
                if (!AnyNaturalVentActive())
                {
                    return "All discovered natural vents are dormant; build storage and pumps while waiting for the next eruption window.";
                }

                if (CountCells(CellKind.WaterPump) == 0 && CountCells(CellKind.GasPump) == 0)
                {
                    return "Tap active natural vents with pumps and storage before the eruption window closes.";
                }
            }

            if (milestoneRenewableVents && !milestoneVentAnalysis)
            {
                int analyzedNaturalVents = CountAnalyzedNaturalVents();
                if (!techAutomationLogistics)
                {
                    return "Research Automation Logistics so the colony can analyze natural vent cycles.";
                }

                if (CountCells(CellKind.VentAnalyzer) == 0)
                {
                    return "Build and wire a Vent Analyzer within range of a natural vent.";
                }

                if (analyzedNaturalVents < naturalVents && CountRunningVentAnalyzers() == 0)
                {
                    return CountVentAnalyzersWithAnalysisTargets() == 0
                        ? "Move or add a Vent Analyzer within range of each unanalyzed natural vent."
                        : "Repair, enable, wire, and keep automation green on the Vent Analyzer.";
                }

                return "Keep Vent Analyzers powered and green until every discovered natural vent is analyzed.";
            }

            if (milestoneVentAnalysis && !milestoneVolcanicRefining && CountCells(CellKind.MetalVolcano) > 0)
            {
                return AnyMetalVolcanoActive()
                    ? "Collect the Metal Volcano output after insulating the chamber around the hot refined metal."
                    : "Use the analyzed Metal Volcano forecast to build insulated storage before the next eruption.";
            }

            return string.Empty;
        }

        private string ForecastColonyMonumentRisk()
        {
            if (milestoneColonyMonument || !milestoneTemporalTearSignal || !milestoneSustainableOperations)
            {
                return string.Empty;
            }

            EnsureRooms();
            int finishedSculptingBlocks = CountFinishedSculptingBlocks();
            if (finishedSculptingBlocks < ColonyMonumentMinimumSculptures)
            {
                return "Finish three Sculpting Blocks as a colony monument before closing the charter.";
            }

            if (AverageWorkerDecor() < ColonyMonumentMinimumDecor)
            {
                return "Add Decor Plants, powered Ceiling Lights, or finished Sculpting Blocks along daily routes before the monument ceremony.";
            }

            if (CountRoomsOfKind(RoomKind.RecreationRoom) + CountRoomsOfKind(RoomKind.GreatHall) == 0)
            {
                return "Seal recreation fixtures into a Recreation Room or Great Hall before the monument ceremony.";
            }

            if (CountLowMoraleWorkers() > 0)
            {
                return "Raise duplicant morale before holding the monument ceremony.";
            }

            if (HighestStress() > ColonyMonumentMaximumStress)
            {
                return "Lower stress with downtime, decor, recreation, and massage before the monument ceremony.";
            }

            if (CountBrokenEquipment() > 0)
            {
                return "Repair broken equipment before holding the monument ceremony.";
            }

            if (CountLongCommuteWorkers() > 0)
            {
                return "Shorten severe commutes before holding the monument ceremony.";
            }

            int remaining = Mathf.Max(0, Mathf.CeilToInt(ColonyMonumentCeremonyTargetSeconds - colonyMonumentCeremonySeconds));
            return remaining > 0
                ? "Hold stable morale, decor, rooms, commutes, and repairs for " + remaining + " more second(s) to dedicate the colony monument."
                : string.Empty;
        }

        private Worker HighestRiskWorker(out string riskText)
        {
            Worker riskiest = null;
            int riskiestScore = int.MinValue;
            foreach (Worker worker in workers)
            {
                int score = WorkerRiskScore(worker);
                if (score > riskiestScore)
                {
                    riskiestScore = score;
                    riskiest = worker;
                }
            }

            riskText = riskiest == null ? "none" : WorkerRiskText(riskiest);
            return riskiest;
        }

        private int WorkerRiskScore(Worker worker)
        {
            if (worker == null)
            {
                return 0;
            }

            if (worker.Health <= 0f)
            {
                return 10000 + Mathf.RoundToInt(worker.IncapacitatedSeconds);
            }

            int score = 0;
            score += Mathf.RoundToInt((100f - worker.Health) * 2f);
            score += Mathf.RoundToInt(Mathf.Max(0f, 70f - worker.Breath) * 3f);
            score += Mathf.RoundToInt(Mathf.Max(0f, 1400f - worker.Calories) / 5f);
            score += Mathf.RoundToInt(worker.Stress * 1.4f);
            score += Mathf.RoundToInt(worker.Fatigue * 1.1f);
            score += Mathf.RoundToInt(worker.Bladder * 1.1f);
            score += Mathf.RoundToInt(worker.Sickness * 2f);
            score += Mathf.RoundToInt(worker.GermExposure * 1.1f);
            score += Mathf.RoundToInt(Mathf.Max(worker.HeatExposure, worker.ChillExposure) * 2f);
            score += Mathf.RoundToInt(EnvironmentalDangerScore(worker.Cell) * 260f);
            score += Mathf.RoundToInt(WorkerMoraleDeficit(worker) * 60f);
            if (IsWorkerInDrabSurroundings(worker))
            {
                score += 35 + Mathf.RoundToInt(DrabDecorSeverity(DecorScoreAt(worker.Cell.x, worker.Cell.y)) * 45f);
            }

            score += Mathf.RoundToInt(Mathf.Max(0f, worker.CommuteSeconds - LongCommuteThresholdSeconds) * 2.5f);
            if (SleepDisruptionFactor(worker) > 0f)
            {
                score += 70;
            }

            if (IsWorkerHoldingBreath(worker))
            {
                score += 140 + Mathf.RoundToInt((BreathCapacity - worker.Breath) * 1.5f);
            }

            if (HasDepletedBreathingGearInUnsafeArea(worker))
            {
                score += 360 + Mathf.RoundToInt((BreathCapacity - worker.Breath) * 1.2f);
            }

            score += Mathf.RoundToInt(worker.BrightSleepSeconds * 1.8f);

            if (worker.NarcolepticNapSeconds > 0f)
            {
                score += 120;
            }

            score += Mathf.RoundToInt(worker.SoggyFeetSeconds * 2.0f);
            score += Mathf.RoundToInt(worker.SoppingWetSeconds * 2.4f);
            score += Mathf.RoundToInt(worker.YuckyLungsSeconds * 2.2f);
            score += Mathf.RoundToInt(worker.PoppedEardrumsSeconds * 1.9f);
            score += Mathf.RoundToInt(worker.IrritatedEyesSeconds * 2.1f);
            score += Mathf.RoundToInt(worker.ScaldedSeconds * 2.8f);
            score += Mathf.RoundToInt(worker.AllergicReactionSeconds * 1.8f);
            score += Mathf.RoundToInt(worker.SuitFatigueSeconds * 1.5f);
            score += Mathf.RoundToInt(worker.GermyHandsSeconds * 2.0f);
            score += Mathf.RoundToInt(worker.NauseousSeconds * 1.6f);
            score += Mathf.RoundToInt(worker.DarkStressSeconds * 1.7f);
            score += Mathf.RoundToInt(worker.SoreBackSeconds * 1.4f);
            score += Mathf.RoundToInt(worker.ExhaustedCollapseSeconds * 12f);
            score += Mathf.RoundToInt(worker.AteWithoutTableSeconds * 1.2f);
            score += Mathf.RoundToInt(worker.AccidentShameSeconds * 1.4f);

            if (worker.StressBreakSeconds > 0f)
            {
                score += 9000;
            }

            if (worker.Breath <= 0.01f)
            {
                score += 5200;
            }

            return score;
        }

        private string WorkerRiskText(Worker worker)
        {
            if (worker == null)
            {
                return "none";
            }

            if (worker.Health <= 0f)
            {
                return "Needs rescue";
            }

            if (worker.StressBreakSeconds > 0f)
            {
                return "Stress break";
            }

            if (worker.ExhaustedCollapseSeconds > 0f)
            {
                return "Exhaustion collapse";
            }

            if (worker.Health <= 35f)
            {
                return "Critical health";
            }

            if (worker.Breath <= 0.01f)
            {
                return "Suffocating";
            }

            if (HasDepletedBreathingGearInUnsafeArea(worker))
            {
                return worker.SuitEquipped ? "Suit oxygen depleted" : "Mask oxygen depleted";
            }

            if (worker.Breath <= 22f)
            {
                return "Low breath";
            }

            if (IsWorkerHoldingBreath(worker))
            {
                return "Holding breath";
            }

            if (NeedsSeekSafety(worker))
            {
                return "Unsafe environment";
            }

            if (worker.Calories <= 350f)
            {
                return "Starving";
            }

            if (worker.Sickness >= 70f)
            {
                return worker.Disease == WorkerDisease.None ? "Severe sickness" : WorkerDiseaseName(worker.Disease);
            }

            if (!worker.LeadSuitEquipped && RadiationAt(worker.Cell.x, worker.Cell.y) >= RadiationExposureThreshold)
            {
                return "Radiation danger";
            }

            if (Mathf.Max(worker.HeatExposure, worker.ChillExposure) >= ThermalInjuryExposureThreshold)
            {
                return worker.Disease == WorkerDisease.None ? "Thermal danger" : WorkerDiseaseName(worker.Disease);
            }

            if (worker.ScaldedSeconds >= 12f)
            {
                return "Scalded";
            }

            if (worker.HeatExposure >= SafetyExposureThreshold && worker.HeatExposure >= worker.ChillExposure)
            {
                return "Too hot";
            }

            if (worker.ChillExposure >= SafetyExposureThreshold)
            {
                return "Too cold";
            }

            if (worker.AllergicReactionSeconds >= 18f)
            {
                return "Allergic reaction";
            }

            if (worker.Stress >= 90f)
            {
                return "Stress critical";
            }

            if (worker.Fatigue >= ExhaustedFatigueThreshold)
            {
                return "Exhausted";
            }

            if (worker.SuitFatigueSeconds >= 28f)
            {
                return "Suit fatigue";
            }

            if (worker.Bladder >= 94f)
            {
                return "Bladder critical";
            }

            if (worker.NauseousSeconds >= 18f)
            {
                return "Nauseous";
            }

            if (worker.AccidentShameSeconds >= 22f)
            {
                return "Made a mess";
            }

            if (worker.GermExposure >= 85f)
            {
                return worker.Disease == WorkerDisease.None ? "Germ risk" : WorkerDiseaseName(worker.Disease);
            }

            if (worker.GermyHandsSeconds >= 28f)
            {
                return "Germy hands";
            }

            if (worker.DarkStressSeconds >= 22f)
            {
                return "Dark stress";
            }

            if (WorkerMoraleDeficit(worker) > 1.25f)
            {
                return "Morale deficit";
            }

            if (IsWorkerInDrabSurroundings(worker))
            {
                return "Drab surroundings";
            }

            if (SleepDisruptionFactor(worker) > 0f)
            {
                return "Sleep disrupted";
            }

            if (worker.BrightSleepSeconds >= 18f)
            {
                return "Bright sleep";
            }

            if (worker.SoreBackSeconds >= 24f)
            {
                return "Sore back";
            }

            if (worker.AteWithoutTableSeconds >= 20f)
            {
                return "Ate without table";
            }

            if (worker.NarcolepticNapSeconds > 0f)
            {
                return "Narcoleptic nap";
            }

            if (worker.SoggyFeetSeconds >= 14f)
            {
                return "Soggy feet";
            }

            if (worker.SoppingWetSeconds >= 18f)
            {
                return "Sopping wet";
            }

            if (worker.YuckyLungsSeconds >= 16f)
            {
                return "Yucky lungs";
            }

            if (worker.PoppedEardrumsSeconds >= 18f)
            {
                return "Popped eardrums";
            }

            if (worker.IrritatedEyesSeconds >= 16f)
            {
                return "Irritated eyes";
            }

            if (worker.CommuteSeconds >= LongCommuteSevereThresholdSeconds)
            {
                return "Long commute";
            }

            if (worker.Calories <= 850f)
            {
                return "Hungry";
            }

            if (worker.Stress >= 70f)
            {
                return "High stress";
            }

            if (worker.Fatigue >= VeryTiredFatigueThreshold)
            {
                return "Very tired";
            }

            if (IsWorkerDrowsy(worker))
            {
                return "Drowsy";
            }

            if (worker.Bladder >= 82f)
            {
                return "Needs toilet";
            }

            return "Stable";
        }

        private string WorkerSummary()
        {
            StringBuilder builder = new StringBuilder();
            for (int i = 0; i < workers.Count; i++)
            {
                if (i > 0)
                {
                    builder.Append(" | ");
                }

                builder.Append(workers[i].Name);
                builder.Append(": ");
                builder.Append(workers[i].Activity);
                builder.Append(" H");
                builder.Append(workers[i].Health.ToString("0"));
                if (workers[i].Health <= 0f)
                {
                    builder.Append(" Down");
                    builder.Append(workers[i].IncapacitatedSeconds.ToString("0"));
                    continue;
                }

                builder.Append(" Lv");
                builder.Append(WorkerSkillLevel(workers[i]));
                float moraleDeficit = WorkerMoraleDeficit(workers[i]);
                if (moraleDeficit > 0.5f)
                {
                    builder.Append(" Mor-");
                    builder.Append(moraleDeficit.ToString("0.0"));
                }
                if (workers[i].SuitEquipped)
                {
                    builder.Append(" Suit");
                }
                else if (workers[i].OxygenMaskEquipped)
                {
                    builder.Append(" Mask");
                }

                if (workers[i].LeadSuitEquipped)
                {
                    builder.Append(" Lead");
                }

                if (workers[i].Breath < 75f)
                {
                    builder.Append(" Br");
                    builder.Append(workers[i].Breath.ToString("0"));
                }

                builder.Append(" F");
                builder.Append(workers[i].Fatigue.ToString("0"));
                if (workers[i].StressBreakSeconds > 0f)
                {
                    builder.Append(" Break");
                    builder.Append(workers[i].StressBreakSeconds.ToString("0"));
                    continue;
                }

                if (workers[i].Stress > 50f)
                {
                    builder.Append(" S");
                    builder.Append(workers[i].Stress.ToString("0"));
                }

                if (workers[i].Bladder > 55f)
                {
                    builder.Append(" B");
                    builder.Append(workers[i].Bladder.ToString("0"));
                }

                if (workers[i].GermExposure > 18f)
                {
                    builder.Append(" Germ");
                    builder.Append(workers[i].GermExposure.ToString("0"));
                }

                if (workers[i].Sickness > 1f)
                {
                    builder.Append(" Sick");
                    builder.Append(workers[i].Sickness.ToString("0"));
                }

                if (workers[i].HeatExposure > 5f)
                {
                    builder.Append(" Heat");
                    builder.Append(workers[i].HeatExposure.ToString("0"));
                }
                else if (workers[i].ChillExposure > 5f)
                {
                    builder.Append(" Chill");
                    builder.Append(workers[i].ChillExposure.ToString("0"));
                }
            }

            return builder.ToString();
        }

        private float MaxWorkerGermExposure()
        {
            float maxExposure = 0f;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && worker.GermExposure > maxExposure)
                {
                    maxExposure = worker.GermExposure;
                }
            }

            return maxExposure;
        }

        private int CountThermallyExposedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && Mathf.Max(worker.HeatExposure, worker.ChillExposure) > 5f)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountCriticalThermalExposureWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && Mathf.Max(worker.HeatExposure, worker.ChillExposure) >= ThermalInjuryExposureThreshold)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountRadiationExposedWorkers()
        {
            int count = 0;
            foreach (Worker worker in workers)
            {
                if (worker.Health > 0f && RadiationAt(worker.Cell.x, worker.Cell.y) > RadiationExposureThreshold)
                {
                    count++;
                }
            }

            return count;
        }

        private int CountRadiationDangerTiles()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (RadiationAt(x, y) > RadiationExposureThreshold)
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private Worker WorkerAt(Vector2Int cell)
        {
            foreach (Worker worker in workers)
            {
                if (worker.Cell == cell)
                {
                    return worker;
                }
            }

            return null;
        }

        private float AverageGas(float[,] gas)
        {
            float total = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPassable(x, y))
                    {
                        total += gas[x, y];
                        count++;
                    }
                }
            }

            return count == 0 ? 0f : total / count;
        }

        private float TotalAtmosphereGas(float[,] gas)
        {
            float total = 0f;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPassable(x, y))
                    {
                        total += gas[x, y];
                    }
                }
            }

            return total;
        }

        private float AverageTemperature()
        {
            float total = 0f;
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPassable(x, y))
                    {
                        total += temperature[x, y];
                        count++;
                    }
                }
            }

            return count == 0 ? 22f : total / count;
        }

        private int CountUnsafeTemperatureTiles()
        {
            int count = 0;
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (IsPassable(x, y) && (temperature[x, y] < 0f || temperature[x, y] > 52f))
                    {
                        count++;
                    }
                }
            }

            return count;
        }

        private bool SpendCost(BuildSpec spec)
        {
            if (dirt < spec.Dirt || metal < spec.Metal || algae < spec.Algae || refinedMetal < spec.RefinedMetal)
            {
                return false;
            }

            dirt -= spec.Dirt;
            metal -= spec.Metal;
            algae -= spec.Algae;
            refinedMetal -= spec.RefinedMetal;
            return true;
        }

        private bool HasJobMaterialCost(Job job)
        {
            return job != null &&
                job.DirtCost + job.MetalCost + job.AlgaeCost + job.RefinedMetalCost > 0.001f;
        }

        private bool IsBuildReservationJob(Job job)
        {
            if (!HasJobMaterialCost(job))
            {
                return false;
            }

            return job.Type == JobType.Build ||
                job.Type == JobType.BuildWire ||
                job.Type == JobType.BuildAutomationWire ||
                job.Type == JobType.BuildPipe ||
                job.Type == JobType.BuildGasPipe ||
                job.Type == JobType.BuildShippingRail;
        }

        private void AccumulateQueuedBuildCosts(out int queuedJobs, out float queuedDirt, out float queuedMetal, out float queuedAlgae, out float queuedRefinedMetal)
        {
            queuedJobs = 0;
            queuedDirt = 0f;
            queuedMetal = 0f;
            queuedAlgae = 0f;
            queuedRefinedMetal = 0f;

            foreach (Job job in jobs)
            {
                if (!IsBuildReservationJob(job))
                {
                    continue;
                }

                queuedJobs++;
                queuedDirt += job.DirtCost;
                queuedMetal += job.MetalCost;
                queuedAlgae += job.AlgaeCost;
                queuedRefinedMetal += job.RefinedMetalCost;
            }
        }

        private string BuildCostFailureText(BuildSpec spec)
        {
            return BuildCostFailureText(spec.Label, spec.Dirt, spec.Metal, spec.Algae, spec.RefinedMetal);
        }

        private string BuildCostFailureText(string label, float dirtCost, float metalCost, float algaeCost, float refinedMetalCost)
        {
            float missingDirt = Mathf.Max(0f, dirtCost - dirt);
            float missingMetal = Mathf.Max(0f, metalCost - metal);
            float missingAlgae = Mathf.Max(0f, algaeCost - algae);
            float missingRefined = Mathf.Max(0f, refinedMetalCost - refinedMetal);

            StringBuilder builder = new StringBuilder();
            builder.Append("Not enough resources for ");
            builder.Append(label);
            builder.Append(": missing ");
            builder.Append(BuildCostText(missingDirt, missingMetal, missingAlgae, missingRefined));
            builder.Append(", available ");
            builder.Append(BuildCostText(dirt, metal, algae, refinedMetal));

            AccumulateQueuedBuildCosts(out int queuedJobs, out float queuedDirt, out float queuedMetal, out float queuedAlgae, out float queuedRefinedMetal);
            if (queuedJobs > 0)
            {
                builder.Append(". Queued builds have reserved ");
                builder.Append(BuildCostText(queuedDirt, queuedMetal, queuedAlgae, queuedRefinedMetal));
            }

            builder.Append(".");
            return builder.ToString();
        }

        private string BuildCostText(float dirtAmount, float metalAmount, float algaeAmount, float refinedMetalAmount)
        {
            StringBuilder builder = new StringBuilder();
            bool hasPart = false;
            AppendBuildCostPart(builder, ref hasPart, dirtAmount, "Dirt");
            AppendBuildCostPart(builder, ref hasPart, metalAmount, "Metal");
            AppendBuildCostPart(builder, ref hasPart, algaeAmount, "Algae");
            AppendBuildCostPart(builder, ref hasPart, refinedMetalAmount, "Refined Metal");
            return hasPart ? builder.ToString() : "none";
        }

        private void AppendBuildCostPart(StringBuilder builder, ref bool hasPart, float amount, string label)
        {
            if (amount <= 0.001f)
            {
                return;
            }

            if (hasPart)
            {
                builder.Append(", ");
            }

            builder.Append(amount.ToString("0.#"));
            builder.Append(" ");
            builder.Append(label);
            hasPart = true;
        }

        private string QueuedBuildReservationText()
        {
            AccumulateQueuedBuildCosts(out int queuedJobs, out float queuedDirt, out float queuedMetal, out float queuedAlgae, out float queuedRefinedMetal);
            if (queuedJobs <= 0)
            {
                return string.Empty;
            }

            return "Build reserve " + queuedJobs + " jobs: " + BuildCostText(queuedDirt, queuedMetal, queuedAlgae, queuedRefinedMetal);
        }

        private void RefundJobCost(Job job)
        {
            dirt += job.DirtCost;
            metal += job.MetalCost;
            algae += job.AlgaeCost;
            refinedMetal += job.RefinedMetalCost;
        }

