                    Log("Research Thermal Engineering before building Insulated Tiles.");
                }

                return false;
            }

            if (kind == CellKind.TempshiftPlate && !techThermalEngineering)
            {
                if (showLog)
                {
                    Log("Research Thermal Engineering before building Tempshift Plates.");
                }

                return false;
            }

            if (kind == CellKind.ThermoAquatuner && !techThermalEngineering)
            {
                if (showLog)
                {
                    Log("Research Thermal Engineering before building a Thermo Aquatuner.");
                }

                return false;
            }

            if (kind == CellKind.LiquidTepidizer && !techThermalEngineering)
            {
                if (showLog)
                {
                    Log("Research Thermal Engineering before building a Liquid Tepidizer.");
                }

                return false;
            }

            if (kind == CellKind.PrintingPod && !techPowerRegulation)
            {
                if (showLog)
                {
                    Log("Research Power Regulation before building another Printing Pod.");
                }

                return false;
            }

            if (kind == CellKind.AirDeodorizer && !techAirSystems)
            {
                if (showLog)
                {
                    Log("Research Air Systems before building an Air Deodorizer.");
                }

                return false;
            }

            if ((kind == CellKind.GasPump || kind == CellKind.GasVent || kind == CellKind.HighPressureGasVent || kind == CellKind.GasReservoir || kind == CellKind.GasBridge) && !techAirSystems)
            {
                if (showLog)
                {
                    Log("Research Air Systems before building ventilation.");
                }

                return false;
            }

            if ((kind == CellKind.Electrolyzer || kind == CellKind.CarbonSkimmer || kind == CellKind.WaterSieve || kind == CellKind.Desalinator) && !techAirSystems)
            {
                if (showLog)
                {
                    Log("Research Air Systems before building advanced atmosphere machines.");
                }

                return false;
            }

            if (kind == CellKind.ThermoRegulator && !techThermalEngineering)
            {
                if (showLog)
                {
                    Log("Research Thermal Engineering before building a Thermo Regulator.");
                }

                return false;
            }

            if (kind == CellKind.RanchingStation && !techFoodPreparation)
            {
                if (showLog)
                {
                    Log("Research Food Preparation before building a Ranching Station.");
                }

                return false;
            }

            if (kind == CellKind.Incubator && !techFoodPreparation)
            {
                if (showLog)
                {
                    Log("Research Food Preparation before building an Incubator.");
                }

                return false;
            }

            if (kind == CellKind.CritterSensor && (!techFoodPreparation || !techAutomationLogistics))
            {
                if (showLog)
                {
                    Log("Research Food Preparation and Automation Logistics before building a Critter Sensor.");
                }

                return false;
            }

            if (kind == CellKind.CritterFeeder && !techFoodPreparation)
            {
                if (showLog)
                {
                    Log("Research Food Preparation before building a Critter Feeder.");
                }

                return false;
            }

            return true;
        }

        private bool HasAdjacentWater(Vector2Int cell)
        {
            return TryFindAdjacentWater(cell, out _);
        }

        private bool HasLiquidPipeAccess(Vector2Int cell)
