            return IsLiquidPipeCell(cell.x, cell.y) ||
                IsLiquidPipeCell(cell.x + 1, cell.y) ||
                IsLiquidPipeCell(cell.x - 1, cell.y) ||
                IsLiquidPipeCell(cell.x, cell.y + 1) ||
                IsLiquidPipeCell(cell.x, cell.y - 1);
        }

        private bool HasMachineWaterFeed(Vector2Int cell)
        {
            return CleanWaterAvailableForMachine(cell) > 0.05f;
        }

        private float SaltWaterAvailableForDesalinator(Vector2Int cell)
        {
            float available = saltWater;
            if (TryFindAdjacentSaltWater(cell, out Vector2Int source))
            {
                available += waterMass[source.x, source.y];
            }

            return available;
        }

        private float ConsumeSaltWaterForDesalinator(Vector2Int center, float requested)
        {
            if (requested <= 0f)
            {
                return 0f;
            }

            float consumed = 0f;
            if (saltWater > 0f)
            {
                float stored = Mathf.Min(requested, saltWater);
                saltWater -= stored;
                consumed += stored;
            }

            float remaining = requested - consumed;
            if (remaining > 0.001f && TryFindAdjacentSaltWater(center, out Vector2Int source))
            {
                float fromTile = Mathf.Min(remaining, waterMass[source.x, source.y]);
                waterMass[source.x, source.y] -= fromTile;
                consumed += fromTile;
                if (waterMass[source.x, source.y] <= 0.5f)
                {
                    DryWaterCell(
                        source,
                        NeighborAverage(oxygen, source.x, source.y, 0.12f),
                        NeighborAverage(carbonDioxide, source.x, source.y, 0.04f),
                        NeighborAverage(pollutedOxygen, source.x, source.y, 0f),
                        NeighborAverage(hydrogen, source.x, source.y, 0f),
                        NeighborAverage(chlorine, source.x, source.y, 0f),
                        NeighborAverage(naturalGas, source.x, source.y, 0f),
                        NeighborAverage(germs, source.x, source.y, 0f),
                        temperature[source.x, source.y],
                        NeighborAverage(sourGas, source.x, source.y, 0f));
                }
            }

            return consumed;
        }

        private float CleanWaterAvailableForMachine(Vector2Int cell)
        {
            float available = water;
            if (TryFindAdjacentLiquidPipeWithWater(cell, out Vector2Int pipe))
            {
                available += pipeWater[pipe.x, pipe.y];
            }

            return available;
        }

        private bool AnyElectrolyzerHasGermyWaterFeed()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if (cells[x, y] == CellKind.Electrolyzer &&
                        MachineWaterGermLevel(new Vector2Int(x, y)) >= CleanWaterGermAlertThreshold)
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private bool AnyGermyGasConduit()
        {
            for (int y = 0; y < WorldHeight; y++)
            {
                for (int x = 0; x < WorldWidth; x++)
                {
                    if ((gasPipe[x, y] && GasPipeTotal(x, y) > 0.001f && gasPipeGerms[x, y] >= GasConduitGermAlertThreshold) ||
                        (cells[x, y] == CellKind.GasReservoir && GasReservoirTotal(x, y) > 0.001f && gasReservoirGerms[x, y] >= GasConduitGermAlertThreshold))
                    {
                        return true;
                    }
                }
            }

            return false;
        }

        private float MachineWaterGermLevel(Vector2Int cell)
        {
            float available = 0f;
            float germLevel = 0f;
            if (TryFindAdjacentLiquidPipeWithWater(cell, out Vector2Int pipe))
            {
                float piped = pipeWater[pipe.x, pipe.y];
                germLevel = MixConcentration(germLevel, available, pipeWaterGerms[pipe.x, pipe.y], piped);
                available += piped;
            }

            if (water > 0f)
            {
                germLevel = MixConcentration(germLevel, available, waterGerms, water);
                available += water;
            }

            return available <= 0.001f ? 0f : germLevel;
        }

        private bool IsLiquidPipeCell(int x, int y)
        {
            return IsInside(x, y) && liquidPipe[x, y];
