        }

        private bool TryFindAdjacentLiquidPipeWithAnyLiquid(Vector2Int cell, out Vector2Int pipe)
        {
            pipe = new Vector2Int(-1, -1);
            float bestAmount = -1f;
            foreach (Vector2Int candidate in AdjacentConduitCandidates(cell))
            {
                if (!IsInside(candidate.x, candidate.y) ||
                    !liquidPipe[candidate.x, candidate.y] ||
                    IsLiquidConduitBlocked(candidate.x, candidate.y))
                {
                    continue;
                }

                float amount = LiquidPipeTotal(candidate.x, candidate.y);
                if (amount <= 0.001f || amount <= bestAmount)
                {
                    continue;
                }

                bestAmount = amount;
                pipe = candidate;
            }

            return pipe.x >= 0;
        }

        private bool TryFindAdjacentLiquidPipeWithPollutedWater(Vector2Int cell, out Vector2Int pipe)
