        private bool TryFindAdjacentLiquidPipeWithFilterLiquid(Vector2Int cell, LiquidFilterMode mode, out Vector2Int pipe)
        {
            pipe = new Vector2Int(-1, -1);
            float bestAmount = -1f;
            foreach (Vector2Int candidate in AdjacentConduitCandidates(cell))
            {
                if (!IsInside(candidate.x, candidate.y) ||
                    !liquidPipe[candidate.x, candidate.y] ||
                    IsLiquidConduitBlocked(candidate.x, candidate.y))
                {
                    continue;
                }

                float amount = LiquidPipeFilterAmount(candidate.x, candidate.y, mode);
                if (amount <= 0.001f || amount <= bestAmount)
                {
                    continue;
                }

                bestAmount = amount;
                pipe = candidate;
            }

