        }

        private bool TryFindAdjacentLiquidPipe(Vector2Int cell, bool requireWater, bool requireSpace, out Vector2Int pipe)
        {
            pipe = new Vector2Int(-1, -1);

            float bestScore = requireWater ? -1f : float.MaxValue;
            foreach (Vector2Int candidate in AdjacentConduitCandidates(cell))
            {
                if (!IsInside(candidate.x, candidate.y) ||
                    !liquidPipe[candidate.x, candidate.y] ||
                    IsLiquidConduitBlocked(candidate.x, candidate.y))
                {
                    continue;
                }

                float waterAmount = pipeWater[candidate.x, candidate.y];
                float totalAmount = LiquidPipeTotal(candidate.x, candidate.y);
                if (requireWater && waterAmount <= 0.001f)
                {
                    continue;
                }

                if (requireSpace && totalAmount >= LiquidPipeCapacity - 0.001f)
                {
                    continue;
                }

                float amount = requireWater ? waterAmount : totalAmount;
                if (requireWater)
                {
                    if (amount <= bestScore)
                    {
                        continue;
                    }

                    bestScore = amount;
                }
                else
                {
                    if (amount >= bestScore)
                    {
                        continue;
                    }

                    bestScore = amount;
                }

                pipe = candidate;
            }

            return pipe.x >= 0;
        }

        private bool TryFindAdjacentLiquidPipeWithSpaceExcluding(Vector2Int cell, Vector2Int excludedPipe, out Vector2Int pipe)
        {
            pipe = new Vector2Int(-1, -1);

            float bestAmount = float.MaxValue;
            foreach (Vector2Int candidate in AdjacentConduitCandidates(cell))
            {
                float amount = IsInside(candidate.x, candidate.y) ? LiquidPipeTotal(candidate.x, candidate.y) : 0f;
                if (candidate == excludedPipe ||
                    !IsInside(candidate.x, candidate.y) ||
                    !liquidPipe[candidate.x, candidate.y] ||
                    IsLiquidConduitBlocked(candidate.x, candidate.y) ||
                    amount >= LiquidPipeCapacity - 0.001f ||
                    amount >= bestAmount)
                {
                    continue;
                }

                bestAmount = amount;
                pipe = candidate;
            }

            return pipe.x >= 0;
        }

        private IEnumerable<Vector2Int> AdjacentConduitCandidates(Vector2Int cell)
        {
            yield return cell;
            yield return new Vector2Int(cell.x + 1, cell.y);
            yield return new Vector2Int(cell.x - 1, cell.y);
            yield return new Vector2Int(cell.x, cell.y + 1);
            yield return new Vector2Int(cell.x, cell.y - 1);
        }

        private bool TryFindLiquidVentOutput(Vector2Int vent, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                new Vector2Int(vent.x, vent.y - 1),
                new Vector2Int(vent.x + 1, vent.y),
                new Vector2Int(vent.x - 1, vent.y),
                new Vector2Int(vent.x, vent.y + 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y))
                {
                    continue;
                }

                if (CanLiquidOccupy(candidate.x, candidate.y) &&
                    LiquidFreeCapacity(candidate.x, candidate.y) > LiquidTileCapacity - 120f)
                {
                    output = candidate;
                    return true;
                }
            }

            return false;
        }

