            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y))
                {
                    continue;
                }

                CellKind kind = cells[candidate.x, candidate.y];
                bool available = kind == CellKind.Magma ||
                    (kind == CellKind.Empty &&
                        !powerWire[candidate.x, candidate.y] &&
                        !automationWire[candidate.x, candidate.y] &&
                        !liquidPipe[candidate.x, candidate.y] &&
                        !gasPipe[candidate.x, candidate.y] &&
                        looseResourceKind[candidate.x, candidate.y] == LooseResourceKind.None);
                if (available)
                {
                    output = candidate;
                    return true;
                }
            }

            return false;
        }

