            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !IsPassable(candidate.x, candidate.y))
                {
                    continue;
                }

                if (TileGasTotal(candidate.x, candidate.y) < GasVentOpenPressureForKind(ventKind))
                {
                    output = candidate;
                    return true;
                }
            }

            return false;
        }

        private bool TryFindNaturalVentGasOutput(Vector2Int vent, out Vector2Int output)
        {
            output = new Vector2Int(-1, -1);
            Vector2Int[] candidates =
            {
                new Vector2Int(vent.x, vent.y + 1),
                new Vector2Int(vent.x + 1, vent.y),
                new Vector2Int(vent.x - 1, vent.y),
                new Vector2Int(vent.x, vent.y - 1)
            };

            for (int i = 0; i < candidates.Length; i++)
            {
                Vector2Int candidate = candidates[i];
                if (!IsInside(candidate.x, candidate.y) || !IsPassable(candidate.x, candidate.y))
                {
                    continue;
                }

                if (TileGasTotal(candidate.x, candidate.y) < NaturalVentOutputPressure)
                {
                    output = candidate;
                    return true;
                }
            }

            return false;
        }

        private bool TryFindAdjacentWater(Vector2Int cell, out Vector2Int waterCell)
        {
            waterCell = new Vector2Int(-1, -1);
            Vector2Int[] offsets =
            {
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1)
            };

            foreach (Vector2Int offset in offsets)
            {
                int x = cell.x + offset.x;
                int y = cell.y + offset.y;
                if (IsInside(x, y) && IsWorldLiquidCell(cells[x, y]) && waterMass[x, y] > 0.5f)
                {
                    waterCell = new Vector2Int(x, y);
                    return true;
                }
            }

            return false;
        }

        private bool TryFindAdjacentPipePumpLiquid(Vector2Int cell, out Vector2Int waterCell)
        {
            waterCell = new Vector2Int(-1, -1);
            Vector2Int[] offsets =
            {
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1)
            };

            foreach (Vector2Int offset in offsets)
            {
                int x = cell.x + offset.x;
                int y = cell.y + offset.y;
                if (IsInside(x, y) &&
                    IsWorldLiquidCell(cells[x, y]) &&
                    !IsSaltWaterWorldLiquidAt(x, y) &&
                    !IsCrudeOilWorldLiquidAt(x, y) &&
                    waterMass[x, y] > 0.5f)
                {
                    waterCell = new Vector2Int(x, y);
                    return true;
                }
            }

            return false;
        }

        private bool TryFindAdjacentCrudeOil(Vector2Int cell, out Vector2Int oilCell)
        {
            oilCell = new Vector2Int(-1, -1);
            Vector2Int[] offsets =
            {
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1)
            };

            foreach (Vector2Int offset in offsets)
            {
                int x = cell.x + offset.x;
                int y = cell.y + offset.y;
                if (IsCrudeOilWorldLiquidAt(x, y))
                {
                    oilCell = new Vector2Int(x, y);
                    return true;
                }
            }

            return false;
        }

        private bool TryFindAdjacentSaltWater(Vector2Int cell, out Vector2Int saltWaterCell)
        {
            saltWaterCell = new Vector2Int(-1, -1);
            Vector2Int[] offsets =
            {
                new Vector2Int(1, 0),
                new Vector2Int(-1, 0),
                new Vector2Int(0, 1),
                new Vector2Int(0, -1)
            };

            foreach (Vector2Int offset in offsets)
            {
                int x = cell.x + offset.x;
                int y = cell.y + offset.y;
                if (IsSaltWaterWorldLiquidAt(x, y))
                {
                    saltWaterCell = new Vector2Int(x, y);
                    return true;
                }
            }

            return false;
        }

        private bool TryFindOilReservoirAccess(Vector2Int center, int range, out Vector2Int oilCell)
        {
            oilCell = new Vector2Int(-1, -1);
            int bestDistance = int.MaxValue;
            for (int y = Mathf.Max(0, center.y - range); y <= Mathf.Min(WorldHeight - 1, center.y + range); y++)
            {
                for (int x = Mathf.Max(0, center.x - range); x <= Mathf.Min(WorldWidth - 1, center.x + range); x++)
                {
                    int distance = Mathf.Abs(x - center.x) + Mathf.Abs(y - center.y);
                    if (distance > range || distance >= bestDistance || !IsCrudeOilWorldLiquidAt(x, y))
                    {
                        continue;
                    }

                    bestDistance = distance;
                    oilCell = new Vector2Int(x, y);
                }
            }

            return oilCell.x >= 0;
        }

