        private string JobLabel(Job job)
        {
            switch (job.Type)
            {
                case JobType.Dig:
                    return "Dig";
                case JobType.Build:
                    return "Build " + CellLabel(job.BuildKind);
                case JobType.BuildWire:
                    return "Build " + PowerWireKindName(job.PowerWireKind);
                case JobType.BuildAutomationWire:
                    return "Build Automation Wire";
                case JobType.BuildPipe:
                    return "Build " + LiquidPipeKindName(job.LiquidPipeKind);
                case JobType.BuildGasPipe:
                    return "Build " + GasPipeKindName(job.GasPipeKind);
                case JobType.BuildShippingRail:
                    return "Build Shipping Rail";
                case JobType.Deconstruct:
                    return "Deconstruct " + DeconstructTargetLabel(job);
                case JobType.Mop:
                    return "Mop Spill";
                case JobType.Disinfect:
                    return "Disinfect Germs";
                case JobType.Repair:
                    return "Repair " + CellLabel(job.BuildKind);
                case JobType.Rescue:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Rescue" : "Rescue " + job.TargetWorkerName;
                case JobType.Sweep:
                    return HasLooseResource(job.Cell) ? "Sweep " + LooseResourceLabel(looseResourceKind[job.Cell.x, job.Cell.y]) : "Sweep";
                case JobType.OperateGenerator:
                    return "Operate Generator";
                case JobType.TuneGenerator:
                    return "Tune Generator";
                case JobType.Sculpt:
                    return "Sculpt Artwork";
                case JobType.Harvest:
                    return "Harvest";
                case JobType.PumpWater:
                    return "Pump Liquid";
                case JobType.EmptyBottle:
                    return "Empty Bottle";
                case JobType.Research:
                    return "Research";
                case JobType.Cook:
                    return "Cook";
                case JobType.RefineMetal:
                    return "Refine Metal";
                case JobType.Sleep:
                    return IsFloorSleepJob(job) ? "Floor Sleep" : "Sleep";
                case JobType.Treat:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Treatment" : "Treat " + job.TargetWorkerName;
                case JobType.MedicalRest:
                    if (IsFloorMedicalRestJob(job))
                    {
                        return string.IsNullOrEmpty(job.TargetWorkerName) ? "Floor Medical Rest" : "Floor Medical Rest " + job.TargetWorkerName;
                    }

                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Medical Rest" : "Medical Rest " + job.TargetWorkerName;
                case JobType.CatchBreath:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Catch Breath" : "Catch Breath " + job.TargetWorkerName;
                case JobType.SeekSafety:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Seek Safety" : "Seek Safety " + job.TargetWorkerName;
                case JobType.MoveTo:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Move To" : "Move To " + job.TargetWorkerName;
                case JobType.ProduceMedicine:
                    return "Compound Medicine";
                case JobType.UseToilet:
                    string toiletLabel = IsInside(job.Cell.x, job.Cell.y) && cells[job.Cell.x, job.Cell.y] == CellKind.Lavatory ? "Lavatory" : "Outhouse";
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Use " + toiletLabel : job.TargetWorkerName + " to " + toiletLabel;
                case JobType.WashHands:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Wash Hands" : job.TargetWorkerName + " to Wash Basin";
                case JobType.Shower:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Shower" : job.TargetWorkerName + " to Shower";
                case JobType.TendCrop:
                    return "Tend Crop";
                case JobType.Eat:
                    if (IsFloorEatJob(job))
                    {
                        return string.IsNullOrEmpty(job.TargetWorkerName) ? "Floor Eat" : "Floor Eat " + job.TargetWorkerName;
                    }

                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Eat" : "Feed " + job.TargetWorkerName;
                case JobType.Relax:
                    if (IsTakeBreakJob(job))
                    {
                        return string.IsNullOrEmpty(job.TargetWorkerName) ? "Take Break" : "Take Break " + job.TargetWorkerName;
                    }

                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Relax" : "Relax " + job.TargetWorkerName;
                case JobType.ScrubSkill:
                    return string.IsNullOrEmpty(job.TargetWorkerName) ? "Scrub Skills" : "Scrub Skills " + job.TargetWorkerName;
                case JobType.Compost:
                    return "Compost Polluted Dirt";
                case JobType.GroomHatch:
                    return "Groom Critter";
                case JobType.WrangleCritter:
                    return "Wrangle Critter";
                case JobType.ButcherCritter:
                    return "Butcher Critter";
                default:
                    return job.Type.ToString();
            }
        }

