        private Job FindAnyJobAt(Vector2Int cell)
        {
            foreach (Job job in jobs)
            {
                if (job.Cell == cell)
                {
                    return job;
                }
            }

            return null;
        }

        private Job FindJobAt(Vector2Int cell, JobType type)
        {
            foreach (Job job in jobs)
            {
                if (job.Cell == cell && job.Type == type)
                {
                    return job;
                }
            }

            return null;
        }

        private bool IsInside(int x, int y)
        {
            return x >= 0 && x < WorldWidth && y >= 0 && y < WorldHeight;
        }

        private bool IsPassable(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return false;
            }

            CellKind kind = cells[x, y];
            if (kind == CellKind.ManualAirlock && !airlockOpen[x, y])
            {
                return false;
            }

            if (kind == CellKind.MechanizedAirlock && !IsMechanizedAirlockOpen(new Vector2Int(x, y)))
            {
                return false;
            }

            if (kind == CellKind.BunkerDoor && IsBunkerDoorClosed(new Vector2Int(x, y)))
            {
                return false;
            }

            return !IsSolidTile(kind) &&
                !IsWorldLiquidCell(kind) &&
                kind != CellKind.SteamVent &&
                kind != CellKind.WaterGeyser &&
                kind != CellKind.CoolSteamVent &&
                kind != CellKind.LeakyOilFissure &&
                kind != CellKind.SaltWaterGeyser &&
                kind != CellKind.CoolSlushGeyser &&
                kind != CellKind.PollutedWaterVent &&
                kind != CellKind.ChlorineGasVent &&
                kind != CellKind.CarbonDioxideVent &&
                kind != CellKind.PollutedOxygenVent &&
                kind != CellKind.HydrogenVent &&
                kind != CellKind.NaturalGasVent &&
                kind != CellKind.MetalVolcano &&
                kind != CellKind.MagmaVolcano &&
                kind != CellKind.AntiEntropyThermoNullifier;
        }

        private bool IsGasExchangeCell(int x, int y)
        {
            return IsInside(x, y) && (IsPassable(x, y) || cells[x, y] == CellKind.AirflowTile);
        }

        private bool IsMechanizedAirlockOpen(Vector2Int cell)
        {
            if (!IsInside(cell.x, cell.y) || cells[cell.x, cell.y] != CellKind.MechanizedAirlock || !CanUseEquipment(cell))
            {
                return false;
            }

            UpdateAutomationWires();
            return !HasCachedAutomationControl(cell) || HasCachedAutomationSignal(cell);
        }

        private bool IsMechanizedAirlockClosedByCachedAutomation(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                cells[cell.x, cell.y] == CellKind.MechanizedAirlock &&
                CanUseEquipment(cell) &&
                HasCachedAutomationControl(cell) &&
                !HasCachedAutomationSignal(cell);
        }

        private float DefaultEquipmentCondition(CellKind kind)
        {
            return IsRepairableEquipment(kind) ? 1f : 0f;
        }

        private ConstructionMaterialGrade ConstructionMaterialGradeForBuild(Job job)
        {
            if (job == null || !ShouldTrackConstructionMaterial(job.BuildKind))
            {
                return ConstructionMaterialGrade.Basic;
            }

            if (job.RefinedMetalCost >= 6f)
            {
                return ConstructionMaterialGrade.HighGrade;
            }

            return job.RefinedMetalCost > 0.001f ? ConstructionMaterialGrade.Refined : ConstructionMaterialGrade.Basic;
        }

        private ConstructionMaterialGrade DefaultConstructionMaterialGrade(CellKind kind)
        {
            if (!ShouldTrackConstructionMaterial(kind))
            {
                return ConstructionMaterialGrade.Basic;
            }

            BuildSpec spec = BuildSpecForKind(kind);
            if (spec.RefinedMetal >= 6f)
            {
                return ConstructionMaterialGrade.HighGrade;
            }

            return spec.RefinedMetal > 0.001f ? ConstructionMaterialGrade.Refined : ConstructionMaterialGrade.Basic;
        }

        private bool ShouldSaveConstructionMaterialGrade(int x, int y)
        {
            return IsInside(x, y) && ShouldTrackConstructionMaterial(cells[x, y]);
        }

        private bool ShouldTrackConstructionMaterial(CellKind kind)
        {
            return IsRepairableEquipment(kind) || kind == CellKind.InsulatedTile || kind == CellKind.TempshiftPlate || kind == CellKind.ComfyBed || kind == CellKind.AirflowTile || kind == CellKind.MeshTile;
        }

        private ConstructionMaterialGrade NormalizeConstructionMaterialGrade(int grade)
        {
            int max = Enum.GetValues(typeof(ConstructionMaterialGrade)).Length - 1;
            return (ConstructionMaterialGrade)Mathf.Clamp(grade, 0, max);
        }

        private float ConstructionMaterialOverheatBonus(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 0f;
            }

            switch (constructionMaterialGrade[x, y])
            {
                case ConstructionMaterialGrade.Thermium:
                    return ThermiumMaterialOverheatBonus;
                case ConstructionMaterialGrade.HighGrade:
                    return HighGradeMaterialOverheatBonus;
                case ConstructionMaterialGrade.Refined:
                    return RefinedMaterialOverheatBonus;
                default:
                    return 0f;
            }
        }

        private float EquipmentOverheatTemperatureAt(int x, int y)
        {
            return EquipmentOverheatTemperature + ConstructionMaterialOverheatBonus(x, y);
        }

        private float EquipmentCriticalOverheatTemperatureAt(int x, int y)
        {
            return EquipmentCriticalOverheatTemperature + ConstructionMaterialOverheatBonus(x, y);
        }

        private float ConstructionMaterialWearMultiplier(int x, int y)
        {
            if (!IsInside(x, y))
            {
                return 1f;
            }

            switch (constructionMaterialGrade[x, y])
            {
                case ConstructionMaterialGrade.Thermium:
                    return ThermiumMaterialWearMultiplier;
                case ConstructionMaterialGrade.HighGrade:
                    return HighGradeMaterialWearMultiplier;
                case ConstructionMaterialGrade.Refined:
                    return RefinedMaterialWearMultiplier;
                default:
                    return 1f;
            }
        }

        private string ConstructionMaterialGradeName(ConstructionMaterialGrade grade)
        {
            switch (grade)
            {
                case ConstructionMaterialGrade.Thermium:
                    return "Thermium";
                case ConstructionMaterialGrade.HighGrade:
                    return "High-grade";
                case ConstructionMaterialGrade.Refined:
                    return "Refined";
                default:
                    return "Basic";
            }
        }

