        private bool IsBrokenEquipment(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsRepairableEquipment(cells[cell.x, cell.y]) &&
                equipmentCondition[cell.x, cell.y] <= EquipmentBrokenThreshold;
        }

        private bool CanUseEquipment(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                !IsBuildingDisabled(cell) &&
                !IsBrokenEquipment(cell) &&
                !IsEquipmentSubmerged(cell);
        }

        private string DisabledBuildingBlockText(Vector2Int cell)
        {
            return IsBuildingDisabled(cell)
                ? "Building blocked: building is disabled."
                : string.Empty;
        }

        private bool IsBuildingDisabled(Vector2Int cell)
        {
            return IsInside(cell.x, cell.y) &&
                IsDisablableBuilding(cells[cell.x, cell.y]) &&
                buildingDisabled[cell.x, cell.y];
        }

